CREATE OR REPLACE FUNCTION custodial_coverall.ack_manual_application_target(p_intent uuid, p_device uuid, p_credential uuid, p_employee uuid, p_epoch bigint, p_revision bigint, p_target_digest text, p_rendered_digest text, p_applied_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare t custodial_coverall.manual_application_intents%rowtype;r custodial_coverall.manual_application_receipts%rowtype;
begin
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 perform public.static_weekly_v19_assert_terminal_principal(p_device,p_credential,p_employee,p_epoch);
 if not exists(select 1 from public.employees where id=p_employee and active=true) then
  raise exception using errcode='42501',message='recurring schedule requires an active employee principal';end if;
 select * into t from custodial_coverall.manual_application_intents where intent_id=p_intent for share;
 if not found or t.device_id is distinct from p_device or t.credential_id is distinct from p_credential
  or t.employee_id is distinct from p_employee or t.assignment_epoch is distinct from p_epoch
  or t.authority_revision is distinct from p_revision or t.target_digest is distinct from p_target_digest
  or t.view_digest is distinct from p_rendered_digest or p_applied_at is null or not isfinite(p_applied_at)
  or p_applied_at<t.created_at or p_applied_at>clock_timestamp()+interval '5 minutes' then
  raise exception using errcode='23514',message='recurring receipt requires exact principal target rendered-view revision and time';end if;
 select * into r from custodial_coverall.manual_application_receipts where intent_id=p_intent;
 if found then
  if r.rendered_digest is distinct from p_rendered_digest or r.applied_at is distinct from p_applied_at then
   raise exception using errcode='23505',message='recurring target already has a different receipt';end if;
 else
  insert into custodial_coverall.manual_application_receipts(intent_id,rendered_digest,applied_at)
   values(p_intent,p_rendered_digest,p_applied_at) returning * into r;
 end if;
 -- This is an immutable historical receipt. The merged reader, not this
 -- response, decides whether it still applies to the CURRENT desired state.
 return jsonb_build_object('intentId',p_intent,'receiptId',r.receipt_id,'applicationStatus','DEVICE_REPORTED_APPLIED',
  'currentAuthorityNotInferred',true,'appliedAt',r.applied_at,'receivedAt',r.received_at);
end
$function$

CREATE OR REPLACE FUNCTION custodial_coverall.activation_packet_fingerprint(p_source uuid, p_template text, p_manager uuid, p_transition jsonb, p_feasibility jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE component jsonb;metadata jsonb;feasibility_identity text;document_identity text;projection_identity text;lunch_identity text;
BEGIN
 feasibility_identity:=p_feasibility->>'digest';
 IF feasibility_identity IS DISTINCT FROM public.static_weekly_digest_jsonb(p_feasibility-ARRAY['digest','initialBaseline']) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='manual activation feasibility identity changed';END IF;
 component:=p_feasibility#>'{initialBaseline,document}';document_identity:=component#>>'{validation,database_document_identity}';
 IF document_identity IS DISTINCT FROM public.static_weekly_digest_jsonb(component#-'{validation,database_document_identity}') THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='manual activation document identity changed';END IF;
 component:=NULL;
 component:=p_feasibility#>'{initialBaseline,projection}';projection_identity:=component->>'database_projection_identity';
 IF projection_identity IS DISTINCT FROM public.static_weekly_digest_jsonb(component-'database_projection_identity') THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='manual activation projection identity changed';END IF;
 component:=NULL;
 component:=p_feasibility->'lunchDocument';lunch_identity:=component->>'document_identity';
 IF lunch_identity IS DISTINCT FROM public.static_weekly_digest_jsonb(component-'document_identity') THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='manual activation lunch identity changed';END IF;
 IF p_feasibility#>'{initialBaseline,lunchDocument}' IS DISTINCT FROM component THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='manual activation initial lunch identity changed';END IF;
 component:=NULL;
 metadata:=(p_feasibility->'initialBaseline')-ARRAY['document','projection','lunchDocument'];
 p_feasibility:=NULL;
 RETURN public.static_weekly_digest_jsonb(jsonb_build_object('sourceId',p_source,'templateId',p_template,'managerId',p_manager,
  'transitionDigest',p_transition->>'transitionDigest','feasibilityDigest',feasibility_identity,
  'documentIdentity',document_identity,'projectionIdentity',projection_identity,'lunchIdentity',lunch_identity,'initialMetadata',metadata));
END $function$

CREATE OR REPLACE FUNCTION custodial_coverall.bind_manual_application(p_publication uuid, p_expected_receipt_digest text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE initial public.static_weekly_approved_initial_confirmations%rowtype;publication public.weekly_schedule_publications%rowtype;
 version public.weekly_schedule_versions%rowtype;source public.static_weekly_authority_source_documents%rowtype;
 progress custodial_coverall.activation_progress%rowtype;activation custodial_coverall.activation_receipts%rowtype;
 projection public.weekly_schedule_compiled_projections%rowtype;lunch public.weekly_schedule_lunch_documents%rowtype;
 prior custodial_coverall.manual_application_bindings%rowtype;binding uuid;original_projection uuid;revision bigint;receipt jsonb;prior_publication uuid;
BEGIN
 PERFORM public.custodial_begin_application_mutation();PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 SELECT * INTO STRICT publication FROM public.weekly_schedule_publications WHERE publication_id=p_publication;
 SELECT * INTO STRICT initial FROM public.static_weekly_approved_initial_confirmations WHERE publication_id=p_publication;
 SELECT * INTO STRICT version FROM public.weekly_schedule_versions WHERE version_id=publication.version_id;
 SELECT * INTO STRICT source FROM public.static_weekly_authority_source_documents WHERE source_id=version.authority_source_id;
 IF initial.receipt_json->>'schema' IS DISTINCT FROM 'custodial.approved-static-initial-confirmation.v1'
  OR initial.receipt_json->>'status' IS DISTINCT FROM 'PERSISTED_CURRENT' OR initial.receipt_json->'ok' IS DISTINCT FROM 'true'::jsonb
  OR initial.receipt_json->>'publication_id' IS DISTINCT FROM p_publication::text OR initial.receipt_json->>'projection_id' IS DISTINCT FROM initial.projection_id::text
  OR initial.receipt_json->>'source_id' IS DISTINCT FROM source.source_id::text OR initial.request_json->>'sourceId' IS DISTINCT FROM source.source_id::text
  OR initial.request_json->>'idempotencyKey' IS DISTINCT FROM initial.idempotency_key
  OR source.source_digest IS DISTINCT FROM public.static_weekly_digest_jsonb(source.canonical_source)
  OR NOT EXISTS(SELECT 1 FROM public.static_weekly_approved_initial_baselines b WHERE b.source_id=source.source_id
    AND b.feasibility#>>'{candidateSource,version,manualGroupRatingAuthority,manifestSha256}'='fe02bbdebc736d95360b55cc7dfe5b73c5a9eaa76f364f1c0f4420a0afb9950f')
  OR EXISTS(SELECT 1 FROM public.static_weekly_recurring_publication_bindings WHERE publication_id=p_publication)
  THEN RAISE EXCEPTION 'Exact genuine manual initial confirmation/source required';END IF;
 original_projection:=initial.projection_id;receipt:=initial.receipt_json;revision:=(receipt->>'authority_revision')::bigint;
 SELECT * INTO progress FROM custodial_coverall.activation_progress WHERE publication_id=p_publication;
 IF FOUND THEN
  SELECT * INTO STRICT activation FROM custodial_coverall.activation_receipts WHERE operation_id=progress.operation_id;
  receipt:=activation.receipt_json;original_projection:=(receipt->>'projectionId')::uuid;revision:=(receipt->>'authorityRevision')::bigint;
  IF receipt->>'schema' IS DISTINCT FROM 'custodial.approved-manual-coverall-source-confirmation.v2'
   OR receipt->>'kind' IS DISTINCT FROM 'INITIAL_EMPLOYMENT_OPERATIONALIZATION' OR receipt->>'status' IS DISTINCT FROM 'PERSISTED_CURRENT'
   OR receipt->>'operationId' IS DISTINCT FROM progress.operation_id::text OR receipt->>'managerId' IS DISTINCT FROM progress.manager_id::text
   OR receipt->>'publicationId' IS DISTINCT FROM p_publication::text OR receipt->>'sourceId' IS DISTINCT FROM source.source_id::text
   OR receipt->>'versionId' IS DISTINCT FROM version.version_id::text OR receipt->'normalBaselineResult' IS DISTINCT FROM progress.normal_result
   OR NOT EXISTS(SELECT 1 FROM public.static_weekly_manual_activation_confirmations m
     JOIN custodial_coverall.activation_operations o ON o.operation_id=progress.operation_id AND o.packet_id=m.packet_id
     WHERE m.manager_id=progress.manager_id AND m.idempotency_key='coverall-source:'||progress.operation_id::text
      AND initial.manager_id=m.manager_id AND initial.idempotency_key=m.idempotency_key||':initial'
      AND m.receipt_json=progress.normal_result AND m.receipt_digest=public.static_weekly_digest_jsonb(m.receipt_json)
      AND m.receipt_json->>'schema'='custodial.approved-manual-activation-confirmation.v1'
      AND m.receipt_json->>'status'='PERSISTED_CURRENT' AND m.receipt_json->>'publication_id'=initial.publication_id::text
      AND m.receipt_json->>'projection_id'=initial.projection_id::text AND m.receipt_json->>'source_id'=source.source_id::text
      AND m.receipt_json->>'lunch_document_identity'=initial.receipt_json->>'lunch_document_identity')
   OR receipt->'samePhysicalTransaction' IS DISTINCT FROM 'true'::jsonb
   THEN RAISE EXCEPTION 'Exact genuine final operational activation receipt required';END IF;
 END IF;
 IF p_expected_receipt_digest IS NOT NULL AND public.static_weekly_digest_jsonb(receipt) IS DISTINCT FROM p_expected_receipt_digest THEN RAISE EXCEPTION 'Selected original receipt digest differs';END IF;
 SELECT * INTO STRICT projection FROM public.weekly_schedule_compiled_projections WHERE projection_id=original_projection;
 SELECT * INTO STRICT lunch FROM public.weekly_schedule_lunch_documents WHERE projection_id=original_projection;
 PERFORM public.static_weekly_v8_assert_lunch_document(original_projection,lunch.document_json);
 IF projection.publication_id IS DISTINCT FROM p_publication OR projection.version_id IS DISTINCT FROM version.version_id
  OR lunch.document_identity IS DISTINCT FROM coalesce(receipt->>'lunchDocumentIdentity',receipt#>>'{lunchResult,document_identity}',initial.receipt_json->>'lunch_document_identity')
  OR lunch.document_identity IS DISTINCT FROM lunch.document_json->>'document_identity'
  OR projection.week_end IS DISTINCT FROM projection.week_start+6
  THEN RAISE EXCEPTION 'Original full publication/projection/lunch receipt correspondence differs';END IF;
 SELECT publication_id INTO prior_publication FROM public.weekly_schedule_publications WHERE version_id=publication.prior_version_id ORDER BY authority_revision DESC LIMIT 1;
 SELECT * INTO prior FROM custodial_coverall.manual_application_bindings WHERE publication_id=p_publication;
 IF FOUND THEN
  IF prior.source_id IS DISTINCT FROM source.source_id OR prior.source_digest IS DISTINCT FROM source.source_digest OR prior.version_id IS DISTINCT FROM version.version_id
   OR prior.initial_manager_id IS DISTINCT FROM initial.manager_id OR prior.initial_idempotency_key IS DISTINCT FROM initial.idempotency_key
   OR prior.initial_request_json IS DISTINCT FROM initial.request_json OR prior.initial_receipt_json IS DISTINCT FROM initial.receipt_json
   OR prior.initial_receipt_digest IS DISTINCT FROM public.static_weekly_digest_jsonb(initial.receipt_json)
   OR prior.initial_projection_id IS DISTINCT FROM initial.projection_id OR prior.activation_operation_id IS DISTINCT FROM activation.operation_id
   OR prior.activation_receipt_json IS DISTINCT FROM activation.receipt_json OR prior.activation_receipt_digest IS DISTINCT FROM (CASE WHEN activation.operation_id IS NULL THEN NULL ELSE public.static_weekly_digest_jsonb(activation.receipt_json) END)
   OR prior.original_projection_id IS DISTINCT FROM projection.projection_id OR prior.original_lunch_identity IS DISTINCT FROM lunch.document_identity
   OR prior.original_authority_revision IS DISTINCT FROM revision OR prior.frame_start IS DISTINCT FROM projection.week_start OR prior.frame_end IS DISTINCT FROM projection.week_end
   OR prior.predecessor_publication_id IS DISTINCT FROM prior_publication THEN RAISE EXCEPTION 'Immutable original manual delivery binding conflict';END IF;
  RETURN prior.operation_id;
 END IF;
 INSERT INTO custodial_coverall.manual_application_bindings(origin,publication_id,source_id,source_digest,version_id,predecessor_publication_id,
  initial_manager_id,initial_idempotency_key,initial_request_json,initial_receipt_json,initial_receipt_digest,initial_projection_id,
  activation_operation_id,activation_receipt_json,activation_receipt_digest,original_projection_id,original_lunch_identity,original_authority_revision,frame_start,frame_end)
 VALUES('MANUAL_INITIAL',p_publication,source.source_id,source.source_digest,version.version_id,prior_publication,initial.manager_id,initial.idempotency_key,
  initial.request_json,initial.receipt_json,public.static_weekly_digest_jsonb(initial.receipt_json),initial.projection_id,
  activation.operation_id,activation.receipt_json,CASE WHEN activation.operation_id IS NULL THEN NULL ELSE public.static_weekly_digest_jsonb(activation.receipt_json) END,
  original_projection,lunch.document_identity,revision,projection.week_start,projection.week_end) RETURNING operation_id INTO binding;
 RETURN binding;
END $function$

CREATE OR REPLACE FUNCTION custodial_coverall.bind_manual_delivery_after_acceptance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE pub uuid;binding uuid;b custodial_coverall.manual_application_bindings%rowtype;day date;a record;
BEGIN
 IF TG_TABLE_SCHEMA='public' AND TG_TABLE_NAME='static_weekly_approved_initial_confirmations' THEN
  IF NOT EXISTS(SELECT 1 FROM public.static_weekly_approved_initial_baselines baseline WHERE baseline.source_id=(NEW.receipt_json->>'source_id')::uuid
   AND baseline.feasibility#>>'{candidateSource,version,manualGroupRatingAuthority,manifestSha256}'='fe02bbdebc736d95360b55cc7dfe5b73c5a9eaa76f364f1c0f4420a0afb9950f') THEN RETURN NEW;END IF;
  pub:=NEW.publication_id;
 ELSIF TG_TABLE_SCHEMA='custodial_coverall' AND TG_TABLE_NAME='activation_receipts' THEN
  SELECT publication_id INTO STRICT pub FROM custodial_coverall.activation_progress WHERE operation_id=NEW.operation_id;
 ELSE RAISE EXCEPTION 'Exact accepted manual receipt owner required';END IF;
 binding:=custodial_coverall.bind_manual_application(pub,NULL);
 PERFORM custodial_coverall.reconcile_manual_publication(pub);
 SELECT * INTO STRICT b FROM custodial_coverall.manual_application_bindings WHERE operation_id=binding;
 FOR day IN SELECT generate_series(b.frame_start,b.frame_end,'1 day')::date LOOP
  SELECT * INTO a FROM public.static_weekly_v6_schedule_authority_state(day);
  IF a.projection_status IS DISTINCT FROM 'current' OR a.publication_id IS DISTINCT FROM pub OR a.projection_id IS NULL
   OR NOT EXISTS(SELECT 1 FROM public.weekly_schedule_lunch_documents WHERE projection_id=a.projection_id)
   THEN RAISE EXCEPTION 'New manual acceptance requires all seven exact current projection/full-lunch days in this transaction';END IF;
 END LOOP;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION custodial_coverall.lunch_validator_fingerprint()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE signatures text[]:=ARRAY[
 'public.static_weekly_v8_assert_lunch_document(uuid,jsonb)',
 'public.static_weekly_manual_assert_native_lunch(uuid,jsonb,jsonb,uuid,date)',
 'public.static_weekly_manual_assert_lunch_lineage(jsonb,jsonb,uuid,date)',
 'public.static_weekly_manual_native_lunch_policy(jsonb)',
 'public.static_weekly_manual_identity_json(jsonb)',
 'public.static_weekly_assert_exact_object(jsonb,text[],text[],text)',
 'public.static_weekly_capacity_assert_lunch_party(uuid,jsonb,text)',
 'public.static_weekly_capacity_accepted_slot(uuid,date,uuid)',
 'public.static_weekly_capacity_registered(jsonb)',
 'public.static_weekly_digest_jsonb(jsonb)','public.static_weekly_digest_text(text)',
 'public.static_weekly_v3_assert_string_array(jsonb,text,boolean,integer)',
 'public.static_weekly_v3_assert_window(jsonb,text)','public.static_weekly_v3_assert_text(jsonb,text,integer)'];
 wrapper_signatures text[]:=ARRAY[
 'public.static_weekly_v8_materialize_lunch_document(uuid,jsonb,uuid)',
 'custodial_coverall.original_v8_materialize_lunch_document(uuid,jsonb,uuid)',
 'custodial_coverall.owner_revalidate_lunch_admission(uuid)',
 'custodial_coverall.require_lunch_admission_proof(uuid,jsonb)',
 'custodial_coverall.lunch_validator_fingerprint()',
 'public.static_weekly_reject_update_delete()','custodial_dr.guard_application_mutation()',
 'public.static_weekly_v27_notification_plan_source_write_fence()'];
 signature text;qualified_names text[];oid_value oid;definition text;definitions jsonb:='[]';wrappers jsonb:='[]';relations jsonb:='[]';
 relation text;crypto_schema text;crypto jsonb;metadata jsonb;
BEGIN
 SELECT array_agg(split_part(value,'(',1)) INTO qualified_names FROM unnest(signatures) value;
 FOREACH signature IN ARRAY signatures LOOP
  oid_value:=to_regprocedure(signature);IF oid_value IS NULL THEN RAISE EXCEPTION 'Complete full-lunch guard closure missing: %',signature USING ERRCODE='55000';END IF;
  definition:=pg_get_functiondef(oid_value);
  -- Changed definitions invalidate old proofs. New/unlisted nonbuilt-in guard
  -- callees or unsupported dynamic SQL refuse until this owning Source updates.
  IF EXISTS(SELECT 1 FROM regexp_matches(definition,'\m(public|custodial_coverall|extensions)\.([a-z_][a-z_0-9]*)[[:space:]]*\(','gi') m(parts)
   WHERE NOT(lower(m.parts[1]||'.'||m.parts[2])=ANY(qualified_names))) THEN
   RAISE EXCEPTION 'Unsupported changed full-lunch guard call closure: %',signature USING ERRCODE='55000';END IF;
  IF definition~*'\mexecute\M' AND signature<>'public.static_weekly_digest_text(text)' THEN RAISE EXCEPTION 'Unsupported dynamic full-lunch guard: %',signature USING ERRCODE='55000';END IF;
  IF signature='public.static_weekly_digest_text(text)' AND public.static_weekly_digest_text(definition)<>'5337ef6187e2febb0668f1350092fa49de3258317ae19537317a889900a0e1c3'
   THEN RAISE EXCEPTION 'Unsupported dynamic digest helper changed' USING ERRCODE='55000';END IF;
  SELECT jsonb_build_object('signature',signature,'oid',p.oid::text,'definition',definition,'owner',pg_get_userbyid(p.proowner),
   'securityDefiner',p.prosecdef,'volatility',p.provolatile,'config',to_jsonb(p.proconfig),'acl',p.proacl::text,'binary',p.probin,'source',p.prosrc) INTO metadata FROM pg_proc p WHERE p.oid=oid_value;
  definitions:=definitions||jsonb_build_array(metadata);
 END LOOP;
 FOREACH signature IN ARRAY wrapper_signatures LOOP
  oid_value:=to_regprocedure(signature);IF oid_value IS NULL THEN RAISE EXCEPTION 'Complete admission wrapper missing: %',signature USING ERRCODE='55000';END IF;
  SELECT jsonb_build_object('signature',signature,'oid',p.oid::text,'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),
   'securityDefiner',p.prosecdef,'config',to_jsonb(p.proconfig),'acl',p.proacl::text) INTO metadata FROM pg_proc p WHERE p.oid=oid_value;
  wrappers:=wrappers||jsonb_build_array(metadata);
 END LOOP;
 FOREACH relation IN ARRAY ARRAY['public.weekly_schedule_compiled_projections','public.weekly_schedule_lunch_documents','custodial_coverall.manual_lunch_admission_proofs'] LOOP
  oid_value:=to_regclass(relation);IF oid_value IS NULL THEN RAISE EXCEPTION 'Immutable admission relation missing';END IF;
  SELECT jsonb_build_object('relation',relation,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'acl',c.relacl::text,
   'columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
   'constraints',(SELECT jsonb_agg(jsonb_build_array(x.conname,pg_get_constraintdef(x.oid),x.convalidated) ORDER BY x.conname COLLATE "C") FROM pg_constraint x WHERE x.conrelid=c.oid),
   'triggers',(SELECT jsonb_agg(jsonb_build_array(t.tgname,pg_get_triggerdef(t.oid),t.tgenabled) ORDER BY t.tgname COLLATE "C") FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal)) INTO metadata FROM pg_class c WHERE c.oid=oid_value;
  relations:=relations||jsonb_build_array(metadata);
 END LOOP;
 SELECT n.nspname,jsonb_build_object('name',e.extname,'version',e.extversion,'namespace',n.nspname) INTO crypto_schema,crypto FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace WHERE e.extname='pgcrypto';
 IF crypto_schema IS NULL OR crypto_schema NOT IN('extensions','public') THEN RAISE EXCEPTION 'Exact installed pgcrypto guard unavailable';END IF;
 oid_value:=to_regprocedure(format('%I.digest(bytea,text)',crypto_schema));IF oid_value IS NULL THEN RAISE EXCEPTION 'Actual SHA256 function unavailable';END IF;
 SELECT crypto||jsonb_build_object('oid',p.oid::text,'definition',pg_get_functiondef(p.oid),'source',p.prosrc,'binary',p.probin,'owner',pg_get_userbyid(p.proowner)) INTO crypto FROM pg_proc p WHERE p.oid=oid_value;
 RETURN public.static_weekly_digest_jsonb(jsonb_build_object('schema','custodial.full-lunch-validator-closure.v1','serverVersion',current_setting('server_version_num'),
  'guards',definitions,'admissionWrappers',wrappers,'immutableRelations',relations,'crypto',crypto));
END $function$

CREATE OR REPLACE FUNCTION custodial_coverall.original_v8_materialize_lunch_document(p_projection_id uuid, p_document jsonb, p_manager_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare projection public.weekly_schedule_compiled_projections%rowtype;
 existing public.weekly_schedule_lunch_documents%rowtype;current_authority record;inserted integer;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform public.static_weekly_v3_manager_actor(p_manager_id);
 perform public.custodial_begin_application_mutation();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select * into projection from public.weekly_schedule_compiled_projections where projection_id=p_projection_id;
 if not found then raise exception 'lunch projection does not exist'; end if;
 select * into current_authority from public.static_weekly_v6_schedule_authority_state(projection.week_start);
 if current_authority.projection_status is distinct from 'current'
  or current_authority.projection_id is distinct from p_projection_id then raise exception 'lunch projection is not current'; end if;
 perform public.static_weekly_v8_assert_lunch_document(p_projection_id,p_document);
 insert into public.weekly_schedule_lunch_documents(projection_id,document_identity,document_json,accepted_by_manager_id)
 values(p_projection_id,p_document->>'document_identity',p_document,p_manager_id) on conflict(projection_id) do nothing;
 get diagnostics inserted=row_count;
 select * into strict existing from public.weekly_schedule_lunch_documents where projection_id=p_projection_id;
 if existing.document_json is distinct from p_document then raise exception 'immutable lunch publication conflicts with existing authority'; end if;
 return jsonb_build_object('ok',true,'persistence_status','PERSISTED','projection_id',p_projection_id,
  'document_identity',existing.document_identity,'replayed',inserted=0);
end $function$

CREATE OR REPLACE FUNCTION custodial_coverall.owner_revalidate_lunch_admission(p_projection uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE projection public.weekly_schedule_compiled_projections%rowtype;document public.weekly_schedule_lunch_documents%rowtype;
 proof custodial_coverall.manual_lunch_admission_proofs%rowtype;before_fingerprint text;after_fingerprint text;
BEGIN
 IF current_user IS DISTINCT FROM session_user OR session_user NOT IN('postgres','supabase_admin')
  OR coalesce(current_setting('role',true),'none') NOT IN('none',session_user::text)
  THEN RAISE EXCEPTION 'Actual owning administrator must explicitly revalidate stored lunch' USING ERRCODE='42501';END IF;
 PERFORM public.custodial_begin_application_mutation();PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 SELECT * INTO STRICT projection FROM public.weekly_schedule_compiled_projections WHERE projection_id=p_projection FOR SHARE;
 SELECT * INTO STRICT document FROM public.weekly_schedule_lunch_documents WHERE projection_id=p_projection FOR SHARE;
 before_fingerprint:=custodial_coverall.lunch_validator_fingerprint();
 -- Always REAL complete validation of the actual stored body, not caller data,
 -- a prepared label, GUC, cached boolean or success receipt. Historical rows stay.
 PERFORM public.static_weekly_v8_assert_lunch_document(p_projection,document.document_json);
 after_fingerprint:=custodial_coverall.lunch_validator_fingerprint();
 IF after_fingerprint IS DISTINCT FROM before_fingerprint THEN RAISE EXCEPTION 'Lunch validator changed during full revalidation';END IF;
 INSERT INTO custodial_coverall.manual_lunch_admission_proofs(projection_id,document_identity,validator_fingerprint,projection_digest,document_digest,full_projection_json,full_document_json)
 VALUES(p_projection,document.document_identity,after_fingerprint,public.static_weekly_digest_jsonb(to_jsonb(projection)),
  public.static_weekly_digest_jsonb(document.document_json),to_jsonb(projection),document.document_json) ON CONFLICT DO NOTHING;
 PERFORM custodial_coverall.require_lunch_admission_proof(p_projection,document.document_json);
 SELECT * INTO STRICT proof FROM custodial_coverall.manual_lunch_admission_proofs WHERE projection_id=p_projection AND document_identity=document.document_identity AND validator_fingerprint=after_fingerprint;
 RETURN jsonb_build_object('schema','custodial.full-lunch-admission-proof.v1','projectionId',proof.projection_id,'documentIdentity',proof.document_identity,
  'validatorFingerprint',proof.validator_fingerprint,'projectionDigest',proof.projection_digest,'documentDigest',proof.document_digest,
  'validatedAt',proof.validated_at,'validationTransactionId',proof.validation_transaction::text,'scope','FULL_STORED_VALIDATION_ONLY_NOT_CURRENT_AUTHORITY_OR_DEVICE_DELIVERY');
END $function$

CREATE OR REPLACE FUNCTION custodial_coverall.read_manual_application_target(p_date date, p_device uuid, p_credential uuid, p_employee uuid, p_epoch bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare t custodial_coverall.manual_application_intents%rowtype;receipt custodial_coverall.manual_application_receipts%rowtype;a record;
begin
 if p_date is null or not isfinite(p_date) then raise exception 'recurring application read requires finite date';end if;
 perform public.static_weekly_v19_assert_terminal_principal(p_device,p_credential,p_employee,p_epoch);
 if not exists(select 1 from public.employees where id=p_employee and active=true) then
  raise exception using errcode='42501',message='recurring schedule requires an active employee principal';end if;
 select * into a from public.static_weekly_v6_schedule_authority_state(p_date);
 if a.projection_status='blocked_recurring_authority' then return public.static_weekly_v19_read_terminal_target(p_date,p_device,p_credential,p_employee,p_epoch);end if;
 select * into t from custodial_coverall.manual_application_intents i
  where i.service_date=p_date and i.device_id=p_device and i.credential_id=p_credential
   and i.employee_id=p_employee and i.assignment_epoch=p_epoch
  order by i.authority_revision desc,i.created_at desc,i.intent_id desc limit 1;
 if not found then
  if exists(select 1 from custodial_coverall.manual_application_bindings where publication_id=a.publication_id) then
   return jsonb_build_object('applicationStatus','PENDING_TARGET_RECONCILIATION','affectedPhonesUpdated',false);end if;
  return null;
 end if;
 if a.projection_status is distinct from 'current' or t.publication_id is distinct from a.publication_id
  or t.projection_id is distinct from a.projection_id or t.authority_revision is distinct from a.projection_authority_revision
  or not exists(select 1 from public.weekly_schedule_lunch_documents l where l.projection_id=a.projection_id and l.document_identity=t.lunch_document_identity) then
  return jsonb_build_object('applicationStatus','PENDING_TARGET_RECONCILIATION','affectedPhonesUpdated',false);end if;
 if t.target_json->>'operationId' is distinct from t.operation_id::text or t.target_digest is distinct from public.static_weekly_digest_jsonb(t.target_json)
  or t.view_digest is distinct from public.static_weekly_digest_jsonb(t.view_json)
  or not exists(select 1 from custodial_coverall.manual_application_bindings b join public.weekly_schedule_versions v using(version_id)
    join public.static_weekly_authority_source_documents s on s.source_id=v.authority_source_id
    where b.operation_id=t.operation_id and b.publication_id=a.publication_id and s.source_id=b.source_id and s.source_digest=b.source_digest and s.active=true)
  then raise exception 'Exact typed manual intent/current source bytes differ';end if;
 -- Current typed recurring data must retain its actual immutable admission,
 -- even when a target already exists. Metadata/mode alone is not acceptance.
 if exists(select 1 from public.weekly_schedule_compiled_projections p where p.projection_id=a.projection_id
   and (p.projection_envelope#>'{semantic_snapshot,recurringOperation}' is not null
     or p.projection_envelope#>>'{adapter,schema}'='custodial.approved-manual-recurring-reference-adapter.v1'))
  and not custodial_coverall.manual_recurring_projection_accepted(t.operation_id,a.projection_id,a.projection_authority_revision)
 then raise exception 'Exact current typed recurring acceptance is unavailable';end if;
 select * into receipt from custodial_coverall.manual_application_receipts where intent_id=t.intent_id;
 return jsonb_build_object('intentId',t.intent_id,'target',t.target_json,'targetDigest',t.target_digest,
  'view',t.view_json,'viewJsonText',t.view_json::text,'viewDigest',t.view_digest,
  'applicationStatus',case when receipt.intent_id is null then 'PENDING' else 'DEVICE_REPORTED_APPLIED' end,
  'receiptId',receipt.receipt_id,'appliedAt',receipt.applied_at,'receivedAt',receipt.received_at);
end
$function$

CREATE OR REPLACE FUNCTION custodial_coverall.reconcile_manual_application_date(p_date date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a record;b custodial_coverall.manual_application_bindings%rowtype;
 current_projection public.weekly_schedule_compiled_projections%rowtype;l public.weekly_schedule_lunch_documents%rowtype;
person record;device record;v_view jsonb;v_target jsonb;v_view_digest text;v_intent uuid;v_count int:=0;v_devices int;
v_recurring_accepted boolean:=false;
begin
 if p_date is null or not isfinite(p_date) then raise exception 'recurring application reconciliation requires one finite date';end if;
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select * into a from public.static_weekly_v6_schedule_authority_state(p_date);
 if a.projection_status='blocked_recurring_authority' then return public.static_weekly_v19_reconcile_terminal_date(p_date);end if;
 if a.projection_status is distinct from 'current' or a.projection_id is null then raise exception 'recurring schedule projection is unavailable';end if;
 select * into b from custodial_coverall.manual_application_bindings where publication_id=a.publication_id;
 if not found then return 0;end if;
 select * into strict current_projection from public.weekly_schedule_compiled_projections where projection_id=a.projection_id;
 if current_projection.publication_id is distinct from b.publication_id or current_projection.version_id is distinct from b.version_id
  or not exists(select 1 from public.weekly_schedule_versions v join public.static_weekly_authority_source_documents s on s.source_id=v.authority_source_id
    where v.version_id=b.version_id and s.source_id=b.source_id and s.source_digest=b.source_digest and s.active=true)
  or not exists(select 1 from public.static_weekly_approved_initial_confirmations i where i.publication_id=b.publication_id and i.manager_id=b.initial_manager_id
    and i.idempotency_key=b.initial_idempotency_key and i.receipt_json=b.initial_receipt_json and i.request_json=b.initial_request_json
    and public.static_weekly_digest_jsonb(i.receipt_json)=b.initial_receipt_digest)
  then raise exception 'Manual target origin/current source correspondence differs';end if;
 if current_projection.projection_id<>b.original_projection_id then
  v_recurring_accepted:=custodial_coverall.manual_recurring_projection_accepted(b.operation_id,current_projection.projection_id,a.projection_authority_revision);
 end if;
 if current_projection.projection_id<>b.original_projection_id and not v_recurring_accepted and
  (current_projection.projection_envelope#>>'{authority,schema}' is distinct from 'custodial.approved-manual-period-projection-authority.v1'
   or current_projection.projection_envelope#>>'{adapter,schema}' is distinct from 'custodial.approved-manual-period-database-adapter.v1'
   or current_projection.projection_envelope#>>'{authority,sourcePublicationId}' is distinct from b.publication_id::text
   or current_projection.projection_envelope#>>'{authority,sourceVersionId}' is distinct from b.version_id::text
   or current_projection.projection_envelope#>'{authority,normalSourceChanged}' is distinct from 'false'::jsonb)
  then raise exception 'Only accepted original or exact native manual lineage creates targets';end if;
 if current_projection.projection_id<>b.original_projection_id and not v_recurring_accepted and not exists(
  select 1 from public.static_weekly_staffing_commands command
  join public.static_weekly_staffing_staged_candidates staged on staged.operation_id=command.operation_id and staged.candidate_kind='projection'
  join public.static_weekly_staffing_command_receipts receipt on receipt.operation_id=command.operation_id and receipt.event_kind='ACCEPTED'
  where command.state='ACCEPTED' and staged.payload_json->'envelope'=current_projection.projection_envelope
   and command.accepted_receipt->>'event'='ACCEPTED' and command.accepted_receipt->>'operation_id'=command.operation_id::text
   and command.accepted_receipt->>'semantic_digest'=command.semantic_digest
   and command.accepted_receipt#>>ARRAY['projections',current_projection.week_start::text,'publication_id']=b.publication_id::text
   and command.accepted_receipt#>>ARRAY['projections',current_projection.week_start::text,'projection_id']=current_projection.projection_id::text
   and receipt.receipt_json=command.accepted_receipt and receipt.receipt_digest=public.static_weekly_digest_jsonb(receipt.receipt_json))
  then raise exception 'Prepared native document is not an accepted original operation';end if;
 if b.activation_operation_id is not null and not exists(select 1 from custodial_coverall.activation_receipts r where r.operation_id=b.activation_operation_id
  and r.receipt_json=b.activation_receipt_json and public.static_weekly_digest_jsonb(r.receipt_json)=b.activation_receipt_digest)
  then raise exception 'Original operational activation receipt changed';end if;
 select * into l from public.weekly_schedule_lunch_documents where projection_id=a.projection_id;
 if not found then raise exception 'exact recurring lunch companion is unavailable';end if;
 if current_projection.projection_id<>b.original_projection_id and not v_recurring_accepted and not exists(select 1 from public.static_weekly_staffing_commands command
  where command.state='ACCEPTED' and command.accepted_receipt#>>ARRAY['projections',current_projection.week_start::text,'projection_id']=current_projection.projection_id::text
   and command.accepted_receipt#>>ARRAY['projections',current_projection.week_start::text,'lunch_document_identity']=l.document_identity)
  then raise exception 'Accepted original native full lunch correspondence differs';end if;
 for person in with people as (
  select (r->>'incumbentPersonId')::uuid employee_id from jsonb_array_elements(coalesce(current_projection.projection_envelope#>'{authority,projectionAvailability}','[]')) r
   where r->>'incumbentPersonId' is not null and r->>'serviceDate'=p_date::text
  union select (r->>'incumbentPersonId')::uuid from public.weekly_schedule_compiled_projections old
   cross join lateral jsonb_array_elements(coalesce(old.projection_envelope#>'{authority,projectionAvailability}','[]')) r
   where old.projection_id=b.original_projection_id and r->>'incumbentPersonId' is not null
    and extract(isodow from (r->>'serviceDate')::date)=extract(isodow from p_date)
  union select (r->>'personId')::uuid from public.weekly_schedule_versions v
   cross join lateral jsonb_array_elements(coalesce(v.draft_document#>'{authority,compilerInput,roster}','[]')) r
   where v.version_id=b.version_id and r->>'personId' is not null
    and extract(isodow from (r->>'serviceDate')::date)=extract(isodow from p_date)
  union select old.employee_id from custodial_coverall.manual_application_intents old where old.publication_id=b.publication_id and old.service_date=p_date
  union select x.owner_person_id_snapshot from public.weekly_schedule_occurrences x join public.weekly_schedule_compiled_projections projection using(projection_id)
   where projection.publication_id in(b.publication_id,b.predecessor_publication_id) and x.service_date=p_date and x.owner_person_id_snapshot is not null
  union select (r->>'normal_owner_person_id')::uuid from public.weekly_schedule_lunch_documents lunch join public.weekly_schedule_compiled_projections projection using(projection_id)
   cross join lateral jsonb_array_elements(lunch.document_json->'responsibilities') r
   where projection.publication_id in(b.publication_id,b.predecessor_publication_id) and r->>'service_date'=p_date::text and r->>'normal_owner_person_id' is not null
  union select (r->>'coverer_person_id')::uuid from public.weekly_schedule_lunch_documents lunch join public.weekly_schedule_compiled_projections projection using(projection_id)
   cross join lateral jsonb_array_elements(lunch.document_json->'responsibilities') r
   where projection.publication_id in(b.publication_id,b.predecessor_publication_id) and r->>'service_date'=p_date::text and r->>'coverer_person_id' is not null
 ) select distinct people.employee_id from people join public.employees e on e.id=people.employee_id order by people.employee_id loop
  v_view:=public.static_weekly_v22_recurring_render_view(a.projection_id,p_date,person.employee_id);
  v_view_digest:=public.static_weekly_digest_jsonb(v_view);v_devices:=0;
  -- Rotation/reconnect must not silently create a different view at the same
  -- authority identity, nor make ON CONFLICT hide changed display bytes.
  if exists(select 1 from custodial_coverall.manual_application_intents i
   where i.publication_id=a.publication_id and i.projection_id=a.projection_id
    and i.service_date=p_date and i.employee_id=person.employee_id
    and i.authority_revision=a.projection_authority_revision
    and (i.view_json is distinct from v_view or i.view_digest is distinct from v_view_digest
      or i.lunch_document_identity is distinct from l.document_identity)) then
   raise exception using errcode='23514',message='recurring render changed without a new exact authority identity';end if;
  for device in select d.id,c.credential_id,d.assignment_epoch from public.devices d
   join public.device_auth_credentials c on c.device_id=d.id and c.confirmed_at is not null
    and c.revoked_at is null and c.expires_at>statement_timestamp()
   where d.active=true and d.assigned_employee_id=person.employee_id
   order by d.id,c.credential_id loop
   v_devices:=v_devices+1;
   v_target:=jsonb_build_object('schema','static-weekly.recurring-application-target.v1','targetType','SCHEDULE',
    'operationId',b.operation_id,'publicationId',a.publication_id,'projectionId',a.projection_id,'serviceDate',p_date,
    'authorityRevision',a.projection_authority_revision,'lunchDocumentIdentity',l.document_identity,
    'employeeId',person.employee_id,'deviceId',device.id,'credentialId',device.credential_id,
    'assignmentEpoch',device.assignment_epoch,'viewDigest',v_view_digest);
   insert into custodial_coverall.manual_application_intents(operation_id,publication_id,projection_id,service_date,
    employee_id,device_id,credential_id,assignment_epoch,authority_revision,lunch_document_identity,view_json,view_digest,target_json,target_digest)
   values(b.operation_id,a.publication_id,a.projection_id,p_date,person.employee_id,device.id,device.credential_id,
    device.assignment_epoch,a.projection_authority_revision,l.document_identity,v_view,v_view_digest,v_target,public.static_weekly_digest_jsonb(v_target))
   on conflict do nothing returning intent_id into v_intent;
   if found then v_count:=v_count+1;end if;
  end loop;
  if v_devices=0 then
   v_target:=jsonb_build_object('schema','static-weekly.recurring-application-target.v1','targetType','SCHEDULE',
    'operationId',b.operation_id,'publicationId',a.publication_id,'projectionId',a.projection_id,'serviceDate',p_date,
    'authorityRevision',a.projection_authority_revision,'lunchDocumentIdentity',l.document_identity,
    'employeeId',person.employee_id,'deviceId',null,'credentialId',null,'assignmentEpoch',null,'viewDigest',v_view_digest);
   insert into custodial_coverall.manual_application_intents(operation_id,publication_id,projection_id,service_date,
    employee_id,authority_revision,lunch_document_identity,view_json,view_digest,target_json,target_digest)
   values(b.operation_id,a.publication_id,a.projection_id,p_date,person.employee_id,a.projection_authority_revision,
    l.document_identity,v_view,v_view_digest,v_target,public.static_weekly_digest_jsonb(v_target))
   on conflict do nothing returning intent_id into v_intent;
   if found then v_count:=v_count+1;end if;
  end if;
 end loop;
 return v_count;
end
$function$

CREATE OR REPLACE FUNCTION custodial_coverall.reconcile_manual_delivery_after_lunch()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE projection public.weekly_schedule_compiled_projections%rowtype;day date;a record;
BEGIN
 SELECT * INTO STRICT projection FROM public.weekly_schedule_compiled_projections WHERE projection_id=NEW.projection_id;
 IF EXISTS(SELECT 1 FROM custodial_coverall.manual_application_bindings WHERE publication_id=projection.publication_id) THEN
  FOR day IN SELECT generate_series(projection.week_start,projection.week_end,'1 day')::date LOOP
   SELECT * INTO a FROM public.static_weekly_v6_schedule_authority_state(day);
   IF a.projection_status='current' AND a.publication_id=projection.publication_id AND a.projection_id=projection.projection_id
    THEN PERFORM custodial_coverall.reconcile_manual_application_date(day);END IF;
  END LOOP;
 END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION custodial_coverall.reconcile_manual_delivery_after_recurring_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE operation custodial_coverall.recurring_materialization_operations%rowtype;
 binding uuid;projection uuid;day date;a record;
BEGIN
 IF TG_TABLE_SCHEMA<>'custodial_coverall' OR TG_TABLE_NAME<>'recurring_materialization_receipts'
 THEN RAISE EXCEPTION 'Exact typed recurring receipt owner required';END IF;
 SELECT * INTO STRICT operation FROM custodial_coverall.recurring_materialization_operations WHERE operation_id=NEW.operation_id;
 SELECT operation_id INTO STRICT binding FROM custodial_coverall.manual_application_bindings WHERE publication_id=operation.publication_id;
 projection:=(NEW.receipt_json->>'projectionId')::uuid;
 IF NOT custodial_coverall.manual_recurring_projection_accepted(binding,projection,(NEW.receipt_json->>'authorityRevision')::bigint,NEW.operation_id)
 THEN RAISE EXCEPTION 'Actual accepted recurring receipt required before delivery reconciliation';END IF;
 FOR day IN SELECT generate_series(operation.frame_start,operation.frame_start+6,'1 day')::date LOOP
  SELECT * INTO a FROM public.static_weekly_v6_schedule_authority_state(day);
  IF a.projection_status='current' AND a.publication_id=operation.publication_id AND a.projection_id=projection
   THEN PERFORM custodial_coverall.reconcile_manual_application_date(day);END IF;
 END LOOP;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION custodial_coverall.reconcile_manual_publication(p_publication uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE b custodial_coverall.manual_application_bindings%rowtype;day date;a record;
BEGIN
 SELECT * INTO STRICT b FROM custodial_coverall.manual_application_bindings WHERE publication_id=p_publication;
 FOR day IN SELECT DISTINCT d::date FROM public.weekly_schedule_compiled_projections p
  JOIN public.weekly_schedule_lunch_documents l USING(projection_id)
  CROSS JOIN LATERAL generate_series(p.week_start,p.week_end,'1 day') d WHERE p.publication_id=b.publication_id ORDER BY d::date LOOP
  SELECT * INTO a FROM public.static_weekly_v6_schedule_authority_state(day);
  IF a.projection_status='current' AND a.publication_id=b.publication_id THEN PERFORM custodial_coverall.reconcile_manual_application_date(day);END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION custodial_coverall.require_lunch_admission_proof(p_projection uuid, p_document jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE projection public.weekly_schedule_compiled_projections%rowtype;document public.weekly_schedule_lunch_documents%rowtype;
 proof custodial_coverall.manual_lunch_admission_proofs%rowtype;fingerprint text;
BEGIN
 IF p_projection IS NULL OR jsonb_typeof(p_document) IS DISTINCT FROM 'object' OR coalesce(p_document->>'document_identity','')!~'^[a-f0-9]{64}$'
  THEN RAISE EXCEPTION 'Exact immutable admitted lunch document required' USING ERRCODE='55000';END IF;
 SELECT * INTO STRICT projection FROM public.weekly_schedule_compiled_projections WHERE projection_id=p_projection;
 SELECT * INTO STRICT document FROM public.weekly_schedule_lunch_documents WHERE projection_id=p_projection;
 fingerprint:=custodial_coverall.lunch_validator_fingerprint();
 SELECT * INTO proof FROM custodial_coverall.manual_lunch_admission_proofs WHERE projection_id=p_projection
  AND document_identity=document.document_identity AND validator_fingerprint=fingerprint;
 IF NOT FOUND OR document.document_identity IS DISTINCT FROM p_document->>'document_identity'
  OR document.document_json IS DISTINCT FROM p_document OR proof.full_document_json IS DISTINCT FROM p_document
  OR proof.full_projection_json IS DISTINCT FROM to_jsonb(projection)
  THEN RAISE EXCEPTION 'Full lunch admission proof missing, stale, or source bytes changed; owner revalidation required' USING ERRCODE='55000';END IF;
 -- Snapshot digests are CHECK-constrained at admission; exact full JSONB source
 -- equality above binds these admitted hashes without repeating all-loan math.
END $function$

CREATE OR REPLACE FUNCTION custodial_employment.admit(p_command jsonb, p_credential_id uuid, p_device_id text, p_session_access text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE employee uuid;manager uuid;request uuid;expected_authority bigint;expected_employment bigint;
 current_authority bigint;previous custodial_employment.admissions%rowtype;
 replay custodial_employment.admissions%rowtype;admitted custodial_employment.admissions%rowtype;
 actor jsonb;f jsonb;initial_fact jsonb;effective date;first_day date;state text;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();
 PERFORM public.static_weekly_assert_exact_object(p_command,
  ARRAY['schema','requestId','managerId','employeeId','expectedAuthorityRevision','expectedEmploymentRevision','fact'],
  ARRAY['schema','requestId','managerId','employeeId','expectedAuthorityRevision','expectedEmploymentRevision','fact'],'employment command');
 IF p_command->>'schema' IS DISTINCT FROM 'custodial.employment-admission-command.v1'
  OR jsonb_typeof(p_command->'expectedAuthorityRevision') IS DISTINCT FROM 'number'
  OR jsonb_typeof(p_command->'expectedEmploymentRevision') IS DISTINCT FROM 'number'
  OR coalesce(p_command->>'expectedAuthorityRevision','') !~ '^(0|[1-9][0-9]{0,15})$'
  OR coalesce(p_command->>'expectedEmploymentRevision','') !~ '^(0|[1-9][0-9]{0,15})$'
  OR coalesce(p_command->>'employeeId','') NOT IN ('1318b295-fd70-4e78-8828-62c29302f96f','d5fecc86-659b-464a-bc99-f0d914385db4')
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Exact scoped employment command required'; END IF;
 employee:=(p_command->>'employeeId')::uuid;manager:=(p_command->>'managerId')::uuid;request:=(p_command->>'requestId')::uuid;
 IF manager IS NULL OR request IS NULL THEN RAISE EXCEPTION 'Explicit manager and request identities required'; END IF;
 expected_authority:=(p_command->>'expectedAuthorityRevision')::bigint;
 expected_employment:=(p_command->>'expectedEmploymentRevision')::bigint;
 IF expected_authority>9007199254740990 OR expected_employment>9007199254740990 THEN RAISE EXCEPTION 'Revision out of bounds'; END IF;
 -- Reuse the maintained write action. Pre-start is NOT delegated PTO.
 actor:=public.custodial_action_actor_v1(manager,p_credential_id,p_device_id,p_session_access,'write');
 PERFORM public.static_weekly_v3_manager_actor(manager);
 IF actor->>'manager_id' IS DISTINCT FROM manager::text OR NOT (
  actor->'owner'='true'::jsonb OR (
   actor->>'actor_kind'='CUSTODIAL_LEADERSHIP_COHORT' AND actor->'owner'='false'::jsonb
   AND actor->'custodialManagementAdmin'='true'::jsonb
   AND actor->>'credential_id'=p_credential_id::text AND actor->>'device_id'=p_device_id
   AND coalesce(actor->>'request_id','') ~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$')) IS TRUE
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Current Custodial management authority required'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 SELECT * INTO replay FROM custodial_employment.admissions WHERE request_id=request;
 IF FOUND THEN
  IF replay.command IS DISTINCT FROM p_command OR replay.manager_id<>manager THEN
   RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='Employment request reused with changed identity or facts'; END IF;
  RETURN jsonb_build_object('schema','custodial.employment-admission-receipt.v1','status','ACCEPTED',
   'employeeId',replay.employee_id,'employmentRevision',replay.employment_revision,
   'acceptedAuthorityRevision',replay.authority_revision,'acceptedByManagerId',replay.manager_id,'command',replay.command);
 END IF;
 SELECT current_revision INTO STRICT current_authority FROM public.static_weekly_schedule_control WHERE singleton FOR SHARE;
 IF current_authority<>expected_authority THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Employment authority revision changed'; END IF;
 PERFORM 1 FROM public.employees WHERE id=employee AND active IS TRUE
  AND display_name=CASE WHEN employee='1318b295-fd70-4e78-8828-62c29302f96f'::uuid THEN 'Xavier Green' ELSE 'Jada Rawlings' END FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Existing active employee identity required; this RPC creates no employee'; END IF;
 f:=p_command->'fact';
 PERFORM public.static_weekly_assert_exact_object(f,
  ARRAY['effectiveFrom','state','ownerEvidenceSha256'],
  ARRAY['effectiveFrom','state','firstServiceDate','approvedLunch','ownerEvidenceSha256'],'employment fact');
 IF NOT (f ?& ARRAY['firstServiceDate','approvedLunch']) THEN RAISE EXCEPTION 'Both nullable employment fields must be present';END IF;
 IF coalesce(f->>'effectiveFrom','') !~ '^[12][0-9]{3}-[0-9]{2}-[0-9]{2}$'
  OR coalesce(f->>'ownerEvidenceSha256','') !~ '^[a-f0-9]{64}$'
  OR f->>'state' NOT IN ('PRE_START','START_DATE_CONFIRMED') OR f->>'state' IS NULL
 THEN RAISE EXCEPTION 'Typed dated employment fact required'; END IF;
 effective:=(f->>'effectiveFrom')::date;state:=f->>'state';
 IF NOT isfinite(effective) OR effective::text<>(f->>'effectiveFrom')
 THEN RAISE EXCEPTION 'Invalid employment fact date'; END IF;
 IF state='PRE_START' THEN
  IF f->'firstServiceDate' IS DISTINCT FROM 'null'::jsonb OR f->'approvedLunch' IS DISTINCT FROM 'null'::jsonb
  THEN RAISE EXCEPTION 'Pre-start has no invented start or lunch'; END IF;
 ELSE
  IF coalesce(f->>'firstServiceDate','') !~ '^[12][0-9]{3}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'Explicit first service date required'; END IF;
  first_day:=(f->>'firstServiceDate')::date;
  IF NOT isfinite(first_day) OR first_day::text<>f->>'firstServiceDate' OR first_day<effective THEN RAISE EXCEPTION 'Invalid or backdated first service date'; END IF;
 END IF;
 IF f->'approvedLunch' IS DISTINCT FROM 'null'::jsonb THEN
  PERFORM public.static_weekly_assert_exact_object(f->'approvedLunch',ARRAY['start','end'],ARRAY['start','end'],'employment lunch');
  IF coalesce(f#>>'{approvedLunch,start}','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
   OR coalesce(f#>>'{approvedLunch,end}','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
   OR (f#>>'{approvedLunch,end}')::time-(f#>>'{approvedLunch,start}')::time<>interval '1 hour'
  THEN RAISE EXCEPTION 'An approved lunch remains one full hour'; END IF;
 END IF;
 -- Immutable Xavier instruction; no normal lunch-edit authority is introduced.
 IF employee='1318b295-fd70-4e78-8828-62c29302f96f'::uuid AND
  (state<>'START_DATE_CONFIRMED' OR first_day IS DISTINCT FROM date '2026-11-01'
   OR f->'approvedLunch' IS DISTINCT FROM '{"start":"12:30","end":"13:30"}'::jsonb)
 THEN RAISE EXCEPTION 'Xavier first service date or approved lunch differs'; END IF;
 SELECT * INTO previous FROM custodial_employment.admissions WHERE employee_id=employee ORDER BY employment_revision DESC LIMIT 1 FOR UPDATE;
 IF coalesce(previous.employment_revision,0)<>expected_employment THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Employee admission revision changed'; END IF;
 IF previous.employment_revision IS NULL THEN
  initial_fact:=jsonb_build_object('effectiveFrom','2026-10-30','state',CASE WHEN employee='1318b295-fd70-4e78-8828-62c29302f96f'::uuid THEN 'START_DATE_CONFIRMED' ELSE 'PRE_START' END,
   'firstServiceDate',CASE WHEN employee='1318b295-fd70-4e78-8828-62c29302f96f'::uuid THEN '2026-11-01' ELSE NULL END,
   'approvedLunch',CASE WHEN employee='1318b295-fd70-4e78-8828-62c29302f96f'::uuid THEN '{"start":"12:30","end":"13:30"}'::jsonb ELSE 'null'::jsonb END,
   'ownerEvidenceSha256','be6c3f5818a8ae1804b85064e083949662710c8d4ced118823ce2bbc6afdaf5c');
  IF f IS DISTINCT FROM initial_fact THEN RAISE EXCEPTION 'Initial admission must bind the exact recorded Eric instruction'; END IF;
 ELSE
  IF previous.command#>>'{fact,state}'='START_DATE_CONFIRMED' THEN RAISE EXCEPTION 'Already admitted first date is historical; no rewrite through this RPC'; END IF;
  IF effective<public.sch_service_date(statement_timestamp()) OR effective<previous.effective_from
   OR (f->>'ownerEvidenceSha256')=(previous.command#>>'{fact,ownerEvidenceSha256}')
  THEN RAISE EXCEPTION 'A later instruction requires new explicit evidence and no historical rewrite'; END IF;
 END IF;
 INSERT INTO custodial_employment.admissions(employee_id,employment_revision,request_id,manager_id,authority_revision,effective_from,command)
 VALUES(employee,expected_employment+1,request,manager,current_authority,effective,p_command) RETURNING * INTO admitted;
 RETURN jsonb_build_object('schema','custodial.employment-admission-receipt.v1','status','ACCEPTED',
  'employeeId',admitted.employee_id,'employmentRevision',admitted.employment_revision,
  'acceptedAuthorityRevision',admitted.authority_revision,'acceptedByManagerId',admitted.manager_id,'command',admitted.command);
END $function$

CREATE OR REPLACE FUNCTION custodial_employment.native_read(p_service_date date, p_revision bigint, p_manager uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actual_revision bigint;records jsonb;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();
 PERFORM public.static_weekly_v3_manager_actor(p_manager);
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 SELECT current_revision INTO STRICT actual_revision FROM public.static_weekly_schedule_control WHERE singleton FOR SHARE;
 IF p_service_date IS NULL OR NOT isfinite(p_service_date) OR p_revision IS DISTINCT FROM actual_revision
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Exact current native employment date and authority revision required';END IF;
 SELECT jsonb_agg(jsonb_build_object('employeeId',a.employee_id,'employmentRevision',a.employment_revision,
  'acceptedByManagerId',a.manager_id,'command',a.command) ORDER BY a.employee_id) INTO records
 FROM (SELECT DISTINCT ON(employee_id) * FROM custodial_employment.admissions
  WHERE effective_from<=p_service_date ORDER BY employee_id,employment_revision DESC) a;
 IF coalesce(jsonb_array_length(records),0)<>2 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Both dated employment admissions are required';END IF;
 RETURN jsonb_build_object('schema','custodial.employment-admission-read.v1','serviceDate',p_service_date::text,
  'authorityRevision',actual_revision,'employees',records);
END $function$

CREATE OR REPLACE FUNCTION custodial_employment.read_admissions(p_service_date date, p_expected_authority_revision bigint, p_manager uuid, p_credential uuid, p_device text, p_session_access text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE revision bigint;rows jsonb;actor jsonb;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();
 actor:=public.custodial_action_actor_v1(p_manager,p_credential,p_device,p_session_access,'read');
 IF actor->>'manager_id' IS DISTINCT FROM p_manager::text THEN RAISE EXCEPTION 'Current named manager required'; END IF;
 IF p_service_date IS NULL OR NOT isfinite(p_service_date) OR p_expected_authority_revision IS NULL
  OR p_expected_authority_revision NOT BETWEEN 0 AND 9007199254740990 THEN RAISE EXCEPTION 'Exact service date and revision required'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 SELECT current_revision INTO STRICT revision FROM public.static_weekly_schedule_control WHERE singleton FOR SHARE;
 IF revision<>p_expected_authority_revision THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Employment reader authority revision changed'; END IF;
 SELECT jsonb_agg(jsonb_build_object('employeeId',a.employee_id,'employmentRevision',a.employment_revision,
  'acceptedByManagerId',a.manager_id,'command',a.command) ORDER BY a.employee_id) INTO rows
 FROM (SELECT DISTINCT ON(employee_id) * FROM custodial_employment.admissions
  WHERE effective_from<=p_service_date ORDER BY employee_id,employment_revision DESC) a;
 IF coalesce(jsonb_array_length(rows),0)<>2 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Both controlled employee admissions must exist for this date'; END IF;
 RETURN jsonb_build_object('schema','custodial.employment-admission-read.v1','serviceDate',p_service_date::text,
  'authorityRevision',revision,'employees',rows);
END $function$

CREATE OR REPLACE FUNCTION custodial_leadership_private.bind_security_scope(p_manager uuid, p_credential uuid, p_device text, p_signed_expires timestamp with time zone, p_security_session uuid, p_version integer, p_security_hash text, p_csrf_hash text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE until_time timestamptz;view jsonb;c custodial_leadership_private.request_contexts%rowtype;
BEGIN
 PERFORM 1 FROM custodial_leadership_private.policy WHERE singleton FOR SHARE;
 PERFORM 1 FROM custodial_leadership_private.registrations WHERE registration_id=p_credential FOR SHARE;
 PERFORM 1 FROM custodial_leadership_private.security_scopes WHERE session_id=p_security_session FOR SHARE;
 until_time:=custodial_leadership_private.read_security_scope(p_manager,p_credential,p_device,p_signed_expires,p_security_session,p_version,p_security_hash,p_csrf_hash);
 view:=custodial_leadership_private.session_view(p_credential);
 SELECT * INTO c FROM custodial_leadership_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current();
 IF c.request_id IS NOT NULL AND(c.request_id<>p_security_session OR c.registration_id<>p_credential OR c.cohort_principal_id<>p_manager)
  THEN RAISE EXCEPTION 'Original cohort security transaction binding changed' USING ERRCODE='42501';END IF;
 INSERT INTO custodial_leadership_private.request_contexts(backend_pid,transaction_id,request_id,registration_id,cohort_principal_id,policy_version,permission)
 VALUES(pg_backend_pid(),txid_current(),p_security_session,p_credential,p_manager,(view#>>'{cohort,policyVersion}')::integer,'custodialManagementAdmin')
 ON CONFLICT(backend_pid,transaction_id) DO NOTHING;
 PERFORM custodial_leadership_private.require_context(p_manager,'custodialManagementAdmin');
 RETURN until_time;
END $function$

CREATE OR REPLACE FUNCTION custodial_leadership_private.execute(p_action text, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE p custodial_leadership_private.policy%rowtype;v custodial_leadership_private.pin_versions%rowtype;
 c custodial_leadership_private.challenges%rowtype;r custodial_leadership_private.registrations%rowtype;
 rotation custodial_leadership_private.rotation_intents%rowtype;event custodial_leadership_private.owner_events%rowtype;
 names jsonb;chosen jsonb;result jsonb;verifier jsonb;stamp timestamptz:=clock_timestamp();owner_id uuid;new_id uuid;
 owner_action boolean:=p_action IN('install_initial','prepare_rotation','confirm_private_delivery','arm_enrollment_share');
BEGIN
 IF jsonb_typeof(p_data) IS DISTINCT FROM 'object' OR octet_length(p_data::text)>4096 THEN RETURN jsonb_build_object('ok',false,'error','invalid_request');END IF;
 SELECT * INTO p FROM custodial_leadership_private.policy WHERE singleton FOR UPDATE;
 stamp:=clock_timestamp();
 IF p.singleton IS NULL THEN RETURN jsonb_build_object('ok',false,'error','policy_unavailable');END IF;
 IF owner_action THEN
  -- This ID is supplied ONLY by Main's independent owner authorizer, NEVER
  -- selected/claimed enrollment. No owner endpoints are mounted by this proposal.
  SELECT manager_id INTO owner_id FROM public.ops_manager_managers WHERE system_key='eric_custodial_manager'
   AND active AND revoked_at IS NULL AND is_system_principal=false;
  IF owner_id IS NULL OR p_data->>'owner_account_id' IS DISTINCT FROM owner_id::text OR p_data->>'approval_id' IS NULL
   THEN RETURN jsonb_build_object('ok',false,'error','owner_authorization_required');END IF;
  SELECT * INTO event FROM custodial_leadership_private.owner_events WHERE approval_id=(p_data->>'approval_id')::uuid;
  IF event.approval_id IS NOT NULL THEN
   IF event.action IS DISTINCT FROM p_action OR event.request_digest IS DISTINCT FROM public.static_weekly_digest_jsonb(p_data)
    THEN RETURN jsonb_build_object('ok',false,'error','owner_authorization_required');END IF;
   RETURN jsonb_build_object('ok',true,'data',event.result_json);
  END IF;
 ELSE
  IF NOT p.enabled OR p.cohort_principal_id IS NULL OR cardinality(p.permissions)=0 OR p.approved_at IS NULL
   OR NOT EXISTS(SELECT 1 FROM public.ops_manager_managers m WHERE m.manager_id=p.cohort_principal_id AND m.active AND m.revoked_at IS NULL AND m.is_system_principal=true)
   THEN RETURN jsonb_build_object('ok',false,'error','policy_unavailable');END IF;
 END IF;

 IF p_action='begin_challenge' THEN
  IF NOT custodial_leadership_private.take_attempt('challenge',p_data->>'source_hash',p_data->>'browser_hash')
   THEN RETURN jsonb_build_object('ok',false,'error','rate_limited');END IF;
  SELECT * INTO v FROM custodial_leadership_private.pin_versions WHERE state='ACTIVE' AND activated_at<=stamp AND expires_at>stamp;
  IF v.pin_version IS NULL THEN RETURN jsonb_build_object('ok',false,'error','enrollment_unavailable');END IF;
  RETURN jsonb_build_object('ok',true,'data',jsonb_build_object('pinVersion',v.pin_version,'verifier',v.verifier));
 ELSIF p_action='finish_challenge' THEN
  SELECT * INTO v FROM custodial_leadership_private.pin_versions WHERE pin_version=(p_data->>'pin_version')::uuid AND state='ACTIVE' AND expires_at>stamp AND activated_at<=stamp;
  names:=custodial_leadership_private.approved_names();
  IF v.pin_version IS NULL OR names IS NULL OR coalesce(p_data->>'challenge_hash','') !~ '^[a-f0-9]{64}$' OR coalesce(p_data->>'browser_hash','') !~ '^[a-f0-9]{64}$'
   THEN RETURN jsonb_build_object('ok',false,'error','enrollment_unavailable');END IF;
  INSERT INTO custodial_leadership_private.challenges(challenge_hash,browser_hash,pin_version,policy_version,created_at,expires_at)
   VALUES(p_data->>'challenge_hash',p_data->>'browser_hash',v.pin_version,p.policy_version,stamp,stamp+interval '5 minutes');
  RETURN jsonb_build_object('ok',true,'data',jsonb_build_object('challengeExpiresAt',stamp+interval '5 minutes','approvedNames',names));
 ELSIF p_action='enroll' THEN
  IF NOT custodial_leadership_private.take_attempt('enroll',p_data->>'source_hash',p_data->>'browser_hash',p_data->>'account_key')
   THEN RETURN jsonb_build_object('ok',false,'error','rate_limited');END IF;
  SELECT * INTO c FROM custodial_leadership_private.challenges WHERE challenge_hash=p_data->>'challenge_hash' FOR UPDATE;
  SELECT * INTO v FROM custodial_leadership_private.pin_versions WHERE pin_version=c.pin_version;
  IF c.challenge_hash IS NULL OR c.browser_hash IS DISTINCT FROM p_data->>'browser_hash' OR c.consumed_at IS NOT NULL OR c.expires_at<=stamp
   OR c.policy_version<>p.policy_version OR v.state IS DISTINCT FROM 'ACTIVE' OR v.expires_at<=stamp
   THEN RETURN jsonb_build_object('ok',false,'error','challenge_unavailable');END IF;
  names:=custodial_leadership_private.approved_names();
  SELECT n INTO chosen FROM jsonb_array_elements(names) n WHERE n->>'accountId'=p_data->>'claimed_account_id';
  IF chosen IS NULL OR coalesce(p_data->>'new_browser_hash','') !~ '^[a-f0-9]{64}$' OR coalesce(p_data->>'token_hash','') !~ '^[a-f0-9]{64}$'
   THEN RETURN jsonb_build_object('ok',false,'error','challenge_unavailable');END IF;
  IF EXISTS(SELECT 1 FROM custodial_leadership_private.registrations WHERE browser_hash=p_data->>'browser_hash' AND revoked_at IS NULL AND expires_at>stamp)
   THEN RETURN jsonb_build_object('ok',false,'error','browser_already_enrolled');END IF;
  INSERT INTO custodial_leadership_private.registrations(token_hash,browser_hash,claimed_account_id,cohort_principal_id,enrollment_policy_version,enrolled_at,expires_at)
   VALUES(p_data->>'token_hash',p_data->>'new_browser_hash',(p_data->>'claimed_account_id')::uuid,p.cohort_principal_id,p.policy_version,stamp,stamp+interval '365 days') RETURNING * INTO r;
  UPDATE custodial_leadership_private.challenges SET consumed_at=stamp WHERE challenge_hash=c.challenge_hash;
  INSERT INTO custodial_leadership_private.audit(event,registration_id,claimed_account_id,cohort_principal_id,policy_version,identity_assurance)
   VALUES('browser_enrolled',r.registration_id,r.claimed_account_id,p.cohort_principal_id,p.policy_version,'SELF_ASSERTED_NAME');
  result:=custodial_leadership_private.session_view(r.registration_id);
 ELSIF p_action='session' THEN
  SELECT * INTO r FROM custodial_leadership_private.registrations WHERE token_hash=p_data->>'token_hash' AND browser_hash=p_data->>'browser_hash';
  result:=custodial_leadership_private.session_view(r.registration_id);
 ELSIF p_action='credential_readback' THEN
  -- Only the private server connection calls this AFTER central signature
  -- verification; no public router exposes IDs as an authentication shortcut.
  SELECT * INTO r FROM custodial_leadership_private.registrations
   WHERE registration_id=(p_data->>'registration_id')::uuid AND browser_id=(p_data->>'browser_id')::uuid
    AND cohort_principal_id=(p_data->>'cohort_principal_id')::uuid;
  result:=custodial_leadership_private.session_view(r.registration_id);
 ELSIF p_action IN('security_scope_issue','security_scope_readback','security_scope_revoke') THEN
  SELECT * INTO r FROM custodial_leadership_private.registrations WHERE registration_id=(p_data->>'registration_id')::uuid
   AND browser_id=(p_data->>'browser_id')::uuid AND cohort_principal_id=(p_data->>'cohort_principal_id')::uuid;
  IF custodial_leadership_private.session_view(r.registration_id) IS NULL OR NOT('custodialManagementAdmin'=ANY(p.permissions))
   THEN RETURN jsonb_build_object('ok',false,'error','registration_unavailable');END IF;
  IF p_action='security_scope_issue' THEN
   IF (p_data->>'policy_version')::integer IS DISTINCT FROM p.policy_version OR (p_data->>'security_epoch')::integer IS DISTINCT FROM p.security_epoch
    OR coalesce(p_data->>'token_hash','')!~'^[a-f0-9]{64}$' OR coalesce(p_data->>'csrf_hash','')!~'^[a-f0-9]{64}$'
    OR (p_data->>'expires_at')::timestamptz<=stamp OR (p_data->>'expires_at')::timestamptz>least(stamp+interval '15 minutes',r.expires_at)
    THEN RETURN jsonb_build_object('ok',false,'error','registration_unavailable');END IF;
   INSERT INTO custodial_leadership_private.security_scopes(session_id,registration_id,cohort_principal_id,browser_id,policy_version,security_epoch,token_hash,csrf_hash,created_at,expires_at)
   VALUES((p_data->>'session_id')::uuid,r.registration_id,p.cohort_principal_id,r.browser_id,p.policy_version,p.security_epoch,p_data->>'token_hash',p_data->>'csrf_hash',stamp,(p_data->>'expires_at')::timestamptz);
  ELSIF p_action='security_scope_revoke' THEN
   UPDATE custodial_leadership_private.security_scopes SET revoked_at=coalesce(revoked_at,stamp) WHERE session_id=(p_data->>'session_id')::uuid AND registration_id=r.registration_id;
  END IF;
  SELECT jsonb_build_object('session_id',ss.session_id,'security_epoch',ss.security_epoch,'expires_at',ss.expires_at,'revoked_at',ss.revoked_at,'token_hash',ss.token_hash,'csrf_hash',ss.csrf_hash)
   INTO result FROM custodial_leadership_private.security_scopes ss WHERE ss.session_id=(p_data->>'session_id')::uuid AND ss.registration_id=r.registration_id
    AND ss.policy_version=p.policy_version AND ss.security_epoch=p.security_epoch AND ss.expires_at>stamp AND (ss.revoked_at IS NULL OR p_action='security_scope_revoke');
 ELSIF p_action IN('gemini_context','gemini_conversation','gemini_begin_turn','gemini_original_outcome') THEN
  result:=custodial_leadership_private.gemini_operation(p_action,p_data);
 ELSIF p_action='security_epoch_bump' THEN
  SELECT * INTO r FROM custodial_leadership_private.registrations WHERE registration_id=(p_data->>'registration_id')::uuid
   AND browser_id=(p_data->>'browser_id')::uuid AND cohort_principal_id=(p_data->>'cohort_principal_id')::uuid;
  IF custodial_leadership_private.session_view(r.registration_id) IS NULL OR NOT('custodialManagementAdmin'=ANY(p.permissions))
   THEN RETURN jsonb_build_object('ok',false,'error','registration_unavailable');END IF;
  UPDATE custodial_leadership_private.policy SET security_epoch=security_epoch+1 WHERE singleton RETURNING security_epoch INTO p.security_epoch;
  result:=jsonb_build_object('securityEpoch',p.security_epoch,'scope','custodial_leadership_device_security','revoked_all',true);
 ELSIF p_action='revoke' THEN
  SELECT * INTO r FROM custodial_leadership_private.registrations WHERE token_hash=p_data->>'token_hash' AND browser_hash=p_data->>'browser_hash' FOR UPDATE;
  IF r.registration_id IS NULL THEN RETURN jsonb_build_object('ok',false,'error','registration_unavailable');END IF;
  UPDATE custodial_leadership_private.registrations SET revoked_at=coalesce(revoked_at,stamp) WHERE registration_id=r.registration_id;
  UPDATE custodial_leadership_private.challenges SET consumed_at=coalesce(consumed_at,stamp) WHERE browser_hash=r.browser_hash;
  INSERT INTO custodial_leadership_private.audit(event,registration_id,claimed_account_id,cohort_principal_id,policy_version,identity_assurance)
   VALUES('browser_revoked',r.registration_id,r.claimed_account_id,p.cohort_principal_id,p.policy_version,'SELF_ASSERTED_NAME');
  result:=jsonb_build_object('revoked',true);
 ELSIF p_action='install_initial' THEN
  IF EXISTS(SELECT 1 FROM custodial_leadership_private.pin_versions) THEN RETURN jsonb_build_object('ok',false,'error','rotation_not_eligible');END IF;
  verifier:=p_data->'verifier';
  IF custodial_leadership_private.valid_verifier(verifier) IS NOT TRUE
   THEN RETURN jsonb_build_object('ok',false,'error','rotation_not_eligible');END IF;
  INSERT INTO custodial_leadership_private.pin_versions(state,verifier,activated_at,expires_at,approval_ref)
   VALUES('ACTIVE',verifier,stamp,stamp+interval '720 hours',(p_data->>'approval_id')::uuid) RETURNING pin_version INTO new_id;
  result:=jsonb_build_object('pinVersion',new_id,'state','ACTIVE','activeUntil',stamp+interval '720 hours','enrollmentOpen',true);
 ELSIF p_action='prepare_rotation' THEN
  SELECT * INTO rotation FROM custodial_leadership_private.rotation_intents WHERE state IN('AWAITING_PRIVATE_DELIVERY','UNUSED');
  IF rotation.rotation_id IS NOT NULL THEN
   result:=jsonb_build_object('rotationId',rotation.rotation_id,'state',rotation.state,'pinVersion',rotation.replacement_pin,'activeUntil',NULL,'enrollmentOpen',true);
  ELSE
   SELECT * INTO v FROM custodial_leadership_private.pin_versions WHERE state='ACTIVE' AND expires_at<=stamp;
   IF v.pin_version IS NULL THEN RETURN jsonb_build_object('ok',false,'error','rotation_not_eligible');END IF;
   INSERT INTO custodial_leadership_private.rotation_intents(previous_pin,state,owner_account_id,prepare_approval)
    VALUES(v.pin_version,'AWAITING_PRIVATE_DELIVERY',owner_id,(p_data->>'approval_id')::uuid) RETURNING * INTO rotation;
   result:=jsonb_build_object('rotationId',rotation.rotation_id,'state',rotation.state,'pinVersion',NULL,'activeUntil',NULL,'enrollmentOpen',true);
  END IF;
 ELSIF p_action='confirm_private_delivery' THEN
  SELECT * INTO rotation FROM custodial_leadership_private.rotation_intents WHERE rotation_id=(p_data->>'rotation_id')::uuid FOR UPDATE;
  IF rotation.rotation_id IS NULL OR rotation.state<>'AWAITING_PRIVATE_DELIVERY' OR rotation.owner_account_id<>owner_id OR p_data->>'delivery_receipt_id' IS NULL
   THEN RETURN jsonb_build_object('ok',false,'error','rotation_not_eligible');END IF;
  verifier:=p_data->'verifier';
  IF custodial_leadership_private.valid_verifier(verifier) IS NOT TRUE
   THEN RETURN jsonb_build_object('ok',false,'error','rotation_not_eligible');END IF;
  UPDATE custodial_leadership_private.pin_versions SET state='RETIRED' WHERE pin_version=rotation.previous_pin;
  INSERT INTO custodial_leadership_private.pin_versions(state,verifier,private_delivery_receipt,approval_ref)
   VALUES('UNUSED',verifier,(p_data->>'delivery_receipt_id')::uuid,(p_data->>'approval_id')::uuid) RETURNING pin_version INTO new_id;
  UPDATE custodial_leadership_private.rotation_intents AS ri SET state='UNUSED',replacement_pin=new_id,private_delivery_receipt=(p_data->>'delivery_receipt_id')::uuid,delivery_approval=(p_data->>'approval_id')::uuid WHERE ri.rotation_id=rotation.rotation_id;
  result:=jsonb_build_object('rotationId',rotation.rotation_id,'pinVersion',new_id,'state','UNUSED','activeUntil',NULL,'enrollmentOpen',true);
 ELSIF p_action='arm_enrollment_share' THEN
  SELECT * INTO v FROM custodial_leadership_private.pin_versions WHERE pin_version=(p_data->>'pin_version')::uuid FOR UPDATE;
  SELECT * INTO rotation FROM custodial_leadership_private.rotation_intents ri WHERE ri.replacement_pin=v.pin_version FOR UPDATE;
  IF v.pin_version IS NULL OR v.state<>'UNUSED' OR v.activated_at IS NOT NULL OR v.expires_at IS NOT NULL OR rotation.state IS DISTINCT FROM 'UNUSED' OR rotation.owner_account_id<>owner_id
   THEN RETURN jsonb_build_object('ok',false,'error','rotation_not_eligible');END IF;
  UPDATE custodial_leadership_private.pin_versions SET state='ACTIVE',activated_at=stamp,expires_at=stamp+interval '720 hours' WHERE pin_version=v.pin_version;
  UPDATE custodial_leadership_private.rotation_intents ri SET state='ARMED',arm_approval=(p_data->>'approval_id')::uuid WHERE ri.rotation_id=rotation.rotation_id;
  result:=jsonb_build_object('pinVersion',v.pin_version,'state','ACTIVE','activeUntil',stamp+interval '720 hours','enrollmentOpen',true);
 ELSE RETURN jsonb_build_object('ok',false,'error','invalid_request');END IF;
 IF owner_action THEN
  INSERT INTO custodial_leadership_private.owner_events(approval_id,action,request_digest,result_json) VALUES((p_data->>'approval_id')::uuid,p_action,public.static_weekly_digest_jsonb(p_data),result);
  INSERT INTO custodial_leadership_private.audit(event,claimed_account_id,owner_approval_ref,identity_assurance) VALUES(p_action,owner_id,(p_data->>'approval_id')::uuid,'INDEPENDENT_OWNER_APPROVAL');
 END IF;
 RETURN jsonb_build_object('ok',true,'data',result);
EXCEPTION WHEN data_exception OR check_violation OR unique_violation THEN RETURN jsonb_build_object('ok',false,'error','invalid_request');
END $function$

CREATE OR REPLACE FUNCTION custodial_leadership_private.gemini_operation(p_action text, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v jsonb;inp jsonb:=p_data->'input';r uuid:=(p_data->>'registration_id')::uuid;c uuid:=(p_data->>'cohort_principal_id')::uuid;
 conversation uuid;message uuid;answer jsonb;attachments uuid[];item public.gemini_console_conversations%rowtype;
BEGIN
 PERFORM 1 FROM custodial_leadership_private.registrations WHERE registration_id=r FOR SHARE;
 v:=custodial_leadership_private.session_view(r);
 IF v IS NULL OR v->>'browserId' IS DISTINCT FROM p_data->>'browser_id' OR v#>>'{cohort,principalId}' IS DISTINCT FROM c::text
  OR NOT(v#>'{cohort,permissions}' ? 'custodialManagementAdmin') OR jsonb_typeof(inp) IS DISTINCT FROM 'object'
  THEN RAISE EXCEPTION 'Current original cohort Gemini registration required' USING ERRCODE='42501';END IF;
 IF p_action='gemini_context' THEN
  IF (SELECT count(*) FROM jsonb_object_keys(inp))>1 OR EXISTS(SELECT 1 FROM jsonb_object_keys(inp) k WHERE k NOT IN('conversation_id','attachment_id','message_id')) THEN RAISE EXCEPTION 'Exact Gemini context required';END IF;
 ELSIF p_action='gemini_conversation' THEN
  IF (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(inp) k) IS DISTINCT FROM ARRAY['conversation_id','title']::text[] THEN RAISE EXCEPTION 'Exact conversation required';END IF;
 ELSIF p_action='gemini_begin_turn' THEN
  IF (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(inp) k) IS DISTINCT FROM ARRAY['attachment_ids','body','client_message_id','conversation_id','correlation_id']::text[] THEN RAISE EXCEPTION 'Exact logical turn required';END IF;
 ELSIF p_action='gemini_original_outcome' THEN
  IF (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(inp) k) IS DISTINCT FROM ARRAY['client_message_id','conversation_id']::text[] THEN RAISE EXCEPTION 'Exact original lookup required';END IF;
 ELSE RAISE EXCEPTION 'Unknown cohort Gemini operation' USING ERRCODE='42501';END IF;
 conversation:=(inp->>'conversation_id')::uuid;
 IF p_action='gemini_context' THEN
  IF inp ? 'attachment_id' THEN SELECT conversation_id INTO conversation FROM public.gemini_console_attachments WHERE attachment_id=(inp->>'attachment_id')::uuid AND manager_id=c;IF NOT FOUND THEN RAISE EXCEPTION 'Original cohort attachment unavailable' USING ERRCODE='42501';END IF;END IF;
  IF inp ? 'message_id' THEN SELECT conversation_id INTO conversation FROM public.gemini_console_messages WHERE message_id=(inp->>'message_id')::uuid AND manager_id=c;IF NOT FOUND THEN RAISE EXCEPTION 'Original cohort message unavailable' USING ERRCODE='42501';END IF;END IF;
  IF conversation IS NOT NULL AND NOT EXISTS(SELECT 1 FROM custodial_leadership_private.gemini_conversation_bindings b JOIN public.gemini_console_conversations g ON g.conversation_id=b.conversation_id WHERE b.conversation_id=conversation AND b.registration_id=r AND b.cohort_principal_id=c AND g.owner_manager_id=c AND g.status='active')
   THEN RAISE EXCEPTION 'Original conversation belongs to another browser or named manager' USING ERRCODE='42501';END IF;
  SELECT jsonb_build_object('conversationIds',coalesce(jsonb_agg(x.conversation_id ORDER BY x.last_activity_at DESC),'[]'::jsonb)) INTO answer FROM(
   SELECT g.conversation_id,g.last_activity_at FROM public.gemini_console_conversations g
   JOIN custodial_leadership_private.gemini_conversation_bindings b ON b.conversation_id=g.conversation_id WHERE b.registration_id=r AND b.cohort_principal_id=c AND g.owner_manager_id=c AND g.status<>'deleted' ORDER BY g.last_activity_at DESC LIMIT 100) x;
  RETURN answer;
 ELSIF p_action='gemini_conversation' THEN
  IF conversation IS NULL OR nullif(btrim(inp->>'title'),'') IS NULL OR length(inp->>'title')>160 THEN RAISE EXCEPTION 'Exact new conversation required';END IF;
  SELECT * INTO item FROM public.gemini_console_conversations WHERE conversation_id=conversation FOR UPDATE;
  IF FOUND THEN
   IF NOT EXISTS(SELECT 1 FROM custodial_leadership_private.gemini_conversation_bindings b JOIN public.gemini_console_conversations g ON g.conversation_id=b.conversation_id WHERE b.conversation_id=conversation AND b.registration_id=r AND b.cohort_principal_id=c AND g.owner_manager_id=c AND g.status='active') THEN RAISE EXCEPTION 'Existing conversation cannot be adopted' USING ERRCODE='42501';END IF;
  ELSE
   INSERT INTO public.gemini_console_conversations(conversation_id,owner_manager_id,title) VALUES(conversation,c,inp->>'title') RETURNING * INTO item;
   INSERT INTO custodial_leadership_private.gemini_conversation_bindings(conversation_id,registration_id,cohort_principal_id,claimed_account_id) VALUES(conversation,r,c,(v#>>'{claimedAccount,accountId}')::uuid);
  END IF;
  RETURN to_jsonb(item);
 END IF;
 IF NOT EXISTS(SELECT 1 FROM custodial_leadership_private.gemini_conversation_bindings b JOIN public.gemini_console_conversations g ON g.conversation_id=b.conversation_id WHERE b.conversation_id=conversation AND b.registration_id=r AND b.cohort_principal_id=c AND g.owner_manager_id=c AND g.status='active')
  THEN RAISE EXCEPTION 'Original cohort conversation required' USING ERRCODE='42501';END IF;
 IF p_action='gemini_original_outcome' THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('original_user',to_jsonb(u),'original_assistant',to_jsonb(a))),'[]'::jsonb) INTO answer
   FROM public.gemini_console_messages u JOIN custodial_leadership_private.gemini_message_bindings b ON b.message_id=u.message_id
   LEFT JOIN public.gemini_console_messages a ON a.response_to_message_id=u.message_id AND a.role='assistant'
   WHERE b.registration_id=r AND b.cohort_principal_id=c AND u.manager_id=c AND u.conversation_id=conversation AND u.client_message_id=(inp->>'client_message_id')::uuid AND u.role='user';
  RETURN answer;
 END IF;
 -- Bind this actual private transaction before existing state-changing RPCs.
 PERFORM public.static_weekly_leadership_bind_verified_request(r,(v->>'browserId')::uuid,c,gen_random_uuid());
 IF p_action='gemini_begin_turn' THEN
  SELECT message_id INTO message FROM public.gemini_console_messages WHERE manager_id=c AND client_message_id=(inp->>'client_message_id')::uuid FOR UPDATE;
  IF FOUND AND NOT EXISTS(SELECT 1 FROM custodial_leadership_private.gemini_message_bindings b WHERE b.message_id=message AND b.registration_id=r AND b.cohort_principal_id=c)
   THEN RAISE EXCEPTION 'Existing logical message cannot be adopted' USING ERRCODE='42501';END IF;
  IF jsonb_typeof(inp->'attachment_ids') IS DISTINCT FROM 'array' OR jsonb_array_length(inp->'attachment_ids')>8 THEN RAISE EXCEPTION 'Exact original attachments required';END IF;
  SELECT coalesce(array_agg(value::uuid),'{}'::uuid[]) INTO attachments FROM jsonb_array_elements_text(inp->'attachment_ids');
  answer:=public.gemini_console_begin_turn(conversation,c,(inp->>'client_message_id')::uuid,inp->>'body',attachments,(inp->>'correlation_id')::uuid);
  message:=(answer#>>'{user_message,message_id}')::uuid;
  IF answer->'inserted'='true'::jsonb THEN INSERT INTO custodial_leadership_private.gemini_message_bindings(message_id,registration_id,cohort_principal_id,claimed_account_id) VALUES(message,r,c,(v#>>'{claimedAccount,accountId}')::uuid);END IF;
  IF NOT EXISTS(SELECT 1 FROM custodial_leadership_private.gemini_message_bindings b WHERE b.message_id=message AND b.registration_id=r AND b.cohort_principal_id=c) THEN RAISE EXCEPTION 'Original message registration differs' USING ERRCODE='42501';END IF;
  RETURN answer;

 END IF;
 RAISE EXCEPTION 'Unknown cohort Gemini operation' USING ERRCODE='42501';
END $function$

CREATE OR REPLACE FUNCTION custodial_leadership_private.guard_staffing_operation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE p custodial_leadership_private.policy%rowtype;b custodial_leadership_private.operation_bindings%rowtype;actor jsonb;
BEGIN
 SELECT * INTO p FROM custodial_leadership_private.policy WHERE singleton;
 SELECT * INTO b FROM custodial_leadership_private.operation_bindings WHERE operation_id=NEW.operation_id;
 IF b.operation_id IS NULL AND NEW.prepared_by_manager_id IS DISTINCT FROM p.cohort_principal_id THEN RETURN NEW;END IF;
 actor:=custodial_leadership_private.require_context(NEW.prepared_by_manager_id,'custodialManagementAdmin');
 IF NEW.confirmed_by_manager_id IS NOT NULL AND NEW.confirmed_by_manager_id IS DISTINCT FROM NEW.prepared_by_manager_id
  THEN RAISE EXCEPTION 'Custodial cohort confirmer cannot become a claimed individual' USING ERRCODE='42501';END IF;
 IF b.operation_id IS NULL AND TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Original cohort operation binding is missing; no named-operation adoption' USING ERRCODE='42501';END IF;
 IF b.operation_id IS NOT NULL THEN
  IF b.registration_id::text IS DISTINCT FROM actor->>'credential_id'
   OR b.cohort_principal_id IS DISTINCT FROM NEW.prepared_by_manager_id
   OR b.claimed_account_id::text IS DISTINCT FROM actor->>'claimed_account_id'
   THEN RAISE EXCEPTION 'Original pending operation belongs to another browser registration' USING ERRCODE='42501';END IF;
 ELSE
  INSERT INTO custodial_leadership_private.operation_bindings(operation_id,registration_id,cohort_principal_id,claimed_account_id,original_request_id)
   VALUES(NEW.operation_id,(actor->>'credential_id')::uuid,NEW.prepared_by_manager_id,(actor->>'claimed_account_id')::uuid,(actor->>'request_id')::uuid);
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION custodial_leadership_private.session_view(p_registration uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r custodial_leadership_private.registrations%rowtype;p custodial_leadership_private.policy%rowtype;
 names jsonb;chosen jsonb;contact jsonb;
BEGIN
 SELECT * INTO r FROM custodial_leadership_private.registrations WHERE registration_id=p_registration;
 SELECT * INTO p FROM custodial_leadership_private.policy WHERE singleton;
 IF NOT p.enabled OR r.registration_id IS NULL OR r.revoked_at IS NOT NULL OR r.expires_at<=clock_timestamp()
  OR r.cohort_principal_id IS DISTINCT FROM p.cohort_principal_id
  OR NOT EXISTS(SELECT 1 FROM public.ops_manager_managers m WHERE m.manager_id=p.cohort_principal_id AND m.active AND m.revoked_at IS NULL AND m.is_system_principal=true)
  THEN RETURN NULL;END IF;
 names:=custodial_leadership_private.approved_names();
 SELECT n INTO chosen FROM jsonb_array_elements(names) n WHERE n->>'accountId'=r.claimed_account_id::text;
 IF chosen IS NULL OR r.claimed_account_id=p.cohort_principal_id THEN RETURN NULL;END IF;
 SELECT jsonb_build_object('email',v.email,'verifiedAt',v.verified_at) INTO contact
  FROM custodial_leadership_private.verified_contacts v WHERE v.account_id=r.claimed_account_id AND v.verified_at<=clock_timestamp();
 RETURN jsonb_build_object('registrationId',r.registration_id,'browserId',r.browser_id,'credentialExpiresAt',r.expires_at,'csrfBinding',r.browser_hash,'claimedAccount',chosen||jsonb_build_object('contact',contact),
  'cohort',jsonb_build_object('principalId',p.cohort_principal_id,'policyVersion',p.policy_version,'securityEpoch',p.security_epoch,'permissions',to_jsonb(p.permissions)));
END $function$

CREATE OR REPLACE FUNCTION custodial_leadership_private.take_attempt(p_stage text, p_source text, p_browser text, p_account text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE bucket timestamptz:=to_timestamp(floor(extract(epoch FROM clock_timestamp())/900)*900);r record;n integer;
BEGIN
 IF coalesce(p_source,'') !~ '^[a-f0-9]{64}$' OR coalesce(p_browser,'') !~ '^[a-f0-9]{64}$' OR p_stage NOT IN('challenge','enroll')
  OR(p_account IS NOT NULL AND p_account !~ '^[a-f0-9]{64}$') THEN RETURN false;END IF;
 -- Caller holds the singleton policy row FOR UPDATE: global counter serializes
 -- all replicas. Success never resets a bucket. Global exhaustion stops new keys.
 FOR r IN SELECT * FROM(VALUES('global',repeat('0',64),20),('source',p_source,5),('browser',p_browser,5),('account',p_account,5)) v(scope,key,cap) LOOP
  IF r.key IS NULL THEN CONTINUE;END IF;
  INSERT INTO custodial_leadership_private.attempt_buckets(stage,scope,key_hash,window_start,attempts)
   VALUES(p_stage,r.scope,r.key,bucket,1)
   ON CONFLICT(stage,scope,key_hash,window_start) DO UPDATE SET attempts=custodial_leadership_private.attempt_buckets.attempts+1
   RETURNING attempts INTO n;
  IF n>r.cap THEN RETURN false;END IF;
 END LOOP;RETURN true;
END $function$

CREATE OR REPLACE FUNCTION custodial_recovery.assert_current_manager(p_manager uuid, p_credential uuid, p_device text, p_signed_expires timestamp with time zone, p_security_session uuid, p_password_version integer, p_security_hash text, p_csrf_hash text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor jsonb;m public.ops_manager_managers%rowtype;c public.ops_manager_trusted_devices%rowtype;
 cfg public.ops_manager_device_security_config%rowtype;s public.ops_manager_device_security_sessions%rowtype;
 decision_time timestamptz;BEGIN
 IF EXISTS(SELECT 1 FROM custodial_leadership_private.policy p WHERE p.cohort_principal_id=p_manager) THEN
  RETURN custodial_leadership_private.bind_security_scope(p_manager,p_credential,p_device,p_signed_expires,p_security_session,p_password_version,p_security_hash,p_csrf_hash);
 END IF;
 actor:=public.custodial_action_actor_v1(p_manager,p_credential,p_device,'full_access','write');
 SELECT * INTO STRICT c FROM public.ops_manager_trusted_devices WHERE credential_id=p_credential FOR SHARE;
 SELECT * INTO STRICT m FROM public.ops_manager_managers WHERE manager_id=p_manager FOR SHARE;
 SELECT * INTO STRICT cfg FROM public.ops_manager_device_security_config WHERE singleton FOR SHARE;
 SELECT * INTO STRICT s FROM public.ops_manager_device_security_sessions WHERE session_id=p_security_session FOR SHARE;
 decision_time:=clock_timestamp();
 IF ('SECURITY_ADMIN'=ANY(m.roles)) IS DISTINCT FROM true OR m.active IS DISTINCT FROM true OR m.revoked_at IS NOT NULL OR m.is_system_principal IS DISTINCT FROM false
  OR m.system_key IS DISTINCT FROM 'eric_custodial_manager' OR c.max_access_level IS DISTINCT FROM 'full_access'
  OR c.manager_id IS DISTINCT FROM p_manager OR c.device_id IS DISTINCT FROM p_device OR c.revoked_at IS NOT NULL
  OR c.expires_at<=decision_time OR c.created_at>decision_time
  OR p_signed_expires IS NULL OR NOT isfinite(p_signed_expires) OR p_signed_expires<=decision_time
  OR s.manager_id IS DISTINCT FROM p_manager OR s.credential_id IS DISTINCT FROM p_credential
  OR s.revoked_at IS NOT NULL OR s.expires_at<=decision_time OR s.created_at>decision_time
  OR s.password_version IS DISTINCT FROM cfg.password_version OR s.password_version IS DISTINCT FROM p_password_version
  OR p_security_hash IS NULL OR p_security_hash !~ '^[a-f0-9]{64}$' OR s.token_hash IS DISTINCT FROM p_security_hash
  OR p_csrf_hash IS NULL OR p_csrf_hash !~ '^[a-f0-9]{64}$' OR s.csrf_hash IS DISTINCT FROM p_csrf_hash
  OR cfg.sessions_revoked_at IS NOT NULL AND s.created_at<=cfg.sessions_revoked_at THEN
  RAISE EXCEPTION USING errcode='42501',message='current same-original owner security session required';END IF;
 RETURN least(decision_time+interval '5 minutes',p_signed_expires,c.expires_at,s.expires_at);
END $function$

CREATE OR REPLACE FUNCTION custodial_recovery.assert_native_inventory_manifest_original(p_operation uuid, p_device uuid, p_credential uuid, p_credential_hash text, p_credential_key_id text, p_generation uuid, p_separation uuid, p_authority_revision text, p_original_request_utf8 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE request jsonb;parent public.custodial_native_inventory_requests%rowtype;
 credential public.device_auth_credentials%rowtype;op public.custodial_native_private_custody_operations%rowtype;
 target jsonb;keys text[];part bytea;total integer;parts integer;ordinal integer;binding text;context jsonb;generation jsonb;BEGIN
 IF p_original_request_utf8 IS NULL OR octet_length(p_original_request_utf8) NOT BETWEEN 1 AND 65536
  OR p_operation IS NULL OR p_device IS NULL OR p_credential IS NULL OR p_generation IS NULL OR p_separation IS NULL
  OR p_credential_hash IS NULL OR p_credential_hash !~ '^[a-f0-9]{64}$'
  OR p_credential_key_id IS NULL OR p_credential_key_id !~ '^[a-f0-9]{64}$' THEN
  RAISE EXCEPTION USING errcode='22023',message='bounded original inventory chunk required';END IF;
 PERFORM public.custodial_v15_assert_native_json(p_original_request_utf8::json,0);
 request:=p_original_request_utf8::jsonb;
 IF jsonb_typeof(request) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING errcode='22023',message='closed manifest chunk required';END IF;
 SELECT array_agg(key ORDER BY key COLLATE "C") INTO keys FROM jsonb_object_keys(request) key;
 IF keys IS DISTINCT FROM ARRAY['chunk_base64','chunk_sha256','intent_disk_sha256','intent_document_sha256','inventory_native_request_id',
  'manifest_byte_count','manifest_chunk_count','manifest_chunk_index','manifest_sha256','original_target','purpose','purpose_attestation',
  'purpose_binding_sha256','registration_request_body_sha256','schema']::text[]
  OR EXISTS(SELECT 1 FROM jsonb_each(request) WHERE key<>'original_target' AND jsonb_typeof(value) IS DISTINCT FROM 'string')
  OR request->>'schema' IS DISTINCT FROM 'custodial.original-native-inventory-manifest-chunk.v1'
  OR request->>'purpose' IS DISTINCT FROM 'RETAIN_EXACT_ORIGINAL_INVENTORY_MANIFEST_CHUNK'
  OR request->>'inventory_native_request_id' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'
  OR EXISTS(SELECT 1 FROM unnest(ARRAY['chunk_sha256','intent_disk_sha256','intent_document_sha256','manifest_sha256',
   'purpose_attestation','purpose_binding_sha256','registration_request_body_sha256']) k WHERE request->>k !~ '^[a-f0-9]{64}$')
  OR request->>'manifest_byte_count' !~ '^[1-9][0-9]{0,7}$'
  OR request->>'manifest_chunk_count' !~ '^[1-9][0-9]{0,2}$'
  OR request->>'manifest_chunk_index' !~ '^(0|[1-9][0-9]{0,2})$' THEN
  RAISE EXCEPTION USING errcode='22023',message='fixed manifest chunk schema required';END IF;
 total:=(request->>'manifest_byte_count')::integer;parts:=(request->>'manifest_chunk_count')::integer;ordinal:=(request->>'manifest_chunk_index')::integer;
 IF total NOT BETWEEN 1 AND 16777216 OR parts<>(total+32767)/32768 OR parts NOT BETWEEN 1 AND 512 OR ordinal>=parts
  OR octet_length(request->>'chunk_base64')>43692 THEN RAISE EXCEPTION USING errcode='22023',message='bounded manifest part required';END IF;
 part:=decode(request->>'chunk_base64','base64');
 IF replace(encode(part,'base64'),E'\n','') IS DISTINCT FROM request->>'chunk_base64'
  OR octet_length(part)<>least(32768,total-ordinal*32768)
  OR encode(extensions.digest(part,'sha256'),'hex') IS DISTINCT FROM request->>'chunk_sha256' THEN
  RAISE EXCEPTION USING errcode='22023',message='exact original chunk bytes required';END IF;
 binding:=encode(extensions.digest(convert_to(concat_ws(E'\n','custodial.native-original-inventory-manifest-chunk-purpose.v1',
  request->>'inventory_native_request_id',request->>'registration_request_body_sha256',request->>'intent_document_sha256',
  request->>'intent_disk_sha256',request->>'manifest_sha256',request->>'manifest_byte_count',request->>'manifest_chunk_count',
  request->>'manifest_chunk_index',request->>'chunk_sha256'),'UTF8'),'sha256'),'hex');
 IF binding IS DISTINCT FROM request->>'purpose_binding_sha256' THEN RAISE EXCEPTION USING errcode='42501',message='original manifest purpose changed';END IF;
 SELECT * INTO STRICT parent FROM public.custodial_native_inventory_requests
  WHERE native_request_id=(request->>'inventory_native_request_id')::uuid;
 SELECT * INTO STRICT credential FROM public.device_auth_credentials WHERE credential_id=p_credential AND device_id=p_device;
 SELECT * INTO STRICT op FROM public.custodial_native_private_custody_operations WHERE operation_id=p_operation;
 target:=request->'original_target';
 IF parent.operation_id IS DISTINCT FROM p_operation OR parent.generation_id IS DISTINCT FROM p_generation
  OR parent.request_body_sha256 IS DISTINCT FROM request->>'registration_request_body_sha256'
  OR parent.intent_document_sha256 IS DISTINCT FROM request->>'intent_document_sha256'
  OR parent.intent_disk_sha256 IS DISTINCT FROM request->>'intent_disk_sha256'
  OR credential.token_hash IS DISTINCT FROM p_credential_hash OR credential.metadata_json->>'credential_secret_key_id' IS DISTINCT FROM p_credential_key_id
  OR credential.revoked_at IS NOT NULL OR credential.confirmed_at IS NULL OR NOT isfinite(credential.confirmed_at)
  OR credential.confirmed_at>clock_timestamp() OR credential.expires_at IS NULL OR NOT isfinite(credential.expires_at)
  OR credential.expires_at<=clock_timestamp() OR target->>'canonical_device_pk' IS DISTINCT FROM p_device::text
  OR target->>'credential_id' IS DISTINCT FROM p_credential::text OR target->>'original_generation_id' IS DISTINCT FROM p_generation::text
  OR target->>'separation_id' IS DISTINCT FROM p_separation::text OR target->>'separation_authority_revision' IS DISTINCT FROM p_authority_revision
  OR target->>'original_credential_secret_key_id' IS DISTINCT FROM p_credential_key_id
  OR ((parent.original_request_utf8::jsonb)->>'original_intent_utf8')::jsonb->'original_target' IS DISTINCT FROM target THEN
  RAISE EXCEPTION USING errcode='42501',message='current exact original inventory owner required';END IF;
 -- Observation-only readers use this nonlocking comparison in READ ONLY.
 -- The writer separately locks the original owner/fence and rechecks it.
 context:=public.custodial_v13_read_separation_context(p_device,p_credential);
 generation:=public.custodial_v14_read_separation_generation(p_device,p_credential,p_separation,p_generation,target->>'principal_digest');
 IF context IS NULL OR context IS DISTINCT FROM op.original_context OR context->>'state' IS DISTINCT FROM 'PENDING_RECONCILIATION'
  OR generation IS NULL OR generation IS DISTINCT FROM op.original_generation THEN
  RAISE EXCEPTION USING errcode='42501',message='current original manifest context required';END IF;
 RETURN request;
END $function$

CREATE OR REPLACE FUNCTION custodial_recovery.assert_original_target(p_target jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE op public.custodial_native_private_custody_operations%rowtype;c public.device_auth_credentials%rowtype;
 context jsonb;generation jsonb;expected jsonb;keys text[];assembled bytea;counted integer;BEGIN
 IF jsonb_typeof(p_target) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING errcode='22023',message='original preparation target required';END IF;
 SELECT * INTO STRICT op FROM public.custodial_native_private_custody_operations WHERE operation_id=(p_target->>'operation_id')::uuid FOR SHARE;
 SELECT * INTO STRICT c FROM public.device_auth_credentials WHERE credential_id=op.credential_id AND device_id=op.device_id FOR SHARE;
 -- Legacy absence/rotation is unresolved. Never stamp today's key identifier
 -- into an original; a Main original challenge must already bind this pin.
 IF c.revoked_at IS NOT NULL OR c.confirmed_at IS NULL
  OR jsonb_typeof(c.metadata_json->'credential_secret_key_id') IS DISTINCT FROM 'string'
  OR c.metadata_json->>'credential_secret_key_id' !~ '^[a-f0-9]{64}$'
  OR c.metadata_json->>'credential_secret_key_id' IS DISTINCT FROM p_target->>'original_credential_secret_key_id' THEN
  RAISE EXCEPTION USING errcode='42501',message='original credential key provenance unavailable or changed';END IF;
 context:=public.custodial_v13_read_separation_context(op.device_id,op.credential_id);
 IF context IS NULL OR context IS DISTINCT FROM op.original_context OR context->>'state' IS DISTINCT FROM 'PENDING_RECONCILIATION' THEN
  RAISE EXCEPTION USING errcode='42501',message='original separation source changed';END IF;
 PERFORM 1 FROM public.custodial_employee_separation_fences WHERE separation_id=op.separation_id FOR SHARE;
 generation:=public.custodial_v14_read_separation_generation(op.device_id,op.credential_id,op.separation_id,op.generation_id,op.principal_digest);
 IF generation IS NULL OR generation IS DISTINCT FROM op.original_generation THEN
  RAISE EXCEPTION USING errcode='42501',message='original generation source changed';END IF;
 expected:=jsonb_build_object('operation_id',op.operation_id,'separation_id',op.separation_id,
  'separation_authority_revision',context->>'authority_revision','canonical_device_pk',op.device_id,
  'canonical_device_id',context->>'canonical_device_id','employee_id',context->>'employee_id','credential_id',op.credential_id,
  'assignment_epoch',context->>'assignment_epoch','original_generation_id',op.generation_id,
  'original_credential_secret_key_id',c.metadata_json->>'credential_secret_key_id','principal_digest',op.principal_digest,
  'engine_revision',op.owner_proof->>'engine_revision','original_wire_sha256',op.original_wire_sha256,
  'original_frozen_work_sha256',op.owner_proof->>'original_frozen_work_sha256','capsule_sha256',op.owner_proof->>'capsule_sha256',
  'record_sha256',op.record_sha256,'frame_sha256',op.frame_sha256,'plan_sha256',op.plan_sha256,
  'aad_binding_sha256',op.owner_proof->>'aad_binding_sha256','source_capture_sha256',op.owner_proof->>'source_capture_sha256',
  'values_sha256',op.owner_proof->>'values_sha256','semantic_join_sha256',op.owner_proof->>'semantic_join_sha256','layout_sha256',op.owner_proof->>'layout_sha256');
 IF p_target IS DISTINCT FROM expected OR EXISTS(SELECT 1 FROM jsonb_each(expected) WHERE jsonb_typeof(value)<>'string') THEN
  RAISE EXCEPTION USING errcode='42501',message='exact original preparation source tuple required';END IF;
 SELECT count(*),decode(string_agg(encode(chunk_bytes,'hex'),'' ORDER BY chunk_index),'hex') INTO counted,assembled
  FROM public.custodial_native_private_custody_chunks WHERE operation_id=op.operation_id;
 IF counted<>op.chunk_count OR octet_length(assembled) IS DISTINCT FROM op.frame_bytes
  OR encode(extensions.digest(assembled,'sha256'),'hex') IS DISTINCT FROM op.frame_sha256 THEN
  RAISE EXCEPTION USING errcode='42501',message='complete original opaque frame unavailable';END IF;
END $function$

CREATE OR REPLACE FUNCTION custodial_recovery.guard_native_registration()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE challenge public.custodial_same_original_recovery_challenges%rowtype;BEGIN
 IF TG_TABLE_NAME='custodial_same_original_recovery_challenges' THEN
  PERFORM custodial_recovery.assert_registered_challenge(NEW);
 ELSE
  SELECT * INTO STRICT challenge FROM public.custodial_same_original_recovery_challenges
   WHERE challenge_id=NEW.challenge_id FOR SHARE;
  PERFORM custodial_recovery.assert_registered_challenge(challenge);
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION custodial_recovery.inventory_completion_current(c jsonb, disposition text, target jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE op public.custodial_native_private_custody_operations%rowtype;
 cred public.device_auth_credentials%rowtype;part public.custodial_native_private_custody_chunks%rowtype;
 actual text;raw text;observed jsonb;BEGIN
 IF c='null'::jsonb THEN
  IF disposition IS DISTINCT FROM 'UNRESOLVED_RETAINED' THEN
   RAISE EXCEPTION USING errcode='42501',message='accepted original requires its exact argument source';END IF;
  RETURN;
 END IF;
 IF NOT custodial_recovery.inventory_object_keys(c,ARRAY['argument_sha256','original_query_request_id',
  'request_body_sha256','actual_response_sha256','readback','original_arguments_utf8'])
  OR EXISTS(SELECT 1 FROM jsonb_each(c) e WHERE e.key<>'readback' AND jsonb_typeof(e.value) IS DISTINCT FROM 'string')
  OR EXISTS(SELECT 1 FROM unnest(ARRAY['argument_sha256','request_body_sha256','actual_response_sha256']) k
   WHERE c->>k !~ '^[a-f0-9]{64}$')
  OR octet_length(c->>'original_query_request_id') NOT BETWEEN 1 AND 65536
  OR octet_length(c->>'original_arguments_utf8') NOT BETWEEN 1 AND 4194304 THEN
  RAISE EXCEPTION USING errcode='22023',message='bounded exact completion argument source required';END IF;
 raw:=c->>'original_arguments_utf8';observed:=c->'readback';
 IF encode(extensions.digest(convert_to(raw,'UTF8'),'sha256'),'hex') IS DISTINCT FROM c->>'argument_sha256'
  OR NOT custodial_recovery.inventory_object_keys(observed,ARRAY['schema','state','operation_id','original_generation_id',
   'argument_values_sha256','disposition','result','transaction_authority','limits'])
  OR observed->>'schema' IS DISTINCT FROM 'custodial.same-original-completion-SQL-read.v1'
  OR observed->>'state' IS DISTINCT FROM 'CURRENT_EXACT_ORIGINAL_COMPLETION_DISPOSITION_NOT_ACK'
  OR observed->>'operation_id' IS DISTINCT FROM target->>'operation_id'
  OR observed->>'original_generation_id' IS DISTINCT FROM target->>'original_generation_id'
  OR observed->>'argument_values_sha256' IS DISTINCT FROM c->>'argument_sha256'
  OR observed->'transaction_authority' IS DISTINCT FROM 'false'::jsonb
  OR observed->'limits' IS DISTINCT FROM custodial_recovery.denied_effects() THEN
  RAISE EXCEPTION USING errcode='42501',message='exact original completion source changed';END IF;
 IF disposition='UNRESOLVED_RETAINED' THEN
  IF observed->>'disposition' IS DISTINCT FROM 'UNRESOLVED_RETAINED' OR observed->'result' IS DISTINCT FROM 'null'::jsonb THEN
   RAISE EXCEPTION USING errcode='42501',message='unresolved original must remain retained';END IF;
  -- A later acceptance cannot turn this saved unknown into a deletion/ACK.
  -- It deliberately remains unknown and retained in this original manifest.
  RETURN;
 END IF;
 IF disposition IS DISTINCT FROM 'CURRENT_ACCEPTED_EXACT_ORIGINAL_NOT_ACK'
  OR observed->>'disposition' IS DISTINCT FROM 'ACCEPTED_EXACT_ORIGINAL' THEN
  RAISE EXCEPTION USING errcode='42501',message='closed original completion disposition required';END IF;
 SELECT * INTO STRICT op FROM public.custodial_native_private_custody_operations WHERE operation_id=(target->>'operation_id')::uuid;
 SELECT * INTO STRICT cred FROM public.device_auth_credentials WHERE credential_id=op.credential_id AND device_id=op.device_id;
 SELECT * INTO STRICT part FROM public.custodial_native_private_custody_chunks WHERE operation_id=op.operation_id AND chunk_index=0;
 -- Arguments are the archived exact bytes. Native request/body/attestation
 -- pins come from the actual immutable retained WRITE, not the manifest's
 -- claimed query IDs/digests. Existing SQL owns all accepted-record semantics.
 actual:=custodial_recovery.read_original_completion(op.operation_id,op.device_id,op.credential_id,cred.token_hash,
  cred.metadata_json->>'credential_secret_key_id',op.generation_id,0,part.native_request_id,
  part.request_body_sha256,part.attestation_digest,raw);
 IF actual IS NULL OR actual::jsonb IS DISTINCT FROM observed THEN
  RAISE EXCEPTION USING errcode='42501',message='current exact original accepted readback required';END IF;
END $function$

CREATE OR REPLACE FUNCTION custodial_recovery.issue_original_inventory_decision_once(p_manager uuid, p_credential uuid, p_device text, p_signed_expires timestamp with time zone, p_security_session uuid, p_password_version integer, p_security_hash text, p_csrf_hash text, p_signed_sha text, p_original_utf8 text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE request jsonb;review jsonb;registered public.custodial_native_inventory_requests%rowtype;
 saved public.custodial_original_inventory_separation_approvals%rowtype;expiry timestamptz;BEGIN
 request:=custodial_recovery.inventory_manager_original_command(p_original_utf8,p_manager,p_credential,p_device);
 IF p_signed_sha IS NULL OR p_signed_sha !~ '^[a-f0-9]{64}$' THEN
  RAISE EXCEPTION USING errcode='22023',message='actual signed original owner session required';END IF;
 PERFORM public.custodial_begin_application_mutation();
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 expiry:=custodial_recovery.assert_current_manager(p_manager,p_credential,p_device,p_signed_expires,
  p_security_session,p_password_version,p_security_hash,p_csrf_hash);
 PERFORM pg_advisory_xact_lock(hashtextextended('original-native-inventory-manifest:'||(request->>'native_request_id'),0));
 SELECT * INTO STRICT registered FROM public.custodial_native_inventory_requests
  WHERE native_request_id=(request->>'native_request_id')::uuid FOR SHARE;
 -- The normal immutable native frame/current separation/generation owner is
 -- held and reopened, not replaced by the request's hashes or a WORK witness.
 review:=custodial_recovery.review_original_inventory(p_manager,p_credential,p_device,p_signed_expires,
  p_security_session,p_password_version,p_security_hash,p_csrf_hash,registered.native_request_id);
 IF review IS NULL OR request->>'expected_review_sha256' IS DISTINCT FROM review->>'review_sha256'
  OR request->>'expected_inventory_manifest_sha256' IS DISTINCT FROM review->>'inventory_manifest_sha256'
  OR request->>'expected_registration_receipt_sha256' IS DISTINCT FROM review->>'registration_receipt_sha256'
  OR request->>'expected_separation_authority_revision' IS DISTINCT FROM review#>>'{original_target,separation_authority_revision}' THEN
  RAISE EXCEPTION USING errcode='40001',message='exact original inventory review changed';END IF;
 PERFORM custodial_recovery.assert_original_target(review->'original_target');
 PERFORM 1 FROM public.devices WHERE id=(review#>>'{original_target,canonical_device_pk}')::uuid FOR SHARE;
 PERFORM 1 FROM public.employees WHERE id=(review#>>'{original_target,employee_id}')::uuid FOR SHARE;
 PERFORM 1 FROM public.employee_native_push_generations WHERE generation_id=(review#>>'{original_target,original_generation_id}')::uuid FOR SHARE;
 -- Duplicate/uncertain writes never become a second dispatch. Only the
 -- separate fixed original-status reader may recover a persisted decision.
 IF EXISTS(SELECT 1 FROM public.custodial_original_inventory_separation_approvals
  WHERE request_id=(request->>'request_id')::uuid OR inventory_native_request_id=registered.native_request_id) THEN
  RAISE EXCEPTION USING errcode='23505',message='original inventory decision exists; read original status only';END IF;
 expiry:=least(expiry,(review->>'expires_at')::timestamptz,
  custodial_recovery.assert_current_manager(p_manager,p_credential,p_device,p_signed_expires,
   p_security_session,p_password_version,p_security_hash,p_csrf_hash));
 PERFORM custodial_recovery.assert_original_target(review->'original_target');
 saved.approved_at:=clock_timestamp();IF saved.approved_at>=expiry THEN
  RAISE EXCEPTION USING errcode='42501',message='original inventory decision expired';END IF;
 saved.request_id:=(request->>'request_id')::uuid;saved.inventory_native_request_id:=registered.native_request_id;
 saved.approval_id:=gen_random_uuid();saved.manager_id:=p_manager;saved.manager_credential_id:=p_credential;saved.manager_device_id:=p_device;
 saved.original_request_utf8:=p_original_utf8;saved.original_request_sha256:=encode(extensions.digest(convert_to(p_original_utf8,'UTF8'),'sha256'),'hex');
 saved.original_target:=review->'original_target';saved.review_sha256:=review->>'review_sha256';saved.manifest_sha256:=review->>'inventory_manifest_sha256';
 saved.registration_receipt_sha256:=review->>'registration_receipt_sha256';saved.signed_session_sha256:=p_signed_sha;
 saved.signed_session_expires_at:=p_signed_expires;saved.security_session_id:=p_security_session;saved.security_password_version:=p_password_version;
 saved.security_token_hash:=p_security_hash;saved.security_csrf_hash:=p_csrf_hash;saved.expires_at:=expiry;
 saved.receipt_utf8:=custodial_recovery.inventory_manager_receipt_document(saved);
 saved.receipt_sha256:=saved.receipt_utf8::jsonb->>'receipt_sha256';
 INSERT INTO public.custodial_original_inventory_separation_approvals SELECT saved.*;
 -- These two server-reported flags describe the stored decision only. The
 -- native engine STILL requires its unforgeable current all-writer/browser
 -- inventory admission before logical finalization. No effect occurs here.
 RETURN saved.receipt_utf8;
END $function$

CREATE OR REPLACE FUNCTION custodial_recovery.issue_original_preparation_once(p_manager uuid, p_credential uuid, p_device text, p_signed_sha text, p_signed_expires timestamp with time zone, p_security_session uuid, p_password_version integer, p_security_hash text, p_csrf_hash text, p_original_utf8 text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE request jsonb;challenge public.custodial_same_original_recovery_challenges%rowtype;
 prior public.custodial_same_original_recovery_approvals%rowtype;request_sha text;receipt jsonb;
 issued timestamptz;expiry timestamptz;approval uuid;keys text[];BEGIN
 IF p_original_utf8 IS NULL OR octet_length(p_original_utf8) NOT BETWEEN 1 AND 8192
  OR p_signed_sha IS NULL OR p_signed_sha !~ '^[a-f0-9]{64}$' THEN
  RAISE EXCEPTION USING errcode='22023',message='original preparation request required';END IF;
 PERFORM public.custodial_v15_assert_native_json(p_original_utf8::json,0);request:=p_original_utf8::jsonb;
 SELECT array_agg(key ORDER BY key COLLATE "C") INTO keys FROM jsonb_object_keys(request) key;
 IF keys IS DISTINCT FROM ARRAY['challenge_id','decision','expected_challenge_sha256','expected_manager_credential_id','expected_manager_device_id','expected_manager_id',
  'expected_preview_sha256','manager_confirmation','request_id','schema']::text[]
  OR request->>'schema' IS DISTINCT FROM 'custodial.same-original-recovery-approval-request.v1'
  OR request->>'decision' IS DISTINCT FROM 'AUTHORIZE_SAME_ORIGINAL_RECOVERY_PREPARATION'
  OR request->>'manager_confirmation' IS DISTINCT FROM 'CONFIRM_THIS_SAME_ORIGINAL_ONLY'
  OR request->>'expected_manager_id' IS DISTINCT FROM p_manager::text
  OR request->>'expected_manager_credential_id' IS DISTINCT FROM p_credential::text
  OR request->>'expected_manager_device_id' IS DISTINCT FROM p_device
  OR EXISTS(SELECT 1 FROM jsonb_each(request) WHERE jsonb_typeof(value)<>'string')
  OR request->>'request_id' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'
  OR request->>'challenge_id' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'
  OR p_device IS NULL OR p_device !~ '^[A-Za-z0-9_-]{1,128}$' THEN
  RAISE EXCEPTION USING errcode='22023',message='exact original preparation request and issuer required';END IF;
 PERFORM public.custodial_begin_application_mutation();
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 expiry:=custodial_recovery.assert_current_manager(p_manager,p_credential,p_device,p_signed_expires,
  p_security_session,p_password_version,p_security_hash,p_csrf_hash);
 SELECT * INTO STRICT challenge FROM public.custodial_same_original_recovery_challenges
  WHERE challenge_id=(request->>'challenge_id')::uuid FOR SHARE;
 IF request->>'expected_challenge_sha256' IS DISTINCT FROM challenge.challenge_sha256
  OR request->>'expected_preview_sha256' IS DISTINCT FROM challenge.preview_sha256 THEN
  RAISE EXCEPTION USING errcode='40001',message='original preparation preview changed';END IF;
 PERFORM custodial_recovery.assert_original_target(challenge.original_target);
 -- Serialize competing confirmations for THIS immutable original challenge.
 PERFORM pg_advisory_xact_lock(hashtextextended('same-original-preparation:'||challenge.challenge_id::text,0));
 request_sha:=custodial_recovery.document_digest('request',request);
 SELECT * INTO prior FROM public.custodial_same_original_recovery_approvals WHERE request_id=(request->>'request_id')::uuid;
 IF FOUND THEN
  IF prior.manager_id<>p_manager OR prior.manager_credential_id<>p_credential OR prior.manager_device_id<>p_device
   OR prior.original_request_utf8 IS DISTINCT FROM p_original_utf8 OR prior.original_request_sha256<>request_sha THEN
   RAISE EXCEPTION USING errcode='23505',message='conflicting original preparation request';END IF;
  RETURN prior.receipt_utf8;
 END IF;
 issued:=clock_timestamp();expiry:=least(expiry,challenge.expires_at);
 IF expiry<=issued THEN RAISE EXCEPTION USING errcode='42501',message='original preparation expired';END IF;
 IF EXISTS(SELECT 1 FROM public.custodial_same_original_recovery_approvals WHERE challenge_id=challenge.challenge_id) THEN
  RAISE EXCEPTION USING errcode='23505',message='original challenge already confirmed';END IF;
 approval:=gen_random_uuid();
 receipt:=jsonb_build_object('schema','custodial.same-original-recovery-approval-receipt.v1','state','APPROVAL_RECORDED_ONLY',
  'approval_id',approval,'original_request',request,'original_request_sha256',request_sha,
  'issuer',jsonb_build_object('manager_id',p_manager,'manager_credential_id',p_credential,'manager_device_id',p_device),
  'challenge_sha256',challenge.challenge_sha256,'preview_sha256',challenge.preview_sha256,'original_target',challenge.original_target,
  'purpose_admission_id','same-original-preparation.v1','issued_at',custodial_recovery.utc_micros(issued),
  'expires_at',custodial_recovery.utc_micros(expiry),'retry_safe',false,'limits',custodial_recovery.denied_effects());
 receipt:=receipt||jsonb_build_object('receipt_sha256',custodial_recovery.document_digest('receipt',receipt));
 INSERT INTO public.custodial_same_original_recovery_approvals(request_id,challenge_id,approval_id,manager_id,manager_credential_id,manager_device_id,
 original_request_utf8,original_request_raw_sha256,original_request_sha256,signed_session_sha256,signed_session_expires_at,
 security_session_id,security_password_version,security_token_hash,security_csrf_hash,receipt_utf8,receipt_sha256,issued_at,expires_at)
 VALUES((request->>'request_id')::uuid,challenge.challenge_id,approval,p_manager,p_credential,p_device,p_original_utf8,
 encode(extensions.digest(convert_to(p_original_utf8,'UTF8'),'sha256'),'hex'),request_sha,p_signed_sha,p_signed_expires,
 p_security_session,p_password_version,p_security_hash,p_csrf_hash,custodial_recovery.canonical_document(receipt),receipt->>'receipt_sha256',issued,expiry);
 RETURN custodial_recovery.canonical_document(receipt);
END $function$

CREATE OR REPLACE FUNCTION custodial_recovery.read_native_inventory_request_original(p_operation uuid, p_device uuid, p_credential uuid, p_credential_hash text, p_credential_key_id text, p_generation uuid, p_separation uuid, p_authority_revision text, p_native_request uuid, p_native_request_timestamp timestamp with time zone, p_native_request_body_sha256 text, p_native_attestation_digest text, p_original_request_utf8 text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE op public.custodial_native_private_custody_operations%rowtype;
 chunk public.custodial_native_private_custody_chunks%rowtype;credential public.device_auth_credentials%rowtype;
 saved public.custodial_native_inventory_requests%rowtype;source jsonb;request jsonb;intent jsonb;receipt jsonb;expected jsonb;digest text;
BEGIN
 IF p_operation IS NULL OR p_device IS NULL OR p_credential IS NULL OR p_generation IS NULL OR p_separation IS NULL
  OR p_native_request IS NULL OR p_original_request_utf8 IS NULL OR octet_length(p_original_request_utf8) NOT BETWEEN 1 AND 65536
  OR p_credential_hash IS NULL OR p_credential_hash !~ '^[a-f0-9]{64}$'
  OR p_credential_key_id IS NULL OR p_credential_key_id !~ '^[a-f0-9]{64}$'
  OR p_native_request_body_sha256 IS NULL OR p_native_request_body_sha256 !~ '^[a-f0-9]{64}$'
  OR p_native_attestation_digest IS NULL OR p_native_attestation_digest !~ '^[a-f0-9]{64}$'
  OR p_authority_revision IS NULL OR p_authority_revision !~ '^[1-9][0-9]*$'
  OR p_native_request_timestamp IS NULL OR NOT isfinite(p_native_request_timestamp)
  OR mod(extract(microseconds FROM p_native_request_timestamp)::bigint,1000)<>0
  OR encode(extensions.digest(convert_to(p_original_request_utf8,'UTF8'),'sha256'),'hex') IS DISTINCT FROM p_native_request_body_sha256 THEN
  RAISE EXCEPTION USING errcode='22023',message='bounded same-original inventory status required';END IF;
 PERFORM public.custodial_v15_assert_native_json(p_original_request_utf8::json,0);request:=p_original_request_utf8::jsonb;
 IF jsonb_typeof(request) IS DISTINCT FROM 'object'
  OR request->>'schema' IS DISTINCT FROM 'custodial.original-native-inventory-ack-request.v1'
  OR request->>'purpose' IS DISTINCT FROM 'REQUEST_EXACT_ORIGINAL_INVENTORY_ACK'
  OR jsonb_typeof(request->'original_intent_utf8') IS DISTINCT FROM 'string'
  OR octet_length(request->>'original_intent_utf8') NOT BETWEEN 1 AND 16384 THEN
  RAISE EXCEPTION USING errcode='22023',message='exact original request required';END IF;
 SELECT * INTO op FROM public.custodial_native_private_custody_operations WHERE operation_id=p_operation;
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT * INTO STRICT credential FROM public.device_auth_credentials WHERE credential_id=p_credential AND device_id=p_device;
 IF op.device_id IS DISTINCT FROM p_device OR op.credential_id IS DISTINCT FROM p_credential
  OR op.generation_id IS DISTINCT FROM p_generation OR op.separation_id IS DISTINCT FROM p_separation
  OR op.original_context->>'authority_revision' IS DISTINCT FROM p_authority_revision
  OR credential.token_hash IS DISTINCT FROM p_credential_hash OR credential.metadata_json->>'credential_secret_key_id' IS DISTINCT FROM p_credential_key_id
  OR credential.revoked_at IS NOT NULL OR credential.confirmed_at IS NULL OR NOT isfinite(credential.confirmed_at)
  OR credential.confirmed_at>clock_timestamp() OR credential.expires_at IS NULL OR NOT isfinite(credential.expires_at)
  OR credential.expires_at<=clock_timestamp() THEN
  RAISE EXCEPTION USING errcode='42501',message='current original status principal required';END IF;
 SELECT * INTO STRICT chunk FROM public.custodial_native_private_custody_chunks WHERE operation_id=p_operation AND chunk_index=0;
 -- This existing intended READ ONLY owner rechecks current separation,
 -- generation and complete original frame; no FOR SHARE/mutation/bootstrap.
 source:=custodial_recovery.read_original_target(p_operation,p_device,p_credential,p_credential_hash,p_credential_key_id,p_generation,
  0,chunk.native_request_id,chunk.request_body_sha256,chunk.attestation_digest);
 IF source IS NULL THEN RETURN NULL;END IF;
 PERFORM public.custodial_v15_assert_native_json((request->>'original_intent_utf8')::json,0);
 intent:=(request->>'original_intent_utf8')::jsonb;
 IF jsonb_typeof(intent) IS DISTINCT FROM 'object' OR intent->'original_target' IS DISTINCT FROM source->'original_target'
  OR intent->>'intent_id' IS DISTINCT FROM p_native_request::text
  OR request->>'original_intent_document_sha256' IS DISTINCT FROM encode(extensions.digest(convert_to(request->>'original_intent_utf8','UTF8'),'sha256'),'hex') THEN
  RAISE EXCEPTION USING errcode='42501',message='same original inventory target required';END IF;
 SELECT * INTO saved FROM public.custodial_native_inventory_requests WHERE native_request_id=p_native_request;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF saved.operation_id IS DISTINCT FROM p_operation OR saved.generation_id IS DISTINCT FROM p_generation
  OR saved.original_request_utf8 IS DISTINCT FROM p_original_request_utf8 OR saved.native_request_timestamp IS DISTINCT FROM p_native_request_timestamp
  OR saved.request_body_sha256 IS DISTINCT FROM p_native_request_body_sha256 OR saved.native_attestation_digest IS DISTINCT FROM p_native_attestation_digest
  OR saved.intent_document_sha256 IS DISTINCT FROM request->>'original_intent_document_sha256'
  OR saved.intent_disk_sha256 IS DISTINCT FROM request->>'original_intent_disk_sha256'
  OR saved.challenge_id::text IS DISTINCT FROM request->>'original_preparation_native_request_id'
  OR saved.request_body_sha256 IS DISTINCT FROM encode(extensions.digest(convert_to(saved.original_request_utf8,'UTF8'),'sha256'),'hex') THEN
  RAISE EXCEPTION USING errcode='42501',message='status belongs to another original request';END IF;
 PERFORM public.custodial_v15_assert_native_json(saved.receipt_utf8::json,0);receipt:=saved.receipt_utf8::jsonb;
 digest:=encode(extensions.digest(convert_to('custodial.native-original-inventory-request-registration-digest.v1'||E'\n'
  ||saved.native_request_id::text||E'\n'||saved.operation_id::text||E'\n'||saved.generation_id::text||E'\n'
  ||saved.request_body_sha256||E'\n'||saved.intent_document_sha256||E'\n'||saved.intent_disk_sha256||E'\n'
  ||custodial_recovery.utc_micros(saved.registered_at),'UTF8'),'sha256'),'hex');
 expected:=jsonb_build_object('schema','custodial.native-original-inventory-request-registration.v1','state','REGISTERED_REQUEST_ONLY_NOT_ACK',
  'native_request_id',saved.native_request_id,'operation_id',saved.operation_id,'original_generation_id',saved.generation_id,
  'request_body_sha256',saved.request_body_sha256,'intent_document_sha256',saved.intent_document_sha256,
  'intent_disk_sha256',saved.intent_disk_sha256,'registered_at',custodial_recovery.utc_micros(saved.registered_at),
  'receipt_sha256',digest,'limits',custodial_recovery.denied_effects());
 IF receipt IS DISTINCT FROM expected THEN RAISE EXCEPTION USING errcode='42501',message='immutable inventory registration receipt changed';END IF;
 -- Historical receipt is not renewed manager approval, present transaction
 -- admission or an effect capability; all six rights remain exactly false.
 RETURN saved.receipt_utf8;
END $function$

CREATE OR REPLACE FUNCTION custodial_recovery.read_original_inventory_decision(p_manager uuid, p_credential uuid, p_device text, p_signed_expires timestamp with time zone, p_security_session uuid, p_password_version integer, p_security_hash text, p_csrf_hash text, p_original_utf8 text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE request jsonb;saved public.custodial_original_inventory_separation_approvals%rowtype;receipt text;BEGIN
 PERFORM custodial_recovery.assert_inventory_manager_read(p_manager,p_credential,p_device,p_signed_expires,
  p_security_session,p_password_version,p_security_hash,p_csrf_hash);
 request:=custodial_recovery.inventory_manager_original_command(p_original_utf8,p_manager,p_credential,p_device);
 SELECT * INTO saved FROM public.custodial_original_inventory_separation_approvals WHERE request_id=(request->>'request_id')::uuid;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF saved.original_request_utf8 IS DISTINCT FROM p_original_utf8 OR saved.inventory_native_request_id::text IS DISTINCT FROM request->>'native_request_id'
  OR saved.manager_id IS DISTINCT FROM p_manager OR saved.manager_credential_id IS DISTINCT FROM p_credential
  OR saved.manager_device_id IS DISTINCT FROM p_device THEN
  RAISE EXCEPTION USING errcode='42501',message='only exact original inventory decision status may be read';END IF;
 receipt:=custodial_recovery.inventory_manager_receipt_document(saved);
 PERFORM custodial_recovery.assert_inventory_manager_read(p_manager,p_credential,p_device,p_signed_expires,
  p_security_session,p_password_version,p_security_hash,p_csrf_hash);
 RETURN receipt; -- Historical bytes, never a freshness renewal or native admission.
END $function$

CREATE OR REPLACE FUNCTION custodial_recovery.read_original_inventory_manifest_for_manager(p_manager uuid, p_credential uuid, p_device text, p_signed_expires timestamp with time zone, p_security_session uuid, p_password_version integer, p_security_hash text, p_csrf_hash text, p_inventory_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE saved public.custodial_native_inventory_requests%rowtype;op public.custodial_native_private_custody_operations%rowtype;
 native_credential public.device_auth_credentials%rowtype;first_chunk public.custodial_native_inventory_manifest_chunks%rowtype;
 registered text;manifest text;intent jsonb;observed timestamptz;until_time timestamptz;BEGIN
 until_time:=custodial_recovery.assert_inventory_manager_read(p_manager,p_credential,p_device,p_signed_expires,
  p_security_session,p_password_version,p_security_hash,p_csrf_hash);
 IF p_inventory_request IS NULL THEN RAISE EXCEPTION USING errcode='22023',message='original inventory request required';END IF;
 SELECT * INTO saved FROM public.custodial_native_inventory_requests WHERE native_request_id=p_inventory_request;
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT * INTO STRICT op FROM public.custodial_native_private_custody_operations WHERE operation_id=saved.operation_id;
 SELECT * INTO STRICT native_credential FROM public.device_auth_credentials WHERE credential_id=op.credential_id AND device_id=op.device_id;
 -- Derive original pins ONLY from immutable original rows/current private
 -- sources. The caller supplies neither native credentials/hashes nor a body.
 -- This is observation of an existing registration, NOT native impersonation
 -- or a writer dispatch. No secret/token is returned or selected.
 registered:=custodial_recovery.read_native_inventory_request_original(op.operation_id,op.device_id,op.credential_id,
  native_credential.token_hash,native_credential.metadata_json->>'credential_secret_key_id',op.generation_id,op.separation_id,
  op.original_context->>'authority_revision',saved.native_request_id,saved.native_request_timestamp,
  saved.request_body_sha256,saved.native_attestation_digest,saved.original_request_utf8);
 IF registered IS NULL THEN RETURN NULL;END IF;
 manifest:=custodial_recovery.retained_inventory_manifest_utf8(saved.native_request_id);
 IF manifest IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO STRICT first_chunk FROM public.custodial_native_inventory_manifest_chunks
  WHERE inventory_native_request_id=saved.native_request_id AND chunk_index=0;
 IF octet_length(manifest) NOT BETWEEN 1 AND 16777216
  OR encode(extensions.digest(convert_to(manifest,'UTF8'),'sha256'),'hex') IS DISTINCT FROM first_chunk.manifest_sha256 THEN
  RAISE EXCEPTION USING errcode='42501',message='complete exact original manifest required';END IF;
 intent:=((saved.original_request_utf8::jsonb)->>'original_intent_utf8')::jsonb;
 -- Recheck actual current manager session and original native source AFTER
 -- assembly. No effect/transaction authority can be derived from this read.
 until_time:=least(until_time,custodial_recovery.assert_inventory_manager_read(p_manager,p_credential,p_device,p_signed_expires,
  p_security_session,p_password_version,p_security_hash,p_csrf_hash));
 IF registered IS DISTINCT FROM custodial_recovery.read_native_inventory_request_original(op.operation_id,op.device_id,op.credential_id,
  native_credential.token_hash,native_credential.metadata_json->>'credential_secret_key_id',op.generation_id,op.separation_id,
  op.original_context->>'authority_revision',saved.native_request_id,saved.native_request_timestamp,
  saved.request_body_sha256,saved.native_attestation_digest,saved.original_request_utf8) THEN
  RAISE EXCEPTION USING errcode='42501',message='original registration read changed';END IF;
 observed:=clock_timestamp();IF observed>=until_time THEN RAISE EXCEPTION USING errcode='42501',message='original manifest read expired';END IF;
 RETURN jsonb_build_object('schema','custodial.original-inventory-manifest-manager-source.v1',
  'state','CURRENT_MANAGER_ORIGINAL_MANIFEST_DATA_ONLY_NOT_REVIEW_OR_ACK','manifest_utf8',manifest,
  'expected_original',jsonb_build_object('inventory_native_request_id',saved.native_request_id,
   'registration_request_body_sha256',saved.request_body_sha256,'intent_document_sha256',saved.intent_document_sha256,
   'intent_disk_sha256',saved.intent_disk_sha256,'original_target',intent->'original_target','manifest_sha256',first_chunk.manifest_sha256),
  'original_registration_receipt_sha256',(registered::jsonb)->>'receipt_sha256',
  'observed_at',custodial_recovery.utc_micros(observed),'current_until',custodial_recovery.utc_micros(until_time),
  'transaction_authority',false,'limits',custodial_recovery.denied_effects());
END $function$

CREATE OR REPLACE FUNCTION custodial_recovery.read_preparation_preview(p_manager uuid, p_credential uuid, p_device text, p_signed_expires timestamp with time zone, p_security_session uuid, p_password_version integer, p_security_hash text, p_csrf_hash text, p_challenge uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE challenge public.custodial_same_original_recovery_challenges%rowtype;BEGIN
 PERFORM custodial_recovery.assert_current_manager(p_manager,p_credential,p_device,p_signed_expires,
 p_security_session,p_password_version,p_security_hash,p_csrf_hash);
 SELECT * INTO challenge FROM public.custodial_same_original_recovery_challenges WHERE challenge_id=p_challenge FOR SHARE;
 IF NOT FOUND OR challenge.expires_at<=clock_timestamp() THEN RETURN NULL;END IF;
 PERFORM custodial_recovery.assert_original_target(challenge.original_target);
 IF challenge.preview_sha256 IS DISTINCT FROM custodial_recovery.document_digest('preview',challenge.preview_utf8::jsonb)
  OR challenge.original_target IS DISTINCT FROM challenge.preview_utf8::jsonb->'original_target'
  OR challenge.challenge_sha256 IS DISTINCT FROM challenge.preview_utf8::jsonb->>'challenge_sha256'
  OR challenge.challenge_id::text IS DISTINCT FROM challenge.preview_utf8::jsonb->>'challenge_id' THEN
 RAISE EXCEPTION USING errcode='42501',message='original preparation preview source changed';END IF;
 RETURN challenge.preview_utf8;
END $function$

CREATE OR REPLACE FUNCTION custodial_recovery.register_native_challenge_once(p_operation uuid, p_device uuid, p_credential uuid, p_credential_hash text, p_credential_key_id text, p_generation uuid, p_chunk_index integer, p_original_write_request uuid, p_original_write_body_sha256 text, p_original_write_attestation_digest text, p_native_request uuid, p_native_request_timestamp timestamp with time zone, p_native_request_body_sha256 text, p_native_attestation_digest text, p_original_utf8 text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE request jsonb;source jsonb;target jsonb;preview jsonb;receipt jsonb;registered timestamptz;expiry timestamptz;
 challenge_sha text;preview_sha text;credential public.device_auth_credentials%rowtype;context jsonb;BEGIN
 IF p_operation IS NULL OR p_device IS NULL OR p_credential IS NULL OR p_generation IS NULL OR p_native_request IS NULL
  OR p_original_write_request IS NULL OR p_chunk_index IS DISTINCT FROM 0
  OR p_original_utf8 IS NULL OR octet_length(p_original_utf8) NOT BETWEEN 1 AND 786432
  OR p_native_request_timestamp IS NULL OR NOT isfinite(p_native_request_timestamp)
  OR mod(extract(microseconds FROM p_native_request_timestamp)::bigint,1000)<>0
  OR p_credential_hash IS NULL OR p_credential_hash !~ '^[a-f0-9]{64}$'
  OR p_credential_key_id IS NULL OR p_credential_key_id !~ '^[a-f0-9]{64}$'
  OR p_original_write_body_sha256 IS NULL OR p_original_write_body_sha256 !~ '^[a-f0-9]{64}$'
  OR p_original_write_attestation_digest IS NULL OR p_original_write_attestation_digest !~ '^[a-f0-9]{64}$'
  OR p_native_request_body_sha256 IS NULL OR p_native_request_body_sha256 !~ '^[a-f0-9]{64}$'
  OR p_native_attestation_digest IS NULL OR p_native_attestation_digest !~ '^[a-f0-9]{64}$'
  OR encode(extensions.digest(convert_to(p_original_utf8,'UTF8'),'sha256'),'hex') IS DISTINCT FROM p_native_request_body_sha256 THEN
  RAISE EXCEPTION USING errcode='22023',message='fixed original native challenge inputs required';END IF;
 PERFORM public.custodial_v15_assert_native_json(p_original_utf8::json,0);request:=p_original_utf8::jsonb;
 IF jsonb_typeof(request) IS DISTINCT FROM 'object' OR request->>'schema' IS DISTINCT FROM 'custodial.same-original-recovery-native-challenge.v1'
  OR request->>'purpose' IS DISTINCT FROM 'AUTHORIZE_SAME_ORIGINAL_RECOVERY_PREPARATION'
  OR request->>'native_challenge_intent_id' IS DISTINCT FROM p_native_request::text
  OR jsonb_typeof(request->'native_challenge_intent_record_sha256') IS DISTINCT FROM 'string'
  OR request->>'native_challenge_intent_record_sha256' !~ '^[a-f0-9]{64}$' THEN
  RAISE EXCEPTION USING errcode='22023',message='original native challenge purpose required';END IF;
 PERFORM public.custodial_begin_application_mutation();
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 SELECT * INTO STRICT credential FROM public.device_auth_credentials WHERE credential_id=p_credential AND device_id=p_device FOR SHARE;
 IF credential.revoked_at IS NOT NULL OR credential.confirmed_at IS NULL OR credential.token_hash IS DISTINCT FROM p_credential_hash
  OR credential.metadata_json->>'credential_secret_key_id' IS DISTINCT FROM p_credential_key_id THEN
  RAISE EXCEPTION USING errcode='42501',message='current original native credential required';END IF;
 context:=public.custodial_v13_read_separation_context(p_device,p_credential);
 IF context IS NULL OR context->>'state' IS DISTINCT FROM 'PENDING_RECONCILIATION' THEN
  RAISE EXCEPTION USING errcode='42501',message='current original native separation required';END IF;
 PERFORM 1 FROM public.custodial_employee_separation_fences WHERE separation_id=(context->>'separation_id')::uuid FOR SHARE;
 source:=custodial_recovery.read_original_target(p_operation,p_device,p_credential,p_credential_hash,p_credential_key_id,p_generation,
  p_chunk_index,p_original_write_request,p_original_write_body_sha256,p_original_write_attestation_digest);
 IF source IS NULL OR source->>'state' IS DISTINCT FROM 'ORIGINAL_TARGET_DESCRIPTOR_ONLY' THEN
  RAISE EXCEPTION USING errcode='42501',message='retained complete original target required';END IF;
 target:=source->'original_target';PERFORM custodial_recovery.assert_original_target(target);
 IF request->'original_target' IS DISTINCT FROM target OR request->>'original_target_sha256' IS DISTINCT FROM source->>'original_target_sha256' THEN
  RAISE EXCEPTION USING errcode='42501',message='declared native target differs from retained original';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('same-original-native-preparation:'||p_operation::text,0));
 IF EXISTS(SELECT 1 FROM public.custodial_same_original_recovery_challenges WHERE challenge_id=p_native_request
  OR operation_id=p_operation AND target_sha256=source->>'original_target_sha256') THEN
  RAISE EXCEPTION USING errcode='23505',message='original challenge already exists; status only, no registration retry';END IF;
 registered:=clock_timestamp();
 IF p_native_request_timestamp>registered+interval '30 seconds' OR p_native_request_timestamp<registered-interval '120 seconds' THEN
  RAISE EXCEPTION USING errcode='42501',message='original native request timestamp no longer current';END IF;
 expiry:=least(registered+interval '5 minutes',p_native_request_timestamp+interval '5 minutes');
 challenge_sha:=encode(extensions.digest(convert_to('custodial.same-original-native-challenge-binding.v1'||E'\n'||p_native_request::text||E'\n'
  ||p_native_request_body_sha256||E'\n'||p_native_attestation_digest||E'\n'||(request->>'native_challenge_intent_record_sha256')||E'\n'
  ||(source->>'original_target_sha256')||E'\n'||custodial_recovery.utc_micros(registered)||E'\n'||custodial_recovery.utc_micros(expiry),'UTF8'),'sha256'),'hex');
 preview:=jsonb_build_object('schema','custodial.same-original-recovery-review.v1','state','ORIGINAL_BINDING_REVIEW_ONLY',
  'purpose','AUTHORIZE_SAME_ORIGINAL_RECOVERY_PREPARATION','challenge_id',p_native_request,'challenge_sha256',challenge_sha,
  'preview_sha256',repeat('0',64),'original_target',target,'expires_at',custodial_recovery.utc_micros(expiry),'limits',custodial_recovery.denied_effects());
 preview_sha:=custodial_recovery.document_digest('preview',preview);preview:=jsonb_set(preview,'{preview_sha256}',to_jsonb(preview_sha));
 receipt:=jsonb_build_object('schema','custodial.same-original-recovery-native-challenge-receipt.v1',
  'state','ORIGINAL_CHALLENGE_RECORDED_PREPARATION_ONLY','challenge_id',p_native_request,'challenge_sha256',challenge_sha,
  'original_target_sha256',source->>'original_target_sha256','native_challenge_intent_id',p_native_request,
  'native_challenge_intent_record_sha256',request->>'native_challenge_intent_record_sha256',
  'registered_at',custodial_recovery.utc_micros(registered),'expires_at',custodial_recovery.utc_micros(expiry),
  'retry_safe',false,'limits',custodial_recovery.denied_effects());
 INSERT INTO public.custodial_same_original_recovery_challenges(challenge_id,operation_id,target_sha256,original_target,challenge_sha256,
  preview_sha256,preview_utf8,native_challenge_request_sha256,registered_at,expires_at,native_request_utf8,native_request_id,
  native_request_timestamp,native_attestation_digest,native_intent_record_sha256,native_registration_receipt_utf8)
 VALUES(p_native_request,p_operation,source->>'original_target_sha256',target,challenge_sha,preview_sha,preview::text,
  p_native_request_body_sha256,registered,expiry,p_original_utf8,p_native_request,p_native_request_timestamp,p_native_attestation_digest,
  request->>'native_challenge_intent_record_sha256',receipt::text);
 RETURN receipt::text;
END $function$

CREATE OR REPLACE FUNCTION custodial_recovery.register_native_inventory_manifest_chunk_once(p_operation uuid, p_device uuid, p_credential uuid, p_credential_hash text, p_credential_key_id text, p_generation uuid, p_separation uuid, p_authority_revision text, p_native_request uuid, p_native_request_timestamp timestamp with time zone, p_native_request_body_sha256 text, p_native_attestation_digest text, p_original_request_utf8 text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE request jsonb;registered timestamptz;receipt jsonb;receipt_sha text;parent_id uuid;ordinal integer;BEGIN
 IF p_native_request IS NULL OR p_native_request_timestamp IS NULL OR NOT isfinite(p_native_request_timestamp)
  OR mod(extract(microseconds FROM p_native_request_timestamp)::bigint,1000)<>0
  OR p_native_request_body_sha256 IS NULL OR p_native_request_body_sha256 !~ '^[a-f0-9]{64}$'
  OR p_native_attestation_digest IS NULL OR p_native_attestation_digest !~ '^[a-f0-9]{64}$'
  OR encode(extensions.digest(convert_to(p_original_request_utf8,'UTF8'),'sha256'),'hex') IS DISTINCT FROM p_native_request_body_sha256 THEN
  RAISE EXCEPTION USING errcode='22023',message='original manifest HTTP identity required';END IF;
 PERFORM public.custodial_begin_application_mutation();
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 request:=custodial_recovery.assert_native_inventory_manifest_original(p_operation,p_device,p_credential,p_credential_hash,p_credential_key_id,
  p_generation,p_separation,p_authority_revision,p_original_request_utf8);
 parent_id:=(request->>'inventory_native_request_id')::uuid;ordinal:=(request->>'manifest_chunk_index')::integer;
 PERFORM pg_advisory_xact_lock(hashtextextended('original-native-inventory-manifest:'||parent_id::text,0));
 PERFORM 1 FROM public.custodial_native_inventory_requests WHERE native_request_id=parent_id FOR SHARE;
 PERFORM 1 FROM public.device_auth_credentials WHERE credential_id=p_credential AND device_id=p_device FOR SHARE;
 PERFORM custodial_recovery.assert_original_target(request->'original_target');
 IF p_native_request=parent_id OR EXISTS(SELECT 1 FROM public.custodial_native_inventory_manifest_chunks
  WHERE inventory_native_request_id=parent_id AND chunk_index=ordinal OR native_request_id=p_native_request) THEN
  RAISE EXCEPTION USING errcode='23505',message='original manifest chunk exists; status only';END IF;
 IF EXISTS(SELECT 1 FROM public.custodial_native_inventory_manifest_chunks WHERE inventory_native_request_id=parent_id
  AND (manifest_sha256 IS DISTINCT FROM request->>'manifest_sha256' OR manifest_byte_count IS DISTINCT FROM (request->>'manifest_byte_count')::integer
   OR manifest_chunk_count IS DISTINCT FROM (request->>'manifest_chunk_count')::integer)) THEN
  RAISE EXCEPTION USING errcode='42501',message='original inventory manifest cannot change';END IF;
 -- Recheck the original principal after waiting for the exact manifest lock.
 PERFORM custodial_recovery.assert_native_inventory_manifest_original(p_operation,p_device,p_credential,p_credential_hash,p_credential_key_id,
  p_generation,p_separation,p_authority_revision,p_original_request_utf8);
 registered:=clock_timestamp();
 IF p_native_request_timestamp NOT BETWEEN registered-interval '120 seconds' AND registered+interval '30 seconds' THEN
  RAISE EXCEPTION USING errcode='42501',message='current manifest request timestamp required';END IF;
 receipt_sha:=encode(extensions.digest(convert_to(concat_ws(E'\n','custodial.native-original-inventory-manifest-chunk-receipt.v1',
  parent_id::text,request->>'manifest_sha256',request->>'manifest_chunk_index',request->>'chunk_sha256',
  p_native_request::text,p_native_request_body_sha256,custodial_recovery.utc_micros(registered)),'UTF8'),'sha256'),'hex');
 receipt:=jsonb_build_object('schema','custodial.native-original-inventory-manifest-chunk-registration.v1','state','CHUNK_RETAINED_NOT_ACK',
  'inventory_native_request_id',parent_id,'manifest_sha256',request->>'manifest_sha256','manifest_chunk_index',request->>'manifest_chunk_index',
  'chunk_sha256',request->>'chunk_sha256','native_request_id',p_native_request,'request_body_sha256',p_native_request_body_sha256,
  'registered_at',custodial_recovery.utc_micros(registered),'receipt_sha256',receipt_sha,'limits',custodial_recovery.denied_effects());
 INSERT INTO public.custodial_native_inventory_manifest_chunks(inventory_native_request_id,chunk_index,manifest_sha256,manifest_byte_count,
  manifest_chunk_count,chunk_sha256,chunk_bytes,native_request_id,native_request_timestamp,original_request_utf8,request_body_sha256,
  native_attestation_digest,registered_at,receipt_utf8)
 VALUES(parent_id,ordinal,request->>'manifest_sha256',(request->>'manifest_byte_count')::integer,(request->>'manifest_chunk_count')::integer,
  request->>'chunk_sha256',decode(request->>'chunk_base64','base64'),p_native_request,p_native_request_timestamp,p_original_request_utf8,
  p_native_request_body_sha256,p_native_attestation_digest,registered,receipt::text);
 RETURN receipt::text;
END $function$

CREATE OR REPLACE FUNCTION custodial_recovery.register_native_inventory_request_once(p_operation uuid, p_device uuid, p_credential uuid, p_credential_hash text, p_credential_key_id text, p_generation uuid, p_separation uuid, p_authority_revision text, p_native_request uuid, p_native_request_timestamp timestamp with time zone, p_native_request_body_sha256 text, p_native_attestation_digest text, p_original_request_utf8 text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE request jsonb;intent jsonb;target jsonb;keys text[];binding text;preparation_digest text;
 op public.custodial_native_private_custody_operations%rowtype;
 chunk public.custodial_native_private_custody_chunks%rowtype;
 credential public.device_auth_credentials%rowtype;
 challenge public.custodial_same_original_recovery_challenges%rowtype;
 approval public.custodial_same_original_recovery_approvals%rowtype;
 manager_read text;registered timestamptz;receipt jsonb;receipt_sha text;BEGIN
 IF p_operation IS NULL OR p_device IS NULL OR p_credential IS NULL OR p_generation IS NULL OR p_separation IS NULL
  OR p_native_request IS NULL OR p_original_request_utf8 IS NULL OR octet_length(p_original_request_utf8) NOT BETWEEN 1 AND 65536
  OR p_credential_hash IS NULL OR p_credential_hash !~ '^[a-f0-9]{64}$'
  OR p_credential_key_id IS NULL OR p_credential_key_id !~ '^[a-f0-9]{64}$'
  OR p_native_request_body_sha256 IS NULL OR p_native_request_body_sha256 !~ '^[a-f0-9]{64}$'
  OR p_native_attestation_digest IS NULL OR p_native_attestation_digest !~ '^[a-f0-9]{64}$'
  OR p_authority_revision IS NULL OR p_authority_revision !~ '^[1-9][0-9]*$'
  OR p_native_request_timestamp IS NULL OR NOT isfinite(p_native_request_timestamp)
  OR mod(extract(microseconds FROM p_native_request_timestamp)::bigint,1000)<>0
  OR encode(extensions.digest(convert_to(p_original_request_utf8,'UTF8'),'sha256'),'hex') IS DISTINCT FROM p_native_request_body_sha256 THEN
  RAISE EXCEPTION USING errcode='22023',message='bounded original inventory request required';END IF;
 PERFORM public.custodial_v15_assert_native_json(p_original_request_utf8::json,0);
 request:=p_original_request_utf8::jsonb;
 IF jsonb_typeof(request) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING errcode='22023',message='closed inventory request required';END IF;
 SELECT array_agg(key ORDER BY key COLLATE "C") INTO keys FROM jsonb_object_keys(request) key;
 IF keys IS DISTINCT FROM ARRAY['original_intent_disk_sha256','original_intent_document_sha256','original_intent_utf8',
  'original_preparation_http_attestation','original_preparation_native_request_id','original_preparation_request_body_sha256',
  'purpose','purpose_attestation','purpose_binding_sha256','schema']::text[]
  OR EXISTS(SELECT 1 FROM jsonb_each(request) WHERE jsonb_typeof(value) IS DISTINCT FROM 'string')
  OR request->>'schema' IS DISTINCT FROM 'custodial.original-native-inventory-ack-request.v1'
  OR request->>'purpose' IS DISTINCT FROM 'REQUEST_EXACT_ORIGINAL_INVENTORY_ACK'
  OR octet_length(request->>'original_intent_utf8') NOT BETWEEN 1 AND 16384 THEN
  RAISE EXCEPTION USING errcode='22023',message='original inventory purpose required';END IF;
 IF EXISTS(SELECT 1 FROM unnest(ARRAY['original_intent_disk_sha256','original_intent_document_sha256',
  'original_preparation_http_attestation','original_preparation_request_body_sha256','purpose_attestation','purpose_binding_sha256']) k
  WHERE request->>k !~ '^[a-f0-9]{64}$') THEN RAISE EXCEPTION USING errcode='22023',message='original request hashes required';END IF;
 IF encode(extensions.digest(convert_to(request->>'original_intent_utf8','UTF8'),'sha256'),'hex')
  IS DISTINCT FROM request->>'original_intent_document_sha256' THEN RAISE EXCEPTION USING errcode='42501',message='original intent bytes changed';END IF;
 PERFORM public.custodial_v15_assert_native_json((request->>'original_intent_utf8')::json,0);
 intent:=(request->>'original_intent_utf8')::jsonb;
 IF jsonb_typeof(intent) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING errcode='22023',message='closed original intent required';END IF;
 SELECT array_agg(key ORDER BY key COLLATE "C") INTO keys FROM jsonb_object_keys(intent) key;
 IF keys IS DISTINCT FROM ARRAY['browser_frame_sha256','browser_part_set_sha256','created_at','finalizer_allowed','intent_id',
  'inventory_acknowledged','key_removal','native_held_stamp','original_target','phone_released','purpose','replay_allowed','schema','work_accepted']::text[]
  OR intent->>'schema' IS DISTINCT FROM 'custodial.native-original-inventory-ack-intent.v1'
  OR intent->>'purpose' IS DISTINCT FROM 'PREPARE_EXACT_ORIGINAL_INVENTORY_ACK'
  OR intent->>'intent_id' IS DISTINCT FROM p_native_request::text
  OR EXISTS(SELECT 1 FROM unnest(ARRAY['schema','purpose','intent_id','native_held_stamp','browser_frame_sha256',
    'browser_part_set_sha256','created_at']) k WHERE jsonb_typeof(intent->k) IS DISTINCT FROM 'string')
  OR intent->>'native_held_stamp' !~ '^DURABLE_HELD:[1-9][0-9]{0,18}$'
  OR substring(intent->>'native_held_stamp' FROM 14)::numeric>9223372036854775807
  OR intent->>'browser_frame_sha256' !~ '^[a-f0-9]{64}$' OR intent->>'browser_part_set_sha256' !~ '^[a-f0-9]{64}$'
  OR intent->>'created_at' IS DISTINCT FROM to_char((intent->>'created_at')::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
  OR intent->>'created_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$'
  OR left(intent->>'created_at',4)='0000'
  OR EXISTS(SELECT 1 FROM jsonb_each(custodial_recovery.denied_effects()) f WHERE intent->f.key IS DISTINCT FROM 'false'::jsonb) THEN
  RAISE EXCEPTION USING errcode='22023',message='exact original held intent with no effect rights required';END IF;
 binding:=encode(extensions.digest(convert_to('custodial.native-original-inventory-ack-purpose.v1'||E'\n'
  ||(request->>'original_intent_disk_sha256')||E'\n'||(request->>'original_intent_document_sha256')||E'\n'
  ||(request->>'original_preparation_native_request_id')||E'\n'||(request->>'original_preparation_request_body_sha256')||E'\n'
  ||(request->>'original_preparation_http_attestation'),'UTF8'),'sha256'),'hex');
 IF binding IS DISTINCT FROM request->>'purpose_binding_sha256' THEN RAISE EXCEPTION USING errcode='42501',message='original purpose binding changed';END IF;
 PERFORM public.custodial_begin_application_mutation();
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 SELECT * INTO STRICT op FROM public.custodial_native_private_custody_operations WHERE operation_id=p_operation FOR SHARE;
 SELECT * INTO STRICT credential FROM public.device_auth_credentials WHERE credential_id=p_credential AND device_id=p_device FOR SHARE;
 IF op.device_id IS DISTINCT FROM p_device OR op.credential_id IS DISTINCT FROM p_credential
  OR op.generation_id IS DISTINCT FROM p_generation OR op.separation_id IS DISTINCT FROM p_separation
  OR op.original_context->>'authority_revision' IS DISTINCT FROM p_authority_revision
  OR credential.token_hash IS DISTINCT FROM p_credential_hash OR credential.metadata_json->>'credential_secret_key_id' IS DISTINCT FROM p_credential_key_id
  OR credential.revoked_at IS NOT NULL OR credential.confirmed_at IS NULL OR NOT isfinite(credential.confirmed_at)
  OR credential.confirmed_at>clock_timestamp() OR credential.expires_at IS NULL
  OR NOT isfinite(credential.expires_at) OR credential.expires_at<=clock_timestamp() THEN
  RAISE EXCEPTION USING errcode='42501',message='current original inventory principal required';END IF;
 target:=intent->'original_target';PERFORM custodial_recovery.assert_original_target(target);
 IF target->>'operation_id' IS DISTINCT FROM p_operation::text OR target->>'original_generation_id' IS DISTINCT FROM p_generation::text
  OR target->>'canonical_device_pk' IS DISTINCT FROM p_device::text OR target->>'credential_id' IS DISTINCT FROM p_credential::text
  OR target->>'original_credential_secret_key_id' IS DISTINCT FROM p_credential_key_id THEN
  RAISE EXCEPTION USING errcode='42501',message='same original inventory target required';END IF;
 SELECT * INTO STRICT challenge FROM public.custodial_same_original_recovery_challenges
  WHERE challenge_id=(request->>'original_preparation_native_request_id')::uuid AND operation_id=p_operation FOR SHARE;
 PERFORM custodial_recovery.assert_registered_challenge(challenge);
 IF challenge.original_target IS DISTINCT FROM target
  OR challenge.native_challenge_request_sha256 IS DISTINCT FROM request->>'original_preparation_request_body_sha256' THEN
  RAISE EXCEPTION USING errcode='42501',message='original preparation does not match inventory request';END IF;
 -- All entries in this JSON transcript are fixed ASCII strings without comma
 -- spaces. Removing the jsonb separators reproduces the existing JS array
 -- digest; it does not normalize original request/intent bytes.
 preparation_digest:=encode(extensions.digest(convert_to(replace(jsonb_build_array('custodial-native-request.v1',p_credential::text,
  target->>'canonical_device_id','POST','/device-auth/same-original-recovery/challenge',challenge.native_challenge_request_sha256,
  challenge.native_request_id::text,to_char(challenge.native_request_timestamp AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  request->>'original_preparation_http_attestation')::text,', ',','),'UTF8'),'sha256'),'hex');
 IF preparation_digest IS DISTINCT FROM challenge.native_attestation_digest THEN
  RAISE EXCEPTION USING errcode='42501',message='original preparation attestation changed';END IF;
 SELECT * INTO STRICT chunk FROM public.custodial_native_private_custody_chunks WHERE operation_id=p_operation AND chunk_index=0 FOR SHARE;
 SELECT * INTO STRICT approval FROM public.custodial_same_original_recovery_approvals WHERE challenge_id=challenge.challenge_id FOR SHARE;
 PERFORM custodial_recovery.assert_current_manager(approval.manager_id,approval.manager_credential_id,approval.manager_device_id,
  approval.signed_session_expires_at,approval.security_session_id,approval.security_password_version,approval.security_token_hash,approval.security_csrf_hash);
 manager_read:=custodial_recovery.read_current_native_manager_preparation(p_operation,p_device,p_credential,p_credential_hash,p_credential_key_id,
  p_generation,0,chunk.native_request_id,chunk.request_body_sha256,chunk.attestation_digest,challenge.native_request_id,
  challenge.native_request_timestamp,challenge.native_challenge_request_sha256,challenge.native_attestation_digest,challenge.native_request_utf8);
 IF manager_read IS NULL THEN RAISE EXCEPTION USING errcode='42501',message='current original manager preparation unavailable';END IF;
 -- Registration is one INSERT, never an upsert/retry or historical adoption.
 -- A lost response is UNKNOWN and needs the later authenticated status route.
 PERFORM pg_advisory_xact_lock(hashtextextended('original-native-inventory-request:'||p_operation::text,0));
 IF EXISTS(SELECT 1 FROM public.custodial_native_inventory_requests WHERE native_request_id=p_native_request
  OR operation_id=p_operation AND generation_id=p_generation) THEN
  RAISE EXCEPTION USING errcode='23505',message='original inventory request exists; status only';END IF;
 PERFORM custodial_recovery.assert_current_manager(approval.manager_id,approval.manager_credential_id,approval.manager_device_id,
  approval.signed_session_expires_at,approval.security_session_id,approval.security_password_version,approval.security_token_hash,approval.security_csrf_hash);
 registered:=clock_timestamp();
 IF challenge.expires_at<=registered OR approval.expires_at<=registered OR credential.expires_at<=registered
  OR p_native_request_timestamp>registered+interval '30 seconds' OR p_native_request_timestamp<registered-interval '120 seconds' THEN
  RAISE EXCEPTION USING errcode='42501',message='original inventory request timestamp expired';END IF;
 receipt_sha:=encode(extensions.digest(convert_to('custodial.native-original-inventory-request-registration-digest.v1'||E'\n'
  ||p_native_request::text||E'\n'||p_operation::text||E'\n'||p_generation::text||E'\n'||p_native_request_body_sha256||E'\n'
  ||(request->>'original_intent_document_sha256')||E'\n'||(request->>'original_intent_disk_sha256')||E'\n'
  ||custodial_recovery.utc_micros(registered),'UTF8'),'sha256'),'hex');
 receipt:=jsonb_build_object('schema','custodial.native-original-inventory-request-registration.v1','state','REGISTERED_REQUEST_ONLY_NOT_ACK',
  'native_request_id',p_native_request,'operation_id',p_operation,'original_generation_id',p_generation,'request_body_sha256',p_native_request_body_sha256,
  'intent_document_sha256',request->>'original_intent_document_sha256','intent_disk_sha256',request->>'original_intent_disk_sha256',
  'registered_at',custodial_recovery.utc_micros(registered),'receipt_sha256',receipt_sha,'limits',custodial_recovery.denied_effects());
 INSERT INTO public.custodial_native_inventory_requests(native_request_id,operation_id,generation_id,challenge_id,original_request_utf8,
  request_body_sha256,native_request_timestamp,native_attestation_digest,intent_document_sha256,intent_disk_sha256,registered_at,receipt_utf8)
 VALUES(p_native_request,p_operation,p_generation,challenge.challenge_id,p_original_request_utf8,p_native_request_body_sha256,
  p_native_request_timestamp,p_native_attestation_digest,request->>'original_intent_document_sha256',request->>'original_intent_disk_sha256',registered,receipt::text);
 RETURN receipt::text;
END $function$

CREATE OR REPLACE FUNCTION custodial_recovery.retained_inventory_manifest_utf8(p_inventory_request uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE first_row public.custodial_native_inventory_manifest_chunks%rowtype;counted integer;assembled bytea;original text;BEGIN
 SELECT * INTO first_row FROM public.custodial_native_inventory_manifest_chunks
  WHERE inventory_native_request_id=p_inventory_request AND chunk_index=0;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF EXISTS(SELECT 1 FROM public.custodial_native_inventory_manifest_chunks WHERE inventory_native_request_id=p_inventory_request
  AND (manifest_sha256 IS DISTINCT FROM first_row.manifest_sha256 OR manifest_byte_count<>first_row.manifest_byte_count
   OR manifest_chunk_count<>first_row.manifest_chunk_count
   OR encode(extensions.digest(chunk_bytes,'sha256'),'hex') IS DISTINCT FROM chunk_sha256)) THEN
  RAISE EXCEPTION USING errcode='42501',message='mixed original manifest retained unresolved';END IF;
 SELECT count(*),decode(string_agg(encode(chunk_bytes,'hex'),'' ORDER BY chunk_index),'hex') INTO counted,assembled
  FROM public.custodial_native_inventory_manifest_chunks WHERE inventory_native_request_id=p_inventory_request;
 IF counted<>first_row.manifest_chunk_count THEN RETURN NULL;END IF;
 IF octet_length(assembled)<>first_row.manifest_byte_count
  OR encode(extensions.digest(assembled,'sha256'),'hex') IS DISTINCT FROM first_row.manifest_sha256 THEN
  RAISE EXCEPTION USING errcode='42501',message='exact full original manifest bytes required';END IF;
 original:=convert_from(assembled,'UTF8');RETURN original;
END $function$

CREATE OR REPLACE FUNCTION custodial_recovery.review_original_inventory(p_manager uuid, p_credential uuid, p_device text, p_signed_expires timestamp with time zone, p_security_session uuid, p_password_version integer, p_security_hash text, p_csrf_hash text, p_inventory_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE source jsonb;manifest jsonb;raw text;bad boolean;target jsonb;intent jsonb;row jsonb;item jsonb;domain jsonb;
 names constant text[]:=ARRAY['MemphisZooCustodialNativeProviderV1','MemphisZooCustodialNativeVaultV1','MemphisZooCustodialNativeVaultV2',
  'MemphisZooCustodialOfflineAuthorityTimeV1','MemphisZooCustodialRetainedAttemptV1','MemphisZooCustodialRetainedBatchV1',
  'MemphisZooCustodialRetainedReadQueryV1','WSSecureStorageSharedPreferences'];
 families constant text[]:=ARRAY['SEPARATE_PROVIDER_V1','LEGACY_VAULT_V1','SHARED_VAULT_V2','SHARED_VAULT_V2',
  'SHARED_VAULT_V2','SHARED_VAULT_V2','SHARED_VAULT_V2','LEGACY_ALIAS_BOUND_SECURE_STORAGE'];
 totals integer[]:=ARRAY[0,0,0,0,0,0,0,0];accepted integer[]:=ARRAY[0,0,0,0,0,0,0,0];
 ordinal integer:=0;idx integer;prior integer:=0;db_count integer:=0;stores integer:=0;domain_counts integer[];
 database_bytes bytea;store_bytes bytea;prior_db bytea;prior_store bytea;db_version bigint;empty_db boolean:=false;
 browser_accepted integer:=0;family_total integer;frame jsonb;summary jsonb;review jsonb;reviewed timestamptz;expiry timestamptz;
 parent public.custodial_native_inventory_requests%rowtype;employee_label text;BEGIN
 source:=custodial_recovery.read_original_inventory_manifest_for_manager(p_manager,p_credential,p_device,p_signed_expires,
  p_security_session,p_password_version,p_security_hash,p_csrf_hash,p_inventory_request);
 IF source IS NULL THEN RETURN NULL;END IF;
 raw:=source->>'manifest_utf8';
 -- Reject duplicate fields and non-integer numeric spellings BEFORE jsonb
 -- conversion; original completion JSON remains an opaque STRING until the
 -- fixed exact reader handles it, preserving arbitrary numeric DATA.
 WITH RECURSIVE nodes(v,d) AS (
  SELECT raw::json,0 UNION ALL SELECT child.v,n.d+1 FROM nodes n CROSS JOIN LATERAL (
   SELECT value v FROM json_each(CASE WHEN json_typeof(n.v)='object' THEN n.v ELSE '{}'::json END)
   UNION ALL SELECT value FROM json_array_elements(CASE WHEN json_typeof(n.v)='array' THEN n.v ELSE '[]'::json END)
  ) child WHERE n.d<=24
 ) SELECT count(*)>2000000 OR coalesce(max(d),0)>24 OR coalesce(bool_or(
  CASE WHEN json_typeof(v)='object' THEN (SELECT count(*)<>count(DISTINCT key COLLATE "C") FROM json_each(v))
   WHEN json_typeof(v)='number' THEN v::text !~ '^(0|[1-9][0-9]*)$' OR v::text::numeric>9007199254740991
   ELSE false END),false) INTO bad FROM nodes;
 IF bad THEN RAISE EXCEPTION USING errcode='22023',message='bounded unambiguous original inventory required';END IF;
 manifest:=raw::jsonb;target:=source#>'{expected_original,original_target}';
 IF NOT custodial_recovery.inventory_object_keys(manifest,ARRAY['schema','state','native_request_id',
  'registration_request_body_sha256','intent_document_sha256','intent_disk_sha256','original_target','native_held_stamp',
  'native_namespaces','native_records','browser_realm_name_encoding','browser_domains','browser_records','browser_value_frame',
  'browser_part_set_sha256','browser_accepted_exact_original_count','browser_unresolved_retained_count','retained_key_families',
  'inventory_acknowledged','work_accepted','replay_allowed','finalizer_allowed','key_removal','phone_released'])
  OR manifest->>'schema' IS DISTINCT FROM 'custodial.native-original-complete-inventory-manifest.v2'
  OR manifest->>'state' IS DISTINCT FROM 'ALL_DECLARED_ORIGINAL_ROWS_WITH_EXPLICIT_UNRESOLVED_RETENTION_NOT_ACK'
  OR manifest->>'native_request_id' IS DISTINCT FROM p_inventory_request::text OR manifest->'original_target' IS DISTINCT FROM target
  OR EXISTS(SELECT 1 FROM jsonb_each(custodial_recovery.denied_effects()) e WHERE manifest->e.key IS DISTINCT FROM e.value)
  OR EXISTS(SELECT 1 FROM unnest(ARRAY['registration_request_body_sha256','intent_document_sha256','intent_disk_sha256']) k
   WHERE manifest->k IS DISTINCT FROM source#>ARRAY['expected_original',k])
  OR jsonb_typeof(manifest->'native_namespaces') IS DISTINCT FROM 'array' OR jsonb_array_length(manifest->'native_namespaces')<>8
  OR jsonb_typeof(manifest->'native_records') IS DISTINCT FROM 'array' OR jsonb_array_length(manifest->'native_records')>32768
  OR jsonb_typeof(manifest->'browser_domains') IS DISTINCT FROM 'array' OR jsonb_array_length(manifest->'browser_domains') NOT BETWEEN 2 AND 4098
  OR jsonb_typeof(manifest->'browser_records') IS DISTINCT FROM 'array' OR jsonb_array_length(manifest->'browser_records')>4096
  OR jsonb_typeof(manifest->'retained_key_families') IS DISTINCT FROM 'array' OR jsonb_array_length(manifest->'retained_key_families')<>4 THEN
  RAISE EXCEPTION USING errcode='42501',message='complete exact original v2 semantic source required';END IF;
 SELECT * INTO STRICT parent FROM public.custodial_native_inventory_requests WHERE native_request_id=p_inventory_request;
 intent:=((parent.original_request_utf8::jsonb)->>'original_intent_utf8')::jsonb;
 IF manifest->'native_held_stamp' IS DISTINCT FROM intent->'native_held_stamp'
  OR manifest#>'{browser_value_frame,frame_sha256}' IS DISTINCT FROM intent->'browser_frame_sha256'
  OR manifest->'browser_part_set_sha256' IS DISTINCT FROM intent->'browser_part_set_sha256' THEN
  RAISE EXCEPTION USING errcode='42501',message='original native/browser hold pins changed';END IF;
 FOR row IN SELECT value FROM jsonb_array_elements(manifest->'native_records') LOOP
  idx:=array_position(names,row->>'namespace');
  IF NOT custodial_recovery.inventory_object_keys(row,ARRAY['ordinal','namespace','key_family','raw_identity_sha256',
    'raw_type','local_source_classification','disposition','completion_readback']) OR idx IS NULL OR idx<prior
   OR row->'ordinal' IS DISTINCT FROM to_jsonb(ordinal) OR row->>'key_family' IS DISTINCT FROM families[idx]
   OR jsonb_typeof(row->'raw_identity_sha256') IS DISTINCT FROM 'string' OR row->>'raw_identity_sha256' !~ '^[a-f0-9]{64}$'
   OR coalesce(row->>'raw_type','') NOT IN ('STRING','INTEGER','LONG','BOOLEAN','FLOAT_RAW_BITS','STRING_SET')
   OR jsonb_typeof(row->'local_source_classification') IS DISTINCT FROM 'string'
   OR row->>'local_source_classification' !~ '^[A-Z0-9_]{1,160}$'
   OR coalesce(row->>'disposition','') NOT IN ('CURRENT_ACCEPTED_EXACT_ORIGINAL_NOT_ACK','UNRESOLVED_RETAINED')
   OR row->'completion_readback'<>'null'::jsonb AND idx<>3 THEN
   RAISE EXCEPTION USING errcode='22023',message='closed original native inventory row required';END IF;
  totals[idx]:=totals[idx]+1;IF totals[idx]>4096 THEN RAISE EXCEPTION USING errcode='22023',message='native inventory bounds';END IF;
  PERFORM custodial_recovery.inventory_completion_current(row->'completion_readback',row->>'disposition',target);
  IF row->>'disposition'='CURRENT_ACCEPTED_EXACT_ORIGINAL_NOT_ACK' THEN accepted[idx]:=accepted[idx]+1;END IF;
  prior:=idx;ordinal:=ordinal+1;
 END LOOP;
 IF (SELECT count(*)<>count(DISTINCT (value->>'namespace',value->>'raw_identity_sha256'))
  FROM jsonb_array_elements(manifest->'native_records')) THEN
  RAISE EXCEPTION USING errcode='22023',message='duplicate original native identity';END IF;
 FOR idx IN 1..8 LOOP
  item:=manifest->'native_namespaces'->(idx-1);
  IF NOT custodial_recovery.inventory_object_keys(item,ARRAY['namespace','record_count','accepted_exact_original_count','unresolved_retained_count'])
   OR item IS DISTINCT FROM jsonb_build_object('namespace',names[idx],'record_count',totals[idx],
    'accepted_exact_original_count',accepted[idx],'unresolved_retained_count',totals[idx]-accepted[idx]) THEN
   RAISE EXCEPTION USING errcode='22023',message='complete exact native partitions required';END IF;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(manifest->'retained_key_families') LOOP
  SELECT coalesce(sum(totals[n]),0) INTO family_total FROM generate_series(1,8) n WHERE families[n]=item->>'key_family';
  IF NOT custodial_recovery.inventory_object_keys(item,ARRAY['key_family','source_declared_raw_rows_to_preserve',
    'possible_undeclared_references','all_writer_durable_freeze_or_ABA_guard','current_server_reconciliation',
    'zero_rows_is_not_key_removal_authority','finalizer_allowed','key_removal'])
   OR coalesce(item->>'key_family','') NOT IN ('SEPARATE_PROVIDER_V1','LEGACY_VAULT_V1','SHARED_VAULT_V2','LEGACY_ALIAS_BOUND_SECURE_STORAGE')
   OR item->'source_declared_raw_rows_to_preserve' IS DISTINCT FROM to_jsonb(family_total)
   OR item->>'possible_undeclared_references' IS DISTINCT FROM 'UNKNOWN'
   OR item->'zero_rows_is_not_key_removal_authority' IS DISTINCT FROM 'true'::jsonb
   OR EXISTS(SELECT 1 FROM unnest(ARRAY['all_writer_durable_freeze_or_ABA_guard','current_server_reconciliation','finalizer_allowed','key_removal']) k
    WHERE item->k IS DISTINCT FROM 'false'::jsonb) THEN
   RAISE EXCEPTION USING errcode='42501',message='all original referenced keys must remain retained';END IF;
 END LOOP;
 IF (SELECT count(DISTINCT value->>'key_family') FROM jsonb_array_elements(manifest->'retained_key_families'))<>4 THEN
  RAISE EXCEPTION USING errcode='22023',message='complete key family coverage required';END IF;
 ordinal:=0;domain_counts:=array_fill(0,ARRAY[jsonb_array_length(manifest->'browser_domains')]);
 FOR domain IN SELECT value FROM jsonb_array_elements(manifest->'browser_domains') LOOP
  IF NOT custodial_recovery.inventory_object_keys(domain,ARRAY['domain_ordinal','store','database_utf16be_base64','version',
    'object_store_utf16be_base64','record_count','state']) OR domain->'domain_ordinal' IS DISTINCT FROM to_jsonb(ordinal) THEN
   RAISE EXCEPTION USING errcode='22023',message='exact declared browser domain required';END IF;
  IF ordinal<2 THEN
   IF domain->>'store' IS DISTINCT FROM (CASE ordinal WHEN 0 THEN 'localStorage' ELSE 'sessionStorage' END)
    OR domain->'database_utf16be_base64' IS DISTINCT FROM 'null'::jsonb OR domain->'version' IS DISTINCT FROM 'null'::jsonb
    OR domain->'object_store_utf16be_base64' IS DISTINCT FROM 'null'::jsonb THEN
    RAISE EXCEPTION USING errcode='22023',message='exact local/session domain required';END IF;
   IF ordinal=1 AND domain->>'state'='UNAVAILABLE_UNRESOLVED_RETAINED' THEN
    IF domain->'record_count' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION USING errcode='22023',message='unavailable session is unknown';END IF;
   ELSIF domain->>'state' IS DISTINCT FROM 'DECLARED_ORIGINAL_ROWS_NOT_AUTHORITY'
    OR NOT custodial_recovery.inventory_count(domain->'record_count',4096) THEN
    RAISE EXCEPTION USING errcode='22023',message='bounded declared browser rows required';
   END IF;
  ELSE
   IF domain->>'store' IS DISTINCT FROM 'indexedDB' OR jsonb_typeof(domain->'database_utf16be_base64') IS DISTINCT FROM 'string'
    OR NOT custodial_recovery.inventory_count(domain->'version',9007199254740991) OR (domain->>'version')::bigint<1
    OR NOT custodial_recovery.inventory_count(domain->'record_count',4096) THEN
    RAISE EXCEPTION USING errcode='22023',message='bounded exact IndexedDB domain required';END IF;
   database_bytes:=decode(domain->>'database_utf16be_base64','base64');
   IF octet_length(database_bytes)>2048 OR mod(octet_length(database_bytes),2)<>0
    OR replace(encode(database_bytes,'base64'),E'\n','') IS DISTINCT FROM domain->>'database_utf16be_base64' THEN
    RAISE EXCEPTION USING errcode='22023',message='lossless original database name required';END IF;
   IF prior_db IS NULL OR database_bytes<>prior_db THEN
    IF prior_db IS NOT NULL AND database_bytes<=prior_db THEN RAISE EXCEPTION USING errcode='22023',message='database ordering';END IF;
    db_count:=db_count+1;IF db_count>32 THEN RAISE EXCEPTION USING errcode='22023',message='database bounds';END IF;
    prior_db:=database_bytes;db_version:=(domain->>'version')::bigint;prior_store:=NULL;stores:=0;empty_db:=false;
   ELSIF db_version<>(domain->>'version')::bigint OR empty_db THEN
    RAISE EXCEPTION USING errcode='22023',message='exact database version/store declaration required';END IF;
   IF domain->'object_store_utf16be_base64'='null'::jsonb THEN
    IF stores<>0 OR domain->>'state' IS DISTINCT FROM 'DECLARED_EMPTY_DATABASE_NOT_AUTHORITY' OR domain->'record_count'<>'0'::jsonb THEN
     RAISE EXCEPTION USING errcode='22023',message='empty database is not an empty store';END IF;empty_db:=true;
   ELSE
    IF jsonb_typeof(domain->'object_store_utf16be_base64') IS DISTINCT FROM 'string'
     OR domain->>'state' IS DISTINCT FROM 'DECLARED_ORIGINAL_ROWS_NOT_AUTHORITY' THEN
     RAISE EXCEPTION USING errcode='22023',message='original object store declaration required';END IF;
    store_bytes:=decode(domain->>'object_store_utf16be_base64','base64');
    IF octet_length(store_bytes)>8388608 OR mod(octet_length(store_bytes),2)<>0
     OR replace(encode(store_bytes,'base64'),E'\n','') IS DISTINCT FROM domain->>'object_store_utf16be_base64'
     OR prior_store IS NOT NULL AND store_bytes<=prior_store THEN
     RAISE EXCEPTION USING errcode='22023',message='lossless ordered original store name required';END IF;
    stores:=stores+1;IF stores>128 THEN RAISE EXCEPTION USING errcode='22023',message='store bounds';END IF;prior_store:=store_bytes;
   END IF;
  END IF;
  ordinal:=ordinal+1;
 END LOOP;
 ordinal:=0;prior:=0;
 FOR row IN SELECT value FROM jsonb_array_elements(manifest->'browser_records') LOOP
  IF NOT custodial_recovery.inventory_object_keys(row,ARRAY['ordinal','domain_ordinal','key_sha256','body_sha256','disposition','completion_readback'])
   OR row->'ordinal' IS DISTINCT FROM to_jsonb(ordinal)
   OR NOT custodial_recovery.inventory_count(row->'domain_ordinal',jsonb_array_length(manifest->'browser_domains')-1)
   OR coalesce(row->>'disposition','') NOT IN ('CURRENT_ACCEPTED_EXACT_ORIGINAL_NOT_ACK','UNRESOLVED_RETAINED')
   OR EXISTS(SELECT 1 FROM unnest(ARRAY['key_sha256','body_sha256']) k WHERE jsonb_typeof(row->k) IS DISTINCT FROM 'string' OR row->>k !~ '^[a-f0-9]{64}$') THEN
   RAISE EXCEPTION USING errcode='22023',message='closed original browser row required';END IF;
  idx:=(row->>'domain_ordinal')::integer;domain:=manifest->'browser_domains'->idx;
  IF idx<prior OR domain->'record_count'='null'::jsonb THEN RAISE EXCEPTION USING errcode='22023',message='declared original browser row order';END IF;
  domain_counts[idx+1]:=domain_counts[idx+1]+1;
  IF row->'completion_readback'<>'null'::jsonb AND (domain->>'store' IS DISTINCT FROM 'indexedDB'
   OR domain->>'database_utf16be_base64' IS DISTINCT FROM 'AG0AegBfAHMAYwBhAG4AXwBxAHUAZQB1AGU='
   OR domain->>'object_store_utf16be_base64' IS DISTINCT FROM 'AGEAYwB0AGkAbwBuAHM='
   OR (domain->>'version')::bigint NOT BETWEEN 1 AND 6) THEN
   RAISE EXCEPTION USING errcode='42501',message='only actual scan queue completion rows can be accepted';END IF;
  PERFORM custodial_recovery.inventory_completion_current(row->'completion_readback',row->>'disposition',target);
  IF row->>'disposition'='CURRENT_ACCEPTED_EXACT_ORIGINAL_NOT_ACK' THEN browser_accepted:=browser_accepted+1;END IF;
  prior:=idx;ordinal:=ordinal+1;
 END LOOP;
 FOR idx IN 1..array_length(domain_counts,1) LOOP
  IF domain_counts[idx]<>coalesce((manifest->'browser_domains'->(idx-1)->>'record_count')::integer,0) THEN
   RAISE EXCEPTION USING errcode='22023',message='complete original browser domain coverage required';END IF;
 END LOOP;
 IF manifest->'browser_accepted_exact_original_count' IS DISTINCT FROM to_jsonb(browser_accepted)
  OR manifest->'browser_unresolved_retained_count' IS DISTINCT FROM to_jsonb(ordinal-browser_accepted)
  OR manifest->>'browser_realm_name_encoding' IS DISTINCT FROM 'UTF16_CODE_UNITS_BE_BASE64' THEN
  RAISE EXCEPTION USING errcode='22023',message='complete original browser partitions required';END IF;
 frame:=manifest->'browser_value_frame';
 IF NOT custodial_recovery.inventory_object_keys(frame,ARRAY['schema','encoding','observation_sha256','frame_sha256',
   'byte_count','chunk_bytes','chunk_count','record_count','session_storage_state','chunk_sha256',
   'native_authority','durable_retention','inventory_acknowledged','finalizer_allowed','key_removal'])
  OR frame->>'schema' IS DISTINCT FROM 'custodial.browser-original-value-frame.v1' OR frame->>'encoding' IS DISTINCT FROM 'MZBRV001'
  OR EXISTS(SELECT 1 FROM unnest(ARRAY['observation_sha256','frame_sha256']) k WHERE jsonb_typeof(frame->k) IS DISTINCT FROM 'string' OR frame->>k !~ '^[a-f0-9]{64}$')
  OR NOT custodial_recovery.inventory_count(frame->'byte_count',67108864) OR (frame->>'byte_count')::bigint<56
  OR frame->'chunk_bytes' IS DISTINCT FROM '1048576'::jsonb OR frame->'record_count' IS DISTINCT FROM to_jsonb(ordinal)
  OR frame->'chunk_count' IS DISTINCT FROM to_jsonb(((frame->>'byte_count')::integer+1048575)/1048576)
  OR jsonb_typeof(frame->'chunk_sha256') IS DISTINCT FROM 'array'
  OR jsonb_array_length(frame->'chunk_sha256')<>(frame->>'chunk_count')::integer
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(frame->'chunk_sha256') v WHERE jsonb_typeof(v) IS DISTINCT FROM 'string' OR v#>>'{}' !~ '^[a-f0-9]{64}$')
  OR frame->'chunk_count'='1'::jsonb AND frame#>'{chunk_sha256,0}' IS DISTINCT FROM frame->'frame_sha256'
  OR frame->>'session_storage_state' IS DISTINCT FROM (CASE WHEN manifest#>'{browser_domains,1,record_count}'='null'::jsonb
    THEN 'NOT_DECLARED_UNKNOWN' ELSE 'CAPTURED_READ_ONLY_NOT_AUTHENTICATED' END)
  OR EXISTS(SELECT 1 FROM unnest(ARRAY['native_authority','durable_retention','inventory_acknowledged','finalizer_allowed','key_removal']) k
   WHERE frame->k IS DISTINCT FROM 'false'::jsonb) THEN
  RAISE EXCEPTION USING errcode='42501',message='exact retained original browser frame required';END IF;
 -- Reopen both current sources AFTER all potentially expensive exact reads.
 IF source#>'{expected_original}' IS DISTINCT FROM
   (custodial_recovery.read_original_inventory_manifest_for_manager(p_manager,p_credential,p_device,p_signed_expires,
     p_security_session,p_password_version,p_security_hash,p_csrf_hash,p_inventory_request))->'expected_original' THEN
  RAISE EXCEPTION USING errcode='42501',message='original inventory source changed during review';END IF;
 SELECT max(registered_at) INTO STRICT reviewed FROM public.custodial_native_inventory_manifest_chunks
  WHERE inventory_native_request_id=p_inventory_request;
 expiry:=least(reviewed+interval '5 minutes',(source->>'current_until')::timestamptz,
  custodial_recovery.assert_inventory_manager_read(p_manager,p_credential,p_device,p_signed_expires,
   p_security_session,p_password_version,p_security_hash,p_csrf_hash));
 IF clock_timestamp()>=expiry THEN RAISE EXCEPTION USING errcode='42501',message='original inventory review expired';END IF;
 SELECT display_name INTO STRICT employee_label FROM public.employees WHERE id=(target->>'employee_id')::uuid;
 IF nullif(btrim(employee_label),'') IS NULL OR length(employee_label)>200 THEN
  RAISE EXCEPTION USING errcode='42501',message='original human employee label unavailable';END IF;
 summary:=jsonb_build_object('declared_domains',jsonb_array_length(manifest->'browser_domains'),'record_count',ordinal,
  'accepted_exact_original_count',browser_accepted,'unresolved_retained_count',ordinal-browser_accepted,
  'frame_sha256',frame->>'frame_sha256','part_set_sha256',manifest->>'browser_part_set_sha256');
 review:=jsonb_build_object('schema','custodial.original-inventory-separation-review.v1',
  'state','COMPLETE_ORIGINAL_INVENTORY_REVIEW_ONLY','purpose','AUTHORIZE_EXACT_ORIGINAL_RETAINED_INVENTORY_SEPARATION',
  'native_request_id',p_inventory_request,'original_target',target,'original_employee_label',employee_label,
  'original_device_label',target->>'canonical_device_id','registration_receipt_sha256',source->>'original_registration_receipt_sha256',
  'inventory_manifest_sha256',source#>>'{expected_original,manifest_sha256}',
  'issuer',jsonb_build_object('manager_id',p_manager,'manager_credential_id',p_credential,'manager_device_id',p_device),
  'native_namespaces',manifest->'native_namespaces','browser_summary',summary,'retained_key_family_count',4,
  'reviewed_at',custodial_recovery.utc_micros(reviewed),'expires_at',custodial_recovery.utc_micros(expiry),
  'limits',custodial_recovery.denied_effects());
 -- Stable review identity binds the fixed original source and issuer. The
 -- bounded observation timestamps cannot renew/change an original decision.
 RETURN review||jsonb_build_object('review_sha256',encode(extensions.digest(convert_to(
  'custodial.original-inventory-separation-review.v1'||E'\n'||(review-'reviewed_at'-'expires_at')::text,'UTF8'),'sha256'),'hex'));
END $function$

CREATE OR REPLACE FUNCTION public.app_apply_event_command(p_command text, p_event_id uuid, p_record jsonb, p_actor text DEFAULT NULL::text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_command text:=nullif(btrim(coalesce(p_command,'')),''); v_record jsonb:=coalesce(p_record,'{}'::jsonb);
  v_row public.events_app_events%rowtype; v_previous jsonb; v_manager public.ops_manager_managers%rowtype;
  v_actor_manager_id uuid; v_actor text; v_reason text:=left(coalesce(nullif(btrim(p_reason),''),'Event updated from Event Input Console.'),1000);
  v_now timestamptz:=statement_timestamp();
begin
  if jsonb_typeof(v_record)<>'object' then raise exception using errcode='22023',message='event command record must be an object'; end if;
  begin v_actor_manager_id:=nullif(lower(btrim(coalesce(v_record->>'actor_manager_id',''))),'')::uuid;
  exception when others then raise exception using errcode='22023',message='authenticated manager UUID is required for event mutation'; end;
  select * into v_manager from public.ops_manager_managers m
  where m.manager_id=v_actor_manager_id and m.active=true and m.revoked_at is null and m.is_system_principal=false
    and m.roles && array['OPS_MANAGER','CUSTODIAL_MANAGER','DIRECTOR','SECURITY_ADMIN']::text[] for share;
  if v_manager.manager_id is null or nullif(btrim(v_manager.display_name),'') is null then
    raise exception using errcode='42501',message='an authorized active named manager principal is required for event mutation';
  end if;
  v_actor:=left(btrim(v_manager.display_name),200);
  if v_command='create' then
    if nullif(v_record->>'start_instant_utc','') is null or nullif(v_record->>'end_instant_utc','') is null then
      raise exception using errcode='22023',message='New event requires explicit Chicago start and end instants';
    end if;
    insert into public.events_app_events(
      event_name,location_group_id,event_scope,primary_venue_id,venue_ids,display_location,coverage_location_ids,staffing_area_ids,
      source_location_text,parser_confidence,needs_review,parse_reason,source_text,source_format,manually_overridden,overridden_by,
      overridden_at,event_timezone,operation_id,event_date,end_date,start_time,end_time,start_instant_utc,end_instant_utc,attendee_count,notes,custodial_note_codes,custodial_public_notes,created_by,
      created_by_manager_id,updated_by_manager_id,updated_at
    ) values(
      v_record->>'event_name',(v_record->>'location_group_id')::uuid,v_record->>'event_scope',nullif(v_record->>'primary_venue_id','')::uuid,
      coalesce(array(select jsonb_array_elements_text(coalesce(v_record->'venue_ids','[]'::jsonb)))::uuid[],'{}'::uuid[]),v_record->>'display_location',
      coalesce(array(select jsonb_array_elements_text(coalesce(v_record->'coverage_location_ids','[]'::jsonb)))::uuid[],'{}'::uuid[]),
      coalesce(array(select jsonb_array_elements_text(coalesce(v_record->'staffing_area_ids','[]'::jsonb)))::uuid[],'{}'::uuid[]),
      nullif(v_record->>'source_location_text',''),nullif(v_record->>'parser_confidence',''),coalesce((v_record->>'needs_review')::boolean,false),
      nullif(v_record->>'parse_reason',''),nullif(v_record->>'source_text',''),nullif(v_record->>'source_format',''),
      coalesce((v_record->>'manually_overridden')::boolean,false),case when coalesce((v_record->>'manually_overridden')::boolean,false) then v_actor end,
      case when coalesce((v_record->>'manually_overridden')::boolean,false) then v_now end,
      coalesce(nullif(v_record->>'event_timezone',''),'America/Chicago'),nullif(v_record->>'operation_id','')::uuid,(v_record->>'event_date')::date,
      (v_record->>'end_date')::date,(v_record->>'start_time')::time,(v_record->>'end_time')::time,(v_record->>'start_instant_utc')::timestamptz,(v_record->>'end_instant_utc')::timestamptz,nullif(v_record->>'attendee_count','')::integer,
      nullif(v_record->>'notes',''),coalesce(array(select distinct code from jsonb_array_elements_text(coalesce(v_record->'custodial_note_codes','[]'::jsonb)) code),'{}'::text[]),coalesce(v_record->>'custodial_public_notes',''),v_actor,v_actor_manager_id,
      case when coalesce((v_record->>'manually_overridden')::boolean,false) then v_actor_manager_id end,v_now
    ) on conflict(operation_id) where operation_id is not null do update set updated_at=public.events_app_events.updated_at
    returning * into v_row;
    return to_jsonb(v_row);
  elsif v_command='update' then
    select to_jsonb(e.*) into v_previous from public.events_app_events e where e.id=p_event_id for update;
    if v_previous is null then raise exception using errcode='P0002',message='event not found'; end if;
    if (nullif(v_record->>'start_instant_utc','') is null) <> (nullif(v_record->>'end_instant_utc','') is null) then
      raise exception using errcode='22023',message='Event start and end instants must be supplied together';
    end if;
    if nullif(v_record->>'start_instant_utc','') is null and (
      nullif(v_previous->>'start_instant_utc','') is not null
      or nullif(v_previous->>'end_instant_utc','') is not null
      or (v_previous->>'event_date')::date is distinct from (v_record->>'event_date')::date
      or (v_previous->>'end_date')::date is distinct from (v_record->>'end_date')::date
      or (v_previous->>'start_time')::time is distinct from (v_record->>'start_time')::time
      or (v_previous->>'end_time')::time is distinct from (v_record->>'end_time')::time
    ) then
      raise exception using errcode='22023',message='Changed event time requires explicit Chicago start and end instants';
    end if;
    update public.events_app_events set
      event_name=v_record->>'event_name',location_group_id=(v_record->>'location_group_id')::uuid,event_scope=v_record->>'event_scope',
      primary_venue_id=nullif(v_record->>'primary_venue_id','')::uuid,
      venue_ids=coalesce(array(select jsonb_array_elements_text(coalesce(v_record->'venue_ids','[]'::jsonb)))::uuid[],'{}'::uuid[]),
      display_location=v_record->>'display_location',
      coverage_location_ids=coalesce(array(select jsonb_array_elements_text(coalesce(v_record->'coverage_location_ids','[]'::jsonb)))::uuid[],'{}'::uuid[]),
      staffing_area_ids=coalesce(array(select jsonb_array_elements_text(coalesce(v_record->'staffing_area_ids','[]'::jsonb)))::uuid[],'{}'::uuid[]),
      source_location_text=nullif(v_record->>'source_location_text',''),parser_confidence=nullif(v_record->>'parser_confidence',''),
      needs_review=coalesce((v_record->>'needs_review')::boolean,false),parse_reason=nullif(v_record->>'parse_reason',''),
      source_text=nullif(v_record->>'source_text',''),source_format=nullif(v_record->>'source_format',''),manually_overridden=true,
      overridden_by=v_actor,overridden_at=v_now,updated_by_manager_id=v_actor_manager_id,
      event_timezone=coalesce(nullif(v_record->>'event_timezone',''),'America/Chicago'),event_date=(v_record->>'event_date')::date,
      end_date=(v_record->>'end_date')::date,start_time=(v_record->>'start_time')::time,end_time=(v_record->>'end_time')::time,start_instant_utc=(v_record->>'start_instant_utc')::timestamptz,end_instant_utc=(v_record->>'end_instant_utc')::timestamptz,
      attendee_count=nullif(v_record->>'attendee_count','')::integer,notes=nullif(v_record->>'notes',''),custodial_note_codes=coalesce(array(select distinct code from jsonb_array_elements_text(coalesce(v_record->'custodial_note_codes','[]'::jsonb)) code),'{}'::text[]),custodial_public_notes=coalesce(v_record->>'custodial_public_notes',''),revision=coalesce(revision,1)+1,updated_at=v_now
    where id=p_event_id returning * into v_row;
    insert into public.events_app_event_history(event_id,action,actor,actor_manager_id,reason,previous_record,new_record,created_at)
    values(v_row.id,'update',v_actor,v_actor_manager_id,v_reason,v_previous,to_jsonb(v_row),v_now);
    return to_jsonb(v_row);
  elsif v_command='cancel' then
    raise exception using errcode='22023',message='event cancellation requires expected revision and operation id';
    select to_jsonb(e.*) into v_previous from public.events_app_events e where e.id=p_event_id for update;
    if v_previous is null then raise exception using errcode='P0002',message='event not found'; end if;
    update public.events_app_events set status='CANCELLED',cancelled_at=coalesce(cancelled_at,v_now),cancelled_by=v_actor,
      cancelled_by_manager_id=v_actor_manager_id,cancellation_reason=v_reason,overridden_by=v_actor,overridden_at=v_now,
      updated_by_manager_id=v_actor_manager_id,revision=coalesce(revision,1)+1,updated_at=v_now
    where id=p_event_id returning * into v_row;
    insert into public.events_app_event_history(event_id,action,actor,actor_manager_id,reason,previous_record,new_record,created_at)
    values(v_row.id,'cancel',v_actor,v_actor_manager_id,v_reason,v_previous,to_jsonb(v_row),v_now);
    return to_jsonb(v_row);
  end if;
  raise exception using errcode='22023',message='unsupported bounded event command';
end
$function$

CREATE OR REPLACE FUNCTION public.app_apply_event_update_cas(p_event_id uuid, p_record jsonb, p_actor text DEFAULT NULL::text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_expected_revision bigint;
  v_current_revision bigint;
begin
  if p_event_id is null or jsonb_typeof(p_record) is distinct from 'object' then
    raise exception using errcode='22023',message='event id and update record are required';
  end if;
  if jsonb_typeof(p_record->'expected_revision') is distinct from 'number'
    or p_record->>'expected_revision' !~ '^[1-9][0-9]*$' then
    raise exception using errcode='22023',message='expected event revision is required';
  end if;
  begin
    v_expected_revision := (p_record->>'expected_revision')::bigint;
  exception when numeric_value_out_of_range then
    raise exception using errcode='22023',message='expected event revision is invalid';
  end;
  select coalesce(e.revision,1) into v_current_revision
    from public.events_app_events e where e.id=p_event_id for update;
  if not found then
    raise exception using errcode='P0002',message='event not found';
  end if;
  if v_current_revision is distinct from v_expected_revision then
    raise exception using errcode='40901',message='Event changed since this preview. Refresh and review before saving.';
  end if;
  return public.app_apply_event_command('update',p_event_id,p_record,p_actor,p_reason);
end
$function$

CREATE OR REPLACE FUNCTION public.app_apply_operational_command(p_command text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_command text := nullif(btrim(coalesce(p_command, '')), '');
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_id uuid;
  v_original_kind text;
  v_query_only boolean;
  v_original_payload jsonb;
  v_current jsonb;
  v_original_fingerprint text;
  v_original_result jsonb;
  v_original_outcome jsonb;
  v_original_target text;
  v_allowed text[];
begin
  if jsonb_typeof(v_payload) <> 'object' then
    raise exception using errcode='22023', message='operational command payload must be an object';
  end if;

  -- Only the EXISTING service-only dispatcher may reach this closed family.
  -- Payload selectors are not authentication; the normal HTTP credential
  -- boundary precedes this RPC. Current DB owner identity is locked here too.
  if v_command in ('employee_message_original_send','employee_message_original_read',
      'employee_message_original_delete','employee_message_original_outcome') then
    v_query_only:=v_command='employee_message_original_outcome';
    v_original_kind:=case when v_query_only then v_payload->>'original_command' else v_command end;
    if v_original_kind not in ('employee_message_original_send','employee_message_original_read','employee_message_original_delete')
      or v_original_kind is null then raise exception using errcode='22023',message='Unknown original Messenger command'; end if;
    v_original_payload:=case when v_query_only then v_payload-'original_command' else v_payload end;
    v_allowed:=array['device_id','expected_employee_id','expected_credential_id','expected_assignment_epoch',
      'user_id','thread_id','credential_token_hash'];
    v_allowed:=v_allowed||case v_original_kind
      when 'employee_message_original_send' then array['body','message_type','metadata_json','client_message_id']
      when 'employee_message_original_read' then array['through_message_id']
      else array['operation_id'] end;
    if (select array_agg(k order by k) from jsonb_object_keys(v_original_payload) k)
        is distinct from (select array_agg(k order by k) from unnest(v_allowed) k)
      or octet_length(v_original_payload::text)>32768
      or jsonb_typeof(v_original_payload->'device_id') is distinct from 'string'
      or v_original_payload->>'device_id' !~ '^[A-Z0-9_-]{1,64}$'
      or jsonb_typeof(v_original_payload->'expected_assignment_epoch') is distinct from 'string'
      or v_original_payload->>'expected_assignment_epoch' !~ '^[1-9][0-9]{0,15}$'
      or (v_original_payload->>'expected_assignment_epoch')::numeric>9007199254740991
      or jsonb_typeof(v_original_payload->'credential_token_hash') is distinct from 'string'
      or v_original_payload->>'credential_token_hash' !~ '^[a-f0-9]{64}$'
      then raise exception using errcode='22023',message='Closed original Messenger request required'; end if;
    foreach v_original_target in array array['expected_employee_id','expected_credential_id','user_id','thread_id'] loop
      if jsonb_typeof(v_original_payload->v_original_target) is distinct from 'string'
        or v_original_payload->>v_original_target !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'
        then raise exception using errcode='22023',message='Canonical original Messenger identity required'; end if;
    end loop;
    if not v_query_only then
      -- No HTTP/provider call occurs while these short DB locks are held.
      -- Updates to assignment, credential revocation, employee or sender block.
      perform d.id from public.devices d join public.device_auth_credentials c on c.device_id=d.id
        join public.employees e on e.id=d.assigned_employee_id join public.msg_users u on u.employee_id=e.id
        join public.msg_device_assignments mda on mda.device_identifier=d.device_id and mda.msg_user_id=u.id and mda.is_active
        where d.device_id=v_original_payload->>'device_id' and d.active and e.active and u.is_active and u.role='employee'
          and d.assigned_employee_id=(v_original_payload->>'expected_employee_id')::uuid
          and d.assignment_epoch=(v_original_payload->>'expected_assignment_epoch')::bigint
          and c.credential_id=(v_original_payload->>'expected_credential_id')::uuid
          and c.token_hash=v_original_payload->>'credential_token_hash'
          and c.confirmed_at is not null and c.revoked_at is null and c.expires_at>clock_timestamp()
          and u.id=(v_original_payload->>'user_id')::uuid
        for update of d,c,e,u,mda;
      if not found then raise exception using errcode='42501',message='Original Messenger actor is no longer current'; end if;
    end if;
    select jsonb_build_object('device_pk',d.id,'device_id',d.device_id,'employee_id',e.id,
        'credential_id',c.credential_id,'assignment_epoch',d.assignment_epoch::text,'user_id',u.id)
      into v_current
      from public.devices d join public.device_auth_credentials c on c.device_id=d.id
      join public.employees e on e.id=d.assigned_employee_id join public.msg_users u on u.employee_id=e.id
      join public.msg_device_assignments mda on mda.device_identifier=d.device_id and mda.msg_user_id=u.id and mda.is_active
      where d.device_id=v_original_payload->>'device_id' and d.active and e.active and u.is_active and u.role='employee'
        and d.assigned_employee_id=(v_original_payload->>'expected_employee_id')::uuid
        and d.assignment_epoch=(v_original_payload->>'expected_assignment_epoch')::bigint
        and c.credential_id=(v_original_payload->>'expected_credential_id')::uuid
        and c.token_hash=v_original_payload->>'credential_token_hash'
        and c.confirmed_at is not null and c.revoked_at is null and c.expires_at>clock_timestamp()
        and u.id=(v_original_payload->>'user_id')::uuid;
    if v_current is null then raise exception using errcode='42501',message='Original Messenger actor is no longer current'; end if;
    v_original_fingerprint:=public.static_weekly_digest_text(v_original_kind||E'\n'||v_original_payload::text);
    if not v_query_only then perform pg_advisory_xact_lock(hashtextextended(v_original_fingerprint,0)); end if;
    select outcome_json into v_original_outcome from custodial_release_identity.employee_message_original_outcomes
      where request_fingerprint=v_original_fingerprint and original_command=v_original_kind
        and original_request=v_original_payload;
    if v_original_outcome is not null then return v_original_outcome; end if;
    if v_query_only then return jsonb_build_object('schema','custodial.employee-original-message-outcome.v1',
      'state','ORIGINAL_OUTCOME_NOT_FOUND_UNKNOWN','request_fingerprint',v_original_fingerprint,
      'original_command',v_original_kind,'original_actor',v_current,'original_outcome_recorded',false,
      'resend_allowed',false,'inventory_acknowledged',false,'finalizer_allowed',false,'key_removal',false); end if;
    if v_original_kind='employee_message_original_send' then
      if jsonb_typeof(v_original_payload->'body') is distinct from 'string'
        or jsonb_typeof(v_original_payload->'message_type') is distinct from 'string'
        or v_original_payload->>'message_type'<>'text'
        or jsonb_typeof(v_original_payload->'metadata_json') is distinct from 'object'
        or jsonb_typeof(v_original_payload->'client_message_id') is distinct from 'string'
        or length(v_original_payload->>'client_message_id') not between 1 and 200
        then raise exception using errcode='22023',message='Exact original send body required'; end if;
      v_original_result:=to_jsonb(public.msg_send_message((v_original_payload->>'thread_id')::uuid,
        (v_original_payload->>'user_id')::uuid,v_original_payload->>'body','text',
        v_original_payload->'metadata_json',v_original_payload->>'client_message_id'));
    elsif v_original_kind='employee_message_original_read' then
      if jsonb_typeof(v_original_payload->'through_message_id') is distinct from 'string'
        or v_original_payload->>'through_message_id' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'
        then raise exception using errcode='22023',message='Original read horizon required'; end if;
      v_original_result:=jsonb_build_object('marked',public.msg_mark_thread_read_through(
        (v_original_payload->>'thread_id')::uuid,(v_original_payload->>'user_id')::uuid,
        (v_original_payload->>'through_message_id')::uuid),
        'thread_id',v_original_payload->>'thread_id','user_id',v_original_payload->>'user_id',
        'through_message_id',v_original_payload->>'through_message_id');
    else
      if jsonb_typeof(v_original_payload->'operation_id') is distinct from 'string'
        or v_original_payload->>'operation_id' !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'
        then raise exception using errcode='22023',message='Original deletion operation required'; end if;
      v_original_result:=public.msg_delete_thread((v_original_payload->>'thread_id')::uuid,
        (v_original_payload->>'user_id')::uuid,(v_original_payload->>'operation_id')::uuid);
      if v_original_result->'ok' is distinct from 'true'::jsonb or v_original_result->'deleted' is distinct from 'true'::jsonb
        or v_original_result->>'thread_id'<>v_original_payload->>'thread_id'
        or v_original_result->>'operation_id'<>v_original_payload->>'operation_id'
        or v_original_result->>'deletion_scope'<>'user'
        then raise exception using errcode='22023',message='Original deletion was not confirmed'; end if;
    end if;
    if not exists(select 1 from public.device_auth_credentials c
      where c.credential_id=(v_original_payload->>'expected_credential_id')::uuid
        and c.revoked_at is null and c.expires_at>clock_timestamp()
        and c.token_hash=v_original_payload->>'credential_token_hash') then
      -- Any effect from the nested RPC rolls back in this same transaction.
      raise exception using errcode='42501',message='Original Messenger credential expired before its outcome';
    end if;
    v_original_outcome:=jsonb_build_object('schema','custodial.employee-original-message-outcome.v1',
      'state','ORIGINAL_TRANSACTION_OUTCOME_RECORDED','request_fingerprint',v_original_fingerprint,
      'original_command',v_original_kind,'original_actor',v_current,'original_outcome_recorded',true,
      'original_request',v_original_payload-'credential_token_hash','result',v_original_result,
      'recorded_at',statement_timestamp(),'inventory_acknowledged',false,'finalizer_allowed',false,'key_removal',false);
    insert into custodial_release_identity.employee_message_original_outcomes
      (request_fingerprint,original_command,original_request,outcome_json)
      values(v_original_fingerprint,v_original_kind,v_original_payload,v_original_outcome);
    return v_original_outcome;
  end if;

  if v_command = 'public_rate_limit' then
    if coalesce(v_payload->>'bucket_key','') !~ '^[0-9a-f]{64}$' or length(coalesce(v_payload->>'scope','')) not between 1 and 80 then
      raise exception using errcode='22023', message='bounded rate-limit key and scope are required';
    end if;
    insert into public.public_submission_rate_limits(bucket_key,scope,window_started_at,request_count,updated_at)
    values(v_payload->>'bucket_key',v_payload->>'scope',now(),1,now())
    on conflict(bucket_key) do update set
      scope=excluded.scope,
      window_started_at=case when public.public_submission_rate_limits.window_started_at <= now()-interval '60 seconds' then now() else public.public_submission_rate_limits.window_started_at end,
      request_count=case when public.public_submission_rate_limits.window_started_at <= now()-interval '60 seconds' then 1 else public.public_submission_rate_limits.request_count+1 end,
      updated_at=now();
    return jsonb_build_object('ok',true);
  elsif v_command = 'attendance_state_upsert' then
    if nullif(v_payload->>'fetched_at','') is null or not isfinite((v_payload->>'fetched_at')::timestamptz) then
      raise exception using errcode='22023',message='visitor observation requires a finite source timestamp';
    end if;
    if (v_payload->>'fetched_at')::timestamptz < statement_timestamp()-interval '1 hour'
      or (v_payload->>'fetched_at')::timestamptz > statement_timestamp()+interval '60 seconds' then
      raise exception using errcode='22023',message='visitor observation requires a current source timestamp';
    end if;
    insert into public.current_attendance_state(id,attendance,last_year,planned,yesterday,yesterday_plan,source,fetched_at,updated_at)
    values(1,(v_payload->>'attendance')::integer,nullif(v_payload->>'last_year','')::integer,nullif(v_payload->>'planned','')::integer,
      nullif(v_payload->>'yesterday','')::integer,nullif(v_payload->>'yesterday_plan','')::integer,nullif(v_payload->>'source',''),
      nullif(v_payload->>'fetched_at','')::timestamptz,now())
    on conflict(id) do update set attendance=excluded.attendance,last_year=excluded.last_year,planned=excluded.planned,
      yesterday=excluded.yesterday,yesterday_plan=excluded.yesterday_plan,source=excluded.source,fetched_at=excluded.fetched_at,updated_at=now()
    where public.current_attendance_state.fetched_at is null
      or not isfinite(public.current_attendance_state.fetched_at)
      -- The conflicting row may have committed after this statement began.
      -- Classify poison when that row is considered, not with a stale start time.
      or public.current_attendance_state.fetched_at>clock_timestamp()+interval '60 seconds'
      or excluded.fetched_at>public.current_attendance_state.fetched_at
      or (excluded.fetched_at=public.current_attendance_state.fetched_at
        and row(excluded.attendance,excluded.last_year,excluded.planned,excluded.yesterday,excluded.yesterday_plan,excluded.source)
          is not distinct from row(public.current_attendance_state.attendance,public.current_attendance_state.last_year,
            public.current_attendance_state.planned,public.current_attendance_state.yesterday,
            public.current_attendance_state.yesterday_plan,public.current_attendance_state.source));
    if not found then
      raise exception using errcode='23514',message='visitor observation is older than or conflicts with the saved source version';
    end if;
    return jsonb_build_object('ok',true);
  elsif v_command = 'guest_report_create' then
    insert into public.guest_cleanliness_reports(
      id,operation_id,request_fingerprint,location_code,location_name,issue_type,severity,notes,status,marketing_review_status,notification_status,metadata_json
    ) values(
      (v_payload->>'id')::uuid,(v_payload->>'operation_id')::uuid,v_payload->>'request_fingerprint',v_payload->>'location_code',
      nullif(v_payload->>'location_name',''),v_payload->>'issue_type',v_payload->>'severity',nullif(v_payload->>'notes',''),
      'pending_marketing_review','pending','awaiting_marketing_review',coalesce(v_payload->'metadata_json','{}'::jsonb)
    ) on conflict(operation_id) do nothing;
    return jsonb_build_object('ok',true);
  elsif v_command = 'guest_report_notification' then
    update public.guest_cleanliness_reports set
      notification_status=v_payload->>'notification_status', notified_employee_user_id=nullif(v_payload->>'notified_employee_user_id','')::uuid,
      notified_ops_count=coalesce((v_payload->>'notified_ops_count')::integer,0),
      dispatched_at=case when coalesce((v_payload->>'delivered_count')::integer,0)>0 then now() else dispatched_at end,
      metadata_json=coalesce(metadata_json,'{}'::jsonb)||jsonb_build_object('notification_errors',coalesce(v_payload->'notification_errors','[]'::jsonb))
    where id=(v_payload->>'id')::uuid;
    return jsonb_build_object('ok',true);
  elsif v_command = 'guest_report_review' then
    if v_payload->>'action' = 'approve' then
      update public.guest_cleanliness_reports set marketing_review_status='approved',marketing_reviewed_at=now(),
        marketing_reviewed_by=v_payload->>'actor',marketing_review_notes=nullif(v_payload->>'notes',''),status='open',notification_status='pending'
      where id=(v_payload->>'id')::uuid and status='pending_marketing_review' and marketing_review_status='pending';
      insert into public.operational_notification_jobs(job_key,job_type,source_id,payload_json)
      select 'guest-report:'||id::text,'guest_cleanliness_report',id,jsonb_build_object('operation_id',operation_id,'marketing_approved',true)
      from public.guest_cleanliness_reports where id=(v_payload->>'id')::uuid and status='open' and marketing_review_status='approved'
      on conflict(job_key) do nothing;
    elsif v_payload->>'action' = 'reject' then
      update public.guest_cleanliness_reports set marketing_review_status='rejected',marketing_reviewed_at=now(),
        marketing_reviewed_by=v_payload->>'actor',marketing_review_notes=nullif(v_payload->>'notes',''),status='rejected',resolved_at=now(),
        resolved_by=v_payload->>'actor',notification_status='not_dispatched'
      where id=(v_payload->>'id')::uuid and status='pending_marketing_review' and marketing_review_status='pending';
    else
      raise exception using errcode='22023', message='guest report review action is unsupported';
    end if;
    return jsonb_build_object('ok',true);
  elsif v_command = 'guest_report_resolve' then
    update public.guest_cleanliness_reports set status='resolved',resolved_at=now(),resolved_by=v_payload->>'actor',
      metadata_json=coalesce(metadata_json,'{}'::jsonb)||jsonb_build_object('resolution_notes',nullif(v_payload->>'notes',''))
    where id=(v_payload->>'id')::uuid and status='open' and marketing_review_status='approved';
    return jsonb_build_object('ok',true);
  elsif v_command = 'feedback_legacy_image_migration' then
    update public.system_feedback_items set metadata_json=coalesce(v_payload->'metadata_json','{}'::jsonb),updated_at=now()
    where id=(v_payload->>'id')::uuid and metadata_json->'image_attachment'->>'data_url' is not null;
    update public.system_feedback_legacy_image_backups set migrated_at=now(),storage_bucket=v_payload->>'storage_bucket',storage_path=v_payload->>'storage_path'
    where feedback_id=(v_payload->>'id')::uuid;
    return jsonb_build_object('ok',true);
  elsif v_command = 'feedback_create' then
    insert into public.system_feedback_items(id,operation_id,request_fingerprint,category,priority,message,submitted_by,hub_context,device_id,page_url,summary,metadata_json)
    values((v_payload->>'id')::uuid,(v_payload->>'operation_id')::uuid,v_payload->>'request_fingerprint',v_payload->>'category',
      v_payload->>'priority',v_payload->>'message',nullif(v_payload->>'submitted_by',''),v_payload->>'hub_context',nullif(v_payload->>'device_id',''),
      nullif(v_payload->>'page_url',''),v_payload->>'summary',coalesce(v_payload->'metadata_json','{}'::jsonb))
    on conflict(operation_id) do nothing;
    return jsonb_build_object('ok',true);
  elsif v_command = 'feedback_notification' then
    update public.system_feedback_items set notification_status=v_payload->>'notification_status',
      notified_ops_count=coalesce(notified_ops_count,0)+coalesce((v_payload->>'notified_ops_count')::integer,0),last_feedback_reminder_at=now(),
      feedback_reminder_count=coalesce(feedback_reminder_count,0)+coalesce((v_payload->>'reminder_increment')::integer,0),updated_at=now(),
      metadata_json=coalesce(metadata_json,'{}'::jsonb)||jsonb_build_object('notification_errors',coalesce(v_payload->'notification_errors','[]'::jsonb))
    where id=(v_payload->>'id')::uuid;
    return jsonb_build_object('ok',true);
  elsif v_command = 'feedback_status' then
    update public.system_feedback_items set status=v_payload->>'status',
      acknowledged_at=case when v_payload->>'status'='acknowledged' then now() else acknowledged_at end,
      acknowledged_by=case when v_payload->>'status'='acknowledged' then v_payload->>'actor' else acknowledged_by end,
      updated_at=now(),metadata_json=coalesce(metadata_json,'{}'::jsonb)||coalesce(v_payload->'metadata_patch','{}'::jsonb)
    where id=(v_payload->>'id')::uuid and status not in ('closed','resolved');
    return jsonb_build_object('ok',true);
  elsif v_command = 'feedback_reminder_exhausted' then
    update public.system_feedback_items set status='reminder_exhausted',updated_at=now(),
      metadata_json=coalesce(metadata_json,'{}'::jsonb)||jsonb_build_object('reminder_exhausted_reason',v_payload->>'reason')
    where id=(v_payload->>'id')::uuid and status not in ('acknowledged','resolved','closed');
    return jsonb_build_object('ok',true);
  elsif v_command = 'feedback_dashboard_only' then
    update public.system_feedback_items set notification_status='dashboard_only',notified_ops_count=0,updated_at=now(),
      metadata_json=coalesce(metadata_json,'{}'::jsonb)||jsonb_build_object('notification_delivery','dashboard_only')
    where id=(v_payload->>'id')::uuid;
    return jsonb_build_object('ok',true);
  end if;
  raise exception using errcode='22023', message='unsupported bounded operational command';
end
$function$

CREATE OR REPLACE FUNCTION public.app_apply_schedule_command(p_command text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_command text := nullif(btrim(coalesce(p_command, '')), '');
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_item jsonb;
  v_rows jsonb := '[]'::jsonb;
  v_date date;
  v_assignment public.daily_schedule_assignments%rowtype;
begin
  if jsonb_typeof(v_payload) <> 'object' then raise exception using errcode='22023', message='schedule command payload must be an object'; end if;
  if v_command = 'sch2_guarded_publish' then
    return public.sch2_publish_solution((v_payload->>'run_id')::uuid, true);
  elsif v_command = 'coverall_assignment_link_issue' then
    update public.coverall_assignment_links set revoked_at=now(),revoked_by=left(v_payload->>'created_by',160)
    where service_date=(v_payload->>'service_date')::date and slot_code=v_payload->>'slot_code' and revoked_at is null;
    insert into public.coverall_assignment_links(id,token_hash,service_date,slot_code,created_by,expires_at)
    values((v_payload->>'id')::uuid,v_payload->>'token_hash',(v_payload->>'service_date')::date,v_payload->>'slot_code',left(v_payload->>'created_by',160),(v_payload->>'expires_at')::timestamptz)
    returning to_jsonb(coverall_assignment_links) into v_rows;
    return v_rows;
  elsif v_command = 'coverall_assignment_link_revoke' then
    with updated as (
      update public.coverall_assignment_links set revoked_at=now(),revoked_by=left(v_payload->>'revoked_by',160)
      where service_date=(v_payload->>'service_date')::date and slot_code=v_payload->>'slot_code' and revoked_at is null
      returning id
    ) select coalesce(jsonb_agg(to_jsonb(updated)),'[]'::jsonb) into v_rows from updated;
    return v_rows;
  elsif v_command = 'coverall_slots_publish' then
    v_date := (v_payload->>'service_date')::date;
    for v_item in select value from jsonb_array_elements(coalesce(v_payload->'operations','[]'::jsonb)) loop
      if coalesce((v_item->>'active')::boolean,false) then
        insert into public.daily_work_roster(service_date,employee_id,shift_start,shift_end,source_type,notes,active)
        values(v_date,(v_item->>'employee_id')::uuid,(v_item->>'shift_start')::time,(v_item->>'shift_end')::time,'coverall_manual',nullif(v_item->>'notes',''),true)
        on conflict(service_date,employee_id) do update set shift_start=excluded.shift_start,shift_end=excluded.shift_end,
          source_type=excluded.source_type,notes=excluded.notes,active=true,updated_at=now();
      else
        update public.daily_work_roster set active=false,updated_at=now(),
          notes=trim(concat_ws(' ',nullif(notes,''),'CoverAll slot removed from scheduler.'))
        where service_date=v_date and employee_id=(v_item->>'employee_id')::uuid;
      end if;
    end loop;
    return jsonb_build_object('ok',true);
  elsif v_command = 'coverall_load_balance' then
    v_date := (v_payload->>'service_date')::date;
    for v_item in select value from jsonb_array_elements(coalesce(v_payload->'moves','[]'::jsonb)) loop
      update public.daily_schedule_assignments set assigned_employee_id=(v_item->>'to_employee_id')::uuid,owner_type='EMPLOYEE',status='ASSIGNED',
        source_type='coverall_manual_balance',notes=trim(concat_ws(' ',nullif(notes,''),'Balanced to '||coalesce(v_item->>'to_employee_name','CoverAll')||' from '||coalesce(v_item->>'from_employee_name','previous owner')||' for extra CoverAll help.')),
        updated_at=now()
      where id=(v_item->>'assignment_id')::uuid and service_date=v_date;
    end loop;
    return jsonb_build_object('ok',true);
  elsif v_command = 'restroom_rebalance_0945' then
    v_date := (v_payload->>'service_date')::date;
    perform pg_advisory_xact_lock(hashtextextended(coalesce(v_payload->>'source','restroom_rebalance_0945')||':'||v_date::text,0));
    for v_item in select value from jsonb_array_elements(coalesce(v_payload->'moves','[]'::jsonb)) loop
      update public.daily_schedule_assignments dsa set assigned_employee_id=(v_item->>'to_employee_id')::uuid,owner_type='EMPLOYEE',status='ASSIGNED',
        source_type=coalesce(v_payload->>'source','restroom_rebalance_0945'),
        notes=trim(concat_ws(' ',nullif(dsa.notes,''),coalesce(v_payload->>'note','Restroom rebalance.')||' From '||coalesce(v_item->>'from_employee_name','previous owner')||' to '||coalesce(v_item->>'to_employee_name','new owner')||'.')),
        updated_at=now()
      where dsa.id=(v_item->>'assignment_id')::uuid and dsa.service_date=v_date and dsa.status='ASSIGNED' and dsa.owner_type='EMPLOYEE'
        and dsa.assigned_employee_id=(v_item->>'from_employee_id')::uuid and coalesce(dsa.coverage_purpose,'')<>'lunch_coverage'
        and coalesce(dsa.source_type,'') not ilike '%manual%' and coalesce(dsa.source_type,'') not ilike '%override%' and coalesce(dsa.source_type,'') not ilike '%manager%'
        and exists(select 1 from public.daily_work_roster r where r.service_date=dsa.service_date and r.employee_id=(v_item->>'to_employee_id')::uuid and r.active=true and r.shift_start<=dsa.coverage_start and r.shift_end>=dsa.coverage_end)
        and not public.sch_is_employee_location_group_restricted((v_item->>'to_employee_id')::uuid,dsa.location_group_id,extract(dow from dsa.service_date)::integer)
      returning * into v_assignment;
      if v_assignment.id is not null then
        v_rows := v_rows || jsonb_build_array(jsonb_build_object('assignment_id',v_assignment.id,'assigned_employee_id',v_assignment.assigned_employee_id,'status',v_assignment.status,'owner_type',v_assignment.owner_type,'source_type',v_assignment.source_type));
      end if;
    end loop;
    return v_rows;
  elsif v_command = 'restroom_rebalance_completion' then
    insert into public.schedule_automation_runs(automation_key,service_date,status,result_json,updated_at)
    values(coalesce(v_payload->>'automation_key','restroom_rebalance_0945'),(v_payload->>'service_date')::date,v_payload->>'status',coalesce(v_payload->'result','{}'::jsonb),now())
    on conflict(automation_key,service_date) do update set status=excluded.status,result_json=excluded.result_json,updated_at=now();
    return jsonb_build_object('ok',true);
  elsif v_command = 'coverall_assignment_apply' then
    v_date := (v_payload->>'service_date')::date;
    if jsonb_array_length(coalesce(v_payload->'assignments','[]'::jsonb)) = 0 then return jsonb_build_object('ok',true); end if;
    insert into public.daily_work_roster(service_date,employee_id,shift_start,shift_end,source_type,notes,active,created_at,updated_at)
    select v_date,(v_payload->>'employee_id')::uuid,min((x->>'coverage_start')::time),max((x->>'coverage_end')::time),'coverall',
      'Call CoverAll: 3+ custodial absences detected. CoverAll fills the 3rd and later absence workload.',true,now(),now()
    from jsonb_array_elements(v_payload->'assignments') x
    on conflict(service_date,employee_id) do update set shift_start=least(public.daily_work_roster.shift_start,excluded.shift_start),
      shift_end=greatest(public.daily_work_roster.shift_end,excluded.shift_end),active=true,updated_at=now(),notes=excluded.notes;
    for v_item in select value from jsonb_array_elements(v_payload->'assignments') loop
      update public.daily_schedule_assignments set assigned_employee_id=(v_payload->>'employee_id')::uuid,owner_type='EMPLOYEE',status='ASSIGNED',source_type='coverall_escalation',
        notes=trim(concat_ws(' ',nullif(notes,''),'Call CoverAll: assigned due to 3+ custodial absences.')),updated_at=now()
      where service_date=v_date and location_group_id=(v_item->>'location_group_id')::uuid and coverage_start=(v_item->>'coverage_start')::time and coverage_end=(v_item->>'coverage_end')::time;
    end loop;
    return jsonb_build_object('ok',true);
  elsif v_command = 'pto_import' then
    for v_item in select value from jsonb_array_elements(coalesce(v_payload->'rows','[]'::jsonb)) loop
      insert into public.employee_planned_time_off(employee_id,start_date,end_date,pto_type,source,notes,active)
      values((v_item->>'employee_id')::uuid,(v_item->>'start_date')::date,(v_item->>'end_date')::date,v_item->>'pto_type',v_item->>'source',nullif(v_item->>'notes',''),true)
      on conflict(employee_id,start_date,end_date,pto_type,source) do update set notes=excluded.notes,active=true,updated_at=now();
    end loop;
    return jsonb_build_object('ok',true);
  elsif v_command = 'restore_static_schedule_owners' then
    v_date := (v_payload->>'service_date')::date;
    update public.daily_schedule_assignments dsa set assigned_employee_id=ct.assigned_employee_id,owner_type='EMPLOYEE',status='ASSIGNED',
      source_type=case when dsa.source_type is null or dsa.source_type='' then 'coverage_template_static_owner' when dsa.source_type like '%static_owner%' then dsa.source_type else dsa.source_type||':static_owner_restored' end,
      notes=trim(concat_ws(' | ',nullif(dsa.notes,''),'Static owner restored because owner is working and not absent.')),updated_at=now()
    from public.coverage_templates ct join public.daily_work_roster dwr on dwr.service_date=v_date and dwr.employee_id=ct.assigned_employee_id and dwr.active=true
    where dsa.service_date=v_date and dwr.shift_start<=dsa.coverage_start and dwr.shift_end>=least(dsa.coverage_end,public.sch_get_schedule_close_time(v_date))
      and ct.active=true and ct.day_of_week=extract(dow from v_date)::integer and ct.location_group_id=dsa.location_group_id and ct.segment_number=dsa.segment_number
      and ct.coverage_start=dsa.coverage_start and least(ct.coverage_end,public.sch_get_schedule_close_time(v_date))=dsa.coverage_end
      and coalesce(ct.coverage_purpose,'area_owner')=coalesce(dsa.coverage_purpose,'area_owner') and coalesce(dsa.coverage_purpose,'')<>'lunch_coverage'
      and coalesce(dsa.source_type,'') not ilike '%lunch%' and ct.assigned_employee_id is not null
      and not public.sch_is_employee_location_group_restricted(ct.assigned_employee_id,ct.location_group_id,extract(dow from v_date)::integer)
      and not exists(select 1 from public.daily_absence_overrides dao where dao.absence_date=v_date and dao.employee_id=ct.assigned_employee_id and dao.active=true
                     union all select 1 from public.employee_planned_time_off pto where pto.start_date<=v_date and pto.end_date>=v_date and pto.employee_id=ct.assigned_employee_id and pto.active=true
                     union all select 1 from public.employee_pto ep where ep.start_date<=v_date and ep.end_date>=v_date and ep.employee_id=ct.assigned_employee_id and ep.active=true)
      and coalesce(dsa.source_type,'') not like 'coverall%' and coalesce(dsa.source_type,'') not ilike '%manual%' and coalesce(dsa.source_type,'') not ilike '%override%' and coalesce(dsa.source_type,'') not ilike '%manager%';
    return jsonb_build_object('ok',true);
  elsif v_command = 'manual_absence_publish' then
    v_date := (v_payload->>'service_date')::date;
    update public.daily_absence_overrides dao set active=dao.employee_id=any(coalesce(array(select jsonb_array_elements_text(coalesce(v_payload->'employee_ids','[]'::jsonb)))::uuid[],'{}'::uuid[])),updated_at=now(),
      notes=case when dao.employee_id=any(coalesce(array(select jsonb_array_elements_text(coalesce(v_payload->'employee_ids','[]'::jsonb)))::uuid[],'{}'::uuid[])) then 'Published from simplified absence scheduler' else coalesce(dao.notes,'Cleared by simplified absence scheduler') end
    where dao.absence_date=v_date and dao.absence_type='manual_override';
    insert into public.daily_absence_overrides(id,absence_date,employee_id,absence_type,active,notes,created_at,updated_at)
    select gen_random_uuid(),v_date,(x.value)::uuid,'manual_override',true,'Published from simplified absence scheduler',now(),now()
    from jsonb_array_elements_text(coalesce(v_payload->'employee_ids','[]'::jsonb)) x
    where not exists(select 1 from public.daily_absence_overrides y where y.absence_date=v_date and y.employee_id=(x.value)::uuid);
    return jsonb_build_object('ok',true);
  elsif v_command = 'manual_absence_return' then
    update public.daily_absence_overrides set active=false,updated_at=now(),notes=trim(concat_ws(' ',nullif(notes,''),'Cleared: employee returned to schedule.'))
    where absence_date=(v_payload->>'service_date')::date and employee_id=(v_payload->>'employee_id')::uuid and absence_type='manual_override' and active=true;
    return jsonb_build_object('ok',true);
  end if;
  raise exception using errcode='22023', message='unsupported bounded schedule command';
end
$function$

CREATE OR REPLACE FUNCTION public.app_event_manager_digest_candidate(p_event_id uuid, p_at timestamp with time zone)
 RETURNS TABLE(event_revision integer, occurrence_starts_at timestamp with time zone, event_name text, event_date date, display_location text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_event public.events_app_events%rowtype;v_place jsonb;
begin
  if p_event_id is null or p_at is null or not isfinite(p_at) then return; end if;
  select * into v_event from public.events_app_events where id=p_event_id;
  if v_event.id is null or v_event.status<>'SCHEDULED'
    or coalesce(v_event.needs_review,false) or v_event.event_scope='UNKNOWN'
    or v_event.cancelled_at is not null or v_event.archived_at is not null
    or v_event.start_instant_utc is null or v_event.end_instant_utc is null
    or v_event.start_instant_utc<=p_at then return;end if;
  v_place:=public.app_event_place_authority(to_jsonb(v_event),p_at);
  if (v_place->>'admissible')::boolean is not true then return;end if;
  return query select v_event.revision,v_event.start_instant_utc,v_event.event_name,
    v_event.event_date,coalesce(nullif(v_place->>'primary_display_name',''),v_event.display_location);
end $function$

CREATE OR REPLACE FUNCTION public.app_event_manager_digest_is_current(p_payload jsonb, p_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_id uuid;v_revision integer;v_start timestamptz;
begin
  if p_payload is null or jsonb_typeof(p_payload)<>'object' or p_at is null then return false;end if;
  if coalesce(p_payload->>'next_event_id','') !~*
    '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or coalesce(p_payload->>'next_event_revision','') !~ '^[1-9][0-9]{0,8}$'
    or coalesce(p_payload->>'next_event_starts_at','')=''
    or not (p_payload ? 'next_event_display_location') then return false;end if;
  begin
    v_id:=(p_payload->>'next_event_id')::uuid;
    v_revision:=(p_payload->>'next_event_revision')::integer;
    v_start:=(p_payload->>'next_event_starts_at')::timestamptz;
  exception when others then return false;end;
  return exists(select 1 from public.app_event_manager_digest_candidate(v_id,p_at) candidate
    where candidate.event_revision=v_revision and candidate.occurrence_starts_at=v_start
      and candidate.display_location is not distinct from
        nullif(p_payload->>'next_event_display_location',''));
end $function$

CREATE OR REPLACE FUNCTION public.app_event_place_admission_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_authority jsonb;
begin
  if new.status='SCHEDULED' and coalesce(new.needs_review,false)=false then
    v_authority:=public.app_event_place_authority(to_jsonb(new),clock_timestamp());
    if (v_authority->>'admissible')::boolean is not true then
      raise exception using errcode='40901',message='Event venue mapping is inactive or requires manager review; refresh the venue before scheduling.',
        detail=v_authority::text;
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.app_event_place_authority(p_record jsonb, p_at timestamp with time zone DEFAULT statement_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_overlay jsonb;
  v_row jsonb;
  v_id text;
  v_primary text:=nullif(p_record->>'primary_venue_id','');
  v_count integer:=0;
  v_primary_display text;
  v_primary_status text;
begin
  if p_record is null or jsonb_typeof(p_record)<>'object' or p_at is null or not isfinite(p_at) then
    raise exception using errcode='22023',message='Event record and finite overlay clock required';
  end if;
  v_overlay:=public.custodial_place_event_venue_overlay(p_at);
  if jsonb_typeof(v_overlay->'venues')<>'array' then
    raise exception using errcode='55000',message='Event venue overlay unavailable';
  end if;
  for v_id in
    select distinct selected.id from (
      select v_primary as id
      union all
      select jsonb_array_elements_text(case when jsonb_typeof(p_record->'venue_ids')='array'
        then p_record->'venue_ids' else '[]'::jsonb end)
    ) selected where selected.id is not null and selected.id<>''
  loop
    v_count:=v_count+1;
    if v_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      return jsonb_build_object('admissible',false,'review_reason','invalid_legacy_venue_id','venue_id',v_id);
    end if;
    select item.value into v_row from jsonb_array_elements(v_overlay->'venues') item(value)
      where item.value->>'venue_id'=v_id;
    if v_row is null then
      return jsonb_build_object('admissible',false,'review_reason','legacy_venue_missing','venue_id',v_id);
    end if;
    if v_row->>'mapping_status' not in ('MAPPED','UNMAPPED')
      or coalesce((v_row->>'event_eligible')::boolean,false) is not true then
      return jsonb_build_object('admissible',false,'review_reason',coalesce(v_row->>'review_reason','legacy_venue_ineligible'),
        'mapping_status',v_row->>'mapping_status','venue_id',v_id,'source_drift',v_row->'source_drift');
    end if;
    if v_id=v_primary then
      v_primary_status:=v_row->>'mapping_status';
      if v_primary_status='MAPPED' then v_primary_display:=v_row->>'display_name'; end if;
    end if;
    v_row:=null;
  end loop;
  -- Older scheduled rows can be group-only. No bridge assignment is invented.
  if v_count=0 and coalesce(p_record->>'event_scope','UNKNOWN') not in ('ZOO_WIDE','OFFSITE','SINGLE_VENUE','MULTI_VENUE') then
    return jsonb_build_object('admissible',false,'review_reason','unresolved_event_scope');
  end if;
  return jsonb_build_object('admissible',true,'mapping_status',coalesce(v_primary_status,'LEGACY_UNMAPPED'),
    'primary_display_name',v_primary_display,'venue_count',v_count,
    'capability_authority',case when v_primary_status='MAPPED' then 'CANONICAL_EVENT_ONLY' else 'LEGACY_UNMAPPED' end);
end $function$

CREATE OR REPLACE FUNCTION public.app_event_supersession_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_op='INSERT' then
    if new.status='SUPERSEDED' then raise exception using errcode='42501',message='new event cannot be born superseded'; end if;
    return new;
  end if;
  if tg_op='DELETE' then
    if old.status='SUPERSEDED' then raise exception using errcode='42501',message='superseded event history cannot be deleted'; end if;
    return old;
  end if;
  if old.status='SUPERSEDED' and new is distinct from old then
    raise exception using errcode='42501',message='superseded event history is immutable';
  end if;
  if old.status<>'SUPERSEDED' and new.status='SUPERSEDED'
    and current_setting('app.event_supersession_command',true) is distinct from 'on' then
    raise exception using errcode='42501',message='named manager supersession command is required';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.app_replace_event_authoritative(p_event_id uuid, p_expected_revision integer, p_record jsonb, p_manager_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_manager public.ops_manager_managers%rowtype;
  v_old public.events_app_events%rowtype;
  v_new public.events_app_events%rowtype;
  v_previous jsonb;
  v_operation_id uuid;
  v_created jsonb;
  v_request_digest text;
  v_now timestamptz:=statement_timestamp();
begin
  select * into v_manager from public.ops_manager_managers m where m.manager_id=p_manager_id
    and m.active=true and m.revoked_at is null and m.is_system_principal=false
    and m.roles && array['OPS_MANAGER','CUSTODIAL_MANAGER','DIRECTOR','SECURITY_ADMIN']::text[] for share;
  if v_manager.manager_id is null or nullif(btrim(v_manager.display_name),'') is null then
    raise exception using errcode='42501',message='active named manager authority is required for event replacement';
  end if;
  if p_event_id is null or p_expected_revision is null or p_expected_revision<1
    or jsonb_typeof(p_record) is distinct from 'object' then
    raise exception using errcode='22023',message='event id, expected revision and normalized replacement are required';
  end if;
  begin v_operation_id:=(p_record->>'operation_id')::uuid;
  exception when others then raise exception using errcode='22023',message='replacement operation id must be a UUID'; end;
  if v_operation_id is null or p_record->>'status'<>'SCHEDULED'
    or coalesce((p_record->>'needs_review')::boolean,true)
    or nullif(p_record->>'start_instant_utc','') is null
    or nullif(p_record->>'end_instant_utc','') is null then
    raise exception using errcode='22023',message='resolved scheduled replacement and explicit Chicago instants are required';
  end if;
  v_request_digest:=public.static_weekly_digest_jsonb(jsonb_build_object(
    'source_event_id',p_event_id,'expected_revision',p_expected_revision,
    'manager_id',p_manager_id,'record',p_record));
  select * into v_old from public.events_app_events e where e.id=p_event_id for update;
  if not found then raise exception using errcode='P0002',message='source event not found'; end if;
  if v_old.status='SUPERSEDED' then
    select * into v_new from public.events_app_events e where e.id=v_old.superseded_by_event_id;
    if v_new.operation_id=v_operation_id and v_old.supersession_request_digest=v_request_digest then
      return jsonb_build_object('old_event',to_jsonb(v_old),'replacement_event',to_jsonb(v_new),'replayed',true);
    end if;
    raise exception using errcode='40901',message='Event was already superseded by another replacement. Refresh before saving.';
  end if;
  if v_old.status<>'SCHEDULED' or coalesce(v_old.needs_review,false) then
    raise exception using errcode='40901',message='Only an active resolved event can be replaced. Refresh before saving.';
  end if;
  if v_old.revision is distinct from p_expected_revision then
    raise exception using errcode='40901',message='Event changed since this preview. Refresh and review before saving.';
  end if;
  if exists(select 1 from public.events_app_events e where e.operation_id=v_operation_id) then
    raise exception using errcode='40901',message='Replacement operation already belongs to another event.';
  end if;
  v_previous:=to_jsonb(v_old);
  v_created:=public.app_apply_event_command('create',null,
    p_record||jsonb_build_object('actor_manager_id',p_manager_id,'manually_overridden',true),null,
    'Manager-confirmed replacement event.');
  select * into v_new from public.events_app_events e where e.id=(v_created->>'id')::uuid;
  if v_new.id is null or v_new.status<>'SCHEDULED' or v_new.operation_id<>v_operation_id then
    raise exception using errcode='22023',message='replacement event did not persist as scheduled';
  end if;
  perform set_config('app.event_supersession_command','on',true);
  update public.events_app_events e set status='SUPERSEDED',superseded_by_event_id=v_new.id,
    superseded_at=v_now,superseded_by_manager_id=p_manager_id,supersession_request_digest=v_request_digest,
    revision=e.revision+1,updated_at=v_now
    where e.id=v_old.id returning * into v_old;
  insert into public.events_app_event_history(event_id,action,actor,actor_manager_id,reason,previous_record,new_record,created_at)
    values(v_old.id,'supersede',v_manager.display_name,p_manager_id,
      'Manager-confirmed replacement; original event retained.',v_previous,to_jsonb(v_old),v_now);
  insert into public.events_app_event_history(event_id,action,actor,actor_manager_id,reason,previous_record,new_record,created_at)
    values(v_new.id,'create_replacement',v_manager.display_name,p_manager_id,
      'Replacement for event '||v_old.id::text,null,to_jsonb(v_new),v_now);
  return jsonb_build_object('old_event',to_jsonb(v_old),'replacement_event',to_jsonb(v_new),'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.app_transition_event_cancellation(p_event_id uuid, p_action text, p_expected_revision integer, p_operation_id uuid, p_manager_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_manager public.ops_manager_managers%rowtype;
  v_old public.events_app_events%rowtype;
  v_new public.events_app_events%rowtype;
  v_receipt public.events_app_transition_receipts%rowtype;
  v_previous jsonb;
  v_history_id uuid;
  v_reason text:=left(coalesce(nullif(btrim(p_reason),''),
    case when p_action='restore' then 'Manager-confirmed ordinary cancellation recovery.'
      else 'Manager-confirmed event cancellation.' end),1000);
  v_digest text;
  v_now timestamptz;
begin
  if p_event_id is null or p_action not in ('cancel','restore') or p_action is null
    or p_expected_revision is null or p_expected_revision<1
    or p_operation_id is null or p_manager_id is null then
    raise exception using errcode='22023',message='event, action, revision, operation and named manager are required';
  end if;
  select * into v_manager from public.ops_manager_managers m
    where m.manager_id=p_manager_id and m.active=true and m.revoked_at is null
      and m.is_system_principal=false
      and m.roles && array['OPS_MANAGER','CUSTODIAL_MANAGER','DIRECTOR','SECURITY_ADMIN']::text[]
    for share;
  if v_manager.manager_id is null or nullif(btrim(v_manager.display_name),'') is null then
    raise exception using errcode='42501',message='active named manager authority is required for event transition';
  end if;
  v_digest:=public.static_weekly_digest_jsonb(jsonb_build_object(
    'event_id',p_event_id,'action',p_action,'expected_revision',p_expected_revision,
    'manager_id',p_manager_id,'reason',v_reason));
  select * into v_old from public.events_app_events e where e.id=p_event_id for update;
  if v_old.id is null then raise exception using errcode='P0002',message='event not found'; end if;
  v_now:=clock_timestamp();
  select * into v_receipt from public.events_app_transition_receipts r
    where r.operation_id=p_operation_id;
  if v_receipt.operation_id is not null then
    if v_receipt.event_id=p_event_id and v_receipt.action=p_action
      and v_receipt.expected_revision=p_expected_revision
      and v_receipt.actor_manager_id=p_manager_id and v_receipt.request_digest=v_digest then
      return jsonb_build_object('event',v_receipt.result_record,'history_id',v_receipt.history_id,
        'operation_id',p_operation_id,'action',p_action,'replayed',true,
        'reminders','current eligibility revalidation pending');
    end if;
    raise exception using errcode='40901',message='Event operation id belongs to a different request.';
  end if;
  if v_old.revision is distinct from p_expected_revision then
    raise exception using errcode='40901',message='Event changed since this preview. Refresh and review before saving.';
  end if;
  if p_action='cancel' then
    if v_old.status not in ('SCHEDULED','NEEDS_REVIEW') or v_old.superseded_by_event_id is not null then
      raise exception using errcode='40901',message='Only a current scheduled or review event can be cancelled.';
    end if;
  else
    if v_old.status<>'CANCELLED' or v_old.cancelled_from_status is distinct from 'SCHEDULED'
      or v_old.superseded_by_event_id is not null or v_old.archived_at is not null
      or coalesce(v_old.needs_review,false) or v_old.event_scope='UNKNOWN' then
      raise exception using errcode='40901',message='Only a resolved ordinary cancellation can be restored.';
    end if;
    if v_old.end_instant_utc is null or v_old.end_instant_utc<=v_now then
      raise exception using errcode='40901',message='Event occurrence is past or lacks a confirmed Chicago instant; correct it before restoring.';
    end if;
    if v_old.event_scope='ZOO_WIDE' then
      if not exists(select 1 from public.event_venues ev
          where ev.id=v_old.primary_venue_id and ev.active and ev.event_scope='ZOO_WIDE') then
        raise exception using errcode='40901',message='Zoo-wide venue is no longer eligible.';
      end if;
    elsif v_old.event_scope in ('SINGLE_VENUE','MULTI_VENUE') then
      if v_old.primary_venue_id is null or not(v_old.primary_venue_id=any(v_old.venue_ids))
        or (v_old.event_scope='MULTI_VENUE' and cardinality(v_old.venue_ids)<2)
        or exists(select 1 from unnest(v_old.venue_ids) selected(id)
          left join public.event_venues ev on ev.id=selected.id
          where ev.id is null or not ev.active or not ev.eligible_event_venue
            or ev.event_scope='ZOO_WIDE') then
        raise exception using errcode='40901',message='Event venue is no longer eligible; manager correction is required.';
      end if;
    elsif v_old.event_scope<>'OFFSITE' then
      raise exception using errcode='40901',message='Event scope is not restorable.';
    end if;
  end if;
  v_previous:=to_jsonb(v_old);
  perform set_config('app.event_cancellation_transition','on',true);
  if p_action='cancel' then
    update public.events_app_events e set status='CANCELLED',cancelled_from_status=v_old.status,
      cancelled_at=v_now,cancelled_by=v_manager.display_name,cancelled_by_manager_id=p_manager_id,
      cancellation_reason=v_reason,overridden_by=v_manager.display_name,overridden_at=v_now,
      updated_by_manager_id=p_manager_id,revision=e.revision+1,updated_at=v_now
      where e.id=p_event_id returning * into v_new;
  else
    update public.events_app_events e set status='SCHEDULED',cancelled_from_status=null,
      cancelled_at=null,cancelled_by=null,cancelled_by_manager_id=null,cancellation_reason=null,
      overridden_by=v_manager.display_name,overridden_at=v_now,
      updated_by_manager_id=p_manager_id,revision=e.revision+1,updated_at=v_now
      where e.id=p_event_id returning * into v_new;
  end if;
  insert into public.events_app_event_history
    (event_id,action,actor,actor_manager_id,reason,previous_record,new_record,created_at)
    values(p_event_id,p_action,v_manager.display_name,p_manager_id,v_reason,v_previous,to_jsonb(v_new),v_now)
    returning id into v_history_id;
  insert into public.events_app_transition_receipts
    (operation_id,event_id,action,expected_revision,actor_manager_id,request_digest,history_id,result_record,created_at)
    values(p_operation_id,p_event_id,p_action,p_expected_revision,p_manager_id,v_digest,v_history_id,to_jsonb(v_new),v_now);
  return jsonb_build_object('event',to_jsonb(v_new),'history_id',v_history_id,
    'operation_id',p_operation_id,'action',p_action,'replayed',false,
    'reminders','current eligibility revalidation pending');
end $function$

CREATE OR REPLACE FUNCTION public.claim_event_notification(p_event_id uuid, p_employee_id uuid, p_msg_user_id uuid, p_notification_kind text, p_scheduled_for_local text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_kind text := nullif(btrim(coalesce(p_notification_kind, '')), '');
  v_scheduled timestamp;
  v_existing public.events_app_notification_log%rowtype;
begin
  if p_event_id is null or p_employee_id is null or p_msg_user_id is null then
    raise exception 'event_id, employee_id, and msg_user_id are required';
  end if;
  if v_kind is null or length(v_kind) > 120 then
    raise exception 'notification_kind is required and must be at most 120 characters';
  end if;
  begin
    v_scheduled := p_scheduled_for_local::timestamp;
  exception when others then
    raise exception 'scheduled_for_local is invalid';
  end;

  perform pg_advisory_xact_lock(hashtextextended('event-reminder:' || p_event_id::text || ':' || p_employee_id::text, 0));

  select log.* into v_existing
  from public.events_app_notification_log log
  where log.event_id = p_event_id
    and log.employee_id = p_employee_id
    and log.status in ('sent', 'sending')
    and (log.status = 'sent' or log.updated_at > now() - interval '10 minutes')
  order by case when log.status = 'sent' then 0 else 1 end, log.updated_at desc
  limit 1;

  if found then
    return jsonb_build_object(
      'claimed', false,
      'reason', case when v_existing.status = 'sent' then 'event_already_notified' else 'event_notification_in_flight' end,
      'notification_kind', v_existing.notification_kind,
      'response_message_id', v_existing.response_message_id,
      'status', v_existing.status
    );
  end if;

  insert into public.events_app_notification_log(
    event_id, employee_id, msg_user_id, notification_kind, scheduled_for_local,
    sent_at, status, notes, created_at, updated_at
  ) values (
    p_event_id, p_employee_id, p_msg_user_id, v_kind, v_scheduled,
    now(), 'sending', 'Claimed before message delivery', now(), now()
  )
  on conflict (event_id, employee_id, notification_kind) do update set
    msg_user_id = excluded.msg_user_id,
    scheduled_for_local = excluded.scheduled_for_local,
    sent_at = now(),
    status = 'sending',
    response_message_id = null,
    notes = 'Retry claimed before message delivery',
    updated_at = now()
  where public.events_app_notification_log.status = 'error'
     or (public.events_app_notification_log.status = 'sending'
         and public.events_app_notification_log.updated_at <= now() - interval '10 minutes')
  returning * into v_existing;

  if not found then
    select log.* into v_existing
    from public.events_app_notification_log log
    where log.event_id = p_event_id
      and log.employee_id = p_employee_id
      and log.notification_kind = v_kind
    limit 1;
    return jsonb_build_object(
      'claimed', false,
      'reason', 'notification_already_claimed',
      'response_message_id', v_existing.response_message_id,
      'status', v_existing.status
    );
  end if;

  return jsonb_build_object(
    'claimed', true,
    'reason', 'claim_created',
    'notification_kind', v_kind,
    'log_id', v_existing.id,
    'status', v_existing.status
  );
end
$function$

CREATE OR REPLACE FUNCTION public.cleaning_inspections_set_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_session record;
  v_completion_at timestamptz;
  v_inspector_name text;
begin
  if tg_op = 'UPDATE' then
    if row(new.operation_id,new.session_id,new.request_fingerprint,new.inspector_manager_id,
           new.inspected_at,new.created_at,new.location_id,new.employee_id,new.inspector_name_snapshot,
           new.employee_name_snapshot,new.location_code_snapshot,new.location_name_snapshot,
           new.session_started_at,new.session_ended_at,new.session_duration_minutes)
       is distinct from
       row(old.operation_id,old.session_id,old.request_fingerprint,old.inspector_manager_id,
           old.inspected_at,old.created_at,old.location_id,old.employee_id,old.inspector_name_snapshot,
           old.employee_name_snapshot,old.location_code_snapshot,old.location_name_snapshot,
           old.session_started_at,old.session_ended_at,old.session_duration_minutes) then
      raise exception using errcode='23514', message='Inspection actor, cleaning identity, and snapshots are immutable';
    end if;
    new.updated_at := clock_timestamp();
    return new;
  end if;

  new.inspected_at := statement_timestamp();
  new.created_at := new.inspected_at;
  select
    s.location_id,s.employee_id,s.started_at,s.ended_at,s.duration_minutes,s.status,
    (select max(cr.submitted_at) from public.completion_responses cr where cr.session_id=s.id) completion_submitted_at,
    s.location_code_snapshot,s.location_name_snapshot,s.employee_name_snapshot
  into v_session
  from public.sessions s
  where s.id = new.session_id;
  if not found then
    raise exception using errcode='P0002', message='Cleaning session was not found';
  end if;
  if v_session.status not in ('pending_submit','closed') then
    raise exception using errcode='23514', message='Only a finished cleaning session can be inspected';
  end if;
  v_completion_at := coalesce(v_session.ended_at,v_session.completion_submitted_at);
  if v_completion_at is null then
    raise exception using errcode='23514', message='Finished cleaning session has no completion timestamp';
  end if;
  if new.inspected_at < v_completion_at or new.inspected_at > v_completion_at + interval '24 hours' then
    raise exception using errcode='23514', message='Inspection must be recorded within 24 hours after cleaning completion';
  end if;

  new.location_id := v_session.location_id;
  new.employee_id := v_session.employee_id;
  new.employee_name_snapshot := v_session.employee_name_snapshot;
  new.location_code_snapshot := v_session.location_code_snapshot;
  new.location_name_snapshot := v_session.location_name_snapshot;
  new.session_started_at := v_session.started_at;
  new.session_ended_at := v_completion_at;
  new.session_duration_minutes := coalesce(v_session.duration_minutes,
    greatest(0,ceil(extract(epoch from (v_completion_at-v_session.started_at))/60.0)::integer));

  if new.inspector_manager_id is not null then
    select m.display_name into v_inspector_name
    from public.ops_manager_managers m
    where m.manager_id=new.inspector_manager_id
      and m.active=true and m.revoked_at is null and m.is_system_principal=false;
    if not found then
      raise exception using errcode='23503', message='Active inspector manager was not found';
    end if;
    new.inspector_name_snapshot := v_inspector_name;
  else
    new.inspector_name_snapshot := coalesce(nullif(btrim(new.inspector_name_snapshot),''),'Custodial Manager');
  end if;
  new.updated_at := clock_timestamp();
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.coverall_original_static_weekly_pending_exception_set(p_operation uuid, p_publication uuid, p_week date, p_day date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.static_weekly_staffing_commands%rowtype;ctx jsonb;result jsonb;d date;slot uuid;version uuid;row jsonb;
BEGIN
 SELECT * INTO STRICT c FROM public.static_weekly_staffing_commands WHERE operation_id=p_operation;
 ctx:=public.static_weekly_pending_context(p_operation,c.prepared_by_manager_id);
 IF p_week IS NULL OR public.static_weekly_projection_window_start(p_week) IS DISTINCT FROM p_week OR p_week>c.end_date OR p_week+6<c.start_date
  OR p_day IS NOT NULL AND (p_day NOT BETWEEN greatest(p_week,c.start_date) AND least(p_week+6,c.end_date))
 THEN RAISE EXCEPTION 'Pending scope differs';END IF;
 SELECT version_id INTO STRICT version FROM public.weekly_schedule_publications WHERE publication_id=p_publication;
 IF public.static_weekly_effective_version(p_week)<>version OR public.static_weekly_effective_version(p_week+6)<>version
 THEN RAISE EXCEPTION 'Pending publication changed within week';END IF;
 result:=public.static_weekly_pending_original_exception_set(p_publication,p_week,p_operation);
 IF c.command_kind='cancel_absence' THEN
  SELECT coalesce(jsonb_agg(e ORDER BY n),'[]') INTO result FROM jsonb_array_elements(result) WITH ORDINALITY x(e,n)
   WHERE (e->>'staffingAbsenceId'=c.target_absence_id::text AND (e->>'serviceDate')::date BETWEEN c.start_date AND c.end_date
    AND (p_day IS NULL OR (e->>'serviceDate')::date=p_day)) IS NOT TRUE;
 ELSE
  FOR d IN SELECT generate_series(greatest(p_week,c.start_date),least(p_week+6,c.end_date),'1 day')::date LOOP
   IF p_day IS NOT NULL AND d<>p_day THEN CONTINUE;END IF;
   SELECT i.slot_id INTO STRICT slot FROM public.v_weekly_roster_slot_incumbency_ranges i WHERE i.person_id=c.employee_id
    AND i.effective_start<=d AND (i.effective_end IS NULL OR d<i.effective_end);
   row:=jsonb_build_object('id',c.operation_id::text||':'||d::text,'type',CASE WHEN c.absence_kind='pto' THEN 'pto' ELSE 'daily_absence' END,
    'serviceDate',d,'staffingAbsenceId',c.operation_id,'staffingAbsenceKind',c.absence_kind,'actorId',c.prepared_by_manager_id,
    'reason','Approved staffing unavailability','idempotencyKey','staffing:'||c.operation_id::text||':'||d::text,
    'expectedRevision',c.expected_revision,'payload',jsonb_build_object('slotId',slot),'baseVersionId',version,'publicationId',p_publication,
    'sequence',c.expected_revision+1+(d-c.start_date));
   -- No accepted/status flag is exported or trusted on this proposed fact.
   result:=result||jsonb_build_array(row);
  END LOOP;
 END IF;
 SELECT coalesce(jsonb_agg(e ORDER BY e->>'serviceDate',(e->>'sequence')::bigint,e->>'id' COLLATE "C"),'[]') INTO result FROM jsonb_array_elements(result) e;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.create_maintenance_tickets_from_response(p_completion_response_id uuid, p_session_id uuid, p_location_id uuid, p_reported_by_employee_id uuid, p_device_id uuid, p_reported_at timestamp with time zone, p_response_json jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_issue_array jsonb;
  v_item jsonb;
  v_issue_summary text;
  v_issue_category text;
  v_fixture_type text;
  v_fixture_identifier text;
  v_out_of_order boolean;
  v_location_code text;
  v_location_name text;
  v_reporter_name text;
  v_count integer := 0;
  v_top_level_out_of_order boolean := (
    lower(coalesce(
      p_response_json->>'out_of_order',
      p_response_json->>'outOfOrder',
      p_response_json->>'place_out_of_order',
      p_response_json->>'placeOutOfOrder',
      p_response_json->>'out_of_order_signed',
      p_response_json->>'outOfOrderSigned',
      'false'
    )) in ('true','t','1','yes','y','on')
  );
  v_top_level_fixture_identifier text := coalesce(
    p_response_json->>'fixture_identifier',
    p_response_json->>'fixtureIdentifier',
    p_response_json->>'out_of_order_details',
    p_response_json->>'outOfOrderDetails',
    p_response_json->>'stall',
    p_response_json->>'stall_number',
    p_response_json->>'stallNumber',
    p_response_json->>'urinal',
    p_response_json->>'urinal_number',
    p_response_json->>'urinalNumber'
  );
  v_explicit_issue_notes text := coalesce(
    p_response_json->>'maintenance_notes',
    p_response_json->>'maintenanceNotes',
    p_response_json->>'issue_notes',
    p_response_json->>'issueNotes'
  );
  v_top_level_notes text := coalesce(
    v_explicit_issue_notes,
    p_response_json->>'notes',
    p_response_json->>'note'
  );
  v_has_explicit_issue boolean := (
    lower(coalesce(
      p_response_json->>'has_maintenance_issue',
      p_response_json->>'hasMaintenanceIssue',
      p_response_json->>'maintenance_issue',
      p_response_json->>'maintenanceIssue',
      'false'
    )) in ('true','t','1','yes','y','on')
  );
begin
  select l.location_code, l.location_name
    into v_location_code, v_location_name
  from public.locations l
  where l.id = p_location_id
  limit 1;

  select e.display_name
    into v_reporter_name
  from public.employees e
  where e.id = p_reported_by_employee_id
  limit 1;

  delete from public.maintenance_tickets mt
  where mt.completion_response_id = p_completion_response_id
    and mt.issue_source = 'completion_form'
    and mt.status = 'open';

  v_issue_array := case
    when jsonb_typeof(p_response_json->'maintenance_issues') = 'array' then p_response_json->'maintenance_issues'
    when jsonb_typeof(p_response_json->'maintenanceIssues') = 'array' then p_response_json->'maintenanceIssues'
    when jsonb_typeof(p_response_json->'maintenance_issue_checks') = 'array' then p_response_json->'maintenance_issue_checks'
    when jsonb_typeof(p_response_json->'maintenanceIssueChecks') = 'array' then p_response_json->'maintenanceIssueChecks'
    when jsonb_typeof(p_response_json->'checked_maintenance_issues') = 'array' then p_response_json->'checked_maintenance_issues'
    when jsonb_typeof(p_response_json->'checkedMaintenanceIssues') = 'array' then p_response_json->'checkedMaintenanceIssues'
    when jsonb_typeof(p_response_json->'maintenance_issues_found') = 'array' then p_response_json->'maintenance_issues_found'
    when jsonb_typeof(p_response_json->'maintenanceIssuesFound') = 'array' then p_response_json->'maintenanceIssuesFound'
    when jsonb_typeof(p_response_json->'maintenance_issue_found') = 'array' then p_response_json->'maintenance_issue_found'
    when jsonb_typeof(p_response_json->'issues') = 'array' then p_response_json->'issues'
    when jsonb_typeof(p_response_json->'maintenance') = 'array' then p_response_json->'maintenance'
    else null
  end;

  if v_issue_array is null
     and (v_has_explicit_issue or v_explicit_issue_notes is not null or v_top_level_out_of_order) then
    v_issue_array := jsonb_build_array(
      jsonb_build_object(
        'label', coalesce(v_explicit_issue_notes, v_top_level_notes, 'Maintenance issue reported'),
        'fixture_identifier', v_top_level_fixture_identifier,
        'out_of_order', v_top_level_out_of_order,
        'raw_response', p_response_json
      )
    );
  end if;

  if v_issue_array is null or jsonb_array_length(v_issue_array) = 0 then
    return 0;
  end if;

  for v_item in select value from jsonb_array_elements(v_issue_array)
  loop
    if jsonb_typeof(v_item) = 'string' then
      v_issue_summary := trim(both '"' from v_item::text);
      if lower(v_issue_summary) in ('other maintenance issue found', 'other') and v_top_level_notes is not null then
        v_issue_summary := 'Other maintenance issue: ' || v_top_level_notes;
      end if;
      v_issue_category := trim(both '"' from v_item::text);
      v_fixture_type := case
        when lower(v_issue_summary) like '%toilet%' then 'toilet'
        when lower(v_issue_summary) like '%urinal%' then 'urinal'
        else null
      end;
      v_fixture_identifier := v_top_level_fixture_identifier;
      v_out_of_order := v_top_level_out_of_order;
    else
      v_issue_summary := coalesce(
        v_item->>'label', v_item->>'issue', v_item->>'issue_label',
        v_item->>'issueLabel', v_item->>'name', v_item->>'value',
        v_item->>'description', v_item->>'maintenance_issue',
        v_item->>'maintenanceIssue', 'Maintenance issue reported'
      );
      if lower(v_issue_summary) in ('other maintenance issue found', 'other') and v_top_level_notes is not null then
        v_issue_summary := 'Other maintenance issue: ' || v_top_level_notes;
      end if;
      v_issue_category := coalesce(
        v_item->>'category', v_item->>'issue_category',
        v_item->>'issueCategory', v_issue_summary
      );
      v_fixture_type := coalesce(
        v_item->>'fixture_type', v_item->>'fixtureType',
        case
          when lower(v_issue_summary) like '%toilet%' then 'toilet'
          when lower(v_issue_summary) like '%urinal%' then 'urinal'
          else null
        end
      );
      v_fixture_identifier := coalesce(
        v_item->>'fixture_identifier', v_item->>'fixtureIdentifier',
        v_item->>'stall', v_item->>'stall_number', v_item->>'stallNumber',
        v_item->>'urinal', v_item->>'urinal_number', v_item->>'urinalNumber',
        v_top_level_fixture_identifier
      );
      v_out_of_order := (
        lower(coalesce(
          v_item->>'out_of_order', v_item->>'outOfOrder',
          v_item->>'place_out_of_order', v_item->>'placeOutOfOrder',
          v_item->>'out_of_order_signed', v_item->>'outOfOrderSigned',
          case when v_top_level_out_of_order then 'true' else 'false' end
        )) in ('true','t','1','yes','y','on')
      );
    end if;

    insert into public.maintenance_tickets (
      completion_response_id, session_id, location_id,
      reported_by_employee_id, device_id, issue_source, status,
      issue_summary, issue_category, fixture_type, fixture_identifier,
      out_of_order, issue_payload, location_code_snapshot,
      location_name_snapshot, reporter_name_snapshot, reported_at
    ) values (
      p_completion_response_id, p_session_id, p_location_id,
      p_reported_by_employee_id, p_device_id, 'completion_form', 'open',
      left(coalesce(v_issue_summary, 'Maintenance issue reported'), 500),
      left(v_issue_category, 200), left(v_fixture_type, 100),
      left(v_fixture_identifier, 100), coalesce(v_out_of_order, false),
      jsonb_build_object(
        'raw_item', v_item,
        'top_level_note', v_top_level_notes,
        'top_level_fixture_identifier', v_top_level_fixture_identifier,
        'top_level_out_of_order', v_top_level_out_of_order
      ),
      v_location_code, v_location_name, v_reporter_name,
      coalesce(p_reported_at, now())
    );

    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.custodial_action_actor_v1(p_manager_id uuid, p_credential_id uuid, p_device_id text, p_session_access text, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE m public.ops_manager_managers%ROWTYPE;c public.ops_manager_trusted_devices%ROWTYPE;is_owner boolean;
BEGIN
 IF p_action IS NULL OR p_action NOT IN ('read','write','close_scan_tickets','manage_absences','manage_coverall','regenerate_routes')
  OR p_session_access IS NULL OR p_session_access NOT IN ('full_access','read_only') THEN
  RAISE EXCEPTION USING errcode='42501',message='Unknown manager action or session access';END IF;
 IF EXISTS(SELECT 1 FROM custodial_leadership_private.policy p WHERE p.cohort_principal_id=p_manager_id) THEN
  IF p_session_access<>'full_access' THEN RAISE EXCEPTION 'Current cohort full management context required' USING ERRCODE='42501';END IF;
  DECLARE cohort_actor jsonb;BEGIN
   cohort_actor:=custodial_leadership_private.require_context(p_manager_id,'custodialManagementAdmin');
   IF cohort_actor->>'credential_id' IS DISTINCT FROM p_credential_id::text OR cohort_actor->>'device_id' IS DISTINCT FROM p_device_id
    OR cohort_actor->'custodialManagementAdmin' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'Original cohort credential differs' USING ERRCODE='42501';END IF;
   RETURN cohort_actor;
  END;
 END IF;
 SELECT * INTO c FROM public.ops_manager_trusted_devices WHERE credential_id=p_credential_id FOR SHARE;
 SELECT * INTO m FROM public.ops_manager_managers WHERE manager_id=p_manager_id FOR SHARE;
 IF c.credential_id IS NULL OR m.manager_id IS NULL OR c.manager_id IS DISTINCT FROM m.manager_id
  OR c.device_id IS DISTINCT FROM p_device_id OR c.revoked_at IS NOT NULL
  OR c.expires_at IS NULL OR c.expires_at<=clock_timestamp() OR c.created_at IS NULL OR c.created_at>clock_timestamp()
  OR m.active IS NOT TRUE OR m.revoked_at IS NOT NULL OR m.is_system_principal IS NOT FALSE
  OR coalesce(m.roles && ARRAY['OPS_MANAGER','CUSTODIAL_MANAGER','DIRECTOR','SECURITY_ADMIN'],false) IS NOT TRUE
  OR nullif(btrim(m.display_name),'') IS NULL THEN
  RAISE EXCEPTION USING errcode='42501',message='A current named manager credential is required';END IF;
 is_owner:=coalesce(m.system_key='eric_custodial_manager' AND p_session_access='full_access' AND c.max_access_level='full_access',false);
 IF p_action<>'read' AND m.system_key='eric_custodial_manager' AND NOT is_owner THEN
  RAISE EXCEPTION USING errcode='42501',message='Use a current full-control owner sign-in';END IF;
 IF p_action='write' AND NOT is_owner THEN
  RAISE EXCEPTION USING errcode='42501',message='This action is owner-only';END IF;
 RETURN jsonb_build_object('manager_id',m.manager_id,'manager_name',m.display_name,'owner',is_owner,
  'credential_id',c.credential_id,'device_id',c.device_id,'scheduler_delegation','dated_absences_coverall_routes',
  'owner_unavailability_required',false);
END $function$

CREATE OR REPLACE FUNCTION public.custodial_activation_assert_consume(p_operation uuid, p_device uuid, p_code_hash text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.custodial_assigned_activation_operations%rowtype; d public.devices%rowtype; c public.device_auth_enrollment_codes%rowtype;
begin
 perform public.custodial_begin_application_mutation();
 select * into strict d from public.devices where id=p_device for update;
 select * into a from public.custodial_assigned_activation_operations where operation_id=p_operation for update;
 if a.operation_id is null then raise exception 'assigned activation operation not found'; end if;
 if a.device_id is distinct from p_device or a.canonical_device_id is distinct from d.device_id or d.active is not true
  or a.expected_employee_id is distinct from d.assigned_employee_id or a.expected_assignment_epoch is distinct from d.assignment_epoch
  or a.state not in ('prepared','delivered','delivery_unknown') or a.expires_at<=now() or a.claimant_credential_id is null
  then raise exception 'assigned activation recipient is stale or unavailable'; end if;
 perform public.custodial_activation_assert_manager(a.requester_manager_id,a.claimant_credential_id,a.claimant_device_id);
 select * into strict c from public.device_auth_enrollment_codes where enrollment_id=a.enrollment_id for update;
 if c.device_id is distinct from p_device or c.code_hash is distinct from p_code_hash or c.revoked_at is not null or c.expires_at<=now()
  or c.failed_attempts>=10 or c.metadata_json->>'purpose' is distinct from 'assigned_device_activation'
  or c.metadata_json->>'operation_id' is distinct from p_operation::text
  or c.metadata_json->>'device_id' is distinct from p_device::text
  or c.metadata_json->>'canonical_device_id' is distinct from d.device_id
  or c.metadata_json->>'employee_id' is distinct from a.expected_employee_id::text
  or c.metadata_json->>'assignment_epoch' is distinct from a.expected_assignment_epoch::text
  or c.metadata_json->>'claimant_credential_id' is distinct from a.claimant_credential_id::text
  or (c.consumed_at is not null and not exists(select 1 from public.device_auth_enrollment_operations e
   where e.operation_id=p_operation and e.device_id=p_device and e.enrollment_id=c.enrollment_id))
  then raise exception 'assigned activation code binding invalid'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_activation_claim(p_operation uuid, p_manager uuid, p_claimant uuid, p_workstation text, p_serial_sha256 text, p_client_version text, p_code_hash text, p_token_envelope jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.custodial_assigned_activation_operations%rowtype; d public.devices%rowtype; code jsonb;
begin
 perform public.custodial_begin_application_mutation();
 perform public.custodial_activation_assert_manager(p_manager,p_claimant,p_workstation);
 if p_workstation is null or p_operation is null then raise exception 'exact workstation claim required'; end if;
 perform pg_advisory_xact_lock(hashtextextended('custodial-enrollment-operation:'||p_operation::text,0));
 select d0.* into strict d from public.devices d0 join public.custodial_assigned_activation_operations a0 on a0.device_id=d0.id
  where a0.operation_id=p_operation for update of d0;
 perform public.custodial_activation_expire_device(d.id);
 select * into strict a from public.custodial_assigned_activation_operations where operation_id=p_operation for update;
 if a.requester_manager_id is distinct from p_manager or a.requester_credential_id=p_claimant
  or a.approved_serial_sha256 is distinct from p_serial_sha256 then raise exception using errcode='42501',message='activation claimant or physical recipient mismatch'; end if;
 if a.terminal_at is not null then return jsonb_build_object('status',public.custodial_activation_public_status(a)); end if;
 -- Reserve the bounded attempt BEFORE returning the dispatch secret. Counting
 -- only the later delivery report permits endless retries after client loss.
 if a.attempts>=5 then raise exception using errcode='40001',message='activation dispatch attempt limit reached'; end if;
 if d.active is not true or d.assigned_employee_id is distinct from a.expected_employee_id
  or d.assignment_epoch is distinct from a.expected_assignment_epoch then raise exception 'activation assignment changed'; end if;
 if a.claimant_credential_id is not null then
  if (a.claimant_credential_id,a.claimant_device_id,a.client_version) is distinct from (p_claimant,p_workstation,p_client_version)
   then raise exception using errcode='42501',message='activation already claimed by another workstation'; end if;
  update public.custodial_assigned_activation_operations set state='prepared',state_version=state_version+1,
   attempts=attempts+1 where operation_id=p_operation returning * into a;
 else
  if coalesce(p_code_hash,'') !~ '^[0-9a-f]{64}$' or coalesce(p_client_version,'') !~ '^[a-z0-9][a-z0-9._-]{0,79}$'
   or p_token_envelope is null or jsonb_typeof(p_token_envelope)<>'object' or pg_column_size(p_token_envelope)>2048
   or p_token_envelope->>'version' is distinct from 'assigned-activation.aes-256-gcm.v1'
   or coalesce(p_token_envelope->>'ciphertext','') !~ '^[A-Za-z0-9_-]{58}$'
   or coalesce(p_token_envelope->>'iv','') !~ '^[A-Za-z0-9_-]{16}$'
   or coalesce(p_token_envelope->>'tag','') !~ '^[A-Za-z0-9_-]{22}$'
   or (select count(*) from jsonb_object_keys(p_token_envelope))<>4
   then raise exception 'bounded authenticated activation envelope required'; end if;
  select to_jsonb(issued) into strict code from public.device_auth_issue_enrollment_code(d.id,p_code_hash,p_manager::text,a.expires_at,
   jsonb_build_object('purpose','assigned_device_activation','operation_id',p_operation,'device_id',d.id,
    'canonical_device_id',d.device_id,'employee_id',a.expected_employee_id,'assignment_epoch',a.expected_assignment_epoch,
    'claimant_credential_id',p_claimant)) issued;
  update public.custodial_assigned_activation_operations set claimant_credential_id=p_claimant,claimant_device_id=p_workstation,
   client_version=p_client_version,enrollment_id=(code->>'enrollment_id')::uuid,token_envelope=p_token_envelope,
   state='prepared',state_version=state_version+1,attempts=1,prepared_at=now() where operation_id=p_operation returning * into a;
 end if;
 return jsonb_build_object('status',public.custodial_activation_public_status(a),'token_envelope',a.token_envelope);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_activation_delivery(p_operation uuid, p_manager uuid, p_claimant uuid, p_workstation text, p_expected_version integer, p_outcome text, p_error_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.custodial_assigned_activation_operations%rowtype;
begin
 perform public.custodial_begin_application_mutation();
 perform public.custodial_activation_assert_manager(p_manager,p_claimant,p_workstation);
 select * into strict a from public.custodial_assigned_activation_operations where operation_id=p_operation;
 perform 1 from public.devices where id=a.device_id for update;
 perform public.custodial_activation_expire_device(a.device_id);
 select * into strict a from public.custodial_assigned_activation_operations where operation_id=p_operation for update;
 if (a.requester_manager_id,a.claimant_credential_id,a.claimant_device_id) is distinct from (p_manager,p_claimant,p_workstation)
  then raise exception using errcode='42501',message='exact activation claimant required'; end if;
 if a.terminal_at is not null then return public.custodial_activation_public_status(a); end if;
 if a.state_version is distinct from p_expected_version or a.state<>'prepared'
  or a.attempts<1 or coalesce(p_outcome,'') not in ('delivered','delivery_unknown')
  then raise exception using errcode='40001',message='stale or invalid activation delivery report'; end if;
 update public.custodial_assigned_activation_operations set state=p_outcome,state_version=state_version+1,
  delivered_at=case when p_outcome='delivered' then coalesce(delivered_at,now()) else delivered_at end,
  last_error_code=p_error_code where operation_id=p_operation returning * into a;
 return public.custodial_activation_public_status(a);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_activation_guard_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
 if tg_op='DELETE' then raise exception 'activation operation history is retained'; end if;
 if old.terminal_at is not null then raise exception 'terminal activation receipt is immutable'; end if;
 if (new.operation_id,new.device_id,new.canonical_device_id,new.expected_employee_id,new.expected_assignment_epoch,
  new.requested_action,new.requester_manager_id,new.requester_credential_id,new.approved_serial_sha256,new.requested_at,new.expires_at)
 is distinct from (old.operation_id,old.device_id,old.canonical_device_id,old.expected_employee_id,old.expected_assignment_epoch,
  old.requested_action,old.requester_manager_id,old.requester_credential_id,old.approved_serial_sha256,old.requested_at,old.expires_at)
 then raise exception 'activation frozen recipient changed'; end if;
 if old.claimant_credential_id is not null and
  (new.claimant_credential_id,new.claimant_device_id,new.client_version,new.enrollment_id,new.prepared_at)
  is distinct from (old.claimant_credential_id,old.claimant_device_id,old.client_version,old.enrollment_id,old.prepared_at)
  then raise exception 'activation claimant changed'; end if;
 if new.state_version<>old.state_version+1 or new.attempts<old.attempts or new.attempts>old.attempts+1
  or not ((old.state='requested' and new.state in ('prepared','error','expired','cancelled'))
   or (old.state in ('prepared','delivered','delivery_unknown') and new.state in
    ('prepared','delivered','delivery_unknown','native_active','not_required','error','expired','cancelled')))
  then raise exception 'activation state transition invalid'; end if;
 if new.terminal_at is null and old.token_envelope is not null and new.token_envelope is distinct from old.token_envelope
  then raise exception 'activation same-operation token cannot rotate'; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_activation_list(p_manager uuid, p_requester uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare d record; result jsonb;
begin
 perform public.custodial_begin_application_mutation();
 perform public.custodial_activation_assert_manager(p_manager,p_requester);
 for d in select dev.id from public.devices dev where exists(select 1 from public.custodial_assigned_activation_operations a
  where a.device_id=dev.id and a.requester_manager_id=p_manager and a.terminal_at is null)
  order by dev.id limit 50 for update of dev
 loop perform public.custodial_activation_expire_device(d.id);end loop;
 select coalesce(jsonb_agg(public.custodial_activation_public_status(a) order by a.requested_at),'[]'::jsonb)
 into result from (select * from public.custodial_assigned_activation_operations
  where requester_manager_id=p_manager and terminal_at is null order by requested_at limit 50) a;
 return jsonb_build_object('operations',result);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_activation_native_result(p_operation uuid, p_device uuid, p_credential uuid, p_token_hash text, p_receipt jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.custodial_assigned_activation_operations%rowtype; d public.devices%rowtype;
 c public.device_auth_credentials%rowtype; e public.device_auth_enrollment_operations%rowtype;
outcome text; lineage uuid;
begin
 perform public.custodial_begin_application_mutation();
 if p_operation is null or p_device is null or p_credential is null then raise exception 'exact native result identity required'; end if;
 perform pg_advisory_xact_lock(hashtextextended('custodial-enrollment-operation:'||p_operation::text,0));
 select * into strict d from public.devices where id=p_device for update;
 perform public.custodial_activation_expire_device(p_device);
 select * into strict a from public.custodial_assigned_activation_operations where operation_id=p_operation for update;
 select * into c from public.device_auth_credentials where credential_id=p_credential and device_id=p_device
  and token_hash=p_token_hash and confirmed_at is not null and revoked_at is null and expires_at>now();
 if c.credential_id is null or a.device_id is distinct from p_device or d.active is not true
  or a.expected_employee_id is distinct from d.assigned_employee_id or a.expected_assignment_epoch is distinct from d.assignment_epoch
  then raise exception using errcode='42501',message='current exact assigned device credential required'; end if;
 if p_receipt is null or jsonb_typeof(p_receipt)<>'object' or pg_column_size(p_receipt)>2048
  or (select count(*) from jsonb_object_keys(p_receipt))<>9
  or p_receipt->>'operation_id' is distinct from p_operation::text
  or p_receipt->>'device_id' is distinct from d.device_id
  or p_receipt->>'credential_id' is distinct from p_credential::text
  or coalesce(p_receipt->>'flow','') not in ('enrollment','recovery')
  or p_receipt->>'journal_schema' is distinct from 'native-assigned-activation.v1'
  or coalesce(p_receipt->>'journal_binding_sha256','') !~ '^[0-9a-f]{64}$'
  or coalesce(p_receipt->>'lineage_operation_id','') !~ '^[0-9a-f-]{36}$'
  then raise exception 'exact bounded protected native receipt required'; end if;
 lineage:=(p_receipt->>'lineage_operation_id')::uuid;
 if not exists(select 1 from public.device_auth_enrollment_operations original
  where original.operation_id=lineage and original.device_id=p_device and original.status='confirmed'
   and public.custodial_credential_may_transmit_frozen_work(original.credential_id,p_credential,p_device,now()))
  then raise exception 'native lineage is not an authenticated predecessor'; end if;
 if a.state in ('native_active','not_required') then
  if a.native_receipt is distinct from p_receipt then raise exception 'native terminal receipt conflict'; end if;
  return public.custodial_activation_public_status(a);
 end if;
 if a.state not in ('prepared','delivered','delivery_unknown') or a.claimant_credential_id is null
  then raise exception 'native activation is not pending'; end if;
 select * into e from public.device_auth_enrollment_operations where operation_id=p_operation;
 if p_receipt->>'outcome'='active' and p_receipt->'changed'='true'::jsonb then
  if e.operation_id is null or e.device_id is distinct from p_device or e.credential_id is distinct from p_credential
   or e.flow is distinct from p_receipt->>'flow' or e.status<>'confirmed' or e.enrollment_id is distinct from a.enrollment_id
   then raise exception 'native active requires exact confirmed enrollment'; end if;
  outcome:='native_active';
 elsif p_receipt->>'outcome'='not_required' and p_receipt->'changed'='false'::jsonb then
  if e.operation_id is not null or c.created_at>=a.requested_at or not exists(
   select 1 from public.device_auth_enrollment_codes where enrollment_id=a.enrollment_id and consumed_at is null)
   then raise exception 'not required must preserve an existing healthy credential'; end if;
  outcome:='not_required';
 else raise exception 'invalid native activation outcome'; end if;
 update public.device_auth_enrollment_codes set revoked_at=coalesce(revoked_at,now())
  where enrollment_id=a.enrollment_id and consumed_at is null;
 update public.custodial_assigned_activation_operations set state=outcome,state_version=state_version+1,
  native_receipt=p_receipt,terminal_at=now(),token_envelope=null,last_error_code=null
  where operation_id=p_operation returning * into a;
 return public.custodial_activation_public_status(a);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_activation_read(p_operation uuid, p_manager uuid, p_requester uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.custodial_assigned_activation_operations%rowtype;
begin
 perform public.custodial_begin_application_mutation();
 perform public.custodial_activation_assert_manager(p_manager,p_requester);
 select * into strict a from public.custodial_assigned_activation_operations where operation_id=p_operation;
 if a.requester_manager_id is distinct from p_manager then raise exception using errcode='42501',message='activation belongs to another manager'; end if;
 perform 1 from public.devices where id=a.device_id for update;
 perform public.custodial_activation_expire_device(a.device_id);
 select * into strict a from public.custodial_assigned_activation_operations where operation_id=p_operation;
 return public.custodial_activation_public_status(a);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_activation_request(p_operation uuid, p_device text, p_employee uuid, p_epoch bigint, p_manager uuid, p_requester uuid, p_serial_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare d public.devices%rowtype; a public.custodial_assigned_activation_operations%rowtype;
begin
 perform public.custodial_begin_application_mutation();
 perform public.custodial_activation_assert_manager(p_manager,p_requester);
 if p_operation is null or p_employee is null or p_epoch is null or p_serial_sha256 is null then raise exception 'exact activation request required'; end if;
 perform pg_advisory_xact_lock(hashtextextended('custodial-enrollment-operation:'||p_operation::text,0));
 select * into strict d from public.devices where device_id=p_device for update;
 perform public.custodial_activation_expire_device(d.id);
 select * into a from public.custodial_assigned_activation_operations where operation_id=p_operation for update;
 if found then
  if (a.device_id,a.expected_employee_id,a.expected_assignment_epoch,a.requester_manager_id,a.requester_credential_id,a.approved_serial_sha256)
   is distinct from (d.id,p_employee,p_epoch,p_manager,p_requester,p_serial_sha256)
   then raise exception using errcode='40001',message='activation operation conflict'; end if;
  return public.custodial_activation_public_status(a);
 end if;
 if d.active is not true or d.assigned_employee_id is distinct from p_employee or d.assignment_epoch is distinct from p_epoch
  or not exists(select 1 from public.employees where id=p_employee and active and employee_code ~ '^EMP[0-9]+$')
 then raise exception using errcode='40001',message='phone assignment changed or unavailable'; end if;
 insert into public.custodial_assigned_activation_operations(operation_id,device_id,canonical_device_id,
  expected_employee_id,expected_assignment_epoch,requested_action,requester_manager_id,requester_credential_id,approved_serial_sha256)
 values(p_operation,d.id,d.device_id,p_employee,p_epoch,'activate_or_recover',p_manager,p_requester,p_serial_sha256) returning * into a;
 return public.custodial_activation_public_status(a);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_append_session_correction(p_operation_id uuid, p_session_id uuid, p_manager_id uuid, p_reason text, p_backend_execution_secret text, p_corrected_employee_id uuid DEFAULT NULL::uuid, p_corrected_location_id uuid DEFAULT NULL::uuid, p_corrected_device_id uuid DEFAULT NULL::uuid, p_corrected_started_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_corrected_ended_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_fingerprint text;
  v_existing public.custodial_session_corrections%rowtype;
  v_current record;
  v_manager_name text;
  v_employee record;
  v_location record;
  v_device record;
  v_employee_id uuid;
  v_location_id uuid;
  v_device_id uuid;
  v_started_at timestamptz;
  v_ended_at timestamptz;
  v_changed_fields text[];
  v_inserted public.custodial_session_corrections%rowtype;
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  if p_operation_id is null or p_session_id is null or p_manager_id is null
     or length(btrim(coalesce(p_reason,''))) not between 1 and 1000 then
    raise exception using errcode='22023', message='Correction operation, session, named manager, and reason are required';
  end if;

  v_fingerprint := encode(extensions.digest(convert_to(jsonb_build_object(
    'operation_id',p_operation_id,'session_id',p_session_id,'manager_id',p_manager_id,
    'reason',btrim(p_reason),'employee_id',p_corrected_employee_id,'location_id',p_corrected_location_id,
    'device_id',p_corrected_device_id,'started_at',p_corrected_started_at,'ended_at',p_corrected_ended_at
  )::text,'UTF8'),'sha256'),'hex');

  select * into v_existing
  from public.custodial_session_corrections c
  where c.operation_id = p_operation_id;
  if found then
    if v_existing.request_fingerprint is distinct from v_fingerprint then
      raise exception using errcode='23505', message='Correction operation was already used for a different request';
    end if;
    return jsonb_build_object('correction_id',v_existing.correction_id,'session_id',v_existing.session_id,
      'operation_id',v_existing.operation_id,'replayed',true,'changed_fields',v_existing.changed_fields,
      'created_at',v_existing.created_at);
  end if;

  select m.display_name into v_manager_name
  from public.ops_manager_managers m
  where m.manager_id = p_manager_id
    and m.active = true and m.revoked_at is null and m.is_system_principal = false
    and m.roles && array['OPS_MANAGER','CUSTODIAL_MANAGER','DIRECTOR','SECURITY_ADMIN']::text[];
  if not found then
    raise exception using errcode='42501', message='An active named manager is required to correct a cleaning record';
  end if;

  select
    coalesce(c.effective_employee_id,s.employee_id) employee_id,
    coalesce(c.effective_location_id,s.location_id) location_id,
    coalesce(c.effective_device_id,s.device_id) device_id,
    coalesce(c.effective_started_at,s.started_at) started_at,
    coalesce(c.effective_ended_at,s.ended_at) ended_at
  into v_current
  from public.sessions s
  left join lateral (
    select c.* from public.custodial_session_corrections c
    where c.session_id = s.id
    order by c.created_at desc,c.correction_id desc
    limit 1
  ) c on true
  where s.id = p_session_id
  for update of s;
  if not found then
    raise exception using errcode='P0002', message='Cleaning session was not found';
  end if;

  v_employee_id := coalesce(p_corrected_employee_id,v_current.employee_id);
  v_location_id := coalesce(p_corrected_location_id,v_current.location_id);
  v_device_id := coalesce(p_corrected_device_id,v_current.device_id);
  v_started_at := coalesce(p_corrected_started_at,v_current.started_at);
  v_ended_at := coalesce(p_corrected_ended_at,v_current.ended_at);

  v_changed_fields := array_remove(array[
    case when v_employee_id is distinct from v_current.employee_id then 'employee' end,
    case when v_location_id is distinct from v_current.location_id then 'location' end,
    case when v_device_id is distinct from v_current.device_id then 'device' end,
    case when v_started_at is distinct from v_current.started_at then 'started_at' end,
    case when v_ended_at is distinct from v_current.ended_at then 'ended_at' end
  ],null);
  if cardinality(v_changed_fields) = 0 then
    raise exception using errcode='22023', message='Correction must change at least one manager-visible fact';
  end if;
  if v_ended_at is not null and v_ended_at < v_started_at then
    raise exception using errcode='22023', message='Corrected cleaning end time cannot precede its start time';
  end if;

  select e.id,e.display_name into v_employee from public.employees e where e.id = v_employee_id;
  select l.id,l.location_code,l.location_name into v_location from public.locations l where l.id = v_location_id;
  select d.id,d.device_id,d.device_name,d.assignment_epoch into v_device from public.devices d where d.id = v_device_id;
  if v_employee.id is null or v_location.id is null or v_device.id is null then
    raise exception using errcode='23503', message='Corrected employee, location, and phone must exist';
  end if;

  insert into public.custodial_session_corrections(
    operation_id,request_fingerprint,session_id,corrected_by_manager_id,corrected_by_manager_name_snapshot,
    reason,changed_fields,effective_employee_id,effective_employee_name_snapshot,effective_location_id,
    effective_location_code_snapshot,effective_location_name_snapshot,effective_device_id,
    effective_device_identifier_snapshot,effective_device_name_snapshot,effective_assignment_epoch_snapshot,
    effective_started_at,effective_ended_at
  ) values (
    p_operation_id,v_fingerprint,p_session_id,p_manager_id,v_manager_name,btrim(p_reason),v_changed_fields,
    v_employee.id,v_employee.display_name,v_location.id,v_location.location_code,v_location.location_name,
    v_device.id,v_device.device_id,v_device.device_name,v_device.assignment_epoch,v_started_at,v_ended_at
  ) returning * into v_inserted;

  return jsonb_build_object('correction_id',v_inserted.correction_id,'session_id',v_inserted.session_id,
    'operation_id',v_inserted.operation_id,'replayed',false,'changed_fields',v_inserted.changed_fields,
    'created_at',v_inserted.created_at);
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_assert_manager(p_manager_id uuid)
 RETURNS ops_manager_managers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_manager public.ops_manager_managers%rowtype;
begin
  if p_manager_id is null then
    raise exception using errcode = '22023', message = 'Custodial Manager identity is required.';
  end if;
  select * into v_manager
  from public.ops_manager_managers
  where manager_id = p_manager_id
    and active is true
    and revoked_at is null
    and is_system_principal is false
  limit 1;
  if v_manager.manager_id is null or not ('CUSTODIAL_MANAGER' = any(coalesce(v_manager.roles, '{}'::text[]))) then
    raise exception using errcode = '42501', message = 'Custodial Manager access is required.';
  end if;
  return v_manager;
end;
$function$

CREATE OR REPLACE FUNCTION public.custodial_assign_employee_device(p_device_identifier text, p_employee_id uuid DEFAULT NULL::uuid, p_changed_by_manager_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_move_existing boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_manager public.ops_manager_managers%rowtype;
  v_identifier text := upper(regexp_replace(btrim(coalesce(p_device_identifier, '')), '^KIOSK[-_ ]?', 'KIOSK_', 'i'));
  v_device public.devices%rowtype;
  v_old_employee public.employees%rowtype;
  v_new_employee public.employees%rowtype;
  v_new_user public.msg_users%rowtype;
  v_other_device public.devices%rowtype;
  v_alias text;
  v_changed boolean := false;
  v_reason text := left(nullif(btrim(coalesce(p_reason, '')), ''), 500);
begin
  v_manager := public.custodial_assert_manager(p_changed_by_manager_id);
  if v_identifier ~ '^KIOSK_[2-9]$' then
    v_identifier := 'KIOSK_0' || substring(v_identifier from 7);
  end if;
  if v_identifier !~ '^KIOSK_(0[2-9]|10)$' then
    raise exception using errcode = '22023', message = 'Choose an employee kiosk from KIOSK_02 through KIOSK_10.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('custodial-device-assignment:' || v_identifier, 0));
  select * into v_device
  from public.devices
  where upper(device_id) = v_identifier and active is true
  for update;
  if v_device.id is null then
    raise exception using errcode = 'P0002', message = 'Active employee kiosk not found.';
  end if;

  if v_device.assigned_employee_id is not null then
    select * into v_old_employee from public.employees where id = v_device.assigned_employee_id;
  end if;

  if p_employee_id is not null then
    select * into v_new_employee
    from public.employees
    where id = p_employee_id
    for update;
    if v_new_employee.id is null then
      raise exception using errcode = 'P0002', message = 'Employee not found.';
    end if;
    if v_new_employee.active is not true or v_new_employee.role <> 'staff' or v_new_employee.employee_code !~ '^EMP[0-9]+$' then
      raise exception using errcode = '22023', message = 'Only an active Memphis Zoo custodial employee can be assigned to a phone.';
    end if;

    select * into v_new_user
    from public.msg_users
    where employee_id = v_new_employee.id
    for update;
    if v_new_user.id is null then
      if exists (select 1 from public.msg_users where lower(btrim(display_name)) = lower(v_new_employee.display_name)) then
        raise exception using errcode = '23505', message = 'Messenger already contains a different user with this employee name.';
      end if;
      insert into public.msg_users(employee_id, display_name, role, is_active)
      values (v_new_employee.id, v_new_employee.display_name, 'employee', true)
      returning * into v_new_user;
    else
      update public.msg_users
      set display_name = v_new_employee.display_name,
          role = 'employee',
          is_active = true,
          updated_at = now()
      where id = v_new_user.id
      returning * into v_new_user;
    end if;

    select * into v_other_device
    from public.devices
    where assigned_employee_id = v_new_employee.id
      and id <> v_device.id
      and active is true
    order by device_id
    limit 1
    for update;

    if v_other_device.id is not null and not p_move_existing then
      raise exception using errcode = '23505', message = format('%s is already assigned to %s. Confirm moving the employee to this phone.', v_new_employee.display_name, v_other_device.device_id);
    end if;

    if v_other_device.id is not null then
      update public.devices
      set assigned_employee_id = null,
          device_name = 'Unassigned ' || v_other_device.device_id,
          updated_at = now()
      where id = v_other_device.id;

      update public.msg_device_assignments
      set is_active = false,
          notes = 'Phone unassigned by Operations app',
          updated_at = now()
      where upper(device_identifier) = upper(v_other_device.device_id)
         or upper(device_identifier) in (
           select upper(alias_identifier) from public.device_aliases
           where canonical_device_id = v_other_device.id and active is true
         );

      insert into public.custodial_employee_device_assignment_history(
        device_id, device_identifier, previous_employee_id, previous_employee_name,
        new_employee_id, new_employee_name, changed_by_manager_id,
        change_reason, source, metadata_json
      ) values (
        v_other_device.id, v_other_device.device_id, v_new_employee.id, v_new_employee.display_name,
        null, null, v_manager.manager_id,
        coalesce(v_reason, 'moved_to_' || v_device.device_id), 'operations_app',
        jsonb_build_object('moved_to_device', v_device.device_id)
      );
    end if;
  end if;

  v_changed := v_device.assigned_employee_id is distinct from p_employee_id;

  update public.devices
  set assigned_employee_id = p_employee_id,
      device_name = case when p_employee_id is null then 'Unassigned ' || v_device.device_id else v_new_employee.display_name end,
      updated_at = now()
  where id = v_device.id
  returning * into v_device;

  if p_employee_id is null then
    update public.msg_device_assignments
    set is_active = false,
        notes = 'Phone unassigned by Operations app',
        updated_at = now()
    where upper(device_identifier) = upper(v_device.device_id)
       or upper(device_identifier) in (
         select upper(alias_identifier) from public.device_aliases
         where canonical_device_id = v_device.id and active is true
       );
  else
    insert into public.msg_device_assignments(device_identifier, msg_user_id, is_active, notes)
    values (v_device.device_id, v_new_user.id, true, 'Managed by Operations app')
    on conflict (device_identifier) do update
    set msg_user_id = excluded.msg_user_id,
        is_active = true,
        notes = excluded.notes,
        updated_at = now();

    for v_alias in
      select alias_identifier from public.device_aliases
      where canonical_device_id = v_device.id and active is true
    loop
      insert into public.msg_device_assignments(device_identifier, msg_user_id, is_active, notes)
      values (v_alias, v_new_user.id, true, 'Managed alias for ' || v_device.device_id)
      on conflict (device_identifier) do update
      set msg_user_id = excluded.msg_user_id,
          is_active = true,
          notes = excluded.notes,
          updated_at = now();
    end loop;
  end if;

  if v_changed or v_other_device.id is not null then
    insert into public.custodial_employee_device_assignment_history(
      device_id, device_identifier, previous_employee_id, previous_employee_name,
      new_employee_id, new_employee_name, changed_by_manager_id,
      change_reason, source, metadata_json
    ) values (
      v_device.id, v_device.device_id, v_old_employee.id, v_old_employee.display_name,
      v_new_employee.id, v_new_employee.display_name, v_manager.manager_id,
      coalesce(v_reason, case when p_employee_id is null then 'phone_unassigned' else 'phone_reassigned' end),
      'operations_app',
      jsonb_build_object('move_existing', p_move_existing, 'messenger_user_id', v_new_user.id)
    );
  end if;

  return jsonb_build_object(
    'changed', v_changed,
    'device', jsonb_build_object(
      'device_pk', v_device.id,
      'device_id', v_device.device_id,
      'device_name', v_device.device_name,
      'assigned_employee_id', v_device.assigned_employee_id,
      'assigned_employee_name', v_new_employee.display_name
    ),
    'previous_employee', case when v_old_employee.id is null then null else jsonb_build_object('id', v_old_employee.id, 'display_name', v_old_employee.display_name, 'employee_code', v_old_employee.employee_code) end,
    'new_employee', case when v_new_employee.id is null then null else jsonb_build_object('id', v_new_employee.id, 'display_name', v_new_employee.display_name, 'employee_code', v_new_employee.employee_code, 'msg_user_id', v_new_user.id) end,
    'moved_from_device', v_other_device.device_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.custodial_assign_employee_device(p_device_identifier text, p_employee_id uuid, p_changed_by_manager_id uuid, p_reason text, p_move_existing boolean, p_expected_owner_provided boolean, p_expected_current_employee_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_identifier text:=upper(regexp_replace(btrim(coalesce(p_device_identifier,'')),'^KIOSK[-_ ]?','KIOSK_','i'));
  v_current_employee_id uuid;
begin
  perform public.custodial_assert_manager(p_changed_by_manager_id);
  if v_identifier ~ '^KIOSK_[2-9]$' then v_identifier:='KIOSK_0'||substring(v_identifier from 7); end if;
  if p_expected_owner_provided is null then raise exception using errcode='22023',message='expected-owner presence must be explicit'; end if;
  perform pg_advisory_xact_lock(hashtextextended('custodial-device-assignment:'||v_identifier,0));
  select d.assigned_employee_id into v_current_employee_id from public.devices d
  where upper(d.device_id)=v_identifier and d.active=true for update;
  if not found then raise exception using errcode='P0002',message='Active employee kiosk not found.'; end if;
  if p_expected_owner_provided and v_current_employee_id is distinct from p_expected_current_employee_id then
    raise exception using errcode='40001',message='This phone assignment changed. Refresh and try again.';
  end if;
  return public.custodial_assign_employee_device(
    v_identifier,p_employee_id,p_changed_by_manager_id,p_reason,p_move_existing
  );
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_authorize_absence_operations_v1(p_manager_id uuid, p_credential_id uuid, p_device_id text, p_session_access text, p_service_date date, p_publication_id uuid, p_operations jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor jsonb;item jsonb;kind text;op text;slot text;capacity jsonb;source jsonb;slots jsonb;
 target public.weekly_schedule_exception_commands%ROWTYPE;reverse_id uuid;other_reverse uuid;
 start_text text;end_text text;shift_start text;shift_end text;
BEGIN
 actor:=public.custodial_action_actor_v1(p_manager_id,p_credential_id,p_device_id,p_session_access,'manage_absences');
 IF actor->'owner'='true'::jsonb THEN RETURN actor;END IF;
 IF p_service_date IS NULL OR NOT isfinite(p_service_date) OR p_publication_id IS NULL
  OR jsonb_typeof(p_operations) IS DISTINCT FROM 'array' OR jsonb_array_length(p_operations) NOT BETWEEN 1 AND 25 THEN
  RAISE EXCEPTION USING errcode='22023',message='One to 25 dated scheduler operations are required';END IF;
 source:=public.static_weekly_v3_read_publication_source(p_publication_id,p_service_date);
 slots:=source#>'{compiler_input,slots}';
 IF jsonb_typeof(slots) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION USING errcode='42501',message='Published roster source is unavailable';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_operations) LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING errcode='42501',message='Invalid dated scheduler operation';END IF;
  op:=item->>'operation';kind:=coalesce(item->>'exceptionType',item->>'exception_type');
  IF item ? 'exceptionType' AND item ? 'exception_type' AND item->>'exceptionType' IS DISTINCT FROM item->>'exception_type' THEN
   RAISE EXCEPTION USING errcode='42501',message='Conflicting operation type';END IF;
  IF op IN ('cover_all','contractor_capacity') THEN
   slot:=coalesce(item->>'slotId',item->>'slot_id');
   IF item ? 'slotId' AND item ? 'slot_id' AND item->>'slotId' IS DISTINCT FROM item->>'slot_id' THEN
    RAISE EXCEPTION USING errcode='42501',message='Conflicting contractor slot';END IF;
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(slots) s WHERE s->>'id'=slot AND s->'contractorCapacity'='true'::jsonb) THEN
    RAISE EXCEPTION USING errcode='42501',message='CoverAll changes require an existing contractor-capacity slot';END IF;
   IF item-'operation'-'slotId'-'slot_id'-'shift'-'reason'-'breakChoice'<>'{}'::jsonb
    OR jsonb_typeof(item->'shift') IS DISTINCT FROM 'object' OR (item->'shift')-'start'-'end'<>'{}'::jsonb
    OR coalesce(item#>>'{shift,start}','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
    OR coalesce(item#>>'{shift,end}','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
    OR item#>>'{shift,start}'>=item#>>'{shift,end}' OR (item ? 'breakChoice' AND item->>'breakChoice' IS DISTINCT FROM 'NONE') THEN
    RAISE EXCEPTION USING errcode='42501',message='Only actual dated contractor shift fields are delegated';END IF;
  ELSIF op='exception' AND kind IN ('daily_absence','partial_absence','pto') THEN
   slot:=item#>>'{payload,slotId}';
   IF jsonb_typeof(item->'payload') IS DISTINCT FROM 'object' OR (item->'payload')-'slotId'<>'{}'::jsonb
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(slots) s WHERE s->>'id'=slot AND s->'contractorCapacity' IS DISTINCT FROM 'true'::jsonb) THEN
    RAISE EXCEPTION USING errcode='42501',message='Absence changes require an existing employee slot';END IF;
  ELSIF op='exception' AND kind='lunch' THEN
   slot:=item#>>'{payload,slotId}';capacity:=NULL;
   SELECT x INTO capacity FROM jsonb_array_elements(p_operations) x
    WHERE x->>'operation' IN ('cover_all','contractor_capacity') AND coalesce(x->>'slotId',x->>'slot_id')=slot LIMIT 1;
   start_text:=coalesce(item->>'startsAt',item->>'starts_at');end_text:=coalesce(item->>'endsAt',item->>'ends_at');
   shift_start:=capacity#>>'{shift,start}';shift_end:=capacity#>>'{shift,end}';
   IF capacity IS NULL OR capacity->>'breakChoice'='NONE' OR jsonb_typeof(item->'payload') IS DISTINCT FROM 'object'
    OR (item->'payload')-'slotId'<>'{}'::jsonb OR coalesce(start_text,'') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
    OR coalesce(end_text,'') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
    OR start_text<shift_start OR end_text>shift_end OR end_text::time<=start_text::time THEN
    RAISE EXCEPTION USING errcode='42501',message='Only the actual positive lunch window within dated CoverAll capacity is delegated';END IF;
  ELSIF op='exception' AND kind='reverse' THEN
   reverse_id:=nullif(coalesce(item->>'reversesExceptionId',item->>'reverses_exception_id',item#>>'{payload,reversesExceptionId}'),'')::uuid;
   other_reverse:=nullif(item#>>'{payload,reversesExceptionId}','')::uuid;
   IF reverse_id IS NULL OR (other_reverse IS NOT NULL AND other_reverse<>reverse_id) THEN
    RAISE EXCEPTION USING errcode='42501',message='Conflicting or missing reversal identity';END IF;
   SELECT * INTO target FROM public.weekly_schedule_exception_commands WHERE exception_id=reverse_id FOR SHARE;
   IF target.exception_id IS NULL OR target.service_date IS DISTINCT FROM p_service_date OR target.publication_id IS DISTINCT FROM p_publication_id
    OR target.exception_type NOT IN ('daily_absence','partial_absence','pto','cover_all','lunch') THEN
    RAISE EXCEPTION USING errcode='42501',message='Only an absence or CoverAll change on this published day may be reversed';END IF;
   IF target.exception_type='lunch' THEN
    slot:=target.payload_json->>'slotId';
    IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(slots) s WHERE s->>'id'=slot AND s->'contractorCapacity'='true'::jsonb) THEN
     RAISE EXCEPTION USING errcode='42501',message='Employee lunch changes remain owner-only';END IF;
   END IF;
  ELSE RAISE EXCEPTION USING errcode='42501',message='Only dated absences and CoverAll changes are delegated';
  END IF;
 END LOOP;
 RETURN actor;
END $function$

CREATE OR REPLACE FUNCTION public.custodial_authorize_coverage_operations_v2(p_manager_id uuid, p_credential_id uuid, p_device_id text, p_session_access text, p_service_date date, p_publication_id uuid, p_operations jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor jsonb; item jsonb; kind text; source jsonb; slot_id text;
 ordinary jsonb := '[]'::jsonb; capacity jsonb; lunch jsonb;
 shift_start time; shift_end time; lunch_start time; lunch_end time;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();
 actor:=public.custodial_action_actor_v1(p_manager_id,p_credential_id,p_device_id,p_session_access,'manage_absences');
 IF (actor->>'owner')::boolean THEN RETURN actor; END IF;
 IF jsonb_typeof(p_operations) IS DISTINCT FROM 'array' OR jsonb_array_length(p_operations) NOT BETWEEN 1 AND 25 THEN
  RAISE EXCEPTION USING errcode='22023',message='One to 25 coverage operations are required';
 END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_operations) LOOP
  kind:=item->>'exceptionType';
  IF item->>'operation'='cover_all' THEN
   IF item-ARRAY['operation','slotId','shift','reason']<>'{}'::jsonb
     OR jsonb_typeof(item->'shift') IS DISTINCT FROM 'object'
     OR (item->'shift')-ARRAY['start','end']<>'{}'::jsonb
     OR coalesce(item#>>'{shift,start}','')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$'
     OR coalesce(item#>>'{shift,end}','')!~'^(([01][0-9]|2[0-3]):[0-5][0-9]|24:00)$' THEN
    RAISE EXCEPTION USING errcode='42501',message='CoverAll requires one explicit valid shift';
   END IF;
   slot_id:=item->>'slotId';
   IF source IS NULL THEN source:=public.static_weekly_v3_read_publication_source(p_publication_id,p_service_date); END IF;
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(source#>'{compiler_input,slots}') s
      WHERE s->>'id'=slot_id AND s->>'contractorCapacity'='true'
      AND EXISTS(SELECT 1 FROM jsonb_array_elements(s->'contractorAvailability') a
       WHERE (a->>'dayOfWeek')::integer=extract(dow FROM p_service_date)::integer)) THEN
    RAISE EXCEPTION USING errcode='42501',message='CoverAll must use registered contractor capacity on this date';
   END IF;
   IF (SELECT count(*) FROM jsonb_array_elements(p_operations) x WHERE x->>'operation'='cover_all' AND x->>'slotId'=slot_id)<>1
     OR (SELECT count(*) FROM jsonb_array_elements(p_operations) x WHERE x->>'operation'='exception' AND x->>'exceptionType'='lunch' AND x#>>'{payload,slotId}'=slot_id)<>1 THEN
    RAISE EXCEPTION USING errcode='42501',message='Each CoverAll addition requires exactly one recorded lunch';
   END IF;
   SELECT x INTO lunch FROM jsonb_array_elements(p_operations) x WHERE x->>'operation'='exception' AND x->>'exceptionType'='lunch' AND x#>>'{payload,slotId}'=slot_id;
   shift_start:=(item#>>'{shift,start}')::time;shift_end:=(item#>>'{shift,end}')::time;
   IF coalesce(lunch->>'startsAt','')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$'
     OR coalesce(lunch->>'endsAt','')!~'^(([01][0-9]|2[0-3]):[0-5][0-9]|24:00)$' THEN
    RAISE EXCEPTION USING errcode='42501',message='CoverAll lunch requires actual start and end times';
   END IF;
   lunch_start:=(lunch->>'startsAt')::time;lunch_end:=(lunch->>'endsAt')::time;
   IF shift_start>=shift_end OR lunch_start<shift_start OR lunch_end>shift_end OR lunch_end<=lunch_start THEN
    RAISE EXCEPTION USING errcode='42501',message='CoverAll lunch must be a positive actual window within the recorded shift';
   END IF;
  ELSIF item->>'operation'='exception' AND kind='lunch' THEN
   IF (item->'payload')-ARRAY['slotId']<>'{}'::jsonb OR item->>'reversesExceptionId' IS NOT NULL
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_operations) x WHERE x->>'operation'='cover_all' AND x->>'slotId'=item#>>'{payload,slotId}') THEN
    RAISE EXCEPTION USING errcode='42501',message='Delegated lunch must belong to the CoverAll addition in this batch';
   END IF;
  ELSE
   ordinary:=ordinary||jsonb_build_array(item);
  END IF;
 END LOOP;
 IF jsonb_array_length(ordinary)>0 THEN
  PERFORM public.custodial_authorize_absence_operations_v1(p_manager_id,p_credential_id,p_device_id,p_session_access,p_service_date,p_publication_id,ordinary);
 END IF;
 RETURN actor;
END $function$

CREATE OR REPLACE FUNCTION public.custodial_authorize_route_regeneration_v1(p_manager_id uuid, p_credential_id uuid, p_device_id text, p_session_access text, p_week_start date, p_publication_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor jsonb;snapshot jsonb;
BEGIN
 actor:=public.custodial_action_actor_v1(p_manager_id,p_credential_id,p_device_id,p_session_access,'regenerate_routes');
 IF p_week_start IS NULL OR NOT isfinite(p_week_start) OR extract(isodow FROM p_week_start)<>1 OR p_publication_id IS NULL THEN
  RAISE EXCEPTION USING errcode='22023',message='Current published week is required';END IF;
 snapshot:=public.static_weekly_v3_read_manager_snapshot(p_week_start);
 IF snapshot#>>'{current_publication,publication_id}' IS DISTINCT FROM p_publication_id::text THEN
  RAISE EXCEPTION USING errcode='40001',message='Published schedule changed; refresh before regenerating routes';END IF;
 RETURN actor;
END $function$

CREATE OR REPLACE FUNCTION public.custodial_begin_application_mutation_lease(p_request_id uuid, p_service_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'custodial_dr'
AS $function$
declare
  v_generation bigint;
  v_paused boolean;
begin
  if p_request_id is null or length(btrim(coalesce(p_service_name, ''))) not between 1 and 120 then
    raise exception using errcode = '22023', message = 'application mutation lease identity is required';
  end if;
  perform pg_catalog.pg_advisory_xact_lock_shared(
    pg_catalog.hashtextextended('memphis-zoo-application-mutation-admission', 0)
  );
  select authority_generation,mutations_paused into v_generation,v_paused
  from custodial_dr.restore_control where singleton=true;
  if v_generation is null then
    raise exception using errcode = '55000', message = 'disaster recovery mutation authority is unavailable';
  end if;
  if v_paused then
    raise exception using errcode = '55000', message = 'disaster recovery is in progress; application mutations are paused';
  end if;
  insert into custodial_dr.application_mutation_leases(
    request_id,authority_generation,service_name,admitted_at,heartbeat_at,expires_at
  ) values (
    p_request_id,v_generation,btrim(p_service_name),clock_timestamp(),clock_timestamp(),clock_timestamp()+interval '3 minutes'
  );
  return jsonb_build_object(
    'request_id',p_request_id,
    'authority_generation',v_generation,
    'mutations_paused',false,
    'expires_at',(select expires_at from custodial_dr.application_mutation_leases where request_id=p_request_id)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_bootstrap_restore_release_authority(p_manager_id uuid, p_request_id uuid, p_device_identifier text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_definition public.custodial_release_authority_bootstrap_definitions%rowtype; v_device text:=upper(btrim(coalesce(p_device_identifier,''))); v_secret_digest text;
begin
  select execution_secret_digest into v_secret_digest from public.custodial_backend_execution_config where config_key=true and enabled=true;
  if v_secret_digest is null or length(coalesce(p_backend_execution_secret,''))<32 or encode(extensions.digest(convert_to(p_backend_execution_secret,'UTF8'),'sha256'),'hex')<>v_secret_digest then raise exception using errcode='42501',message='backend execution secret is not authorized'; end if;
  if p_request_id is null or v_device !~ '^KIOSK_(0[2-9]|10)$' or not coalesce((select paused from public.custodial_release_canary_controls where device_identifier=v_device),false) then raise exception using errcode='55000',message='the exact release canary must be paused before bootstrap restoration'; end if;
  if not exists(select 1 from public.ops_manager_managers m where m.manager_id=p_manager_id and m.active and m.revoked_at is null and m.roles && array['DIRECTOR','SECURITY_ADMIN']::text[]) then raise exception using errcode='42501',message='named release manager authority is required'; end if;
  select * into v_definition from public.custodial_release_authority_bootstrap_definitions where bootstrap_key=true;
  if v_definition.function_identity is null or encode(extensions.digest(convert_to(v_definition.function_definition,'UTF8'),'sha256'),'hex')<>v_definition.definition_sha256 then raise exception using errcode='23514',message='bootstrap controller definition failed its digest'; end if;
  execute v_definition.function_definition;
  execute 'revoke all on function public.custodial_control_release_canary(uuid,uuid,text,text,text,jsonb,text) from public,anon,authenticated,service_role';
  execute 'grant execute on function public.custodial_control_release_canary(uuid,uuid,text,text,text,jsonb,text) to postgres,service_role';
  return jsonb_build_object('restored_controller',v_definition.function_identity,'canary_paused',true,'request_id',p_request_id);
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_claim_offline_reconciliation_notification_recipients(p_outbox_id uuid, p_worker_id text, p_outbox_lease_token uuid, p_recipients jsonb, p_backend_execution_secret text)
 RETURNS TABLE(delivery_recipient_id uuid, manager_id uuid, recipient_user_id uuid, client_message_id text, notification_instance_key text, attempts integer, lease_token uuid, lease_expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_outbox public.custodial_offline_reconciliation_outbox%rowtype;
  v_worker_id text := nullif(btrim(coalesce(p_worker_id,'')), '');
  v_expected integer;
  v_inserted integer;
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  if v_worker_id is null or length(v_worker_id)>200 or p_outbox_id is null then raise exception using errcode='22023',message='a bounded worker and notification identity are required'; end if;
  select * into v_outbox from public.custodial_offline_reconciliation_outbox where outbox_id=p_outbox_id for update;
  if v_outbox.outbox_id is null then raise exception using errcode='P0002',message='offline reconciliation notification was not found'; end if;
  if v_outbox.state<>'claimed' or v_outbox.claimed_by<>v_worker_id or v_outbox.lease_token is distinct from p_outbox_lease_token or v_outbox.lease_expires_at<=now() then
    raise exception using errcode='40901',message='notification claim is no longer owned by this worker';
  end if;
  if not exists(select 1 from public.custodial_offline_reconciliation_delivery_recipients where outbox_id=p_outbox_id) then
    if jsonb_typeof(coalesce(p_recipients,'null'::jsonb))<>'array' or jsonb_array_length(p_recipients) not between 1 and 100 then
      raise exception using errcode='22023',message='one to one hundred authoritative named-manager recipients are required';
    end if;
    select count(*) into v_expected from (
      select distinct input.manager_id,input.user_id from jsonb_to_recordset(p_recipients) as input(manager_id uuid,user_id uuid)
    ) candidates;
    insert into public.custodial_offline_reconciliation_delivery_recipients(
      outbox_id,manager_id,recipient_user_id,client_message_id,notification_instance_key
    )
    select p_outbox_id,c.manager_id,c.user_id,
      'offline-reconciliation:'||p_outbox_id::text||':'||c.user_id::text,
      'offline-reconciliation:'||p_outbox_id::text||':'||c.user_id::text
    from (select distinct input.manager_id,input.user_id from jsonb_to_recordset(p_recipients) as input(manager_id uuid,user_id uuid)) c
    join public.ops_manager_managers m on m.manager_id=c.manager_id and m.active=true and m.revoked_at is null and m.is_system_principal=false
    join public.msg_users u on u.id=c.user_id and u.ops_manager_id=m.manager_id and coalesce(u.is_active,true)=true;
    get diagnostics v_inserted=row_count;
    if v_inserted<>v_expected then raise exception using errcode='42501',message='notification recipients must be active named-manager Messenger identities'; end if;
    insert into public.custodial_offline_reconciliation_delivery_events(outbox_id,delivery_recipient_id,event_type,evidence_json)
      select p_outbox_id,r.delivery_recipient_id,'recipient_declared',jsonb_build_object('manager_id',r.manager_id,'recipient_user_id',r.recipient_user_id,'client_message_id',r.client_message_id)
      from public.custodial_offline_reconciliation_delivery_recipients r where r.outbox_id=p_outbox_id;
  end if;
  with exhausted as (
    update public.custodial_offline_reconciliation_delivery_recipients r
    set state='failed',failed_at=now(),claimed_by=null,lease_token=null,claimed_at=null,lease_expires_at=null,
      last_error='recipient delivery lease expired after maximum attempts'
    where r.outbox_id=p_outbox_id and r.state='claimed' and r.lease_expires_at<=now() and r.attempts>=5
    returning r.delivery_recipient_id,r.attempts
  ) insert into public.custodial_offline_reconciliation_delivery_events(outbox_id,delivery_recipient_id,event_type,attempt,error_text,evidence_json)
    select p_outbox_id,e.delivery_recipient_id,'recipient_lease_exhausted',e.attempts,'recipient delivery lease expired after maximum attempts',jsonb_build_object('terminal',true) from exhausted e;
  with reclaimed as (
    update public.custodial_offline_reconciliation_delivery_recipients r
    set state='retry',claimed_by=null,lease_token=null,claimed_at=null,lease_expires_at=null,next_attempt_at=now(),
      last_error=coalesce(nullif(r.last_error,''),'recipient delivery lease expired')
    where r.outbox_id=p_outbox_id and r.state='claimed' and r.lease_expires_at<=now() and r.attempts<5
    returning r.delivery_recipient_id,r.attempts
  ) insert into public.custodial_offline_reconciliation_delivery_events(outbox_id,delivery_recipient_id,event_type,attempt,error_text,evidence_json)
    select p_outbox_id,r.delivery_recipient_id,'recipient_lease_reclaimed',r.attempts,'recipient delivery lease expired',jsonb_build_object('requeued',true) from reclaimed r;
  return query
  with candidates as (
    select r.delivery_recipient_id from public.custodial_offline_reconciliation_delivery_recipients r
    where r.outbox_id=p_outbox_id and r.state in ('pending','retry') and r.next_attempt_at<=now() and r.attempts<5
    order by r.created_at,r.delivery_recipient_id for update skip locked
  ), claimed as (
    update public.custodial_offline_reconciliation_delivery_recipients r
    set state='claimed',claimed_by=v_worker_id,lease_token=gen_random_uuid(),claimed_at=now(),lease_expires_at=least(v_outbox.lease_expires_at,now()+interval '120 seconds'),attempts=r.attempts+1
    from candidates c where r.delivery_recipient_id=c.delivery_recipient_id returning r.*
  ), evidence as (
    insert into public.custodial_offline_reconciliation_delivery_events(outbox_id,delivery_recipient_id,event_type,attempt,worker_id,evidence_json)
    select p_outbox_id,c.delivery_recipient_id,'recipient_claimed',c.attempts,v_worker_id,jsonb_build_object('lease_token',c.lease_token,'lease_expires_at',c.lease_expires_at) from claimed c
  )
  select c.delivery_recipient_id,c.manager_id,c.recipient_user_id,c.client_message_id,c.notification_instance_key,c.attempts,c.lease_token,c.lease_expires_at from claimed c;
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_close_maintenance_ticket_authoritative(p_ticket_id uuid, p_closed_by text, p_close_notes text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_closed_by text := nullif(left(btrim(coalesce(p_closed_by,'')),200),'');
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  if p_ticket_id is null or v_closed_by is null then raise exception using errcode='22023',message='ticket identity and named closer are required'; end if;
  return public.close_maintenance_ticket(p_ticket_id,v_closed_by,nullif(left(btrim(coalesce(p_close_notes,'')),1000),''));
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_close_scan_ticket_outcome_v1(p_manager_id uuid, p_credential_id uuid, p_device_id text, p_session_access text, p_ticket_id uuid, p_outcome text, p_external_work_order_reference text, p_close_notes text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor jsonb;ticket public.maintenance_tickets%rowtype;provenance_id uuid;result jsonb;
 requested_reference text:=nullif(btrim(coalesce(p_external_work_order_reference,'')),'');
 requested_notes text:=nullif(btrim(coalesce(p_close_notes,'')),'');
BEGIN
 PERFORM public.custodial_require_backend_execution_secret(p_backend_execution_secret);
 actor:=public.custodial_action_actor_v1(p_manager_id,p_credential_id,p_device_id,p_session_access,'close_scan_tickets');
 IF p_outcome IS NULL OR p_outcome NOT IN ('mark_fixed','work_order_sent')
  OR (p_outcome='work_order_sent' AND (requested_reference IS NULL OR length(requested_reference)>120))
  OR (p_outcome='mark_fixed' AND requested_reference IS NOT NULL)
  OR length(coalesce(requested_notes,''))>1000 THEN
  RAISE EXCEPTION USING errcode='22023',message='Choose fixed or provide the reference for an already submitted work order';END IF;
 SELECT * INTO ticket FROM public.maintenance_tickets WHERE id=p_ticket_id FOR UPDATE;
 IF ticket.id IS NULL THEN RAISE EXCEPTION USING errcode='P0002',message='Ticket not found';END IF;
 IF NOT (actor->>'owner')::boolean THEN
  SELECT s.id INTO provenance_id FROM public.completion_responses r JOIN public.sessions s ON s.id=r.session_id
   WHERE r.id=ticket.completion_response_id AND s.id=ticket.session_id AND ticket.issue_source='completion_form'
    AND ticket.location_id=r.location_id AND r.location_id=s.location_id
    AND ticket.device_id=r.device_id AND r.device_id=s.device_id
    AND ticket.reported_by_employee_id=r.submitted_by_employee_id AND r.submitted_by_employee_id=s.employee_id FOR SHARE OF r,s;
  IF provenance_id IS NULL THEN RAISE EXCEPTION USING errcode='42501',message='Delegated closure requires a verified scan-session ticket';END IF;
 END IF;
 IF ticket.status='closed' THEN
  IF ticket.resolution_outcome IS DISTINCT FROM p_outcome OR ticket.external_work_order_reference IS DISTINCT FROM requested_reference
   OR nullif(btrim(coalesce(ticket.close_notes,'')),'') IS DISTINCT FROM requested_notes THEN
   RAISE EXCEPTION USING errcode='40901',message='Ticket already has a different recorded outcome; refresh instead of replacing history';END IF;
  RETURN jsonb_build_object('ticket_id',ticket.id,'status','closed','closed_at',ticket.closed_at,'closed_by',ticket.closed_by,
   'outcome',ticket.resolution_outcome,'external_work_order_reference',ticket.external_work_order_reference,
   'actor_manager_id',ticket.resolution_actor_manager_id,'replayed',true);
 END IF;
 result:=public.custodial_set_maintenance_ticket_outcome(p_ticket_id,p_outcome,p_manager_id,requested_reference,requested_notes,p_backend_execution_secret);
 INSERT INTO public.ops_manager_auth_events(credential_id,device_id,event_type,success,detail_json)
  VALUES(p_credential_id,p_device_id,'scan_ticket_outcome_recorded',true,jsonb_build_object('ticket_id',p_ticket_id,
   'manager_id',p_manager_id,'outcome',p_outcome,'owner',(actor->>'owner')::boolean));
 RETURN result||jsonb_build_object('closed_at',result->'recorded_at','closed_by',result->'actor_name','replayed',false);
END $function$

CREATE OR REPLACE FUNCTION public.custodial_close_scan_ticket_v1(p_manager_id uuid, p_credential_id uuid, p_device_id text, p_session_access text, p_ticket_id uuid, p_close_notes text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor jsonb; ticket public.maintenance_tickets%ROWTYPE; provenance_id uuid; result jsonb;
BEGIN
  PERFORM public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  actor:=public.custodial_action_actor_v1(p_manager_id,p_credential_id,p_device_id,p_session_access,'close_scan_tickets');
  SELECT * INTO ticket FROM public.maintenance_tickets WHERE id=p_ticket_id FOR UPDATE;
  IF ticket.id IS NULL THEN RAISE EXCEPTION USING errcode='P0002',message='Ticket not found'; END IF;
  IF NOT (actor->>'owner')::boolean THEN
    SELECT s.id INTO provenance_id
      FROM public.completion_responses r JOIN public.sessions s ON s.id=r.session_id
      WHERE r.id=ticket.completion_response_id AND s.id=ticket.session_id
        AND ticket.issue_source='completion_form'
        AND ticket.location_id=r.location_id AND r.location_id=s.location_id
        AND ticket.device_id=r.device_id AND r.device_id=s.device_id
        AND ticket.reported_by_employee_id=r.submitted_by_employee_id AND r.submitted_by_employee_id=s.employee_id
      FOR SHARE OF r,s;
    IF provenance_id IS NULL THEN
      RAISE EXCEPTION USING errcode='42501',message='Delegated closure requires a verified scan-session ticket';
    END IF;
  END IF;
  IF ticket.status='closed' THEN
    RETURN jsonb_build_object('ticket_id',ticket.id,'status',ticket.status,'closed_by',ticket.closed_by,
      'closed_at',ticket.closed_at,'closed_via',ticket.closed_via,'replayed',true);
  END IF;
  result:=public.custodial_close_maintenance_ticket_authoritative(ticket.id,
    'manager:'||p_manager_id::text||':'||left(actor->>'manager_name',155),left(p_close_notes,1000),p_backend_execution_secret);
  INSERT INTO public.ops_manager_auth_events(credential_id,device_id,event_type,success,detail_json)
    VALUES(p_credential_id,p_device_id,'scan_ticket_closed',true,jsonb_build_object('ticket_id',ticket.id,'manager_id',p_manager_id,'owner',(actor->>'owner')::boolean));
  RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.custodial_commit_offline_occurrence(p_client_session_id text, p_client_completion_id text, p_device_id text, p_location_code text, p_client_started_at text, p_client_ended_at text, p_response_json jsonb, p_scan_evidence jsonb, p_correlation_id text, p_context_id text, p_submission_proof text, p_authenticated_credential_id text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_client_session_id text := nullif(btrim(coalesce(p_client_session_id,'')), '');
  v_client_completion_id text := nullif(btrim(coalesce(p_client_completion_id,'')), '');
  v_context_id uuid;
  v_credential_id uuid;
  v_started_at timestamptz;
  v_ended_at timestamptz;
  v_context public.custodial_offline_actor_contexts%rowtype;
  v_proof public.custodial_offline_submission_proofs%rowtype;
  v_existing public.custodial_offline_reconciliation_records%rowtype;
  v_device public.devices%rowtype;
  v_employee public.employees%rowtype;
  v_credential public.device_auth_credentials%rowtype;
  v_location record;
  v_session public.sessions%rowtype;
  v_completion_response_id uuid;
  v_submitted_at timestamptz;
  v_ticket_count integer := 0;
  v_payload_fingerprint text;
  v_result jsonb;
  v_item jsonb;
  v_event_type text;
  v_event_id text;
  v_event_time timestamptz;
  v_event_fingerprint text;
  v_event_ids text[] := array[]::text[];
  v_reconciliation_id uuid;
  v_failure_detail text;
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  select session.* into v_session
  from public.sessions session
  where session.client_session_id=v_client_session_id and session.status='cancelled'
  limit 1;
  if v_session.id is not null then
    if not exists(
      select 1
      from public.custodial_offline_actor_contexts context
      join public.locations location on location.id=context.location_id
      join public.devices device on device.id=context.device_id
      where context.context_id::text=lower(btrim(coalesce(p_context_id,'')))
        and context.client_session_id=v_client_session_id
        and context.status='cancelled'
        and context.location_id=v_session.location_id
        and context.employee_id=v_session.employee_id
        and context.device_id=v_session.device_id
        and location.location_code=public.resolve_scan_location_code(p_location_code)
        and (
          upper(btrim(device.device_id))=upper(btrim(coalesce(p_device_id,'')))
          or exists(
            select 1 from public.device_aliases alias
            where alias.canonical_device_id=device.id and alias.active=true
              and upper(btrim(alias.alias_identifier))=upper(btrim(coalesce(p_device_id,'')))
          )
        )
    ) then
      raise exception using errcode='23514',message='Cancelled session does not match the frozen offline occurrence';
    end if;
    return jsonb_build_object(
      'status','cancelled','terminal',true,'discard_local_workflow',true,
      'reason','offline_context_expired','session_uuid',v_session.session_uuid,
      'client_session_id',v_session.client_session_id,
      'client_completion_id',v_client_completion_id,
      'started_at',v_session.started_at,'ended_at',v_session.ended_at,
      'duration_minutes',v_session.duration_minutes,
      'duration_display',v_session.duration_display,'replayed',true
    );
  end if;
  if v_client_session_id is null or length(v_client_session_id)>200 or v_client_completion_id is null or length(v_client_completion_id)>200 then
    return public.custodial_quarantine_offline_submission(p_client_session_id,p_client_completion_id,null,null,
      jsonb_build_object('response_json',coalesce(p_response_json,'null'::jsonb),'scan_evidence',coalesce(p_scan_evidence,'null'::jsonb)),
      'invalid_stable_submission_identity','{}'::jsonb,p_backend_execution_secret);
  end if;
  if jsonb_typeof(p_response_json) is distinct from 'object' or pg_column_size(coalesce(p_response_json,'null'::jsonb))>1048576
     or jsonb_typeof(p_scan_evidence) is distinct from 'array' or coalesce(jsonb_array_length(p_scan_evidence),0)>100
     or pg_column_size(coalesce(p_scan_evidence,'null'::jsonb))>1048576 then
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,null,null,
      jsonb_build_object('response_json',coalesce(p_response_json,'null'::jsonb),'scan_evidence',coalesce(p_scan_evidence,'null'::jsonb)),
      'invalid_payload_shape_or_bounds','{}'::jsonb,p_backend_execution_secret);
  end if;
  begin
    v_context_id := nullif(lower(btrim(coalesce(p_context_id,''))), '')::uuid;
    v_credential_id := nullif(lower(btrim(coalesce(p_authenticated_credential_id,''))), '')::uuid;
    v_started_at := nullif(btrim(coalesce(p_client_started_at,'')), '')::timestamptz;
    v_ended_at := nullif(btrim(coalesce(p_client_ended_at,'')), '')::timestamptz;
  exception when others then
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,null,null,
      jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'malformed_authority_or_timestamp',jsonb_build_object('context_id',p_context_id,'credential_id',p_authenticated_credential_id),p_backend_execution_secret);
  end;
  if not isfinite(v_started_at) or not isfinite(v_ended_at) or v_ended_at<=v_started_at or v_ended_at>now()+interval '10 minutes'
     or v_started_at<now()-interval '7 days' or v_ended_at-v_started_at>interval '24 hours' then
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,v_context_id,null,
      jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'invalid_occurrence_timestamps','{}'::jsonb,p_backend_execution_secret);
  end if;
  perform public.custodial_lock_offline_reconciliation_keys(v_client_session_id,v_client_completion_id);
  select * into v_context from public.custodial_offline_actor_contexts where context_id=v_context_id for update;
  if v_context.context_id is null then
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,null,null,jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'offline_actor_context_not_found','{}'::jsonb,p_backend_execution_secret);
  end if;
  if not public.custodial_credential_may_transmit_frozen_work(v_context.credential_id,v_credential_id,v_context.device_id) then
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,v_context.context_id,null,
      jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'context_binding_mismatch','{}'::jsonb,p_backend_execution_secret);
  end if;
  v_payload_fingerprint := public.custodial_offline_payload_fingerprint(v_context,v_client_completion_id,v_started_at,v_ended_at,p_response_json,p_scan_evidence,p_correlation_id);
  select * into v_existing from public.custodial_offline_reconciliation_records where client_completion_id=v_client_completion_id or client_session_id=v_client_session_id order by case when client_completion_id=v_client_completion_id then 0 else 1 end limit 1 for update;
  if v_existing.reconciliation_id is not null then
    if v_existing.client_session_id=v_client_session_id and v_existing.client_completion_id=v_client_completion_id and v_existing.payload_fingerprint=v_payload_fingerprint then
      insert into public.custodial_offline_reconciliation_audits(reconciliation_id,event_type,evidence_json) values(v_existing.reconciliation_id,'replayed',jsonb_build_object('exact_payload_replay',true));
      return v_existing.result_json || jsonb_build_object('reconciliation_id',v_existing.reconciliation_id,'replayed',true);
    end if;
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,v_context.context_id,v_payload_fingerprint,jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'payload_fingerprint_conflict','{}'::jsonb,p_backend_execution_secret);
  end if;
  if v_context.client_session_id<>v_client_session_id or v_context.status<>'activated' or v_context.expires_at<=now()
     or upper(btrim(coalesce(p_device_id,'')))<>upper((select device_id from public.devices where id=v_context.device_id))
     or public.resolve_scan_location_code(p_location_code)<>v_context.canonical_location_code or v_context.started_at<>v_started_at then
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,v_context.context_id,v_payload_fingerprint,jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'context_binding_mismatch','{}'::jsonb,p_backend_execution_secret);
  end if;
  select * into v_proof from public.custodial_offline_submission_proofs where context_id=v_context.context_id for update;
  if v_proof.state<>'issued' or coalesce(p_submission_proof,'') !~ '^[0-9a-f]{64}$' or encode(extensions.digest(convert_to(lower(p_submission_proof),'UTF8'),'sha256'),'hex')<>v_proof.proof_digest then
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,v_context.context_id,v_payload_fingerprint,jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'submission_proof_invalid','{}'::jsonb,p_backend_execution_secret);
  end if;
  select * into v_device from public.devices where id=v_context.device_id for update;
  select * into v_employee from public.employees where id=v_context.employee_id;
  select * into v_credential from public.device_auth_credentials where credential_id=v_context.credential_id;
  select l.id,l.location_code,l.location_name,l.location_type,l.form_type into v_location from public.locations l where l.id=v_context.location_id;
  if v_device.id is null or v_employee.id is null or v_credential.credential_id is null
     or v_credential.device_id<>v_context.device_id or v_credential.confirmed_at is null
     or v_location.id is null
     or (v_context.snapshot_id is null and (
       v_device.active is not true or v_employee.active is not true
       or v_credential.revoked_at is not null or v_credential.expires_at<=now()
       or not exists(select 1 from public.custodial_employee_device_assignment_history h
         where h.assignment_change_id=v_context.assignment_change_id and h.device_id=v_context.device_id
           and h.new_employee_id=v_context.employee_id)
     ))
     or (v_context.snapshot_id is not null and (
       v_credential.confirmed_at>v_started_at or v_started_at>=v_credential.expires_at
       or v_ended_at>=v_credential.expires_at
       or (v_credential.revoked_at is not null and v_ended_at>=v_credential.revoked_at)
       or not exists(select 1 from public.custodial_employee_device_assignment_history h
         where h.assignment_change_id=v_context.assignment_change_id and h.device_id=v_context.device_id
           and h.new_employee_id=v_context.employee_id and h.changed_at<=v_started_at)
       or exists(select 1 from public.custodial_employee_device_assignment_history h
         where h.device_id=v_context.device_id and h.assignment_change_id<>v_context.assignment_change_id
           and h.changed_at>v_started_at and h.changed_at<=v_ended_at)
     )) then
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,v_context.context_id,v_payload_fingerprint,jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'permanent_actor_or_credential_proof_loss','{}'::jsonb,p_backend_execution_secret);
  end if;
  begin
    for v_item in select value from jsonb_array_elements(p_scan_evidence) loop
      if jsonb_typeof(v_item)<>'object' or pg_column_size(v_item)>65536
         or not (v_item ?& array['client_event_id','event_type','result','notes','scanned_at','payload_json'])
         or exists(select 1 from jsonb_object_keys(v_item) k where k not in ('client_event_id','event_type','result','notes','scanned_at','payload_json'))
         or jsonb_typeof(v_item->'event_type')<>'string' or jsonb_typeof(v_item->'client_event_id')<>'string' or jsonb_typeof(v_item->'scanned_at')<>'string'
         or coalesce(jsonb_typeof(v_item->'result'),'null') not in ('string','null') or coalesce(jsonb_typeof(v_item->'notes'),'null') not in ('string','null')
         or jsonb_typeof(v_item->'payload_json')<>'object' or not ((v_item->'payload_json') ? 'entry_source')
         or exists(select 1 from jsonb_object_keys(v_item->'payload_json') k where k<>'entry_source')
         or (v_item->'payload_json'->>'entry_source') not in ('native-nfc','manual-qr-fallback')
      then raise exception using errcode='22023',message='scan event shape or provenance is invalid'; end if;
      v_event_type := nullif(btrim(v_item->>'event_type'),''); v_event_id := nullif(btrim(v_item->>'client_event_id'),'');
      if v_event_type not in ('scan_received','scan_blocked','scan_start','scan_finish','scan_resume_pending','scan_invalid_location','scan_unauthorized_device','scan_error') or v_event_id is null or length(v_event_id)>200 or length(coalesce(v_item->>'result',''))>200 or length(coalesce(v_item->>'notes',''))>4000 or jsonb_typeof(coalesce(v_item->'payload_json','{}'::jsonb))<>'object' or pg_column_size(coalesce(v_item->'payload_json','{}'::jsonb))>32768 then raise exception using errcode='22023',message='scan event fields are invalid'; end if;
      v_event_time := (v_item->>'scanned_at')::timestamptz;
      if not isfinite(v_event_time) or v_event_time<v_started_at-interval '10 minutes' or v_event_time>v_ended_at+interval '10 minutes' then raise exception using errcode='22023',message='scan event timestamp is outside the occurrence window'; end if;
      if array_position(v_event_ids,v_event_id) is not null then raise exception using errcode='23505',message='duplicate scan event identity in one payload'; end if;
      v_event_ids := array_append(v_event_ids,v_event_id);
    end loop;
  exception when others then
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,v_context.context_id,v_payload_fingerprint,jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'malformed_scan_evidence',jsonb_build_object('detail',sqlerrm),p_backend_execution_secret);
  end;
  for v_event_id in select unnest(v_event_ids) order by 1 loop
    perform pg_advisory_xact_lock(hashtextextended('custodial-offline-event:'||v_event_id,0));
    if exists(select 1 from public.custodial_offline_scan_event_evidence where client_event_id=v_event_id) or exists(select 1 from public.scan_events where client_event_id=v_event_id) then
      return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,v_context.context_id,v_payload_fingerprint,jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'scan_event_identity_already_bound',jsonb_build_object('client_event_id',v_event_id),p_backend_execution_secret);
    end if;
  end loop;
  begin
    insert into public.custodial_offline_time_reservations(occurrence_id,employee_id,device_id,started_at,ended_at) values(v_context.occurrence_id,v_context.employee_id,v_context.device_id,v_started_at,v_ended_at);
    select * into v_session from public.sessions where client_session_id=v_client_session_id for update;
    if v_session.id is null then
      insert into public.sessions(session_uuid,client_session_id,location_id,employee_id,device_id,status,started_at,ended_at,duration_minutes,duration_display,completion_source)
      values(v_client_session_id,v_client_session_id,v_context.location_id,v_context.employee_id,v_context.device_id,'pending_submit',v_started_at,v_ended_at,greatest(0,round(extract(epoch from(v_ended_at-v_started_at))/60.0)::integer),greatest(0,round(extract(epoch from(v_ended_at-v_started_at))/60.0)::integer)::text||' min','kiosk_form') returning * into v_session;
    elsif v_session.device_id<>v_context.device_id or v_session.employee_id<>v_context.employee_id or v_session.location_id<>v_context.location_id or v_session.status not in ('active','pending_submit') then raise exception using errcode='23514',message='server session is not bound to the activated occurrence';
    else
      update public.sessions set status='pending_submit',ended_at=v_ended_at,duration_minutes=greatest(0,round(extract(epoch from(v_ended_at-v_started_at))/60.0)::integer),duration_display=greatest(0,round(extract(epoch from(v_ended_at-v_started_at))/60.0)::integer)::text||' min' where id=v_session.id and status='active';
      select * into v_session from public.sessions where id=v_session.id;
    end if;
    insert into public.completion_responses(session_id,location_id,submitted_by_employee_id,device_id,response_json,submitted_at,client_completion_id) values(v_session.id,v_context.location_id,v_context.employee_id,v_context.device_id,p_response_json,now(),v_client_completion_id) returning id,submitted_at into v_completion_response_id,v_submitted_at;
    v_ticket_count := public.create_maintenance_tickets_from_response(v_completion_response_id,v_session.id,v_context.location_id,v_context.employee_id,v_context.device_id,v_submitted_at,p_response_json);
    update public.sessions set status='closed',completion_source='kiosk_form',updated_at=now() where id=v_session.id and status='pending_submit';
    if not found then raise exception using errcode='40001',message='session did not reach the canonical pending_submit state'; end if;
    v_result := jsonb_build_object('status','closed','terminal',true,'client_session_id',v_client_session_id,'client_completion_id',v_client_completion_id,'session_uuid',v_session.session_uuid,'completion_response_id',v_completion_response_id,'occurrence_id',v_context.occurrence_id,'original_employee_id',v_context.employee_id,'started_at',v_started_at,'ended_at',v_ended_at,'correlation_id',nullif(btrim(coalesce(p_correlation_id,'')),''),'maintenance_ticket_count',v_ticket_count,'replayed',false);
    insert into public.custodial_offline_reconciliation_records(context_id,occurrence_id,occurrence_fingerprint,original_employee_id,device_id,credential_id,location_id,client_session_id,client_completion_id,payload_fingerprint,payload_json,state,result_json,session_id,completion_response_id)
    values(v_context.context_id,v_context.occurrence_id,v_context.occurrence_fingerprint,v_context.employee_id,v_context.device_id,v_context.credential_id,v_context.location_id,v_client_session_id,v_client_completion_id,v_payload_fingerprint,jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'committed',v_result,v_session.id,v_completion_response_id) returning reconciliation_id into v_reconciliation_id;
    for v_item in select value from jsonb_array_elements(p_scan_evidence) loop
      v_event_type := v_item->>'event_type'; v_event_id := btrim(v_item->>'client_event_id'); v_event_time := (v_item->>'scanned_at')::timestamptz;
      v_event_fingerprint := encode(extensions.digest(convert_to(jsonb_build_object('client_event_id',v_event_id,'context_id',v_context.context_id::text,'device_id',v_context.device_id::text,'event_type',v_event_type,'location_id',v_context.location_id::text,'payload_json',coalesce(v_item->'payload_json','{}'::jsonb),'result',nullif(v_item->>'result',''),'scanned_at',v_event_time,'session_id',v_session.id::text,'notes',nullif(v_item->>'notes',''))::text,'UTF8'),'sha256'),'hex');
      insert into public.custodial_offline_scan_event_evidence(client_event_id,context_id,reconciliation_id,session_id,event_fingerprint,event_payload) values(v_event_id,v_context.context_id,v_reconciliation_id,v_session.id,v_event_fingerprint,v_item);
      insert into public.scan_events(scanned_at,location_id,location_code,device_id,device_identifier,session_id,event_type,result,notes,payload_json,client_event_id) values(v_event_time,v_context.location_id,v_context.canonical_location_code,v_context.device_id,v_device.device_id,v_session.id,v_event_type,nullif(v_item->>'result',''),nullif(v_item->>'notes',''),coalesce(v_item->'payload_json','{}'::jsonb)||jsonb_build_object('offline_occurrence_id',v_context.occurrence_id),v_event_id);
    end loop;
    update public.custodial_offline_actor_contexts set status='committed' where context_id=v_context.context_id and status='activated';
    update public.custodial_offline_submission_proofs set state='consumed',consumed_at=now() where context_id=v_context.context_id and state='issued';
    insert into public.custodial_offline_reconciliation_audits(reconciliation_id,event_type,evidence_json) values(v_reconciliation_id,'accepted',jsonb_build_object('occurrence_fingerprint',v_context.occurrence_fingerprint,'payload_fingerprint',v_payload_fingerprint));
  exception when exclusion_violation then
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,v_context.context_id,v_payload_fingerprint,jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'overlapping_employee_or_device_occurrence','{}'::jsonb,p_backend_execution_secret);
  when others then
    v_failure_detail := sqlerrm;
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,v_context.context_id,v_payload_fingerprint,jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'operational_commit_exception',jsonb_build_object('detail',v_failure_detail),p_backend_execution_secret);
  end;
  return v_result || jsonb_build_object('reconciliation_id',v_reconciliation_id);
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_completion_assert_taxonomy(p_response jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare t jsonb; v_catalog jsonb; v_digest text; v_area text;
 v_raw jsonb; v_selections jsonb; v_item jsonb; v_label text; v_id text; i integer; v_kind text;
begin
 if not (p_response ? 'taxonomy') then return; end if;
 t:=p_response->'taxonomy';
 if jsonb_typeof(t) is distinct from 'object'
   or jsonb_typeof(t->'version') is distinct from 'string'
   or jsonb_typeof(t->'digest') is distinct from 'string' then
  raise exception using errcode='22023',message='completion taxonomy metadata is malformed';
 end if;
 select c.catalog_json,c.catalog_sha256 into v_catalog,v_digest
 from public.custodial_completion_taxonomy_versions c where c.version=t->>'version';
 if not found or t->>'digest' is distinct from v_digest then
  raise exception using errcode='22023',message='completion taxonomy version or digest is unavailable';
 end if;
 v_area:=p_response->>'form_type';
 if v_area not in ('restroom','exhibit') or v_catalog->'areas'->v_area is null then
  raise exception using errcode='22023',message='completion taxonomy area is invalid';
 end if;
 for v_kind in select unnest(array['services','issues']::text[]) loop
  v_raw:=p_response->(case when v_kind='services' then 'services_performed' else 'maintenance_issues_found' end);
  v_selections:=t->v_kind;
  if jsonb_typeof(v_raw) is distinct from 'array' or jsonb_typeof(v_selections) is distinct from 'array'
    or jsonb_array_length(v_raw)<>jsonb_array_length(v_selections) then
   raise exception using errcode='22023',message='completion taxonomy selections do not match raw answers';
  end if;
  for i in 0..jsonb_array_length(v_raw)-1 loop
   v_item:=v_selections->i;
   if jsonb_typeof(v_raw->i) is distinct from 'string' or jsonb_typeof(v_item) is distinct from 'object'
    or jsonb_typeof(v_item->'id') is distinct from 'string'
    or jsonb_typeof(v_item->'label') is distinct from 'string' then
    raise exception using errcode='22023',message='completion taxonomy selection is malformed';
   end if;
   v_label:=v_raw->>i; v_id:=v_item->>'id';
   if v_item->>'label' is distinct from v_label or btrim(v_label)='' then
    raise exception using errcode='22023',message='completion taxonomy selection changed the original answer';
   end if;
   if v_kind='services' and v_id='OTHER' then
    if exists(select 1 from jsonb_array_elements(v_catalog->'areas'->v_area->v_kind) known
      where known->>'label'=v_label) then
     raise exception using errcode='22023',message='known completion service cannot be classified OTHER';
    end if;
   elsif not exists(select 1 from jsonb_array_elements(v_catalog->'areas'->v_area->v_kind) known
      where known->>'id'=v_id and known->>'label'=v_label) then
    raise exception using errcode='22023',message='completion taxonomy selection is not in this version';
   end if;
  end loop;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_control_release_canary(p_manager_id uuid, p_request_id uuid, p_device_identifier text, p_action text, p_reason text, p_authoritative_health jsonb, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_device text:=upper(btrim(coalesce(p_device_identifier,''))); v_existing public.custodial_release_canary_rollback_audits%rowtype;
  v_entry public.custodial_release_authority_restore_inventory%rowtype; v_entries public.custodial_release_authority_restore_inventory[]; v_result jsonb; v_restored integer:=0;
  v_secret_digest text; v_health jsonb; v_transport jsonb;
begin
  select execution_secret_digest into v_secret_digest from public.custodial_backend_execution_config where config_key=true and enabled=true;
  if v_secret_digest is null or length(coalesce(p_backend_execution_secret,''))<32 or encode(extensions.digest(convert_to(p_backend_execution_secret,'UTF8'),'sha256'),'hex')<>v_secret_digest then raise exception using errcode='42501',message='backend execution secret is not authorized'; end if;
  if not exists(select 1 from public.ops_manager_managers m where m.manager_id=p_manager_id and m.active and m.revoked_at is null and m.roles && array['DIRECTOR','SECURITY_ADMIN']::text[]) then raise exception using errcode='42501',message='named release manager authority is required'; end if;
  if p_request_id is null or v_device !~ '^KIOSK_(0[2-9]|10)$' or p_action not in ('pause_canary','resume_canary','restore_authority') or length(btrim(coalesce(p_reason,''))) not between 1 and 1000 or jsonb_typeof(p_authoritative_health)<>'object' then raise exception using errcode='22023',message='stable request, exact canary, supported action, reason, and authority health are required'; end if;
  perform pg_advisory_xact_lock(hashtextextended('custodial-release-canary:'||v_device,0));
  select * into v_existing from public.custodial_release_canary_rollback_audits where requested_by_manager_id=p_manager_id and request_id=p_request_id for update;
  if found then
    if v_existing.device_identifier<>v_device or v_existing.action<>p_action or v_existing.reason<>btrim(p_reason) or v_existing.authoritative_health<>p_authoritative_health then raise exception using errcode='23505',message='release control request identity is already bound to different inputs'; end if;
    return v_existing.result_json||jsonb_build_object('audit_id',v_existing.audit_id,'replayed',true);
  end if;
  if p_action='pause_canary' then
    insert into public.custodial_release_canary_controls(device_identifier,paused,updated_by_manager_id,reason,last_transport_probe_id) values(v_device,true,p_manager_id,btrim(p_reason),null) on conflict(device_identifier) do update set paused=true,updated_at=statement_timestamp(),updated_by_manager_id=excluded.updated_by_manager_id,reason=excluded.reason,last_transport_probe_id=null;
    v_result:=jsonb_build_object('device_identifier',v_device,'canary_paused',true,'restored_objects',0);
  elsif p_action='restore_authority' then
    if not coalesce((select paused from public.custodial_release_canary_controls where device_identifier=v_device),false) then raise exception using errcode='55000',message='the exact release canary must be paused before authority restoration'; end if;
    select array_agg(i order by i.restore_order,i.object_identity) into v_entries from public.custodial_release_authority_restore_inventory i;
    foreach v_entry in array v_entries loop
      if encode(extensions.digest(convert_to(v_entry.definition_sql,'UTF8'),'sha256'),'hex')<>v_entry.definition_sha256 then raise exception using errcode='23514',message='a captured authority restoration definition failed its digest'; end if;
      execute v_entry.definition_sql; v_restored:=v_restored+1;
    end loop;
    update public.custodial_release_canary_controls set updated_at=statement_timestamp(),updated_by_manager_id=p_manager_id,reason=btrim(p_reason),last_transport_probe_id=null where device_identifier=v_device;
    v_result:=jsonb_build_object('device_identifier',v_device,'canary_paused',true,'restored_objects',v_restored);
  else
    v_health:=public.custodial_run_release_canary_recovery_probe(v_device,p_backend_execution_secret);
    if coalesce((v_health->>'passed')::boolean,false) is not true then raise exception using errcode='55000',message='fresh persisted database recovery probe is green before canary resume'; end if;
    v_transport:=public.custodial_get_release_canary_transport_probe_health(v_device,p_authoritative_health#>>'{scan_rpc_transport,backend_commit_sha}',p_authoritative_health#>>'{scan_rpc_transport,release_id}',p_backend_execution_secret);
    if coalesce((v_transport->>'ready')::boolean,false) is not true then raise exception using errcode='55000',message='fresh native phone transport proof is required before canary resume'; end if;
    update public.custodial_release_canary_controls set paused=false,updated_at=statement_timestamp(),updated_by_manager_id=p_manager_id,reason=btrim(p_reason),last_transport_probe_id=(v_transport->>'probe_id')::uuid where device_identifier=v_device and paused=true;
    if not found then raise exception using errcode='55000',message='the exact release canary must be paused before resume'; end if;
    v_result:=jsonb_build_object('device_identifier',v_device,'canary_paused',false,'restored_objects',0,'verified_authoritative_health',v_health,'verified_transport_health',v_transport);
  end if;
  insert into public.custodial_release_canary_rollback_audits(requested_by_manager_id,request_id,device_identifier,action,reason,authoritative_health,result_json) values(p_manager_id,p_request_id,v_device,p_action,btrim(p_reason),p_authoritative_health,v_result) returning audit_id into v_existing.audit_id;
  return v_result||jsonb_build_object('audit_id',v_existing.audit_id,'replayed',false);
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_create_employee(p_display_name text, p_employee_code text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_changed_by_manager_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_manager public.ops_manager_managers%rowtype;
  v_name text := regexp_replace(btrim(coalesce(p_display_name, '')), '\s+', ' ', 'g');
  v_code text := upper(btrim(coalesce(p_employee_code, '')));
  v_employee public.employees%rowtype;
  v_user public.msg_users%rowtype;
begin
  v_manager := public.custodial_assert_manager(p_changed_by_manager_id);
  if length(v_name) < 2 or length(v_name) > 160 then
    raise exception using errcode = '22023', message = 'Employee name must be between 2 and 160 characters.';
  end if;
  if exists (select 1 from public.employees where lower(btrim(display_name)) = lower(v_name)) then
    raise exception using errcode = '23505', message = 'An employee record with that name already exists. Reactivate the existing record instead.';
  end if;
  if v_code = '' then v_code := public.custodial_next_employee_code(); end if;
  if v_code is null or v_code !~ '^EMP[0-9]{3,6}$' then
    raise exception using errcode = '22023', message = 'Employee code must use the EMP number format, such as EMP010.';
  end if;
  if exists (select 1 from public.employees where upper(coalesce(employee_code, '')) = v_code) then
    raise exception using errcode = '23505', message = 'That employee code is already in use.';
  end if;

  insert into public.employees(employee_code, display_name, active, role, notes)
  values (v_code, v_name, true, 'staff', nullif(btrim(coalesce(p_notes, '')), ''))
  returning * into v_employee;

  insert into public.msg_users(employee_id, display_name, role, is_active)
  values (v_employee.id, v_employee.display_name, 'employee', true)
  returning * into v_user;

  insert into public.custodial_employee_status_history(
    employee_id, employee_name, previous_active, new_active,
    changed_by_manager_id, change_reason, source, metadata_json
  ) values (
    v_employee.id, v_employee.display_name, null, true,
    v_manager.manager_id, 'employee_created', 'operations_app',
    jsonb_build_object('employee_code', v_employee.employee_code, 'msg_user_id', v_user.id)
  );

  return jsonb_build_object(
    'created', true,
    'employee', to_jsonb(v_employee),
    'messenger_user_id', v_user.id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.custodial_dated_control(op text, args jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare actor jsonb;manager uuid;plan jsonb;dep text;state jsonb;r public.custodial_dated_publications%rowtype;
 request jsonb;response jsonb;rev bigint;slot jsonb;day jsonb;work jsonb;inc record;actual text;expected bigint;
begin
 perform public.static_weekly_v3_assert_control_plane();
 -- Direct callers use the same fence-before-authority order as the adapter.
 perform public.custodial_begin_application_mutation();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 if jsonb_typeof(args) is distinct from 'object' then raise exception using errcode='22023',message='typed operation arguments required'; end if;
 manager:=nullif(args->>'managerId','')::uuid;
 if op in ('snapshot','receipt','stage','staged','finalize','rollback') then
  actor:=public.static_weekly_v3_manager_actor(manager);
 end if;
 if op='snapshot' then
  -- Status and exact rollback remain available after dependency drift.
  -- This does not authorize a new stage or skip its full admission checks.
  if args->'authorityOnly'='true'::jsonb then return jsonb_build_object('authorizedManagerId',manager,
   'authorityRevision',(select current_revision from public.static_weekly_schedule_control where singleton));end if;
  plan:=args->'plan';perform public.custodial_dated_assert_plan(plan);
  if args->>'start' is distinct from '2026-10-01' or args->>'end' is distinct from '2026-10-05' then
   raise exception using errcode='23514',message='exact bounded date range required'; end if;
  for slot in select value from jsonb_array_elements(plan->'rosterSlots') loop
   if not exists(select 1 from public.weekly_roster_slots s where s.slot_id::text=slot->>'slotId') then
    raise exception using errcode='23514',message='current stable slot missing'; end if;
   for day in select value from jsonb_array_elements(plan->'days') loop
    select count(*)::text into actual from public.v_weekly_roster_slot_incumbency_ranges i
      where i.slot_id::text=slot->>'slotId' and i.effective_start<=(day->>'serviceDate')::date
      and (i.effective_end is null or (day->>'serviceDate')::date<i.effective_end);
    if (slot->>'personId' is null and actual<>'0') or (slot->>'personId' is not null and actual<>'1') then
     raise exception using errcode='23514',message='current incumbent/vacancy mismatch'; end if;
    if slot->>'personId' is not null and not exists(select 1 from public.v_weekly_roster_slot_incumbency_ranges i
     join public.employees e on e.id=i.person_id and e.active=true
     where i.slot_id::text=slot->>'slotId' and i.person_id::text=slot->>'personId' and e.display_name=slot->>'displayName'
      and i.effective_start<=(day->>'serviceDate')::date and (i.effective_end is null or (day->>'serviceDate')::date<i.effective_end)) then
     raise exception using errcode='23514',message='current employee identity mismatch'; end if;
   end loop;
  end loop;
  if exists(select 1 from jsonb_array_elements(plan->'days') d cross join lateral jsonb_array_elements(d->'assignments') w
   where not exists(select 1 from public.location_groups g where g.group_code=w#>>'{workSnapshot,locationCodeSnapshot}' and g.active))
   or exists(select 1 from jsonb_array_elements(plan->'days') d cross join lateral jsonb_array_elements(d->'assignments') w
    cross join lateral jsonb_array_elements(w#>'{workSnapshot,includedLocations}') x
    where not exists(select 1 from public.locations l where l.id::text=x->>'locationId' and l.active)) then
    raise exception using errcode='23514',message='active physical location mapping required'; end if;
  if exists(select 1 from public.weekly_schedule_exception_commands e where e.service_date>=date '2026-10-01' and e.service_date<date '2026-10-05')
   or exists(select 1 from jsonb_array_elements(plan->'days') d cross join lateral jsonb_array_elements(d->'availability') a
    join lateral(select s.staffing_state from public.weekly_roster_slot_staffing_states s
     where s.slot_id::text=a->>'slotId' and s.effective_start<=(d->>'serviceDate')::date
     order by s.effective_start desc,s.authority_revision desc limit 1) staffing on true
    where a->>'status'='working' and staffing.staffing_state<>'working') then
   raise exception using errcode='23514',message='current staffing/dated exceptions require reconciliation';end if;
  return jsonb_build_object('authorizedManagerId',manager,'authorityRevision',(select current_revision from public.static_weekly_schedule_control where singleton),
   'dependencyDigest',public.static_weekly_digest_jsonb(public.custodial_dated_dependencies(plan)),'rosterSlots',plan->'rosterSlots',
   'approvedAvailability',(select jsonb_agg(jsonb_build_object('serviceDate',d->'serviceDate','availability',d->'availability') order by d->>'serviceDate') from jsonb_array_elements(plan->'days') d),
   'hasExistingOccurrences',exists(select 1 from public.weekly_schedule_occurrences o where service_date>=date '2026-10-01' and service_date<date '2026-10-05')
    or public.custodial_dated_record() is not null);
 elsif op='receipt' then
  select jsonb_build_object('request',x.request,'response',x.response) into response from public.custodial_dated_receipts x
    where manager_id=manager and operation_key=args->>'key';return response;
 elsif op='stage' then
  plan:=args->'plan';perform public.custodial_dated_assert_plan(plan);
  if public.custodial_dated_record() is not null or exists(select 1 from public.weekly_schedule_occurrences o
    where o.service_date>=date '2026-10-01' and o.service_date<date '2026-10-05') then
   raise exception using errcode='23514',message='existing occurrences require explicit reconciliation'; end if;
  if exists(select 1 from public.custodial_dated_publications where staged_transaction=pg_current_xact_id()) then
   raise exception using errcode='23514',message='one bounded stage per transaction'; end if;
  -- Recheck identities at the writer even if the caller bypassed JS preview.
  state:=public.custodial_dated_control('snapshot',jsonb_build_object('managerId',manager,'plan',plan,'start','2026-10-01','end','2026-10-05'));
  insert into public.custodial_dated_publications(plan_digest,plan,dependency_digest,manager_id,staged_transaction,expected_revision)
   values(plan->>'planDigest',plan,state->>'dependencyDigest',manager,pg_current_xact_id(),(state->>'authorityRevision')::bigint) returning * into r;
  for day in select value from jsonb_array_elements(plan->'days') loop
   for work in select value from jsonb_array_elements(day->'assignments') loop
    insert into public.custodial_dated_occurrences(publication_id,service_date,plan_work_id,assignment)
     values(r.publication_id,(day->>'serviceDate')::date,work->>'planWorkId',work);
   end loop;
  end loop;
  return null;
 elsif op='staged' then
  select * into r from public.custodial_dated_publications where staged_transaction=pg_current_xact_id() and manager_id=manager;
  if not found then raise exception using errcode='55000',message='transaction-local stage required'; end if;
  return jsonb_build_object('persistenceStatus','PERSISTED','publicationId',r.publication_id,'projectionId',r.projection_id,
   'planDigest',r.plan_digest,'phonePdfRevision',r.plan->>'phonePdfRevision','days',r.plan->'days');
 elsif op in ('finalize','rollback') then
  request:=args->'request';expected:=(request->>'expectedRevision')::bigint;
  if request->>'managerId' is distinct from manager::text or request->>'planDigest' is distinct from '89f600b965259f6bbf30488ff5eef2a6d754b3cbd0072f00419b318245e9459d'
   or request->>'phonePdfRevision' is distinct from 'ee75f76a21e0d3a82291b8c720b5548532e1f168f1941a0cd74e80662302bd08'
   or nullif(btrim(request->>'idempotencyKey'),'') is null or length(request->>'idempotencyKey')>200 then
    raise exception using errcode='23514',message='exact authorized operation identity required'; end if;
  if op='finalize' then
   select * into r from public.custodial_dated_publications where staged_transaction=pg_current_xact_id() and manager_id=manager;
   if not found or r.expected_revision is distinct from expected or args#>>'{record,publicationId}' is distinct from r.publication_id::text
     or args#>>'{record,projectionId}' is distinct from r.projection_id::text then
    raise exception using errcode='23514',message='complete transaction-local stage identity required'; end if;
   if request->>'operation' is distinct from 'materialize' or request->>'previewDigest' is distinct from public.static_weekly_digest_jsonb(
     jsonb_build_object('planDigest',r.plan_digest,'managerId',manager::text,'authorityRevision',expected,'dependencyDigest',r.dependency_digest)) then
    raise exception using errcode='23514',message='preview acceptance identity mismatch'; end if;
  else
   state:=public.custodial_dated_record();
   if state is null or request->>'operation' is distinct from 'rollback'
    or request->>'publicationId' is distinct from state->>'publicationId' or request->>'projectionId' is distinct from state->>'projectionId' then
    raise exception using errcode='23514',message='rollback must name exact current publication'; end if;
   select * into strict r from public.custodial_dated_publications where publication_id=(state->>'publicationId')::uuid;
  end if;
  rev:=public.static_weekly_advance_authority(expected,case when op='finalize' then 'materialize_projection' else 'rollback' end,
    manager,actor->>'manager_name',gen_random_uuid(),public.static_weekly_digest_jsonb(request));
  insert into public.custodial_dated_activations(publication_id,authority_revision,active,manager_id) values(r.publication_id,rev,op='finalize',manager);
  response:=jsonb_build_object('state',case when op='finalize' then 'PERSISTED' else 'ROLLED_BACK' end,'revision',rev,
   'publicationId',r.publication_id,'projectionId',r.projection_id,'planDigest',r.plan_digest,'phonePdfRevision',r.plan->>'phonePdfRevision',
   'phoneDeliveryState','PENDING','affectedPhonesUpdated',false);
  insert into public.custodial_dated_receipts values(manager,request->>'idempotencyKey',request,response);
  return response;
 elsif op='current' then return public.custodial_dated_record();
 elsif op='day' then
  state:=public.custodial_dated_record((args->>'date')::date);
  if state->>'projectionStatus' is distinct from 'current' then return null; end if;
  return (select d from jsonb_array_elements(state->'days') d where d->>'serviceDate'=args->>'date');
 else raise exception using errcode='22023',message='unknown bounded operation'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_evaluate_location_proximity_measurement(p_location_code text, p_device_identifier text, p_latitude numeric, p_longitude numeric, p_accuracy_m numeric DEFAULT NULL::numeric, p_session_uuid text DEFAULT NULL::text, p_client_event_id text DEFAULT NULL::text, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_presented_device text := nullif(btrim(coalesce(p_device_identifier, '')), '');
  v_resolved_location_code text := public.resolve_scan_location_code(p_location_code);
  v_device_pk uuid;
  v_device_id text;
  v_location_id uuid;
  v_location_name text;
  v_session_id uuid;
  v_target_lat numeric;
  v_target_lon numeric;
  v_coordinate_source text;
  v_radius numeric := greatest(25, public.get_setting_int('gps_proximity_radius_m', 175));
  v_max_accuracy numeric := greatest(25, public.get_setting_int('gps_max_accuracy_m', 100));
  v_distance numeric;
  v_effective_radius numeric;
  v_result text;
  v_badge_color text;
  v_event_id uuid;
  v_session_key text := coalesce(nullif(btrim(p_session_uuid), ''), '');
begin
  if v_presented_device is null then raise exception 'device identifier is required'; end if;
  if v_resolved_location_code is null then raise exception 'Active location not found for code: %', p_location_code; end if;
  if p_latitude is null or p_latitude < -90 or p_latitude > 90 then raise exception 'latitude is invalid'; end if;
  if p_longitude is null or p_longitude < -180 or p_longitude > 180 then raise exception 'longitude is invalid'; end if;
  if p_accuracy_m is not null and p_accuracy_m < 0 then raise exception 'accuracy_m cannot be negative'; end if;

  select d.id, d.device_id
    into v_device_pk, v_device_id
  from public.devices d
  where d.active = true and upper(btrim(d.device_id)) = upper(v_presented_device)
  union all
  select d.id, d.device_id
  from public.device_aliases da
  join public.devices d on d.id = da.canonical_device_id and d.active = true
  where da.active = true and upper(btrim(da.alias_identifier)) = upper(v_presented_device)
  limit 1;
  if v_device_pk is null then raise exception 'Active device not found: %', v_presented_device; end if;

  select l.id, l.location_name
    into v_location_id, v_location_name
  from public.locations l
  where l.active = true and l.location_code = v_resolved_location_code
  limit 1;

  if v_session_key <> '' then
    select s.id into v_session_id
    from public.sessions s
    where s.session_uuid = v_session_key
      and s.device_id = v_device_pk
      and s.location_id = v_location_id
    limit 1;
    if v_session_id is null and public.custodial_gps_session_state(
      v_resolved_location_code,v_presented_device,v_session_key
    ) is null then
      raise exception 'Session does not belong to this device and location';
    end if;
  end if;

  select lp.latitude, lp.longitude,
         coalesce(nullif(lp.coordinate_source, ''), 'location_proximity_settings')
    into v_target_lat, v_target_lon, v_coordinate_source
  from public.location_proximity_settings lp
  where lp.location_id = v_location_id
    and lp.active = true
    and lp.latitude is not null
    and lp.longitude is not null
  order by lp.updated_at desc
  limit 1;

  if v_target_lat is null or v_target_lon is null then
    select gp.latitude, gp.longitude,
           coalesce(nullif(gp.coordinate_source, ''), 'location_group_proximity_settings')
      into v_target_lat, v_target_lon, v_coordinate_source
    from public.location_group_memberships gm
    join public.location_groups lg on lg.id = gm.location_group_id and lg.active = true
    join public.location_group_proximity_settings gp
      on gp.location_group_id = lg.id
     and gp.active = true
     and gp.latitude is not null
     and gp.longitude is not null
    where gm.location_id = v_location_id and gm.active = true
    order by gp.updated_at desc, lg.group_name
    limit 1;
  end if;

  if v_target_lat is null or v_target_lon is null then
    v_result := 'not_configured';
    v_badge_color := 'amber';
    v_effective_radius := v_radius;
  else
    v_distance := 6371000 * 2 * asin(sqrt(
      power(sin(radians((p_latitude - v_target_lat)::double precision) / 2), 2)
      + cos(radians(v_target_lat::double precision))
      * cos(radians(p_latitude::double precision))
      * power(sin(radians((p_longitude - v_target_lon)::double precision) / 2), 2)
    ));
    v_effective_radius := v_radius + least(greatest(coalesce(p_accuracy_m, 0), 0), 25);
    if p_accuracy_m is not null and p_accuracy_m > v_max_accuracy then
      v_result := 'low_accuracy';
      v_badge_color := 'amber';
    elsif v_distance <= v_effective_radius then
      v_result := 'near';
      v_badge_color := 'green';
    else
      v_result := 'away';
      v_badge_color := 'red';
    end if;
  end if;

  insert into public.device_location_proximity_status(
    device_id, location_id, session_uuid, presented_identifier, result, badge_color,
    distance_m, allowed_radius_m, accuracy_m, client_latitude, client_longitude,
    target_latitude, target_longitude, coordinate_source, evaluated_at,
    correlation_id, metadata_json
  ) values (
    v_device_pk, v_location_id, v_session_key, v_presented_device, v_result, v_badge_color,
    v_distance, v_effective_radius, p_accuracy_m, p_latitude, p_longitude,
    v_target_lat, v_target_lon, v_coordinate_source, now(),
    nullif(btrim(coalesce(p_correlation_id, '')), ''),
    jsonb_build_object('location_code', v_resolved_location_code, 'location_name', v_location_name)
  )
  on conflict (device_id, location_id, session_uuid) do update set
    presented_identifier = excluded.presented_identifier,
    result = excluded.result,
    badge_color = excluded.badge_color,
    distance_m = excluded.distance_m,
    allowed_radius_m = excluded.allowed_radius_m,
    accuracy_m = excluded.accuracy_m,
    client_latitude = excluded.client_latitude,
    client_longitude = excluded.client_longitude,
    target_latitude = excluded.target_latitude,
    target_longitude = excluded.target_longitude,
    coordinate_source = excluded.coordinate_source,
    evaluated_at = now(),
    correlation_id = excluded.correlation_id,
    metadata_json = excluded.metadata_json;

  if p_client_event_id is not null then
    select se.id into v_event_id
    from public.scan_events se
    where se.client_event_id = p_client_event_id
    limit 1;
  end if;

  if v_event_id is null then
    insert into public.scan_events(
      scanned_at, location_id, location_code, device_id, device_identifier,
      session_id, event_type, result, notes, payload_json, client_event_id
    ) values (
      now(), v_location_id, v_resolved_location_code, v_device_pk, v_device_id,
      v_session_id, 'work_position_check', v_result,
      case
        when v_result = 'away' then format('Phone is %s meters from the authoritative location coordinate.', round(v_distance))
        when v_result = 'near' then 'Phone is within the authoritative location radius.'
        when v_result = 'low_accuracy' then 'GPS accuracy is too low for a green proximity result.'
        else 'No authoritative GPS coordinate is configured for this location.'
      end,
      jsonb_build_object(
        'session_uuid', nullif(v_session_key, ''),
        'client_session_id', nullif(v_session_key, ''),
        'distance_m', v_distance,
        'allowed_radius_m', v_effective_radius,
        'accuracy_m', p_accuracy_m,
        'client_latitude', p_latitude,
        'client_longitude', p_longitude,
        'target_latitude', v_target_lat,
        'target_longitude', v_target_lon,
        'coordinate_source', v_coordinate_source,
        'badge_color', v_badge_color,
        'correlation_id', p_correlation_id
      ),
      nullif(btrim(coalesce(p_client_event_id, '')), '')
    ) returning id into v_event_id;
  end if;

  return jsonb_build_object(
    'ok', true,
    'result', v_result,
    'badge_color', v_badge_color,
    'device_id', v_device_id,
    'presented_device_id', v_presented_device,
    'location_code', v_resolved_location_code,
    'location_name', v_location_name,
    'session_uuid', nullif(v_session_key, ''),
    'distance_m', case when v_distance is null then null else round(v_distance, 1) end,
    'allowed_radius_m', round(v_effective_radius, 1),
    'accuracy_m', p_accuracy_m,
    'target_latitude', v_target_lat,
    'target_longitude', v_target_lon,
    'coordinate_source', v_coordinate_source,
    'evaluated_at', now(),
    'scan_event_id', v_event_id
  );
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_evaluate_location_proximity_v2_measurement(p_location_code text, p_device_identifier text, p_latitude numeric, p_longitude numeric, p_accuracy_m numeric DEFAULT NULL::numeric, p_session_uuid text DEFAULT NULL::text, p_client_event_id text DEFAULT NULL::text, p_correlation_id text DEFAULT NULL::text, p_observed_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_now timestamptz := clock_timestamp();
  v_observed_at timestamptz := coalesce(p_observed_at, clock_timestamp());
  v_presented_device text := nullif(btrim(coalesce(p_device_identifier, '')), '');
  v_resolved_location_code text := public.resolve_scan_location_code(p_location_code);
  v_device_pk uuid;
  v_device_id text;
  v_location_id uuid;
  v_location_name text;
  v_session_id uuid;
  v_target_lat numeric;
  v_target_lon numeric;
  v_coordinate_source text;
  v_radius numeric := greatest(25, public.get_setting_int('gps_proximity_radius_m', 175));
  v_max_accuracy numeric := greatest(25, public.get_setting_int('gps_max_accuracy_m', 100));
  v_max_age_seconds numeric := greatest(30, public.get_setting_int('gps_max_observation_age_seconds', 120));
  v_future_tolerance_seconds numeric := greatest(0, public.get_setting_int('gps_future_tolerance_seconds', 30));
  v_boundary_hysteresis numeric := greatest(5, public.get_setting_int('gps_boundary_hysteresis_m', 15));
  v_max_human_speed numeric := greatest(2, public.get_setting_int('gps_max_human_speed_mps', 12));
  v_distance numeric;
  v_uncertainty numeric;
  v_observation_age_seconds numeric;
  v_previous_lat numeric;
  v_previous_lon numeric;
  v_previous_accuracy_m numeric;
  v_previous_observed_at timestamptz;
  v_motion_distance_m numeric;
  v_motion_effective_distance_m numeric;
  v_motion_elapsed_seconds numeric;
  v_motion_speed_mps numeric;
  v_status_observed_at timestamptz;
  v_result text;
  v_badge_color text;
  v_event_id uuid;
  v_session_key text := coalesce(nullif(btrim(p_session_uuid), ''), '');
  v_authoritative boolean := false;
begin
  if v_presented_device is null then raise exception 'device identifier is required'; end if;
  if v_resolved_location_code is null then raise exception 'Active location not found for code: %', p_location_code; end if;
  if p_latitude is null or p_latitude < -90 or p_latitude > 90 then raise exception 'latitude is invalid'; end if;
  if p_longitude is null or p_longitude < -180 or p_longitude > 180 then raise exception 'longitude is invalid'; end if;
  if p_accuracy_m is not null and p_accuracy_m < 0 then raise exception 'accuracy_m cannot be negative'; end if;

  select d.id, d.device_id into v_device_pk, v_device_id
  from public.devices d
  where d.active = true and upper(btrim(d.device_id)) = upper(v_presented_device)
  union all
  select d.id, d.device_id
  from public.device_aliases da
  join public.devices d on d.id = da.canonical_device_id and d.active = true
  where da.active = true and upper(btrim(da.alias_identifier)) = upper(v_presented_device)
  limit 1;
  if v_device_pk is null then raise exception 'Active device not found: %', v_presented_device; end if;

  select l.id, l.location_name into v_location_id, v_location_name
  from public.locations l
  where l.active = true and l.location_code = v_resolved_location_code
  limit 1;

  if v_session_key <> '' then
    select s.id into v_session_id
    from public.sessions s
    where s.session_uuid = v_session_key
      and s.device_id = v_device_pk
      and s.location_id = v_location_id
    limit 1;
    if v_session_id is null and public.custodial_gps_session_state(
      v_resolved_location_code,v_presented_device,v_session_key
    ) is null then
      raise exception 'Session does not belong to this device and location';
    end if;
  end if;

  select lp.latitude, lp.longitude, coalesce(nullif(lp.coordinate_source, ''), 'location_proximity_settings')
  into v_target_lat, v_target_lon, v_coordinate_source
  from public.location_proximity_settings lp
  where lp.location_id = v_location_id
    and lp.active = true
    and lp.latitude is not null
    and lp.longitude is not null
  order by lp.updated_at desc
  limit 1;

  if v_target_lat is null or v_target_lon is null then
    select gp.latitude, gp.longitude, coalesce(nullif(gp.coordinate_source, ''), 'location_group_proximity_settings')
    into v_target_lat, v_target_lon, v_coordinate_source
    from public.location_group_memberships gm
    join public.location_groups lg on lg.id = gm.location_group_id and lg.active = true
    join public.location_group_proximity_settings gp
      on gp.location_group_id = lg.id
     and gp.active = true
     and gp.latitude is not null
     and gp.longitude is not null
    where gm.location_id = v_location_id and gm.active = true
    order by gp.updated_at desc, lg.group_name
    limit 1;
  end if;

  select s.client_latitude, s.client_longitude, s.accuracy_m, coalesce(s.observed_at, s.evaluated_at)
  into v_previous_lat, v_previous_lon, v_previous_accuracy_m, v_previous_observed_at
  from public.device_location_proximity_status s
  where s.device_id = v_device_pk
    and s.location_id = v_location_id
    and s.session_uuid = v_session_key
    and s.result in ('near', 'away', 'boundary_uncertain')
  limit 1;

  v_observation_age_seconds := extract(epoch from (v_now - v_observed_at));
  -- A client clock that is ahead must not pin the current-status row into the
  -- future and suppress later legitimate observations. The unmodified client
  -- timestamp remains in the scan event and metadata for audit evidence.
  v_status_observed_at := least(v_observed_at, v_now);
  v_uncertainty := greatest(v_boundary_hysteresis, least(greatest(coalesce(p_accuracy_m, 0), 0), v_max_accuracy));

  if v_target_lat is not null and v_target_lon is not null then
    v_distance := 6371000 * 2 * asin(sqrt(
      power(sin(radians((p_latitude - v_target_lat)::double precision) / 2), 2)
      + cos(radians(v_target_lat::double precision)) * cos(radians(p_latitude::double precision))
      * power(sin(radians((p_longitude - v_target_lon)::double precision) / 2), 2)
    ));
  end if;

  if v_previous_lat is not null
     and v_previous_lon is not null
     and v_previous_observed_at is not null
     and v_observed_at > v_previous_observed_at then
    v_motion_elapsed_seconds := extract(epoch from (v_observed_at - v_previous_observed_at));
    v_motion_distance_m := 6371000 * 2 * asin(sqrt(
      power(sin(radians((p_latitude - v_previous_lat)::double precision) / 2), 2)
      + cos(radians(v_previous_lat::double precision)) * cos(radians(p_latitude::double precision))
      * power(sin(radians((p_longitude - v_previous_lon)::double precision) / 2), 2)
    ));
    v_motion_effective_distance_m := greatest(
      0,
      v_motion_distance_m - greatest(coalesce(p_accuracy_m, 0), 0) - greatest(coalesce(v_previous_accuracy_m, 0), 0)
    );
    v_motion_speed_mps := v_motion_effective_distance_m / greatest(v_motion_elapsed_seconds, 0.001);
  end if;

  if v_observation_age_seconds < -v_future_tolerance_seconds then
    v_result := 'future_clock'; v_badge_color := 'amber';
  elsif v_observation_age_seconds > v_max_age_seconds then
    v_result := 'stale'; v_badge_color := 'amber';
  elsif p_accuracy_m is null or p_accuracy_m > v_max_accuracy then
    v_result := 'low_accuracy'; v_badge_color := 'amber';
  elsif v_target_lat is null or v_target_lon is null then
    v_result := 'not_configured'; v_badge_color := 'amber';
  elsif v_motion_speed_mps is not null and v_motion_speed_mps > v_max_human_speed then
    v_result := 'implausible_jump'; v_badge_color := 'amber';
  elsif abs(v_distance - v_radius) <= v_uncertainty then
    v_result := 'boundary_uncertain'; v_badge_color := 'amber';
  elsif v_distance < v_radius then
    v_result := 'near'; v_badge_color := 'green'; v_authoritative := true;
  else
    v_result := 'away'; v_badge_color := 'red'; v_authoritative := true;
  end if;

  insert into public.device_location_proximity_status(
    device_id, location_id, session_uuid, presented_identifier, result, badge_color,
    distance_m, allowed_radius_m, accuracy_m, client_latitude, client_longitude,
    target_latitude, target_longitude, coordinate_source, observed_at,
    observation_age_seconds, motion_speed_mps, evaluated_at, correlation_id, metadata_json
  ) values (
    v_device_pk, v_location_id, v_session_key, v_presented_device, v_result, v_badge_color,
    v_distance, v_radius, p_accuracy_m, p_latitude, p_longitude,
    v_target_lat, v_target_lon, v_coordinate_source, v_status_observed_at,
    v_observation_age_seconds, v_motion_speed_mps, v_now,
    nullif(btrim(coalesce(p_correlation_id, '')), ''),
    jsonb_build_object(
      'location_code', v_resolved_location_code,
      'location_name', v_location_name,
      'authoritative', v_authoritative,
      'reported_observed_at', v_observed_at,
      'boundary_uncertainty_m', v_uncertainty,
      'motion_distance_m', v_motion_distance_m,
      'motion_effective_distance_m', v_motion_effective_distance_m
    )
  )
  on conflict(device_id, location_id, session_uuid) do update set
    presented_identifier = excluded.presented_identifier,
    result = excluded.result,
    badge_color = excluded.badge_color,
    distance_m = excluded.distance_m,
    allowed_radius_m = excluded.allowed_radius_m,
    accuracy_m = excluded.accuracy_m,
    client_latitude = excluded.client_latitude,
    client_longitude = excluded.client_longitude,
    target_latitude = excluded.target_latitude,
    target_longitude = excluded.target_longitude,
    coordinate_source = excluded.coordinate_source,
    observed_at = excluded.observed_at,
    observation_age_seconds = excluded.observation_age_seconds,
    motion_speed_mps = excluded.motion_speed_mps,
    evaluated_at = excluded.evaluated_at,
    correlation_id = excluded.correlation_id,
    metadata_json = excluded.metadata_json
  where excluded.observed_at >= coalesce(device_location_proximity_status.observed_at, device_location_proximity_status.evaluated_at);

  insert into public.scan_events(
      scanned_at, location_id, location_code, device_id, device_identifier,
      session_id, event_type, result, notes, payload_json, client_event_id
    ) values (
      v_now, v_location_id, v_resolved_location_code, v_device_pk, v_device_id,
      v_session_id, 'work_position_check', v_result,
      case
        when v_result = 'away' then format('Phone is %s meters from the authoritative location coordinate.', round(v_distance))
        when v_result = 'near' then 'Phone is within the authoritative location radius.'
        when v_result = 'boundary_uncertain' then 'Phone is near the GPS boundary; location remains advisory until a clearer reading arrives.'
        when v_result = 'low_accuracy' then 'GPS accuracy is too low for an authoritative proximity result.'
        when v_result = 'stale' then 'GPS observation is stale and was not accepted as current position.'
        when v_result = 'future_clock' then 'GPS observation timestamp is ahead of server time.'
        when v_result = 'implausible_jump' then 'GPS movement is implausibly fast and requires a fresh reading.'
        else 'No authoritative GPS coordinate is configured for this location.'
      end,
      jsonb_build_object(
        'session_uuid', nullif(v_session_key, ''),
        'client_session_id', nullif(v_session_key, ''),
        'distance_m', v_distance,
        'allowed_radius_m', v_radius,
        'accuracy_m', p_accuracy_m,
        'client_latitude', p_latitude,
        'client_longitude', p_longitude,
        'target_latitude', v_target_lat,
        'target_longitude', v_target_lon,
        'coordinate_source', v_coordinate_source,
        'badge_color', v_badge_color,
        'authoritative', v_authoritative,
        'observed_at', v_observed_at,
        'observation_age_seconds', v_observation_age_seconds,
        'motion_speed_mps', v_motion_speed_mps,
        'motion_distance_m', v_motion_distance_m,
        'motion_effective_distance_m', v_motion_effective_distance_m,
        'correlation_id', p_correlation_id
      ),
      nullif(btrim(coalesce(p_client_event_id, '')), '')
    )
    on conflict(client_event_id) where client_event_id is not null do nothing
    returning id into v_event_id;

  if v_event_id is null and nullif(btrim(coalesce(p_client_event_id, '')), '') is not null then
    select se.id into v_event_id
    from public.scan_events se
    where se.client_event_id = nullif(btrim(p_client_event_id), '')
    limit 1;
  end if;

  return jsonb_build_object(
    'ok', true,
    'result', v_result,
    'authoritative', v_authoritative,
    'badge_color', v_badge_color,
    'device_id', v_device_id,
    'presented_device_id', v_presented_device,
    'location_code', v_resolved_location_code,
    'location_name', v_location_name,
    'session_uuid', nullif(v_session_key, ''),
    'distance_m', case when v_distance is null then null else round(v_distance, 1) end,
    'allowed_radius_m', round(v_radius, 1),
    'accuracy_m', p_accuracy_m,
    'target_latitude', v_target_lat,
    'target_longitude', v_target_lon,
    'coordinate_source', v_coordinate_source,
    'observed_at', v_observed_at,
    'observation_age_seconds', round(v_observation_age_seconds, 1),
    'motion_speed_mps', case when v_motion_speed_mps is null then null else round(v_motion_speed_mps, 2) end,
    'evaluated_at', v_now,
    'scan_event_id', v_event_id
  );
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_feedback_relay_attachment_internal(p_principal text, p_action text, p_args jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  cfg public.system_feedback_email_relay_config%rowtype;
  item public.system_feedback_email_intents%rowtype;
  image jsonb;
  expected_sha text;
  canonical_match text[];
  observed jsonb;
  ticket uuid;
  disposition text;
  allowed text[];
begin
  if p_principal !~ '^relay:[0-9a-f]{64}$' or p_args is null or jsonb_typeof(p_args)<>'object'
    or octet_length(p_args::text)>16384 or p_args->>'adapter_schema_sha256' !~ '^[0-9a-f]{64}$'
    or p_args->>'intent_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or p_args->>'claim_token' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or p_args->>'claim_generation' !~ '^[1-9][0-9]{0,8}$'
    or p_args->>'envelope_sha256' !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='22023',message='Exact private attachment admission fence required';end if;
  allowed:=case p_action when 'prepare' then array['intent_id','claim_token','claim_generation','envelope_sha256','adapter_schema_sha256']
    when 'complete' then array['intent_id','claim_token','claim_generation','envelope_sha256','adapter_schema_sha256','ticket','observed']
    when 'reject' then array['intent_id','claim_token','claim_generation','envelope_sha256','adapter_schema_sha256','ticket','disposition'] end;
  if allowed is null or exists(select 1 from jsonb_object_keys(p_args) k where not k=any(allowed))
    or exists(select 1 from unnest(allowed) k where not p_args ? k or p_args->k='null'::jsonb) then
    raise exception using errcode='22023',message='Unknown or missing private attachment admission argument';end if;
  select * into strict cfg from public.system_feedback_email_relay_config where singleton for update;
  select * into strict item from public.system_feedback_email_intents where id=(p_args->>'intent_id')::uuid for update;
  if item.claim_principal is distinct from p_principal or item.claim_token::text is distinct from p_args->>'claim_token'
    or item.claim_generation<>(p_args->>'claim_generation')::integer
    or item.envelope_sha256 is distinct from p_args->>'envelope_sha256' then
    raise exception using errcode='42501',message='Stale or foreign attachment claim';end if;
  if p_action='prepare' and item.attempt_id is not null then return '{"status":"already_attempted"}'::jsonb;end if;
  if cfg.paused or cfg.transport_principal is distinct from p_principal or cfg.transport_verified_at is null
    or cfg.transport_verified_at<now()-interval '15 minutes'
    or cfg.transport_schema_sha256 is distinct from p_args->>'adapter_schema_sha256'
    or item.state<>'claimed' or item.claim_until<=now() or item.attempt_id is not null then
    raise exception using errcode='55000',message='Private attachment preparation is paused or expired';end if;
  image:=item.feedback_snapshot->'image_attachment';
  if image is null or image='null'::jsonb then
    if p_action='prepare' then return '{"status":"no_attachment"}'::jsonb;end if;
    raise exception using errcode='22023',message='No protected attachment to attest';
  end if;
  if not public.feedback_email_attachment_source_matches(item.id) then
    update public.system_feedback_email_intents set state='needs_attention',attention_reason='attachment_source_changed',
      claim_token=null,claim_until=null,attachment_verification_state='blocked' where id=item.id;
    return '{"status":"needs_attention"}'::jsonb;
  end if;
  if p_action='prepare' then
    ticket:=gen_random_uuid();
    update public.system_feedback_email_intents set attachment_verification_ticket=ticket,
      attachment_verification_state='pending',attachment_verification_claim_token=item.claim_token,
      attachment_verification_generation=item.claim_generation,
      attachment_verification_source_digest=public.static_weekly_digest_jsonb(image),
      attachment_verification_sha256=null,attachment_verification_size=null,
      attachment_verification_type=null,attachment_verified_at=null where id=item.id;
    return jsonb_build_object('status','ready','ticket',ticket,'operation_id',item.operation_id,'image',image);
  end if;
  if p_args->>'ticket' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or item.attachment_verification_ticket::text is distinct from p_args->>'ticket'
    or item.attachment_verification_state<>'pending'
    or item.attachment_verification_claim_token is distinct from item.claim_token
    or item.attachment_verification_generation is distinct from item.claim_generation
    or item.attachment_verification_source_digest is distinct from public.static_weekly_digest_jsonb(image) then
    raise exception using errcode='42501',message='Stale private attachment verification ticket';end if;
  if p_action='reject' then
    disposition:=p_args->>'disposition';
    if disposition not in ('missing','corrupt','configuration_unavailable') or disposition is null then
      raise exception using errcode='22023',message='Typed private attachment disposition required';end if;
    if disposition='configuration_unavailable' then
      update public.system_feedback_email_relay_config set paused=true,pause_reason='attachment_storage_unavailable',updated_at=now() where singleton;
      update public.system_feedback_email_intents set state='queued',claim_token=null,claim_until=null,
        attachment_verification_state='unverified',attachment_verification_ticket=null where id=item.id;
      return '{"status":"paused"}'::jsonb;
    end if;
    update public.system_feedback_email_intents set state='needs_attention',claim_token=null,claim_until=null,
      attention_reason=case when disposition='missing' then 'protected_attachment_missing' else 'protected_attachment_corrupt' end,
      attachment_verification_state='blocked' where id=item.id;
    return '{"status":"needs_attention"}'::jsonb;
  end if;
  observed:=p_args->'observed';
  if jsonb_typeof(observed)<>'object' or
    (select count(*) from jsonb_object_keys(observed))<>3 or not(observed ?& array['sha256','size','type'])
    or observed->>'sha256' !~ '^[0-9a-f]{64}$'
    or observed->>'size' !~ '^[1-9][0-9]{0,6}$'
    or (observed->>'size')::integer>5*1024*1024
    or observed->>'type' not in ('image/png','image/jpeg','image/webp','image/gif')
    or nullif(image->>'size','')::integer is distinct from (observed->>'size')::integer
    or replace(image->>'type','image/jpg','image/jpeg') is distinct from observed->>'type' then
    raise exception using errcode='22023',message='Actual attachment size and type proof required';end if;
  canonical_match:=regexp_match(coalesce(image->>'storage_path',''),
    '^feedback/'||item.operation_id::text||'/([0-9a-f]{64})\.(png|jpg|webp|gif)$');
  expected_sha:=coalesce(nullif(image->>'sha256',''),canonical_match[1]);
  if expected_sha is not null and expected_sha is distinct from observed->>'sha256' then
    raise exception using errcode='22023',message='Actual attachment digest mismatch';end if;
  if expected_sha is null and nullif(image->>'data_url','') is null and nullif(image->>'dataUrl','') is null then
    raise exception using errcode='22023',message='No immutable attachment digest source';end if;
  update public.system_feedback_email_intents set attachment_verification_state='verified',
    attachment_verification_sha256=observed->>'sha256',attachment_verification_size=(observed->>'size')::integer,
    attachment_verification_type=observed->>'type',attachment_verified_at=now() where id=item.id;
  return '{"status":"verified"}'::jsonb;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_feedback_triage(p_request uuid, p_manager uuid, p_credential uuid, p_feedback uuid, p_action text, p_expected_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
 old_receipt public.system_feedback_triage_receipts%rowtype;
 item public.system_feedback_items%rowtype;
 manager public.ops_manager_managers%rowtype;
 accepted timestamptz; result jsonb;
begin
 if p_request is null or p_manager is null or p_credential is null or p_feedback is null
  or p_action is null or p_action not in ('acknowledged','resolved','closed')
  or p_expected_version is null or p_expected_version!~'^[a-f0-9]{64}$' then
  raise exception using errcode='22023',message='Exact Feedback command and version required'; end if;
 select * into manager from public.ops_manager_managers m where m.manager_id=p_manager
  and m.active and m.revoked_at is null and not m.is_system_principal
  and m.roles&&array['OPS_MANAGER','CUSTODIAL_MANAGER','DIRECTOR','SECURITY_ADMIN']::text[] for share;
 if not found then raise exception using errcode='42501',message='Current named manager required'; end if;
 perform 1 from public.ops_manager_trusted_devices d where d.credential_id=p_credential
  and d.manager_id=p_manager and d.revoked_at is null and d.expires_at>clock_timestamp()
  and d.max_access_level='full_access' for share;
 if not found then raise exception using errcode='42501',message='Current full-access manager credential required'; end if;
 perform pg_advisory_xact_lock(hashtextextended('feedback-triage:'||p_request::text,0));
 select * into old_receipt from public.system_feedback_triage_receipts where request_id=p_request;
 if found then
  if old_receipt.feedback_id<>p_feedback or old_receipt.manager_id<>p_manager
   or old_receipt.credential_id<>p_credential or old_receipt.action<>p_action
   or old_receipt.expected_version<>p_expected_version then
   raise exception using errcode='40001',message='Feedback request identity conflict'; end if;
  return jsonb_build_object('ok',true,'replayed',true,'receipt',old_receipt.receipt);
 end if;
 select * into item from public.system_feedback_items where id=p_feedback for update;
 if not found then raise exception using errcode='P0002',message='Feedback item unavailable'; end if;
 if public.custodial_feedback_triage_version(item.status,item.updated_at)<>p_expected_version
  or item.status='closed' or item.status=p_action
  or (item.status='resolved' and p_action<>'closed') then
  raise exception using errcode='40001',message='Feedback changed; refresh before a new action'; end if;
 accepted:=clock_timestamp();
 update public.system_feedback_items set status=p_action,updated_at=accepted,
  acknowledged_at=case when p_action='acknowledged' then accepted else acknowledged_at end,
  acknowledged_by=case when p_action='acknowledged' then manager.display_name else acknowledged_by end,
  metadata_json=coalesce(metadata_json,'{}'::jsonb)||jsonb_build_object(
   'status_changed_via','manager_feedback_inbox','status_changed_by',manager.display_name,
   'status_changed_manager_id',p_manager,'status_changed_credential_id',p_credential)
  where id=p_feedback returning * into item;
 result:=jsonb_build_object('request_id',p_request,'feedback_id',p_feedback,'status',p_action,
  'triage_version',public.custodial_feedback_triage_version(item.status,item.updated_at),
  'actor_manager_id',p_manager,'actor_credential_id',p_credential,'accepted_at',accepted);
 insert into public.system_feedback_triage_receipts
  (request_id,feedback_id,manager_id,credential_id,action,expected_version,receipt,accepted_at)
 values(p_request,p_feedback,p_manager,p_credential,p_action,p_expected_version,result,accepted);
 return jsonb_build_object('ok',true,'replayed',false,'receipt',result);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_feedback_triage_receipt(p_request uuid, p_manager uuid, p_credential uuid, p_feedback uuid, p_action text, p_expected_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
 original public.system_feedback_triage_receipts%ROWTYPE;
 manager public.ops_manager_managers%ROWTYPE;
 credential public.ops_manager_trusted_devices%ROWTYPE;
 accepted_text text; accepted_instant timestamptz;
 unknown_result CONSTANT jsonb := '{"ok":true,"outcome":"UNKNOWN","retry_safe":false}'::jsonb;
BEGIN
 IF p_request IS NULL OR p_manager IS NULL OR p_credential IS NULL OR p_feedback IS NULL
  OR p_action IS NULL OR p_action NOT IN ('acknowledged','resolved','closed')
  OR p_expected_version IS NULL OR length(p_expected_version)<>64
  OR p_expected_version!~'^[a-f0-9]{64}$' THEN
  RAISE EXCEPTION USING errcode='22023',message='Exact original Feedback command required';END IF;

 -- Share locks prevent a concurrent revocation/change from slipping between
 -- authorization and the bounded read. They never lock or mutate feedback.
 SELECT * INTO manager FROM public.ops_manager_managers m WHERE m.manager_id=p_manager
  AND m.active IS TRUE AND m.revoked_at IS NULL AND m.is_system_principal IS FALSE
  AND nullif(btrim(m.display_name),'') IS NOT NULL
  AND m.roles&&ARRAY['OPS_MANAGER','CUSTODIAL_MANAGER','DIRECTOR','SECURITY_ADMIN']::text[] FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING errcode='42501',message='Current named manager required';END IF;
 SELECT * INTO credential FROM public.ops_manager_trusted_devices d WHERE d.credential_id=p_credential
  AND d.manager_id=manager.manager_id AND d.revoked_at IS NULL AND d.expires_at>clock_timestamp()
  AND d.created_at<=clock_timestamp() AND d.max_access_level='full_access'
  AND nullif(btrim(d.device_id),'') IS NOT NULL FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING errcode='42501',message='Current full-access manager credential required';END IF;

 -- A foreign request never returns its stored command. No current feedback
 -- projection, caller echo, advisory writer lock, or inferred no-effect result.
 SELECT * INTO original FROM public.system_feedback_triage_receipts r
 WHERE r.request_id=p_request AND r.manager_id=p_manager AND r.credential_id=p_credential
  AND r.feedback_id=p_feedback AND r.action=p_action AND r.expected_version=p_expected_version;
 IF NOT FOUND THEN RETURN unknown_result;END IF;

 IF jsonb_typeof(original.receipt) IS DISTINCT FROM 'object'
  OR (SELECT count(*) FROM jsonb_object_keys(original.receipt))<>7
  OR NOT(original.receipt ?& ARRAY['request_id','feedback_id','status','triage_version',
    'actor_manager_id','actor_credential_id','accepted_at'])
  OR EXISTS(SELECT 1 FROM jsonb_each(original.receipt) entry WHERE jsonb_typeof(entry.value)<>'string')
  OR original.receipt->>'request_id' IS DISTINCT FROM original.request_id::text
  OR original.receipt->>'feedback_id' IS DISTINCT FROM original.feedback_id::text
  OR original.receipt->>'status' IS DISTINCT FROM original.action
  OR original.receipt->>'actor_manager_id' IS DISTINCT FROM original.manager_id::text
  OR original.receipt->>'actor_credential_id' IS DISTINCT FROM original.credential_id::text
  OR length(original.receipt->>'triage_version')<>64
  OR original.receipt->>'triage_version'!~'^[a-f0-9]{64}$'
  OR original.receipt->>'triage_version'=original.expected_version THEN RETURN unknown_result;END IF;

 -- Preserve the persisted timestamp bytes, including SQL microseconds. A
 -- genuine Gregorian date and exact civil time must match the stored instant;
 -- no current-clock cutoff, repaired date, or reconstructed acceptance value.
 accepted_text:=original.receipt->>'accepted_at';
 IF accepted_text!~'^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](\.[0-9]{1,6})?(Z|[+-]([01][0-9]|2[0-3]):[0-5][0-9])$'
  OR right(accepted_text,1) IN (chr(10),chr(13),chr(8232),chr(8233)) THEN RETURN unknown_result;END IF;
 BEGIN
  PERFORM make_date(substring(accepted_text,1,4)::integer,substring(accepted_text,6,2)::integer,
    substring(accepted_text,9,2)::integer);
  accepted_instant:=accepted_text::timestamptz;
 EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN RETURN unknown_result;
 END;
 IF accepted_instant IS DISTINCT FROM original.accepted_at THEN RETURN unknown_result;END IF;
 IF credential.expires_at<=clock_timestamp() THEN
  RAISE EXCEPTION USING errcode='42501',message='Current full-access manager credential required';END IF;
 RETURN jsonb_build_object('ok',true,'outcome','APPLIED','retry_safe',false,
  'command',jsonb_build_object('request_id',original.request_id,'feedback_id',original.feedback_id,
    'status',original.action,'expected_version',original.expected_version,
    'expected_manager_id',original.manager_id,'expected_credential_id',original.credential_id),
  'receipt',original.receipt);
END $function$

CREATE OR REPLACE FUNCTION public.custodial_finish_historical_session_authoritative(p_session_identifier text, p_device_id text, p_finish_operation_id uuid, p_client_ended_at timestamp with time zone, p_backend_execution_secret text)
 RETURNS jsonb
