CREATE OR REPLACE FUNCTION public.events_app_validate_scope_venue()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_scope text;
  v_zoo_venue public.event_venues%rowtype;
  v_primary public.event_venues%rowtype;
  v_bad_count integer;
begin
  v_scope := upper(replace(btrim(coalesce(new.event_scope, 'UNKNOWN')), '-', '_'));
  if v_scope in ('ZOO', 'ZOO_FOOTPRINT') then
    v_scope := 'ZOO_WIDE';
  elsif v_scope in ('SINGLE') then
    v_scope := 'SINGLE_VENUE';
  elsif v_scope in ('MULTI', 'MULTIPLE', 'MULTIPLE_VENUES') then
    v_scope := 'MULTI_VENUE';
  elsif v_scope = 'OFF_SITE' then
    v_scope := 'OFFSITE';
  end if;

  if v_scope not in ('ZOO_WIDE', 'SINGLE_VENUE', 'MULTI_VENUE', 'OFFSITE', 'UNKNOWN') then
    raise exception 'Invalid event scope %', new.event_scope using errcode = '23514';
  end if;

  new.event_scope := v_scope;
  new.event_timezone := coalesce(nullif(btrim(new.event_timezone), ''), 'America/Chicago');
  if new.event_timezone <> 'America/Chicago' then
    raise exception 'event_timezone must be America/Chicago' using errcode = '23514';
  end if;
  new.venue_ids := coalesce(new.venue_ids, '{}'::uuid[]);
  new.coverage_location_ids := coalesce(new.coverage_location_ids, '{}'::uuid[]);
  new.staffing_area_ids := coalesce(new.staffing_area_ids, '{}'::uuid[]);
  new.display_location := nullif(btrim(coalesce(new.display_location, '')), '');

  if new.parser_confidence is not null and new.parser_confidence not in ('high', 'medium', 'low') then
    raise exception 'parser_confidence must be high, medium, or low' using errcode = '23514';
  end if;

  if v_scope = 'ZOO_WIDE' then
    select * into v_zoo_venue
    from public.event_venues
    where venue_code = 'ZOO_FOOTPRINT' and active = true
    limit 1;
    if v_zoo_venue.id is null then
      raise exception 'Zoo Footprint venue is not configured' using errcode = '23514';
    end if;
    new.primary_venue_id := v_zoo_venue.id;
    new.venue_ids := array[v_zoo_venue.id]::uuid[];
    new.location_group_id := v_zoo_venue.location_group_id;
    new.display_location := 'Zoo Footprint';
    new.needs_review := false;
  elsif v_scope = 'SINGLE_VENUE' then
    if new.primary_venue_id is null then
      raise exception 'SINGLE_VENUE events require one eligible event venue' using errcode = '23514';
    end if;
    select * into v_primary
    from public.event_venues
    where id = new.primary_venue_id and active = true
    limit 1;
    if v_primary.id is null or v_primary.eligible_event_venue is not true or v_primary.event_scope = 'ZOO_WIDE' then
      raise exception 'Selected event venue is not eligible as a primary event venue' using errcode = '23514';
    end if;
    if not (new.primary_venue_id = any(new.venue_ids)) then
      new.venue_ids := array_prepend(new.primary_venue_id, new.venue_ids);
    end if;
    new.location_group_id := coalesce(v_primary.location_group_id, new.location_group_id);
    new.display_location := coalesce(new.display_location, v_primary.display_name);
    new.needs_review := false;
  elsif v_scope = 'MULTI_VENUE' then
    if coalesce(array_length(new.venue_ids, 1), 0) < 2 then
      raise exception 'MULTI_VENUE events require at least two eligible event venues' using errcode = '23514';
    end if;
    select count(*) into v_bad_count
    from unnest(new.venue_ids) as selected(venue_id)
    left join public.event_venues ev on ev.id = selected.venue_id and ev.active = true
    where ev.id is null or ev.eligible_event_venue is not true or ev.event_scope = 'ZOO_WIDE';
    if v_bad_count > 0 then
      raise exception 'MULTI_VENUE events contain an ineligible venue' using errcode = '23514';
    end if;
    if new.primary_venue_id is null or not (new.primary_venue_id = any(new.venue_ids)) then
      new.primary_venue_id := new.venue_ids[1];
    end if;
    select * into v_primary from public.event_venues where id = new.primary_venue_id limit 1;
    new.location_group_id := coalesce(v_primary.location_group_id, new.location_group_id);
    new.display_location := coalesce(
      new.display_location,
      (
        select string_agg(ev.display_name, ', ' order by ev.display_name)
        from public.event_venues ev
        where ev.id = any(new.venue_ids)
      )
    );
    new.needs_review := false;
  elsif v_scope = 'OFFSITE' then
    new.display_location := coalesce(new.display_location, 'Offsite');
    new.needs_review := false;
  else
    new.needs_review := true;
    new.display_location := coalesce(new.display_location, 'Needs Review');
  end if;

  select count(*) into v_bad_count
  from unnest(new.coverage_location_ids) as selected(location_group_id)
  left join public.location_groups lg on lg.id = selected.location_group_id
  where lg.id is null or lg.eligible_custodial_coverage is not true;
  if v_bad_count > 0 then
    raise exception 'coverage_location_ids contains an ineligible custodial coverage location' using errcode = '23514';
  end if;

  select count(*) into v_bad_count
  from unnest(new.staffing_area_ids) as selected(location_group_id)
  left join public.location_groups lg on lg.id = selected.location_group_id
  where lg.id is null or lg.eligible_staffing_assignment is not true;
  if v_bad_count > 0 then
    raise exception 'staffing_area_ids contains an ineligible staffing location' using errcode = '23514';
  end if;

  if new.event_scope <> 'UNKNOWN' and exists (
    select 1
    from public.location_groups lg
    where lg.id = new.location_group_id
      and lg.eligible_event_venue is not true
      and lg.eligible_event_scope is not true
      and (lg.public_restroom is true or lg.staff_restroom is true or lg.group_name ilike '%restroom%' or lg.group_code ilike '%RESTROOM%')
  ) then
    raise exception 'Restroom/custodial coverage locations cannot be saved as primary event venues' using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.feedback_email_relay_command(p_principal text, p_verb text, p_args jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  cfg public.system_feedback_email_relay_config%rowtype;
  item public.system_feedback_email_intents%rowtype;
  attempt public.system_feedback_email_attempts%rowtype;
  previous public.system_feedback_email_relay_requests%rowtype;
  req uuid;
  arg_hash text;
  result jsonb;
  observed jsonb;
  kind text;
  allowed text[];
  receipt_id uuid;
  proof jsonb;
  proof_key text;
begin
  if p_principal is null or p_principal !~ '^relay:[0-9a-f]{64}$' then
    raise exception using errcode='42501', message='Verified relay principal required';
  end if;
  if p_args is null or jsonb_typeof(p_args) <> 'object' or octet_length(p_args::text)>32768
     or p_args->>'contract_version' is distinct from 'custodial-feedback-relay.v2'
     or jsonb_typeof(p_args->'adapter_schema_sha256') is distinct from 'string'
     or p_args->>'adapter_schema_sha256' !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='22023', message='Invalid feedback relay contract';
  end if;
  allowed := case p_verb
    when 'status' then array['contract_version']
    when 'claim' then array['contract_version','request_id']
    when 'begin' then array['contract_version','request_id','intent_id','claim_token','claim_generation','envelope_sha256']
    when 'receipt' then array['contract_version','request_id','intent_id','attempt_id','envelope_sha256','observation']
    when 'defer' then array['contract_version','request_id','intent_id','claim_token','claim_generation','reason']
    when 'control' then array['contract_version','request_id','action','reason'] end;
  allowed:=allowed||array['adapter_schema_sha256'];
  if p_verb='control' and p_args->>'action'='resume_preflight_verified' then allowed:=allowed||array['preflight']; end if;
  if allowed is null or exists(select 1 from jsonb_object_keys(p_args) k where not k=any(allowed))
     or exists(select 1 from unnest(allowed) k where not p_args ? k or p_args->k='null'::jsonb) then
    raise exception using errcode='22023', message='Missing or unknown relay arguments';
  end if;
  -- Serialize the small queue's authority transitions and idempotent requests.
  -- Row locks never span a provider call. No external exactly-once assertion.
  select * into strict cfg from public.system_feedback_email_relay_config where singleton for update;
  if p_verb='status' then
    return jsonb_build_object('contract_version','custodial-feedback-relay.v2','server_now',now(),
      'paused',cfg.paused,'pause_reason',cfg.pause_reason,'recipient','eoperle@memphiszoo.org',
      'provider','outlook','provider_account','eoperle@memphiszoo.org',
      'transport_verified',coalesce(cfg.transport_verified_at>=now()-interval '15 minutes'
        and cfg.transport_principal=p_principal and cfg.transport_account='eoperle@memphiszoo.org'
        and cfg.transport_schema_sha256=p_args->>'adapter_schema_sha256',false),
      'transport_verified_at',cfg.transport_verified_at,'adapter_schema_sha256',p_args->>'adapter_schema_sha256',
      'verified_schema_sha256',cfg.transport_schema_sha256,
      'preflight_evidence_source','authenticated_connected_agent_observation',
      'counts',(select coalesce(jsonb_object_agg(state,n),'{}'::jsonb) from
        (select state,count(*) n from public.system_feedback_email_intents group by state) s),
      'protected_attachment_pending',(select count(*) from public.system_feedback_email_intents
        where feedback_snapshot->'image_attachment' is not null and feedback_snapshot->'image_attachment'<>'null'::jsonb),
      'oldest_queued_at',(select min(captured_at) from public.system_feedback_email_intents where state='queued'),
      'last_receipt_at',(select max(recorded_at) from public.system_feedback_email_receipts),
      'recoverable',(select jsonb_build_object('intent_id',id,'attempt_id',attempt_id,
        'envelope_sha256',envelope_sha256,'claim_generation',claim_generation,'claim_until',claim_until,'next_reconcile_at',next_reconcile_at,
        'reconciliation_until',reconciliation_until,'reconciliation_count',reconciliation_count,
        'mode',case when attempt_id is null then 'send' else 'reconcile' end)
        from public.system_feedback_email_intents where claim_principal=p_principal
        and (attempt_id is not null or claim_until>now()) and state not in ('inbox_observed','needs_attention')
        order by captured_at limit 1));
  end if;
  if jsonb_typeof(p_args->'request_id')<>'string' or p_args->>'request_id' !~*
    '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    raise exception using errcode='22023', message='UUID request_id required';
  end if;
  req := (p_args->>'request_id')::uuid;
  arg_hash := encode(extensions.digest(convert_to(p_args::text,'UTF8'),'sha256'),'hex');
  select * into previous from public.system_feedback_email_relay_requests where request_id=req;
  if found then
    if previous.principal<>p_principal or previous.verb<>p_verb or previous.argument_sha256<>arg_hash then
      raise exception using errcode='23505', message='Relay request_id conflict';
    end if;
    if p_verb='begin' then return previous.result || '{"may_send":false,"replayed":true}'::jsonb; end if;
    if p_verb='claim' and previous.result ? 'intent_id' then
      select * into item from public.system_feedback_email_intents where id=(previous.result->>'intent_id')::uuid;
      return previous.result || jsonb_build_object('mode',case when item.attempt_id is null then 'send' else 'reconcile' end,
        'attempt_id',item.attempt_id,'replayed',true);
    end if;
    return previous.result || '{"replayed":true}'::jsonb;
  end if;

  if p_verb='control' then
    if jsonb_typeof(p_args->'reason')<>'string' or length(p_args->>'reason') not between 1 and 300 then
      raise exception using errcode='22023', message='Bounded control reason required';
    end if;
    if p_args->>'action'='pause' then
      update public.system_feedback_email_relay_config set paused=true,pause_reason=p_args->>'reason',updated_at=now();
    elsif p_args->>'action'='prepare_preflight' then
      update public.system_feedback_email_relay_config set paused=true,pause_reason='preflight_pending',
        preflight_challenge_id=gen_random_uuid(),preflight_challenge_nonce=gen_random_uuid(),
        preflight_issued_at=now(),preflight_principal=p_principal,
        preflight_schema_sha256=p_args->>'adapter_schema_sha256',updated_at=now()
        where singleton returning * into cfg;
      result:=jsonb_build_object('ok',true,'paused',true,'challenge_id',cfg.preflight_challenge_id,
        'challenge_nonce',cfg.preflight_challenge_nonce,'issued_at',cfg.preflight_issued_at,
        'expires_at',cfg.preflight_issued_at+interval '5 minutes',
        'adapter_schema_sha256',cfg.preflight_schema_sha256,'provider_account','eoperle@memphiszoo.org');
    elsif p_args->>'action'='resume_preflight_verified' then
      proof:=p_args->'preflight';
      if jsonb_typeof(proof) is distinct from 'object'
        or exists(select 1 from jsonb_object_keys(proof) k where not k=any(array['challenge_id','challenge_nonce',
          'provider_account','profile_observed_at','profile_result_sha256','sent_folder_id','inbox_folder_id',
          'sent_read_at','sent_result_sha256','inbox_read_at','inbox_result_sha256']))
        or exists(select 1 from unnest(array['challenge_id','challenge_nonce','provider_account','profile_observed_at',
          'profile_result_sha256','sent_folder_id','inbox_folder_id','sent_read_at','sent_result_sha256',
          'inbox_read_at','inbox_result_sha256']) k where jsonb_typeof(proof->k) is distinct from 'string') then
        raise exception using errcode='22023',message='Exact typed transport preflight observation required';
      end if;
      if cfg.preflight_challenge_id is null or proof->>'challenge_id' is distinct from cfg.preflight_challenge_id::text
        or proof->>'challenge_nonce' is distinct from cfg.preflight_challenge_nonce::text
        or cfg.preflight_principal is distinct from p_principal
        or cfg.preflight_schema_sha256 is distinct from p_args->>'adapter_schema_sha256'
        or cfg.preflight_issued_at<now()-interval '5 minutes'
        or proof->>'provider_account' is distinct from 'eoperle@memphiszoo.org' then
        raise exception using errcode='55000',message='Transport preflight challenge is stale, foreign or mismatched';
      end if;
      foreach proof_key in array array['profile_result_sha256','sent_result_sha256','inbox_result_sha256'] loop
        if proof->>proof_key !~ '^[0-9a-f]{64}$' then raise exception using errcode='22023',message='Preflight result digest required';end if;
      end loop;
      foreach proof_key in array array['profile_observed_at','sent_read_at','inbox_read_at'] loop
        if proof->>proof_key !~ '(Z|[+-][0-9]{2}:[0-9]{2})$'
          or (proof->>proof_key)::timestamptz<cfg.preflight_issued_at
          or (proof->>proof_key)::timestamptz>now()+interval '30 seconds' then
          raise exception using errcode='22023',message='Preflight requires fresh reads after the server challenge';
        end if;
      end loop;
      if length(proof->>'sent_folder_id') not between 1 and 512 or length(proof->>'inbox_folder_id') not between 1 and 512
        or proof->>'sent_folder_id'=proof->>'inbox_folder_id' then
        raise exception using errcode='22023',message='Distinct exact Sent and Inbox folder identities required';
      end if;
      update public.system_feedback_email_relay_config set paused=false,pause_reason='',
        transport_verified_at=now(),transport_principal=p_principal,transport_account='eoperle@memphiszoo.org',
        transport_schema_sha256=p_args->>'adapter_schema_sha256',preflight_challenge_id=null,
        preflight_challenge_nonce=null,updated_at=now() where singleton;
      -- The immutable request receipt retains bounded observations, not a
      -- cryptographic Microsoft attestation, configuration proof or send result.
      result:=jsonb_build_object('ok',true,'paused',false,'preflight',proof,
        'observer_principal',p_principal,'adapter_schema_sha256',p_args->>'adapter_schema_sha256',
        'evidence_source','authenticated_connected_agent_observation','verified_until',now()+interval '15 minutes');
    else raise exception using errcode='22023', message='Unsupported relay control'; end if;
    result:=coalesce(result,jsonb_build_object('ok',true,'paused',p_args->>'action'='pause'));
  elsif p_verb='claim' then
    -- Persisted due times and fenced observation lease prevent overlapping
    -- minutely polls from burning the budget. No reconciliation permits resend.
    update public.system_feedback_email_intents set state='needs_attention',attention_reason='reconciliation_exhausted'
      where state in ('outcome_unknown','connector_accepted','sent_observed') and reconciliation_count>=5
        and reconciliation_until<=now();
    if exists(select 1 from public.system_feedback_email_intents where claim_principal=p_principal
      and state in ('outcome_unknown','connector_accepted','sent_observed') and reconciliation_until>now()) then
      result:=jsonb_build_object('ok',true,'busy',true,'reason','reconciliation_lease_active');
    else
      select * into item from public.system_feedback_email_intents where claim_principal=p_principal
        and state in ('outcome_unknown','connector_accepted','sent_observed') and reconciliation_count<5
        and coalesce(next_reconcile_at,'-infinity')<=now()
        order by captured_at,id limit 1 for update;
    end if;
    if item.id is not null then
      update public.system_feedback_email_intents set reconciliation_count=reconciliation_count+1,
        reconciliation_token=gen_random_uuid(),reconciliation_until=now()+interval '120 seconds',
        next_reconcile_at=now()+make_interval(secs=>case reconciliation_count
          when 0 then 300 when 1 then 900 when 2 then 1800 when 3 then 3600 else 120 end)
        where id=item.id returning * into item;
    elsif result is null then
      select * into item from public.system_feedback_email_intents where claim_principal=p_principal
        and state='claimed' and claim_until>now() order by captured_at,id limit 1 for update;
      if not found then
        if cfg.paused or cfg.transport_verified_at is null or cfg.transport_verified_at<now()-interval '15 minutes'
          or cfg.transport_principal is distinct from p_principal
          or cfg.transport_schema_sha256 is distinct from p_args->>'adapter_schema_sha256' then
          result:=jsonb_build_object('ok',true,'paused',true,'reason','transport_not_verified_or_paused');
        else
          select * into item from public.system_feedback_email_intents
            where attempt_id is null and (state='queued' or (state='claimed' and claim_until<=now()))
              and next_claim_at<=now()
            order by captured_at,id limit 1 for update skip locked;
          if found then
            update public.system_feedback_email_intents set state='claimed',claim_principal=p_principal,
              claim_token=gen_random_uuid(),claim_generation=claim_generation+1,claim_until=now()+interval '300 seconds'
              where id=item.id returning * into item;
          end if;
        end if;
      end if;
    end if;
    if item.id is not null and result is null then
      result:=jsonb_build_object('ok',true,'intent_id',item.id,'operation_id',item.operation_id,'feedback_id',item.feedback_id,
        'mode',case when item.attempt_id is null then 'send' else 'reconcile' end,'attempt_id',item.attempt_id,
        'request_fingerprint',item.request_fingerprint,'reconciliation_token',item.reconciliation_token,
        'reconciliation_until',item.reconciliation_until,'next_reconcile_at',item.next_reconcile_at,
        'envelope_sha256',item.envelope_sha256,'claim_token',item.claim_token,'claim_generation',item.claim_generation,
        'claim_until',item.claim_until,'provider','outlook','provider_account','eoperle@memphiszoo.org',
        'recipient','eoperle@memphiszoo.org','protected_attachment',(item.feedback_snapshot->'image_attachment' is not null and item.feedback_snapshot->'image_attachment'<>'null'::jsonb),'expected_subject',item.email_subject,'expected_text',item.email_text);
    end if;
    result:=coalesce(result,'{"ok":true,"empty":true}'::jsonb);
  else
    if jsonb_typeof(p_args->'intent_id')<>'string' or p_args->>'intent_id' !~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      raise exception using errcode='22023', message='UUID intent_id required';
    end if;
    select * into strict item from public.system_feedback_email_intents where id=(p_args->>'intent_id')::uuid for update;
    if p_verb in ('begin','defer') then
      if jsonb_typeof(p_args->'claim_generation')<>'number' or p_args->>'claim_generation' !~ '^[1-9][0-9]{0,8}$'
        or jsonb_typeof(p_args->'claim_token')<>'string' then
        raise exception using errcode='22023', message='Invalid claim fence';
      end if;
      if item.claim_principal is distinct from p_principal or item.claim_token::text is distinct from p_args->>'claim_token'
         or item.claim_generation<>(p_args->>'claim_generation')::integer then
        raise exception using errcode='42501', message='Stale or foreign claim';
      end if;
    end if;
    if p_verb='begin' then
      if item.envelope_sha256 is distinct from p_args->>'envelope_sha256' then
        raise exception using errcode='22023', message='Envelope mismatch';
      end if;
      if item.attempt_id is not null then
        result:=jsonb_build_object('ok',true,'may_send',false,'attempt_id',item.attempt_id,'mode','reconcile');
      elsif cfg.paused or cfg.transport_principal is distinct from p_principal or cfg.transport_verified_at is null
        or cfg.transport_verified_at<now()-interval '15 minutes' or item.claim_until<=now() or item.state<>'claimed'
        or cfg.transport_schema_sha256 is distinct from p_args->>'adapter_schema_sha256' then
        raise exception using errcode='55000', message='Send preparation is paused or expired';
      elsif item.feedback_snapshot->'image_attachment' is not null
        and item.feedback_snapshot->'image_attachment'<>'null'::jsonb and (
          item.attachment_verification_state<>'verified'
          or item.attachment_verification_claim_token is distinct from item.claim_token
          or item.attachment_verification_generation is distinct from item.claim_generation
          or item.attachment_verification_source_digest is distinct from public.static_weekly_digest_jsonb(item.feedback_snapshot->'image_attachment')
          or item.attachment_verification_sha256 is null
          or item.attachment_verified_at<now()-interval '60 seconds'
          or not public.feedback_email_attachment_source_matches(item.id)) then
        raise exception using errcode='55000',message='Protected attachment admission is missing or stale';
      else
        insert into public.system_feedback_email_attempts(intent_id,principal,envelope_sha256,claim_generation)
          values(item.id,p_principal,item.envelope_sha256,item.claim_generation) returning * into attempt;
        update public.system_feedback_email_intents set attempt_id=attempt.id,state='outcome_unknown',
          next_reconcile_at=now()+interval '60 seconds' where id=item.id;
        result:=jsonb_build_object('ok',true,'may_send',true,'attempt_id',attempt.id,
          'attempt_generation',1,'provider_generation',1,'envelope_sha256',item.envelope_sha256);
      end if;
    elsif p_verb='defer' then
      if item.attempt_id is not null or item.state<>'claimed' or item.claim_until<=now() then
        raise exception using errcode='55000', message='Only a current pre-begin claim can defer';
      end if;
      if p_args->>'reason' in ('missing_profile','auth_unavailable','configuration_unavailable','attachment_unavailable') then
        update public.system_feedback_email_relay_config set paused=true,pause_reason=p_args->>'reason',updated_at=now();
        update public.system_feedback_email_intents set state='queued',claim_until=null,claim_token=null where id=item.id;
      elsif p_args->>'reason'='transient_preflight' then
        update public.system_feedback_email_intents set preflight_failures=preflight_failures+1,
          state=case when preflight_failures>=2 then 'needs_attention' else 'queued' end,
          next_claim_at=now()+make_interval(secs=>case preflight_failures when 0 then 60 when 1 then 300 else 900 end),
          attention_reason=case when preflight_failures>=2 then 'preflight_retry_exhausted' else null end,
          claim_until=null,claim_token=null where id=item.id;
      else raise exception using errcode='22023', message='Unsupported preflight defer reason'; end if;
      result:=jsonb_build_object('ok',true,'intent_id',item.id,'deferred',true);
    elsif p_verb='receipt' then
      if item.attempt_id is null or item.attempt_id::text is distinct from p_args->>'attempt_id'
         or item.envelope_sha256 is distinct from p_args->>'envelope_sha256' then
        raise exception using errcode='22023', message='Exact attempt and envelope required';
      end if;
      select * into strict attempt from public.system_feedback_email_attempts where id=item.attempt_id;
      if attempt.principal<>p_principal then raise exception using errcode='42501', message='Foreign attempt receipt'; end if;
      observed:=p_args->'observation'; kind:=observed->>'kind';
      if jsonb_typeof(observed)<>'object' or octet_length(observed::text)>16384
        or exists(select 1 from jsonb_object_keys(observed) k where not k=any(array['kind','provider_account','to','cc','bcc',
          'subject','operation_id','feedback_id','request_fingerprint','full_text_matches','folder','provider_message_id',
          'internet_message_id','observed_at','result_sha256','match_count','reconciliation_token']))
        or observed->>'provider_account' is distinct from 'eoperle@memphiszoo.org'
        or observed->'to' is distinct from '["eoperle@memphiszoo.org"]'::jsonb
        or observed->'cc' is distinct from '[]'::jsonb or observed->'bcc' is distinct from '[]'::jsonb
        or observed->>'subject' is distinct from item.email_subject
        or observed->>'operation_id' is distinct from item.operation_id::text
        or observed->>'feedback_id' is distinct from item.feedback_id::text
        or observed->>'request_fingerprint' is distinct from item.request_fingerprint then
        raise exception using errcode='22023', message='Receipt does not bind the fixed envelope';
      end if;
      if kind not in ('connector_accepted','outcome_unknown','sent_observed','inbox_observed','multiple_matching_messages','reconciliation_not_found') or kind is null then
        -- P-01: no reviewed positive-nonacceptance mapping exists yet. Unknown
        -- tool errors/HTTP codes/absence must never create a retry generation.
        raise exception using errcode='22023', message='Unsupported observation; no nonacceptance proof mapping exists';
      end if;
      if kind in ('sent_observed','inbox_observed','multiple_matching_messages') and (
        observed->'full_text_matches' is distinct from 'true'::jsonb
        or jsonb_typeof(observed->'provider_message_id') is distinct from 'string'
        or length(observed->>'provider_message_id') not between 1 and 512
        or (kind<>'multiple_matching_messages' and observed->>'folder' is distinct from case when kind='sent_observed' then 'sent' else 'inbox' end)
        or (kind='multiple_matching_messages' and coalesce(observed->>'folder','') not in ('sent','inbox'))
        or jsonb_typeof(observed->'observed_at') is distinct from 'string') then
        raise exception using errcode='22023', message='Positive mailbox receipt requires exact text, folder and provider message ID';
      end if;
      if kind in ('sent_observed','inbox_observed','multiple_matching_messages') then
        if (observed->>'observed_at')::timestamptz>now()+interval '5 minutes' then
          raise exception using errcode='22023', message='Mailbox observation is in the future';
        end if;
      end if;
      if kind='multiple_matching_messages' and (jsonb_typeof(observed->'match_count') is distinct from 'number'
        or observed->>'match_count' !~ '^[0-9]{1,6}$' or (observed->>'match_count')::integer<2) then
        raise exception using errcode='22023', message='Duplicate observation requires multiple matches';
      end if;
      if kind='reconciliation_not_found' then
        if item.reconciliation_token is null or observed->>'reconciliation_token' is distinct from item.reconciliation_token::text
          or item.reconciliation_until<=now() or jsonb_typeof(observed->'observed_at') is distinct from 'string'
          or jsonb_typeof(observed->'result_sha256') is distinct from 'string'
          or observed->>'result_sha256' !~ '^[0-9a-f]{64}$'
          or (observed->>'observed_at')::timestamptz>now()+interval '30 seconds'
          or (observed->>'observed_at')::timestamptz<item.reconciliation_until-interval '120 seconds' then
          raise exception using errcode='22023',message='Current bounded reconciliation observation required';
        end if;
      end if;
      insert into public.system_feedback_email_receipts(intent_id,attempt_id,principal,observation)
        values(item.id,attempt.id,p_principal,observed) returning id into receipt_id;
      update public.system_feedback_email_intents set
        state=case when kind='inbox_observed' or state='inbox_observed' then 'inbox_observed'
          when kind='multiple_matching_messages' then 'needs_attention'
          when state='needs_attention' then state
          when kind='reconciliation_not_found' and reconciliation_count>=5 then 'needs_attention'
          when kind='sent_observed' or state='sent_observed' then 'sent_observed'
          when kind='connector_accepted' or state='connector_accepted' then 'connector_accepted'
          else 'outcome_unknown' end,
        possible_duplicate=possible_duplicate or kind='multiple_matching_messages',
        attention_reason=case when kind='multiple_matching_messages' then 'multiple_matching_messages'
          when kind='reconciliation_not_found' and reconciliation_count>=5 then 'reconciliation_exhausted' else attention_reason end,
        reconciliation_until=case when kind='reconciliation_not_found' then now() else reconciliation_until end
        where id=item.id;
      result:=jsonb_build_object('ok',true,'receipt_id',receipt_id,'intent_id',item.id,'attempt_id',attempt.id,
        'observer_principal',p_principal,'evidence_source','connected_agent_observation');
    else raise exception using errcode='22023', message='Unsupported relay command'; end if;
  end if;
  insert into public.system_feedback_email_relay_requests(request_id,principal,verb,argument_sha256,result)
    values(req,p_principal,p_verb,arg_hash,result);
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.feedback_email_relay_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_table_name = 'system_feedback_email_intents' and tg_op = 'UPDATE' then
    if (to_jsonb(new) - array['state','claim_principal','claim_token','claim_generation','claim_until',
      'attempt_id','preflight_failures','next_claim_at','attention_reason','reconciliation_count','possible_duplicate','next_reconcile_at','reconciliation_token','reconciliation_until','attachment_verification_ticket','attachment_verification_state','attachment_verification_claim_token','attachment_verification_generation','attachment_verification_source_digest','attachment_verification_sha256','attachment_verification_size','attachment_verification_type','attachment_verified_at'])
       = (to_jsonb(old) - array['state','claim_principal','claim_token','claim_generation','claim_until',
      'attempt_id','preflight_failures','next_claim_at','attention_reason','reconciliation_count','possible_duplicate','next_reconcile_at','reconciliation_token','reconciliation_until','attachment_verification_ticket','attachment_verification_state','attachment_verification_claim_token','attachment_verification_generation','attachment_verification_source_digest','attachment_verification_sha256','attachment_verification_size','attachment_verification_type','attachment_verified_at']) then
      return new;
    end if;
  end if;
  raise exception using errcode='23514', message='Feedback email evidence and envelope are immutable';
end;
$function$

CREATE OR REPLACE FUNCTION public.force_close_session(p_session_uuid text, p_closed_by text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_session_id uuid;
  v_location_id uuid;
  v_device_pk uuid;
  v_started_at timestamptz;
  v_ended_at timestamptz := now();
  v_duration_minutes integer;
  v_duration_display text;
  v_status text;
begin
  select s.id, s.location_id, s.device_id, s.started_at, s.status
    into v_session_id, v_location_id, v_device_pk, v_started_at, v_status
  from public.sessions s
  where s.session_uuid = p_session_uuid
    and s.status in ('active', 'pending_submit')
  limit 1;

  if v_session_id is null then
    raise exception 'Open session not found for session_uuid: %', p_session_uuid;
  end if;

  v_duration_minutes := greatest(0, round(extract(epoch from (v_ended_at - v_started_at)) / 60.0));
  v_duration_display := v_duration_minutes::text || ' min';

  update public.sessions
  set
    status = 'closed',
    ended_at = coalesce(ended_at, v_ended_at),
    duration_minutes = coalesce(duration_minutes, v_duration_minutes),
    duration_display = coalesce(duration_display, v_duration_display),
    completion_source = coalesce(completion_source, 'admin_force_close'),
    updated_at = now()
  where id = v_session_id;

  insert into public.session_events (
    session_id,
    event_type,
    actor_type,
    actor_ref,
    details_json
  )
  values (
    v_session_id,
    'session_force_closed',
    'admin',
    coalesce(nullif(trim(p_closed_by), ''), 'unknown'),
    jsonb_build_object(
      'reason', p_reason,
      'previous_status', v_status,
      'forced_at', v_ended_at
    )
  );

  insert into public.system_logs (
    level,
    source,
    message,
    session_id,
    location_id,
    device_id
  )
  values (
    'WARN',
    'force_close_session',
    'Session force-closed by admin',
    v_session_id,
    v_location_id,
    v_device_pk
  );

  return jsonb_build_object(
    'session_uuid', p_session_uuid,
    'status', 'closed',
    'closed_at', v_ended_at,
    'closed_by', coalesce(nullif(trim(p_closed_by), ''), 'unknown'),
    'reason', p_reason
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.gemini_console_authorize_repair(p_proposal_id uuid, p_manager_id uuid, p_credential_id uuid, p_authorization_message_id uuid, p_operation_id uuid, p_release_id text, p_backend_commit text, p_frontend_commit text, p_schema_fingerprint text, p_correlation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_proposal public.gemini_console_repair_proposals%rowtype;
  v_authorization public.gemini_console_messages%rowtype;
  v_job public.gemini_console_repair_jobs%rowtype;
  v_kind text;
begin
  select * into v_proposal from public.gemini_console_repair_proposals
  where proposal_id = p_proposal_id for update;
  if not found then raise exception 'repair proposal not found'; end if;
  if v_proposal.status <> 'proposed' or v_proposal.expires_at <= now() then raise exception 'repair proposal is no longer authorizable'; end if;

  if not exists (
    select 1 from public.ops_manager_managers m
    where m.manager_id = p_manager_id and m.active and m.revoked_at is null
      and 'CUSTODIAL_MANAGER' = any(m.roles)
  ) then raise exception 'Custodial Manager authorization is required'; end if;
  if not exists (
    select 1 from public.ops_manager_trusted_devices d
    where d.credential_id = p_credential_id and d.manager_id = p_manager_id
      and d.revoked_at is null and d.expires_at > now()
  ) then raise exception 'active approving credential is required'; end if;

  select * into v_authorization from public.gemini_console_messages
  where message_id = p_authorization_message_id and manager_id = p_manager_id
    and conversation_id = v_proposal.conversation_id and role='user' for update;
  if not found or v_authorization.metadata_json->>'source' <> 'direct_authenticated_user' then
    raise exception 'direct authenticated authorization message is required';
  end if;
  if lower(btrim(v_authorization.body)) !~ '^(go ahead and repair that|implement the plan|fix it|proceed with the repair)[.! ]*$' then
    raise exception 'authorization message is not an explicit repair instruction';
  end if;

  v_kind := case when v_proposal.repair_kind='acceptance_probe' then 'acceptance_probe' else 'controlled_worker' end;
  insert into public.gemini_console_repair_jobs(
    proposal_id, conversation_id, approving_manager_id, approving_credential_id,
    authorization_message_id, operation_id, status, execution_mode,
    affected_components, starting_backend_commit, starting_frontend_commit,
    starting_schema_fingerprint, release_id, backup_reference, metadata_json
  ) values (
    v_proposal.proposal_id, v_proposal.conversation_id, p_manager_id, p_credential_id,
    p_authorization_message_id, p_operation_id,
    case when v_kind='acceptance_probe' then 'completed' else 'authorized' end,
    v_kind, v_proposal.affected_components,
    nullif(btrim(p_backend_commit),''), nullif(btrim(p_frontend_commit),''),
    nullif(btrim(p_schema_fingerprint),''), nullif(btrim(p_release_id),''),
    'required_before_worker_claim',
    jsonb_build_object('plan_sha256',v_proposal.plan_sha256,'authorization_source','direct_authenticated_user')
  )
  on conflict (proposal_id) do update set updated_at=now()
  returning * into v_job;

  if v_kind='acceptance_probe' then
    update public.gemini_console_repair_jobs
    set started_at=coalesce(started_at,now()), finished_at=coalesce(finished_at,now()),
        test_evidence=jsonb_build_array(jsonb_build_object('kind','database_transaction','result','pass')),
        verification_evidence=jsonb_build_array(jsonb_build_object('kind','durable_job_readback','result','pass')),
        rollback_evidence=jsonb_build_array(jsonb_build_object('kind','no_production_feature_changed','result','pass')),
        updated_at=now()
    where repair_job_id=v_job.repair_job_id
    returning * into v_job;
  end if;

  update public.gemini_console_repair_proposals
  set status='authorized', authorized_at=now()
  where proposal_id=v_proposal.proposal_id;
  insert into public.gemini_console_repair_job_events(
    repair_job_id,event_type,status,correlation_id,actor_manager_id,detail_json
  ) values (
    v_job.repair_job_id,'repair_authorized',v_job.status,p_correlation_id,p_manager_id,
    jsonb_build_object('execution_mode',v_kind,'plan_sha256',v_proposal.plan_sha256)
  );
  return to_jsonb(v_job);
end
$function$

CREATE OR REPLACE FUNCTION public.gemini_console_begin_turn(p_conversation_id uuid, p_manager_id uuid, p_client_message_id uuid, p_body text, p_attachment_ids uuid[], p_correlation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_conversation public.gemini_console_conversations%rowtype;
  v_message public.gemini_console_messages%rowtype;
  v_assistant public.gemini_console_messages%rowtype;
  v_inserted boolean := false;
  v_claimed boolean := false;
  v_expected integer := coalesce(cardinality(p_attachment_ids), 0);
  v_attached integer := 0;
begin
  if p_conversation_id is null or p_manager_id is null or p_client_message_id is null or p_correlation_id is null then
    raise exception 'conversation, manager, client message, and correlation identifiers are required';
  end if;
  if nullif(btrim(coalesce(p_body, '')), '') is null then raise exception 'message body is required'; end if;
  if char_length(p_body) > 30000 then raise exception 'message body exceeds 30000 characters'; end if;

  select * into v_conversation
  from public.gemini_console_conversations
  where conversation_id = p_conversation_id
  for update;
  if not found or v_conversation.status <> 'active' then raise exception 'active conversation not found'; end if;
  if v_conversation.owner_manager_id <> p_manager_id then raise exception 'conversation access denied'; end if;
  if not exists (
    select 1 from public.ops_manager_managers m
    where m.manager_id = p_manager_id and m.active and m.revoked_at is null
  ) then raise exception 'active manager not found'; end if;

  if v_expected > 8
    or exists(select 1 from unnest(p_attachment_ids) id where id is null)
    or (select count(distinct id) from unnest(p_attachment_ids) id) <> v_expected
  then raise exception 'original attachment identifiers must be distinct and bounded'; end if;

  insert into public.gemini_console_messages(
    conversation_id, manager_id, role, body, state, client_message_id,
    correlation_id, metadata_json
  ) values (
    p_conversation_id, p_manager_id, 'user', p_body, 'queued',
    p_client_message_id, p_correlation_id,
    jsonb_build_object('source', 'direct_authenticated_user',
      'original_attachment_ids',to_jsonb(coalesce(p_attachment_ids,'{}'::uuid[])),
      'original_client_time_policy','LOCAL_DISPLAY_METADATA_NOT_SERVER_AUTHORITY')
  )
  on conflict (manager_id, client_message_id) do nothing
  returning * into v_message;
  v_inserted := found;

  if not v_inserted then
    select * into v_message
    from public.gemini_console_messages
    where manager_id = p_manager_id and client_message_id = p_client_message_id
    for update;
    if v_message.conversation_id <> p_conversation_id or v_message.role <> 'user' or v_message.body <> p_body then
      raise exception 'client message identifier conflicts with another logical message';
    end if;
  end if;

  -- A legacy/mismatched original cannot adopt newly supplied pins.
  if v_message.correlation_id is distinct from p_correlation_id
    or v_message.metadata_json->'original_attachment_ids' is distinct from to_jsonb(coalesce(p_attachment_ids,'{}'::uuid[]))
    or v_message.metadata_json->>'original_client_time_policy' is distinct from 'LOCAL_DISPLAY_METADATA_NOT_SERVER_AUTHORITY'
  then raise exception 'original message request identity is unavailable or conflicts'; end if;

  if v_expected > 0 then
    update public.gemini_console_attachments
    set message_id = v_message.message_id,
        status = 'attached',
        attached_at = coalesce(attached_at, now())
    where attachment_id = any(p_attachment_ids)
      and conversation_id = p_conversation_id
      and manager_id = p_manager_id
      and (status = 'pending' or message_id = v_message.message_id);
    get diagnostics v_attached = row_count;
    if v_attached <> v_expected then raise exception 'one or more attachments are unavailable'; end if;
  end if;

  select * into v_assistant
  from public.gemini_console_messages
  where response_to_message_id = v_message.message_id and role = 'assistant'
  limit 1;

  if v_assistant.message_id is null and v_message.state in ('queued','failed','cancelled') then
    update public.gemini_console_messages
    set state = 'generating', error_code = null, error_message = null,
        cancelled_at = null
    where message_id = v_message.message_id
      and state in ('queued','failed','cancelled')
    returning * into v_message;
    v_claimed := found;
  end if;

  update public.gemini_console_conversations
  set last_activity_at = now(), updated_at = now(),
      title = case when title = 'New chat' then left(regexp_replace(p_body, E'[\\n\\r\\t]+', ' ', 'g'), 80) else title end
  where conversation_id = p_conversation_id;

  return jsonb_build_object(
    'inserted', v_inserted,
    'claimed', v_claimed,
    'user_message', to_jsonb(v_message),
    'assistant_message', case when v_assistant.message_id is null then null else to_jsonb(v_assistant) end
  );
end
$function$

CREATE OR REPLACE FUNCTION public.gemini_console_complete_turn(p_user_message_id uuid, p_body text, p_provider text, p_model text, p_correlation_id uuid, p_metadata_json jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_user public.gemini_console_messages%rowtype;
  v_assistant public.gemini_console_messages%rowtype;
begin
  select * into v_user from public.gemini_console_messages
  where message_id = p_user_message_id and role = 'user' for update;
  if not found then raise exception 'user message not found'; end if;
  if v_user.correlation_id is distinct from p_correlation_id
    or not exists(select 1 from public.ops_manager_managers m
      where m.manager_id=v_user.manager_id and m.active and m.revoked_at is null)
  then raise exception 'original turn identity or manager authority changed'; end if;
  select * into v_assistant from public.gemini_console_messages
    where response_to_message_id=v_user.message_id and role='assistant' for update;
  if found then
    if v_user.state<>'completed' or v_assistant.state<>'completed'
      or v_assistant.manager_id is distinct from v_user.manager_id
      or v_assistant.conversation_id is distinct from v_user.conversation_id
      or v_assistant.correlation_id is distinct from p_correlation_id
      or v_assistant.body is distinct from coalesce(p_body,'')
      or v_assistant.provider is distinct from nullif(btrim(p_provider),'')
      or v_assistant.model is distinct from nullif(btrim(p_model),'')
      or v_assistant.metadata_json is distinct from coalesce(p_metadata_json,'{}'::jsonb)
    then raise exception 'original completed turn conflicts; history retained'; end if;
    return to_jsonb(v_assistant);
  end if;
  if v_user.state<>'generating' then raise exception 'original turn is not generating'; end if;

  insert into public.gemini_console_messages(
    conversation_id, manager_id, role, body, state, client_message_id,
    response_to_message_id, correlation_id, provider, model, metadata_json,
    completed_at
  ) values (
    v_user.conversation_id, v_user.manager_id, 'assistant', coalesce(p_body,''),
    'completed', gen_random_uuid(), v_user.message_id, p_correlation_id,
    nullif(btrim(p_provider),''), nullif(btrim(p_model),''),
    coalesce(p_metadata_json,'{}'::jsonb), now()
  )
  on conflict (response_to_message_id) where response_to_message_id is not null and role = 'assistant'
  do nothing
  returning * into v_assistant;

  if not found then raise exception 'original completed turn conflicted; history retained'; end if;

  update public.gemini_console_messages
  set state = 'completed', completed_at = now(), error_code = null, error_message = null
  where message_id = v_user.message_id;
  update public.gemini_console_conversations
  set updated_at = now(), last_activity_at = now()
  where conversation_id = v_user.conversation_id;
  return to_jsonb(v_assistant);
end
$function$

CREATE OR REPLACE FUNCTION public.gemini_console_finish_repair_job(p_repair_job_id uuid, p_lease_token uuid, p_status text, p_branch_name text DEFAULT NULL::text, p_changed_files jsonb DEFAULT '[]'::jsonb, p_test_evidence jsonb DEFAULT '[]'::jsonb, p_migration_evidence jsonb DEFAULT '[]'::jsonb, p_deployment_evidence jsonb DEFAULT '[]'::jsonb, p_verification_evidence jsonb DEFAULT '[]'::jsonb, p_rollback_evidence jsonb DEFAULT '[]'::jsonb, p_error_code text DEFAULT NULL::text, p_error_message text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_job public.gemini_console_repair_jobs%rowtype;
begin
  if p_status not in ('completed','failed','rolled_back','blocked','cancelled') then raise exception 'invalid terminal repair status'; end if;
  if p_status='completed' and (
    jsonb_typeof(coalesce(p_test_evidence,'[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_test_evidence,'[]'::jsonb))=0
    or jsonb_typeof(coalesce(p_verification_evidence,'[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_verification_evidence,'[]'::jsonb))=0
  ) then raise exception 'completed repair requires test and verification evidence'; end if;
  update public.gemini_console_repair_jobs
  set status=p_status, branch_name=nullif(btrim(coalesce(p_branch_name,'')),''),
      changed_files=coalesce(p_changed_files,'[]'::jsonb), test_evidence=coalesce(p_test_evidence,'[]'::jsonb),
      migration_evidence=coalesce(p_migration_evidence,'[]'::jsonb), deployment_evidence=coalesce(p_deployment_evidence,'[]'::jsonb),
      verification_evidence=coalesce(p_verification_evidence,'[]'::jsonb), rollback_evidence=coalesce(p_rollback_evidence,'[]'::jsonb),
      error_code=nullif(left(coalesce(p_error_code,''),80),''), error_message=nullif(left(coalesce(p_error_message,''),1000),''),
      finished_at=clock_timestamp(), updated_at=clock_timestamp(), lease_owner=null, lease_token=null, leased_until=null
  where repair_job_id=p_repair_job_id and lease_token=p_lease_token
    and backup_reference is not null and leased_until >= clock_timestamp()
  returning * into v_job;
  if not found then raise exception 'active repair lease with completed backup is required'; end if;
  insert into public.gemini_console_repair_job_events(repair_job_id,event_type,status,correlation_id,detail_json)
  values(v_job.repair_job_id,'repair_finished',v_job.status,gen_random_uuid(),jsonb_build_object('changed_files',v_job.changed_files));
  return to_jsonb(v_job);
end
$function$

CREATE OR REPLACE FUNCTION public.get_setting_bool(p_setting_key text, p_default boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v jsonb;
begin
  select public.get_setting(p_setting_key) into v;
  if v is null then
    return p_default;
  end if;
  return (v::text)::boolean;
exception
  when others then
    return p_default;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_setting_text(p_setting_key text, p_default text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v jsonb;
begin
  select public.get_setting(p_setting_key) into v;
  if v is null then
    return p_default;
  end if;
  return trim(both '"' from v::text);
end;
$function$

CREATE OR REPLACE FUNCTION public.list_device_notification_acknowledgements(p_device_identifier text, p_limit integer DEFAULT 500)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_requested text := nullif(btrim(coalesce(p_device_identifier,'')), '');
  v_device text;
  v_limit integer := greatest(1, least(coalesce(p_limit,500), 2000));
  v_result jsonb;
begin
  if v_requested is null or length(v_requested) > 200 then
    raise exception 'device_identifier is required and must be at most 200 characters';
  end if;

  select d.device_id into v_device
  from public.devices d
  where d.active = true and upper(btrim(d.device_id)) = upper(v_requested)
  limit 1;

  if v_device is null then
    select d.device_id into v_device
    from public.device_aliases da
    join public.devices d on d.id = da.canonical_device_id and d.active = true
    where da.active = true and upper(btrim(da.alias_identifier)) = upper(v_requested)
    limit 1;
  end if;

  if v_device is null then raise exception 'Active device not found: %', v_requested; end if;

  select coalesce(jsonb_agg(to_jsonb(x) order by x.updated_at desc), '[]'::jsonb)
    into v_result
  from (
    select notification_key, notification_type, displayed_at, dismissed_at,
           opened_at, acknowledged_at, updated_at
    from public.device_notification_acknowledgements
    where device_identifier = v_device
      and acknowledged_at is not null
    order by updated_at desc
    limit v_limit
  ) x;

  return jsonb_build_object(
    'device_identifier', v_device,
    'acknowledgements', v_result
  );
end
$function$

CREATE OR REPLACE FUNCTION public.mcp_oauth_consume_decision_v2(p_artifact_digest text, p_expires_at bigint, p_authority_generation text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '5s'
 SET statement_timeout TO '8s'
AS $function$
declare v_authority_generation bigint;
begin
  v_authority_generation := public.custodial_begin_application_mutation();
  if p_authority_generation is null or p_authority_generation <> v_authority_generation::text then return false; end if;
  if p_artifact_digest is null or p_artifact_digest !~ '^[0-9a-f]{64}$' or p_expires_at is null
    or p_expires_at <= extract(epoch from clock_timestamp()) or p_expires_at > extract(epoch from clock_timestamp())+600 then return false; end if;
  insert into public.mcp_oauth_replay_artifacts_v2(artifact_digest,authority_generation,artifact_kind,expires_at)
    values(p_artifact_digest,v_authority_generation,'decision',to_timestamp(p_expires_at)) on conflict do nothing;
  if not found then return false; end if;
  -- Unique-key contention can wait past expiration. Raising rolls back the insert.
  if p_expires_at <= extract(epoch from clock_timestamp()) then raise exception 'OAuth decision expired' using errcode='22023'; end if;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.mcp_oauth_exchange_code_v2(p_code_digest text, p_code_expires_at bigint, p_family_digest text, p_binding_digest text, p_refresh_digest text, p_expires_at bigint, p_authority_generation text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '5s'
 SET statement_timeout TO '8s'
AS $function$
declare v_authority_generation bigint;
begin
  v_authority_generation := public.custodial_begin_application_mutation();
  if p_authority_generation is null or p_authority_generation <> v_authority_generation::text then return false; end if;
  if p_code_digest is null or p_code_digest !~ '^[0-9a-f]{64}$'
    or p_family_digest is null or p_family_digest !~ '^[0-9a-f]{64}$'
    or p_binding_digest is null or p_binding_digest !~ '^[0-9a-f]{64}$'
    or (p_refresh_digest is not null and p_refresh_digest !~ '^[0-9a-f]{64}$')
    or p_code_expires_at is null or p_expires_at is null
    or p_code_expires_at <= extract(epoch from clock_timestamp())
    or p_code_expires_at > extract(epoch from clock_timestamp())+600
    or p_expires_at <= extract(epoch from clock_timestamp())
    or p_expires_at > extract(epoch from clock_timestamp())+2592000 then return false; end if;
  insert into public.mcp_oauth_replay_artifacts_v2(artifact_digest,authority_generation,artifact_kind,expires_at)
    values(p_code_digest,v_authority_generation,'code',to_timestamp(p_code_expires_at)) on conflict do nothing;
  if not found then return false; end if;
  -- This family INSERT and the code's one-use INSERT commit or roll back together.
  insert into public.mcp_oauth_token_families_v2(family_digest,authority_generation,binding_digest,current_refresh_digest,expires_at)
    values(p_family_digest,v_authority_generation,p_binding_digest,p_refresh_digest,to_timestamp(p_expires_at));
  if p_code_expires_at <= extract(epoch from clock_timestamp()) or p_expires_at <= extract(epoch from clock_timestamp()) then
    raise exception 'OAuth code expired' using errcode='22023'; end if;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.mcp_oauth_rotate_refresh_v2(p_family_digest text, p_binding_digest text, p_previous_digest text, p_generation bigint, p_next_digest text, p_expires_at bigint, p_authority_generation text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '5s'
 SET statement_timeout TO '8s'
AS $function$
declare f public.mcp_oauth_token_families_v2%rowtype; v_authority_generation bigint;
begin
  v_authority_generation := public.custodial_begin_application_mutation();
  if p_authority_generation is null or p_authority_generation <> v_authority_generation::text then return false; end if;
  if p_family_digest is null or p_family_digest !~ '^[0-9a-f]{64}$'
    or p_binding_digest is null or p_binding_digest !~ '^[0-9a-f]{64}$'
    or p_previous_digest is null or p_previous_digest !~ '^[0-9a-f]{64}$'
    or p_next_digest is null or p_next_digest !~ '^[0-9a-f]{64}$' or p_next_digest=p_previous_digest
    or p_generation is null or p_generation < 0 or p_generation >= 9007199254740991
    or p_expires_at is null then return false; end if;
  select * into f from public.mcp_oauth_token_families_v2 where family_digest=p_family_digest for update;
  if not found or f.authority_generation <> v_authority_generation or f.binding_digest <> p_binding_digest or f.revoked_at is not null
    or f.expires_at <= clock_timestamp() or p_expires_at <= extract(epoch from clock_timestamp())
    or p_expires_at > extract(epoch from clock_timestamp())+2592000 then return false; end if;
  if f.generation<>p_generation or f.current_refresh_digest is distinct from p_previous_digest then
    -- Return false rather than raising: the reuse revocation MUST commit.
    update public.mcp_oauth_token_families_v2 set revoked_at=clock_timestamp(),revocation_reason='refresh_reuse'
      where family_digest=p_family_digest;
    return false;
  end if;
  update public.mcp_oauth_token_families_v2 set current_refresh_digest=p_next_digest,
    generation=p_generation+1,expires_at=to_timestamp(p_expires_at) where family_digest=p_family_digest;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.moxie_save_chat_state(p_expected_revision bigint, p_history jsonb, p_saved_chats jsonb)
 RETURNS annie_chat_state
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_row public.annie_chat_state;
begin
  if p_expected_revision is null or p_expected_revision < 1 then
    raise exception using errcode = '22023', message = 'expected revision is required';
  end if;
  if jsonb_typeof(coalesce(p_history, '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_saved_chats, '[]'::jsonb)) <> 'array' then
    raise exception 'chat state must contain arrays';
  end if;
  insert into public.annie_chat_state(id, history, saved_chats, revision, updated_at)
  values ('default', coalesce(p_history, '[]'::jsonb), coalesce(p_saved_chats, '[]'::jsonb), 1, now())
  on conflict (id) do nothing;
  update public.annie_chat_state
  set history = coalesce(p_history, '[]'::jsonb),
      saved_chats = coalesce(p_saved_chats, '[]'::jsonb),
      revision = revision + 1,
      updated_at = now()
  where id = 'default'
    and revision = p_expected_revision
  returning * into v_row;
  if v_row.id is null then
    raise exception using errcode = '40001', message = 'Moxie chat state changed in another browser.';
  end if;
  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.msg_acknowledge_event_device_notification(p_device_identifier text, p_notification_key text, p_notification_type text, p_action text, p_metadata_json jsonb, p_message_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_device public.devices%rowtype;
  v_instance public.event_push_instances%rowtype;
  v_log public.events_app_notification_log%rowtype;
  v_linked_user public.msg_users%rowtype;
  v_message public.msg_messages%rowtype;
  v_thread_id uuid;
  v_notification jsonb;
  v_receipt public.msg_receipts%rowtype;
begin
  select * into v_device
  from public.devices d
  where d.active is true
    and upper(btrim(d.device_id))=upper(btrim(coalesce(p_device_identifier,'')))
  for update;
  if v_device.id is null then
    raise exception using errcode='P0002',message='Active canonical device was not found for event acknowledgement';
  end if;

  select i.* into v_instance
  from public.event_push_instances i
  join public.device_auth_credentials c
    on c.credential_id=i.credential_id
   and c.device_id=v_device.id
   and c.confirmed_at is not null
   and c.revoked_at is null
   and c.expires_at>now()
  where i.notification_key=btrim(coalesce(p_notification_key,''))
    and i.device_id=v_device.id
    and i.employee_id=v_device.assigned_employee_id
    and i.assignment_epoch=v_device.assignment_epoch
    and i.state in ('sent','opened')
  for update of i;
  if v_instance.instance_id is null then
    raise exception using errcode='P0002',message='Active event notification was not found for this device assignment';
  end if;

  select * into v_log
  from public.events_app_notification_log l
  where l.event_id=v_instance.event_id
    and l.employee_id=v_instance.employee_id
    and l.notification_kind=v_instance.notification_kind
  for update;

  if v_log.id is not null and v_log.response_message_id is not null then
    if v_log.status<>'sent' or v_log.msg_user_id is null or v_log.thread_id is null then
      raise exception using errcode='23514',message='Authoritative Event-to-Messenger notification linkage is invalid';
    end if;
    select * into v_linked_user
    from public.msg_users u
    where u.id=v_log.msg_user_id
      and u.employee_id=v_instance.employee_id
      and u.is_active is true
    for key share;
    if v_linked_user.id is null or p_user_id is null or p_user_id<>v_linked_user.id then
      raise exception using errcode='42501',message='Server-derived Messenger user does not match the authoritative event notification recipient';
    end if;
    select * into v_message
    from public.msg_messages m
    where m.id=v_log.response_message_id
      and m.thread_id=v_log.thread_id
    for key share;
    if v_message.id is null then
      raise exception using errcode='23514',message='Authoritative Event-to-Messenger response message linkage is invalid';
    end if;
    if p_message_id is not null and p_message_id<>v_message.id then
      raise exception using errcode='23514',message='Provided message id does not match the authoritative event notification link';
    end if;
    v_thread_id:=v_message.thread_id;
    perform public.msg_assert_active_mutable_thread(v_thread_id);
    if not exists (
      select 1 from public.msg_thread_participants p
      where p.thread_id=v_thread_id and p.user_id=v_linked_user.id and p.left_at is null
    ) then
      raise exception using errcode='42501',message='Authoritative event recipient is not an active Messenger participant';
    end if;
    if not exists (
      select 1 from public.msg_receipts r
      where r.message_id=v_message.id and r.user_id=v_linked_user.id
    ) then
      raise exception using errcode='P0002',message='Authoritative event message receipt was not found';
    end if;
  elsif p_message_id is not null then
    raise exception using errcode='23514',message='Provided message id has no authoritative Event-to-Messenger link';
  end if;

  v_notification:=public.ack_device_notification(
    v_device.device_id,v_instance.notification_key,p_notification_type,p_action,p_metadata_json
  );
  if v_message.id is not null then
    v_receipt:=public.msg_acknowledge_message(v_message.id,v_linked_user.id,v_device.device_id);
  end if;
  return v_notification || jsonb_build_object(
    'event_push_instance_id',v_instance.instance_id,
    'message_receipt_id',v_receipt.id,
    'linked_message_id',v_message.id
  );
end
$function$

CREATE OR REPLACE FUNCTION public.msg_acknowledge_message(p_message_id uuid, p_user_id uuid, p_device_identifier text)
 RETURNS msg_receipts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_receipt public.msg_receipts%rowtype;
begin
  perform public.msg_assert_active_mutable_message(p_message_id);
  update public.msg_receipts set delivered_at=coalesce(delivered_at,now()),displayed_at=coalesce(displayed_at,now()),read_at=coalesce(read_at,now()),acknowledged_at=coalesce(acknowledged_at,now()),delivery_device_identifier=nullif(btrim(coalesce(p_device_identifier,'')), '')
  where message_id=p_message_id and user_id=p_user_id returning * into v_receipt;
  if not found then raise exception 'Message receipt not found.'; end if;
  return v_receipt;
end
$function$

CREATE OR REPLACE FUNCTION public.msg_admin_tombstone_thread(p_thread_id uuid, p_request_user_id uuid, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_thread public.msg_threads%rowtype;
  v_existing public.msg_thread_deletion_operations%rowtype;
  v_now timestamptz:=clock_timestamp();
  v_deleted_messages integer:=0;
begin
  if p_thread_id is null or p_request_user_id is null or p_operation_id is null then
    raise exception using errcode='22023',message='Thread, authenticated admin, and deletion operation are required';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_operation_id::text,0));
  select * into v_existing from public.msg_thread_deletion_operations where operation_id=p_operation_id;
  if v_existing.operation_id is not null then
    if v_existing.thread_id<>p_thread_id or v_existing.user_id<>p_request_user_id or v_existing.deletion_scope<>'global' then
      raise exception using errcode='23505',message='Deletion operation id was already used for another target';
    end if;
    return jsonb_build_object('ok',true,'thread_id',v_existing.thread_id,'deleted',true,'deletion_scope','global','deleted_at',v_existing.deleted_at,'purge_after',v_existing.deleted_at+interval '14 days','operation_id',v_existing.operation_id,'replayed',true);
  end if;
  perform public.msg_assert_active_mutable_thread(p_thread_id);
  if not exists (
    select 1
    from public.msg_users u
    join public.ops_manager_managers m on m.manager_id=u.ops_manager_id
    where u.id=p_request_user_id
      and u.role='manager'
      and u.is_active is true
      and m.active is true
      and m.revoked_at is null
      and m.is_system_principal is false
      and 'SECURITY_ADMIN'=any(m.roles)
  ) then
    raise exception using errcode='42501',message='An active named SECURITY_ADMIN Messenger principal is required for global tombstoning';
  end if;
  select * into v_thread from public.msg_threads where id=p_thread_id for update;
  update public.msg_messages set is_deleted=true,body='[deleted]',deleted_at=coalesce(deleted_at,v_now),deleted_by_user_id=coalesce(deleted_by_user_id,p_request_user_id),purge_after=coalesce(purge_after,coalesce(deleted_at,v_now)+interval '14 days'),metadata_json=(coalesce(metadata_json,'{}'::jsonb)-'deleted_by'-'deleted_at')||jsonb_build_object('deletion_retention_days',14,'conversation_globally_tombstoned',true),updated_at=v_now
  where thread_id=p_thread_id and is_deleted is false;
  get diagnostics v_deleted_messages=row_count;
  update public.msg_threads set is_active=false,deleted_at=v_now,deleted_by_user_id=p_request_user_id,deletion_operation_id=p_operation_id,purge_after=v_now+interval '14 days',last_message_at=null,updated_at=v_now where id=p_thread_id returning * into v_thread;
  insert into public.msg_thread_deletion_operations(operation_id,thread_id,user_id,deletion_scope,deleted_through,deleted_at,thread_type,metadata_json)
  values(p_operation_id,p_thread_id,p_request_user_id,'global',v_now,v_now,v_thread.thread_type,jsonb_build_object('deleted_message_count',v_deleted_messages));
  return jsonb_build_object('ok',true,'thread_id',p_thread_id,'deleted',true,'deletion_scope','global','deleted_at',v_now,'purge_after',v_now+interval '14 days','operation_id',p_operation_id,'deleted_message_count',v_deleted_messages,'replayed',false);
end
$function$

CREATE OR REPLACE FUNCTION public.msg_assert_active_mutable_message(p_message_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_thread_id uuid;
begin
  if p_message_id is null then
    raise exception using errcode='22023',message='message_id is required.';
  end if;
  select m.thread_id into v_thread_id
  from public.msg_messages m
  where m.id=p_message_id
  for key share;
  if v_thread_id is null then
    raise exception using errcode='P0002',message='Message not found';
  end if;
  perform public.msg_assert_active_mutable_thread(v_thread_id);
end
$function$

CREATE OR REPLACE FUNCTION public.msg_assert_active_mutable_thread(p_thread_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_thread public.msg_threads%rowtype;
begin
  if p_thread_id is null then
    raise exception using errcode='22023',message='thread_id is required.';
  end if;
  select * into v_thread
  from public.msg_threads
  where id=p_thread_id
  for update;
  if v_thread.id is null then
    raise exception using errcode='P0002',message='Conversation not found';
  end if;
  if v_thread.system_key='ops_manager_shared_chat_v1' then
    raise exception using errcode='23514',message='The retired Operations Leadership conversation is immutable';
  end if;
  if v_thread.is_active is not true then
    raise exception using errcode='23514',message='Conversation is retired or inactive';
  end if;
end
$function$

CREATE OR REPLACE FUNCTION public.msg_assert_no_ambiguous_active_pair_for_thread(p_thread_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_thread public.msg_threads%rowtype;
  v_low uuid;
  v_high uuid;
  v_candidate_count integer;
begin
  select * into v_thread from public.msg_threads where id=p_thread_id;
  if v_thread.id is null or v_thread.is_active is not true or v_thread.thread_type not in ('direct','bot') then return; end if;
  select (array_agg(p.user_id order by p.user_id))[1],(array_agg(p.user_id order by p.user_id))[2] into v_low,v_high
  from public.msg_thread_participants p where p.thread_id=p_thread_id and p.left_at is null;
  if v_low is null or v_low=v_high or 2<>(select count(*) from public.msg_thread_participants p where p.thread_id=p_thread_id and p.left_at is null) then return; end if;
  perform pg_advisory_xact_lock(hashtextextended('msg-canonical-conversation-pair:v1:'||v_low::text||':'||v_high::text,0));
  select count(*) into v_candidate_count
  from public.msg_threads t
  join public.msg_thread_participants p1 on p1.thread_id=t.id and p1.user_id=v_low and p1.left_at is null
  join public.msg_thread_participants p2 on p2.thread_id=t.id and p2.user_id=v_high and p2.left_at is null
  where t.is_active is true and t.thread_type in ('direct','bot')
    and 2=(select count(*) from public.msg_thread_participants px where px.thread_id=t.id and px.left_at is null);
  if v_candidate_count>1 then
    raise exception using errcode='23505',message='Ambiguous active Messenger canonical pair has more than one candidate';
  end if;
end
$function$

CREATE OR REPLACE FUNCTION public.msg_create_group_thread(p_created_by_user_id uuid, p_title text, p_member_user_ids uuid[])
 RETURNS msg_threads
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_thread public.msg_threads%rowtype;
  v_member_id uuid;
  v_title text;
  v_member_ids uuid[];
begin
  if p_created_by_user_id is null then
    raise exception 'created_by_user_id is required.';
  end if;
  if not exists (select 1 from public.msg_users where id = p_created_by_user_id and is_active = true) then
    raise exception 'Creator not found or inactive.';
  end if;

  v_member_ids := array(
    select distinct x
    from unnest(coalesce(p_member_user_ids, array[]::uuid[])) as x
    where x is not null
      and x <> p_created_by_user_id
  );

  if coalesce(array_length(v_member_ids, 1), 0) < 2 then
    raise exception 'Group thread requires at least two additional members.';
  end if;

  if exists (
    select 1
    from unnest(v_member_ids) as x
    where not exists (select 1 from public.msg_users mu where mu.id = x and mu.is_active = true)
  ) then
    raise exception 'One or more selected members are invalid or inactive.';
  end if;

  v_title := nullif(btrim(coalesce(p_title, '')), '');

  insert into public.msg_threads (thread_type, title, created_by_user_id, is_active)
  values ('group', case when v_title is null then null else left(v_title, 120) end, p_created_by_user_id, true)
  returning * into v_thread;

  insert into public.msg_thread_participants (thread_id, user_id)
  values (v_thread.id, p_created_by_user_id);

  foreach v_member_id in array v_member_ids
  loop
    insert into public.msg_thread_participants (thread_id, user_id)
    values (v_thread.id, v_member_id)
    on conflict (thread_id, user_id) do nothing;
  end loop;

  return v_thread;
end;
$function$

CREATE OR REPLACE FUNCTION public.msg_create_group_thread_v2(p_created_by_user_id uuid, p_title text, p_member_user_ids uuid[], p_client_thread_id text)
 RETURNS msg_threads
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_thread public.msg_threads%rowtype;
  v_member_ids uuid[];
  v_title text;
  v_client_thread_id text;
  v_original jsonb;
  v_ledger custodial_release_identity.group_original_creations%rowtype;
begin
  if p_created_by_user_id is null then
    raise exception using errcode='22023',message='Authenticated group creator is required';
  end if;
  if not public.msg_is_runtime_user(p_created_by_user_id) then
    raise exception using errcode='42501',message='Group creator is not an active Messenger user';
  end if;
  -- The existing HTTP facade supplies a one-dimensional UUID vector. Do not
  -- flatten multidimensional arrays into an invented original request.
  if p_member_user_ids is not null and cardinality(p_member_user_ids)>0
    and (array_ndims(p_member_user_ids) is distinct from 1
      or array_lower(p_member_user_ids,1) is distinct from 1) then
    raise exception using errcode='22023',message='Original group recipients must use the received one-dimensional vector';
  end if;
  v_member_ids := array(
    select distinct member_id
    from unnest(coalesce(p_member_user_ids,array[]::uuid[])) as selected(member_id)
    where member_id is not null and member_id <> p_created_by_user_id
    order by member_id
  );
  if coalesce(array_length(v_member_ids,1),0)<2 then
    raise exception using errcode='22023',message='A group requires at least two recipients';
  end if;
  if coalesce(array_length(v_member_ids,1),0)>100 then
    raise exception using errcode='22023',message='A group may contain at most 100 recipients';
  end if;
  if exists(select 1 from unnest(v_member_ids) as selected(member_id)
    where not public.msg_is_runtime_user(selected.member_id)) then
    raise exception using errcode='22023',message='One or more recipients are invalid or inactive';
  end if;
  v_title := nullif(left(btrim(coalesce(p_title,'')),120),'');
  v_client_thread_id := nullif(btrim(coalesce(p_client_thread_id,'')),'');
  if v_client_thread_id is null or length(v_client_thread_id) not between 8 and 200 then
    raise exception using errcode='22023',message='A stable client thread operation id is required';
  end if;
  v_original := jsonb_build_object(
    'schema','custodial.group-original-creation.v1',
    'created_by_user_id',p_created_by_user_id,
    'client_thread_id',p_client_thread_id,
    'title',p_title,
    'member_user_ids',to_jsonb(p_member_user_ids)
  );
  -- Serialize this existing canonical creator/key (including first use) until
  -- transaction completion; hash collisions only serialize unrelated work.
  -- Raw received key spelling remains in the closed original tuple.
  perform pg_advisory_xact_lock(hashtextextended('custodial.group-original-creation.v1:'
    ||p_created_by_user_id::text||':'||v_client_thread_id,0));
  select * into v_ledger from custodial_release_identity.group_original_creations
    where creator_uuid=p_created_by_user_id and original_client_thread_id=v_client_thread_id;
  if found then
    if v_ledger.original_tuple is distinct from v_original then
      raise exception using errcode='22023',message='Group operation already belongs to a different original creation tuple';
    end if;
    select * into v_thread from public.msg_threads where id=v_ledger.group_uuid for update;
    if v_thread.id is null then
      raise exception using errcode='55000',message='Original group was retired; its original operation remains held and cannot create a replacement';
    end if;
    if v_thread.thread_type is distinct from 'group'
      or v_thread.created_by_user_id is distinct from p_created_by_user_id
      or v_thread.client_thread_id is distinct from v_client_thread_id
      or v_thread.original_group_creation is distinct from v_ledger.original_tuple then
      raise exception using errcode='55000',message='Original group ledger and current row binding disagree';
    end if;
    return v_thread;
  end if;
  -- A surviving row without an original ledger is legacy/unbound, even if
  -- someone presents matching current members or an unqualified column.
  if exists(select 1 from public.msg_threads
      where created_by_user_id=p_created_by_user_id and client_thread_id=v_client_thread_id) then
    raise exception using errcode='55000',message='Legacy group original creation is unbound and remains held';
  end if;
  insert into public.msg_threads(
    thread_type,title,created_by_user_id,client_thread_id,is_active,original_group_creation
  ) values('group',v_title,p_created_by_user_id,v_client_thread_id,true,v_original)
  on conflict(created_by_user_id,client_thread_id) where client_thread_id is not null
  do nothing returning * into v_thread;
  if v_thread.id is null then
    select * into v_thread from public.msg_threads
    where created_by_user_id=p_created_by_user_id and client_thread_id=v_client_thread_id
    limit 1 for update;
    if v_thread.id is null then
      raise exception using errcode='40001',message='Concurrent group creation could not be reconciled';
    end if;
    -- No adoption: all legitimate same-key RPC creators hold the same lock
    -- and store a ledger in their transaction. An outside legacy insertion
    -- must not gain provenance through this conflict branch.
    raise exception using errcode='55000',message='Concurrent group row lacks original ledger and remains held';
  end if;
  insert into custodial_release_identity.group_original_creations(
    creator_uuid,original_client_thread_id,group_uuid,original_tuple
  ) values(p_created_by_user_id,v_client_thread_id,v_thread.id,v_original);
  insert into public.msg_thread_participants(thread_id,user_id)
  values(v_thread.id,p_created_by_user_id)
  on conflict(thread_id,user_id) do update set left_at=null;
  insert into public.msg_thread_participants(thread_id,user_id)
  select v_thread.id,member_id from unnest(v_member_ids) as selected(member_id)
  on conflict(thread_id,user_id) do update set left_at=null;
  return v_thread;
end
$function$

CREATE OR REPLACE FUNCTION public.msg_delete_thread(p_thread_id uuid, p_request_user_id uuid, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_thread public.msg_threads%rowtype;
  v_existing public.msg_thread_deletion_operations%rowtype;
  v_request_role text;
  v_now timestamptz:=clock_timestamp();
  v_deleted_through timestamptz;
  v_is_memphis boolean:=false;
begin
  if p_thread_id is null or p_request_user_id is null or p_operation_id is null then
    raise exception using errcode='22023',message='Thread, authenticated user, and deletion operation are required';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_operation_id::text,0));
  select * into v_existing from public.msg_thread_deletion_operations where operation_id=p_operation_id;
  if v_existing.operation_id is not null then
    if v_existing.thread_id<>p_thread_id or v_existing.user_id<>p_request_user_id or v_existing.deletion_scope<>'user' then
      raise exception using errcode='23505',message='Deletion operation id was already used for another target';
    end if;
    return jsonb_build_object('ok',true,'thread_id',v_existing.thread_id,'deleted',true,'deletion_scope','user','deleted_at',v_existing.deleted_at,'deleted_through',v_existing.deleted_through,'operation_id',v_existing.operation_id,'replayed',true);
  end if;
  perform public.msg_assert_active_mutable_thread(p_thread_id);
  select role into v_request_role from public.msg_users where id=p_request_user_id and is_active is true;
  if v_request_role is null or not public.msg_is_runtime_user(p_request_user_id) then
    raise exception using errcode='42501',message='Authenticated messaging user was not found';
  end if;
  select * into v_thread from public.msg_threads where id=p_thread_id for update;
  if v_request_role not in ('manager','admin') and not exists (
    select 1 from public.msg_thread_participants p where p.thread_id=p_thread_id and p.user_id=p_request_user_id and p.left_at is null
  ) then raise exception using errcode='42501',message='Only a participant or Ops Manager can remove this conversation'; end if;
  v_deleted_through:=greatest(v_now,coalesce((select max(coalesce(m.sent_at,m.created_at)) from public.msg_messages m where m.thread_id=p_thread_id),v_now));
  delete from public.msg_thread_visibility where thread_id=p_thread_id and user_id=p_request_user_id and device_identifier is null;
  insert into public.msg_thread_visibility(thread_id,user_id,device_identifier,hidden_before,created_at,updated_at)
  values(p_thread_id,p_request_user_id,null,v_deleted_through,v_now,v_now);
  select exists(select 1 from public.msg_thread_participants p join public.msg_users u on u.id=p.user_id where p.thread_id=p_thread_id and p.left_at is null and u.role='bot' and lower(btrim(u.display_name))='memphis') into v_is_memphis;
  if v_is_memphis then update public.msg_thread_participants set left_at=coalesce(left_at,v_now) where thread_id=p_thread_id and user_id=p_request_user_id and left_at is null; end if;
  insert into public.msg_thread_deletion_operations(operation_id,thread_id,user_id,deletion_scope,deleted_through,deleted_at,thread_type,metadata_json)
  values(p_operation_id,p_thread_id,p_request_user_id,'user',v_deleted_through,v_now,v_thread.thread_type,jsonb_build_object('memphis_generation_ended',v_is_memphis));
  update public.msg_threads set updated_at=v_now where id=p_thread_id;
  return jsonb_build_object('ok',true,'thread_id',p_thread_id,'deleted',true,'deletion_scope','user','deleted_at',v_now,'deleted_through',v_deleted_through,'operation_id',p_operation_id,'memphis_generation_ended',v_is_memphis,'replayed',false);
end
$function$

CREATE OR REPLACE FUNCTION public.msg_effective_message_metadata(p_metadata_json jsonb, p_client_message_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_metadata jsonb := coalesce(p_metadata_json,'{}'::jsonb);
  v_metadata_client_message_id text := nullif(btrim(coalesce(p_metadata_json->>'client_message_id','')),'');
  v_client_message_id text := nullif(btrim(coalesce(p_client_message_id,'')),'');
  v_source text := lower(btrim(coalesce(p_metadata_json->>'source','')));
  v_event_id text := nullif(btrim(coalesce(p_metadata_json->>'event_id','')),'');
  v_dedupe_key text := nullif(btrim(coalesce(
    p_metadata_json->>'notification_instance_key',
    p_metadata_json->>'instance_key',
    p_metadata_json->>'notification_key',
    p_metadata_json->>'alert_key',
    p_metadata_json->>'reminder_key',
    ''
  )), '');
begin
  if jsonb_typeof(v_metadata) <> 'object' then
    raise exception using errcode='22023',message='Message metadata must be a JSON object.';
  end if;
  if v_client_message_id is null then
    v_client_message_id:=v_metadata_client_message_id;
  elsif v_metadata_client_message_id is not null and v_metadata_client_message_id<>v_client_message_id then
    raise exception using errcode='22023',message='client_message_id must match metadata_json.client_message_id.';
  end if;
  if v_client_message_id is not null and length(v_client_message_id)>200 then
    raise exception using errcode='22023',message='client_message_id cannot exceed 200 characters.';
  end if;

  v_metadata := v_metadata - 'client_message_id';
  if v_client_message_id is not null then
    v_metadata := v_metadata || jsonb_build_object('client_message_id',v_client_message_id);
  end if;
  if v_dedupe_key is null and v_source='events_app' and v_event_id is not null then
    v_dedupe_key:='event:'||v_event_id;
  end if;
  if v_dedupe_key is not null then
    if length(v_dedupe_key)>500 then
      raise exception using errcode='22023',message='notification instance key cannot exceed 500 characters.';
    end if;
    v_metadata := (v_metadata
      - 'notification_instance_key'
      - 'instance_key'
      - 'notification_key'
      - 'alert_key'
      - 'reminder_key')
      || jsonb_build_object('notification_instance_key',v_dedupe_key);
  end if;
  return v_metadata;
end
$function$

CREATE OR REPLACE FUNCTION public.msg_ensure_ops_manager_user(p_manager_id uuid)
 RETURNS msg_users
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_manager public.ops_manager_managers%rowtype;
  v_user public.msg_users%rowtype;
  v_link public.msg_ops_manager_legacy_identity_links%rowtype;
  v_display_name text;
  v_identity_key text;
begin
  if p_manager_id is null then raise exception using errcode='22023',message='Authenticated leadership manager id is required'; end if;
  perform pg_advisory_xact_lock(hashtextextended('named-manager-messenger:'||p_manager_id::text,0));
  select * into v_manager from public.ops_manager_managers
  where manager_id=p_manager_id and active=true and revoked_at is null and is_system_principal=false for update;
  if v_manager.manager_id is null then raise exception using errcode='42501',message='Active named leadership identity was not found'; end if;
  v_identity_key:='ops_manager_named_'||replace(p_manager_id::text,'-','');

  select * into v_user from public.msg_users where ops_manager_id=p_manager_id order by created_at,id limit 1 for update;
  if v_user.id is null then
    select * into v_link from public.msg_ops_manager_legacy_identity_links where manager_id=p_manager_id for update;
    if v_link.manager_id is not null then
      select * into v_user from public.msg_users where id=v_link.msg_user_id for update;
      if v_user.id is null or (v_user.ops_manager_id is not null and v_user.ops_manager_id<>p_manager_id) then
        raise exception using errcode='23514',message='Verified legacy Messenger identity link is invalid';
      end if;
    end if;
  end if;

  v_display_name:=btrim(v_manager.display_name);
  perform pg_advisory_xact_lock(hashtextextended('named-manager-messenger-display-name:v1:'||lower(v_display_name),0));
  if exists(select 1 from public.msg_users u where lower(btrim(u.display_name))=lower(v_display_name) and (v_user.id is null or u.id<>v_user.id)) then
    v_display_name:=left(v_display_name,112)||' · Leadership '||replace(p_manager_id::text,'-','');
  end if;
  if v_user.id is null then
    insert into public.msg_users(display_name,role,is_active,ops_manager_id,messaging_identity_key)
    values(v_display_name,'manager',true,p_manager_id,v_identity_key)
    returning * into v_user;
  else
    update public.msg_users
    set ops_manager_id=p_manager_id,display_name=v_display_name,role='manager',is_active=true,messaging_identity_key=v_identity_key,updated_at=now()
    where id=v_user.id
    returning * into v_user;
  end if;
  return v_user;
end
$function$

CREATE OR REPLACE FUNCTION public.msg_get_or_create_direct_thread(p_user_a uuid, p_user_b uuid)
 RETURNS msg_threads
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_thread public.msg_threads%rowtype;
  v_pair public.msg_canonical_thread_pairs%rowtype;
  v_candidate_ids uuid[];
  v_candidate_count integer:=0;
  v_low uuid;
  v_high uuid;
begin
  if p_user_a is null or p_user_b is null then raise exception 'Both users are required.'; end if;
  if p_user_a=p_user_b then raise exception 'Direct thread requires two different users.'; end if;
  if not exists(select 1 from public.msg_users where id=p_user_a and is_active is true) then raise exception 'User A not found or inactive.'; end if;
  if not exists(select 1 from public.msg_users where id=p_user_b and is_active is true) then raise exception 'User B not found or inactive.'; end if;
  v_low:=least(p_user_a,p_user_b); v_high:=greatest(p_user_a,p_user_b);
  perform pg_advisory_xact_lock(hashtextextended('msg-canonical-conversation-pair:v1:'||v_low::text||':'||v_high::text,0));
  select * into v_pair from public.msg_canonical_thread_pairs where principal_low_id=v_low and principal_high_id=v_high for update;
  with candidates as materialized (
    select t.id from public.msg_threads t
    join public.msg_thread_participants p1 on p1.thread_id=t.id and p1.user_id=p_user_a and p1.left_at is null
    join public.msg_thread_participants p2 on p2.thread_id=t.id and p2.user_id=p_user_b and p2.left_at is null
    where t.thread_type='direct' and t.is_active is true
      and 2=(select count(*) from public.msg_thread_participants px where px.thread_id=t.id and px.left_at is null)
    order by t.created_at,t.id for update of t
  ) select coalesce(array_agg(id order by id),'{}'::uuid[]),count(*) into v_candidate_ids,v_candidate_count from candidates;
  if v_candidate_count>1 then raise exception using errcode='23505',message='Ambiguous active Messenger canonical pair has more than one direct candidate'; end if;
  if v_candidate_count=1 then
    select * into v_thread from public.msg_threads where id=v_candidate_ids[1] for update;
  elsif v_pair.thread_id is not null then
    delete from public.msg_canonical_thread_pairs where principal_low_id=v_low and principal_high_id=v_high;
  end if;
  if v_thread.id is null then
    insert into public.msg_threads(thread_type,title,created_by_user_id,is_active) values('direct',null,p_user_a,true) returning * into v_thread;
    insert into public.msg_thread_participants(thread_id,user_id) values(v_thread.id,p_user_a),(v_thread.id,p_user_b);
  end if;
  insert into public.msg_canonical_thread_pairs(principal_low_id,principal_high_id,thread_id,conversation_type)
  values(v_low,v_high,v_thread.id,'direct')
  on conflict(principal_low_id,principal_high_id) do update set thread_id=excluded.thread_id,conversation_type=excluded.conversation_type
  where public.msg_canonical_thread_pairs.thread_id is distinct from excluded.thread_id or public.msg_canonical_thread_pairs.conversation_type is distinct from excluded.conversation_type;
  return v_thread;
end
$function$

CREATE OR REPLACE FUNCTION public.msg_get_or_create_memphis_thread(p_user_id uuid)
 RETURNS msg_threads
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_memphis_user_id uuid;
  v_thread public.msg_threads%rowtype;
  v_pair public.msg_canonical_thread_pairs%rowtype;
  v_candidate_ids uuid[];
  v_candidate_count integer:=0;
  v_low uuid;
  v_high uuid;
begin
  if p_user_id is null then raise exception 'user_id is required.'; end if;
  if not public.msg_is_runtime_user(p_user_id) then raise exception 'User is not an active custodial Messenger identity.'; end if;
  select mu.id into v_memphis_user_id from public.msg_users mu
  where mu.is_active is true and mu.role='bot' and lower(btrim(mu.display_name))='memphis'
  order by mu.created_at,mu.id limit 1;
  if v_memphis_user_id is null then raise exception 'Memphis bot user not found.'; end if;
  if p_user_id=v_memphis_user_id then raise exception 'Memphis cannot create a conversation with itself.'; end if;
  v_low:=least(p_user_id,v_memphis_user_id); v_high:=greatest(p_user_id,v_memphis_user_id);
  perform pg_advisory_xact_lock(hashtextextended('msg-canonical-conversation-pair:v1:'||v_low::text||':'||v_high::text,0));
  select * into v_pair from public.msg_canonical_thread_pairs where principal_low_id=v_low and principal_high_id=v_high for update;
  with candidates as materialized (
    select t.id from public.msg_threads t
    join public.msg_thread_participants p1 on p1.thread_id=t.id and p1.user_id=p_user_id and p1.left_at is null
    join public.msg_thread_participants p2 on p2.thread_id=t.id and p2.user_id=v_memphis_user_id and p2.left_at is null
    where t.thread_type in ('direct','bot') and t.is_active is true
      and 2=(select count(*) from public.msg_thread_participants px where px.thread_id=t.id and px.left_at is null)
    order by case when t.thread_type='bot' then 0 else 1 end,t.created_at,t.id for update of t
  ) select coalesce(array_agg(id order by id),'{}'::uuid[]),count(*) into v_candidate_ids,v_candidate_count from candidates;
  if v_candidate_count>1 then raise exception using errcode='23505',message='Ambiguous active Messenger canonical pair has more than one Memphis candidate'; end if;
  if v_candidate_count=1 then
    select * into v_thread from public.msg_threads where id=v_candidate_ids[1] for update;
  elsif v_pair.thread_id is not null then
    delete from public.msg_canonical_thread_pairs where principal_low_id=v_low and principal_high_id=v_high;
  end if;
  if v_thread.id is null then
    insert into public.msg_threads(thread_type,title,created_by_user_id,is_active) values('bot','Memphis',p_user_id,true) returning * into v_thread;
    insert into public.msg_thread_participants(thread_id,user_id) values(v_thread.id,p_user_id),(v_thread.id,v_memphis_user_id);
  elsif v_thread.thread_type is distinct from 'bot' or v_thread.title is distinct from 'Memphis' then
    update public.msg_threads set thread_type='bot',title='Memphis',updated_at=now() where id=v_thread.id returning * into v_thread;
  end if;
  insert into public.msg_canonical_thread_pairs(principal_low_id,principal_high_id,thread_id,conversation_type)
  values(v_low,v_high,v_thread.id,'bot')
  on conflict(principal_low_id,principal_high_id) do update set thread_id=excluded.thread_id,conversation_type=excluded.conversation_type
  where public.msg_canonical_thread_pairs.thread_id is distinct from excluded.thread_id or public.msg_canonical_thread_pairs.conversation_type is distinct from excluded.conversation_type;
  return v_thread;
end
$function$

