CREATE OR REPLACE FUNCTION public.static_weekly_approved_recurring_materialize_projection(p_publication_id uuid, p_service_date date, p_exception_set_digest text, p_compiler_version text, p_objective jsonb, p_metrics jsonb, p_replay_digest text, p_assignments jsonb, p_expected_revision bigint, p_actor_manager_id uuid, p_actor_manager_name text, p_idempotency_key text)
 RETURNS jsonb
