  if v_assignment.assignment_id is null and (v_work->>'overlayWork') is distinct from 'true' then raise exception using errcode='23514',message='active baseline work must retain its stored baseline assignment link'; end if;
    perform public.static_weekly_capacity_assert_projection_owner(p_assignments,p_publication_id,v_item);
    if upper(v_item->>'status')='ASSIGNED' and v_item->>'owner_kind'='CONTRACTOR_CAPACITY' then
      v_owner:=null;
    elsif upper(v_item->>'status')='ASSIGNED' then select * into v_owner from public.v_weekly_roster_slot_incumbency_ranges where slot_id=(v_item->>'owner_slot_id')::uuid and effective_start<=(v_item->>'service_date')::date and (effective_end is null or (v_item->>'service_date')::date<effective_end); if not found or v_owner.person_id::text is distinct from v_item->>'owner_person_id' then raise exception using errcode='23514',message='projection assigned owner lacks an effective dated incumbent'; end if; elsif upper(v_item->>'status') not in ('OPEN','REVIEW') or v_item->>'owner_slot_id' is not null or v_item->>'owner_person_id' is not null then raise exception using errcode='23514',message='open and review projection rows must have null owner facts'; end if;
    insert into public.weekly_schedule_occurrences(projection_id,publication_id,version_id,assignment_id,service_date,work_id,day_of_week,location_id,location_code_snapshot,location_name_snapshot,coverage_start,coverage_end,owner_slot_id,owner_slot_label_snapshot,owner_person_id_snapshot,owner_name_snapshot,owner_kind,owner_capacity_id,state,state_reason,original_actor_person_id,original_actor_name_snapshot,authority_facts_json,occurrence_digest) values(v_projection,p_publication_id,v_publication.version_id,v_assignment.assignment_id,(v_item->>'service_date')::date,v_item->>'work_id',(v_item->>'day_of_week')::smallint,nullif(v_work->>'locationId','')::uuid,coalesce(v_work->>'locationCodeSnapshot',v_item->>'work_id'),coalesce(v_work->>'locationNameSnapshot',v_item->>'work_id'),(v_work#>>'{window,start}')::time,(v_work#>>'{window,end}')::time,case when lower(v_item->>'status')='assigned' then (v_item->>'owner_slot_id')::uuid else null end,case when lower(v_item->>'status')='assigned' then (select slot_label from public.weekly_roster_slots where slot_id=(v_item->>'owner_slot_id')::uuid) else null end,case when lower(v_item->>'status')='assigned' then (v_item->>'owner_person_id')::uuid else null end,case when lower(v_item->>'status')='assigned' then v_owner.person_name_snapshot else null end,nullif(v_item->>'owner_kind',''),nullif(v_item->>'capacity_id','')::uuid,case lower(v_item->>'status') when 'assigned' then 'created' when 'open' then 'open' else 'review' end,v_item->>'reason_code',nullif(v_item->>'original_actor_person_id','')::uuid,nullif(v_item->>'original_actor_name',''),jsonb_build_object('baseline_owner_slot_id',v_item->>'baseline_owner_slot_id','baseline_owner_person_id',v_item->>'baseline_owner_person_id','baseline_owner_name',v_item->>'baseline_owner_name','original_actor_person_id',v_item->>'original_actor_person_id','original_actor_name',v_item->>'original_actor_name','optimized_owner_slot_id',v_item->>'optimized_owner_slot_id','optimized_owner_person_id',v_item->>'optimized_owner_person_id','actual_actor_person_id',v_item->>'actual_actor_person_id','work_snapshot',v_work)||case when v_item->>'owner_kind'='CONTRACTOR_CAPACITY' then jsonb_build_object('owner_kind','CONTRACTOR_CAPACITY','capacity_id',v_item->>'capacity_id') else '{}'::jsonb end,public.static_weekly_digest_jsonb(v_item)) returning occurrence_id into v_occurrence;
    insert into public.weekly_schedule_projection_assignments(projection_id,occurrence_id,work_id,status,reason_code,owner_slot_id,owner_slot_label_snapshot,owner_person_id_snapshot,owner_name_snapshot,owner_kind,owner_capacity_id,authority_facts_json,explanation_json,content_digest) values(v_projection,v_occurrence,v_item->>'work_id',lower(v_item->>'status'),v_item->>'reason_code',case when lower(v_item->>'status')='assigned' then (v_item->>'owner_slot_id')::uuid else null end,case when lower(v_item->>'status')='assigned' then (select slot_label from public.weekly_roster_slots where slot_id=(v_item->>'owner_slot_id')::uuid) else null end,case when lower(v_item->>'status')='assigned' then (v_item->>'owner_person_id')::uuid else null end,case when lower(v_item->>'status')='assigned' then v_owner.person_name_snapshot else null end,nullif(v_item->>'owner_kind',''),nullif(v_item->>'capacity_id','')::uuid,(select authority_facts_json from public.weekly_schedule_occurrences where occurrence_id=v_occurrence),coalesce(v_item->'explanation','{}'::jsonb),public.static_weekly_digest_jsonb(v_item));
  end loop;
  v_response:=public.static_weekly_response_json('materialize_projection',v_revision,v_content_digest,v_request_digest,jsonb_build_object('projection_id',v_projection,'publication_id',p_publication_id,'week_start',p_service_date,'week_end',p_service_date+6,'replay_digest',p_replay_digest)); insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest) values(v_command,p_actor_manager_id,p_actor_manager_name,'materialize_projection',p_idempotency_key,p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest); return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_approved_recurring_publish_draft(p_draft_version_id uuid, p_expected_draft_revision bigint, p_expected_revision bigint, p_actor_manager_id uuid, p_actor_manager_name text, p_idempotency_key text, p_publication_kind text DEFAULT 'publish'::text, p_rollback_of_version_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_request jsonb; v_request_digest text; v_prior public.weekly_schedule_command_receipts%rowtype; v_draft public.weekly_schedule_versions%rowtype; v_target public.weekly_schedule_versions%rowtype; v_command uuid:=gen_random_uuid(); v_publication uuid; v_revision bigint; v_version_number bigint; v_previous uuid; v_response jsonb; v_operation text;
begin
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_actor_manager_id,p_actor_manager_name,p_idempotency_key,'publish_draft');
  v_request:=jsonb_build_object('operation','publish_draft','draft_version_id',p_draft_version_id,'expected_draft_revision',p_expected_draft_revision,'expected_revision',p_expected_revision,'actor_manager_id',p_actor_manager_id,'actor_manager_name',p_actor_manager_name,'publication_kind',p_publication_kind,'rollback_of_version_id',p_rollback_of_version_id); v_request_digest:=public.static_weekly_digest_jsonb(v_request); perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts where actor_manager_id=p_actor_manager_id and idempotency_key=p_idempotency_key; if found then if v_prior.request_digest<>v_request_digest then raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs'; end if; return v_prior.response_json; end if;
  if p_draft_version_id is null or p_expected_draft_revision is null or p_expected_draft_revision<1 or p_publication_kind is null or p_publication_kind not in ('publish','supersede','rollback_compensation') then raise exception using errcode='23514',message='invalid publication kind'; end if;
  select * into v_draft from public.weekly_schedule_versions where version_id=p_draft_version_id and lifecycle_state='draft' and revision=p_expected_draft_revision for update; if not found then raise exception using errcode='40001',message='stale draft revision'; end if;
  perform public.static_weekly_assert_approved_recurring_document(v_draft.draft_document,v_draft.effective_start,true);
  if not exists(select 1 from public.weekly_schedule_slot_availability a where a.version_id=v_draft.version_id) or not exists(select 1 from public.weekly_schedule_slot_assignments a where a.version_id=v_draft.version_id) then raise exception using errcode='23514',message='document relational projection is incomplete'; end if;
  select version_id into v_previous from public.weekly_schedule_versions where lifecycle_state='published' order by effective_start desc,version_number desc limit 1;
  -- A future Monday can have a newer accepted winner even when another
  -- later Monday is already scheduled. The private guard below authorizes
  -- only parent-bound same-Monday replacement, never a legacy rollback.
  if exists(select 1 from public.weekly_schedule_publications where effective_start=v_draft.effective_start) then
    select version_id into v_previous from public.weekly_schedule_publications
      where effective_start=v_draft.effective_start order by authority_revision desc limit 1;
  end if;
  if v_previous is null then
    if p_publication_kind<>'publish' or p_rollback_of_version_id is not null then raise exception using errcode='23514',message='the first weekly authority publication must be labeled publish'; end if;
  else
    if v_draft.effective_start <= (select effective_start from public.weekly_schedule_versions where version_id=v_previous) then perform public.static_weekly_v16_assert_future_same_monday(v_draft.version_id,v_previous,p_actor_manager_id,p_idempotency_key,p_publication_kind,p_rollback_of_version_id); end if;
    if p_publication_kind='publish' then raise exception using errcode='23514',message='a later ordinary authority replacement must be labeled supersede'; end if;
    if p_publication_kind='supersede' and p_rollback_of_version_id is not null then raise exception using errcode='23514',message='supersede may not claim a rollback target'; end if;
  end if;
  if p_publication_kind='rollback_compensation' then
    select * into v_target from public.weekly_schedule_versions where version_id=p_rollback_of_version_id and lifecycle_state='published';
    if not found or p_rollback_of_version_id is null or public.static_weekly_rollback_semantic_snapshot(v_draft.draft_document) is distinct from public.static_weekly_rollback_semantic_snapshot(v_target.draft_document) then raise exception using errcode='23514',message='rollback compensation must restore the target recurring semantics with new version and effective-date identities'; end if;
  elsif p_rollback_of_version_id is not null then raise exception using errcode='23514',message='only rollback compensation accepts a rollback target'; end if;
  v_operation:=case p_publication_kind when 'rollback_compensation' then 'rollback' when 'supersede' then 'supersede' else 'publish' end; v_revision:=public.static_weekly_advance_authority(p_expected_revision,v_operation,p_actor_manager_id,p_actor_manager_name,v_command,v_draft.content_digest); select coalesce(max(version_number),0)+1 into v_version_number from public.weekly_schedule_versions where lifecycle_state='published';
  v_publication:=gen_random_uuid();
  perform set_config('app.static_weekly_publish_write','on',true); update public.weekly_schedule_versions set version_number=v_version_number,lifecycle_state='published',publication_kind=p_publication_kind,rollback_of_version_id=p_rollback_of_version_id,published_by_manager_id=p_actor_manager_id,published_by_manager_name_snapshot=p_actor_manager_name,published_at=statement_timestamp() where version_id=v_draft.version_id;
  v_response:=public.static_weekly_response_json(v_operation,v_revision,v_draft.content_digest,v_request_digest,jsonb_build_object('version_id',v_draft.version_id,'version_number',v_version_number,'publication_id',v_publication,'effective_start',v_draft.effective_start,'replay_digest',v_draft.draft_document#>>'{validation,replay_digest}','rollback_of_version_id',p_rollback_of_version_id));
  insert into public.weekly_schedule_publications(publication_id,version_id,authority_revision,publication_kind,effective_start,prior_version_id,expected_revision,idempotency_key,actor_manager_id,actor_manager_name_snapshot,request_digest,replay_digest,content_digest,output_digest) values(v_publication,v_draft.version_id,v_revision,p_publication_kind,v_draft.effective_start,v_previous,p_expected_revision,p_idempotency_key,p_actor_manager_id,p_actor_manager_name,v_request_digest,v_draft.draft_document#>>'{validation,replay_digest}',v_draft.content_digest,v_response->>'output_digest');
  if v_previous is not null and v_draft.effective_start > (select effective_start from public.weekly_schedule_versions where version_id=v_previous) then insert into public.weekly_schedule_effective_range_closures(closed_version_id,closed_at_effective_date,superseding_version_id,publication_id,created_by_manager_id,created_by_manager_name_snapshot,content_digest) values(v_previous,v_draft.effective_start,v_draft.version_id,v_publication,p_actor_manager_id,p_actor_manager_name,v_draft.content_digest); end if;
  insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest) values(v_command,p_actor_manager_id,p_actor_manager_name,v_operation,p_idempotency_key,p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_draft.content_digest); return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_assert_approved_dated_lunch(p_projection uuid, p_document jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE projection public.weekly_schedule_compiled_projections%rowtype;source jsonb;loan jsonb;areas jsonb;effective_work jsonb;
 area jsonb;helper jsonb;target text;edge record;evidence jsonb;cost integer;costs jsonb;eligible text[];pair text[];
 best jsonb;states jsonb;next_states jsonb;state jsonb;candidate jsonb;old jsonb;mask integer;new_mask integer;i integer;j integer;k integer;
 required integer;helper_id text;selected text;expected_id text;area_text text;owners jsonb;responsibility jsonb;intent jsonb;
 expected_responsibilities jsonb:='[]';expected_notifications jsonb:='[]';pair_sets jsonb;pair_item jsonb;pair_count integer;
BEGIN
 PERFORM public.static_weekly_v8_assert_lunch_document(p_projection,p_document);
 SELECT * INTO STRICT projection FROM public.weekly_schedule_compiled_projections WHERE projection_id=p_projection;
 source:=projection.projection_envelope#>'{authority,overlayCompilerInput}';
 effective_work:=public.static_weekly_approved_dated_effective_work(projection.publication_id,projection.week_start,source);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(projection.projection_envelope->'assignments') a
  WHERE a->>'plan_work_id'!~'^[ -~]+$')
 THEN RAISE EXCEPTION USING ERRCODE='0A000',MESSAGE='Unqualified dated lunch work identity collation';END IF;
 FOR loan IN SELECT value FROM jsonb_array_elements(p_document->'loans') LOOP
  -- The exact six primitive fields used by the existing lunch producer.
  expected_id:=public.static_weekly_digest_text('{"end":'||to_jsonb(loan->>'coverage_end')::text||
   ',"input":'||to_jsonb(projection.projection_envelope#>>'{authority,inputDigest}')::text||
   ',"ownerSlotId":'||to_jsonb(loan->>'normal_owner_slot_id')::text||
   ',"policy":"owner-20260921-two-nearby-full-hour-v1","serviceDate":'||to_jsonb(loan->>'service_date')::text||
   ',"start":'||to_jsonb(loan->>'coverage_start')::text||'}');
  IF loan->>'loan_id' IS DISTINCT FROM expected_id THEN RAISE EXCEPTION 'Dated original lunch loan identity differs';END IF;
  WITH RECURSIVE base AS(
   SELECT a,extract(epoch FROM greatest((a#>>'{work_snapshot,window,start}')::time,(loan->>'coverage_start')::time))::integer/60 s,
    extract(epoch FROM least((a#>>'{work_snapshot,window,end}')::time,(loan->>'coverage_end')::time))::integer/60 e
   FROM jsonb_array_elements(projection.projection_envelope->'assignments') a
   JOIN jsonb_array_elements(effective_work) w ON w->>'workId'=a->>'work_id' AND w->'dayOfWeek'=a->'day_of_week'
   WHERE a->>'service_date'=loan->>'service_date' AND a->'owner_slot_id'=loan->'normal_owner_slot_id'
    AND a->>'status'='assigned' AND w->>'schedulingMode'='flexible_coverage_ownership' AND w->>'serviceMode'<>'reminder_only'
    AND (a#>>'{work_snapshot,window,start}')::time<(loan->>'coverage_end')::time
    AND (loan->>'coverage_start')::time<(a#>>'{work_snapshot,window,end}')::time
  ), reach(root,key) AS(
   SELECT a->>'plan_work_id',a->>'plan_work_id' FROM base
   UNION SELECT reach.root,b.a->>'plan_work_id' FROM reach JOIN base x ON x.a->>'plan_work_id'=reach.key
   JOIN base b ON EXISTS(SELECT 1 FROM jsonb_array_elements(x.a#>'{work_snapshot,includedLocations}') l
    JOIN jsonb_array_elements(b.a#>'{work_snapshot,includedLocations}') r ON l->'locationId'=r->'locationId')
  ), groups AS(SELECT key,min(root COLLATE "C") root FROM reach GROUP BY key), parts AS(
   SELECT root,jsonb_agg(a ORDER BY a->>'plan_work_id' COLLATE "C") rows,
    '['||string_agg('{"end":'||e::text||',"start":'||s::text||',"work":'||to_jsonb(a->>'plan_work_id')::text||'}',',' ORDER BY a->>'plan_work_id' COLLATE "C")||']' preimage,
    jsonb_agg(jsonb_build_object('planWorkId',a->'plan_work_id','workId',a->'work_id','serviceMode',a#>'{work_snapshot,serviceMode}',
     'window',jsonb_build_object('start',to_char(time '00:00'+make_interval(mins=>s),'HH24:MI'),
      'end',to_char(time '00:00'+make_interval(mins=>e),'HH24:MI')),'includedLocations',a#>'{work_snapshot,includedLocations}')
     ORDER BY a->>'plan_work_id' COLLATE "C") segments
   FROM base JOIN groups ON key=a->>'plan_work_id' GROUP BY root
  ) SELECT coalesce(jsonb_agg(jsonb_build_object('areaId',public.static_weekly_digest_text(preimage),'rows',rows,'segments',segments,
    'targets',(SELECT jsonb_agg(loc ORDER BY loc#>>'{}' COLLATE "C") FROM(
      SELECT DISTINCT a#>'{work_snapshot,locationId}' loc FROM jsonb_array_elements(rows) a)t))
    ORDER BY public.static_weekly_digest_text(preimage) COLLATE "C"),'[]') INTO areas FROM parts;
  IF jsonb_array_length(areas)>128 THEN RAISE EXCEPTION 'Dated lunch area bound exceeded';END IF;
  costs:='{}'::jsonb;
  FOR area IN SELECT value FROM jsonb_array_elements(areas) LOOP
   FOR helper IN SELECT value FROM jsonb_array_elements(projection.projection_envelope#>'{authority,projectionAvailability}')
    WHERE value->>'serviceDate'=loan->>'service_date' AND value->>'status'='working'
     AND value->>'incumbentPersonId' IS NOT NULL AND value->'slotId'<>loan->'normal_owner_slot_id'
     AND (value#>>'{shift,start}')::time<=(loan->>'coverage_start')::time AND (value#>>'{shift,end}')::time>=(loan->>'coverage_end')::time
     AND NOT((value#>>'{lunch,start}')::time<(loan->>'coverage_end')::time AND (loan->>'coverage_start')::time<(value#>>'{lunch,end}')::time)
     AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(value->'blockedWindows','[]'::jsonb)) b
      WHERE (b->>'start')::time<(loan->>'coverage_end')::time AND (loan->>'coverage_start')::time<(b->>'end')::time)
    ORDER BY value->>'slotId' COLLATE "C" LOOP
    helper_id:=helper->>'slotId';
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(area->'rows') a
     WHERE NOT(helper->'qualifications' @> a#>'{work_snapshot,requiredQualifications}')
      OR a#>'{work_snapshot,restrictedSlotIds}' ? helper_id
      OR EXISTS(SELECT 1 FROM jsonb_array_elements(a#>'{work_snapshot,includedLocations}') l WHERE helper->'restrictions' ? (l->>'locationId')))
    THEN CONTINUE;END IF;
    evidence:='[]'::jsonb;cost:=0;
    FOR target IN SELECT jsonb_array_elements_text(area->'targets') LOOP
     SELECT from_id,minutes,provenance INTO edge FROM(
      SELECT a#>>'{work_snapshot,locationId}' from_id,0 minutes,'same_normal_assigned_area'::text provenance
      FROM jsonb_array_elements(projection.projection_envelope->'assignments') a
      JOIN jsonb_array_elements(effective_work) w ON w->>'workId'=a->>'work_id' AND w->'dayOfWeek'=a->'day_of_week'
      WHERE a->>'service_date'=loan->>'service_date' AND a->>'owner_slot_id'=helper_id AND a->>'status'='assigned'
       AND w->>'schedulingMode'='flexible_coverage_ownership' AND w->>'serviceMode'<>'reminder_only'
       AND (a#>>'{work_snapshot,window,start}')::time<(loan->>'coverage_end')::time AND (loan->>'coverage_start')::time<(a#>>'{work_snapshot,window,end}')::time
       AND a#>>'{work_snapshot,locationId}'=target
      UNION ALL
      SELECT a#>>'{work_snapshot,locationId}',(e->>'minutes')::integer,e->>'provenance'
      FROM jsonb_array_elements(projection.projection_envelope->'assignments') a
      JOIN jsonb_array_elements(effective_work) w ON w->>'workId'=a->>'work_id' AND w->'dayOfWeek'=a->'day_of_week'
      JOIN jsonb_array_elements(source->'proximity') e ON
       ((e->>'fromLocationId'=a#>>'{work_snapshot,locationId}' AND e->>'toLocationId'=target)
        OR ((e->'bidirectional'='true'::jsonb OR e->'symmetric'='true'::jsonb) AND e->>'toLocationId'=a#>>'{work_snapshot,locationId}' AND e->>'fromLocationId'=target))
      WHERE a->>'service_date'=loan->>'service_date' AND a->>'owner_slot_id'=helper_id AND a->>'status'='assigned'
       AND w->>'schedulingMode'='flexible_coverage_ownership' AND w->>'serviceMode'<>'reminder_only'
       AND (a#>>'{work_snapshot,window,start}')::time<(loan->>'coverage_end')::time AND (loan->>'coverage_start')::time<(a#>>'{work_snapshot,window,end}')::time
       AND e->'verified'='true'::jsonb AND jsonb_typeof(e->'minutes')='number' AND (e->>'minutes')::numeric BETWEEN 1 AND 1440
       AND (e->>'minutes')::numeric=trunc((e->>'minutes')::numeric) AND nullif(e->>'provenance','') IS NOT NULL
     ) options ORDER BY minutes,from_id COLLATE "C",provenance COLLATE "C" LIMIT 1;
     IF NOT FOUND THEN evidence:=NULL;EXIT;END IF;
     cost:=greatest(cost,edge.minutes);evidence:=evidence||jsonb_build_array(jsonb_build_object(
      'fromLocationId',edge.from_id,'toLocationId',target,'minutes',edge.minutes,'provenance',edge.provenance));
    END LOOP;
    IF evidence IS NOT NULL THEN
     IF NOT(costs ? (area->>'areaId')) THEN costs:=costs||jsonb_build_object(area->>'areaId','{}'::jsonb);END IF;
     costs:=jsonb_set(costs,ARRAY[area->>'areaId',helper_id],jsonb_build_object('cost',cost,'evidence',evidence));
    END IF;
   END LOOP;
  END LOOP;
  SELECT array_agg(id ORDER BY id COLLATE "C") INTO eligible FROM(
   SELECT DISTINCT h.key id FROM jsonb_each(costs) a CROSS JOIN LATERAL jsonb_each(a.value) h)t;
  IF jsonb_array_length(areas)=0 THEN
   IF loan->>'status' IS DISTINCT FROM 'NO_AREAS' OR loan->'helper_slot_ids' IS DISTINCT FROM '[]'::jsonb
    OR loan->'total_distance_minutes' IS DISTINCT FROM '0'::jsonb OR loan->'fallback' IS DISTINCT FROM 'null'::jsonb
    OR loan->'reason' IS DISTINCT FROM 'null'::jsonb
   THEN RAISE EXCEPTION 'Dated no-area lunch result differs';END IF;CONTINUE;
  END IF;
  required:=least(2,coalesce(cardinality(eligible),0));
  IF required=0 OR jsonb_array_length(areas)<required THEN RAISE EXCEPTION 'Dated lunch has no complete eligible partition';END IF;
  pair_sets:='[]'::jsonb;
  IF required=1 THEN pair_sets:=jsonb_build_array(to_jsonb(eligible));
  ELSE FOR i IN 1..cardinality(eligible)-1 LOOP FOR j IN i+1..cardinality(eligible) LOOP
   pair_sets:=pair_sets||jsonb_build_array(to_jsonb(ARRAY[eligible[i],eligible[j]]));END LOOP;END LOOP;END IF;
  best:=NULL;
  FOR pair_item IN SELECT value FROM jsonb_array_elements(pair_sets) LOOP
   SELECT array_agg(value ORDER BY n) INTO pair FROM jsonb_array_elements_text(pair_item) WITH ORDINALITY t(value,n);
   states:='{"0":{"cost":0,"owners":[]}}'::jsonb;
   FOR area IN SELECT value FROM jsonb_array_elements(areas) LOOP
    next_states:='{}'::jsonb;
    FOR mask IN 0..(1<<required)-1 LOOP
     state:=states->mask::text;IF state IS NULL THEN CONTINUE;END IF;
     FOR k IN 1..required LOOP
      IF costs#>ARRAY[area->>'areaId',pair[k]] IS NULL THEN CONTINUE;END IF;
      new_mask:=mask | (1<<(k-1));candidate:=jsonb_build_object('cost',(state->>'cost')::integer+
       (costs#>>ARRAY[area->>'areaId',pair[k],'cost'])::integer,'owners',state->'owners'||jsonb_build_array(pair[k]));
      old:=next_states->new_mask::text;
      IF old IS NULL OR (candidate->>'cost')::integer<(old->>'cost')::integer
       OR ((candidate->>'cost')::integer=(old->>'cost')::integer AND (candidate->'owners')::text COLLATE "C"<(old->'owners')::text COLLATE "C")
      THEN next_states:=jsonb_set(next_states,ARRAY[new_mask::text],candidate);END IF;
     END LOOP;
    END LOOP;
    states:=next_states;
   END LOOP;
   candidate:=states->((1<<required)-1)::text;
   IF candidate IS NOT NULL AND (best IS NULL OR (candidate->>'cost')::integer<(best->>'cost')::integer
    OR ((candidate->>'cost')::integer=(best->>'cost')::integer AND (candidate->'owners')::text COLLATE "C"<(best->'owners')::text COLLATE "C"))
   THEN best:=candidate||jsonb_build_object('pair',pair_item);END IF;
  END LOOP;
  IF best IS NULL OR loan->>'status' IS DISTINCT FROM 'PLANNED' OR loan->'helper_slot_ids' IS DISTINCT FROM best->'pair'
   OR loan->'total_distance_minutes' IS DISTINCT FROM best->'cost'
   OR loan->'reason' IS DISTINCT FROM 'null'::jsonb
   OR loan->'fallback' IS DISTINCT FROM (CASE WHEN required=1 THEN '"only_one_eligible_custodian"'::jsonb ELSE 'null'::jsonb END)
  THEN RAISE EXCEPTION 'Dated deterministic original lunch helper partition differs';END IF;
  i:=0;
  FOR area IN SELECT value FROM jsonb_array_elements(areas) LOOP
   selected:=best#>>ARRAY['owners',i::text];i:=i+1;
   expected_id:=public.static_weekly_digest_text('{"areaId":'||to_jsonb(area->>'areaId')::text||',"covererSlotId":'||to_jsonb(selected)::text||',"loanId":'||to_jsonb(loan->>'loan_id')::text||'}');
   SELECT value INTO STRICT responsibility FROM jsonb_array_elements(p_document->'responsibilities') r(value)
    WHERE value->>'responsibility_id'=expected_id;
   IF responsibility->>'loan_id' IS DISTINCT FROM loan->>'loan_id' OR responsibility->>'coverer_slot_id' IS DISTINCT FROM selected
    OR responsibility->'segments' IS DISTINCT FROM area->'segments'
    OR responsibility->'proximity_evidence' IS DISTINCT FROM costs#>ARRAY[area->>'areaId',selected,'evidence']
   THEN RAISE EXCEPTION 'Dated exact original lunch area responsibility or directed evidence differs';END IF;
   expected_responsibilities:=expected_responsibilities||jsonb_build_array(expected_id);
  END LOOP;
 END LOOP;
 FOR intent IN SELECT value FROM jsonb_array_elements(p_document->'notification_intents') LOOP
  expected_id:=public.static_weekly_digest_text('{"event":'||to_jsonb(intent->>'event')::text||',"loanId":'||to_jsonb(intent->>'loan_id')::text||',"slot":'||to_jsonb(intent->>'coverer_slot_id')::text||'}');
  IF intent->>'notification_key' IS DISTINCT FROM expected_id THEN RAISE EXCEPTION 'Dated original lunch notification identity differs';END IF;
 END LOOP;
 IF EXISTS((SELECT value FROM jsonb_array_elements(expected_responsibilities) EXCEPT ALL SELECT value->'responsibility_id' FROM jsonb_array_elements(p_document->'responsibilities'))
  UNION ALL(SELECT value->'responsibility_id' FROM jsonb_array_elements(p_document->'responsibilities') EXCEPT ALL SELECT value FROM jsonb_array_elements(expected_responsibilities)))
 THEN RAISE EXCEPTION 'Dated complete original lunch responsibilities differ';END IF;
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_assert_approved_dated_projection(p_envelope jsonb, p_publication_id uuid, p_week date, p_exceptions jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE authority jsonb:=p_envelope->'authority';source jsonb;live_source jsonb;approved_source jsonb;config jsonb;entry record;current_source record;
 expected_availability jsonb:='[]';expected_slots jsonb:='[]';expected_rows jsonb:='[]';expected_projection jsonb:='[]';
 slot jsonb;availability jsonb;incumbent jsonb;owner_config jsonb;work jsonb;normalized_work jsonb;person jsonb;owner_key text;
 roster jsonb:='[]';projection_availability jsonb;item jsonb;identity_key text;d date;day integer;baseline_person jsonb;
 productive numeric;effort numeric;duty numeric;v_source_id uuid;employee_count integer;working_count integer:=0;
 mapped_rows jsonb;mapping jsonb;role_availability jsonb;actual_availability jsonb;role_profile jsonb;actual_profile jsonb;
 route jsonb;stops jsonb;stop jsonb;nodes jsonb;node jsonb;previous_node jsonb;blocked jsonb;protected_windows jsonb;
 route_start text;route_provenance text;node_start integer;node_end integer;previous_end integer;shift_start integer;shift_end integer;
 block_start integer;block_end integer;cursor_minute integer;protected_minutes integer;travel integer;available_gap integer;
 committed_duty numeric;stop_effort numeric;stop_duration integer;route_count integer:=0;route_pass integer;baseline_travel integer;staged_stop_nodes jsonb;
 p_date date:=p_week;operation_date date;operation_day integer;raw_source jsonb;compiler_exceptions jsonb;
 baseline jsonb;candidate_version jsonb;original_rows jsonb;unaffected jsonb;expected_unaffected jsonb;physical_rows jsonb;
 assignment_links jsonb:='{}';original_assignment uuid;effective_work jsonb;effective_original jsonb;
 closing jsonb:=authority->'shiftEndDerivation';closing_result jsonb;closing_enabled boolean;parent_id text;raw_parent jsonb;is_open boolean;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 IF p_week IS NULL OR NOT isfinite(p_week) OR extract(isodow FROM p_week)<>1
  OR p_publication_id IS NULL OR jsonb_typeof(authority) IS DISTINCT FROM 'object'
 THEN RAISE EXCEPTION 'Exact dated publication and Monday required';END IF;
 PERFORM public.static_weekly_assert_exact_object(authority,
  ARRAY['schema','effectiveDate','compilerInput','overlayCompilerInput','inputDigest','baselineInputDigest','derivedBaselineDigest','shiftEndDerivation','projectionAvailability','mapping','basisDigest','witnessDigest','solverInvoked','optimized','originalCompilerInput','originalWeekCompilerInput','weekDerivation','originalInputDigest','mappedBaselineInputDigest','originalPublicationId','originalVersionId','scopeDates','scopeDays','appliedExceptions'],
  ARRAY['schema','effectiveDate','compilerInput','overlayCompilerInput','inputDigest','baselineInputDigest','derivedBaselineDigest','shiftEndDerivation','projectionAvailability','mapping','basisDigest','witnessDigest','solverInvoked','optimized','originalCompilerInput','originalWeekCompilerInput','weekDerivation','originalInputDigest','mappedBaselineInputDigest','originalPublicationId','originalVersionId','scopeDates','scopeDays','appliedExceptions'],'approved dated authority');
 PERFORM public.static_weekly_assert_exact_object(p_envelope->'receipt',
  ARRAY['schema','feasibilityDigest','hardConstraintCount','hardConstraintDigest','independentDerivations','solverInvoked','optimized'],
  ARRAY['schema','feasibilityDigest','hardConstraintCount','hardConstraintDigest','independentDerivations','solverInvoked','optimized'],'approved dated receipt DATA');
 PERFORM public.static_weekly_assert_exact_object(p_envelope,
  ARRAY['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','semantic_snapshot','database_projection_identity'],
  ARRAY['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','semantic_snapshot','database_projection_identity'],'approved dated projection');
 IF jsonb_typeof(authority->'scopeDates') IS DISTINCT FROM 'array' OR jsonb_array_length(authority->'scopeDates')<>1
  OR jsonb_typeof(authority->'scopeDays') IS DISTINCT FROM 'array' OR jsonb_array_length(authority->'scopeDays')<>1
  OR coalesce(authority#>>'{scopeDates,0}','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
 THEN RAISE EXCEPTION 'Singleton dated operation scope required';END IF;
 operation_date:=(authority#>>'{scopeDates,0}')::date;operation_day:=extract(dow FROM operation_date)::integer;
 IF NOT isfinite(operation_date) OR operation_date NOT BETWEEN p_week AND p_week+6
  OR authority->'scopeDays' IS DISTINCT FROM jsonb_build_array(operation_day)
 THEN RAISE EXCEPTION 'Dated operation lies outside its original week';END IF;
 SELECT s.source_id,s.canonical_source,s.source_digest,v.draft_document,v.version_id INTO STRICT current_source
  FROM public.weekly_schedule_publications p JOIN public.weekly_schedule_versions v USING(version_id)
  JOIN public.static_weekly_authority_source_documents s ON s.source_id=v.authority_source_id
  WHERE p.publication_id=p_publication_id AND v.version_id=public.static_weekly_effective_version(p_week)
   AND v.version_id=public.static_weekly_effective_version(p_week+6) AND s.active AND s.retired_at IS NULL;
 v_source_id:=current_source.source_id;
 IF current_source.source_digest IS DISTINCT FROM public.static_weekly_digest_jsonb(current_source.canonical_source)
 THEN RAISE EXCEPTION 'Dated registered Source differs';END IF;
 raw_source:=public.static_weekly_v3_read_publication_source(p_publication_id,p_week);
 live_source:=raw_source->'compiler_input';
 compiler_exceptions:=public.static_weekly_compiler_exception_set(p_publication_id,p_week);
 baseline:=authority->'compilerInput';closing_enabled:=live_source#>'{version,shiftEndContinuityPolicy}' IS NOT NULL;
 source:=CASE WHEN closing_enabled THEN closing->'mappedInput' ELSE authority->'overlayCompilerInput' END;
 IF jsonb_typeof(source->'slots') IS DISTINCT FROM 'array' OR jsonb_array_length(source->'slots') NOT BETWEEN 6 AND 32
  OR jsonb_typeof(source#>'{version,slotAvailability}') IS DISTINCT FROM 'array'
  OR jsonb_typeof(source#>'{version,assignments}') IS DISTINCT FROM 'array'
  OR jsonb_array_length(source#>'{version,assignments}') NOT BETWEEN 1 AND 4096
  OR (SELECT count(*) FROM jsonb_array_elements(source#>'{version,slotAvailability}'))<>7*jsonb_array_length(source->'slots')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(source->'slots') s CROSS JOIN generate_series(0,6) day(n)
   WHERE (SELECT count(*) FROM jsonb_array_elements(source#>'{version,slotAvailability}') a
    WHERE a->'slotId'=s->'id' AND a->'dayOfWeek'=to_jsonb(day.n))<>1)
 THEN RAISE EXCEPTION 'Dated bounded total seven-day slot Source required';END IF;
 IF p_exceptions IS DISTINCT FROM public.static_weekly_accepted_exception_set(p_publication_id,p_week)
  OR authority->'appliedExceptions' IS DISTINCT FROM p_exceptions OR p_envelope->'applied_exceptions' IS DISTINCT FROM p_exceptions
  OR authority->'originalCompilerInput' IS DISTINCT FROM jsonb_set(jsonb_set(live_source,'{serviceDate}',to_jsonb(operation_date::text),true),'{exceptions}',compiler_exceptions,true)
  OR authority->'originalWeekCompilerInput' IS DISTINCT FROM jsonb_set(CASE WHEN closing_enabled THEN closing->'originalDerivedInput' ELSE live_source END,'{exceptions}',compiler_exceptions,true)
  OR baseline IS DISTINCT FROM jsonb_set(live_source,'{exceptions}','[]'::jsonb,true)
  OR source->'exceptions' IS DISTINCT FROM compiler_exceptions
  OR source-'version'-'exceptions' IS DISTINCT FROM live_source-'version'-'exceptions'
  OR (source->'version')-'assignments' IS DISTINCT FROM (live_source->'version')-'assignments'
  OR authority->>'originalPublicationId' IS DISTINCT FROM p_publication_id::text
  OR authority->>'originalVersionId' IS DISTINCT FROM live_source#>>'{version,id}'
 THEN RAISE EXCEPTION 'Dated original Source publication version or complete exceptions differ';END IF;
 IF (closing_enabled AND closing->>'schema' IS DISTINCT FROM 'custodial.approved-static-dated-closing.v1')
  OR (NOT closing_enabled AND closing IS DISTINCT FROM 'null'::jsonb)
  OR source#>'{version,shiftEndDerivationApplied}' IS NOT NULL
 THEN RAISE EXCEPTION 'Dated closing requires its exact typed original/selected wrapper';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(compiler_exceptions) e
   WHERE e->>'type' NOT IN('pto','daily_absence','partial_absence','lunch','shift_override','event_impact','manager_correction','nine_forty_five_rebalance'))
 THEN RAISE EXCEPTION USING ERRCODE='0A000',MESSAGE='Unqualified approved dated work-changing exception profile';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(compiler_exceptions) e WHERE e->>'type' IN('pto','daily_absence')
  GROUP BY e->>'serviceDate',e#>>'{payload,slotId}' HAVING count(*)>1)
 THEN RAISE EXCEPTION 'Dated duplicate full-day absence differs';END IF;
 SELECT c.owner_config INTO STRICT config FROM public.static_weekly_approved_template_source_configs c
  WHERE c.source_id=v_source_id AND c.config_digest=public.static_weekly_digest_jsonb(c.owner_config);
 IF config->>'schema' IS DISTINCT FROM 'custodial.owner-corrected-recurring-schedule.v2'
  OR jsonb_typeof(config->'slots') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Recurring typed owner configuration required';END IF;
 FOR owner_key,owner_config IN SELECT key,value FROM jsonb_each(config->'slots') LOOP
  IF owner_config ? 'normalAllowedFamilies' OR owner_config ? 'forbiddenFamilies'
   OR EXISTS(SELECT 1 FROM unnest(ARRAY['normalAssignmentFamilies','hardForbiddenFamilies']) f
    WHERE owner_config ? f AND (jsonb_typeof(owner_config->f) IS DISTINCT FROM 'array'
     OR EXISTS(SELECT 1 FROM jsonb_array_elements(owner_config->f) family WHERE jsonb_typeof(family)<>'string' OR family#>>'{}' !~ '^[A-Z0-9_]+$')
     OR (SELECT count(*) FROM jsonb_array_elements(owner_config->f))<>(SELECT count(DISTINCT family) FROM jsonb_array_elements(owner_config->f) family))) THEN
   RAISE EXCEPTION 'Recurring normal geography and hard exclusions require exact separate typed families';END IF;
  IF (owner_config->>'personId'='3da709bb-2223-4e15-8e3a-db02e3f32e97' AND (owner_key<>'KAREN' OR owner_config->>'slotId'<>'f22348e9-d4b9-5a7e-b8fd-d0d2c1ec534f'))
   OR (owner_config->>'personId'='cd97111e-cfa0-4228-b4d7-401bc7a5ac13' AND (owner_key<>'TAMMY' OR owner_config->>'slotId'<>'4a5a83ca-d297-5a30-8344-db08d05b978c'))
   OR (owner_config->>'personId'='30ec85e0-a579-45a8-9c27-c164e77a9190' AND (owner_key<>'KATHY' OR owner_config->>'slotId'<>'55e5939c-175c-5026-94fd-c4350d538922'))
   OR (owner_config->>'personId'='77d50e9a-6338-43b1-aed5-9f47d7129466' AND (owner_key<>'ALIJAH' OR owner_config->>'slotId'<>'36829381-70d7-521b-9f14-bad0af16ba87'
    OR owner_config->'hardForbiddenFamilies' IS DISTINCT FROM '["HERPETARIUM"]'::jsonb)) THEN
   RAISE EXCEPTION 'Recurring original personal geography identity or hard exclusion differs';END IF;
 END LOOP;

 SELECT * INTO STRICT entry FROM public.static_weekly_approved_template_catalog
  WHERE template_id=authority#>>'{mapping,templateId}' AND NOT EXISTS(
   SELECT 1 FROM public.static_weekly_approved_template_retirements r WHERE r.template_id=static_weekly_approved_template_catalog.template_id);
 IF entry.staffing_count NOT BETWEEN 6 AND 9 OR entry.owner_config IS DISTINCT FROM config
  OR entry.binding_json->>'patternAuthority' IS DISTINCT FROM 'OWNER_APPROVED_OPERATIONAL_PATTERN'
  OR entry.catalog_entry_digest IS DISTINCT FROM public.static_weekly_digest_jsonb(jsonb_build_object(
   'template',entry.template_json,'binding',entry.binding_json,'ownerConfig',entry.owner_config,'approvalEvidence',entry.approval_evidence))
  OR authority#>>'{mapping,schema}' IS DISTINCT FROM 'custodial.approved-static-template-mapping.v1'
  OR authority#>>'{mapping,contract}' IS DISTINCT FROM 'FIXED_APPROVED_GEOMETRY_COMPATIBILITY_NOT_GLOBAL_OPTIMALITY'
  OR authority#>'{mapping,staffingCount}' IS DISTINCT FROM to_jsonb(entry.staffing_count)
  OR authority#>>'{mapping,serviceDate}' IS DISTINCT FROM operation_date::text
  OR authority#>'{mapping,scopeDays}' IS DISTINCT FROM jsonb_build_array(operation_day)
  OR authority#>'{mapping,solverInvoked}' IS DISTINCT FROM 'false'::jsonb
  OR authority#>'{mapping,admitted}' IS DISTINCT FROM 'false'::jsonb
  OR authority#>'{mapping,published}' IS DISTINCT FROM 'false'::jsonb
 THEN RAISE EXCEPTION 'Dated current approved template configuration or scope differs';END IF;
 approved_source:=entry.template_json->'source';
 IF jsonb_typeof(approved_source->'version') IS DISTINCT FROM 'object'
  OR approved_source->'exceptions' IS DISTINCT FROM '[]'::jsonb
  OR approved_source->'proximity' IS DISTINCT FROM live_source->'proximity'
  OR approved_source#>'{version,shiftEndContinuityPolicy}' IS DISTINCT FROM live_source#>'{version,shiftEndContinuityPolicy}'
  OR jsonb_typeof(authority#>'{mapping,slotMapping}') IS DISTINCT FROM 'array'
  OR jsonb_array_length(authority#>'{mapping,slotMapping}')<>entry.staffing_count
  OR jsonb_array_length(entry.template_json->'roleSlotIds')<>entry.staffing_count
  OR (SELECT count(DISTINCT r) FROM jsonb_array_elements(entry.template_json->'roleSlotIds') r)<>entry.staffing_count
  OR (SELECT count(DISTINCT m->>'patternSlotId') FROM jsonb_array_elements(authority#>'{mapping,slotMapping}') m)<>entry.staffing_count
  OR (SELECT count(DISTINCT m->>'actualSlotId') FROM jsonb_array_elements(authority#>'{mapping,slotMapping}') m)<>entry.staffing_count
  OR (SELECT count(DISTINCT m->>'actualPersonId') FROM jsonb_array_elements(authority#>'{mapping,slotMapping}') m)<>entry.staffing_count
 THEN RAISE EXCEPTION 'Dated bijection or original route policy differs';END IF;
 FOR mapping IN SELECT value FROM jsonb_array_elements(authority#>'{mapping,slotMapping}') LOOP
  PERFORM public.static_weekly_assert_exact_object(mapping,ARRAY['patternSlotId','actualSlotId','actualPersonId'],
   ARRAY['patternSlotId','actualSlotId','actualPersonId'],'dated role mapping');
  SELECT value INTO STRICT slot FROM jsonb_array_elements(live_source->'slots') WHERE value->'id'=mapping->'actualSlotId';
  SELECT value INTO STRICT incumbent FROM jsonb_array_elements(slot->'incumbencies')
   WHERE (value->>'effectiveStart')::date<=operation_date AND (value->>'effectiveEnd' IS NULL OR operation_date<(value->>'effectiveEnd')::date);
  IF NOT(entry.template_json->'roleSlotIds' ? (mapping->>'patternSlotId'))
   OR coalesce(slot->'contractorCapacity','false'::jsonb)<>'false'::jsonb
   OR incumbent->'personId' IS DISTINCT FROM mapping->'actualPersonId'
   OR NOT EXISTS(SELECT 1 FROM jsonb_each(config->'slots') c WHERE c.value->'slotId'=mapping->'actualSlotId'
    AND c.value->'personId'=mapping->'actualPersonId' AND c.value->'vacancy' IS DISTINCT FROM 'true'::jsonb)
  THEN RAISE EXCEPTION 'Dated role does not name actual operation-day employee';END IF;
  SELECT value INTO STRICT role_availability FROM jsonb_array_elements(approved_source#>'{version,slotAvailability}')
   WHERE value->'slotId'=mapping->'patternSlotId' AND value->>'dayOfWeek'=operation_day::text;
  SELECT value INTO STRICT actual_availability FROM jsonb_array_elements(live_source#>'{version,slotAvailability}')
   WHERE value->'slotId'=mapping->'actualSlotId' AND value->>'dayOfWeek'=operation_day::text;
  actual_availability:=public.static_weekly_approved_dated_effective_availability(actual_availability,mapping->>'actualSlotId',operation_date,compiler_exceptions);
  IF NOT(role_availability ? 'acceptedRoute') AND approved_source#>ARRAY['version','acceptedRoutesBySlot',mapping->>'patternSlotId'] IS NOT NULL THEN
   role_availability:=role_availability||jsonb_build_object('acceptedRoute',approved_source#>ARRAY['version','acceptedRoutesBySlot',mapping->>'patternSlotId']);END IF;
  IF NOT(actual_availability ? 'acceptedRoute') AND live_source#>ARRAY['version','acceptedRoutesBySlot',mapping->>'actualSlotId'] IS NOT NULL THEN
   actual_availability:=actual_availability||jsonb_build_object('acceptedRoute',live_source#>ARRAY['version','acceptedRoutesBySlot',mapping->>'actualSlotId']);END IF;
  SELECT jsonb_build_object('shift',a->'shift','lunch',a->'lunch','blocked',coalesce(a->'blockedWindows','[]'::jsonb),
   'service',coalesce(a->'maxServiceEffortMinutes',a->'maxLoadPoints'),'duty',coalesce(a->'maxDutyMinutes',a->'max_duty_minutes'),
   'route',a->'acceptedRoute','start',coalesce(a->'acceptedRouteStartLocationId',a->'acceptedRouteAnchorLocationId',a->'routeAnchorLocationId'),
   'stops',a->'acceptedRouteStops') INTO role_profile FROM(SELECT role_availability a)t;
  SELECT jsonb_build_object('shift',a->'shift','lunch',a->'lunch','blocked',coalesce(a->'blockedWindows','[]'::jsonb),
   'service',coalesce(a->'maxServiceEffortMinutes',a->'maxLoadPoints'),'duty',coalesce(a->'maxDutyMinutes',a->'max_duty_minutes'),
   'route',a->'acceptedRoute','start',coalesce(a->'acceptedRouteStartLocationId',a->'acceptedRouteAnchorLocationId',a->'routeAnchorLocationId'),
   'stops',a->'acceptedRouteStops') INTO actual_profile FROM(SELECT actual_availability a)t;
  IF role_profile IS DISTINCT FROM actual_profile OR actual_availability->>'status' IS DISTINCT FROM 'working'
  THEN RAISE EXCEPTION 'Dated current role availability route or duty profile differs';END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(approved_source#>'{version,assignments}') w WHERE w->>'dayOfWeek'=operation_day::text
   AND (SELECT count(*) FROM jsonb_array_elements(authority#>'{mapping,slotMapping}') m WHERE m->'patternSlotId'=w->'ownerSlotId')<>1)
 THEN RAISE EXCEPTION 'Dated approved work has an unmapped role';END IF;
 SELECT coalesce(jsonb_agg(w ORDER BY (w->>'dayOfWeek')::integer,w->>'workId' COLLATE "C"),'[]') INTO original_rows
  FROM jsonb_array_elements(live_source#>'{version,assignments}') w WHERE w->>'dayOfWeek'<>operation_day::text;
 SELECT coalesce(jsonb_agg(w ORDER BY (w->>'dayOfWeek')::integer,w->>'workId' COLLATE "C"),'[]') INTO unaffected
  FROM jsonb_array_elements(source#>'{version,assignments}') w WHERE w->>'dayOfWeek'<>operation_day::text;
 SELECT coalesce(jsonb_agg(jsonb_set(w,'{ownerSlotId}',m->'actualSlotId') ORDER BY w->>'workId' COLLATE "C"),'[]') INTO mapped_rows
  FROM jsonb_array_elements(approved_source#>'{version,assignments}') w
  JOIN jsonb_array_elements(authority#>'{mapping,slotMapping}') m ON m->'patternSlotId'=w->'ownerSlotId' WHERE w->>'dayOfWeek'=operation_day::text;
 SELECT coalesce(jsonb_agg(w ORDER BY w->>'workId' COLLATE "C"),'[]') INTO expected_rows
  FROM jsonb_array_elements(source#>'{version,assignments}') w WHERE w->>'dayOfWeek'=operation_day::text;
 IF original_rows IS DISTINCT FROM unaffected OR mapped_rows IS DISTINCT FROM expected_rows OR jsonb_array_length(mapped_rows)=0
  OR (SELECT count(*) FROM jsonb_array_elements(source#>'{version,assignments}'))<>
   (SELECT count(DISTINCT (w->>'dayOfWeek',w->>'workId')) FROM jsonb_array_elements(source#>'{version,assignments}') w)
 THEN RAISE EXCEPTION 'Dated exact selected mapping or six unaffected day rows differ';END IF;
 effective_work:=public.static_weekly_approved_dated_effective_work(p_publication_id,p_week,source);
 effective_original:=public.static_weekly_approved_dated_effective_work(p_publication_id,p_week,
  jsonb_set(live_source,'{exceptions}',compiler_exceptions,true));
 IF EXISTS(WITH rows AS(
   SELECT 0 side,w FROM jsonb_array_elements(approved_source#>'{version,assignments}') w
   UNION ALL SELECT 1,w FROM jsonb_array_elements(live_source#>'{version,assignments}') w
  UNION ALL SELECT 2,w FROM jsonb_array_elements(current_source.canonical_source#>'{version,assignments}') w
  ), facts AS(SELECT side,w,jsonb_build_object('day',w->'dayOfWeek','family',w->'locationCodeSnapshot',
   'phase',CASE WHEN w#>>'{window,end}'='09:45' THEN '"morning"'::jsonb WHEN w#>>'{window,start}'='09:45' THEN '"equalized"'::jsonb ELSE w->'window' END,
   'mode',w->'serviceMode','scheduling',w->'schedulingMode','required',coalesce(w->'required','true'::jsonb),
   'priority',w->'priority','qualifications',w->'requiredQualifications','restrictions',w->'restrictions',
   'restrictedSlots',coalesce(w->'restrictedSlotIds','[]'::jsonb),'policy',w->'coveragePolicy','order',w->'coveragePolicyOrder') f FROM rows WHERE w->>'dayOfWeek'=operation_day::text),
  efforts AS(SELECT side,f,sum((w->>'serviceEffortMinutes')::numeric) effort FROM facts GROUP BY side,f),
  members AS(SELECT side,f,jsonb_agg(member ORDER BY member) members FROM facts CROSS JOIN LATERAL
   jsonb_array_elements(CASE WHEN jsonb_array_length(coalesce(w->'includedLocations','[]'::jsonb))>0 THEN w->'includedLocations'
    ELSE jsonb_build_array(jsonb_build_object('locationId',w->'locationId','locationNameSnapshot',w->'locationNameSnapshot')) END) member GROUP BY side,f),
  domain AS(SELECT side,f,effort,members FROM efforts JOIN members USING(side,f))
  (SELECT f,effort,members FROM domain WHERE side=0 EXCEPT ALL SELECT f,effort,members FROM domain WHERE side=1)
  UNION ALL(SELECT f,effort,members FROM domain WHERE side=1 EXCEPT ALL SELECT f,effort,members FROM domain WHERE side=0)
  UNION ALL(SELECT f,effort,members FROM domain WHERE side=1 EXCEPT ALL SELECT f,effort,members FROM domain WHERE side=2)
  UNION ALL(SELECT f,effort,members FROM domain WHERE side=2 EXCEPT ALL SELECT f,effort,members FROM domain WHERE side=1)) THEN
  RAISE EXCEPTION 'Dated approved physical responsibility multiset differs from current Source';END IF;
 -- The existing producer compares the approved physical domain against the
 -- EFFECTIVE current work, not just its raw baseline. Never let an event get
 -- dropped into a stale pattern; no hash or accepted-command label replaces
 -- this multiplicity/effort/eligibility check. A truly new domain needs an
 -- actual compatible approved producer/catalog entry before this can succeed.
 IF EXISTS(WITH rows AS(
   SELECT 0 side,w FROM jsonb_array_elements(approved_source#>'{version,assignments}') w
   UNION ALL SELECT 1,w FROM jsonb_array_elements(effective_original) w
   UNION ALL SELECT 2,w FROM jsonb_array_elements(effective_work) w
  ), facts AS(SELECT side,w,jsonb_build_object('day',w->'dayOfWeek','family',w->'locationCodeSnapshot',
   'phase',CASE WHEN w#>>'{window,end}'='09:45' THEN '"morning"'::jsonb WHEN w#>>'{window,start}'='09:45' THEN '"equalized"'::jsonb ELSE w->'window' END,
   'mode',w->'serviceMode','scheduling',w->'schedulingMode','required',coalesce(w->'required','true'::jsonb),
   'priority',w->'priority','qualifications',w->'requiredQualifications','restrictions',w->'restrictions',
   'restrictedSlots',coalesce(w->'restrictedSlotIds','[]'::jsonb),'policy',w->'coveragePolicy','order',w->'coveragePolicyOrder') f
   FROM rows WHERE w->>'dayOfWeek'=operation_day::text),
  efforts AS(SELECT side,f,sum((w->>'serviceEffortMinutes')::numeric) effort FROM facts GROUP BY side,f),
  members AS(SELECT side,f,jsonb_agg(member ORDER BY member) members FROM facts CROSS JOIN LATERAL
   jsonb_array_elements(CASE WHEN jsonb_array_length(coalesce(w->'includedLocations','[]'::jsonb))>0 THEN w->'includedLocations'
    ELSE jsonb_build_array(jsonb_build_object('locationId',w->'locationId','locationNameSnapshot',w->'locationNameSnapshot')) END) member GROUP BY side,f),
  domain AS(SELECT side,f,effort,members FROM efforts JOIN members USING(side,f))
  (SELECT f,effort,members FROM domain WHERE side=0 EXCEPT ALL SELECT f,effort,members FROM domain WHERE side=1)
  UNION ALL(SELECT f,effort,members FROM domain WHERE side=1 EXCEPT ALL SELECT f,effort,members FROM domain WHERE side=0)
  UNION ALL(SELECT f,effort,members FROM domain WHERE side=1 EXCEPT ALL SELECT f,effort,members FROM domain WHERE side=2)
  UNION ALL(SELECT f,effort,members FROM domain WHERE side=2 EXCEPT ALL SELECT f,effort,members FROM domain WHERE side=1))
 THEN RAISE EXCEPTION USING ERRCODE='0A000',MESSAGE='Dated accepted event requires a compatible approved physical domain';END IF;
 IF closing_enabled THEN
  closing_result:=public.static_weekly_approved_dated_assert_closing(closing,baseline,approved_source,config,authority->'mapping',operation_date);
  IF (authority->'overlayCompilerInput')-'version' IS DISTINCT FROM
    jsonb_set(closing_result->'effectiveInput','{exceptions}',compiler_exceptions,true)-'version'
   OR (authority#>'{overlayCompilerInput,version}')-'assignments' IS DISTINCT FROM (closing_result#>'{effectiveInput,version}')-'assignments'
   OR (SELECT jsonb_agg(w ORDER BY n) FROM jsonb_array_elements(authority#>'{overlayCompilerInput,version,assignments}') WITH ORDINALITY x(w,n) WHERE w->>'dayOfWeek'<>operation_day::text)
    IS DISTINCT FROM (SELECT jsonb_agg(w ORDER BY n) FROM jsonb_array_elements(closing#>'{originalDerivedInput,version,assignments}') WITH ORDINALITY x(w,n) WHERE w->>'dayOfWeek'<>operation_day::text)
   OR EXISTS((SELECT value FROM jsonb_array_elements(authority#>'{overlayCompilerInput,version,assignments}')
     EXCEPT ALL SELECT value FROM jsonb_array_elements(closing_result#>'{effectiveInput,version,assignments}'))
    UNION ALL(SELECT value FROM jsonb_array_elements(closing_result#>'{effectiveInput,version,assignments}')
     EXCEPT ALL SELECT value FROM jsonb_array_elements(authority#>'{overlayCompilerInput,version,assignments}')))
  THEN RAISE EXCEPTION 'Dated whole derived week differs from original six days plus selected chain';END IF;
  effective_work:=public.static_weekly_approved_dated_effective_work(p_publication_id,p_week,
   jsonb_set(closing_result->'effectiveInput','{exceptions}',compiler_exceptions,true));
  effective_original:=public.static_weekly_approved_dated_effective_work(p_publication_id,p_week,
   jsonb_set(closing->'originalDerivedInput','{exceptions}',compiler_exceptions,true));
 END IF;
 FOR availability IN SELECT value FROM jsonb_array_elements(source#>'{version,slotAvailability}') LOOP
  SELECT value INTO STRICT slot FROM jsonb_array_elements(source->'slots') WHERE value->>'id'=availability->>'slotId';
  IF NOT(availability ? 'acceptedRoute') AND source#>ARRAY['version','acceptedRoutesBySlot',slot->>'id'] IS NOT NULL THEN
   availability:=availability||jsonb_build_object('acceptedRoute',source#>ARRAY['version','acceptedRoutesBySlot',slot->>'id']);
  END IF;
  day:=(availability->>'dayOfWeek')::integer;d:=p_date+mod(day+6,7);
  availability:=public.static_weekly_approved_dated_effective_availability(availability,slot->>'id',d,compiler_exceptions);
  incumbent:=NULL;
  IF coalesce(slot->'contractorCapacity','false'::jsonb)='false'::jsonb THEN
   SELECT value INTO incumbent FROM jsonb_array_elements(slot->'incumbencies')
    WHERE (value->>'effectiveStart')::date<=d AND (value->>'effectiveEnd' IS NULL OR d<(value->>'effectiveEnd')::date);
   IF (SELECT count(*) FROM jsonb_array_elements(slot->'incumbencies')
     WHERE (value->>'effectiveStart')::date<=d AND (value->>'effectiveEnd' IS NULL OR d<(value->>'effectiveEnd')::date))>1 THEN
    RAISE EXCEPTION 'Dated dated incumbent is ambiguous';END IF;
  ELSIF availability->>'status'='working' THEN
   RAISE EXCEPTION 'Active contractor capacity is not an ordinary dated employee profile';END IF;
  projection_availability:=jsonb_build_object('dayOfWeek',day,'serviceDate',d::text)||availability||jsonb_build_object(
   'incumbentSlotId',slot->'id','incumbentSlotLabel',slot->'label',
   'incumbentPersonId',incumbent->'personId','incumbentName',incumbent->'displayName');
  IF slot->>'kind'='CONTRACTOR_CAPACITY' THEN
   IF slot->'capacityId' IS DISTINCT FROM slot->'id' OR slot->'incumbencies' IS DISTINCT FROM '[]'::jsonb THEN
    RAISE EXCEPTION 'Dated inactive capacity original identity differs';END IF;
   projection_availability:=projection_availability||jsonb_build_object('ownerKind','CONTRACTOR_CAPACITY','capacityId',slot->'id');
  END IF;
  expected_availability:=expected_availability||jsonb_build_array(projection_availability);
  roster:=roster||jsonb_build_array(projection_availability);
  IF coalesce(slot->'contractorCapacity','false'::jsonb)='true'::jsonb THEN CONTINUE;END IF;
  IF availability->>'status'='working' THEN
   working_count:=working_count+1;
   -- Only the selected day creates a new mapped employee choice. Preserve
   -- the six other days' actual dated snapshots, including prior/future
   -- incumbents; never reinterpret them as the operation-day employee.
   SELECT value INTO STRICT owner_config FROM jsonb_each(config->'slots')
    WHERE value->>'slotId'=slot->>'id' AND (d<>operation_date OR
     (value->>'personId'=incumbent->>'personId' AND value->'vacancy' IS DISTINCT FROM 'true'::jsonb));
   IF incumbent IS NULL OR (d=operation_date AND NOT EXISTS(SELECT 1 FROM public.employees e
    WHERE e.id=(incumbent->>'personId')::uuid AND e.active AND e.display_name=incumbent->>'displayName')) THEN
    RAISE EXCEPTION 'Dated mapped owner requires the exact active operation-day employee';END IF;
   PERFORM public.static_weekly_approved_dated_assert_window(availability->'shift','dated shift');
   PERFORM public.static_weekly_approved_dated_assert_window(availability->'lunch','dated lunch');
   -- Flexible responsibility is not an appointment. Fixed work and accepted
   -- stops instead share one independently reconstructed chronological route.
   route:=coalesce(availability->'acceptedRoute','{}'::jsonb);
   route_start:=coalesce(route->>'startLocationId',route->>'start_location_id',availability->>'acceptedRouteStartLocationId',
    availability->>'acceptedRouteAnchorLocationId',availability->>'routeAnchorLocationId');
   route_provenance:=coalesce(route->>'provenance',availability->>'acceptedRouteProvenance');
   stops:=coalesce(route->'stops',route->'existingStops',availability->'acceptedRouteStops','[]'::jsonb);
   IF jsonb_typeof(route) IS DISTINCT FROM 'object' OR jsonb_typeof(stops) IS DISTINCT FROM 'array'
    OR nullif(route_start,'') IS NULL OR nullif(route_provenance,'') IS NULL
    OR jsonb_typeof(coalesce(availability->'blockedWindows','[]'::jsonb)) IS DISTINCT FROM 'array'
    OR nullif(availability->>'productiveCapacityProvenance','') IS NULL
    OR nullif(availability->>'maxServiceEffortProvenance','') IS NULL
    OR nullif(availability->>'qualificationProvenance','') IS NULL
    OR nullif(availability->>'restrictionProvenance','') IS NULL
    OR jsonb_typeof(availability->'qualifications') IS DISTINCT FROM 'array'
    OR jsonb_typeof(availability->'restrictions') IS DISTINCT FROM 'array'
    OR availability#>>'{lunch,start}'<availability#>>'{shift,start}'
    OR availability#>>'{lunch,end}'>availability#>>'{shift,end}' THEN
    RAISE EXCEPTION 'Dated current duty route and eligibility provenance invalid';END IF;
   shift_start:=extract(epoch FROM (availability#>>'{shift,start}')::time)::integer/60;
   shift_end:=extract(epoch FROM (availability#>>'{shift,end}')::time)::integer/60;
   protected_windows:=coalesce(availability->'blockedWindows','[]'::jsonb)||jsonb_build_array(availability->'lunch');
   FOR blocked IN SELECT value FROM jsonb_array_elements(protected_windows) LOOP
    PERFORM public.static_weekly_approved_dated_assert_window(blocked,'dated protected interval');
   END LOOP;
   -- Union clipped lunch/blocked intervals: overlaps are not double charged.
   cursor_minute:=shift_start;protected_minutes:=0;
   FOR blocked IN SELECT value FROM jsonb_array_elements(protected_windows) ORDER BY value->>'start',value->>'end' LOOP
    block_start:=greatest(shift_start,extract(epoch FROM (blocked->>'start')::time)::integer/60);
    block_end:=least(shift_end,extract(epoch FROM (blocked->>'end')::time)::integer/60);
    IF block_end>greatest(cursor_minute,block_start) THEN
     protected_minutes:=protected_minutes+block_end-greatest(cursor_minute,block_start);cursor_minute:=block_end;
    END IF;
   END LOOP;
   productive:=shift_end-shift_start-protected_minutes;
   duty:=coalesce((availability->>'maxDutyMinutes')::numeric,(availability->>'max_duty_minutes')::numeric,productive);
   IF productive<=0 OR duty<=0 OR duty>productive OR duty<>trunc(duty)
    OR ((availability ? 'maxDutyMinutes' OR availability ? 'max_duty_minutes')
     AND nullif(coalesce(availability->>'maxDutyProvenance',availability->>'max_duty_provenance'),'') IS NULL)
    OR jsonb_typeof(availability->'maxServiceEffortMinutes') IS DISTINCT FROM 'number'
    OR (availability->>'maxServiceEffortMinutes')::numeric<=0
    OR (availability->>'maxServiceEffortMinutes')::numeric<>trunc((availability->>'maxServiceEffortMinutes')::numeric) THEN
    RAISE EXCEPTION 'Dated independent duty or workload capacity invalid';END IF;
   nodes:='[]'::jsonb;stop_effort:=0;committed_duty:=0;
   FOR stop IN SELECT value FROM jsonb_array_elements(stops) LOOP
    PERFORM public.static_weekly_v3_assert_window(stop->'window','dated accepted stop');
    node_start:=extract(epoch FROM (stop#>>'{window,start}')::time)::integer/60;
    node_end:=extract(epoch FROM (stop#>>'{window,end}')::time)::integer/60;
    stop_duration:=node_end-node_start;
    IF nullif(coalesce(stop->>'locationId',stop->>'location'),'') IS NULL
     OR nullif(coalesce(stop->>'provenance',route_provenance),'') IS NULL
     OR nullif(coalesce(stop->>'serviceEffortProvenance',stop->>'service_effort_provenance',stop->>'provenance',route_provenance),'') IS NULL
     OR node_start<shift_start OR node_end>shift_end
     OR coalesce((stop->>'serviceEffortMinutes')::numeric,(stop->>'service_effort_minutes')::numeric,stop_duration)<=0
     OR coalesce((stop->>'serviceEffortMinutes')::numeric,(stop->>'service_effort_minutes')::numeric,stop_duration)>stop_duration
     OR coalesce((stop->>'serviceEffortMinutes')::numeric,(stop->>'service_effort_minutes')::numeric,stop_duration)<>
      trunc(coalesce((stop->>'serviceEffortMinutes')::numeric,(stop->>'service_effort_minutes')::numeric,stop_duration)) THEN
     RAISE EXCEPTION 'Dated accepted stop window effort or provenance invalid';END IF;
    stop_effort:=stop_effort+coalesce((stop->>'serviceEffortMinutes')::numeric,(stop->>'service_effort_minutes')::numeric,stop_duration);
    nodes:=nodes||jsonb_build_array(jsonb_build_object('start',node_start,'end',node_end,'location',coalesce(stop->>'locationId',stop->>'location')));
   END LOOP;
   staged_stop_nodes:=nodes;
   FOR route_pass IN 1..2 LOOP
   nodes:=staged_stop_nodes;baseline_travel:=0;committed_duty:=0;
   IF route_pass=2 THEN
    FOR work IN SELECT value FROM jsonb_array_elements(effective_work)
     WHERE value->'ownerSlotId'=slot->'id' AND value->>'dayOfWeek'=day::text AND NOT(value ? 'schedulingMode') LOOP
     PERFORM public.static_weekly_v3_assert_window(work->'window','dated fixed appointment');
     nodes:=nodes||jsonb_build_array(jsonb_build_object('start',extract(epoch FROM (work#>>'{window,start}')::time)::integer/60,
      'end',extract(epoch FROM (work#>>'{window,end}')::time)::integer/60,'location',work->>'locationId'));
    END LOOP;
   END IF;
   previous_end:=shift_start;previous_node:=jsonb_build_object('location',route_start);
   FOR node IN SELECT value FROM jsonb_array_elements(nodes) ORDER BY (value->>'start')::integer,(value->>'end')::integer,value->>'location' COLLATE "C" LOOP
    node_start:=(node->>'start')::integer;node_end:=(node->>'end')::integer;
    IF node_start<previous_end OR node_start<shift_start OR node_end>shift_end
     OR EXISTS(SELECT 1 FROM jsonb_array_elements(protected_windows) b
      WHERE extract(epoch FROM (b->>'start')::time)/60<node_end AND extract(epoch FROM (b->>'end')::time)/60>node_start) THEN
     RAISE EXCEPTION 'Dated fixed route overlaps another node lunch blocked interval or shift';END IF;
    travel:=NULL;
    IF previous_node->'location'=node->'location' THEN travel:=0;
    ELSE SELECT min((e->>'minutes')::integer) INTO travel FROM jsonb_array_elements(source->'proximity') e
     WHERE ((e->>'fromLocationId'=previous_node->>'location' AND e->>'toLocationId'=node->>'location')
      OR ((e->'bidirectional'='true'::jsonb OR e->'symmetric'='true'::jsonb)
       AND e->>'toLocationId'=previous_node->>'location' AND e->>'fromLocationId'=node->>'location'))
      AND e->'verified'='true'::jsonb AND jsonb_typeof(e->'minutes')='number'
      AND (e->>'minutes')::numeric>0 AND (e->>'minutes')::numeric=trunc((e->>'minutes')::numeric)
      AND nullif(e->>'provenance','') IS NOT NULL;
    END IF;
    cursor_minute:=previous_end;protected_minutes:=0;available_gap:=0;
    FOR blocked IN SELECT value FROM jsonb_array_elements(protected_windows) ORDER BY value->>'start',value->>'end' LOOP
     block_start:=greatest(previous_end,extract(epoch FROM (blocked->>'start')::time)::integer/60);
     block_end:=least(node_start,extract(epoch FROM (blocked->>'end')::time)::integer/60);
     IF block_end>block_start THEN
      available_gap:=greatest(available_gap,block_start-cursor_minute);
      protected_minutes:=protected_minutes+greatest(0,block_end-greatest(cursor_minute,block_start));
      cursor_minute:=greatest(cursor_minute,block_end);
     END IF;
    END LOOP;
    available_gap:=greatest(available_gap,node_start-cursor_minute);
    IF travel IS NULL OR (route_pass=1 AND node_start-previous_end<travel) OR (route_pass=2 AND available_gap<travel) THEN
     RAISE EXCEPTION 'Dated fixed route has no contiguous protected-safe directed transit';END IF;
    baseline_travel:=baseline_travel+travel;
    committed_duty:=committed_duty+node_end-node_start+travel+greatest(0,node_start-previous_end-travel-protected_minutes);
    previous_end:=node_end;previous_node:=node;
   END LOOP;
   IF route_pass=1 AND stop_effort+baseline_travel>productive THEN RAISE EXCEPTION 'Dated immutable accepted route baseline exceeds productive capacity';END IF;
   IF route_pass=2 AND committed_duty>duty THEN RAISE EXCEPTION 'Dated fixed service travel and committed waiting exceed duty capacity';END IF;
   END LOOP;
   route_count:=route_count+jsonb_array_length(stops);
   SELECT coalesce(sum((w->>'serviceEffortMinutes')::numeric),0) INTO effort
    FROM jsonb_array_elements(effective_work) w
    WHERE w->>'ownerSlotId'=slot->>'id' AND w->>'dayOfWeek'=day::text;
   IF effort+stop_effort>(availability->>'maxServiceEffortMinutes')::numeric THEN RAISE EXCEPTION 'Dated hard workload capacity including original stops exceeded';END IF;
  END IF;
 END LOOP;

 IF EXISTS((SELECT value FROM jsonb_array_elements(expected_availability) EXCEPT ALL SELECT value FROM jsonb_array_elements(authority->'projectionAvailability'))
  UNION ALL(SELECT value FROM jsonb_array_elements(authority->'projectionAvailability') EXCEPT ALL SELECT value FROM jsonb_array_elements(expected_availability)))
 THEN RAISE EXCEPTION 'Dated independently reconstructed full-week availability differs';END IF;
 SELECT count(*) INTO employee_count FROM jsonb_array_elements(roster) r WHERE r->>'serviceDate'=operation_date::text
  AND r->>'status'='working' AND r->>'incumbentPersonId' IS NOT NULL AND r->>'ownerKind' IS DISTINCT FROM 'CONTRACTOR_CAPACITY';
 IF employee_count<>entry.staffing_count OR EXISTS(SELECT 1 FROM jsonb_array_elements(roster) r
  WHERE r->>'serviceDate'=operation_date::text AND r->>'status'='working' AND r->>'incumbentPersonId' IS NOT NULL
  AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(authority#>'{mapping,slotMapping}') m
   WHERE m->'actualSlotId'=r->'slotId' AND m->'actualPersonId'=r->'incumbentPersonId'))
 THEN RAISE EXCEPTION 'Dated template must account for every current available operation-day employee';END IF;
 FOR work IN SELECT value FROM jsonb_array_elements(effective_work) LOOP
  day:=(work->>'dayOfWeek')::integer;
  SELECT value INTO STRICT person FROM jsonb_array_elements(roster) WHERE value->'slotId'=work->'ownerSlotId' AND value->>'dayOfWeek'=day::text;
  is_open:=closing_enabled AND person->>'status'='vacant_unfilled' AND person->>'incumbentPersonId' IS NULL
   AND position(':open:' in work->>'workId')>0;
  SELECT value INTO STRICT owner_config FROM jsonb_each(config->'slots') WHERE value->'slotId'=work->'ownerSlotId'
   AND (p_date+mod(day+6,7)<>operation_date OR value->'personId'=person->'incumbentPersonId'
    OR (is_open AND value->'vacancy'='true'::jsonb AND value->>'personId' IS NULL));
  PERFORM public.static_weekly_v3_assert_window(work->'window','dated independently derived work');
  IF (work ? 'schedulingMode' AND work->'schedulingMode' IS DISTINCT FROM '"flexible_coverage_ownership"'::jsonb)
   OR (NOT is_open AND (person->>'status' IS DISTINCT FROM 'working' OR person->>'incumbentPersonId' IS NULL))
   OR jsonb_typeof(work->'serviceEffortMinutes') IS DISTINCT FROM 'number'
   OR jsonb_typeof(work->'requiredQualifications') IS DISTINCT FROM 'array'
   OR jsonb_typeof(work->'restrictions') IS DISTINCT FROM 'array'
   OR nullif(work->>'qualificationProvenance','') IS NULL OR nullif(work->>'restrictionProvenance','') IS NULL
   OR (coalesce(work->'required','true'::jsonb) NOT IN('true'::jsonb,'false'::jsonb))
   OR (coalesce(work->'required','true'::jsonb)='true'::jsonb AND (jsonb_typeof(work->'priority') IS DISTINCT FROM 'number'
    OR (work->>'priority')::numeric<>trunc((work->>'priority')::numeric) OR nullif(work->>'priorityProvenance','') IS NULL))
   OR (work->>'serviceEffortMinutes')::numeric<=0 OR (work->>'serviceEffortMinutes')::numeric<>trunc((work->>'serviceEffortMinutes')::numeric)
   OR nullif(work->>'serviceEffortProvenance','') IS NULL
   OR (NOT(work ? 'schedulingMode') AND (work->>'serviceEffortMinutes')::numeric>
    extract(epoch FROM ((work#>>'{window,end}')::time-(work#>>'{window,start}')::time))/60)
   OR work#>>'{window,start}'<person#>>'{shift,start}' OR work#>>'{window,end}'>person#>>'{shift,end}'
   OR NOT(person->'qualifications' @> coalesce(work->'requiredQualifications','[]'::jsonb))
   OR coalesce(work->'restrictedSlotIds','[]'::jsonb) ? (work->>'ownerSlotId')
   OR coalesce(owner_config->'hardForbiddenFamilies','[]'::jsonb) ? (work->>'locationCodeSnapshot')
   OR (person->'restrictions') ? (work->>'locationId')
   OR (work->'_datedManualLock'<>'null'::jsonb AND work->'ownerSlotId' IS DISTINCT FROM work->'_datedManualLock')
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(work->'includedLocations','[]'::jsonb)) l WHERE (person->'restrictions') ? (l->>'locationId')) THEN
   RAISE EXCEPTION 'Dated independent fixed owner eligibility or work window differs';END IF;
  route_start:=coalesce(person#>>'{acceptedRoute,startLocationId}',person#>>'{acceptedRoute,start_location_id}',person->>'acceptedRouteStartLocationId',
   person->>'acceptedRouteAnchorLocationId',person->>'routeAnchorLocationId');
  IF work->>'schedulingMode'='flexible_coverage_ownership' AND work->>'serviceMode'<>'reminder_only' AND route_start IS DISTINCT FROM work->>'locationId'
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(source->'proximity') edge
    WHERE ((edge->>'fromLocationId'=route_start AND edge->>'toLocationId'=work->>'locationId')
     OR ((edge->'bidirectional'='true'::jsonb OR edge->'symmetric'='true'::jsonb) AND edge->>'toLocationId'=route_start AND edge->>'fromLocationId'=work->>'locationId'))
     AND edge->'verified'='true'::jsonb AND jsonb_typeof(edge->'minutes')='number'
     AND (edge->>'minutes')::numeric>=0 AND (edge->>'minutes')::numeric=trunc((edge->>'minutes')::numeric)
     AND nullif(edge->>'provenance','') IS NOT NULL) THEN
   RAISE EXCEPTION 'Dated fixed flexible area lacks exact verified directed geography';END IF;
  IF (person->>'incumbentPersonId',person->>'slotId') IN(
    ('3da709bb-2223-4e15-8e3a-db02e3f32e97','f22348e9-d4b9-5a7e-b8fd-d0d2c1ec534f'),
    ('cd97111e-cfa0-4228-b4d7-401bc7a5ac13','4a5a83ca-d297-5a30-8344-db08d05b978c'),
    ('30ec85e0-a579-45a8-9c27-c164e77a9190','55e5939c-175c-5026-94fd-c4350d538922'))
   AND NOT(coalesce(owner_config->'normalAssignmentFamilies','[]'::jsonb) ? (work->>'locationCodeSnapshot')) THEN
   RAISE EXCEPTION 'Dated original personal geography differs';END IF;
  SELECT value INTO baseline_person FROM jsonb_array_elements(roster) WHERE value->'slotId'=work->'originSlotId' AND value->>'dayOfWeek'=day::text;
  d:=p_date+mod(day+6,7);identity_key:=day::text||':'||(work->>'workId');
  IF is_open THEN work:=work||'{"required":false,"priority":0}'::jsonb;END IF;
  normalized_work:=jsonb_build_object('workId',work->'workId','dayOfWeek',day,'originSlotId',work->'originSlotId',
   'locationId',work->'locationId','locationCodeSnapshot',work->'locationCodeSnapshot','locationNameSnapshot',work->'locationNameSnapshot',
   'serviceMode',work->'serviceMode','includedLocations',work->'includedLocations','window',work->'window',
   'serviceEffortMinutes',work->'serviceEffortMinutes','serviceEffortProvenance',work->'serviceEffortProvenance',
   'priority',CASE WHEN work->'required'='false'::jsonb THEN '0'::jsonb ELSE work->'priority' END,
   'priorityProvenance',work->'priorityProvenance','required',coalesce(work->'required','true'::jsonb),
   'coveragePolicy',work->'coveragePolicy','bestEffortCoverage',coalesce(work->'required'='false'::jsonb,false) AND
    (coalesce(work->'coveragePolicy'='"best_effort"'::jsonb,false) OR coalesce(work->'bestEffortCoverage'='true'::jsonb,false)),
   'coveragePolicyOrder',CASE WHEN work->'required'='false'::jsonb AND
    (work->>'coveragePolicy'='best_effort' OR work->'bestEffortCoverage'='true'::jsonb) THEN coalesce(work->'coveragePolicyOrder','1'::jsonb) ELSE 'null'::jsonb END,
   'coveragePolicyProvenance',work->'coveragePolicyProvenance',
   'requiredQualifications',coalesce(work->'requiredQualifications','[]'::jsonb),'qualificationProvenance',work->'qualificationProvenance',
   'restrictions',coalesce(work->'restrictions','[]'::jsonb),'restrictionProvenance',work->'restrictionProvenance',
   'restrictedSlotIds',coalesce(work->'restrictedSlotIds','[]'::jsonb),'manualLock',work->'_datedManualLock'<>'null'::jsonb,
   'manualLockSlotId',work->'_datedManualLock','overlayWork',work->'_datedOverlayWork');
  expected_projection:=expected_projection||jsonb_build_array(jsonb_build_object('plan_work_id',identity_key,'work_id',work->'workId',
   'day_of_week',day,'service_date',d::text,'status',CASE WHEN is_open THEN 'open' ELSE 'assigned' END,'reason_code',CASE WHEN is_open THEN 'permitted_open' ELSE NULL END,
   'owner_slot_id',CASE WHEN is_open THEN NULL ELSE work->'ownerSlotId' END,'owner_person_id',person->'incumbentPersonId',
   'owner_digest',public.static_weekly_digest_jsonb(jsonb_build_object('planWorkId',identity_key,'slotId',CASE WHEN is_open THEN NULL ELSE work->'ownerSlotId' END,'personId',person->'incumbentPersonId','serviceDate',d::text)),
   'exact_owner_identity',public.static_weekly_digest_jsonb(jsonb_build_object('plan_work_id',identity_key,'service_date',d::text,
    'optimized_owner_slot_id',CASE WHEN is_open THEN NULL ELSE work->'ownerSlotId' END,'optimized_owner_person_id',person->'incumbentPersonId',
    'baseline_owner_slot_id',work->'originSlotId','baseline_owner_person_id',baseline_person->'incumbentPersonId')),
   'baseline_owner_slot_id',work->'originSlotId','baseline_owner_person_id',baseline_person->'incumbentPersonId','baseline_owner_name',baseline_person->'incumbentName',
   'original_actor_person_id',baseline_person->'incumbentPersonId','original_actor_name',baseline_person->'incumbentName',
   'optimized_owner_slot_id',CASE WHEN is_open THEN NULL ELSE work->'ownerSlotId' END,'optimized_owner_person_id',person->'incumbentPersonId','work_snapshot',normalized_work,
   'explanation',jsonb_build_object('contract','fixed_approved_pattern','hardConstraints','satisfied','reasons',CASE WHEN is_open THEN '[{"code":"permitted_open"}]'::jsonb ELSE '[]'::jsonb END)));
 END LOOP;

 IF EXISTS((SELECT value FROM jsonb_array_elements(expected_projection) EXCEPT ALL SELECT value FROM jsonb_array_elements(p_envelope->'assignments'))
  UNION ALL(SELECT value FROM jsonb_array_elements(p_envelope->'assignments') EXCEPT ALL SELECT value FROM jsonb_array_elements(expected_projection)))
  OR jsonb_array_length(expected_projection)=0 THEN RAISE EXCEPTION 'Dated exact independently derived relational rows differ';END IF;
 -- A work ID alone is not a physical parent. Keep actual stored links only
 -- for an exact original parent (owner substitution alone is allowed).
 -- Selected-day regrouping has NO fabricated one-to-one original assignment.
 FOR work IN SELECT value FROM jsonb_array_elements(effective_work) LOOP
  day:=(work->>'dayOfWeek')::integer;identity_key:=day::text||':'||(work->>'workId');original_assignment:=NULL;
  IF closing_enabled THEN
   IF day=operation_day THEN
    parent_id:=closing_result#>>ARRAY['selectedParentLinks',identity_key];
    SELECT value->'originalParent' INTO STRICT raw_parent FROM jsonb_array_elements(closing#>'{selected,parentReferences}')
     WHERE value->>'parentWorkId'=parent_id;
   ELSE
    SELECT c->>'parentWorkId' INTO STRICT parent_id FROM jsonb_array_elements(closing#>'{originalReceipt,parentChains}') c
     WHERE c->>'dayOfWeek'=day::text AND EXISTS(SELECT 1 FROM jsonb_array_elements(c->'segments') s WHERE s->'workId'=work->'workId');
    SELECT value INTO STRICT raw_parent FROM jsonb_array_elements(live_source#>'{version,assignments}')
     WHERE value->>'dayOfWeek'=day::text AND value->>'workId'=parent_id;
   END IF;
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(live_source#>'{version,assignments}') original
    WHERE original->>'dayOfWeek'=day::text AND original->>'workId'=parent_id AND original-'ownerSlotId'=raw_parent-'ownerSlotId') THEN
    SELECT assignment_id INTO STRICT original_assignment FROM public.weekly_schedule_slot_assignments
     WHERE version_id=current_source.version_id AND day_of_week=day AND work_id=parent_id;
   ELSIF day<>operation_day THEN RAISE EXCEPTION 'Dated closing unaffected original parent link differs';END IF;
  ELSIF EXISTS(SELECT 1 FROM jsonb_array_elements(effective_original) original
   WHERE original->'dayOfWeek'=work->'dayOfWeek' AND original->'workId'=work->'workId'
    AND original-'ownerSlotId'=work-'ownerSlotId') THEN
   -- An accepted event addition has an immutable command origin, not a
   -- fabricated stored baseline assignment; patches keep their actual parent.
   IF work->'_datedOverlayWork'='false'::jsonb THEN
    SELECT assignment_id INTO STRICT original_assignment FROM public.weekly_schedule_slot_assignments
     WHERE version_id=current_source.version_id AND day_of_week=day AND work_id=work->>'workId';
   END IF;
  ELSIF day<>operation_day THEN RAISE EXCEPTION 'Dated unaffected original parent link differs';END IF;
  assignment_links:=assignment_links||jsonb_build_object(identity_key,original_assignment);
 END LOOP;
 IF p_envelope->'adapter' IS DISTINCT FROM '{"schema":"custodial.approved-static-dated-adapter.v1","version":"approved-static-dated-v1"}'::jsonb
  OR p_envelope->>'service_date' IS DISTINCT FROM p_week::text OR p_envelope->>'week_start' IS DISTINCT FROM p_week::text
  OR p_envelope->>'week_end' IS DISTINCT FROM (p_week+6)::text
  OR p_envelope->>'compiler_version' IS DISTINCT FROM 'approved-static-dated-v1'
  OR p_envelope->'objective' IS DISTINCT FROM '{"contract":"FIXED_APPROVED_PATTERN_NOT_OPTIMALITY"}'::jsonb
  OR authority->>'schema' IS DISTINCT FROM 'custodial.approved-static-authority.v1'
  OR authority->>'effectiveDate' IS DISTINCT FROM p_week::text
  OR authority->'solverInvoked' IS DISTINCT FROM 'false'::jsonb OR authority->'optimized' IS DISTINCT FROM 'false'::jsonb
  OR authority ? 'optimizerResult'
  OR authority->>'baselineInputDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(baseline)
  OR authority->>'mappedBaselineInputDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(jsonb_set(source,'{exceptions}','[]'::jsonb))
  OR authority->>'derivedBaselineDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(CASE WHEN closing_enabled THEN closing->'originalDerivedInput' ELSE baseline END)
  OR authority->>'inputDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(source)
  OR authority->>'originalInputDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(authority->'originalWeekCompilerInput')
  OR p_envelope->>'authority_digest' IS DISTINCT FROM public.static_weekly_digest_jsonb(authority)
  OR p_envelope->>'database_projection_identity' IS DISTINCT FROM public.static_weekly_digest_jsonb(p_envelope-'database_projection_identity')
  OR authority->'weekDerivation' IS DISTINCT FROM jsonb_build_object(
   'schema','custodial.approved-static-dated-week-derivation.v1','operationDate',operation_date::text,
   'weekStart',p_week::text,'weekEnd',(p_week+6)::text,'originalSourceDigest',public.static_weekly_digest_jsonb(authority->'originalCompilerInput'),
   'originalWeekInputDigest',authority->'originalInputDigest','mappedWeekInputDigest',authority->'inputDigest')
  OR p_envelope->'semantic_snapshot' IS DISTINCT FROM jsonb_build_object(
   'schema','custodial.approved-static-dated-projection-snapshot.v1','sourcePublicationId',p_publication_id::text,
   'sourceVersionId',live_source#>>'{version,id}','serviceDate',operation_date::text,'weekStart',p_week::text,'weekEnd',(p_week+6)::text,
   'sourceDigest',public.static_weekly_digest_jsonb(authority->'originalCompilerInput'),
   'feasibilityDigest',p_envelope#>'{receipt,feasibilityDigest}','original_baseline_digest',authority->'baselineInputDigest',
   'applied_exceptions_digest',public.static_weekly_digest_jsonb(p_exceptions))
  OR p_envelope#>>'{receipt,schema}' IS DISTINCT FROM 'custodial.approved-static-feasibility-receipt.v1'
  OR p_envelope#>'{receipt,independentDerivations}' IS DISTINCT FROM '2'::jsonb
  OR p_envelope#>'{receipt,solverInvoked}' IS DISTINCT FROM 'false'::jsonb OR p_envelope#>'{receipt,optimized}' IS DISTINCT FROM 'false'::jsonb
  OR jsonb_typeof(p_envelope#>'{receipt,hardConstraintCount}') IS DISTINCT FROM 'number'
  OR (p_envelope#>>'{receipt,hardConstraintCount}')::numeric NOT BETWEEN jsonb_array_length(expected_projection) AND 100000
  OR (p_envelope#>>'{receipt,hardConstraintCount}')::numeric<>trunc((p_envelope#>>'{receipt,hardConstraintCount}')::numeric)
  OR p_envelope->'metrics' IS DISTINCT FROM jsonb_build_object('hardConstraints',p_envelope#>'{receipt,hardConstraintCount}','violations',0)
 THEN RAISE EXCEPTION 'Dated envelope identities or fixed semantics differ';END IF;
 RETURN jsonb_build_object('source_id',v_source_id,'projection_assignments',expected_projection,
  'assignment_links',assignment_links,'staffing_count',employee_count,'operation_date',operation_date,'version_id',current_source.version_id);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_assert_approved_recurring_shift_end_derivation(p_authority jsonb, p_original_source jsonb, p_current_source jsonb, p_owner_config jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare

 approved_receipt jsonb:=p_authority->'shiftEndDerivation';approved_ref jsonb;original_parent jsonb;mapped_parent jsonb;owner_mapping jsonb;
 actual_slot jsonb;actual_availability jsonb;current_person jsonb;actual_config jsonb;approved_date date;
 source jsonb:=p_authority->'compilerInput';
 effective jsonb:=jsonb_set(p_authority->'overlayCompilerInput','{exceptions}','[]'::jsonb);
 policy jsonb:=source#>'{version,shiftEndContinuityPolicy}';
 receipt jsonb:=p_authority#>'{shiftEndDerivation,derivation}';
 roster jsonb; boundaries jsonb; chain jsonb; parent jsonb; segment jsonb; work jsonb;
 person jsonb; owner jsonb; physical jsonb; key text; previous_end text; final_end text;
 day integer; matches integer; total numeric; seen text[]:='{}'; parent_seen text[]:='{}';
 minute_samples integer:=0; location_samples integer:=0; location_count integer; span integer;
 named jsonb; named_parent jsonb; named_chain jsonb; named_from jsonb; named_to jsonb; named_to_availability jsonb;
 named_parent_id text; named_key text; named_seen text[]:='{}';
begin

 perform public.static_weekly_assert_exact_object(approved_receipt,
  array['schema','algorithm','originalTemplateDigest','currentSourceDigest','mappedSourceDigest','ownerConfigDigest','parentReferences','derivation'],
  array['schema','algorithm','originalTemplateDigest','currentSourceDigest','mappedSourceDigest','ownerConfigDigest','parentReferences','derivation'],'approved mapped derivation');
 if approved_receipt->>'schema' is distinct from 'custodial.approved-mapped-shift-end-derivation.v1'
  or approved_receipt->>'algorithm' is distinct from 'dated-real-staff-directed-proximity-weighted-v1'
  or approved_receipt->>'originalTemplateDigest' is distinct from public.static_weekly_digest_jsonb(p_original_source)
  or approved_receipt->>'currentSourceDigest' is distinct from public.static_weekly_digest_jsonb(p_current_source)
  or approved_receipt->>'mappedSourceDigest' is distinct from public.static_weekly_digest_jsonb(source)
  or approved_receipt->>'ownerConfigDigest' is distinct from public.static_weekly_digest_jsonb(p_owner_config)
  or source-'version' is distinct from p_current_source-'version'
  or (source->'version')-'assignments' is distinct from (p_current_source->'version')-'assignments'
  or jsonb_typeof(approved_receipt->'parentReferences') is distinct from 'array'
  or jsonb_array_length(approved_receipt->'parentReferences')<>jsonb_array_length(source#>'{version,assignments}')
  or jsonb_array_length(approved_receipt->'parentReferences')<>jsonb_array_length(p_original_source#>'{version,assignments}')
  or (select count(distinct (r->>'dayOfWeek',r->>'parentWorkId')) from jsonb_array_elements(approved_receipt->'parentReferences') r)
   <>jsonb_array_length(approved_receipt->'parentReferences') then
  raise exception 'Approved mapped original/current Source lineage differs';end if;
 for approved_ref in select value from jsonb_array_elements(approved_receipt->'parentReferences') loop
  perform public.static_weekly_assert_exact_object(approved_ref,
   array['dayOfWeek','parentWorkId','originalParent','mappedParent','originalOwnerSlotId','mappedOwnerSlotId','currentPersonId'],
   array['dayOfWeek','parentWorkId','originalParent','mappedParent','originalOwnerSlotId','mappedOwnerSlotId','currentPersonId'],'approved mapped parent reference');
  select w into strict original_parent from jsonb_array_elements(p_original_source#>'{version,assignments}') w
   where w->'dayOfWeek'=approved_ref->'dayOfWeek' and w->'workId'=approved_ref->'parentWorkId';
  select w into strict mapped_parent from jsonb_array_elements(source#>'{version,assignments}') w
   where w->'dayOfWeek'=approved_ref->'dayOfWeek' and w->'workId'=approved_ref->'parentWorkId';
  select m into strict owner_mapping from jsonb_array_elements(p_authority#>'{mapping,slotMapping}') m where m->'patternSlotId'=original_parent->'ownerSlotId';
  select s into strict actual_slot from jsonb_array_elements(p_current_source->'slots') s where s->'id'=mapped_parent->'ownerSlotId';
  select a into strict actual_availability from jsonb_array_elements(p_current_source#>'{version,slotAvailability}') a
   where a->'slotId'=mapped_parent->'ownerSlotId' and a->'dayOfWeek'=mapped_parent->'dayOfWeek';
  approved_date:=(source->>'serviceDate')::date+mod((mapped_parent->>'dayOfWeek')::integer+6,7);
  select i into strict current_person from jsonb_array_elements(actual_slot->'incumbencies') i where
   (i->>'effectiveStart')::date<=approved_date and (i->>'effectiveEnd' is null or approved_date<(i->>'effectiveEnd')::date);
  select c.value into strict actual_config from jsonb_each(p_owner_config->'slots') c where c.value->'slotId'=actual_slot->'id';
  if approved_ref->'originalParent' is distinct from original_parent or approved_ref->'mappedParent' is distinct from mapped_parent
   or approved_ref->'originalOwnerSlotId' is distinct from original_parent->'ownerSlotId'
   or approved_ref->'mappedOwnerSlotId' is distinct from mapped_parent->'ownerSlotId'
   or mapped_parent is distinct from jsonb_set(original_parent,'{ownerSlotId}',owner_mapping->'actualSlotId')
   or mapped_parent->'originSlotId' is distinct from original_parent->'originSlotId'
   or owner_mapping->'actualSlotId' is distinct from mapped_parent->'ownerSlotId'
   or owner_mapping->'actualPersonId' is distinct from current_person->'personId'
   or approved_ref->'currentPersonId' is distinct from current_person->'personId'
   or coalesce(actual_slot->'contractorCapacity','false'::jsonb)<>'false'::jsonb
   or actual_availability->>'status' is distinct from 'working'
   or mapped_parent#>>'{window,start}'<actual_availability#>>'{shift,start}'
   or mapped_parent#>>'{window,end}'>actual_availability#>>'{shift,end}'
   or (mapped_parent#>>'{window,start}'='09:45' and mapped_parent#>'{window,end}' is distinct from actual_availability#>'{shift,end}')
   or not(coalesce(actual_config->'workDays','[]'::jsonb) @> jsonb_build_array(mapped_parent->'dayOfWeek'))
   or actual_availability->'shift' is distinct from jsonb_build_object(
    'start',coalesce(actual_config#>array['shiftByDay',mapped_parent->>'dayOfWeek'],actual_config->'shift')->0,
    'end',coalesce(actual_config#>array['shiftByDay',mapped_parent->>'dayOfWeek'],actual_config->'shift')->1)
   or actual_availability->'lunch' is distinct from jsonb_build_object(
    'start',coalesce(actual_config#>array['lunchByDay',mapped_parent->>'dayOfWeek'],actual_config->'lunch')->0,
    'end',coalesce(actual_config#>array['lunchByDay',mapped_parent->>'dayOfWeek'],actual_config->'lunch')->1)
   or not exists(select 1 from jsonb_each(p_owner_config->'slots') c where c.value->'slotId'=actual_slot->'id'
    and c.value->'personId'=current_person->'personId' and c.value->'vacancy' is distinct from 'true'::jsonb) then
   raise exception 'Approved mapped parent original/current position person or shift differs';end if;
 end loop;
 perform public.static_weekly_assert_exact_object(policy,
  array['schema','algorithm','normalPhaseStart','weights','provenance','policyDigest'],
  array['schema','algorithm','normalPhaseStart','weights','provenance','policyDigest','namedHandoffs'],'shift-end source policy');
 if policy ? 'namedHandoffs' then
  if jsonb_typeof(policy->'namedHandoffs') is distinct from 'array' then
   raise exception using errcode='23514',message='shift-end named handoffs must be one array';
  end if;
  if jsonb_array_length(policy->'namedHandoffs')>14 then
   raise exception using errcode='23514',message='shift-end named handoffs exceed the source bound';
  end if;
 end if;
 perform public.static_weekly_assert_exact_object(receipt,
  array['schema','algorithm','templateDigest','policyDigest','datedRosterDigest','derivedBaselineDigest','staffedDepartureByDay','parentChains','outputWorkDigest','continuity'],
  array['schema','algorithm','templateDigest','policyDigest','datedRosterDigest','derivedBaselineDigest','staffedDepartureByDay','parentChains','outputWorkDigest','continuity'],'shift-end derivation receipt');
 if policy->>'schema' is distinct from 'memphis-zoo.shift-end-continuity-policy.v1'
  or policy->>'algorithm' is distinct from 'dated-real-staff-directed-proximity-weighted-v1'
  or policy->>'normalPhaseStart' is distinct from '09:45'
  or coalesce(policy->>'provenance','') !~ '^owner-configuration-sha256:[a-f0-9]{64}$'
  or policy->>'policyDigest' is distinct from public.static_weekly_digest_jsonb(policy-'policyDigest')
  or receipt->>'schema' is distinct from 'memphis-zoo.shift-end-derivation.v1'
  or receipt->>'algorithm' is distinct from policy->>'algorithm'
  or receipt->>'policyDigest' is distinct from policy->>'policyDigest'
  or receipt->>'templateDigest' is distinct from public.static_weekly_digest_jsonb(source)
  or receipt->>'derivedBaselineDigest' is distinct from public.static_weekly_digest_jsonb(effective)
  or receipt->>'derivedBaselineDigest' is distinct from p_authority->>'derivedBaselineDigest'
  or source->'exceptions' is distinct from '[]'::jsonb
  or source#>'{version,shiftEndDerivationApplied}' is not null
  or effective#>>'{version,shiftEndDerivationApplied}' is distinct from policy->>'policyDigest'
  or source-'version' is distinct from effective-'version'
  or (source->'version')-'assignments' is distinct from (effective->'version')-'assignments'-'shiftEndDerivationApplied'
  or jsonb_typeof(policy->'weights') is distinct from 'object'
  or jsonb_typeof(source#>'{version,assignments}') is distinct from 'array'
  or jsonb_typeof(effective#>'{version,assignments}') is distinct from 'array'
  or jsonb_typeof(receipt->'parentChains') is distinct from 'array'
  or jsonb_array_length(source#>'{version,assignments}') not between 1 and 1024
  or jsonb_array_length(effective#>'{version,assignments}') not between 1 and 1024
  or jsonb_array_length(receipt->'parentChains')<>jsonb_array_length(source#>'{version,assignments}')
  or receipt->>'outputWorkDigest' is distinct from public.static_weekly_digest_jsonb(effective#>'{version,assignments}') then
  raise exception using errcode='23514',message='shift-end source, policy, derived baseline and receipt identities must be exact';
 end if;
 if exists(select 1 from jsonb_each(policy->'weights') w where jsonb_typeof(w.value)<>'number'
  or (w.value#>>'{}')::numeric<=0 or (w.value#>>'{}')::numeric>1000
  or (w.value#>>'{}')::numeric*2<>trunc((w.value#>>'{}')::numeric*2)) then
  raise exception using errcode='23514',message='shift-end weights require exact positive bounded half units';
 end if;
 -- Derive this roster from immutable availability plus dated incumbent ranges,
 -- never from exception-mutated projectionAvailability or a caller roster blob.
 with facts as (
  select a, s, (source->>'serviceDate')::date+
   mod((a->>'dayOfWeek')::int-extract(dow from (source->>'serviceDate')::date)::int+7,7) d
  from jsonb_array_elements(source#>'{version,slotAvailability}') a
  join jsonb_array_elements(source->'slots') s on s->>'id'=a->>'slotId'
  where coalesce(s->'contractorCapacity','false'::jsonb)='false'::jsonb
 ), dated as (
  select *, (select count(*) from jsonb_array_elements(s->'incumbencies') i
   where (i->>'effectiveStart')::date<=d and (i->>'effectiveEnd' is null or d<(i->>'effectiveEnd')::date)) n,
   (select i from jsonb_array_elements(s->'incumbencies') i
   where (i->>'effectiveStart')::date<=d and (i->>'effectiveEnd' is null or d<(i->>'effectiveEnd')::date) limit 1) incumbent
  from facts
 ) select coalesce(jsonb_agg(jsonb_build_object('serviceDate',d::text,'dayOfWeek',a->'dayOfWeek',
   'slotId',a->'slotId','personId',incumbent->'personId','vacant',n=0,'status',a->'status',
   'shift',a->'shift','lunch',a->'lunch') order by (a->>'dayOfWeek')::int,a->>'slotId'),'[]'::jsonb),
  count(*) filter(where n>1 or (n=0 and not coalesce((source#>'{version,vacancyCapableSlotIds}') ? (a->>'slotId'),false))
   or (n=0) is distinct from (a->>'status'='vacant_unfilled')
   or a->>'status' not in ('working','vacant_unfilled','departed_named_absent'))
 into roster,matches from dated;
 if matches<>0 or jsonb_array_length(roster)=0
  or (select count(*) from jsonb_array_elements(roster))<>(select count(distinct (r->>'dayOfWeek',r->>'slotId')) from jsonb_array_elements(roster) r)
  or receipt->>'datedRosterDigest' is distinct from public.static_weekly_digest_jsonb(roster) then
  raise exception using errcode='23514',message='shift-end receipt must bind one exact dated real roster';
 end if;
 select jsonb_object_agg(d::text,closing) into boundaries from (
  select (r->>'dayOfWeek')::int d,max(r#>>'{shift,end}') closing from jsonb_array_elements(roster) r
  where r->'vacant'='false'::jsonb and r->>'status'='working' group by 1
 ) endings;
 if boundaries is null or (select count(*) from jsonb_object_keys(boundaries))<>7
  or boundaries is distinct from receipt->'staffedDepartureByDay' then
  raise exception using errcode='23514',message='shift-end boundary requires real working incumbent on every day';
 end if;
 for chain in select value from jsonb_array_elements(receipt->'parentChains') loop
  perform public.static_weekly_assert_exact_object(chain,
   array['dayOfWeek','parentWorkId','physicalIdentityDigest','workloadBefore','workloadAfter','segments'],
   array['dayOfWeek','parentWorkId','physicalIdentityDigest','workloadBefore','workloadAfter','segments'],'shift-end parent chain');
  day:=(chain->>'dayOfWeek')::int; key:=day::text||':'||(chain->>'parentWorkId');
  select count(*) into matches from jsonb_array_elements(source#>'{version,assignments}') w
   where w->>'dayOfWeek'=day::text and w->>'workId'=chain->>'parentWorkId';
  if matches<>1 or key=any(parent_seen) then raise exception 'shift-end parent must exist exactly once'; end if;
  parent_seen:=array_append(parent_seen,key);
  select w into parent from jsonb_array_elements(source#>'{version,assignments}') w
   where w->>'dayOfWeek'=day::text and w->>'workId'=chain->>'parentWorkId';
  select jsonb_object_agg(k,coalesce(parent->k,'null'::jsonb)) into physical from unnest(array[
   'locationId','locationCodeSnapshot','locationNameSnapshot','includedLocations','serviceMode','requiredQualifications',
   'restrictedSlotIds','restrictions','qualificationProvenance','restrictionProvenance']) k;
  if chain->>'physicalIdentityDigest' is distinct from public.static_weekly_digest_jsonb(physical)
   or chain->'workloadBefore' is distinct from parent->'serviceEffortMinutes'
   or chain->'workloadAfter' is distinct from parent->'serviceEffortMinutes'
   or jsonb_typeof(chain->'segments') is distinct from 'array' or jsonb_array_length(chain->'segments')<1
   or position(':handoff:' in parent->>'workId')>0 or position(':open:' in parent->>'workId')>0 then
   raise exception 'shift-end chain must retain exact immutable parent identity and workload';
  end if;
  previous_end:=parent#>>'{window,start}';final_end:=boundaries->>day::text;total:=0;
  if previous_end='09:45' then
   select r into owner from jsonb_array_elements(roster) r where r->>'slotId'=parent->>'ownerSlotId' and r->>'dayOfWeek'=day::text;
   if not found or parent#>>'{window,end}' is distinct from owner#>>'{shift,end}'
    or parent->'originSlotId' is distinct from (select r#>'{originalParent,originSlotId}' from jsonb_array_elements(approved_receipt->'parentReferences') r where r->'dayOfWeek'=parent->'dayOfWeek' and r->'parentWorkId'=parent->'workId')
    or not ((policy->'weights') ? (parent->>'locationCodeSnapshot')) then
    raise exception 'immutable normal parent must retain full owning position shift and weight'; end if;
  end if;
  for segment in select value from jsonb_array_elements(chain->'segments') loop
   perform public.static_weekly_assert_exact_object(segment,
    array['workId','ownerSlotId','window','serviceEffortMinutes','kind'],
    array['workId','ownerSlotId','window','serviceEffortMinutes','kind'],'shift-end segment');
   key:=day::text||':'||(segment->>'workId');
   select count(*) into matches from jsonb_array_elements(effective#>'{version,assignments}') w
    where w->>'dayOfWeek'=day::text and w->>'workId'=segment->>'workId';
   if matches<>1 or key=any(seen) then raise exception 'derived segment must occur exactly once'; end if;
   seen:=array_append(seen,key);
   select w into work from jsonb_array_elements(effective#>'{version,assignments}') w
    where w->>'dayOfWeek'=day::text and w->>'workId'=segment->>'workId';
   perform public.static_weekly_v3_assert_window(segment->'window','shift-end segment');
   if segment#>>'{window,start}' is distinct from previous_end
    or segment->'window' is distinct from work->'window'
    or segment->'ownerSlotId' is distinct from work->'ownerSlotId'
    or segment->'serviceEffortMinutes' is distinct from work->'serviceEffortMinutes'
    or jsonb_typeof(segment->'serviceEffortMinutes') is distinct from 'number'
    or (segment->>'serviceEffortMinutes')::numeric<=0
    or (segment->>'serviceEffortMinutes')::numeric<>trunc((segment->>'serviceEffortMinutes')::numeric)
    or (work-'workId'-'ownerSlotId'-'originSlotId'-'window'-'serviceEffortMinutes'-'serviceEffortProvenance')
       is distinct from (parent-'workId'-'ownerSlotId'-'originSlotId'-'window'-'serviceEffortMinutes'-'serviceEffortProvenance')
    or work->'originSlotId' is distinct from (case when work->'workId'=parent->'workId' then parent->'originSlotId' else work->'ownerSlotId' end)
    or work->>'serviceEffortProvenance' is distinct from ((parent->>'serviceEffortProvenance')||
       case when jsonb_array_length(chain->'segments')>1 then ';shift-split-preserves-budget' else '' end) then
    raise exception 'derived segment changed immutable work, exact workload or contiguous window';
   end if;
   previous_end:=segment#>>'{window,end}';total:=total+(segment->>'serviceEffortMinutes')::numeric;
   if parent#>>'{window,start}'<>'09:45' then
    if work is distinct from parent or segment->>'kind' is distinct from 'baseline' then raise exception 'non-closing work must be unchanged'; end if;
   else
    select r into person from jsonb_array_elements(roster) r where r->>'slotId'=work->>'ownerSlotId' and r->>'dayOfWeek'=day::text;
    select a into owner from jsonb_array_elements(source#>'{version,slotAvailability}') a where a->>'slotId'=work->>'ownerSlotId' and a->>'dayOfWeek'=day::text;
    if person is null or owner is null or work#>>'{window,start}'<person#>>'{shift,start}'
     or previous_end>person#>>'{shift,end}' or previous_end>final_end
     or (work->'restrictedSlotIds') ? (work->>'ownerSlotId')
     or not ((owner->'qualifications') @> (work->'requiredQualifications'))
     or exists(select 1 from jsonb_array_elements(work->'includedLocations') loc where (owner->'restrictions') ? (loc->>'locationId')) then
     raise exception 'derived normal responsibility has off-duty or ineligible position'; end if;
    if segment->>'kind'='baseline' then
     if work->'workId' is distinct from parent->'workId' or work->'ownerSlotId' is distinct from parent->'ownerSlotId' then raise exception 'baseline segment identity changed'; end if;
    elsif segment->>'kind' in ('open','handoff') then
     if work->>'workId' is distinct from (parent->>'workId')||':'||(segment->>'kind')||':'||(work#>>'{window,start}')||':'||(work->>'ownerSlotId')
      or (segment->>'kind'='open') is distinct from (person->'vacant'='true'::jsonb)
      or (segment->>'kind'='handoff' and (person->>'status'<>'working' or person->>'personId' is null))
      or (person#>>'{lunch,start}'<=work#>>'{window,start}' and work#>>'{window,start}'<person#>>'{lunch,end}') then
      raise exception 'physical handoff or explicit OPEN segment identity invalid'; end if;
    else raise exception 'unknown derived segment kind'; end if;
   end if;
  end loop;
  if total<>(parent->>'serviceEffortMinutes')::numeric
   or (parent#>>'{window,start}'='09:45' and previous_end is distinct from final_end) then
   raise exception 'parent chain must conserve workload and reach final staffed boundary'; end if;
 end loop;
 if cardinality(seen)<>jsonb_array_length(effective#>'{version,assignments}') then raise exception 'unaccounted derived work'; end if;

 -- A policy string alone never authorizes a new recipient. Every named
 -- handoff must occur exactly once in the already-validated immutable
 -- parent chain, at the departing source worker's actual shift end, with a
 -- real eligible/on-duty recipient and all required directed edges. The
 -- accepted six-key historical policy follows this block without change.
 for named in select value from jsonb_array_elements(coalesce(policy->'namedHandoffs','[]'::jsonb)) loop
  perform public.static_weekly_assert_exact_object(named,
   array['dayOfWeek','locationCode','at','fromSlotId','toSlotId','source'],
   array['dayOfWeek','locationCode','at','fromSlotId','toSlotId','source'],'shift-end named handoff');
  if (jsonb_typeof(named->'dayOfWeek')='number'
    and named->>'dayOfWeek' ~ '^[0-6]$'
    and jsonb_typeof(named->'locationCode')='string'
    and (policy->'weights') ? (named->>'locationCode')
    and jsonb_typeof(named->'at')='string'
    and named->>'at' ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
    and jsonb_typeof(named->'fromSlotId')='string'
    and named->>'fromSlotId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    and jsonb_typeof(named->'toSlotId')='string'
    and named->>'toSlotId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    and named->>'fromSlotId'<>named->>'toSlotId'
    and jsonb_typeof(named->'source')='string'
    and length(named->>'source') between 10 and 300) is distinct from true then
   raise exception using errcode='23514',message='shift-end named handoff typed source identity invalid';
  end if;
  named_key:=(named->>'dayOfWeek')||':'||(named->>'locationCode')||':'||(named->>'at');
  if named_key=any(named_seen) then
   raise exception using errcode='23514',message='shift-end named handoff duplicated';
  end if;
  named_seen:=array_append(named_seen,named_key);
  select count(*),max(w->>'workId') into matches,named_parent_id
   from jsonb_array_elements(source#>'{version,assignments}') w
   where w->>'dayOfWeek'=named->>'dayOfWeek'
    and w->>'locationCodeSnapshot'=named->>'locationCode'
    and w#>>'{window,start}'='09:45';
  if matches<>1 then
   raise exception using errcode='23514',message='shift-end named parent source is not unique';
  end if;
  select w into named_parent from jsonb_array_elements(source#>'{version,assignments}') w
   where w->>'dayOfWeek'=named->>'dayOfWeek' and w->>'workId'=named_parent_id;
  select c into named_chain from jsonb_array_elements(receipt->'parentChains') c
   where c->>'dayOfWeek'=named->>'dayOfWeek' and c->>'parentWorkId'=named_parent_id;
  if named_chain is null then
   raise exception using errcode='23514',message='shift-end named parent chain absent';
  end if;
  select count(*) into matches
   from jsonb_array_elements(named_chain->'segments') with ordinality as s(segment,ordinal)
   where s.ordinal>1 and s.segment->>'kind'='handoff'
    and s.segment#>>'{window,start}'=named->>'at'
    and s.segment->>'ownerSlotId'=named->>'toSlotId'
    and (named_chain->'segments'->(s.ordinal::integer-2))->>'ownerSlotId'=named->>'fromSlotId'
    and (named_chain->'segments'->(s.ordinal::integer-2))#>>'{window,end}'=named->>'at';
  if matches<>1 then
   raise exception using errcode='23514',message='shift-end named handoff does not match exactly one derived segment';
  end if;
  select r into named_from from jsonb_array_elements(roster) r
   where r->>'dayOfWeek'=named->>'dayOfWeek' and r->>'slotId'=named->>'fromSlotId';
  select r into named_to from jsonb_array_elements(roster) r
   where r->>'dayOfWeek'=named->>'dayOfWeek' and r->>'slotId'=named->>'toSlotId';
  select a into named_to_availability from jsonb_array_elements(source#>'{version,slotAvailability}') a
   where a->>'dayOfWeek'=named->>'dayOfWeek' and a->>'slotId'=named->>'toSlotId';
  if (named_from->>'status'='working' and named_from->>'personId' is not null
    and named_from#>>'{shift,end}'=named->>'at'
    and named_to->>'status'='working' and named_to->>'personId' is not null
    and named_to#>>'{shift,start}'<=named->>'at'
    and named->>'at'<named_to#>>'{shift,end}'
    and not (named_to#>>'{lunch,start}'<=named->>'at' and named->>'at'<named_to#>>'{lunch,end}')
    and (named_to_availability->'qualifications') @> (named_parent->'requiredQualifications')
    and not ((named_parent->'restrictedSlotIds') ? (named->>'toSlotId'))
    and not exists(select 1 from jsonb_array_elements(case
      when jsonb_array_length(named_parent->'includedLocations')>0 then named_parent->'includedLocations'
      else jsonb_build_array(jsonb_build_object('locationId',named_parent->'locationId')) end) target
      where (named_to_availability->'restrictions') ? (target->>'locationId'))
  ) is distinct from true then
   raise exception using errcode='23514',message='shift-end named handoff source or recipient is not current and eligible';
  end if;
  -- The JS source-derived selector requires a verified directed edge from
  -- at least one exact current-source target-position anchor to every member.
  -- Normal owned members take precedence; only a position owning no normal
  -- row may use its explicit accepted route anchor.
  with anchors as (
   select l->>'locationId' id from jsonb_array_elements(source#>'{version,assignments}') w
    cross join lateral jsonb_array_elements(case when jsonb_array_length(w->'includedLocations')>0
      then w->'includedLocations' else jsonb_build_array(jsonb_build_object('locationId',w->'locationId')) end) l
    where w->>'dayOfWeek'=named->>'dayOfWeek' and w->>'ownerSlotId'=named->>'toSlotId'
     and w#>>'{window,start}'='09:45'
   union all
   select named_to_availability->>'acceptedRouteAnchorLocationId'
    where not exists(select 1 from jsonb_array_elements(source#>'{version,assignments}') w
      where w->>'dayOfWeek'=named->>'dayOfWeek' and w->>'ownerSlotId'=named->>'toSlotId'
       and w#>>'{window,start}'='09:45')
  ), targets as (
   select l->>'locationId' id from jsonb_array_elements(case
     when jsonb_array_length(named_parent->'includedLocations')>0 then named_parent->'includedLocations'
     else jsonb_build_array(jsonb_build_object('locationId',named_parent->'locationId')) end) l
  )
  select count(*) into matches from targets target where not exists(
   select 1 from anchors anchor where anchor.id is not null and
    (anchor.id=target.id or exists(select 1 from jsonb_array_elements(source->'proximity') edge
      where edge->>'fromLocationId'=anchor.id and edge->>'toLocationId'=target.id
       and edge->'verified'='true'::jsonb and jsonb_typeof(edge->'minutes')='number'
       and (edge->>'minutes')::numeric>=0 and (edge->>'minutes')::numeric=trunc((edge->>'minutes')::numeric)
       and nullif(edge->>'provenance','') is not null)));
  if matches<>0 then
   raise exception using errcode='23514',message='shift-end named handoff lacks verified directed source proximity';
  end if;
 end loop;
 -- OPEN may retain a stable baseline position, never a fictitious execution
 -- owner/person. Existing optimizer/document validators retain their checks.
 if exists(select 1 from jsonb_array_elements(p_authority#>'{optimizerResult,assignments}') a
  where a->>'status' in ('OPEN','REVIEW') and (a->>'slotId' is not null or a->>'personId' is not null)) then
  raise exception 'OPEN derived work may not invent execution identity'; end if;
 for day in 0..6 loop
  select count(*),count(distinct id) into matches,location_count from (
   select l->>'locationId' id from jsonb_array_elements(source#>'{version,assignments}') w
   cross join lateral jsonb_array_elements(case when jsonb_array_length(w->'includedLocations')>0 then w->'includedLocations'
     else jsonb_build_array(jsonb_build_object('locationId',w->'locationId')) end) l
   where w->>'dayOfWeek'=day::text and w#>>'{window,start}'='09:45'
  ) locations;
  if matches<>location_count then raise exception 'immutable normal template contains duplicate physical ownership'; end if;
  span:=(extract(epoch from (boundaries->>day::text)::time)/60)::int-585;
  if span<=0 then raise exception 'invalid staffed operating span'; end if;
  minute_samples:=minute_samples+span;location_samples:=location_samples+span*location_count;
 end loop;
 if receipt->'continuity' is distinct from jsonb_build_object('minuteSamples',minute_samples,'locationMinuteChecks',location_samples,
  'coverageGaps',0,'duplicateLocations',0,'staffedDepartureByDay',boundaries,
  'scope','dated real-staff handoffs and explicit vacancy OPEN responsibility until final staffed departure; lunch overlay checked separately') then
  raise exception 'shift-end continuity counters must be independently recomputed'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_assert_authority_attestation(p_attestation jsonb, p_scope text, p_payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_key public.static_weekly_authority_attestation_keys%rowtype; v_signature text; v_expected text;
begin
  perform public.static_weekly_assert_exact_object(p_attestation,array['schema','key_id','scope','payload_digest','signature'],array['schema','key_id','scope','payload_digest','signature'],'authority attestation');
  if p_attestation->>'schema' is distinct from 'memphis-zoo.static-weekly-authority-attestation.v2' or p_attestation->>'scope' is distinct from p_scope or p_attestation->>'payload_digest' is distinct from public.static_weekly_digest_jsonb(p_payload) or jsonb_typeof(p_attestation->'key_id') is distinct from 'string' or jsonb_typeof(p_attestation->'signature') is distinct from 'string' then raise exception using errcode='23514',message='complete versioned authority attestation is required'; end if;
  v_signature:=p_attestation->>'signature';
  if v_signature !~ '^[0-9a-f]{64}$' then raise exception using errcode='23514',message='authority attestation signature must be canonical lower-case fixed-length hex'; end if;
  select * into v_key from public.static_weekly_authority_attestation_keys where key_id=p_attestation->>'key_id' and key_state in ('active','overlap') and activates_at<=statement_timestamp() and (verify_not_after is null or verify_not_after>statement_timestamp()) for share;
  if not found then raise exception using errcode='23514',message='authority attestation key is unknown, expired, or revoked'; end if;
  v_expected:=public.static_weekly_v3_hmac(v_key.secret_material,p_scope,p_payload);
  if not public.static_weekly_v3_constant_time_equal(decode(v_signature,'hex'),decode(v_expected,'hex')) then raise exception using errcode='23514',message='authority attestation does not bind the canonical semantic payload'; end if;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_assert_coverall_link_basis(p_binding jsonb, p_source uuid DEFAULT NULL::uuid, p_digest text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a record;src jsonb;source_row record;doc jsonb;projection record;day date;revision bigint;
begin
 perform public.static_weekly_v3_assert_control_plane();
 if not exists(select 1 from custodial_dr.restore_control where singleton and mutations_paused is false and state in('READY','COMPLETE')) then
  raise exception using errcode='55000',message='Canonical CoverAll authority is unavailable during restore';end if;
 perform public.static_weekly_assert_exact_object(p_binding,
  array['schema','week_start','service_date','capacity_id','publication_id','projection_id','authority_revision','replay_digest','lunch_document_identity','document_digest'],
  array['schema','week_start','service_date','capacity_id','publication_id','projection_id','authority_revision','replay_digest','lunch_document_identity','document_digest'],'canonical CoverAll binding');
 if (p_binding->>'schema'='custodial.coverall-canonical-binding.v1'
  and p_binding->>'service_date'~'^\d{4}-\d{2}-\d{2}$' and p_binding->>'week_start'~'^\d{4}-\d{2}-\d{2}$'
  and p_binding->>'capacity_id'~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$'
  and p_binding->>'publication_id'~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$'
  and p_binding->>'projection_id'~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$'
  and jsonb_typeof(p_binding->'authority_revision')='number' and p_binding->>'authority_revision'~'^(0|[1-9][0-9]*)$'
  and p_binding->>'replay_digest'~'^[a-f0-9]{64}$' and p_binding->>'lunch_document_identity'~'^[a-f0-9]{64}$'
  and p_binding->>'document_digest'~'^[a-f0-9]{64}$') is not true then
  raise exception using errcode='22023',message='Exact canonical CoverAll binding required';end if;
 day:=(p_binding->>'service_date')::date;
 if not isfinite(day) or day-(extract(isodow from day)::integer-1)<>(p_binding->>'week_start')::date then
  raise exception using errcode='22023',message='Exact canonical CoverAll week/date required';end if;
 select current_revision into strict revision from public.static_weekly_schedule_control where singleton;
 select * into a from public.static_weekly_v6_schedule_authority_state(day);
 select * into projection from public.weekly_schedule_compiled_projections where projection_id=(p_binding->>'projection_id')::uuid;
 if a.governed is not true or a.projection_status is distinct from 'current'
  or a.projection_id::text is distinct from p_binding->>'projection_id'
  or a.publication_id::text is distinct from p_binding->>'publication_id'
  or revision is distinct from (p_binding->>'authority_revision')::bigint
  or projection.replay_digest is distinct from p_binding->>'replay_digest' then
  raise exception using errcode='40001',message='Canonical CoverAll schedule changed';end if;
 select s.* into source_row from public.weekly_schedule_versions v
  join public.static_weekly_authority_source_documents s on s.source_id=v.authority_source_id
  where v.version_id=a.version_id;
 if source_row.source_id is null or source_row.active is not true or source_row.retired_at is not null
  or source_row.source_digest is distinct from public.static_weekly_digest_jsonb(source_row.canonical_source)
  or (p_source is not null and source_row.source_id is distinct from p_source)
  or (p_digest is not null and source_row.source_digest is distinct from p_digest) then
  raise exception using errcode='40001',message='Canonical CoverAll source changed';end if;
 doc:=public.static_weekly_v8_read_lunch_document(day);
 if doc->>'persistence_status' is distinct from 'PERSISTED'
  or doc->>'projection_id' is distinct from p_binding->>'projection_id'
  or doc->>'document_identity' is distinct from p_binding->>'lunch_document_identity' then
  raise exception using errcode='40001',message='Canonical CoverAll lunch changed';end if;
 src:=public.static_weekly_v3_read_publication_source(a.publication_id,day);
 if not exists(select 1 from jsonb_array_elements(src#>'{compiler_input,slots}') s
   where s->>'id'=p_binding->>'capacity_id' and s->'contractorCapacity'='true'::jsonb)
  or not exists(select 1 from jsonb_array_elements(src->'exceptions') e
   where e->>'type'='cover_all' and e->>'serviceDate'=day::text
    and e#>>'{payload,availability,slotId}'=p_binding->>'capacity_id') then
  raise exception using errcode='40001',message='Canonical CoverAll capacity is not accepted for this date';end if;
 return jsonb_build_object('source_id',source_row.source_id,'source_digest',source_row.source_digest);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_assert_document_attested(p_document jsonb, p_effective_start date, p_require_publishable boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_legacy jsonb;
begin
  perform public.static_weekly_assert_exact_object(p_document,
    array['adapter','authority','receipt','slot_availability','assignments','objective_inputs','validation','semantic_snapshot','attestation'],
    array['adapter','authority','receipt','slot_availability','assignments','objective_inputs','validation','semantic_snapshot','attestation'],'attested adapter document');
  perform public.static_weekly_v6_assert_document_attestation(p_document);
  perform public.static_weekly_assert_exact_object(p_document->'semantic_snapshot',
    array['schema','recurring_source_digest','relational_slot_availability_digest','relational_assignments_digest']||case when p_document#>>'{adapter,schema}'='memphis-zoo.static-weekly-database-adapter.v2' then array['derived_baseline_digest','shift_end_derivation_digest'] else '{}'::text[] end,
    array['schema','recurring_source_digest','relational_slot_availability_digest','relational_assignments_digest']||case when p_document#>>'{adapter,schema}'='memphis-zoo.static-weekly-database-adapter.v2' then array['derived_baseline_digest','shift_end_derivation_digest'] else '{}'::text[] end,'recurring semantic snapshot');
  if p_document#>>'{semantic_snapshot,schema}' is distinct from (case p_document#>>'{adapter,schema}' when 'memphis-zoo.static-weekly-database-adapter.v2' then 'memphis-zoo.static-weekly-recurring-semantic-snapshot.v3' else 'memphis-zoo.static-weekly-recurring-semantic-snapshot.v2' end)
    or p_document#>>'{semantic_snapshot,recurring_source_digest}' is distinct from public.static_weekly_digest_jsonb(p_document#>'{authority,compilerInput}')
    or p_document#>>'{semantic_snapshot,relational_slot_availability_digest}' is distinct from public.static_weekly_digest_jsonb(p_document->'slot_availability')
    or p_document#>>'{semantic_snapshot,relational_assignments_digest}' is distinct from public.static_weekly_digest_jsonb(p_document->'assignments') then
    raise exception using errcode='23514',message='attested recurring semantic snapshot and relational materialization must be exact';
  end if;

  if p_document#>>'{adapter,schema}'='memphis-zoo.static-weekly-database-adapter.v2' and (
   p_document#>'{semantic_snapshot,derived_baseline_digest}' is distinct from coalesce(p_document#>'{authority,derivedBaselineDigest}',p_document#>'{authority,baselineInputDigest}')
   or p_document#>'{semantic_snapshot,shift_end_derivation_digest}' is distinct from to_jsonb(public.static_weekly_digest_jsonb(coalesce(p_document#>'{authority,shiftEndDerivation}','null'::jsonb)))) then
   raise exception 'recurring snapshot does not bind exact derived baseline'; end if;
  v_legacy:=p_document-'semantic_snapshot'-'attestation';
  v_legacy:=jsonb_set(v_legacy,'{validation,database_document_identity}',to_jsonb(public.static_weekly_document_identity(v_legacy)),true);
  perform public.static_weekly_assert_document(v_legacy,p_effective_start,p_require_publishable);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_assert_exception_payload(p_exception_type text, p_service_date date, p_starts_at time without time zone, p_ends_at time without time zone, p_base_version_id uuid, p_publication_id uuid, p_payload jsonb, p_reverses_exception_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_slot text; v_lock jsonb; v_patch jsonb; v_add jsonb; v_ids text[]; v_effort numeric;
begin
  if jsonb_typeof(p_payload) is distinct from 'object' then raise exception using errcode='23514',message='exception payload must be an exact JSON object'; end if;
  if exists(select 1 from public.weekly_schedule_exception_commands e where e.publication_id=p_publication_id and e.base_version_id=p_base_version_id and e.service_date=p_service_date and e.exception_type=p_exception_type and e.payload_digest=public.static_weekly_digest_jsonb(p_payload) and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id)) then
    raise exception using errcode='23514',message='duplicate semantic exception command is already effective';
  end if;
  if p_exception_type in ('pto','daily_absence') then
    perform public.static_weekly_assert_exact_object(p_payload,array['slotId'],array['slotId'],p_exception_type||' payload'); perform public.static_weekly_v3_assert_uuid(p_payload->'slotId',p_exception_type||' slotId'); v_slot:=p_payload->>'slotId';
    if p_starts_at is not null or p_ends_at is not null or not public.static_weekly_exception_slot_exists(p_base_version_id,p_service_date,v_slot,true)
      or exists(select 1 from public.weekly_schedule_exception_commands e where e.publication_id=p_publication_id and e.service_date=p_service_date and e.exception_type in ('pto','daily_absence','partial_absence','lunch') and e.payload_json->>'slotId'=v_slot and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id)) then
      raise exception using errcode='23514',message='full-day absence must target one currently working slot without conflict or no-op';
    end if;
  elsif p_exception_type in ('partial_absence','lunch') then
    if p_exception_type='lunch' and exists(select 1 from public.weekly_schedule_exception_commands e
      where e.publication_id=p_publication_id and e.base_version_id=p_base_version_id and e.service_date=p_service_date
       and e.exception_type='cover_all' and e.payload_json#>>'{availability,slotId}'=p_payload->>'slotId'
       and e.payload_json#>>'{availability,breakChoice}'='NONE'
       and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id)) then
      raise exception using errcode='23514',message='Explicit no-break conflicts with a lunch; reverse and replace the dated engagement';end if;
    perform public.static_weekly_assert_exact_object(p_payload,array['slotId'],array['slotId'],p_exception_type||' payload'); perform public.static_weekly_v3_assert_uuid(p_payload->'slotId',p_exception_type||' slotId'); v_slot:=p_payload->>'slotId';
    if p_starts_at is null or p_ends_at is null or not (
      public.static_weekly_exception_slot_exists(p_base_version_id,p_service_date,v_slot,true)
      or (p_exception_type='lunch' and p_ends_at>p_starts_at
        and public.static_weekly_exception_slot_exists(p_base_version_id,p_service_date,v_slot,false)
        and exists(select 1 from public.weekly_schedule_versions v
          cross join lateral jsonb_array_elements(v.draft_document#>'{authority,compilerInput,slots}') slot
          where v.version_id=p_base_version_id and slot->>'id'=v_slot and slot->'contractorCapacity'='true'::jsonb)
        and exists(select 1 from public.weekly_schedule_exception_commands capacity
          where capacity.base_version_id=p_base_version_id and capacity.publication_id=p_publication_id
            and capacity.service_date=p_service_date and capacity.exception_type='cover_all'
            and capacity.payload_json#>>'{availability,slotId}'=v_slot
            and (capacity.payload_json#>>'{availability,shift,start}')::time<=p_starts_at
            and p_ends_at<=(capacity.payload_json#>>'{availability,shift,end}')::time
            and not exists(select 1 from public.weekly_schedule_exception_commands reversal
              where reversal.reverses_exception_id=capacity.exception_id))))
      or exists(select 1 from public.weekly_schedule_exception_commands e where e.publication_id=p_publication_id and e.service_date=p_service_date and e.exception_type in ('pto','daily_absence') and e.payload_json->>'slotId'=v_slot and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id))
      or exists(select 1 from public.weekly_schedule_exception_commands e where e.publication_id=p_publication_id and e.service_date=p_service_date and e.exception_type in ('partial_absence','lunch') and e.payload_json->>'slotId'=v_slot and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id) and p_starts_at<e.ends_at and e.starts_at<p_ends_at) then
      raise exception using errcode='23514',message='partial absence or lunch must target one working slot with a nonoverlapping effective window';
    end if;
  elsif p_exception_type='shift_override' then
    perform public.static_weekly_assert_exact_object(p_payload,array['slotId','status','shift'],array['slotId','status','shift'],'shift override payload'); perform public.static_weekly_v3_assert_uuid(p_payload->'slotId','shift override slotId'); perform public.static_weekly_v3_assert_window(p_payload->'shift','shift override shift'); v_slot:=p_payload->>'slotId';
    if p_starts_at is not null or p_ends_at is not null or p_payload->>'status' not in ('working','absent','unavailable') or not public.static_weekly_exception_slot_exists(p_base_version_id,p_service_date,v_slot,false)
      or exists(select 1 from public.weekly_schedule_exception_commands e where e.publication_id=p_publication_id and e.service_date=p_service_date and e.exception_type='shift_override' and e.payload_json->>'slotId'=v_slot and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id)) then raise exception using errcode='23514',message='shift override requires one extant slot and one nonduplicate exact replacement'; end if;
  elsif p_exception_type='cover_all' then
    perform public.static_weekly_assert_exact_object(p_payload,array['availability'],array['availability'],'coverall payload');
    perform public.static_weekly_assert_exact_object(p_payload->'availability',array['slotId','shift','productiveCapacityProvenance','maxServiceEffortMinutes','maxServiceEffortProvenance','qualifications','qualificationProvenance','restrictions','restrictionProvenance','acceptedRouteAnchorLocationId','acceptedRouteProvenance'],array['slotId','shift','productiveCapacityProvenance','maxServiceEffortMinutes','maxServiceEffortProvenance','qualifications','qualificationProvenance','restrictions','restrictionProvenance','acceptedRouteAnchorLocationId','acceptedRouteProvenance','breakChoice'],'coverall availability');
    if p_payload->'availability' ? 'breakChoice' then
      if p_payload#>'{availability,breakChoice}' is distinct from '"NONE"'::jsonb
       or not exists(select 1 from public.weekly_schedule_versions v
        cross join lateral jsonb_array_elements(v.draft_document#>'{authority,compilerInput,slots}') s
        where v.version_id=p_base_version_id and s->>'id'=p_payload#>>'{availability,slotId}'
         and s->>'kind'='CONTRACTOR_CAPACITY' and public.static_weekly_capacity_registered(s)) then
        raise exception using errcode='23514',message='Explicit no-break requires source-bound registered nonemployee capacity';
      end if;
    end if;
    perform public.static_weekly_v3_assert_uuid(p_payload#>'{availability,slotId}','coverall slotId'); perform public.static_weekly_v3_assert_window(p_payload#>'{availability,shift}','coverall shift'); perform public.static_weekly_v3_assert_uuid(p_payload#>'{availability,acceptedRouteAnchorLocationId}','coverall route anchor');
    foreach v_slot in array array['productiveCapacityProvenance','maxServiceEffortProvenance','qualificationProvenance','restrictionProvenance','acceptedRouteProvenance'] loop perform public.static_weekly_v3_assert_text(p_payload#>array['availability',v_slot],'coverall '||v_slot); end loop;
    perform public.static_weekly_v3_assert_string_array(p_payload#>'{availability,qualifications}','coverall qualifications'); perform public.static_weekly_v3_assert_string_array(p_payload#>'{availability,restrictions}','coverall restrictions');
    if jsonb_typeof(p_payload#>'{availability,maxServiceEffortMinutes}') is distinct from 'number' then raise exception using errcode='23514',message='coverall maximum effort must be a JSON integer'; end if; v_effort:=(p_payload#>>'{availability,maxServiceEffortMinutes}')::numeric;
    if v_effort<>trunc(v_effort) or v_effort<1 or v_effort>1440 or p_starts_at is not null or p_ends_at is not null or not public.static_weekly_exception_slot_exists(p_base_version_id,p_service_date,p_payload#>>'{availability,slotId}',false)
      or exists(select 1 from public.weekly_schedule_exception_commands e where e.publication_id=p_publication_id and e.service_date=p_service_date and e.exception_type='cover_all' and e.payload_json#>>'{availability,slotId}'=p_payload#>>'{availability,slotId}' and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id)) then raise exception using errcode='23514',message='coverall requires one extant slot and one bounded nonduplicate availability replacement'; end if;
  elsif p_exception_type in ('nine_forty_five_rebalance','manager_correction') then
    perform public.static_weekly_assert_exact_object(p_payload,array['locks'],array['locks'],p_exception_type||' payload');
    if jsonb_typeof(p_payload->'locks') is distinct from 'array' or jsonb_array_length(p_payload->'locks')=0 or p_starts_at is not null or p_ends_at is not null then raise exception using errcode='23514',message='rebalance and correction require nonempty lock arrays without a window'; end if;
    for v_lock in select value from jsonb_array_elements(p_payload->'locks') loop
      perform public.static_weekly_assert_exact_object(v_lock,array['workId','slotId'],array['workId','slotId'],'manager correction lock'); perform public.static_weekly_v3_assert_text(v_lock->'workId','manager correction workId',160); perform public.static_weekly_v3_assert_uuid(v_lock->'slotId','manager correction slotId');
      if not public.static_weekly_exception_work_exists(p_base_version_id,p_service_date,v_lock->>'workId') or not (public.static_weekly_exception_slot_exists(p_base_version_id,p_service_date,v_lock->>'slotId',true)
       or exists(select 1 from public.weekly_schedule_versions v
        cross join lateral jsonb_array_elements(v.draft_document#>'{authority,compilerInput,slots}') s
        join public.weekly_schedule_exception_commands e on e.base_version_id=v.version_id
         and e.publication_id=p_publication_id and e.service_date=p_service_date and e.exception_type='cover_all'
         and e.payload_json#>>'{availability,slotId}'=s->>'id'
        where v.version_id=p_base_version_id and s->>'id'=v_lock->>'slotId'
         and s->>'kind'='CONTRACTOR_CAPACITY' and public.static_weekly_capacity_registered(s)
         and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id))) then raise exception using errcode='23514',message='rebalance and correction locks must target current weekday work and working slots'; end if;
    end loop;
    if (select count(*) from jsonb_array_elements(p_payload->'locks'))<>(select count(distinct value->>'workId') from jsonb_array_elements(p_payload->'locks')) or exists(select 1 from public.weekly_schedule_exception_commands e cross join lateral jsonb_array_elements(coalesce(e.payload_json->'locks','[]'::jsonb)) l(value) where e.publication_id=p_publication_id and e.service_date=p_service_date and e.exception_type in ('nine_forty_five_rebalance','manager_correction') and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id) and l.value->>'workId' in (select value->>'workId' from jsonb_array_elements(p_payload->'locks'))) then raise exception using errcode='23514',message='rebalance and correction locks may not duplicate or contradict effective commands'; end if;
  elsif p_exception_type='event_impact' then
    perform public.static_weekly_assert_exact_object(p_payload,array['removeWorkIds','patchWork','addWork'],array['removeWorkIds','patchWork','addWork'],'event impact payload');
    if p_starts_at is not null or p_ends_at is not null or jsonb_typeof(p_payload->'removeWorkIds') is distinct from 'array' or jsonb_typeof(p_payload->'patchWork') is distinct from 'array' or jsonb_typeof(p_payload->'addWork') is distinct from 'array' or jsonb_array_length(p_payload->'removeWorkIds')+jsonb_array_length(p_payload->'patchWork')+jsonb_array_length(p_payload->'addWork')=0 then raise exception using errcode='23514',message='event impact requires nonempty exact command arrays without a window'; end if;
    perform public.static_weekly_v3_assert_string_array(p_payload->'removeWorkIds','event removal targets',true,160);
    if exists(select 1 from jsonb_array_elements(p_payload->'removeWorkIds') x(value) where not public.static_weekly_exception_work_exists(p_base_version_id,p_service_date,x.value#>>'{}')) then raise exception using errcode='23514',message='event removal must target work on the exception service weekday'; end if;
    for v_patch in select value from jsonb_array_elements(p_payload->'patchWork') loop perform public.static_weekly_v3_assert_work_payload(v_patch,false); if not public.static_weekly_exception_work_exists(p_base_version_id,p_service_date,v_patch->>'workId') then raise exception using errcode='23514',message='event patch must target work on the exception service weekday'; end if; end loop;
    for v_add in select value from jsonb_array_elements(p_payload->'addWork') loop perform public.static_weekly_v3_assert_work_payload(v_add,true); if (v_add->>'dayOfWeek')::integer<>extract(dow from p_service_date)::integer or exists(select 1 from public.weekly_schedule_slot_assignments a where a.version_id=p_base_version_id and a.day_of_week=extract(dow from p_service_date)::smallint and a.work_id=v_add->>'workId') or not public.static_weekly_exception_slot_exists(p_base_version_id,p_service_date,v_add->>'originSlotId',false) then raise exception using errcode='23514',message='event addition must be a new work identity for the service weekday and an extant origin slot'; end if; end loop;
    select array_agg(value#>>'{}') into v_ids from jsonb_array_elements(p_payload->'removeWorkIds');
    if exists(select 1 from jsonb_array_elements(p_payload->'patchWork') x(value) where x.value->>'workId'=any(coalesce(v_ids,array[]::text[]))) or exists(select 1 from jsonb_array_elements(p_payload->'addWork') x(value) where x.value->>'workId'=any(coalesce(v_ids,array[]::text[]))) or (select count(*) from jsonb_array_elements(p_payload->'patchWork'))<>(select count(distinct value->>'workId') from jsonb_array_elements(p_payload->'patchWork')) or (select count(*) from jsonb_array_elements(p_payload->'addWork'))<>(select count(distinct value->>'workId') from jsonb_array_elements(p_payload->'addWork')) then raise exception using errcode='23514',message='event targets must be unique and may not remove, patch, and add the same work'; end if;
  elsif p_exception_type='reverse' then
    perform public.static_weekly_assert_exact_object(p_payload,array['reversesExceptionId'],array['reversesExceptionId'],'reverse payload'); perform public.static_weekly_v3_assert_uuid(p_payload->'reversesExceptionId','reverse target');
    if p_starts_at is not null or p_ends_at is not null or p_reverses_exception_id is distinct from (p_payload->>'reversesExceptionId')::uuid then raise exception using errcode='23514',message='reversal requires one coherent UUID target without a window'; end if;
  else raise exception using errcode='23514',message='unsupported exception operation';
  end if;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_assert_manual_repeat_projection(p_envelope jsonb, p_publication uuid, p_date date, p_exceptions jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE sid uuid;expected jsonb;
BEGIN
 IF p_exceptions IS DISTINCT FROM '[]'::jsonb THEN RAISE EXCEPTION 'Dated exceptions require the same native adjustment path'; END IF;
 SELECT authority_source_id INTO STRICT sid FROM public.weekly_schedule_versions v
 JOIN public.weekly_schedule_publications p USING(version_id) WHERE p.publication_id=p_publication;
 expected:=public.static_weekly_manual_repeat_components(sid,p_date)->'projection';
 IF p_envelope IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Repeated normal rows differ from admitted immutable components'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_assert_manual_roster_transition(p_transition jsonb, p_snapshot jsonb, p_config jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare target jsonb;slot jsonb;person jsonb;current_rows jsonb;current_person jsonb;change jsonb;
 at date;expected_transfers integer:=0;expected_unchanged integer:=0;matches integer;
begin
 at:=(p_snapshot->>'serviceDate')::date;
 if p_transition->>'schema' is distinct from 'custodial.approved-manual-roster-transition.v1'
  or p_transition->>'status' is distinct from 'PREPARED_NOT_ADMITTED'
  or p_transition->>'serviceDate' is distinct from at::text
  or p_transition->'expectedRevision' is distinct from p_snapshot->'authorityRevision'
  or p_transition->'parentPublication' is distinct from p_snapshot->'parentPublication'
  or p_transition->>'readbackDigest' is distinct from public.static_weekly_digest_jsonb(p_snapshot)
  or p_transition->>'transitionDigest' is distinct from public.static_weekly_digest_jsonb(p_transition-'transitionDigest')
  or p_transition->>'manualDataDigest' is distinct from 'eeff371f1510c6e4a079bde3ba17136dc10f64b100c7562d9b139fd14805a1c8'
  or p_transition->'liveSlotCount' is distinct from to_jsonb(jsonb_array_length(p_snapshot->'rosterSlots'))
  or (select count(*) from jsonb_each(p_config->'slots') s where s.value->'vacancy'='false'::jsonb)<>8
  or jsonb_array_length(p_snapshot->'employees')<>8 then
  raise exception using errcode='40001',message='manual activation roster, source, date, parent or revision changed';end if;
 for target in select value from jsonb_each(p_config->'slots') where value->'vacancy'='false'::jsonb loop
  select value into strict person from jsonb_array_elements(p_snapshot->'employees') where value->>'employeeId'=target->>'personId';
  select value into strict slot from jsonb_array_elements(p_snapshot->'rosterSlots') where value->>'slotId'=target->>'slotId';
  if person->'active' is distinct from 'true'::jsonb or person->'hasMessenger' is distinct from 'true'::jsonb
   or person->>'displayName' is distinct from target->>'name' or coalesce(person->>'employeeCode','')!~'^EMP[0-9]+$'
   or exists(select 1 from jsonb_array_elements(p_snapshot->'rosterSlots') s
    cross join lateral jsonb_array_elements(s->'incumbencies') r where s->>'slotId'<>target->>'slotId'
     and r->>'personId'=target->>'personId' and (r->>'effectiveEnd' is null or at<(r->>'effectiveEnd')::date)) then
   raise exception using errcode='23514',message='manual activation requires the exact existing active employee, Messenger and stable position';end if;
  select coalesce(jsonb_agg(r),'[]'::jsonb) into current_rows from jsonb_array_elements(slot->'incumbencies') r
   where (r->>'effectiveStart')::date<=at and (r->>'effectiveEnd' is null or at<(r->>'effectiveEnd')::date);
  if jsonb_array_length(current_rows)>1 then raise exception 'overlapping current roster authority';end if;
  current_person:=current_rows->0;
  if current_person->>'personId'=target->>'personId' then
   expected_unchanged:=expected_unchanged+1;
   select count(*) into matches from jsonb_array_elements(p_transition->'unchanged') r
    where r=jsonb_build_object('slotId',target->>'slotId','employeeId',target->>'personId','incumbencyId',current_person->>'incumbencyId');
   if matches<>1 or exists(select 1 from jsonb_array_elements(slot->'incumbencies') r where (r->>'effectiveStart')::date>at) then
    raise exception 'unchanged manual roster identity changed';end if;
  else
   expected_transfers:=expected_transfers+1;
   if exists(select 1 from jsonb_array_elements(slot->'incumbencies') r where (r->>'effectiveStart')::date>=at) then
    raise exception 'manual activation cannot replace a current-day or future incumbency';end if;
   select value into strict change from jsonb_array_elements(p_transition->'transfers') r
    where r->>'slotId'=target->>'slotId' and r->>'employeeId'=target->>'personId';
   if change->>'employeeName' is distinct from person->>'displayName' or change->>'slotLabel' is distinct from slot->>'label'
    or change->>'effectiveStart' is distinct from at::text
    or change->>'expectedLiveRangeDigest' is distinct from public.static_weekly_digest_jsonb(slot)
    or change->'newEmployeeCreated' is distinct from 'false'::jsonb or change->'messengerPrincipalCreated' is distinct from 'false'::jsonb
    or change->'phoneAssignment' is distinct from 'null'::jsonb then raise exception 'manual roster transfer binding changed';end if;
   if current_person is null then
    if change->>'operation' is distinct from 'ASSIGN_EXISTING_EMPLOYEE_TO_EMPTY_SLOT' or change->'closure' is distinct from 'null'::jsonb then
     raise exception 'empty manual position cannot invent former history';end if;
   elsif change->>'operation' is distinct from 'REASSIGN_EXISTING_EMPLOYEE'
    or change->'closure' is distinct from jsonb_build_object('incumbencyId',current_person->>'incumbencyId',
     'personId',current_person->>'personId','displayName',current_person->>'displayName','effectiveStart',current_person->>'effectiveStart',
     'previousEffectiveEnd',current_person->'effectiveEnd','closeAt',at::text) then
    raise exception 'manual transfer requires the exact append-only predecessor closure';
   end if;
  end if;
 end loop;
 if jsonb_array_length(p_transition->'transfers')<>expected_transfers or jsonb_array_length(p_transition->'unchanged')<>expected_unchanged then
  raise exception 'manual transition has extra or missing roster operations';end if;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_assert_projection_envelope(p_envelope jsonb, p_publication_id uuid, p_week_start date, p_exception_set jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_authority jsonb:=p_envelope->'authority'; v_base jsonb; v_compiler_exceptions jsonb; v_publication public.weekly_schedule_publications%rowtype;
begin
  perform public.static_weekly_assert_exact_object(p_envelope,array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','database_projection_identity'],array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','database_projection_identity'],'projection envelope');
  perform public.static_weekly_assert_exact_object(p_envelope->'adapter',array['schema','version'],array['schema','version'],'projection envelope adapter');
  if jsonb_typeof(p_exception_set) is distinct from 'array' or jsonb_typeof(p_envelope->'service_date') is distinct from 'string'
    or jsonb_typeof(p_envelope->'week_start') is distinct from 'string' or jsonb_typeof(p_envelope->'week_end') is distinct from 'string'
    or jsonb_typeof(p_envelope->'authority_digest') is distinct from 'string' or jsonb_typeof(p_envelope->'replay_digest') is distinct from 'string'
    or jsonb_typeof(p_envelope->'compiler_version') is distinct from 'string' or jsonb_typeof(p_envelope->'objective') is distinct from 'object'
    or jsonb_typeof(p_envelope->'metrics') is distinct from 'object' or jsonb_typeof(p_envelope->'applied_exceptions') is distinct from 'array'
    or jsonb_typeof(p_envelope->'assignments') is distinct from 'array' or jsonb_typeof(p_envelope->'database_projection_identity') is distinct from 'string' then
    raise exception using errcode='23514',message='projection envelope requires complete typed authority, receipt, identity, and assignment fields';
  end if;
  if jsonb_array_length(p_envelope->'assignments')=0 then raise exception using errcode='23514',message='projection assignments may not be empty'; end if;
  if exists(select 1 from jsonb_array_elements(p_envelope->'assignments') as a(x) where jsonb_typeof(a.x) is distinct from 'object') then raise exception using errcode='23514',message='projection assignment rows must be JSON objects'; end if;
  if exists(select 1 from jsonb_array_elements(p_envelope->'assignments') as a(x) where not (a.x ?& array['plan_work_id','work_id','day_of_week','service_date','status','work_snapshot','explanation'])) then raise exception using errcode='23514',message='projection assignments require every identity, status, snapshot, and explanation key'; end if;
  if exists(select 1 from jsonb_array_elements(p_envelope->'assignments') as a(x)
      where jsonb_typeof(a.x->'plan_work_id') is distinct from 'string' or nullif(btrim(a.x->>'plan_work_id'),'') is null
        or jsonb_typeof(a.x->'work_id') is distinct from 'string' or nullif(btrim(a.x->>'work_id'),'') is null) then
    raise exception using errcode='23514',message='projection assignments require nonblank string plan_work_id and work_id values';
  end if;
  if exists(select 1 from jsonb_array_elements(p_envelope->'assignments') as a(x)
      where jsonb_typeof(a.x->'day_of_week') is distinct from 'number' or (a.x->>'day_of_week') !~ '^[0-6]$') then
    raise exception using errcode='23514',message='projection assignments require integer day_of_week values from 0 through 6';
  end if;
  -- Keep the input probe and cast in one CASE branch: malformed JSON strings
  -- never reach a date cast.  The explicit [0-9] form avoids the prior
  -- doubly-escaped \\d regex, which rejected valid canonical dates.
  if exists(select 1 from jsonb_array_elements(p_envelope->'assignments') as a(x)
      where jsonb_typeof(a.x->'service_date') is distinct from 'string' or nullif(btrim(a.x->>'service_date'),'') is null
        or (a.x->>'service_date') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
        or not pg_input_is_valid(a.x->>'service_date','date')
        or case when jsonb_typeof(a.x->'service_date')='string'
                       and (a.x->>'service_date') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
                       and pg_input_is_valid(a.x->>'service_date','date')
                then (a.x->>'service_date')::date::text is distinct from a.x->>'service_date'
                  or (a.x->>'service_date')::date<p_week_start
                  or (a.x->>'service_date')::date>p_week_start+6
                else false end) then
    raise exception using errcode='23514',message='projection assignments require canonical valid seven-day service_date values';
  end if;
  if exists(select 1 from jsonb_array_elements(p_envelope->'assignments') as a(x) where jsonb_typeof(a.x->'explanation') is distinct from 'object') then
    raise exception using errcode='23514',message='projection assignments require object explanation facts';
  end if;
  if exists(select 1 from jsonb_array_elements(p_envelope->'assignments') as a(x)
      where jsonb_typeof(a.x->'status') is distinct from 'string' or upper(a.x->>'status') not in ('ASSIGNED','OPEN','REVIEW')) then
    raise exception using errcode='23514',message='projection assignments require an explicit ASSIGNED, OPEN, or REVIEW status';
  end if;
  if (select count(*) from jsonb_array_elements(p_envelope->'assignments'))<>(select count(distinct x->>'plan_work_id') from jsonb_array_elements(p_envelope->'assignments') as a(x)) then
    raise exception using errcode='23514',message='projection assignments may not contain duplicate work identities';
  end if;
  select * into v_publication from public.weekly_schedule_publications where publication_id=p_publication_id;
  if not found then raise exception using errcode='23514',message='projection publication is unknown'; end if;
  select draft_document->'authority' into v_base from public.weekly_schedule_versions where version_id=v_publication.version_id;
  v_compiler_exceptions:=public.static_weekly_compiler_exception_set(p_publication_id,p_week_start);
  perform public.static_weekly_assert_compiler_authority(v_authority,p_envelope->'receipt',p_week_start,false);
  if p_envelope #>> '{adapter,schema}' is distinct from 'memphis-zoo.static-weekly-database-adapter.v1' or p_envelope #>> '{adapter,version}' is distinct from 'static-weekly-database-adapter-v1' or p_envelope->>'service_date' is distinct from p_week_start::text or p_envelope->>'week_start' is distinct from p_week_start::text or p_envelope->>'week_end' is distinct from (p_week_start+6)::text
    or p_envelope->>'authority_digest' is distinct from public.static_weekly_digest_jsonb(v_authority) or p_envelope->>'replay_digest' is distinct from p_envelope #>>'{receipt,compiler,replayDigest}'
    or p_envelope->>'compiler_version' is distinct from v_authority #>>'{optimizerResult,compilerVersion}' or p_envelope->'objective' is distinct from v_authority #> '{optimizerResult,objective}' or p_envelope->'metrics' is distinct from v_authority #> '{optimizerResult,metrics}'
    or p_envelope->>'database_projection_identity' is distinct from public.static_weekly_digest_jsonb(p_envelope-'database_projection_identity')
    or v_authority->'compilerInput' is distinct from v_base->'compilerInput' or v_authority->>'baselineInputDigest' is distinct from v_base->>'baselineInputDigest' or v_authority->>'weeklyVersionDigest' is distinct from v_base->>'weeklyVersionDigest' then
    raise exception using errcode='23514',message='projection must bind the stored baseline, complete receipt, objective, metrics, replay, and full weekly envelope';
  end if;
  if v_authority->'appliedExceptions' is distinct from p_exception_set
    or p_envelope->'applied_exceptions' is distinct from p_exception_set then raise exception using errcode='23514',message='overlay compiler input and applied exceptions must bind the complete accepted seven-day exception set'; end if;
  if v_authority #> '{overlayCompilerInput,exceptions}' is distinct from v_compiler_exceptions then raise exception using errcode='23514',message='overlay compiler input must carry every semantic accepted exception fact for the same seven-day horizon'; end if;
  if exists(
    with optimizer as(select value x from jsonb_array_elements(v_authority #> '{optimizerResult,assignments}')),
    projected as(select value x from jsonb_array_elements(p_envelope->'assignments'))
    select 1 from optimizer o full join projected p on p.x->>'plan_work_id'=o.x->>'planWorkId'
    where o.x is null or p.x is null or p.x->>'service_date' is distinct from o.x->>'serviceDate' or p.x->>'work_id' is distinct from o.x->>'workId' or p.x->>'day_of_week' is distinct from o.x->>'dayOfWeek' or upper(p.x->>'status') is distinct from upper(o.x->>'status')
      or (o.x->>'status'='ASSIGNED' and (p.x->>'owner_slot_id' is distinct from o.x->>'slotId' or p.x->>'owner_person_id' is distinct from o.x->>'personId'))
      or (o.x->>'status' in ('OPEN','REVIEW') and (p.x->>'owner_slot_id' is not null or p.x->>'owner_person_id' is not null))
  ) then raise exception using errcode='23514',message='complete weekly projection assignments must exactly bind the canonical optimizer'; end if;
  if exists(
    with optimizer as(select value x from jsonb_array_elements(v_authority #> '{optimizerResult,assignments}')),
    projected as(select value x from jsonb_array_elements(p_envelope->'assignments'))
    select 1 from optimizer o join projected p on p.x->>'plan_work_id'=o.x->>'planWorkId'
    where jsonb_typeof(p.x->'work_snapshot') is distinct from 'object'
      or not (p.x->'work_snapshot' ?& array['workId','dayOfWeek','originSlotId','locationId','locationCodeSnapshot','locationNameSnapshot','window','serviceEffortMinutes','serviceEffortProvenance','priority','priorityProvenance','required','coveragePolicy','bestEffortCoverage','coveragePolicyOrder','coveragePolicyProvenance','requiredQualifications','qualificationProvenance','restrictions','restrictionProvenance','restrictedSlotIds','manualLock','manualLockSlotId','overlayWork'])
      or exists(select 1 from jsonb_object_keys(p.x->'work_snapshot') as k(key) where not (k.key=any(array['workId','dayOfWeek','originSlotId','locationId','locationCodeSnapshot','locationNameSnapshot','window','serviceEffortMinutes','serviceEffortProvenance','priority','priorityProvenance','required','coveragePolicy','bestEffortCoverage','coveragePolicyOrder','coveragePolicyProvenance','requiredQualifications','qualificationProvenance','restrictions','restrictionProvenance','restrictedSlotIds','manualLock','manualLockSlotId','overlayWork'])))
      or jsonb_typeof(p.x#>'{work_snapshot,workId}') is distinct from 'string'
      or jsonb_typeof(p.x#>'{work_snapshot,dayOfWeek}') is distinct from 'number'
      or jsonb_typeof(p.x#>'{work_snapshot,originSlotId}') not in ('string','null')
      or p.x#>>'{work_snapshot,workId}' is distinct from o.x->>'workId'
      or p.x#>>'{work_snapshot,dayOfWeek}' is distinct from o.x->>'dayOfWeek'
      or p.x#>>'{work_snapshot,window,start}' is distinct from o.x#>>'{window,start}'
      or p.x#>>'{work_snapshot,window,end}' is distinct from o.x#>>'{window,end}'
      or p.x#>>'{work_snapshot,serviceEffortMinutes}' is distinct from o.x->>'serviceEffortMinutes'
      or jsonb_typeof(p.x#>'{work_snapshot,locationId}') is distinct from 'string'
      or p.x#>>'{work_snapshot,locationId}' !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
      or jsonb_typeof(p.x#>'{work_snapshot,locationCodeSnapshot}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,locationCodeSnapshot}'),'') is null
      or jsonb_typeof(p.x#>'{work_snapshot,locationNameSnapshot}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,locationNameSnapshot}'),'') is null
      or jsonb_typeof(p.x#>'{work_snapshot,window}') is distinct from 'object'
      or jsonb_typeof(p.x#>'{work_snapshot,window,start}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,window,start}'),'') is null
      or jsonb_typeof(p.x#>'{work_snapshot,window,end}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,window,end}'),'') is null
      or jsonb_typeof(p.x#>'{work_snapshot,serviceEffortMinutes}') is distinct from 'number'
      or jsonb_typeof(p.x#>'{work_snapshot,serviceEffortProvenance}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,serviceEffortProvenance}'),'') is null
      or jsonb_typeof(p.x#>'{work_snapshot,priority}') is distinct from 'number'
      or jsonb_typeof(p.x#>'{work_snapshot,priorityProvenance}') not in ('string','null')
      or (jsonb_typeof(p.x#>'{work_snapshot,priorityProvenance}')='string' and nullif(btrim(p.x#>>'{work_snapshot,priorityProvenance}'),'') is null)
      or jsonb_typeof(p.x#>'{work_snapshot,required}') is distinct from 'boolean'
      or jsonb_typeof(p.x#>'{work_snapshot,coveragePolicy}') not in ('string','null')
      or jsonb_typeof(p.x#>'{work_snapshot,bestEffortCoverage}') is distinct from 'boolean'
      or jsonb_typeof(p.x#>'{work_snapshot,coveragePolicyOrder}') not in ('number','null')
      or jsonb_typeof(p.x#>'{work_snapshot,coveragePolicyProvenance}') not in ('string','null')
      or jsonb_typeof(p.x#>'{work_snapshot,requiredQualifications}') is distinct from 'array'
      or jsonb_typeof(p.x#>'{work_snapshot,qualificationProvenance}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,qualificationProvenance}'),'') is null
      or jsonb_typeof(p.x#>'{work_snapshot,restrictions}') is distinct from 'array'
      or jsonb_typeof(p.x#>'{work_snapshot,restrictionProvenance}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,restrictionProvenance}'),'') is null
      or jsonb_typeof(p.x#>'{work_snapshot,restrictedSlotIds}') is distinct from 'array'
      or jsonb_typeof(p.x#>'{work_snapshot,manualLock}') is distinct from 'boolean'
      or jsonb_typeof(p.x#>'{work_snapshot,manualLockSlotId}') not in ('string','null')
      or jsonb_typeof(p.x#>'{work_snapshot,overlayWork}') is distinct from 'boolean'
      or exists(select 1 from jsonb_array_elements(p.x#>'{work_snapshot,requiredQualifications}') as q(value) where jsonb_typeof(q.value) is distinct from 'string' or nullif(btrim(q.value#>>'{}'),'') is null)
      or exists(select 1 from jsonb_array_elements(p.x#>'{work_snapshot,restrictions}') as r(value) where jsonb_typeof(r.value) is distinct from 'string' or nullif(btrim(r.value#>>'{}'),'') is null)
      or exists(select 1 from jsonb_array_elements(p.x#>'{work_snapshot,restrictedSlotIds}') as r(value) where jsonb_typeof(r.value) is distinct from 'string' or nullif(btrim(r.value#>>'{}'),'') is null)
      or (select count(*) from jsonb_array_elements(p.x#>'{work_snapshot,requiredQualifications}'))<>(select count(distinct value#>>'{}') from jsonb_array_elements(p.x#>'{work_snapshot,requiredQualifications}'))
      or (select count(*) from jsonb_array_elements(p.x#>'{work_snapshot,restrictions}'))<>(select count(distinct value#>>'{}') from jsonb_array_elements(p.x#>'{work_snapshot,restrictions}'))
      or (select count(*) from jsonb_array_elements(p.x#>'{work_snapshot,restrictedSlotIds}'))<>(select count(distinct value#>>'{}') from jsonb_array_elements(p.x#>'{work_snapshot,restrictedSlotIds}'))
  ) then raise exception using errcode='23514',message='projection work snapshots must be complete semantic authority facts bound to the canonical optimizer'; end if;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_assert_projection_envelope_attested(p_envelope jsonb, p_publication_id uuid, p_week_start date, p_exception_set jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_legacy jsonb;
  v_snapshot jsonb;
  v_document jsonb;
  v_recurring_source_digest text;
  v_published_source_digest text;
  v_overlay_source_digest text;
begin
  perform public.static_weekly_assert_exact_object(
    p_envelope,
    array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','database_projection_identity','semantic_snapshot','attestation'],
    array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','database_projection_identity','semantic_snapshot','attestation'],
    'attested projection envelope'
  );
  perform public.static_weekly_assert_authority_attestation(
    p_envelope->'attestation','dated_projection',public.static_weekly_projection_attestation_payload(p_envelope)
  );
  if p_envelope->>'database_projection_identity' is distinct from
     public.static_weekly_digest_jsonb(p_envelope-array['attestation','database_projection_identity']) then
    raise exception using errcode='23514',message='projection semantic identity must bind the complete attested envelope';
  end if;

  v_snapshot:=p_envelope->'semantic_snapshot';
  perform public.static_weekly_assert_exact_object(
    v_snapshot,
    array['schema','recurring_source_digest','overlay_source_digest','applied_exceptions_digest','active_assignments_digest']||case when p_envelope#>>'{adapter,schema}'='memphis-zoo.static-weekly-database-adapter.v2' then array['derived_baseline_digest','shift_end_derivation_digest'] else '{}'::text[] end,
    array['schema','recurring_source_digest','overlay_source_digest','applied_exceptions_digest','active_assignments_digest']||case when p_envelope#>>'{adapter,schema}'='memphis-zoo.static-weekly-database-adapter.v2' then array['derived_baseline_digest','shift_end_derivation_digest'] else '{}'::text[] end,
    'projection semantic snapshot'
  );
  if exists(
    select 1
    from unnest(array['recurring_source_digest','overlay_source_digest','applied_exceptions_digest','active_assignments_digest']) field_name
    where jsonb_typeof(v_snapshot->field_name) is distinct from 'string'
       or coalesce(v_snapshot->>field_name,'') !~ '^[0-9a-f]{64}$'
  ) then
    raise exception using errcode='23514',message='projection semantic snapshot requires exact canonical SHA-256 identities';
  end if;

  select v.draft_document#>'{authority,compilerInput}' into v_document
  from public.weekly_schedule_versions v
  join public.weekly_schedule_publications p on p.version_id=v.version_id
  where p.publication_id=p_publication_id;
  if not found then
    raise exception using errcode='23514',message='projection publication is unknown';
  end if;

  v_recurring_source_digest:=public.static_weekly_digest_jsonb(
    public.static_weekly_v5_projection_source_identity(p_envelope#>'{authority,compilerInput}')
  );
  v_published_source_digest:=public.static_weekly_digest_jsonb(
    public.static_weekly_v5_projection_source_identity(v_document)
  );
  v_overlay_source_digest:=public.static_weekly_digest_jsonb(
    public.static_weekly_v5_projection_source_identity(p_envelope#>'{authority,overlayCompilerInput}')
  );

  if v_snapshot->>'schema' is distinct from (case p_envelope#>>'{adapter,schema}' when 'memphis-zoo.static-weekly-database-adapter.v2' then 'memphis-zoo.static-weekly-projection-semantic-snapshot.v3' else 'memphis-zoo.static-weekly-projection-semantic-snapshot.v2' end)
    or v_snapshot->>'recurring_source_digest' is distinct from v_recurring_source_digest
    or v_snapshot->>'recurring_source_digest' is distinct from v_published_source_digest
    or v_snapshot->>'overlay_source_digest' is distinct from v_overlay_source_digest
    or v_snapshot->>'applied_exceptions_digest' is distinct from public.static_weekly_digest_jsonb(p_envelope->'applied_exceptions')
    or v_snapshot->>'active_assignments_digest' is distinct from public.static_weekly_digest_jsonb(p_envelope->'assignments') then
    raise exception using errcode='23514',message='projection must bind stable recurring source, dated staffing and exceptions, and active assignments';
  end if;

  -- The established v4 validator still performs the complete structural,
  -- optimizer, work-snapshot, service-mode, and location checks.  Only the
  -- redundant semantic copies have been replaced by independently recomputed
  -- identities.

  if p_envelope#>>'{adapter,schema}'='memphis-zoo.static-weekly-database-adapter.v2' and (
   v_snapshot->'derived_baseline_digest' is distinct from coalesce(p_envelope#>'{authority,derivedBaselineDigest}',p_envelope#>'{authority,baselineInputDigest}')
   or v_snapshot->'shift_end_derivation_digest' is distinct from to_jsonb(public.static_weekly_digest_jsonb(coalesce(p_envelope#>'{authority,shiftEndDerivation}','null'::jsonb)))) then
   raise exception 'projection snapshot does not bind exact derived baseline'; end if;
  v_legacy:=p_envelope-array['semantic_snapshot','attestation'];
  v_legacy:=jsonb_set(
    v_legacy,'{database_projection_identity}',
    to_jsonb(public.static_weekly_digest_jsonb(v_legacy-'database_projection_identity')),true
  );
  perform public.static_weekly_v4_assert_projection_envelope(
    v_legacy,p_publication_id,p_week_start,p_exception_set
  );
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_authority_hmac(p_scope text, p_payload jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_secret text; v_enabled boolean; v_schema text; v_hmac text;
begin
  select hmac_secret,enabled into v_secret,v_enabled from public.static_weekly_authority_attestation_config where singleton=true;
  if v_enabled is not true or length(coalesce(v_secret,''))<32 then
    raise exception using errcode='42501',message='static weekly authority attestation boundary is not configured';
  end if;
  select n.nspname into v_schema from pg_extension e join pg_namespace n on n.oid=e.extnamespace where e.extname='pgcrypto';
  if v_schema not in ('extensions','public') then raise exception using errcode='55000',message='pgcrypto must be installed in extensions or public'; end if;
  execute format('select encode(%I.hmac(convert_to($1,''UTF8''),convert_to($2,''UTF8''),''sha256''),''hex'')',v_schema)
    into v_hmac using p_scope||E'\n'||p_payload::text,v_secret;
  return v_hmac;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_begin_coverall_activation(p_manager uuid, p_packet uuid, p_operation uuid, p_revision bigint, p_preview text, p_credential uuid, p_device text, p_access text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE packet record;snapshot jsonb;request jsonb;prior record;slot jsonb;actor jsonb;code text;basis jsonb;result jsonb;employees_before text;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();actor:=public.custodial_action_actor_v1(p_manager,p_credential,p_device,p_access,'write');
 PERFORM public.custodial_begin_application_mutation();PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 request:=jsonb_build_object('managerId',p_manager,'packetId',p_packet,'operationId',p_operation,'expectedRevision',p_revision,'previewDigest',p_preview);
 SELECT o.request_json,r.receipt_json INTO prior FROM custodial_coverall.activation_operations o JOIN custodial_coverall.activation_receipts r USING(operation_id) WHERE o.operation_id=p_operation;
 IF FOUND THEN IF prior.request_json IS DISTINCT FROM request THEN RAISE EXCEPTION 'Original activation identity conflict';END IF;RETURN prior.receipt_json;END IF;
 -- Explicit scalar/source/config fields ONLY: the outer transaction never
 -- retains a13MBfeasibility record while native helpers allocate components.
 SELECT packet_id,source_id,template_id,manager_id,service_date,expected_revision,roster_digest,preview_digest,
  source_json,source_digest,transition_json,capacity_json,owner_config,template_json,binding_json,approval_json,packet_fingerprint
 INTO STRICT packet FROM custodial_coverall.activation_packets WHERE packet_id=p_packet;
 snapshot:=public.static_weekly_manual_roster_snapshot(public.sch_service_date(statement_timestamp()));
 IF p_operation IS NULL OR packet.manager_id<>p_manager OR packet.expected_revision<>p_revision OR p_preview IS DISTINCT FROM (public.static_weekly_read_coverall_activation_basis(p_manager,p_packet,p_revision)->>'previewDigest')
  OR packet.service_date::text<>snapshot->>'serviceDate' OR p_revision::text<>snapshot->>'authorityRevision'
  OR packet.roster_digest<>public.static_weekly_digest_jsonb(snapshot)
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Current typed activation Source/manager/roster/revision changed';END IF;
 SELECT public.static_weekly_digest_jsonb(jsonb_agg(to_jsonb(e) ORDER BY e.id)) INTO employees_before FROM public.employees e;
 INSERT INTO custodial_coverall.activation_operations VALUES(p_operation,p_packet,p_manager,pg_current_xact_id(),request);
 INSERT INTO public.static_weekly_authority_source_documents(source_id,canonical_source,source_digest,configured_by)
 VALUES(packet.source_id,packet.source_json,packet.source_digest,'approved-manual-coverall:'||p_operation);
 FOR slot IN SELECT value FROM jsonb_array_elements(packet.source_json->'slots') WHERE value->>'kind'='CONTRACTOR_CAPACITY' LOOP
  PERFORM public.static_weekly_capacity_assert_shape(slot);code:='STATIC_'||upper(replace(slot->>'id','-',''));
  INSERT INTO public.weekly_roster_slots(slot_id,slot_code,slot_label,created_by_manager_id,created_by_manager_name_snapshot,content_digest)
  VALUES((slot->>'id')::uuid,code,slot->>'label',p_manager,actor->>'manager_name',public.static_weekly_digest_jsonb(jsonb_build_object('source_id',packet.source_id,'slot_id',slot->>'id','slot_code',code,'slot_label',slot->>'label')));
  INSERT INTO public.static_weekly_contractor_capacity_registrations(capacity_slot_id,capacity_code,source_id,source_digest,slot_snapshot,slot_digest,registered_by_manager_id,manager_name_snapshot)
  VALUES((slot->>'id')::uuid,slot->>'label',packet.source_id,packet.source_digest,slot,public.static_weekly_digest_jsonb(slot),p_manager,actor->>'manager_name');
 END LOOP;
 PERFORM public.static_weekly_v3_source_identity(packet.source_json);
 PERFORM public.static_weekly_coverall_register_template(packet.source_id,packet.template_json,packet.binding_json,packet.owner_config,packet.approval_json);
 INSERT INTO public.static_weekly_manual_activation_packets(packet_id,source_id,template_id,service_date,manager_id,transition_json,feasibility_json,packet_digest)
 SELECT packet_id,source_id,template_id,service_date,manager_id,transition_json,feasibility_json,packet_fingerprint FROM custodial_coverall.activation_packets WHERE packet_id=p_packet;
 basis:=public.static_weekly_coverall_activation_basis(p_manager,p_packet,p_revision);
 result:=public.static_weekly_coverall_activate_source301(p_manager,p_packet,p_revision,basis->>'previewDigest','coverall-source:'||p_operation);
 IF result->>'status'<>'PERSISTED_CURRENT' OR result->>'source_id'<>packet.source_id::text
  OR (SELECT count(*) FROM public.weekly_roster_slots)<>30
  OR employees_before IS DISTINCT FROM(SELECT public.static_weekly_digest_jsonb(jsonb_agg(to_jsonb(e) ORDER BY e.id)) FROM public.employees e)
  OR EXISTS(SELECT 1 FROM public.weekly_roster_slot_incumbencies WHERE slot_id::text IN(SELECT jsonb_array_elements_text(packet.capacity_json->'newCapacityIds')))
 THEN RAISE EXCEPTION 'Atomic source/registry/roster/normal346/40 publication did not preserve employees and empty nonemployee capacity';END IF;
 RETURN public.static_weekly_coverall_record_activation_begin(p_operation,p_manager,p_credential,p_device,p_access,result);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_begin_manual_recurring(p_request jsonb, p_credential uuid, p_device text, p_access text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE manager uuid;op uuid;pub uuid;rev bigint;frame date;origin date;sid uuid;vid uuid;actor jsonb;basis jsonb;repeat_basis jsonb;
 prior custodial_coverall.recurring_materialization_operations%rowtype;receipt jsonb;source_digest text;catalog text;generation bigint;needs_native boolean;reason jsonb;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 IF p_request IS NULL OR pg_column_size(p_request)>16384 THEN RAISE EXCEPTION 'Bounded recurring original request required';END IF;
 PERFORM public.static_weekly_assert_exact_object(p_request,
  ARRAY['schema','kind','operationId','managerId','publicationId','serviceDate','expectedRevision','idempotencyKey'],
  ARRAY['schema','kind','operationId','managerId','publicationId','serviceDate','expectedRevision','idempotencyKey'],'recurring original request');
 IF p_request->>'schema'<>'custodial.approved-manual-recurring-request.v1' OR p_request->>'kind'<>'RECURRING_MANUAL_MATERIALIZATION'
  OR jsonb_typeof(p_request->'idempotencyKey') IS DISTINCT FROM 'string' OR jsonb_typeof(p_request->'expectedRevision') IS DISTINCT FROM 'number'
  OR length(p_request->>'idempotencyKey') NOT BETWEEN 1 AND 200 OR btrim(p_request->>'idempotencyKey')<>p_request->>'idempotencyKey'
 THEN RAISE EXCEPTION 'Exact typed recurring request required';END IF;
 manager:=(p_request->>'managerId')::uuid;op:=(p_request->>'operationId')::uuid;pub:=(p_request->>'publicationId')::uuid;
 rev:=(p_request->>'expectedRevision')::bigint;frame:=(p_request->>'serviceDate')::date;
 actor:=public.custodial_action_actor_v1(manager,p_credential,p_device,p_access,'write');
 SELECT * INTO prior FROM custodial_coverall.recurring_materialization_operations WHERE manager_id=manager AND idempotency_key=p_request->>'idempotencyKey';
 IF FOUND THEN
  IF prior.request_json IS DISTINCT FROM p_request THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='Original recurring operation identity conflict';END IF;
  SELECT receipt_json INTO STRICT receipt FROM custodial_coverall.recurring_materialization_receipts WHERE operation_id=prior.operation_id;
  RETURN jsonb_build_object('state','ORIGINAL_RECEIPT','operationId',op,'receipt',receipt,'currentReadbackRepeated',false);
 END IF;
 IF rev IS DISTINCT FROM(SELECT current_revision FROM public.static_weekly_schedule_control WHERE singleton) OR frame IS NULL OR NOT isfinite(frame)
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Current recurring revision/date required';END IF;
 SELECT v.authority_source_id,v.version_id,p.effective_start,s.source_digest INTO STRICT sid,vid,origin,source_digest
 FROM public.weekly_schedule_publications p JOIN public.weekly_schedule_versions v USING(version_id)
 JOIN public.static_weekly_authority_source_documents s ON s.source_id=v.authority_source_id AND s.active AND s.retired_at IS NULL WHERE p.publication_id=pub;
 IF frame<origin OR mod(frame-origin,7)<>0 THEN RAISE EXCEPTION 'Exact publication-origin aligned frame required';END IF;
 needs_native:=frame=origin;
 IF NOT needs_native THEN
  repeat_basis:=public.static_weekly_read_manual_repeat_basis(manager,pub,frame,rev,p_credential,p_device,p_access);
  needs_native:=jsonb_array_length(repeat_basis->'adjustmentReasons')>0 OR jsonb_array_length(repeat_basis->'acceptedExceptions')>0 OR EXISTS(
   SELECT 1 FROM jsonb_array_elements(repeat_basis->'employmentByDate') ed CROSS JOIN LATERAL jsonb_array_elements(ed->'employees') ee
    JOIN LATERAL jsonb_array_elements(repeat_basis->'participants') part ON part->'serviceDate'=ed->'serviceDate'
   WHERE (ee#>>'{command,fact,state}'='PRE_START' OR (ed->>'serviceDate')::date<(ee#>>'{command,fact,firstServiceDate}')::date)
    AND ((part->'assignmentEmployeeIds')?(ee->>'employeeId') OR (part->'lunchOwnerEmployeeIds')?(ee->>'employeeId') OR (part->'lunchCovererEmployeeIds')?(ee->>'employeeId')));
 END IF;
 IF needs_native THEN basis:=public.static_weekly_manual_recurring_basis(manager,pub,frame,rev);repeat_basis:=NULL;END IF;
 catalog:=coalesce(basis->>'catalogEntryDigest',repeat_basis->>'catalogEntryDigest');generation:=coalesce((basis->>'generation')::bigint,(repeat_basis->>'generation')::bigint);
 PERFORM public.custodial_begin_application_mutation();
 INSERT INTO custodial_coverall.recurring_materialization_operations VALUES(op,manager,p_request->>'idempotencyKey',p_request,
  pg_current_xact_id(),pg_backend_pid(),p_credential,p_device,p_access,sid,pub,vid,frame,rev,basis,repeat_basis,source_digest,catalog,generation);
 RETURN jsonb_build_object('state',CASE WHEN needs_native THEN 'NATIVE_ADJUSTMENT_REQUIRED' ELSE 'NORMAL_REFERENCE_REQUIRED' END,
  'operationId',op,'backendPid',pg_backend_pid(),'transactionId',pg_current_xact_id()::text,'basis',basis,'repeatBasis',repeat_basis,'accepted',false,'committed',false);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_bind_coverall_activation_request(p_manager uuid, p_operation uuid, p_key text, p_packet uuid, p_revision bigint, p_preview text, p_credential uuid, p_device text, p_access text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE request jsonb;prior custodial_coverall.activation_request_aliases%rowtype;preview jsonb;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();PERFORM public.custodial_action_actor_v1(p_manager,p_credential,p_device,p_access,'write');
 PERFORM public.custodial_begin_application_mutation();PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 IF p_operation IS NULL OR p_key IS NULL OR length(p_key) NOT BETWEEN 1 AND 120 OR p_key<>btrim(p_key)
 THEN RAISE EXCEPTION 'Original activation operation/key required';END IF;
 request:=jsonb_build_object('managerId',p_manager,'packetId',p_packet,'operationId',p_operation,'expectedRevision',p_revision,'previewDigest',p_preview,'idempotencyKey',p_key);
 SELECT * INTO prior FROM custodial_coverall.activation_request_aliases WHERE (manager_id=p_manager AND idempotency_key=p_key) OR operation_id=p_operation;
 IF FOUND THEN
  IF prior.manager_id<>p_manager OR prior.idempotency_key<>p_key OR prior.request_json IS DISTINCT FROM request THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='Original activation operation/key semantic conflict';END IF;RETURN;
 END IF;
 preview:=public.static_weekly_read_coverall_activation_basis(p_manager,p_packet,p_revision);
 IF preview IS NULL OR preview->>'previewDigest' IS DISTINCT FROM p_preview THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Typed activation/employment preview changed';END IF;
 INSERT INTO custodial_coverall.activation_request_aliases VALUES(p_manager,p_key,p_operation,request,public.static_weekly_digest_jsonb(request));
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_bind_manual_device_delivery(p_manager uuid, p_publication uuid, p_receipt_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE binding uuid;b custodial_coverall.manual_application_bindings%rowtype;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();PERFORM public.static_weekly_v3_manager_actor(p_manager);
 IF coalesce(p_receipt_digest,'')!~'^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Exact original receipt digest required';END IF;
 binding:=custodial_coverall.bind_manual_application(p_publication,p_receipt_digest);
 PERFORM custodial_coverall.reconcile_manual_publication(p_publication);
 SELECT * INTO STRICT b FROM custodial_coverall.manual_application_bindings WHERE operation_id=binding;
 RETURN jsonb_build_object('schema','custodial.manual-device-delivery-binding.v1','origin','MANUAL_INITIAL','bindingId',binding,
  'publicationId',b.publication_id,'sourceId',b.source_id,'originalProjectionId',b.original_projection_id,
  'originalLunchDocumentIdentity',b.original_lunch_identity,'originalReceiptDigest',coalesce(b.activation_receipt_digest,b.initial_receipt_digest),
  'phoneDeliveryState','PENDING','affectedPhonesUpdated',false,'acceptanceRerun',false);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_capacity_assert_lunch_party(p_projection uuid, p_row jsonb, p_prefix text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare projection public.weekly_schedule_compiled_projections%rowtype;availability jsonb;slot_id text;capacity_id text;
begin
 if p_prefix not in('normal_owner','coverer') then raise exception 'Invalid private lunch party';end if;
 slot_id:=p_row->>(p_prefix||'_slot_id');capacity_id:=p_row->>(p_prefix||'_capacity_id');
 if not (p_row ? (p_prefix||'_capacity_id')) then
  if nullif(p_row->>(p_prefix||'_person_id'),'') is null then
   raise exception using errcode='23514',message='ordinary lunch party still requires a real incumbent person';
  end if;
  return;
 end if;
 if capacity_id is null or capacity_id is distinct from slot_id
  or p_row->(p_prefix||'_person_id') is distinct from 'null'::jsonb then
  raise exception using errcode='23514',message='typed lunch party requires matching capacity identity and explicit null person';
 end if;
 select * into strict projection from public.weekly_schedule_compiled_projections where projection_id=p_projection;
 perform public.static_weekly_capacity_accepted_slot(projection.publication_id,(p_row->>'service_date')::date,slot_id::uuid);
 select value into strict availability from jsonb_array_elements(projection.projection_envelope#>'{authority,projectionAvailability}')
  where value->>'slotId'=slot_id and value->>'serviceDate'=p_row->>'service_date';
 if availability->>'status' is distinct from 'working' or availability->>'ownerKind' is distinct from 'CONTRACTOR_CAPACITY'
  or availability->>'capacityId' is distinct from capacity_id or availability->'incumbentPersonId' is distinct from 'null'::jsonb then
  raise exception using errcode='23514',message='typed lunch party must bind exact accepted nonemployee projection availability';
 end if;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_capacity_source_assert_unchanged_draft(p_version uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare command public.static_weekly_capacity_source_commands%rowtype;preview public.static_weekly_capacity_source_previews%rowtype;
 old_version uuid;old_facts jsonb;new_facts jsonb;old_capacities uuid[];new_capacities uuid[];
begin
 select c.* into command from public.static_weekly_capacity_source_commands c join public.weekly_schedule_versions v on v.authority_source_id=c.source_id where v.version_id=p_version;
 if not found or exists(select 1 from public.static_weekly_capacity_source_receipts where operation_id=command.operation_id) then return;end if;
 select * into strict preview from public.static_weekly_capacity_source_previews where preview_id=command.preview_id;
 select version_id into strict old_version from public.weekly_schedule_publications where publication_id=preview.source_publication_id;
 select array_agg((s->>'legacy_slot_id')::uuid),array_agg((s->>'new_capacity_id')::uuid) into old_capacities,new_capacities from jsonb_array_elements(preview.selection) s;
 select jsonb_agg(to_jsonb(a)-array['assignment_id','version_id','payload_json','authority_facts_json','content_digest','created_at'] order by day_of_week,work_id)
  into old_facts from public.weekly_schedule_slot_assignments a where version_id=old_version;
 select jsonb_agg(to_jsonb(a)-array['assignment_id','version_id','payload_json','authority_facts_json','content_digest','created_at'] order by day_of_week,work_id)
  into new_facts from public.weekly_schedule_slot_assignments a where version_id=p_version;
 if old_facts is distinct from new_facts then raise exception using errcode='55000',message='Capacity registration changed accepted ordinary ownership, work, windows or constraints';end if;
 select jsonb_agg(to_jsonb(a)-array['availability_id','version_id','content_digest','created_at'] order by slot_id,day_of_week)
  into old_facts from public.weekly_schedule_slot_availability a where version_id=old_version and not slot_id=any(old_capacities);
 select jsonb_agg(to_jsonb(a)-array['availability_id','version_id','content_digest','created_at'] order by slot_id,day_of_week)
  into new_facts from public.weekly_schedule_slot_availability a where version_id=p_version and not slot_id=any(new_capacities);
 if old_facts is distinct from new_facts then raise exception using errcode='55000',message='Capacity registration changed employee identity/workday/shift/lunch/restrictions';end if;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_capacity_source_assert_use(p_source uuid, p_manager uuid, p_key text, p_stage text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare command public.static_weekly_capacity_source_commands%rowtype;
begin
 select * into command from public.static_weekly_capacity_source_commands where source_id=p_source;
 if not found or exists(select 1 from public.static_weekly_capacity_source_receipts where operation_id=command.operation_id) then return;end if;
 if command.owner_xid<>pg_current_xact_id() or command.manager_id<>p_manager or p_stage not in('draft','publish')
  or p_key is distinct from 'capacity-source:'||command.operation_id||':'||p_stage then
  raise exception using errcode='42501',message='Unaccepted source restricted to exact admitted manager/transaction/child operation';end if;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_capacity_source_basis(p_manager uuid, p_publication uuid, p_start date, p_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare actor jsonb;source jsonb;roster jsonb;dependencies jsonb;old_people uuid[];findings jsonb;authority record;
begin
 perform public.static_weekly_v3_assert_control_plane();actor:=public.static_weekly_v3_manager_actor(p_manager);
 perform public.static_weekly_capacity_source_locks();
 if p_start is null or extract(isodow from p_start)<>1 or p_start<=public.sch_service_date(clock_timestamp())
  or p_revision is distinct from (select current_revision from public.static_weekly_schedule_control where singleton) then
  raise exception using errcode='40001',message='Capacity source preview requires exact current revision and a future complete Monday';end if;
 source:=public.static_weekly_v3_read_publication_source(p_publication,p_start);
 select * into strict authority from public.static_weekly_v6_schedule_authority_state(p_start);
 if authority.publication_id is distinct from p_publication then raise exception using errcode='40001',message='Exact effective source publication required';end if;
 select coalesce(array_agg(distinct (i->>'personId')::uuid),'{}'::uuid[]) into old_people
  from jsonb_array_elements(source#>'{compiler_input,slots}') s
  cross join lateral jsonb_array_elements(coalesce(s->'incumbencies','[]'::jsonb)) i
  where s->'contractorCapacity'='true'::jsonb and s->>'kind' is distinct from 'CONTRACTOR_CAPACITY';
 roster:=jsonb_build_object(
  'slots',coalesce((select jsonb_agg(to_jsonb(s) order by slot_id) from public.weekly_roster_slots s),'[]'::jsonb),
  'incumbencies',coalesce((select jsonb_agg(to_jsonb(s) order by incumbency_id) from public.weekly_roster_slot_incumbencies s),'[]'::jsonb),
  'closures',coalesce((select jsonb_agg(to_jsonb(s) order by incumbency_closure_id) from public.weekly_roster_slot_incumbency_closures s),'[]'::jsonb),
  'staffing',coalesce((select jsonb_agg(to_jsonb(s) order by staffing_state_id) from public.weekly_roster_slot_staffing_states s),'[]'::jsonb));
 dependencies:=jsonb_build_object(
  'catalog',public.place_source_manifest(),
  'employee_status',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'active',e.active,'display_name',e.display_name) order by e.id)
    from public.employees e where exists(select 1 from jsonb_array_elements(source#>'{compiler_input,slots}') s
      cross join lateral jsonb_array_elements(coalesce(s->'incumbencies','[]'::jsonb)) i where i->>'personId'=e.id::text)),'[]'::jsonb),
  'devices',coalesce((select jsonb_agg(to_jsonb(d) order by id) from public.devices d where assigned_employee_id=any(old_people)),'[]'::jsonb),
  'protected_sessions',coalesce((select jsonb_agg(to_jsonb(s) order by id) from public.sessions s where employee_id=any(old_people) and status in('active','pending_submit')),'[]'::jsonb),
  'protected_offline_contexts',coalesce((select jsonb_agg(to_jsonb(c) order by context_id) from public.custodial_offline_actor_contexts c where employee_id=any(old_people) and status='activated'),'[]'::jsonb),
  'registered_capacity',coalesce((select jsonb_agg(to_jsonb(c) order by capacity_slot_id) from public.static_weekly_contractor_capacity_registrations c),'[]'::jsonb));
 findings:='[]'::jsonb;
 if jsonb_array_length(dependencies->'devices')>0 then findings:=findings||'"LEGACY_CAPACITY_HAS_DEVICE_IDENTITY_REQUIRING_RECONCILIATION"'::jsonb;end if;
 if jsonb_array_length(dependencies->'protected_sessions')>0 or jsonb_array_length(dependencies->'protected_offline_contexts')>0 then findings:=findings||'"LEGACY_CAPACITY_HAS_PROTECTED_WORK_REQUIRING_RECONCILIATION"'::jsonb;end if;
 if jsonb_array_length(dependencies->'registered_capacity')>0 then findings:=findings||'"TYPED_POOL_ALREADY_REGISTERED_RECONCILE_EXISTING_SOURCE"'::jsonb;end if;
 return jsonb_build_object('manager_id',p_manager,'manager_name',actor->>'manager_name',
  'authority_revision',p_revision,'trusted_service_date',public.sch_service_date(clock_timestamp()),
  'source_id',source->'source_id','publication_id',source->'publication_id','current_publication_id',source->'publication_id',
  'version_id',source->'version_id','compiler_input',source->'compiler_input',
  'source_digest',public.static_weekly_digest_jsonb(source->'compiler_input'),
  'roster_digest',public.static_weekly_digest_jsonb(roster),'dependency_digest',public.static_weekly_digest_jsonb(dependencies),
  'all_slot_ids',coalesce((select jsonb_agg(slot_id::text order by slot_id) from public.weekly_roster_slots),'[]'::jsonb),
  'future_exception_count',(select count(*) from public.weekly_schedule_exception_commands where publication_id=p_publication and service_date>=p_start),
  'capacity_dependency_findings',findings);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_capacity_source_begin(p_manager uuid, p_operation uuid, p_preview uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare command public.static_weekly_capacity_source_commands%rowtype;preview public.static_weekly_capacity_source_previews%rowtype;
 basis jsonb;sid uuid:=gen_random_uuid();slot jsonb;actor jsonb;code text;request jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();actor:=public.static_weekly_v3_manager_actor(p_manager);
 perform public.static_weekly_capacity_source_locks();
 if p_operation is null or p_preview is null then raise exception using errcode='22023',message='Exact original operation and preview identities required';end if;
 select * into command from public.static_weekly_capacity_source_commands where operation_id=p_operation;
 if found then
  if command.manager_id<>p_manager or command.preview_id<>p_preview then raise exception using errcode='23505',message='Original manager, operation and complete preview required';end if;
  return jsonb_build_object('replayed',true,'receipt',public.static_weekly_capacity_source_status(p_manager,p_operation));end if;
 select * into preview from public.static_weekly_capacity_source_previews where preview_id=p_preview;
 if not found or preview.manager_id<>p_manager then raise exception using errcode='42501',message='Exact attributable preview required';end if;
 if preview.expires_at<=clock_timestamp() then raise exception using errcode='40001',message='Source preview expired; generate a new exact preview';end if;
 basis:=public.static_weekly_capacity_source_basis(p_manager,preview.source_publication_id,preview.effective_start,preview.expected_revision);
 if basis is distinct from preview.basis_json then raise exception using errcode='40001',message='Exact source/publication/roster/dependencies changed';end if;
 if not public.static_weekly_capacity_source_order_equivalent(preview.candidate_source,public.static_weekly_capacity_source_candidate(basis,preview.selection,preview.effective_start,
  (preview.candidate_source#>>'{version,id}')::uuid,(preview.candidate_source#>>'{version,publicationId}')::uuid))
  or preview.candidate_digest<>public.static_weekly_digest_jsonb(preview.candidate_source) then raise exception 'Stored source candidate integrity mismatch';end if;
 request:=jsonb_build_object('operation_id',p_operation,'manager_id',p_manager,'manager_name',actor->>'manager_name',
  'preview_id',p_preview,'basis',basis,'selection',preview.selection,'reason',preview.reason,'candidate_digest',preview.candidate_digest);
 perform public.custodial_begin_application_mutation();
 insert into public.static_weekly_authority_source_documents(source_id,canonical_source,source_digest,configured_by)
 values(sid,preview.candidate_source,preview.candidate_digest,'capacity-source-transition:'||p_operation);
 insert into public.static_weekly_capacity_source_commands(operation_id,manager_id,preview_id,source_id,request_digest)
 values(p_operation,p_manager,p_preview,sid,public.static_weekly_digest_jsonb(request));
 for slot in select value from jsonb_array_elements(preview.candidate_source->'slots') where value->>'kind'='CONTRACTOR_CAPACITY' loop
  code:='STATIC_'||upper(replace(slot->>'id','-',''));
  insert into public.weekly_roster_slots(slot_id,slot_code,slot_label,created_by_manager_id,created_by_manager_name_snapshot,content_digest)
  values((slot->>'id')::uuid,code,slot->>'label',p_manager,actor->>'manager_name',
   public.static_weekly_digest_jsonb(jsonb_build_object('source_id',sid,'slot_id',slot->>'id','slot_code',code,'slot_label',slot->>'label')));
  insert into public.static_weekly_contractor_capacity_registrations(capacity_slot_id,capacity_code,source_id,source_digest,slot_snapshot,slot_digest,registered_by_manager_id,manager_name_snapshot)
  values((slot->>'id')::uuid,slot->>'label',sid,preview.candidate_digest,slot,public.static_weekly_digest_jsonb(slot),p_manager,actor->>'manager_name');
 end loop;
 return public.static_weekly_capacity_source_preview_document(preview)||jsonb_build_object('source_id',sid,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_capacity_source_candidate(p_basis jsonb, p_selection jsonb, p_start date, p_version uuid, p_publication uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare source jsonb:=p_basis->'compiler_input';candidate jsonb;version jsonb;slot jsonb;mapping jsonb;availability jsonb;
 slots jsonb:='[]';rows jsonb:='[]';old_ids text[];seen_old text[]:='{}';seen_new text[]:='{}';seen_codes text[]:='{}';
 ordinary_people text[];id text;new_id text;code text;
begin
 if source is null or jsonb_typeof(source->'slots') is distinct from 'array'
  or p_basis->'capacity_dependency_findings' is distinct from '[]'::jsonb
  or p_basis->>'future_exception_count'<>'0'
  or p_basis->>'source_digest' is distinct from public.static_weekly_digest_jsonb(source)
  or p_version is null or p_publication is null then raise exception using errcode='55000',message='Exact unconflicted server source basis required';end if;
 select array_agg(s->>'id' order by s->>'id') into old_ids from jsonb_array_elements(source->'slots') s where s->'contractorCapacity'='true'::jsonb;
 if cardinality(old_ids) is distinct from 8
  or (select count(*) from jsonb_array_elements(source->'slots') s where s->'contractorCapacity' is distinct from 'true'::jsonb)<>9
  or exists(select 1 from jsonb_array_elements(source->'slots') s where s->'contractorCapacity'='true'::jsonb and s->>'kind'='CONTRACTOR_CAPACITY') then
  raise exception using errcode='55000',message='Existing source does not contain the explicit nine-position/eight-legacy-capacity pool; reconcile actual source templates';end if;
 select coalesce(array_agg(distinct i->>'personId'),'{}'::text[]) into ordinary_people
  from jsonb_array_elements(source->'slots') s cross join lateral jsonb_array_elements(coalesce(s->'incumbencies','[]'::jsonb)) i
  where s->'contractorCapacity' is distinct from 'true'::jsonb;
 if exists(select 1 from jsonb_array_elements(source->'slots') s where s->>'id'=any(old_ids)
  and (jsonb_typeof(s->'incumbencies') is distinct from 'array' or jsonb_array_length(s->'incumbencies')=0
   or exists(select 1 from jsonb_array_elements(s->'incumbencies') i where i->>'personId'=any(ordinary_people)))) then
  raise exception using errcode='55000',message='Legacy capacity identity is absent or shared with a real employee position; explicit reconciliation required';end if;
 if p_selection is null or jsonb_typeof(p_selection)<>'array' or jsonb_array_length(p_selection)<>8 or octet_length(p_selection::text)>8192 then
  raise exception using errcode='22023',message='Exactly eight explicit old-slot/new-capacity/code mappings required';end if;
 for mapping in select value from jsonb_array_elements(p_selection) loop
  perform public.static_weekly_assert_exact_object(mapping,array['legacy_slot_id','new_capacity_id','capacity_code'],array['legacy_slot_id','new_capacity_id','capacity_code'],'capacity source mapping');
  perform public.static_weekly_v3_assert_uuid(mapping->'legacy_slot_id','legacy capacity slot');
  perform public.static_weekly_v3_assert_uuid(mapping->'new_capacity_id','new nonemployee capacity');
  id:=(mapping->>'legacy_slot_id')::uuid::text;new_id:=(mapping->>'new_capacity_id')::uuid::text;code:=mapping->>'capacity_code';
  if id<>mapping->>'legacy_slot_id' or new_id<>mapping->>'new_capacity_id' or not id=any(old_ids)
   or id=any(seen_old) or new_id=any(seen_new) or code=any(seen_codes) or code is null or code !~ '^CoverAll0[1-8]$'
   or exists(select 1 from public.weekly_roster_slots where slot_id=new_id::uuid) then
   raise exception using errcode='22023',message='Mapping must use each exact original UUID once, each new unused UUID once and each CoverAll01..08 code once';end if;
  seen_old:=array_append(seen_old,id);seen_new:=array_append(seen_new,new_id);seen_codes:=array_append(seen_codes,code);
 end loop;
 version:=source->'version';
 if public.static_weekly_capacity_source_legacy_reference(version-array['id','publicationId','effectiveStart','effectiveEnd','slotAvailability'],old_ids) then
  raise exception using errcode='55000',message='Accepted duties/origins/policy reference legacy capacity; explicit replacement-duty reconciliation required';end if;
 for slot in select value from jsonb_array_elements(source->'slots') loop
  if slot->>'id'=any(old_ids) then
   select value into strict mapping from jsonb_array_elements(p_selection) where value->>'legacy_slot_id'=slot->>'id';
   slot:=jsonb_build_object('id',mapping->>'new_capacity_id','capacityId',mapping->>'new_capacity_id','label',mapping->>'capacity_code',
     'kind','CONTRACTOR_CAPACITY','contractorCapacity',true,'incumbencies','[]'::jsonb,'contractorAvailability',slot->'contractorAvailability');
   perform public.static_weekly_capacity_assert_shape(slot);
  end if;slots:=slots||jsonb_build_array(slot);
 end loop;
 for availability in select value from jsonb_array_elements(version->'slotAvailability') loop
  if availability->>'slotId'=any(old_ids) then
   perform public.static_weekly_assert_exact_object(availability,array['slotId','dayOfWeek','status'],array['slotId','dayOfWeek','status'],'inactive legacy capacity');
   if availability->>'status'<>'unavailable' then raise exception using errcode='55000',message='Recurring legacy capacity is active; do not silently change eligibility';end if;
   select value into strict mapping from jsonb_array_elements(p_selection) where value->>'legacy_slot_id'=availability->>'slotId';
   availability:=jsonb_set(availability,'{slotId}',mapping->'new_capacity_id');
  end if;rows:=rows||jsonb_build_array(availability);
 end loop;
 version:=version||jsonb_build_object('id',p_version,'publicationId',p_publication,'effectiveStart',p_start,'effectiveEnd',null,'status','published','slotAvailability',rows);
 candidate:=source||jsonb_build_object('slots',slots,'version',version,'serviceDate',p_start);
 return candidate;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_capacity_source_finalize(p_manager uuid, p_operation uuid, p_publication uuid, p_projection uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare command public.static_weekly_capacity_source_commands%rowtype;preview public.static_weekly_capacity_source_previews%rowtype;
 authority record;lunch public.weekly_schedule_lunch_documents%rowtype;receipt jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();perform public.static_weekly_v3_manager_actor(p_manager);
 select * into strict command from public.static_weekly_capacity_source_commands where operation_id=p_operation;
 if command.manager_id<>p_manager or command.owner_xid<>pg_current_xact_id() then raise exception using errcode='42501',message='Exact original source transaction required';end if;
 select * into strict preview from public.static_weekly_capacity_source_previews where preview_id=command.preview_id;
 if not exists(select 1 from public.weekly_schedule_publications p join public.weekly_schedule_versions v using(version_id)
  where p.publication_id=p_publication and p.actor_manager_id=p_manager and p.idempotency_key='capacity-source:'||p_operation||':publish'
   and v.authority_source_id=command.source_id and p.effective_start=preview.effective_start) then raise exception 'Exact admitted source publication receipt required';end if;
 select * into strict authority from public.static_weekly_v6_schedule_authority_state(preview.effective_start);
 select * into strict lunch from public.weekly_schedule_lunch_documents where projection_id=p_projection;
 if authority.publication_id is distinct from p_publication or authority.projection_id is distinct from p_projection
  or authority.projection_status is distinct from 'current' or lunch.accepted_by_manager_id is distinct from p_manager
  or not exists(select 1 from public.weekly_schedule_command_receipts where actor_manager_id=p_manager
   and command_type='materialize_projection' and idempotency_key='capacity-source:'||p_operation||':projection:'||preview.effective_start
   and response_json#>>'{data,projection_id}'=p_projection::text) then raise exception 'Complete current projection/lunch and original child receipt required';end if;
 receipt:=jsonb_build_object('schema','custodial.capacity-source-receipt.v1','state','ACCEPTED','accepted',true,
  'operation_id',p_operation,'manager_id',p_manager,'preview_id',preview.preview_id,'request_digest',command.request_digest,
  'source_id',command.source_id,'candidate_digest',preview.candidate_digest,'basis_source_digest',preview.basis_json->'source_digest',
  'basis_roster_digest',preview.basis_json->'roster_digest','basis_dependency_digest',preview.basis_json->'dependency_digest',
  'publication_id',p_publication,'projection_id',p_projection,'authority_revision',authority.projection_authority_revision,
  'effective_start',preview.effective_start,'selection',preview.selection,'historical_employee_rows_changed',false,
  'new_employee_rows',0,'manual_activation_required',true,'affected_phones_updated',false,'phone_delivery_state','PENDING');
 insert into public.static_weekly_capacity_source_receipts(operation_id,publication_id,projection_id,receipt_json,receipt_digest)
 values(p_operation,p_publication,p_projection,receipt,public.static_weekly_digest_jsonb(receipt));return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_capacity_source_legacy_reference(p_value jsonb, p_ids text[])
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare item jsonb;key text;begin
 if jsonb_typeof(p_value)='string' then return (p_value#>>'{}')=any(p_ids);
 elsif jsonb_typeof(p_value)='array' then
  for item in select value from jsonb_array_elements(p_value) loop
   if public.static_weekly_capacity_source_legacy_reference(item,p_ids) then return true;end if;
  end loop;
 elsif jsonb_typeof(p_value)='object' then
  for key,item in select * from jsonb_each(p_value) loop
   if key=any(p_ids) or public.static_weekly_capacity_source_legacy_reference(item,p_ids) then return true;end if;
  end loop;
 end if;return false;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_capacity_source_locks()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
 -- Existing common recurring lock FIRST. Then source/roster/catalog/device
 -- admission witnesses in fixed order. Core snapshots and history unchanged.
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 lock table public.weekly_roster_slots,public.weekly_roster_slot_incumbencies,
  public.weekly_roster_slot_incumbency_closures,public.weekly_roster_slot_staffing_states,
  public.static_weekly_authority_source_documents,public.static_weekly_contractor_capacity_registrations,
  public.weekly_schedule_publications,public.location_groups,public.location_group_memberships,public.locations,
  public.employees,public.devices in share mode;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_capacity_source_order_equivalent(p_raw jsonb, p_canonical jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a jsonb;b jsonb;items jsonb;v jsonb;
begin
 if jsonb_typeof(p_raw) is distinct from 'object' or jsonb_typeof(p_canonical) is distinct from 'object'
  or jsonb_typeof(p_raw->'slots') is distinct from 'array' or jsonb_typeof(p_canonical->'slots') is distinct from 'array'
  or jsonb_typeof(p_raw#>'{version,slotAvailability}') is distinct from 'array'
  or jsonb_typeof(p_canonical#>'{version,slotAvailability}') is distinct from 'array' then return false;end if;
 a:=p_raw;b:=p_canonical;
 select coalesce(jsonb_agg(value order by value->>'id' collate "C",value::text collate "C"),'[]'::jsonb) into items from jsonb_array_elements(a->'slots');a:=jsonb_set(a,'{slots}',items);
 select coalesce(jsonb_agg(value order by value->>'id' collate "C",value::text collate "C"),'[]'::jsonb) into items from jsonb_array_elements(b->'slots');b:=jsonb_set(b,'{slots}',items);
 select coalesce(jsonb_agg(value order by (value->>'dayOfWeek')::integer,value->>'slotId' collate "C",value::text collate "C"),'[]'::jsonb) into items from jsonb_array_elements(a#>'{version,slotAvailability}');a:=jsonb_set(a,'{version,slotAvailability}',items);
 select coalesce(jsonb_agg(value order by (value->>'dayOfWeek')::integer,value->>'slotId' collate "C",value::text collate "C"),'[]'::jsonb) into items from jsonb_array_elements(b#>'{version,slotAvailability}');b:=jsonb_set(b,'{version,slotAvailability}',items);
 return a=b;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_capacity_source_preview(p_manager uuid, p_publication uuid, p_start date, p_revision bigint, p_selection jsonb, p_reason text, p_canonical_source jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare basis jsonb;candidate jsonb;preview public.static_weekly_capacity_source_previews%rowtype;
begin
 basis:=public.static_weekly_capacity_source_basis(p_manager,p_publication,p_start,p_revision);
 if p_reason is null or length(btrim(p_reason)) not between 1 and 500 then raise exception using errcode='22023',message='Explicit source transition reason required';end if;
 candidate:=public.static_weekly_capacity_source_candidate(basis,p_selection,p_start,
  (p_canonical_source#>>'{version,id}')::uuid,(p_canonical_source#>>'{version,publicationId}')::uuid);
 if not public.static_weekly_capacity_source_order_equivalent(candidate,p_canonical_source) then
  raise exception using errcode='23514',message='Canonical source may permute only exact slot/availability elements; no values, multiplicity or other array changes';end if;
 candidate:=p_canonical_source;
 insert into public.static_weekly_capacity_source_previews(manager_id,source_publication_id,expected_revision,effective_start,selection,basis_json,candidate_source,candidate_digest,reason)
 values(p_manager,p_publication,p_revision,p_start,p_selection,basis,candidate,public.static_weekly_digest_jsonb(candidate),p_reason) returning * into preview;
 return public.static_weekly_capacity_source_preview_document(preview);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_capacity_source_roster_visible(p_slot uuid, p_version uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare included boolean;scoped boolean;
begin
 select exists(select 1 from public.weekly_schedule_versions v
  cross join lateral jsonb_array_elements(v.draft_document#>'{authority,compilerInput,slots}') s
  where v.version_id=p_version and s->>'id'=p_slot::text) into included;
 if exists(select 1 from public.static_weekly_contractor_capacity_registrations where capacity_slot_id=p_slot)
  and not included then return false;end if;
 select exists(select 1 from public.weekly_schedule_versions v
  join public.static_weekly_capacity_source_commands c on c.source_id=v.authority_source_id
  where v.version_id=p_version and (c.owner_xid=pg_current_xact_id()
   or exists(select 1 from public.static_weekly_capacity_source_receipts r where r.operation_id=c.operation_id))) into scoped;
 return not scoped or included;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_capacity_source_status(p_manager uuid, p_operation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare command public.static_weekly_capacity_source_commands%rowtype;receipt jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();perform public.static_weekly_v3_manager_actor(p_manager);
 -- A NOT_FOUND result must wait for an in-flight confirmation, not race its
 -- commit. VOLATILE permits a fresh snapshot after the authority lock wait.
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select * into command from public.static_weekly_capacity_source_commands where operation_id=p_operation;
 if not found then return jsonb_build_object('operation_id',p_operation,'state','NOT_FOUND','accepted',false);end if;
 if command.manager_id<>p_manager then raise exception using errcode='42501',message='Original named manager required';end if;
 select receipt_json into strict receipt from public.static_weekly_capacity_source_receipts where operation_id=p_operation;
 return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_component_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_state text;
begin
  select lifecycle_state into v_state from public.weekly_schedule_versions where version_id=coalesce(new.version_id,old.version_id);
  if current_setting('app.static_weekly_draft_write',true)='on' and v_state='draft' then
    if tg_op='DELETE' then return old; end if; return new;
  end if;
  if current_setting('app.static_weekly_publish_write',true)='on' and v_state='published' and tg_op='INSERT' then return new; end if;
  raise exception using errcode='23514',message='scheduler components may change only through a revision-checked v2 command';
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_consume_vacancy_reviewed_preparation(p_manager uuid, p_credential uuid, p_device text, p_access text, p_key text, p_preview_digest text, p_post_input_utf8 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor jsonb;generation bigint;r public.static_weekly_vacancy_reviewed_preparations%rowtype;
 packet jsonb;v jsonb;p jsonb;completed jsonb;mutation public.weekly_schedule_command_receipts%rowtype;
 projection public.weekly_schedule_command_receipts%rowtype;mutation_xid bigint;projection_xid bigint;BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();generation:=public.custodial_begin_application_mutation();
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 actor:=public.custodial_action_actor_v1(p_manager,p_credential,p_device,p_access,'write');
 SELECT * INTO r FROM public.static_weekly_vacancy_reviewed_preparations WHERE manager_id=p_manager AND idempotency_key=p_key FOR UPDATE;
 IF NOT FOUND OR r.credential_id IS DISTINCT FROM p_credential OR r.device_identifier IS DISTINCT FROM p_device
  OR r.generation IS DISTINCT FROM generation OR r.preview_digest IS DISTINCT FROM p_preview_digest
 THEN RAISE EXCEPTION 'Vacancy original retained preparation/actor/generation/digest required';END IF;
 packet:=public.static_weekly_vacancy_reviewed_packet(r.packet_utf8,p_manager,p_key);
 v:=(packet->>'previewUtf8')::jsonb;p:=(packet->>'preparedProjectionUtf8')::jsonb;
 IF public.static_weekly_digest_text(r.packet_utf8) IS DISTINCT FROM r.payload_sha256
  OR p_post_input_utf8 IS NULL OR octet_length(convert_to(p_post_input_utf8,'UTF8')) NOT BETWEEN 1 AND 16777216
  OR p_post_input_utf8::jsonb IS DISTINCT FROM (packet->>'postInputUtf8')::jsonb THEN
  RAISE EXCEPTION 'Vacancy actual post-mutation full compiler input changed';END IF;
 -- Normal source263 fixed read validates immutable mutation/projection/lunch,
 -- original actor/revisions, closed server attestation and actual owning HMAC.
 -- No staged parent, caller Boolean or a future/current selector is acceptance.
 completed:=public.static_weekly_read_original_staffing_outcome_v1(p_manager,p_key,'vacate_roster_slot');
 IF completed->>'schema' IS DISTINCT FROM 'custodial.original-staffing-outcome.v1'
  OR completed->>'state' IS DISTINCT FROM 'ACCEPTED_ORIGINAL'
  OR completed#>>'{original_request,operation}' IS DISTINCT FROM 'vacate_roster_slot'
  OR completed#>>'{original_request,source_id}' IS DISTINCT FROM v->>'sourceId'
  OR completed#>>'{original_request,slot_id}' IS DISTINCT FROM v->>'slotId'
  OR completed#>>'{original_request,employee_id}' IS DISTINCT FROM v->>'employeeId'
  OR completed#>>'{original_request,effective_start}' IS DISTINCT FROM v->>'effectiveStart'
  OR completed#>>'{original_request,reason}' IS DISTINCT FROM packet->>'reason'
  OR completed#>>'{receipt,data,worker_candidate_digest}' IS DISTINCT FROM r.worker_candidate_digest
  OR completed#>>'{receipt,data,paired_lunch_document_identity}' IS DISTINCT FROM p#>>'{lunchDocument,document_identity}'
 THEN RAISE EXCEPTION 'Vacancy exact accepted original candidate witness required';END IF;
 SELECT * INTO mutation FROM public.weekly_schedule_command_receipts WHERE actor_manager_id=p_manager AND idempotency_key=p_key
  AND command_type='vacate_roster_slot';
 SELECT * INTO projection FROM public.weekly_schedule_command_receipts WHERE actor_manager_id=p_manager
  AND idempotency_key='projection-'||public.static_weekly_digest_text(p_key) AND command_type='materialize_projection';
 IF mutation.command_id IS NULL OR projection.command_id IS NULL
  OR mutation.expected_revision IS DISTINCT FROM (v->>'expectedRevision')::bigint
  OR projection.expected_revision IS DISTINCT FROM mutation.expected_revision+1
  OR projection.request_canonical_json->>'publication_id' IS DISTINCT FROM v->>'publicationId'
  OR (projection.response_json->>'revision')::bigint IS DISTINCT FROM (v->>'resultingRevision')::bigint
 THEN RAISE EXCEPTION 'Vacancy accepted original revision/publication witness changed';END IF;
 IF r.state='CONSUMED' THEN
  IF r.accepted_witness IS DISTINCT FROM completed OR r.accepted_witness_sha256 IS DISTINCT FROM public.static_weekly_digest_jsonb(completed)
  THEN RAISE EXCEPTION 'Vacancy original consumed witness changed';END IF;
  RETURN public.static_weekly_vacancy_reviewed_descriptor(r,false,true);
 END IF;
 -- Normal writers insert both immutable receipts directly in this same outer
 -- transaction. A later transaction cannot manufacture initial consumption.
 SELECT xmin::text::bigint INTO mutation_xid FROM public.weekly_schedule_command_receipts WHERE command_id=mutation.command_id;
 SELECT xmin::text::bigint INTO projection_xid FROM public.weekly_schedule_command_receipts WHERE command_id=projection.command_id;
 IF mutation_xid IS DISTINCT FROM mod(txid_current(),4294967296)
  OR projection_xid IS DISTINCT FROM mod(txid_current(),4294967296)
  OR (SELECT current_revision FROM public.static_weekly_schedule_control WHERE singleton) IS DISTINCT FROM (v->>'resultingRevision')::bigint
 THEN RAISE EXCEPTION 'Vacancy consume requires this same accepted authority transaction';END IF;
 PERFORM set_config('app.static_weekly_vacancy_preparation_write','consume',true);
 UPDATE public.static_weekly_vacancy_reviewed_preparations SET state='CONSUMED',consumed_at=clock_timestamp(),
  accepted_witness=completed,accepted_witness_sha256=public.static_weekly_digest_jsonb(completed)
  WHERE manager_id=p_manager AND idempotency_key=p_key AND state='UNSUBMITTED' RETURNING * INTO r;
 IF NOT FOUND THEN RAISE EXCEPTION 'Vacancy original reviewed consumption conflicted';END IF;
 PERFORM set_config('app.static_weekly_vacancy_preparation_write','',true);
 RETURN public.static_weekly_vacancy_reviewed_descriptor(r,false,false);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_accept_companion(p_operation uuid, p_manager uuid, p_revision bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.static_weekly_staffing_commands%rowtype;b custodial_coverall.staged_bindings%rowtype;q custodial_coverall.choices%rowtype;d jsonb;request_actor custodial_coverall.request_actors%rowtype;
BEGIN
 SELECT * INTO STRICT c FROM public.static_weekly_staffing_commands WHERE operation_id=p_operation FOR UPDATE;
 SELECT * INTO b FROM custodial_coverall.staged_bindings WHERE operation_id=p_operation;IF NOT FOUND THEN
  IF EXISTS(SELECT 1 FROM custodial_coverall.choices WHERE operation_id=CASE WHEN c.command_kind='cancel_absence' THEN c.target_absence_id ELSE p_operation END) THEN RAISE EXCEPTION 'CoverAll cannot accept without its staged original binding';END IF;RETURN;END IF;
 SELECT * INTO STRICT q FROM custodial_coverall.choices WHERE operation_id=b.choice_operation_id;
 SELECT * INTO STRICT request_actor FROM custodial_coverall.request_actors WHERE operation_id=p_operation;
 PERFORM public.custodial_action_actor_v1(p_manager,request_actor.credential_id,request_actor.device_id,request_actor.session_access,'manage_coverall');
 IF c.state<>'PREPARED' OR c.prepared_by_manager_id<>p_manager OR p_revision<>c.expected_revision+1
  OR (SELECT current_revision FROM public.static_weekly_schedule_control WHERE singleton)<>p_revision
  OR current_setting('app.static_weekly_staffing_batch_operation',true) IS DISTINCT FROM p_operation::text
  OR NOT EXISTS(SELECT 1 FROM public.weekly_schedule_authority_revisions r WHERE r.authority_revision=p_revision AND r.command_id=p_operation AND r.operation='apply_staffing_command' AND r.actor_manager_id=p_manager)
  OR c.candidate_set_digest<>b.candidate_set_digest OR c.preview_digest<>b.preview_digest OR q.choice_digest<>b.choice_digest
 THEN RAISE EXCEPTION 'CoverAll acceptance must share the exact canonical native transaction/revision';END IF;
 IF c.command_kind='absence' THEN
  IF NOT EXISTS(SELECT 1 FROM public.static_weekly_staffing_absences WHERE absence_id=p_operation AND accepted_revision=p_revision) THEN RAISE EXCEPTION 'Canonical third absence fact missing';END IF;
  FOR d IN SELECT value FROM jsonb_array_elements(q.choice_json->'days') LOOP
   INSERT INTO custodial_coverall.accepted_days VALUES(p_operation,(d->>'serviceDate')::date,(d->>'sourceId')::uuid,(d->>'publicationId')::uuid,
    (d->>'capacityId')::uuid,p_revision,p_manager,d);
  END LOOP;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM public.static_weekly_staffing_absence_cancellations WHERE accepted_operation_id=p_operation AND absence_id=c.target_absence_id AND accepted_revision=p_revision) THEN RAISE EXCEPTION 'Canonical cancellation fact missing';END IF;
  INSERT INTO custodial_coverall.cancellations SELECT p_operation,a.operation_id,a.service_date,p_revision,p_manager FROM custodial_coverall.accepted_days a
   WHERE a.operation_id=c.target_absence_id AND a.service_date BETWEEN c.start_date AND c.end_date;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_activate_source301(p_manager uuid, p_packet uuid, p_revision bigint, p_preview text, p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare packet record;prior public.static_weekly_manual_activation_confirmations%rowtype;
 actor jsonb;basis jsonb;request jsonb;change jsonb;revision bigint:=p_revision;incumbency uuid;command uuid;
 content text;initial_body jsonb;published jsonb;receipt jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();actor:=public.static_weekly_v3_manager_actor(p_manager);
 perform public.custodial_begin_application_mutation();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 if p_key is null or length(btrim(p_key)) not between 1 and 120 or p_preview!~'^[0-9a-f]{64}$' then
  raise exception using errcode='23514',message='manual activation requires exact preview and bounded original idempotency key';end if;
 request:=jsonb_build_object('managerId',p_manager,'packetId',p_packet,'expectedRevision',p_revision,'previewDigest',p_preview,'idempotencyKey',p_key);
 select * into prior from public.static_weekly_manual_activation_confirmations where manager_id=p_manager and idempotency_key=p_key;
 if found then
  if prior.request_json is distinct from request or prior.receipt_digest is distinct from public.static_weekly_digest_jsonb(prior.receipt_json) then
   raise exception using errcode='23505',message='manual activation original identity conflict';end if;
  return prior.receipt_json;
 end if;
 basis:=public.static_weekly_coverall_activation_basis(p_manager,p_packet,p_revision);
 if basis->>'previewDigest' is distinct from p_preview then raise exception using errcode='40001',message='manual activation preview changed';end if;
 -- Keep only the small command facts in the outer atomic operation. Large
 -- immutable feasibility components are read by short-lived private helpers.
 select source_id,template_id,service_date,transition_json->'transfers' as transfers
  into strict packet from public.static_weekly_manual_activation_packets where packet_id=p_packet;
 for change in select value from jsonb_array_elements(packet.transfers) loop
  command:=gen_random_uuid();incumbency:=gen_random_uuid();
  content:=public.static_weekly_digest_jsonb(jsonb_build_object('packetId',p_packet,'transfer',change));
  revision:=public.static_weekly_advance_authority(revision,'activate_approved_manual_roster',p_manager,actor->>'manager_name',command,content);
  insert into public.weekly_roster_slot_incumbencies(incumbency_id,slot_id,person_id,person_name_snapshot,effective_start,
   created_by_manager_id,created_by_manager_name_snapshot,content_digest)
  values(incumbency,(change->>'slotId')::uuid,(change->>'employeeId')::uuid,change->>'employeeName',packet.service_date,
   p_manager,actor->>'manager_name',content);
  if change->'closure'<>'null'::jsonb then
   insert into public.weekly_roster_slot_incumbency_closures(closed_incumbency_id,replacement_incumbency_id,
    closed_at_effective_date,authority_revision,actor_manager_id,actor_manager_name_snapshot,content_digest)
   values((change#>>'{closure,incumbencyId}')::uuid,incumbency,packet.service_date,revision,p_manager,actor->>'manager_name',content);
  end if;
  insert into public.weekly_roster_slot_staffing_states(slot_id,employee_id,staffing_state,effective_start,
   authority_revision,actor_manager_id,actor_manager_name_snapshot,reason,content_digest)
  values((change->>'slotId')::uuid,(change->>'employeeId')::uuid,'working',packet.service_date,
   revision,p_manager,actor->>'manager_name','Owner-approved manual schedule activation; existing employee identity preserved',content);
 end loop;
 -- The shared NORMAL validator now checks the real post-transfer hydrated
 -- source. A failure rolls back every new range, closure and state above.
 perform public.static_weekly_manual_activation_store_baseline(p_packet);
 initial_body:=public.static_weekly_manual_activation_initial_envelope(p_manager,p_packet,revision,p_key||':initial');
 published:=public.static_weekly_materialize_approved_initial_baseline(p_manager,packet.source_id,packet.service_date,revision,
  (initial_body->>'generation')::bigint,p_key||':initial',initial_body);
 if published->'ok' is distinct from 'true'::jsonb or published->>'persistence_status' is distinct from 'PERSISTED'
  or published->>'source_id' is distinct from packet.source_id::text then raise exception 'manual activation normal publication was not persisted';end if;
 receipt:=published||jsonb_build_object('schema','custodial.approved-manual-activation-confirmation.v1','status','PERSISTED_CURRENT',
  'packetId',p_packet,'previewDigest',p_preview,'serviceDate',packet.service_date::text,'windowEnd',(packet.service_date+6)::text,
  'rosterTransfers',jsonb_array_length(packet.transfers),'historyPreserved',true,'newEmployeesCreated',false,
  'messengerPrincipalsCreated',false,'solverInvoked',false,'weeklyBaselineChanged',false,'atomicRosterAndPublication',true);
 insert into public.static_weekly_manual_activation_confirmations(manager_id,idempotency_key,packet_id,request_json,receipt_json,receipt_digest)
 values(p_manager,p_key,p_packet,request,receipt,public.static_weekly_digest_jsonb(receipt));
 return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_activation_basis(p_manager uuid, p_packet uuid, p_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare packet record;entry public.static_weekly_approved_template_catalog%rowtype;
 snapshot jsonb;body jsonb;generation bigint;
begin
 perform public.static_weekly_v3_assert_control_plane();perform public.static_weekly_v3_manager_actor(p_manager);
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select packet_id,source_id,template_id,service_date,manager_id,transition_json,packet_digest,
  feasibility_json->>'digest' as feasibility_digest,feasibility_json->'assignments' as assignments,feasibility_json->'lunchDocument' as lunch_document
 into strict packet from public.static_weekly_manual_activation_packets where packet_id=p_packet for share;
 select * into strict entry from public.static_weekly_approved_template_catalog where template_id=packet.template_id;
 snapshot:=public.static_weekly_coverall_activation_filtered_roster(p_packet);
 if packet.manager_id is distinct from p_manager or packet.service_date::text is distinct from snapshot->>'serviceDate'
  or p_revision::text is distinct from snapshot->>'authorityRevision'
  or exists(select 1 from public.static_weekly_approved_template_retirements where template_id=packet.template_id)
  or packet.packet_digest is distinct from custodial_coverall.stored_manual_packet_fingerprint(p_packet) then
  raise exception using errcode='40001',message='manual activation packet, manager, service date or revision changed';end if;
 perform public.static_weekly_assert_manual_roster_transition(packet.transition_json,snapshot,entry.owner_config);
 generation:=public.static_weekly_v15_read_recurring_generation();
 body:=jsonb_build_object('schema','custodial.approved-manual-activation-preview-basis.v1','managerId',p_manager,
  'packetId',p_packet,'packetDigest',packet.packet_digest,'sourceId',packet.source_id,'templateId',packet.template_id,
  'serviceDate',packet.service_date::text,'windowEnd',(packet.service_date+6)::text,'expectedRevision',p_revision,
  'generation',generation,'readbackDigest',public.static_weekly_digest_jsonb(snapshot),
  'feasibilityDigest',packet.feasibility_digest);
 return body||jsonb_build_object('previewDigest',public.static_weekly_digest_jsonb(body),
  'assignments',packet.assignments,'lunch',packet.lunch_document,
  'transfers',packet.transition_json->'transfers','unchanged',packet.transition_json->'unchanged',
  'parentPublication',snapshot->'parentPublication');
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_activation_filtered_roster(p_packet uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE snapshot jsonb;ids jsonb;slots jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM custodial_coverall.activation_operations o WHERE o.packet_id=p_packet AND o.owner_xid=pg_current_xact_id())
 THEN RAISE EXCEPTION 'Only this atomic original activation may exclude its own eight new empty capacity positions from the original22 CAS';END IF;
 SELECT capacity_json->'newCapacityIds' INTO STRICT ids FROM custodial_coverall.activation_packets WHERE packet_id=p_packet;
 snapshot:=public.static_weekly_manual_roster_snapshot(public.sch_service_date(statement_timestamp()));
 IF jsonb_array_length(snapshot->'rosterSlots')<>30 OR EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot->'rosterSlots') s
  WHERE ids?(s->>'slotId') AND jsonb_array_length(s->'incumbencies')<>0) THEN RAISE EXCEPTION 'Expected22 histories plus eight empty nonemployee positions';END IF;
 SELECT jsonb_agg(s ORDER BY s->>'slotId') INTO slots FROM jsonb_array_elements(snapshot->'rosterSlots') s WHERE NOT ids?(s->>'slotId');
 IF jsonb_array_length(slots)<>22 THEN RAISE EXCEPTION 'Original history slot set differs';END IF;
 RETURN jsonb_set(snapshot,'{rosterSlots}',slots,false);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_assert_activation_data(p_data jsonb, p_snapshot jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE source jsonb:=p_data->'source';transition jsonb:=p_data->'transition';cp jsonb:=p_data->'capacityTransition';
 oldsource jsonb;oldslot jsonb;newslot jsonb;mapping jsonb;expected jsonb;actual jsonb;ids text[];row jsonb;at date;end_date date;
BEGIN
 IF p_data IS NULL OR pg_column_size(p_data)>33554432 THEN RAISE EXCEPTION 'Bounded current-date activation DATA required';END IF;
 IF p_data->>'schema' IS DISTINCT FROM 'custodial.approved-manual-coverall-activation-data.v1'
  OR jsonb_array_length(p_snapshot->'rosterSlots')<>22 OR p_data->'currentPositions'<>'22'::jsonb
  OR p_data->'additionalCapacityPositions'<>'8'::jsonb OR p_data->'prospectivePositions'<>'30'::jsonb OR p_data->'newEmployees'<>'0'::jsonb
  OR p_data->'weeklyBaselineChanged' IS DISTINCT FROM 'false'::jsonb OR p_data->'registered' IS DISTINCT FROM 'false'::jsonb
  OR p_data->'published' IS DISTINCT FROM 'false'::jsonb OR p_data->'productionWritten' IS DISTINCT FROM 'false'::jsonb
 THEN RAISE EXCEPTION 'Exact original22 plus eight NEW nonemployee capacity DATA required';END IF;
 at:=(p_snapshot->>'serviceDate')::date;end_date:=at+6;
 IF source->>'serviceDate'<>at::text OR source#>>'{version,effectiveStart}'<>at::text
  OR p_data->>'serviceDate'<>at::text OR p_data->>'windowEnd'<>end_date::text
  OR source->>'serviceDate'<>p_data#>>'{capacityTransition,serviceDate}'
  OR p_data->>'sourceDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(source)
  OR source->'exceptions' IS DISTINCT FROM '[]'::jsonb
 THEN RAISE EXCEPTION 'Native capacity activation uses current service date and exact immutable Source';END IF;
 PERFORM public.static_weekly_assert_manual_roster_transition(transition,p_snapshot,p_data->'ownerConfig');
 oldsource:=transition->'projectedSourceDraft';
 IF cp->>'capacityTransitionDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(cp-'capacityTransitionDigest')
  OR cp->>'rosterReadbackDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(p_snapshot)
  OR cp->>'normalRosterTransitionDigest' IS DISTINCT FROM transition->>'transitionDigest'
  OR jsonb_array_length(cp->'selection')<>8 OR jsonb_array_length(source->'slots')<>17
  OR jsonb_array_length(source#>'{version,assignments}')<>346
  OR (SELECT jsonb_agg(x ORDER BY x::text) FROM jsonb_array_elements(source#>'{version,assignments}') x)
   IS DISTINCT FROM(SELECT jsonb_agg(x ORDER BY x::text) FROM jsonb_array_elements(oldsource#>'{version,assignments}') x)
  OR source#>'{version,lunchCoveragePolicy}' IS DISTINCT FROM oldsource#>'{version,lunchCoveragePolicy}'
  OR source->'proximity' IS DISTINCT FROM oldsource->'proximity'
  OR (source->'version')-ARRAY['id','publicationId','status','effectiveStart','namedAbsentSlotIds','vacancyCapableSlotIds','vacantSlotIds','slotAvailability','assignments']
   IS DISTINCT FROM (oldsource->'version')-ARRAY['id','publicationId','status','effectiveStart','namedAbsentSlotIds','vacancyCapableSlotIds','vacantSlotIds','slotAvailability','assignments']
  OR (SELECT jsonb_agg(x ORDER BY x::text) FROM jsonb_array_elements(source#>'{version,slotAvailability}') x)
   IS DISTINCT FROM(SELECT jsonb_agg(x ORDER BY x::text) FROM jsonb_array_elements(oldsource#>'{version,slotAvailability}') x)
 THEN RAISE EXCEPTION 'Shared mapper/roster/normal geometry binding differs';END IF;
 SELECT array_agg(x->>'new_capacity_id') INTO ids FROM jsonb_array_elements(cp->'selection') x;
 IF (SELECT count(DISTINCT x) FROM unnest(ids) x)<>8 OR EXISTS(SELECT 1 FROM public.weekly_roster_slots WHERE slot_id::text=ANY(ids))
  OR (SELECT count(DISTINCT x->>'capacity_code') FROM jsonb_array_elements(cp->'selection') x)<>8
 THEN RAISE EXCEPTION 'Capacity IDs/codes must be eight unique NEW positions';END IF;
 FOR mapping IN SELECT value FROM jsonb_array_elements(cp->'selection') LOOP
  SELECT x INTO STRICT oldslot FROM jsonb_array_elements(oldsource->'slots') x WHERE x->'id'=mapping->'legacy_slot_id' AND x->'contractorCapacity'='true'::jsonb;
  SELECT x INTO STRICT newslot FROM jsonb_array_elements(source->'slots') x WHERE x->'id'=mapping->'new_capacity_id';
  expected:=jsonb_build_object('id',mapping->'new_capacity_id','capacityId',mapping->'new_capacity_id','label',mapping->'capacity_code',
   'kind','CONTRACTOR_CAPACITY','contractorCapacity',true,'incumbencies','[]'::jsonb,'contractorAvailability',oldslot->'contractorAvailability');
  IF newslot IS DISTINCT FROM expected OR EXISTS(SELECT 1 FROM public.static_weekly_contractor_capacity_registrations WHERE capacity_code=mapping->>'capacity_code')
  THEN RAISE EXCEPTION 'Source-bound typed capacity template/codes require explicit reconciliation';END IF;
  PERFORM public.static_weekly_capacity_assert_shape(newslot);
 END LOOP;
 FOR oldslot IN SELECT value FROM jsonb_array_elements(oldsource->'slots') WHERE value->'contractorCapacity' IS DISTINCT FROM 'true'::jsonb LOOP
  SELECT coalesce(jsonb_agg(x ORDER BY n),'[]') INTO actual FROM jsonb_array_elements(oldslot->'incumbencies') WITH ORDINALITY q(x,n)
   WHERE (x->>'effectiveStart')::date<=end_date AND (x->>'effectiveEnd' IS NULL OR (x->>'effectiveEnd')::date>at);
  SELECT x INTO STRICT newslot FROM jsonb_array_elements(source->'slots') x WHERE x->'id'=oldslot->'id';
  IF newslot IS DISTINCT FROM (oldslot||jsonb_build_object('incumbencies',actual)) THEN RAISE EXCEPTION 'Ordinary employee or history facts changed';END IF;
 END LOOP;
 IF p_data#>'{feasibility,candidateSource}' IS DISTINCT FROM source OR p_data#>'{template,source}' IS DISTINCT FROM source
  OR p_data#>'{feasibility,solverInvoked}' IS DISTINCT FROM 'false'::jsonb OR p_data#>'{feasibility,mapping,unchanged}' IS DISTINCT FROM 'true'::jsonb
  OR jsonb_array_length(p_data#>'{feasibility,initialBaseline,projection,assignments}')<>346
  OR jsonb_array_length(p_data#>'{feasibility,lunchDocument,loans}')<>40
 THEN RAISE EXCEPTION 'Existing fixed-pattern adapter snapshot, not a new optimizer receipt, required';END IF;
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_assert_native_projection(p_operation uuid, p_manager uuid, p_envelope jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare ctx jsonb;basis jsonb;snapshot jsonb:=p_envelope->'semantic_snapshot';a jsonb:=p_envelope->'authority';source jsonb;
 frame date;publication uuid;version uuid;expected_dates jsonb;day date;dow integer;normal_day jsonb;day_basis jsonb;plan jsonb;
 item jsonb;w jsonb;parent jsonb;link jsonb;availability jsonb;expected jsonb;actual jsonb;slot jsonb;person jsonb;
 base jsonb;exceptions jsonb;summary jsonb;links jsonb:='{}';expected_availability jsonb:='[]';absent jsonb;
 complete_start text;complete_end text;normal_start text;normal_end text;previous_owner text;previous_end text;
 row_owner text;owner_config jsonb;code text;normal_changed boolean;day_changed boolean;inherited boolean;
 input jsonb;phase jsonb;previous_phase jsonb;slice jsonb;loan jsonb;owners jsonb;points jsonb;anchors jsonb;policy jsonb;
 p_loss numeric;l_loss numeric;n integer;minutes numeric;total_minutes numeric;weighted_p numeric;weighted_l numeric;actual_effort numeric;
 count_rows integer;budget integer;assignment uuid;key text;window_start text;window_end text;
 coverall jsonb;choice_day jsonb;capacity_id text;replaced_id text;is_coverall boolean;employment_employee jsonb;pre_start jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 ctx:=public.static_weekly_pending_context(p_operation,p_manager);
 perform public.static_weekly_assert_exact_object(p_envelope,
  array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','semantic_snapshot','database_projection_identity'],
  array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','semantic_snapshot','database_projection_identity'],'manual native projection');
 perform public.static_weekly_assert_exact_object(snapshot,
  array['schema','originalCommand','originalSource','scopeDates','weekStart','generation','catalogEntryDigest','nativeBasisDigest'],
  array['schema','originalCommand','originalSource','scopeDates','weekStart','generation','catalogEntryDigest','nativeBasisDigest'],'manual native original snapshot');
 if snapshot->>'schema' is distinct from 'custodial.approved-manual-pending-staffing-snapshot.v1'
  or snapshot->'originalCommand' is distinct from ctx->'originalCommand'
  or coalesce(snapshot->>'weekStart','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
  or coalesce(snapshot->>'nativeBasisDigest','')!~'^[0-9a-f]{64}$'
 then raise exception 'Manual native original command differs';end if;
 frame:=(snapshot->>'weekStart')::date;publication:=(snapshot#>>'{originalSource,publication_id}')::uuid;
 basis:=public.static_weekly_manual_period_basis(p_manager,publication,frame,
  (select current_revision from public.static_weekly_schedule_control where singleton),p_operation);
 source:=basis->'normalSource';version:=(basis->>'versionId')::uuid;exceptions:=basis->'preparedExceptions';summary:=basis->'preparedSummary';
 if frame::text is distinct from basis->>'frameStart' or snapshot->'originalSource' is distinct from basis->'originalSource'
  or snapshot->'generation' is distinct from basis->'generation' or snapshot->'catalogEntryDigest' is distinct from basis->'catalogEntryDigest'
  or (not (ctx->>'afterFact')::boolean and snapshot->'nativeBasisDigest' is distinct from basis->'basisDigest')
 then raise exception 'Manual native current Source or preparation basis changed';end if;
 if (ctx->>'afterFact')::boolean and not exists(select 1 from public.static_weekly_staffing_staged_candidates s
  where s.operation_id=p_operation and s.candidate_kind='projection' and s.service_date=frame and s.payload_json->'envelope'=p_envelope)
 then raise exception 'Manual native acceptance must use the exact immutable staged preview';end if;
 select jsonb_agg(d::date::text order by d) into expected_dates from generate_series(
  greatest(frame,(ctx#>>'{originalCommand,semanticBody,startDate}')::date),
  least(frame+6,(ctx#>>'{originalCommand,semanticBody,endDate}')::date),'1 day') d;
 if snapshot->'scopeDates' is distinct from expected_dates or a->'compilerInput' is distinct from source
  or a->>'schema' is distinct from 'custodial.approved-manual-period-projection-authority.v1'
  or a->>'sourceDigest' is distinct from basis->>'normalSourceDigest'
  or a->>'sourcePublicationId' is distinct from publication::text or a->>'sourceVersionId' is distinct from version::text
  or a->>'frameStart' is distinct from frame::text or a->>'frameEnd' is distinct from (frame+6)::text
  or a->'normalSourceChanged' is distinct from 'false'::jsonb or a->'objectiveSolverRerun' is distinct from 'false'::jsonb
  or a->>'acceptedExceptionsDigest' is distinct from public.static_weekly_digest_jsonb(exceptions)
  or a->'employmentRevisionVector' is distinct from basis->'employmentRevisionVector'
  or a->>'formulaObjectiveDigest' is distinct from '7796e95573b389d8d77fc80502d4f6f7f1b54a5155327f9a7f1eb42a7137f531'
  or p_envelope->'applied_exceptions' is distinct from summary
  or p_envelope->'adapter' is distinct from '{"schema":"custodial.approved-manual-period-database-adapter.v1","version":"approved-manual-period-v1"}'::jsonb
  or p_envelope->>'compiler_version' is distinct from 'approved-manual-period-v1'
  or p_envelope->>'service_date' is distinct from frame::text or p_envelope->>'week_start' is distinct from frame::text
  or p_envelope->>'week_end' is distinct from (frame+6)::text
  or p_envelope->>'authority_digest' is distinct from public.static_weekly_digest_jsonb(a)
  or p_envelope->>'database_projection_identity' is distinct from public.static_weekly_digest_jsonb(p_envelope-'database_projection_identity')
  or p_envelope->'objective' is distinct from jsonb_build_object('contract','OWNER_APPROVED_MANUAL_DATED_75_25_V2',
   'formulaObjectiveDigest',a->'formulaObjectiveDigest','proximityPercent',75,'workloadPercent',25,'normalDaysOptimized',false)
  or p_envelope->'metrics' is distinct from jsonb_build_object('hardConstraints',a->'hardConstraintCount','violations',0)
  or p_envelope#>>'{receipt,schema}' is distinct from 'custodial.approved-manual-native-feasibility-data.v1'
  or p_envelope#>'{receipt,hardConstraintCount}' is distinct from a->'hardConstraintCount'
  or p_envelope#>'{receipt,hardConstraintDigest}' is distinct from a->'hardConstraintDigest'
  or p_envelope#>'{receipt,fixedWitnessDigest}' is distinct from a->'fixedWitnessDigest'
 then raise exception 'Manual native envelope identity or approved formula differs';end if;
 if jsonb_typeof(p_envelope->'assignments') is distinct from 'array' or jsonb_array_length(p_envelope->'assignments') not between 1 and 4096
  or jsonb_typeof(a->'datedDayBases') is distinct from 'array' or jsonb_array_length(a->'datedDayBases')>7
  or jsonb_typeof(a->'parentLinks') is distinct from 'array' or jsonb_array_length(a->'parentLinks')>4096
  or jsonb_typeof(a->'projectionAvailability') is distinct from 'array' or jsonb_array_length(a->'projectionAvailability')>224
  or (select count(*)<>count(distinct r->>'plan_work_id') from jsonb_array_elements(p_envelope->'assignments') r)
  or (select count(*)<>count(distinct r->>'serviceDate') from jsonb_array_elements(a->'datedDayBases') r)
  or (select count(*)<>count(distinct r->>'workId') from jsonb_array_elements(a->'parentLinks') r)
 then raise exception 'Manual native bounded unique records required';end if;
 -- This first admission supports full-day canonical PTO/absence and its exact
 -- cancellation. Other exception shapes fail closed, never silently disappear.
 if exists(select 1 from jsonb_array_elements(exceptions) e where (e->>'type' not in('pto','daily_absence') or e ? 'window')
  and (e->>'type' not in('cover_all','lunch') or not e ? 'coverAllChoiceId'
   or not public.static_weekly_coverall_exact_fact(p_operation,p_manager,publication,frame,e)))
 then raise exception using errcode='0A000',message='Manual native exception requires its qualified dated profile';end if;
 policy:=public.static_weekly_manual_absence_policy();
 for base in select value from jsonb_array_elements(source#>'{version,slotAvailability}') loop
  dow:=(base->>'dayOfWeek')::integer;day:=frame+mod(dow-extract(dow from frame)::integer+7,7);
  availability:=public.static_weekly_approved_dated_effective_availability(base,base->>'slotId',day,exceptions);
  if availability->>'status'='working' and (
   exists(select 1 from jsonb_array_elements(exceptions) e
    join jsonb_array_elements(source#>'{version,slotAvailability}') av on av->'slotId'=e#>'{payload,slotId}' and av->>'dayOfWeek'=dow::text and av->>'status'='working'
    where e->>'serviceDate'=day::text and e->>'type' in('pto','daily_absence'))
   or exists(select 1 from jsonb_array_elements(basis->'employmentByDate') ed
    cross join lateral jsonb_array_elements(ed->'employees') ee
    join jsonb_array_elements(source->'slots') es on exists(select 1 from jsonb_array_elements(es->'incumbencies') ei
     where ei->'personId'=ee->'employeeId' and (ei->>'effectiveStart')::date<=day and (ei->>'effectiveEnd' is null or day<(ei->>'effectiveEnd')::date))
    join jsonb_array_elements(source#>'{version,slotAvailability}') ea on ea->'slotId'=es->'id' and ea->>'dayOfWeek'=dow::text and ea->>'status'='working'
    where ed->>'serviceDate'=day::text and (ee#>>'{command,fact,state}'='PRE_START' or day<(ee#>>'{command,fact,firstServiceDate}')::date))) then
   availability:=availability||'{"blockedWindows":[]}'::jsonb;
  end if;
  select s into strict slot from jsonb_array_elements(source->'slots') s where s->'id'=base->'slotId';
  select i into strict person from jsonb_array_elements(slot->'incumbencies') i
   where (i->>'effectiveStart')::date<=day and (i->>'effectiveEnd' is null or day<(i->>'effectiveEnd')::date);
  select e into employment_employee from jsonb_array_elements(basis->'employmentByDate') d
   cross join lateral jsonb_array_elements(d->'employees') e
   where d->>'serviceDate'=day::text and e->'employeeId'=person->'personId';
  if base->>'status'='working' and employment_employee is not null and
   (employment_employee#>>'{command,fact,state}'='PRE_START' or day<(employment_employee#>>'{command,fact,firstServiceDate}')::date) then
   availability:=availability||'{"status":"absent","blockedWindows":[{"start":"00:00","end":"23:59"}],"unavailabilityClassification":"PRE_START_NOT_PTO"}'::jsonb;
  end if;
  expected_availability:=expected_availability||jsonb_build_array(availability||jsonb_build_object(
   'serviceDate',day::text,'incumbentPersonId',person->'personId','incumbentName',person->'displayName'));
 end loop;
 -- Add only the exact selected active capacity; inactive templates do not create employees.
 for day_basis in select value from jsonb_array_elements(a->'datedDayBases') where value->>'kind'='COVERALL' loop
  coverall:=public.static_weekly_coverall_assert_retained_day(p_operation,p_manager,day_basis,publication);
  choice_day:=coverall->'choiceDay';capacity_id:=choice_day->>'capacityId';
  select coalesce(jsonb_agg(r),'[]') into expected_availability from jsonb_array_elements(expected_availability) r
   where not(r->>'serviceDate'=choice_day->>'serviceDate' and r->>'slotId'=capacity_id);
  expected_availability:=expected_availability||jsonb_build_array(public.static_weekly_coverall_capacity_availability(source,choice_day)||jsonb_build_object(
   'serviceDate',choice_day->'serviceDate','incumbentPersonId',null,'incumbentName',null,'ownerKind','CONTRACTOR_CAPACITY','capacityId',capacity_id));
 end loop;
 select coalesce(jsonb_agg(r order by (r->>'dayOfWeek')::integer,r->>'slotId' collate "C"),'[]') into expected from jsonb_array_elements(expected_availability) r;
 select coalesce(jsonb_agg(r order by (r->>'dayOfWeek')::integer,r->>'slotId' collate "C"),'[]') into actual from jsonb_array_elements(a->'projectionAvailability') r;
 if actual is distinct from expected then raise exception 'Manual native static hours, eligibility or actual absence changed';end if;

 for day in select generate_series(frame,frame+6,'1 day')::date loop
  dow:=extract(dow from day)::integer;
  select r into strict normal_day from jsonb_array_elements(policy->'days') r where r->>'weekday'=dow::text;
  select coalesce(jsonb_agg(r->'incumbentPersonId' order by r->>'incumbentPersonId'),'[]') into absent
   from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'status'='absent';
  select coalesce(jsonb_agg(r->'incumbentPersonId' order by r->>'incumbentPersonId'),'[]') into pre_start
   from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'unavailabilityClassification'='PRE_START_NOT_PTO';
  day_changed:=jsonb_array_length(absent)>0;
  select r into day_basis from jsonb_array_elements(a->'datedDayBases') r where r->>'serviceDate'=day::text;
  if day_changed is distinct from (day_basis is not null) then raise exception 'Manual native complete dated day set differs';end if;
  normal_start:=normal_day#>>'{checkedWindow,start}';normal_end:=normal_day#>>'{checkedWindow,end}';
  select max(r#>>'{shift,start}'),max(r#>>'{shift,end}') into complete_start,complete_end
   from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'status'='working';
  if complete_start is null or complete_start>=complete_end then raise exception 'Manual native staffed window is empty';end if;
  is_coverall:=day_basis->>'kind'='COVERALL';coverall:=null;choice_day:=null;capacity_id:=null;replaced_id:=null;
  if coalesce(is_coverall,false) then
   coverall:=public.static_weekly_coverall_assert_retained_day(p_operation,p_manager,day_basis,publication);
   choice_day:=coverall->'choiceDay';capacity_id:=choice_day->>'capacityId';replaced_id:=coverall->>'replacedSlotId';
   if jsonb_array_length(absent)<>3 or absent is distinct from day_basis#>'{overlay,absentPersonIds}' then raise exception 'Exact third actual absence required';end if;
   input:=day_basis->'input';plan:=day_basis->'overlay';
   select coalesce(jsonb_agg(r->'incumbentPersonId' order by r->>'incumbentPersonId'),'[]') into expected
    from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'unavailabilityClassification'='PRE_START_NOT_PTO';
   if coalesce(input->'preStartPersonIds','[]') is distinct from expected then raise exception 'Retained2 pre-start classification differs from current actual employment reads';end if;
   complete_start:=plan#>>'{checkedWindow,start}';complete_end:=plan#>>'{checkedWindow,end}';
  end if;
  if day_changed and not coalesce(is_coverall,false) then
   if jsonb_array_length(absent) not between 1 and 2 or day_basis->>'kind' is distinct from 'ABSENCE' then
    raise exception using errcode='0A000',message='Third absence requires the retained two-absence basis and actual CoverAll hours';end if;
   input:=day_basis->'input';plan:=day_basis->'plan';
   if input->>'inputDigest' is distinct from public.static_weekly_digest_jsonb(input-'inputDigest')
    or plan->>'planDigest' is distinct from public.static_weekly_digest_jsonb(plan-'planDigest')
    or input->'sourceDigest' is distinct from a->'sourceDigest' or input->'formulaObjectiveDigest' is distinct from a->'formulaObjectiveDigest'
    or input->>'serviceDate' is distinct from day::text or plan->>'serviceDate' is distinct from day::text
    or input->'absentPersonIds' is distinct from absent or plan->'absentPersonIds' is distinct from absent
    or coalesce(input->'preStartPersonIds','[]') is distinct from pre_start
    or (jsonb_array_length(pre_start)>0 and input->>'preStartClassification' is distinct from 'PRE_START_NOT_PTO')
    or input->'checkedWindow' is distinct from jsonb_build_object('start',complete_start,'end',complete_end)
    or plan->'checkedWindow' is distinct from input->'checkedWindow' or plan->'inputDigest' is distinct from input->'inputDigest'
    or plan->'proposalDigest' is distinct from a->'formulaObjectiveDigest' or input->'access' is distinct from policy->'access'
    or input->'groups' is distinct from policy->'groups' or plan->'groups' is distinct from policy->'groups'
    or plan->'hardFeasibilityValidatedBeforeScoring' is distinct from 'true'::jsonb or plan->'globalOptimalityClaim' is distinct from 'false'::jsonb
    or exists(select 1 from unnest(array['publicationEligible','weeklyBaselineChanged','productionWritten','contractorBooked']) k where plan->k is distinct from 'false'::jsonb)
   then raise exception 'Manual native dated immutable input, source or formula changed';end if;
   select coalesce(jsonb_agg(jsonb_build_array(r->'slotId',r->'incumbentPersonId',r->'shift',r->'lunch') order by r->>'slotId'),'[]') into expected
    from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'status'='working';
   select coalesce(jsonb_agg(jsonb_build_array(r->'slotId',r->'personId',r->'shift',r->'lunch') order by r->>'slotId'),'[]') into actual from jsonb_array_elements(input->'roster') r;
   if expected is distinct from actual then raise exception 'Manual native dated roster changed';end if;
   for item in select value from jsonb_array_elements(input->'roster') loop
    select r->'baseGroups' into strict expected from jsonb_array_elements(normal_day->'employees') r where r->>'name'=item->>'name';
    select coalesce(jsonb_agg(to_jsonb(r->>'code') order by ord),'[]') into actual
     from jsonb_array_elements(expected) with ordinality x(name,ord) join jsonb_array_elements(policy->'groups') r on r->'name'=name;
    if item->'baseCodes' is distinct from actual then raise exception 'Manual native distance anchor changed from approved normal day';end if;
   end loop;
  end if;

  for item in select value from jsonb_array_elements(p_envelope->'assignments') where value->>'service_date'=day::text loop
   w:=item->'work_snapshot';parent:=null;link:=null;
   select r into parent from jsonb_array_elements(source#>'{version,assignments}') r
    where r->>'dayOfWeek'=dow::text and r->'workId'=item->'work_id';
   if parent is null then
    select r into strict link from jsonb_array_elements(a->'parentLinks') r where r->'workId'=item->'work_id';
    select r into strict parent from jsonb_array_elements(source#>'{version,assignments}') r where r->>'dayOfWeek'=dow::text and r->'workId'=link->'parentWorkId';
    if link->'serviceDate' is distinct from item->'service_date' or link->'window' is distinct from w->'window' or link->'slotId' is distinct from item->'owner_slot_id'
     or coalesce(item->>'work_id','')!~'^manual-dated:[0-9a-f]{64}$' then raise exception 'Manual native parent lineage differs';end if;
   end if;
   select r into strict availability from jsonb_array_elements(expected_availability) r where r->'slotId'=item->'owner_slot_id' and r->>'serviceDate'=day::text;
   if coalesce(is_coverall,false) and item->>'owner_slot_id'=capacity_id then owner_config:='{}';
   else select value into strict owner_config from jsonb_each(basis#>'{ownerConfig,slots}') where value->'slotId'=item->'owner_slot_id';end if;
   window_start:=w#>>'{window,start}';window_end:=w#>>'{window,end}';
   perform public.static_weekly_v3_assert_window(w->'window','manual native custody');
   if item->>'status' is distinct from 'assigned' or item->'reason_code' is distinct from 'null'::jsonb
    or item->>'day_of_week' is distinct from dow::text or item->>'plan_work_id' is distinct from dow::text||':'||(item->>'work_id')
    or item->'owner_person_id' is distinct from availability->'incumbentPersonId' or item->'optimized_owner_person_id' is distinct from item->'owner_person_id'
    or item->'optimized_owner_slot_id' is distinct from item->'owner_slot_id'
    or (case when coalesce(is_coverall,false) and item->>'owner_slot_id'=capacity_id then
      item->>'owner_kind' is distinct from 'CONTRACTOR_CAPACITY' or item->>'capacity_id' is distinct from capacity_id or item->'owner_person_id' is distinct from 'null'::jsonb
     else item ? 'owner_kind' or item ? 'capacity_id' end)
    or availability->>'status' is distinct from 'working' or window_start<availability#>>'{shift,start}' or window_end>availability#>>'{shift,end}'
    or item->'baseline_owner_slot_id' is distinct from parent->'originSlotId' or w->'originSlotId' is distinct from parent->'originSlotId'
   then raise exception 'Manual native actual static owner, window or original actor changed';end if;
   select r into strict base from jsonb_array_elements(expected_availability) r where r->'slotId'=parent->'originSlotId' and r->>'serviceDate'=day::text;
   if item->'baseline_owner_person_id' is distinct from base->'incumbentPersonId' or item->'original_actor_person_id' is distinct from base->'incumbentPersonId'
    or item->'baseline_owner_name' is distinct from base->'incumbentName' or item->'original_actor_name' is distinct from base->'incumbentName'
    or item->>'owner_digest' is distinct from public.static_weekly_digest_jsonb(jsonb_build_object('planWorkId',item->'plan_work_id','slotId',item->'owner_slot_id','personId',item->'owner_person_id','serviceDate',item->'service_date'))
    or item->>'exact_owner_identity' is distinct from public.static_weekly_digest_jsonb(jsonb_build_object('plan_work_id',item->'plan_work_id','service_date',item->'service_date','optimized_owner_slot_id',item->'owner_slot_id','optimized_owner_person_id',item->'owner_person_id','baseline_owner_slot_id',parent->'originSlotId','baseline_owner_person_id',base->'incumbentPersonId'))
   then raise exception 'Manual native owner lineage digest changed';end if;
   inherited:=day_changed and exists(select 1 from jsonb_array_elements(plan->'phaseOwners') with ordinality x(ph,phase_number)
    where phase_number>1 and ph#>>'{window,start}'<=window_start and window_start<ph#>>'{window,end}');
   expected:=jsonb_build_object('workId',item->'work_id','dayOfWeek',dow,'originSlotId',parent->'originSlotId',
    'locationId',parent->'locationId','locationCodeSnapshot',parent->'locationCodeSnapshot','locationNameSnapshot',parent->'locationNameSnapshot',
    'serviceMode',parent->'serviceMode','includedLocations',parent->'includedLocations','window',w->'window',
    'serviceEffortMinutes',w->'serviceEffortMinutes','serviceEffortProvenance',w->'serviceEffortProvenance',
    'priority',parent->'priority','priorityProvenance',parent->'priorityProvenance','required',parent->'required',
    'coveragePolicy',null,'bestEffortCoverage',false,'coveragePolicyOrder',null,'coveragePolicyProvenance',null,
    'requiredQualifications',parent->'requiredQualifications','qualificationProvenance',parent->'qualificationProvenance',
    'restrictions',parent->'restrictions','restrictionProvenance',parent->'restrictionProvenance','restrictedSlotIds',parent->'restrictedSlotIds',
    'manualLock',false,'manualLockSlotId',null,'overlayWork',false);
   if jsonb_array_length(coalesce(parent->'normalAssignmentRestrictedSlotIds','[]'))>0 then
    expected:=expected||jsonb_build_object('normalAssignmentRestrictedSlotIds',parent->'normalAssignmentRestrictedSlotIds','coveragePurpose',parent->'coveragePurpose');
   end if;
   if inherited and dow<>1 and parent->>'locationCodeSnapshot'='HERPETARIUM'
    and parent->'restrictedSlotIds' ? (basis#>>'{ownerConfig,slots,ALIJAH,slotId}') then
    expected:=expected||jsonb_build_object('restrictedSlotIds',(parent->'restrictedSlotIds')-(basis#>>'{ownerConfig,slots,ALIJAH,slotId}'),
     'normalAssignmentRestrictedSlotIds',jsonb_build_array(basis#>>'{ownerConfig,slots,ALIJAH,slotId}'),
     'coveragePurpose','INHERITED_ALERTS_AND_ISSUES_ONLY','restrictionProvenance',(parent->>'restrictionProvenance')||';normal-assignment-scope:fe02bbdebc736d95360b55cc7dfe5b73c5a9eaa76f364f1c0f4420a0afb9950f');
   end if;
   if w is distinct from expected or not ((availability->'qualifications') @> (w->'requiredQualifications'))
    or w->'restrictedSlotIds' ? (item->>'owner_slot_id') or owner_config->'hardForbiddenFamilies' ? (w->>'locationCodeSnapshot')
    or exists(select 1 from jsonb_array_elements(w->'includedLocations') r where availability->'restrictions' ? (r->>'locationId'))
    or (item->>'owner_slot_id'=basis#>>'{ownerConfig,slots,TAMMY,slotId}' and w->>'locationCodeSnapshot' not in('TETON','NORTH_WEST_PASSAGE','EAST_END_RESTROOMS','CHINA'))
   then raise exception 'Manual native physical members, hard eligibility or scoped restriction changed: work %, fields %',item->>'work_id',
    (select coalesce(jsonb_agg(k order by k),'[]') from (select jsonb_object_keys(w||expected) k) q where w->k is distinct from expected->k);end if;
   if not day_changed and (link is not null or item->'owner_slot_id' is distinct from parent->'ownerSlotId' or w->'window' is distinct from parent->'window'
    or w->'serviceEffortMinutes' is distinct from parent->'serviceEffortMinutes' or w->'serviceEffortProvenance' is distinct from parent->'serviceEffortProvenance')
   then raise exception 'Manual native changed an approved normal day';end if;
   if day_changed and ((window_end>parent#>>'{window,end}' and not(coalesce(is_coverall,false) and item->>'owner_slot_id'=capacity_id
     and parent#>>'{window,end}'=normal_end and window_end<=choice_day#>>'{shift,end}')) or window_start<case
    when parent#>>'{window,start}'<=normal_start and parent#>>'{window,end}'>normal_start
     then least(parent#>>'{window,start}',complete_start) else parent#>>'{window,start}' end)
   then raise exception 'Manual native custody exceeds its exact parent boundary';end if;
   -- A single unchanged owner can continue across the complete-crew arrival.
   -- That harmless merged row must still preserve the whole early base prefix.
   if day_changed and window_start<complete_start and ((item->'owner_slot_id' is distinct from parent->'ownerSlotId'
     and not(coalesce(is_coverall,false) and parent->>'ownerSlotId'=replaced_id and item->>'owner_slot_id'=capacity_id))
    or window_start<>parent#>>'{window,start}' or window_end<least(parent#>>'{window,end}',complete_start))
   then raise exception 'Manual native early own-base custody differs';end if;
   if day_changed and window_end>complete_start then
    if window_end>complete_end then raise exception 'Manual native actual full-site window differs';end if;
    for phase in select value from jsonb_array_elements(plan->'phaseOwners') where value#>>'{window,start}'<window_end and window_start<value#>>'{window,end}' loop
     if phase#>>array['owners',w->>'locationCodeSnapshot'] is distinct from item->>'owner_slot_id' then raise exception 'Manual native selected phase differs from stored custody';end if;
    end loop;
   end if;
   select assignment_id into strict assignment from public.weekly_schedule_slot_assignments
    where version_id=version and day_of_week=dow and work_id=parent->>'workId';
   links:=links||jsonb_build_object(item->>'plan_work_id',assignment::text);
  end loop;

  -- Every physical group tiles the complete actual staffed window once.
  for code in select r->>'code' from jsonb_array_elements(policy->'groups') r loop
   previous_end:=complete_start;previous_owner:=null;
   for item in select r from jsonb_array_elements(p_envelope->'assignments') r where r->>'service_date'=day::text
    and r#>>'{work_snapshot,locationCodeSnapshot}'=code and r#>>'{work_snapshot,window,end}'>complete_start
    order by r#>>'{work_snapshot,window,start}' loop
    window_start:=greatest(complete_start,item#>>'{work_snapshot,window,start}');window_end:=least(complete_end,item#>>'{work_snapshot,window,end}');
    if window_end<=window_start then continue;end if;
    if window_start<>previous_end then raise exception 'Manual native full-site gap or overlap';end if;
    if day_changed and previous_owner is not null and previous_owner<>item->>'owner_slot_id' and not exists(
     select 1 from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'slotId'=previous_owner and r#>>'{shift,end}'=window_start)
     and not(coalesce(is_coverall,false) and previous_owner=capacity_id and exists(
      select 1 from jsonb_array_elements(day_basis#>'{input,roster}') retained_owner
       where retained_owner->>'slotId'=replaced_id and retained_owner#>>'{shift,end}'=window_start))
    then raise exception 'Manual native owner moved before the static departure';end if;
    previous_end:=window_end;previous_owner:=item->>'owner_slot_id';
   end loop;
   if previous_end<>complete_end then raise exception 'Manual native full-site coverage incomplete';end if;
   select sum((r->>'serviceEffortMinutes')::integer) into budget from jsonb_array_elements(source#>'{version,assignments}') r where r->>'dayOfWeek'=dow::text and r->>'locationCodeSnapshot'=code;
   select sum((r#>>'{work_snapshot,serviceEffortMinutes}')::integer) into actual_effort from jsonb_array_elements(p_envelope->'assignments') r where r->>'service_date'=day::text and r#>>'{work_snapshot,locationCodeSnapshot}'=code;
   if actual_effort is distinct from budget then raise exception 'Manual native combined group workload budget changed';end if;
  end loop;
  if not day_changed and (select count(*) from jsonb_array_elements(p_envelope->'assignments') r where r->>'service_date'=day::text)
   <>(select count(*) from jsonb_array_elements(source#>'{version,assignments}') r where r->>'dayOfWeek'=dow::text)
  then raise exception 'Manual native omitted approved normal rows';end if;
  if day_changed and not coalesce(is_coverall,false) then
   perform public.static_weekly_manual_assert_absence_score(day_basis,normal_day,policy,expected_availability,p_envelope->'assignments',basis->'ownerConfig');
  end if;
 end loop;
 if (select count(*) from jsonb_object_keys(links))<>jsonb_array_length(p_envelope->'assignments')
  or exists(select 1 from jsonb_array_elements(a->'parentLinks') l where not exists(select 1 from jsonb_array_elements(p_envelope->'assignments') r where r->'work_id'=l->'workId' and r->'service_date'=l->'serviceDate'))
 then raise exception 'Manual native foreign row or unused parent link';end if;
 if (ctx->>'afterFact')::boolean and summary is distinct from public.static_weekly_accepted_exception_set(publication,frame)
 then raise exception 'Manual native original fact did not become exact accepted authority';end if;
 return jsonb_build_object('assignment_links',links,'projection_assignments',p_envelope->'assignments','afterFact',ctx->'afterFact');
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_assert_retained_day(p_operation uuid, p_manager uuid, p_day jsonb, p_publication uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE q record;d jsonb;retained jsonb;input jsonb;plan jsonb;o jsonb:=p_day->'overlay';replaced jsonb;capacity jsonb;template jsonb;
 source jsonb;ph jsonb;owners jsonb;phases jsonb:='[]';lunches jsonb:='[]';roster jsonb:='[]';coverage jsonb:='[]';
 r jsonb;l jsonb;helper jsonb;recipient jsonb;areas jsonb;expected jsonb;actual jsonb;edge text;next_edge text;normal_owner text;actual_owner text;
 checked_end text;normal_end text;capacity_id text;replaced_id text;recipient_id text;coverer_id text;last_edge text;
BEGIN
 SELECT c.*,x.day INTO STRICT q FROM custodial_coverall.choices c CROSS JOIN LATERAL jsonb_array_elements(c.choice_json->'days') x(day)
 WHERE x.day->>'publicationId'=p_publication::text AND x.day->'serviceDate'=p_day->'serviceDate'
  AND x.day->>'overlayDigest'=o->>'overlayDigest'
  AND (c.operation_id=p_operation OR EXISTS(SELECT 1 FROM custodial_coverall.accepted_days a
    JOIN public.static_weekly_staffing_commands cmd USING(operation_id)
    WHERE a.operation_id=c.operation_id AND a.service_date=(p_day->>'serviceDate')::date AND cmd.state='ACCEPTED'
     AND NOT EXISTS(SELECT 1 FROM custodial_coverall.cancellations z WHERE z.original_operation_id=a.operation_id AND z.service_date=a.service_date)));
 d:=q.day;
 IF q.operation_id=p_operation THEN PERFORM public.static_weekly_coverall_validate_choice_day(p_operation,p_manager,d);END IF;
 SELECT x INTO STRICT retained FROM public.weekly_schedule_compiled_projections prior
 CROSS JOIN LATERAL jsonb_array_elements(prior.projection_envelope#>'{authority,datedDayBases}') x
 WHERE prior.projection_id=(d->>'retainedProjectionId')::uuid AND prior.publication_id=p_publication
  AND prior.projection_envelope->>'database_projection_identity'=d->>'retainedEnvelopeIdentity'
  AND x->'serviceDate'=p_day->'serviceDate';
 input:=retained->'input';plan:=retained->'plan';
 SELECT canonical_source INTO STRICT source FROM public.static_weekly_authority_source_documents WHERE source_id=(d->>'sourceId')::uuid;
 source:=jsonb_set(source,'{serviceDate}',to_jsonb((SELECT week_start::text FROM public.weekly_schedule_compiled_projections WHERE projection_id=(d->>'retainedProjectionId')::uuid)),true);
 SELECT r0 INTO STRICT replaced FROM jsonb_array_elements(input->'roster') r0 WHERE r0->>'personId'=q.choice_json#>>'{canonicalSemanticBody,employeeId}';
 SELECT s INTO STRICT capacity FROM jsonb_array_elements(source->'slots') s WHERE s->'id'=d->'capacityId';
 PERFORM public.static_weekly_capacity_assert_shape(capacity);IF NOT public.static_weekly_capacity_registered(capacity) THEN RAISE EXCEPTION 'Unregistered CoverAll retained owner';END IF;
 SELECT a INTO STRICT template FROM jsonb_array_elements(capacity->'contractorAvailability') a WHERE a->'dayOfWeek'=input->'weekday';
 IF p_day->>'kind'<>'COVERALL' OR p_day->'input' IS DISTINCT FROM input OR p_day->'plan' IS DISTINCT FROM plan
  OR plan->>'planDigest' IS DISTINCT FROM d->>'retainedPlanDigest' OR plan->>'planDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(plan-'planDigest')
  OR o->>'overlayDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(o-'overlayDigest')
  OR o->>'sourceDigest' IS DISTINCT FROM input->>'sourceDigest' OR input->>'sourceDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(source)
  OR o->>'acceptedPlanDigest' IS DISTINCT FROM plan->>'planDigest'
  OR o->>'replacedPersonId' IS DISTINCT FROM replaced->>'personId'
  OR o->'substitute' IS DISTINCT FROM jsonb_build_object('slotId',d->'capacityId','kind','CONTRACTOR_CAPACITY','shift',d->'shift','lunch',d->'lunch',
    'confirmationReference',d->'confirmationReference','actualHoursConfirmed',true,'managerConfirmationIsCallerInput',true)
 THEN RAISE EXCEPTION 'Original two-absence plan/input or actual-hours overlay identity changed';END IF;
 PERFORM public.static_weekly_assert_exact_object(o,
 ARRAY['schema','status','serviceDate','acceptedPlanDigest','sourceDigest','absentPersonIds','replacedPersonId','substitute','checkedWindow','phaseOwners','lunchPlans','coverage','roster','groups','conservedRatingTotal','solverInvoked','scoringRerun','otherNormalOwnersChanged','weeklyBaselineChanged','formulaApproved','publicationEligible','productionWritten','contractorBooked','overlayDigest']||CASE WHEN o->>'schema'='custodial.approved-manual-coverall-overlay.v2' THEN ARRAY['normalCoverageWindow','confirmedCoverageExtension'] ELSE ARRAY[]::text[] END,
 ARRAY['schema','status','serviceDate','acceptedPlanDigest','sourceDigest','absentPersonIds','replacedPersonId','substitute','checkedWindow','phaseOwners','lunchPlans','coverage','roster','groups','conservedRatingTotal','solverInvoked','scoringRerun','otherNormalOwnersChanged','weeklyBaselineChanged','formulaApproved','publicationEligible','productionWritten','contractorBooked','overlayDigest']||CASE WHEN o->>'schema'='custodial.approved-manual-coverall-overlay.v2' THEN ARRAY['normalCoverageWindow','confirmedCoverageExtension'] ELSE ARRAY[]::text[] END,'exact mechanical CoverAll overlay');
 capacity_id:=d->>'capacityId';replaced_id:=replaced->>'slotId';normal_end:=input#>>'{checkedWindow,end}';checked_end:=greatest(normal_end,d#>>'{shift,end}');
 FOR ph IN SELECT value FROM jsonb_array_elements(plan->'phaseOwners') LOOP
  SELECT jsonb_object_agg(key,CASE WHEN value=to_jsonb(replaced_id) THEN to_jsonb(capacity_id) ELSE value END) INTO owners FROM jsonb_each(ph->'owners');
  phases:=phases||jsonb_build_array(jsonb_build_object('window',ph->'window','owners',owners));
 END LOOP;
 IF checked_end>normal_end THEN
  SELECT jsonb_object_agg(g->>'code',capacity_id) INTO owners FROM jsonb_array_elements(input->'groups') g;
  phases:=phases||jsonb_build_array(jsonb_build_object('window',jsonb_build_object('start',normal_end,'end',checked_end),'owners',owners));
 END IF;
 IF o->'phaseOwners' IS DISTINCT FROM phases OR o->'checkedWindow' IS DISTINCT FROM jsonb_build_object('start',input#>'{checkedWindow,start}','end',checked_end)
 THEN RAISE EXCEPTION 'Only third owner replacement and confirmed later ALL-area inheritance allowed';END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(input->'roster') WHERE value->>'slotId'<>replaced_id LOOP
  roster:=roster||jsonb_build_array(jsonb_build_object('slotId',r->'slotId','personId',r->'personId','name',r->'name','shift',r->'shift','lunch',r->'lunch','kind','EMPLOYEE'));
 END LOOP;
 roster:=roster||jsonb_build_array(jsonb_build_object('slotId',capacity_id,'name',capacity->'label','kind','CONTRACTOR_CAPACITY','shift',d->'shift','lunch',d->'lunch','replacesPersonId',replaced->'personId'));
 IF o->'roster' IS DISTINCT FROM roster THEN RAISE EXCEPTION 'Other normal owners or actual static end times changed';END IF;
 FOR l IN SELECT value FROM jsonb_array_elements(plan->'lunchPlans') LOOP
  recipient_id:=CASE WHEN l->>'recipientSlotId'=replaced_id THEN capacity_id ELSE l->>'recipientSlotId' END;
  coverer_id:=CASE WHEN l->>'recipientSlotId'=replaced_id THEN d->>'lunchCovererSlotId' WHEN l->>'covererSlotId'=replaced_id THEN capacity_id ELSE l->>'covererSlotId' END;
  expected:=CASE WHEN l->>'recipientSlotId'=replaced_id THEN d->'lunch' ELSE l->'window' END;
  SELECT coalesce(jsonb_agg(to_jsonb(code) ORDER BY code),'[]') INTO areas FROM(
   SELECT DISTINCT own.key code FROM jsonb_array_elements(phases) phase CROSS JOIN LATERAL jsonb_each(phase->'owners') own
   WHERE phase#>>'{window,start}'<expected->>'end' AND expected->>'start'<phase#>>'{window,end}' AND own.value=to_jsonb(recipient_id)) a;
  lunches:=lunches||jsonb_build_array(jsonb_build_object('recipientSlotId',recipient_id,'covererSlotId',coverer_id,'window',expected,'areas',areas));
  SELECT v INTO STRICT recipient FROM jsonb_array_elements(roster) v WHERE v->>'slotId'=recipient_id;
  SELECT v INTO STRICT helper FROM jsonb_array_elements(roster) v WHERE v->>'slotId'=coverer_id;
  IF recipient_id=coverer_id OR expected->>'start'<recipient#>>'{shift,start}' OR expected->>'end'>recipient#>>'{shift,end}'
   OR expected->>'start'<helper#>>'{shift,start}' OR expected->>'end'>helper#>>'{shift,end}'
   OR (expected->>'end')::time-(expected->>'start')::time<>interval '1 hour'
   OR (expected->>'start'<helper#>>'{lunch,end}' AND helper#>>'{lunch,start}'<expected->>'end')
  THEN RAISE EXCEPTION 'Actual full-hour helper is unavailable';END IF;
 END LOOP;
 IF o->'lunchPlans' IS DISTINCT FROM lunches OR EXISTS(SELECT 1 FROM jsonb_array_elements(lunches) a,jsonb_array_elements(lunches) b
  WHERE a<>b AND a->'covererSlotId'=b->'covererSlotId' AND a#>>'{window,start}'<b#>>'{window,end}' AND b#>>'{window,start}'<a#>>'{window,end}')
 THEN RAISE EXCEPTION 'Only matched third-owner lunch substitution is allowed';END IF;
 -- Same real time-slice edges as the maintained pure substitute; no score or optimizer.
 last_edge:=NULL;
 FOR edge IN SELECT DISTINCT t FROM(
  SELECT input#>>'{checkedWindow,start}' t UNION SELECT checked_end
  UNION SELECT phase#>>'{window,start}' FROM jsonb_array_elements(phases) phase
  UNION SELECT phase#>>'{window,end}' FROM jsonb_array_elements(phases) phase
  UNION SELECT v#>>'{shift,start}' FROM jsonb_array_elements(roster) v UNION SELECT v#>>'{shift,end}' FROM jsonb_array_elements(roster) v
  UNION SELECT v#>>'{lunch,start}' FROM jsonb_array_elements(roster) v UNION SELECT v#>>'{lunch,end}' FROM jsonb_array_elements(roster) v
 ) edges WHERE t BETWEEN input#>>'{checkedWindow,start}' AND checked_end ORDER BY t LOOP
  IF last_edge IS NULL THEN last_edge:=edge;CONTINUE;END IF;
  SELECT phase INTO STRICT ph FROM jsonb_array_elements(phases) phase WHERE phase#>>'{window,start}'<=last_edge AND last_edge<phase#>>'{window,end}';owners:='{}';
  FOR r IN SELECT value FROM jsonb_array_elements(input->'groups') LOOP
   normal_owner:=ph#>>ARRAY['owners',r->>'code'];SELECT v INTO STRICT recipient FROM jsonb_array_elements(roster) v WHERE v->>'slotId'=normal_owner;
   IF recipient#>>'{shift,start}'>last_edge OR recipient#>>'{shift,end}'<edge THEN RAISE EXCEPTION 'Confirmed hours miss retained duty; no invented earlier capacity';END IF;
   actual_owner:=normal_owner;
   IF recipient#>>'{lunch,start}'<=last_edge AND last_edge<recipient#>>'{lunch,end}' THEN
    SELECT v->>'covererSlotId' INTO STRICT actual_owner FROM jsonb_array_elements(lunches) v WHERE v->>'recipientSlotId'=normal_owner;
   END IF;
   SELECT v INTO STRICT helper FROM jsonb_array_elements(roster) v WHERE v->>'slotId'=actual_owner;
   IF helper#>>'{shift,start}'>last_edge OR helper#>>'{shift,end}'<edge OR (helper#>>'{lunch,start}'<=last_edge AND last_edge<helper#>>'{lunch,end}')
   THEN RAISE EXCEPTION 'Actual lunch coverage missing';END IF;
   if actual_owner=capacity_id then
    SELECT area->'work' INTO STRICT actual FROM jsonb_array_elements(input->'phases') WITH ORDINALITY x(phase,n)
     CROSS JOIN LATERAL jsonb_array_elements(phase->'areas') area
     WHERE n=least((SELECT ord FROM jsonb_array_elements(phases) WITH ORDINALITY y(v,ord) WHERE v=ph),jsonb_array_length(input->'phases')) AND area->'code'=r->'code';
    IF NOT((template->'qualifications') @> (actual->'requiredQualifications')) OR template->'restrictions' ? (actual->>'locationId') OR actual->'restrictedSlotIds' ? capacity_id
    THEN RAISE EXCEPTION 'CoverAll actual source qualification or physical restriction differs';END IF;
   elsif actual_owner<>normal_owner then
    if NOT(input->'reliefEligibility' ? ((least((SELECT ord FROM jsonb_array_elements(phases) WITH ORDINALITY y(v,ord) WHERE v=ph),jsonb_array_length(input->'phases'))-1)::text||':'||(r->>'code')||':'||actual_owner)) then raise exception 'Unqualified original relief helper';end if;
    SELECT v INTO STRICT helper FROM jsonb_array_elements(input->'roster') v WHERE v->>'slotId'=actual_owner;
    IF helper#>>'{owner,key}'='TAMMY' AND r->>'code'='CHINA' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(plan->'coverage') c WHERE c#>>'{window,start}'<=last_edge AND last_edge<c#>>'{window,end}' AND c#>>'{owners,CHINA}'=actual_owner)
    THEN RAISE EXCEPTION 'CoverAll cannot introduce new Tammy extras';END IF;
   end if;
   owners:=owners||jsonb_build_object(r->>'code',actual_owner);
  END LOOP;
  IF (SELECT count(*) FROM jsonb_object_keys(owners))<>23 THEN RAISE EXCEPTION 'All23 areas required after every clockout';END IF;
  coverage:=coverage||jsonb_build_array(jsonb_build_object('window',jsonb_build_object('start',last_edge,'end',edge),'owners',owners,
   'zooWideCoverage',(SELECT count(*)=1 FROM jsonb_array_elements(roster) v WHERE v#>>'{shift,start}'<=last_edge AND v#>>'{shift,end}'>=edge)));
  last_edge:=edge;
 END LOOP;
 SELECT jsonb_agg(id ORDER BY id) INTO actual FROM(SELECT value id FROM jsonb_array_elements(input->'absentPersonIds') UNION ALL SELECT replaced->'personId') a;
 IF o->'coverage' IS DISTINCT FROM coverage OR o->'absentPersonIds' IS DISTINCT FROM actual OR o->'groups' IS DISTINCT FROM input->'groups'
  OR o->'conservedRatingTotal'<>'136'::jsonb OR o->>'status'<>'VALIDATED_UNPUBLISHED_COVERALL_OVERLAY'
  OR o->'formulaApproved' IS DISTINCT FROM 'true'::jsonb
  OR EXISTS(SELECT 1 FROM unnest(ARRAY['solverInvoked','scoringRerun','otherNormalOwnersChanged','weeklyBaselineChanged','publicationEligible','productionWritten','contractorBooked']) k WHERE o->k IS DISTINCT FROM 'false'::jsonb)
 THEN RAISE EXCEPTION 'CoverAll exact mechanical coverage, rating or non-publication facts differ';END IF;
 IF checked_end>normal_end THEN
  IF o->>'schema'<>'custodial.approved-manual-coverall-overlay.v2' OR o->'normalCoverageWindow' IS DISTINCT FROM input->'checkedWindow'
   OR o->'confirmedCoverageExtension' IS DISTINCT FROM jsonb_build_object('beforeNormalMinutes',0,
    'afterNormalMinutes',extract(epoch FROM(checked_end::time-normal_end::time))::integer/60,'ownerSlotId',capacity_id,'purpose','INHERITED_ALERTS_AND_ISSUES_ONLY','employeeShiftExtensions',false)
  THEN RAISE EXCEPTION 'Later actual contractor hours may only inherit ALL areas';END IF;
 ELSIF o->>'schema'<>'custodial.approved-manual-coverall-overlay.v1' OR o?'confirmedCoverageExtension' OR o?'normalCoverageWindow'
 THEN RAISE EXCEPTION 'Unexpected normal-window extension';END IF;
 RETURN jsonb_build_object('choiceDay',d,'retained',retained,'overlay',o,'replacedSlotId',replaced_id);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_bind_actor(p_operation uuid, p_manager uuid, p_credential uuid, p_device text, p_access text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.static_weekly_staffing_commands%rowtype;prior custodial_coverall.request_actors%rowtype;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();
 PERFORM public.custodial_action_actor_v1(p_manager,p_credential,p_device,p_access,'manage_coverall');
 PERFORM public.custodial_begin_application_mutation();
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 SELECT * INTO STRICT c FROM public.static_weekly_staffing_commands WHERE operation_id=p_operation FOR UPDATE;
 IF c.state<>'PREPARING' OR c.prepared_by_manager_id<>p_manager THEN RAISE EXCEPTION 'Original PREPARING actor required';END IF;
 SELECT * INTO prior FROM custodial_coverall.request_actors WHERE operation_id=p_operation;
 IF FOUND THEN
  IF prior.manager_id<>p_manager OR prior.credential_id<>p_credential OR prior.device_id<>p_device OR prior.session_access<>p_access THEN RAISE EXCEPTION 'Original supplementary actor binding changed';END IF;
 ELSE INSERT INTO custodial_coverall.request_actors VALUES(p_operation,p_manager,p_credential,p_device,p_access);END IF;
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_capacity_availability(p_source jsonb, p_day jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE slot jsonb;template jsonb;day integer:=extract(dow FROM (p_day->>'serviceDate')::date)::integer;minutes integer;
BEGIN
 SELECT s INTO STRICT slot FROM jsonb_array_elements(p_source->'slots') s WHERE s->>'id'=p_day->>'capacityId';
 PERFORM public.static_weekly_capacity_assert_shape(slot);IF NOT public.static_weekly_capacity_registered(slot) THEN RAISE EXCEPTION 'Unregistered source capacity';END IF;
 SELECT t INTO STRICT template FROM jsonb_array_elements(slot->'contractorAvailability') t WHERE t->>'dayOfWeek'=day::text;
 minutes:=extract(epoch FROM ((p_day#>>'{shift,end}')::time-(p_day#>>'{shift,start}')::time))::integer/60-60;
 IF minutes<=0 THEN RAISE EXCEPTION 'Actual productive capacity is empty';END IF;
 RETURN (template-'breakChoice')||jsonb_build_object('slotId',slot->'id','dayOfWeek',day,'status','working','shift',p_day->'shift',
  'lunch',(p_day->'lunch')||jsonb_build_object('startMinute',extract(epoch FROM (p_day#>>'{lunch,start}')::time)::integer/60,'endMinute',extract(epoch FROM (p_day#>>'{lunch,end}')::time)::integer/60),
  'maxDutyMinutes',minutes,'maxDutyProvenance',template->'productiveCapacityProvenance','blockedWindows','[]'::jsonb);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_day_facts(p_operation uuid, p_day jsonb, p_manager uuid, p_revision bigint, p_choice uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE source jsonb;availability jsonb;version uuid;base jsonb;cover jsonb;lunch jsonb;
BEGIN
 SELECT s.canonical_source,v.version_id INTO STRICT source,version FROM public.static_weekly_authority_source_documents s
 JOIN public.weekly_schedule_versions v ON v.authority_source_id=s.source_id JOIN public.weekly_schedule_publications p USING(version_id)
 WHERE s.source_id=(p_day->>'sourceId')::uuid AND p.publication_id=(p_day->>'publicationId')::uuid;
 availability:=public.static_weekly_coverall_capacity_availability(source,p_day);
 base:=jsonb_build_object('baseVersionId',version,'publicationId',p_day->'publicationId','serviceDate',p_day->'serviceDate',
  'actorId',p_manager,'expectedRevision',p_revision,'reason','Actual manager-confirmed source-bound third-absence capacity','sequence',p_revision+1,'coverAllChoiceId',p_choice,'coverAllOperationId',p_operation);
 cover:=base||jsonb_build_object('id','coverall:'||p_operation||':'||(p_day->>'serviceDate'),
  'type','cover_all','payload',jsonb_build_object('availability',availability),'idempotencyKey','coverall:'||p_operation||':'||(p_day->>'serviceDate'));
 lunch:=base||jsonb_build_object('id','coverall-lunch:'||p_operation||':'||(p_day->>'serviceDate'),
  'type','lunch','window',p_day->'lunch','payload',jsonb_build_object('slotId',p_day->'capacityId'),
  'idempotencyKey','coverall-lunch:'||p_operation||':'||(p_day->>'serviceDate'));
 RETURN jsonb_build_array(cover||jsonb_build_object('payloadDigest',public.static_weekly_digest_jsonb(cover->'payload')),
  lunch||jsonb_build_object('payloadDigest',public.static_weekly_digest_jsonb(jsonb_build_object('payload',lunch->'payload','window',lunch->'window'))));
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_event_brief_candidate(p_manager_id uuid, p_event_id uuid, p_event_revision integer, p_capacity_slot_id uuid, p_service_date date, p_projection_id uuid, p_expected_authority_revision bigint, p_lunch_document_identity text, p_print_document_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
 v_manager public.ops_manager_managers%rowtype;
 v_authority record;
 v_control_revision bigint;
 v_capacity public.static_weekly_contractor_capacity_registrations%rowtype;
 v_lunch public.weekly_schedule_lunch_documents%rowtype;
 v_lunch_read jsonb;
 v_event public.events_app_events%rowtype;
 v_place jsonb;
 v_areas jsonb;
 v_replay_digest text;
begin
 if p_manager_id is null or p_event_id is null or p_event_revision is null or p_event_revision<1
  or p_capacity_slot_id is null or p_service_date is null or p_projection_id is null
  or p_expected_authority_revision is null or p_expected_authority_revision<1
  or coalesce(p_lunch_document_identity,'') !~ '^[0-9a-f]{64}$'
  or coalesce(p_print_document_digest,'') !~ '^[0-9a-f]{64}$' then
  raise exception using errcode='22023',message='exact manager, event, capacity and accepted print basis required';
 end if;
 select * into v_manager from public.ops_manager_managers where manager_id=p_manager_id;
 if v_manager.manager_id is null or v_manager.active is not true or v_manager.revoked_at is not null
  or v_manager.is_system_principal is true
  or (v_manager.roles && array['OPS_MANAGER','CUSTODIAL_MANAGER','DIRECTOR','SECURITY_ADMIN']::text[]) is not true then
  raise exception using errcode='42501',message='active named manager required for contractor Event brief';
 end if;
 select current_revision into v_control_revision from public.static_weekly_schedule_control where singleton;
 select * into v_authority from public.static_weekly_v6_schedule_authority_state(p_service_date);
 if v_control_revision is distinct from p_expected_authority_revision
  or v_authority.governed is not true or v_authority.projection_status is distinct from 'current'
  or v_authority.projection_id is distinct from p_projection_id then
  return jsonb_build_object('schema','custodial.coverall-event-brief-candidate.v1',
   'status','STALE_PRINT_BASIS','disclosure_approved',false);
 end if;
 select * into v_capacity from public.static_weekly_contractor_capacity_registrations
  where capacity_slot_id=p_capacity_slot_id;
 if v_capacity.capacity_slot_id is null or not public.static_weekly_capacity_registered(v_capacity.slot_snapshot)
  or not exists(select 1 from jsonb_array_elements(public.static_weekly_compiler_exception_set(
    v_authority.publication_id,v_authority.week_start)) item(value)
    where item.value->>'type'='cover_all' and item.value->>'serviceDate'=p_service_date::text
      and item.value#>>'{payload,availability,slotId}'=p_capacity_slot_id::text) then
  return jsonb_build_object('schema','custodial.coverall-event-brief-candidate.v1',
   'status','CAPACITY_NOT_ACCEPTED','disclosure_approved',false);
 end if;
 select * into v_lunch from public.weekly_schedule_lunch_documents
  where projection_id=p_projection_id;
 v_lunch_read:=public.static_weekly_v8_read_lunch_document(p_service_date);
 if v_lunch.projection_id is null or v_lunch.document_identity is distinct from p_lunch_document_identity
  or v_lunch_read->>'persistence_status' is distinct from 'PERSISTED'
  or v_lunch_read->>'document_identity' is distinct from p_lunch_document_identity
  or v_lunch_read->>'projection_id' is distinct from p_projection_id::text then
  return jsonb_build_object('schema','custodial.coverall-event-brief-candidate.v1',
   'status','STALE_PRINT_BASIS','disclosure_approved',false);
 end if;
 select replay_digest into v_replay_digest from public.weekly_schedule_compiled_projections
  where projection_id=p_projection_id and publication_id=v_authority.publication_id
   and version_id=v_authority.version_id;
 if v_replay_digest is null then
  return jsonb_build_object('schema','custodial.coverall-event-brief-candidate.v1',
   'status','STALE_PRINT_BASIS','disclosure_approved',false);
 end if;
 select * into v_event from public.events_app_events where id=p_event_id;
 if v_event.id is null or v_event.revision is distinct from p_event_revision
  or v_event.status is distinct from 'SCHEDULED' or coalesce(v_event.needs_review,false)
  or v_event.event_scope='UNKNOWN' or v_event.cancelled_at is not null
  or v_event.archived_at is not null or v_event.superseded_by_event_id is not null
  or v_event.start_instant_utc is null or v_event.end_instant_utc is null
  or v_event.end_instant_utc<=v_event.start_instant_utc
  or v_event.event_date is distinct from p_service_date
  or (v_event.start_instant_utc at time zone 'America/Chicago')::date is distinct from p_service_date
  or coalesce(cardinality(v_event.coverage_location_ids),0)=0 then
  return jsonb_build_object('schema','custodial.coverall-event-brief-candidate.v1',
   'status','EVENT_NOT_CURRENT_OR_UNSCOPED','disclosure_approved',false);
 end if;
 v_place:=public.app_event_place_authority(to_jsonb(v_event),statement_timestamp());
 if (v_place->>'admissible')::boolean is not true then
  return jsonb_build_object('schema','custodial.coverall-event-brief-candidate.v1',
   'status','EVENT_PLACE_NEEDS_REVIEW','disclosure_approved',false);
 end if;
 -- The typed readers prove current group/physical identities. Ordinary
 -- ownership and exact accepted lunch loans are separate branches. No Event
 -- venue or display-name equivalence is used as custodial coverage.
 with ordinary as (
  select s.location_group_id,s.group_name,s.coverage_start::time as starts,
   s.coverage_end::time as ends,s.included_location_ids,'area_owner'::text as purpose
  from public.static_weekly_v6_read_schedule_segments(p_service_date) s
  join public.weekly_schedule_occurrences o on o.occurrence_id=s.segment_id
  where s.projection_id=p_projection_id and s.status='ASSIGNED' and s.owner_type='COVERALL'
   and s.service_mode='scan_tracked' and cardinality(s.included_location_ids)>0
   and o.owner_kind='CONTRACTOR_CAPACITY' and o.owner_capacity_id=p_capacity_slot_id
 ), temporary as (
  select s.location_group_id,s.group_name,s.coverage_start starts,s.coverage_end ends,
   s.included_location_ids,'lunch_coverage'::text purpose
  from public.static_weekly_v8_read_lunch_segments(p_service_date) s
  join jsonb_array_elements(v_lunch.document_json->'responsibilities') r(value)
   on r.value->>'responsibility_id'=s.responsibility_id
  where s.projection_id=p_projection_id and s.service_mode='scan_tracked'
   and cardinality(s.included_location_ids)>0
   and r.value->>'coverer_slot_id'=p_capacity_slot_id::text
   and r.value->>'coverer_capacity_id'=p_capacity_slot_id::text
   and r.value->'coverer_person_id'='null'::jsonb
 ), matched as (
  select distinct * from (select * from ordinary union all select * from temporary) areas
  where areas.location_group_id=any(v_event.coverage_location_ids)
 ) select coalesce(jsonb_agg(jsonb_build_object('location_group_id',location_group_id,
    'group_name',group_name,'starts',to_char(starts,'HH24:MI'),
    'ends',to_char(ends,'HH24:MI'),'included_location_ids',included_location_ids,
    'purpose',purpose) order by starts,ends,location_group_id,purpose),'[]'::jsonb)
  into v_areas from matched;
 if jsonb_array_length(v_areas)=0 then
  return jsonb_build_object('schema','custodial.coverall-event-brief-candidate.v1',
   'status','NO_MATCHED_ACCEPTED_COVERAGE','disclosure_approved',false);
 end if;
 return jsonb_build_object('schema','custodial.coverall-event-brief-candidate.v1',
  'status','PREVIEW_ONLY','disclosure_approved',false,
  'manager_id',p_manager_id,'capacity_slot_id',p_capacity_slot_id,
  'service_date',p_service_date,'projection_id',p_projection_id,
  'publication_id',v_authority.publication_id,
  'authority_revision',v_control_revision,'projection_replay_digest',v_replay_digest,
  'lunch_document_identity',p_lunch_document_identity,
  'print_document_digest',p_print_document_digest,
  'event_id',v_event.id,'event_revision',v_event.revision,
  'event_name',v_event.event_name,
  'display_location',coalesce(nullif(v_place->>'primary_display_name',''),v_event.display_location),
  'event_date',v_event.event_date,
  'start_instant_utc',v_event.start_instant_utc,'end_instant_utc',v_event.end_instant_utc,
  'start_time',v_event.start_time,'end_time',v_event.end_time,
  'custodial_note_codes',v_event.custodial_note_codes,
  'custodial_public_notes',v_event.custodial_public_notes,
  'matched_areas',v_areas);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_event_brief_candidates(p_manager_id uuid, p_capacity_slot_id uuid, p_service_date date, p_projection_id uuid, p_expected_authority_revision bigint, p_lunch_document_identity text, p_print_document_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
 v_manager public.ops_manager_managers%rowtype;
 v_authority record;
 v_control_revision bigint;
 v_capacity public.static_weekly_contractor_capacity_registrations%rowtype;
 v_lunch public.weekly_schedule_lunch_documents%rowtype;
 v_lunch_read jsonb;
 v_event record;
 v_row jsonb;
 v_rows jsonb:='[]'::jsonb;
 v_count integer:=0;
 v_scanned integer;
 v_replay_digest text;
begin
 if p_manager_id is null or p_capacity_slot_id is null or p_service_date is null
  or p_projection_id is null or p_expected_authority_revision is null
  or p_expected_authority_revision<1
  or coalesce(p_lunch_document_identity,'') !~ '^[0-9a-f]{64}$'
  or coalesce(p_print_document_digest,'') !~ '^[0-9a-f]{64}$' then
  raise exception using errcode='22023',message='exact manager, capacity and accepted print basis required';
 end if;
 select * into v_manager from public.ops_manager_managers where manager_id=p_manager_id;
 if v_manager.manager_id is null or v_manager.active is not true or v_manager.revoked_at is not null
  or v_manager.is_system_principal is true
  or (v_manager.roles && array['OPS_MANAGER','CUSTODIAL_MANAGER','DIRECTOR','SECURITY_ADMIN']::text[]) is not true then
  raise exception using errcode='42501',message='active named manager required for contractor Event list';
 end if;
 select current_revision into v_control_revision from public.static_weekly_schedule_control where singleton;
 select * into v_authority from public.static_weekly_v6_schedule_authority_state(p_service_date);
 select p.replay_digest into v_replay_digest from public.weekly_schedule_compiled_projections p
  where p.projection_id=p_projection_id and p.publication_id=v_authority.publication_id
   and p.version_id=v_authority.version_id;
 if v_control_revision is distinct from p_expected_authority_revision
  or v_authority.governed is not true or v_authority.projection_status is distinct from 'current'
  or v_authority.projection_id is distinct from p_projection_id
  or coalesce(v_replay_digest,'') !~ '^[0-9a-f]{64}$' then
  return jsonb_build_object('schema','custodial.coverall-event-brief-list.v1',
   'status','STALE_PRINT_BASIS','disclosure_approved',false,'candidates','[]'::jsonb);
 end if;
 select * into v_capacity from public.static_weekly_contractor_capacity_registrations
  where capacity_slot_id=p_capacity_slot_id;
 if v_capacity.capacity_slot_id is null or not public.static_weekly_capacity_registered(v_capacity.slot_snapshot)
  or not exists(select 1 from jsonb_array_elements(public.static_weekly_compiler_exception_set(
    v_authority.publication_id,v_authority.week_start)) item(value)
    where item.value->>'type'='cover_all' and item.value->>'serviceDate'=p_service_date::text
      and item.value#>>'{payload,availability,slotId}'=p_capacity_slot_id::text) then
  return jsonb_build_object('schema','custodial.coverall-event-brief-list.v1',
   'status','CAPACITY_NOT_ACCEPTED','disclosure_approved',false,'candidates','[]'::jsonb);
 end if;
 select * into v_lunch from public.weekly_schedule_lunch_documents where projection_id=p_projection_id;
 v_lunch_read:=public.static_weekly_v8_read_lunch_document(p_service_date);
 if v_lunch.projection_id is null or v_lunch.document_identity is distinct from p_lunch_document_identity
  or v_lunch_read->>'persistence_status' is distinct from 'PERSISTED'
  or v_lunch_read->>'document_identity' is distinct from p_lunch_document_identity
  or v_lunch_read->>'projection_id' is distinct from p_projection_id::text then
  return jsonb_build_object('schema','custodial.coverall-event-brief-list.v1',
   'status','STALE_PRINT_BASIS','disclosure_approved',false,'candidates','[]'::jsonb);
 end if;
 select count(*) into v_scanned from (
  select 1 from public.events_app_events e
   where e.event_date=p_service_date and e.status='SCHEDULED'
   order by e.start_instant_utc,e.id limit 33
 ) bounded;
 if v_scanned>32 then
  return jsonb_build_object('schema','custodial.coverall-event-brief-list.v1',
   'status','LIMIT_EXCEEDED','limit_reason','same_day_scan','disclosure_approved',false,
   'candidates','[]'::jsonb);
 end if;
 for v_event in select e.id,e.revision from public.events_app_events e
  where e.event_date=p_service_date and e.status='SCHEDULED'
  order by e.start_instant_utc,e.id
 loop
  v_row:=public.static_weekly_coverall_event_brief_candidate(p_manager_id,v_event.id,
    v_event.revision,p_capacity_slot_id,p_service_date,p_projection_id,
    p_expected_authority_revision,p_lunch_document_identity,p_print_document_digest);
  if v_row->>'status'='PREVIEW_ONLY' then
   if octet_length(v_row::text)>8192 or v_count>=16 then
    return jsonb_build_object('schema','custodial.coverall-event-brief-list.v1',
     'status','LIMIT_EXCEEDED','limit_reason','eligible_count_or_size',
     'disclosure_approved',false,'candidates','[]'::jsonb);
   end if;
   v_rows:=v_rows||jsonb_build_array(v_row);
   v_count:=v_count+1;
  end if;
 end loop;
 return jsonb_build_object('schema','custodial.coverall-event-brief-list.v1',
  'status','PREVIEW_ONLY','disclosure_approved',false,
  'manager_id',p_manager_id,'capacity_slot_id',p_capacity_slot_id,
  'service_date',p_service_date,'projection_id',p_projection_id,
  'publication_id',v_authority.publication_id,'projection_replay_digest',v_replay_digest,
  'authority_revision',v_control_revision,'lunch_document_identity',p_lunch_document_identity,
  'print_document_digest',p_print_document_digest,'candidate_limit',16,'scan_limit',32,
  'candidates',v_rows);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_finalize_initial_operational(p_operation uuid, p_manager uuid, p_candidate_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE a custodial_coverall.activation_progress%rowtype;s custodial_coverall.initial_operational_stages%rowtype;ctx jsonb;proof jsonb;stored jsonb;lunch jsonb;receipt jsonb;projection uuid;actor jsonb;revision bigint;
BEGIN
 ctx:=public.static_weekly_coverall_initial_context(p_operation,p_manager);PERFORM public.custodial_begin_application_mutation();
 SELECT * INTO STRICT a FROM custodial_coverall.activation_progress WHERE operation_id=p_operation;
 SELECT * INTO STRICT s FROM custodial_coverall.initial_operational_stages WHERE operation_id=p_operation;
 IF s.candidate_digest IS DISTINCT FROM p_candidate_digest THEN RAISE EXCEPTION 'Original staged initial candidate identity required';END IF;
 proof:=public.static_weekly_coverall_initial_assert_payload(p_operation,p_manager,s.envelope_json);
 actor:=public.custodial_action_actor_v1(p_manager,a.credential_id,a.device_id,a.session_access,'write');
 IF s.envelope_json#>>'{semantic_snapshot,initialActivation,operationId}' IS DISTINCT FROM p_operation::text
  OR s.envelope_json#>'{authority,employmentRevisionVector}' IS DISTINCT FROM a.basis_json->'employmentRevisionVector'
 THEN RAISE EXCEPTION 'Original initial operation and all14 actual employment revisions must remain bound';END IF;
 stored:=public.static_weekly_coverall_initial_projection_sink(a.publication_id,a.frame_start,
  public.static_weekly_digest_jsonb(public.static_weekly_accepted_exception_set(a.publication_id,a.frame_start)),
  s.envelope_json->>'compiler_version',s.envelope_json->'objective',s.envelope_json->'metrics',s.envelope_json->>'replay_digest',
  s.envelope_json,a.authority_revision,p_manager,actor->>'manager_name','coverall-initial:'||p_operation);
 projection:=(stored#>>'{data,projection_id}')::uuid;
 IF projection IS NULL THEN RAISE EXCEPTION 'Native projection writer did not return actual projection ID';END IF;
 lunch:=public.static_weekly_v8_materialize_lunch_document(projection,s.lunch_json,p_manager);
 SELECT current_revision INTO STRICT revision FROM public.static_weekly_schedule_control WHERE singleton;
 IF NOT EXISTS(SELECT 1 FROM public.weekly_schedule_compiled_projections p JOIN public.weekly_schedule_lunch_documents l USING(projection_id)
  WHERE p.projection_id=projection AND p.publication_id=a.publication_id AND p.projection_envelope=s.envelope_json
   AND l.document_json=s.lunch_json AND l.document_identity=s.lunch_json->>'document_identity')
 THEN RAISE EXCEPTION 'Actual same-transaction operational projection/full lunch missing';END IF;
 receipt:=jsonb_build_object('schema','custodial.approved-manual-coverall-source-confirmation.v2','kind','INITIAL_EMPLOYMENT_OPERATIONALIZATION',
  'status','PERSISTED_CURRENT','operationId',p_operation,'managerId',p_manager,'sourceId',a.source_id,'publicationId',a.publication_id,
  'versionId',a.version_id,'frameStart',a.frame_start,'frameEnd',a.frame_start+6,'authorityRevision',revision,
  'normalBaselineResult',a.normal_result,'operationalProjectionResult',stored,'lunchResult',lunch,'projectionId',projection,
  'employmentRevisionVector',a.basis_json->'employmentRevisionVector','actualPositions',30,'originalHistoryPositions',22,
  'newNonemployeeCapacityPositions',8,'newEmployeesCreated',false,'weeklyBaselineChanged',false,'contractorBooked',false,
  'candidateDigest',s.candidate_digest,'revision',revision,'lunchDocumentIdentity',s.lunch_json->>'document_identity','normalPatternSolverInvoked',false,'operationalSelectionSolverInvoked',s.envelope_json#>'{receipt,selectionSolverInvoked}','samePhysicalTransaction',true);
 INSERT INTO custodial_coverall.activation_receipts VALUES(p_operation,receipt);RETURN receipt;
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_initial_assert_payload(p_operation uuid, p_manager uuid, p_envelope jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE ctx jsonb;proof jsonb;
BEGIN
 ctx:=public.static_weekly_coverall_initial_context(p_operation,p_manager);
 IF ctx->'stagedEnvelope' IS DISTINCT FROM p_envelope OR ctx->>'candidateDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(
  jsonb_build_object('envelope',p_envelope,'lunch',ctx->'stagedLunch'))
 THEN RAISE EXCEPTION 'Exact staged original INITIAL_EMPLOYMENT_OPERATIONALIZATION data required';END IF;
 -- One explicit Main factoring seam; NOT a boolean, fake staffing command,
 -- optimizer attestation or I1 receipt. Main's entry must derive its context
 -- by calling initial_context above and preserve the real native checks.
 IF to_regprocedure('public.static_weekly_manual_assert_initial_employment_projection(uuid,uuid,jsonb,jsonb)') IS NULL
 THEN RAISE EXCEPTION USING ERRCODE='0A000',MESSAGE='Main factored initial-employment native guard not installed';END IF;
 EXECUTE 'select public.static_weekly_manual_assert_initial_employment_projection($1,$2,$3,$4)'
 INTO STRICT proof USING p_operation,p_manager,p_envelope,ctx->'stagedLunch';
 IF proof->'projection_assignments' IS DISTINCT FROM p_envelope->'assignments' OR jsonb_typeof(proof->'assignment_links')<>'object'
 THEN RAISE EXCEPTION 'Factored native guard must return complete checked assignment lineage';END IF;
 PERFORM public.static_weekly_manual_assert_native_lunch(NULL,ctx->'stagedLunch',p_envelope,(ctx->>'publicationId')::uuid,(ctx->>'frameStart')::date);
 RETURN proof;
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_initial_context(p_operation uuid, p_manager uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE a custodial_coverall.activation_progress%rowtype;s custodial_coverall.initial_operational_stages%rowtype;fresh jsonb;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 SELECT * INTO STRICT a FROM custodial_coverall.activation_progress WHERE operation_id=p_operation;
 IF a.manager_id<>p_manager OR a.owner_xid<>pg_current_xact_id() OR a.backend_pid<>pg_backend_pid()
  OR a.authority_revision<>(SELECT current_revision FROM public.static_weekly_schedule_control WHERE singleton)
 THEN RAISE EXCEPTION 'Initial operational candidate must stay on its original physical transaction/revision';END IF;
 PERFORM public.custodial_action_actor_v1(p_manager,a.credential_id,a.device_id,a.session_access,'write');
 fresh:=public.static_weekly_manual_period_basis(p_manager,a.publication_id,a.frame_start,a.authority_revision,NULL);
 IF fresh IS DISTINCT FROM a.basis_json OR fresh->>'basisDigest'<>a.basis_digest
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Initial normal Source/canonical exceptions/7employment reads or14bindings changed';END IF;
 SELECT * INTO s FROM custodial_coverall.initial_operational_stages WHERE operation_id=p_operation;
 RETURN jsonb_build_object('schema','custodial.initial-employment-native-sql-context.v1','kind','INITIAL_EMPLOYMENT_OPERATIONALIZATION',
  'operationId',p_operation,'managerId',p_manager,'transactionId',a.owner_xid::text,'backendPid',a.backend_pid,
  'publicationId',a.publication_id,'versionId',a.version_id,'sourceId',a.source_id,'frameStart',a.frame_start,'frameEnd',a.frame_start+6,
  'authorityRevision',a.authority_revision,'basis',fresh,'stagedEnvelope',s.envelope_json,'stagedLunch',s.lunch_json,'candidateDigest',s.candidate_digest);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_initial_projection_sink(p_publication_id uuid, p_service_date date, p_exception_set_digest text, p_compiler_version text, p_objective jsonb, p_metrics jsonb, p_replay_digest text, p_assignments jsonb, p_expected_revision bigint, p_actor_manager_id uuid, p_actor_manager_name text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_pending_validation jsonb; v_request jsonb; v_request_digest text; v_prior public.weekly_schedule_command_receipts%rowtype; v_publication public.weekly_schedule_publications%rowtype; v_effective_start date; v_effective_end date; v_exception_set jsonb; v_exception_digest text; v_command uuid:=gen_random_uuid(); v_projection uuid:=gen_random_uuid(); v_revision bigint; v_content_digest text; v_response jsonb; v_item jsonb; v_assignment public.weekly_schedule_slot_assignments%rowtype; v_owner public.v_weekly_roster_slot_incumbency_ranges%rowtype; v_occurrence uuid; v_work jsonb;
begin
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_actor_manager_id,p_actor_manager_name,p_idempotency_key,'materialize_projection'); v_request:=jsonb_build_object('operation','materialize_projection','publication_id',p_publication_id,'service_date',p_service_date,'exception_set_digest',p_exception_set_digest,'compiler_version',p_compiler_version,'objective',p_objective,'metrics',p_metrics,'replay_digest',p_replay_digest,'projection_envelope',p_assignments,'expected_revision',p_expected_revision,'actor_manager_id',p_actor_manager_id,'actor_manager_name',p_actor_manager_name); v_request_digest:=public.static_weekly_digest_jsonb(v_request); perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts where actor_manager_id=p_actor_manager_id and idempotency_key=p_idempotency_key; if found then if v_prior.request_digest<>v_request_digest then raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs'; end if; return v_prior.response_json; end if;
  select * into v_publication from public.weekly_schedule_publications where publication_id=p_publication_id; select effective_start,effective_end into v_effective_start,v_effective_end from public.v_weekly_schedule_effective_ranges where version_id=v_publication.version_id; if not found or v_publication.publication_id is null or p_service_date is null or public.static_weekly_effective_version(p_service_date) is distinct from v_publication.version_id or mod(p_service_date-v_effective_start,7)<>0 or (v_effective_end is not null and p_service_date+6>=v_effective_end) then raise exception using errcode='23514',message='projection must be an aligned complete seven-day horizon wholly within one effective publication'; end if;
  v_exception_set:=public.static_weekly_accepted_exception_set(p_publication_id,p_service_date); v_exception_digest:=public.static_weekly_digest_jsonb(v_exception_set); if p_exception_set_digest is distinct from v_exception_digest or p_compiler_version is distinct from p_assignments->>'compiler_version' or p_objective is distinct from p_assignments->'objective' or p_metrics is distinct from p_assignments->'metrics' or p_replay_digest is distinct from p_assignments->>'replay_digest' then raise exception using errcode='23514',message='projection command identity must include exact compiler, objective, metrics, replay, and weekly exception authority'; end if;
  v_pending_validation:=public.static_weekly_coverall_initial_assert_payload((p_assignments#>>'{semantic_snapshot,initialActivation,operationId}')::uuid,p_actor_manager_id,p_assignments); if exists(select 1 from public.weekly_schedule_compiled_projections where publication_id=p_publication_id and week_start=p_service_date and exception_set_digest=v_exception_digest and compiler_version=p_compiler_version and authority_digest=p_assignments->>'authority_digest') then raise exception using errcode='23505',message='immutable projection already exists for this exact weekly authority'; end if;
  v_content_digest:=public.static_weekly_digest_jsonb(jsonb_build_object('publication_id',p_publication_id,'week_start',p_service_date,'exception_set_digest',v_exception_digest,'compiler_version',p_compiler_version,'objective',p_objective,'metrics',p_metrics,'replay_digest',p_replay_digest,'projection_envelope_identity',p_assignments->>'database_projection_identity','attestation',p_assignments->'attestation')); v_revision:=public.static_weekly_advance_authority(p_expected_revision,'materialize_projection',p_actor_manager_id,p_actor_manager_name,v_command,v_content_digest);
  insert into public.weekly_schedule_compiled_projections(projection_id,publication_id,version_id,week_start,week_end,exception_set_json,exception_set_digest,compiler_version,objective_json,metrics_json,replay_digest,authority_digest,receipt_json,projection_envelope,compiled_by_manager_id) values(v_projection,p_publication_id,v_publication.version_id,p_service_date,p_service_date+6,v_exception_set,v_exception_digest,p_compiler_version,p_objective,p_metrics,p_replay_digest,p_assignments->>'authority_digest',p_assignments->'receipt',p_assignments,p_actor_manager_id);
  for v_item in select value from jsonb_array_elements(p_assignments->'assignments') loop
    v_owner:=null; v_assignment:=null; v_work:=v_item->'work_snapshot'; 
 if p_assignments#>>'{authority,schema}'='custodial.approved-static-pending-staffing-authority.v1'
    and (v_work->>'overlayWork') is distinct from 'true' then
  select baseline.* into strict v_assignment
   from public.weekly_schedule_slot_assignments baseline
   join jsonb_array_elements(p_assignments#>'{authority,shiftEndDerivation,parentChains}') chain
    on baseline.work_id=chain->>'parentWorkId' and baseline.day_of_week=(chain->>'dayOfWeek')::smallint
   join lateral jsonb_array_elements(chain->'segments') segment on segment->>'workId'=v_item->>'work_id'
   where baseline.version_id=v_publication.version_id and baseline.day_of_week=(v_item->>'day_of_week')::smallint;
 else
  select * into v_assignment from public.weekly_schedule_slot_assignments where assignment_id=nullif(v_pending_validation#>>ARRAY['assignment_links',v_item->>'plan_work_id'],'')::uuid;
 end if;
  if v_assignment.assignment_id is null and not exists(select 1 from jsonb_array_elements(v_pending_validation->'projection_assignments') r where r=v_item) then raise exception using errcode='23514',message='pending work lacks independently checked original lineage';end if;
    perform public.static_weekly_capacity_assert_projection_owner(p_assignments,p_publication_id,v_item);
    if upper(v_item->>'status')='ASSIGNED' and v_item->>'owner_kind'='CONTRACTOR_CAPACITY' then
      v_owner:=null;
    elsif upper(v_item->>'status')='ASSIGNED' then select * into v_owner from public.v_weekly_roster_slot_incumbency_ranges where slot_id=(v_item->>'owner_slot_id')::uuid and effective_start<=(v_item->>'service_date')::date and (effective_end is null or (v_item->>'service_date')::date<effective_end); if not found or v_owner.person_id::text is distinct from v_item->>'owner_person_id' then raise exception using errcode='23514',message='projection assigned owner lacks an effective dated incumbent'; end if; elsif upper(v_item->>'status') not in ('OPEN','REVIEW') or v_item->>'owner_slot_id' is not null or v_item->>'owner_person_id' is not null then raise exception using errcode='23514',message='open and review projection rows must have null owner facts'; end if;
    insert into public.weekly_schedule_occurrences(projection_id,publication_id,version_id,assignment_id,service_date,work_id,day_of_week,location_id,location_code_snapshot,location_name_snapshot,coverage_start,coverage_end,owner_slot_id,owner_slot_label_snapshot,owner_person_id_snapshot,owner_name_snapshot,owner_kind,owner_capacity_id,state,state_reason,original_actor_person_id,original_actor_name_snapshot,authority_facts_json,occurrence_digest) values(v_projection,p_publication_id,v_publication.version_id,v_assignment.assignment_id,(v_item->>'service_date')::date,v_item->>'work_id',(v_item->>'day_of_week')::smallint,nullif(v_work->>'locationId','')::uuid,coalesce(v_work->>'locationCodeSnapshot',v_item->>'work_id'),coalesce(v_work->>'locationNameSnapshot',v_item->>'work_id'),(v_work#>>'{window,start}')::time,(v_work#>>'{window,end}')::time,case when lower(v_item->>'status')='assigned' then (v_item->>'owner_slot_id')::uuid else null end,case when lower(v_item->>'status')='assigned' then (select slot_label from public.weekly_roster_slots where slot_id=(v_item->>'owner_slot_id')::uuid) else null end,case when lower(v_item->>'status')='assigned' then (v_item->>'owner_person_id')::uuid else null end,case when lower(v_item->>'status')='assigned' then v_owner.person_name_snapshot else null end,nullif(v_item->>'owner_kind',''),nullif(v_item->>'capacity_id','')::uuid,case lower(v_item->>'status') when 'assigned' then 'created' when 'open' then 'open' else 'review' end,v_item->>'reason_code',nullif(v_item->>'original_actor_person_id','')::uuid,nullif(v_item->>'original_actor_name',''),jsonb_build_object('baseline_owner_slot_id',v_item->>'baseline_owner_slot_id','baseline_owner_person_id',v_item->>'baseline_owner_person_id','baseline_owner_name',v_item->>'baseline_owner_name','original_actor_person_id',v_item->>'original_actor_person_id','original_actor_name',v_item->>'original_actor_name','optimized_owner_slot_id',v_item->>'optimized_owner_slot_id','optimized_owner_person_id',v_item->>'optimized_owner_person_id','actual_actor_person_id',v_item->>'actual_actor_person_id','work_snapshot',v_work)||case when v_item->>'owner_kind'='CONTRACTOR_CAPACITY' then jsonb_build_object('owner_kind','CONTRACTOR_CAPACITY','capacity_id',v_item->>'capacity_id') else '{}'::jsonb end,public.static_weekly_digest_jsonb(v_item)) returning occurrence_id into v_occurrence;
    insert into public.weekly_schedule_projection_assignments(projection_id,occurrence_id,work_id,status,reason_code,owner_slot_id,owner_slot_label_snapshot,owner_person_id_snapshot,owner_name_snapshot,owner_kind,owner_capacity_id,authority_facts_json,explanation_json,content_digest) values(v_projection,v_occurrence,v_item->>'work_id',lower(v_item->>'status'),v_item->>'reason_code',case when lower(v_item->>'status')='assigned' then (v_item->>'owner_slot_id')::uuid else null end,case when lower(v_item->>'status')='assigned' then (select slot_label from public.weekly_roster_slots where slot_id=(v_item->>'owner_slot_id')::uuid) else null end,case when lower(v_item->>'status')='assigned' then (v_item->>'owner_person_id')::uuid else null end,case when lower(v_item->>'status')='assigned' then v_owner.person_name_snapshot else null end,nullif(v_item->>'owner_kind',''),nullif(v_item->>'capacity_id','')::uuid,(select authority_facts_json from public.weekly_schedule_occurrences where occurrence_id=v_occurrence),coalesce(v_item->'explanation','{}'::jsonb),public.static_weekly_digest_jsonb(v_item));
  end loop;
  v_response:=public.static_weekly_response_json('materialize_projection',v_revision,v_content_digest,v_request_digest,jsonb_build_object('projection_id',v_projection,'publication_id',p_publication_id,'week_start',p_service_date,'week_end',p_service_date+6,'replay_digest',p_replay_digest)); insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest) values(v_command,p_actor_manager_id,p_actor_manager_name,'materialize_projection',p_idempotency_key,p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest); return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_pending_facts(p_operation uuid, p_manager uuid, p_publication uuid, p_frame date, p_day date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.static_weekly_staffing_commands%rowtype;q custodial_coverall.choices%rowtype;d jsonb;facts jsonb:='[]';
BEGIN
 PERFORM public.static_weekly_pending_context(p_operation,p_manager);
 SELECT * INTO STRICT c FROM public.static_weekly_staffing_commands WHERE operation_id=p_operation;
 IF c.command_kind='cancel_absence' THEN RETURN '[]'::jsonb;END IF;
 SELECT * INTO q FROM custodial_coverall.choices WHERE operation_id=p_operation;IF NOT FOUND THEN RETURN facts;END IF;
 FOR d IN SELECT value FROM jsonb_array_elements(q.choice_json->'days') WHERE value->>'publicationId'=p_publication::text
  AND (value->>'serviceDate')::date BETWEEN p_frame AND p_frame+6 AND (p_day IS NULL OR value->>'serviceDate'=p_day::text) LOOP
  facts:=facts||public.static_weekly_coverall_day_facts(p_operation,d,p_manager,c.expected_revision,q.choice_id);
 END LOOP;
 RETURN facts;
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_preparing_basis(p_manager uuid, p_operation uuid, p_publication uuid, p_frame date, p_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE basis jsonb;q custodial_coverall.choices%rowtype;d jsonb;r record;retained jsonb:='[]';sources jsonb:='[]';c public.static_weekly_staffing_commands%rowtype;
BEGIN
 basis:=public.static_weekly_manual_period_basis(p_manager,p_publication,p_frame,p_revision,p_operation);
 SELECT * INTO STRICT c FROM public.static_weekly_staffing_commands WHERE operation_id=p_operation;
 SELECT * INTO q FROM custodial_coverall.choices WHERE operation_id=CASE WHEN c.command_kind='cancel_absence' THEN c.target_absence_id ELSE p_operation END;
 IF FOUND THEN
  FOR d IN SELECT value FROM jsonb_array_elements(q.choice_json->'days') WHERE value->>'publicationId'=p_publication::text AND (value->>'serviceDate')::date BETWEEN p_frame AND p_frame+6 LOOP
   SELECT p.projection_id,p.projection_envelope,s.canonical_source INTO STRICT r FROM public.weekly_schedule_compiled_projections p
    JOIN public.static_weekly_authority_source_documents s ON s.source_id=(d->>'sourceId')::uuid
    WHERE p.projection_id=(d->>'retainedProjectionId')::uuid AND p.publication_id=p_publication AND p.projection_envelope->>'database_projection_identity'=d->>'retainedEnvelopeIdentity';
   retained:=retained||jsonb_build_array(jsonb_build_object('serviceDate',d->'serviceDate','sourceId',d->'sourceId','publicationId',p_publication,
    'projectionId',r.projection_id,'envelopeIdentity',d->'retainedEnvelopeIdentity','dayBasis',(SELECT x FROM jsonb_array_elements(r.projection_envelope#>'{authority,datedDayBases}') x WHERE x->'serviceDate'=d->'serviceDate')));
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(sources) s WHERE s->'sourceId'=d->'sourceId') THEN
    sources:=sources||jsonb_build_array(jsonb_build_object('sourceId',d->'sourceId','publicationId',p_publication,'source',jsonb_set(r.canonical_source,'{serviceDate}',to_jsonb(p_frame::text),true)));END IF;
  END LOOP;
 END IF;
 RETURN jsonb_build_object('periodBasis',basis,'originalCommand',basis->'originalCommand','choice',q.choice_json,'retainedDays',retained,'normalSources',sources);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_record_activation_begin(p_operation uuid, p_manager uuid, p_credential uuid, p_device text, p_access text, p_normal_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE a record;projection record;revision bigint;basis jsonb;body jsonb;
BEGIN
 SELECT o.*,p.source_id,p.service_date INTO STRICT a FROM custodial_coverall.activation_operations o
 JOIN custodial_coverall.activation_packets p USING(packet_id) WHERE o.operation_id=p_operation AND o.manager_id=p_manager AND o.owner_xid=pg_current_xact_id();
 SELECT p.publication_id,p.version_id,p.week_start,p.projection_id INTO STRICT projection FROM public.weekly_schedule_compiled_projections p
 JOIN public.weekly_schedule_versions v USING(version_id)
 WHERE v.authority_source_id=a.source_id AND p.week_start=a.service_date AND p.xmin=pg_current_xact_id()::text::xid;
 SELECT current_revision INTO STRICT revision FROM public.static_weekly_schedule_control WHERE singleton;
 basis:=public.static_weekly_manual_period_basis(p_manager,projection.publication_id,a.service_date,revision,NULL);
 IF basis->>'sourceId'<>a.source_id::text OR basis->>'frameStart'<>a.service_date::text
  OR jsonb_array_length(basis->'employmentByDate')<>7 OR jsonb_array_length(basis->'employmentRevisionVector')<>14
 THEN RAISE EXCEPTION 'Main current employment-aware native basis (7reads/14bindings) is required';END IF;
 INSERT INTO custodial_coverall.activation_progress VALUES(p_operation,pg_current_xact_id(),pg_backend_pid(),p_manager,p_credential,p_device,p_access,
  a.source_id,projection.publication_id,projection.version_id,a.service_date,revision,p_normal_result,basis,basis->>'basisDigest');
 body:=jsonb_build_object('schema','custodial.coverall-initial-uncommitted.v1','kind','INITIAL_EMPLOYMENT_OPERATIONALIZATION','operationId',p_operation,
  'managerId',p_manager,'backendPid',pg_backend_pid(),'transactionId',pg_current_xact_id()::text,'sourceId',a.source_id,
  'publicationId',projection.publication_id,'versionId',projection.version_id,'frameStart',a.service_date,'frameEnd',a.service_date+6,
  'authorityRevision',revision,'basis',basis,'normalBaselineResult',p_normal_result,'normalBaselineIsNotActualCoverage',true,'committed',false,'accepted',false);
 RETURN body;
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_register_template(p_source_id uuid, p_template jsonb, p_binding jsonb, p_owner_config jsonb, p_approval_evidence jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare id text;count_people integer;body jsonb;entry_digest text;prior record;source_row record;
begin

 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select * into source_row from public.static_weekly_authority_source_documents
  where source_id=p_source_id and active and retired_at is null for share;
 if not found or source_row.source_digest is distinct from public.static_weekly_digest_jsonb(source_row.canonical_source) then
  raise exception using errcode='23514',message='approved template requires an exact active registered current source';end if;
 perform public.static_weekly_assert_exact_object(p_template,
  array['templateId','staffingCount','source','roleSlotIds'],
  array['templateId','staffingCount','source','roleSlotIds'],'approved static template');
 perform public.static_weekly_assert_exact_object(p_binding,
  array['schema','templateId','staffingCount','sourceDigest','roleSlotIdsDigest','patternAuthority','artifactSha256','ownerConfigDigest','patternPublicationStatus'],
  array['schema','templateId','staffingCount','sourceDigest','roleSlotIdsDigest','patternAuthority','artifactSha256','ownerConfigDigest','patternPublicationStatus'],'approved static binding');
 id:=p_template->>'templateId';
 if id is null or length(id) not between 1 and 160
  or jsonb_typeof(p_template->'staffingCount') is distinct from 'number'
  or (p_template->>'staffingCount')!~'^[1-9][0-9]?$'
  or jsonb_typeof(p_template->'source') is distinct from 'object'
  or jsonb_typeof(p_template->'roleSlotIds') is distinct from 'array'
  or jsonb_typeof(p_owner_config) is distinct from 'object'
  or jsonb_typeof(p_approval_evidence) is distinct from 'object'
  or p_binding->>'schema' is distinct from 'custodial.approved-static-template-binding.v1'
  or p_binding->>'templateId' is distinct from id
  or p_binding->'staffingCount' is distinct from p_template->'staffingCount'
  or p_binding->>'patternAuthority' is distinct from 'OWNER_APPROVED_OPERATIONAL_PATTERN'
  or p_approval_evidence->>'classification' is distinct from 'OWNER_APPROVED_OPERATIONAL_PATTERN'
  or coalesce(p_approval_evidence->>'sourceReference','')=''
  or coalesce(p_approval_evidence->>'ownerDecisionReference','')=''
  or p_approval_evidence->>'artifactSha256' is distinct from p_binding->>'artifactSha256'
  or exists(select 1 from unnest(array['sourceDigest','roleSlotIdsDigest','artifactSha256','ownerConfigDigest']) key
     where coalesce(p_binding->>key,'')!~'^[0-9a-f]{64}$') then
  raise exception using errcode='23514',message='exact approved artifact, owner decision and complete template/config binding required';end if;
 count_people:=(p_template->>'staffingCount')::integer;
 if count_people not between 1 and 32 or jsonb_array_length(p_template->'roleSlotIds')<>count_people
  or exists(select 1 from jsonb_array_elements(p_template->'roleSlotIds') item
      where jsonb_typeof(item) is distinct from 'string' or coalesce(item#>>'{}','')='')
  or (select count(distinct item#>>'{}') from jsonb_array_elements(p_template->'roleSlotIds') item)<>count_people then
  raise exception using errcode='23514',message='approved role identities must be complete and unique';end if;
 body:=jsonb_build_object('template',p_template,'binding',p_binding,'ownerConfig',p_owner_config,'approvalEvidence',p_approval_evidence);
 entry_digest:=public.static_weekly_digest_jsonb(body);
 select * into prior from public.static_weekly_approved_template_catalog where template_id=id;
 if found then
  if prior.catalog_entry_digest is distinct from entry_digest then
   raise exception using errcode='23505',message='approved template ID already binds different immutable bytes';end if;
 else
  insert into public.static_weekly_approved_template_catalog
   (template_id,staffing_count,template_json,binding_json,owner_config,approval_evidence,catalog_entry_digest)
   values(id,count_people,p_template,p_binding,p_owner_config,p_approval_evidence,entry_digest);
 end if;
 if exists(select 1 from public.static_weekly_approved_template_retirements where template_id=id) then
  raise exception using errcode='23514',message='retired template cannot be readmitted under the same identity';end if;
 insert into public.static_weekly_approved_template_source_configs(source_id,owner_config,config_digest)
  values(p_source_id,p_owner_config,public.static_weekly_digest_jsonb(p_owner_config)) on conflict(source_id) do nothing;
 if not exists(select 1 from public.static_weekly_approved_template_source_configs
   where source_id=p_source_id and owner_config=p_owner_config and config_digest=public.static_weekly_digest_jsonb(p_owner_config)) then
  raise exception using errcode='23505',message='current source already binds a different owner configuration';end if;
 return jsonb_build_object('registered',true,'template_id',id,'catalog_entry_digest',entry_digest,'published',false);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_stage_companion(p_operation uuid, p_manager uuid, p_candidates jsonb, p_preview text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.static_weekly_staffing_commands%rowtype;choice custodial_coverall.choices%rowtype;prior custodial_coverall.staged_bindings%rowtype;day jsonb;request_actor custodial_coverall.request_actors%rowtype;
BEGIN
 SELECT * INTO STRICT c FROM public.static_weekly_staffing_commands WHERE operation_id=p_operation FOR UPDATE;
 SELECT * INTO choice FROM custodial_coverall.choices WHERE operation_id=CASE WHEN c.command_kind='cancel_absence' THEN c.target_absence_id ELSE p_operation END;
 IF NOT FOUND THEN RETURN;END IF;
 PERFORM public.static_weekly_pending_context(p_operation,p_manager);
 SELECT * INTO STRICT request_actor FROM custodial_coverall.request_actors WHERE operation_id=p_operation;
 PERFORM public.custodial_action_actor_v1(p_manager,request_actor.credential_id,request_actor.device_id,request_actor.session_access,'manage_coverall');
 IF c.prepared_by_manager_id<>p_manager OR c.state NOT IN('PREPARING','PREPARED') THEN RAISE EXCEPTION 'Original staffing stage ownership required';END IF;
 IF c.command_kind='absence' THEN
  FOR day IN SELECT value FROM jsonb_array_elements(choice.choice_json->'days') LOOP PERFORM public.static_weekly_coverall_validate_choice_day(p_operation,p_manager,day);END LOOP;
 END IF;
 SELECT * INTO prior FROM custodial_coverall.staged_bindings WHERE operation_id=p_operation;
 IF FOUND THEN
  IF prior.choice_digest<>choice.choice_digest OR prior.candidate_set_digest<>public.static_weekly_digest_jsonb(p_candidates) OR prior.preview_digest<>p_preview THEN RAISE EXCEPTION 'Staged CoverAll identity changed';END IF;
 ELSE INSERT INTO custodial_coverall.staged_bindings VALUES(p_operation,choice.operation_id,choice.choice_digest,public.static_weekly_digest_jsonb(p_candidates),p_preview);END IF;
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_stage_initial_operational(p_operation uuid, p_manager uuid, p_envelope jsonb, p_lunch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE ctx jsonb;prior custodial_coverall.initial_operational_stages%rowtype;fingerprint text;proof jsonb;
BEGIN
 ctx:=public.static_weekly_coverall_initial_context(p_operation,p_manager);PERFORM public.custodial_begin_application_mutation();
 IF pg_column_size(p_envelope)>16777216 OR pg_column_size(p_lunch)>16777216 OR p_envelope IS NULL OR p_lunch IS NULL
 THEN RAISE EXCEPTION 'Bounded actual native candidate and full lunch required';END IF;
 fingerprint:=public.static_weekly_digest_jsonb(jsonb_build_object('envelope',p_envelope,'lunch',p_lunch));
 SELECT * INTO prior FROM custodial_coverall.initial_operational_stages WHERE operation_id=p_operation;
 IF FOUND THEN
  IF prior.envelope_json IS DISTINCT FROM p_envelope OR prior.lunch_json IS DISTINCT FROM p_lunch OR prior.candidate_digest<>fingerprint THEN RAISE EXCEPTION 'Immutable initial native candidate conflict';END IF;
 ELSE INSERT INTO custodial_coverall.initial_operational_stages(operation_id,envelope_json,lunch_json,candidate_digest) VALUES(p_operation,p_envelope,p_lunch,fingerprint);END IF;
 proof:=public.static_weekly_coverall_initial_assert_payload(p_operation,p_manager,p_envelope);
 RETURN jsonb_build_object('state','STAGED_UNCOMMITTED','operationId',p_operation,'candidateDigest',fingerprint,'committed',false);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_validate_choice_day(p_operation uuid, p_manager uuid, p_day jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE ctx jsonb;prior record;source jsonb;slot jsonb;day_basis jsonb;service date;original_exceptions jsonb;
BEGIN
 ctx:=public.static_weekly_pending_context(p_operation,p_manager);service:=(p_day->>'serviceDate')::date;
 IF ctx#>>'{originalCommand,semanticBody,commandKind}'<>'absence'
  OR service<(ctx#>>'{originalCommand,semanticBody,startDate}')::date OR service>(ctx#>>'{originalCommand,semanticBody,endDate}')::date
  OR p_day->'actualHoursConfirmed' IS DISTINCT FROM 'true'::jsonb
  OR nullif(btrim(p_day->>'confirmationReference'),'') IS NULL OR length(p_day->>'confirmationReference')>256
 THEN RAISE EXCEPTION 'Original third-absence actual-hours confirmation required';END IF;
 PERFORM public.static_weekly_assert_exact_object(p_day,
  ARRAY['serviceDate','sourceId','publicationId','capacityId','shift','lunch','lunchCovererSlotId','confirmationReference','actualHoursConfirmed','retainedProjectionId','retainedEnvelopeIdentity','retainedPlanDigest','overlayDigest'],
  ARRAY['serviceDate','sourceId','publicationId','capacityId','shift','lunch','lunchCovererSlotId','confirmationReference','actualHoursConfirmed','retainedProjectionId','retainedEnvelopeIdentity','retainedPlanDigest','overlayDigest'],'CoverAll day');
 PERFORM public.static_weekly_v3_assert_window(p_day->'shift','actual CoverAll hours');PERFORM public.static_weekly_v3_assert_window(p_day->'lunch','actual CoverAll lunch');
 IF (p_day#>>'{lunch,end}')::time-(p_day#>>'{lunch,start}')::time<>interval '1 hour'
  OR p_day#>>'{lunch,start}'<p_day#>>'{shift,start}' OR p_day#>>'{lunch,end}'>p_day#>>'{shift,end}'
 THEN RAISE EXCEPTION 'Actual full-hour CoverAll lunch must fit the actual shift';END IF;
 SELECT s.canonical_source INTO STRICT source FROM public.static_weekly_authority_source_documents s
 JOIN public.weekly_schedule_versions v ON v.authority_source_id=s.source_id JOIN public.weekly_schedule_publications p USING(version_id)
 WHERE p.publication_id=(p_day->>'publicationId')::uuid AND s.source_id=(p_day->>'sourceId')::uuid
  AND public.static_weekly_effective_version(service)=v.version_id AND s.active AND s.retired_at IS NULL;
 SELECT x INTO STRICT slot FROM jsonb_array_elements(source->'slots') x WHERE x->>'id'=p_day->>'capacityId';
 PERFORM public.static_weekly_capacity_assert_shape(slot);
 IF NOT public.static_weekly_capacity_registered(slot) THEN RAISE EXCEPTION 'Capacity is not registered to this immutable source';END IF;
 SELECT p.projection_id,p.publication_id,p.week_start,p.projection_envelope INTO STRICT prior
 FROM public.weekly_schedule_compiled_projections p WHERE p.projection_id=(p_day->>'retainedProjectionId')::uuid
  AND p.publication_id=(p_day->>'publicationId')::uuid AND service BETWEEN p.week_start AND p.week_end
  AND p.projection_envelope->>'database_projection_identity'=p_day->>'retainedEnvelopeIdentity';
 source:=jsonb_set(source,'{serviceDate}',to_jsonb(prior.week_start::text),true);
 original_exceptions:=public.static_weekly_pending_original_exception_set((p_day->>'publicationId')::uuid,prior.week_start,p_operation);
 IF NOT EXISTS(SELECT 1 FROM public.weekly_schedule_compiled_projections p WHERE p.projection_id=prior.projection_id
  AND p.exception_set_digest=public.static_weekly_digest_jsonb(public.static_weekly_manual_exception_summary(original_exceptions)))
 THEN RAISE EXCEPTION 'Exact current accepted two-absence projection required';END IF;
 SELECT x INTO STRICT day_basis FROM jsonb_array_elements(prior.projection_envelope#>'{authority,datedDayBases}') x WHERE x->>'serviceDate'=service::text;
 IF day_basis->>'kind'<>'ABSENCE' OR jsonb_array_length(day_basis#>'{input,absentPersonIds}')<>2
  OR day_basis#>>'{plan,planDigest}' IS DISTINCT FROM p_day->>'retainedPlanDigest'
  OR day_basis#>>'{plan,planDigest}' IS DISTINCT FROM public.static_weekly_digest_jsonb((day_basis->'plan')-'planDigest')
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(day_basis#>'{input,roster}') r WHERE r->>'personId'=ctx#>>'{originalCommand,semanticBody,employeeId}')
 THEN RAISE EXCEPTION 'Retained two-absence day or third employee changed';END IF;
 RETURN jsonb_build_object('source',source,'slot',slot,'dayBasis',day_basis,'originalCommand',ctx->'originalCommand');
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_digest_text(p_value text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE STRICT SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_schema text; v_digest text;
begin
  select n.nspname into v_schema
  from pg_extension e join pg_namespace n on n.oid=e.extnamespace
  where e.extname='pgcrypto';
  if v_schema not in ('extensions','public') then
    raise exception using errcode='55000', message='pgcrypto must be installed in extensions or public';
  end if;
  execute format('select encode(%I.digest(convert_to($1,''UTF8''),''sha256''),''hex'')',v_schema) into v_digest using p_value;
  return v_digest;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_finalize_manual_recurring(p_operation uuid, p_manager uuid, p_candidate_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE ctx jsonb;a custodial_coverall.recurring_materialization_operations%rowtype;s custodial_coverall.recurring_materialization_stages%rowtype;
 actor jsonb;stored jsonb;lunch jsonb;receipt jsonb;projection uuid;revision bigint;
BEGIN
 ctx:=public.static_weekly_manual_recurring_context(p_operation,p_manager);PERFORM public.custodial_begin_application_mutation();
 SELECT * INTO STRICT a FROM custodial_coverall.recurring_materialization_operations WHERE operation_id=p_operation;
 SELECT * INTO STRICT s FROM custodial_coverall.recurring_materialization_stages WHERE operation_id=p_operation;
 IF s.candidate_digest IS DISTINCT FROM p_candidate_digest THEN RAISE EXCEPTION 'Original recurring candidate digest required';END IF;
 PERFORM public.static_weekly_manual_recurring_assert_payload(p_operation,p_manager,s.envelope_json);
 actor:=public.custodial_action_actor_v1(p_manager,a.credential_id,a.device_id,a.session_access,'write');
 stored:=public.static_weekly_manual_recurring_projection_sink(a.publication_id,a.frame_start,
  public.static_weekly_digest_jsonb(a.basis_json->'preparedSummary'),s.envelope_json->>'compiler_version',s.envelope_json->'objective',s.envelope_json->'metrics',
  s.envelope_json->>'replay_digest',s.envelope_json,a.authority_revision,p_manager,actor->>'manager_name','manual-recurring:'||p_operation);
 projection:=(stored#>>'{data,projection_id}')::uuid;
 IF projection IS NULL THEN RAISE EXCEPTION 'Actual native recurring projection ID missing';END IF;
 lunch:=public.static_weekly_v8_materialize_lunch_document(projection,s.lunch_json,p_manager);
 IF lunch->'ok' IS DISTINCT FROM 'true'::jsonb OR lunch->>'persistence_status' IS DISTINCT FROM 'PERSISTED'
  OR lunch->>'document_identity' IS DISTINCT FROM s.lunch_json->>'document_identity'
  OR NOT EXISTS(SELECT 1 FROM public.weekly_schedule_compiled_projections p JOIN public.weekly_schedule_lunch_documents l USING(projection_id)
   WHERE p.projection_id=projection AND p.publication_id=a.publication_id AND p.version_id=a.version_id AND p.week_start=a.frame_start AND p.week_end=a.frame_start+6
    AND p.projection_envelope=s.envelope_json AND l.document_json=s.lunch_json AND l.document_identity=s.lunch_json->>'document_identity')
 THEN RAISE EXCEPTION 'Actual same-transaction recurring projection/full-hour lunch missing';END IF;
 SELECT current_revision INTO STRICT revision FROM public.static_weekly_schedule_control WHERE singleton;
 receipt:=jsonb_build_object('schema','custodial.approved-manual-recurring-confirmation.v2','kind','RECURRING_MANUAL_MATERIALIZATION','status','PERSISTED_CURRENT',
  'operationId',p_operation,'managerId',p_manager,'sourceId',a.source_id,'publicationId',a.publication_id,'versionId',a.version_id,
  'projectionId',projection,'frameStart',a.frame_start,'frameEnd',a.frame_start+6,'authorityRevision',revision,'candidateDigest',s.candidate_digest,
  'lunchDocumentIdentity',s.lunch_json->'document_identity','employmentRevisionVector',a.basis_json->'employmentRevisionVector',
  'normalPatternSolverInvoked',false,'operationalSelectionSolverInvoked',s.envelope_json#>'{receipt,selectionSolverInvoked}',
  'normalSourceChanged',false,'newStaffingCommandCreated',false,'newPTOCreated',false,'samePhysicalTransaction',true);
 INSERT INTO custodial_coverall.recurring_materialization_receipts VALUES(p_operation,receipt);RETURN receipt;
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_finish_manual_recurring_normal(p_operation uuid, p_manager uuid, p_reference jsonb, p_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE a custodial_coverall.recurring_materialization_operations%rowtype;r jsonb;receipt jsonb;projection uuid;doc text;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 SELECT * INTO STRICT a FROM custodial_coverall.recurring_materialization_operations WHERE operation_id=p_operation;
 IF a.manager_id<>p_manager OR a.owner_xid<>pg_current_xact_id() OR a.backend_pid<>pg_backend_pid() OR a.repeat_basis IS NULL
  OR p_reference->>'managerId' IS DISTINCT FROM p_manager::text OR p_reference->>'requestId' IS DISTINCT FROM p_operation::text
  OR p_reference->>'publicationId' IS DISTINCT FROM a.publication_id::text OR p_reference->>'sourceId' IS DISTINCT FROM a.source_id::text
  OR p_reference->>'frameStart' IS DISTINCT FROM a.frame_start::text OR (p_reference->>'expectedRevision')::bigint IS DISTINCT FROM a.authority_revision
  OR p_reference->'employmentRevisionVector' IS DISTINCT FROM(SELECT jsonb_agg(jsonb_build_object('serviceDate',d->'serviceDate','employeeId',e->'employeeId',
    'employmentRevision',e->'employmentRevision','requestId',e#>>'{command,requestId}') ORDER BY d->>'serviceDate',e->>'employeeId')
    FROM jsonb_array_elements(a.repeat_basis->'employmentByDate') days(d) CROSS JOIN LATERAL jsonb_array_elements(d->'employees') employees(e))
 THEN RAISE EXCEPTION 'Original physical recurring normal request/reference differs';END IF;
 r:=public.static_weekly_materialize_manual_repeat(p_reference,p_digest,a.credential_id,a.device_id,a.session_access);
 IF r->>'status' IS DISTINCT FROM 'PERSISTED_CURRENT' THEN RAISE EXCEPTION 'Normal repeat did not accept current source/employment';END IF;
 projection:=(r->>'projection_id')::uuid;doc:=r->>'lunch_document_identity';
 IF projection IS NULL OR doc IS NULL OR NOT EXISTS(SELECT 1 FROM public.weekly_schedule_compiled_projections p
  JOIN public.weekly_schedule_lunch_documents l USING(projection_id) WHERE p.projection_id=projection AND p.publication_id=a.publication_id
   AND p.week_start=a.frame_start AND p.week_end=a.frame_start+6 AND l.document_identity=doc)
 THEN RAISE EXCEPTION 'Actual repeated normal/lunch row missing';END IF;
 receipt:=jsonb_build_object('schema','custodial.approved-manual-recurring-confirmation.v2','kind','RECURRING_MANUAL_MATERIALIZATION','status','PERSISTED_CURRENT',
  'operationId',p_operation,'managerId',p_manager,'sourceId',a.source_id,'publicationId',a.publication_id,'versionId',a.version_id,
  'projectionId',projection,'frameStart',a.frame_start,'frameEnd',a.frame_start+6,'authorityRevision',r->'authority_revision','lunchDocumentIdentity',doc,
  'normalPatternSolverInvoked',false,'operationalSelectionSolverInvoked',false,'normalSourceChanged',false,'samePhysicalTransaction',true,
  'originalRepeatReceipt',r,'employmentRevisionVector',p_reference->'employmentRevisionVector');
 INSERT INTO custodial_coverall.recurring_materialization_receipts VALUES(p_operation,receipt);RETURN receipt;
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_issue_coverall_link(p_manager uuid, p_credential uuid, p_device text, p_access text, p_link uuid, p_token_hash text, p_binding jsonb, p_ttl integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare actor jsonb;basis jsonb;created timestamptz;expires timestamptz;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 actor:=public.custodial_action_actor_v1(p_manager,p_credential,p_device,p_access,'manage_coverall');
 if p_link is null or coalesce(p_token_hash,'')!~'^[a-f0-9]{64}$' or p_ttl is null or p_ttl not between 1 and 168 then
  raise exception using errcode='22023',message='Bounded canonical CoverAll issuance required';end if;
 basis:=public.static_weekly_assert_coverall_link_basis(p_binding);
 actor:=public.custodial_action_actor_v1(p_manager,p_credential,p_device,p_access,'manage_coverall');
 created:=clock_timestamp();expires:=created+make_interval(hours=>p_ttl);
 -- The once-only request ID is scoped to the server-derived issuing manager.
 -- Another manager may use/revoke the same nonsecret UUID without interference.
 insert into public.static_weekly_coverall_access_links(link_id,token_hash,binding,source_id,source_digest,manager_id,credential_id,device_id,session_access,created_at,expires_at)
 values(p_link,p_token_hash,p_binding,(basis->>'source_id')::uuid,basis->>'source_digest',p_manager,p_credential,p_device,p_access,created,expires);
 return jsonb_build_object('link_id',p_link,'expires_at',expires);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_leadership_bind_request(p_browser_hash text, p_token_hash text, p_request uuid, p_permission text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r custodial_leadership_private.registrations%rowtype;p custodial_leadership_private.policy%rowtype;
 c custodial_leadership_private.request_contexts%rowtype;view jsonb;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();
 IF coalesce(p_browser_hash,'') !~ '^[a-f0-9]{64}$' OR coalesce(p_token_hash,'') !~ '^[a-f0-9]{64}$'
  OR p_request IS NULL OR p_permission IS NULL OR p_permission NOT IN('custodial.read','custodial.edit','custodialManagementAdmin')
  THEN RAISE EXCEPTION 'Custodial cohort credential context required' USING ERRCODE='42501';END IF;
 SELECT * INTO p FROM custodial_leadership_private.policy WHERE singleton FOR SHARE;
 SELECT * INTO r FROM custodial_leadership_private.registrations WHERE browser_hash=p_browser_hash AND token_hash=p_token_hash FOR SHARE;
 view:=custodial_leadership_private.session_view(r.registration_id);
 IF view IS NULL OR NOT(p_permission=ANY(p.permissions)) THEN RAISE EXCEPTION 'Custodial cohort permission unavailable' USING ERRCODE='42501';END IF;
 SELECT * INTO c FROM custodial_leadership_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current();
 IF c.request_id IS NOT NULL AND(c.request_id<>p_request OR c.registration_id<>r.registration_id OR c.permission<>p_permission)
  THEN RAISE EXCEPTION 'Custodial original request context cannot change' USING ERRCODE='42501';END IF;
 INSERT INTO custodial_leadership_private.request_contexts(backend_pid,transaction_id,request_id,registration_id,cohort_principal_id,policy_version,permission)
  VALUES(pg_backend_pid(),txid_current(),p_request,r.registration_id,p.cohort_principal_id,p.policy_version,p_permission)
  ON CONFLICT(backend_pid,transaction_id) DO NOTHING;
 RETURN custodial_leadership_private.require_context(p.cohort_principal_id,p_permission);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_leadership_bind_verified_request(p_registration uuid, p_browser uuid, p_cohort uuid, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE view jsonb;c custodial_leadership_private.request_contexts%rowtype;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();
 PERFORM 1 FROM custodial_leadership_private.policy WHERE singleton FOR SHARE;
 PERFORM 1 FROM custodial_leadership_private.registrations WHERE registration_id=p_registration FOR SHARE;
 view:=custodial_leadership_private.session_view(p_registration);
 IF view IS NULL OR p_request IS NULL OR view->>'browserId' IS DISTINCT FROM p_browser::text
  OR view#>>'{cohort,principalId}' IS DISTINCT FROM p_cohort::text OR NOT(view#>'{cohort,permissions}' ? 'custodialManagementAdmin')
  THEN RAISE EXCEPTION 'Actual cohort credential is unavailable' USING ERRCODE='42501';END IF;
 SELECT * INTO c FROM custodial_leadership_private.request_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current();
 IF c.request_id IS NOT NULL AND(c.request_id<>p_request OR c.registration_id<>p_registration OR c.cohort_principal_id<>p_cohort)
  THEN RAISE EXCEPTION 'Original cohort transaction binding changed' USING ERRCODE='42501';END IF;
 INSERT INTO custodial_leadership_private.request_contexts(backend_pid,transaction_id,request_id,registration_id,cohort_principal_id,policy_version,permission)
 VALUES(pg_backend_pid(),txid_current(),p_request,p_registration,p_cohort,(view#>>'{cohort,policyVersion}')::integer,'custodialManagementAdmin')
 ON CONFLICT(backend_pid,transaction_id) DO NOTHING;
 RETURN custodial_leadership_private.require_context(p_cohort,'custodialManagementAdmin');
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_manual_activation_packet_fingerprint(p_source uuid, p_template text, p_manager uuid, p_transition jsonb, p_feasibility jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare document jsonb;projection jsonb;lunch jsonb;metadata jsonb;
begin
 -- Hash the independently verifiable components without constructing another
 -- full copy of the large feasibility envelope. Their identities cover every
 -- feasibility field, including the separately materialized initial snapshot.
 document:=p_feasibility#>'{initialBaseline,document}';projection:=p_feasibility#>'{initialBaseline,projection}';
 lunch:=p_feasibility->'lunchDocument';metadata:=(p_feasibility->'initialBaseline')-array['document','projection','lunchDocument'];
 -- Separate statements release each large temporary hash input before the
 -- next component. Removing keys in one operation avoids a full intermediate
 -- copy of the thirteen-megabyte envelope for each deleted key.
 if p_feasibility->>'digest' is distinct from public.static_weekly_digest_jsonb(p_feasibility-array['digest','initialBaseline']) then
  raise exception using errcode='23514',message='manual activation feasibility identity changed';end if;
 if document#>>'{validation,database_document_identity}' is distinct from public.static_weekly_digest_jsonb(document#-'{validation,database_document_identity}') then
  raise exception using errcode='23514',message='manual activation document identity changed';end if;
 if projection->>'database_projection_identity' is distinct from public.static_weekly_digest_jsonb(projection-'database_projection_identity') then
  raise exception using errcode='23514',message='manual activation projection identity changed';end if;
 if lunch->>'document_identity' is distinct from public.static_weekly_digest_jsonb(lunch-'document_identity') then
  raise exception using errcode='23514',message='manual activation lunch identity changed';end if;
 if p_feasibility#>'{initialBaseline,lunchDocument}' is distinct from lunch then
  raise exception using errcode='23514',message='manual activation initial lunch identity changed';end if;
 return public.static_weekly_digest_jsonb(jsonb_build_object('sourceId',p_source,'templateId',p_template,'managerId',p_manager,
  'transitionDigest',p_transition->>'transitionDigest','feasibilityDigest',p_feasibility->>'digest',
  'documentIdentity',document#>>'{validation,database_document_identity}',
  'projectionIdentity',projection->>'database_projection_identity','lunchIdentity',lunch->>'document_identity','initialMetadata',metadata));
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_manual_assert_absence_score(p_day jsonb, p_normal jsonb, p_policy jsonb, p_availability jsonb, p_rows jsonb, p_config jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare input jsonb:=p_day->'input';plan jsonb:=p_day->'plan';d text:=p_day->>'serviceDate';
 start_at text:=plan#>>'{checkedWindow,start}';end_at text:=plan#>>'{checkedWindow,end}';
 phase jsonb;prior jsonb;loan jsonb;helper jsonb;recipient jsonb;group_row jsonb;slice jsonb;owners jsonb;points jsonb;
 expected jsonb;actual jsonb;anchors jsonb;keys jsonb;code text;owner text;normal_owner text;t text;last_t text;
 p_sum numeric:=0;l_sum numeric:=0;total_minutes numeric:=0;p_loss numeric;l_loss numeric;distance numeric;minutes numeric;n integer;
 tammy text:=p_config#>>'{slots,TAMMY,slotId}';china_minutes integer:=0;tammy_reliefs integer:=0;preferred_minutes integer:=0;
 preferred_key text;preferred_slot text;preferred_codes text[];
begin
 select jsonb_agg(r->'code' order by r->>'code') into keys from jsonb_array_elements(p_policy->'groups') r;
 select coalesce(jsonb_agg(jsonb_build_object('start',case when ord=1 then start_at else ph->>'start' end,
  'end',least(ph->>'end',end_at)) order by ord),'[]') into expected
  from jsonb_array_elements(p_normal->'phases') with ordinality x(ph,ord)
  where (case when ord=1 then start_at else ph->>'start' end)<least(ph->>'end',end_at);
 select coalesce(jsonb_agg(ph->'window' order by ord),'[]') into actual from jsonb_array_elements(plan->'phaseOwners') with ordinality x(ph,ord);
 if actual is distinct from expected then raise exception 'Manual native phase window or static departure changed';end if;
 prior:=null;
 for phase in select value from jsonb_array_elements(plan->'phaseOwners') loop
  if (select coalesce(jsonb_agg(k order by k),'[]') from jsonb_object_keys(phase->'owners') k) is distinct from keys then raise exception 'Manual native phase does not own the 23 exact groups';end if;
  for code,owner in select key,value#>>'{}' from jsonb_each(phase->'owners') loop
   if not exists(select 1 from jsonb_array_elements(p_availability) r where r->>'serviceDate'=d and r->>'slotId'=owner
    and r->>'status'='working' and r#>>'{shift,start}'<=phase#>>'{window,start}' and r#>>'{shift,end}'>=phase#>>'{window,end}')
   then raise exception 'Manual native phase owner is not actually on shift';end if;
   if prior is not null and prior#>>array['owners',code] is distinct from owner and not exists(
    select 1 from jsonb_array_elements(p_availability) r where r->>'serviceDate'=d and r->>'slotId'=prior#>>array['owners',code]
     and r#>>'{shift,end}'=phase#>>'{window,start}') then raise exception 'Manual native phase reshuffled an available owner';end if;
  end loop;
  foreach preferred_key in array array['KAREN','KATHY'] loop
   preferred_slot:=p_config#>>array['slots',preferred_key,'slotId'];
   preferred_codes:=case when preferred_key='KAREN' then array['ZAMBEZI','PRIMATE_PAVILLION'] else array['EAST_ADMIN','WEST_ADMIN'] end;
   if exists(select 1 from jsonb_array_elements(p_availability) r where r->>'serviceDate'=d and r->>'slotId'=preferred_slot
    and r->>'status'='working' and r#>>'{shift,start}'<=phase#>>'{window,start}' and r#>>'{shift,end}'>=phase#>>'{window,end}') then
    foreach code in array preferred_codes loop
     if phase#>>array['owners',code] is distinct from preferred_slot then preferred_minutes:=preferred_minutes+
      extract(epoch from ((phase#>>'{window,end}')::time-(phase#>>'{window,start}')::time))::integer/60;end if;
    end loop;
   end if;
  end loop;
  prior:=phase;
 end loop;
 select coalesce(jsonb_agg(r->'slotId' order by r->>'slotId'),'[]') into expected from jsonb_array_elements(p_availability) r where r->>'serviceDate'=d and r->>'status'='working';
 select coalesce(jsonb_agg(r->'recipientSlotId' order by r->>'recipientSlotId'),'[]') into actual from jsonb_array_elements(plan->'lunchPlans') r;
 if actual is distinct from expected then raise exception 'Manual native full-hour lunch plan omits or duplicates a worker';end if;
 for loan in select value from jsonb_array_elements(plan->'lunchPlans') loop
  select r into strict recipient from jsonb_array_elements(p_availability) r where r->>'serviceDate'=d and r->'slotId'=loan->'recipientSlotId';
  select r into strict helper from jsonb_array_elements(p_availability) r where r->>'serviceDate'=d and r->'slotId'=loan->'covererSlotId';
  if loan->'window' is distinct from recipient->'lunch' or (loan#>>'{window,end}')::time-(loan#>>'{window,start}')::time<>interval '1 hour'
   or loan->'recipientSlotId'=loan->'covererSlotId' or helper->>'status' is distinct from 'working'
   or helper#>>'{shift,start}'>loan#>>'{window,start}' or helper#>>'{shift,end}'<loan#>>'{window,end}'
   or helper#>>'{lunch,start}'<loan#>>'{window,end}' and loan#>>'{window,start}'<helper#>>'{lunch,end}'
  then raise exception 'Manual native full-hour helper availability changed';end if;
  select coalesce(jsonb_agg(to_jsonb(codes.code) order by codes.code collate "C"),'[]') into expected from (
   select distinct key code from jsonb_array_elements(plan->'phaseOwners') p cross join lateral jsonb_each(p->'owners') o
   where p#>>'{window,start}'<loan#>>'{window,end}' and loan#>>'{window,start}'<p#>>'{window,end}' and o.value=loan->'recipientSlotId') codes;
  if loan->'areas' is distinct from expected then raise exception 'Manual native lunch omits inherited groups';end if;
  if loan->>'covererSlotId'=tammy then tammy_reliefs:=tammy_reliefs+1;end if;
 end loop;
 if exists(select 1 from jsonb_array_elements(plan->'lunchPlans') a join jsonb_array_elements(plan->'lunchPlans') b
  on a->'recipientSlotId'<b->'recipientSlotId' and a->'covererSlotId'=b->'covererSlotId'
   and a#>>'{window,start}'<b#>>'{window,end}' and b#>>'{window,start}'<a#>>'{window,end}')
 then raise exception 'Manual native helper appointments overlap';end if;
 -- Derive the slice boundaries independently from actual shift/lunch facts.
 select jsonb_agg(v order by v) into expected from (
  select distinct v from (
   select start_at v union all select end_at union all
   select ph#>>'{window,start}' from jsonb_array_elements(plan->'phaseOwners') ph union all
   select ph#>>'{window,end}' from jsonb_array_elements(plan->'phaseOwners') ph union all
   select av#>>'{lunch,start}' from jsonb_array_elements(p_availability) av where av->>'serviceDate'=d and av->>'status'='working' union all
   select av#>>'{lunch,end}' from jsonb_array_elements(p_availability) av where av->>'serviceDate'=d and av->>'status'='working'
  ) q where v>=start_at and v<=end_at) boundaries;
 select jsonb_agg(v order by v) into actual from (select distinct v from (
  select r#>>'{window,start}' v from jsonb_array_elements(plan->'coverage') r union all
  select r#>>'{window,end}' from jsonb_array_elements(plan->'coverage') r) q) boundaries;
 if actual is distinct from expected then raise exception 'Manual native actual duration slices changed';end if;
 last_t:=start_at;
 for slice in select value from jsonb_array_elements(plan->'coverage') loop
  t:=slice#>>'{window,start}';
  if t is distinct from last_t or t>=slice#>>'{window,end}' then raise exception 'Manual native scored coverage has a gap or overlap';end if;
  select ph into strict phase from jsonb_array_elements(plan->'phaseOwners') ph where ph#>>'{window,start}'<=t and t<ph#>>'{window,end}';
  points:='{}';owners:='{}';n:=0;p_loss:=0;
  for recipient in select r from jsonb_array_elements(p_availability) r where r->>'serviceDate'=d and r->>'status'='working'
   and r#>>'{shift,start}'<=t and t<r#>>'{shift,end}' and not(r#>>'{lunch,start}'<=t and t<r#>>'{lunch,end}') loop
   points:=points||jsonb_build_object(recipient->>'slotId',0);n:=n+1;
  end loop;
  if n=0 then raise exception 'Manual native coverage has no actually available owner';end if;
  for group_row in select value from jsonb_array_elements(p_policy->'groups') loop
   code:=group_row->>'code';normal_owner:=phase#>>array['owners',code];owner:=normal_owner;
   select r into strict recipient from jsonb_array_elements(p_availability) r where r->>'serviceDate'=d and r->>'slotId'=normal_owner;
   if recipient#>>'{lunch,start}'<=t and t<recipient#>>'{lunch,end}' then
    select l into strict loan from jsonb_array_elements(plan->'lunchPlans') l where l->>'recipientSlotId'=normal_owner;
    owner:=loan->>'covererSlotId';
   end if;
   if not(points ? owner) then raise exception 'Manual native owner is off shift or on lunch';end if;
   owners:=owners||jsonb_build_object(code,owner);points:=jsonb_set(points,array[owner],to_jsonb((points->>owner)::integer+(group_row->>'points')::integer));
   if owner=tammy and code not in('TETON','NORTH_WEST_PASSAGE','EAST_END_RESTROOMS','CHINA') then raise exception 'Manual native Tammy received an unauthorized extra';end if;
   if code in('TETON','NORTH_WEST_PASSAGE','EAST_END_RESTROOMS') and points ? tammy and owner is distinct from tammy then raise exception 'Manual native Tammy lost an available core area';end if;
   select r->'baseCodes' into strict anchors from jsonb_array_elements(input->'roster') r where r->>'slotId'=owner;
   select min(case when anchor=code then 0 else (
    select (pair->>'accessPenaltyMeters')::numeric from jsonb_array_elements(p_policy#>'{access,pairs}') pair
     where pair->>'from'=anchor and pair->>'to'=code or pair->>'from'=code and pair->>'to'=anchor) end)
    into distance from jsonb_array_elements_text(anchors) anchor;
   if distance is null then raise exception 'Manual native approved normal distance anchor missing';end if;
   p_loss:=p_loss+distance/807.6262463035904/23;
  end loop;
  select case when n=1 then 0 else sum(abs((v#>>'{}')::numeric-136.0/n))/(272*(1-1.0/n)) end into l_loss from jsonb_each(points) x(k,v);
  minutes:=extract(epoch from ((slice#>>'{window,end}')::time-t::time))/60;
  if slice->'owners' is distinct from owners or slice->'zooWideCoverage' is distinct from to_jsonb(
   (select count(*)=1 from jsonb_array_elements(p_availability) r where r->>'serviceDate'=d and r->>'status'='working' and r#>>'{shift,start}'<=t and t<r#>>'{shift,end}') and n=1)
   or p_loss not between 0 and 1.000000001 or l_loss not between 0 and 1.000000001
  then raise exception 'Manual native complete 23-group slice, Zoo Wide Coverage or penalty scale differs';end if;
  if owners->>'CHINA'=tammy then china_minutes:=china_minutes+minutes::integer;end if;
  p_sum:=p_sum+minutes*p_loss;l_sum:=l_sum+minutes*l_loss;total_minutes:=total_minutes+minutes;last_t:=slice#>>'{window,end}';
 end loop;
 if last_t is distinct from end_at or total_minutes<=0
  or abs((plan#>>'{scoreBreakdown,proximityPenalty}')::numeric-100*p_sum/total_minutes)>0.000001
  or abs((plan#>>'{scoreBreakdown,workloadPenalty}')::numeric-100*l_sum/total_minutes)>0.000001
  or abs((plan#>>'{scoreBreakdown,combinedPenalty}')::numeric-100*(.75*p_sum+.25*l_sum)/total_minutes)>0.000001
  or abs((plan->>'normalizedScore')::numeric-(.75*p_sum+.25*l_sum)/total_minutes)>0.00000001
  or plan->'policyLimits' is distinct from jsonb_build_object('tammyChinaExtraMinutes',china_minutes,'tammyReliefAppointments',tammy_reliefs,'preferredCoreMovedMinutes',preferred_minutes)
 then raise exception 'Manual native exact fixed 75/25 duration score or personal priority evidence differs';end if;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_manual_assert_initial_employment_projection(p_operation uuid, p_manager uuid, p_envelope jsonb, p_lunch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare ctx jsonb;basis jsonb;snapshot jsonb:=p_envelope->'semantic_snapshot';a jsonb:=p_envelope->'authority';source jsonb;
 frame date;publication uuid;version uuid;expected_dates jsonb;day date;dow integer;normal_day jsonb;day_basis jsonb;plan jsonb;
 item jsonb;w jsonb;parent jsonb;link jsonb;availability jsonb;expected jsonb;actual jsonb;slot jsonb;person jsonb;
 base jsonb;exceptions jsonb;summary jsonb;links jsonb:='{}';expected_availability jsonb:='[]';absent jsonb;
 complete_start text;complete_end text;normal_start text;normal_end text;previous_owner text;previous_end text;
 row_owner text;owner_config jsonb;code text;normal_changed boolean;day_changed boolean;inherited boolean;
 input jsonb;phase jsonb;previous_phase jsonb;slice jsonb;loan jsonb;owners jsonb;points jsonb;anchors jsonb;policy jsonb;
 p_loss numeric;l_loss numeric;n integer;minutes numeric;total_minutes numeric;weighted_p numeric;weighted_l numeric;actual_effort numeric;
 count_rows integer;budget integer;assignment uuid;key text;window_start text;window_end text;employment_employee jsonb;pre_start jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 ctx:=public.static_weekly_coverall_initial_context(p_operation,p_manager);
 if ctx->>'schema' is distinct from 'custodial.initial-employment-native-sql-context.v1'
  or ctx->>'kind' is distinct from 'INITIAL_EMPLOYMENT_OPERATIONALIZATION'
  or ctx->>'operationId' is distinct from p_operation::text or ctx->>'managerId' is distinct from p_manager::text
  or ctx->'stagedEnvelope' is distinct from p_envelope or ctx->'stagedLunch' is distinct from p_lunch
  or ctx->>'candidateDigest' is distinct from public.static_weekly_digest_jsonb(jsonb_build_object('envelope',p_envelope,'lunch',p_lunch))
 then raise exception 'Exact original staged initial employment scope required';end if;
 perform public.static_weekly_assert_exact_object(p_envelope,
  array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','semantic_snapshot','database_projection_identity'],
  array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','semantic_snapshot','database_projection_identity'],'manual native projection');
 perform public.static_weekly_assert_exact_object(snapshot,
  array['schema','initialActivation','originalSource','scopeDates','weekStart','generation','catalogEntryDigest','nativeBasisDigest'],
  array['schema','initialActivation','originalSource','scopeDates','weekStart','generation','catalogEntryDigest','nativeBasisDigest'],'manual native original snapshot');
 if snapshot->>'schema' is distinct from 'custodial.approved-manual-initial-employment-snapshot.v1'
  or snapshot->'initialActivation' is distinct from jsonb_build_object('kind','INITIAL_EMPLOYMENT_OPERATIONALIZATION',
   'operationId',p_operation,'managerId',p_manager,'sourceId',ctx->'sourceId','publicationId',ctx->'publicationId','versionId',ctx->'versionId',
   'frameStart',ctx->'frameStart','frameEnd',ctx->'frameEnd','authorityRevision',ctx->'authorityRevision')
  or coalesce(snapshot->>'weekStart','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
  or coalesce(snapshot->>'nativeBasisDigest','')!~'^[0-9a-f]{64}$'
 then raise exception 'Manual native original command differs';end if;
 frame:=(snapshot->>'weekStart')::date;publication:=(snapshot#>>'{originalSource,publication_id}')::uuid;
 basis:=ctx->'basis';
 source:=basis->'normalSource';version:=(basis->>'versionId')::uuid;exceptions:=basis->'preparedExceptions';summary:=basis->'preparedSummary';
 if frame::text is distinct from basis->>'frameStart' or snapshot->'originalSource' is distinct from basis->'originalSource'
  or snapshot->'generation' is distinct from basis->'generation' or snapshot->'catalogEntryDigest' is distinct from basis->'catalogEntryDigest'
  or snapshot->'nativeBasisDigest' is distinct from basis->'basisDigest'
 then raise exception 'Manual native current Source or preparation basis changed';end if;
 if frame::text is distinct from ctx->>'frameStart' or publication::text is distinct from ctx->>'publicationId'
  or (frame+6)::text is distinct from ctx->>'frameEnd' then raise exception 'Initial native actual publication/frame changed';end if;
 select jsonb_agg(d::date::text order by d) into expected_dates from generate_series(frame,frame+6,'1 day') d;
 if snapshot->'scopeDates' is distinct from expected_dates or a->'compilerInput' is distinct from source
  or a->>'schema' is distinct from 'custodial.approved-manual-period-projection-authority.v1'
  or a->>'sourceDigest' is distinct from basis->>'normalSourceDigest'
  or a->>'sourcePublicationId' is distinct from publication::text or a->>'sourceVersionId' is distinct from version::text
  or a->>'frameStart' is distinct from frame::text or a->>'frameEnd' is distinct from (frame+6)::text
  or a->'normalSourceChanged' is distinct from 'false'::jsonb or a->'objectiveSolverRerun' is distinct from 'false'::jsonb
  or a->>'acceptedExceptionsDigest' is distinct from public.static_weekly_digest_jsonb(exceptions)
  or a->'employmentRevisionVector' is distinct from basis->'employmentRevisionVector'
  or a->>'formulaObjectiveDigest' is distinct from '7796e95573b389d8d77fc80502d4f6f7f1b54a5155327f9a7f1eb42a7137f531'
  or p_envelope->'applied_exceptions' is distinct from summary
  or p_envelope->'adapter' is distinct from '{"schema":"custodial.approved-manual-period-database-adapter.v1","version":"approved-manual-period-v1"}'::jsonb
  or p_envelope->>'compiler_version' is distinct from 'approved-manual-period-v1'
  or p_envelope->>'service_date' is distinct from frame::text or p_envelope->>'week_start' is distinct from frame::text
  or p_envelope->>'week_end' is distinct from (frame+6)::text
  or p_envelope->>'authority_digest' is distinct from public.static_weekly_digest_jsonb(a)
  or p_envelope->>'database_projection_identity' is distinct from public.static_weekly_digest_jsonb(p_envelope-'database_projection_identity')
  or p_envelope->'objective' is distinct from jsonb_build_object('contract','OWNER_APPROVED_MANUAL_DATED_75_25_V2',
   'formulaObjectiveDigest',a->'formulaObjectiveDigest','proximityPercent',75,'workloadPercent',25,'normalDaysOptimized',false)
  or p_envelope->'metrics' is distinct from jsonb_build_object('hardConstraints',a->'hardConstraintCount','violations',0)
  or p_envelope#>>'{receipt,schema}' is distinct from 'custodial.approved-manual-native-feasibility-data.v1'
  or p_envelope#>'{receipt,hardConstraintCount}' is distinct from a->'hardConstraintCount'
  or p_envelope#>'{receipt,hardConstraintDigest}' is distinct from a->'hardConstraintDigest'
  or p_envelope#>'{receipt,fixedWitnessDigest}' is distinct from a->'fixedWitnessDigest'
 then raise exception 'Manual native envelope identity or approved formula differs';end if;
 if jsonb_typeof(p_envelope->'assignments') is distinct from 'array' or jsonb_array_length(p_envelope->'assignments') not between 1 and 4096
  or jsonb_typeof(a->'datedDayBases') is distinct from 'array' or jsonb_array_length(a->'datedDayBases')>7
  or jsonb_typeof(a->'parentLinks') is distinct from 'array' or jsonb_array_length(a->'parentLinks')>4096
  or jsonb_typeof(a->'projectionAvailability') is distinct from 'array' or jsonb_array_length(a->'projectionAvailability')>224
  or (select count(*)<>count(distinct r->>'plan_work_id') from jsonb_array_elements(p_envelope->'assignments') r)
  or (select count(*)<>count(distinct r->>'serviceDate') from jsonb_array_elements(a->'datedDayBases') r)
  or (select count(*)<>count(distinct r->>'workId') from jsonb_array_elements(a->'parentLinks') r)
 then raise exception 'Manual native bounded unique records required';end if;
 -- This first admission supports full-day canonical PTO/absence and its exact
 -- cancellation. Other exception shapes fail closed, never silently disappear.
 if exists(select 1 from jsonb_array_elements(exceptions) e where e->>'type' not in('pto','daily_absence') or e ? 'window')
 then raise exception using errcode='0A000',message='Manual native exception requires its qualified dated profile';end if;
 policy:=public.static_weekly_manual_absence_policy();
 for base in select value from jsonb_array_elements(source#>'{version,slotAvailability}') loop
  dow:=(base->>'dayOfWeek')::integer;day:=frame+mod(dow-extract(dow from frame)::integer+7,7);
  availability:=public.static_weekly_approved_dated_effective_availability(base,base->>'slotId',day,exceptions);
  if availability->>'status'='working' and (
   exists(select 1 from jsonb_array_elements(exceptions) e
    join jsonb_array_elements(source#>'{version,slotAvailability}') av on av->'slotId'=e#>'{payload,slotId}' and av->>'dayOfWeek'=dow::text and av->>'status'='working'
    where e->>'serviceDate'=day::text and e->>'type' in('pto','daily_absence'))
   or exists(select 1 from jsonb_array_elements(basis->'employmentByDate') ed
    cross join lateral jsonb_array_elements(ed->'employees') ee
    join jsonb_array_elements(source->'slots') es on exists(select 1 from jsonb_array_elements(es->'incumbencies') ei
     where ei->'personId'=ee->'employeeId' and (ei->>'effectiveStart')::date<=day and (ei->>'effectiveEnd' is null or day<(ei->>'effectiveEnd')::date))
    join jsonb_array_elements(source#>'{version,slotAvailability}') ea on ea->'slotId'=es->'id' and ea->>'dayOfWeek'=dow::text and ea->>'status'='working'
    where ed->>'serviceDate'=day::text and (ee#>>'{command,fact,state}'='PRE_START' or day<(ee#>>'{command,fact,firstServiceDate}')::date))) then
   availability:=availability||'{"blockedWindows":[]}'::jsonb;
  end if;
  select s into strict slot from jsonb_array_elements(source->'slots') s where s->'id'=base->'slotId';
  select i into strict person from jsonb_array_elements(slot->'incumbencies') i
   where (i->>'effectiveStart')::date<=day and (i->>'effectiveEnd' is null or day<(i->>'effectiveEnd')::date);
  select e into employment_employee from jsonb_array_elements(basis->'employmentByDate') d
   cross join lateral jsonb_array_elements(d->'employees') e
   where d->>'serviceDate'=day::text and e->'employeeId'=person->'personId';
  if base->>'status'='working' and employment_employee is not null and
   (employment_employee#>>'{command,fact,state}'='PRE_START' or day<(employment_employee#>>'{command,fact,firstServiceDate}')::date) then
   availability:=availability||'{"status":"absent","blockedWindows":[{"start":"00:00","end":"23:59"}],"unavailabilityClassification":"PRE_START_NOT_PTO"}'::jsonb;
  end if;
  expected_availability:=expected_availability||jsonb_build_array(availability||jsonb_build_object(
   'serviceDate',day::text,'incumbentPersonId',person->'personId','incumbentName',person->'displayName'));
 end loop;
 select coalesce(jsonb_agg(r order by (r->>'dayOfWeek')::integer,r->>'slotId' collate "C"),'[]') into expected from jsonb_array_elements(expected_availability) r;
 select coalesce(jsonb_agg(r order by (r->>'dayOfWeek')::integer,r->>'slotId' collate "C"),'[]') into actual from jsonb_array_elements(a->'projectionAvailability') r;
 if actual is distinct from expected then raise exception 'Manual native static hours, eligibility or actual absence changed';end if;

 for day in select generate_series(frame,frame+6,'1 day')::date loop
  dow:=extract(dow from day)::integer;
  select r into strict normal_day from jsonb_array_elements(policy->'days') r where r->>'weekday'=dow::text;
  select coalesce(jsonb_agg(r->'incumbentPersonId' order by r->>'incumbentPersonId'),'[]') into absent
   from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'status'='absent';
  select coalesce(jsonb_agg(r->'incumbentPersonId' order by r->>'incumbentPersonId'),'[]') into pre_start
   from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'unavailabilityClassification'='PRE_START_NOT_PTO';
  day_changed:=jsonb_array_length(absent)>0;
  select r into day_basis from jsonb_array_elements(a->'datedDayBases') r where r->>'serviceDate'=day::text;
  if day_changed is distinct from (day_basis is not null) then raise exception 'Manual native complete dated day set differs';end if;
  normal_start:=normal_day#>>'{checkedWindow,start}';normal_end:=normal_day#>>'{checkedWindow,end}';
  select max(r#>>'{shift,start}'),max(r#>>'{shift,end}') into complete_start,complete_end
   from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'status'='working';
  if complete_start is null or complete_start>=complete_end then raise exception 'Manual native staffed window is empty';end if;
  if day_changed then
   if jsonb_array_length(absent) not between 1 and 2 or day_basis->>'kind' is distinct from 'ABSENCE' then
    raise exception using errcode='0A000',message='Third absence requires the retained two-absence basis and actual CoverAll hours';end if;
   input:=day_basis->'input';plan:=day_basis->'plan';
   if input->>'inputDigest' is distinct from public.static_weekly_digest_jsonb(input-'inputDigest')
    or plan->>'planDigest' is distinct from public.static_weekly_digest_jsonb(plan-'planDigest')
    or input->'sourceDigest' is distinct from a->'sourceDigest' or input->'formulaObjectiveDigest' is distinct from a->'formulaObjectiveDigest'
    or input->>'serviceDate' is distinct from day::text or plan->>'serviceDate' is distinct from day::text
    or input->'absentPersonIds' is distinct from absent or plan->'absentPersonIds' is distinct from absent
    or coalesce(input->'preStartPersonIds','[]') is distinct from pre_start
    or (jsonb_array_length(pre_start)>0 and input->>'preStartClassification' is distinct from 'PRE_START_NOT_PTO')
    or input->'checkedWindow' is distinct from jsonb_build_object('start',complete_start,'end',complete_end)
    or plan->'checkedWindow' is distinct from input->'checkedWindow' or plan->'inputDigest' is distinct from input->'inputDigest'
    or plan->'proposalDigest' is distinct from a->'formulaObjectiveDigest' or input->'access' is distinct from policy->'access'
    or input->'groups' is distinct from policy->'groups' or plan->'groups' is distinct from policy->'groups'
    or plan->'hardFeasibilityValidatedBeforeScoring' is distinct from 'true'::jsonb or plan->'globalOptimalityClaim' is distinct from 'false'::jsonb
    or exists(select 1 from unnest(array['publicationEligible','weeklyBaselineChanged','productionWritten','contractorBooked']) k where plan->k is distinct from 'false'::jsonb)
   then raise exception 'Manual native dated immutable input, source or formula changed';end if;
   select coalesce(jsonb_agg(jsonb_build_array(r->'slotId',r->'incumbentPersonId',r->'shift',r->'lunch') order by r->>'slotId'),'[]') into expected
    from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'status'='working';
   select coalesce(jsonb_agg(jsonb_build_array(r->'slotId',r->'personId',r->'shift',r->'lunch') order by r->>'slotId'),'[]') into actual from jsonb_array_elements(input->'roster') r;
   if expected is distinct from actual then raise exception 'Manual native dated roster changed';end if;
   for item in select value from jsonb_array_elements(input->'roster') loop
    select r->'baseGroups' into strict expected from jsonb_array_elements(normal_day->'employees') r where r->>'name'=item->>'name';
    select coalesce(jsonb_agg(to_jsonb(r->>'code') order by ord),'[]') into actual
     from jsonb_array_elements(expected) with ordinality x(name,ord) join jsonb_array_elements(policy->'groups') r on r->'name'=name;
    if item->'baseCodes' is distinct from actual then raise exception 'Manual native distance anchor changed from approved normal day';end if;
   end loop;
  end if;

  for item in select value from jsonb_array_elements(p_envelope->'assignments') where value->>'service_date'=day::text loop
   w:=item->'work_snapshot';parent:=null;link:=null;
   select r into parent from jsonb_array_elements(source#>'{version,assignments}') r
    where r->>'dayOfWeek'=dow::text and r->'workId'=item->'work_id';
   if parent is null then
    select r into strict link from jsonb_array_elements(a->'parentLinks') r where r->'workId'=item->'work_id';
    select r into strict parent from jsonb_array_elements(source#>'{version,assignments}') r where r->>'dayOfWeek'=dow::text and r->'workId'=link->'parentWorkId';
    if link->'serviceDate' is distinct from item->'service_date' or link->'window' is distinct from w->'window' or link->'slotId' is distinct from item->'owner_slot_id'
     or coalesce(item->>'work_id','')!~'^manual-dated:[0-9a-f]{64}$' then raise exception 'Manual native parent lineage differs';end if;
   end if;
   select r into strict availability from jsonb_array_elements(expected_availability) r where r->'slotId'=item->'owner_slot_id' and r->>'serviceDate'=day::text;
   select value into strict owner_config from jsonb_each(basis#>'{ownerConfig,slots}') where value->'slotId'=item->'owner_slot_id';
   window_start:=w#>>'{window,start}';window_end:=w#>>'{window,end}';
   perform public.static_weekly_v3_assert_window(w->'window','manual native custody');
   if item->>'status' is distinct from 'assigned' or item->'reason_code' is distinct from 'null'::jsonb
    or item->>'day_of_week' is distinct from dow::text or item->>'plan_work_id' is distinct from dow::text||':'||(item->>'work_id')
    or item->'owner_person_id' is distinct from availability->'incumbentPersonId' or item->'optimized_owner_person_id' is distinct from item->'owner_person_id'
    or item->'optimized_owner_slot_id' is distinct from item->'owner_slot_id' or item ? 'owner_kind' or item ? 'capacity_id'
    or availability->>'status' is distinct from 'working' or window_start<availability#>>'{shift,start}' or window_end>availability#>>'{shift,end}'
    or item->'baseline_owner_slot_id' is distinct from parent->'originSlotId' or w->'originSlotId' is distinct from parent->'originSlotId'
   then raise exception 'Manual native actual static owner, window or original actor changed';end if;
   select r into strict base from jsonb_array_elements(expected_availability) r where r->'slotId'=parent->'originSlotId' and r->>'serviceDate'=day::text;
   if item->'baseline_owner_person_id' is distinct from base->'incumbentPersonId' or item->'original_actor_person_id' is distinct from base->'incumbentPersonId'
    or item->'baseline_owner_name' is distinct from base->'incumbentName' or item->'original_actor_name' is distinct from base->'incumbentName'
    or item->>'owner_digest' is distinct from public.static_weekly_digest_jsonb(jsonb_build_object('planWorkId',item->'plan_work_id','slotId',item->'owner_slot_id','personId',item->'owner_person_id','serviceDate',item->'service_date'))
    or item->>'exact_owner_identity' is distinct from public.static_weekly_digest_jsonb(jsonb_build_object('plan_work_id',item->'plan_work_id','service_date',item->'service_date','optimized_owner_slot_id',item->'owner_slot_id','optimized_owner_person_id',item->'owner_person_id','baseline_owner_slot_id',parent->'originSlotId','baseline_owner_person_id',base->'incumbentPersonId'))
   then raise exception 'Manual native owner lineage digest changed';end if;
   inherited:=day_changed and exists(select 1 from jsonb_array_elements(plan->'phaseOwners') with ordinality x(ph,phase_number)
    where phase_number>1 and ph#>>'{window,start}'<=window_start and window_start<ph#>>'{window,end}');
   expected:=jsonb_build_object('workId',item->'work_id','dayOfWeek',dow,'originSlotId',parent->'originSlotId',
    'locationId',parent->'locationId','locationCodeSnapshot',parent->'locationCodeSnapshot','locationNameSnapshot',parent->'locationNameSnapshot',
    'serviceMode',parent->'serviceMode','includedLocations',parent->'includedLocations','window',w->'window',
    'serviceEffortMinutes',w->'serviceEffortMinutes','serviceEffortProvenance',w->'serviceEffortProvenance',
    'priority',parent->'priority','priorityProvenance',parent->'priorityProvenance','required',parent->'required',
    'coveragePolicy',null,'bestEffortCoverage',false,'coveragePolicyOrder',null,'coveragePolicyProvenance',null,
    'requiredQualifications',parent->'requiredQualifications','qualificationProvenance',parent->'qualificationProvenance',
    'restrictions',parent->'restrictions','restrictionProvenance',parent->'restrictionProvenance','restrictedSlotIds',parent->'restrictedSlotIds',
    'manualLock',false,'manualLockSlotId',null,'overlayWork',false);
   if jsonb_array_length(coalesce(parent->'normalAssignmentRestrictedSlotIds','[]'))>0 then
    expected:=expected||jsonb_build_object('normalAssignmentRestrictedSlotIds',parent->'normalAssignmentRestrictedSlotIds','coveragePurpose',parent->'coveragePurpose');
   end if;
   if inherited and dow<>1 and parent->>'locationCodeSnapshot'='HERPETARIUM'
    and parent->'restrictedSlotIds' ? (basis#>>'{ownerConfig,slots,ALIJAH,slotId}') then
    expected:=expected||jsonb_build_object('restrictedSlotIds',(parent->'restrictedSlotIds')-(basis#>>'{ownerConfig,slots,ALIJAH,slotId}'),
     'normalAssignmentRestrictedSlotIds',jsonb_build_array(basis#>>'{ownerConfig,slots,ALIJAH,slotId}'),
     'coveragePurpose','INHERITED_ALERTS_AND_ISSUES_ONLY','restrictionProvenance',(parent->>'restrictionProvenance')||';normal-assignment-scope:fe02bbdebc736d95360b55cc7dfe5b73c5a9eaa76f364f1c0f4420a0afb9950f');
   end if;
   if w is distinct from expected or not ((availability->'qualifications') @> (w->'requiredQualifications'))
    or w->'restrictedSlotIds' ? (item->>'owner_slot_id') or owner_config->'hardForbiddenFamilies' ? (w->>'locationCodeSnapshot')
    or exists(select 1 from jsonb_array_elements(w->'includedLocations') r where availability->'restrictions' ? (r->>'locationId'))
    or (item->>'owner_slot_id'=basis#>>'{ownerConfig,slots,TAMMY,slotId}' and w->>'locationCodeSnapshot' not in('TETON','NORTH_WEST_PASSAGE','EAST_END_RESTROOMS','CHINA'))
   then raise exception 'Manual native physical members, hard eligibility or scoped restriction changed: work %, fields %',item->>'work_id',
    (select coalesce(jsonb_agg(k order by k),'[]') from (select jsonb_object_keys(w||expected) k) q where w->k is distinct from expected->k);end if;
   if not day_changed and (link is not null or item->'owner_slot_id' is distinct from parent->'ownerSlotId' or w->'window' is distinct from parent->'window'
    or w->'serviceEffortMinutes' is distinct from parent->'serviceEffortMinutes' or w->'serviceEffortProvenance' is distinct from parent->'serviceEffortProvenance')
   then raise exception 'Manual native changed an approved normal day';end if;
   if day_changed and (window_end>parent#>>'{window,end}' or window_start<case
    when parent#>>'{window,start}'<=normal_start and parent#>>'{window,end}'>normal_start
     then least(parent#>>'{window,start}',complete_start) else parent#>>'{window,start}' end)
   then raise exception 'Manual native custody exceeds its exact parent boundary';end if;
   -- A single unchanged owner can continue across the complete-crew arrival.
   -- That harmless merged row must still preserve the whole early base prefix.
   if day_changed and window_start<complete_start and (item->'owner_slot_id' is distinct from parent->'ownerSlotId'
    or window_start<>parent#>>'{window,start}' or window_end<least(parent#>>'{window,end}',complete_start))
   then raise exception 'Manual native early own-base custody differs';end if;
   if day_changed and window_end>complete_start then
    if window_end>complete_end then raise exception 'Manual native actual full-site window differs';end if;
    for phase in select value from jsonb_array_elements(plan->'phaseOwners') where value#>>'{window,start}'<window_end and window_start<value#>>'{window,end}' loop
     if phase#>>array['owners',w->>'locationCodeSnapshot'] is distinct from item->>'owner_slot_id' then raise exception 'Manual native selected phase differs from stored custody';end if;
    end loop;
   end if;
   select assignment_id into strict assignment from public.weekly_schedule_slot_assignments
    where version_id=version and day_of_week=dow and work_id=parent->>'workId';
   links:=links||jsonb_build_object(item->>'plan_work_id',assignment::text);
  end loop;

  -- Every physical group tiles the complete actual staffed window once.
  for code in select r->>'code' from jsonb_array_elements(policy->'groups') r loop
   previous_end:=complete_start;previous_owner:=null;
   for item in select r from jsonb_array_elements(p_envelope->'assignments') r where r->>'service_date'=day::text
    and r#>>'{work_snapshot,locationCodeSnapshot}'=code and r#>>'{work_snapshot,window,end}'>complete_start
    order by r#>>'{work_snapshot,window,start}' loop
    window_start:=greatest(complete_start,item#>>'{work_snapshot,window,start}');window_end:=least(complete_end,item#>>'{work_snapshot,window,end}');
    if window_end<=window_start then continue;end if;
    if window_start<>previous_end then raise exception 'Manual native full-site gap or overlap';end if;
    if day_changed and previous_owner is not null and previous_owner<>item->>'owner_slot_id' and not exists(
     select 1 from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'slotId'=previous_owner and r#>>'{shift,end}'=window_start)
    then raise exception 'Manual native owner moved before the static departure';end if;
    previous_end:=window_end;previous_owner:=item->>'owner_slot_id';
   end loop;
   if previous_end<>complete_end then raise exception 'Manual native full-site coverage incomplete';end if;
   select sum((r->>'serviceEffortMinutes')::integer) into budget from jsonb_array_elements(source#>'{version,assignments}') r where r->>'dayOfWeek'=dow::text and r->>'locationCodeSnapshot'=code;
   select sum((r#>>'{work_snapshot,serviceEffortMinutes}')::integer) into actual_effort from jsonb_array_elements(p_envelope->'assignments') r where r->>'service_date'=day::text and r#>>'{work_snapshot,locationCodeSnapshot}'=code;
   if actual_effort is distinct from budget then raise exception 'Manual native combined group workload budget changed';end if;
  end loop;
  if not day_changed and (select count(*) from jsonb_array_elements(p_envelope->'assignments') r where r->>'service_date'=day::text)
   <>(select count(*) from jsonb_array_elements(source#>'{version,assignments}') r where r->>'dayOfWeek'=dow::text)
  then raise exception 'Manual native omitted approved normal rows';end if;
  if day_changed then
   perform public.static_weekly_manual_assert_absence_score(day_basis,normal_day,policy,expected_availability,p_envelope->'assignments',basis->'ownerConfig');
  end if;
 end loop;
 if (select count(*) from jsonb_object_keys(links))<>jsonb_array_length(p_envelope->'assignments')
  or exists(select 1 from jsonb_array_elements(a->'parentLinks') l where not exists(select 1 from jsonb_array_elements(p_envelope->'assignments') r where r->'work_id'=l->'workId' and r->'service_date'=l->'serviceDate'))
 then raise exception 'Manual native foreign row or unused parent link';end if;
 if summary is distinct from public.static_weekly_accepted_exception_set(publication,frame)
 then raise exception 'Manual native original fact did not become exact accepted authority';end if;
 perform public.static_weekly_manual_assert_native_lunch(NULL,p_lunch,p_envelope,publication,frame);
 return jsonb_build_object('assignment_links',links,'projection_assignments',p_envelope->'assignments','kind','INITIAL_EMPLOYMENT_OPERATIONALIZATION');
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_manual_assert_lunch_lineage(p_envelope jsonb, p_document jsonb, p_publication uuid, p_week date)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare retention jsonb:=p_envelope#>'{authority,lunchIdentityRetention}';prior jsonb;loan jsonb;old_loan jsonb;r jsonb;intent jsonb;
 record jsonb;fresh text;area_id text;expected jsonb;actual jsonb;expected_evidence jsonb;target text;edge jsonb;
 cost integer;total_cost integer;source jsonb:=p_envelope#>'{authority,compilerInput}';
begin
 if p_envelope->>'replay_digest' is distinct from public.static_weekly_digest_jsonb(jsonb_build_object(
  'projectionAssignments',p_envelope->'assignments','lunchDocument',p_document-array['base_authority_digest','base_replay_digest','document_identity']))
 then raise exception 'Manual native complete lunch replay differs';end if;
 if retention is not null then
  perform public.static_weekly_assert_exact_object(retention,array['schema','priorProjectionId','priorDocumentIdentity','loans','requiresSqlOwnerCurrentnessCheck'],array['schema','priorProjectionId','priorDocumentIdentity','loans','requiresSqlOwnerCurrentnessCheck'],'manual native retained lunch lineage');
  if retention->>'schema' is distinct from 'custodial.approved-manual-lunch-identity-retention.v1'
   or retention->'requiresSqlOwnerCurrentnessCheck' is distinct from 'true'::jsonb or jsonb_typeof(retention->'loans') is distinct from 'array'
   or (select count(*)<>count(distinct v->>'loanId') from jsonb_array_elements(retention->'loans') v)
  then raise exception 'Manual native retained lunch lineage malformed';end if;
  select l.document_json into strict prior from public.weekly_schedule_compiled_projections p join public.weekly_schedule_lunch_documents l using(projection_id)
   where p.projection_id=(retention->>'priorProjectionId')::uuid and p.publication_id=p_publication and p.week_start=p_week and p.week_end=p_week+6
    and p.version_id::text=p_envelope#>>'{authority,sourceVersionId}' and l.document_identity=retention->>'priorDocumentIdentity';
 end if;
 for loan in select value from jsonb_array_elements(p_document->'loans') loop
  fresh:=public.static_weekly_digest_text(public.static_weekly_manual_identity_json(jsonb_build_object(
   'policy','owner-20260921-two-nearby-full-hour-v1','input',p_envelope#>'{authority,overlayInputDigest}',
   'serviceDate',loan->'service_date','ownerSlotId',loan->'normal_owner_slot_id','start',loan->'coverage_start','end',loan->'coverage_end')));
  select v into record from jsonb_array_elements(coalesce(retention->'loans','[]')) v where v->'loanId'=loan->'loan_id';
  if record is not null then
   if record is distinct from jsonb_build_object('serviceDate',loan->'service_date','normalOwnerSlotId',loan->'normal_owner_slot_id','loanId',loan->'loan_id') then raise exception 'Manual native retained loan scope changed';end if;
   select v into strict old_loan from jsonb_array_elements(prior->'loans') v where v->'loan_id'=loan->'loan_id';
   if loan-array['loan_id','total_distance_minutes'] is distinct from old_loan-array['loan_id','total_distance_minutes'] then raise exception 'Manual native retained loan changed its helper or actual hour';end if;
   select coalesce(jsonb_agg(v-array['loan_id','responsibility_id','proximity_evidence'] order by (v-array['loan_id','responsibility_id','proximity_evidence'])::text),'[]') into expected from jsonb_array_elements(prior->'responsibilities') v where v->'loan_id'=loan->'loan_id';
   select coalesce(jsonb_agg(v-array['loan_id','responsibility_id','proximity_evidence'] order by (v-array['loan_id','responsibility_id','proximity_evidence'])::text),'[]') into actual from jsonb_array_elements(p_document->'responsibilities') v where v->'loan_id'=loan->'loan_id';
   if actual is distinct from expected then raise exception 'Manual native retained physical lunch duties changed';end if;
   select coalesce(jsonb_agg(v-array['loan_id','notification_key'] order by (v-array['loan_id','notification_key'])::text),'[]') into expected from jsonb_array_elements(prior->'notification_intents') v where v->'loan_id'=loan->'loan_id';
   select coalesce(jsonb_agg(v-array['loan_id','notification_key'] order by (v-array['loan_id','notification_key'])::text),'[]') into actual from jsonb_array_elements(p_document->'notification_intents') v where v->'loan_id'=loan->'loan_id';
   if actual is distinct from expected then raise exception 'Manual native retained delivery identities changed';end if;
  elsif loan->>'loan_id' is distinct from fresh then raise exception 'Manual native fresh loan key or retained immutable lineage differs';end if;
  total_cost:=0;
  for r in select value from jsonb_array_elements(p_document->'responsibilities') where value->'loan_id'=loan->'loan_id' loop
   select public.static_weekly_digest_text(public.static_weekly_manual_identity_json(jsonb_agg(jsonb_build_object(
    'work',s->'planWorkId','start',extract(epoch from (s#>>'{normalWindow,start}')::time)::integer/60,
    'end',extract(epoch from (s#>>'{normalWindow,end}')::time)::integer/60) order by s->>'planWorkId' collate "C"))) into area_id from jsonb_array_elements(r->'segments') s;
   fresh:=public.static_weekly_digest_text(public.static_weekly_manual_identity_json(jsonb_build_object('loanId',r->'loan_id','areaId',area_id,'covererSlotId',r->'coverer_slot_id')));
   if r->>'responsibility_id' is distinct from fresh then raise exception 'Manual native canonical physical responsibility key differs';end if;
   expected_evidence:='[]';cost:=0;
   for target in select distinct w#>>'{work_snapshot,locationId}' from jsonb_array_elements(r->'segments') s
    join jsonb_array_elements(p_envelope->'assignments') w on w->'plan_work_id'=s->'planWorkId' and w->'service_date'=r->'service_date'
    order by 1 loop
    with current_anchors as (
     select distinct w#>>'{work_snapshot,locationId}' id from jsonb_array_elements(p_envelope->'assignments') w
      where w->'service_date'=r->'service_date' and w->'owner_slot_id'=r->'coverer_slot_id'
       and w#>>'{work_snapshot,window,start}'<loan->>'coverage_end' and loan->>'coverage_start'<w#>>'{work_snapshot,window,end}'
    ), anchors as (
     select id from current_anchors
     union all
     select a->>'acceptedRouteAnchorLocationId' from jsonb_array_elements(p_envelope#>'{authority,projectionAvailability}') a
      where a->'serviceDate'=r->'service_date' and a->'slotId'=r->'coverer_slot_id'
       and jsonb_typeof(a->'acceptedRouteAnchorLocationId')='string'
       and coalesce(btrim(a->>'acceptedRouteProvenance'),'')<>'' and not exists(select 1 from current_anchors)
       and exists(select 1 from (
        select v as availability from jsonb_array_elements(source#>'{version,slotAvailability}') v
        union all
        select v||jsonb_build_object('slotId',s->'id') from jsonb_array_elements(source->'slots') s
         cross join lateral jsonb_array_elements(case when jsonb_typeof(s->'contractorAvailability')='array' then s->'contractorAvailability' else '[]'::jsonb end) v
       ) approved where approved.availability->'slotId'=a->'slotId' and approved.availability->'dayOfWeek'=a->'dayOfWeek'
        and approved.availability->'acceptedRouteAnchorLocationId'=a->'acceptedRouteAnchorLocationId'
        and approved.availability->'acceptedRouteProvenance'=a->'acceptedRouteProvenance')
    ), choices as (
     select jsonb_build_object('fromLocationId',id,'toLocationId',target,'minutes',0,'provenance','same_normal_assigned_area') value from anchors where id=target
     union all
     select jsonb_build_object('fromLocationId',id,'toLocationId',target,'minutes',e->'minutes','provenance',e->'provenance')
      from anchors join jsonb_array_elements(source->'proximity') e on
       (e->>'fromLocationId'=id and e->>'toLocationId'=target or e->>'toLocationId'=id and e->>'fromLocationId'=target)
      where e->'verified'='true'::jsonb and jsonb_typeof(e->'minutes')='number' and coalesce(e->>'provenance','')<>''
    ) select value into edge from choices order by (value->>'minutes')::integer,value->>'fromLocationId' collate "C",value->>'provenance' collate "C" limit 1;
    if edge is null then raise exception 'Manual native full-hour helper lacks verified proximity evidence';end if;
    expected_evidence:=expected_evidence||jsonb_build_array(edge);cost:=greatest(cost,(edge->>'minutes')::integer);
   end loop;
   if r->'proximity_evidence' is distinct from expected_evidence then raise exception 'Manual native full-hour proximity differs from actual source edges and current helper areas';end if;
   total_cost:=total_cost+cost;
  end loop;
  if loan->'total_distance_minutes' is distinct from to_jsonb(total_cost) then raise exception 'Manual native lunch proximity total differs';end if;
 end loop;
 if exists(select 1 from jsonb_array_elements(coalesce(retention->'loans','[]')) retained_item where not exists(select 1 from jsonb_array_elements(p_document->'loans') l where l->'loan_id'=retained_item->'loanId')) then raise exception 'Manual native unused retained lunch key';end if;
 for intent in select value from jsonb_array_elements(p_document->'notification_intents') loop
  fresh:=public.static_weekly_digest_text(public.static_weekly_manual_identity_json(jsonb_build_object('loanId',intent->'loan_id','slot',intent->'coverer_slot_id','event',intent->'event')));
  if intent->>'notification_key' is distinct from fresh then raise exception 'Manual native canonical lunch notification key differs';end if;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_manual_assert_native_lunch(p_projection_id uuid, p_document jsonb, p_envelope jsonb, p_publication uuid, p_week date)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
 projection public.weekly_schedule_compiled_projections%rowtype;
 loan jsonb;responsibility jsonb;segment jsonb;intent jsonb;availability jsonb;helper jsonb;
 base_work jsonb;expected jsonb;actual jsonb;helper_id text;identity_key text;
 start_time time;end_time time;
 projection_availability jsonb;projection_assignments jsonb;projection_work jsonb;
 full_hour_policy jsonb;full_hour boolean;planned_loan jsonb;normal_segment_window jsonb;
 native_source jsonb;native_availability jsonb;native_slot jsonb;native_day jsonb;native_overlay jsonb;
 native_substitute jsonb;native_template jsonb;native_expected jsonb;native_parties jsonb:='[]'::jsonb;
begin
 perform public.static_weekly_assert_exact_object(p_document,
  array['schema','persistence_authority','verification_status','week_start','base_authority_digest','base_replay_digest','source_input_digest','candidate_digest','loans','responsibilities','notification_intents','semantic_snapshot','document_identity'],
  array['schema','persistence_authority','verification_status','week_start','base_authority_digest','base_replay_digest','source_input_digest','candidate_digest','loans','responsibilities','notification_intents','semantic_snapshot','document_identity'],'lunch document');
 if p_projection_id is not null then
  select * into strict projection from public.weekly_schedule_compiled_projections where projection_id=p_projection_id;
  if projection.publication_id is distinct from p_publication or projection.week_start is distinct from p_week
   or projection.projection_envelope is distinct from p_envelope then
   raise exception 'Native lunch stored projection context differs from the exact supplied native envelope';end if;
 end if;
 projection.publication_id:=p_publication;projection.week_start:=p_week;projection.projection_envelope:=p_envelope;projection.authority_digest:=p_envelope->>'authority_digest';projection.replay_digest:=p_envelope->>'replay_digest';

 projection_availability:=projection.projection_envelope#>'{authority,projectionAvailability}';
 projection_assignments:=projection.projection_envelope->'assignments';
 select jsonb_agg(r->'work_snapshot'||'{"schedulingMode":"flexible_coverage_ownership"}'::jsonb) into projection_work from jsonb_array_elements(p_envelope->'assignments') r;
 full_hour_policy:=public.static_weekly_manual_native_lunch_policy(p_envelope);full_hour:=true;
 if full_hour then
  perform public.static_weekly_assert_exact_object(full_hour_policy,
   array['schema','sourceDigest','loans','policyDigest'],array['schema','sourceDigest','loans','policyDigest'],'full lunch policy');
  if full_hour_policy->>'schema' is distinct from 'memphis-zoo.static-weekly-full-hour-lunch-policy.v1'
   or jsonb_typeof(full_hour_policy->'sourceDigest') is distinct from 'string'
   or coalesce(full_hour_policy->>'sourceDigest','') !~ '^[0-9a-f]{64}$'
   or full_hour_policy->>'policyDigest' is distinct from public.static_weekly_digest_jsonb(full_hour_policy-'policyDigest')
   or jsonb_typeof(full_hour_policy->'loans') is distinct from 'array'
   or jsonb_array_length(full_hour_policy->'loans')>1792 then raise exception 'invalid full lunch source policy';end if;
  for planned_loan in select value from jsonb_array_elements(full_hour_policy->'loans') loop
   perform public.static_weekly_assert_exact_object(planned_loan,
    array['dayOfWeek','normalOwnerSlotId','window','areas'],array['dayOfWeek','normalOwnerSlotId','window','areas'],'full lunch source loan');
   perform public.static_weekly_v3_assert_window(planned_loan->'window','full lunch source window');
   if jsonb_typeof(planned_loan->'dayOfWeek') is distinct from 'number'
    or (planned_loan->>'dayOfWeek') !~ '^[0-6]$'
    or jsonb_typeof(planned_loan->'normalOwnerSlotId') is distinct from 'string'
    or length(planned_loan->>'normalOwnerSlotId') not between 1 and 512
    or jsonb_typeof(planned_loan->'areas') is distinct from 'array'
    or jsonb_array_length(planned_loan->'areas')>128 then raise exception 'invalid full lunch source owner or areas';end if;
  end loop;
  select coalesce(jsonb_agg(entry order by entry::text),'[]') into expected from
   (select jsonb_build_array(value->'dayOfWeek',value->'normalOwnerSlotId') entry
    from jsonb_array_elements(full_hour_policy->'loans')) q;
  select coalesce(jsonb_agg(entry order by entry::text),'[]') into actual from
   (select jsonb_build_array(value->'day_of_week',value->'normal_owner_slot_id') entry
    from jsonb_array_elements(p_document->'loans')) q;
  if expected is distinct from actual then raise exception 'full lunch source owner set changed';end if;
 end if;

 if p_document->>'schema' is distinct from 'memphis-zoo.static-weekly-lunch-authority-document.v1'
  or p_document->>'persistence_authority' is distinct from 'NOT_PERSISTED'
  or p_document->>'verification_status' is distinct from 'VERIFIED'
  or p_document->>'week_start' is distinct from projection.week_start::text
  or p_document->>'base_authority_digest' is distinct from projection.authority_digest
  or p_document->>'base_replay_digest' is distinct from projection.replay_digest
  or p_document->>'source_input_digest' is distinct from projection.projection_envelope#>>'{authority,overlayInputDigest}'
  or coalesce(p_document->>'candidate_digest','') !~ '^[0-9a-f]{64}$'
  or p_document->>'document_identity' is distinct from public.static_weekly_digest_jsonb(p_document-'document_identity') then
  raise exception 'lunch document is not bound to the exact verified projection';
 end if;
 foreach identity_key in array array['loans','responsibilities','notification_intents'] loop
  if jsonb_typeof(p_document->identity_key) is distinct from 'array'
   or jsonb_array_length(p_document->identity_key)>4096 then raise exception 'lunch document array invalid'; end if;
 end loop;
 expected:=jsonb_build_object('schema','memphis-zoo.static-weekly-lunch-semantic-snapshot.v1',
  'loans_digest',public.static_weekly_digest_jsonb(p_document->'loans'),
  'responsibilities_digest',public.static_weekly_digest_jsonb(p_document->'responsibilities'),
  'notification_intents_digest',public.static_weekly_digest_jsonb(p_document->'notification_intents'));
 if p_document->'semantic_snapshot' is distinct from expected then raise exception 'lunch semantic snapshot mismatch'; end if;
 if (select count(*)<>count(distinct value->>'loan_id') from jsonb_array_elements(p_document->'loans'))
 or (select count(*)<>count(distinct value->>'responsibility_id') from jsonb_array_elements(p_document->'responsibilities'))
 or (select count(*)<>count(distinct value->>'notification_key') from jsonb_array_elements(p_document->'notification_intents')) then
  raise exception 'duplicate or missing lunch record identity'; end if;
 -- Native typed capacity has no legacy recurring command and may not yet
 -- have a stored projection. Validate its immutable native source instead.
 if exists(select 1 from jsonb_array_elements(projection_availability) a
   where a->>'status'='working' and (a->>'ownerKind'='CONTRACTOR_CAPACITY' or a ? 'capacityId')) then
  native_source:=p_envelope#>'{authority,compilerInput}';
  if jsonb_typeof(native_source) is distinct from 'object'
   or p_envelope#>>'{authority,schema}' is distinct from 'custodial.approved-manual-period-projection-authority.v1'
   or p_envelope#>>'{authority,sourceDigest}' is distinct from public.static_weekly_digest_jsonb(native_source)
   or native_source#>>'{version,publicationId}' is distinct from p_publication::text
   or p_envelope#>>'{authority,sourcePublicationId}' is distinct from p_publication::text
   or p_envelope#>>'{authority,sourceVersionId}' is distinct from native_source#>>'{version,id}'
   or nullif(native_source#>>'{version,id}','') is null
   or native_source->>'serviceDate' is distinct from p_week::text
   or p_envelope->>'authority_digest' is distinct from public.static_weekly_digest_jsonb(p_envelope->'authority')
   or p_envelope->>'database_projection_identity' is distinct from public.static_weekly_digest_jsonb(p_envelope-'database_projection_identity')
   then raise exception 'Native typed lunch source or envelope identity changed';end if;
  for native_availability in select value from jsonb_array_elements(projection_availability)
   where value->>'status'='working' and (value->>'ownerKind'='CONTRACTOR_CAPACITY' or value ? 'capacityId') loop
   if native_availability->>'ownerKind' is distinct from 'CONTRACTOR_CAPACITY'
    or nullif(native_availability->>'slotId','') is null
    or native_availability->>'capacityId' is distinct from native_availability->>'slotId'
    or native_availability->'incumbentPersonId' is distinct from 'null'::jsonb
    or native_availability->'incumbentName' is distinct from 'null'::jsonb
    or (native_availability->>'serviceDate')::date not between p_week and p_week+6
    or native_availability->'dayOfWeek' is distinct from to_jsonb(extract(dow from (native_availability->>'serviceDate')::date)::integer)
    or (select count(*) from jsonb_array_elements(projection_availability) a
      where a->>'slotId'=native_availability->>'slotId' and a->>'serviceDate'=native_availability->>'serviceDate')<>1
    then raise exception 'Native typed lunch requires unique working capacity with explicit null person';end if;
   select value into strict native_slot from jsonb_array_elements(native_source->'slots')
    where value->>'id'=native_availability->>'slotId';
   if native_slot->>'kind' is distinct from 'CONTRACTOR_CAPACITY'
    or native_slot->'incumbencies' is distinct from '[]'::jsonb
    or public.static_weekly_capacity_registered(native_slot) is not true
    then raise exception 'Native typed lunch capacity is not the exact registered nonemployee source slot';end if;
   select value into strict native_day from jsonb_array_elements(p_envelope#>'{authority,datedDayBases}')
    where value->>'serviceDate'=native_availability->>'serviceDate' and value->>'kind'='COVERALL';
   native_overlay:=native_day->'overlay';native_substitute:=native_overlay->'substitute';
   if coalesce(native_overlay->>'schema','') not in('custodial.approved-manual-coverall-overlay.v1','custodial.approved-manual-coverall-overlay.v2')
    or native_overlay->>'status' is distinct from 'VALIDATED_UNPUBLISHED_COVERALL_OVERLAY'
    or native_overlay->>'overlayDigest' is distinct from public.static_weekly_digest_jsonb(native_overlay-'overlayDigest')
    or native_overlay->>'sourceDigest' is distinct from p_envelope#>>'{authority,sourceDigest}'
    or native_overlay->>'serviceDate' is distinct from native_availability->>'serviceDate'
    or native_day#>>'{input,sourceDigest}' is distinct from p_envelope#>>'{authority,sourceDigest}'
    or native_day#>>'{input,inputDigest}' is distinct from public.static_weekly_digest_jsonb((native_day->'input')-'inputDigest')
    or native_day#>>'{plan,planDigest}' is distinct from public.static_weekly_digest_jsonb((native_day->'plan')-'planDigest')
    or native_overlay->>'acceptedPlanDigest' is distinct from native_day#>>'{plan,planDigest}'
    or native_substitute->>'kind' is distinct from 'CONTRACTOR_CAPACITY'
    or native_substitute->>'slotId' is distinct from native_availability->>'slotId'
    or native_substitute->'actualHoursConfirmed' is distinct from 'true'::jsonb
    or jsonb_typeof(native_substitute->'confirmationReference') is distinct from 'string'
    or length(native_substitute->>'confirmationReference') not between 1 and 256
    or native_substitute->'shift' is distinct from native_availability->'shift'
    or native_substitute#>>'{lunch,start}' is distinct from native_availability#>>'{lunch,start}'
    or native_substitute#>>'{lunch,end}' is distinct from native_availability#>>'{lunch,end}'
    then raise exception 'Native typed lunch does not bind its exact confirmed CoverAll overlay';end if;
   select value into strict native_template from jsonb_array_elements(native_slot->'contractorAvailability')
    where value->'dayOfWeek'=native_availability->'dayOfWeek';
   native_expected:=(native_template-'breakChoice')||jsonb_build_object(
    'slotId',native_slot->'id','dayOfWeek',native_availability->'dayOfWeek','status','working',
    'shift',native_substitute->'shift',
    'lunch',(native_substitute->'lunch')||jsonb_build_object(
      'startMinute',(extract(epoch from (native_substitute#>>'{lunch,start}')::time)/60)::integer,
      'endMinute',(extract(epoch from (native_substitute#>>'{lunch,end}')::time)/60)::integer),
    'maxDutyMinutes',(extract(epoch from ((native_substitute#>>'{shift,end}')::time-(native_substitute#>>'{shift,start}')::time))/60)::integer-60,
    'maxDutyProvenance',native_template->'productiveCapacityProvenance','blockedWindows','[]'::jsonb,
    'serviceDate',native_availability->'serviceDate','incumbentPersonId','null'::jsonb,
    'incumbentName','null'::jsonb,'ownerKind','CONTRACTOR_CAPACITY','capacityId',native_slot->'id');
   if native_availability is distinct from native_expected then
    raise exception 'Native typed lunch hours, eligibility or raw lunch differ from registered capacity and confirmed overlay';end if;
   native_parties:=native_parties||jsonb_build_array(jsonb_build_object(
    'service_date',native_availability->'serviceDate','day_of_week',native_availability->'dayOfWeek',
    'slot_id',native_slot->'id','capacity_id',native_slot->'id','person_id','null'::jsonb));
  end loop;
 end if;
 select coalesce(jsonb_agg(jsonb_build_array(value->>'serviceDate',value->>'slotId') order by value->>'serviceDate',value->>'slotId'),'[]')
 into expected from jsonb_array_elements(projection_availability)
 where value->>'status'='working' and (nullif(value->>'incumbentPersonId','') is not null or value->>'ownerKind'='CONTRACTOR_CAPACITY')
  and (value->>'ownerKind'='CONTRACTOR_CAPACITY' and value->>'breakChoice'='NONE' and value->'lunch'='null'::jsonb) is not true;
 select coalesce(jsonb_agg(jsonb_build_array(value->>'service_date',value->>'normal_owner_slot_id') order by value->>'service_date',value->>'normal_owner_slot_id'),'[]')
 into actual from jsonb_array_elements(p_document->'loans');
 if actual is distinct from expected then raise exception 'lunch coverage omits or duplicates a working owner'; end if;
 for loan in select value from jsonb_array_elements(p_document->'loans') loop
  if loan ? 'normal_owner_capacity_id' then
   if not(native_parties @> jsonb_build_array(jsonb_build_object(
     'service_date',loan->'service_date','day_of_week',loan->'day_of_week',
     'slot_id',loan->'normal_owner_slot_id','capacity_id',loan->'normal_owner_capacity_id',
     'person_id',loan->'normal_owner_person_id')))
    or loan->'normal_owner_person_id' is distinct from 'null'::jsonb then
    raise exception 'Native typed lunch party does not match its exact validated capacity tuple';end if;
  else
  perform public.static_weekly_capacity_assert_lunch_party(p_projection_id,loan,'normal_owner');
  end if;
  perform public.static_weekly_assert_exact_object(loan,
   case when loan ? 'normal_owner_capacity_id' then array['loan_id','service_date','day_of_week','normal_owner_slot_id','normal_owner_capacity_id','coverage_start','coverage_end','status','helper_slot_ids']
    else array['loan_id','service_date','day_of_week','normal_owner_slot_id','normal_owner_person_id','coverage_start','coverage_end','status','helper_slot_ids'] end,
   array['loan_id','service_date','day_of_week','normal_owner_slot_id','normal_owner_person_id','normal_owner_capacity_id','coverage_start','coverage_end','status','reason','helper_slot_ids','fallback','total_distance_minutes'],'lunch loan');
  if not (loan ?& array['reason','fallback','total_distance_minutes']) then raise exception 'lunch explanatory fields are missing'; end if;
  if coalesce(loan->>'loan_id','') !~ '^[0-9a-f]{64}$' then raise exception 'invalid lunch loan identity'; end if;
  select value into availability from jsonb_array_elements(projection_availability)
   where value->>'slotId'=loan->>'normal_owner_slot_id' and value->>'serviceDate'=loan->>'service_date';
  if not found or availability->>'incumbentPersonId' is distinct from loan->>'normal_owner_person_id'
   or loan->'day_of_week' is distinct from availability->'dayOfWeek'
   or loan->>'coverage_start' is distinct from availability#>>'{lunch,start}'
   or loan->>'coverage_end' is distinct from availability#>>'{lunch,end}' then raise exception 'lunch owner or scheduled hour mismatch'; end if;
  perform public.static_weekly_v3_assert_window(jsonb_build_object('start',loan->'coverage_start','end',loan->'coverage_end'),'lunch');
  start_time:=(loan->>'coverage_start')::time;end_time:=(loan->>'coverage_end')::time;
  if end_time-start_time<>interval '1 hour'
   or ((loan->>'status'='PLANNED' and jsonb_array_length(loan->'helper_slot_ids')=1)
    or (loan->>'status'='NO_AREAS' and jsonb_array_length(loan->'helper_slot_ids')=0)) is not true
   or loan->'fallback' is distinct from 'null'::jsonb then raise exception 'Manual native lunch requires the complete scheduled hour and exact helper count for its area status';end if;
  perform public.static_weekly_v3_assert_string_array(loan->'helper_slot_ids','lunch helpers');
  if ((loan->>'status'='NO_AREAS' and jsonb_array_length(loan->'helper_slot_ids')=0 and loan->'fallback'='null'::jsonb)
    or (loan->>'status'='PLANNED' and (
      (full_hour and jsonb_array_length(loan->'helper_slot_ids') between 1 and 2
        and (loan->'fallback'='null'::jsonb or (jsonb_array_length(loan->'helper_slot_ids')=1 and loan->>'fallback'='only_one_eligible_custodian')))
      or (not full_hour and ((jsonb_array_length(loan->'helper_slot_ids')=2 and loan->'fallback'='null'::jsonb)
        or (jsonb_array_length(loan->'helper_slot_ids')=1 and loan->>'fallback'='only_one_eligible_custodian')))))) is not true then
   raise exception 'lunch helper cardinality or fallback invalid'; end if;
  if full_hour then
   select value into strict planned_loan from jsonb_array_elements(full_hour_policy->'loans')
    where value->'dayOfWeek'=loan->'day_of_week' and value->'normalOwnerSlotId'=loan->'normal_owner_slot_id';
   if planned_loan->'window' is distinct from jsonb_build_object('start',loan->'coverage_start','end',loan->'coverage_end')
    then raise exception 'full lunch source window changed';end if;
   if loan->'helper_slot_ids' is distinct from (
     select coalesce(jsonb_agg(coverer order by coverer collate "C"),'[]'::jsonb)
     from (select distinct area->>'covererSlotId' coverer
       from jsonb_array_elements(planned_loan->'areas') area) named)
    then raise exception 'full lunch source coverer set changed';end if;
  end if;
  for helper_id in select jsonb_array_elements_text(loan->'helper_slot_ids') loop
   select value into helper from jsonb_array_elements(projection_availability)
    where value->>'slotId'=helper_id and value->>'serviceDate'=loan->>'service_date';
   if not found or helper->>'status' is distinct from 'working' or helper_id=loan->>'normal_owner_slot_id'
    or (nullif(helper->>'incumbentPersonId','') is null and helper->>'ownerKind' is distinct from 'CONTRACTOR_CAPACITY')
    or ((helper#>>'{lunch,start}' is null or helper#>>'{lunch,end}' is null)
      and (helper->>'ownerKind'='CONTRACTOR_CAPACITY' and helper->>'breakChoice'='NONE' and helper->'lunch'='null'::jsonb) is not true) or (helper#>>'{shift,start}')::time>start_time
    or (helper#>>'{shift,end}')::time<end_time
    or ((helper#>>'{lunch,start}')::time<end_time and start_time<(helper#>>'{lunch,end}')::time) then
    raise exception 'lunch helper is not available for the full scheduled hour'; end if;
   if not exists(select 1 from jsonb_array_elements(p_document->'responsibilities') r
     where r->>'loan_id'=loan->>'loan_id' and r->>'coverer_slot_id'=helper_id) then
    raise exception 'lunch helper has no assigned responsibility'; end if;
  end loop;
 end loop;
 for responsibility in select value from jsonb_array_elements(p_document->'responsibilities') loop
  if responsibility ? 'normal_owner_capacity_id' then
   if not(native_parties @> jsonb_build_array(jsonb_build_object(
     'service_date',responsibility->'service_date','day_of_week',responsibility->'day_of_week',
     'slot_id',responsibility->'normal_owner_slot_id','capacity_id',responsibility->'normal_owner_capacity_id',
     'person_id',responsibility->'normal_owner_person_id')))
    or responsibility->'normal_owner_person_id' is distinct from 'null'::jsonb then
    raise exception 'Native typed lunch party does not match its exact validated capacity tuple';end if;
  else
  perform public.static_weekly_capacity_assert_lunch_party(p_projection_id,responsibility,'normal_owner');
  end if;
  if responsibility ? 'coverer_capacity_id' then
   if not(native_parties @> jsonb_build_array(jsonb_build_object(
     'service_date',responsibility->'service_date','day_of_week',responsibility->'day_of_week',
     'slot_id',responsibility->'coverer_slot_id','capacity_id',responsibility->'coverer_capacity_id',
     'person_id',responsibility->'coverer_person_id')))
    or responsibility->'coverer_person_id' is distinct from 'null'::jsonb then
    raise exception 'Native typed lunch party does not match its exact validated capacity tuple';end if;
  else
  perform public.static_weekly_capacity_assert_lunch_party(p_projection_id,responsibility,'coverer');
  end if;
  perform public.static_weekly_assert_exact_object(responsibility,
   array['responsibility_id','loan_id','service_date','day_of_week','normal_owner_slot_id','coverer_slot_id','coverage_purpose','coverage_start','coverage_end','check_deadline_policy','creates_deep_clean','proximity_evidence','segments']
    ||case when responsibility ? 'normal_owner_capacity_id' then array['normal_owner_capacity_id'] else array['normal_owner_person_id'] end
    ||case when responsibility ? 'coverer_capacity_id' then array['coverer_capacity_id'] else array['coverer_person_id'] end,
   array['responsibility_id','loan_id','service_date','day_of_week','normal_owner_slot_id','normal_owner_person_id','normal_owner_capacity_id','coverer_slot_id','coverer_person_id','coverer_capacity_id','coverage_purpose','coverage_start','coverage_end','check_deadline_policy','creates_deep_clean','proximity_evidence','segments'],'lunch responsibility');
  select value into loan from jsonb_array_elements(p_document->'loans') where value->>'loan_id'=responsibility->>'loan_id';
  if not found or loan->>'status'<>'PLANNED' then raise exception 'lunch responsibility has no planned loan'; end if;
  foreach identity_key in array array['service_date','day_of_week','normal_owner_slot_id','normal_owner_person_id','coverage_start','coverage_end'] loop
   if responsibility->identity_key is distinct from loan->identity_key then raise exception 'lunch responsibility scope mismatch'; end if;
  end loop;
  select value into helper from jsonb_array_elements(projection_availability)
   where value->>'slotId'=responsibility->>'coverer_slot_id' and value->>'serviceDate'=responsibility->>'service_date';
  if not found or helper->>'incumbentPersonId' is distinct from responsibility->>'coverer_person_id'
   or not (loan->'helper_slot_ids' ? (responsibility->>'coverer_slot_id'))
   or coalesce(responsibility->>'responsibility_id','') !~ '^[0-9a-f]{64}$'
   or responsibility->>'coverage_purpose' is distinct from 'lunch_coverage'
   or responsibility->>'check_deadline_policy' is distinct from 'inherit_existing_90_minute_deadline'
   or responsibility->'creates_deep_clean' is distinct from 'false'::jsonb
   or jsonb_typeof(responsibility->'segments') is distinct from 'array'
   or jsonb_array_length(responsibility->'segments')=0 then raise exception 'lunch responsibility policy or recipient mismatch'; end if;
  for segment in select value from jsonb_array_elements(responsibility->'segments') loop
   perform public.static_weekly_assert_exact_object(segment,
    array['planWorkId','workId','serviceMode','window','includedLocations']||case when full_hour then array['normalWindow'] else array[]::text[] end,
    array['planWorkId','workId','serviceMode','window','includedLocations']||case when full_hour then array['normalWindow'] else array[]::text[] end,'lunch segment');
   select value into base_work from jsonb_array_elements(projection_assignments)
    where value->>'plan_work_id'=segment->>'planWorkId' and value->>'service_date'=responsibility->>'service_date';
   if not found or base_work->>'status' is distinct from 'assigned'
    or base_work->>'owner_slot_id' is distinct from responsibility->>'normal_owner_slot_id'
    or base_work->>'owner_person_id' is distinct from responsibility->>'normal_owner_person_id'
    or base_work->>'work_id' is distinct from segment->>'workId'
    or base_work#>'{work_snapshot,includedLocations}' is distinct from segment->'includedLocations'
    or base_work#>>'{work_snapshot,serviceMode}' is distinct from segment->>'serviceMode'
    or segment->>'serviceMode'='reminder_only' then raise exception 'borrowed area differs from original assignment'; end if;
   if not ((helper->'qualifications') @> (base_work#>'{work_snapshot,requiredQualifications}'))
    or ((base_work#>'{work_snapshot,restrictedSlotIds}') ? (responsibility->>'coverer_slot_id') and not (
      base_work#>>'{work_snapshot,locationCodeSnapshot}'='HERPETARIUM' and base_work->>'day_of_week'<>'1'
      and responsibility->>'coverer_slot_id'=(select v#>>'{slots,ALIJAH,slotId}' from (select c.owner_config v from public.static_weekly_approved_initial_baselines b join public.static_weekly_approved_template_catalog c using(template_id) join public.weekly_schedule_versions ver on ver.authority_source_id=b.source_id join public.weekly_schedule_publications pub using(version_id) where pub.publication_id=p_publication) cfg)))
    or exists(select 1 from jsonb_array_elements(segment->'includedLocations') location
      where helper->'restrictions' ? (location->>'locationId')) then
    raise exception 'lunch helper is restricted or unqualified for a borrowed area'; end if;
   perform public.static_weekly_v3_assert_window(segment->'window','borrowed area');
   normal_segment_window:=case when full_hour then segment->'normalWindow' else segment->'window' end;
   perform public.static_weekly_v3_assert_window(normal_segment_window,'original borrowed-area anchor');
   if (normal_segment_window->>'start')::time<>greatest((base_work#>>'{work_snapshot,window,start}')::time,(loan->>'coverage_start')::time)
    or (normal_segment_window->>'end')::time<>least((base_work#>>'{work_snapshot,window,end}')::time,(loan->>'coverage_end')::time) then
    raise exception 'borrowed-area window must be the exact normal-duty and lunch intersection'; end if;
   if full_hour then
    if segment->'window' is distinct from jsonb_build_object('start',loan->'coverage_start','end',loan->'coverage_end')
     then raise exception 'full lunch area must cover the entire accepted lunch';end if;
    select value into strict planned_loan from jsonb_array_elements(full_hour_policy->'loans')
     where value->'dayOfWeek'=loan->'day_of_week' and value->'normalOwnerSlotId'=loan->'normal_owner_slot_id';
    if not exists(select 1 from jsonb_array_elements(planned_loan->'areas') area
     where area->>'locationCode'=base_work#>>'{work_snapshot,locationCodeSnapshot}'
      and area->'covererSlotId'=responsibility->'coverer_slot_id') then
     raise exception 'full lunch recipient differs from the immutable area plan';end if;
   end if;
  end loop;
 end loop;
 if full_hour then
  for planned_loan in select value from jsonb_array_elements(full_hour_policy->'loans') loop
   for segment in select value from jsonb_array_elements(planned_loan->'areas') loop
    perform public.static_weekly_assert_exact_object(segment,array['locationCode','covererSlotId'],array['locationCode','covererSlotId'],'full lunch source area');
    if jsonb_typeof(segment->'locationCode') is distinct from 'string' or length(segment->>'locationCode') not between 1 and 512
     or jsonb_typeof(segment->'covererSlotId') is distinct from 'string' or length(segment->>'covererSlotId') not between 1 and 512
     or segment->'covererSlotId'=planned_loan->'normalOwnerSlotId' then raise exception 'invalid full lunch source area';end if;
   end loop;
  end loop;
  select coalesce(jsonb_agg(entry order by entry::text),'[]') into expected from
   (select jsonb_build_array(l->'dayOfWeek',l->'normalOwnerSlotId',a->'locationCode',a->'covererSlotId') entry
    from jsonb_array_elements(full_hour_policy->'loans') l cross join lateral jsonb_array_elements(l->'areas') a) q;
  select coalesce(jsonb_agg(entry order by entry::text),'[]') into actual from
   (select distinct jsonb_build_array(r->'day_of_week',r->'normal_owner_slot_id',a#>'{work_snapshot,locationCodeSnapshot}',r->'coverer_slot_id') entry
    from jsonb_array_elements(p_document->'responsibilities') r cross join lateral jsonb_array_elements(r->'segments') s
    join jsonb_array_elements(projection_assignments) a on a->>'plan_work_id'=s->>'planWorkId'
     and a->'service_date'=r->'service_date') q;
  if expected is distinct from actual then raise exception 'full lunch source areas omitted, duplicated or reassigned';end if;
  if exists(with areas as materialized (
    select r->>'service_date' service_date,loc->>'locationId' location_id,
     jsonb_build_array(r->'coverer_slot_id',r->'coverer_person_id',r->'coverer_capacity_id') recipient,
     (s#>>'{window,start}')::time starts,(s#>>'{window,end}')::time ends
    from jsonb_array_elements(p_document->'responsibilities') r cross join lateral jsonb_array_elements(r->'segments') s
     cross join lateral jsonb_array_elements(s->'includedLocations') loc)
   select 1 from areas a join areas b on a.service_date=b.service_date and a.location_id=b.location_id
    and a.recipient is distinct from b.recipient and a.starts<b.ends and b.starts<a.ends) then
   raise exception 'full lunch plans conflict on current physical responsibility';end if;
 end if;
 -- Account for every normal flexible duty that intersects each scheduled lunch.
 select coalesce(jsonb_agg(jsonb_build_array(l->>'loan_id',a->>'plan_work_id')
  order by l->>'loan_id',a->>'plan_work_id'),'[]') into expected
 from jsonb_array_elements(p_document->'loans') l
 join jsonb_array_elements(projection_assignments) a
  on a->>'service_date'=l->>'service_date' and a->>'owner_slot_id'=l->>'normal_owner_slot_id'
 join jsonb_array_elements(projection_work) w
  on w->>'workId'=a->>'work_id' and w->>'dayOfWeek'=a->>'day_of_week'
 where a->>'status'='assigned' and w->>'schedulingMode'='flexible_coverage_ownership'
  and w->>'serviceMode'<>'reminder_only'
  and (a#>>'{work_snapshot,window,start}')::time<(l->>'coverage_end')::time
  and (l->>'coverage_start')::time<(a#>>'{work_snapshot,window,end}')::time;
 select coalesce(jsonb_agg(jsonb_build_array(r->>'loan_id',s->>'planWorkId')
  order by r->>'loan_id',s->>'planWorkId'),'[]') into actual
 from jsonb_array_elements(p_document->'responsibilities') r cross join lateral jsonb_array_elements(r->'segments') s;
 if actual is distinct from expected then raise exception 'lunch responsibility must cover every eligible original area exactly once'; end if;
 if exists(select 1 from jsonb_array_elements(p_document->'responsibilities') r,
  jsonb_array_elements(r->'segments') s group by r->>'loan_id',s->>'planWorkId' having count(*)>1) then
  raise exception 'borrowed work assigned more than once'; end if;
 if exists(select 1 from jsonb_array_elements(p_document->'responsibilities') r,
  jsonb_array_elements(r->'segments') s,jsonb_array_elements(s->'includedLocations') location
  group by r->>'loan_id',location->>'locationId' having count(distinct r->>'coverer_slot_id')>1) then
  raise exception 'paired or grouped locations split between lunch helpers'; end if;
 for intent in select value from jsonb_array_elements(p_document->'notification_intents') loop
  perform public.static_weekly_assert_exact_object(intent,
   array['notification_key','loan_id','service_date','event','scheduled_time','coverer_slot_id','delivery_state'],
   array['notification_key','loan_id','service_date','event','scheduled_time','coverer_slot_id','delivery_state'],'lunch notification intent');
  if coalesce(intent->>'notification_key','') !~ '^[0-9a-f]{64}$'
   or intent->>'delivery_state' is distinct from 'NOT_ENQUEUED' then raise exception 'invalid lunch notification intent'; end if;
 end loop;
 select coalesce(jsonb_agg(jsonb_build_array(l->>'loan_id',l->>'service_date',h,e,
  case e when 'start' then l->>'coverage_start' else l->>'coverage_end' end) order by l->>'loan_id',h,e),'[]') into expected
 from jsonb_array_elements(p_document->'loans') l cross join lateral jsonb_array_elements_text(l->'helper_slot_ids') h
 cross join unnest(array['start','end']) e
 where exists(select 1 from jsonb_array_elements(projection_availability) a
  where a->>'slotId'=h and a->>'serviceDate'=l->>'service_date' and nullif(a->>'incumbentPersonId','') is not null);
 select coalesce(jsonb_agg(jsonb_build_array(n->>'loan_id',n->>'service_date',n->>'coverer_slot_id',n->>'event',n->>'scheduled_time')
  order by n->>'loan_id',n->>'coverer_slot_id',n->>'event'),'[]') into actual
 from jsonb_array_elements(p_document->'notification_intents') n;
 if actual is distinct from expected then raise exception 'lunch start/end intents must exactly cover every helper'; end if;
 if exists(select 1 from jsonb_array_elements(p_document->'loans') a join jsonb_array_elements(p_document->'loans') b
  on a->>'loan_id'<b->>'loan_id' and a->'service_date'=b->'service_date' and a->'helper_slot_ids'=b->'helper_slot_ids'
  and a->>'coverage_start'<b->>'coverage_end' and b->>'coverage_start'<a->>'coverage_end') then raise exception 'Manual native helper appointments overlap';end if;
 perform public.static_weekly_manual_assert_lunch_lineage(p_envelope,p_document,p_publication,p_week);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_manual_assert_native_projection(p_operation uuid, p_manager uuid, p_envelope jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare ctx jsonb;basis jsonb;snapshot jsonb:=p_envelope->'semantic_snapshot';a jsonb:=p_envelope->'authority';source jsonb;
 frame date;publication uuid;version uuid;expected_dates jsonb;day date;dow integer;normal_day jsonb;day_basis jsonb;plan jsonb;
 item jsonb;w jsonb;parent jsonb;link jsonb;availability jsonb;expected jsonb;actual jsonb;slot jsonb;person jsonb;
 base jsonb;exceptions jsonb;summary jsonb;links jsonb:='{}';expected_availability jsonb:='[]';absent jsonb;
 complete_start text;complete_end text;normal_start text;normal_end text;previous_owner text;previous_end text;
 row_owner text;owner_config jsonb;code text;normal_changed boolean;day_changed boolean;inherited boolean;
 input jsonb;phase jsonb;previous_phase jsonb;slice jsonb;loan jsonb;owners jsonb;points jsonb;anchors jsonb;policy jsonb;
 p_loss numeric;l_loss numeric;n integer;minutes numeric;total_minutes numeric;weighted_p numeric;weighted_l numeric;actual_effort numeric;
 count_rows integer;budget integer;assignment uuid;key text;window_start text;window_end text;employment_employee jsonb;pre_start jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 ctx:=public.static_weekly_pending_context(p_operation,p_manager);
 perform public.static_weekly_assert_exact_object(p_envelope,
  array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','semantic_snapshot','database_projection_identity'],
  array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','semantic_snapshot','database_projection_identity'],'manual native projection');
 perform public.static_weekly_assert_exact_object(snapshot,
  array['schema','originalCommand','originalSource','scopeDates','weekStart','generation','catalogEntryDigest','nativeBasisDigest'],
  array['schema','originalCommand','originalSource','scopeDates','weekStart','generation','catalogEntryDigest','nativeBasisDigest'],'manual native original snapshot');
 if snapshot->>'schema' is distinct from 'custodial.approved-manual-pending-staffing-snapshot.v1'
  or snapshot->'originalCommand' is distinct from ctx->'originalCommand'
  or coalesce(snapshot->>'weekStart','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
  or coalesce(snapshot->>'nativeBasisDigest','')!~'^[0-9a-f]{64}$'
 then raise exception 'Manual native original command differs';end if;
 frame:=(snapshot->>'weekStart')::date;publication:=(snapshot#>>'{originalSource,publication_id}')::uuid;
 basis:=public.static_weekly_manual_period_basis(p_manager,publication,frame,
  (select current_revision from public.static_weekly_schedule_control where singleton),p_operation);
 source:=basis->'normalSource';version:=(basis->>'versionId')::uuid;exceptions:=basis->'preparedExceptions';summary:=basis->'preparedSummary';
 if frame::text is distinct from basis->>'frameStart' or snapshot->'originalSource' is distinct from basis->'originalSource'
  or snapshot->'generation' is distinct from basis->'generation' or snapshot->'catalogEntryDigest' is distinct from basis->'catalogEntryDigest'
  or (not (ctx->>'afterFact')::boolean and snapshot->'nativeBasisDigest' is distinct from basis->'basisDigest')
 then raise exception 'Manual native current Source or preparation basis changed';end if;
 if (ctx->>'afterFact')::boolean and not exists(select 1 from public.static_weekly_staffing_staged_candidates s
  where s.operation_id=p_operation and s.candidate_kind='projection' and s.service_date=frame and s.payload_json->'envelope'=p_envelope)
 then raise exception 'Manual native acceptance must use the exact immutable staged preview';end if;
 select jsonb_agg(d::date::text order by d) into expected_dates from generate_series(
  greatest(frame,(ctx#>>'{originalCommand,semanticBody,startDate}')::date),
  least(frame+6,(ctx#>>'{originalCommand,semanticBody,endDate}')::date),'1 day') d;
 if snapshot->'scopeDates' is distinct from expected_dates or a->'compilerInput' is distinct from source
  or a->>'schema' is distinct from 'custodial.approved-manual-period-projection-authority.v1'
  or a->>'sourceDigest' is distinct from basis->>'normalSourceDigest'
  or a->>'sourcePublicationId' is distinct from publication::text or a->>'sourceVersionId' is distinct from version::text
  or a->>'frameStart' is distinct from frame::text or a->>'frameEnd' is distinct from (frame+6)::text
  or a->'normalSourceChanged' is distinct from 'false'::jsonb or a->'objectiveSolverRerun' is distinct from 'false'::jsonb
  or a->>'acceptedExceptionsDigest' is distinct from public.static_weekly_digest_jsonb(exceptions)
  or a->'employmentRevisionVector' is distinct from basis->'employmentRevisionVector'
  or a->>'formulaObjectiveDigest' is distinct from '7796e95573b389d8d77fc80502d4f6f7f1b54a5155327f9a7f1eb42a7137f531'
  or p_envelope->'applied_exceptions' is distinct from summary
  or p_envelope->'adapter' is distinct from '{"schema":"custodial.approved-manual-period-database-adapter.v1","version":"approved-manual-period-v1"}'::jsonb
  or p_envelope->>'compiler_version' is distinct from 'approved-manual-period-v1'
  or p_envelope->>'service_date' is distinct from frame::text or p_envelope->>'week_start' is distinct from frame::text
  or p_envelope->>'week_end' is distinct from (frame+6)::text
  or p_envelope->>'authority_digest' is distinct from public.static_weekly_digest_jsonb(a)
  or p_envelope->>'database_projection_identity' is distinct from public.static_weekly_digest_jsonb(p_envelope-'database_projection_identity')
  or p_envelope->'objective' is distinct from jsonb_build_object('contract','OWNER_APPROVED_MANUAL_DATED_75_25_V2',
   'formulaObjectiveDigest',a->'formulaObjectiveDigest','proximityPercent',75,'workloadPercent',25,'normalDaysOptimized',false)
  or p_envelope->'metrics' is distinct from jsonb_build_object('hardConstraints',a->'hardConstraintCount','violations',0)
  or p_envelope#>>'{receipt,schema}' is distinct from 'custodial.approved-manual-native-feasibility-data.v1'
  or p_envelope#>'{receipt,hardConstraintCount}' is distinct from a->'hardConstraintCount'
  or p_envelope#>'{receipt,hardConstraintDigest}' is distinct from a->'hardConstraintDigest'
  or p_envelope#>'{receipt,fixedWitnessDigest}' is distinct from a->'fixedWitnessDigest'
 then raise exception 'Manual native envelope identity or approved formula differs';end if;
 if jsonb_typeof(p_envelope->'assignments') is distinct from 'array' or jsonb_array_length(p_envelope->'assignments') not between 1 and 4096
  or jsonb_typeof(a->'datedDayBases') is distinct from 'array' or jsonb_array_length(a->'datedDayBases')>7
  or jsonb_typeof(a->'parentLinks') is distinct from 'array' or jsonb_array_length(a->'parentLinks')>4096
  or jsonb_typeof(a->'projectionAvailability') is distinct from 'array' or jsonb_array_length(a->'projectionAvailability')>224
  or (select count(*)<>count(distinct r->>'plan_work_id') from jsonb_array_elements(p_envelope->'assignments') r)
  or (select count(*)<>count(distinct r->>'serviceDate') from jsonb_array_elements(a->'datedDayBases') r)
  or (select count(*)<>count(distinct r->>'workId') from jsonb_array_elements(a->'parentLinks') r)
 then raise exception 'Manual native bounded unique records required';end if;
 -- This first admission supports full-day canonical PTO/absence and its exact
 -- cancellation. Other exception shapes fail closed, never silently disappear.
 if exists(select 1 from jsonb_array_elements(exceptions) e where e->>'type' not in('pto','daily_absence') or e ? 'window')
 then raise exception using errcode='0A000',message='Manual native exception requires its qualified dated profile';end if;
 policy:=public.static_weekly_manual_absence_policy();
 for base in select value from jsonb_array_elements(source#>'{version,slotAvailability}') loop
  dow:=(base->>'dayOfWeek')::integer;day:=frame+mod(dow-extract(dow from frame)::integer+7,7);
  availability:=public.static_weekly_approved_dated_effective_availability(base,base->>'slotId',day,exceptions);
  if availability->>'status'='working' and (
   exists(select 1 from jsonb_array_elements(exceptions) e
    join jsonb_array_elements(source#>'{version,slotAvailability}') av on av->'slotId'=e#>'{payload,slotId}' and av->>'dayOfWeek'=dow::text and av->>'status'='working'
    where e->>'serviceDate'=day::text and e->>'type' in('pto','daily_absence'))
   or exists(select 1 from jsonb_array_elements(basis->'employmentByDate') ed
    cross join lateral jsonb_array_elements(ed->'employees') ee
    join jsonb_array_elements(source->'slots') es on exists(select 1 from jsonb_array_elements(es->'incumbencies') ei
     where ei->'personId'=ee->'employeeId' and (ei->>'effectiveStart')::date<=day and (ei->>'effectiveEnd' is null or day<(ei->>'effectiveEnd')::date))
    join jsonb_array_elements(source#>'{version,slotAvailability}') ea on ea->'slotId'=es->'id' and ea->>'dayOfWeek'=dow::text and ea->>'status'='working'
    where ed->>'serviceDate'=day::text and (ee#>>'{command,fact,state}'='PRE_START' or day<(ee#>>'{command,fact,firstServiceDate}')::date))) then
   availability:=availability||'{"blockedWindows":[]}'::jsonb;
  end if;
  select s into strict slot from jsonb_array_elements(source->'slots') s where s->'id'=base->'slotId';
  select i into strict person from jsonb_array_elements(slot->'incumbencies') i
   where (i->>'effectiveStart')::date<=day and (i->>'effectiveEnd' is null or day<(i->>'effectiveEnd')::date);
  select e into employment_employee from jsonb_array_elements(basis->'employmentByDate') d
   cross join lateral jsonb_array_elements(d->'employees') e
   where d->>'serviceDate'=day::text and e->'employeeId'=person->'personId';
  if base->>'status'='working' and employment_employee is not null and
   (employment_employee#>>'{command,fact,state}'='PRE_START' or day<(employment_employee#>>'{command,fact,firstServiceDate}')::date) then
   availability:=availability||'{"status":"absent","blockedWindows":[{"start":"00:00","end":"23:59"}],"unavailabilityClassification":"PRE_START_NOT_PTO"}'::jsonb;
  end if;
  expected_availability:=expected_availability||jsonb_build_array(availability||jsonb_build_object(
   'serviceDate',day::text,'incumbentPersonId',person->'personId','incumbentName',person->'displayName'));
 end loop;
 select coalesce(jsonb_agg(r order by (r->>'dayOfWeek')::integer,r->>'slotId' collate "C"),'[]') into expected from jsonb_array_elements(expected_availability) r;
 select coalesce(jsonb_agg(r order by (r->>'dayOfWeek')::integer,r->>'slotId' collate "C"),'[]') into actual from jsonb_array_elements(a->'projectionAvailability') r;
 if actual is distinct from expected then raise exception 'Manual native static hours, eligibility or actual absence changed';end if;

 for day in select generate_series(frame,frame+6,'1 day')::date loop
  dow:=extract(dow from day)::integer;
  select r into strict normal_day from jsonb_array_elements(policy->'days') r where r->>'weekday'=dow::text;
  select coalesce(jsonb_agg(r->'incumbentPersonId' order by r->>'incumbentPersonId'),'[]') into absent
   from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'status'='absent';
  select coalesce(jsonb_agg(r->'incumbentPersonId' order by r->>'incumbentPersonId'),'[]') into pre_start
   from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'unavailabilityClassification'='PRE_START_NOT_PTO';
  day_changed:=jsonb_array_length(absent)>0;
  select r into day_basis from jsonb_array_elements(a->'datedDayBases') r where r->>'serviceDate'=day::text;
  if day_changed is distinct from (day_basis is not null) then raise exception 'Manual native complete dated day set differs';end if;
  normal_start:=normal_day#>>'{checkedWindow,start}';normal_end:=normal_day#>>'{checkedWindow,end}';
  select max(r#>>'{shift,start}'),max(r#>>'{shift,end}') into complete_start,complete_end
   from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'status'='working';
  if complete_start is null or complete_start>=complete_end then raise exception 'Manual native staffed window is empty';end if;
  if day_changed then
   if jsonb_array_length(absent) not between 1 and 2 or day_basis->>'kind' is distinct from 'ABSENCE' then
    raise exception using errcode='0A000',message='Third absence requires the retained two-absence basis and actual CoverAll hours';end if;
   input:=day_basis->'input';plan:=day_basis->'plan';
   if input->>'inputDigest' is distinct from public.static_weekly_digest_jsonb(input-'inputDigest')
    or plan->>'planDigest' is distinct from public.static_weekly_digest_jsonb(plan-'planDigest')
    or input->'sourceDigest' is distinct from a->'sourceDigest' or input->'formulaObjectiveDigest' is distinct from a->'formulaObjectiveDigest'
    or input->>'serviceDate' is distinct from day::text or plan->>'serviceDate' is distinct from day::text
    or input->'absentPersonIds' is distinct from absent or plan->'absentPersonIds' is distinct from absent
    or coalesce(input->'preStartPersonIds','[]') is distinct from pre_start
    or (jsonb_array_length(pre_start)>0 and input->>'preStartClassification' is distinct from 'PRE_START_NOT_PTO')
    or input->'checkedWindow' is distinct from jsonb_build_object('start',complete_start,'end',complete_end)
    or plan->'checkedWindow' is distinct from input->'checkedWindow' or plan->'inputDigest' is distinct from input->'inputDigest'
    or plan->'proposalDigest' is distinct from a->'formulaObjectiveDigest' or input->'access' is distinct from policy->'access'
    or input->'groups' is distinct from policy->'groups' or plan->'groups' is distinct from policy->'groups'
    or plan->'hardFeasibilityValidatedBeforeScoring' is distinct from 'true'::jsonb or plan->'globalOptimalityClaim' is distinct from 'false'::jsonb
    or exists(select 1 from unnest(array['publicationEligible','weeklyBaselineChanged','productionWritten','contractorBooked']) k where plan->k is distinct from 'false'::jsonb)
   then raise exception 'Manual native dated immutable input, source or formula changed';end if;
   select coalesce(jsonb_agg(jsonb_build_array(r->'slotId',r->'incumbentPersonId',r->'shift',r->'lunch') order by r->>'slotId'),'[]') into expected
    from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'status'='working';
   select coalesce(jsonb_agg(jsonb_build_array(r->'slotId',r->'personId',r->'shift',r->'lunch') order by r->>'slotId'),'[]') into actual from jsonb_array_elements(input->'roster') r;
   if expected is distinct from actual then raise exception 'Manual native dated roster changed';end if;
   for item in select value from jsonb_array_elements(input->'roster') loop
    select r->'baseGroups' into strict expected from jsonb_array_elements(normal_day->'employees') r where r->>'name'=item->>'name';
    select coalesce(jsonb_agg(to_jsonb(r->>'code') order by ord),'[]') into actual
     from jsonb_array_elements(expected) with ordinality x(name,ord) join jsonb_array_elements(policy->'groups') r on r->'name'=name;
    if item->'baseCodes' is distinct from actual then raise exception 'Manual native distance anchor changed from approved normal day';end if;
   end loop;
  end if;

  for item in select value from jsonb_array_elements(p_envelope->'assignments') where value->>'service_date'=day::text loop
   w:=item->'work_snapshot';parent:=null;link:=null;
   select r into parent from jsonb_array_elements(source#>'{version,assignments}') r
    where r->>'dayOfWeek'=dow::text and r->'workId'=item->'work_id';
   if parent is null then
    select r into strict link from jsonb_array_elements(a->'parentLinks') r where r->'workId'=item->'work_id';
    select r into strict parent from jsonb_array_elements(source#>'{version,assignments}') r where r->>'dayOfWeek'=dow::text and r->'workId'=link->'parentWorkId';
    if link->'serviceDate' is distinct from item->'service_date' or link->'window' is distinct from w->'window' or link->'slotId' is distinct from item->'owner_slot_id'
     or coalesce(item->>'work_id','')!~'^manual-dated:[0-9a-f]{64}$' then raise exception 'Manual native parent lineage differs';end if;
   end if;
   select r into strict availability from jsonb_array_elements(expected_availability) r where r->'slotId'=item->'owner_slot_id' and r->>'serviceDate'=day::text;
   select value into strict owner_config from jsonb_each(basis#>'{ownerConfig,slots}') where value->'slotId'=item->'owner_slot_id';
   window_start:=w#>>'{window,start}';window_end:=w#>>'{window,end}';
   perform public.static_weekly_v3_assert_window(w->'window','manual native custody');
   if item->>'status' is distinct from 'assigned' or item->'reason_code' is distinct from 'null'::jsonb
    or item->>'day_of_week' is distinct from dow::text or item->>'plan_work_id' is distinct from dow::text||':'||(item->>'work_id')
    or item->'owner_person_id' is distinct from availability->'incumbentPersonId' or item->'optimized_owner_person_id' is distinct from item->'owner_person_id'
    or item->'optimized_owner_slot_id' is distinct from item->'owner_slot_id' or item ? 'owner_kind' or item ? 'capacity_id'
    or availability->>'status' is distinct from 'working' or window_start<availability#>>'{shift,start}' or window_end>availability#>>'{shift,end}'
    or item->'baseline_owner_slot_id' is distinct from parent->'originSlotId' or w->'originSlotId' is distinct from parent->'originSlotId'
   then raise exception 'Manual native actual static owner, window or original actor changed';end if;
   select r into strict base from jsonb_array_elements(expected_availability) r where r->'slotId'=parent->'originSlotId' and r->>'serviceDate'=day::text;
   if item->'baseline_owner_person_id' is distinct from base->'incumbentPersonId' or item->'original_actor_person_id' is distinct from base->'incumbentPersonId'
    or item->'baseline_owner_name' is distinct from base->'incumbentName' or item->'original_actor_name' is distinct from base->'incumbentName'
    or item->>'owner_digest' is distinct from public.static_weekly_digest_jsonb(jsonb_build_object('planWorkId',item->'plan_work_id','slotId',item->'owner_slot_id','personId',item->'owner_person_id','serviceDate',item->'service_date'))
    or item->>'exact_owner_identity' is distinct from public.static_weekly_digest_jsonb(jsonb_build_object('plan_work_id',item->'plan_work_id','service_date',item->'service_date','optimized_owner_slot_id',item->'owner_slot_id','optimized_owner_person_id',item->'owner_person_id','baseline_owner_slot_id',parent->'originSlotId','baseline_owner_person_id',base->'incumbentPersonId'))
   then raise exception 'Manual native owner lineage digest changed';end if;
   inherited:=day_changed and exists(select 1 from jsonb_array_elements(plan->'phaseOwners') with ordinality x(ph,phase_number)
    where phase_number>1 and ph#>>'{window,start}'<=window_start and window_start<ph#>>'{window,end}');
   expected:=jsonb_build_object('workId',item->'work_id','dayOfWeek',dow,'originSlotId',parent->'originSlotId',
    'locationId',parent->'locationId','locationCodeSnapshot',parent->'locationCodeSnapshot','locationNameSnapshot',parent->'locationNameSnapshot',
    'serviceMode',parent->'serviceMode','includedLocations',parent->'includedLocations','window',w->'window',
    'serviceEffortMinutes',w->'serviceEffortMinutes','serviceEffortProvenance',w->'serviceEffortProvenance',
    'priority',parent->'priority','priorityProvenance',parent->'priorityProvenance','required',parent->'required',
    'coveragePolicy',null,'bestEffortCoverage',false,'coveragePolicyOrder',null,'coveragePolicyProvenance',null,
    'requiredQualifications',parent->'requiredQualifications','qualificationProvenance',parent->'qualificationProvenance',
    'restrictions',parent->'restrictions','restrictionProvenance',parent->'restrictionProvenance','restrictedSlotIds',parent->'restrictedSlotIds',
    'manualLock',false,'manualLockSlotId',null,'overlayWork',false);
   if jsonb_array_length(coalesce(parent->'normalAssignmentRestrictedSlotIds','[]'))>0 then
    expected:=expected||jsonb_build_object('normalAssignmentRestrictedSlotIds',parent->'normalAssignmentRestrictedSlotIds','coveragePurpose',parent->'coveragePurpose');
   end if;
   if inherited and dow<>1 and parent->>'locationCodeSnapshot'='HERPETARIUM'
    and parent->'restrictedSlotIds' ? (basis#>>'{ownerConfig,slots,ALIJAH,slotId}') then
    expected:=expected||jsonb_build_object('restrictedSlotIds',(parent->'restrictedSlotIds')-(basis#>>'{ownerConfig,slots,ALIJAH,slotId}'),
     'normalAssignmentRestrictedSlotIds',jsonb_build_array(basis#>>'{ownerConfig,slots,ALIJAH,slotId}'),
     'coveragePurpose','INHERITED_ALERTS_AND_ISSUES_ONLY','restrictionProvenance',(parent->>'restrictionProvenance')||';normal-assignment-scope:fe02bbdebc736d95360b55cc7dfe5b73c5a9eaa76f364f1c0f4420a0afb9950f');
   end if;
   if w is distinct from expected or not ((availability->'qualifications') @> (w->'requiredQualifications'))
    or w->'restrictedSlotIds' ? (item->>'owner_slot_id') or owner_config->'hardForbiddenFamilies' ? (w->>'locationCodeSnapshot')
    or exists(select 1 from jsonb_array_elements(w->'includedLocations') r where availability->'restrictions' ? (r->>'locationId'))
    or (item->>'owner_slot_id'=basis#>>'{ownerConfig,slots,TAMMY,slotId}' and w->>'locationCodeSnapshot' not in('TETON','NORTH_WEST_PASSAGE','EAST_END_RESTROOMS','CHINA'))
   then raise exception 'Manual native physical members, hard eligibility or scoped restriction changed: work %, fields %',item->>'work_id',
    (select coalesce(jsonb_agg(k order by k),'[]') from (select jsonb_object_keys(w||expected) k) q where w->k is distinct from expected->k);end if;
   if not day_changed and (link is not null or item->'owner_slot_id' is distinct from parent->'ownerSlotId' or w->'window' is distinct from parent->'window'
    or w->'serviceEffortMinutes' is distinct from parent->'serviceEffortMinutes' or w->'serviceEffortProvenance' is distinct from parent->'serviceEffortProvenance')
   then raise exception 'Manual native changed an approved normal day';end if;
   if day_changed and (window_end>parent#>>'{window,end}' or window_start<case
    when parent#>>'{window,start}'<=normal_start and parent#>>'{window,end}'>normal_start
     then least(parent#>>'{window,start}',complete_start) else parent#>>'{window,start}' end)
   then raise exception 'Manual native custody exceeds its exact parent boundary';end if;
   -- A single unchanged owner can continue across the complete-crew arrival.
   -- That harmless merged row must still preserve the whole early base prefix.
   if day_changed and window_start<complete_start and (item->'owner_slot_id' is distinct from parent->'ownerSlotId'
    or window_start<>parent#>>'{window,start}' or window_end<least(parent#>>'{window,end}',complete_start))
   then raise exception 'Manual native early own-base custody differs';end if;
   if day_changed and window_end>complete_start then
    if window_end>complete_end then raise exception 'Manual native actual full-site window differs';end if;
    for phase in select value from jsonb_array_elements(plan->'phaseOwners') where value#>>'{window,start}'<window_end and window_start<value#>>'{window,end}' loop
     if phase#>>array['owners',w->>'locationCodeSnapshot'] is distinct from item->>'owner_slot_id' then raise exception 'Manual native selected phase differs from stored custody';end if;
    end loop;
   end if;
   select assignment_id into strict assignment from public.weekly_schedule_slot_assignments
    where version_id=version and day_of_week=dow and work_id=parent->>'workId';
   links:=links||jsonb_build_object(item->>'plan_work_id',assignment::text);
  end loop;

  -- Every physical group tiles the complete actual staffed window once.
  for code in select r->>'code' from jsonb_array_elements(policy->'groups') r loop
   previous_end:=complete_start;previous_owner:=null;
   for item in select r from jsonb_array_elements(p_envelope->'assignments') r where r->>'service_date'=day::text
    and r#>>'{work_snapshot,locationCodeSnapshot}'=code and r#>>'{work_snapshot,window,end}'>complete_start
    order by r#>>'{work_snapshot,window,start}' loop
    window_start:=greatest(complete_start,item#>>'{work_snapshot,window,start}');window_end:=least(complete_end,item#>>'{work_snapshot,window,end}');
    if window_end<=window_start then continue;end if;
    if window_start<>previous_end then raise exception 'Manual native full-site gap or overlap';end if;
    if day_changed and previous_owner is not null and previous_owner<>item->>'owner_slot_id' and not exists(
     select 1 from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'slotId'=previous_owner and r#>>'{shift,end}'=window_start)
    then raise exception 'Manual native owner moved before the static departure';end if;
    previous_end:=window_end;previous_owner:=item->>'owner_slot_id';
   end loop;
   if previous_end<>complete_end then raise exception 'Manual native full-site coverage incomplete';end if;
   select sum((r->>'serviceEffortMinutes')::integer) into budget from jsonb_array_elements(source#>'{version,assignments}') r where r->>'dayOfWeek'=dow::text and r->>'locationCodeSnapshot'=code;
   select sum((r#>>'{work_snapshot,serviceEffortMinutes}')::integer) into actual_effort from jsonb_array_elements(p_envelope->'assignments') r where r->>'service_date'=day::text and r#>>'{work_snapshot,locationCodeSnapshot}'=code;
   if actual_effort is distinct from budget then raise exception 'Manual native combined group workload budget changed';end if;
  end loop;
  if not day_changed and (select count(*) from jsonb_array_elements(p_envelope->'assignments') r where r->>'service_date'=day::text)
   <>(select count(*) from jsonb_array_elements(source#>'{version,assignments}') r where r->>'dayOfWeek'=dow::text)
  then raise exception 'Manual native omitted approved normal rows';end if;
  if day_changed then
   perform public.static_weekly_manual_assert_absence_score(day_basis,normal_day,policy,expected_availability,p_envelope->'assignments',basis->'ownerConfig');
  end if;
 end loop;
 if (select count(*) from jsonb_object_keys(links))<>jsonb_array_length(p_envelope->'assignments')
  or exists(select 1 from jsonb_array_elements(a->'parentLinks') l where not exists(select 1 from jsonb_array_elements(p_envelope->'assignments') r where r->'work_id'=l->'workId' and r->'service_date'=l->'serviceDate'))
 then raise exception 'Manual native foreign row or unused parent link';end if;
 if (ctx->>'afterFact')::boolean and summary is distinct from public.static_weekly_accepted_exception_set(publication,frame)
 then raise exception 'Manual native original fact did not become exact accepted authority';end if;
 return jsonb_build_object('assignment_links',links,'projection_assignments',p_envelope->'assignments','afterFact',ctx->'afterFact');
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_manual_assert_recurring_projection(p_operation uuid, p_manager uuid, p_envelope jsonb, p_lunch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare ctx jsonb;basis jsonb;snapshot jsonb:=p_envelope->'semantic_snapshot';a jsonb:=p_envelope->'authority';source jsonb;
 frame date;publication uuid;version uuid;expected_dates jsonb;day date;dow integer;normal_day jsonb;day_basis jsonb;plan jsonb;
 item jsonb;w jsonb;parent jsonb;link jsonb;availability jsonb;expected jsonb;actual jsonb;slot jsonb;person jsonb;
 base jsonb;exceptions jsonb;summary jsonb;links jsonb:='{}';expected_availability jsonb:='[]';absent jsonb;
 complete_start text;complete_end text;normal_start text;normal_end text;previous_owner text;previous_end text;
 row_owner text;owner_config jsonb;code text;normal_changed boolean;day_changed boolean;inherited boolean;
 input jsonb;phase jsonb;previous_phase jsonb;slice jsonb;loan jsonb;owners jsonb;points jsonb;anchors jsonb;policy jsonb;
 p_loss numeric;l_loss numeric;n integer;minutes numeric;total_minutes numeric;weighted_p numeric;weighted_l numeric;actual_effort numeric;
 count_rows integer;budget integer;assignment uuid;key text;window_start text;window_end text;
 coverall jsonb;choice_day jsonb;capacity_id text;replaced_id text;is_coverall boolean;employment_employee jsonb;pre_start jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 ctx:=public.static_weekly_manual_recurring_context(p_operation,p_manager);
 if ctx->>'schema' is distinct from 'custodial.recurring-employment-native-sql-context.v1'
  or ctx->>'kind' is distinct from 'RECURRING_MANUAL_MATERIALIZATION'
  or ctx->>'operationId' is distinct from p_operation::text or ctx->>'managerId' is distinct from p_manager::text
  or ctx->'stagedEnvelope' is distinct from p_envelope or ctx->'stagedLunch' is distinct from p_lunch
  or ctx->>'candidateDigest' is distinct from public.static_weekly_digest_jsonb(jsonb_build_object('envelope',p_envelope,'lunch',p_lunch))
 then raise exception 'Exact original staged initial employment scope required';end if;
 perform public.static_weekly_assert_exact_object(p_envelope,
  array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','semantic_snapshot','database_projection_identity'],
  array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','semantic_snapshot','database_projection_identity'],'manual native projection');
 perform public.static_weekly_assert_exact_object(snapshot,
  array['schema','recurringOperation','originalSource','scopeDates','weekStart','generation','catalogEntryDigest','nativeBasisDigest'],
  array['schema','recurringOperation','originalSource','scopeDates','weekStart','generation','catalogEntryDigest','nativeBasisDigest'],'manual native original snapshot');
 if snapshot->>'schema' is distinct from 'custodial.approved-manual-recurring-adjustment-snapshot.v1'
  or snapshot->'recurringOperation' is distinct from jsonb_build_object('kind','RECURRING_MANUAL_MATERIALIZATION',
   'operationId',p_operation,'managerId',p_manager,'sourceId',ctx->'sourceId','publicationId',ctx->'publicationId','versionId',ctx->'versionId',
   'frameStart',ctx->'frameStart','frameEnd',ctx->'frameEnd','authorityRevision',ctx->'authorityRevision')
  or coalesce(snapshot->>'weekStart','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
  or coalesce(snapshot->>'nativeBasisDigest','')!~'^[0-9a-f]{64}$'
 then raise exception 'Manual native original command differs';end if;
 frame:=(snapshot->>'weekStart')::date;publication:=(snapshot#>>'{originalSource,publication_id}')::uuid;
 basis:=ctx->'basis';
 source:=basis->'normalSource';version:=(basis->>'versionId')::uuid;exceptions:=basis->'preparedExceptions';summary:=basis->'preparedSummary';
 if frame::text is distinct from basis->>'frameStart' or snapshot->'originalSource' is distinct from basis->'originalSource'
  or snapshot->'generation' is distinct from basis->'generation' or snapshot->'catalogEntryDigest' is distinct from basis->'catalogEntryDigest'
  or snapshot->'nativeBasisDigest' is distinct from basis->'basisDigest'
 then raise exception 'Manual native current Source or preparation basis changed';end if;
 if frame::text is distinct from ctx->>'frameStart' or publication::text is distinct from ctx->>'publicationId'
  or (frame+6)::text is distinct from ctx->>'frameEnd' then raise exception 'Initial native actual publication/frame changed';end if;
 select jsonb_agg(d::date::text order by d) into expected_dates from generate_series(frame,frame+6,'1 day') d;
 if snapshot->'scopeDates' is distinct from expected_dates or a->'compilerInput' is distinct from source
  or a->>'schema' is distinct from 'custodial.approved-manual-period-projection-authority.v1'
  or a->>'sourceDigest' is distinct from basis->>'normalSourceDigest'
  or a->>'sourcePublicationId' is distinct from publication::text or a->>'sourceVersionId' is distinct from version::text
  or a->>'frameStart' is distinct from frame::text or a->>'frameEnd' is distinct from (frame+6)::text
  or a->'normalSourceChanged' is distinct from 'false'::jsonb or a->'objectiveSolverRerun' is distinct from 'false'::jsonb
  or a->>'acceptedExceptionsDigest' is distinct from public.static_weekly_digest_jsonb(exceptions)
  or a->'employmentRevisionVector' is distinct from basis->'employmentRevisionVector'
  or a->>'formulaObjectiveDigest' is distinct from '7796e95573b389d8d77fc80502d4f6f7f1b54a5155327f9a7f1eb42a7137f531'
  or p_envelope->'applied_exceptions' is distinct from summary
  or p_envelope->'adapter' is distinct from '{"schema":"custodial.approved-manual-period-database-adapter.v1","version":"approved-manual-period-v1"}'::jsonb
  or p_envelope->>'compiler_version' is distinct from 'approved-manual-period-v1'
  or p_envelope->>'service_date' is distinct from frame::text or p_envelope->>'week_start' is distinct from frame::text
  or p_envelope->>'week_end' is distinct from (frame+6)::text
  or p_envelope->>'authority_digest' is distinct from public.static_weekly_digest_jsonb(a)
  or p_envelope->>'database_projection_identity' is distinct from public.static_weekly_digest_jsonb(p_envelope-'database_projection_identity')
  or p_envelope->'objective' is distinct from jsonb_build_object('contract','OWNER_APPROVED_MANUAL_DATED_75_25_V2',
   'formulaObjectiveDigest',a->'formulaObjectiveDigest','proximityPercent',75,'workloadPercent',25,'normalDaysOptimized',false)
  or p_envelope->'metrics' is distinct from jsonb_build_object('hardConstraints',a->'hardConstraintCount','violations',0)
  or p_envelope#>>'{receipt,schema}' is distinct from 'custodial.approved-manual-native-feasibility-data.v1'
  or p_envelope#>'{receipt,hardConstraintCount}' is distinct from a->'hardConstraintCount'
  or p_envelope#>'{receipt,hardConstraintDigest}' is distinct from a->'hardConstraintDigest'
  or p_envelope#>'{receipt,fixedWitnessDigest}' is distinct from a->'fixedWitnessDigest'
 then raise exception 'Manual native envelope identity or approved formula differs';end if;
 if jsonb_typeof(p_envelope->'assignments') is distinct from 'array' or jsonb_array_length(p_envelope->'assignments') not between 1 and 4096
  or jsonb_typeof(a->'datedDayBases') is distinct from 'array' or jsonb_array_length(a->'datedDayBases')>7
  or jsonb_typeof(a->'parentLinks') is distinct from 'array' or jsonb_array_length(a->'parentLinks')>4096
  or jsonb_typeof(a->'projectionAvailability') is distinct from 'array' or jsonb_array_length(a->'projectionAvailability')>224
  or (select count(*)<>count(distinct r->>'plan_work_id') from jsonb_array_elements(p_envelope->'assignments') r)
  or (select count(*)<>count(distinct r->>'serviceDate') from jsonb_array_elements(a->'datedDayBases') r)
  or (select count(*)<>count(distinct r->>'workId') from jsonb_array_elements(a->'parentLinks') r)
 then raise exception 'Manual native bounded unique records required';end if;
 -- This first admission supports full-day canonical PTO/absence and its exact
 -- cancellation. Other exception shapes fail closed, never silently disappear.
 if exists(select 1 from jsonb_array_elements(exceptions) e where (e->>'type' not in('pto','daily_absence') or e ? 'window')
  and (e->>'type' not in('cover_all','lunch') or not e ? 'coverAllChoiceId'
   or not public.static_weekly_recurring_exact_accepted_coverall_fact(p_operation,p_manager,publication,frame,e)))
 then raise exception using errcode='0A000',message='Manual native exception requires its qualified dated profile';end if;
 policy:=public.static_weekly_manual_absence_policy();
 for base in select value from jsonb_array_elements(source#>'{version,slotAvailability}') loop
  dow:=(base->>'dayOfWeek')::integer;day:=frame+mod(dow-extract(dow from frame)::integer+7,7);
  availability:=public.static_weekly_approved_dated_effective_availability(base,base->>'slotId',day,exceptions);
  if availability->>'status'='working' and exists(select 1 from jsonb_array_elements(basis->'rosterUnavailableByDate') r where r->>'serviceDate'=day::text)
  then availability:=availability||'{"blockedWindows":[]}'::jsonb;end if;
  if availability->>'status'='working' and (
   exists(select 1 from jsonb_array_elements(exceptions) e
    join jsonb_array_elements(source#>'{version,slotAvailability}') av on av->'slotId'=e#>'{payload,slotId}' and av->>'dayOfWeek'=dow::text and av->>'status'='working'
    where e->>'serviceDate'=day::text and e->>'type' in('pto','daily_absence'))
   or exists(select 1 from jsonb_array_elements(basis->'employmentByDate') ed
    cross join lateral jsonb_array_elements(ed->'employees') ee
    join jsonb_array_elements(source->'slots') es on exists(select 1 from jsonb_array_elements(es->'incumbencies') ei
     where ei->'personId'=ee->'employeeId' and (ei->>'effectiveStart')::date<=day and (ei->>'effectiveEnd' is null or day<(ei->>'effectiveEnd')::date))
    join jsonb_array_elements(source#>'{version,slotAvailability}') ea on ea->'slotId'=es->'id' and ea->>'dayOfWeek'=dow::text and ea->>'status'='working'
    where ed->>'serviceDate'=day::text and (ee#>>'{command,fact,state}'='PRE_START' or day<(ee#>>'{command,fact,firstServiceDate}')::date))) then
   availability:=availability||'{"blockedWindows":[]}'::jsonb;
  end if;
  select s into strict slot from jsonb_array_elements(source->'slots') s where s->'id'=base->'slotId';
  select i into strict person from jsonb_array_elements(slot->'incumbencies') i
   where (i->>'effectiveStart')::date<=day and (i->>'effectiveEnd' is null or day<(i->>'effectiveEnd')::date);
  select e into employment_employee from jsonb_array_elements(basis->'employmentByDate') d
   cross join lateral jsonb_array_elements(d->'employees') e
   where d->>'serviceDate'=day::text and e->'employeeId'=person->'personId';
  if base->>'status'='working' and exists(select 1 from jsonb_array_elements(basis->'rosterUnavailableByDate') r
   where r->>'serviceDate'=day::text and r->'slotId'=base->'slotId' and r->'employeeId'=person->'personId') then
   availability:=availability||'{"status":"absent","blockedWindows":[{"start":"00:00","end":"23:59"}]}'::jsonb;
  end if;
  if base->>'status'='working' and employment_employee is not null and
   (employment_employee#>>'{command,fact,state}'='PRE_START' or day<(employment_employee#>>'{command,fact,firstServiceDate}')::date) then
   availability:=availability||'{"status":"absent","blockedWindows":[{"start":"00:00","end":"23:59"}],"unavailabilityClassification":"PRE_START_NOT_PTO"}'::jsonb;
  end if;
  expected_availability:=expected_availability||jsonb_build_array(availability||jsonb_build_object(
   'serviceDate',day::text,'incumbentPersonId',person->'personId','incumbentName',person->'displayName'));
 end loop;
 -- Add only the exact selected active capacity; inactive templates do not create employees.
 for day_basis in select value from jsonb_array_elements(a->'datedDayBases') where value->>'kind'='COVERALL' loop
  coverall:=public.static_weekly_coverall_assert_retained_day(p_operation,p_manager,day_basis,publication);
  choice_day:=coverall->'choiceDay';capacity_id:=choice_day->>'capacityId';
  select coalesce(jsonb_agg(r),'[]') into expected_availability from jsonb_array_elements(expected_availability) r
   where not(r->>'serviceDate'=choice_day->>'serviceDate' and r->>'slotId'=capacity_id);
  expected_availability:=expected_availability||jsonb_build_array(public.static_weekly_coverall_capacity_availability(source,choice_day)||jsonb_build_object(
   'serviceDate',choice_day->'serviceDate','incumbentPersonId',null,'incumbentName',null,'ownerKind','CONTRACTOR_CAPACITY','capacityId',capacity_id));
 end loop;
 select coalesce(jsonb_agg(r order by (r->>'dayOfWeek')::integer,r->>'slotId' collate "C"),'[]') into expected from jsonb_array_elements(expected_availability) r;
 select coalesce(jsonb_agg(r order by (r->>'dayOfWeek')::integer,r->>'slotId' collate "C"),'[]') into actual from jsonb_array_elements(a->'projectionAvailability') r;
 if actual is distinct from expected then raise exception 'Manual native static hours, eligibility or actual absence changed';end if;

 for day in select generate_series(frame,frame+6,'1 day')::date loop
  dow:=extract(dow from day)::integer;
  select r into strict normal_day from jsonb_array_elements(policy->'days') r where r->>'weekday'=dow::text;
  select coalesce(jsonb_agg(r->'incumbentPersonId' order by r->>'incumbentPersonId'),'[]') into absent
   from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'status'='absent';
  select coalesce(jsonb_agg(r->'incumbentPersonId' order by r->>'incumbentPersonId'),'[]') into pre_start
   from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'unavailabilityClassification'='PRE_START_NOT_PTO';
  day_changed:=jsonb_array_length(absent)>0;
  select r into day_basis from jsonb_array_elements(a->'datedDayBases') r where r->>'serviceDate'=day::text;
  if day_changed is distinct from (day_basis is not null) then raise exception 'Manual native complete dated day set differs';end if;
  normal_start:=normal_day#>>'{checkedWindow,start}';normal_end:=normal_day#>>'{checkedWindow,end}';
  select max(r#>>'{shift,start}'),max(r#>>'{shift,end}') into complete_start,complete_end
   from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'status'='working';
  if complete_start is null or complete_start>=complete_end then raise exception 'Manual native staffed window is empty';end if;
  is_coverall:=day_basis->>'kind'='COVERALL';coverall:=null;choice_day:=null;capacity_id:=null;replaced_id:=null;
  if coalesce(is_coverall,false) then
   coverall:=public.static_weekly_coverall_assert_retained_day(p_operation,p_manager,day_basis,publication);
   choice_day:=coverall->'choiceDay';capacity_id:=choice_day->>'capacityId';replaced_id:=coverall->>'replacedSlotId';
   if jsonb_array_length(absent)<>3 or absent is distinct from day_basis#>'{overlay,absentPersonIds}' then raise exception 'Exact third actual absence required';end if;
   input:=day_basis->'input';plan:=day_basis->'overlay';
   select coalesce(jsonb_agg(r->'incumbentPersonId' order by r->>'incumbentPersonId'),'[]') into expected
    from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'unavailabilityClassification'='PRE_START_NOT_PTO';
   if coalesce(input->'preStartPersonIds','[]') is distinct from expected then raise exception 'Retained2 pre-start classification differs from current actual employment reads';end if;
   complete_start:=plan#>>'{checkedWindow,start}';complete_end:=plan#>>'{checkedWindow,end}';
  end if;
  if day_changed and not coalesce(is_coverall,false) then
   if jsonb_array_length(absent) not between 1 and 2 or day_basis->>'kind' is distinct from 'ABSENCE' then
    raise exception using errcode='0A000',message='Third absence requires the retained two-absence basis and actual CoverAll hours';end if;
   input:=day_basis->'input';plan:=day_basis->'plan';
   if input->>'inputDigest' is distinct from public.static_weekly_digest_jsonb(input-'inputDigest')
    or plan->>'planDigest' is distinct from public.static_weekly_digest_jsonb(plan-'planDigest')
    or input->'sourceDigest' is distinct from a->'sourceDigest' or input->'formulaObjectiveDigest' is distinct from a->'formulaObjectiveDigest'
    or input->>'serviceDate' is distinct from day::text or plan->>'serviceDate' is distinct from day::text
    or input->'absentPersonIds' is distinct from absent or plan->'absentPersonIds' is distinct from absent
    or coalesce(input->'preStartPersonIds','[]') is distinct from pre_start
    or (jsonb_array_length(pre_start)>0 and input->>'preStartClassification' is distinct from 'PRE_START_NOT_PTO')
    or input->'checkedWindow' is distinct from jsonb_build_object('start',complete_start,'end',complete_end)
    or plan->'checkedWindow' is distinct from input->'checkedWindow' or plan->'inputDigest' is distinct from input->'inputDigest'
    or plan->'proposalDigest' is distinct from a->'formulaObjectiveDigest' or input->'access' is distinct from policy->'access'
    or input->'groups' is distinct from policy->'groups' or plan->'groups' is distinct from policy->'groups'
    or plan->'hardFeasibilityValidatedBeforeScoring' is distinct from 'true'::jsonb or plan->'globalOptimalityClaim' is distinct from 'false'::jsonb
    or exists(select 1 from unnest(array['publicationEligible','weeklyBaselineChanged','productionWritten','contractorBooked']) k where plan->k is distinct from 'false'::jsonb)
   then raise exception 'Manual native dated immutable input, source or formula changed';end if;
   select coalesce(jsonb_agg(jsonb_build_array(r->'slotId',r->'incumbentPersonId',r->'shift',r->'lunch') order by r->>'slotId'),'[]') into expected
    from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'status'='working';
   select coalesce(jsonb_agg(jsonb_build_array(r->'slotId',r->'personId',r->'shift',r->'lunch') order by r->>'slotId'),'[]') into actual from jsonb_array_elements(input->'roster') r;
   if expected is distinct from actual then raise exception 'Manual native dated roster changed';end if;
   for item in select value from jsonb_array_elements(input->'roster') loop
    select r->'baseGroups' into strict expected from jsonb_array_elements(normal_day->'employees') r where r->>'name'=item->>'name';
    select coalesce(jsonb_agg(to_jsonb(r->>'code') order by ord),'[]') into actual
     from jsonb_array_elements(expected) with ordinality x(name,ord) join jsonb_array_elements(policy->'groups') r on r->'name'=name;
    if item->'baseCodes' is distinct from actual then raise exception 'Manual native distance anchor changed from approved normal day';end if;
   end loop;
  end if;

  for item in select value from jsonb_array_elements(p_envelope->'assignments') where value->>'service_date'=day::text loop
   w:=item->'work_snapshot';parent:=null;link:=null;
   select r into parent from jsonb_array_elements(source#>'{version,assignments}') r
    where r->>'dayOfWeek'=dow::text and r->'workId'=item->'work_id';
   if parent is null then
    select r into strict link from jsonb_array_elements(a->'parentLinks') r where r->'workId'=item->'work_id';
    select r into strict parent from jsonb_array_elements(source#>'{version,assignments}') r where r->>'dayOfWeek'=dow::text and r->'workId'=link->'parentWorkId';
    if link->'serviceDate' is distinct from item->'service_date' or link->'window' is distinct from w->'window' or link->'slotId' is distinct from item->'owner_slot_id'
     or coalesce(item->>'work_id','')!~'^manual-dated:[0-9a-f]{64}$' then raise exception 'Manual native parent lineage differs';end if;
   end if;
   select r into strict availability from jsonb_array_elements(expected_availability) r where r->'slotId'=item->'owner_slot_id' and r->>'serviceDate'=day::text;
   if coalesce(is_coverall,false) and item->>'owner_slot_id'=capacity_id then owner_config:='{}';
   else select value into strict owner_config from jsonb_each(basis#>'{ownerConfig,slots}') where value->'slotId'=item->'owner_slot_id';end if;
   window_start:=w#>>'{window,start}';window_end:=w#>>'{window,end}';
   perform public.static_weekly_v3_assert_window(w->'window','manual native custody');
   if item->>'status' is distinct from 'assigned' or item->'reason_code' is distinct from 'null'::jsonb
    or item->>'day_of_week' is distinct from dow::text or item->>'plan_work_id' is distinct from dow::text||':'||(item->>'work_id')
    or item->'owner_person_id' is distinct from availability->'incumbentPersonId' or item->'optimized_owner_person_id' is distinct from item->'owner_person_id'
    or item->'optimized_owner_slot_id' is distinct from item->'owner_slot_id'
    or (case when coalesce(is_coverall,false) and item->>'owner_slot_id'=capacity_id then
      item->>'owner_kind' is distinct from 'CONTRACTOR_CAPACITY' or item->>'capacity_id' is distinct from capacity_id or item->'owner_person_id' is distinct from 'null'::jsonb
     else item ? 'owner_kind' or item ? 'capacity_id' end)
    or availability->>'status' is distinct from 'working' or window_start<availability#>>'{shift,start}' or window_end>availability#>>'{shift,end}'
    or item->'baseline_owner_slot_id' is distinct from parent->'originSlotId' or w->'originSlotId' is distinct from parent->'originSlotId'
   then raise exception 'Manual native actual static owner, window or original actor changed';end if;
   select r into strict base from jsonb_array_elements(expected_availability) r where r->'slotId'=parent->'originSlotId' and r->>'serviceDate'=day::text;
   if item->'baseline_owner_person_id' is distinct from base->'incumbentPersonId' or item->'original_actor_person_id' is distinct from base->'incumbentPersonId'
    or item->'baseline_owner_name' is distinct from base->'incumbentName' or item->'original_actor_name' is distinct from base->'incumbentName'
    or item->>'owner_digest' is distinct from public.static_weekly_digest_jsonb(jsonb_build_object('planWorkId',item->'plan_work_id','slotId',item->'owner_slot_id','personId',item->'owner_person_id','serviceDate',item->'service_date'))
    or item->>'exact_owner_identity' is distinct from public.static_weekly_digest_jsonb(jsonb_build_object('plan_work_id',item->'plan_work_id','service_date',item->'service_date','optimized_owner_slot_id',item->'owner_slot_id','optimized_owner_person_id',item->'owner_person_id','baseline_owner_slot_id',parent->'originSlotId','baseline_owner_person_id',base->'incumbentPersonId'))
   then raise exception 'Manual native owner lineage digest changed';end if;
   inherited:=day_changed and exists(select 1 from jsonb_array_elements(plan->'phaseOwners') with ordinality x(ph,phase_number)
    where phase_number>1 and ph#>>'{window,start}'<=window_start and window_start<ph#>>'{window,end}');
   expected:=jsonb_build_object('workId',item->'work_id','dayOfWeek',dow,'originSlotId',parent->'originSlotId',
    'locationId',parent->'locationId','locationCodeSnapshot',parent->'locationCodeSnapshot','locationNameSnapshot',parent->'locationNameSnapshot',
    'serviceMode',parent->'serviceMode','includedLocations',parent->'includedLocations','window',w->'window',
    'serviceEffortMinutes',w->'serviceEffortMinutes','serviceEffortProvenance',w->'serviceEffortProvenance',
    'priority',parent->'priority','priorityProvenance',parent->'priorityProvenance','required',parent->'required',
    'coveragePolicy',null,'bestEffortCoverage',false,'coveragePolicyOrder',null,'coveragePolicyProvenance',null,
    'requiredQualifications',parent->'requiredQualifications','qualificationProvenance',parent->'qualificationProvenance',
    'restrictions',parent->'restrictions','restrictionProvenance',parent->'restrictionProvenance','restrictedSlotIds',parent->'restrictedSlotIds',
    'manualLock',false,'manualLockSlotId',null,'overlayWork',false);
   if jsonb_array_length(coalesce(parent->'normalAssignmentRestrictedSlotIds','[]'))>0 then
    expected:=expected||jsonb_build_object('normalAssignmentRestrictedSlotIds',parent->'normalAssignmentRestrictedSlotIds','coveragePurpose',parent->'coveragePurpose');
   end if;
   if inherited and dow<>1 and parent->>'locationCodeSnapshot'='HERPETARIUM'
    and parent->'restrictedSlotIds' ? (basis#>>'{ownerConfig,slots,ALIJAH,slotId}') then
    expected:=expected||jsonb_build_object('restrictedSlotIds',(parent->'restrictedSlotIds')-(basis#>>'{ownerConfig,slots,ALIJAH,slotId}'),
     'normalAssignmentRestrictedSlotIds',jsonb_build_array(basis#>>'{ownerConfig,slots,ALIJAH,slotId}'),
     'coveragePurpose','INHERITED_ALERTS_AND_ISSUES_ONLY','restrictionProvenance',(parent->>'restrictionProvenance')||';normal-assignment-scope:fe02bbdebc736d95360b55cc7dfe5b73c5a9eaa76f364f1c0f4420a0afb9950f');
   end if;
   if w is distinct from expected or not ((availability->'qualifications') @> (w->'requiredQualifications'))
    or w->'restrictedSlotIds' ? (item->>'owner_slot_id') or owner_config->'hardForbiddenFamilies' ? (w->>'locationCodeSnapshot')
    or exists(select 1 from jsonb_array_elements(w->'includedLocations') r where availability->'restrictions' ? (r->>'locationId'))
    or (item->>'owner_slot_id'=basis#>>'{ownerConfig,slots,TAMMY,slotId}' and w->>'locationCodeSnapshot' not in('TETON','NORTH_WEST_PASSAGE','EAST_END_RESTROOMS','CHINA'))
   then raise exception 'Manual native physical members, hard eligibility or scoped restriction changed: work %, fields %',item->>'work_id',
    (select coalesce(jsonb_agg(k order by k),'[]') from (select jsonb_object_keys(w||expected) k) q where w->k is distinct from expected->k);end if;
   if not day_changed and (link is not null or item->'owner_slot_id' is distinct from parent->'ownerSlotId' or w->'window' is distinct from parent->'window'
    or w->'serviceEffortMinutes' is distinct from parent->'serviceEffortMinutes' or w->'serviceEffortProvenance' is distinct from parent->'serviceEffortProvenance')
   then raise exception 'Manual native changed an approved normal day';end if;
   if day_changed and ((window_end>parent#>>'{window,end}' and not(coalesce(is_coverall,false) and item->>'owner_slot_id'=capacity_id
     and parent#>>'{window,end}'=normal_end and window_end<=choice_day#>>'{shift,end}')) or window_start<case
    when parent#>>'{window,start}'<=normal_start and parent#>>'{window,end}'>normal_start
     then least(parent#>>'{window,start}',complete_start) else parent#>>'{window,start}' end)
   then raise exception 'Manual native custody exceeds its exact parent boundary';end if;
   -- A single unchanged owner can continue across the complete-crew arrival.
   -- That harmless merged row must still preserve the whole early base prefix.
   if day_changed and window_start<complete_start and ((item->'owner_slot_id' is distinct from parent->'ownerSlotId'
     and not(coalesce(is_coverall,false) and parent->>'ownerSlotId'=replaced_id and item->>'owner_slot_id'=capacity_id))
    or window_start<>parent#>>'{window,start}' or window_end<least(parent#>>'{window,end}',complete_start))
   then raise exception 'Manual native early own-base custody differs';end if;
   if day_changed and window_end>complete_start then
    if window_end>complete_end then raise exception 'Manual native actual full-site window differs';end if;
    for phase in select value from jsonb_array_elements(plan->'phaseOwners') where value#>>'{window,start}'<window_end and window_start<value#>>'{window,end}' loop
     if phase#>>array['owners',w->>'locationCodeSnapshot'] is distinct from item->>'owner_slot_id' then raise exception 'Manual native selected phase differs from stored custody';end if;
    end loop;
   end if;
   select assignment_id into strict assignment from public.weekly_schedule_slot_assignments
    where version_id=version and day_of_week=dow and work_id=parent->>'workId';
   links:=links||jsonb_build_object(item->>'plan_work_id',assignment::text);
  end loop;

  -- Every physical group tiles the complete actual staffed window once.
  for code in select r->>'code' from jsonb_array_elements(policy->'groups') r loop
   previous_end:=complete_start;previous_owner:=null;
   for item in select r from jsonb_array_elements(p_envelope->'assignments') r where r->>'service_date'=day::text
    and r#>>'{work_snapshot,locationCodeSnapshot}'=code and r#>>'{work_snapshot,window,end}'>complete_start
    order by r#>>'{work_snapshot,window,start}' loop
    window_start:=greatest(complete_start,item#>>'{work_snapshot,window,start}');window_end:=least(complete_end,item#>>'{work_snapshot,window,end}');
    if window_end<=window_start then continue;end if;
    if window_start<>previous_end then raise exception 'Manual native full-site gap or overlap';end if;
    if day_changed and previous_owner is not null and previous_owner<>item->>'owner_slot_id' and not exists(
     select 1 from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'slotId'=previous_owner and r#>>'{shift,end}'=window_start)
     and not(coalesce(is_coverall,false) and previous_owner=capacity_id and exists(
      select 1 from jsonb_array_elements(day_basis#>'{input,roster}') retained_owner
       where retained_owner->>'slotId'=replaced_id and retained_owner#>>'{shift,end}'=window_start))
    then raise exception 'Manual native owner moved before the static departure';end if;
    previous_end:=window_end;previous_owner:=item->>'owner_slot_id';
   end loop;
   if previous_end<>complete_end then raise exception 'Manual native full-site coverage incomplete';end if;
   select sum((r->>'serviceEffortMinutes')::integer) into budget from jsonb_array_elements(source#>'{version,assignments}') r where r->>'dayOfWeek'=dow::text and r->>'locationCodeSnapshot'=code;
   select sum((r#>>'{work_snapshot,serviceEffortMinutes}')::integer) into actual_effort from jsonb_array_elements(p_envelope->'assignments') r where r->>'service_date'=day::text and r#>>'{work_snapshot,locationCodeSnapshot}'=code;
   if actual_effort is distinct from budget then raise exception 'Manual native combined group workload budget changed';end if;
  end loop;
  if not day_changed and (select count(*) from jsonb_array_elements(p_envelope->'assignments') r where r->>'service_date'=day::text)
   <>(select count(*) from jsonb_array_elements(source#>'{version,assignments}') r where r->>'dayOfWeek'=dow::text)
  then raise exception 'Manual native omitted approved normal rows';end if;
  if day_changed and not coalesce(is_coverall,false) then
   perform public.static_weekly_manual_assert_absence_score(day_basis,normal_day,policy,expected_availability,p_envelope->'assignments',basis->'ownerConfig');
  end if;
 end loop;
 if (select count(*) from jsonb_object_keys(links))<>jsonb_array_length(p_envelope->'assignments')
  or exists(select 1 from jsonb_array_elements(a->'parentLinks') l where not exists(select 1 from jsonb_array_elements(p_envelope->'assignments') r where r->'work_id'=l->'workId' and r->'service_date'=l->'serviceDate'))
 then raise exception 'Manual native foreign row or unused parent link';end if;
 if summary is distinct from public.static_weekly_accepted_exception_set(publication,frame)
 then raise exception 'Manual native original fact did not become exact accepted authority';end if;
 if exists(select 1 from jsonb_array_elements(p_envelope->'assignments') assigned where assigned->>'owner_person_id' is not null
  and not exists(select 1 from public.v_weekly_roster_slot_incumbency_ranges r join public.employees e on e.id=r.person_id
   where r.slot_id=(assigned->>'owner_slot_id')::uuid and r.person_id=(assigned->>'owner_person_id')::uuid and r.effective_start<=(assigned->>'service_date')::date
    and (r.effective_end is null or (assigned->>'service_date')::date<r.effective_end) and e.active))
 then raise exception 'Recurring assignment cannot use a displaced/inactive historical employee';end if;
 perform public.static_weekly_manual_assert_native_lunch(NULL,p_lunch,p_envelope,publication,frame);
 return jsonb_build_object('assignment_links',links,'projection_assignments',p_envelope->'assignments','kind','RECURRING_MANUAL_MATERIALIZATION');
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_manual_identity_json(p_value jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare result text;
begin
 case jsonb_typeof(p_value)
 when 'object' then select '{'||coalesce(string_agg(to_jsonb(k)::text||':'||public.static_weekly_manual_identity_json(v),',' order by k collate "C"),'')||'}' into result from jsonb_each(p_value) x(k,v);
 when 'array' then select '['||coalesce(string_agg(public.static_weekly_manual_identity_json(v),',' order by n),'')||']' into result from jsonb_array_elements(p_value) with ordinality x(v,n);
 else result:=p_value::text;
 end case;return result;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_manual_lunch_current_basis(p_source uuid, p_source_document text, p_notification_key text, p_service_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
 authority record;origin public.weekly_schedule_compiled_projections%rowtype;
 current_projection public.weekly_schedule_compiled_projections%rowtype;
 prior_projection public.weekly_schedule_compiled_projections%rowtype;
 original_doc public.weekly_schedule_lunch_documents%rowtype;
 current_doc public.weekly_schedule_lunch_documents%rowtype;
 prior_doc public.weekly_schedule_lunch_documents%rowtype;
 original_intent jsonb;intent jsonb;original_loan jsonb;loan jsonb;retention jsonb;
 expected jsonb;actual jsonb;matches integer;visited uuid[]:='{}';hop integer:=0;
 current_id uuid;current_identity text;
BEGIN
 IF p_source IS NULL OR p_service_date IS NULL OR NOT isfinite(p_service_date)
  OR coalesce(p_source_document,'') !~ '^[0-9a-f]{64}$'
  OR coalesce(p_notification_key,'') !~ '^[0-9a-f]{64}$' THEN RETURN NULL;END IF;
 SELECT * INTO authority FROM public.static_weekly_v6_schedule_authority_state(p_service_date);
 IF authority.governed IS NOT TRUE OR authority.projection_status IS DISTINCT FROM 'current'
  OR authority.projection_id IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO origin FROM public.weekly_schedule_compiled_projections WHERE projection_id=p_source;
 SELECT * INTO original_doc FROM public.weekly_schedule_lunch_documents WHERE projection_id=p_source;
 SELECT * INTO current_projection FROM public.weekly_schedule_compiled_projections WHERE projection_id=authority.projection_id;
 SELECT * INTO current_doc FROM public.weekly_schedule_lunch_documents WHERE projection_id=authority.projection_id;
 IF origin.projection_id IS NULL OR original_doc.projection_id IS NULL
  OR current_projection.projection_id IS NULL OR current_doc.projection_id IS NULL
  OR original_doc.document_identity IS DISTINCT FROM p_source_document
  OR origin.publication_id IS DISTINCT FROM authority.publication_id
  OR origin.version_id IS DISTINCT FROM authority.version_id
  OR origin.week_start IS DISTINCT FROM current_projection.week_start
  OR origin.week_end IS DISTINCT FROM current_projection.week_end
  OR p_service_date NOT BETWEEN origin.week_start AND origin.week_end THEN RETURN NULL;END IF;
 PERFORM custodial_coverall.require_lunch_admission_proof(origin.projection_id,original_doc.document_json);
 SELECT count(*) INTO matches FROM jsonb_array_elements(original_doc.document_json->'notification_intents') n
  WHERE n->>'notification_key'=p_notification_key AND n->>'service_date'=p_service_date::text;
 IF matches<>1 THEN RETURN NULL;END IF;
 SELECT n INTO original_intent FROM jsonb_array_elements(original_doc.document_json->'notification_intents') n
  WHERE n->>'notification_key'=p_notification_key AND n->>'service_date'=p_service_date::text;
 SELECT count(*) INTO matches FROM jsonb_array_elements(original_doc.document_json->'loans') l
  WHERE l->>'loan_id'=original_intent->>'loan_id' AND l->>'service_date'=p_service_date::text AND l->>'status'='PLANNED';
 IF matches<>1 THEN RETURN NULL;END IF;
 SELECT l INTO original_loan FROM jsonb_array_elements(original_doc.document_json->'loans') l
  WHERE l->>'loan_id'=original_intent->>'loan_id' AND l->>'service_date'=p_service_date::text AND l->>'status'='PLANNED';
 current_id:=current_projection.projection_id;current_identity:=current_doc.document_identity;
 LOOP
  -- Fail closed after 128 immutable links or a cycle; never repair/reset a job.
  hop:=hop+1;
  IF hop>128 OR current_projection.projection_id=ANY(visited)
   OR current_projection.publication_id IS DISTINCT FROM origin.publication_id
   OR current_projection.version_id IS DISTINCT FROM origin.version_id
   OR current_projection.week_start IS DISTINCT FROM origin.week_start
   OR current_projection.week_end IS DISTINCT FROM origin.week_end
   OR current_doc.projection_id IS DISTINCT FROM current_projection.projection_id
   OR current_doc.document_identity IS DISTINCT FROM current_doc.document_json->>'document_identity'
   THEN RETURN NULL;END IF;
  visited:=array_append(visited,current_projection.projection_id);
  PERFORM custodial_coverall.require_lunch_admission_proof(current_projection.projection_id,current_doc.document_json);
  SELECT count(*) INTO matches FROM jsonb_array_elements(current_doc.document_json->'notification_intents') n
   WHERE n->>'notification_key'=p_notification_key AND n->>'service_date'=p_service_date::text;
  IF matches<>1 THEN RETURN NULL;END IF;
  SELECT n INTO intent FROM jsonb_array_elements(current_doc.document_json->'notification_intents') n
   WHERE n->>'notification_key'=p_notification_key AND n->>'service_date'=p_service_date::text;
  IF intent IS DISTINCT FROM original_intent THEN RETURN NULL;END IF;
  SELECT count(*) INTO matches FROM jsonb_array_elements(current_doc.document_json->'loans') l
   WHERE l->>'loan_id'=intent->>'loan_id' AND l->>'service_date'=p_service_date::text AND l->>'status'='PLANNED';
  IF matches<>1 THEN RETURN NULL;END IF;
  SELECT l INTO loan FROM jsonb_array_elements(current_doc.document_json->'loans') l
   WHERE l->>'loan_id'=intent->>'loan_id' AND l->>'service_date'=p_service_date::text AND l->>'status'='PLANNED';
  IF loan-'total_distance_minutes' IS DISTINCT FROM original_loan-'total_distance_minutes' THEN RETURN NULL;END IF;
  SELECT coalesce(jsonb_agg(r-'proximity_evidence' ORDER BY (r-'proximity_evidence')::text),'[]') INTO expected
   FROM jsonb_array_elements(original_doc.document_json->'responsibilities') r WHERE r->'loan_id'=original_loan->'loan_id';
  SELECT coalesce(jsonb_agg(r-'proximity_evidence' ORDER BY (r-'proximity_evidence')::text),'[]') INTO actual
   FROM jsonb_array_elements(current_doc.document_json->'responsibilities') r WHERE r->'loan_id'=loan->'loan_id';
  IF expected='[]'::jsonb OR actual IS DISTINCT FROM expected THEN RETURN NULL;END IF;
  SELECT coalesce(jsonb_agg(n ORDER BY n::text),'[]') INTO expected
   FROM jsonb_array_elements(original_doc.document_json->'notification_intents') n WHERE n->'loan_id'=original_loan->'loan_id';
  SELECT coalesce(jsonb_agg(n ORDER BY n::text),'[]') INTO actual
   FROM jsonb_array_elements(current_doc.document_json->'notification_intents') n WHERE n->'loan_id'=loan->'loan_id';
  IF actual IS DISTINCT FROM expected THEN RETURN NULL;END IF;
  -- Original spoken owner/principal and original shift-end validity remain exact.
  SELECT coalesce(jsonb_agg(a-ARRAY['incumbentSlotId','incumbentSlotLabel'] ORDER BY (a-ARRAY['incumbentSlotId','incumbentSlotLabel'])::text),'[]') INTO expected
   FROM jsonb_array_elements(origin.projection_envelope#>'{authority,projectionAvailability}') a
   WHERE a->>'serviceDate'=p_service_date::text
    AND (a->>'slotId'=original_loan->>'normal_owner_slot_id' OR original_loan->'helper_slot_ids' ? (a->>'slotId'));
  SELECT coalesce(jsonb_agg(a-ARRAY['incumbentSlotId','incumbentSlotLabel'] ORDER BY (a-ARRAY['incumbentSlotId','incumbentSlotLabel'])::text),'[]') INTO actual
   FROM jsonb_array_elements(current_projection.projection_envelope#>'{authority,projectionAvailability}') a
   WHERE a->>'serviceDate'=p_service_date::text
    AND (a->>'slotId'=loan->>'normal_owner_slot_id' OR loan->'helper_slot_ids' ? (a->>'slotId'));
  IF expected='[]'::jsonb OR actual IS DISTINCT FROM expected THEN RETURN NULL;END IF;
  IF current_projection.projection_id=p_source THEN
   IF current_doc.document_identity IS DISTINCT FROM p_source_document THEN RETURN NULL;END IF;
   RETURN jsonb_build_object('source_projection_id',p_source,'source_document_identity',p_source_document,
    'current_projection_id',current_id,'current_document_identity',current_identity,'notification_key',p_notification_key);
  END IF;
  IF current_projection.projection_envelope#>>'{authority,schema}' IS DISTINCT FROM 'custodial.approved-manual-period-projection-authority.v1'
   OR current_projection.projection_envelope->'adapter' IS DISTINCT FROM
    '{"schema":"custodial.approved-manual-period-database-adapter.v1","version":"approved-manual-period-v1"}'::jsonb
   THEN RETURN NULL;END IF;
  retention:=current_projection.projection_envelope#>'{authority,lunchIdentityRetention}';
  IF retention IS NULL THEN RETURN NULL;END IF;
  PERFORM public.static_weekly_assert_exact_object(retention,
   ARRAY['schema','priorProjectionId','priorDocumentIdentity','loans','requiresSqlOwnerCurrentnessCheck'],
   ARRAY['schema','priorProjectionId','priorDocumentIdentity','loans','requiresSqlOwnerCurrentnessCheck'],'notification immutable lunch lineage');
  IF retention->>'schema' IS DISTINCT FROM 'custodial.approved-manual-lunch-identity-retention.v1'
   OR retention->'requiresSqlOwnerCurrentnessCheck' IS DISTINCT FROM 'true'::jsonb
   OR jsonb_typeof(retention->'loans') IS DISTINCT FROM 'array'
   OR coalesce(retention->>'priorDocumentIdentity','') !~ '^[0-9a-f]{64}$'
   OR (SELECT count(*) FROM jsonb_array_elements(retention->'loans') r
    WHERE r=jsonb_build_object('serviceDate',p_service_date::text,'normalOwnerSlotId',loan->'normal_owner_slot_id','loanId',loan->'loan_id'))<>1
   THEN RETURN NULL;END IF;
  SELECT * INTO prior_projection FROM public.weekly_schedule_compiled_projections WHERE projection_id=(retention->>'priorProjectionId')::uuid;
  SELECT * INTO prior_doc FROM public.weekly_schedule_lunch_documents WHERE projection_id=prior_projection.projection_id;
  IF prior_projection.projection_id IS NULL OR prior_doc.projection_id IS NULL
   OR prior_doc.document_identity IS DISTINCT FROM retention->>'priorDocumentIdentity' THEN RETURN NULL;END IF;
  current_projection:=prior_projection;current_doc:=prior_doc;
 END LOOP;
EXCEPTION WHEN data_exception OR check_violation OR cardinality_violation THEN RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_manual_period_basis(p_manager uuid, p_publication uuid, p_date date, p_revision bigint, p_operation uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare source jsonb;normal_source jsonb;original_source jsonb;exceptions jsonb;original_exceptions jsonb;summary jsonb;
 ctx jsonb;actor jsonb;frame date;version uuid;sid uuid;entry record;prior record;prior_json jsonb:=null;
 day_bases jsonb:='[]';body jsonb;original_revision bigint:=p_revision;employment jsonb:='[]';employment_vector jsonb;employment_day date;
begin
 perform public.static_weekly_v3_assert_control_plane();actor:=public.static_weekly_v3_manager_actor(p_manager);
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 if p_revision is null or p_revision not between 0 and 9007199254740991
  or p_revision is distinct from (select current_revision from public.static_weekly_schedule_control where singleton)
  or p_date is null or not isfinite(p_date) then raise exception using errcode='40001',message='Exact current manual period revision and date required';end if;
 source:=public.static_weekly_v3_read_publication_source(p_publication,p_date);
 if source#>>'{compiler_input,version,manualGroupRatingAuthority,manifestSha256}' is distinct from 'fe02bbdebc736d95360b55cc7dfe5b73c5a9eaa76f364f1c0f4420a0afb9950f'
  or source->>'publication_id' is distinct from p_publication::text then raise exception 'Exact approved manual publication required';end if;
 frame:=public.static_weekly_source_window_start(source->'compiler_input',p_date);
 source:=public.static_weekly_v3_read_publication_source(p_publication,frame);
 version:=(source->>'version_id')::uuid;
 if public.static_weekly_effective_version(frame) is distinct from version
  or public.static_weekly_effective_version(frame+6) is distinct from version then raise exception 'Manual period crosses an effective publication';end if;
 select authority_source_id into strict sid from public.weekly_schedule_versions where version_id=version;
 select c.template_id,c.owner_config,c.catalog_entry_digest,c.template_json,c.binding_json,c.approval_evidence into strict entry
 from public.static_weekly_approved_initial_baselines b join public.static_weekly_approved_template_catalog c using(template_id)
 where b.source_id=sid and not exists(select 1 from public.static_weekly_approved_template_retirements r where r.template_id=c.template_id);
 if entry.catalog_entry_digest is distinct from public.static_weekly_digest_jsonb(jsonb_build_object(
  'template',entry.template_json,'binding',entry.binding_json,'ownerConfig',entry.owner_config,'approvalEvidence',entry.approval_evidence))
  or entry.owner_config->>'approvedManualDataDigest' is distinct from 'eeff371f1510c6e4a079bde3ba17136dc10f64b100c7562d9b139fd14805a1c8'
 then raise exception 'The admitted manual policy/configuration changed';end if;
 normal_source:=jsonb_set(jsonb_set(source->'compiler_input','{serviceDate}',to_jsonb(frame::text),true),'{exceptions}','[]'::jsonb,true);
 if p_operation is not null then
  ctx:=public.static_weekly_pending_context(p_operation,p_manager);
  original_revision:=(ctx#>>'{originalCommand,expectedRevision}')::bigint;
  if frame>(ctx#>>'{originalCommand,semanticBody,endDate}')::date
   or frame+6<(ctx#>>'{originalCommand,semanticBody,startDate}')::date then raise exception 'Manual frame is outside the original command';end if;
  original_exceptions:=public.static_weekly_pending_original_exception_set(p_publication,frame,p_operation);
  exceptions:=public.static_weekly_pending_exception_set(p_operation,p_publication,frame,null);
  summary:=public.static_weekly_pending_summary(p_operation,p_publication,frame,null);
  original_source:=jsonb_set(jsonb_set(source,'{authority_revision}',to_jsonb(original_revision),false),'{exceptions}',original_exceptions,false);
 else
  exceptions:=public.static_weekly_compiler_exception_set(p_publication,frame);original_exceptions:=exceptions;
  summary:=public.static_weekly_accepted_exception_set(p_publication,frame);original_source:=source;
 end if;
 select p.projection_id,p.publication_id,p.version_id,p.week_start,p.week_end,p.projection_envelope,l.document_json into prior
 from public.weekly_schedule_compiled_projections p join public.weekly_schedule_lunch_documents l using(projection_id)
 where p.publication_id=p_publication and p.version_id=version and p.week_start=frame and p.week_end=frame+6
  and p.exception_set_digest=public.static_weekly_digest_jsonb(public.static_weekly_manual_exception_summary(original_exceptions))
 order by p.compiled_at desc,p.projection_id desc limit 1;
 if found then
  prior_json:=jsonb_build_object('projectionId',prior.projection_id,'publicationId',prior.publication_id,'versionId',prior.version_id,
   'frameStart',prior.week_start::text,'frameEnd',prior.week_end::text,'lunchDocument',prior.document_json);
  day_bases:=coalesce(prior.projection_envelope#>'{authority,datedDayBases}','[]'::jsonb);
 end if;
 for employment_day in select generate_series(frame,frame+6,'1 day')::date loop
  employment:=employment||jsonb_build_array(custodial_employment.native_read(employment_day,p_revision,p_manager));
 end loop;
 select jsonb_agg(jsonb_build_object('serviceDate',d->'serviceDate','employeeId',e->'employeeId',
  'employmentRevision',e->'employmentRevision','requestId',e#>>'{command,requestId}') order by d->>'serviceDate',e->>'employeeId')
 into employment_vector from jsonb_array_elements(employment) days(d) cross join lateral jsonb_array_elements(d->'employees') employees(e);
 body:=jsonb_build_object('schema','custodial.approved-manual-period-basis.v1','managerId',p_manager,'actor',actor,
  'publicationId',p_publication,'versionId',version,'sourceId',sid,'frameStart',frame::text,'frameEnd',(frame+6)::text,
  'authorityRevision',original_revision,'currentServiceDate',public.sch_service_date(statement_timestamp())::text,
  'originalCommand',ctx->'originalCommand','originalSource',original_source,'normalSource',normal_source,
  'normalSourceDigest',public.static_weekly_digest_jsonb(normal_source),'ownerConfig',entry.owner_config,
  'catalogEntryDigest',entry.catalog_entry_digest,'generation',public.static_weekly_v15_read_recurring_generation(),
  'employmentByDate',employment,'employmentRevisionVector',employment_vector,
  'preparedExceptions',exceptions,'preparedSummary',summary,'priorProjection',prior_json,'priorDayBases',day_bases,
  'priorRefreshTargets',public.static_weekly_v11_read_current_refresh_targets(
   case when p_operation is null then frame else greatest(frame,(ctx#>>'{originalCommand,semanticBody,startDate}')::date) end,
   case when p_operation is null then frame+6 else least(frame+6,(ctx#>>'{originalCommand,semanticBody,endDate}')::date) end,p_manager));
 return body||jsonb_build_object('basisDigest',public.static_weekly_digest_jsonb(body));
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_manual_projection_view_basis(p_manager uuid, p_projection uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare p public.weekly_schedule_compiled_projections%rowtype;current_state record;
begin
 perform public.static_weekly_v3_assert_control_plane();perform public.static_weekly_v3_manager_actor(p_manager);
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select * into strict p from public.weekly_schedule_compiled_projections where projection_id=p_projection;
 select * into current_state from public.static_weekly_v6_schedule_authority_state(p.week_start);
 if current_state.projection_status is distinct from 'current' or current_state.projection_id is distinct from p.projection_id
  or p.compiler_version is distinct from 'approved-manual-period-v1'
  or p.projection_envelope#>>'{adapter,schema}' is distinct from 'custodial.approved-manual-period-database-adapter.v1'
 then raise exception using errcode='40001',message='Exact current manual dated projection required for manager display';end if;
 return jsonb_build_object('schema','custodial.approved-manual-projection-view-basis.v1','projectionId',p.projection_id,
  'publicationId',p.publication_id,'versionId',p.version_id,'frameStart',p.week_start::text,'frameEnd',p.week_end::text,
  'projectionAvailability',p.projection_envelope#>'{authority,projectionAvailability}');
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_manual_recurring_assert_payload(p_operation uuid, p_manager uuid, p_envelope jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE ctx jsonb;proof jsonb;
BEGIN
 ctx:=public.static_weekly_manual_recurring_context(p_operation,p_manager);
 IF ctx->'stagedEnvelope' IS DISTINCT FROM p_envelope THEN RAISE EXCEPTION 'Exact same-transaction recurring stage required';END IF;
 proof:=public.static_weekly_manual_assert_recurring_projection(p_operation,p_manager,p_envelope,ctx->'stagedLunch');
 IF proof->'projection_assignments' IS DISTINCT FROM p_envelope->'assignments' OR jsonb_typeof(proof->'assignment_links') IS DISTINCT FROM 'object'
 THEN RAISE EXCEPTION 'Full native recurring feasibility/assignment proof required';END IF;
 RETURN proof;
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_manual_recurring_basis(p_manager uuid, p_publication uuid, p_frame date, p_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE basis jsonb;fixed_source jsonb;slots jsonb;canonical jsonb;days jsonb;body jsonb;
BEGIN
 basis:=public.static_weekly_manual_period_basis(p_manager,p_publication,p_frame,p_revision,NULL);
 SELECT s.canonical_source INTO STRICT canonical FROM public.static_weekly_authority_source_documents s
 WHERE s.source_id=(basis->>'sourceId')::uuid AND s.active AND s.retired_at IS NULL;
 IF NOT EXISTS(SELECT 1 FROM public.static_weekly_approved_initial_confirmations c WHERE c.publication_id=p_publication)
 THEN RAISE EXCEPTION 'Original accepted manual activation required';END IF;
 -- Preserve actual publication/version metadata, immutable original normal slots.
 fixed_source:=jsonb_set(basis->'normalSource','{slots}',canonical->'slots',false);
 SELECT coalesce(jsonb_agg(a.day_json||jsonb_build_object('choiceId',q.choice_id) ORDER BY a.service_date,a.operation_id),'[]') INTO days
 FROM custodial_coverall.accepted_days a JOIN custodial_coverall.choices q USING(operation_id)
 JOIN public.static_weekly_staffing_commands c USING(operation_id)
 WHERE a.publication_id=p_publication AND a.service_date BETWEEN p_frame AND p_frame+6 AND c.state='ACCEPTED'
  AND EXISTS(SELECT 1 FROM jsonb_array_elements(public.static_weekly_coverall_effective_facts(p_publication,p_frame)) e
    WHERE e->>'type'='cover_all' AND e->>'coverAllChoiceId'=q.choice_id::text AND e->>'serviceDate'=a.service_date::text);
 body:=(basis-'basisDigest')||jsonb_build_object('normalSource',fixed_source,'normalSourceDigest',public.static_weekly_digest_jsonb(fixed_source),
  'rosterUnavailableByDate',public.static_weekly_manual_recurring_roster_unavailable(fixed_source,p_frame),'acceptedCoverAllDays',days);
 IF jsonb_array_length(body->'employmentByDate')<>7 OR jsonb_array_length(body->'employmentRevisionVector')<>14
 THEN RAISE EXCEPTION 'Seven actual employment reads and14 bindings required';END IF;
 RETURN body||jsonb_build_object('basisDigest',public.static_weekly_digest_jsonb(body));
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_manual_recurring_context(p_operation uuid, p_manager uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE a custodial_coverall.recurring_materialization_operations%rowtype;stage_row custodial_coverall.recurring_materialization_stages%rowtype;
 employment jsonb:='[]';vector jsonb;service_day date;source_digest text;catalog text;ctx jsonb;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 SELECT * INTO STRICT a FROM custodial_coverall.recurring_materialization_operations WHERE operation_id=p_operation;
 IF a.manager_id<>p_manager OR a.owner_xid<>pg_current_xact_id() OR a.backend_pid<>pg_backend_pid()
  OR a.authority_revision IS DISTINCT FROM(SELECT current_revision FROM public.static_weekly_schedule_control WHERE singleton)
  OR a.generation IS DISTINCT FROM public.static_weekly_v15_read_recurring_generation()
  OR public.static_weekly_effective_version(a.frame_start) IS DISTINCT FROM a.version_id
  OR public.static_weekly_effective_version(a.frame_start+6) IS DISTINCT FROM a.version_id
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Original physical recurring transaction/revision/generation/publication changed';END IF;
 PERFORM public.custodial_action_actor_v1(p_manager,a.credential_id,a.device_id,a.session_access,'write');
 IF a.basis_json IS NULL THEN RAISE EXCEPTION 'Native recurring context required';END IF;
 SELECT s.source_digest,c.catalog_entry_digest INTO STRICT source_digest,catalog FROM public.static_weekly_authority_source_documents s
 JOIN public.static_weekly_approved_initial_baselines b ON b.source_id=s.source_id JOIN public.static_weekly_approved_template_catalog c USING(template_id)
 WHERE s.source_id=a.source_id AND s.active AND s.retired_at IS NULL AND NOT EXISTS(SELECT 1 FROM public.static_weekly_approved_template_retirements r WHERE r.template_id=c.template_id);
 FOR service_day IN SELECT generate_series(a.frame_start,a.frame_start+6,'1 day')::date LOOP employment:=employment||jsonb_build_array(custodial_employment.native_read(service_day,a.authority_revision,p_manager));END LOOP;
 SELECT jsonb_agg(jsonb_build_object('serviceDate',d->'serviceDate','employeeId',e->'employeeId','employmentRevision',e->'employmentRevision',
  'requestId',e#>>'{command,requestId}') ORDER BY d->>'serviceDate',e->>'employeeId') INTO vector
 FROM jsonb_array_elements(employment) days(d) CROSS JOIN LATERAL jsonb_array_elements(d->'employees') employees(e);
 IF source_digest IS DISTINCT FROM a.source_digest OR catalog IS DISTINCT FROM a.catalog_digest
  OR employment IS DISTINCT FROM a.basis_json->'employmentByDate' OR vector IS DISTINCT FROM a.basis_json->'employmentRevisionVector'
  OR public.static_weekly_compiler_exception_set(a.publication_id,a.frame_start) IS DISTINCT FROM a.basis_json->'preparedExceptions'
  OR public.static_weekly_accepted_exception_set(a.publication_id,a.frame_start) IS DISTINCT FROM a.basis_json->'preparedSummary'
  OR public.static_weekly_manual_recurring_roster_unavailable(a.basis_json->'normalSource',a.frame_start) IS DISTINCT FROM a.basis_json->'rosterUnavailableByDate'
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Actual recurring source/catalog/accepted facts/employment14/roster changed';END IF;
 SELECT * INTO stage_row FROM custodial_coverall.recurring_materialization_stages WHERE operation_id=p_operation;
 RETURN jsonb_build_object('schema','custodial.recurring-employment-native-sql-context.v1','kind','RECURRING_MANUAL_MATERIALIZATION',
  'operationId',p_operation,'managerId',p_manager,'publicationId',a.publication_id,'versionId',a.version_id,'sourceId',a.source_id,
  'frameStart',a.frame_start,'frameEnd',a.frame_start+6,'authorityRevision',a.authority_revision,'basis',a.basis_json,
  'stagedEnvelope',stage_row.envelope_json,'stagedLunch',stage_row.lunch_json,'candidateDigest',stage_row.candidate_digest);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_manual_recurring_projection_sink(p_publication_id uuid, p_service_date date, p_exception_set_digest text, p_compiler_version text, p_objective jsonb, p_metrics jsonb, p_replay_digest text, p_assignments jsonb, p_expected_revision bigint, p_actor_manager_id uuid, p_actor_manager_name text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_pending_validation jsonb; v_request jsonb; v_request_digest text; v_prior public.weekly_schedule_command_receipts%rowtype; v_publication public.weekly_schedule_publications%rowtype; v_effective_start date; v_effective_end date; v_exception_set jsonb; v_exception_digest text; v_command uuid:=gen_random_uuid(); v_projection uuid:=gen_random_uuid(); v_revision bigint; v_content_digest text; v_response jsonb; v_item jsonb; v_assignment public.weekly_schedule_slot_assignments%rowtype; v_owner public.v_weekly_roster_slot_incumbency_ranges%rowtype; v_occurrence uuid; v_work jsonb;
begin
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_actor_manager_id,p_actor_manager_name,p_idempotency_key,'materialize_projection'); v_request:=jsonb_build_object('operation','materialize_projection','publication_id',p_publication_id,'service_date',p_service_date,'exception_set_digest',p_exception_set_digest,'compiler_version',p_compiler_version,'objective',p_objective,'metrics',p_metrics,'replay_digest',p_replay_digest,'projection_envelope',p_assignments,'expected_revision',p_expected_revision,'actor_manager_id',p_actor_manager_id,'actor_manager_name',p_actor_manager_name); v_request_digest:=public.static_weekly_digest_jsonb(v_request); perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts where actor_manager_id=p_actor_manager_id and idempotency_key=p_idempotency_key; if found then if v_prior.request_digest<>v_request_digest then raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs'; end if; return v_prior.response_json; end if;
  select * into v_publication from public.weekly_schedule_publications where publication_id=p_publication_id; select effective_start,effective_end into v_effective_start,v_effective_end from public.v_weekly_schedule_effective_ranges where version_id=v_publication.version_id; if not found or v_publication.publication_id is null or p_service_date is null or public.static_weekly_effective_version(p_service_date) is distinct from v_publication.version_id or mod(p_service_date-v_effective_start,7)<>0 or (v_effective_end is not null and p_service_date+6>=v_effective_end) then raise exception using errcode='23514',message='projection must be an aligned complete seven-day horizon wholly within one effective publication'; end if;
  v_exception_set:=public.static_weekly_accepted_exception_set(p_publication_id,p_service_date); v_exception_digest:=public.static_weekly_digest_jsonb(v_exception_set); if p_exception_set_digest is distinct from v_exception_digest or p_compiler_version is distinct from p_assignments->>'compiler_version' or p_objective is distinct from p_assignments->'objective' or p_metrics is distinct from p_assignments->'metrics' or p_replay_digest is distinct from p_assignments->>'replay_digest' then raise exception using errcode='23514',message='projection command identity must include exact compiler, objective, metrics, replay, and weekly exception authority'; end if;
  v_pending_validation:=public.static_weekly_manual_recurring_assert_payload((p_assignments#>>'{semantic_snapshot,recurringOperation,operationId}')::uuid,p_actor_manager_id,p_assignments); if exists(select 1 from public.weekly_schedule_compiled_projections where publication_id=p_publication_id and week_start=p_service_date and exception_set_digest=v_exception_digest and compiler_version=p_compiler_version and authority_digest=p_assignments->>'authority_digest') then raise exception using errcode='23505',message='immutable projection already exists for this exact weekly authority'; end if;
  v_content_digest:=public.static_weekly_digest_jsonb(jsonb_build_object('publication_id',p_publication_id,'week_start',p_service_date,'exception_set_digest',v_exception_digest,'compiler_version',p_compiler_version,'objective',p_objective,'metrics',p_metrics,'replay_digest',p_replay_digest,'projection_envelope_identity',p_assignments->>'database_projection_identity','attestation',p_assignments->'attestation')); v_revision:=public.static_weekly_advance_authority(p_expected_revision,'materialize_projection',p_actor_manager_id,p_actor_manager_name,v_command,v_content_digest);
  insert into public.weekly_schedule_compiled_projections(projection_id,publication_id,version_id,week_start,week_end,exception_set_json,exception_set_digest,compiler_version,objective_json,metrics_json,replay_digest,authority_digest,receipt_json,projection_envelope,compiled_by_manager_id) values(v_projection,p_publication_id,v_publication.version_id,p_service_date,p_service_date+6,v_exception_set,v_exception_digest,p_compiler_version,p_objective,p_metrics,p_replay_digest,p_assignments->>'authority_digest',p_assignments->'receipt',p_assignments,p_actor_manager_id);
  for v_item in select value from jsonb_array_elements(p_assignments->'assignments') loop
    v_owner:=null; v_assignment:=null; v_work:=v_item->'work_snapshot'; 
 if p_assignments#>>'{authority,schema}'='custodial.approved-static-pending-staffing-authority.v1'
    and (v_work->>'overlayWork') is distinct from 'true' then
  select baseline.* into strict v_assignment
   from public.weekly_schedule_slot_assignments baseline
   join jsonb_array_elements(p_assignments#>'{authority,shiftEndDerivation,parentChains}') chain
    on baseline.work_id=chain->>'parentWorkId' and baseline.day_of_week=(chain->>'dayOfWeek')::smallint
   join lateral jsonb_array_elements(chain->'segments') segment on segment->>'workId'=v_item->>'work_id'
   where baseline.version_id=v_publication.version_id and baseline.day_of_week=(v_item->>'day_of_week')::smallint;
 else
  select * into v_assignment from public.weekly_schedule_slot_assignments where assignment_id=nullif(v_pending_validation#>>ARRAY['assignment_links',v_item->>'plan_work_id'],'')::uuid;
 end if;
  if v_assignment.assignment_id is null and not exists(select 1 from jsonb_array_elements(v_pending_validation->'projection_assignments') r where r=v_item) then raise exception using errcode='23514',message='pending work lacks independently checked original lineage';end if;
    perform public.static_weekly_capacity_assert_projection_owner(p_assignments,p_publication_id,v_item);
    if upper(v_item->>'status')='ASSIGNED' and v_item->>'owner_kind'='CONTRACTOR_CAPACITY' then
      v_owner:=null;
    elsif upper(v_item->>'status')='ASSIGNED' then select * into v_owner from public.v_weekly_roster_slot_incumbency_ranges where slot_id=(v_item->>'owner_slot_id')::uuid and effective_start<=(v_item->>'service_date')::date and (effective_end is null or (v_item->>'service_date')::date<effective_end); if not found or v_owner.person_id::text is distinct from v_item->>'owner_person_id' then raise exception using errcode='23514',message='projection assigned owner lacks an effective dated incumbent'; end if; elsif upper(v_item->>'status') not in ('OPEN','REVIEW') or v_item->>'owner_slot_id' is not null or v_item->>'owner_person_id' is not null then raise exception using errcode='23514',message='open and review projection rows must have null owner facts'; end if;
    insert into public.weekly_schedule_occurrences(projection_id,publication_id,version_id,assignment_id,service_date,work_id,day_of_week,location_id,location_code_snapshot,location_name_snapshot,coverage_start,coverage_end,owner_slot_id,owner_slot_label_snapshot,owner_person_id_snapshot,owner_name_snapshot,owner_kind,owner_capacity_id,state,state_reason,original_actor_person_id,original_actor_name_snapshot,authority_facts_json,occurrence_digest) values(v_projection,p_publication_id,v_publication.version_id,v_assignment.assignment_id,(v_item->>'service_date')::date,v_item->>'work_id',(v_item->>'day_of_week')::smallint,nullif(v_work->>'locationId','')::uuid,coalesce(v_work->>'locationCodeSnapshot',v_item->>'work_id'),coalesce(v_work->>'locationNameSnapshot',v_item->>'work_id'),(v_work#>>'{window,start}')::time,(v_work#>>'{window,end}')::time,case when lower(v_item->>'status')='assigned' then (v_item->>'owner_slot_id')::uuid else null end,case when lower(v_item->>'status')='assigned' then (select slot_label from public.weekly_roster_slots where slot_id=(v_item->>'owner_slot_id')::uuid) else null end,case when lower(v_item->>'status')='assigned' then (v_item->>'owner_person_id')::uuid else null end,case when lower(v_item->>'status')='assigned' then v_owner.person_name_snapshot else null end,nullif(v_item->>'owner_kind',''),nullif(v_item->>'capacity_id','')::uuid,case lower(v_item->>'status') when 'assigned' then 'created' when 'open' then 'open' else 'review' end,v_item->>'reason_code',nullif(v_item->>'original_actor_person_id','')::uuid,nullif(v_item->>'original_actor_name',''),jsonb_build_object('baseline_owner_slot_id',v_item->>'baseline_owner_slot_id','baseline_owner_person_id',v_item->>'baseline_owner_person_id','baseline_owner_name',v_item->>'baseline_owner_name','original_actor_person_id',v_item->>'original_actor_person_id','original_actor_name',v_item->>'original_actor_name','optimized_owner_slot_id',v_item->>'optimized_owner_slot_id','optimized_owner_person_id',v_item->>'optimized_owner_person_id','actual_actor_person_id',v_item->>'actual_actor_person_id','work_snapshot',v_work)||case when v_item->>'owner_kind'='CONTRACTOR_CAPACITY' then jsonb_build_object('owner_kind','CONTRACTOR_CAPACITY','capacity_id',v_item->>'capacity_id') else '{}'::jsonb end,public.static_weekly_digest_jsonb(v_item)) returning occurrence_id into v_occurrence;
    insert into public.weekly_schedule_projection_assignments(projection_id,occurrence_id,work_id,status,reason_code,owner_slot_id,owner_slot_label_snapshot,owner_person_id_snapshot,owner_name_snapshot,owner_kind,owner_capacity_id,authority_facts_json,explanation_json,content_digest) values(v_projection,v_occurrence,v_item->>'work_id',lower(v_item->>'status'),v_item->>'reason_code',case when lower(v_item->>'status')='assigned' then (v_item->>'owner_slot_id')::uuid else null end,case when lower(v_item->>'status')='assigned' then (select slot_label from public.weekly_roster_slots where slot_id=(v_item->>'owner_slot_id')::uuid) else null end,case when lower(v_item->>'status')='assigned' then (v_item->>'owner_person_id')::uuid else null end,case when lower(v_item->>'status')='assigned' then v_owner.person_name_snapshot else null end,nullif(v_item->>'owner_kind',''),nullif(v_item->>'capacity_id','')::uuid,(select authority_facts_json from public.weekly_schedule_occurrences where occurrence_id=v_occurrence),coalesce(v_item->'explanation','{}'::jsonb),public.static_weekly_digest_jsonb(v_item));
  end loop;
  v_response:=public.static_weekly_response_json('materialize_projection',v_revision,v_content_digest,v_request_digest,jsonb_build_object('projection_id',v_projection,'publication_id',p_publication_id,'week_start',p_service_date,'week_end',p_service_date+6,'replay_digest',p_replay_digest)); insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest) values(v_command,p_actor_manager_id,p_actor_manager_name,'materialize_projection',p_idempotency_key,p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest); return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_manual_repeat_components(p_source uuid, p_frame date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE origin date;snapshot text;projection jsonb;lunch jsonb;rows jsonb;availability jsonb;
 loans jsonb;responsibilities jsonb;intents jsonb;loan_keys jsonb;authority jsonb;input jsonb;overlay_input jsonb;
 authority_digest text;input_digest text;replay_digest text;source_projection text;source_lunch text;
BEGIN
 SELECT b.effective_start,b.snapshot_digest,b.feasibility#>'{initialBaseline,projection}',b.feasibility->'lunchDocument'
  INTO STRICT origin,snapshot,projection,lunch FROM public.static_weekly_approved_initial_baselines b WHERE source_id=p_source;
 IF p_frame IS NULL OR NOT isfinite(p_frame) OR p_frame<=origin OR mod(p_frame-origin,7)<>0
  OR projection->>'week_start' IS DISTINCT FROM origin::text OR lunch->>'week_start' IS DISTINCT FROM origin::text
  OR jsonb_array_length(projection->'assignments')<>346 OR jsonb_array_length(lunch->'loans')<>40
  OR projection#>>'{authority,compilerInput,version,manualGroupRatingAuthority,manifestSha256}' IS DISTINCT FROM 'fe02bbdebc736d95360b55cc7dfe5b73c5a9eaa76f364f1c0f4420a0afb9950f'
 THEN RAISE EXCEPTION 'Exact later publication-aligned normal period required'; END IF;
 source_projection:=projection->>'database_projection_identity';source_lunch:=lunch->>'document_identity';
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(projection->'assignments') r WHERE
  (r->>'service_date')::date<>origin+mod((r->>'day_of_week')::integer-extract(dow FROM origin)::integer+7,7)
  OR r->>'status'<>'assigned') THEN RAISE EXCEPTION 'Original normal assignment dates/status differ'; END IF;
 SELECT jsonb_agg(r||jsonb_build_object('service_date',d::text,
  'owner_digest',public.static_weekly_digest_jsonb(jsonb_build_object('planWorkId',r->'plan_work_id','slotId',r->'owner_slot_id','personId',r->'owner_person_id','serviceDate',d::text)),
  'exact_owner_identity',public.static_weekly_digest_jsonb(jsonb_build_object('plan_work_id',r->'plan_work_id','service_date',d::text,
   'optimized_owner_slot_id',r->'owner_slot_id','optimized_owner_person_id',r->'owner_person_id',
   'baseline_owner_slot_id',r->'baseline_owner_slot_id','baseline_owner_person_id',r->'baseline_owner_person_id'))) ORDER BY n) INTO rows
 FROM jsonb_array_elements(projection->'assignments') WITH ORDINALITY x(r,n)
 CROSS JOIN LATERAL(SELECT p_frame+mod((r->>'day_of_week')::integer-extract(dow FROM p_frame)::integer+7,7) d) dates;
 SELECT jsonb_agg(r||jsonb_build_object('serviceDate',(p_frame+mod((r->>'dayOfWeek')::integer-extract(dow FROM p_frame)::integer+7,7))::text) ORDER BY n)
 INTO availability FROM jsonb_array_elements(projection#>'{authority,projectionAvailability}') WITH ORDINALITY x(r,n);
 input:=jsonb_set(projection#>'{authority,compilerInput}','{serviceDate}',to_jsonb(p_frame::text),false);
 overlay_input:=jsonb_set(projection#>'{authority,overlayCompilerInput}','{serviceDate}',to_jsonb(p_frame::text),false);
 input_digest:=public.static_weekly_digest_jsonb(overlay_input);
 -- EXACT existing manual/native lunch key language (canonical JSON, no spaces).
 SELECT jsonb_object_agg(r->>'loan_id',public.static_weekly_digest_text(public.static_weekly_manual_identity_json(jsonb_build_object(
  'policy','owner-20260921-two-nearby-full-hour-v1','input',input_digest,
  'serviceDate',(p_frame+mod((r->>'day_of_week')::integer-extract(dow FROM p_frame)::integer+7,7))::text,
  'ownerSlotId',r->'normal_owner_slot_id','start',r->'coverage_start','end',r->'coverage_end')))) INTO loan_keys
 FROM jsonb_array_elements(lunch->'loans') r;
 SELECT jsonb_agg(r||jsonb_build_object('loan_id',loan_keys->>(r->>'loan_id'),
  'service_date',(p_frame+mod((r->>'day_of_week')::integer-extract(dow FROM p_frame)::integer+7,7))::text) ORDER BY n)
 INTO loans FROM jsonb_array_elements(lunch->'loans') WITH ORDINALITY x(r,n);
 SELECT jsonb_agg(r||jsonb_build_object('responsibility_id',public.static_weekly_digest_text(public.static_weekly_manual_identity_json(jsonb_build_object(
  'loanId',loan_keys->>(r->>'loan_id'),'areaId',physical_area.area_id,'covererSlotId',r->'coverer_slot_id'))),
  'loan_id',loan_keys->>(r->>'loan_id'),
  'service_date',(p_frame+mod((r->>'day_of_week')::integer-extract(dow FROM p_frame)::integer+7,7))::text) ORDER BY n)
 INTO responsibilities FROM jsonb_array_elements(lunch->'responsibilities') WITH ORDINALITY x(r,n)
 CROSS JOIN LATERAL(SELECT public.static_weekly_digest_text(public.static_weekly_manual_identity_json(jsonb_agg(jsonb_build_object(
  'work',segment->'planWorkId','start',extract(epoch FROM (segment#>>'{normalWindow,start}')::time)::integer/60,
  'end',extract(epoch FROM (segment#>>'{normalWindow,end}')::time)::integer/60) ORDER BY segment->>'planWorkId' COLLATE "C"))) area_id
 FROM jsonb_array_elements(r->'segments') seg(segment)) physical_area;
 SELECT jsonb_agg(r||jsonb_build_object('notification_key',public.static_weekly_digest_text(public.static_weekly_manual_identity_json(jsonb_build_object(
  'loanId',loan_keys->>(r->>'loan_id'),'slot',r->'coverer_slot_id','event',r->'event'))),
  'loan_id',loan_keys->>(r->>'loan_id'),'service_date',((r->>'service_date')::date+(p_frame-origin))::text) ORDER BY n)
 INTO intents FROM jsonb_array_elements(lunch->'notification_intents') WITH ORDINALITY x(r,n);
 authority:=((projection->'authority')-ARRAY['lunchIdentityRetention','derivedBaselineDigest','basisDigest','witnessDigest','shiftEndDerivation','mapping'])||jsonb_build_object('effectiveDate',p_frame::text,'compilerInput',input,'overlayCompilerInput',overlay_input,
  'projectionAvailability',availability,'inputDigest',input_digest,'overlayInputDigest',input_digest,'baselineInputDigest',public.static_weekly_digest_jsonb(input),
  'repeatReference',jsonb_build_object('schema','custodial.approved-manual-fixed-period-reference.v1','sourceId',p_source,
   'origin',origin::text,'frameStart',p_frame::text,'baselineSnapshotDigest',snapshot,'originalProjectionIdentity',source_projection,
   'originalLunchIdentity',source_lunch,'originalFixedEvidence',jsonb_build_object('derivedBaselineDigest',projection#>'{authority,derivedBaselineDigest}','basisDigest',projection#>'{authority,basisDigest}','witnessDigest',projection#>'{authority,witnessDigest}','shiftEndDerivation',projection#>'{authority,shiftEndDerivation}','mapping',projection#>'{authority,mapping}'),'witnessMeaning','UNCHANGED_ADMITTED_PATTERN_TRANSLATED_BY_WHOLE_SEVEN_DAY_PERIODS'));
 authority_digest:=public.static_weekly_digest_jsonb(authority);
 -- The exact native replay is bound AFTER the complete fresh lunch body below.
 replay_digest:=NULL;
 projection:=projection-'database_projection_identity';
 projection:=projection||jsonb_build_object('adapter',jsonb_build_object('schema','custodial.approved-manual-recurring-reference-adapter.v1','version','approved-manual-repeat-v1'),
  'service_date',p_frame::text,'week_start',p_frame::text,'week_end',(p_frame+6)::text,'authority',authority,'authority_digest',authority_digest,
  'compiler_version','approved-manual-repeat-v1','replay_digest',replay_digest,'assignments',rows,'applied_exceptions','[]'::jsonb,
  'receipt',jsonb_build_object('schema','custodial.approved-manual-recurring-reference-data.v1','baselineSnapshotDigest',snapshot,
   'originalProjectionIdentity',source_projection,'solverInvoked',false,'newOptimizerOrI1Receipt',false),
  'semantic_snapshot',jsonb_build_object('schema','custodial.approved-manual-recurring-reference-snapshot.v1','sourceId',p_source,
   'origin',origin::text,'frameStart',p_frame::text,'baselineSnapshotDigest',snapshot,'originalProjectionIdentity',source_projection));
 lunch:=lunch-'document_identity';
 lunch:=lunch||jsonb_build_object('week_start',p_frame::text,'base_authority_digest',authority_digest,'base_replay_digest',replay_digest,
  'source_input_digest',input_digest,'candidate_digest',public.static_weekly_digest_jsonb(jsonb_build_object('schema','custodial.approved-manual-repeat-lunch-data.v1','source_input_digest',input_digest,'loans',loans,'responsibilities',responsibilities,'notification_intents',intents)),
  'loans',loans,'responsibilities',responsibilities,'notification_intents',intents,
  'semantic_snapshot',jsonb_build_object('schema','memphis-zoo.static-weekly-lunch-semantic-snapshot.v1',
   'loans_digest',public.static_weekly_digest_jsonb(loans),'responsibilities_digest',public.static_weekly_digest_jsonb(responsibilities),
   'notification_intents_digest',public.static_weekly_digest_jsonb(intents)));
 lunch:=lunch-ARRAY['base_authority_digest','base_replay_digest','document_identity'];
 replay_digest:=public.static_weekly_digest_jsonb(jsonb_build_object('projectionAssignments',rows,'lunchDocument',lunch));
 lunch:=lunch||jsonb_build_object('base_authority_digest',authority_digest,'base_replay_digest',replay_digest);
 lunch:=lunch||jsonb_build_object('document_identity',public.static_weekly_digest_jsonb(lunch));
 projection:=(projection-'database_projection_identity')||jsonb_build_object('replay_digest',replay_digest);
 projection:=projection||jsonb_build_object('database_projection_identity',public.static_weekly_digest_jsonb(projection));
 RETURN jsonb_build_object('projection',projection,'lunchDocument',lunch);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_manual_repeat_materialize_projection(p_publication_id uuid, p_service_date date, p_exception_set_digest text, p_compiler_version text, p_objective jsonb, p_metrics jsonb, p_replay_digest text, p_assignments jsonb, p_expected_revision bigint, p_actor_manager_id uuid, p_actor_manager_name text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_request jsonb; v_request_digest text; v_prior public.weekly_schedule_command_receipts%rowtype; v_publication public.weekly_schedule_publications%rowtype; v_effective_start date; v_effective_end date; v_exception_set jsonb; v_exception_digest text; v_command uuid:=gen_random_uuid(); v_projection uuid:=gen_random_uuid(); v_revision bigint; v_content_digest text; v_response jsonb; v_item jsonb; v_assignment public.weekly_schedule_slot_assignments%rowtype; v_owner public.v_weekly_roster_slot_incumbency_ranges%rowtype; v_occurrence uuid; v_work jsonb;
begin
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_actor_manager_id,p_actor_manager_name,p_idempotency_key,'materialize_projection'); v_request:=jsonb_build_object('operation','materialize_projection','publication_id',p_publication_id,'service_date',p_service_date,'exception_set_digest',p_exception_set_digest,'compiler_version',p_compiler_version,'objective',p_objective,'metrics',p_metrics,'replay_digest',p_replay_digest,'projection_envelope',p_assignments,'expected_revision',p_expected_revision,'actor_manager_id',p_actor_manager_id,'actor_manager_name',p_actor_manager_name); v_request_digest:=public.static_weekly_digest_jsonb(v_request); perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts where actor_manager_id=p_actor_manager_id and idempotency_key=p_idempotency_key; if found then if v_prior.request_digest<>v_request_digest then raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs'; end if; return v_prior.response_json; end if;
  select * into v_publication from public.weekly_schedule_publications where publication_id=p_publication_id; select effective_start,effective_end into v_effective_start,v_effective_end from public.v_weekly_schedule_effective_ranges where version_id=v_publication.version_id; if not found or v_publication.publication_id is null or p_service_date is null or public.static_weekly_effective_version(p_service_date) is distinct from v_publication.version_id or mod(p_service_date-v_effective_start,7)<>0 or (v_effective_end is not null and p_service_date+6>=v_effective_end) then raise exception using errcode='23514',message='projection must be an aligned complete seven-day horizon wholly within one effective publication'; end if;
  v_exception_set:=public.static_weekly_accepted_exception_set(p_publication_id,p_service_date); v_exception_digest:=public.static_weekly_digest_jsonb(v_exception_set); if p_exception_set_digest is distinct from v_exception_digest or p_compiler_version is distinct from p_assignments->>'compiler_version' or p_objective is distinct from p_assignments->'objective' or p_metrics is distinct from p_assignments->'metrics' or p_replay_digest is distinct from p_assignments->>'replay_digest' then raise exception using errcode='23514',message='projection command identity must include exact compiler, objective, metrics, replay, and weekly exception authority'; end if;
  perform public.static_weekly_assert_manual_repeat_projection(p_assignments,p_publication_id,p_service_date,v_exception_set); if exists(select 1 from public.weekly_schedule_compiled_projections where publication_id=p_publication_id and week_start=p_service_date and exception_set_digest=v_exception_digest and compiler_version=p_compiler_version and authority_digest=p_assignments->>'authority_digest') then raise exception using errcode='23505',message='immutable projection already exists for this exact weekly authority'; end if;
  v_content_digest:=public.static_weekly_digest_jsonb(jsonb_build_object('publication_id',p_publication_id,'week_start',p_service_date,'exception_set_digest',v_exception_digest,'compiler_version',p_compiler_version,'objective',p_objective,'metrics',p_metrics,'replay_digest',p_replay_digest,'projection_envelope_identity',p_assignments->>'database_projection_identity','attestation',p_assignments->'attestation')); v_revision:=public.static_weekly_advance_authority(p_expected_revision,'materialize_projection',p_actor_manager_id,p_actor_manager_name,v_command,v_content_digest);
  insert into public.weekly_schedule_compiled_projections(projection_id,publication_id,version_id,week_start,week_end,exception_set_json,exception_set_digest,compiler_version,objective_json,metrics_json,replay_digest,authority_digest,receipt_json,projection_envelope,compiled_by_manager_id) values(v_projection,p_publication_id,v_publication.version_id,p_service_date,p_service_date+6,v_exception_set,v_exception_digest,p_compiler_version,p_objective,p_metrics,p_replay_digest,p_assignments->>'authority_digest',p_assignments->'receipt',p_assignments,p_actor_manager_id);
  for v_item in select value from jsonb_array_elements(p_assignments->'assignments') loop
    v_owner:=null; v_assignment:=null; v_work:=v_item->'work_snapshot'; 
 if p_assignments#>>'{authority,schema}'='custodial.approved-static-authority.v1'
    and jsonb_typeof(p_assignments#>'{authority,shiftEndDerivation}')='object'
    and (v_work->>'overlayWork') is distinct from 'true' then
  select baseline.* into strict v_assignment
   from public.weekly_schedule_slot_assignments baseline
   join jsonb_array_elements(p_assignments#>'{authority,shiftEndDerivation,parentChains}') chain
    on baseline.work_id=chain->>'parentWorkId' and baseline.day_of_week=(chain->>'dayOfWeek')::smallint
   join lateral jsonb_array_elements(chain->'segments') segment on segment->>'workId'=v_item->>'work_id'
   where baseline.version_id=v_publication.version_id and baseline.day_of_week=(v_item->>'day_of_week')::smallint;
 else
  select * into v_assignment from public.weekly_schedule_slot_assignments
   where version_id=v_publication.version_id and day_of_week=(v_item->>'day_of_week')::smallint and work_id=v_item->>'work_id';
 end if;
  if v_assignment.assignment_id is null and (v_work->>'overlayWork') is distinct from 'true' then raise exception using errcode='23514',message='active baseline work must retain its stored baseline assignment link'; end if;
    perform public.static_weekly_capacity_assert_projection_owner(p_assignments,p_publication_id,v_item);
    if upper(v_item->>'status')='ASSIGNED' and v_item->>'owner_kind'='CONTRACTOR_CAPACITY' then
      v_owner:=null;
    elsif upper(v_item->>'status')='ASSIGNED' then select * into v_owner from public.v_weekly_roster_slot_incumbency_ranges where slot_id=(v_item->>'owner_slot_id')::uuid and effective_start<=(v_item->>'service_date')::date and (effective_end is null or (v_item->>'service_date')::date<effective_end); if not found or v_owner.person_id::text is distinct from v_item->>'owner_person_id' then raise exception using errcode='23514',message='projection assigned owner lacks an effective dated incumbent'; end if; elsif upper(v_item->>'status') not in ('OPEN','REVIEW') or v_item->>'owner_slot_id' is not null or v_item->>'owner_person_id' is not null then raise exception using errcode='23514',message='open and review projection rows must have null owner facts'; end if;
    insert into public.weekly_schedule_occurrences(projection_id,publication_id,version_id,assignment_id,service_date,work_id,day_of_week,location_id,location_code_snapshot,location_name_snapshot,coverage_start,coverage_end,owner_slot_id,owner_slot_label_snapshot,owner_person_id_snapshot,owner_name_snapshot,owner_kind,owner_capacity_id,state,state_reason,original_actor_person_id,original_actor_name_snapshot,authority_facts_json,occurrence_digest) values(v_projection,p_publication_id,v_publication.version_id,v_assignment.assignment_id,(v_item->>'service_date')::date,v_item->>'work_id',(v_item->>'day_of_week')::smallint,nullif(v_work->>'locationId','')::uuid,coalesce(v_work->>'locationCodeSnapshot',v_item->>'work_id'),coalesce(v_work->>'locationNameSnapshot',v_item->>'work_id'),(v_work#>>'{window,start}')::time,(v_work#>>'{window,end}')::time,case when lower(v_item->>'status')='assigned' then (v_item->>'owner_slot_id')::uuid else null end,case when lower(v_item->>'status')='assigned' then (select slot_label from public.weekly_roster_slots where slot_id=(v_item->>'owner_slot_id')::uuid) else null end,case when lower(v_item->>'status')='assigned' then (v_item->>'owner_person_id')::uuid else null end,case when lower(v_item->>'status')='assigned' then v_owner.person_name_snapshot else null end,nullif(v_item->>'owner_kind',''),nullif(v_item->>'capacity_id','')::uuid,case lower(v_item->>'status') when 'assigned' then 'created' when 'open' then 'open' else 'review' end,v_item->>'reason_code',nullif(v_item->>'original_actor_person_id','')::uuid,nullif(v_item->>'original_actor_name',''),jsonb_build_object('baseline_owner_slot_id',v_item->>'baseline_owner_slot_id','baseline_owner_person_id',v_item->>'baseline_owner_person_id','baseline_owner_name',v_item->>'baseline_owner_name','original_actor_person_id',v_item->>'original_actor_person_id','original_actor_name',v_item->>'original_actor_name','optimized_owner_slot_id',v_item->>'optimized_owner_slot_id','optimized_owner_person_id',v_item->>'optimized_owner_person_id','actual_actor_person_id',v_item->>'actual_actor_person_id','work_snapshot',v_work)||case when v_item->>'owner_kind'='CONTRACTOR_CAPACITY' then jsonb_build_object('owner_kind','CONTRACTOR_CAPACITY','capacity_id',v_item->>'capacity_id') else '{}'::jsonb end,public.static_weekly_digest_jsonb(v_item)) returning occurrence_id into v_occurrence;
    insert into public.weekly_schedule_projection_assignments(projection_id,occurrence_id,work_id,status,reason_code,owner_slot_id,owner_slot_label_snapshot,owner_person_id_snapshot,owner_name_snapshot,owner_kind,owner_capacity_id,authority_facts_json,explanation_json,content_digest) values(v_projection,v_occurrence,v_item->>'work_id',lower(v_item->>'status'),v_item->>'reason_code',case when lower(v_item->>'status')='assigned' then (v_item->>'owner_slot_id')::uuid else null end,case when lower(v_item->>'status')='assigned' then (select slot_label from public.weekly_roster_slots where slot_id=(v_item->>'owner_slot_id')::uuid) else null end,case when lower(v_item->>'status')='assigned' then (v_item->>'owner_person_id')::uuid else null end,case when lower(v_item->>'status')='assigned' then v_owner.person_name_snapshot else null end,nullif(v_item->>'owner_kind',''),nullif(v_item->>'capacity_id','')::uuid,(select authority_facts_json from public.weekly_schedule_occurrences where occurrence_id=v_occurrence),coalesce(v_item->'explanation','{}'::jsonb),public.static_weekly_digest_jsonb(v_item));
  end loop;
  v_response:=public.static_weekly_response_json('materialize_projection',v_revision,v_content_digest,v_request_digest,jsonb_build_object('projection_id',v_projection,'publication_id',p_publication_id,'week_start',p_service_date,'week_end',p_service_date+6,'replay_digest',p_replay_digest)); insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest) values(v_command,p_actor_manager_id,p_actor_manager_name,'materialize_projection',p_idempotency_key,p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest); return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_materialize_approved_initial_baseline(p_manager_id uuid, p_source_id uuid, p_date date, p_revision bigint, p_generation bigint, p_key text, p_envelope jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare actor jsonb;basis jsonb;baseline public.static_weekly_approved_initial_baselines%rowtype;prior public.static_weekly_approved_initial_confirmations%rowtype;
 document jsonb;projection jsonb;draft jsonb;published jsonb;materialized jsonb;lunch jsonb;receipt jsonb;provenance jsonb;
 lunch_document jsonb;feasibility_digest text;reference_mode boolean:=false;
 v_version_id uuid;v_publication_id uuid;v_projection_id uuid;revision bigint;kind text;
begin
 perform public.static_weekly_v3_assert_control_plane();perform public.custodial_begin_application_mutation();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 actor:=public.static_weekly_v3_manager_actor(p_manager_id);
 if p_key is null or length(btrim(p_key)) not between 1 and 150 then raise exception 'exact initial idempotency key required';end if;
 select * into prior from public.static_weekly_approved_initial_confirmations where manager_id=p_manager_id and idempotency_key=p_key;
 if found then
  if prior.request_json is distinct from p_envelope->'request' then raise exception using errcode='23505',message='initial confirmation identity conflict';end if;
  return prior.receipt_json;end if;
 basis:=public.static_weekly_read_approved_initial_basis(p_manager_id,p_source_id,p_date,p_revision,p_envelope#>>'{request,templateId}');
 select * into strict baseline from public.static_weekly_approved_initial_baselines where source_id=p_source_id;
 if p_envelope->>'schema'='custodial.approved-static-initial-materialization.compact.v1' then
  perform public.static_weekly_assert_exact_object(p_envelope,
   array['schema','managerId','sourceId','effectiveStart','expectedRevision','generation','templateCatalogDigest','feasibilityDigest','previewDigest','request'],
   array['schema','managerId','sourceId','effectiveStart','expectedRevision','generation','templateCatalogDigest','feasibilityDigest','previewDigest','request'],
   'compact initial confirmation');
  if p_envelope->>'feasibilityDigest' is distinct from baseline.feasibility->>'digest' then
   raise exception using errcode='23514',message='compact initial confirmation snapshot digest changed';end if;
  -- The basis above verifies the immutable snapshot and its catalog/source.
  -- Reconstruct the SAME full v1 envelope; its original preview digest, full
  -- feasibility equality, actor, revision, generation and request checks below
  -- remain the admission boundary for both old and compact callers.
  p_envelope:=(p_envelope-'feasibilityDigest')||jsonb_build_object(
   'schema','custodial.approved-static-initial-materialization.v1','feasibility',baseline.feasibility);
 end if;

 if p_envelope->>'schema'='custodial.approved-static-initial-materialization.reference.v1' then
  perform public.static_weekly_assert_exact_object(p_envelope,
   array['schema','managerId','sourceId','effectiveStart','expectedRevision','generation','templateCatalogDigest','feasibilityDigest','baselineSnapshotDigest','previewDigest','request'],
   array['schema','managerId','sourceId','effectiveStart','expectedRevision','generation','templateCatalogDigest','feasibilityDigest','baselineSnapshotDigest','previewDigest','request'],
   'manual initial snapshot reference');
  if baseline.feasibility#>>'{candidateSource,version,manualGroupRatingAuthority,manifestSha256}' is distinct from 'fe02bbdebc736d95360b55cc7dfe5b73c5a9eaa76f364f1c0f4420a0afb9950f'
   or p_envelope->>'feasibilityDigest' is distinct from baseline.feasibility->>'digest'
   or p_envelope->>'baselineSnapshotDigest' is distinct from baseline.snapshot_digest then
   raise exception using errcode='23514',message='manual initial snapshot reference changed';end if;
  -- The basis has independently rehashed the complete immutable snapshot and
  -- checked its fresh source/catalog. Bind that exact snapshot by its full
  -- identity instead of allocating a second full feasibility envelope.
  if p_envelope->>'previewDigest' is distinct from public.static_weekly_digest_jsonb(p_envelope-array['request','previewDigest']) then
   raise exception using errcode='23514',message='manual initial snapshot reference preview changed';end if;
  reference_mode:=true;
 end if;
 if (not reference_mode and p_envelope->>'schema' is distinct from 'custodial.approved-static-initial-materialization.v1')
  or p_envelope->>'managerId' is distinct from p_manager_id::text or p_envelope->>'sourceId' is distinct from p_source_id::text
  or p_envelope->>'effectiveStart' is distinct from p_date::text or p_envelope->'expectedRevision' is distinct from to_jsonb(p_revision)
  or p_generation is distinct from (basis->>'generation')::bigint or p_envelope->'generation' is distinct from to_jsonb(p_generation)
  or p_envelope->>'templateCatalogDigest' is distinct from basis->>'templateCatalogDigest'
  or p_envelope->'request' is distinct from jsonb_build_object('sourceId',p_source_id,'effectiveStart',p_date,
    'templateId',baseline.template_id,'expectedRevision',p_revision,'previewDigest',p_envelope->>'previewDigest','idempotencyKey',p_key) then
  raise exception using errcode='23514',message='initial baseline must bind exact current source/catalog/actor/revision/generation and independently prepared fixed snapshot';end if;
 -- Release each hash/equality temporary before constructing another.
 if not reference_mode then
  if p_envelope->'feasibility' is distinct from baseline.feasibility then
   raise exception using errcode='23514',message='initial baseline fixed snapshot changed';end if;
  if p_envelope->>'previewDigest' is distinct from public.static_weekly_digest_jsonb(p_envelope-array['request','previewDigest']) then
   raise exception using errcode='23514',message='initial baseline full preview identity changed';end if;
 end if;
 p_envelope:=p_envelope-'feasibility';basis:=null;
 document:=baseline.feasibility#>'{initialBaseline,document}';projection:=baseline.feasibility#>'{initialBaseline,projection}';
 lunch_document:=baseline.feasibility->'lunchDocument';feasibility_digest:=baseline.feasibility->>'digest';
 baseline.feasibility:=null;
 provenance:=jsonb_build_object('adapter_schema',document#>>'{adapter,schema}','compiler_version',document#>>'{validation,compiler_version}',
  'input_digest',document#>>'{validation,input_digest}','baseline_input_digest',document#>>'{validation,baseline_input_digest}',
  'authority_digest',document#>>'{validation,authority_digest}','replay_digest',document#>>'{validation,replay_digest}');
 draft:=public.static_weekly_approved_initial_create_draft(p_date,projection->>'compiler_version',projection->'objective',provenance,
  document,p_revision,p_manager_id,actor->>'manager_name',p_key||':draft');
 document:=null;
 v_version_id:=(draft#>>'{data,version_id}')::uuid;revision:=(draft->>'revision')::bigint;
 perform set_config('app.static_weekly_source_bind','on',true);
 update public.weekly_schedule_versions set authority_source_id=p_source_id where version_id=v_version_id and authority_source_id is null;
 if not exists(select 1 from public.weekly_schedule_versions v where v.version_id=v_version_id and v.authority_source_id=p_source_id) then raise exception 'initial source identity was not retained';end if;
 perform public.static_weekly_v3_assert_draft_incumbency(v_version_id);
 kind:=case when exists(select 1 from public.weekly_schedule_publications) then 'supersede' else 'publish' end;
 published:=public.static_weekly_approved_initial_publish_draft(v_version_id,(draft#>>'{data,draft_revision}')::bigint,revision,
  p_manager_id,actor->>'manager_name',p_key||':publish',kind,null);
 v_publication_id:=(published#>>'{data,publication_id}')::uuid;revision:=(published->>'revision')::bigint;
 materialized:=public.static_weekly_approved_initial_materialize_projection(v_publication_id,p_date,public.static_weekly_digest_jsonb('[]'::jsonb),
  projection->>'compiler_version',projection->'objective',projection->'metrics',projection->>'replay_digest',projection,revision,
  p_manager_id,actor->>'manager_name',p_key||':projection');
 projection:=null;
 v_projection_id:=(materialized#>>'{data,projection_id}')::uuid;revision:=(materialized->>'revision')::bigint;
 lunch:=public.static_weekly_v8_materialize_lunch_document(v_projection_id,lunch_document,p_manager_id);
 if lunch->>'persistence_status' is distinct from 'PERSISTED' then raise exception 'initial lunch not persisted';end if;
 receipt:=jsonb_build_object('schema','custodial.approved-static-initial-confirmation.v1','status','PERSISTED_CURRENT',
  'ok',true,'persistence_status','PERSISTED','source_id',p_source_id,'publication_id',v_publication_id,'projection_id',v_projection_id,
  'authority_revision',revision,'revision',revision,'feasibility_digest',feasibility_digest,
  'lunch_document_identity',lunch->>'document_identity','previewDigest',p_envelope->>'previewDigest','solverInvoked',false);
 insert into public.static_weekly_approved_initial_confirmations values(p_manager_id,p_key,p_envelope->'request',receipt,v_publication_id,v_projection_id);
 return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_materialize_document(p_version_id uuid, p_document jsonb, p_content_digest text, p_actor_manager_id uuid, p_actor_manager_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  perform set_config('app.static_weekly_draft_write','on',true);
  delete from public.weekly_schedule_slot_assignments where version_id=p_version_id;
  delete from public.weekly_schedule_slot_availability where version_id=p_version_id;
  delete from public.weekly_schedule_objective_inputs where version_id=p_version_id;
  insert into public.weekly_schedule_slot_availability(version_id,slot_id,day_of_week,availability_state,shift_start,shift_end,lunch_start,lunch_end,capacity_units,max_load_points,qualification_snapshot,qualification_provenance,restriction_snapshot,restriction_provenance,slot_label_snapshot,incumbent_person_id_snapshot,incumbent_name_snapshot,content_digest)
  select p_version_id,x.slot_id,x.day_of_week,x.availability_state,x.shift_start,x.shift_end,x.lunch_start,x.lunch_end,x.capacity_units,x.max_load_points,x.qualification_snapshot,x.qualification_provenance,x.restriction_snapshot,x.restriction_provenance,x.slot_label_snapshot,x.incumbent_person_id_snapshot,x.incumbent_name_snapshot,p_content_digest
  from jsonb_to_recordset(p_document->'slot_availability') x(slot_id uuid,day_of_week smallint,availability_state text,shift_start time,shift_end time,lunch_start time,lunch_end time,capacity_units numeric,max_load_points numeric,qualification_snapshot jsonb,qualification_provenance jsonb,restriction_snapshot jsonb,restriction_provenance jsonb,slot_label_snapshot text,incumbent_person_id_snapshot uuid,incumbent_name_snapshot text);
  insert into public.weekly_schedule_slot_assignments(version_id,work_id,day_of_week,status,location_id,location_code_snapshot,location_name_snapshot,coverage_start,coverage_end,owner_slot_id,owner_slot_label_snapshot,owner_person_id_snapshot,owner_name_snapshot,required_qualifications_snapshot,restriction_snapshot,workload_points,workload_provenance,manual_lock,payload_json,authority_facts_json,content_digest)
  select p_version_id,x.work_id,x.day_of_week,lower(x.status),x.location_id,x.location_code_snapshot,x.location_name_snapshot,x.coverage_start,x.coverage_end,x.owner_slot_id,x.owner_slot_label_snapshot,x.owner_person_id_snapshot,x.owner_name_snapshot,x.required_qualifications_snapshot,x.restriction_snapshot,x.workload_points,x.workload_provenance,x.manual_lock,x.payload_json,x.payload_json->'authority_facts',p_content_digest
  from jsonb_to_recordset(p_document->'assignments') x(work_id text,day_of_week smallint,status text,location_id uuid,location_code_snapshot text,location_name_snapshot text,coverage_start time,coverage_end time,owner_slot_id uuid,owner_slot_label_snapshot text,owner_person_id_snapshot uuid,owner_name_snapshot text,required_qualifications_snapshot jsonb,restriction_snapshot jsonb,workload_points numeric,workload_provenance jsonb,manual_lock boolean,payload_json jsonb);
  insert into public.weekly_schedule_objective_inputs(version_id,input_key,input_value,provenance,content_digest,captured_by_manager_id,captured_by_manager_name_snapshot)
  select p_version_id,x.input_key,x.input_value,x.provenance,p_content_digest,p_actor_manager_id,p_actor_manager_name
  from jsonb_to_recordset(p_document->'objective_inputs') x(input_key text,input_value jsonb,provenance jsonb);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_materialize_manual_repeat(p_reference jsonb, p_reference_digest text, p_credential uuid, p_device text, p_access text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE manager uuid;publication uuid;request uuid;frame date;revision bigint;basis jsonb;expected jsonb;vector jsonb;reasons jsonb;
 actor jsonb;components jsonb;projection jsonb;materialized jsonb;lunch jsonb;receipt jsonb;prior record;employee jsonb;v_day jsonb;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();
 IF p_reference IS NULL OR pg_column_size(p_reference)>32768 THEN RAISE EXCEPTION 'Bounded compact normal period reference required'; END IF;
 PERFORM public.static_weekly_assert_exact_object(p_reference,
  ARRAY['schema','managerId','requestId','sourceId','publicationId','versionId','origin','frameStart','frameEnd','expectedRevision','generation','baselineSnapshotDigest','catalogEntryDigest','sourceProjectionIdentity','sourceLunchIdentity','employmentRevisionVector','exceptionSetDigest'],
  ARRAY['schema','managerId','requestId','sourceId','publicationId','versionId','origin','frameStart','frameEnd','expectedRevision','generation','baselineSnapshotDigest','catalogEntryDigest','sourceProjectionIdentity','sourceLunchIdentity','employmentRevisionVector','exceptionSetDigest'],'normal recurring reference');
 IF p_reference->>'schema' IS DISTINCT FROM 'custodial.approved-manual-recurring-reference.v1'
  OR p_reference_digest IS DISTINCT FROM public.static_weekly_digest_jsonb(p_reference)
 THEN RAISE EXCEPTION 'Exact compact repeat reference required'; END IF;
 manager:=(p_reference->>'managerId')::uuid;publication:=(p_reference->>'publicationId')::uuid;request:=(p_reference->>'requestId')::uuid;
 frame:=(p_reference->>'frameStart')::date;revision:=(p_reference->>'expectedRevision')::bigint;
 IF manager IS NULL OR publication IS NULL OR request IS NULL THEN RAISE EXCEPTION 'Explicit request/publication/manager identity required'; END IF;
 actor:=public.custodial_action_actor_v1(manager,p_credential,p_device,p_access,'write');
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 SELECT * INTO prior FROM public.static_weekly_manual_repeat_confirmations WHERE manager_id=manager AND request_id=request;
 IF FOUND THEN
  IF prior.request_json IS DISTINCT FROM p_reference THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='Original repeat request identity changed'; END IF;
  RETURN prior.receipt_json;
 END IF;
 basis:=public.static_weekly_read_manual_repeat_basis(manager,publication,frame,revision,p_credential,p_device,p_access);
 reasons:=basis->'adjustmentReasons';
 IF basis->'acceptedExceptions' IS DISTINCT FROM '[]'::jsonb THEN reasons:=reasons||jsonb_build_array(jsonb_build_object('kind','ACCEPTED_EXCEPTIONS')); END IF;
 FOR v_day IN SELECT value FROM jsonb_array_elements(basis->'employmentByDate') LOOP
  FOR employee IN SELECT value FROM jsonb_array_elements(v_day->'employees') LOOP
   IF (employee#>>'{command,fact,state}'='PRE_START' OR (employee#>>'{command,fact,firstServiceDate}')::date>(v_day->>'serviceDate')::date)
    AND EXISTS(SELECT 1 FROM jsonb_array_elements(basis->'participants') p WHERE p->>'serviceDate'=v_day->>'serviceDate'
     AND ((p->'assignmentEmployeeIds')?(employee->>'employeeId') OR (p->'lunchOwnerEmployeeIds')?(employee->>'employeeId') OR (p->'lunchCovererEmployeeIds')?(employee->>'employeeId'))) THEN
    reasons:=reasons||jsonb_build_array(jsonb_build_object('kind','PRE_START_NOT_PTO','serviceDate',v_day->>'serviceDate','employeeId',employee->>'employeeId'));
   END IF;
  END LOOP;
 END LOOP;
 IF jsonb_array_length(reasons)>0 THEN RETURN jsonb_build_object('schema','custodial.approved-manual-recurring-decision.v1',
  'status','NEEDS_DATED_ADJUSTMENT','frameStart',basis->'frameStart','frameEnd',basis->'frameEnd','reasons',reasons,
  'route','SAME_NATIVE_APPROVED_MANUAL_DATED_OWNER_PATH','normalSourceChanged',false,'solverInvoked',false,'published',false); END IF;
 SELECT jsonb_agg(jsonb_build_object('serviceDate',day_row->>'serviceDate','employeeId',employee_row->>'employeeId',
  'employmentRevision',employee_row->'employmentRevision','requestId',employee_row#>>'{command,requestId}') ORDER BY day_row->>'serviceDate',employee_row->>'employeeId') INTO vector
 FROM jsonb_array_elements(basis->'employmentByDate') days(day_row) CROSS JOIN LATERAL jsonb_array_elements(day_row->'employees') employees(employee_row);
 expected:=jsonb_build_object('schema','custodial.approved-manual-recurring-reference.v1','managerId',manager,'requestId',request,
  'sourceId',basis->'sourceId','publicationId',basis->'publicationId','versionId',basis->'versionId','origin',basis->'origin',
  'frameStart',basis->'frameStart','frameEnd',basis->'frameEnd','expectedRevision',revision,'generation',basis->'generation',
  'baselineSnapshotDigest',basis->'baselineSnapshotDigest','catalogEntryDigest',basis->'catalogEntryDigest',
  'sourceProjectionIdentity',basis->'sourceProjectionIdentity','sourceLunchIdentity',basis->'sourceLunchIdentity',
  'employmentRevisionVector',vector,'exceptionSetDigest',public.static_weekly_digest_jsonb(basis->'acceptedExceptions'));
 IF expected IS DISTINCT FROM p_reference THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Current repeat source/catalog/generation/employment/reference changed'; END IF;
 IF basis->'existingProjectionId' IS DISTINCT FROM 'null'::jsonb THEN RETURN jsonb_build_object('status','ALREADY_MATERIALIZED',
  'projectionId',basis->'existingProjectionId','frameStart',basis->'frameStart','published',false); END IF;
 PERFORM public.custodial_begin_application_mutation();
 components:=public.static_weekly_manual_repeat_components((basis->>'sourceId')::uuid,frame);
 projection:=components->'projection';
 PERFORM public.static_weekly_manual_assert_lunch_lineage(projection,components->'lunchDocument',publication,frame);
 materialized:=public.static_weekly_manual_repeat_materialize_projection(publication,frame,public.static_weekly_digest_jsonb('[]'::jsonb),
  projection->>'compiler_version',projection->'objective',projection->'metrics',projection->>'replay_digest',projection,revision,
  manager,actor->>'manager_name',request::text||':normal-period');
 projection:=NULL;
 lunch:=public.static_weekly_v8_materialize_lunch_document((materialized#>>'{data,projection_id}')::uuid,components->'lunchDocument',manager);
 IF materialized->'ok' IS DISTINCT FROM 'true'::jsonb OR materialized->>'revision' IS NULL OR lunch->>'persistence_status' IS DISTINCT FROM 'PERSISTED' THEN RAISE EXCEPTION 'Native repeated period/lunch did not persist'; END IF;
 receipt:=jsonb_build_object('schema','custodial.approved-manual-recurring-confirmation.v1','status','PERSISTED_CURRENT',
  'source_id',basis->'sourceId','publication_id',publication,'projection_id',materialized#>'{data,projection_id}',
  'authority_revision',materialized->'revision','frameStart',basis->'frameStart','frameEnd',basis->'frameEnd',
  'lunch_document_identity',lunch->'document_identity','referenceDigest',p_reference_digest,'solverInvoked',false,'normalSourceChanged',false);
 INSERT INTO public.static_weekly_manual_repeat_confirmations VALUES(manager,request,p_reference,receipt);
 RETURN receipt;
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_pending_assert_day(p_operation uuid, p_envelope jsonb, p_publication_id uuid, p_week date, p_exceptions jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE authority jsonb:=p_envelope->'authority';source jsonb;live_source jsonb;approved_source jsonb;config jsonb;entry record;current_source record;
 expected_availability jsonb:='[]';expected_slots jsonb:='[]';expected_rows jsonb:='[]';expected_projection jsonb:='[]';
 slot jsonb;availability jsonb;incumbent jsonb;owner_config jsonb;work jsonb;normalized_work jsonb;person jsonb;owner_key text;
 roster jsonb:='[]';projection_availability jsonb;item jsonb;identity_key text;d date;day integer;baseline_person jsonb;
 productive numeric;effort numeric;duty numeric;v_source_id uuid;employee_count integer;working_count integer:=0;
 mapped_rows jsonb;mapping jsonb;role_availability jsonb;actual_availability jsonb;role_profile jsonb;actual_profile jsonb;
 route jsonb;stops jsonb;stop jsonb;nodes jsonb;node jsonb;previous_node jsonb;blocked jsonb;protected_windows jsonb;
 route_start text;route_provenance text;node_start integer;node_end integer;previous_end integer;shift_start integer;shift_end integer;
 block_start integer;block_end integer;cursor_minute integer;protected_minutes integer;travel integer;available_gap integer;
 committed_duty numeric;stop_effort numeric;stop_duration integer;route_count integer:=0;route_pass integer;baseline_travel integer;staged_stop_nodes jsonb;
 p_date date:=p_week;operation_date date;operation_day integer;raw_source jsonb;compiler_exceptions jsonb;
 baseline jsonb;candidate_version jsonb;original_rows jsonb;unaffected jsonb;expected_unaffected jsonb;physical_rows jsonb;
 assignment_links jsonb:='{}';original_assignment uuid;effective_work jsonb;effective_original jsonb;
 closing jsonb:=authority->'shiftEndDerivation';closing_result jsonb;closing_enabled boolean;parent_id text;raw_parent jsonb;is_open boolean;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 IF p_week IS NULL OR NOT isfinite(p_week) OR extract(isodow FROM p_week)<>1
  OR p_publication_id IS NULL OR jsonb_typeof(authority) IS DISTINCT FROM 'object'
 THEN RAISE EXCEPTION 'Exact dated publication and Monday required';END IF;
 PERFORM public.static_weekly_assert_exact_object(authority,
  ARRAY['schema','effectiveDate','compilerInput','overlayCompilerInput','inputDigest','baselineInputDigest','derivedBaselineDigest','shiftEndDerivation','projectionAvailability','mapping','basisDigest','witnessDigest','solverInvoked','optimized','originalCompilerInput','originalWeekCompilerInput','weekDerivation','originalInputDigest','mappedBaselineInputDigest','originalPublicationId','originalVersionId','scopeDates','scopeDays','appliedExceptions'],
  ARRAY['schema','effectiveDate','compilerInput','overlayCompilerInput','inputDigest','baselineInputDigest','derivedBaselineDigest','shiftEndDerivation','projectionAvailability','mapping','basisDigest','witnessDigest','solverInvoked','optimized','originalCompilerInput','originalWeekCompilerInput','weekDerivation','originalInputDigest','mappedBaselineInputDigest','originalPublicationId','originalVersionId','scopeDates','scopeDays','appliedExceptions'],'approved dated authority');
 PERFORM public.static_weekly_assert_exact_object(p_envelope->'receipt',
  ARRAY['schema','feasibilityDigest','hardConstraintCount','hardConstraintDigest','independentDerivations','solverInvoked','optimized'],
  ARRAY['schema','feasibilityDigest','hardConstraintCount','hardConstraintDigest','independentDerivations','solverInvoked','optimized'],'approved dated receipt DATA');
 PERFORM public.static_weekly_assert_exact_object(p_envelope,
  ARRAY['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','semantic_snapshot','database_projection_identity'],
  ARRAY['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','semantic_snapshot','database_projection_identity'],'approved dated projection');
 IF jsonb_typeof(authority->'scopeDates') IS DISTINCT FROM 'array' OR jsonb_array_length(authority->'scopeDates')<>1
  OR jsonb_typeof(authority->'scopeDays') IS DISTINCT FROM 'array' OR jsonb_array_length(authority->'scopeDays')<>1
  OR coalesce(authority#>>'{scopeDates,0}','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
 THEN RAISE EXCEPTION 'Singleton dated operation scope required';END IF;
 operation_date:=(authority#>>'{scopeDates,0}')::date;operation_day:=extract(dow FROM operation_date)::integer;
 IF NOT isfinite(operation_date) OR operation_date NOT BETWEEN p_week AND p_week+6
  OR authority->'scopeDays' IS DISTINCT FROM jsonb_build_array(operation_day)
 THEN RAISE EXCEPTION 'Dated operation lies outside its original week';END IF;
 SELECT s.source_id,s.canonical_source,s.source_digest,v.draft_document,v.version_id INTO STRICT current_source
  FROM public.weekly_schedule_publications p JOIN public.weekly_schedule_versions v USING(version_id)
  JOIN public.static_weekly_authority_source_documents s ON s.source_id=v.authority_source_id
  WHERE p.publication_id=p_publication_id AND v.version_id=public.static_weekly_effective_version(p_week)
   AND v.version_id=public.static_weekly_effective_version(p_week+6) AND s.active AND s.retired_at IS NULL;
 v_source_id:=current_source.source_id;
 IF current_source.source_digest IS DISTINCT FROM public.static_weekly_digest_jsonb(current_source.canonical_source)
 THEN RAISE EXCEPTION 'Dated registered Source differs';END IF;
 raw_source:=public.static_weekly_pending_day_source(p_operation,p_publication_id,p_week,operation_date);
 live_source:=raw_source->'compiler_input';
 compiler_exceptions:=public.static_weekly_pending_exception_set(p_operation,p_publication_id,p_week,operation_date);
 baseline:=authority->'compilerInput';closing_enabled:=live_source#>'{version,shiftEndContinuityPolicy}' IS NOT NULL;
 source:=CASE WHEN closing_enabled THEN closing->'mappedInput' ELSE authority->'overlayCompilerInput' END;
 IF jsonb_typeof(source->'slots') IS DISTINCT FROM 'array' OR jsonb_array_length(source->'slots') NOT BETWEEN 6 AND 32
  OR jsonb_typeof(source#>'{version,slotAvailability}') IS DISTINCT FROM 'array'
  OR jsonb_typeof(source#>'{version,assignments}') IS DISTINCT FROM 'array'
  OR jsonb_array_length(source#>'{version,assignments}') NOT BETWEEN 1 AND 4096
  OR (SELECT count(*) FROM jsonb_array_elements(source#>'{version,slotAvailability}'))<>7*jsonb_array_length(source->'slots')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(source->'slots') s CROSS JOIN generate_series(0,6) day(n)
   WHERE (SELECT count(*) FROM jsonb_array_elements(source#>'{version,slotAvailability}') a
    WHERE a->'slotId'=s->'id' AND a->'dayOfWeek'=to_jsonb(day.n))<>1)
 THEN RAISE EXCEPTION 'Dated bounded total seven-day slot Source required';END IF;
 IF p_exceptions IS DISTINCT FROM public.static_weekly_pending_applied_summary(p_operation,p_publication_id,p_week,operation_date)
  OR authority->'appliedExceptions' IS DISTINCT FROM p_exceptions OR p_envelope->'applied_exceptions' IS DISTINCT FROM p_exceptions
  OR authority->'originalCompilerInput' IS DISTINCT FROM jsonb_set(jsonb_set(live_source,'{serviceDate}',to_jsonb(operation_date::text),true),'{exceptions}',compiler_exceptions,true)
  OR authority->'originalWeekCompilerInput' IS DISTINCT FROM jsonb_set(CASE WHEN closing_enabled THEN closing->'originalDerivedInput' ELSE live_source END,'{exceptions}',compiler_exceptions,true)
  OR baseline IS DISTINCT FROM jsonb_set(live_source,'{exceptions}','[]'::jsonb,true)
  OR source->'exceptions' IS DISTINCT FROM compiler_exceptions
  OR source-'version'-'exceptions' IS DISTINCT FROM live_source-'version'-'exceptions'
  OR (source->'version')-'assignments' IS DISTINCT FROM (live_source->'version')-'assignments'
  OR authority->>'originalPublicationId' IS DISTINCT FROM p_publication_id::text
  OR authority->>'originalVersionId' IS DISTINCT FROM live_source#>>'{version,id}'
 THEN RAISE EXCEPTION 'Dated original Source publication version or complete exceptions differ';END IF;
 IF (closing_enabled AND closing->>'schema' IS DISTINCT FROM 'custodial.approved-static-dated-closing.v1')
  OR (NOT closing_enabled AND closing IS DISTINCT FROM 'null'::jsonb)
  OR source#>'{version,shiftEndDerivationApplied}' IS NOT NULL
 THEN RAISE EXCEPTION 'Dated closing requires its exact typed original/selected wrapper';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(compiler_exceptions) e
   WHERE e->>'type' NOT IN('pto','daily_absence','partial_absence','lunch','shift_override','event_impact','manager_correction','nine_forty_five_rebalance'))
 THEN RAISE EXCEPTION USING ERRCODE='0A000',MESSAGE='Unqualified approved dated work-changing exception profile';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(compiler_exceptions) e WHERE e->>'type' IN('pto','daily_absence')
  GROUP BY e->>'serviceDate',e#>>'{payload,slotId}' HAVING count(*)>1)
 THEN RAISE EXCEPTION 'Dated duplicate full-day absence differs';END IF;
 SELECT c.owner_config INTO STRICT config FROM public.static_weekly_approved_template_source_configs c
  WHERE c.source_id=v_source_id AND c.config_digest=public.static_weekly_digest_jsonb(c.owner_config);
 IF config->>'schema' IS DISTINCT FROM 'custodial.owner-corrected-recurring-schedule.v2'
  OR jsonb_typeof(config->'slots') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Recurring typed owner configuration required';END IF;
 FOR owner_key,owner_config IN SELECT key,value FROM jsonb_each(config->'slots') LOOP
  IF owner_config ? 'normalAllowedFamilies' OR owner_config ? 'forbiddenFamilies'
   OR EXISTS(SELECT 1 FROM unnest(ARRAY['normalAssignmentFamilies','hardForbiddenFamilies']) f
    WHERE owner_config ? f AND (jsonb_typeof(owner_config->f) IS DISTINCT FROM 'array'
     OR EXISTS(SELECT 1 FROM jsonb_array_elements(owner_config->f) family WHERE jsonb_typeof(family)<>'string' OR family#>>'{}' !~ '^[A-Z0-9_]+$')
     OR (SELECT count(*) FROM jsonb_array_elements(owner_config->f))<>(SELECT count(DISTINCT family) FROM jsonb_array_elements(owner_config->f) family))) THEN
   RAISE EXCEPTION 'Recurring normal geography and hard exclusions require exact separate typed families';END IF;
  IF (owner_config->>'personId'='3da709bb-2223-4e15-8e3a-db02e3f32e97' AND (owner_key<>'KAREN' OR owner_config->>'slotId'<>'f22348e9-d4b9-5a7e-b8fd-d0d2c1ec534f'))
   OR (owner_config->>'personId'='cd97111e-cfa0-4228-b4d7-401bc7a5ac13' AND (owner_key<>'TAMMY' OR owner_config->>'slotId'<>'4a5a83ca-d297-5a30-8344-db08d05b978c'))
   OR (owner_config->>'personId'='30ec85e0-a579-45a8-9c27-c164e77a9190' AND (owner_key<>'KATHY' OR owner_config->>'slotId'<>'55e5939c-175c-5026-94fd-c4350d538922'))
   OR (owner_config->>'personId'='77d50e9a-6338-43b1-aed5-9f47d7129466' AND (owner_key<>'ALIJAH' OR owner_config->>'slotId'<>'36829381-70d7-521b-9f14-bad0af16ba87'
    OR owner_config->'hardForbiddenFamilies' IS DISTINCT FROM '["HERPETARIUM"]'::jsonb)) THEN
   RAISE EXCEPTION 'Recurring original personal geography identity or hard exclusion differs';END IF;
 END LOOP;

 SELECT * INTO STRICT entry FROM public.static_weekly_approved_template_catalog
  WHERE template_id=authority#>>'{mapping,templateId}' AND NOT EXISTS(
   SELECT 1 FROM public.static_weekly_approved_template_retirements r WHERE r.template_id=static_weekly_approved_template_catalog.template_id);
 IF entry.staffing_count NOT BETWEEN 6 AND 9 OR entry.owner_config IS DISTINCT FROM config
  OR entry.binding_json->>'patternAuthority' IS DISTINCT FROM 'OWNER_APPROVED_OPERATIONAL_PATTERN'
  OR entry.catalog_entry_digest IS DISTINCT FROM public.static_weekly_digest_jsonb(jsonb_build_object(
   'template',entry.template_json,'binding',entry.binding_json,'ownerConfig',entry.owner_config,'approvalEvidence',entry.approval_evidence))
  OR authority#>>'{mapping,schema}' IS DISTINCT FROM 'custodial.approved-static-template-mapping.v1'
  OR authority#>>'{mapping,contract}' IS DISTINCT FROM 'FIXED_APPROVED_GEOMETRY_COMPATIBILITY_NOT_GLOBAL_OPTIMALITY'
  OR authority#>'{mapping,staffingCount}' IS DISTINCT FROM to_jsonb(entry.staffing_count)
  OR authority#>>'{mapping,serviceDate}' IS DISTINCT FROM operation_date::text
  OR authority#>'{mapping,scopeDays}' IS DISTINCT FROM jsonb_build_array(operation_day)
  OR authority#>'{mapping,solverInvoked}' IS DISTINCT FROM 'false'::jsonb
  OR authority#>'{mapping,admitted}' IS DISTINCT FROM 'false'::jsonb
  OR authority#>'{mapping,published}' IS DISTINCT FROM 'false'::jsonb
 THEN RAISE EXCEPTION 'Dated current approved template configuration or scope differs';END IF;
 approved_source:=entry.template_json->'source';
 IF jsonb_typeof(approved_source->'version') IS DISTINCT FROM 'object'
  OR approved_source->'exceptions' IS DISTINCT FROM '[]'::jsonb
  OR approved_source->'proximity' IS DISTINCT FROM live_source->'proximity'
  OR approved_source#>'{version,shiftEndContinuityPolicy}' IS DISTINCT FROM live_source#>'{version,shiftEndContinuityPolicy}'
  OR jsonb_typeof(authority#>'{mapping,slotMapping}') IS DISTINCT FROM 'array'
  OR jsonb_array_length(authority#>'{mapping,slotMapping}')<>entry.staffing_count
  OR jsonb_array_length(entry.template_json->'roleSlotIds')<>entry.staffing_count
  OR (SELECT count(DISTINCT r) FROM jsonb_array_elements(entry.template_json->'roleSlotIds') r)<>entry.staffing_count
  OR (SELECT count(DISTINCT m->>'patternSlotId') FROM jsonb_array_elements(authority#>'{mapping,slotMapping}') m)<>entry.staffing_count
  OR (SELECT count(DISTINCT m->>'actualSlotId') FROM jsonb_array_elements(authority#>'{mapping,slotMapping}') m)<>entry.staffing_count
  OR (SELECT count(DISTINCT m->>'actualPersonId') FROM jsonb_array_elements(authority#>'{mapping,slotMapping}') m)<>entry.staffing_count
 THEN RAISE EXCEPTION 'Dated bijection or original route policy differs';END IF;
 FOR mapping IN SELECT value FROM jsonb_array_elements(authority#>'{mapping,slotMapping}') LOOP
  PERFORM public.static_weekly_assert_exact_object(mapping,ARRAY['patternSlotId','actualSlotId','actualPersonId'],
   ARRAY['patternSlotId','actualSlotId','actualPersonId'],'dated role mapping');
  SELECT value INTO STRICT slot FROM jsonb_array_elements(live_source->'slots') WHERE value->'id'=mapping->'actualSlotId';
  SELECT value INTO STRICT incumbent FROM jsonb_array_elements(slot->'incumbencies')
   WHERE (value->>'effectiveStart')::date<=operation_date AND (value->>'effectiveEnd' IS NULL OR operation_date<(value->>'effectiveEnd')::date);
  IF NOT(entry.template_json->'roleSlotIds' ? (mapping->>'patternSlotId'))
   OR coalesce(slot->'contractorCapacity','false'::jsonb)<>'false'::jsonb
   OR incumbent->'personId' IS DISTINCT FROM mapping->'actualPersonId'
   OR NOT EXISTS(SELECT 1 FROM jsonb_each(config->'slots') c WHERE c.value->'slotId'=mapping->'actualSlotId'
    AND c.value->'personId'=mapping->'actualPersonId' AND c.value->'vacancy' IS DISTINCT FROM 'true'::jsonb)
  THEN RAISE EXCEPTION 'Dated role does not name actual operation-day employee';END IF;
  SELECT value INTO STRICT role_availability FROM jsonb_array_elements(approved_source#>'{version,slotAvailability}')
   WHERE value->'slotId'=mapping->'patternSlotId' AND value->>'dayOfWeek'=operation_day::text;
  SELECT value INTO STRICT actual_availability FROM jsonb_array_elements(live_source#>'{version,slotAvailability}')
   WHERE value->'slotId'=mapping->'actualSlotId' AND value->>'dayOfWeek'=operation_day::text;
  actual_availability:=public.static_weekly_approved_dated_effective_availability(actual_availability,mapping->>'actualSlotId',operation_date,compiler_exceptions);
  IF NOT(role_availability ? 'acceptedRoute') AND approved_source#>ARRAY['version','acceptedRoutesBySlot',mapping->>'patternSlotId'] IS NOT NULL THEN
   role_availability:=role_availability||jsonb_build_object('acceptedRoute',approved_source#>ARRAY['version','acceptedRoutesBySlot',mapping->>'patternSlotId']);END IF;
  IF NOT(actual_availability ? 'acceptedRoute') AND live_source#>ARRAY['version','acceptedRoutesBySlot',mapping->>'actualSlotId'] IS NOT NULL THEN
   actual_availability:=actual_availability||jsonb_build_object('acceptedRoute',live_source#>ARRAY['version','acceptedRoutesBySlot',mapping->>'actualSlotId']);END IF;
  SELECT jsonb_build_object('shift',a->'shift','lunch',a->'lunch','blocked',coalesce(a->'blockedWindows','[]'::jsonb),
   'service',coalesce(a->'maxServiceEffortMinutes',a->'maxLoadPoints'),'duty',coalesce(a->'maxDutyMinutes',a->'max_duty_minutes'),
   'route',a->'acceptedRoute','start',coalesce(a->'acceptedRouteStartLocationId',a->'acceptedRouteAnchorLocationId',a->'routeAnchorLocationId'),
   'stops',a->'acceptedRouteStops') INTO role_profile FROM(SELECT role_availability a)t;
  SELECT jsonb_build_object('shift',a->'shift','lunch',a->'lunch','blocked',coalesce(a->'blockedWindows','[]'::jsonb),
   'service',coalesce(a->'maxServiceEffortMinutes',a->'maxLoadPoints'),'duty',coalesce(a->'maxDutyMinutes',a->'max_duty_minutes'),
   'route',a->'acceptedRoute','start',coalesce(a->'acceptedRouteStartLocationId',a->'acceptedRouteAnchorLocationId',a->'routeAnchorLocationId'),
   'stops',a->'acceptedRouteStops') INTO actual_profile FROM(SELECT actual_availability a)t;
  IF role_profile IS DISTINCT FROM actual_profile OR actual_availability->>'status' IS DISTINCT FROM 'working'
  THEN RAISE EXCEPTION 'Dated current role availability route or duty profile differs';END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(approved_source#>'{version,assignments}') w WHERE w->>'dayOfWeek'=operation_day::text
   AND (SELECT count(*) FROM jsonb_array_elements(authority#>'{mapping,slotMapping}') m WHERE m->'patternSlotId'=w->'ownerSlotId')<>1)
 THEN RAISE EXCEPTION 'Dated approved work has an unmapped role';END IF;
 SELECT coalesce(jsonb_agg(w ORDER BY (w->>'dayOfWeek')::integer,w->>'workId' COLLATE "C"),'[]') INTO original_rows
  FROM jsonb_array_elements(live_source#>'{version,assignments}') w WHERE w->>'dayOfWeek'<>operation_day::text;
 SELECT coalesce(jsonb_agg(w ORDER BY (w->>'dayOfWeek')::integer,w->>'workId' COLLATE "C"),'[]') INTO unaffected
  FROM jsonb_array_elements(source#>'{version,assignments}') w WHERE w->>'dayOfWeek'<>operation_day::text;
 SELECT coalesce(jsonb_agg(jsonb_set(w,'{ownerSlotId}',m->'actualSlotId') ORDER BY w->>'workId' COLLATE "C"),'[]') INTO mapped_rows
  FROM jsonb_array_elements(approved_source#>'{version,assignments}') w
  JOIN jsonb_array_elements(authority#>'{mapping,slotMapping}') m ON m->'patternSlotId'=w->'ownerSlotId' WHERE w->>'dayOfWeek'=operation_day::text;
 SELECT coalesce(jsonb_agg(w ORDER BY w->>'workId' COLLATE "C"),'[]') INTO expected_rows
  FROM jsonb_array_elements(source#>'{version,assignments}') w WHERE w->>'dayOfWeek'=operation_day::text;
 IF original_rows IS DISTINCT FROM unaffected OR mapped_rows IS DISTINCT FROM expected_rows OR jsonb_array_length(mapped_rows)=0
  OR (SELECT count(*) FROM jsonb_array_elements(source#>'{version,assignments}'))<>
   (SELECT count(DISTINCT (w->>'dayOfWeek',w->>'workId')) FROM jsonb_array_elements(source#>'{version,assignments}') w)
 THEN RAISE EXCEPTION 'Dated exact selected mapping or six unaffected day rows differ';END IF;
 effective_work:=public.static_weekly_pending_effective_work(p_operation,operation_date,p_publication_id,p_week,source);
 effective_original:=public.static_weekly_pending_effective_work(p_operation,operation_date,p_publication_id,p_week,
  jsonb_set(live_source,'{exceptions}',compiler_exceptions,true));
 IF EXISTS(WITH rows AS(
   SELECT 0 side,w FROM jsonb_array_elements(approved_source#>'{version,assignments}') w
   UNION ALL SELECT 1,w FROM jsonb_array_elements(live_source#>'{version,assignments}') w
  UNION ALL SELECT 2,w FROM jsonb_array_elements(current_source.canonical_source#>'{version,assignments}') w
  ), facts AS(SELECT side,w,jsonb_build_object('day',w->'dayOfWeek','family',w->'locationCodeSnapshot',
   'phase',CASE WHEN w#>>'{window,end}'='09:45' THEN '"morning"'::jsonb WHEN w#>>'{window,start}'='09:45' THEN '"equalized"'::jsonb ELSE w->'window' END,
   'mode',w->'serviceMode','scheduling',w->'schedulingMode','required',coalesce(w->'required','true'::jsonb),
   'priority',w->'priority','qualifications',w->'requiredQualifications','restrictions',w->'restrictions',
   'restrictedSlots',coalesce(w->'restrictedSlotIds','[]'::jsonb),'policy',w->'coveragePolicy','order',w->'coveragePolicyOrder') f FROM rows WHERE w->>'dayOfWeek'=operation_day::text),
  efforts AS(SELECT side,f,sum((w->>'serviceEffortMinutes')::numeric) effort FROM facts GROUP BY side,f),
  members AS(SELECT side,f,jsonb_agg(member ORDER BY member) members FROM facts CROSS JOIN LATERAL
   jsonb_array_elements(CASE WHEN jsonb_array_length(coalesce(w->'includedLocations','[]'::jsonb))>0 THEN w->'includedLocations'
    ELSE jsonb_build_array(jsonb_build_object('locationId',w->'locationId','locationNameSnapshot',w->'locationNameSnapshot')) END) member GROUP BY side,f),
  domain AS(SELECT side,f,effort,members FROM efforts JOIN members USING(side,f))
  (SELECT f,effort,members FROM domain WHERE side=0 EXCEPT ALL SELECT f,effort,members FROM domain WHERE side=1)
  UNION ALL(SELECT f,effort,members FROM domain WHERE side=1 EXCEPT ALL SELECT f,effort,members FROM domain WHERE side=0)
  UNION ALL(SELECT f,effort,members FROM domain WHERE side=1 EXCEPT ALL SELECT f,effort,members FROM domain WHERE side=2)
  UNION ALL(SELECT f,effort,members FROM domain WHERE side=2 EXCEPT ALL SELECT f,effort,members FROM domain WHERE side=1)) THEN
  RAISE EXCEPTION 'Dated approved physical responsibility multiset differs from current Source';END IF;
 -- The existing producer compares the approved physical domain against the
 -- EFFECTIVE current work, not just its raw baseline. Never let an event get
 -- dropped into a stale pattern; no hash or accepted-command label replaces
 -- this multiplicity/effort/eligibility check. A truly new domain needs an
 -- actual compatible approved producer/catalog entry before this can succeed.
 IF EXISTS(WITH rows AS(
   SELECT 0 side,w FROM jsonb_array_elements(approved_source#>'{version,assignments}') w
   UNION ALL SELECT 1,w FROM jsonb_array_elements(effective_original) w
   UNION ALL SELECT 2,w FROM jsonb_array_elements(effective_work) w
  ), facts AS(SELECT side,w,jsonb_build_object('day',w->'dayOfWeek','family',w->'locationCodeSnapshot',
   'phase',CASE WHEN w#>>'{window,end}'='09:45' THEN '"morning"'::jsonb WHEN w#>>'{window,start}'='09:45' THEN '"equalized"'::jsonb ELSE w->'window' END,
   'mode',w->'serviceMode','scheduling',w->'schedulingMode','required',coalesce(w->'required','true'::jsonb),
   'priority',w->'priority','qualifications',w->'requiredQualifications','restrictions',w->'restrictions',
   'restrictedSlots',coalesce(w->'restrictedSlotIds','[]'::jsonb),'policy',w->'coveragePolicy','order',w->'coveragePolicyOrder') f
   FROM rows WHERE w->>'dayOfWeek'=operation_day::text),
  efforts AS(SELECT side,f,sum((w->>'serviceEffortMinutes')::numeric) effort FROM facts GROUP BY side,f),
  members AS(SELECT side,f,jsonb_agg(member ORDER BY member) members FROM facts CROSS JOIN LATERAL
   jsonb_array_elements(CASE WHEN jsonb_array_length(coalesce(w->'includedLocations','[]'::jsonb))>0 THEN w->'includedLocations'
    ELSE jsonb_build_array(jsonb_build_object('locationId',w->'locationId','locationNameSnapshot',w->'locationNameSnapshot')) END) member GROUP BY side,f),
  domain AS(SELECT side,f,effort,members FROM efforts JOIN members USING(side,f))
  (SELECT f,effort,members FROM domain WHERE side=0 EXCEPT ALL SELECT f,effort,members FROM domain WHERE side=1)
  UNION ALL(SELECT f,effort,members FROM domain WHERE side=1 EXCEPT ALL SELECT f,effort,members FROM domain WHERE side=0)
  UNION ALL(SELECT f,effort,members FROM domain WHERE side=1 EXCEPT ALL SELECT f,effort,members FROM domain WHERE side=2)
  UNION ALL(SELECT f,effort,members FROM domain WHERE side=2 EXCEPT ALL SELECT f,effort,members FROM domain WHERE side=1))
 THEN RAISE EXCEPTION USING ERRCODE='0A000',MESSAGE='Dated accepted event requires a compatible approved physical domain';END IF;
 IF closing_enabled THEN
  closing_result:=public.static_weekly_approved_dated_assert_closing(closing,baseline,approved_source,config,authority->'mapping',operation_date);
  IF (authority->'overlayCompilerInput')-'version' IS DISTINCT FROM
    jsonb_set(closing_result->'effectiveInput','{exceptions}',compiler_exceptions,true)-'version'
   OR (authority#>'{overlayCompilerInput,version}')-'assignments' IS DISTINCT FROM (closing_result#>'{effectiveInput,version}')-'assignments'
   OR (SELECT jsonb_agg(w ORDER BY n) FROM jsonb_array_elements(authority#>'{overlayCompilerInput,version,assignments}') WITH ORDINALITY x(w,n) WHERE w->>'dayOfWeek'<>operation_day::text)
    IS DISTINCT FROM (SELECT jsonb_agg(w ORDER BY n) FROM jsonb_array_elements(closing#>'{originalDerivedInput,version,assignments}') WITH ORDINALITY x(w,n) WHERE w->>'dayOfWeek'<>operation_day::text)
   OR EXISTS((SELECT value FROM jsonb_array_elements(authority#>'{overlayCompilerInput,version,assignments}')
     EXCEPT ALL SELECT value FROM jsonb_array_elements(closing_result#>'{effectiveInput,version,assignments}'))
    UNION ALL(SELECT value FROM jsonb_array_elements(closing_result#>'{effectiveInput,version,assignments}')
     EXCEPT ALL SELECT value FROM jsonb_array_elements(authority#>'{overlayCompilerInput,version,assignments}')))
  THEN RAISE EXCEPTION 'Dated whole derived week differs from original six days plus selected chain';END IF;
  effective_work:=public.static_weekly_pending_effective_work(p_operation,operation_date,p_publication_id,p_week,
   jsonb_set(closing_result->'effectiveInput','{exceptions}',compiler_exceptions,true));
  effective_original:=public.static_weekly_pending_effective_work(p_operation,operation_date,p_publication_id,p_week,
   jsonb_set(closing->'originalDerivedInput','{exceptions}',compiler_exceptions,true));
 END IF;
 FOR availability IN SELECT value FROM jsonb_array_elements(source#>'{version,slotAvailability}') LOOP
  SELECT value INTO STRICT slot FROM jsonb_array_elements(source->'slots') WHERE value->>'id'=availability->>'slotId';
  IF NOT(availability ? 'acceptedRoute') AND source#>ARRAY['version','acceptedRoutesBySlot',slot->>'id'] IS NOT NULL THEN
   availability:=availability||jsonb_build_object('acceptedRoute',source#>ARRAY['version','acceptedRoutesBySlot',slot->>'id']);
  END IF;
  day:=(availability->>'dayOfWeek')::integer;d:=p_date+mod(day+6,7);
  availability:=public.static_weekly_approved_dated_effective_availability(availability,slot->>'id',d,compiler_exceptions);
  incumbent:=NULL;
  IF coalesce(slot->'contractorCapacity','false'::jsonb)='false'::jsonb THEN
   SELECT value INTO incumbent FROM jsonb_array_elements(slot->'incumbencies')
    WHERE (value->>'effectiveStart')::date<=d AND (value->>'effectiveEnd' IS NULL OR d<(value->>'effectiveEnd')::date);
   IF (SELECT count(*) FROM jsonb_array_elements(slot->'incumbencies')
     WHERE (value->>'effectiveStart')::date<=d AND (value->>'effectiveEnd' IS NULL OR d<(value->>'effectiveEnd')::date))>1 THEN
    RAISE EXCEPTION 'Dated dated incumbent is ambiguous';END IF;
  ELSIF availability->>'status'='working' THEN
   RAISE EXCEPTION 'Active contractor capacity is not an ordinary dated employee profile';END IF;
  projection_availability:=jsonb_build_object('dayOfWeek',day,'serviceDate',d::text)||availability||jsonb_build_object(
   'incumbentSlotId',slot->'id','incumbentSlotLabel',slot->'label',
   'incumbentPersonId',incumbent->'personId','incumbentName',incumbent->'displayName');
  IF slot->>'kind'='CONTRACTOR_CAPACITY' THEN
   IF slot->'capacityId' IS DISTINCT FROM slot->'id' OR slot->'incumbencies' IS DISTINCT FROM '[]'::jsonb THEN
    RAISE EXCEPTION 'Dated inactive capacity original identity differs';END IF;
   projection_availability:=projection_availability||jsonb_build_object('ownerKind','CONTRACTOR_CAPACITY','capacityId',slot->'id');
  END IF;
  expected_availability:=expected_availability||jsonb_build_array(projection_availability);
  roster:=roster||jsonb_build_array(projection_availability);
  IF coalesce(slot->'contractorCapacity','false'::jsonb)='true'::jsonb THEN CONTINUE;END IF;
  IF availability->>'status'='working' THEN
   working_count:=working_count+1;
   -- Only the selected day creates a new mapped employee choice. Preserve
   -- the six other days' actual dated snapshots, including prior/future
   -- incumbents; never reinterpret them as the operation-day employee.
   SELECT value INTO STRICT owner_config FROM jsonb_each(config->'slots')
    WHERE value->>'slotId'=slot->>'id' AND (d<>operation_date OR
     (value->>'personId'=incumbent->>'personId' AND value->'vacancy' IS DISTINCT FROM 'true'::jsonb));
   IF incumbent IS NULL OR (d=operation_date AND NOT EXISTS(SELECT 1 FROM public.employees e
    WHERE e.id=(incumbent->>'personId')::uuid AND e.active AND e.display_name=incumbent->>'displayName')) THEN
    RAISE EXCEPTION 'Dated mapped owner requires the exact active operation-day employee';END IF;
   PERFORM public.static_weekly_approved_dated_assert_window(availability->'shift','dated shift');
   PERFORM public.static_weekly_approved_dated_assert_window(availability->'lunch','dated lunch');
   -- Flexible responsibility is not an appointment. Fixed work and accepted
   -- stops instead share one independently reconstructed chronological route.
   route:=coalesce(availability->'acceptedRoute','{}'::jsonb);
   route_start:=coalesce(route->>'startLocationId',route->>'start_location_id',availability->>'acceptedRouteStartLocationId',
    availability->>'acceptedRouteAnchorLocationId',availability->>'routeAnchorLocationId');
   route_provenance:=coalesce(route->>'provenance',availability->>'acceptedRouteProvenance');
   stops:=coalesce(route->'stops',route->'existingStops',availability->'acceptedRouteStops','[]'::jsonb);
   IF jsonb_typeof(route) IS DISTINCT FROM 'object' OR jsonb_typeof(stops) IS DISTINCT FROM 'array'
    OR nullif(route_start,'') IS NULL OR nullif(route_provenance,'') IS NULL
    OR jsonb_typeof(coalesce(availability->'blockedWindows','[]'::jsonb)) IS DISTINCT FROM 'array'
    OR nullif(availability->>'productiveCapacityProvenance','') IS NULL
    OR nullif(availability->>'maxServiceEffortProvenance','') IS NULL
    OR nullif(availability->>'qualificationProvenance','') IS NULL
    OR nullif(availability->>'restrictionProvenance','') IS NULL
    OR jsonb_typeof(availability->'qualifications') IS DISTINCT FROM 'array'
    OR jsonb_typeof(availability->'restrictions') IS DISTINCT FROM 'array'
    OR availability#>>'{lunch,start}'<availability#>>'{shift,start}'
    OR availability#>>'{lunch,end}'>availability#>>'{shift,end}' THEN
    RAISE EXCEPTION 'Dated current duty route and eligibility provenance invalid';END IF;
   shift_start:=extract(epoch FROM (availability#>>'{shift,start}')::time)::integer/60;
   shift_end:=extract(epoch FROM (availability#>>'{shift,end}')::time)::integer/60;
   protected_windows:=coalesce(availability->'blockedWindows','[]'::jsonb)||jsonb_build_array(availability->'lunch');
   FOR blocked IN SELECT value FROM jsonb_array_elements(protected_windows) LOOP
    PERFORM public.static_weekly_approved_dated_assert_window(blocked,'dated protected interval');
   END LOOP;
   -- Union clipped lunch/blocked intervals: overlaps are not double charged.
   cursor_minute:=shift_start;protected_minutes:=0;
   FOR blocked IN SELECT value FROM jsonb_array_elements(protected_windows) ORDER BY value->>'start',value->>'end' LOOP
    block_start:=greatest(shift_start,extract(epoch FROM (blocked->>'start')::time)::integer/60);
    block_end:=least(shift_end,extract(epoch FROM (blocked->>'end')::time)::integer/60);
    IF block_end>greatest(cursor_minute,block_start) THEN
     protected_minutes:=protected_minutes+block_end-greatest(cursor_minute,block_start);cursor_minute:=block_end;
    END IF;
   END LOOP;
   productive:=shift_end-shift_start-protected_minutes;
   duty:=coalesce((availability->>'maxDutyMinutes')::numeric,(availability->>'max_duty_minutes')::numeric,productive);
   IF productive<=0 OR duty<=0 OR duty>productive OR duty<>trunc(duty)
    OR ((availability ? 'maxDutyMinutes' OR availability ? 'max_duty_minutes')
     AND nullif(coalesce(availability->>'maxDutyProvenance',availability->>'max_duty_provenance'),'') IS NULL)
    OR jsonb_typeof(availability->'maxServiceEffortMinutes') IS DISTINCT FROM 'number'
    OR (availability->>'maxServiceEffortMinutes')::numeric<=0
    OR (availability->>'maxServiceEffortMinutes')::numeric<>trunc((availability->>'maxServiceEffortMinutes')::numeric) THEN
    RAISE EXCEPTION 'Dated independent duty or workload capacity invalid';END IF;
   nodes:='[]'::jsonb;stop_effort:=0;committed_duty:=0;
   FOR stop IN SELECT value FROM jsonb_array_elements(stops) LOOP
    PERFORM public.static_weekly_v3_assert_window(stop->'window','dated accepted stop');
    node_start:=extract(epoch FROM (stop#>>'{window,start}')::time)::integer/60;
    node_end:=extract(epoch FROM (stop#>>'{window,end}')::time)::integer/60;
    stop_duration:=node_end-node_start;
    IF nullif(coalesce(stop->>'locationId',stop->>'location'),'') IS NULL
     OR nullif(coalesce(stop->>'provenance',route_provenance),'') IS NULL
     OR nullif(coalesce(stop->>'serviceEffortProvenance',stop->>'service_effort_provenance',stop->>'provenance',route_provenance),'') IS NULL
     OR node_start<shift_start OR node_end>shift_end
     OR coalesce((stop->>'serviceEffortMinutes')::numeric,(stop->>'service_effort_minutes')::numeric,stop_duration)<=0
     OR coalesce((stop->>'serviceEffortMinutes')::numeric,(stop->>'service_effort_minutes')::numeric,stop_duration)>stop_duration
     OR coalesce((stop->>'serviceEffortMinutes')::numeric,(stop->>'service_effort_minutes')::numeric,stop_duration)<>
      trunc(coalesce((stop->>'serviceEffortMinutes')::numeric,(stop->>'service_effort_minutes')::numeric,stop_duration)) THEN
     RAISE EXCEPTION 'Dated accepted stop window effort or provenance invalid';END IF;
    stop_effort:=stop_effort+coalesce((stop->>'serviceEffortMinutes')::numeric,(stop->>'service_effort_minutes')::numeric,stop_duration);
    nodes:=nodes||jsonb_build_array(jsonb_build_object('start',node_start,'end',node_end,'location',coalesce(stop->>'locationId',stop->>'location')));
   END LOOP;
   staged_stop_nodes:=nodes;
   FOR route_pass IN 1..2 LOOP
   nodes:=staged_stop_nodes;baseline_travel:=0;committed_duty:=0;
   IF route_pass=2 THEN
    FOR work IN SELECT value FROM jsonb_array_elements(effective_work)
     WHERE value->'ownerSlotId'=slot->'id' AND value->>'dayOfWeek'=day::text AND NOT(value ? 'schedulingMode') LOOP
     PERFORM public.static_weekly_v3_assert_window(work->'window','dated fixed appointment');
     nodes:=nodes||jsonb_build_array(jsonb_build_object('start',extract(epoch FROM (work#>>'{window,start}')::time)::integer/60,
      'end',extract(epoch FROM (work#>>'{window,end}')::time)::integer/60,'location',work->>'locationId'));
    END LOOP;
   END IF;
   previous_end:=shift_start;previous_node:=jsonb_build_object('location',route_start);
   FOR node IN SELECT value FROM jsonb_array_elements(nodes) ORDER BY (value->>'start')::integer,(value->>'end')::integer,value->>'location' COLLATE "C" LOOP
    node_start:=(node->>'start')::integer;node_end:=(node->>'end')::integer;
    IF node_start<previous_end OR node_start<shift_start OR node_end>shift_end
     OR EXISTS(SELECT 1 FROM jsonb_array_elements(protected_windows) b
      WHERE extract(epoch FROM (b->>'start')::time)/60<node_end AND extract(epoch FROM (b->>'end')::time)/60>node_start) THEN
     RAISE EXCEPTION 'Dated fixed route overlaps another node lunch blocked interval or shift';END IF;
    travel:=NULL;
    IF previous_node->'location'=node->'location' THEN travel:=0;
    ELSE SELECT min((e->>'minutes')::integer) INTO travel FROM jsonb_array_elements(source->'proximity') e
     WHERE ((e->>'fromLocationId'=previous_node->>'location' AND e->>'toLocationId'=node->>'location')
      OR ((e->'bidirectional'='true'::jsonb OR e->'symmetric'='true'::jsonb)
       AND e->>'toLocationId'=previous_node->>'location' AND e->>'fromLocationId'=node->>'location'))
      AND e->'verified'='true'::jsonb AND jsonb_typeof(e->'minutes')='number'
      AND (e->>'minutes')::numeric>0 AND (e->>'minutes')::numeric=trunc((e->>'minutes')::numeric)
      AND nullif(e->>'provenance','') IS NOT NULL;
    END IF;
    cursor_minute:=previous_end;protected_minutes:=0;available_gap:=0;
    FOR blocked IN SELECT value FROM jsonb_array_elements(protected_windows) ORDER BY value->>'start',value->>'end' LOOP
     block_start:=greatest(previous_end,extract(epoch FROM (blocked->>'start')::time)::integer/60);
     block_end:=least(node_start,extract(epoch FROM (blocked->>'end')::time)::integer/60);
     IF block_end>block_start THEN
      available_gap:=greatest(available_gap,block_start-cursor_minute);
      protected_minutes:=protected_minutes+greatest(0,block_end-greatest(cursor_minute,block_start));
      cursor_minute:=greatest(cursor_minute,block_end);
     END IF;
    END LOOP;
    available_gap:=greatest(available_gap,node_start-cursor_minute);
    IF travel IS NULL OR (route_pass=1 AND node_start-previous_end<travel) OR (route_pass=2 AND available_gap<travel) THEN
     RAISE EXCEPTION 'Dated fixed route has no contiguous protected-safe directed transit';END IF;
    baseline_travel:=baseline_travel+travel;
    committed_duty:=committed_duty+node_end-node_start+travel+greatest(0,node_start-previous_end-travel-protected_minutes);
    previous_end:=node_end;previous_node:=node;
   END LOOP;
   IF route_pass=1 AND stop_effort+baseline_travel>productive THEN RAISE EXCEPTION 'Dated immutable accepted route baseline exceeds productive capacity';END IF;
   IF route_pass=2 AND committed_duty>duty THEN RAISE EXCEPTION 'Dated fixed service travel and committed waiting exceed duty capacity';END IF;
   END LOOP;
   route_count:=route_count+jsonb_array_length(stops);
   SELECT coalesce(sum((w->>'serviceEffortMinutes')::numeric),0) INTO effort
    FROM jsonb_array_elements(effective_work) w
    WHERE w->>'ownerSlotId'=slot->>'id' AND w->>'dayOfWeek'=day::text;
   IF effort+stop_effort>(availability->>'maxServiceEffortMinutes')::numeric THEN RAISE EXCEPTION 'Dated hard workload capacity including original stops exceeded';END IF;
  END IF;
 END LOOP;

 IF EXISTS((SELECT value FROM jsonb_array_elements(expected_availability) EXCEPT ALL SELECT value FROM jsonb_array_elements(authority->'projectionAvailability'))
  UNION ALL(SELECT value FROM jsonb_array_elements(authority->'projectionAvailability') EXCEPT ALL SELECT value FROM jsonb_array_elements(expected_availability)))
 THEN RAISE EXCEPTION 'Dated independently reconstructed full-week availability differs';END IF;
 SELECT count(*) INTO employee_count FROM jsonb_array_elements(roster) r WHERE r->>'serviceDate'=operation_date::text
  AND r->>'status'='working' AND r->>'incumbentPersonId' IS NOT NULL AND r->>'ownerKind' IS DISTINCT FROM 'CONTRACTOR_CAPACITY';
 IF employee_count<>entry.staffing_count OR EXISTS(SELECT 1 FROM jsonb_array_elements(roster) r
  WHERE r->>'serviceDate'=operation_date::text AND r->>'status'='working' AND r->>'incumbentPersonId' IS NOT NULL
  AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(authority#>'{mapping,slotMapping}') m
   WHERE m->'actualSlotId'=r->'slotId' AND m->'actualPersonId'=r->'incumbentPersonId'))
 THEN RAISE EXCEPTION 'Dated template must account for every current available operation-day employee';END IF;
 FOR work IN SELECT value FROM jsonb_array_elements(effective_work) LOOP
  day:=(work->>'dayOfWeek')::integer;
  SELECT value INTO STRICT person FROM jsonb_array_elements(roster) WHERE value->'slotId'=work->'ownerSlotId' AND value->>'dayOfWeek'=day::text;
  is_open:=closing_enabled AND person->>'status'='vacant_unfilled' AND person->>'incumbentPersonId' IS NULL
   AND position(':open:' in work->>'workId')>0;
  SELECT value INTO STRICT owner_config FROM jsonb_each(config->'slots') WHERE value->'slotId'=work->'ownerSlotId'
   AND (p_date+mod(day+6,7)<>operation_date OR value->'personId'=person->'incumbentPersonId'
    OR (is_open AND value->'vacancy'='true'::jsonb AND value->>'personId' IS NULL));
  PERFORM public.static_weekly_v3_assert_window(work->'window','dated independently derived work');
  IF (work ? 'schedulingMode' AND work->'schedulingMode' IS DISTINCT FROM '"flexible_coverage_ownership"'::jsonb)
   OR (NOT is_open AND (person->>'status' IS DISTINCT FROM 'working' OR person->>'incumbentPersonId' IS NULL))
   OR jsonb_typeof(work->'serviceEffortMinutes') IS DISTINCT FROM 'number'
   OR jsonb_typeof(work->'requiredQualifications') IS DISTINCT FROM 'array'
   OR jsonb_typeof(work->'restrictions') IS DISTINCT FROM 'array'
   OR nullif(work->>'qualificationProvenance','') IS NULL OR nullif(work->>'restrictionProvenance','') IS NULL
   OR (coalesce(work->'required','true'::jsonb) NOT IN('true'::jsonb,'false'::jsonb))
   OR (coalesce(work->'required','true'::jsonb)='true'::jsonb AND (jsonb_typeof(work->'priority') IS DISTINCT FROM 'number'
    OR (work->>'priority')::numeric<>trunc((work->>'priority')::numeric) OR nullif(work->>'priorityProvenance','') IS NULL))
   OR (work->>'serviceEffortMinutes')::numeric<=0 OR (work->>'serviceEffortMinutes')::numeric<>trunc((work->>'serviceEffortMinutes')::numeric)
   OR nullif(work->>'serviceEffortProvenance','') IS NULL
   OR (NOT(work ? 'schedulingMode') AND (work->>'serviceEffortMinutes')::numeric>
    extract(epoch FROM ((work#>>'{window,end}')::time-(work#>>'{window,start}')::time))/60)
   OR work#>>'{window,start}'<person#>>'{shift,start}' OR work#>>'{window,end}'>person#>>'{shift,end}'
   OR NOT(person->'qualifications' @> coalesce(work->'requiredQualifications','[]'::jsonb))
   OR coalesce(work->'restrictedSlotIds','[]'::jsonb) ? (work->>'ownerSlotId')
   OR coalesce(owner_config->'hardForbiddenFamilies','[]'::jsonb) ? (work->>'locationCodeSnapshot')
   OR (person->'restrictions') ? (work->>'locationId')
   OR (work->'_datedManualLock'<>'null'::jsonb AND work->'ownerSlotId' IS DISTINCT FROM work->'_datedManualLock')
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(work->'includedLocations','[]'::jsonb)) l WHERE (person->'restrictions') ? (l->>'locationId')) THEN
   RAISE EXCEPTION 'Dated independent fixed owner eligibility or work window differs';END IF;
  route_start:=coalesce(person#>>'{acceptedRoute,startLocationId}',person#>>'{acceptedRoute,start_location_id}',person->>'acceptedRouteStartLocationId',
   person->>'acceptedRouteAnchorLocationId',person->>'routeAnchorLocationId');
  IF work->>'schedulingMode'='flexible_coverage_ownership' AND work->>'serviceMode'<>'reminder_only' AND route_start IS DISTINCT FROM work->>'locationId'
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(source->'proximity') edge
    WHERE ((edge->>'fromLocationId'=route_start AND edge->>'toLocationId'=work->>'locationId')
     OR ((edge->'bidirectional'='true'::jsonb OR edge->'symmetric'='true'::jsonb) AND edge->>'toLocationId'=route_start AND edge->>'fromLocationId'=work->>'locationId'))
     AND edge->'verified'='true'::jsonb AND jsonb_typeof(edge->'minutes')='number'
     AND (edge->>'minutes')::numeric>=0 AND (edge->>'minutes')::numeric=trunc((edge->>'minutes')::numeric)
     AND nullif(edge->>'provenance','') IS NOT NULL) THEN
   RAISE EXCEPTION 'Dated fixed flexible area lacks exact verified directed geography';END IF;
  IF (person->>'incumbentPersonId',person->>'slotId') IN(
    ('3da709bb-2223-4e15-8e3a-db02e3f32e97','f22348e9-d4b9-5a7e-b8fd-d0d2c1ec534f'),
    ('cd97111e-cfa0-4228-b4d7-401bc7a5ac13','4a5a83ca-d297-5a30-8344-db08d05b978c'),
    ('30ec85e0-a579-45a8-9c27-c164e77a9190','55e5939c-175c-5026-94fd-c4350d538922'))
   AND NOT(coalesce(owner_config->'normalAssignmentFamilies','[]'::jsonb) ? (work->>'locationCodeSnapshot')) THEN
   RAISE EXCEPTION 'Dated original personal geography differs';END IF;
  SELECT value INTO baseline_person FROM jsonb_array_elements(roster) WHERE value->'slotId'=work->'originSlotId' AND value->>'dayOfWeek'=day::text;
  d:=p_date+mod(day+6,7);identity_key:=day::text||':'||(work->>'workId');
  IF is_open THEN work:=work||'{"required":false,"priority":0}'::jsonb;END IF;
  normalized_work:=jsonb_build_object('workId',work->'workId','dayOfWeek',day,'originSlotId',work->'originSlotId',
   'locationId',work->'locationId','locationCodeSnapshot',work->'locationCodeSnapshot','locationNameSnapshot',work->'locationNameSnapshot',
   'serviceMode',work->'serviceMode','includedLocations',work->'includedLocations','window',work->'window',
   'serviceEffortMinutes',work->'serviceEffortMinutes','serviceEffortProvenance',work->'serviceEffortProvenance',
   'priority',CASE WHEN work->'required'='false'::jsonb THEN '0'::jsonb ELSE work->'priority' END,
   'priorityProvenance',work->'priorityProvenance','required',coalesce(work->'required','true'::jsonb),
   'coveragePolicy',work->'coveragePolicy','bestEffortCoverage',coalesce(work->'required'='false'::jsonb,false) AND
    (coalesce(work->'coveragePolicy'='"best_effort"'::jsonb,false) OR coalesce(work->'bestEffortCoverage'='true'::jsonb,false)),
   'coveragePolicyOrder',CASE WHEN work->'required'='false'::jsonb AND
    (work->>'coveragePolicy'='best_effort' OR work->'bestEffortCoverage'='true'::jsonb) THEN coalesce(work->'coveragePolicyOrder','1'::jsonb) ELSE 'null'::jsonb END,
   'coveragePolicyProvenance',work->'coveragePolicyProvenance',
   'requiredQualifications',coalesce(work->'requiredQualifications','[]'::jsonb),'qualificationProvenance',work->'qualificationProvenance',
   'restrictions',coalesce(work->'restrictions','[]'::jsonb),'restrictionProvenance',work->'restrictionProvenance',
   'restrictedSlotIds',coalesce(work->'restrictedSlotIds','[]'::jsonb),'manualLock',work->'_datedManualLock'<>'null'::jsonb,
   'manualLockSlotId',work->'_datedManualLock','overlayWork',work->'_datedOverlayWork');
  expected_projection:=expected_projection||jsonb_build_array(jsonb_build_object('plan_work_id',identity_key,'work_id',work->'workId',
   'day_of_week',day,'service_date',d::text,'status',CASE WHEN is_open THEN 'open' ELSE 'assigned' END,'reason_code',CASE WHEN is_open THEN 'permitted_open' ELSE NULL END,
   'owner_slot_id',CASE WHEN is_open THEN NULL ELSE work->'ownerSlotId' END,'owner_person_id',person->'incumbentPersonId',
   'owner_digest',public.static_weekly_digest_jsonb(jsonb_build_object('planWorkId',identity_key,'slotId',CASE WHEN is_open THEN NULL ELSE work->'ownerSlotId' END,'personId',person->'incumbentPersonId','serviceDate',d::text)),
   'exact_owner_identity',public.static_weekly_digest_jsonb(jsonb_build_object('plan_work_id',identity_key,'service_date',d::text,
    'optimized_owner_slot_id',CASE WHEN is_open THEN NULL ELSE work->'ownerSlotId' END,'optimized_owner_person_id',person->'incumbentPersonId',
    'baseline_owner_slot_id',work->'originSlotId','baseline_owner_person_id',baseline_person->'incumbentPersonId')),
   'baseline_owner_slot_id',work->'originSlotId','baseline_owner_person_id',baseline_person->'incumbentPersonId','baseline_owner_name',baseline_person->'incumbentName',
   'original_actor_person_id',baseline_person->'incumbentPersonId','original_actor_name',baseline_person->'incumbentName',
   'optimized_owner_slot_id',CASE WHEN is_open THEN NULL ELSE work->'ownerSlotId' END,'optimized_owner_person_id',person->'incumbentPersonId','work_snapshot',normalized_work,
   'explanation',jsonb_build_object('contract','fixed_approved_pattern','hardConstraints','satisfied','reasons',CASE WHEN is_open THEN '[{"code":"permitted_open"}]'::jsonb ELSE '[]'::jsonb END)));
 END LOOP;

 IF EXISTS((SELECT value FROM jsonb_array_elements(expected_projection) EXCEPT ALL SELECT value FROM jsonb_array_elements(p_envelope->'assignments'))
  UNION ALL(SELECT value FROM jsonb_array_elements(p_envelope->'assignments') EXCEPT ALL SELECT value FROM jsonb_array_elements(expected_projection)))
  OR jsonb_array_length(expected_projection)=0 THEN RAISE EXCEPTION 'Dated exact independently derived relational rows differ';END IF;
 -- A work ID alone is not a physical parent. Keep actual stored links only
 -- for an exact original parent (owner substitution alone is allowed).
 -- Selected-day regrouping has NO fabricated one-to-one original assignment.
 FOR work IN SELECT value FROM jsonb_array_elements(effective_work) LOOP
  day:=(work->>'dayOfWeek')::integer;identity_key:=day::text||':'||(work->>'workId');original_assignment:=NULL;
  IF closing_enabled THEN
   IF day=operation_day THEN
    parent_id:=closing_result#>>ARRAY['selectedParentLinks',identity_key];
    SELECT value->'originalParent' INTO STRICT raw_parent FROM jsonb_array_elements(closing#>'{selected,parentReferences}')
     WHERE value->>'parentWorkId'=parent_id;
   ELSE
    SELECT c->>'parentWorkId' INTO STRICT parent_id FROM jsonb_array_elements(closing#>'{originalReceipt,parentChains}') c
     WHERE c->>'dayOfWeek'=day::text AND EXISTS(SELECT 1 FROM jsonb_array_elements(c->'segments') s WHERE s->'workId'=work->'workId');
    SELECT value INTO STRICT raw_parent FROM jsonb_array_elements(live_source#>'{version,assignments}')
     WHERE value->>'dayOfWeek'=day::text AND value->>'workId'=parent_id;
   END IF;
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(live_source#>'{version,assignments}') original
    WHERE original->>'dayOfWeek'=day::text AND original->>'workId'=parent_id AND original-'ownerSlotId'=raw_parent-'ownerSlotId') THEN
    SELECT assignment_id INTO STRICT original_assignment FROM public.weekly_schedule_slot_assignments
     WHERE version_id=current_source.version_id AND day_of_week=day AND work_id=parent_id;
   ELSIF day<>operation_day THEN RAISE EXCEPTION 'Dated closing unaffected original parent link differs';END IF;
  ELSIF EXISTS(SELECT 1 FROM jsonb_array_elements(effective_original) original
   WHERE original->'dayOfWeek'=work->'dayOfWeek' AND original->'workId'=work->'workId'
    AND original-'ownerSlotId'=work-'ownerSlotId') THEN
   -- An accepted event addition has an immutable command origin, not a
   -- fabricated stored baseline assignment; patches keep their actual parent.
   IF work->'_datedOverlayWork'='false'::jsonb THEN
    SELECT assignment_id INTO STRICT original_assignment FROM public.weekly_schedule_slot_assignments
     WHERE version_id=current_source.version_id AND day_of_week=day AND work_id=work->>'workId';
   END IF;
  ELSIF day<>operation_day THEN RAISE EXCEPTION 'Dated unaffected original parent link differs';END IF;
  assignment_links:=assignment_links||jsonb_build_object(identity_key,original_assignment);
 END LOOP;
 IF p_envelope->'adapter' IS DISTINCT FROM '{"schema":"custodial.approved-static-dated-adapter.v1","version":"approved-static-dated-v1"}'::jsonb
  OR p_envelope->>'service_date' IS DISTINCT FROM p_week::text OR p_envelope->>'week_start' IS DISTINCT FROM p_week::text
  OR p_envelope->>'week_end' IS DISTINCT FROM (p_week+6)::text
  OR p_envelope->>'compiler_version' IS DISTINCT FROM 'approved-static-dated-v1'
  OR p_envelope->'objective' IS DISTINCT FROM '{"contract":"FIXED_APPROVED_PATTERN_NOT_OPTIMALITY"}'::jsonb
  OR authority->>'schema' IS DISTINCT FROM 'custodial.approved-static-authority.v1'
  OR authority->>'effectiveDate' IS DISTINCT FROM p_week::text
  OR authority->'solverInvoked' IS DISTINCT FROM 'false'::jsonb OR authority->'optimized' IS DISTINCT FROM 'false'::jsonb
  OR authority ? 'optimizerResult'
  OR authority->>'baselineInputDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(baseline)
  OR authority->>'mappedBaselineInputDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(jsonb_set(source,'{exceptions}','[]'::jsonb))
  OR authority->>'derivedBaselineDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(CASE WHEN closing_enabled THEN closing->'originalDerivedInput' ELSE baseline END)
  OR authority->>'inputDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(source)
  OR authority->>'originalInputDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(authority->'originalWeekCompilerInput')
  OR p_envelope->>'authority_digest' IS DISTINCT FROM public.static_weekly_digest_jsonb(authority)
  OR p_envelope->>'database_projection_identity' IS DISTINCT FROM public.static_weekly_digest_jsonb(p_envelope-'database_projection_identity')
  OR authority->'weekDerivation' IS DISTINCT FROM jsonb_build_object(
   'schema','custodial.approved-static-dated-week-derivation.v1','operationDate',operation_date::text,
   'weekStart',p_week::text,'weekEnd',(p_week+6)::text,'originalSourceDigest',public.static_weekly_digest_jsonb(authority->'originalCompilerInput'),
   'originalWeekInputDigest',authority->'originalInputDigest','mappedWeekInputDigest',authority->'inputDigest')
  OR p_envelope->'semantic_snapshot' IS DISTINCT FROM jsonb_build_object(
   'schema','custodial.approved-static-dated-projection-snapshot.v1','sourcePublicationId',p_publication_id::text,
   'sourceVersionId',live_source#>>'{version,id}','serviceDate',operation_date::text,'weekStart',p_week::text,'weekEnd',(p_week+6)::text,
   'sourceDigest',public.static_weekly_digest_jsonb(authority->'originalCompilerInput'),
   'feasibilityDigest',p_envelope#>'{receipt,feasibilityDigest}','original_baseline_digest',authority->'baselineInputDigest',
   'applied_exceptions_digest',public.static_weekly_digest_jsonb(p_exceptions))
  OR p_envelope#>>'{receipt,schema}' IS DISTINCT FROM 'custodial.approved-static-feasibility-receipt.v1'
  OR p_envelope#>'{receipt,independentDerivations}' IS DISTINCT FROM '2'::jsonb
  OR p_envelope#>'{receipt,solverInvoked}' IS DISTINCT FROM 'false'::jsonb OR p_envelope#>'{receipt,optimized}' IS DISTINCT FROM 'false'::jsonb
  OR jsonb_typeof(p_envelope#>'{receipt,hardConstraintCount}') IS DISTINCT FROM 'number'
  OR (p_envelope#>>'{receipt,hardConstraintCount}')::numeric NOT BETWEEN jsonb_array_length(expected_projection) AND 100000
  OR (p_envelope#>>'{receipt,hardConstraintCount}')::numeric<>trunc((p_envelope#>>'{receipt,hardConstraintCount}')::numeric)
  OR p_envelope->'metrics' IS DISTINCT FROM jsonb_build_object('hardConstraints',p_envelope#>'{receipt,hardConstraintCount}','violations',0)
 THEN RAISE EXCEPTION 'Dated envelope identities or fixed semantics differ';END IF;
 RETURN jsonb_build_object('source_id',v_source_id,'projection_assignments',expected_projection,
  'assignment_links',assignment_links,'staffing_count',employee_count,'operation_date',operation_date,'version_id',current_source.version_id);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_pending_assert_lunch(p_operation uuid, p_manager uuid, p_publication uuid, p_week date, p_envelope jsonb, p_document jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 PERFORM public.static_weekly_pending_assert_projection(p_operation,p_manager,p_envelope);
 IF p_envelope#>>'{semantic_snapshot,originalSource,publication_id}' IS DISTINCT FROM p_publication::text
  OR p_envelope->>'week_start' IS DISTINCT FROM p_week::text THEN RAISE EXCEPTION 'Pending lunch original publication or week differs';END IF;
 IF p_envelope->>'replay_digest' IS DISTINCT FROM public.static_weekly_digest_jsonb(jsonb_build_object(
  'projectionAssignments',p_envelope->'assignments','lunchDocument',p_document-ARRAY['base_authority_digest','base_replay_digest','document_identity']))
 THEN RAISE EXCEPTION 'Pending complete merged lunch replay differs';END IF;
 IF p_envelope#>>'{semantic_snapshot,schema}'='custodial.approved-manual-pending-staffing-snapshot.v1' THEN
  PERFORM public.static_weekly_manual_assert_native_lunch(NULL,p_document,p_envelope,p_publication,p_week);
 ELSE PERFORM public.static_weekly_pending_lunch_derivation(NULL,p_document,p_envelope,p_publication,p_week,p_operation);END IF;
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_pending_assert_projection(p_operation uuid, p_manager uuid, p_envelope jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE ctx jsonb;c public.static_weekly_staffing_commands%rowtype;snapshot jsonb;source jsonb;before_source jsonb;
 publication uuid;week date;date date;expected_dates jsonb;part jsonb;proof jsonb;first_projection jsonb;chosen jsonb;
 expected_rows jsonb:='[]';expected_availability jsonb:='[]';expected_work jsonb:='[]';links jsonb:='{}';item jsonb;
 basis jsonb;first_basis jsonb;summary jsonb;effective jsonb;actual jsonb;expected jsonb;
BEGIN
 IF p_envelope#>>'{semantic_snapshot,schema}'='custodial.approved-manual-pending-staffing-snapshot.v1' THEN
  RETURN public.static_weekly_coverall_assert_dispatch(p_operation,p_manager,p_envelope);END IF;
 ctx:=public.static_weekly_pending_context(p_operation,p_manager);
 SELECT * INTO STRICT c FROM public.static_weekly_staffing_commands WHERE operation_id=p_operation;
 PERFORM public.static_weekly_assert_exact_object(p_envelope,
  ARRAY['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','semantic_snapshot','database_projection_identity'],
  ARRAY['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','semantic_snapshot','database_projection_identity'],'pending projection');
 snapshot:=p_envelope->'semantic_snapshot';
 PERFORM public.static_weekly_assert_exact_object(snapshot,
  ARRAY['schema','originalCommand','originalSource','scopeDates','weekStart','generation','templateCatalogDigest','templateInputsDigest','partitions'],
  ARRAY['schema','originalCommand','originalSource','scopeDates','weekStart','generation','templateCatalogDigest','templateInputsDigest','partitions'],'pending original snapshot');
 IF snapshot->>'schema' IS DISTINCT FROM 'custodial.approved-static-pending-staffing-projection-snapshot.v1'
  OR snapshot->'originalCommand' IS DISTINCT FROM ctx->'originalCommand'
  OR coalesce(snapshot->>'weekStart','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
 THEN RAISE EXCEPTION 'Pending original tuple differs';END IF;
 week:=(snapshot->>'weekStart')::date;
 IF NOT isfinite(week) OR extract(isodow FROM week)<>1 OR week>c.end_date OR week+6<c.start_date THEN RAISE EXCEPTION 'Pending original week differs';END IF;
 publication:=(snapshot#>>'{originalSource,publication_id}')::uuid;
 source:=public.static_weekly_v3_read_publication_source(publication,week);
 before_source:=jsonb_set(jsonb_set(source,'{authority_revision}',to_jsonb(c.expected_revision),false),'{exceptions}',
  public.static_weekly_pending_original_exception_set(publication,week,p_operation),false);
 IF snapshot->'originalSource' IS DISTINCT FROM before_source OR public.static_weekly_effective_version(week+6)::text IS DISTINCT FROM source->>'version_id'
 THEN RAISE EXCEPTION 'Pending original accepted Source differs';END IF;
 SELECT jsonb_agg(d::date::text ORDER BY d) INTO expected_dates
  FROM generate_series(greatest(c.start_date,week),least(c.end_date,week+6),'1 day') d;
 IF snapshot->'scopeDates' IS DISTINCT FROM expected_dates OR jsonb_typeof(snapshot->'partitions') IS DISTINCT FROM 'array'
  OR jsonb_array_length(snapshot->'partitions')<>jsonb_array_length(expected_dates)
 THEN RAISE EXCEPTION 'Pending complete original day partitions required';END IF;
 FOR part IN SELECT value FROM jsonb_array_elements(snapshot->'partitions') WITH ORDINALITY x(value,n) ORDER BY n LOOP
  PERFORM public.static_weekly_assert_exact_object(part,ARRAY['serviceDate','projection'],ARRAY['serviceDate','projection'],'pending day partition');
  IF jsonb_typeof(part->'serviceDate') IS DISTINCT FROM 'string' OR NOT(expected_dates ? (part->>'serviceDate'))
   OR (SELECT count(*) FROM jsonb_array_elements(snapshot->'partitions') p WHERE p->'serviceDate'=part->'serviceDate')<>1
   OR part#>'{projection,authority,scopeDates}' IS DISTINCT FROM jsonb_build_array(part->'serviceDate')
  THEN RAISE EXCEPTION 'Pending duplicate or foreign day partition';END IF;
  date:=(part->>'serviceDate')::date;
  basis:=public.static_weekly_read_approved_template_basis(p_manager,publication,date,'DATED_ABSENCE',NULL,
   CASE WHEN (ctx->>'afterFact')::boolean THEN c.expected_revision+1 ELSE c.expected_revision END);
  IF first_basis IS NULL THEN first_basis:=basis;END IF;
  IF basis->'generation' IS DISTINCT FROM snapshot->'generation'
   OR basis->'templateCatalogDigest' IS DISTINCT FROM snapshot->'templateCatalogDigest'
   OR basis->'templateInputsDigest' IS DISTINCT FROM snapshot->'templateInputsDigest'
   OR basis->'ownerConfig' IS DISTINCT FROM first_basis->'ownerConfig'
  THEN RAISE EXCEPTION 'Pending approved catalog config or generation differs';END IF;
  summary:=public.static_weekly_pending_applied_summary(p_operation,publication,week,date);
  proof:=public.static_weekly_pending_assert_day(p_operation,part->'projection',publication,week,summary);
  IF first_projection IS NULL THEN first_projection:=part->'projection';END IF;
 END LOOP;
 -- Deterministic disjoint composition: one source for every changed day and
 -- the exact same original six-day rows for every component's unaffected day.
 FOR date IN SELECT generate_series(week,week+6,'1 day')::date LOOP
  SELECT value->'projection' INTO chosen FROM jsonb_array_elements(snapshot->'partitions') WHERE value->>'serviceDate'=date::text;
  IF NOT FOUND THEN
   chosen:=first_projection;
   FOR part IN SELECT value FROM jsonb_array_elements(snapshot->'partitions') LOOP
    SELECT coalesce(jsonb_agg(r ORDER BY n),'[]') INTO actual FROM jsonb_array_elements(part#>'{projection,assignments}') WITH ORDINALITY x(r,n) WHERE r->>'service_date'=date::text;
    SELECT coalesce(jsonb_agg(r ORDER BY n),'[]') INTO expected FROM jsonb_array_elements(chosen->'assignments') WITH ORDINALITY x(r,n) WHERE r->>'service_date'=date::text;
    IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Pending unaffected original day changed';END IF;
   END LOOP;
  END IF;
  proof:=public.static_weekly_pending_assert_day(p_operation,chosen,publication,week,
   public.static_weekly_pending_applied_summary(p_operation,publication,week,(chosen#>>'{authority,scopeDates,0}')::date));
  SELECT expected_rows||coalesce(jsonb_agg(r ORDER BY n),'[]') INTO expected_rows FROM jsonb_array_elements(chosen->'assignments') WITH ORDINALITY x(r,n) WHERE r->>'service_date'=date::text;
  FOR item IN SELECT value FROM jsonb_array_elements(chosen->'assignments') WHERE value->>'service_date'=date::text LOOP
   links:=links||jsonb_build_object(item->>'plan_work_id',proof#>ARRAY['assignment_links',item->>'plan_work_id']);
  END LOOP;
  SELECT expected_availability||coalesce(jsonb_agg(r ORDER BY n),'[]') INTO expected_availability
   FROM jsonb_array_elements(chosen#>'{authority,projectionAvailability}') WITH ORDINALITY x(r,n) WHERE r->>'serviceDate'=date::text;
  SELECT expected_work||coalesce(jsonb_agg(r ORDER BY n),'[]') INTO expected_work
   FROM jsonb_array_elements(chosen#>'{authority,overlayCompilerInput,version,assignments}') WITH ORDINALITY x(r,n) WHERE r->>'dayOfWeek'=extract(dow FROM date)::text;
 END LOOP;
 SELECT jsonb_agg(r ORDER BY (r->>'dayOfWeek')::integer,r->>'slotId' COLLATE "C") INTO expected_availability FROM jsonb_array_elements(expected_availability) r;
 SELECT jsonb_agg(r ORDER BY (r->>'dayOfWeek')::integer,r->>'workId' COLLATE "C") INTO expected_work FROM jsonb_array_elements(expected_work) r;
 effective:=jsonb_set(jsonb_set(first_projection#>'{authority,overlayCompilerInput}','{version,assignments}',expected_work,false),
  '{exceptions}',public.static_weekly_pending_exception_set(p_operation,publication,week,NULL),false);
 expected:=jsonb_build_object('schema','custodial.approved-static-pending-staffing-authority.v1','effectiveDate',week,
  'compilerInput',first_projection#>'{authority,compilerInput}','overlayCompilerInput',effective,
  'inputDigest',public.static_weekly_digest_jsonb(effective),'projectionAvailability',expected_availability,'solverInvoked',false,'optimized',false);
 IF p_envelope->'assignments' IS DISTINCT FROM expected_rows OR p_envelope->'authority' IS DISTINCT FROM expected
  OR p_envelope->>'authority_digest' IS DISTINCT FROM public.static_weekly_digest_jsonb(expected)
  OR p_envelope->>'database_projection_identity' IS DISTINCT FROM public.static_weekly_digest_jsonb(p_envelope-'database_projection_identity')
  OR p_envelope->'adapter' IS DISTINCT FROM '{"schema":"custodial.approved-static-pending-staffing-adapter.v1","version":"approved-static-pending-staffing-v1"}'::jsonb
  OR p_envelope->>'compiler_version' IS DISTINCT FROM 'approved-static-pending-staffing-v1'
  OR p_envelope->>'week_start' IS DISTINCT FROM week::text OR p_envelope->>'service_date' IS DISTINCT FROM week::text
  OR p_envelope->>'week_end' IS DISTINCT FROM (week+6)::text
  OR p_envelope->'objective' IS DISTINCT FROM '{"contract":"FIXED_APPROVED_PENDING_STAFFING_NOT_OPTIMALITY"}'::jsonb
  OR p_envelope->'applied_exceptions' IS DISTINCT FROM public.static_weekly_pending_applied_summary(p_operation,publication,week,NULL)
 THEN RAISE EXCEPTION 'Pending merged exact week projection or original relation differs';END IF;
 PERFORM public.static_weekly_assert_exact_object(p_envelope->'receipt',
  ARRAY['schema','hardConstraintCount','hardConstraintDigest','solverInvoked','optimized'],
  ARRAY['schema','hardConstraintCount','hardConstraintDigest','solverInvoked','optimized'],'pending fixed feasibility DATA');
 IF p_envelope#>>'{receipt,schema}' IS DISTINCT FROM 'custodial.approved-static-pending-feasibility.v1'
  OR p_envelope#>'{receipt,solverInvoked}' IS DISTINCT FROM 'false'::jsonb OR p_envelope#>'{receipt,optimized}' IS DISTINCT FROM 'false'::jsonb
  OR jsonb_typeof(p_envelope#>'{receipt,hardConstraintCount}') IS DISTINCT FROM 'number'
  OR (p_envelope#>>'{receipt,hardConstraintCount}')::numeric NOT BETWEEN jsonb_array_length(expected_rows) AND 100000
  OR (p_envelope#>>'{receipt,hardConstraintCount}')::numeric<>trunc((p_envelope#>>'{receipt,hardConstraintCount}')::numeric)
  OR coalesce(p_envelope#>>'{receipt,hardConstraintDigest}','')!~'^[0-9a-f]{64}$'
  OR coalesce(p_envelope->>'replay_digest','')!~'^[0-9a-f]{64}$'
  OR p_envelope->'metrics' IS DISTINCT FROM jsonb_build_object('hardConstraints',p_envelope#>'{receipt,hardConstraintCount}','violations',0)
 THEN RAISE EXCEPTION 'Pending fixed feasibility DATA malformed';END IF;
 IF (ctx->>'afterFact')::boolean AND public.static_weekly_pending_summary(p_operation,publication,week,NULL)
  IS DISTINCT FROM public.static_weekly_accepted_exception_set(publication,week)
 THEN RAISE EXCEPTION 'Pending original semantics did not become the exact accepted facts';END IF;
 IF public.static_weekly_pending_context(p_operation,p_manager) IS DISTINCT FROM ctx THEN RAISE EXCEPTION 'Pending native context changed';END IF;
 RETURN jsonb_build_object('assignment_links',links,'projection_assignments',expected_rows,'afterFact',ctx->'afterFact');
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_pending_context(p_operation uuid, p_manager uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.static_weekly_staffing_commands%rowtype;a public.static_weekly_staffing_absences%rowtype;
 original public.static_weekly_staffing_commands%rowtype;actor jsonb;revision bigint;after_fact boolean:=false;target jsonb:=NULL;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();
 actor:=public.static_weekly_v3_manager_actor(p_manager);
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 SELECT * INTO STRICT c FROM public.static_weekly_staffing_commands WHERE operation_id=p_operation FOR UPDATE;
 SELECT current_revision INTO STRICT revision FROM public.static_weekly_schedule_control WHERE singleton FOR SHARE;
 IF c.prepared_by_manager_id IS DISTINCT FROM p_manager OR c.state NOT IN('PREPARING','PREPARED')
  OR c.command_kind NOT IN('absence','cancel_absence') OR c.expected_revision NOT BETWEEN 0 AND 9007199254740990
  OR c.semantic_body IS DISTINCT FROM jsonb_build_object('absenceKind',c.absence_kind,'commandKind',c.command_kind,
   'employeeId',c.employee_id::text,'endDate',c.end_date::text,'startDate',c.start_date::text,'targetAbsenceId',c.target_absence_id)
  OR c.semantic_digest IS DISTINCT FROM public.static_weekly_digest_jsonb(c.semantic_body)
  OR c.end_date<c.start_date OR c.end_date-c.start_date>=366 OR c.start_date<public.sch_service_date(statement_timestamp())
 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Pending exact original command unavailable';END IF;
 IF c.command_kind='absence' THEN
  IF c.target_absence_id IS NOT NULL OR c.absence_kind NOT IN('daily_absence','pto','unavailable')
   OR NOT EXISTS(SELECT 1 FROM public.employees WHERE id=c.employee_id AND active) THEN RAISE EXCEPTION 'Pending employee or kind differs';END IF;
  SELECT * INTO a FROM public.static_weekly_staffing_absences WHERE absence_id=c.operation_id;
  IF FOUND THEN
   IF a.accepted_operation_id<>c.operation_id OR a.employee_id<>c.employee_id OR a.start_date<>c.start_date OR a.end_date<>c.end_date
    OR a.absence_kind<>c.absence_kind OR a.accepted_by_manager_id<>p_manager OR a.accepted_revision<>c.expected_revision+1
   THEN RAISE EXCEPTION 'Pending original accepted absence differs';END IF;
   after_fact:=true;
  END IF;
 ELSE
  IF c.absence_kind IS NOT NULL OR c.target_absence_id IS NULL THEN RAISE EXCEPTION 'Pending cancellation kind differs';END IF;
  SELECT * INTO STRICT a FROM public.static_weekly_staffing_absences WHERE absence_id=c.target_absence_id FOR SHARE;
  SELECT * INTO STRICT original FROM public.static_weekly_staffing_commands WHERE operation_id=a.accepted_operation_id FOR SHARE;
  IF a.absence_id<>a.accepted_operation_id OR a.employee_id<>c.employee_id OR c.start_date<>greatest(a.start_date,public.sch_service_date(statement_timestamp()))
   OR c.end_date<>a.end_date OR original.state<>'ACCEPTED' OR original.command_kind<>'absence'
   OR original.employee_id<>a.employee_id OR original.start_date<>a.start_date OR original.end_date<>a.end_date
   OR original.absence_kind<>a.absence_kind OR original.target_absence_id IS NOT NULL
   OR original.accepted_revision<>a.accepted_revision OR original.prepared_by_manager_id<>a.accepted_by_manager_id
   OR original.confirmed_by_manager_id<>a.accepted_by_manager_id
   OR original.semantic_digest<>public.static_weekly_digest_jsonb(original.semantic_body)
   OR original.semantic_body<>jsonb_build_object('absenceKind',a.absence_kind,'commandKind','absence','employeeId',a.employee_id::text,
    'endDate',a.end_date::text,'startDate',a.start_date::text,'targetAbsenceId',NULL)
   OR original.accepted_receipt->>'event' IS DISTINCT FROM 'ACCEPTED'
   OR original.accepted_receipt->>'operation_id' IS DISTINCT FROM original.operation_id::text
   OR original.accepted_receipt->>'semantic_digest' IS DISTINCT FROM original.semantic_digest
   OR original.accepted_receipt->>'authority_revision' IS DISTINCT FROM a.accepted_revision::text
  THEN RAISE EXCEPTION 'Pending original cancellation ledger differs';END IF;
  IF EXISTS(SELECT 1 FROM public.static_weekly_staffing_absence_cancellations x WHERE x.absence_id=a.absence_id
   AND (x.accepted_operation_id<>c.operation_id OR x.remaining_start_date<>c.start_date OR x.remaining_end_date<>c.end_date
    OR x.accepted_revision<>c.expected_revision+1 OR x.accepted_by_manager_id<>p_manager)) THEN RAISE EXCEPTION 'Pending target already cancelled or foreign';END IF;
  after_fact:=EXISTS(SELECT 1 FROM public.static_weekly_staffing_absence_cancellations WHERE absence_id=a.absence_id AND accepted_operation_id=c.operation_id);
  target:=jsonb_build_object('absenceId',a.absence_id,'employeeId',a.employee_id,'startDate',a.start_date,'endDate',a.end_date,
   'acceptedOperationId',a.accepted_operation_id,'status','accepted');
 END IF;
 IF after_fact THEN
  IF c.state<>'PREPARED' OR revision<>c.expected_revision+1
   OR current_setting('app.static_weekly_staffing_batch_operation',true) IS DISTINCT FROM c.operation_id::text
   OR NOT EXISTS(SELECT 1 FROM public.weekly_schedule_authority_revisions r WHERE r.authority_revision=revision
    AND r.command_id=c.operation_id AND r.operation='apply_staffing_command' AND r.actor_manager_id=p_manager)
  THEN RAISE EXCEPTION 'Pending original fact is outside its native acceptance transaction';END IF;
 ELSIF revision<>c.expected_revision THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Pending original revision changed';END IF;
 RETURN jsonb_build_object('originalCommand',jsonb_build_object('operationId',c.operation_id,'preparerId',c.prepared_by_manager_id,
  'semanticBody',c.semantic_body,'semanticDigest',c.semantic_digest,'expectedRevision',c.expected_revision,
  'currentServiceDate',public.sch_service_date(statement_timestamp()),'originalCancellationTarget',target),
  'afterFact',after_fact,'actor',actor);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_pending_day_source(p_operation uuid, p_publication uuid, p_week date, p_day date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE source jsonb;exceptions jsonb;
BEGIN
 source:=public.static_weekly_v3_read_publication_source(p_publication,p_week);
 exceptions:=public.static_weekly_pending_exception_set(p_operation,p_publication,p_week,p_day);
 RETURN jsonb_set(jsonb_set(source,'{exceptions}',exceptions,true),'{compiler_input,exceptions}',exceptions,true);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_pending_effective_work(p_operation uuid, p_day date, p_publication uuid, p_week date, p_source jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;accepted jsonb;e jsonb;payload jsonb;item jsonb;patch jsonb;prior jsonb;merged jsonb;locations jsonb;
 command public.weekly_schedule_exception_commands%rowtype;current_revision bigint;day integer;idx integer;key text;locks jsonb:='{}';
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 IF p_publication IS NULL OR p_week IS NULL OR NOT isfinite(p_week) OR extract(isodow FROM p_week)<>1
  OR p_source#>>'{version,publicationId}' IS DISTINCT FROM p_publication::text
  OR jsonb_typeof(p_source#>'{version,assignments}') IS DISTINCT FROM 'array'
  OR jsonb_array_length(p_source#>'{version,assignments}') NOT BETWEEN 1 AND 4096
 THEN RAISE EXCEPTION 'Dated effective work original bounded Source differs';END IF;
 accepted:=public.static_weekly_pending_exception_set(p_operation,p_publication,p_week,p_day);
 IF p_source->'exceptions' IS DISTINCT FROM accepted THEN RAISE EXCEPTION 'Dated effective work original exceptions differ';END IF;
 SELECT c.current_revision INTO STRICT current_revision FROM public.static_weekly_schedule_control c WHERE c.singleton;
 SELECT jsonb_agg(w||jsonb_build_object('_datedOverlayWork',false,'_datedCancelled',false,
  '_datedManualLock',NULL) ORDER BY n) INTO result
  FROM jsonb_array_elements(p_source#>'{version,assignments}') WITH ORDINALITY x(w,n);
 -- The native source producer orders by service date, immutable revision, ID.
 -- Within each day this is the compiler's original exception order.
 FOR e IN SELECT value FROM jsonb_array_elements(accepted) WITH ORDINALITY x(value,n) ORDER BY n LOOP
  IF e->>'type' NOT IN('event_impact','manager_correction','nine_forty_five_rebalance') THEN CONTINUE;END IF;
  SELECT * INTO STRICT command FROM public.weekly_schedule_exception_commands c
   WHERE c.exception_id::text=e->>'id' AND c.publication_id=p_publication
    AND c.base_version_id::text=p_source#>>'{version,id}' AND c.service_date::text=e->>'serviceDate'
    AND NOT EXISTS(SELECT 1 FROM public.weekly_schedule_exception_commands r WHERE r.reverses_exception_id=c.exception_id);
  IF e->>'status' IS DISTINCT FROM 'accepted' OR e->>'type' IS DISTINCT FROM command.exception_type
   OR e->'payload' IS DISTINCT FROM command.payload_json OR e->>'payloadDigest' IS DISTINCT FROM command.payload_digest
   OR command.payload_digest IS DISTINCT FROM public.static_weekly_digest_jsonb(command.payload_json)
   OR e->>'actorId' IS DISTINCT FROM command.actor_manager_id::text
   OR e->>'idempotencyKey' IS DISTINCT FROM command.idempotency_key
   OR e->'expectedRevision' IS DISTINCT FROM to_jsonb(command.expected_revision)
   OR e->'sequence' IS DISTINCT FROM to_jsonb(command.authority_revision)
   OR command.authority_revision<>command.expected_revision+1 OR command.authority_revision>current_revision
   OR command.starts_at IS NOT NULL OR command.ends_at IS NOT NULL
   OR command.service_date NOT BETWEEN p_week AND p_week+6
  THEN RAISE EXCEPTION 'Dated effective work accepted command provenance differs';END IF;
  payload:=command.payload_json;day:=extract(dow FROM command.service_date)::integer;
  IF command.exception_type IN('manager_correction','nine_forty_five_rebalance') THEN
   PERFORM public.static_weekly_assert_exact_object(payload,ARRAY['locks'],ARRAY['locks'],'dated original locks');
   IF jsonb_typeof(payload->'locks') IS DISTINCT FROM 'array' OR jsonb_array_length(payload->'locks')=0
   THEN RAISE EXCEPTION 'Dated original locks are empty';END IF;
   FOR item IN SELECT value FROM jsonb_array_elements(payload->'locks') LOOP
    PERFORM public.static_weekly_assert_exact_object(item,ARRAY['workId','slotId'],ARRAY['workId','slotId'],'dated original lock');
    PERFORM public.static_weekly_v3_assert_text(item->'workId','dated original lock work',160);
    PERFORM public.static_weekly_v3_assert_uuid(item->'slotId','dated original lock slot');
    key:=day::text||':'||(item->>'workId');
    IF locks ? key OR NOT public.static_weekly_exception_work_exists(command.base_version_id,command.service_date,item->>'workId')
     OR NOT public.static_weekly_exception_slot_exists(command.base_version_id,command.service_date,item->>'slotId',true)
    THEN RAISE EXCEPTION 'Dated original lock duplicate or target differs';END IF;
    locks:=locks||jsonb_build_object(key,item->'slotId');
   END LOOP;
  ELSE
   PERFORM public.static_weekly_assert_exact_object(payload,ARRAY['removeWorkIds','patchWork','addWork'],
    ARRAY['removeWorkIds','patchWork','addWork'],'dated original event command');
   PERFORM public.static_weekly_v3_assert_string_array(payload->'removeWorkIds','dated event removals',true,160);
   IF jsonb_typeof(payload->'patchWork') IS DISTINCT FROM 'array' OR jsonb_typeof(payload->'addWork') IS DISTINCT FROM 'array'
    OR jsonb_array_length(payload->'removeWorkIds')+jsonb_array_length(payload->'patchWork')+jsonb_array_length(payload->'addWork')=0
   THEN RAISE EXCEPTION 'Dated original event command arrays differ';END IF;
   IF EXISTS(SELECT 1 FROM(
    SELECT value#>>'{}' id FROM jsonb_array_elements(payload->'removeWorkIds')
    UNION ALL SELECT value->>'workId' FROM jsonb_array_elements(payload->'patchWork')
    UNION ALL SELECT value->>'workId' FROM jsonb_array_elements(payload->'addWork')) targets
    GROUP BY id HAVING id IS NULL OR count(*)<>1)
   THEN RAISE EXCEPTION 'Dated original event duplicate or overlapping target differs';END IF;
   FOR item IN SELECT value FROM jsonb_array_elements(payload->'removeWorkIds') LOOP
    IF NOT public.static_weekly_exception_work_exists(command.base_version_id,command.service_date,item#>>'{}')
    THEN RAISE EXCEPTION 'Dated event removed original target differs';END IF;
    SELECT coalesce(jsonb_agg(CASE WHEN w->>'dayOfWeek'=day::text AND w->'workId'=item
     THEN w||'{"_datedCancelled":true}'::jsonb ELSE w END ORDER BY n),'[]') INTO result
     FROM jsonb_array_elements(result) WITH ORDINALITY x(w,n);
   END LOOP;
   FOR patch IN SELECT value FROM jsonb_array_elements(payload->'patchWork') LOOP
    PERFORM public.static_weekly_v3_assert_work_payload(patch,false);
    IF NOT public.static_weekly_exception_work_exists(command.base_version_id,command.service_date,patch->>'workId')
    THEN RAISE EXCEPTION 'Dated event patched original target differs';END IF;
    SELECT (n-1)::integer,w INTO STRICT idx,prior FROM jsonb_array_elements(result) WITH ORDINALITY x(w,n)
     WHERE w->>'dayOfWeek'=day::text AND w->'workId'=patch->'workId';
    merged:=prior||patch;
    -- Exactly applyException's location-sensitive physical-member rule.
    IF NOT(patch ? 'includedLocations') AND patch->'locationId' IS DISTINCT FROM prior->'locationId'
    THEN merged:=merged-'includedLocations';END IF;
    IF coalesce(merged->>'serviceMode','scan_tracked')='scan_tracked' THEN
     locations:=coalesce(merged->'includedLocations',jsonb_build_array(jsonb_build_object(
      'locationId',merged->'locationId','locationNameSnapshot',merged->'locationNameSnapshot')));
    ELSE locations:=merged->'includedLocations';END IF;
    -- This normal native payload validator also checks exact member identities,
    -- service mode, finite effort/windows/qualifications and provenance.
    PERFORM public.static_weekly_v3_assert_work_payload(patch||jsonb_build_object(
     'serviceMode',coalesce(merged->'serviceMode','"scan_tracked"'::jsonb),'includedLocations',locations),false);
    result:=jsonb_set(result,ARRAY[idx::text],merged||jsonb_build_object('includedLocations',locations));
   END LOOP;
   FOR item IN SELECT value FROM jsonb_array_elements(payload->'addWork') LOOP
    PERFORM public.static_weekly_v3_assert_work_payload(item,true);
    IF item->>'dayOfWeek'<>day::text OR EXISTS(SELECT 1 FROM jsonb_array_elements(result) w
      WHERE w->>'dayOfWeek'=day::text AND w->'workId'=item->'workId')
     OR NOT public.static_weekly_exception_slot_exists(command.base_version_id,command.service_date,item->>'originSlotId',false)
    THEN RAISE EXCEPTION 'Dated event added original identity or date differs';END IF;
    locations:=coalesce(item->'includedLocations',jsonb_build_array(jsonb_build_object(
     'locationId',item->'locationId','locationNameSnapshot',item->'locationNameSnapshot')));
    result:=result||jsonb_build_array(item||jsonb_build_object('ownerSlotId',item->'originSlotId',
     'serviceMode',coalesce(item->'serviceMode','"scan_tracked"'::jsonb),'includedLocations',locations,
     '_datedOverlayWork',true,'_datedCancelled',false,'_datedManualLock',NULL));
   END LOOP;
  END IF;
  IF jsonb_array_length(result)>4096 THEN RAISE EXCEPTION 'Dated effective work bound exceeded';END IF;
 END LOOP;
 -- Regrouping is not permission to lose an accepted manual target. A command
 -- targeting work later cancelled by an accepted event still has its exact
 -- original state row here, just as the compiler retains it before filtering.
 IF EXISTS(SELECT 1 FROM jsonb_each(locks) l WHERE NOT EXISTS(
  SELECT 1 FROM jsonb_array_elements(result) w WHERE (w->>'dayOfWeek')||':'||(w->>'workId')=l.key))
 THEN RAISE EXCEPTION 'Dated accepted lock lost its exact mapped work target';END IF;
 SELECT coalesce(jsonb_agg(w||jsonb_build_object('_datedManualLock',locks->((w->>'dayOfWeek')||':'||(w->>'workId')))
  ORDER BY (w->>'dayOfWeek')::integer,w->>'workId' COLLATE "C"),'[]') INTO result
  FROM jsonb_array_elements(result) w WHERE w->'_datedCancelled'='false'::jsonb;
 IF (SELECT count(*) FROM jsonb_array_elements(result))<>
  (SELECT count(DISTINCT (w->>'dayOfWeek',w->>'workId')) FROM jsonb_array_elements(result) w)
 THEN RAISE EXCEPTION 'Dated effective duplicate work differs';END IF;
 IF accepted IS DISTINCT FROM public.static_weekly_compiler_exception_set(p_publication,p_week)
  OR current_revision IS DISTINCT FROM(SELECT c.current_revision FROM public.static_weekly_schedule_control c WHERE c.singleton)
 THEN RAISE EXCEPTION 'Dated effective work current original Source changed';END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_pending_exception_set(p_operation uuid, p_publication uuid, p_week date, p_day date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.static_weekly_staffing_commands%rowtype;facts jsonb;
BEGIN
 SELECT * INTO STRICT c FROM public.static_weekly_staffing_commands WHERE operation_id=p_operation;
 -- The original function retains all six-field/date/revision/roster checks.
 facts:=public.coverall_original_static_weekly_pending_exception_set(p_operation,p_publication,p_week,p_day);
 SELECT coalesce(jsonb_agg(e ORDER BY n),'[]') INTO facts FROM jsonb_array_elements(facts) WITH ORDINALITY x(e,n)
 WHERE (e->>'coverAllOperationId'=CASE WHEN c.command_kind='cancel_absence' THEN c.target_absence_id::text ELSE p_operation::text END
  AND (e->>'serviceDate')::date BETWEEN c.start_date AND c.end_date AND (p_day IS NULL OR e->>'serviceDate'=p_day::text)) IS NOT TRUE;
 RETURN public.static_weekly_coverall_sort_facts(facts||public.static_weekly_coverall_pending_facts(p_operation,c.prepared_by_manager_id,p_publication,p_week,p_day));
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_pending_lunch_base(p_projection_id uuid, p_document jsonb, p_envelope jsonb, p_publication uuid, p_week date)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
 projection public.weekly_schedule_compiled_projections%rowtype;
 loan jsonb;responsibility jsonb;segment jsonb;intent jsonb;availability jsonb;helper jsonb;
 base_work jsonb;expected jsonb;actual jsonb;helper_id text;identity_key text;
 start_time time;end_time time;
 projection_availability jsonb;projection_assignments jsonb;projection_work jsonb;
begin
 perform public.static_weekly_assert_exact_object(p_document,
  array['schema','persistence_authority','verification_status','week_start','base_authority_digest','base_replay_digest','source_input_digest','candidate_digest','loans','responsibilities','notification_intents','semantic_snapshot','document_identity'],
  array['schema','persistence_authority','verification_status','week_start','base_authority_digest','base_replay_digest','source_input_digest','candidate_digest','loans','responsibilities','notification_intents','semantic_snapshot','document_identity'],'lunch document');
 projection.publication_id:=p_publication;projection.week_start:=p_week;projection.projection_envelope:=p_envelope;projection.authority_digest:=p_envelope->>'authority_digest';projection.replay_digest:=p_envelope->>'replay_digest';

 projection_availability:=projection.projection_envelope#>'{authority,projectionAvailability}';
 projection_assignments:=projection.projection_envelope->'assignments';
 projection_work:=projection.projection_envelope#>'{authority,overlayCompilerInput,version,assignments}';

 if p_document->>'schema' is distinct from 'memphis-zoo.static-weekly-lunch-authority-document.v1'
  or p_document->>'persistence_authority' is distinct from 'NOT_PERSISTED'
  or p_document->>'verification_status' is distinct from 'VERIFIED'
  or p_document->>'week_start' is distinct from projection.week_start::text
  or p_document->>'base_authority_digest' is distinct from projection.authority_digest
  or p_document->>'base_replay_digest' is distinct from projection.replay_digest
  or p_document->>'source_input_digest' is distinct from projection.projection_envelope#>>'{authority,inputDigest}'
  or coalesce(p_document->>'candidate_digest','') !~ '^[0-9a-f]{64}$'
  or p_document->>'document_identity' is distinct from public.static_weekly_digest_jsonb(p_document-'document_identity') then
  raise exception 'lunch document is not bound to the exact verified projection';
 end if;
 foreach identity_key in array array['loans','responsibilities','notification_intents'] loop
  if jsonb_typeof(p_document->identity_key) is distinct from 'array'
   or jsonb_array_length(p_document->identity_key)>4096 then raise exception 'lunch document array invalid'; end if;
 end loop;
 expected:=jsonb_build_object('schema','memphis-zoo.static-weekly-lunch-semantic-snapshot.v1',
  'loans_digest',public.static_weekly_digest_jsonb(p_document->'loans'),
  'responsibilities_digest',public.static_weekly_digest_jsonb(p_document->'responsibilities'),
  'notification_intents_digest',public.static_weekly_digest_jsonb(p_document->'notification_intents'));
 if p_document->'semantic_snapshot' is distinct from expected then raise exception 'lunch semantic snapshot mismatch'; end if;
 if (select count(*)<>count(distinct value->>'loan_id') from jsonb_array_elements(p_document->'loans'))
 or (select count(*)<>count(distinct value->>'responsibility_id') from jsonb_array_elements(p_document->'responsibilities'))
 or (select count(*)<>count(distinct value->>'notification_key') from jsonb_array_elements(p_document->'notification_intents')) then
  raise exception 'duplicate or missing lunch record identity'; end if;
 select coalesce(jsonb_agg(jsonb_build_array(value->>'serviceDate',value->>'slotId') order by value->>'serviceDate',value->>'slotId'),'[]')
 into expected from jsonb_array_elements(projection_availability)
 where value->>'status'='working' and (nullif(value->>'incumbentPersonId','') is not null or value->>'ownerKind'='CONTRACTOR_CAPACITY')
  and (value->>'ownerKind'='CONTRACTOR_CAPACITY' and value->>'breakChoice'='NONE' and value->'lunch'='null'::jsonb) is not true;
 select coalesce(jsonb_agg(jsonb_build_array(value->>'service_date',value->>'normal_owner_slot_id') order by value->>'service_date',value->>'normal_owner_slot_id'),'[]')
 into actual from jsonb_array_elements(p_document->'loans');
 if actual is distinct from expected then raise exception 'lunch coverage omits or duplicates a working owner'; end if;
 for loan in select value from jsonb_array_elements(p_document->'loans') loop
  perform public.static_weekly_capacity_assert_lunch_party(p_projection_id,loan,'normal_owner');
  perform public.static_weekly_assert_exact_object(loan,
   case when loan ? 'normal_owner_capacity_id' then array['loan_id','service_date','day_of_week','normal_owner_slot_id','normal_owner_capacity_id','coverage_start','coverage_end','status','helper_slot_ids']
    else array['loan_id','service_date','day_of_week','normal_owner_slot_id','normal_owner_person_id','coverage_start','coverage_end','status','helper_slot_ids'] end,
   array['loan_id','service_date','day_of_week','normal_owner_slot_id','normal_owner_person_id','normal_owner_capacity_id','coverage_start','coverage_end','status','reason','helper_slot_ids','fallback','total_distance_minutes'],'lunch loan');
  if not (loan ?& array['reason','fallback','total_distance_minutes']) then raise exception 'lunch explanatory fields are missing'; end if;
  if coalesce(loan->>'loan_id','') !~ '^[0-9a-f]{64}$' then raise exception 'invalid lunch loan identity'; end if;
  select value into availability from jsonb_array_elements(projection_availability)
   where value->>'slotId'=loan->>'normal_owner_slot_id' and value->>'serviceDate'=loan->>'service_date';
  if not found or availability->>'incumbentPersonId' is distinct from loan->>'normal_owner_person_id'
   or loan->'day_of_week' is distinct from availability->'dayOfWeek'
   or loan->>'coverage_start' is distinct from availability#>>'{lunch,start}'
   or loan->>'coverage_end' is distinct from availability#>>'{lunch,end}' then raise exception 'lunch owner or scheduled hour mismatch'; end if;
  perform public.static_weekly_v3_assert_window(jsonb_build_object('start',loan->'coverage_start','end',loan->'coverage_end'),'lunch');
  start_time:=(loan->>'coverage_start')::time;end_time:=(loan->>'coverage_end')::time;
  if end_time-start_time<>interval '1 hour' then raise exception 'lunch must last exactly one hour'; end if;
  perform public.static_weekly_v3_assert_string_array(loan->'helper_slot_ids','lunch helpers');
  if ((loan->>'status'='NO_AREAS' and jsonb_array_length(loan->'helper_slot_ids')=0 and loan->'fallback'='null'::jsonb)
    or (loan->>'status'='PLANNED' and ((jsonb_array_length(loan->'helper_slot_ids')=2 and loan->'fallback'='null'::jsonb)
      or (jsonb_array_length(loan->'helper_slot_ids')=1 and loan->>'fallback'='only_one_eligible_custodian')))) is not true then
   raise exception 'lunch helper cardinality or fallback invalid'; end if;
  for helper_id in select jsonb_array_elements_text(loan->'helper_slot_ids') loop
   select value into helper from jsonb_array_elements(projection_availability)
    where value->>'slotId'=helper_id and value->>'serviceDate'=loan->>'service_date';
   if not found or helper->>'status' is distinct from 'working' or helper_id=loan->>'normal_owner_slot_id'
    or (nullif(helper->>'incumbentPersonId','') is null and helper->>'ownerKind' is distinct from 'CONTRACTOR_CAPACITY')
    or ((helper#>>'{lunch,start}' is null or helper#>>'{lunch,end}' is null)
      and (helper->>'ownerKind'='CONTRACTOR_CAPACITY' and helper->>'breakChoice'='NONE' and helper->'lunch'='null'::jsonb) is not true) or (helper#>>'{shift,start}')::time>start_time
    or (helper#>>'{shift,end}')::time<end_time
    or ((helper#>>'{lunch,start}')::time<end_time and start_time<(helper#>>'{lunch,end}')::time) then
    raise exception 'lunch helper is not available for the full scheduled hour'; end if;
   if not exists(select 1 from jsonb_array_elements(p_document->'responsibilities') r
     where r->>'loan_id'=loan->>'loan_id' and r->>'coverer_slot_id'=helper_id) then
    raise exception 'lunch helper has no assigned responsibility'; end if;
  end loop;
 end loop;
 for responsibility in select value from jsonb_array_elements(p_document->'responsibilities') loop
  perform public.static_weekly_capacity_assert_lunch_party(p_projection_id,responsibility,'normal_owner');
  perform public.static_weekly_capacity_assert_lunch_party(p_projection_id,responsibility,'coverer');
  perform public.static_weekly_assert_exact_object(responsibility,
   array['responsibility_id','loan_id','service_date','day_of_week','normal_owner_slot_id','coverer_slot_id','coverage_purpose','coverage_start','coverage_end','check_deadline_policy','creates_deep_clean','proximity_evidence','segments']
    ||case when responsibility ? 'normal_owner_capacity_id' then array['normal_owner_capacity_id'] else array['normal_owner_person_id'] end
    ||case when responsibility ? 'coverer_capacity_id' then array['coverer_capacity_id'] else array['coverer_person_id'] end,
   array['responsibility_id','loan_id','service_date','day_of_week','normal_owner_slot_id','normal_owner_person_id','normal_owner_capacity_id','coverer_slot_id','coverer_person_id','coverer_capacity_id','coverage_purpose','coverage_start','coverage_end','check_deadline_policy','creates_deep_clean','proximity_evidence','segments'],'lunch responsibility');
  select value into loan from jsonb_array_elements(p_document->'loans') where value->>'loan_id'=responsibility->>'loan_id';
  if not found or loan->>'status'<>'PLANNED' then raise exception 'lunch responsibility has no planned loan'; end if;
  foreach identity_key in array array['service_date','day_of_week','normal_owner_slot_id','normal_owner_person_id','coverage_start','coverage_end'] loop
   if responsibility->identity_key is distinct from loan->identity_key then raise exception 'lunch responsibility scope mismatch'; end if;
  end loop;
  select value into helper from jsonb_array_elements(projection_availability)
   where value->>'slotId'=responsibility->>'coverer_slot_id' and value->>'serviceDate'=responsibility->>'service_date';
  if not found or helper->>'incumbentPersonId' is distinct from responsibility->>'coverer_person_id'
   or not (loan->'helper_slot_ids' ? (responsibility->>'coverer_slot_id'))
   or coalesce(responsibility->>'responsibility_id','') !~ '^[0-9a-f]{64}$'
   or responsibility->>'coverage_purpose' is distinct from 'lunch_coverage'
   or responsibility->>'check_deadline_policy' is distinct from 'inherit_existing_90_minute_deadline'
   or responsibility->'creates_deep_clean' is distinct from 'false'::jsonb
   or jsonb_typeof(responsibility->'segments') is distinct from 'array'
   or jsonb_array_length(responsibility->'segments')=0 then raise exception 'lunch responsibility policy or recipient mismatch'; end if;
  for segment in select value from jsonb_array_elements(responsibility->'segments') loop
   perform public.static_weekly_assert_exact_object(segment,
    array['planWorkId','workId','serviceMode','window','includedLocations'],array['planWorkId','workId','serviceMode','window','includedLocations'],'lunch segment');
   select value into base_work from jsonb_array_elements(projection_assignments)
    where value->>'plan_work_id'=segment->>'planWorkId' and value->>'service_date'=responsibility->>'service_date';
   if not found or base_work->>'status' is distinct from 'assigned'
    or base_work->>'owner_slot_id' is distinct from responsibility->>'normal_owner_slot_id'
    or base_work->>'owner_person_id' is distinct from responsibility->>'normal_owner_person_id'
    or base_work->>'work_id' is distinct from segment->>'workId'
    or base_work#>'{work_snapshot,includedLocations}' is distinct from segment->'includedLocations'
    or base_work#>>'{work_snapshot,serviceMode}' is distinct from segment->>'serviceMode'
    or segment->>'serviceMode'='reminder_only' then raise exception 'borrowed area differs from original assignment'; end if;
   if not ((helper->'qualifications') @> (base_work#>'{work_snapshot,requiredQualifications}'))
    or (base_work#>'{work_snapshot,restrictedSlotIds}') ? (responsibility->>'coverer_slot_id')
    or exists(select 1 from jsonb_array_elements(segment->'includedLocations') location
      where helper->'restrictions' ? (location->>'locationId')) then
    raise exception 'lunch helper is restricted or unqualified for a borrowed area'; end if;
   perform public.static_weekly_v3_assert_window(segment->'window','borrowed area');
   if (segment#>>'{window,start}')::time<>greatest((base_work#>>'{work_snapshot,window,start}')::time,(loan->>'coverage_start')::time)
    or (segment#>>'{window,end}')::time<>least((base_work#>>'{work_snapshot,window,end}')::time,(loan->>'coverage_end')::time) then
    raise exception 'borrowed-area window must be the exact normal-duty and lunch intersection'; end if;
  end loop;
 end loop;
 -- Account for every normal flexible duty that intersects each scheduled lunch.
 select coalesce(jsonb_agg(jsonb_build_array(l->>'loan_id',a->>'plan_work_id')
  order by l->>'loan_id',a->>'plan_work_id'),'[]') into expected
 from jsonb_array_elements(p_document->'loans') l
 join jsonb_array_elements(projection_assignments) a
  on a->>'service_date'=l->>'service_date' and a->>'owner_slot_id'=l->>'normal_owner_slot_id'
 join jsonb_array_elements(projection_work) w
  on w->>'workId'=a->>'work_id' and w->>'dayOfWeek'=a->>'day_of_week'
 where a->>'status'='assigned' and w->>'schedulingMode'='flexible_coverage_ownership'
  and w->>'serviceMode'<>'reminder_only'
  and (a#>>'{work_snapshot,window,start}')::time<(l->>'coverage_end')::time
  and (l->>'coverage_start')::time<(a#>>'{work_snapshot,window,end}')::time;
 select coalesce(jsonb_agg(jsonb_build_array(r->>'loan_id',s->>'planWorkId')
  order by r->>'loan_id',s->>'planWorkId'),'[]') into actual
 from jsonb_array_elements(p_document->'responsibilities') r cross join lateral jsonb_array_elements(r->'segments') s;
 if actual is distinct from expected then raise exception 'lunch responsibility must cover every eligible original area exactly once'; end if;
 if exists(select 1 from jsonb_array_elements(p_document->'responsibilities') r,
  jsonb_array_elements(r->'segments') s group by r->>'loan_id',s->>'planWorkId' having count(*)>1) then
  raise exception 'borrowed work assigned more than once'; end if;
 if exists(select 1 from jsonb_array_elements(p_document->'responsibilities') r,
  jsonb_array_elements(r->'segments') s,jsonb_array_elements(s->'includedLocations') location
  group by r->>'loan_id',location->>'locationId' having count(distinct r->>'coverer_slot_id')>1) then
  raise exception 'paired or grouped locations split between lunch helpers'; end if;
 for intent in select value from jsonb_array_elements(p_document->'notification_intents') loop
  perform public.static_weekly_assert_exact_object(intent,
   array['notification_key','loan_id','service_date','event','scheduled_time','coverer_slot_id','delivery_state'],
   array['notification_key','loan_id','service_date','event','scheduled_time','coverer_slot_id','delivery_state'],'lunch notification intent');
  if coalesce(intent->>'notification_key','') !~ '^[0-9a-f]{64}$'
   or intent->>'delivery_state' is distinct from 'NOT_ENQUEUED' then raise exception 'invalid lunch notification intent'; end if;
 end loop;
 select coalesce(jsonb_agg(jsonb_build_array(l->>'loan_id',l->>'service_date',h,e,
  case e when 'start' then l->>'coverage_start' else l->>'coverage_end' end) order by l->>'loan_id',h,e),'[]') into expected
 from jsonb_array_elements(p_document->'loans') l cross join lateral jsonb_array_elements_text(l->'helper_slot_ids') h
 cross join unnest(array['start','end']) e
 where exists(select 1 from jsonb_array_elements(projection_availability) a
  where a->>'slotId'=h and a->>'serviceDate'=l->>'service_date' and nullif(a->>'incumbentPersonId','') is not null);
 select coalesce(jsonb_agg(jsonb_build_array(n->>'loan_id',n->>'service_date',n->>'coverer_slot_id',n->>'event',n->>'scheduled_time')
  order by n->>'loan_id',n->>'coverer_slot_id',n->>'event'),'[]') into actual
 from jsonb_array_elements(p_document->'notification_intents') n;
 if actual is distinct from expected then raise exception 'lunch start/end intents must exactly cover every helper'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_pending_lunch_derivation(p_projection uuid, p_document jsonb, p_envelope jsonb, p_publication uuid, p_week date, p_operation uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE projection public.weekly_schedule_compiled_projections%rowtype;source jsonb;loan jsonb;areas jsonb;effective_work jsonb;
 area jsonb;helper jsonb;target text;edge record;evidence jsonb;cost integer;costs jsonb;eligible text[];pair text[];
 best jsonb;states jsonb;next_states jsonb;state jsonb;candidate jsonb;old jsonb;mask integer;new_mask integer;i integer;j integer;k integer;
 required integer;helper_id text;selected text;expected_id text;area_text text;owners jsonb;responsibility jsonb;intent jsonb;
 expected_responsibilities jsonb:='[]';expected_notifications jsonb:='[]';pair_sets jsonb;pair_item jsonb;pair_count integer;
BEGIN
 PERFORM public.static_weekly_pending_lunch_base(p_projection,p_document,p_envelope,p_publication,p_week);
 projection.publication_id:=p_publication;projection.week_start:=p_week;projection.projection_envelope:=p_envelope;projection.authority_digest:=p_envelope->>'authority_digest';projection.replay_digest:=p_envelope->>'replay_digest';
 source:=projection.projection_envelope#>'{authority,overlayCompilerInput}';
 effective_work:=public.static_weekly_pending_effective_work(p_operation,NULL,projection.publication_id,projection.week_start,source);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(projection.projection_envelope->'assignments') a
  WHERE a->>'plan_work_id'!~'^[ -~]+$')
 THEN RAISE EXCEPTION USING ERRCODE='0A000',MESSAGE='Unqualified dated lunch work identity collation';END IF;
 FOR loan IN SELECT value FROM jsonb_array_elements(p_document->'loans') LOOP
  -- The exact six primitive fields used by the existing lunch producer.
  expected_id:=public.static_weekly_digest_text('{"end":'||to_jsonb(loan->>'coverage_end')::text||
   ',"input":'||to_jsonb(projection.projection_envelope#>>'{authority,inputDigest}')::text||
   ',"ownerSlotId":'||to_jsonb(loan->>'normal_owner_slot_id')::text||
   ',"policy":"owner-20260921-two-nearby-full-hour-v1","serviceDate":'||to_jsonb(loan->>'service_date')::text||
   ',"start":'||to_jsonb(loan->>'coverage_start')::text||'}');
  IF loan->>'loan_id' IS DISTINCT FROM expected_id THEN RAISE EXCEPTION 'Dated original lunch loan identity differs';END IF;
  WITH RECURSIVE base AS(
   SELECT a,extract(epoch FROM greatest((a#>>'{work_snapshot,window,start}')::time,(loan->>'coverage_start')::time))::integer/60 s,
    extract(epoch FROM least((a#>>'{work_snapshot,window,end}')::time,(loan->>'coverage_end')::time))::integer/60 e
   FROM jsonb_array_elements(projection.projection_envelope->'assignments') a
   JOIN jsonb_array_elements(effective_work) w ON w->>'workId'=a->>'work_id' AND w->'dayOfWeek'=a->'day_of_week'
   WHERE a->>'service_date'=loan->>'service_date' AND a->'owner_slot_id'=loan->'normal_owner_slot_id'
    AND a->>'status'='assigned' AND w->>'schedulingMode'='flexible_coverage_ownership' AND w->>'serviceMode'<>'reminder_only'
    AND (a#>>'{work_snapshot,window,start}')::time<(loan->>'coverage_end')::time
    AND (loan->>'coverage_start')::time<(a#>>'{work_snapshot,window,end}')::time
  ), reach(root,key) AS(
   SELECT a->>'plan_work_id',a->>'plan_work_id' FROM base
   UNION SELECT reach.root,b.a->>'plan_work_id' FROM reach JOIN base x ON x.a->>'plan_work_id'=reach.key
   JOIN base b ON EXISTS(SELECT 1 FROM jsonb_array_elements(x.a#>'{work_snapshot,includedLocations}') l
    JOIN jsonb_array_elements(b.a#>'{work_snapshot,includedLocations}') r ON l->'locationId'=r->'locationId')
  ), groups AS(SELECT key,min(root COLLATE "C") root FROM reach GROUP BY key), parts AS(
   SELECT root,jsonb_agg(a ORDER BY a->>'plan_work_id' COLLATE "C") rows,
    '['||string_agg('{"end":'||e::text||',"start":'||s::text||',"work":'||to_jsonb(a->>'plan_work_id')::text||'}',',' ORDER BY a->>'plan_work_id' COLLATE "C")||']' preimage,
    jsonb_agg(jsonb_build_object('planWorkId',a->'plan_work_id','workId',a->'work_id','serviceMode',a#>'{work_snapshot,serviceMode}',
     'window',jsonb_build_object('start',to_char(time '00:00'+make_interval(mins=>s),'HH24:MI'),
      'end',to_char(time '00:00'+make_interval(mins=>e),'HH24:MI')),'includedLocations',a#>'{work_snapshot,includedLocations}')
     ORDER BY a->>'plan_work_id' COLLATE "C") segments
   FROM base JOIN groups ON key=a->>'plan_work_id' GROUP BY root
  ) SELECT coalesce(jsonb_agg(jsonb_build_object('areaId',public.static_weekly_digest_text(preimage),'rows',rows,'segments',segments,
    'targets',(SELECT jsonb_agg(loc ORDER BY loc#>>'{}' COLLATE "C") FROM(
      SELECT DISTINCT a#>'{work_snapshot,locationId}' loc FROM jsonb_array_elements(rows) a)t))
    ORDER BY public.static_weekly_digest_text(preimage) COLLATE "C"),'[]') INTO areas FROM parts;
  IF jsonb_array_length(areas)>128 THEN RAISE EXCEPTION 'Dated lunch area bound exceeded';END IF;
  costs:='{}'::jsonb;
  FOR area IN SELECT value FROM jsonb_array_elements(areas) LOOP
   FOR helper IN SELECT value FROM jsonb_array_elements(projection.projection_envelope#>'{authority,projectionAvailability}')
    WHERE value->>'serviceDate'=loan->>'service_date' AND value->>'status'='working'
     AND value->>'incumbentPersonId' IS NOT NULL AND value->'slotId'<>loan->'normal_owner_slot_id'
     AND (value#>>'{shift,start}')::time<=(loan->>'coverage_start')::time AND (value#>>'{shift,end}')::time>=(loan->>'coverage_end')::time
     AND NOT((value#>>'{lunch,start}')::time<(loan->>'coverage_end')::time AND (loan->>'coverage_start')::time<(value#>>'{lunch,end}')::time)
     AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(value->'blockedWindows','[]'::jsonb)) b
      WHERE (b->>'start')::time<(loan->>'coverage_end')::time AND (loan->>'coverage_start')::time<(b->>'end')::time)
    ORDER BY value->>'slotId' COLLATE "C" LOOP
    helper_id:=helper->>'slotId';
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(area->'rows') a
     WHERE NOT(helper->'qualifications' @> a#>'{work_snapshot,requiredQualifications}')
      OR a#>'{work_snapshot,restrictedSlotIds}' ? helper_id
      OR EXISTS(SELECT 1 FROM jsonb_array_elements(a#>'{work_snapshot,includedLocations}') l WHERE helper->'restrictions' ? (l->>'locationId')))
    THEN CONTINUE;END IF;
    evidence:='[]'::jsonb;cost:=0;
    FOR target IN SELECT jsonb_array_elements_text(area->'targets') LOOP
     SELECT from_id,minutes,provenance INTO edge FROM(
      SELECT a#>>'{work_snapshot,locationId}' from_id,0 minutes,'same_normal_assigned_area'::text provenance
      FROM jsonb_array_elements(projection.projection_envelope->'assignments') a
      JOIN jsonb_array_elements(effective_work) w ON w->>'workId'=a->>'work_id' AND w->'dayOfWeek'=a->'day_of_week'
      WHERE a->>'service_date'=loan->>'service_date' AND a->>'owner_slot_id'=helper_id AND a->>'status'='assigned'
       AND w->>'schedulingMode'='flexible_coverage_ownership' AND w->>'serviceMode'<>'reminder_only'
       AND (a#>>'{work_snapshot,window,start}')::time<(loan->>'coverage_end')::time AND (loan->>'coverage_start')::time<(a#>>'{work_snapshot,window,end}')::time
       AND a#>>'{work_snapshot,locationId}'=target
      UNION ALL
      SELECT a#>>'{work_snapshot,locationId}',(e->>'minutes')::integer,e->>'provenance'
      FROM jsonb_array_elements(projection.projection_envelope->'assignments') a
      JOIN jsonb_array_elements(effective_work) w ON w->>'workId'=a->>'work_id' AND w->'dayOfWeek'=a->'day_of_week'
      JOIN jsonb_array_elements(source->'proximity') e ON
       ((e->>'fromLocationId'=a#>>'{work_snapshot,locationId}' AND e->>'toLocationId'=target)
        OR ((e->'bidirectional'='true'::jsonb OR e->'symmetric'='true'::jsonb) AND e->>'toLocationId'=a#>>'{work_snapshot,locationId}' AND e->>'fromLocationId'=target))
      WHERE a->>'service_date'=loan->>'service_date' AND a->>'owner_slot_id'=helper_id AND a->>'status'='assigned'
       AND w->>'schedulingMode'='flexible_coverage_ownership' AND w->>'serviceMode'<>'reminder_only'
       AND (a#>>'{work_snapshot,window,start}')::time<(loan->>'coverage_end')::time AND (loan->>'coverage_start')::time<(a#>>'{work_snapshot,window,end}')::time
       AND e->'verified'='true'::jsonb AND jsonb_typeof(e->'minutes')='number' AND (e->>'minutes')::numeric BETWEEN 1 AND 1440
       AND (e->>'minutes')::numeric=trunc((e->>'minutes')::numeric) AND nullif(e->>'provenance','') IS NOT NULL
     ) options ORDER BY minutes,from_id COLLATE "C",provenance COLLATE "C" LIMIT 1;
     IF NOT FOUND THEN evidence:=NULL;EXIT;END IF;
     cost:=greatest(cost,edge.minutes);evidence:=evidence||jsonb_build_array(jsonb_build_object(
      'fromLocationId',edge.from_id,'toLocationId',target,'minutes',edge.minutes,'provenance',edge.provenance));
    END LOOP;
    IF evidence IS NOT NULL THEN
     IF NOT(costs ? (area->>'areaId')) THEN costs:=costs||jsonb_build_object(area->>'areaId','{}'::jsonb);END IF;
     costs:=jsonb_set(costs,ARRAY[area->>'areaId',helper_id],jsonb_build_object('cost',cost,'evidence',evidence));
    END IF;
   END LOOP;
  END LOOP;
  SELECT array_agg(id ORDER BY id COLLATE "C") INTO eligible FROM(
   SELECT DISTINCT h.key id FROM jsonb_each(costs) a CROSS JOIN LATERAL jsonb_each(a.value) h)t;
  IF jsonb_array_length(areas)=0 THEN
   IF loan->>'status' IS DISTINCT FROM 'NO_AREAS' OR loan->'helper_slot_ids' IS DISTINCT FROM '[]'::jsonb
    OR loan->'total_distance_minutes' IS DISTINCT FROM '0'::jsonb OR loan->'fallback' IS DISTINCT FROM 'null'::jsonb
    OR loan->'reason' IS DISTINCT FROM 'null'::jsonb
   THEN RAISE EXCEPTION 'Dated no-area lunch result differs';END IF;CONTINUE;
  END IF;
  required:=least(2,coalesce(cardinality(eligible),0));
  IF required=0 OR jsonb_array_length(areas)<required THEN RAISE EXCEPTION 'Dated lunch has no complete eligible partition';END IF;
  pair_sets:='[]'::jsonb;
  IF required=1 THEN pair_sets:=jsonb_build_array(to_jsonb(eligible));
  ELSE FOR i IN 1..cardinality(eligible)-1 LOOP FOR j IN i+1..cardinality(eligible) LOOP
   pair_sets:=pair_sets||jsonb_build_array(to_jsonb(ARRAY[eligible[i],eligible[j]]));END LOOP;END LOOP;END IF;
  best:=NULL;
  FOR pair_item IN SELECT value FROM jsonb_array_elements(pair_sets) LOOP
   SELECT array_agg(value ORDER BY n) INTO pair FROM jsonb_array_elements_text(pair_item) WITH ORDINALITY t(value,n);
   states:='{"0":{"cost":0,"owners":[]}}'::jsonb;
   FOR area IN SELECT value FROM jsonb_array_elements(areas) LOOP
    next_states:='{}'::jsonb;
    FOR mask IN 0..(1<<required)-1 LOOP
     state:=states->mask::text;IF state IS NULL THEN CONTINUE;END IF;
     FOR k IN 1..required LOOP
      IF costs#>ARRAY[area->>'areaId',pair[k]] IS NULL THEN CONTINUE;END IF;
      new_mask:=mask | (1<<(k-1));candidate:=jsonb_build_object('cost',(state->>'cost')::integer+
       (costs#>>ARRAY[area->>'areaId',pair[k],'cost'])::integer,'owners',state->'owners'||jsonb_build_array(pair[k]));
      old:=next_states->new_mask::text;
      IF old IS NULL OR (candidate->>'cost')::integer<(old->>'cost')::integer
       OR ((candidate->>'cost')::integer=(old->>'cost')::integer AND (candidate->'owners')::text COLLATE "C"<(old->'owners')::text COLLATE "C")
      THEN next_states:=jsonb_set(next_states,ARRAY[new_mask::text],candidate);END IF;
     END LOOP;
    END LOOP;
    states:=next_states;
   END LOOP;
   candidate:=states->((1<<required)-1)::text;
   IF candidate IS NOT NULL AND (best IS NULL OR (candidate->>'cost')::integer<(best->>'cost')::integer
    OR ((candidate->>'cost')::integer=(best->>'cost')::integer AND (candidate->'owners')::text COLLATE "C"<(best->'owners')::text COLLATE "C"))
   THEN best:=candidate||jsonb_build_object('pair',pair_item);END IF;
  END LOOP;
  IF best IS NULL OR loan->>'status' IS DISTINCT FROM 'PLANNED' OR loan->'helper_slot_ids' IS DISTINCT FROM best->'pair'
   OR loan->'total_distance_minutes' IS DISTINCT FROM best->'cost'
   OR loan->'reason' IS DISTINCT FROM 'null'::jsonb
   OR loan->'fallback' IS DISTINCT FROM (CASE WHEN required=1 THEN '"only_one_eligible_custodian"'::jsonb ELSE 'null'::jsonb END)
  THEN RAISE EXCEPTION 'Dated deterministic original lunch helper partition differs';END IF;
  i:=0;
  FOR area IN SELECT value FROM jsonb_array_elements(areas) LOOP
   selected:=best#>>ARRAY['owners',i::text];i:=i+1;
   expected_id:=public.static_weekly_digest_text('{"areaId":'||to_jsonb(area->>'areaId')::text||',"covererSlotId":'||to_jsonb(selected)::text||',"loanId":'||to_jsonb(loan->>'loan_id')::text||'}');
   SELECT value INTO STRICT responsibility FROM jsonb_array_elements(p_document->'responsibilities') r(value)
    WHERE value->>'responsibility_id'=expected_id;
   IF responsibility->>'loan_id' IS DISTINCT FROM loan->>'loan_id' OR responsibility->>'coverer_slot_id' IS DISTINCT FROM selected
    OR responsibility->'segments' IS DISTINCT FROM area->'segments'
    OR responsibility->'proximity_evidence' IS DISTINCT FROM costs#>ARRAY[area->>'areaId',selected,'evidence']
   THEN RAISE EXCEPTION 'Dated exact original lunch area responsibility or directed evidence differs';END IF;
   expected_responsibilities:=expected_responsibilities||jsonb_build_array(expected_id);
  END LOOP;
 END LOOP;
 FOR intent IN SELECT value FROM jsonb_array_elements(p_document->'notification_intents') LOOP
  expected_id:=public.static_weekly_digest_text('{"event":'||to_jsonb(intent->>'event')::text||',"loanId":'||to_jsonb(intent->>'loan_id')::text||',"slot":'||to_jsonb(intent->>'coverer_slot_id')::text||'}');
  IF intent->>'notification_key' IS DISTINCT FROM expected_id THEN RAISE EXCEPTION 'Dated original lunch notification identity differs';END IF;
 END LOOP;
 IF EXISTS((SELECT value FROM jsonb_array_elements(expected_responsibilities) EXCEPT ALL SELECT value->'responsibility_id' FROM jsonb_array_elements(p_document->'responsibilities'))
  UNION ALL(SELECT value->'responsibility_id' FROM jsonb_array_elements(p_document->'responsibilities') EXCEPT ALL SELECT value FROM jsonb_array_elements(expected_responsibilities)))
 THEN RAISE EXCEPTION 'Dated complete original lunch responsibilities differ';END IF;
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_pending_projection_sink(p_publication_id uuid, p_service_date date, p_exception_set_digest text, p_compiler_version text, p_objective jsonb, p_metrics jsonb, p_replay_digest text, p_assignments jsonb, p_expected_revision bigint, p_actor_manager_id uuid, p_actor_manager_name text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_pending_validation jsonb; v_request jsonb; v_request_digest text; v_prior public.weekly_schedule_command_receipts%rowtype; v_publication public.weekly_schedule_publications%rowtype; v_effective_start date; v_effective_end date; v_exception_set jsonb; v_exception_digest text; v_command uuid:=gen_random_uuid(); v_projection uuid:=gen_random_uuid(); v_revision bigint; v_content_digest text; v_response jsonb; v_item jsonb; v_assignment public.weekly_schedule_slot_assignments%rowtype; v_owner public.v_weekly_roster_slot_incumbency_ranges%rowtype; v_occurrence uuid; v_work jsonb;
begin
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_actor_manager_id,p_actor_manager_name,p_idempotency_key,'materialize_projection'); v_request:=jsonb_build_object('operation','materialize_projection','publication_id',p_publication_id,'service_date',p_service_date,'exception_set_digest',p_exception_set_digest,'compiler_version',p_compiler_version,'objective',p_objective,'metrics',p_metrics,'replay_digest',p_replay_digest,'projection_envelope',p_assignments,'expected_revision',p_expected_revision,'actor_manager_id',p_actor_manager_id,'actor_manager_name',p_actor_manager_name); v_request_digest:=public.static_weekly_digest_jsonb(v_request); perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
