$function$

CREATE OR REPLACE FUNCTION public.static_weekly_prepare_coverall_activation(p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE snapshot jsonb;fingerprint text;body jsonb;feasibility jsonb;
BEGIN
 PERFORM public.static_weekly_v3_assert_release_operator();PERFORM custodial_coverall.assert_packet_preparation_target((p_data->>'managerId')::uuid);
 PERFORM public.custodial_begin_application_mutation();
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 snapshot:=public.static_weekly_manual_roster_snapshot(public.sch_service_date(statement_timestamp()));
 PERFORM public.static_weekly_coverall_assert_activation_data(p_data,snapshot);
 -- Drop the large feasibility field from the caller packet before hashing.
 -- The unchanged full feasibility is persisted below; no wire/data field drops.
 feasibility:=p_data->'feasibility';p_data:=p_data-'feasibility';
 fingerprint:=custodial_coverall.activation_packet_fingerprint((p_data->>'sourceId')::uuid,p_data->>'templateId',(p_data->>'managerId')::uuid,p_data->'transition',feasibility);
 body:=jsonb_build_object('packetId',p_data->'packetId','sourceId',p_data->'sourceId','managerId',p_data->'managerId','expectedRevision',snapshot->'authorityRevision',
  'serviceDate',snapshot->'serviceDate','sourceDigest',p_data->'sourceDigest','rosterDigest',public.static_weekly_digest_jsonb(snapshot),'packetFingerprint',fingerprint);
 INSERT INTO custodial_coverall.activation_packets VALUES((p_data->>'packetId')::uuid,(p_data->>'sourceId')::uuid,p_data->>'templateId',(p_data->>'managerId')::uuid,
  (snapshot->>'serviceDate')::date,(snapshot->>'authorityRevision')::bigint,public.static_weekly_digest_jsonb(snapshot),public.static_weekly_digest_jsonb(body),
  p_data->'source',p_data->>'sourceDigest',p_data->'transition',p_data->'capacityTransition',p_data->'ownerConfig',p_data->'template',p_data->'binding',p_data->'approvalEvidence',feasibility,fingerprint);
 feasibility:=NULL;p_data:=NULL;
 RETURN body||jsonb_build_object('previewDigest',public.static_weekly_digest_jsonb(body),'registered',false,'published',false);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_prepare_coverall_choice(p_choice jsonb, p_credential uuid, p_device text, p_access text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE ctx jsonb;c public.static_weekly_staffing_commands%rowtype;prior custodial_coverall.choices%rowtype;d jsonb;actor jsonb;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();
 IF p_choice IS NULL OR pg_column_size(p_choice)>262144 OR jsonb_array_length(p_choice->'days') NOT BETWEEN 1 AND 366
  OR p_choice->>'choiceDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(p_choice-'choiceDigest')
  OR p_choice->>'schema' IS DISTINCT FROM 'custodial.approved-manual-coverall-choice.v1'
  OR p_choice->'contractorBooked' IS DISTINCT FROM 'false'::jsonb OR p_choice->'vendorApprovalClaimed' IS DISTINCT FROM 'false'::jsonb
 THEN RAISE EXCEPTION 'Exact bounded CoverAll preparing DATA required';END IF;
 PERFORM public.static_weekly_assert_exact_object(p_choice,
 ARRAY['schema','choiceId','operationId','managerId','semanticDigest','expectedRevision','days','canonicalSemanticBody','contractorBooked','vendorApprovalClaimed','choiceDigest'],
 ARRAY['schema','choiceId','operationId','managerId','semanticDigest','expectedRevision','days','canonicalSemanticBody','contractorBooked','vendorApprovalClaimed','choiceDigest'],'original CoverAll choice');
 actor:=public.custodial_action_actor_v1((p_choice->>'managerId')::uuid,p_credential,p_device,p_access,'manage_coverall');
 PERFORM public.static_weekly_coverall_bind_actor((p_choice->>'operationId')::uuid,(p_choice->>'managerId')::uuid,p_credential,p_device,p_access);
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 SELECT * INTO STRICT c FROM public.static_weekly_staffing_commands WHERE operation_id=(p_choice->>'operationId')::uuid FOR UPDATE;
 ctx:=public.static_weekly_pending_context(c.operation_id,(p_choice->>'managerId')::uuid);
 IF c.state<>'PREPARING' OR c.command_kind<>'absence' OR c.prepared_by_manager_id::text<>p_choice->>'managerId'
  OR c.semantic_body IS DISTINCT FROM p_choice->'canonicalSemanticBody' OR c.semantic_digest IS DISTINCT FROM p_choice->>'semanticDigest'
  OR to_jsonb(c.expected_revision) IS DISTINCT FROM p_choice->'expectedRevision'
 THEN RAISE EXCEPTION 'Supplement cannot change six-field canonical command or its original PREPARING owner';END IF;
 IF (SELECT count(*)<>count(DISTINCT x->>'serviceDate') FROM jsonb_array_elements(p_choice->'days') x) THEN RAISE EXCEPTION 'Duplicate actual day choice';END IF;
 SELECT * INTO prior FROM custodial_coverall.choices WHERE operation_id=c.operation_id;
 IF FOUND THEN
  IF prior.choice_json IS DISTINCT FROM p_choice THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='Original CoverAll choice is immutable';END IF;
  RETURN jsonb_build_object('state','PREPARING','operationId',c.operation_id,'choiceId',prior.choice_id,'choiceDigest',prior.choice_digest,'replayed',true);
 END IF;
 FOR d IN SELECT value FROM jsonb_array_elements(p_choice->'days') LOOP PERFORM public.static_weekly_coverall_validate_choice_day(c.operation_id,c.prepared_by_manager_id,d);END LOOP;
 INSERT INTO custodial_coverall.choices VALUES(c.operation_id,(p_choice->>'choiceId')::uuid,c.prepared_by_manager_id,c.semantic_digest,c.expected_revision,
  p_credential,p_device,p_access,p_choice,p_choice->>'choiceDigest',clock_timestamp());
 RETURN jsonb_build_object('state','PREPARING','operationId',c.operation_id,'choiceId',p_choice->'choiceId','choiceDigest',p_choice->'choiceDigest','accepted',false);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_projection_window_start(p_date date)
 RETURNS date
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare manifest text;origin date;
begin
 if p_date is null or not isfinite(p_date) then raise exception using errcode='22023',message='exact projection service date required';end if;
 -- Read scalar metadata only. Native occurrence guards call this repeatedly;
 -- retaining the complete source JSON in their nested contexts is unbounded.
 select s.canonical_source#>>'{version,manualGroupRatingAuthority,manifestSha256}',v.effective_start into manifest,origin
 from public.weekly_schedule_versions v
 join public.static_weekly_authority_source_documents s on s.source_id=v.authority_source_id
 where v.version_id=public.static_weekly_effective_version(p_date);
 if manifest='fe02bbdebc736d95360b55cc7dfe5b73c5a9eaa76f364f1c0f4420a0afb9950f' then return p_date-mod(p_date-origin,7);end if;
 return p_date-(extract(isodow from p_date)::integer-1);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_read_approved_initial_basis(p_manager_id uuid, p_source_id uuid, p_date date, p_revision bigint, p_template_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare baseline public.static_weekly_approved_initial_baselines%rowtype;entry public.static_weekly_approved_template_catalog%rowtype;
 source jsonb;revision bigint;templates jsonb;bindings jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 perform public.static_weekly_v3_manager_actor(p_manager_id);
 select current_revision into strict revision from public.static_weekly_schedule_control where singleton;
 if revision is distinct from p_revision then raise exception using errcode='40001',message='stale initial baseline revision';end if;
 select * into strict baseline from public.static_weekly_approved_initial_baselines
  where source_id=p_source_id and template_id=p_template_id and effective_start=p_date;
 select * into strict entry from public.static_weekly_approved_template_catalog where template_id=p_template_id;
 source:=(public.static_weekly_v3_read_authority_source(p_source_id,p_date))->'compiler_input';
 if exists(select 1 from public.static_weekly_approved_template_retirements where template_id=p_template_id)
  or baseline.snapshot_digest<>public.static_weekly_digest_jsonb(baseline.feasibility)
  or baseline.feasibility->'candidateSource' is distinct from source
  or entry.catalog_entry_digest<>public.static_weekly_digest_jsonb(jsonb_build_object('template',entry.template_json,
    'binding',entry.binding_json,'ownerConfig',entry.owner_config,'approvalEvidence',entry.approval_evidence)) then
  raise exception 'approved initial source or current people/availability changed';end if;
 templates:=jsonb_build_array(entry.template_json);bindings:=jsonb_build_array(entry.binding_json);
 return jsonb_build_object('schema','custodial.approved-static-initial-basis.v1','sourceId',p_source_id,'serviceDate',p_date,
  'authorityRevision',revision,'generation',public.static_weekly_v15_read_recurring_generation(),
  'currentSource',source,'currentSourceDigest',public.static_weekly_digest_jsonb(source),
  'ownerConfig',entry.owner_config,'templates',templates,'admittedBindings',bindings,
  'templateCatalogDigest',public.static_weekly_digest_jsonb(jsonb_build_object('templates',templates,'admittedBindings',bindings,'ownerConfig',entry.owner_config)));
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_read_approved_initial_confirmation(p_manager_id uuid, p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare result jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();perform public.static_weekly_v3_manager_actor(p_manager_id);
 select jsonb_build_object('request',request_json,'receipt',receipt_json) into result
  from public.static_weekly_approved_initial_confirmations where manager_id=p_manager_id and idempotency_key=p_key;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_read_approved_template_basis(p_manager_id uuid, p_publication_id uuid, p_service_date date, p_kind text, p_template_id text, p_expected_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare source_row jsonb;source_input jsonb;config jsonb;templates jsonb;bindings jsonb;catalog jsonb;
 week_start date;revision bigint;generation bigint;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 perform public.static_weekly_v3_manager_actor(p_manager_id);
 if p_service_date is null or not isfinite(p_service_date)
  or p_kind is null or p_kind not in ('RECURRING_STAFFING','DATED_ABSENCE')
  or (p_kind='RECURRING_STAFFING' and extract(isodow from p_service_date)<>1) then
  raise exception using errcode='22023',message='one finite date and explicit static template operation kind required';end if;
 week_start:=p_service_date-(extract(isodow from p_service_date)::integer-1);
 select current_revision into strict revision from public.static_weekly_schedule_control where singleton;
 if p_expected_revision is distinct from revision then raise exception using errcode='40001',message='stale approved template preview revision';end if;
 source_row:=public.static_weekly_v3_read_publication_source(p_publication_id,week_start);
 source_input:=jsonb_set(jsonb_set(source_row->'compiler_input','{serviceDate}',to_jsonb(p_service_date::text),true),
  '{exceptions}',source_row->'exceptions',true);
 select c.owner_config into config from public.static_weekly_approved_template_source_configs c
  join public.static_weekly_authority_source_documents s using(source_id)
  where c.source_id=(source_row->>'source_id')::uuid and s.active and s.retired_at is null
   and c.config_digest=public.static_weekly_digest_jsonb(c.owner_config)
   and s.source_digest=public.static_weekly_digest_jsonb(s.canonical_source);
 if config is null then raise exception using errcode='55000',message='current publication lacks release-admitted static template owner configuration';end if;
 select coalesce(jsonb_agg(c.template_json order by c.template_id),'[]'::jsonb),
  coalesce(jsonb_agg(c.binding_json order by c.template_id),'[]'::jsonb),
  coalesce(jsonb_agg(jsonb_build_object('templateId',c.template_id,'entryDigest',c.catalog_entry_digest) order by c.template_id),'[]'::jsonb)
  into templates,bindings,catalog from public.static_weekly_approved_template_catalog c
  where c.owner_config=config and (p_template_id is null or c.template_id=p_template_id)
   and not exists(select 1 from public.static_weekly_approved_template_retirements r where r.template_id=c.template_id)
   and c.catalog_entry_digest=public.static_weekly_digest_jsonb(jsonb_build_object(
    'template',c.template_json,'binding',c.binding_json,'ownerConfig',c.owner_config,'approvalEvidence',c.approval_evidence));
 if jsonb_array_length(templates)=0 then raise exception using errcode='55000',message='missing approved static template; automatic solver generation is not authorized';end if;
 select public.static_weekly_v15_read_recurring_generation() into generation;
 return jsonb_build_object('schema','custodial.approved-static-template-basis.v1',
  'publicationId',p_publication_id,'serviceDate',p_service_date,'kind',p_kind,
  'authorityRevision',revision,'generation',generation,
  'templateCatalogDigest',public.static_weekly_digest_jsonb(catalog),
  'currentSource',source_input,'ownerConfig',config,'templates',templates,'admittedBindings',bindings,
  'templateCatalogEntries',catalog,'templateInputsDigest',public.static_weekly_digest_jsonb(
   jsonb_build_object('templates',templates,'admittedBindings',bindings,'ownerConfig',config)));
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_read_approved_template_confirmation(p_manager_id uuid, p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 PERFORM public.static_weekly_v3_manager_actor(p_manager_id);
 IF p_key IS NULL OR length(p_key)<>36
  OR p_key !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
  RAISE EXCEPTION USING errcode='22023',message='Exact original approved confirmation UUID key required';END IF;
 IF p_key IS DISTINCT FROM (p_key::uuid)::text THEN
  RAISE EXCEPTION USING errcode='22023',message='Exact original approved confirmation UUID key required';END IF;
 SELECT jsonb_build_object('request',request_json,'receipt',receipt_json) INTO result
  FROM public.static_weekly_approved_template_confirmations WHERE manager_id=p_manager_id AND idempotency_key=p_key;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_read_coverall_activation_basis(p_manager uuid, p_packet uuid, p_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE packet record;snapshot jsonb;employment jsonb:='[]';vector jsonb;d date;body jsonb;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();PERFORM public.static_weekly_v3_manager_actor(p_manager);
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 SELECT packet_id,source_id,template_id,manager_id,service_date,expected_revision,roster_digest,preview_digest,packet_fingerprint,source_digest INTO packet
 FROM custodial_coverall.activation_packets WHERE packet_id=p_packet;
 IF NOT FOUND THEN RETURN NULL;END IF;
 snapshot:=public.static_weekly_manual_roster_snapshot(public.sch_service_date(statement_timestamp()));
 IF packet.manager_id<>p_manager OR packet.expected_revision<>p_revision OR p_revision::text<>snapshot->>'authorityRevision'
  OR packet.service_date::text<>snapshot->>'serviceDate' OR packet.roster_digest<>public.static_weekly_digest_jsonb(snapshot)
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Original current typed activation packet/manager/date/roster/revision changed';END IF;
 FOR d IN SELECT generate_series(packet.service_date,packet.service_date+6,'1 day')::date LOOP
  employment:=employment||jsonb_build_array(custodial_employment.native_read(d,p_revision,p_manager));END LOOP;
 SELECT jsonb_agg(jsonb_build_object('serviceDate',day->'serviceDate','employeeId',e->'employeeId','employmentRevision',e->'employmentRevision','requestId',e#>'{command,requestId}') ORDER BY day->>'serviceDate',e->>'employeeId')
 INTO vector FROM jsonb_array_elements(employment) days(day) CROSS JOIN LATERAL jsonb_array_elements(day->'employees') employees(e);
 IF jsonb_array_length(vector)<>14 THEN RAISE EXCEPTION 'Actual fourteen employment bindings required';END IF;
 body:=jsonb_build_object('schema','custodial.approved-manual-coverall-activation-preview-basis.v2','managerId',p_manager,'packetId',p_packet,
  'sourceId',packet.source_id,'templateId',packet.template_id,'serviceDate',packet.service_date,'windowEnd',packet.service_date+6,'expectedRevision',p_revision,
  'packetPreviewDigest',packet.preview_digest,'packetFingerprint',packet.packet_fingerprint,'sourceDigest',packet.source_digest,'employmentRevisionVector',vector,
  'currentPositions',22,'additionalCapacityPositions',8,'prospectivePositions',30,'newEmployees',0);
 RETURN body||jsonb_build_object('previewDigest',public.static_weekly_digest_jsonb(body),'normalPatternSolverInvoked',false,'operationalAdjustmentPending',true,'published',false);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_read_coverall_activation_request(p_manager uuid, p_key text, p_credential uuid, p_device text, p_access text)
