CREATE OR REPLACE FUNCTION public.static_weekly_read_manual_repeat_basis(p_manager uuid, p_publication uuid, p_date date, p_revision bigint, p_credential uuid, p_device text, p_access text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor jsonb;v_source_id uuid;v_version_id uuid;origin date;frame date;snapshot text;catalog text;projection jsonb;lunch jsonb;
 entry record;exceptions jsonb;reasons jsonb:='[]';participants jsonb;employment jsonb:='[]';readback jsonb;
 d date;a jsonb;r record;existing uuid;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();
 actor:=public.custodial_action_actor_v1(p_manager,p_credential,p_device,p_access,'read');
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 IF p_revision IS NULL OR p_revision NOT BETWEEN 0 AND 9007199254740990 OR p_revision IS DISTINCT FROM
  (SELECT current_revision FROM public.static_weekly_schedule_control WHERE singleton)
  OR p_date IS NULL OR NOT isfinite(p_date) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Current recurring date/revision required'; END IF;
 SELECT v.authority_source_id,v.version_id,p.effective_start INTO STRICT v_source_id,v_version_id,origin
 FROM public.weekly_schedule_publications p JOIN public.weekly_schedule_versions v USING(version_id)
 WHERE p.publication_id=p_publication;
 SELECT b.snapshot_digest,b.feasibility#>'{initialBaseline,projection}' AS projection_component,b.feasibility->'lunchDocument' AS lunch_component,c.catalog_entry_digest,
  c.template_json,c.binding_json,c.owner_config,c.approval_evidence,c.template_id INTO STRICT entry
 FROM public.static_weekly_approved_initial_baselines b JOIN public.static_weekly_approved_template_catalog c USING(template_id)
 JOIN public.static_weekly_authority_source_documents s ON s.source_id=b.source_id
 WHERE b.source_id=v_source_id AND b.effective_start=origin AND s.active AND s.retired_at IS NULL;
 snapshot:=entry.snapshot_digest;projection:=entry.projection_component;lunch:=entry.lunch_component;catalog:=entry.catalog_entry_digest;
 IF p_date<origin OR entry.template_id IS NULL
  OR EXISTS(SELECT 1 FROM public.static_weekly_approved_template_retirements WHERE template_id=entry.template_id)
  OR catalog IS DISTINCT FROM public.static_weekly_digest_jsonb(jsonb_build_object('template',entry.template_json,'binding',entry.binding_json,'ownerConfig',entry.owner_config,'approvalEvidence',entry.approval_evidence))
  OR projection#>>'{authority,compilerInput,version,manualGroupRatingAuthority,manifestSha256}' IS DISTINCT FROM 'fe02bbdebc736d95360b55cc7dfe5b73c5a9eaa76f364f1c0f4420a0afb9950f'
  OR NOT EXISTS(SELECT 1 FROM public.static_weekly_approved_initial_confirmations c WHERE c.publication_id=p_publication)
 THEN RAISE EXCEPTION 'Current live catalog and original accepted manual publication required'; END IF;
 frame:=public.static_weekly_source_window_start(projection#>'{authority,compilerInput}',p_date);
 IF frame IS DISTINCT FROM origin+((p_date-origin)/7)*7 THEN RAISE EXCEPTION 'Original publication origin differs from Source301 window authority'; END IF;
 IF frame<=origin THEN RAISE EXCEPTION 'Initial frame remains owned by the original activation'; END IF;
 IF public.static_weekly_effective_version(frame) IS DISTINCT FROM v_version_id
  OR public.static_weekly_effective_version(frame+6) IS DISTINCT FROM v_version_id
 THEN RAISE EXCEPTION 'Period crosses or has left the original normal publication'; END IF;
 IF projection->>'database_projection_identity' IS DISTINCT FROM public.static_weekly_digest_jsonb(projection-'database_projection_identity')
  OR lunch->>'document_identity' IS DISTINCT FROM public.static_weekly_digest_jsonb(lunch-'document_identity') THEN RAISE EXCEPTION 'Original admitted component identity differs'; END IF;
 IF jsonb_array_length(projection->'assignments')<>346 OR jsonb_array_length(lunch->'loans')<>40 THEN RAISE EXCEPTION 'Original normal component counts differ'; END IF;
 exceptions:=public.static_weekly_accepted_exception_set(p_publication,frame);
 SELECT jsonb_agg(jsonb_build_object('serviceDate',service_day::date::text,
  'assignmentEmployeeIds',(SELECT jsonb_agg(id ORDER BY id) FROM(SELECT DISTINCT item->>'owner_person_id' id FROM jsonb_array_elements(projection->'assignments') x(item) WHERE (item->>'day_of_week')::integer=extract(dow FROM service_day)::integer) ids),
  'lunchOwnerEmployeeIds',(SELECT jsonb_agg(id ORDER BY id) FROM(SELECT DISTINCT item->>'normal_owner_person_id' id FROM jsonb_array_elements(lunch->'loans') x(item) WHERE (item->>'day_of_week')::integer=extract(dow FROM service_day)::integer) ids),
  'lunchCovererEmployeeIds',(SELECT jsonb_agg(id ORDER BY id) FROM(SELECT DISTINCT item->>'coverer_person_id' id FROM jsonb_array_elements(lunch->'responsibilities') x(item) WHERE (item->>'day_of_week')::integer=extract(dow FROM service_day)::integer) ids)) ORDER BY service_day)
 INTO participants FROM generate_series(frame::timestamp,(frame+6)::timestamp,interval '1 day') dates(service_day);
 FOR d IN SELECT generate_series(frame::timestamp,(frame+6)::timestamp,interval '1 day')::date LOOP
  FOR a IN SELECT value FROM jsonb_array_elements(projection#>'{authority,projectionAvailability}') WHERE value->>'status'='working' AND (value->>'dayOfWeek')::integer=extract(dow FROM d)::integer LOOP
   IF NOT EXISTS(SELECT 1 FROM public.v_weekly_roster_slot_incumbency_ranges incumbency JOIN public.employees e ON e.id=incumbency.person_id
    WHERE incumbency.slot_id=(a->>'slotId')::uuid AND incumbency.person_id=(a->>'incumbentPersonId')::uuid AND incumbency.effective_start<=d
     AND (incumbency.effective_end IS NULL OR d<incumbency.effective_end) AND e.active)
   THEN reasons:=reasons||jsonb_build_array(jsonb_build_object('kind','ACTUAL_ROSTER_CHANGED','serviceDate',d::text,'slotId',a->>'slotId')); END IF;
  END LOOP;
  readback:=custodial_employment.read_admissions(d,p_revision,p_manager,p_credential,p_device,p_access);
  employment:=employment||jsonb_build_array(readback);
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(lunch->'loans') l WHERE l->>'normal_owner_person_id'='1318b295-fd70-4e78-8828-62c29302f96f'
  AND (l->>'coverage_start'<>'12:30' OR l->>'coverage_end'<>'13:30')) THEN
  reasons:=reasons||jsonb_build_array(jsonb_build_object('kind','APPROVED_XAVIER_LUNCH_DIFFERS')); END IF;
 -- A bare same-frame projection does not prove current employment14 or a
 -- normal-reference admission. The typed recurring owner always obtains a real
 -- same-request repeat receipt; native writer replay still deduplicates bytes.
 existing:=NULL;
 RETURN jsonb_build_object('schema','custodial.approved-manual-recurring-basis.v1','managerId',p_manager,
  'sourceId',v_source_id,'publicationId',p_publication,'versionId',v_version_id,'origin',origin::text,'frameStart',frame::text,'frameEnd',(frame+6)::text,
  'authorityRevision',p_revision,'generation',public.static_weekly_v15_read_recurring_generation(),
  'manifestSha256','fe02bbdebc736d95360b55cc7dfe5b73c5a9eaa76f364f1c0f4420a0afb9950f',
  'baselineSnapshotDigest',snapshot,'catalogEntryDigest',catalog,'sourceProjectionIdentity',projection->>'database_projection_identity',
  'sourceLunchIdentity',lunch->>'document_identity','assignmentCount',346,'lunchCount',40,'acceptedExceptions',exceptions,
  'adjustmentReasons',reasons,'participants',participants,'employmentByDate',employment,'existingProjectionId',existing);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_read_manual_repeat_confirmation(p_manager uuid, p_request uuid, p_credential uuid, p_device text, p_access text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();
 PERFORM public.custodial_action_actor_v1(p_manager,p_credential,p_device,p_access,'read');
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 SELECT jsonb_build_object('request',request_json,'receipt',receipt_json) INTO result FROM public.static_weekly_manual_repeat_confirmations WHERE manager_id=p_manager AND request_id=p_request;
 RETURN result; -- NULL is absence DATA, not retry/resend permission.
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_read_original_staffing_outcome_v1(p_manager_id uuid, p_idempotency_key text, p_operation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE original public.weekly_schedule_command_receipts%rowtype;completed jsonb;
 projection_receipt public.weekly_schedule_command_receipts%rowtype;
 original_projection public.weekly_schedule_compiled_projections%rowtype;
 original_lunch public.weekly_schedule_lunch_documents%rowtype;
 request jsonb;persisted_candidate jsonb;worker_candidate jsonb;
 projection_key text;service_date date;week_start date;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();
 PERFORM public.custodial_assert_manager(p_manager_id);
 PERFORM public.static_weekly_v3_manager_actor(p_manager_id);
 IF p_manager_id IS NULL OR p_operation IS NULL
  OR p_operation NOT IN ('vacate_roster_slot','fill_vacant_slot','restore_existing_employee')
  OR nullif(btrim(p_idempotency_key),'') IS NULL OR p_idempotency_key<>btrim(p_idempotency_key)
  OR char_length(p_idempotency_key)>200 THEN
  RAISE EXCEPTION USING errcode='22023',message='Exact original staffing manager, operation and key required';
 END IF;
 SELECT * INTO original FROM public.weekly_schedule_command_receipts
  WHERE actor_manager_id=p_manager_id AND idempotency_key=p_idempotency_key AND command_type=p_operation;
 IF NOT FOUND THEN RETURN jsonb_build_object('schema','custodial.original-staffing-outcome.v1',
  'state','OUTCOME_UNCONFIRMED','manager_id',p_manager_id,'operation',p_operation,
  'idempotency_key',p_idempotency_key,'retry_safe',false,'phone_released',false);END IF;
 PERFORM public.static_weekly_v8_assert_vacancy_receipt(original.command_id,p_operation);
 completed:=public.static_weekly_v9_read_completed_roster_change(p_manager_id,p_idempotency_key,p_operation);
 IF completed IS NULL THEN RAISE EXCEPTION USING errcode='23514',message='Original staffing completion unavailable';END IF;

 IF p_operation='vacate_roster_slot' THEN
  -- v9 already verifies the original mutation/projection revision chain and
  -- original paired lunch. Repeat full immutable row/request relationships;
  -- never resolve today's latest projection or adopt a caller's saved hash.
  IF original.response_json#>>'{data,completion_mode}' IS DISTINCT FROM 'projection_required'
   OR jsonb_typeof(completed->'data') IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION USING errcode='23514',message='Original vacancy prepared plan is unavailable';
  END IF;
  projection_key:='projection-'||public.static_weekly_digest_text(p_idempotency_key);
  SELECT * INTO projection_receipt FROM public.weekly_schedule_command_receipts
   WHERE actor_manager_id=p_manager_id AND idempotency_key=projection_key AND command_type='materialize_projection';
  IF NOT FOUND THEN
   RAISE EXCEPTION USING errcode='23514',message='Original vacancy projection command is unavailable';
  END IF;
  PERFORM public.static_weekly_v8_assert_vacancy_receipt(projection_receipt.command_id,'materialize_projection');
  request:=projection_receipt.request_canonical_json;
  service_date:=(original.request_canonical_json->>'effective_start')::date;
  week_start:=service_date-(extract(isodow FROM service_date)::integer-1);
  IF projection_receipt.expected_revision IS DISTINCT FROM original.expected_revision+1
   OR (projection_receipt.response_json->>'revision')::bigint IS DISTINCT FROM original.expected_revision+2
   OR request->>'publication_id' IS DISTINCT FROM original.response_json#>>'{data,original_publication_id}'
   OR request->>'service_date' IS DISTINCT FROM week_start::text
   OR (completed->>'revision')::bigint IS DISTINCT FROM original.expected_revision+2
   OR completed#>>'{data,projection_id}' IS DISTINCT FROM projection_receipt.response_json#>>'{data,projection_id}' THEN
   RAISE EXCEPTION USING errcode='23514',message='Original vacancy prepared plan command binding changed';
  END IF;
  SELECT * INTO original_projection FROM public.weekly_schedule_compiled_projections
   WHERE projection_id=(projection_receipt.response_json#>>'{data,projection_id}')::uuid;
  IF NOT FOUND
   OR original_projection.publication_id::text IS DISTINCT FROM request->>'publication_id'
   OR original_projection.week_start IS DISTINCT FROM week_start
   OR original_projection.week_end IS DISTINCT FROM week_start+6
   OR original_projection.compiled_by_manager_id IS DISTINCT FROM p_manager_id
   OR original_projection.exception_set_digest IS DISTINCT FROM request->>'exception_set_digest'
   OR public.static_weekly_digest_jsonb(original_projection.exception_set_json) IS DISTINCT FROM original_projection.exception_set_digest
   OR original_projection.compiler_version IS DISTINCT FROM request->>'compiler_version'
   OR original_projection.objective_json IS DISTINCT FROM request->'objective'
   OR original_projection.metrics_json IS DISTINCT FROM request->'metrics'
   OR original_projection.replay_digest IS DISTINCT FROM request->>'replay_digest'
   OR original_projection.projection_envelope IS DISTINCT FROM request->'projection_envelope'
   OR original_projection.authority_digest IS DISTINCT FROM request#>>'{projection_envelope,authority_digest}'
   OR original_projection.receipt_json IS DISTINCT FROM request#>'{projection_envelope,receipt}'
   OR completed#>>'{data,current_projection,projection_id}' IS DISTINCT FROM original_projection.projection_id::text
   OR completed#>>'{data,current_projection,publication_id}' IS DISTINCT FROM original_projection.publication_id::text
   OR completed#>>'{data,current_projection,version_id}' IS DISTINCT FROM original_projection.version_id::text THEN
   RAISE EXCEPTION USING errcode='23514',message='Original vacancy complete prepared projection is inconsistent';
  END IF;
  -- The existing owning assertion checks the CLOSED complete envelope,
  -- source/semantic identity and real versioned HMAC through the normal key
  -- verifier. No key is read or emitted by this reader and no grant is added.
  PERFORM public.static_weekly_assert_projection_envelope_attested(
   original_projection.projection_envelope,original_projection.publication_id,
   original_projection.week_start,original_projection.exception_set_json);
  PERFORM public.static_weekly_assert_authority_attestation(
   original_projection.projection_envelope->'attestation','dated_projection',
   public.static_weekly_projection_attestation_payload(original_projection.projection_envelope));
  SELECT * INTO original_lunch FROM public.weekly_schedule_lunch_documents
   WHERE projection_id=original_projection.projection_id;
  IF NOT FOUND OR original_lunch.accepted_by_manager_id IS DISTINCT FROM p_manager_id
   OR original_lunch.document_identity IS DISTINCT FROM original_lunch.document_json->>'document_identity'
   OR original_lunch.document_json->>'base_authority_digest' IS DISTINCT FROM original_projection.authority_digest
   OR original_lunch.document_json->>'base_replay_digest' IS DISTINCT FROM original_projection.replay_digest THEN
   RAISE EXCEPTION USING errcode='23514',message='Original vacancy paired lunch identity changed';
  END IF;
  PERFORM public.static_weekly_v8_assert_lunch_document(original_projection.projection_id,original_lunch.document_json);
  -- Exact camel DTO mirrors the pure prepared candidate's 12 RPC fields.
  -- The fixed writer stores snake keys; idempotency is the actual receipt key.
  persisted_candidate:=jsonb_build_object(
   'publicationId',request->'publication_id','serviceDate',request->'service_date',
   'exceptionSetDigest',request->'exception_set_digest','compilerVersion',request->'compiler_version',
   'objective',request->'objective','metrics',request->'metrics','replayDigest',request->'replay_digest',
   'envelope',request->'projection_envelope','expectedRevision',request->'expected_revision',
   'actorManagerId',request->'actor_manager_id','idempotencyKey',projection_receipt.idempotency_key,
   'lunchDocument',original_lunch.document_json);
  -- Only v3's source-proved server-added TOP-LEVEL attestation is removed.
  -- Owning assertion above rejects unknown envelope fields/signatures. Keep
  -- complete worker identity/receipt/authority/compiler/source/lunch bytes.
  worker_candidate:=jsonb_set(persisted_candidate,'{envelope}',
   original_projection.projection_envelope-'attestation',false);
  completed:=jsonb_set(completed,'{data}',completed->'data'||jsonb_build_object(
   'persisted_projection_digest',public.static_weekly_digest_jsonb(persisted_candidate),
   'worker_candidate_digest',public.static_weekly_digest_jsonb(worker_candidate),
   'paired_lunch_document_identity',original_lunch.document_identity,
   'projection_authority_digest',original_projection.authority_digest),false);
 END IF;
 RETURN jsonb_build_object('schema','custodial.original-staffing-outcome.v1','state','ACCEPTED_ORIGINAL',
  'manager_id',p_manager_id,'operation',p_operation,'idempotency_key',p_idempotency_key,
  'command_id',original.command_id,'original_request',original.request_canonical_json,
  'original_request_digest',original.request_digest,'receipt',completed,'retry_safe',false,'phone_released',false);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_read_vacancy_reviewed_preparation(p_manager uuid, p_credential uuid, p_device text, p_access text, p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor jsonb;generation bigint;r public.static_weekly_vacancy_reviewed_preparations%rowtype;BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();generation:=public.custodial_begin_application_mutation();
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 actor:=public.custodial_action_actor_v1(p_manager,p_credential,p_device,p_access,'read');
 IF p_key IS NULL OR length(p_key) NOT BETWEEN 1 AND 200 OR p_key<>btrim(p_key) OR p_key~'[[:cntrl:]]'
 THEN RAISE EXCEPTION 'Vacancy exact original read key required';END IF;
 SELECT * INTO r FROM public.static_weekly_vacancy_reviewed_preparations WHERE manager_id=p_manager AND idempotency_key=p_key FOR SHARE;
 IF NOT FOUND THEN RETURN jsonb_build_object('found',false);END IF;
 IF r.credential_id IS DISTINCT FROM p_credential OR r.device_identifier IS DISTINCT FROM p_device THEN
  RAISE EXCEPTION USING errcode='42501',message='Vacancy original private review actor mismatch';END IF;
 RETURN public.static_weekly_vacancy_reviewed_descriptor(r,
  public.static_weekly_vacancy_reviewed_current(r,generation,actor->>'manager_name'),true);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_register_approved_template(p_source_id uuid, p_template jsonb, p_binding jsonb, p_owner_config jsonb, p_approval_evidence jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare id text;count_people integer;body jsonb;entry_digest text;prior record;source_row record;
begin
 perform public.static_weekly_v3_assert_release_operator();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select * into source_row from public.static_weekly_authority_source_documents
  where source_id=p_source_id and active and retired_at is null for share;
 if not found or source_row.source_digest is distinct from public.static_weekly_digest_jsonb(source_row.canonical_source) then
  raise exception using errcode='23514',message='approved template requires an exact active registered current source';end if;
 perform public.static_weekly_assert_exact_object(p_template,
  array['templateId','staffingCount','source','roleSlotIds'],
  array['templateId','staffingCount','source','roleSlotIds'],'approved static template');
 perform public.static_weekly_assert_exact_object(p_binding,
  array['schema','templateId','staffingCount','sourceDigest','roleSlotIdsDigest','patternAuthority','artifactSha256','ownerConfigDigest','patternPublicationStatus'],
  array['schema','templateId','staffingCount','sourceDigest','roleSlotIdsDigest','patternAuthority','artifactSha256','ownerConfigDigest','patternPublicationStatus'],'approved static binding');
 id:=p_template->>'templateId';
 if id is null or length(id) not between 1 and 160
  or jsonb_typeof(p_template->'staffingCount') is distinct from 'number'
  or (p_template->>'staffingCount')!~'^[1-9][0-9]?$'
  or jsonb_typeof(p_template->'source') is distinct from 'object'
  or jsonb_typeof(p_template->'roleSlotIds') is distinct from 'array'
  or jsonb_typeof(p_owner_config) is distinct from 'object'
  or jsonb_typeof(p_approval_evidence) is distinct from 'object'
  or p_binding->>'schema' is distinct from 'custodial.approved-static-template-binding.v1'
  or p_binding->>'templateId' is distinct from id
  or p_binding->'staffingCount' is distinct from p_template->'staffingCount'
  or p_binding->>'patternAuthority' is distinct from 'OWNER_APPROVED_OPERATIONAL_PATTERN'
  or p_approval_evidence->>'classification' is distinct from 'OWNER_APPROVED_OPERATIONAL_PATTERN'
  or coalesce(p_approval_evidence->>'sourceReference','')=''
  or coalesce(p_approval_evidence->>'ownerDecisionReference','')=''
  or p_approval_evidence->>'artifactSha256' is distinct from p_binding->>'artifactSha256'
  or exists(select 1 from unnest(array['sourceDigest','roleSlotIdsDigest','artifactSha256','ownerConfigDigest']) key
     where coalesce(p_binding->>key,'')!~'^[0-9a-f]{64}$') then
  raise exception using errcode='23514',message='exact approved artifact, owner decision and complete template/config binding required';end if;
 count_people:=(p_template->>'staffingCount')::integer;
 if count_people not between 1 and 32 or jsonb_array_length(p_template->'roleSlotIds')<>count_people
  or exists(select 1 from jsonb_array_elements(p_template->'roleSlotIds') item
      where jsonb_typeof(item) is distinct from 'string' or coalesce(item#>>'{}','')='')
  or (select count(distinct item#>>'{}') from jsonb_array_elements(p_template->'roleSlotIds') item)<>count_people then
  raise exception using errcode='23514',message='approved role identities must be complete and unique';end if;
 body:=jsonb_build_object('template',p_template,'binding',p_binding,'ownerConfig',p_owner_config,'approvalEvidence',p_approval_evidence);
 entry_digest:=public.static_weekly_digest_jsonb(body);
 select * into prior from public.static_weekly_approved_template_catalog where template_id=id;
 if found then
  if prior.catalog_entry_digest is distinct from entry_digest then
   raise exception using errcode='23505',message='approved template ID already binds different immutable bytes';end if;
 else
  insert into public.static_weekly_approved_template_catalog
   (template_id,staffing_count,template_json,binding_json,owner_config,approval_evidence,catalog_entry_digest)
   values(id,count_people,p_template,p_binding,p_owner_config,p_approval_evidence,entry_digest);
 end if;
 if exists(select 1 from public.static_weekly_approved_template_retirements where template_id=id) then
  raise exception using errcode='23514',message='retired template cannot be readmitted under the same identity';end if;
 insert into public.static_weekly_approved_template_source_configs(source_id,owner_config,config_digest)
  values(p_source_id,p_owner_config,public.static_weekly_digest_jsonb(p_owner_config)) on conflict(source_id) do nothing;
 if not exists(select 1 from public.static_weekly_approved_template_source_configs
   where source_id=p_source_id and owner_config=p_owner_config and config_digest=public.static_weekly_digest_jsonb(p_owner_config)) then
  raise exception using errcode='23505',message='current source already binds a different owner configuration';end if;
 return jsonb_build_object('registered',true,'template_id',id,'catalog_entry_digest',entry_digest,'published',false);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_register_manual_activation_packet(p_packet uuid, p_source uuid, p_template text, p_manager uuid, p_transition jsonb, p_feasibility jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare snapshot jsonb;entry public.static_weekly_approved_template_catalog%rowtype;source jsonb;body jsonb;
begin
 perform public.static_weekly_v3_assert_release_operator();perform public.static_weekly_v3_manager_actor(p_manager);
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 snapshot:=public.static_weekly_manual_roster_snapshot(public.sch_service_date(statement_timestamp()));
 select * into strict entry from public.static_weekly_approved_template_catalog where template_id=p_template;
 select canonical_source into strict source from public.static_weekly_authority_source_documents where source_id=p_source and active and retired_at is null;
 perform public.static_weekly_assert_manual_roster_transition(p_transition,snapshot,entry.owner_config);
 if p_feasibility->>'schema' is distinct from 'custodial.approved-static-feasibility.v1'
  or p_feasibility->'candidateSource' is distinct from source or entry.template_json->'source' is distinct from source
  or p_feasibility#>>'{mapping,templateId}' is distinct from p_template
  or p_feasibility#>'{mapping,unchanged}' is distinct from 'true'::jsonb
  or source#>>'{version,manualGroupRatingAuthority,manifestSha256}' is distinct from 'fe02bbdebc736d95360b55cc7dfe5b73c5a9eaa76f364f1c0f4420a0afb9950f'
  or entry.binding_json->>'artifactSha256' is distinct from '3942a5d77774a3dcc8a8ab3e572d02716efaae3428a015f076bdbd8c5e1ec2dd'
  or source->>'serviceDate' is distinct from snapshot->>'serviceDate'
  or source#>>'{version,effectiveStart}' is distinct from snapshot->>'serviceDate'
  or p_feasibility#>>'{initialBaseline,projection,week_end}' is distinct from ((snapshot->>'serviceDate')::date+6)::text then
  raise exception using errcode='23514',message='manual activation requires the exact admitted unchanged seven-day source and current-date feasibility';end if;
 body:=jsonb_build_object('packetDigest',public.static_weekly_manual_activation_packet_fingerprint(p_source,p_template,p_manager,p_transition,p_feasibility));
 insert into public.static_weekly_manual_activation_packets(packet_id,source_id,template_id,service_date,manager_id,transition_json,feasibility_json,packet_digest)
 values(p_packet,p_source,p_template,(snapshot->>'serviceDate')::date,p_manager,p_transition,p_feasibility,body->>'packetDigest');
 return jsonb_build_object('registered',true,'packetId',p_packet,'packetDigest',body->>'packetDigest','published',false);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_reject_legacy_daily_schedule_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_payload jsonb;
  v_date date;
  v_dates date[] := array[]::date[];
  v_authority record;
begin
  if tg_op <> 'INSERT' then
    v_payload := to_jsonb(old);
    v_date := case tg_table_name
      when 'daily_schedule_assignments' then nullif(v_payload->>'service_date','')::date
      when 'daily_work_roster' then nullif(v_payload->>'service_date','')::date
      when 'daily_group_assignments' then nullif(v_payload->>'assignment_date','')::date
      when 'daily_absence_overrides' then nullif(v_payload->>'absence_date','')::date
      else null
    end;
    if v_date is not null then v_dates := array_append(v_dates,v_date); end if;
  end if;

  if tg_op <> 'DELETE' then
    v_payload := to_jsonb(new);
    v_date := case tg_table_name
      when 'daily_schedule_assignments' then nullif(v_payload->>'service_date','')::date
      when 'daily_work_roster' then nullif(v_payload->>'service_date','')::date
      when 'daily_group_assignments' then nullif(v_payload->>'assignment_date','')::date
      when 'daily_absence_overrides' then nullif(v_payload->>'absence_date','')::date
      else null
    end;
    if v_date is not null and not v_date=any(v_dates) then
      v_dates := array_append(v_dates,v_date);
    end if;
  end if;

  if cardinality(v_dates)=0 then
    raise exception using errcode='22023',
      message='legacy schedule write did not identify one service date';
  end if;

  foreach v_date in array v_dates loop
    select * into strict v_authority
    from public.static_weekly_v6_schedule_authority_state(v_date);
    if v_authority.governed then
      raise exception using errcode='55000',
        message='legacy daily schedule writes are retired for static-weekly governed dates',
        detail='service_date='||v_date::text||'; projection_status='||v_authority.projection_status,
        hint='Use the static-weekly append-only dated-change control plane.';
    end if;
  end loop;

  if tg_op='DELETE' then return old; end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_revoke_coverall_link(p_manager uuid, p_credential uuid, p_device text, p_access text, p_link uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare actor jsonb;link public.static_weekly_coverall_access_links%rowtype;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 actor:=public.custodial_action_actor_v1(p_manager,p_credential,p_device,p_access,'manage_coverall');
 select * into link from public.static_weekly_coverall_access_links where manager_id=p_manager and link_id=p_link for update;
 -- Capture FOUND before rechecking current credential after a possible row wait.
 if found then
  actor:=public.custodial_action_actor_v1(p_manager,p_credential,p_device,p_access,'manage_coverall');
 else
  actor:=public.custodial_action_actor_v1(p_manager,p_credential,p_device,p_access,'manage_coverall');
  -- Durable nonsecret tombstone settles an unknown issuance and prevents a
  -- delayed original POST from creating this request after revocation ACK.
  insert into public.static_weekly_coverall_access_links(link_id,token_hash,binding,manager_id,credential_id,device_id,session_access,created_at,expires_at,revoked_at,revoked_by)
   values(p_link,public.static_weekly_digest_text('revoked-coverall-request:'||p_manager::text||':'||p_link::text),'{}'::jsonb,p_manager,p_credential,p_device,p_access,
    statement_timestamp(),statement_timestamp()+interval '1 second',statement_timestamp(),p_manager);
  return jsonb_build_object('link_id',p_link,'revoked',true);
 end if;
 -- Revocation is exact issuer scope. Cross-issuer administrative revocation
 -- requires a separate explicit issuer context, never a guessed request ID.
 update public.static_weekly_coverall_access_links set revoked_at=coalesce(revoked_at,clock_timestamp()),revoked_by=coalesce(revoked_by,p_manager) where manager_id=p_manager and link_id=p_link;
 return jsonb_build_object('link_id',p_link,'revoked',true);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_sch022_candidate_witness(p_candidates jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare candidate jsonb;one text;records jsonb:='[]'::jsonb;target_count integer:=0;
 no_target text:=public.static_weekly_digest_jsonb(jsonb_build_object('sch022','NO_TARGET_V1'));
begin
 if jsonb_typeof(p_candidates)<>'array' or jsonb_array_length(p_candidates)>100000 then
  raise exception using errcode='22023',message='SCH022 requires bounded staffing candidates';end if;
 for candidate in select value from jsonb_array_elements(p_candidates) value
  where value->>'candidateKind'='projection' order by value->>'serviceDate',value->>'candidateKey' loop
  if candidate->>'serviceDate'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
   raise exception using errcode='22023',message='SCH022 staffing candidate week is invalid';end if;
  one:=public.static_weekly_sch022_work_witness((candidate->>'serviceDate')::date,
   public.static_weekly_sch022_projection_work(candidate->'payload'));
  if one<>no_target then target_count:=target_count+1;end if;
  records:=records||jsonb_build_array(jsonb_build_object('week_start',candidate->>'serviceDate','catalog_witness',one));
 end loop;
 return jsonb_build_object('digest',public.static_weekly_digest_jsonb(records),'target_week_count',target_count);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_sch022_exception_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare work jsonb;
begin
 if new.exception_type='event_impact' then
  select coalesce(jsonb_agg(public.static_weekly_sch022_normalize_work(
   nullif(item->>'locationId','')::uuid,item->>'locationCodeSnapshot',
   coalesce(item->'includedLocations','[]'::jsonb))),'[]'::jsonb) into work
  from (select value item from jsonb_array_elements(new.payload_json->'patchWork')
   union all select value from jsonb_array_elements(new.payload_json->'addWork')) source;
  perform public.static_weekly_sch022_work_witness(new.service_date,work);
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_sch022_group_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare identity_changed boolean;
begin
 if tg_op='DELETE' then identity_changed:=true;
 else identity_changed:=new.id is distinct from old.id or new.group_code is distinct from old.group_code;end if;
 if old.group_code='SPLASH_PAD_RESTROOMS'
  and identity_changed
  and exists(select 1 from public.location_group_memberships m where m.location_group_id=old.id
   and public.static_weekly_sch022_retained_member_referenced(m.location_id)) then
  raise exception using errcode='23514',message='SCH022 accepted Splash group identity cannot be deleted or renamed';
 end if;
 if tg_op='DELETE' then return old;end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_sch022_membership_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare identity_changed boolean;
begin
 if tg_op='DELETE' then identity_changed:=true;
 else identity_changed:=new.location_group_id is distinct from old.location_group_id
   or new.location_id is distinct from old.location_id;end if;
 if identity_changed
  and exists(select 1 from public.location_groups g where g.id=old.location_group_id
   and g.group_code='SPLASH_PAD_RESTROOMS')
