CREATE OR REPLACE FUNCTION public.static_weekly_sch022_projection_work(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare assignments jsonb;work jsonb;
begin
 assignments:=p_payload#>'{envelope,assignments}';
 if jsonb_typeof(assignments)<>'array' or jsonb_array_length(assignments)>10000 then
  raise exception using errcode='23514',message='SCH022 staged projection assignments unavailable';end if;
 if exists(select 1 from jsonb_array_elements(assignments) item
  where jsonb_typeof(item->'work_snapshot')<>'object') then
  raise exception using errcode='23514',message='SCH022 staged projection work identity unavailable';end if;
 select coalesce(jsonb_agg(public.static_weekly_sch022_normalize_work(
  nullif(item#>>'{work_snapshot,locationId}','')::uuid,item#>>'{work_snapshot,locationCodeSnapshot}',
  coalesce(item#>'{work_snapshot,includedLocations}','[]'::jsonb)) order by item->>'work_id'),'[]'::jsonb)
 into work from jsonb_array_elements(assignments) item;
 return work;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_sch022_staffing_accept_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare current_witness jsonb;prior public.static_weekly_sch022_staffing_witnesses%rowtype;
begin
 if old.state='PREPARED' and new.state='ACCEPTED' then
  current_witness:=public.static_weekly_sch022_staged_witness(new.operation_id);
  select * into prior from public.static_weekly_sch022_staffing_witnesses where operation_id=new.operation_id;
  if found then
   if prior.witness_digest is distinct from current_witness->>'digest'
    or prior.target_week_count is distinct from (current_witness->>'target_week_count')::integer
    or prior.manager_id is distinct from new.confirmed_by_manager_id
    or prior.preview_digest is distinct from new.preview_digest then
    raise exception using errcode='40001',message='SCH022 staffing confirmation requires a current exact catalog preview';end if;
  elsif (current_witness->>'target_week_count')::integer>0 then
   raise exception using errcode='23514',message='SCH022 target-bearing staffing confirmation has no prepared catalog witness';
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_sch022_stage_staffing_command(p_operation_id uuid, p_candidates jsonb, p_preview_digest text, p_input_digest text, p_publication_vector jsonb, p_manager_id uuid, p_witness_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare before_state text;staged jsonb;current_witness jsonb;prior public.static_weekly_sch022_staffing_witnesses%rowtype;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform public.static_weekly_v3_manager_actor(p_manager_id);
 if p_witness_digest is null or p_witness_digest!~'^[0-9a-f]{64}$' then
  raise exception using errcode='22023',message='SCH022 exact staffing preview witness required';end if;
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select state into before_state from public.static_weekly_staffing_commands where operation_id=p_operation_id for update;
 staged:=public.static_weekly_v10_stage_staffing_command(p_operation_id,p_candidates,p_preview_digest,
  p_input_digest,p_publication_vector,p_manager_id);
 current_witness:=public.static_weekly_sch022_staged_witness(p_operation_id);
 if current_witness->>'digest' is distinct from p_witness_digest then
  raise exception using errcode='40001',message='SCH022 staffing catalog changed since manager preview';end if;
 select * into prior from public.static_weekly_sch022_staffing_witnesses where operation_id=p_operation_id;
 if found then
  if prior.manager_id is distinct from p_manager_id or prior.witness_digest is distinct from p_witness_digest
   or prior.preview_digest is distinct from p_preview_digest then
   raise exception using errcode='23505',message='SCH022 staffing witness replay identity changed';end if;
 elsif before_state='PREPARING' then
  insert into public.static_weekly_sch022_staffing_witnesses(operation_id,manager_id,witness_digest,target_week_count,preview_digest)
  values(p_operation_id,p_manager_id,p_witness_digest,(current_witness->>'target_week_count')::integer,p_preview_digest);
 elsif (current_witness->>'target_week_count')::integer>0 then
  raise exception using errcode='23514',message='SCH022 protected target-bearing staffing preview has no original witness';
 end if;
 return staged;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_sch022_work_witness(p_service_date date, p_work jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare g public.location_groups%rowtype;w jsonb;included jsonb;id_text text;
 target boolean:=false; unbound_target boolean:=false; member_ids uuid[];retained_ids uuid[];
 included_ids uuid[]:=array[]::uuid[];row_ids uuid[];row_target boolean;
 source_rows jsonb;v_head jsonb;result text;
begin
 if p_service_date is null or jsonb_typeof(p_work) is distinct from 'array'
  or jsonb_array_length(p_work)>10000 then
  raise exception using errcode='22023',message='SCH022 requires bounded typed work and an exact service date';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 lock table public.location_groups,public.location_group_memberships,public.locations,
  public.custodial_place_source_versions in share mode;
 select * into g from public.location_groups where group_code='SPLASH_PAD_RESTROOMS' for share;
 select coalesce(array_agg(distinct m.location_id order by m.location_id) filter(where m.active=true),array[]::uuid[]),
  coalesce(array_agg(distinct m.location_id order by m.location_id),array[]::uuid[])
 into member_ids,retained_ids from public.location_group_memberships m where m.location_group_id=g.id;
 for w in select value from jsonb_array_elements(p_work) loop
  if jsonb_typeof(w) is distinct from 'object'
   or (select array_agg(key order by key) from jsonb_object_keys(w) key)
      is distinct from array['includedLocationIds','locationCode','locationId']::text[]
   or jsonb_typeof(w->'locationCode') is distinct from 'string'
   or jsonb_typeof(w->'includedLocationIds') is distinct from 'array'
   or jsonb_array_length(w->'includedLocationIds')>256 then
   raise exception using errcode='22023',message='SCH022 typed work identity is invalid';
  end if;
  included:=w->'includedLocationIds';row_ids:=array[]::uuid[];
  if jsonb_typeof(w->'locationId') not in ('string','null') then
   raise exception using errcode='22023',message='SCH022 typed work location identity is invalid';
  end if;
  if w->>'locationId' is not null then
   begin row_ids:=array_append(row_ids,(w->>'locationId')::uuid);
   exception when invalid_text_representation then
    raise exception using errcode='22023',message='SCH022 typed work location UUID is invalid';end;
  end if;
  for id_text in select value from jsonb_array_elements_text(included) value loop
   begin row_ids:=array_append(row_ids,id_text::uuid);
   exception when invalid_text_representation then
    raise exception using errcode='22023',message='SCH022 included location UUID is invalid';end;
  end loop;
  row_target:=w->>'locationCode'='SPLASH_PAD_RESTROOMS' or (g.id is not null and
   exists(select 1 from unnest(row_ids) member(member_id)
    where member.member_id=g.id or member.member_id=any(retained_ids)));
  if row_target then
   target:=true;included_ids:=included_ids||row_ids;
   if not exists(select 1 from unnest(row_ids) member(member_id)
    where member.member_id=any(member_ids)) then unbound_target:=true;end if;
  end if;
 end loop;
 if not target then return public.static_weekly_digest_jsonb(jsonb_build_object('sch022','NO_TARGET_V1'));end if;
 if g.id is null or g.active is not true then
  raise exception using errcode='23514',message='Splash Pad Restrooms duty requires the exact active custodial group';
 end if;
 if p_service_date<date '2027-05-31' then
  raise exception using errcode='23514',message='Splash Pad Restrooms coverage is inactive before Memorial Day 2027';
 end if;
 if cardinality(member_ids)=0 or unbound_target or exists(select 1 from unnest(included_ids) member(member_id)
  where member.member_id<>g.id and member.member_id<>all(member_ids)) then
  raise exception using errcode='23514',message='Splash Pad Restrooms duty must bind current exact group members';
 end if;
 if exists(select 1 from unnest(member_ids) member(member_id) left join public.locations l on l.id=member.member_id
  where l.id is null or l.active is not true) then
  raise exception using errcode='23514',message='Splash Pad Restrooms has an inactive or unbound physical member';
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',l.id,'source',public.place_source_row('physical_location',l.id),
  'source_updated_at',l.updated_at,
  'place_head',(select jsonb_build_object('revision',v.revision,'effective_at',v.effective_at,'source_row_sha256',v.source_row_sha256)
   from public.custodial_place_source_versions v where v.legacy_kind='physical_location' and v.legacy_id=l.id
   order by v.revision desc limit 1)) order by l.id),'[]'::jsonb)
 into source_rows from public.locations l where l.id=any(member_ids);
 select jsonb_build_object('revision',v.revision,'effective_at',v.effective_at,'source_row_sha256',v.source_row_sha256)
 into v_head from public.custodial_place_source_versions v
 where v.legacy_kind='location_group' and v.legacy_id=g.id order by v.revision desc limit 1;
 result:=public.static_weekly_digest_jsonb(jsonb_build_object('sch022','TARGET_V1','group_id',g.id,
  'group_source',public.place_source_row('location_group',g.id),'group_place_head',v_head,
  'membership_revisions',(select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'location_id',m.location_id,
   'active',m.active,'updated_at',m.updated_at) order by m.id),'[]'::jsonb)
   from public.location_group_memberships m where m.location_group_id=g.id),
  'members',source_rows,'start',date '2027-05-31'));
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_source_window_start(p_source jsonb, p_date date)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare version jsonb;start date;
begin
 version:=coalesce(p_source->'version',p_source#>'{versions,0}');
 if version#>>'{manualGroupRatingAuthority,manifestSha256}'='fe02bbdebc736d95360b55cc7dfe5b73c5a9eaa76f364f1c0f4420a0afb9950f' then
  start:=(version->>'effectiveStart')::date;
  if start is null or p_date is null or not isfinite(start) or not isfinite(p_date) or p_date<start then
   raise exception using errcode='23514',message='manual weekly window requires its exact effective source date';end if;
  return p_date-mod(p_date-start,7);
 end if;
 return p_date-(extract(isodow from p_date)::integer-1);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_staffing_period_frames(p_operation uuid, p_manager uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare ctx jsonb;frames jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 ctx:=public.static_weekly_pending_context(p_operation,p_manager);
 select jsonb_agg(jsonb_build_object('serviceDate',d::date::text,
  'frameStart',public.static_weekly_projection_window_start(d::date)::text) order by d) into frames
  from generate_series((ctx#>>'{originalCommand,semanticBody,startDate}')::date,
   (ctx#>>'{originalCommand,semanticBody,endDate}')::date,'1 day') d;
 return jsonb_build_object('schema','custodial.staffing-source-period-frames.v1','originalCommand',ctx->'originalCommand','frames',frames);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_stage_manual_recurring(p_operation uuid, p_manager uuid, p_envelope jsonb, p_lunch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE ctx jsonb;prior custodial_coverall.recurring_materialization_stages%rowtype;fingerprint text;
BEGIN
 ctx:=public.static_weekly_manual_recurring_context(p_operation,p_manager);PERFORM public.custodial_begin_application_mutation();
 IF p_envelope IS NULL OR p_lunch IS NULL OR pg_column_size(p_envelope)>16777216 OR pg_column_size(p_lunch)>16777216
 THEN RAISE EXCEPTION 'Bounded actual native recurring projection and lunch required';END IF;
 fingerprint:=public.static_weekly_digest_jsonb(jsonb_build_object('envelope',p_envelope,'lunch',p_lunch));
 SELECT * INTO prior FROM custodial_coverall.recurring_materialization_stages WHERE operation_id=p_operation;
 IF FOUND THEN
  IF prior.envelope_json IS DISTINCT FROM p_envelope OR prior.lunch_json IS DISTINCT FROM p_lunch OR prior.candidate_digest<>fingerprint
  THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='Original recurring candidate conflict';END IF;
 ELSE INSERT INTO custodial_coverall.recurring_materialization_stages VALUES(p_operation,p_envelope,p_lunch,fingerprint);END IF;
 PERFORM public.static_weekly_manual_recurring_assert_payload(p_operation,p_manager,p_envelope);
 RETURN jsonb_build_object('state','STAGED_UNCOMMITTED','operationId',p_operation,'candidateDigest',fingerprint,'committed',false);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_stage_vacancy_reviewed_preparation(p_manager uuid, p_credential uuid, p_device text, p_access text, p_key text, p_packet_utf8 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor jsonb;generation bigint;packet jsonb;v jsonb;r public.static_weekly_vacancy_reviewed_preparations%rowtype;
 prior public.static_weekly_vacancy_reviewed_preparations%rowtype;BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();generation:=public.custodial_begin_application_mutation();
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 actor:=public.custodial_action_actor_v1(p_manager,p_credential,p_device,p_access,'write');
 packet:=public.static_weekly_vacancy_reviewed_packet(p_packet_utf8,p_manager,p_key);v:=(packet->>'previewUtf8')::jsonb;
 SELECT * INTO prior FROM public.static_weekly_vacancy_reviewed_preparations WHERE manager_id=p_manager AND idempotency_key=p_key FOR UPDATE;
 IF FOUND THEN
  IF prior.credential_id IS DISTINCT FROM p_credential OR prior.device_identifier IS DISTINCT FROM p_device
   OR prior.packet_utf8 IS DISTINCT FROM p_packet_utf8 OR prior.payload_sha256 IS DISTINCT FROM public.static_weekly_digest_text(p_packet_utf8)
   OR public.static_weekly_vacancy_reviewed_current(prior,generation,actor->>'manager_name') IS NOT TRUE
  THEN RAISE EXCEPTION USING errcode='23505',message='Original vacancy review key is occupied or no longer current';END IF;
  RETURN public.static_weekly_vacancy_reviewed_descriptor(prior,true,true);
 END IF;
 IF EXISTS(SELECT 1 FROM public.weekly_schedule_command_receipts WHERE actor_manager_id=p_manager
   AND idempotency_key IN(p_key,'projection-'||public.static_weekly_digest_text(p_key))) THEN
  RAISE EXCEPTION 'Vacancy preview cannot adopt an existing original mutation';END IF;
 r.manager_id:=p_manager;r.idempotency_key:=p_key;r.credential_id:=p_credential;r.device_identifier:=p_device;
 r.generation:=generation;r.state:='UNSUBMITTED';r.packet_utf8:=p_packet_utf8;
 r.payload_sha256:=public.static_weekly_digest_text(p_packet_utf8);r.preview_digest:=v->>'previewDigest';
 r.worker_candidate_digest:=v->>'workerCandidateDigest';r.staged_at:=clock_timestamp();
 IF public.static_weekly_vacancy_reviewed_current(r,generation,actor->>'manager_name') IS NOT TRUE THEN
  RAISE EXCEPTION USING errcode='40001',message='Vacancy original source/revision/current actor changed';END IF;
 INSERT INTO public.static_weekly_vacancy_reviewed_preparations SELECT r.*;
 RETURN public.static_weekly_vacancy_reviewed_descriptor(r,true,false);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v10_ack_device_schedule_application(p_intent_id uuid, p_device_id uuid, p_credential_id uuid, p_employee_id uuid, p_assignment_epoch bigint, p_authority_revision bigint, p_projection_id uuid, p_lunch_document_identity text, p_rendered_digest text, p_applied_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare target public.static_weekly_schedule_application_intents%rowtype;prior public.static_weekly_schedule_application_receipts%rowtype;v_receipt uuid:=gen_random_uuid();
begin
 if p_rendered_digest is null or p_rendered_digest!~'^[0-9a-f]{64}$' or p_applied_at is null
  or p_applied_at>statement_timestamp()+interval '5 minutes' then
  raise exception using errcode='22023',message='invalid schedule application receipt';end if;
 select * into target from public.static_weekly_schedule_application_intents where intent_id=p_intent_id for share;
 if not found or target.device_id is distinct from p_device_id or target.credential_id is distinct from p_credential_id
  or target.employee_id is distinct from p_employee_id or target.assignment_epoch is distinct from p_assignment_epoch
  or target.authority_revision is distinct from p_authority_revision or target.projection_id is distinct from p_projection_id
  or target.lunch_document_identity is distinct from p_lunch_document_identity or p_applied_at<target.created_at then
  raise exception using errcode='23514',message='schedule application receipt does not match its complete target';end if;
 if not exists(select 1 from public.devices d where d.id=p_device_id and d.active=true
   and d.assigned_employee_id=p_employee_id and d.assignment_epoch=p_assignment_epoch)
  or not exists(select 1 from public.device_auth_credentials c where c.credential_id=p_credential_id
   and c.device_id=p_device_id and c.confirmed_at is not null and c.revoked_at is null
   and c.expires_at>statement_timestamp()) then
  raise exception using errcode='42501',message='current schedule application principal is required';end if;
 select * into prior from public.static_weekly_schedule_application_receipts where intent_id=p_intent_id;
 if found then
  if prior.employee_id is distinct from p_employee_id or prior.device_id is distinct from p_device_id
   or prior.credential_id is distinct from p_credential_id or prior.assignment_epoch is distinct from p_assignment_epoch
   or prior.authority_revision is distinct from p_authority_revision or prior.projection_id is distinct from p_projection_id
   or prior.lunch_document_identity is distinct from p_lunch_document_identity
   or prior.rendered_digest is distinct from p_rendered_digest or prior.applied_at is distinct from p_applied_at then
   raise exception using errcode='23505',message='schedule application intent already has a different receipt';end if;
  return jsonb_build_object('intent_id',prior.intent_id,'receipt_id',prior.receipt_id,
   'application_status','DEVICE_REPORTED_APPLIED','received_at',prior.received_at,'replayed',true);
 end if;
 insert into public.static_weekly_schedule_application_receipts(receipt_id,intent_id,employee_id,device_id,
  credential_id,assignment_epoch,authority_revision,projection_id,lunch_document_identity,rendered_digest,applied_at)
 values(v_receipt,p_intent_id,p_employee_id,p_device_id,p_credential_id,p_assignment_epoch,p_authority_revision,
  p_projection_id,p_lunch_document_identity,p_rendered_digest,p_applied_at);
 return jsonb_build_object('intent_id',p_intent_id,'receipt_id',v_receipt,
  'application_status','DEVICE_REPORTED_APPLIED','received_at',statement_timestamp(),'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v10_begin_staffing_command(p_semantic_body jsonb, p_client_prepare_key uuid, p_expected_revision bigint, p_manager_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare actor jsonb; prior public.static_weekly_staffing_commands%rowtype;
 v_operation uuid:=gen_random_uuid();v_command_kind text;v_employee uuid;v_start_date date;v_end_date date;
 v_absence_kind text;v_target_absence uuid;v_current_revision bigint;v_receipt jsonb;v_semantic_digest text;
begin
 perform public.static_weekly_v3_assert_control_plane();
 actor:=public.static_weekly_v3_manager_actor(p_manager_id);
 if jsonb_typeof(p_semantic_body) is distinct from 'object'
  or (select array_agg(key order by key) from jsonb_object_keys(p_semantic_body) key)
   is distinct from array['absenceKind','commandKind','employeeId','endDate','startDate','targetAbsenceId']::text[]
  or p_client_prepare_key is null or p_expected_revision is null or p_expected_revision<0 then
  raise exception using errcode='22023',message='invalid canonical staffing command';
 end if;
 v_semantic_digest:=public.static_weekly_digest_jsonb(p_semantic_body);
 v_command_kind:=p_semantic_body->>'commandKind';
 v_employee:=(p_semantic_body->>'employeeId')::uuid;
 v_start_date:=(p_semantic_body->>'startDate')::date;
 v_end_date:=(p_semantic_body->>'endDate')::date;
 v_absence_kind:=nullif(p_semantic_body->>'absenceKind','');
 v_target_absence:=nullif(p_semantic_body->>'targetAbsenceId','')::uuid;
 if v_start_date>v_end_date or v_end_date-v_start_date>=366
  or (v_command_kind='absence' and (v_absence_kind not in ('daily_absence','pto','unavailable') or v_target_absence is not null))
  or (v_command_kind='cancel_absence' and (v_absence_kind is not null or v_target_absence is null))
  or v_command_kind not in ('absence','cancel_absence') then
  raise exception using errcode='22023',message='invalid staffing command semantics';
 end if;
 select * into prior from public.static_weekly_staffing_commands
  where prepared_by_manager_id=p_manager_id and client_prepare_key=p_client_prepare_key for share;
 if found then
  if prior.semantic_digest is distinct from v_semantic_digest or prior.semantic_body is distinct from p_semantic_body
   or prior.expected_revision is distinct from p_expected_revision then
   raise exception using errcode='23505',message='staffing prepare key was used for different semantics';
  end if;
  return jsonb_build_object('operation_id',prior.operation_id,'state',prior.state,
   'semantic_digest',prior.semantic_digest,'expected_revision',prior.expected_revision,'replayed',true);
 end if;
 if v_command_kind='cancel_absence' and v_start_date<public.sch_service_date(statement_timestamp()) then
  raise exception using errcode='23514',message='staffing cancellation cannot rewrite an elapsed service date';end if;
 select control.current_revision into v_current_revision from public.static_weekly_schedule_control control where control.singleton for share;
 if v_current_revision is distinct from p_expected_revision then
  raise exception using errcode='40001',message='staffing command expected revision is stale';
 end if;
 if v_command_kind='absence' and not exists(select 1 from public.employees where id=v_employee and active=true) then
  raise exception using errcode='23514',message='staffing command employee is not currently active';
 end if;
 if v_command_kind='cancel_absence' and not exists(
  select 1 from public.static_weekly_staffing_absences a
  join public.static_weekly_staffing_commands acceptedcmd
   on acceptedcmd.operation_id=a.accepted_operation_id and acceptedcmd.operation_id=a.absence_id
    and acceptedcmd.command_kind='absence' and acceptedcmd.state='ACCEPTED'
    and acceptedcmd.employee_id=a.employee_id and acceptedcmd.start_date=a.start_date and acceptedcmd.end_date=a.end_date
    and acceptedcmd.absence_kind=a.absence_kind and acceptedcmd.target_absence_id is null
    and acceptedcmd.accepted_revision=a.accepted_revision
    and acceptedcmd.prepared_by_manager_id=a.accepted_by_manager_id
    and acceptedcmd.confirmed_by_manager_id=a.accepted_by_manager_id
    and acceptedcmd.semantic_body=jsonb_build_object('absenceKind',a.absence_kind,'commandKind','absence',
     'employeeId',a.employee_id::text,'endDate',a.end_date::text,'startDate',a.start_date::text,'targetAbsenceId',null)
    and acceptedcmd.semantic_digest=public.static_weekly_digest_jsonb(acceptedcmd.semantic_body)
    and acceptedcmd.accepted_receipt->>'event'='ACCEPTED'
    and acceptedcmd.accepted_receipt->>'operation_id'=acceptedcmd.operation_id::text
    and acceptedcmd.accepted_receipt->>'semantic_digest'=acceptedcmd.semantic_digest
    and acceptedcmd.accepted_receipt->>'authority_revision'=a.accepted_revision::text where a.absence_id=v_target_absence
   and a.employee_id=v_employee and v_start_date=greatest(a.start_date,public.sch_service_date(statement_timestamp())) and v_start_date<=a.end_date and v_end_date=a.end_date
   and not exists(select 1 from public.static_weekly_staffing_absence_cancellations c where c.absence_id=a.absence_id)
 ) then raise exception using errcode='23514',message='cancellation must target the exact uncancelled remaining absence window'; end if;
 perform set_config('app.static_weekly_staffing_write','on',true);
 insert into public.static_weekly_staffing_commands(operation_id,command_kind,employee_id,start_date,end_date,
  absence_kind,target_absence_id,semantic_body,semantic_digest,client_prepare_key,expected_revision,prepared_by_manager_id)
 values(v_operation,v_command_kind,v_employee,v_start_date,v_end_date,v_absence_kind,v_target_absence,p_semantic_body,
  v_semantic_digest,p_client_prepare_key,p_expected_revision,p_manager_id);
 v_receipt:=jsonb_build_object('operation_id',v_operation,'event','PREPARING','manager_id',p_manager_id,
  'semantic_digest',v_semantic_digest,'expected_revision',p_expected_revision,'recorded_at',statement_timestamp());
 insert into public.static_weekly_staffing_command_receipts(operation_id,event_kind,actor_manager_id,
  semantic_digest,receipt_json,receipt_digest)
 values(v_operation,'PREPARING',p_manager_id,v_semantic_digest,v_receipt,public.static_weekly_digest_jsonb(v_receipt));
 return jsonb_build_object('operation_id',v_operation,'state','PREPARING','semantic_digest',v_semantic_digest,
  'expected_revision',p_expected_revision,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v10_cancel_staffing_preparation(p_operation_id uuid, p_manager_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare actor jsonb;command public.static_weekly_staffing_commands%rowtype;v_event text;v_receipt jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();actor:=public.static_weekly_v3_manager_actor(p_manager_id);
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select * into command from public.static_weekly_staffing_commands where operation_id=p_operation_id for update;
 if not found then raise exception using errcode='P0002',message='staffing command is unavailable';end if;
 if command.state='ACCEPTED' then
  return jsonb_build_object('operation_id',command.operation_id,'state','ACCEPTED',
   'accepted_revision',command.accepted_revision,'accepted_receipt',command.accepted_receipt,'cancelled',false);
 end if;
 if command.state in ('CANCELLED','CANCELLED_BY_SUCCESSOR','REJECTED') then
  return jsonb_build_object('operation_id',command.operation_id,'state',command.state,'cancelled',command.state<>'REJECTED','replayed',true);
 end if;
 if command.state not in ('PREPARING','PREPARED') then
  raise exception using errcode='55000',message='staffing command cannot be cancelled from its current state';end if;
 v_event:=case when command.prepared_by_manager_id=p_manager_id then 'CANCELLED' else 'CANCELLED_BY_SUCCESSOR' end;
 perform set_config('app.static_weekly_staffing_write','on',true);
 update public.static_weekly_staffing_commands set state=v_event where operation_id=command.operation_id;
 v_receipt:=jsonb_build_object('operation_id',command.operation_id,'event',v_event,'manager_id',p_manager_id,
  'original_preparer_manager_id',command.prepared_by_manager_id,'semantic_digest',command.semantic_digest,
  'recorded_at',statement_timestamp());
 insert into public.static_weekly_staffing_command_receipts(operation_id,event_kind,actor_manager_id,
  semantic_digest,receipt_json,receipt_digest) values(command.operation_id,v_event,p_manager_id,
  command.semantic_digest,v_receipt,public.static_weekly_digest_jsonb(v_receipt));
 return jsonb_build_object('operation_id',command.operation_id,'state',v_event,'cancelled',true,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v10_read_staffing_command(p_operation_id uuid, p_manager_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare command public.static_weekly_staffing_commands%rowtype;
 original_target jsonb:=null;target_revision bigint;
 preview_weeks jsonb:='[]'::jsonb; prepared_week jsonb; projection record;
 envelope jsonb; availability jsonb; safe_availability jsonb; a jsonb;
 safe_row jsonb; field text; value jsonb; windows jsonb; w jsonb;
 safe_objective jsonb; safe_metrics jsonb; daily jsonb; day_row jsonb;
 loads jsonb; load_row jsonb; safe_load jsonb; safe_day jsonb; weekly jsonb;
 map_value jsonb; pair record; raw_metrics jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();perform public.static_weekly_v3_manager_actor(p_manager_id);
 select * into command from public.static_weekly_staffing_commands where operation_id=p_operation_id;
 if not found then return null; end if;
 -- Cancellation refers to an immutable original absence, not today's incumbent.
 -- Only the authenticated current pending command may expose this private target.
 if command.command_kind='cancel_absence' and command.state in ('PREPARING','PREPARED') then
  if command.prepared_by_manager_id is distinct from p_manager_id then
   raise exception using errcode='42501',message='only original authenticated preparer may read cancellation target';end if;
  select control.current_revision into strict target_revision from public.static_weekly_schedule_control control where control.singleton;
  if command.expected_revision is distinct from target_revision then
   raise exception using errcode='40001',message='original cancellation target revision is stale';end if;
  if command.semantic_digest is distinct from public.static_weekly_digest_jsonb(command.semantic_body)
   or command.semantic_body is distinct from jsonb_build_object('absenceKind',null,'commandKind','cancel_absence',
    'employeeId',command.employee_id::text,'endDate',command.end_date::text,'startDate',command.start_date::text,
    'targetAbsenceId',command.target_absence_id::text) then
   raise exception using errcode='23514',message='original cancellation command identity is inconsistent';end if;
  select jsonb_build_object('absenceId',a.absence_id::text,'employeeId',a.employee_id::text,
   'startDate',a.start_date::text,'endDate',a.end_date::text,'acceptedOperationId',a.accepted_operation_id::text,
   'status','accepted') into original_target
  from public.static_weekly_staffing_absences a
  join public.static_weekly_staffing_commands acceptedcmd
   on acceptedcmd.operation_id=a.accepted_operation_id and acceptedcmd.operation_id=a.absence_id
    and acceptedcmd.command_kind='absence' and acceptedcmd.state='ACCEPTED'
    and acceptedcmd.employee_id=a.employee_id and acceptedcmd.start_date=a.start_date and acceptedcmd.end_date=a.end_date
    and acceptedcmd.absence_kind=a.absence_kind and acceptedcmd.target_absence_id is null
    and acceptedcmd.accepted_revision=a.accepted_revision
    and acceptedcmd.prepared_by_manager_id=a.accepted_by_manager_id
    and acceptedcmd.confirmed_by_manager_id=a.accepted_by_manager_id
    and acceptedcmd.semantic_body=jsonb_build_object('absenceKind',a.absence_kind,'commandKind','absence',
     'employeeId',a.employee_id::text,'endDate',a.end_date::text,'startDate',a.start_date::text,'targetAbsenceId',null)
    and acceptedcmd.semantic_digest=public.static_weekly_digest_jsonb(acceptedcmd.semantic_body)
    and acceptedcmd.accepted_receipt->>'event'='ACCEPTED'
    and acceptedcmd.accepted_receipt->>'operation_id'=acceptedcmd.operation_id::text
    and acceptedcmd.accepted_receipt->>'semantic_digest'=acceptedcmd.semantic_digest
    and acceptedcmd.accepted_receipt->>'authority_revision'=a.accepted_revision::text
  where a.absence_id=command.target_absence_id and a.employee_id=command.employee_id
   and command.start_date=greatest(a.start_date,public.sch_service_date(statement_timestamp()))
   and command.start_date<=a.end_date and command.end_date=a.end_date
   and not exists(select 1 from public.static_weekly_staffing_absence_cancellations c where c.absence_id=a.absence_id);
  if not found then raise exception using errcode='23514',message='original accepted cancellation target is unavailable or inconsistent';end if;
 end if;
 -- Only this command's immutable PREPARED candidates may supply these facts.
 -- PREPARING/terminal states retain the original null preview behavior.
 if command.state='PREPARED' then
  if (select count(*) from public.static_weekly_staffing_staged_candidates
   where operation_id=command.operation_id and candidate_kind='projection')>54 then
   raise exception using errcode='54000',message='prepared preview week bound exceeded';end if;
  for projection in
   select p.*,l.payload_json as lunch_payload
   from public.static_weekly_staffing_staged_candidates p
   left join public.static_weekly_staffing_staged_candidates l
    on l.operation_id=p.operation_id and l.candidate_kind='lunch' and l.service_date=p.service_date
   where p.operation_id=command.operation_id and p.candidate_kind='projection'
   order by p.service_date
  loop
   if projection.payload_digest is distinct from public.static_weekly_digest_jsonb(projection.payload_json) then
    raise exception using errcode='23514',message='prepared preview staged projection digest changed';end if;
   envelope:=projection.payload_json->'envelope';
   availability:=envelope#>'{authority,projectionAvailability}';
   safe_availability:=null;
   if jsonb_typeof(availability)='array' then
    if jsonb_array_length(availability)>1792 then
     raise exception using errcode='54000',message='prepared preview availability bound exceeded';end if;
    safe_availability:='[]'::jsonb;
    for a in select item from jsonb_array_elements(availability) item loop
     if jsonb_typeof(a) is distinct from 'object' then
      raise exception using errcode='23514',message='prepared preview availability row is not an object';end if;
     safe_row:='{}'::jsonb;
     foreach field in array array['serviceDate','slotId','status','incumbentSlotId','incumbentSlotLabel',
      'incumbentPersonId','incumbentName','ownerKind','capacityId','acceptedRouteAnchorLocationId',
      'acceptedRouteStartLocationId','routeAnchorLocationId'] loop
      value:=a->field;
      safe_row:=safe_row||jsonb_build_object(field,case when jsonb_typeof(value)='string'
       and length(a->>field)<=300 then value else null end);
     end loop;
     foreach field in array array['dayOfWeek','productiveCapacityMinutes','maxServiceEffortMinutes',
      'maxLoadPoints','maxDutyMinutes'] loop
      value:=a->field;
      safe_row:=safe_row||jsonb_build_object(field,case when jsonb_typeof(value)='number' then value else null end);
     end loop;
     foreach field in array array['shift','lunch'] loop
      value:=a->field;
      safe_row:=safe_row||jsonb_build_object(field,case when jsonb_typeof(value)='object'
       then jsonb_build_object('start',case when jsonb_typeof(value->'start')='string' and length(value->>'start')<=5 then value->'start' else null end,
        'end',case when jsonb_typeof(value->'end')='string' and length(value->>'end')<=5 then value->'end' else null end) else null end);
     end loop;
     foreach field in array array['blockedWindows','productiveWindows'] loop
      value:=a->field;windows:=null;
      if jsonb_typeof(value)='array' then
       if jsonb_array_length(value)>256 then raise exception using errcode='54000',message='prepared preview window bound exceeded';end if;
       windows:='[]'::jsonb;
       for w in select item from jsonb_array_elements(value) item loop
        if jsonb_typeof(w) is distinct from 'object' then raise exception using errcode='23514',message='prepared preview window is not an object';end if;
        windows:=windows||jsonb_build_array(jsonb_build_object(
         'start',case when jsonb_typeof(w->'start')='string' and length(w->>'start')<=5 then w->'start' else null end,
         'end',case when jsonb_typeof(w->'end')='string' and length(w->>'end')<=5 then w->'end' else null end));
       end loop;
      end if;
      safe_row:=safe_row||jsonb_build_object(field,windows);
     end loop;
     -- Hash arbitrary provenance instead of leaking leave/restriction notes.
     foreach field in array array['productiveCapacityProvenance','capacityProvenance','acceptedRouteProvenance'] loop
      safe_row:=safe_row||jsonb_build_object(field||'Digest',case when a ? field and a->field<>'null'::jsonb
       then public.static_weekly_digest_jsonb(a->field) else null end);
     end loop;
     safe_row:=safe_row||jsonb_build_object('acceptedRoute',case when jsonb_typeof(a->'acceptedRoute')='object'
      then jsonb_build_object('startLocationId',case when jsonb_typeof(a#>'{acceptedRoute,startLocationId}')='string'
       and length(a#>>'{acceptedRoute,startLocationId}')<=300 then a#>'{acceptedRoute,startLocationId}' else null end) else null end);
     safe_row:=safe_row||jsonb_build_object('acceptedRouteDigest',case when jsonb_typeof(a->'acceptedRoute')='object'
      then public.static_weekly_digest_jsonb(a->'acceptedRoute') else null end);
     safe_availability:=safe_availability||jsonb_build_array(safe_row);
    end loop;
   end if;
   -- Safe fields only: never return optimizer certificates, witnesses, raw
   -- compiler slots/exceptions/proximity matrices or preflight source data.
   safe_objective:=null;
   if jsonb_typeof(envelope->'objective')='object' then
    safe_objective:='{}'::jsonb;
    foreach field in array array['mode','policyVersion','integerServiceEffort','serviceEffortWireSemantics',
     'directedTravelDuty','flexibleCoverageTravelRole','acceptedRouteInsertions','weeklyEquityResource',
     'equityIntegerScale','exactEquityCommonDenominator'] loop
     value:=envelope->'objective'->field;
     if jsonb_typeof(value) in ('number','boolean') or (jsonb_typeof(value)='string'
      and length(envelope->'objective'->>field)<=2000) then safe_objective:=safe_objective||jsonb_build_object(field,value);end if;
    end loop;
    foreach field in array array['tiers','rankingOrder'] loop
     value:=envelope->'objective'->field;
     if jsonb_typeof(value)='array' then
      if jsonb_array_length(value)>4096 or exists(select 1 from jsonb_array_elements(value) x
       where jsonb_typeof(x)<>'string' or length(x#>>'{}')>300) then
       raise exception using errcode='54000',message='prepared preview objective text bound exceeded';end if;
      safe_objective:=safe_objective||jsonb_build_object(field,value);
     end if;
    end loop;
   end if;
   raw_metrics:=envelope->'metrics';safe_metrics:=null;
   if jsonb_typeof(raw_metrics)='object' then
    safe_metrics:='{}'::jsonb;map_value:='{}'::jsonb;
    foreach field in array array['workload','service','travel','waiting','protected','totalDuty'] loop
     value:=raw_metrics->'dutySemantics'->field;
     if jsonb_typeof(value)='string' and length(raw_metrics->'dutySemantics'->>field)<=2000 then
      map_value:=map_value||jsonb_build_object(field,value);end if;
    end loop;
    safe_metrics:=safe_metrics||jsonb_build_object('dutySemantics',case when jsonb_typeof(raw_metrics->'dutySemantics')='object' then map_value else null end);
    daily:=null;
    if jsonb_typeof(raw_metrics->'daily')='array' then
     if jsonb_array_length(raw_metrics->'daily')>7 then raise exception using errcode='54000',message='prepared preview metric day bound exceeded';end if;
     daily:='[]'::jsonb;
     for day_row in select item from jsonb_array_elements(raw_metrics->'daily') item loop
      safe_day:='{}'::jsonb;
      foreach field in array array['dayOfWeek','normalizedInequity','exactNormalizedInequity'] loop
       value:=day_row->field;
       safe_day:=safe_day||jsonb_build_object(field,case when jsonb_typeof(value)='number' then value else null end);
      end loop;
      loads:=null;
      if jsonb_typeof(day_row->'loads')='array' then
       if jsonb_array_length(day_row->'loads')>256 then raise exception using errcode='54000',message='prepared preview metric slot bound exceeded';end if;
       loads:='[]'::jsonb;
       for load_row in select item from jsonb_array_elements(day_row->'loads') item loop
        safe_load:=jsonb_build_object('slotId',case when jsonb_typeof(load_row->'slotId')='string'
         and length(load_row->>'slotId')<=300 then load_row->'slotId' else null end);
        foreach field in array array['effort','capacity','utilization','normalizedLoad','serviceDutyMinutes',
         'serviceEffortMinutes','normalizedServiceLoad','maxServiceEffortMinutes',
         'fixedServiceEffortMinutes','flexibleWorkloadPoints','fixedRouteTravelMinutes','flexibleCoverageTravelMinutes',
         'travelDutyMinutes','waitingMinutes','fixedWindowWaitingMinutes','transitWaitingMinutes',
         'protectedBreakUnavailableMinutes','routeSpanMinutes','routeNodeCount','fixedRouteDutyMinutes',
         'totalDutyMinutes','dutyCapacityMinutes','productiveCapacityMinutes','acceptedRouteTravelMinutes'] loop
         value:=load_row->field;
         if jsonb_typeof(value)='number' then safe_load:=safe_load||jsonb_build_object(field,value);end if;
        end loop;
        loads:=loads||jsonb_build_array(safe_load);
       end loop;
      end if;
      daily:=daily||jsonb_build_array(safe_day||jsonb_build_object('loads',loads));
     end loop;
    end if;
    safe_metrics:=safe_metrics||jsonb_build_object('daily',daily);
    weekly:=null;
    if jsonb_typeof(raw_metrics->'weekly')='object' then
     weekly:='{}'::jsonb;
     foreach field in array array['normalizedInequity','incrementalDirectedRouteCost','disruption'] loop
      value:=raw_metrics->'weekly'->field;
      if jsonb_typeof(value)='number' then weekly:=weekly||jsonb_build_object(field,value);end if;
     end loop;
     value:=raw_metrics#>'{weekly,resource}';
     if jsonb_typeof(value)='string' and length(raw_metrics#>>'{weekly,resource}')<=2000 then weekly:=weekly||jsonb_build_object('resource',value);end if;
     foreach field in array array['normalizedLoads','provenancedWorkloadUnits','productiveCapacityMinutes','uncoveredByPriority'] loop
      value:=raw_metrics->'weekly'->field;
      if jsonb_typeof(value)='object' then
       if (select count(*) from jsonb_object_keys(value))>256 then raise exception using errcode='54000',message='prepared preview weekly metric bound exceeded';end if;
       map_value:='{}'::jsonb;
       for pair in select * from jsonb_each(value) loop
        if length(pair.key)<=300 and jsonb_typeof(pair.value)='number' then map_value:=map_value||jsonb_build_object(pair.key,pair.value);end if;
       end loop;
       weekly:=weekly||jsonb_build_object(field,map_value);
      end if;
     end loop;
    end if;
    safe_metrics:=safe_metrics||jsonb_build_object('weekly',weekly);
   end if;
   prepared_week:=jsonb_build_object(
    'week_start',projection.service_date::text,
    'assignments',coalesce(projection.payload_json#>'{envelope,assignments}','[]'::jsonb),
    'lunch_responsibilities',coalesce(projection.lunch_payload->'responsibilities','[]'::jsonb),
    'lunch_loans',coalesce(projection.lunch_payload->'loans','[]'::jsonb),
    'publicationId',case when jsonb_typeof(projection.payload_json->'publicationId')='string'
     and length(projection.payload_json->>'publicationId')<=300 then projection.payload_json->'publicationId' else null end,
    'versionId',case when jsonb_typeof(envelope#>'{authority,compilerInput,version,id}')='string'
     and length(envelope#>>'{authority,compilerInput,version,id}')<=300 then envelope#>'{authority,compilerInput,version,id}' else null end,
    'database_projection_identity',case when jsonb_typeof(envelope->'database_projection_identity')='string'
     and envelope->>'database_projection_identity'~'^[a-f0-9]{64}$' then envelope->'database_projection_identity' else null end,
    'replayDigest',case when jsonb_typeof(envelope->'replay_digest')='string'
     and envelope->>'replay_digest'~'^[a-f0-9]{64}$' then envelope->'replay_digest' else null end,
    'compilerVersion',case when jsonb_typeof(envelope->'compiler_version')='string'
     and length(envelope->>'compiler_version')<=300 then envelope->'compiler_version' else null end,
    'objective',safe_objective,'metrics',safe_metrics,'projectionAvailability',safe_availability,
    'projectionAvailabilityDigest',case when jsonb_typeof(availability)='array' then public.static_weekly_digest_jsonb(availability) else null end,
    'projectionAvailabilityBasis','envelope.authority.projectionAvailability',
    'sourceDigest',case when envelope->>'compiler_version'='approved-manual-period-v1'
      and envelope#>>'{adapter,schema}'='custodial.approved-manual-period-database-adapter.v1'
      and envelope#>>'{authority,schema}'='custodial.approved-manual-period-projection-authority.v1'
     then case when jsonb_typeof(envelope#>'{authority,sourceDigest}')='string'
      and envelope#>>'{authority,sourceDigest}'~'^[a-f0-9]{64}$'
      and envelope#>>'{authority,sourceDigest}'=public.static_weekly_digest_jsonb(envelope#>'{authority,compilerInput}')
      then envelope#>'{authority,sourceDigest}' else null end
     else case when jsonb_typeof(envelope#>'{authority,inputDigest}')='string'
      and envelope#>>'{authority,inputDigest}'~'^[a-f0-9]{64}$' then envelope#>'{authority,inputDigest}' else null end end,
    'sourceDigestBasis',case when envelope->>'compiler_version'='approved-manual-period-v1'
      and envelope#>>'{adapter,schema}'='custodial.approved-manual-period-database-adapter.v1'
      and envelope#>>'{authority,schema}'='custodial.approved-manual-period-projection-authority.v1'
     then 'envelope.authority.sourceDigest' else 'envelope.authority.inputDigest' end,
    'geographyDigest',case when jsonb_typeof(envelope#>'{authority,compilerInput,proximity}')='array'
     then public.static_weekly_digest_jsonb(envelope#>'{authority,compilerInput,proximity}') else null end,
    'geographyDigestBasis','envelope.authority.compilerInput.proximity');
   if octet_length(prepared_week::text)>4194304 then raise exception using errcode='54000',message='prepared preview week byte bound exceeded';end if;
   preview_weeks:=preview_weeks||jsonb_build_array(prepared_week);
   if octet_length(preview_weeks::text)>16777216 then raise exception using errcode='54000',message='prepared preview total byte bound exceeded';end if;
  end loop;
 end if;
 return jsonb_build_object('operation_id',command.operation_id,'state',command.state,
  'original_cancellation_target',original_target,
  'semantic_body',command.semantic_body,'semantic_digest',command.semantic_digest,
  'expected_revision',command.expected_revision,'prepared_by_manager_id',command.prepared_by_manager_id,
  'preview_digest',command.preview_digest,'candidate_set_digest',command.candidate_set_digest,
  'input_digest',command.input_digest,'publication_vector',command.publication_vector,
  'candidate_row_count',command.candidate_row_count,'candidate_bytes',command.candidate_bytes,
  'candidate_summary',command.candidate_summary,'accepted_revision',command.accepted_revision,
  'accepted_receipt',command.accepted_receipt,'created_at',command.created_at,'prepared_at',command.prepared_at,
  'accepted_at',command.accepted_at,'current_service_date',public.sch_service_date(statement_timestamp())::text,
  'preview',case when command.state='PREPARED' then jsonb_build_object(
   'schema','memphis-zoo.staffing-command-preview.v1',
   'weeks',preview_weeks)
   else null end);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v10_staffing_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
 if tg_op='DELETE' then raise exception 'staffing commands are durable and cannot be deleted'; end if;
 if current_setting('app.static_weekly_staffing_write',true) is distinct from 'on' then
  raise exception 'staffing command transitions require the typed authority RPC';
 end if;
 if (to_jsonb(new)-array['state','preview_digest','input_digest','candidate_set_digest','candidate_row_count',
  'candidate_bytes','publication_vector','candidate_summary','accepted_revision','accepted_receipt',
  'prepared_at','accepted_at','confirmation_key','confirmed_by_manager_id','authority_command_id']) is distinct from
  (to_jsonb(old)-array['state','preview_digest','input_digest','candidate_set_digest','candidate_row_count',
  'candidate_bytes','publication_vector','candidate_summary','accepted_revision','accepted_receipt',
  'prepared_at','accepted_at','confirmation_key','confirmed_by_manager_id','authority_command_id']) then
  raise exception 'immutable staffing command identity changed'; end if;
 if not ((old.state='PREPARING' and new.state in ('PREPARED','CANCELLED','CANCELLED_BY_SUCCESSOR','REJECTED'))
  or (old.state='PREPARED' and new.state in ('ACCEPTED','CANCELLED','CANCELLED_BY_SUCCESSOR','REJECTED')))
  then raise exception 'invalid staffing command state transition'; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v10_stage_staffing_command(p_operation_id uuid, p_candidates jsonb, p_preview_digest text, p_input_digest text, p_publication_vector jsonb, p_manager_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_pending record;v_pending_lunch jsonb; actor jsonb;command public.static_weekly_staffing_commands%rowtype;
 v_candidate_set_digest text;v_candidate_rows integer;v_candidate_bytes bigint;v_week_count integer;
 v_projection_weeks integer;v_lunch_weeks integer;v_summary jsonb;v_receipt jsonb;v_current_revision bigint;
begin
 perform public.static_weekly_v3_assert_control_plane();
 actor:=public.static_weekly_v3_manager_actor(p_manager_id);
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select * into command from public.static_weekly_staffing_commands where operation_id=p_operation_id for update;
 if not found then raise exception using errcode='P0002',message='staffing command is unavailable';end if;
 if command.prepared_by_manager_id is distinct from p_manager_id then
  raise exception using errcode='42501',message='only the authenticated original preparer may stage this command';end if;
 if p_preview_digest is null or p_preview_digest!~'^[0-9a-f]{64}$'
  or p_input_digest is null or p_input_digest!~'^[0-9a-f]{64}$'
  or jsonb_typeof(p_publication_vector) is distinct from 'object'
  or jsonb_typeof(p_candidates) is distinct from 'array' then
  raise exception using errcode='22023',message='invalid staffing candidate envelope';end if;
 v_candidate_set_digest:=public.static_weekly_digest_jsonb(p_candidates);
 if command.state='PREPARED' then
  if command.candidate_set_digest is distinct from v_candidate_set_digest
   or command.preview_digest is distinct from p_preview_digest
   or command.input_digest is distinct from p_input_digest
   or command.publication_vector is distinct from p_publication_vector then
   raise exception using errcode='23505',message='prepared staffing operation was replayed with different candidates';end if;
  return jsonb_build_object('operation_id',command.operation_id,'state',command.state,
   'candidate_set_digest',command.candidate_set_digest,'candidate_row_count',command.candidate_row_count,
   'candidate_bytes',command.candidate_bytes,'candidate_summary',command.candidate_summary,'replayed',true);
 end if;
 if command.state<>'PREPARING' then raise exception using errcode='55000',message='staffing command cannot be staged from its current state';end if;
 select control.current_revision into v_current_revision from public.static_weekly_schedule_control control where control.singleton for share;
 if v_current_revision is distinct from command.expected_revision then
  raise exception using errcode='40001',message='staffing command expected revision became stale during preparation';end if;
 if command.command_kind='absence' and not exists(select 1 from public.employees where id=command.employee_id and active=true) then
  raise exception using errcode='23514',message='staffing command employee is no longer active';end if;
 if command.command_kind='cancel_absence' and command.start_date<public.sch_service_date(statement_timestamp()) then
  raise exception using errcode='23514',message='staffing cancellation cannot rewrite an elapsed service date during preparation';end if;
 if command.command_kind='cancel_absence' and not exists(
  select 1 from public.static_weekly_staffing_absences a
  join public.static_weekly_staffing_commands acceptedcmd
   on acceptedcmd.operation_id=a.accepted_operation_id and acceptedcmd.operation_id=a.absence_id
    and acceptedcmd.command_kind='absence' and acceptedcmd.state='ACCEPTED'
    and acceptedcmd.employee_id=a.employee_id and acceptedcmd.start_date=a.start_date and acceptedcmd.end_date=a.end_date
    and acceptedcmd.absence_kind=a.absence_kind and acceptedcmd.target_absence_id is null
    and acceptedcmd.accepted_revision=a.accepted_revision
    and acceptedcmd.prepared_by_manager_id=a.accepted_by_manager_id
    and acceptedcmd.confirmed_by_manager_id=a.accepted_by_manager_id
    and acceptedcmd.semantic_body=jsonb_build_object('absenceKind',a.absence_kind,'commandKind','absence',
     'employeeId',a.employee_id::text,'endDate',a.end_date::text,'startDate',a.start_date::text,'targetAbsenceId',null)
    and acceptedcmd.semantic_digest=public.static_weekly_digest_jsonb(acceptedcmd.semantic_body)
    and acceptedcmd.accepted_receipt->>'event'='ACCEPTED'
    and acceptedcmd.accepted_receipt->>'operation_id'=acceptedcmd.operation_id::text
    and acceptedcmd.accepted_receipt->>'semantic_digest'=acceptedcmd.semantic_digest
    and acceptedcmd.accepted_receipt->>'authority_revision'=a.accepted_revision::text where a.absence_id=command.target_absence_id
   and a.employee_id=command.employee_id and command.start_date=greatest(a.start_date,public.sch_service_date(statement_timestamp())) and command.start_date<=a.end_date
   and command.end_date=a.end_date
   and not exists(select 1 from public.static_weekly_staffing_absence_cancellations c where c.absence_id=a.absence_id)
 ) then raise exception using errcode='23514',message='staffing cancellation remaining window changed during preparation';end if;
 if jsonb_array_length(p_candidates)>100000 then raise exception using errcode='54000',message='staffing candidate row limit exceeded';end if;
 if exists(select 1 from jsonb_array_elements(p_candidates) item where jsonb_typeof(item)<>'object'
   or (select array_agg(key order by key) from jsonb_object_keys(item) key)
      is distinct from array['candidateKey','candidateKind','payload','serviceDate']::text[]
   or jsonb_typeof(item->'candidateKind') is distinct from 'string'
   or item->>'candidateKind' not in ('projection','lunch','schedule_refresh')
   or jsonb_typeof(item->'candidateKey') is distinct from 'string'
   or length(btrim(item->>'candidateKey')) not between 1 and 300
   or item->>'candidateKey' is distinct from btrim(item->>'candidateKey')
   or jsonb_typeof(item->'serviceDate') is distinct from 'string'
   or item->>'serviceDate'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
   or jsonb_typeof(item->'payload') is distinct from 'object'
   or case when item->>'candidateKind' in ('projection','lunch')
      then not exists(select 1 from generate_series(command.start_date,command.end_date,'1 day') d where public.static_weekly_projection_window_start(d::date)=(item->>'serviceDate')::date)
      else (item->>'serviceDate')::date not between command.start_date and command.end_date end) then
  raise exception using errcode='22023',message='invalid staffing candidate row';end if;
 if p_candidates is distinct from (select coalesce(jsonb_agg(item order by (item->>'serviceDate') collate "C",
   (item->>'candidateKind') collate "C",(item->>'candidateKey') collate "C"),'[]'::jsonb) from jsonb_array_elements(p_candidates) item) then
  raise exception using errcode='22023',message='staffing candidates are not in deterministic order';end if;
 if exists(select 1 from jsonb_array_elements(p_candidates) item
  group by item->>'candidateKind',item->>'candidateKey' having count(*)<>1) then
  raise exception using errcode='23505',message='duplicate staffing candidate identity';end if;
 select count(distinct public.static_weekly_projection_window_start(d::date)) into v_week_count from generate_series(command.start_date,command.end_date,'1 day') d;
 select count(distinct (item->>'serviceDate')::date) filter(where item->>'candidateKind'='projection'),
  count(distinct (item->>'serviceDate')::date) filter(where item->>'candidateKind'='lunch') into v_projection_weeks,v_lunch_weeks from jsonb_array_elements(p_candidates) item;
 if v_projection_weeks is distinct from v_week_count or v_lunch_weeks is distinct from v_week_count
  or exists(select 1 from (select distinct public.static_weekly_projection_window_start(d::date) frame from generate_series(command.start_date,command.end_date,'1 day') d) frames
   where (select count(*) from jsonb_array_elements(p_candidates) item where item->>'candidateKind'='projection' and (item->>'serviceDate')::date=frame)<>1
    or (select count(*) from jsonb_array_elements(p_candidates) item where item->>'candidateKind'='lunch' and (item->>'serviceDate')::date=frame)<>1)
 then raise exception using errcode='23514',message='staffing exact source-aligned period companions are incomplete';end if;
 select count(*),coalesce(sum(octet_length(item::text)),0) into v_candidate_rows,v_candidate_bytes
  from jsonb_array_elements(p_candidates) item;
 if v_candidate_bytes>16777216 then raise exception using errcode='54000',message='staffing candidate byte limit exceeded';end if;
 v_summary:=jsonb_build_object('weeks',v_week_count,
  'projections',(select count(*) from jsonb_array_elements(p_candidates) item where item->>'candidateKind'='projection'),
  'lunches',(select count(*) from jsonb_array_elements(p_candidates) item where item->>'candidateKind'='lunch'),
  'scheduleRefreshes',(select count(*) from jsonb_array_elements(p_candidates) item where item->>'candidateKind'='schedule_refresh'));

 perform public.static_weekly_coverall_stage_companion(p_operation_id,p_manager_id,p_candidates,p_preview_digest);
 -- BEGIN PRIVATE ORIGINAL-PENDING APPROVED STAGE
 FOR v_pending IN SELECT item->'payload' payload,item->>'serviceDate' AS service_date_text FROM jsonb_array_elements(p_candidates) item
  WHERE item->>'candidateKind'='projection' AND item#>>'{payload,envelope,semantic_snapshot,schema}' IN('custodial.approved-static-pending-staffing-projection-snapshot.v1','custodial.approved-manual-pending-staffing-snapshot.v1') LOOP
  IF v_pending.payload->>'serviceDate' IS DISTINCT FROM v_pending.service_date_text
   OR p_publication_vector->'expectedRevision' IS DISTINCT FROM to_jsonb(command.expected_revision)
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_publication_vector->'weeks') w
    WHERE (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(w) k)=ARRAY['authorityRevision','publicationId','versionId','weekStart']::text[]
     AND w->>'weekStart'=v_pending.service_date_text AND w->'authorityRevision'=to_jsonb(command.expected_revision)
     AND w->'publicationId'=v_pending.payload->'publicationId'
     AND w->'versionId'=v_pending.payload#>'{envelope,semantic_snapshot,originalSource,version_id}')
  THEN RAISE EXCEPTION 'Pending original publication vector differs';END IF;
  PERFORM public.static_weekly_pending_assert_payload(p_operation_id,p_manager_id,v_pending.payload);
  SELECT item->'payload' INTO STRICT v_pending_lunch FROM jsonb_array_elements(p_candidates) item
   WHERE item->>'candidateKind'='lunch' AND item->>'serviceDate'=v_pending.service_date_text;
  PERFORM public.static_weekly_pending_assert_lunch(p_operation_id,p_manager_id,(v_pending.payload->>'publicationId')::uuid,
   v_pending.service_date_text::date,v_pending.payload->'envelope',v_pending_lunch);
 END LOOP;
 -- END PRIVATE ORIGINAL-PENDING APPROVED STAGE
 insert into public.static_weekly_staffing_staged_candidates(operation_id,candidate_kind,candidate_key,service_date,
  payload_json,payload_digest,canonical_bytes)
 select command.operation_id,item->>'candidateKind',item->>'candidateKey',(item->>'serviceDate')::date,item->'payload',
  public.static_weekly_digest_jsonb(item->'payload'),octet_length(item::text)
 from jsonb_array_elements(p_candidates) item;
 perform set_config('app.static_weekly_staffing_write','on',true);
 update public.static_weekly_staffing_commands set state='PREPARED',preview_digest=p_preview_digest,
  input_digest=p_input_digest,candidate_set_digest=v_candidate_set_digest,candidate_row_count=v_candidate_rows,
  candidate_bytes=v_candidate_bytes,publication_vector=p_publication_vector,candidate_summary=v_summary,
  prepared_at=statement_timestamp() where operation_id=command.operation_id;
 v_receipt:=jsonb_build_object('operation_id',command.operation_id,'event','PREPARED','manager_id',p_manager_id,
  'semantic_digest',command.semantic_digest,'candidate_set_digest',v_candidate_set_digest,
  'candidate_row_count',v_candidate_rows,'candidate_bytes',v_candidate_bytes,'recorded_at',statement_timestamp());
 insert into public.static_weekly_staffing_command_receipts(operation_id,event_kind,actor_manager_id,
  semantic_digest,receipt_json,receipt_digest) values(command.operation_id,'PREPARED',p_manager_id,
  command.semantic_digest,v_receipt,public.static_weekly_digest_jsonb(v_receipt));
 return jsonb_build_object('operation_id',command.operation_id,'state','PREPARED',
  'candidate_set_digest',v_candidate_set_digest,'candidate_row_count',v_candidate_rows,
  'candidate_bytes',v_candidate_bytes,'candidate_summary',v_summary,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v11_accept_staffing_command(p_operation_id uuid, p_preview_digest text, p_confirmation_key uuid, p_manager_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_pending_check jsonb; actor jsonb;command public.static_weekly_staffing_commands%rowtype;target_absence public.static_weekly_staffing_absences%rowtype;
 v_candidates jsonb;v_count integer;v_bytes bigint;v_current_revision bigint;v_revision bigint;
 v_content_digest text;v_projection_candidate record;v_lunch jsonb;v_payload jsonb;v_projection_response jsonb;
 v_projection uuid;v_existing public.weekly_schedule_compiled_projections%rowtype;v_existing_lunch public.weekly_schedule_lunch_documents%rowtype;
 v_signed_envelope jsonb;v_request jsonb;v_request_digest text;v_projection_content_digest text;v_projection_receipt jsonb;
 v_projection_map jsonb:='{}'::jsonb;v_refresh record;v_mapping jsonb;v_intent_count integer:=0;
 v_missing_device jsonb:='[]'::jsonb;v_prior_refresh jsonb:='[]'::jsonb;v_receipt jsonb;v_receipt_digest text;v_reused boolean;v_command_id uuid;
begin
 perform public.static_weekly_v3_assert_control_plane();actor:=public.static_weekly_v3_manager_actor(p_manager_id);
 perform public.custodial_begin_application_mutation();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select * into command from public.static_weekly_staffing_commands where operation_id=p_operation_id for update;
 if not found then raise exception using errcode='P0002',message='staffing command is unavailable';end if;
 if command.state='ACCEPTED' then
  if command.prepared_by_manager_id is distinct from p_manager_id
   or command.confirmation_key is distinct from p_confirmation_key
   or command.preview_digest is distinct from p_preview_digest then
   raise exception using errcode='23505',message='accepted staffing command was replayed with different confirmation identity';end if;
  return command.accepted_receipt||jsonb_build_object('replayed',true);
 end if;
 if command.state<>'PREPARED' then raise exception using errcode='55000',message='staffing command is not prepared for acceptance';end if;
 if command.prepared_by_manager_id is distinct from p_manager_id then
  raise exception using errcode='42501',message='only the authenticated original preparer may confirm this command';end if;
 if p_confirmation_key is null or p_preview_digest is null or p_preview_digest!~'^[0-9a-f]{64}$'
  or command.preview_digest is distinct from p_preview_digest then
  raise exception using errcode='22023',message='exact staffing preview and confirmation key are required';end if;
 if command.command_kind='cancel_absence' and command.start_date<public.sch_service_date(statement_timestamp()) then
  perform set_config('app.static_weekly_staffing_write','on',true);
  update public.static_weekly_staffing_commands set state='REJECTED' where operation_id=command.operation_id;
  v_receipt:=jsonb_build_object('operation_id',command.operation_id,'event','REJECTED',
   'reason','ELAPSED_CANCELLATION','manager_id',p_manager_id,'semantic_digest',command.semantic_digest,
   'preview_digest',command.preview_digest,'recorded_at',statement_timestamp());
  insert into public.static_weekly_staffing_command_receipts(operation_id,event_kind,actor_manager_id,
   semantic_digest,receipt_json,receipt_digest) values(command.operation_id,'REJECTED',p_manager_id,
   command.semantic_digest,v_receipt,public.static_weekly_digest_jsonb(v_receipt));
  return jsonb_build_object('operation_id',command.operation_id,'state','REJECTED',
   'reason','ELAPSED_CANCELLATION','replayed',false);
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('candidateKey',candidate_key,'candidateKind',candidate_kind,
  'payload',payload_json,'serviceDate',service_date::text)
  order by service_date,candidate_kind collate "C",candidate_key collate "C"),'[]'::jsonb),
  count(*),coalesce(sum(canonical_bytes),0) into v_candidates,v_count,v_bytes
 from public.static_weekly_staffing_staged_candidates where operation_id=command.operation_id;
 if public.static_weekly_digest_jsonb(v_candidates) is distinct from command.candidate_set_digest
  or v_count is distinct from command.candidate_row_count or v_bytes is distinct from command.candidate_bytes
  or v_count>100000 or v_bytes>16777216 then
  raise exception using errcode='23514',message='prepared staffing candidate set no longer matches its complete digest';end if;
 select current_revision into v_current_revision from public.static_weekly_schedule_control where singleton for update;
 if v_current_revision is distinct from command.expected_revision then
  raise exception using errcode='40001',message='staffing confirmation expected revision is stale';end if;
 if command.command_kind='absence' and not exists(select 1 from public.employees where id=command.employee_id and active=true) then
  raise exception using errcode='23514',message='staffing command employee is no longer active';end if;
 if command.command_kind='cancel_absence' then
  select * into target_absence from public.static_weekly_staffing_absences a
  join public.static_weekly_staffing_commands acceptedcmd
   on acceptedcmd.operation_id=a.accepted_operation_id and acceptedcmd.operation_id=a.absence_id
    and acceptedcmd.command_kind='absence' and acceptedcmd.state='ACCEPTED'
    and acceptedcmd.employee_id=a.employee_id and acceptedcmd.start_date=a.start_date and acceptedcmd.end_date=a.end_date
    and acceptedcmd.absence_kind=a.absence_kind and acceptedcmd.target_absence_id is null
    and acceptedcmd.accepted_revision=a.accepted_revision
    and acceptedcmd.prepared_by_manager_id=a.accepted_by_manager_id
    and acceptedcmd.confirmed_by_manager_id=a.accepted_by_manager_id
    and acceptedcmd.semantic_body=jsonb_build_object('absenceKind',a.absence_kind,'commandKind','absence',
     'employeeId',a.employee_id::text,'endDate',a.end_date::text,'startDate',a.start_date::text,'targetAbsenceId',null)
    and acceptedcmd.semantic_digest=public.static_weekly_digest_jsonb(acceptedcmd.semantic_body)
    and acceptedcmd.accepted_receipt->>'event'='ACCEPTED'
    and acceptedcmd.accepted_receipt->>'operation_id'=acceptedcmd.operation_id::text
    and acceptedcmd.accepted_receipt->>'semantic_digest'=acceptedcmd.semantic_digest
    and acceptedcmd.accepted_receipt->>'authority_revision'=a.accepted_revision::text
   where a.absence_id=command.target_absence_id and a.employee_id=command.employee_id
    and command.start_date=greatest(a.start_date,public.sch_service_date(statement_timestamp())) and command.start_date<=a.end_date and command.end_date=a.end_date
    and not exists(select 1 from public.static_weekly_staffing_absence_cancellations c where c.absence_id=a.absence_id)
   for share;
  if not found then raise exception using errcode='23514',message='staffing cancellation must target the exact uncancelled remaining absence window';end if;
 end if;
 if jsonb_typeof(command.publication_vector) is distinct from 'object'
  or (select array_agg(key order by key) from jsonb_object_keys(command.publication_vector) key)
    is distinct from array['expectedRevision','weeks']::text[]
  or (command.publication_vector->>'expectedRevision')::bigint<>command.expected_revision
  or jsonb_typeof(command.publication_vector->'weeks') is distinct from 'array' then
  raise exception using errcode='23514',message='prepared staffing publication vector is invalid';end if;
 if exists(select 1 from jsonb_array_elements(command.publication_vector->'weeks') week
  where jsonb_typeof(week)<>'object'
   or (select array_agg(key order by key) from jsonb_object_keys(week) key)
      is distinct from array['authorityRevision','publicationId','versionId','weekStart']::text[]
   or (week->>'authorityRevision')::bigint<>command.expected_revision
   or not exists(select 1 from public.weekly_schedule_publications p
    where p.publication_id=(week->>'publicationId')::uuid and p.version_id=(week->>'versionId')::uuid
     and public.static_weekly_effective_version((week->>'weekStart')::date)=p.version_id)) then
  raise exception using errcode='23514',message='prepared staffing publication vector became stale';end if;
 if (select count(*) from jsonb_array_elements(command.publication_vector->'weeks'))<>
    (select count(*) from public.static_weekly_staffing_staged_candidates
      where operation_id=command.operation_id and candidate_kind='projection') then
  raise exception using errcode='23514',message='prepared staffing projection vector is incomplete';end if;

 v_prior_refresh:=public.static_weekly_v11_read_current_refresh_targets(
  command.start_date,command.end_date,p_manager_id);

 v_content_digest:=public.static_weekly_digest_jsonb(jsonb_build_object('operation_id',command.operation_id,
  'semantic_digest',command.semantic_digest,'preview_digest',command.preview_digest,
  'input_digest',command.input_digest,'candidate_set_digest',command.candidate_set_digest,
  'publication_vector',command.publication_vector));
 v_revision:=public.static_weekly_advance_authority(command.expected_revision,'apply_staffing_command',
  p_manager_id,actor->>'manager_name',command.operation_id,v_content_digest);
 if command.command_kind='absence' then
  insert into public.static_weekly_staffing_absences(absence_id,employee_id,absence_kind,start_date,end_date,
   accepted_operation_id,accepted_revision,accepted_by_manager_id)
  values(command.operation_id,command.employee_id,command.absence_kind,command.start_date,command.end_date,
   command.operation_id,v_revision,p_manager_id);
 else
  insert into public.static_weekly_staffing_absence_cancellations(absence_id,accepted_operation_id,
   remaining_start_date,remaining_end_date,accepted_revision,accepted_by_manager_id)
  values(command.target_absence_id,command.operation_id,command.start_date,command.end_date,v_revision,p_manager_id);
 end if;
 perform set_config('app.static_weekly_staffing_batch_operation',command.operation_id::text,true);
 perform public.static_weekly_coverall_accept_companion(command.operation_id,p_manager_id,v_revision);

 for v_projection_candidate in select service_date,payload_json from public.static_weekly_staffing_staged_candidates
  where operation_id=command.operation_id and candidate_kind='projection' order by service_date,candidate_key loop
  v_payload:=v_projection_candidate.payload_json;
  if (select array_agg(key order by key) from jsonb_object_keys(v_payload) key) is distinct from
   array['actorManagerId','actorManagerName','compilerVersion','envelope','exceptionSetDigest','expectedRevision',
    'idempotencyKey','metrics','objective','publicationId','replayDigest','serviceDate']::text[]
   or (v_payload->>'serviceDate')::date is distinct from v_projection_candidate.service_date
   or (v_payload->>'expectedRevision')::bigint is distinct from command.expected_revision
   or v_payload->>'actorManagerId' is distinct from p_manager_id::text
   or v_payload->>'idempotencyKey' is distinct from 'staffing:'||command.operation_id::text||':'||v_projection_candidate.service_date::text
   or not exists(select 1 from jsonb_array_elements(command.publication_vector->'weeks') week
    where week->>'weekStart'=v_projection_candidate.service_date::text
     and week->>'publicationId'=v_payload->>'publicationId'
     and week->>'versionId'=v_payload#>>'{envelope,authority,compilerInput,version,id}') then
   raise exception using errcode='23514',message='staged staffing projection identity is invalid';end if;
  if v_payload->>'exceptionSetDigest' is distinct from public.static_weekly_digest_jsonb(
    public.static_weekly_accepted_exception_set((v_payload->>'publicationId')::uuid,v_projection_candidate.service_date))
   or v_payload->>'compilerVersion' is distinct from v_payload#>>'{envelope,compiler_version}'
   or v_payload->'objective' is distinct from v_payload#>'{envelope,objective}'
   or v_payload->'metrics' is distinct from v_payload#>'{envelope,metrics}'
   or v_payload->>'replayDigest' is distinct from v_payload#>>'{envelope,replay_digest}' then
   raise exception using errcode='23514',message='staged staffing projection compiler identity no longer matches accepted exception authority',
    detail=jsonb_build_object('staged_exception_digest',v_payload->>'exceptionSetDigest',
     'database_exception_digest',public.static_weekly_digest_jsonb(public.static_weekly_accepted_exception_set(
      (v_payload->>'publicationId')::uuid,v_projection_candidate.service_date)),
     'staged_exceptions',v_payload#>'{envelope,applied_exceptions}',
     'database_exceptions',public.static_weekly_accepted_exception_set(
      (v_payload->>'publicationId')::uuid,v_projection_candidate.service_date))::text;end if;

  -- BEGIN PRIVATE ORIGINAL-PENDING APPROVED ACCEPT
  IF v_payload#>>'{envelope,semantic_snapshot,schema}' IN('custodial.approved-static-pending-staffing-projection-snapshot.v1','custodial.approved-manual-pending-staffing-snapshot.v1') THEN
   v_pending_check:=public.static_weekly_pending_assert_payload(command.operation_id,p_manager_id,v_payload);
   IF (v_pending_check->>'afterFact')::boolean IS NOT TRUE THEN RAISE EXCEPTION 'Pending original fact not accepted in this transaction';END IF;
   v_projection_response:=public.static_weekly_pending_projection_sink((v_payload->>'publicationId')::uuid,
    v_projection_candidate.service_date,v_payload->>'exceptionSetDigest',v_payload->>'compilerVersion',v_payload->'objective',
    v_payload->'metrics',v_payload->>'replayDigest',v_payload->'envelope',command.expected_revision,p_manager_id,
    actor->>'manager_name',v_payload->>'idempotencyKey');
   v_projection:=(v_projection_response#>>'{data,projection_id}')::uuid;
  ELSE
  v_signed_envelope:=jsonb_set(v_payload->'envelope','{attestation}',
   public.static_weekly_v3_issue_attestation('dated_projection',
    public.static_weekly_projection_attestation_payload(v_payload->'envelope')),true);
  select * into v_existing from public.weekly_schedule_compiled_projections p
   where p.publication_id=(v_payload->>'publicationId')::uuid
    and p.week_start=v_projection_candidate.service_date
    and p.exception_set_digest=public.static_weekly_digest_jsonb(public.static_weekly_accepted_exception_set(
     (v_payload->>'publicationId')::uuid,v_projection_candidate.service_date))
    and p.compiler_version=v_payload->>'compilerVersion'
    and p.authority_digest=v_signed_envelope->>'authority_digest'
   order by p.compiled_at desc,p.projection_id desc limit 1;
  v_reused:=found;
  if v_reused then
   if (v_existing.projection_envelope-array['attestation','receipt','database_projection_identity']) is distinct from
      (v_signed_envelope-array['attestation','receipt','database_projection_identity']) then
    raise exception using errcode='23514',message='historical projection identity conflicts with the exact staged candidate';end if;
   v_projection:=v_existing.projection_id;
   v_command_id:=gen_random_uuid();
   v_request:=jsonb_build_object('operation','materialize_projection','publication_id',(v_payload->>'publicationId')::uuid,
    'service_date',v_projection_candidate.service_date,'exception_set_digest',v_existing.exception_set_digest,
    'compiler_version',v_existing.compiler_version,'objective',v_existing.objective_json,'metrics',v_existing.metrics_json,
    'replay_digest',v_existing.replay_digest,'projection_envelope',v_existing.projection_envelope,
    'expected_revision',command.expected_revision,'actor_manager_id',p_manager_id,'actor_manager_name',actor->>'manager_name');
   v_request_digest:=public.static_weekly_digest_jsonb(v_request);
   v_projection_content_digest:=public.static_weekly_digest_jsonb(jsonb_build_object(
    'publication_id',v_existing.publication_id,'week_start',v_existing.week_start,
    'exception_set_digest',v_existing.exception_set_digest,'compiler_version',v_existing.compiler_version,
    'objective',v_existing.objective_json,'metrics',v_existing.metrics_json,'replay_digest',v_existing.replay_digest,
    'projection_envelope_identity',v_existing.projection_envelope->>'database_projection_identity',
    'attestation',v_existing.projection_envelope->'attestation'));
   v_projection_receipt:=public.static_weekly_response_json('materialize_projection',v_revision,
    v_projection_content_digest,v_request_digest,jsonb_build_object('projection_id',v_projection,
     'publication_id',v_existing.publication_id,'week_start',v_existing.week_start,
     'week_end',v_existing.week_end,'replay_digest',v_existing.replay_digest));
   insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,
    command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest)
   values(v_command_id,p_manager_id,actor->>'manager_name','materialize_projection',v_payload->>'idempotencyKey',
    command.expected_revision,v_request_digest,v_request,v_projection_receipt,v_projection_receipt->>'output_digest',v_projection_content_digest);
  else
   v_projection_response:=public.static_weekly_v3_materialize_projection(
    (v_payload->>'publicationId')::uuid,v_projection_candidate.service_date,v_payload->>'exceptionSetDigest',
    v_payload->>'compilerVersion',v_payload->'objective',v_payload->'metrics',v_payload->>'replayDigest',
    v_payload->'envelope',command.expected_revision,p_manager_id,v_payload->>'idempotencyKey');
   v_projection:=(v_projection_response#>>'{data,projection_id}')::uuid;
  end if;

  END IF;
  -- END PRIVATE ORIGINAL-PENDING APPROVED ACCEPT
  select payload_json into strict v_lunch from public.static_weekly_staffing_staged_candidates
   where operation_id=command.operation_id and candidate_kind='lunch'
    and service_date=v_projection_candidate.service_date;

  IF v_payload#>>'{envelope,semantic_snapshot,schema}' IN('custodial.approved-static-pending-staffing-projection-snapshot.v1','custodial.approved-manual-pending-staffing-snapshot.v1') THEN
   PERFORM public.static_weekly_pending_assert_lunch(command.operation_id,p_manager_id,(v_payload->>'publicationId')::uuid,
    v_projection_candidate.service_date,v_payload->'envelope',v_lunch);
   IF NOT EXISTS(SELECT 1 FROM public.weekly_schedule_compiled_projections WHERE projection_id=v_projection
    AND projection_envelope=v_payload->'envelope' AND compiled_by_manager_id=p_manager_id) THEN RAISE EXCEPTION 'Pending exact persisted original projection differs';END IF;
  END IF;
  perform public.static_weekly_v8_materialize_lunch_document(v_projection,v_lunch,p_manager_id);
  select * into strict v_existing_lunch from public.weekly_schedule_lunch_documents where projection_id=v_projection;
  v_projection_map:=v_projection_map||jsonb_build_object(v_projection_candidate.service_date::text,
   jsonb_build_object('projection_id',v_projection,'publication_id',(v_payload->>'publicationId')::uuid,
    'projection_identity',v_payload#>>'{envelope,database_projection_identity}',
    'lunch_document_identity',v_existing_lunch.document_identity,'reused',v_reused));
 end loop;

 if exists(
 with projection as (select service_date week_start,payload_json from public.static_weekly_staffing_staged_candidates
    where operation_id=command.operation_id and candidate_kind='projection'),
  lunch as (select payload_json from public.static_weekly_staffing_staged_candidates
    where operation_id=command.operation_id and candidate_kind='lunch'),
  expected as (
   select distinct assignment->>'service_date' service_date,assignment->>'owner_person_id' employee_id
   from projection cross join lateral jsonb_array_elements(payload_json#>'{envelope,assignments}') assignment
   where lower(assignment->>'status')='assigned' and assignment->>'owner_person_id' is not null
    and assignment->>'service_date' between command.start_date::text and command.end_date::text
   union select responsibility->>'service_date',responsibility->>'normal_owner_person_id'
    from lunch cross join lateral jsonb_array_elements(coalesce(payload_json->'responsibilities','[]'::jsonb)) responsibility
    where responsibility->>'service_date' between command.start_date::text and command.end_date::text
     and responsibility->>'normal_owner_person_id' is not null
   union select responsibility->>'service_date',responsibility->>'coverer_person_id'
    from lunch cross join lateral jsonb_array_elements(coalesce(payload_json->'responsibilities','[]'::jsonb)) responsibility
    where responsibility->>'service_date' between command.start_date::text and command.end_date::text
     and responsibility->>'coverer_person_id' is not null
   union select item->>'serviceDate',item->>'employeeId' from jsonb_array_elements(v_prior_refresh) item
   union select (day::date)::text,command.employee_id::text from generate_series(command.start_date,command.end_date,interval '1 day') day
    where command.command_kind='absence'
  ),actual as (select service_date::text,payload_json->>'employeeId' employee_id
   from public.static_weekly_staffing_staged_candidates where operation_id=command.operation_id and candidate_kind='schedule_refresh')
  (select * from expected except select * from actual) union all (select * from actual except select * from expected)
 ) then raise exception using errcode='23514',message='affected employee schedule refresh set is incomplete or excessive';end if;

 for v_refresh in select service_date,payload_json from public.static_weekly_staffing_staged_candidates
  where operation_id=command.operation_id and candidate_kind='schedule_refresh' order by service_date,candidate_key loop
  v_mapping:=v_projection_map->(v_refresh.payload_json->>'weekStart');
  if (select array_agg(key order by key) from jsonb_object_keys(v_refresh.payload_json) key) is distinct from
   array['employeeId','lunchDocumentIdentity','projectionIdentity','publicationId','weekStart']::text[]
   or v_mapping is null or v_refresh.payload_json->>'publicationId' is distinct from v_mapping->>'publication_id'
   or v_refresh.payload_json->>'projectionIdentity' is distinct from v_mapping->>'projection_identity'
   or v_refresh.payload_json->>'lunchDocumentIdentity' is distinct from v_mapping->>'lunch_document_identity'
   or v_refresh.service_date not between command.start_date and command.end_date then
   raise exception using errcode='23514',message='schedule refresh is not bound to the exact accepted projection and lunch';end if;
  insert into public.static_weekly_schedule_application_intents(operation_id,service_date,employee_id,
   device_id,credential_id,assignment_epoch,authority_revision,publication_id,projection_id,lunch_document_identity)
  select command.operation_id,v_refresh.service_date,(v_refresh.payload_json->>'employeeId')::uuid,
   d.id,c.credential_id,d.assignment_epoch,v_revision,(v_mapping->>'publication_id')::uuid,
   (v_mapping->>'projection_id')::uuid,v_mapping->>'lunch_document_identity'
  from public.devices d join public.device_auth_credentials c on c.device_id=d.id
   and c.confirmed_at is not null and c.revoked_at is null and c.expires_at>statement_timestamp()
  where d.active=true and d.assigned_employee_id=(v_refresh.payload_json->>'employeeId')::uuid;
  get diagnostics v_count=row_count;v_intent_count:=v_intent_count+v_count;
  if v_count=0 then v_missing_device:=v_missing_device||jsonb_build_array(jsonb_build_object(
   'service_date',v_refresh.service_date,'employee_id',v_refresh.payload_json->>'employeeId','status','NO_CURRENT_DEVICE'));end if;
 end loop;

 v_receipt:=jsonb_build_object('operation_id',command.operation_id,'event','ACCEPTED',
  'manager_id',p_manager_id,'original_preparer_manager_id',command.prepared_by_manager_id,
  'semantic_digest',command.semantic_digest,'preview_digest',command.preview_digest,
  'candidate_set_digest',command.candidate_set_digest,'authority_revision',v_revision,
  'projections',v_projection_map,'device_intent_count',v_intent_count,
  'missing_device_targets',v_missing_device,'recorded_at',statement_timestamp());
 v_receipt_digest:=public.static_weekly_digest_jsonb(v_receipt);
 perform set_config('app.static_weekly_staffing_write','on',true);
 update public.static_weekly_staffing_commands set state='ACCEPTED',confirmation_key=p_confirmation_key,
  confirmed_by_manager_id=p_manager_id,authority_command_id=command.operation_id,accepted_revision=v_revision,
  accepted_receipt=v_receipt,accepted_at=statement_timestamp() where operation_id=command.operation_id;
 insert into public.static_weekly_staffing_command_receipts(operation_id,event_kind,actor_manager_id,
  semantic_digest,receipt_json,receipt_digest) values(command.operation_id,'ACCEPTED',p_manager_id,
  command.semantic_digest,v_receipt,v_receipt_digest);
 return v_receipt||jsonb_build_object('replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v11_staged_projection_digest_matches(p_operation_id uuid, p_content_digest text, p_manager_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare candidate record;signed_envelope jsonb;expected_digest text;matches integer:=0;
begin
 for candidate in select payload_json from public.static_weekly_staffing_staged_candidates
  where operation_id=p_operation_id and candidate_kind='projection' loop
  if candidate.payload_json->>'actorManagerId' is distinct from p_manager_id::text then continue;end if;

  -- BEGIN PRIVATE ORIGINAL-PENDING BATCH DIGEST
  IF candidate.payload_json#>>'{envelope,semantic_snapshot,schema}' IN('custodial.approved-static-pending-staffing-projection-snapshot.v1','custodial.approved-manual-pending-staffing-snapshot.v1') THEN
   PERFORM public.static_weekly_pending_assert_payload(p_operation_id,p_manager_id,candidate.payload_json);
   expected_digest:=public.static_weekly_digest_jsonb(jsonb_build_object(
    'publication_id',(candidate.payload_json->>'publicationId')::uuid,'week_start',(candidate.payload_json->>'serviceDate')::date,
    'exception_set_digest',candidate.payload_json->>'exceptionSetDigest','compiler_version',candidate.payload_json->>'compilerVersion',
    'objective',candidate.payload_json->'objective','metrics',candidate.payload_json->'metrics','replay_digest',candidate.payload_json->>'replayDigest',
    'projection_envelope_identity',candidate.payload_json#>>'{envelope,database_projection_identity}','attestation',NULL));
   IF expected_digest=p_content_digest THEN matches:=matches+1;END IF;
   CONTINUE;
  END IF;
  -- END PRIVATE ORIGINAL-PENDING BATCH DIGEST
  signed_envelope:=jsonb_set(candidate.payload_json->'envelope','{attestation}',
   public.static_weekly_v3_issue_attestation('dated_projection',
    public.static_weekly_projection_attestation_payload(candidate.payload_json->'envelope')),true);
  expected_digest:=public.static_weekly_digest_jsonb(jsonb_build_object(
   'publication_id',(candidate.payload_json->>'publicationId')::uuid,
   'week_start',(candidate.payload_json->>'serviceDate')::date,
   'exception_set_digest',public.static_weekly_digest_jsonb(public.static_weekly_accepted_exception_set(
    (candidate.payload_json->>'publicationId')::uuid,(candidate.payload_json->>'serviceDate')::date)),
   'compiler_version',candidate.payload_json->>'compilerVersion','objective',candidate.payload_json->'objective',
   'metrics',candidate.payload_json->'metrics','replay_digest',candidate.payload_json->>'replayDigest',
   'projection_envelope_identity',signed_envelope->>'database_projection_identity',
   'attestation',signed_envelope->'attestation'));
  if expected_digest=p_content_digest then matches:=matches+1;end if;
 end loop;
 return matches=1;
exception when others then return false;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v13_begin_recurring_confirmation(p_manager_id uuid, p_confirmation_key uuid, p_effective_start date, p_expected_revision bigint, p_preview_digest text, p_full_nine_source_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_request jsonb; v_digest text; v_revision bigint;
  v_parent public.static_weekly_recurring_confirmations%rowtype;
  v_receipt jsonb;
begin
  perform public.static_weekly_v3_assert_control_plane();
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  perform public.static_weekly_v3_manager_actor(p_manager_id);
  if p_confirmation_key is null or p_effective_start is null
    or extract(isodow from p_effective_start)<>1 or not isfinite(p_effective_start)
    or p_expected_revision is null or p_expected_revision<0
    or p_preview_digest is null or p_preview_digest!~'^[0-9a-f]{64}$'
    or (p_full_nine_source_id is not null
      and p_full_nine_source_id<>'a00cdf2a-0623-5e2d-bc65-338c1dd67202'::uuid) then
    raise exception using errcode='22023',message='exact recurring confirmation request required';
  end if;
  v_request:=jsonb_build_object('schema','static-weekly.recurring-confirmation-request.v1',
    'managerId',p_manager_id,'confirmationKey',p_confirmation_key,
    'effectiveStart',p_effective_start,'expectedRevision',p_expected_revision,
    'previewDigest',p_preview_digest,'fullNineSourceId',p_full_nine_source_id);
  v_digest:=public.static_weekly_digest_jsonb(v_request);

  -- Reread a same-key parent BEFORE time/revision staleness. A committed retry
  -- must not accidentally compile/publish against today's roster.
  select * into v_parent from public.static_weekly_recurring_confirmations
    where manager_id=p_manager_id and confirmation_key=p_confirmation_key for update;
  if found then
    if v_parent.request_digest<>v_digest or v_parent.request_json<>v_request then
      raise exception using errcode='23505',message='recurring confirmation idempotency conflict';
    end if;
    select receipt_json into v_receipt from public.static_weekly_recurring_confirmation_receipts
      where operation_id=v_parent.operation_id;
    if v_receipt is not null then
      return jsonb_build_object('state','ACCEPTED','operationId',v_parent.operation_id,'receipt',v_receipt);
    end if;
    if v_parent.owner_xid<>pg_current_xact_id() then
      raise exception using errcode='23514',message='incomplete recurring confirmation from another transaction';
    end if;
    return jsonb_build_object('state','RESERVED','operationId',v_parent.operation_id,'requestDigest',v_digest);
  end if;
  if p_effective_start<=public.sch_service_date(statement_timestamp()) then
    raise exception using errcode='23514',message='new recurring plan must start on a future zoo-local Monday';
  end if;
  select current_revision into v_revision from public.static_weekly_schedule_control where singleton for update;
  if v_revision is distinct from p_expected_revision then
    raise exception using errcode='40001',message='recurring confirmation authority revision changed';
  end if;
  insert into public.static_weekly_recurring_confirmations(manager_id,confirmation_key,
    request_json,request_digest,effective_start,expected_revision,preview_digest,full_nine_source_id)
  values(p_manager_id,p_confirmation_key,v_request,v_digest,p_effective_start,p_expected_revision,
    p_preview_digest,p_full_nine_source_id) returning * into v_parent;
  return jsonb_build_object('state','RESERVED','operationId',v_parent.operation_id,'requestDigest',v_digest);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v13_read_recurring_confirmation(p_manager_id uuid, p_confirmation_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_parent public.static_weekly_recurring_confirmations%rowtype;v_receipt jsonb;
begin
  perform public.static_weekly_v3_assert_control_plane();
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  perform public.static_weekly_v3_manager_actor(p_manager_id);
  if p_confirmation_key is null then raise exception using errcode='22023',message='exact recurring confirmation key required';end if;

  select * into v_parent from public.static_weekly_recurring_confirmations
    where manager_id=p_manager_id and confirmation_key=p_confirmation_key;
  if not found then return jsonb_build_object('state','NOT_FOUND','confirmationKey',p_confirmation_key);end if;
  select receipt_json into v_receipt from public.static_weekly_recurring_confirmation_receipts
    where operation_id=v_parent.operation_id;
  if v_receipt is null then
    raise exception using errcode='23514',message='recurring confirmation has not committed a complete receipt';
  end if;
  return jsonb_build_object('state','ACCEPTED','operationId',v_parent.operation_id,'receipt',v_receipt);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v14_admit_recurring_source(p_manager_id uuid, p_confirmation_key uuid, p_canonical_source jsonb, p_source_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_parent public.static_weekly_recurring_confirmations%rowtype;
  v_binding public.static_weekly_recurring_source_bindings%rowtype;
  v_digest text;v_identity text;v_source_id uuid;
begin
  perform public.static_weekly_v3_assert_control_plane();
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  perform public.static_weekly_v3_manager_actor(p_manager_id);

  select * into v_parent from public.static_weekly_recurring_confirmations
    where manager_id=p_manager_id and confirmation_key=p_confirmation_key for update;
  if not found or v_parent.owner_xid<>pg_current_xact_id()
    or exists(select 1 from public.static_weekly_recurring_confirmation_receipts where operation_id=v_parent.operation_id) then
    raise exception using errcode='42501',message='recurring source requires this transaction''s uncompleted named-manager reservation';
  end if;
  if p_canonical_source is null or jsonb_typeof(p_canonical_source) is distinct from 'object'
    or jsonb_typeof(p_canonical_source->'version') is distinct from 'object'
    or p_canonical_source ? 'versions'
    or p_canonical_source->'exceptions' is distinct from '[]'::jsonb
    or p_canonical_source#>'{version,namedAbsentSlotIds}' is distinct from '[]'::jsonb
    or p_canonical_source->>'serviceDate' is distinct from v_parent.effective_start::text
    or p_canonical_source#>>'{version,effectiveStart}' is distinct from v_parent.effective_start::text
    or p_canonical_source#>'{version,effectiveEnd}' is distinct from 'null'::jsonb
    or p_source_digest is null or p_source_digest!~'^[0-9a-f]{64}$' then
    raise exception using errcode='23514',message='recurring source must match the exact future exception-free candidate';
  end if;
  perform public.static_weekly_v3_source_identity(p_canonical_source);
  v_digest:=public.static_weekly_digest_jsonb(p_canonical_source);
  if p_source_digest<>v_digest then
    raise exception using errcode='23514',message='recurring source digest does not match actual inserted bytes';
  end if;
  select * into v_binding from public.static_weekly_recurring_source_bindings where operation_id=v_parent.operation_id;
  if found then
    if v_binding.owner_xid<>pg_current_xact_id() or v_binding.source_digest<>v_digest
      or not exists(select 1 from public.static_weekly_authority_source_documents
        where source_id=v_binding.source_id and source_digest=v_digest and canonical_source=p_canonical_source) then
      raise exception using errcode='23505',message='recurring parent already binds different source bytes';
    end if;
    return jsonb_build_object('source_id',v_binding.source_id,'source_digest',v_digest,'operation_id',v_parent.operation_id);
  end if;
  v_identity:=public.static_weekly_digest_text('static-weekly.recurring-source.v1:'||p_manager_id||':'||p_confirmation_key||':'||v_digest);
  -- Stable RFC-variant UUID identity from parent semantic identity + actual
  -- bytes. Rollback/retry does not pick a different registered source UUID.
  v_source_id:=(substr(v_identity,1,8)||'-'||substr(v_identity,9,4)||'-5'||substr(v_identity,14,3)||'-a'||substr(v_identity,18,3)||'-'||substr(v_identity,21,12))::uuid;
  insert into public.static_weekly_authority_source_documents(source_id,canonical_source,source_digest,configured_by)
    values(v_source_id,p_canonical_source,v_digest,'recurring-confirmation:'||v_parent.operation_id);
  insert into public.static_weekly_recurring_source_bindings(source_id,operation_id,source_digest)
    values(v_source_id,v_parent.operation_id,v_digest);
  return jsonb_build_object('source_id',v_source_id,'source_digest',v_digest,'operation_id',v_parent.operation_id);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v15_advance_recurring_generation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_table_name='employees' then
    if tg_op='UPDATE' and new.active is not distinct from old.active
      and new.display_name is not distinct from old.display_name
      and new.employee_code is not distinct from old.employee_code then return null;end if;
    if tg_op='INSERT' and new.employee_code!~'^EMP[0-9]+$' and not exists(select 1 from public.weekly_roster_slot_incumbencies i where i.person_id=new.id) then return null;end if;
    if tg_op='DELETE' and old.employee_code!~'^EMP[0-9]+$' and not exists(select 1 from public.weekly_roster_slot_incumbencies i where i.person_id=old.id) then return null;end if;
    if tg_op='UPDATE' and new.employee_code!~'^EMP[0-9]+$' and old.employee_code!~'^EMP[0-9]+$' and not exists(select 1 from public.weekly_roster_slot_incumbencies i where i.person_id=new.id) then return null;end if;
  elsif tg_table_name='static_weekly_authority_source_documents' then
    -- Registration is immutable evidence, not schedule activation. Retirement
    -- or corruption/change of a selected source does invalidate preview basis.
    if tg_op='INSERT' then return null;end if;
    if tg_op='UPDATE' and new.active is not distinct from old.active
      and new.retired_at is not distinct from old.retired_at
      and new.canonical_source is not distinct from old.canonical_source
      and new.source_digest is not distinct from old.source_digest then return null;end if;
  elsif tg_op='UPDATE' and to_jsonb(new)=to_jsonb(old) then return null;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  update public.static_weekly_recurring_generation set generation=generation+1,
    changed_at=statement_timestamp() where singleton;
  if not found then raise exception 'recurring generation singleton is missing';end if;

  perform public.static_weekly_v21_track_dependency_change(tg_table_name,tg_op,
   case when tg_op='INSERT' then null else to_jsonb(old) end,
   case when tg_op='DELETE' then null else to_jsonb(new) end);

  return null;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v15_read_recurring_generation()
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_generation bigint;
begin
  perform public.static_weekly_v3_assert_control_plane();
  select generation into strict v_generation from public.static_weekly_recurring_generation where singleton;
  return v_generation;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v17_recurring_dependency_snapshot(p_source_id uuid, p_week_start date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_source public.static_weekly_authority_source_documents%rowtype;
  v_slots jsonb;v_roster jsonb;v_body jsonb;
begin
  if p_source_id is null or p_week_start is null or not isfinite(p_week_start)
    or extract(isodow from p_week_start)<>1 then
    raise exception using errcode='22023',message='recurring dependency snapshot requires one source and Monday';
  end if;
  select * into v_source from public.static_weekly_authority_source_documents where source_id=p_source_id;
  if not found then raise exception using errcode='23514',message='recurring dependency source is unknown';end if;
  if jsonb_typeof(v_source.canonical_source->'slots') is distinct from 'array'
    or jsonb_array_length(v_source.canonical_source->'slots')=0
    or v_source.source_digest<>public.static_weekly_digest_jsonb(v_source.canonical_source) then
    raise exception using errcode='23514',message='recurring dependency source bytes are not intact';
  end if;
  if exists(select 1 from jsonb_array_elements(v_source.canonical_source->'slots') s
      where s->>'id' is null or not pg_input_is_valid(s->>'id','uuid')
        or (s ? 'contractorCapacity' and jsonb_typeof(s->'contractorCapacity') is distinct from 'boolean'))
    or (select count(*)<>count(distinct s->>'id') from jsonb_array_elements(v_source.canonical_source->'slots') s) then
    raise exception using errcode='23514',message='recurring dependency source requires exact unique registered positions';
  end if;
  if (select count(*)<>count(distinct (s->>'id')::uuid) from jsonb_array_elements(v_source.canonical_source->'slots') s)
    or exists(select 1 from jsonb_array_elements(v_source.canonical_source->'slots') s
    left join public.weekly_roster_slots r on r.slot_id=(s->>'id')::uuid where r.slot_id is null) then
    raise exception using errcode='23514',message='recurring dependency source requires exact unique registered positions';
  end if;
  select jsonb_agg(jsonb_build_object('slotId',r.slot_id,'slotCode',r.slot_code,
    'slotLabel',r.slot_label,'contractorCapacity',coalesce(s->'contractorCapacity','false'::jsonb)) order by r.slot_id)
    into v_slots from jsonb_array_elements(v_source.canonical_source->'slots') s
    join public.weekly_roster_slots r on r.slot_id=(s->>'id')::uuid;
  if exists(
    select s->>'slotId',p_week_start+offset_day
    from jsonb_array_elements(v_slots) s cross join generate_series(0,6) offset_day
    join public.v_weekly_roster_slot_incumbency_ranges i on i.slot_id=(s->>'slotId')::uuid
      and i.effective_start<=p_week_start+offset_day
      and (i.effective_end is null or p_week_start+offset_day<i.effective_end)
    group by s->>'slotId',p_week_start+offset_day having count(*)>1
  ) then raise exception using errcode='23514',message='recurring dependency position has ambiguous dated incumbency';end if;
  select jsonb_agg(jsonb_build_object('slotId',s->'slotId','serviceDate',(p_week_start+offset_day)::text,
      'incumbencyId',i.incumbency_id,'personId',i.person_id,'incumbentName',i.person_name_snapshot,
      'employeeExists',e.id is not null,'employeeActive',e.active,
      'employeeName',e.display_name,'employeeCode',e.employee_code,
      'staffingPersonId',staffing.employee_id,'staffingState',staffing.staffing_state)
    order by s->>'slotId',offset_day) into v_roster
  from jsonb_array_elements(v_slots) s cross join generate_series(0,6) offset_day
  left join public.v_weekly_roster_slot_incumbency_ranges i on i.slot_id=(s->>'slotId')::uuid
    and i.effective_start<=p_week_start+offset_day
    and (i.effective_end is null or p_week_start+offset_day<i.effective_end)
  left join public.employees e on e.id=i.person_id
  left join lateral (select r.employee_id,r.staffing_state
    from public.weekly_roster_slot_staffing_states r where r.slot_id=(s->>'slotId')::uuid
      and r.effective_start<=p_week_start+offset_day
    order by r.effective_start desc,r.authority_revision desc limit 1) staffing on true;
  v_body:=jsonb_build_object('schema','static-weekly.recurring-dependency-snapshot.v1',
    'sourceId',v_source.source_id,'sourceDigest',v_source.source_digest,
    'sourceActive',v_source.active,'sourceRetiredAt',to_char(v_source.retired_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'weekStart',p_week_start,'weekEnd',p_week_start+6,'slots',v_slots,'roster',v_roster);
  return jsonb_build_object('snapshot',v_body,'digest',public.static_weekly_digest_jsonb(v_body));
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v18_bind_recurring_publication(p_manager_id uuid, p_confirmation_key uuid, p_publication_id uuid, p_expected_generation bigint, p_decision jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_parent public.static_weekly_recurring_confirmations%rowtype;
 v_source public.static_weekly_recurring_source_bindings%rowtype;
 v_publication public.weekly_schedule_publications%rowtype;
 v_version public.weekly_schedule_versions%rowtype;
 v_existing public.static_weekly_recurring_publication_bindings%rowtype;
 v_dependencies jsonb;v_generation bigint;v_predecessor uuid;v_digest text;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  perform public.static_weekly_v3_manager_actor(p_manager_id);

 select * into v_parent from public.static_weekly_recurring_confirmations
  where manager_id=p_manager_id and confirmation_key=p_confirmation_key;
 if not found or v_parent.owner_xid<>pg_current_xact_id()
  or exists(select 1 from public.static_weekly_recurring_confirmation_receipts where operation_id=v_parent.operation_id) then
  raise exception using errcode='42501',message='publication binding requires this transaction''s pending recurring parent';end if;
 select * into v_source from public.static_weekly_recurring_source_bindings where operation_id=v_parent.operation_id;
 select * into v_publication from public.weekly_schedule_publications where publication_id=p_publication_id;
 select * into v_version from public.weekly_schedule_versions where version_id=v_publication.version_id;
 if v_source.source_id is null or v_source.owner_xid<>pg_current_xact_id()
  or v_publication.publication_id is null or v_publication.actor_manager_id is distinct from p_manager_id
  or v_publication.idempotency_key is distinct from 'recurring:'||p_manager_id||':'||p_confirmation_key||':publish'
  or v_publication.effective_start is distinct from v_parent.effective_start
  or v_publication.effective_start<=public.sch_service_date(statement_timestamp())
  or v_version.authority_source_id is distinct from v_source.source_id
  or public.static_weekly_effective_version(v_parent.effective_start) is distinct from v_version.version_id then
  raise exception using errcode='23514',message='recurring publication binding must name its exact current parent-bound child';end if;
 select generation into strict v_generation from public.static_weekly_recurring_generation where singleton;
 if p_expected_generation is null or p_expected_generation<>v_generation then
  raise exception using errcode='40001',message='recurring dependency generation changed before publication binding';end if;
 perform public.static_weekly_assert_exact_object(p_decision,
  array['schema','implementationDigest','effectiveDate','timezone','compilerVersion','candidateSourceDigest',
    'recurringAvailabilityDigest','geographyDigest','assignments','gaps','fixedLunch','metrics','changes'],
  array['schema','implementationDigest','effectiveDate','timezone','compilerVersion','candidateSourceDigest',
    'recurringAvailabilityDigest','geographyDigest','assignments','gaps','fixedLunch','metrics','changes','shiftEnd'],
  'recurring displayed decision');
 if p_decision->>'schema' is distinct from 'memphis-zoo.recurring-manager-decision.v1'
  or p_decision->>'effectiveDate' is distinct from v_parent.effective_start::text
  or p_decision->>'timezone' is distinct from 'America/Chicago'
  or p_decision->>'candidateSourceDigest' is distinct from v_source.source_digest
  or p_decision->>'implementationDigest'!~'^[0-9a-f]{64}$'
  or p_decision->>'compilerVersion' is distinct from v_version.draft_document#>>'{authority,optimizerResult,compilerVersion}'
  or p_decision->'metrics' is distinct from v_version.draft_document#>'{authority,optimizerResult,metrics}'
  or jsonb_typeof(p_decision->'assignments') is distinct from 'array'
  or jsonb_typeof(p_decision->'fixedLunch') is distinct from 'object'
  or jsonb_typeof(p_decision->'gaps') is distinct from 'object'
  or jsonb_typeof(p_decision->'changes') is distinct from 'array'
  or not (p_decision ? 'shiftEnd') then
  raise exception using errcode='23514',message='recurring displayed decision does not match its attested publication';end if;
 -- Compare every canonical assignment byte by identity, independent of SQL
 -- collation and Node's stable sort. No browser-supplied subset is accepted.
 if jsonb_array_length(p_decision->'assignments')=0
  or (select count(*)<>count(distinct a->>'planWorkId') from jsonb_array_elements(p_decision->'assignments') a)
  or exists(with displayed as (
    select a->>'planWorkId' id,public.static_weekly_v18_canonical_display_assignment(a) body
    from jsonb_array_elements(p_decision->'assignments') a
   ),attested as (
    select a->>'planWorkId' id,a body from jsonb_array_elements(v_version.draft_document#>'{authority,optimizerResult,assignments}') a
   ) select 1 from displayed d full join attested a using(id) where d.id is null or a.id is null or d.body is distinct from a.body) then
  raise exception using errcode='23514',message='recurring displayed assignments differ from the complete attested publication';end if;
 v_dependencies:=public.static_weekly_v17_recurring_dependency_snapshot(v_source.source_id,v_parent.effective_start);
 if v_dependencies#>'{snapshot,sourceActive}' is distinct from 'true'::jsonb
  or v_dependencies#>>'{snapshot,sourceDigest}' is distinct from v_source.source_digest then
  raise exception using errcode='23514',message='recurring publication source is no longer active and intact';end if;
 v_digest:=public.static_weekly_digest_jsonb(p_decision);
 select publication_id into v_predecessor from public.weekly_schedule_publications where version_id=v_publication.prior_version_id;
 select * into v_existing from public.static_weekly_recurring_publication_bindings where operation_id=v_parent.operation_id;
 if found then
  if v_existing.publication_id is distinct from p_publication_id or v_existing.owner_xid<>pg_current_xact_id()
   or v_existing.decision_json is distinct from p_decision or v_existing.decision_digest<>v_digest
   or v_existing.recurring_generation<>v_generation or v_existing.dependency_snapshot is distinct from v_dependencies->'snapshot'
   or v_existing.dependency_digest is distinct from v_dependencies->>'digest' then
   raise exception using errcode='23505',message='recurring parent already binds different publication dependencies';end if;
 else
  insert into public.static_weekly_recurring_publication_bindings(publication_id,operation_id,source_id,source_digest,
   effective_start,recurring_generation,predecessor_publication_id,implementation_digest,decision_json,decision_digest,
   dependency_snapshot,dependency_digest)
  values(p_publication_id,v_parent.operation_id,v_source.source_id,v_source.source_digest,v_parent.effective_start,
   v_generation,v_predecessor,p_decision->>'implementationDigest',p_decision,v_digest,v_dependencies->'snapshot',v_dependencies->>'digest');
 end if;
 return jsonb_build_object('state','BOUND_PENDING_FINALIZATION','publicationId',p_publication_id,
  'operationId',v_parent.operation_id,'recurringGeneration',v_generation,'dependencyDigest',v_dependencies->>'digest',
  'decisionDigest',v_digest,'predecessorPublicationId',v_predecessor,'accepted',false,'affectedPhonesUpdated',false);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v19_ack_terminal_target(p_intent uuid, p_device uuid, p_credential uuid, p_employee uuid, p_epoch bigint, p_revision bigint, p_rendered_digest text, p_applied_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare t public.static_weekly_recurring_terminal_intents%rowtype;a public.static_weekly_recurring_terminal_receipts%rowtype;
begin
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 perform public.static_weekly_v19_assert_terminal_principal(p_device,p_credential,p_employee,p_epoch);
 select * into t from public.static_weekly_recurring_terminal_intents where intent_id=p_intent;
 if not found or t.device_id is distinct from p_device or t.credential_id is distinct from p_credential
  or t.employee_id is distinct from p_employee or t.assignment_epoch is distinct from p_epoch
  or t.authority_revision is distinct from p_revision or t.target_digest is distinct from p_rendered_digest
  or p_applied_at is null or not isfinite(p_applied_at) or p_applied_at<t.created_at
  or p_applied_at>statement_timestamp()+interval '5 minutes' then
  raise exception using errcode='23514',message='terminal receipt must match exact principal target revision digest and time';end if;
 select * into a from public.static_weekly_recurring_terminal_receipts where intent_id=p_intent;
 if found then
  if a.rendered_digest is distinct from p_rendered_digest or a.applied_at is distinct from p_applied_at then
   raise exception using errcode='23505',message='terminal target already has a different receipt';end if;
 else
  insert into public.static_weekly_recurring_terminal_receipts(intent_id,rendered_digest,applied_at)
  values(p_intent,p_rendered_digest,p_applied_at) returning * into a;
 end if;
 -- An old exact receipt is retained history only. Selection always consults
 -- the latest winner/range, so this cannot acknowledge a later invalidation.
 return jsonb_build_object('intentId',a.intent_id,'receiptId',a.receipt_id,'applicationStatus','DEVICE_REPORTED_BLOCKED',
  'replacementCoverageReady',false,'receivedAt',a.received_at);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v19_invalidate_recurring_range(p_manager_id uuid, p_operation_id uuid, p_publication_id uuid, p_start date, p_end date, p_reason text, p_dependency_digest text, p_expected_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_actor jsonb;v_request jsonb;v_prior public.static_weekly_recurring_invalidations%rowtype;
 v_binding public.static_weekly_recurring_publication_bindings%rowtype;v_revision bigint;v_id uuid:=gen_random_uuid();
 v_weekday date;v_count int:=0;
begin
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
 v_request:=jsonb_build_object('managerId',p_manager_id,'operationId',p_operation_id,'publicationId',p_publication_id,
  'start',p_start,'end',p_end,'reason',p_reason,'dependencyDigest',p_dependency_digest,'expectedRevision',p_expected_revision);
 select * into v_prior from public.static_weekly_recurring_invalidations where operation_id=p_operation_id;
 if found then
  if v_prior.request_json is distinct from v_request then raise exception using errcode='23505',message='recurring invalidation operation already binds a different request';end if;
  return jsonb_build_object('invalidationId',v_prior.invalidation_id,'authorityRevision',v_prior.authority_revision,'state','BLOCKED_RECURRING_AUTHORITY','replayed',true);
 end if;
 select * into v_binding from public.static_weekly_recurring_publication_bindings where publication_id=p_publication_id;
 if p_operation_id is null or v_binding.publication_id is null or p_start is null or not isfinite(p_start)
  or p_start<=public.sch_service_date(statement_timestamp())
  or p_start<v_binding.effective_start or (p_end is not null and (not isfinite(p_end) or p_end<=p_start))
  or p_reason is null or p_reason not in ('ROSTER_DEPENDENCY_CHANGED','SOURCE_RETIRED','RESTRICTION_DEPENDENCY_CHANGED')
  or p_dependency_digest is null or p_dependency_digest!~'^[0-9a-f]{64}$'
  or not exists(select 1 from public.v_weekly_schedule_effective_ranges r join public.weekly_schedule_publications p using(version_id)
   where p.publication_id=p_publication_id and r.effective_start<=p_start
    and (r.effective_end is null or (p_start<r.effective_end and p_end is not null and p_end<=r.effective_end))) then
  raise exception using errcode='23514',message='recurring invalidation requires the exact latest winner and an affected future range';end if;
 v_revision:=public.static_weekly_advance_authority(p_expected_revision,'invalidate_recurring',p_manager_id,
  v_actor->>'manager_name',p_operation_id,public.static_weekly_digest_jsonb(v_request));
 insert into public.static_weekly_recurring_invalidations(invalidation_id,operation_id,publication_id,effective_start,effective_end,
  authority_revision,reason_code,dependency_digest,actor_manager_id,request_json,request_digest)
 values(v_id,p_operation_id,p_publication_id,p_start,p_end,v_revision,p_reason,p_dependency_digest,p_manager_id,v_request,public.static_weekly_digest_jsonb(v_request));
 insert into public.static_weekly_recurring_invalidated_principals(invalidation_id,employee_id)
 select distinct v_id,(r->>'personId')::uuid from jsonb_array_elements(v_binding.dependency_snapshot->'roster') r
 join public.employees e on e.id=(r->>'personId')::uuid where r->>'personId' is not null;
 -- All known materialized weeks, not just the first seven days. The persistent
 -- range plus principals also covers dates/phones not materialized yet.
 for v_weekday in select distinct x.week_start+n from public.weekly_schedule_compiled_projections x
  cross join generate_series(0,6) n where x.publication_id=p_publication_id
   and x.week_start+n>=p_start and (p_end is null or x.week_start+n<p_end) order by 1 loop
  v_count:=v_count+public.static_weekly_v19_reconcile_terminal_date(v_weekday);
 end loop;
 return jsonb_build_object('invalidationId',v_id,'authorityRevision',v_revision,
  'state','BLOCKED_RECURRING_AUTHORITY','targetsCreated',v_count,'affectedPhonesUpdated',false,'replayed',false);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v19_read_terminal_target(p_date date, p_device uuid, p_credential uuid, p_employee uuid, p_epoch bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare r public.static_weekly_recurring_invalidations%rowtype;t public.static_weekly_recurring_terminal_intents%rowtype;
 ack public.static_weekly_recurring_terminal_receipts%rowtype;
begin
 if p_date is null or not isfinite(p_date) then raise exception 'terminal read requires one finite service date';end if;
 perform public.static_weekly_v19_assert_terminal_principal(p_device,p_credential,p_employee,p_epoch);
 r:=public.static_weekly_v19_current_terminal_range(p_date);if r.invalidation_id is null then return null;end if;
 select * into t from public.static_weekly_recurring_terminal_intents where invalidation_id=r.invalidation_id
  and service_date=p_date and employee_id=p_employee and device_id=p_device and credential_id=p_credential and assignment_epoch=p_epoch;
 if not found then return jsonb_build_object('targetType','BLOCKED_RECURRING_AUTHORITY','authorityRevision',r.authority_revision,
  'publicationId',r.publication_id,'invalidationId',r.invalidation_id,'applicationStatus','PENDING_TARGET_RECONCILIATION');end if;
 select * into ack from public.static_weekly_recurring_terminal_receipts where intent_id=t.intent_id;
 return jsonb_build_object('intentId',t.intent_id,'target',t.target_json,'targetDigest',t.target_digest,
  'applicationStatus',case when ack.intent_id is null then 'PENDING' else 'DEVICE_REPORTED_BLOCKED' end,
  'appliedAt',ack.applied_at,'receivedAt',ack.received_at,'replacementCoverageReady',false);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v19_reconcile_terminal_date(p_service_date date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_range public.static_weekly_recurring_invalidations%rowtype;person record;device record;
 v_target jsonb;v_intent uuid;v_count int:=0;v_has_device boolean;
begin
 if p_service_date is null or not isfinite(p_service_date) then raise exception 'terminal target requires one finite service date';end if;
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 v_range:=public.static_weekly_v19_current_terminal_range(p_service_date);
 if v_range.invalidation_id is null then return 0;end if;
 -- Capture currently incumbent people too: filling a position or assigning a
 -- first phone must not make an invalid recurring pattern look usable.
 insert into public.static_weekly_recurring_invalidated_principals(invalidation_id,employee_id)
 select distinct v_range.invalidation_id,r.person_id from public.static_weekly_recurring_publication_bindings b
 cross join lateral jsonb_array_elements(b.dependency_snapshot->'slots') s
 join public.v_weekly_roster_slot_incumbency_ranges r on r.slot_id=(s->>'slotId')::uuid
  and r.effective_start<=p_service_date and (r.effective_end is null or p_service_date<r.effective_end)
 join public.employees e on e.id=r.person_id where b.publication_id=v_range.publication_id
 on conflict do nothing;
 for person in select employee_id from public.static_weekly_recurring_invalidated_principals
  where invalidation_id=v_range.invalidation_id order by employee_id loop
  v_has_device:=false;
  for device in select d.id,c.credential_id,d.assignment_epoch from public.devices d
   join public.device_auth_credentials c on c.device_id=d.id and c.confirmed_at is not null
    and c.revoked_at is null and c.expires_at>statement_timestamp()
   where d.active=true and d.assigned_employee_id=person.employee_id order by d.id,c.credential_id loop
   v_has_device:=true;
   v_target:=jsonb_build_object('schema','static-weekly.recurring-terminal-target.v1',
    'targetType','BLOCKED_RECURRING_AUTHORITY','invalidationId',v_range.invalidation_id,
    'operationId',v_range.operation_id,'publicationId',v_range.publication_id,'serviceDate',p_service_date,
    'authorityRevision',v_range.authority_revision,'reasonCode',v_range.reason_code,
    'employeeId',person.employee_id,'deviceId',device.id,'credentialId',device.credential_id,'assignmentEpoch',device.assignment_epoch);
   insert into public.static_weekly_recurring_terminal_intents(invalidation_id,service_date,employee_id,
    device_id,credential_id,assignment_epoch,authority_revision,target_json,target_digest)
   values(v_range.invalidation_id,p_service_date,person.employee_id,device.id,device.credential_id,device.assignment_epoch,
    v_range.authority_revision,v_target,public.static_weekly_digest_jsonb(v_target)) on conflict do nothing returning intent_id into v_intent;
   if found then v_count:=v_count+1;end if;
  end loop;
  if not v_has_device then
   v_target:=jsonb_build_object('schema','static-weekly.recurring-terminal-target.v1',
    'targetType','BLOCKED_RECURRING_AUTHORITY','invalidationId',v_range.invalidation_id,
    'operationId',v_range.operation_id,'publicationId',v_range.publication_id,'serviceDate',p_service_date,
    'authorityRevision',v_range.authority_revision,'reasonCode',v_range.reason_code,
    'employeeId',person.employee_id,'deviceId',null,'credentialId',null,'assignmentEpoch',null);
   insert into public.static_weekly_recurring_terminal_intents(invalidation_id,service_date,employee_id,
    authority_revision,target_json,target_digest)
   values(v_range.invalidation_id,p_service_date,person.employee_id,v_range.authority_revision,
    v_target,public.static_weekly_digest_jsonb(v_target)) on conflict do nothing returning intent_id into v_intent;
   if found then v_count:=v_count+1;end if;
  end if;
 end loop;
 return v_count;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v20_read_recurring_preview_basis(p_manager uuid, p_week date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_winner public.weekly_schedule_publications%rowtype;v_pattern record;v_invalidations jsonb;
 v_revision bigint;v_context jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 perform public.static_weekly_v3_manager_actor(p_manager);
 if p_week is null or not isfinite(p_week) or extract(isodow from p_week)<>1
  or p_week<=public.sch_service_date(statement_timestamp()) then
  raise exception using errcode='22023',message='recurring repair preview requires one future Monday';end if;
 select * into v_winner from public.weekly_schedule_publications
  where version_id=public.static_weekly_effective_version(p_week);
 if not found then raise exception using errcode='23514',message='recurring preview has no effective publication';end if;
 select jsonb_agg(jsonb_build_object('invalidationId',i.invalidation_id,'authorityRevision',i.authority_revision,
  'effectiveStart',i.effective_start,'effectiveEnd',i.effective_end,'reasonCode',i.reason_code)
  order by i.authority_revision,i.invalidation_id) into v_invalidations
 from public.static_weekly_recurring_invalidations i where i.publication_id=v_winner.publication_id
  and i.effective_start<=p_week+6 and (i.effective_end is null or p_week<i.effective_end);
 if v_invalidations is null then return public.static_weekly_v3_read_publication_source(v_winner.publication_id,p_week);end if;
 select p.publication_id,p.version_id,v.authority_source_id,s.source_digest,v.draft_document into v_pattern
 from public.weekly_schedule_publications p join public.weekly_schedule_versions v using(version_id)
 join public.static_weekly_authority_source_documents s on s.source_id=v.authority_source_id
 where p.authority_revision<v_winner.authority_revision and p.effective_start<=p_week
  and s.active=true and s.retired_at is null and s.source_digest=public.static_weekly_digest_jsonb(s.canonical_source)
  and not exists(select 1 from public.static_weekly_recurring_invalidations i where i.publication_id=p.publication_id
   and i.effective_start<=p_week+6 and (i.effective_end is null or p_week<i.effective_end))
 order by p.effective_start desc,p.authority_revision desc limit 1;
 if not found then raise exception using errcode='23514',message='no preceding valid registered source pattern is available for recurring repair';end if;
 select current_revision into strict v_revision from public.static_weekly_schedule_control where singleton;
 v_context:=jsonb_build_object('schema','static-weekly.recurring-repair-basis.v1',
  'state','REPLACING_INVALID_FUTURE','effectivePublicationId',v_winner.publication_id,
  'patternPublicationId',v_pattern.publication_id,'patternSourceId',v_pattern.authority_source_id,
  'patternSourceDigest',v_pattern.source_digest,'effectiveStart',p_week,'authorityRevision',v_revision,
  'invalidations',v_invalidations,'managerConfirmationRequired',true,'published',false);
 return jsonb_build_object('source_id',v_pattern.authority_source_id,
  'compiler_input',public.static_weekly_v4_hydrate_compiler_source(v_pattern.draft_document#>'{authority,compilerInput}',p_week),
  'exceptions','[]'::jsonb,'publication_id',v_pattern.publication_id,'version_id',v_pattern.version_id,
  'authority_revision',v_revision,'repair_context',v_context,'repair_context_digest',public.static_weekly_digest_jsonb(v_context));
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v21_first_changed_dependency_date(p_publication uuid, p_week date)
 RETURNS date
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare b public.static_weekly_recurring_publication_bindings%rowtype;v_current jsonb;v_date date;
begin
 select * into strict b from public.static_weekly_recurring_publication_bindings where publication_id=p_publication;
 v_current:=public.static_weekly_v17_recurring_dependency_snapshot(b.source_id,p_week)->'snapshot';
 if (v_current-array['weekStart','weekEnd','roster']) is distinct from
  (b.dependency_snapshot-array['weekStart','weekEnd','roster']) then return p_week;end if;
 select min((actual->>'serviceDate')::date) into v_date from jsonb_array_elements(v_current->'roster') actual
 where not exists(select 1 from jsonb_array_elements(b.dependency_snapshot->'roster') expected
  where expected->>'slotId'=actual->>'slotId'
   and extract(isodow from (expected->>'serviceDate')::date)=extract(isodow from (actual->>'serviceDate')::date)
   and (actual-'serviceDate')=(expected-'serviceDate'));
 return v_date;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v21_reconcile_dependency_changes(p_manager_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_ids uuid[];v_binding record;v_week date;v_date date;v_first date;v_revision bigint;
 v_source public.static_weekly_authority_source_documents%rowtype;v_result jsonb;v_checked jsonb:='[]';
 v_effects jsonb:='[]';v_dependency jsonb;v_existing public.static_weekly_recurring_invalidations%rowtype;
 v_day date;v_state jsonb;v_count int;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 perform public.static_weekly_v3_manager_actor(p_manager_id);
 select array_agg(c.change_id order by c.generation,c.change_id) into v_ids
 from public.static_weekly_recurring_dependency_changes c where c.owner_xid=pg_current_xact_id()
  and not exists(select 1 from public.static_weekly_recurring_dependency_checks done where done.change_id=c.change_id);
 if cardinality(v_ids)>0 then
  for v_binding in select b.*,r.effective_end from public.static_weekly_recurring_publication_bindings b
   join public.weekly_schedule_publications p using(publication_id)
   join public.v_weekly_schedule_effective_ranges r using(version_id)
   where r.effective_start>public.sch_service_date(statement_timestamp())
   order by r.effective_start,b.publication_id loop
   v_first:=null;
   for v_week in select distinct week_start from (
    select v_binding.effective_start week_start
    union all
    select date_trunc('week',field.value::date::timestamp)::date
    from public.static_weekly_recurring_dependency_changes c
    cross join lateral (values(c.before_json),(c.after_json)) body(value)
    cross join lateral jsonb_each_text(body.value) field
    where c.change_id=any(v_ids) and field.key in ('effective_start','effective_end','closed_at_effective_date')
     and field.value is not null and pg_input_is_valid(field.value,'date')
     and isfinite(field.value::date)
   ) weeks where week_start>=v_binding.effective_start
    and (v_binding.effective_end is null or week_start<v_binding.effective_end) order by week_start loop
    v_date:=public.static_weekly_v21_first_changed_dependency_date(v_binding.publication_id,v_week);
    if v_date is not null and (v_binding.effective_end is null or v_date<v_binding.effective_end) then
     v_first:=least(v_first,v_date);end if;
   end loop;
   v_checked:=v_checked||jsonb_build_array(jsonb_build_object('publicationId',v_binding.publication_id,'firstChangedDate',v_first));
   if v_first is null then continue;end if;
   select * into v_existing from public.static_weekly_recurring_invalidations i where i.publication_id=v_binding.publication_id
    and i.effective_start<=v_first and (i.effective_end is null or (v_binding.effective_end is not null and i.effective_end>=v_binding.effective_end))
    order by i.authority_revision desc limit 1;
   if found then
    -- An already terminal winner stays terminal; new/current principals still
    -- acquire their exact pending targets. Do not fabricate another revision.
    for v_day in select distinct x.week_start+n from public.weekly_schedule_compiled_projections x
     cross join generate_series(0,6) n where x.publication_id=v_binding.publication_id
      and x.week_start+n>=v_existing.effective_start
      and (v_existing.effective_end is null or x.week_start+n<v_existing.effective_end) order by 1 loop
     perform public.static_weekly_v19_reconcile_terminal_date(v_day);
    end loop;
    v_effects:=v_effects||jsonb_build_array(jsonb_build_object('invalidationId',v_existing.invalidation_id,
     'publicationId',v_binding.publication_id,'authorityRevision',v_existing.authority_revision,'state','BLOCKED_RECURRING_AUTHORITY','existing',true));
   else
    select * into strict v_source from public.static_weekly_authority_source_documents where source_id=v_binding.source_id;
    select current_revision into strict v_revision from public.static_weekly_schedule_control where singleton;
    v_week:=date_trunc('week',v_first::timestamp)::date;
    v_dependency:=public.static_weekly_v17_recurring_dependency_snapshot(v_binding.source_id,v_week);
    v_state:=public.static_weekly_v19_invalidate_recurring_range(p_manager_id,gen_random_uuid(),v_binding.publication_id,
     v_first,v_binding.effective_end,case when not v_source.active or v_source.retired_at is not null then 'SOURCE_RETIRED' else 'ROSTER_DEPENDENCY_CHANGED' end,
     v_dependency->>'digest',v_revision);
    v_effects:=v_effects||jsonb_build_array(v_state||jsonb_build_object('publicationId',v_binding.publication_id));
   end if;
  end loop;
  select current_revision into strict v_revision from public.static_weekly_schedule_control where singleton;
  v_result:=jsonb_build_object('schema','static-weekly.recurring-dependency-reconciliation.v1',
   'changeIds',to_jsonb(v_ids),'processedByManagerId',p_manager_id,'authorityRevision',v_revision,
   'checkedPublications',v_checked,'invalidations',v_effects,'affectedPhonesUpdated',false);
  insert into public.static_weekly_recurring_dependency_checks(change_id,processed_by_manager_id,result_json,result_digest)
   select id,p_manager_id,v_result,public.static_weekly_digest_jsonb(v_result) from unnest(v_ids) id;
 end if;
 -- Return current future blocked state separately from any historical accepted
 -- mutation response, including an exact retry with no new dependency changes.
 select coalesce(jsonb_agg(jsonb_build_object('publicationId',p.publication_id,'invalidationId',i.invalidation_id,
  'effectiveStart',i.effective_start,'effectiveEnd',i.effective_end,'authorityRevision',i.authority_revision,
  'state','BLOCKED_RECURRING_AUTHORITY') order by r.effective_start,i.authority_revision),'[]'::jsonb) into v_state
 from public.v_weekly_schedule_effective_ranges r join public.weekly_schedule_publications p using(version_id)
 join public.static_weekly_recurring_invalidations i on i.publication_id=p.publication_id
 where r.effective_start>public.sch_service_date(statement_timestamp());
 select current_revision into strict v_revision from public.static_weekly_schedule_control where singleton;
 return jsonb_build_object('processedChangeCount',coalesce(cardinality(v_ids),0),'authorityRevision',v_revision,
  'invalidations',v_effects,'blockedPublications',v_state,'affectedPhonesUpdated',false);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v21_track_dependency_change(p_table text, p_operation text, p_before jsonb, p_after jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_keys text[];v_before jsonb;v_after jsonb;
begin
 -- Publishing a separately validated version changes generation but is not
 -- a staffing edit. Registration and semantic no-ops are filtered by v15.
 if p_table='weekly_schedule_publications' then return;end if;
 if not exists(select 1 from public.static_weekly_recurring_publication_bindings b
  join public.weekly_schedule_publications p using(publication_id)
  join public.v_weekly_schedule_effective_ranges r using(version_id)
  where r.effective_start>public.sch_service_date(statement_timestamp())) then return;end if;
 v_keys:=case p_table
  when 'employees' then array['id','employee_code','display_name','active']
  when 'weekly_roster_slots' then array['slot_id','slot_code','slot_label']
  when 'weekly_roster_slot_incumbencies' then array['incumbency_id','slot_id','person_id','person_name_snapshot','effective_start','effective_end']
  when 'weekly_roster_slot_incumbency_closures' then array['incumbency_closure_id','closed_incumbency_id','replacement_incumbency_id','closed_at_effective_date']
  when 'weekly_roster_slot_staffing_states' then array['staffing_state_id','slot_id','employee_id','staffing_state','effective_start']
  when 'static_weekly_authority_source_documents' then array['source_id','active','retired_at','source_digest'] end;
 if v_keys is null or p_operation not in ('INSERT','UPDATE','DELETE') then raise exception 'unknown recurring dependency change';end if;
 select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) into v_before from jsonb_each(coalesce(p_before,'{}'::jsonb)) where key=any(v_keys);
 select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) into v_after from jsonb_each(coalesce(p_after,'{}'::jsonb)) where key=any(v_keys);
 if p_table='static_weekly_authority_source_documents' then
  -- Record exact content identity without copying the large private source.
  v_before:=v_before||jsonb_build_object('canonical_source_digest',public.static_weekly_digest_jsonb(p_before->'canonical_source'));
  v_after:=v_after||jsonb_build_object('canonical_source_digest',public.static_weekly_digest_jsonb(p_after->'canonical_source'));
 end if;
 if v_before=v_after then return;end if;
 insert into public.static_weekly_recurring_dependency_changes(generation,origin_table,origin_operation,origin_session_user,before_json,after_json)
 select generation,p_table,p_operation,session_user,v_before,v_after from public.static_weekly_recurring_generation where singleton;
 if not found then raise exception 'recurring dependency generation unavailable';end if;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v22_ack_recurring_application_target(p_intent uuid, p_device uuid, p_credential uuid, p_employee uuid, p_epoch bigint, p_revision bigint, p_target_digest text, p_rendered_digest text, p_applied_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare t public.static_weekly_recurring_application_intents%rowtype;r public.static_weekly_recurring_application_receipts%rowtype;
begin
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 perform public.static_weekly_v19_assert_terminal_principal(p_device,p_credential,p_employee,p_epoch);
 if not exists(select 1 from public.employees where id=p_employee and active=true) then
  raise exception using errcode='42501',message='recurring schedule requires an active employee principal';end if;
 if exists(select 1 from custodial_coverall.manual_application_intents where intent_id=p_intent) then
  if exists(select 1 from public.static_weekly_recurring_application_intents where intent_id=p_intent) then raise exception 'Ambiguous typed intent ownership';end if;
  return custodial_coverall.ack_manual_application_target(p_intent,p_device,p_credential,p_employee,p_epoch,p_revision,p_target_digest,p_rendered_digest,p_applied_at);end if;
 select * into t from public.static_weekly_recurring_application_intents where intent_id=p_intent for share;
 if not found or t.device_id is distinct from p_device or t.credential_id is distinct from p_credential
  or t.employee_id is distinct from p_employee or t.assignment_epoch is distinct from p_epoch
  or t.authority_revision is distinct from p_revision or t.target_digest is distinct from p_target_digest
  or t.view_digest is distinct from p_rendered_digest or p_applied_at is null or not isfinite(p_applied_at)
  or p_applied_at<t.created_at or p_applied_at>clock_timestamp()+interval '5 minutes' then
  raise exception using errcode='23514',message='recurring receipt requires exact principal target rendered-view revision and time';end if;
 select * into r from public.static_weekly_recurring_application_receipts where intent_id=p_intent;
 if found then
  if r.rendered_digest is distinct from p_rendered_digest or r.applied_at is distinct from p_applied_at then
   raise exception using errcode='23505',message='recurring target already has a different receipt';end if;
 else
  insert into public.static_weekly_recurring_application_receipts(intent_id,rendered_digest,applied_at)
   values(p_intent,p_rendered_digest,p_applied_at) returning * into r;
 end if;
 -- This is an immutable historical receipt. The merged reader, not this
 -- response, decides whether it still applies to the CURRENT desired state.
 return jsonb_build_object('intentId',p_intent,'receiptId',r.receipt_id,'applicationStatus','DEVICE_REPORTED_APPLIED',
  'currentAuthorityNotInferred',true,'appliedAt',r.applied_at,'receivedAt',r.received_at);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v22_read_recurring_application_target(p_date date, p_device uuid, p_credential uuid, p_employee uuid, p_epoch bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare t public.static_weekly_recurring_application_intents%rowtype;receipt public.static_weekly_recurring_application_receipts%rowtype;a record;
begin
 if p_date is null or not isfinite(p_date) then raise exception 'recurring application read requires finite date';end if;
 perform public.static_weekly_v19_assert_terminal_principal(p_device,p_credential,p_employee,p_epoch);
 if not exists(select 1 from public.employees where id=p_employee and active=true) then
  raise exception using errcode='42501',message='recurring schedule requires an active employee principal';end if;
 select * into a from public.static_weekly_v6_schedule_authority_state(p_date);
 if a.projection_status='blocked_recurring_authority' then return public.static_weekly_v19_read_terminal_target(p_date,p_device,p_credential,p_employee,p_epoch);end if;
 if exists(select 1 from custodial_coverall.manual_application_bindings where publication_id=a.publication_id)
  and exists(select 1 from public.static_weekly_recurring_publication_bindings where publication_id=a.publication_id) then raise exception 'Conflicting current manual/recurring origins';end if;
 if exists(select 1 from custodial_coverall.manual_application_bindings where publication_id=a.publication_id) then
  return custodial_coverall.read_manual_application_target(p_date,p_device,p_credential,p_employee,p_epoch);end if;
 select * into t from public.static_weekly_recurring_application_intents i
  where i.service_date=p_date and i.device_id=p_device and i.credential_id=p_credential
   and i.employee_id=p_employee and i.assignment_epoch=p_epoch
  order by i.authority_revision desc,i.created_at desc,i.intent_id desc limit 1;
 if not found then
  if exists(select 1 from public.static_weekly_recurring_publication_bindings where publication_id=a.publication_id) then
   return jsonb_build_object('applicationStatus','PENDING_TARGET_RECONCILIATION','affectedPhonesUpdated',false);end if;
  return null;
 end if;
 if a.projection_status is distinct from 'current' or t.publication_id is distinct from a.publication_id
  or t.projection_id is distinct from a.projection_id or t.authority_revision is distinct from a.projection_authority_revision then
  return jsonb_build_object('applicationStatus','PENDING_TARGET_RECONCILIATION','affectedPhonesUpdated',false);end if;
 select * into receipt from public.static_weekly_recurring_application_receipts where intent_id=t.intent_id;
 return jsonb_build_object('intentId',t.intent_id,'target',t.target_json,'targetDigest',t.target_digest,
  'view',t.view_json,'viewJsonText',t.view_json::text,'viewDigest',t.view_digest,
  'applicationStatus',case when receipt.intent_id is null then 'PENDING' else 'DEVICE_REPORTED_APPLIED' end,
  'receiptId',receipt.receipt_id,'appliedAt',receipt.applied_at,'receivedAt',receipt.received_at);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v22_reconcile_recurring_application_date(p_date date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a record;b public.static_weekly_recurring_publication_bindings%rowtype;
 p public.static_weekly_recurring_confirmations%rowtype;l public.weekly_schedule_lunch_documents%rowtype;
person record;device record;v_view jsonb;v_target jsonb;v_view_digest text;v_intent uuid;v_count int:=0;v_devices int;
begin
 if p_date is null or not isfinite(p_date) then raise exception 'recurring application reconciliation requires one finite date';end if;
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select * into a from public.static_weekly_v6_schedule_authority_state(p_date);
 if a.projection_status='blocked_recurring_authority' then return public.static_weekly_v19_reconcile_terminal_date(p_date);end if;
 if a.projection_status is distinct from 'current' or a.projection_id is null then raise exception 'recurring schedule projection is unavailable';end if;
 if exists(select 1 from custodial_coverall.manual_application_bindings where publication_id=a.publication_id)
  and exists(select 1 from public.static_weekly_recurring_publication_bindings where publication_id=a.publication_id) then raise exception 'Conflicting current manual/recurring origins';end if;
 select * into b from public.static_weekly_recurring_publication_bindings where publication_id=a.publication_id;
 if not found then return custodial_coverall.reconcile_manual_application_date(p_date);end if; -- exact manual origin is separate, never a recurring confirmation
 select * into strict p from public.static_weekly_recurring_confirmations where operation_id=b.operation_id;
 if not exists(select 1 from public.static_weekly_recurring_confirmation_receipts r where r.operation_id=b.operation_id)
  and (b.owner_xid<>pg_current_xact_id() or p.owner_xid<>pg_current_xact_id()) then
  raise exception 'unaccepted recurring parent cannot create phone targets';end if;
 select * into l from public.weekly_schedule_lunch_documents where projection_id=a.projection_id;
 if not found then raise exception 'exact recurring lunch companion is unavailable';end if;
 for person in with people as (
  select (r->>'personId')::uuid employee_id from jsonb_array_elements(b.dependency_snapshot->'roster') r
   where r->>'personId' is not null and extract(isodow from (r->>'serviceDate')::date)=extract(isodow from p_date)
  union
  select (r->>'personId')::uuid from public.static_weekly_recurring_publication_bindings prior
   cross join lateral jsonb_array_elements(prior.dependency_snapshot->'roster') r
   where prior.publication_id=b.predecessor_publication_id and r->>'personId' is not null
    and extract(isodow from (r->>'serviceDate')::date)=extract(isodow from p_date)
  union
  select x.owner_person_id_snapshot from public.weekly_schedule_occurrences x
   join public.weekly_schedule_compiled_projections projection using(projection_id)
   where projection.publication_id in (a.publication_id,b.predecessor_publication_id) and x.service_date=p_date
    and x.owner_person_id_snapshot is not null
  union
  select (r->>'normal_owner_person_id')::uuid from public.weekly_schedule_lunch_documents lunch
   join public.weekly_schedule_compiled_projections projection using(projection_id)
   cross join lateral jsonb_array_elements(lunch.document_json->'responsibilities') r
   where projection.publication_id in (a.publication_id,b.predecessor_publication_id)
    and r->>'service_date'=p_date::text and r->>'normal_owner_person_id' is not null
  union
  select (r->>'coverer_person_id')::uuid from public.weekly_schedule_lunch_documents lunch
   join public.weekly_schedule_compiled_projections projection using(projection_id)
   cross join lateral jsonb_array_elements(lunch.document_json->'responsibilities') r
   where projection.publication_id in (a.publication_id,b.predecessor_publication_id)
    and r->>'service_date'=p_date::text and r->>'coverer_person_id' is not null
 ) select distinct people.employee_id from people join public.employees e on e.id=people.employee_id order by people.employee_id loop
  v_view:=public.static_weekly_v22_recurring_render_view(a.projection_id,p_date,person.employee_id);
  v_view_digest:=public.static_weekly_digest_jsonb(v_view);v_devices:=0;
  -- Rotation/reconnect must not silently create a different view at the same
  -- authority identity, nor make ON CONFLICT hide changed display bytes.
  if exists(select 1 from public.static_weekly_recurring_application_intents i
   where i.publication_id=a.publication_id and i.projection_id=a.projection_id
    and i.service_date=p_date and i.employee_id=person.employee_id
    and i.authority_revision=a.projection_authority_revision
    and (i.view_json is distinct from v_view or i.view_digest is distinct from v_view_digest
      or i.lunch_document_identity is distinct from l.document_identity)) then
   raise exception using errcode='23514',message='recurring render changed without a new exact authority identity';end if;
  for device in select d.id,c.credential_id,d.assignment_epoch from public.devices d
   join public.device_auth_credentials c on c.device_id=d.id and c.confirmed_at is not null
    and c.revoked_at is null and c.expires_at>statement_timestamp()
   where d.active=true and d.assigned_employee_id=person.employee_id
   order by d.id,c.credential_id loop
   v_devices:=v_devices+1;
   v_target:=jsonb_build_object('schema','static-weekly.recurring-application-target.v1','targetType','SCHEDULE',
    'operationId',b.operation_id,'publicationId',a.publication_id,'projectionId',a.projection_id,'serviceDate',p_date,
    'authorityRevision',a.projection_authority_revision,'lunchDocumentIdentity',l.document_identity,
    'employeeId',person.employee_id,'deviceId',device.id,'credentialId',device.credential_id,
    'assignmentEpoch',device.assignment_epoch,'viewDigest',v_view_digest);
   insert into public.static_weekly_recurring_application_intents(operation_id,publication_id,projection_id,service_date,
    employee_id,device_id,credential_id,assignment_epoch,authority_revision,lunch_document_identity,view_json,view_digest,target_json,target_digest)
   values(b.operation_id,a.publication_id,a.projection_id,p_date,person.employee_id,device.id,device.credential_id,
    device.assignment_epoch,a.projection_authority_revision,l.document_identity,v_view,v_view_digest,v_target,public.static_weekly_digest_jsonb(v_target))
   on conflict do nothing returning intent_id into v_intent;
   if found then v_count:=v_count+1;end if;
  end loop;
  if v_devices=0 then
   v_target:=jsonb_build_object('schema','static-weekly.recurring-application-target.v1','targetType','SCHEDULE',
    'operationId',b.operation_id,'publicationId',a.publication_id,'projectionId',a.projection_id,'serviceDate',p_date,
    'authorityRevision',a.projection_authority_revision,'lunchDocumentIdentity',l.document_identity,
    'employeeId',person.employee_id,'deviceId',null,'credentialId',null,'assignmentEpoch',null,'viewDigest',v_view_digest);
   insert into public.static_weekly_recurring_application_intents(operation_id,publication_id,projection_id,service_date,
    employee_id,authority_revision,lunch_document_identity,view_json,view_digest,target_json,target_digest)
   values(b.operation_id,a.publication_id,a.projection_id,p_date,person.employee_id,a.projection_authority_revision,
    l.document_identity,v_view,v_view_digest,v_target,public.static_weekly_digest_jsonb(v_target))
   on conflict do nothing returning intent_id into v_intent;
   if found then v_count:=v_count+1;end if;
  end if;
 end loop;
 return v_count;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v22_recurring_render_view(p_projection uuid, p_date date, p_employee uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a record;d jsonb;
begin
 if p_date is null or not isfinite(p_date) or p_projection is null or p_employee is null then raise exception 'exact recurring render principal date and projection required';end if;
 select * into a from public.static_weekly_v6_schedule_authority_state(p_date);
 if a.projection_status is distinct from 'current' or a.projection_id is distinct from p_projection then
  raise exception using errcode='23514',message='recurring view requires the exact current usable projection';end if;
 d:=public.static_weekly_v5_read_employee_day(p_date,p_employee,(p_date::timestamp+interval '12 hours') at time zone 'America/Chicago');
 if d->>'projection_status' is distinct from 'current' or d->>'projection_id' is distinct from p_projection::text
  or d->>'employee_id' is distinct from p_employee::text or d->>'service_date' is distinct from p_date::text
  or jsonb_typeof(d->'all_items') is distinct from 'array' then
  raise exception using errcode='23514',message='recurring full-day render source is unavailable';end if;
 return jsonb_build_object('schema','static-weekly.recurring-render-view.v1','service_date',p_date,
  'employee_id',p_employee,'employee_name',d->'employee_name','publication_id',a.publication_id,
  'projection_id',p_projection,'projection_status','current','full_day',true,
  'shift',d->'shift','raw_items',d->'all_items');
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v23_finalize_recurring_confirmation(p_manager uuid, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare p public.static_weekly_recurring_confirmations%rowtype;b public.static_weekly_recurring_publication_bindings%rowtype;
 r public.static_weekly_recurring_confirmation_receipts%rowtype;l public.weekly_schedule_lunch_documents%rowtype;
 a record;day_authority record;v_revision bigint;v_generation bigint;v_day date;v_manifest jsonb;v_receipt jsonb;v_count integer;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 perform public.static_weekly_v3_manager_actor(p_manager);
 select * into p from public.static_weekly_recurring_confirmations where manager_id=p_manager and confirmation_key=p_key for update;
 if not found then raise exception 'recurring finalizer requires exact named-manager parent';end if;
 select * into r from public.static_weekly_recurring_confirmation_receipts where operation_id=p.operation_id;
 if found then return r.receipt_json;end if; -- immutable history before current staleness
 if p.owner_xid<>pg_current_xact_id() or p.effective_start<=public.sch_service_date(statement_timestamp()) then
  raise exception 'recurring finalizer requires this transaction and future effective Monday';end if;
 select * into b from public.static_weekly_recurring_publication_bindings where operation_id=p.operation_id;
 select generation into strict v_generation from public.static_weekly_recurring_generation where singleton;
 select current_revision into strict v_revision from public.static_weekly_schedule_control where singleton;
 if b.operation_id is null or b.owner_xid<>pg_current_xact_id() or b.recurring_generation<>v_generation
  or b.decision_digest<>public.static_weekly_digest_jsonb(b.decision_json)
  or b.dependency_digest<>public.static_weekly_digest_jsonb(b.dependency_snapshot)
  or public.static_weekly_v21_first_changed_dependency_date(b.publication_id,p.effective_start) is not null then
  raise exception using errcode='40001',message='recurring finalization dependency or decision changed';end if;
 select * into a from public.static_weekly_v6_schedule_authority_state(p.effective_start);
 if a.projection_status is distinct from 'current' or a.publication_id is distinct from b.publication_id
  or a.projection_id is null or a.projection_authority_revision is distinct from v_revision then
  raise exception 'recurring finalization requires exact current projection and revision';end if;
 if not exists(select 1 from public.weekly_schedule_command_receipts c
  join public.weekly_schedule_publications publication on publication.publication_id=b.publication_id
  where c.actor_manager_id=p_manager and c.command_type='materialize_projection'
   and c.idempotency_key='recurring:'||p_manager||':'||p_key||':projection:'||p.effective_start
   and c.response_json#>>'{data,projection_id}'=a.projection_id::text
   and (c.response_json->>'revision')::bigint=v_revision
   and c.expected_revision=publication.authority_revision
   and c.response_digest=c.response_json->>'output_digest'
   and c.response_digest=public.static_weekly_digest_jsonb(c.response_json-'output_digest')) then
  raise exception 'recurring finalization requires its exact projection child receipt';end if;
 select * into l from public.weekly_schedule_lunch_documents where projection_id=a.projection_id;
 if not found or l.accepted_by_manager_id is distinct from p_manager then
  raise exception 'recurring finalization requires its exact named-manager lunch companion';end if;
 -- The complete initial week is materialized atomically. The ongoing bounded
 -- reconciliation path must separately populate future materialized weeks.
 for v_day in select p.effective_start+offset_day from generate_series(0,6) offset_day loop
  select * into day_authority from public.static_weekly_v6_schedule_authority_state(v_day);
  if day_authority.projection_status is distinct from 'current' or day_authority.publication_id is distinct from b.publication_id
   or day_authority.projection_id is distinct from a.projection_id or day_authority.projection_authority_revision is distinct from v_revision then
   raise exception 'recurring finalization week contains a different or blocked authority';end if;
  perform public.static_weekly_v22_reconcile_recurring_application_date(v_day);
 end loop;
 select jsonb_agg(jsonb_build_object('intentId',i.intent_id,'serviceDate',i.service_date,
  'employeeId',i.employee_id,'deviceId',i.device_id,'credentialId',i.credential_id,'assignmentEpoch',i.assignment_epoch,
  'targetDigest',i.target_digest,'viewDigest',i.view_digest) order by i.service_date,i.employee_id,i.device_id nulls first,i.credential_id nulls first,i.intent_id),
  count(distinct i.service_date)::int into v_manifest,v_count
 from public.static_weekly_recurring_application_intents i
 where i.operation_id=p.operation_id and i.publication_id=b.publication_id and i.projection_id=a.projection_id
  and i.authority_revision=v_revision and i.service_date between p.effective_start and p.effective_start+6;
 if v_manifest is null or v_count<>7 then raise exception 'recurring finalization requires complete durable initial-week phone targets';end if;
 insert into public.static_weekly_recurring_acceptance_proofs(operation_id,publication_id,projection_id,accepted_revision,
  decision_digest,dependency_digest,target_manifest,target_manifest_digest)
 values(p.operation_id,b.publication_id,a.projection_id,v_revision,b.decision_digest,b.dependency_digest,v_manifest,public.static_weekly_digest_jsonb(v_manifest));
 v_receipt:=jsonb_build_object('schema','static-weekly.recurring-confirmation-receipt.v1',
  'operationId',p.operation_id,'managerId',p.manager_id,'confirmationKey',p.confirmation_key,'requestDigest',p.request_digest,
  'previewDigest',p.preview_digest,'effectiveStart',p.effective_start,'sourceId',b.source_id,'sourceDigest',b.source_digest,
  'publicationId',b.publication_id,'projectionId',a.projection_id,'authorityRevision',v_revision,'lunchDocumentIdentity',l.document_identity,
  'accepted',true,'phoneDeliveryState','PENDING','affectedPhonesUpdated',false);
 insert into public.static_weekly_recurring_confirmation_receipts(operation_id,source_id,source_digest,publication_id,
  projection_id,accepted_revision,lunch_document_identity,receipt_json,receipt_digest)
 values(p.operation_id,b.source_id,b.source_digest,b.publication_id,a.projection_id,v_revision,l.document_identity,v_receipt,
  public.static_weekly_digest_jsonb(v_receipt));
 return v_receipt;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v24_ack_device_schedule_delivery(p_intent uuid, p_device uuid, p_credential uuid, p_employee uuid, p_epoch bigint, p_target_type text, p_revision bigint, p_target_digest text, p_rendered_digest text, p_applied_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare t public.static_weekly_recurring_application_intents%rowtype;
 terminal public.static_weekly_recurring_terminal_intents%rowtype;dated record;v_result jsonb;
begin
 perform public.custodial_begin_application_mutation();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 perform public.static_weekly_v19_assert_terminal_principal(p_device,p_credential,p_employee,p_epoch);
 if not exists(select 1 from public.employees where id=p_employee and active=true) then
  raise exception using errcode='42501',message='schedule delivery requires an active employee principal';end if;
 if p_target_type='BLOCKED_RECURRING_AUTHORITY' then
  select * into terminal from public.static_weekly_recurring_terminal_intents where intent_id=p_intent;
  if not found or p_target_digest is distinct from terminal.target_digest
   or p_rendered_digest is distinct from p_target_digest then
   raise exception using errcode='23514',message='terminal delivery receipt requires exact target bytes';end if;
  v_result:=public.static_weekly_v19_ack_terminal_target(p_intent,p_device,p_credential,p_employee,p_epoch,
   p_revision,p_rendered_digest,p_applied_at);
 elsif p_target_type='SCHEDULE' then
  v_result:=public.static_weekly_v22_ack_recurring_application_target(p_intent,p_device,p_credential,p_employee,p_epoch,
   p_revision,p_target_digest,p_rendered_digest,p_applied_at);
  if exists(select 1 from custodial_coverall.manual_application_intents where intent_id=p_intent) then
   select * into strict t from custodial_coverall.manual_application_intents where intent_id=p_intent;
  else
   select * into strict t from public.static_weekly_recurring_application_intents where intent_id=p_intent;
  end if;
  -- A dated absence/cancellation may use the same current recurring winner.
  -- Preserve its existing manager delivery receipt only for the EXACT same
  -- principal, date, revision, projection and lunch just applied. Caller
  -- supplies no dated operation/intent identity. Old/different targets remain
  -- history; no fabricated ACK on enqueue, provider acceptance or new device.
  for dated in select i.* from public.static_weekly_schedule_application_intents i
   join public.static_weekly_staffing_commands c on c.operation_id=i.operation_id and c.state='ACCEPTED'
   where i.service_date=t.service_date and i.employee_id=t.employee_id and i.device_id=t.device_id
    and i.credential_id=t.credential_id and i.assignment_epoch=t.assignment_epoch
    and i.authority_revision=t.authority_revision and i.publication_id=t.publication_id
    and i.projection_id=t.projection_id and i.lunch_document_identity=t.lunch_document_identity
    and not exists(select 1 from public.static_weekly_schedule_application_receipts r where r.intent_id=i.intent_id)
   order by i.intent_id loop
   perform public.static_weekly_v10_ack_device_schedule_application(dated.intent_id,p_device,p_credential,p_employee,p_epoch,
    p_revision,t.projection_id,t.lunch_document_identity,p_rendered_digest,p_applied_at);
  end loop;
 else raise exception using errcode='22023',message='exact typed schedule delivery receipt required';end if;
 return jsonb_build_object('schema','static-weekly.device-schedule-delivery-receipt.v1','receipt',v_result,
  'currentAuthorityNotInferred',true);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v24_read_device_schedule_delivery(p_date date, p_device uuid, p_credential uuid, p_employee uuid, p_epoch bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a record;v_delivery jsonb;v_dated jsonb;
begin
 if p_date is null or not isfinite(p_date) then raise exception 'schedule delivery requires one finite service date';end if;
 perform public.custodial_begin_application_mutation();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 perform public.static_weekly_v19_assert_terminal_principal(p_device,p_credential,p_employee,p_epoch);
 if not exists(select 1 from public.employees where id=p_employee and active=true) then
  raise exception using errcode='42501',message='schedule delivery requires an active employee principal';end if;
 select * into a from public.static_weekly_v6_schedule_authority_state(p_date);
 if exists(select 1 from custodial_coverall.manual_application_bindings where publication_id=a.publication_id)
  and exists(select 1 from public.static_weekly_recurring_publication_bindings where publication_id=a.publication_id) then raise exception 'Conflicting current manual/recurring origins';end if;
 if a.projection_status='blocked_recurring_authority' then
  -- Terminal wins before any older dated or recurring schedule is considered.
  v_delivery:=public.static_weekly_v19_read_terminal_target(p_date,p_device,p_credential,p_employee,p_epoch);
  if v_delivery->>'intentId' is null then
   perform public.static_weekly_v19_reconcile_terminal_date(p_date);
   v_delivery:=public.static_weekly_v19_read_terminal_target(p_date,p_device,p_credential,p_employee,p_epoch);
  end if;
  return jsonb_build_object('schema','static-weekly.device-schedule-delivery.v1','mode','RECURRING_TERMINAL',
   'delivery',v_delivery,'datedApplication',null,'affectedPhonesUpdated',false);
 end if;
 if exists(select 1 from public.static_weekly_recurring_publication_bindings where publication_id=a.publication_id)
  or exists(select 1 from custodial_coverall.manual_application_bindings where publication_id=a.publication_id) then
  if a.projection_status is distinct from 'current' then
   return jsonb_build_object('schema','static-weekly.device-schedule-delivery.v1','mode','UNAVAILABLE',
    'projectionStatus',a.projection_status,'delivery',null,'datedApplication',null,'affectedPhonesUpdated',false);
  end if;
  v_delivery:=public.static_weekly_v22_read_recurring_application_target(p_date,p_device,p_credential,p_employee,p_epoch);
  if v_delivery->>'intentId' is null then
   -- Reconcile only a missing current identity. Existing immutable views do
   -- not need all-person reconstruction on every connected phone poll.
   perform public.static_weekly_v22_reconcile_recurring_application_date(p_date);
   v_delivery:=public.static_weekly_v22_read_recurring_application_target(p_date,p_device,p_credential,p_employee,p_epoch);
  end if;
  return jsonb_build_object('schema','static-weekly.device-schedule-delivery.v1','mode','RECURRING_SCHEDULE',
   'delivery',v_delivery,'datedApplication',null,'affectedPhonesUpdated',false,
   'authorityOrigin',case when exists(select 1 from custodial_coverall.manual_application_bindings where publication_id=a.publication_id)
    then (select jsonb_build_object('kind','MANUAL_INITIAL','bindingId',operation_id) from custodial_coverall.manual_application_bindings where publication_id=a.publication_id)
    else jsonb_build_object('kind','RECURRING_CONFIRMATION','bindingId',v_delivery#>'{target,operationId}') end);
 end if;
 -- Existing release-registered/dated workflow stays separate. Never use an
 -- old dated target with a different exact current publication/projection.
 v_dated:=public.static_weekly_v10_read_device_schedule_application(p_date,p_device,p_credential,p_employee,p_epoch);
 if a.projection_status is distinct from 'current'
  or v_dated->>'publication_id' is distinct from a.publication_id::text
  or v_dated->>'projection_id' is distinct from a.projection_id::text
  or v_dated->>'authority_revision' is distinct from a.projection_authority_revision::text then v_dated:=null;end if;
 return jsonb_build_object('schema','static-weekly.device-schedule-delivery.v1','mode','LEGACY_REGISTERED',
  'delivery',null,'datedApplication',v_dated,'affectedPhonesUpdated',false);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v26_read_original_delivery_outcome(p_intent uuid, p_target_type text, p_device uuid, p_credential uuid, p_employee uuid, p_epoch bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare intent record;receipt record;expected_render text;
begin
 if p_intent is null or p_target_type is null
  or p_target_type not in ('SCHEDULE','BLOCKED_RECURRING_AUTHORITY')
  or p_epoch is null or p_epoch<1 or p_epoch>9007199254740991 then
  raise exception using errcode='22023',message='exact original delivery identity is required';end if;
 perform public.static_weekly_v19_assert_terminal_principal(p_device,p_credential,p_employee,p_epoch);
 if not exists(select 1 from public.employees where id=p_employee and active=true) then
  raise exception using errcode='42501',message='exact original delivery principal is required';end if;
 if p_target_type='SCHEDULE' then
  select i.intent_id,i.device_id,i.credential_id,i.employee_id,i.assignment_epoch,
   i.authority_revision,i.target_digest,i.view_digest into intent
   from public.static_weekly_recurring_application_intents i where i.intent_id=p_intent;
  if not found then
   raise exception using errcode='42501',message='exact original delivery principal is required';end if;
  expected_render:=intent.view_digest;
  select r.receipt_id,r.rendered_digest,r.applied_at,r.received_at into receipt
   from public.static_weekly_recurring_application_receipts r where r.intent_id=p_intent;
 else
  select i.intent_id,i.device_id,i.credential_id,i.employee_id,i.assignment_epoch,
   i.authority_revision,i.target_digest into intent
   from public.static_weekly_recurring_terminal_intents i where i.intent_id=p_intent;
  if not found then
   raise exception using errcode='42501',message='exact original delivery principal is required';end if;
  expected_render:=intent.target_digest;
  select r.receipt_id,r.rendered_digest,r.applied_at,r.received_at into receipt
   from public.static_weekly_recurring_terminal_receipts r where r.intent_id=p_intent;
 end if;
 if intent.device_id is distinct from p_device or intent.credential_id is distinct from p_credential
  or intent.employee_id is distinct from p_employee or intent.assignment_epoch is distinct from p_epoch then
  raise exception using errcode='42501',message='exact original delivery principal is required';end if;
 if receipt.receipt_id is not null and (receipt.rendered_digest is distinct from expected_render
  or not isfinite(receipt.applied_at) or not isfinite(receipt.received_at)) then
  raise exception using errcode='23514',message='original delivery receipt is inconsistent';end if;
 return jsonb_build_object('schema','static-weekly.original-device-delivery-outcome.v1',
  'intentId',intent.intent_id,'targetType',p_target_type,'authorityRevision',intent.authority_revision,
  'targetDigest',intent.target_digest,'renderedDigest',expected_render,
  'status',case when receipt.receipt_id is null then 'NO_RECORDED_RECEIPT' else 'RECEIPT_RECORDED' end,
  'receiptId',receipt.receipt_id,'appliedAt',receipt.applied_at,'receivedAt',receipt.received_at,
  'retryAuthorized',false,'currentAuthorityNotInferred',true);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v27_ack_device_schedule_delivery(p_plan_read uuid, p_intent uuid, p_device uuid, p_credential uuid, p_employee uuid, p_epoch bigint, p_target_type text, p_revision bigint, p_target_digest text, p_rendered_digest text, p_applied_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare original public.static_weekly_recurring_notification_plan_reads%rowtype;principal jsonb;current_plan jsonb;body jsonb;
 result jsonb;semantic text;at_time timestamptz;until_time timestamptz;locked record;
begin
 perform public.static_weekly_v27_lock_notification_plan_sources();
 principal:=public.static_weekly_v27_notification_plan_backend_principal(p_device,p_credential,p_employee,p_epoch);
 select * into strict original from public.static_weekly_recurring_notification_plan_reads where plan_read_id=p_plan_read;
 if original.intent_id is distinct from p_intent or original.device_id is distinct from p_device
  or original.credential_id is distinct from p_credential or original.employee_id is distinct from p_employee
  or original.assignment_epoch is distinct from p_epoch or original.target_type is distinct from p_target_type
  or original.authority_revision is distinct from p_revision or original.target_digest is distinct from p_target_digest
  or original.rendered_digest is distinct from p_rendered_digest or original.backend_principal is distinct from principal then
  raise exception 'exact issued notification plan read required' using errcode='42501';end if;
 -- A complete normal plan with unavailable original jobs is UI DATA only.
 -- It must never grant the same receipt through a header/token-only caller.
 if original.plan_body->>'schema'='custodial.recurring-current-notification-plan.v2'
  and (original.plan_body#>>'{delivery_bindings,state}' is distinct from 'ORIGINAL_NATIVE_RESERVATIONS'
   or case when jsonb_typeof(original.plan_body#>'{delivery_bindings,entries}')='array'
    then jsonb_array_length(original.plan_body#>'{delivery_bindings,entries}') else 0 end<>jsonb_array_length(original.plan_body->'required_effects')
   or jsonb_array_length(original.plan_body->'required_effects')<1) then
  raise exception 'issued original native bindings unavailable' using errcode='42501';end if;
 at_time:=clock_timestamp();if at_time>=original.valid_until then raise exception 'issued notification plan expired' using errcode='40001';end if;
 current_plan:=public.static_weekly_v27_notification_plan_at(original.service_date,p_device,p_credential,p_employee,p_epoch,p_intent,p_target_digest,at_time);
 body:=current_plan->'body';until_time:=least((body->>'valid_until')::timestamptz,(principal->>'credential_expires_at')::timestamptz);
 body:=jsonb_set(body,'{valid_until}',to_jsonb(public.custodial_native_location_utc(until_time)))
  ||jsonb_build_object('backend_principal_digest',public.static_weekly_digest_jsonb(principal));
 semantic:=public.static_weekly_digest_jsonb(body-'observed_at');
 -- Exact original job selection is separately bound/recompared. A future
 -- semantic-effect refactor must not silently omit native-original custody.
 if (body->'delivery_bindings') is distinct from (original.plan_body->'delivery_bindings')
  or (body->>'schema') is distinct from (original.plan_body->>'schema') then
  raise exception 'issued original native binding changed' using errcode='40001';end if;
 if semantic is distinct from original.semantic_digest or until_time is distinct from original.valid_until then
  raise exception 'issued notification plan source changed' using errcode='40001';end if;
 -- Old writer's explicit row locks and FK key-share probes are pre-admitted
 -- with NOWAIT, including pure row-locking transactions (ROW SHARE table mode).
 -- Source-exclusive prevents new recurring rows; auxiliary SRE prevents new
 -- dated intent/receipt rows. Any pre-existing conflicting row lock refuses.
 if p_target_type='SCHEDULE' then
  if exists(select 1 from custodial_coverall.manual_application_intents where intent_id=p_intent) then
   if exists(select 1 from public.static_weekly_recurring_application_intents where intent_id=p_intent)
    then raise exception 'Ambiguous original manual/recurring intent owner';end if;
  perform 1 from custodial_coverall.manual_application_intents where intent_id=p_intent for share nowait;
  perform 1 from public.weekly_schedule_compiled_projections p
   join custodial_coverall.manual_application_intents i on i.projection_id=p.projection_id
   where i.intent_id=p_intent for share of p nowait;
  for locked in select d.intent_id,d.projection_id
   from public.static_weekly_schedule_application_intents d
   join custodial_coverall.manual_application_intents i on i.intent_id=p_intent
   join public.static_weekly_staffing_commands c on c.operation_id=d.operation_id and c.state='ACCEPTED'
   where d.service_date=i.service_date and d.employee_id=i.employee_id and d.device_id=i.device_id
    and d.credential_id=i.credential_id and d.assignment_epoch=i.assignment_epoch
    and d.authority_revision=i.authority_revision and d.publication_id=i.publication_id
    and d.projection_id=i.projection_id and d.lunch_document_identity=i.lunch_document_identity
    and not exists(select 1 from public.static_weekly_schedule_application_receipts r where r.intent_id=d.intent_id)
   order by d.intent_id for share of d nowait loop
   perform 1 from public.weekly_schedule_compiled_projections where projection_id=locked.projection_id for share nowait;
  end loop;
  else
  perform 1 from public.static_weekly_recurring_application_intents where intent_id=p_intent for share nowait;
  perform 1 from public.weekly_schedule_compiled_projections p
   join public.static_weekly_recurring_application_intents i on i.projection_id=p.projection_id
   where i.intent_id=p_intent for share of p nowait;
  for locked in select d.intent_id,d.projection_id
   from public.static_weekly_schedule_application_intents d
   join public.static_weekly_recurring_application_intents i on i.intent_id=p_intent
   join public.static_weekly_staffing_commands c on c.operation_id=d.operation_id and c.state='ACCEPTED'
   where d.service_date=i.service_date and d.employee_id=i.employee_id and d.device_id=i.device_id
    and d.credential_id=i.credential_id and d.assignment_epoch=i.assignment_epoch
    and d.authority_revision=i.authority_revision and d.publication_id=i.publication_id
    and d.projection_id=i.projection_id and d.lunch_document_identity=i.lunch_document_identity
    and not exists(select 1 from public.static_weekly_schedule_application_receipts r where r.intent_id=d.intent_id)
   order by d.intent_id for share of d nowait loop
   perform 1 from public.weekly_schedule_compiled_projections where projection_id=locked.projection_id for share nowait;
  end loop;
  end if;
 else
  perform 1 from public.static_weekly_recurring_terminal_intents where intent_id=p_intent for share nowait;
 end if;
 result:=public.static_weekly_v24_ack_device_schedule_delivery(p_intent,p_device,p_credential,p_employee,p_epoch,
  p_target_type,p_revision,p_target_digest,p_rendered_digest,p_applied_at);
 -- All sources stay write-fenced until COMMIT. Fresh server time AFTER the
 -- original receipt writer is the final check; a failure rolls back its rows.
 if clock_timestamp()>=original.valid_until then raise exception 'issued notification plan expired during receipt' using errcode='40001';end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v27_issue_recurring_notification_plan(p_date date, p_device uuid, p_credential uuid, p_employee uuid, p_epoch bigint, p_intent uuid, p_target_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare envelope jsonb;body jsonb;principal jsonb;semantic text;wire text;token uuid:=gen_random_uuid();issued timestamptz;until_time timestamptz;
begin
 perform public.static_weekly_v27_lock_notification_plan_sources();
 principal:=public.static_weekly_v27_notification_plan_backend_principal(p_device,p_credential,p_employee,p_epoch);
 issued:=clock_timestamp();
 envelope:=public.static_weekly_v27_notification_plan_at(p_date,p_device,p_credential,p_employee,p_epoch,p_intent,p_target_digest,issued);
 body:=envelope->'body';until_time:=least((body->>'valid_until')::timestamptz,(principal->>'credential_expires_at')::timestamptz);
 body:=jsonb_set(body,'{valid_until}',to_jsonb(public.custodial_native_location_utc(until_time)))
  ||jsonb_build_object('backend_principal_digest',public.static_weekly_digest_jsonb(principal));
 semantic:=public.static_weekly_digest_jsonb(body-'observed_at');
 body:=body||jsonb_build_object('plan_read_id',token,'semantic_digest',semantic);
 if until_time<=clock_timestamp() then raise exception 'normal notification plan expired while issuing' using errcode='40001';end if;
 if (select count(*) from public.static_weekly_recurring_notification_plan_reads where service_date=p_date and credential_id=p_credential)>=16384 then
  raise exception 'normal notification plan daily read bound exceeded' using errcode='54000';end if;
 insert into public.static_weekly_recurring_notification_plan_reads(plan_read_id,service_date,device_id,credential_id,employee_id,assignment_epoch,
  intent_id,target_type,authority_revision,target_digest,rendered_digest,backend_principal,semantic_digest,plan_body,issued_at,valid_until)
 values(token,p_date,p_device,p_credential,p_employee,p_epoch,p_intent,body#>>'{target,targetType}',(body#>>'{target,authorityRevision}')::bigint,
  p_target_digest,body->>'rendered_digest',principal,semantic,body,issued,until_time);
 if until_time<=clock_timestamp() then raise exception 'normal notification plan expired while retaining' using errcode='40001';end if;
 wire:=body::text;return jsonb_build_object('schema',case body->>'schema' when 'custodial.recurring-current-notification-plan.v2' then 'custodial.recurring-current-notification-plan-envelope.v2' else 'custodial.recurring-current-notification-plan-envelope.v1' end,
  'body',body,'bodyJsonText',wire,'bodyDigest',public.static_weekly_digest_text(wire));
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v27_notification_plan_at(p_date date, p_device uuid, p_credential uuid, p_employee uuid, p_epoch bigint, p_intent uuid, p_target_digest text, p_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
 at_time timestamptz:=p_at; delivery jsonb; target jsonb; a record;
 doc public.weekly_schedule_lunch_documents%rowtype; projection public.weekly_schedule_compiled_projections%rowtype;
 device public.devices%rowtype; person public.employees%rowtype; roster public.daily_work_roster%rowtype;
 n jsonb; loan jsonb; mapped jsonb; availability jsonb; candidate record; item jsonb;
 all_intents jsonb:='[]'; effects jsonb:='[]'; audio jsonb:='[]';
 expected jsonb; body jsonb; wire text; notification_state jsonb;
 scheduled timestamptz; ends_at timestamptz; expires timestamptz; boundary timestamptz;
 matches integer; total_intents integer:=0; total_locations integer:=0;
 role_name text; override_enabled boolean; silent boolean; reason text; kind text;
begin
 if at_time is null or not isfinite(at_time) or p_date is null or p_date is distinct from public.sch_service_date(at_time)
  or p_intent is null or coalesce(p_target_digest,'')!~'^[a-f0-9]{64}$'
  or p_epoch is null or p_epoch<1 or p_epoch>9007199254740991 then
  raise exception 'exact current recurring notification plan principal required' using errcode='22023';end if;
 perform public.static_weekly_v19_assert_terminal_principal(p_device,p_credential,p_employee,p_epoch);
 select * into strict device from public.devices where id=p_device;
 select * into strict person from public.employees where id=p_employee and active=true;
 if not exists(select 1 from public.device_auth_credentials c where c.credential_id=p_credential and c.device_id=p_device
  and c.confirmed_at is not null and c.revoked_at is null and c.expires_at>at_time) then
  raise exception 'current notification plan credential expired' using errcode='42501';end if;
 delivery:=public.static_weekly_v22_read_recurring_application_target(p_date,p_device,p_credential,p_employee,p_epoch);
 target:=delivery->'target';
 if delivery->>'intentId' is distinct from p_intent::text or delivery->>'targetDigest' is distinct from p_target_digest
  or target->>'serviceDate' is distinct from p_date::text then
  raise exception 'recurring notification plan target superseded' using errcode='40001';end if;
 expires:=((p_date+1)::timestamp+make_interval(hours=>public.get_setting_int('operational_day_start_hour',4))) at time zone 'America/Chicago';
 select * into strict a from public.static_weekly_v6_schedule_authority_state(p_date);
 if target->>'targetType'='BLOCKED_RECURRING_AUTHORITY' then
  if a.projection_status is distinct from 'blocked_recurring_authority' then
   raise exception 'terminal notification plan authority differs' using errcode='40001';end if;
  kind:='AUTHENTICATED_BLOCKED_TARGET';
 elsif target->>'targetType'='SCHEDULE' then
  if a.projection_status is distinct from 'current' or a.projection_id::text is distinct from target->>'projectionId'
   or a.publication_id::text is distinct from target->>'publicationId'
   or a.projection_authority_revision::text is distinct from target->>'authorityRevision' then
   raise exception 'notification plan accepted authority differs' using errcode='40001';end if;
  select * into strict doc from public.weekly_schedule_lunch_documents where projection_id=a.projection_id;
  select * into strict projection from public.weekly_schedule_compiled_projections where projection_id=a.projection_id;
  if doc.document_identity is distinct from target->>'lunchDocumentIdentity' then
   raise exception 'notification plan lunch companion differs' using errcode='23514';end if;
  if jsonb_array_length(doc.document_json->'notification_intents')>16384
   or jsonb_array_length(doc.document_json->'responsibilities')>16384 then
   raise exception 'complete notification plan source bound exceeded' using errcode='54000';end if;
  perform custodial_coverall.require_lunch_admission_proof(doc.projection_id,doc.document_json);
  -- Exactly the normal device notification shift/override policy. A mapping
  -- role is observed from the same active normal device-user source, not from
  -- caller metadata or an inferred employee label.
  select lower(coalesce(mu.role,'')) into role_name from public.msg_device_assignments mda
   join public.msg_users mu on mu.id=mda.msg_user_id
   where mda.device_identifier=device.device_id and mda.is_active=true and mu.is_active=true
   order by mda.updated_at desc nulls last,mda.created_at desc nulls last limit 1;
  select * into roster from public.daily_work_roster r where r.service_date=p_date and r.employee_id=p_employee and r.active=true
   order by r.updated_at desc nulls last,r.created_at desc nulls last limit 1;
  select coalesce(setting_value='true'::jsonb,false) into override_enabled from public.system_settings
   where setting_key='off_shift_employee_notifications_override_enabled';
  override_enabled:=coalesce(override_enabled,false);
  if coalesce(role_name,'') in ('manager','bot','ops','ops_manager','operations_manager') then silent:=false;reason:='not_employee_device';
  elsif override_enabled then silent:=false;reason:='admin_overtime_override_enabled';
  elsif roster.id is null then silent:=true;reason:='no_active_roster_shift';
  elsif roster.shift_start is null or roster.shift_end is null then silent:=true;reason:='invalid_roster_shift_window';
  elsif (at_time at time zone 'America/Chicago') < p_date+roster.shift_start then silent:=true;reason:='scheduled_shift_not_started';
  elsif (at_time at time zone 'America/Chicago') >= p_date+roster.shift_end then silent:=true;reason:='scheduled_shift_ended';
  else silent:=false;reason:='on_shift';end if;
  notification_state:=jsonb_build_object('notifications_silent',silent,'silent_reason',reason,'override_enabled',override_enabled);
  foreach boundary in array array[(p_date+roster.shift_start) at time zone 'America/Chicago',(p_date+roster.shift_end) at time zone 'America/Chicago'] loop
   if boundary>at_time then expires:=least(expires,boundary);end if;
  end loop;
  -- Validate the whole accepted document before selecting this recipient. No
  -- truncated page or pre-existing job list can hide a required accepted intent.
  for n in select ni.value from jsonb_array_elements(doc.document_json->'notification_intents') ni(value)
   where ni.value->>'service_date'=p_date::text and exists(
    select 1 from jsonb_array_elements(doc.document_json->'responsibilities') rr(value)
     where rr.value->>'loan_id'=ni.value->>'loan_id' and rr.value->>'coverer_slot_id'=ni.value->>'coverer_slot_id'
      and rr.value->>'coverer_person_id'=p_employee::text)
   order by ni.value->>'scheduled_time',ni.value->>'notification_key' loop
   total_intents:=total_intents+1;if total_intents>1024 then raise exception 'complete notification plan bound exceeded' using errcode='54000';end if;
   select value into strict loan from jsonb_array_elements(doc.document_json->'loans') value
    where value->>'loan_id'=n->>'loan_id' and value->>'status'='PLANNED';
   select count(*) into matches from jsonb_array_elements(projection.projection_envelope#>'{authority,projectionAvailability}') value
    where value->>'serviceDate'=p_date::text and value->>'slotId'=n->>'coverer_slot_id'
     and value->>'incumbentPersonId'=p_employee::text and value->>'status'='working';
   if matches<>1 then raise exception 'notification plan recipient availability ambiguous' using errcode='23514';end if;
   select value into strict availability from jsonb_array_elements(projection.projection_envelope#>'{authority,projectionAvailability}') value
    where value->>'serviceDate'=p_date::text and value->>'slotId'=n->>'coverer_slot_id'
     and value->>'incumbentPersonId'=p_employee::text and value->>'status'='working';
   scheduled:=(p_date+(n->>'scheduled_time')::time) at time zone 'America/Chicago';
   ends_at:=(p_date+(case when n->>'event'='start' then loan->>'coverage_end' else availability#>>'{shift,end}' end)::time) at time zone 'America/Chicago';
   if ends_at is null or ends_at<=scheduled or n->>'event' not in ('start','end') then
    raise exception 'notification plan accepted interval unsupported' using errcode='23514';end if;
   if scheduled>at_time then expires:=least(expires,scheduled);end if;
   if ends_at>at_time then expires:=least(expires,ends_at);end if;
   all_intents:=all_intents||jsonb_build_array(jsonb_build_object('intent',n,'valid_from',public.custodial_native_location_utc(scheduled),
    'valid_until',public.custodial_native_location_utc(ends_at)));
   if not silent and scheduled<=at_time and at_time<ends_at and not exists(
    select 1 from public.device_notification_acknowledgements ack where upper(btrim(ack.device_identifier))=upper(btrim(device.device_id))
     and ack.notification_key=n->>'notification_key' and ack.credential_id=p_credential and ack.assignment_epoch=p_epoch
     and ack.employee_id=p_employee and ack.acknowledged_at is not null) then
    expected:=jsonb_build_object('kind','employee_lunch_coverage','notification_type','lunch_coverage',
     'notification_key',n->>'notification_key','service_date',p_date,'loan_id',n->>'loan_id','event',n->>'event',
     'scheduled_time',n->>'scheduled_time','scheduled_at',public.custodial_native_location_utc(scheduled),
     'valid_until',public.custodial_native_location_utc(ends_at),'coverer_slot_id',n->>'coverer_slot_id',
     'projection_id',a.projection_id,'document_identity',doc.document_identity,
     'receipt_employee_id',p_employee,'receipt_credential_id',p_credential,'receipt_device_id',device.device_id,'receipt_assignment_epoch',p_epoch::text,
     'route','employee-schedule.html?hub=employee');
    item:=jsonb_build_object('origin','FULL_ACCEPTED_LUNCH_DOCUMENT','notification_key',n->>'notification_key',
     'notification',jsonb_build_object('title',case n->>'event' when 'start' then 'Lunch coverage starts now' else 'Lunch coverage ended' end,
      'body',public.custodial_native_lunch_spoken_body(a.projection_id,doc.document_identity,n->>'loan_id',p_employee,n->>'event'),
      'data',expected),'required_audio',true);
    effects:=effects||jsonb_build_array(item);audio:=audio||jsonb_build_array(n->>'notification_key');
   end if;
  end loop;
  -- The same normal operational assignment + cycle source as the reminder
  -- route, but exhaustive for this exact employee/current accepted projection.
  -- No LIMIT: overflow refuses the WHOLE observation instead of empty/subset.
  for candidate in
   select distinct on (assignment.location_id) assignment.*,cycle.notification_key as cycle_key,
    cycle.status_code,cycle.due_soon_at,cycle.overdue_at
   from public.custodial_operational_location_assignments(p_date) assignment
   left join public.mz_location_reminder_candidates(p_date,at_time) cycle on cycle.location_id=assignment.location_id
   where assignment.assigned_employee_id=p_employee and assignment.assignment_status='ASSIGNED'
    and assignment.projection_status='current' and assignment.projection_id=a.projection_id
    and assignment.coverage_start <= (at_time at time zone 'America/Chicago')::time
    and (at_time at time zone 'America/Chicago')::time < assignment.coverage_end
   order by assignment.location_id,assignment.coverage_start,assignment.group_name,assignment.group_code loop
   total_locations:=total_locations+1;if total_locations>1024 then raise exception 'complete notification plan bound exceeded' using errcode='54000';end if;
   boundary:=(p_date+candidate.coverage_end) at time zone 'America/Chicago';if boundary>at_time then expires:=least(expires,boundary);end if;
   if candidate.due_soon_at>at_time then expires:=least(expires,candidate.due_soon_at);end if;
   if candidate.overdue_at>at_time then expires:=least(expires,candidate.overdue_at);end if;
   if not silent and candidate.status_code in ('due_soon','overdue') and not exists(
    select 1 from public.device_notification_acknowledgements ack where upper(btrim(ack.device_identifier))=upper(btrim(device.device_id))
     and ack.notification_key=candidate.cycle_key||':projection:'||a.projection_id::text and ack.credential_id=p_credential
     and ack.assignment_epoch=p_epoch and ack.employee_id=p_employee and ack.acknowledged_at is not null) then
    expected:=jsonb_build_object('kind','employee_location_status','notification_type','location_status',
     'notification_key',candidate.cycle_key||':projection:'||a.projection_id::text,'service_date',p_date,
     'device_id',device.device_id,'employee_id',p_employee,'employee_name',person.display_name,
     'projection_id',a.projection_id,'publication_id',a.publication_id,'schedule_authority_revision',a.projection_authority_revision::text,
     'location_id',candidate.location_id,'location_code',candidate.location_code,'location_name',candidate.location_name,
     'group_code',candidate.group_code,'group_name',candidate.group_name,'form_type',candidate.form_type,'status_code',candidate.status_code,
     'receipt_employee_id',p_employee,'receipt_credential_id',p_credential,'receipt_device_id',device.device_id,'receipt_assignment_epoch',p_epoch::text);
    effects:=effects||jsonb_build_array(jsonb_build_object('origin','EXHAUSTIVE_NORMAL_CURRENT_LOCATION_CYCLES',
     'notification_key',expected->>'notification_key','data',expected,'required_audio',true));
    audio:=audio||jsonb_build_array(expected->>'notification_key');
   end if;
  end loop;
  -- The ordinary candidate function omits not-yet-due rows. Sample the SAME
  -- underlying verified normal cycle for expiry only, so empty coverage cannot
  -- cross a first due threshold or the existing five-minute overdue repeat.
  select min(b.x) into boundary from public.custodial_operational_location_assignments(p_date) assignment
   join public.v_location_dashboard_status status on status.location_id=assignment.location_id
   cross join lateral public.mz_verified_location_reminder_cycle(status.location_id,status.form_type,status.latest_completed_at,
    public.mz_latest_verified_check(status.location_id,status.operational_day_start,at_time),at_time) cycle
   cross join lateral (values (cycle.due_soon_at),(cycle.overdue_at),
    (case when cycle.overdue_at<=at_time then cycle.overdue_at+make_interval(secs=>((cycle.repeat_index+1)*300)::double precision) else null end)) b(x)
   where assignment.assigned_employee_id=p_employee and assignment.assignment_status='ASSIGNED'
    and assignment.projection_status='current' and assignment.projection_id=a.projection_id
    and status.latest_completed_at>=status.operational_day_start and b.x>at_time;
  if boundary is not null then expires:=least(expires,boundary);end if;
  -- Include ALL future normal assignment boundaries, including locations not
  -- active in the loop above. Otherwise a currently-empty plan could outlive
  -- the next accepted work window and pretend no future transition exists.
  select min(x) into boundary from public.custodial_operational_location_assignments(p_date) assignment
   cross join lateral (values ((p_date+assignment.coverage_start) at time zone 'America/Chicago'),
    ((p_date+assignment.coverage_end) at time zone 'America/Chicago')) b(x)
   where assignment.assigned_employee_id=p_employee and assignment.assignment_status='ASSIGNED'
    and assignment.projection_status='current' and assignment.projection_id=a.projection_id and x>at_time;
  if boundary is not null then expires:=least(expires,boundary);end if;
  kind:='FULL_ACCEPTED_LUNCH_AND_EXHAUSTIVE_CURRENT_LOCATION_DERIVATION';
 else raise exception 'unsupported recurring notification plan target' using errcode='22023';end if;
 if expires<=at_time or jsonb_array_length(effects)>1024 then raise exception 'complete notification plan time/bound unsupported' using errcode='54000';end if;
 body:=jsonb_build_object('schema','custodial.recurring-current-notification-plan.v1','complete',true,'receipt_eligible',false,
  'scope','CURRENT_PRESENTATION_AND_FULL_EFFECTS_REQUIRED_BY_ACCEPTED_TARGET_NOT_FUTURE_ALARM_INVENTORY',
  'source',kind,'service_date',p_date,'intent_id',p_intent,'target_digest',p_target_digest,'target',target,
  'rendered_digest',case when target->>'targetType'='SCHEDULE' then target->>'viewDigest' else p_target_digest end,
  'device_pk',p_device,'canonical_device_id',device.device_id,'employee_id',p_employee,'credential_id',p_credential,'assignment_epoch',p_epoch::text,
  'observed_at',public.custodial_native_location_utc(at_time),'valid_until',public.custodial_native_location_utc(expires),
  'notification_state',coalesce(notification_state,jsonb_build_object('notifications_silent',true,'silent_reason','blocked_recurring_authority','override_enabled',false)),
  'accepted_lunch_intents',all_intents,'required_effects',effects,'required_audio',audio,
  'source_counts',jsonb_build_object('accepted_lunch_intents',total_intents,'current_assigned_locations',total_locations));
 -- EMPTY/BLOCKED v1 stays byte-contract compatible. Nonempty v2 MUST carry
 -- an explicit original-binding state; missing history is never empty proof.
 if jsonb_array_length(effects)>0 then
  body:=body||jsonb_build_object('schema','custodial.recurring-current-notification-plan.v2',
   'delivery_bindings',public.static_weekly_v27_original_native_bindings(body,at_time));
  if body#>>'{delivery_bindings,state}'='ORIGINAL_NATIVE_RESERVATIONS' then
   select min((value->>'valid_until')::timestamptz) into boundary
    from jsonb_array_elements(body#>'{delivery_bindings,entries}');
   expires:=least(expires,boundary);
   body:=jsonb_set(body,'{valid_until}',to_jsonb(public.custodial_native_location_utc(expires)));
  end if;
 end if;
 wire:=body::text;if octet_length(wire)>196608 then raise exception 'complete notification plan byte bound exceeded' using errcode='54000';end if;
 return jsonb_build_object('schema',case body->>'schema' when 'custodial.recurring-current-notification-plan.v2' then 'custodial.recurring-current-notification-plan-envelope.v2' else 'custodial.recurring-current-notification-plan-envelope.v1' end,'body',body,
  'bodyJsonText',wire,'bodyDigest',public.static_weekly_digest_text(wire));
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v27_notification_plan_backend_principal(p_device uuid, p_credential uuid, p_employee uuid, p_epoch bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare d public.devices%rowtype;c public.device_auth_credentials%rowtype;e public.employees%rowtype;
begin
 select * into strict d from public.devices where id=p_device for share nowait;
 select * into strict c from public.device_auth_credentials where credential_id=p_credential for share nowait;
 select * into strict e from public.employees where id=p_employee for share nowait;
 if d.active is not true or e.active is not true or d.assigned_employee_id is distinct from p_employee
  or d.assignment_epoch is distinct from p_epoch or c.device_id is distinct from p_device
  or c.confirmed_at is null or c.revoked_at is not null or c.expires_at<=clock_timestamp() then
  raise exception 'current notification plan backend principal required' using errcode='42501';end if;
 return jsonb_build_object('binding_scope','EXACT_BACKEND_CREDENTIAL_DEVICE_EMPLOYEE_EPOCH_CONFIRMATION_NOT_NATIVE_INSTALLATION_IDENTITY',
  'device_pk',d.id,'canonical_device_id',d.device_id,'employee_id',e.id,'credential_id',c.credential_id,'assignment_epoch',d.assignment_epoch::text,
  'credential_created_at',c.created_at,'credential_confirmed_at',c.confirmed_at,'credential_expires_at',c.expires_at,
  'credential_metadata_digest',public.static_weekly_digest_jsonb(c.metadata_json));
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v27_read_home_time_facts(p_date date, p_employee uuid, p_publication uuid, p_projection uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare rec jsonb:=public.custodial_dated_record(p_date);roster jsonb;working boolean;
begin
 if p_date is null or p_employee is null or p_publication is null or p_projection is null then return null;end if;
 if rec is null or rec->>'projectionStatus'<>'current' or rec->>'publicationId'<>p_publication::text or rec->>'projectionId'<>p_projection::text then return null;end if;
 select r into roster from jsonb_array_elements(public.custodial_dated_rows('roster',p_date)) r where r->>'employee_id'=p_employee::text;
 if roster is null then return null;end if;working:=roster->>'active'='true';
 return jsonb_build_object('contract_version','employee-home-time-facts.v1','service_date',p_date,'employee_id',p_employee,
  'employee_name',roster->>'employee_name','projection_status','current','projection_id',p_projection,'publication_id',p_publication,
  'candidate_revision',rec->>'phonePdfRevision','source','static_weekly_projection','reason',null,
  'schedule_status',case when working then 'scheduled' else 'off' end,
  'shift',case when working then jsonb_build_object('active',true,'start',roster->>'shift_start','end',roster->>'shift_end',
   'shift_start',roster->>'shift_start','shift_end',roster->>'shift_end','lunch_start',roster->>'lunch_start','lunch_end',roster->>'lunch_end') else jsonb_build_object('active',false) end,
  'lunch',case when working then jsonb_build_object('start',roster->>'lunch_start','end',roster->>'lunch_end') else null end);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v2_apply_exception(p_exception_type text, p_service_date date, p_starts_at time without time zone, p_ends_at time without time zone, p_base_version_id uuid, p_publication_id uuid, p_reason text, p_payload jsonb, p_expected_revision bigint, p_actor_manager_id uuid, p_actor_manager_name text, p_idempotency_key text, p_reverses_exception_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_request jsonb; v_request_digest text; v_prior public.weekly_schedule_command_receipts%rowtype; v_command uuid:=gen_random_uuid(); v_exception uuid:=gen_random_uuid(); v_payload jsonb:=coalesce(p_payload,'{}'::jsonb); v_payload_digest text; v_revision bigint; v_response jsonb; v_target public.weekly_schedule_exception_commands%rowtype; v_operation text;
begin
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_actor_manager_id,p_actor_manager_name,p_idempotency_key,'apply_exception');
  v_request:=jsonb_build_object('operation','apply_exception','exception_type',p_exception_type,'service_date',p_service_date,'starts_at',p_starts_at,'ends_at',p_ends_at,'base_version_id',p_base_version_id,'publication_id',p_publication_id,'reason',p_reason,'payload',v_payload,'expected_revision',p_expected_revision,'actor_manager_id',p_actor_manager_id,'actor_manager_name',p_actor_manager_name,'reverses_exception_id',p_reverses_exception_id); v_request_digest:=public.static_weekly_digest_jsonb(v_request); perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts where actor_manager_id=p_actor_manager_id and idempotency_key=p_idempotency_key; if found then if v_prior.request_digest<>v_request_digest then raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs'; end if; return v_prior.response_json; end if;
  if p_exception_type is null or p_exception_type not in ('pto','daily_absence','partial_absence','shift_override','cover_all','lunch','nine_forty_five_rebalance','event_impact','manager_correction','reverse') or p_service_date is null or p_base_version_id is null or p_publication_id is null or btrim(coalesce(p_reason,''))='' or jsonb_typeof(p_payload) is distinct from 'object' or ((p_starts_at is null)<>(p_ends_at is null)) or (p_starts_at is not null and p_starts_at>=p_ends_at) then raise exception using errcode='23514',message='complete exception semantic inputs are required'; end if;
  if not exists(select 1 from public.weekly_schedule_publications where publication_id=p_publication_id and version_id=p_base_version_id) or public.static_weekly_effective_version(p_service_date) is distinct from p_base_version_id then raise exception using errcode='23514',message='exception must bind its effective publication and version'; end if;
  if (p_exception_type='reverse') is distinct from (p_reverses_exception_id is not null) then raise exception using errcode='23514',message='reversal target coherence is required'; end if;
  perform public.static_weekly_assert_exception_payload(p_exception_type,p_service_date,p_starts_at,p_ends_at,p_base_version_id,p_publication_id,v_payload,p_reverses_exception_id);
  if p_exception_type='reverse' then select * into v_target from public.weekly_schedule_exception_commands where exception_id=p_reverses_exception_id; if not found or v_target.exception_type='reverse' or v_target.service_date is distinct from p_service_date or v_target.base_version_id is distinct from p_base_version_id or v_target.publication_id is distinct from p_publication_id or exists(select 1 from public.weekly_schedule_exception_commands where reverses_exception_id=p_reverses_exception_id) then raise exception using errcode='23514',message='reversal must target one compatible unreversed exception'; end if; end if;
  v_payload_digest:=public.static_weekly_digest_jsonb(v_payload); v_operation:=case when p_exception_type='reverse' then 'reverse_exception' else 'apply_exception' end; v_revision:=public.static_weekly_advance_authority(p_expected_revision,v_operation,p_actor_manager_id,p_actor_manager_name,v_command,v_payload_digest);
  insert into public.weekly_schedule_exception_commands(exception_id,authority_revision,exception_type,service_date,starts_at,ends_at,base_version_id,publication_id,reverses_exception_id,expected_revision,idempotency_key,actor_manager_id,actor_manager_name_snapshot,reason,payload_json,payload_digest) values(v_exception,v_revision,p_exception_type,p_service_date,p_starts_at,p_ends_at,p_base_version_id,p_publication_id,p_reverses_exception_id,p_expected_revision,p_idempotency_key,p_actor_manager_id,p_actor_manager_name,p_reason,v_payload,v_payload_digest);
  v_response:=public.static_weekly_response_json(v_operation,v_revision,v_payload_digest,v_request_digest,jsonb_build_object('exception_id',v_exception,'exception_type',p_exception_type,'service_date',p_service_date,'payload_digest',v_payload_digest,'sequence',v_revision)); insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest) values(v_command,p_actor_manager_id,p_actor_manager_name,v_operation,p_idempotency_key,p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_payload_digest); return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v2_create_draft(p_effective_start date, p_objective_version text, p_objective jsonb, p_input_provenance jsonb, p_document jsonb, p_expected_revision bigint, p_actor_manager_id uuid, p_actor_manager_name text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_request jsonb; v_request_digest text; v_prior public.weekly_schedule_command_receipts%rowtype; v_command uuid:=gen_random_uuid(); v_version uuid; v_content_digest text; v_revision bigint; v_response jsonb;
begin
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_actor_manager_id,p_actor_manager_name,p_idempotency_key,'create_draft');
  v_request:=jsonb_build_object('operation','create_draft','effective_start',p_effective_start,'objective_version',p_objective_version,'objective_digest',public.static_weekly_digest_jsonb(p_objective),'input_provenance_digest',public.static_weekly_digest_jsonb(p_input_provenance),'document_identity',p_document#>>'{validation,database_document_identity}','expected_revision',p_expected_revision,'actor_manager_id',p_actor_manager_id,'actor_manager_name',p_actor_manager_name);
  v_request_digest:=public.static_weekly_digest_jsonb(v_request); perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts where actor_manager_id=p_actor_manager_id and idempotency_key=p_idempotency_key;
  if found then if v_prior.request_digest<>v_request_digest then raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs'; end if; return v_prior.response_json; end if;
  if p_effective_start is null or btrim(coalesce(p_objective_version,''))='' then raise exception using errcode='23514',message='complete draft command identity is required'; end if;
  perform public.static_weekly_assert_document_attested(p_document,p_effective_start,true);
  perform public.static_weekly_assert_exact_object(p_input_provenance,array['adapter_schema','compiler_version','input_digest','baseline_input_digest','authority_digest','replay_digest'],array['adapter_schema','compiler_version','input_digest','baseline_input_digest','authority_digest','replay_digest'],'draft input provenance');
  if jsonb_typeof(p_objective) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_input_provenance) k(key) where jsonb_typeof(p_input_provenance->k.key) is distinct from 'string') or p_objective is distinct from p_document#>'{authority,optimizerResult,objective}' or p_objective_version is distinct from p_document#>>'{validation,compiler_version}' or p_input_provenance->>'adapter_schema' is distinct from p_document#>>'{adapter,schema}' or p_input_provenance->>'compiler_version' is distinct from p_document#>>'{validation,compiler_version}' or p_input_provenance->>'input_digest' is distinct from p_document#>>'{validation,input_digest}' or p_input_provenance->>'baseline_input_digest' is distinct from p_document#>>'{authority,baselineInputDigest}' or p_input_provenance->>'authority_digest' is distinct from p_document#>>'{validation,authority_digest}' or p_input_provenance->>'replay_digest' is distinct from p_document#>>'{validation,replay_digest}' then raise exception using errcode='23514',message='draft command may use only attested adapter-derived objective and provenance'; end if;
  begin v_version:=(p_document#>>'{authority,compilerInput,version,id}')::uuid; exception when others then raise exception using errcode='23514',message='compiler weekly version identity must be a canonical UUID'; end;
  v_content_digest:=public.static_weekly_digest_jsonb(jsonb_build_object('objective_version',p_objective_version,'objective_digest',public.static_weekly_digest_jsonb(p_objective),'input_provenance_digest',public.static_weekly_digest_jsonb(p_input_provenance),'document_identity',p_document#>>'{validation,database_document_identity}'));
  v_revision:=public.static_weekly_advance_authority(p_expected_revision,'create_draft',p_actor_manager_id,p_actor_manager_name,v_command,v_content_digest);
  insert into public.weekly_schedule_versions(version_id,lifecycle_state,effective_start,objective_version,objective_json,input_provenance_json,draft_document,content_digest,created_by_manager_id,created_by_manager_name_snapshot) values(v_version,'draft',p_effective_start,p_objective_version,p_objective,p_input_provenance,p_document,v_content_digest,p_actor_manager_id,p_actor_manager_name);
  perform public.static_weekly_materialize_document(v_version,p_document,v_content_digest,p_actor_manager_id,p_actor_manager_name);
  v_response:=public.static_weekly_response_json('create_draft',v_revision,v_content_digest,v_request_digest,jsonb_build_object('version_id',v_version,'draft_revision',1,'effective_start',p_effective_start));
  insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest) values(v_command,p_actor_manager_id,p_actor_manager_name,'create_draft',p_idempotency_key,p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest); return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v2_materialize_projection(p_publication_id uuid, p_service_date date, p_exception_set_digest text, p_compiler_version text, p_objective jsonb, p_metrics jsonb, p_replay_digest text, p_assignments jsonb, p_expected_revision bigint, p_actor_manager_id uuid, p_actor_manager_name text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_request jsonb; v_request_digest text; v_prior public.weekly_schedule_command_receipts%rowtype; v_publication public.weekly_schedule_publications%rowtype; v_effective_start date; v_effective_end date; v_exception_set jsonb; v_exception_digest text; v_command uuid:=gen_random_uuid(); v_projection uuid:=gen_random_uuid(); v_revision bigint; v_content_digest text; v_response jsonb; v_item jsonb; v_assignment public.weekly_schedule_slot_assignments%rowtype; v_owner public.v_weekly_roster_slot_incumbency_ranges%rowtype; v_occurrence uuid; v_work jsonb;
begin
