CREATE OR REPLACE FUNCTION public.static_weekly_v3_read_manager_snapshot(p_week_start date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_snapshot jsonb;
  v_source jsonb;
  v_roster jsonb; v_terminal jsonb; v_cancel_exceptions jsonb;
  v_original_absences jsonb;v_absence record;v_target_revision bigint;v_target_count integer:=0;
begin
  perform public.static_weekly_v3_assert_control_plane();
  -- A calendar-week request containing NOW follows its actual active
  -- publication. Historical requests keep their own effective publication.
  p_week_start:=public.static_weekly_projection_window_start(case
   when public.sch_service_date(statement_timestamp()) between p_week_start and p_week_start+6
   then public.sch_service_date(statement_timestamp()) else p_week_start end);
  v_snapshot:=public.static_weekly_v3_read_manager_snapshot_staffing_base(p_week_start);
  -- Server civil date is a cancellation fence, never the selected week,
  -- client clock, physical clock qualification or acceptance permission.
  v_snapshot:=v_snapshot||jsonb_build_object('current_service_date',public.sch_service_date(statement_timestamp())::text);
  -- Independently expose original private accepted targets even when a
  -- replaced/deactivated person has NO current compiler exception/incumbency.
  -- This is not compiler input, projection enrichment or historical restore.
  select control.current_revision into strict v_target_revision from public.static_weekly_schedule_control control where control.singleton;
  if v_snapshot->>'authority_revision' is distinct from v_target_revision::text then
    raise exception using errcode='40001',message='original absence target snapshot revision is stale';end if;
  v_original_absences:='[]'::jsonb;
  for v_absence in
    select a.*,acceptedcmd.operation_id is not null as valid_original_target
    from public.static_weekly_staffing_absences a
    left join public.static_weekly_staffing_commands acceptedcmd
   on acceptedcmd.operation_id=a.accepted_operation_id and acceptedcmd.operation_id=a.absence_id
    and acceptedcmd.command_kind='absence' and acceptedcmd.state='ACCEPTED'
    and acceptedcmd.employee_id=a.employee_id and acceptedcmd.start_date=a.start_date and acceptedcmd.end_date=a.end_date
    and acceptedcmd.absence_kind=a.absence_kind and acceptedcmd.target_absence_id is null
    and acceptedcmd.accepted_revision=a.accepted_revision
    and acceptedcmd.prepared_by_manager_id=a.accepted_by_manager_id
    and acceptedcmd.confirmed_by_manager_id=a.accepted_by_manager_id
    and acceptedcmd.semantic_body=jsonb_build_object('absenceKind',a.absence_kind,'commandKind','absence',
     'employeeId',a.employee_id::text,'endDate',a.end_date::text,'startDate',a.start_date::text,'targetAbsenceId',null)
    and acceptedcmd.semantic_digest=public.static_weekly_digest_jsonb(acceptedcmd.semantic_body)
    and acceptedcmd.accepted_receipt->>'event'='ACCEPTED'
    and acceptedcmd.accepted_receipt->>'operation_id'=acceptedcmd.operation_id::text
    and acceptedcmd.accepted_receipt->>'semantic_digest'=acceptedcmd.semantic_digest
    and acceptedcmd.accepted_receipt->>'authority_revision'=a.accepted_revision::text
    where a.start_date<=p_week_start+6
     and a.end_date>=greatest(p_week_start,public.sch_service_date(statement_timestamp()))
     and not exists(select 1 from public.static_weekly_staffing_absence_cancellations c where c.absence_id=a.absence_id)
    order by a.start_date,a.absence_id
  loop
    if not v_absence.valid_original_target then
      raise exception using errcode='23514',message='snapshot original accepted absence identity is inconsistent';end if;
    v_target_count:=v_target_count+1;
    if v_target_count>100000 then raise exception using errcode='54000',message='canonical original absence target row bound exceeded';end if;
    v_original_absences:=v_original_absences||jsonb_build_array(jsonb_build_object(
      'staffingAbsenceId',v_absence.absence_id::text,'staffingEmployeeId',v_absence.employee_id::text,
      'staffingStartDate',v_absence.start_date::text,'staffingEndDate',v_absence.end_date::text,
      'staffingAcceptedOperationId',v_absence.accepted_operation_id::text,'status','accepted',
      'absenceKind',v_absence.absence_kind::text,'actorId',v_absence.accepted_by_manager_id::text,
      'sourceKind','canonical_staffing_absence'));
    if octet_length(v_original_absences::text)>16777216 then
      raise exception using errcode='54000',message='canonical original absence target byte bound exceeded';end if;
  end loop;
  v_snapshot:=v_snapshot||jsonb_build_object('canonical_staffing_absences',v_original_absences);
  -- Enrich ONLY rows already included by the existing canonical compiler
  -- exception-set/cancellation guard. Never reconstruct a range from a week
  -- or an employee from today's slot incumbent, and never add absent rows.
  if jsonb_typeof(v_snapshot->'exceptions')='array' then
    if jsonb_array_length(v_snapshot->'exceptions')>100000 then
      raise exception using errcode='54000',message='manager cancellation target row bound exceeded';
    end if;
    select coalesce(jsonb_agg(
      case when a.absence_id is null then e.value else e.value||jsonb_build_object(
        'staffingEmployeeId',a.employee_id::text,
        'staffingStartDate',a.start_date::text,
        'staffingEndDate',a.end_date::text,
        'staffingAcceptedOperationId',a.accepted_operation_id::text)
      end order by e.ordinal),'[]'::jsonb) into v_cancel_exceptions
    from jsonb_array_elements(v_snapshot->'exceptions') with ordinality e(value,ordinal)
    left join public.static_weekly_staffing_absences a
      on a.absence_id::text=e.value->>'staffingAbsenceId'
      and e.value->>'id'=a.absence_id::text||':'||(e.value->>'serviceDate')
      and e.value->>'serviceDate' between a.start_date::text and a.end_date::text
      and e.value->>'actorId'=a.accepted_by_manager_id::text
      and e.value->>'status'='accepted';
    if octet_length(v_cancel_exceptions::text)>16777216 then
      raise exception using errcode='54000',message='manager cancellation target byte bound exceeded';
    end if;
    v_snapshot:=jsonb_set(v_snapshot,'{exceptions}',v_cancel_exceptions,false);
  end if;


  select jsonb_agg(jsonb_build_object('invalidationId',r.invalidation_id,'publicationId',r.publication_id,
    'authorityRevision',r.authority_revision,'effectiveStart',r.effective_start,'effectiveEnd',r.effective_end,
    'state','BLOCKED_RECURRING_AUTHORITY') order by r.authority_revision,r.invalidation_id) into v_terminal
  from (select distinct i.invalidation_id,i.publication_id,i.authority_revision,i.effective_start,i.effective_end
    from generate_series(0,6) offset_day
    cross join lateral public.static_weekly_v19_current_terminal_range(p_week_start+offset_day) i
    where i.invalidation_id is not null) r;
  if v_terminal is not null then
    return v_snapshot||jsonb_build_object('projection_status','blocked_recurring_authority',
      'latest_projection',null,'assignments','[]'::jsonb,'recurring_invalidations',v_terminal,
      'recurring_repair_required',true);
  end if;


  -- A draft or publication already binds its own immutable compiler input.
  if jsonb_typeof(v_snapshot->'display_version')='object' then
    return v_snapshot;
  end if;

  begin
    select s.canonical_source into strict v_source
    from public.static_weekly_authority_source_documents s
    where s.active=true;
  exception
    when no_data_found then
      raise exception using errcode='23514',message='initial manager snapshot requires one active registered recurring source';
    when too_many_rows then
      raise exception using errcode='23514',message='initial manager snapshot requires exactly one active registered recurring source';
  end;

  if jsonb_typeof(v_source->'slots')<>'array' then
    raise exception using errcode='23514',message='active registered recurring source has no canonical slot array';
  end if;

  select coalesce(jsonb_agg(
    item||jsonb_build_object(
      'contractor_capacity',coalesce((
        select lower(slot->>'contractorCapacity')='true'
        from jsonb_array_elements(v_source->'slots') slot
        where slot->>'id'=item->>'slot_id'
        limit 1
      ),false)
    ) order by item->>'slot_label',item->>'slot_id'
  ),'[]'::jsonb) into v_roster
  from jsonb_array_elements(coalesce(v_snapshot->'roster','[]'::jsonb)) item;

  return jsonb_set(v_snapshot,'{roster}',v_roster,true);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_read_manager_snapshot_staffing_base(p_week_start date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_snapshot jsonb; v_availability jsonb:='[]'::jsonb; v_roster jsonb:='[]'::jsonb; v_item jsonb; v_date date; v_state text; v_person uuid; v_name text; v_active boolean; v_devices jsonb; v_week_staffing jsonb; v_projection_revision bigint; v_staffing_revision bigint; v_projection_status text:='missing';
begin
  perform public.static_weekly_v3_assert_control_plane();
  v_snapshot:=public.static_weekly_v3_read_manager_snapshot_base(p_week_start);
  for v_item in select value from jsonb_array_elements(coalesce(v_snapshot->'availability','[]'::jsonb)) loop
    v_date:=p_week_start+mod((v_item->>'day_of_week')::integer-extract(dow from p_week_start)::integer+7,7);
    select s.staffing_state into v_state from public.weekly_roster_slot_staffing_states s
    where s.slot_id=(v_item->>'slot_id')::uuid and s.effective_start<=v_date
    order by s.effective_start desc,s.authority_revision desc limit 1;
    select r.person_id,r.person_name_snapshot into v_person,v_name from public.v_weekly_roster_slot_incumbency_ranges r
    where r.slot_id=(v_item->>'slot_id')::uuid and r.effective_start<=v_date and (r.effective_end is null or v_date<r.effective_end)
    order by r.effective_start desc,r.incumbency_id desc limit 1;
    select e.active into v_active from public.employees e where e.id=v_person;
    select coalesce(jsonb_agg(d.device_id order by d.device_id),'[]'::jsonb) into v_devices from public.devices d where d.active=true and d.assigned_employee_id=v_person;
    v_item:=v_item||jsonb_build_object(
      'service_date',v_date::text,
      'availability_state',coalesce(v_state,v_item->>'availability_state'),
      'person_id',v_person::text,
      'person_name',v_name,
      'employee_active',v_active,
      'device_ids',coalesce(v_devices,'[]'::jsonb)
    );
    v_availability:=v_availability||jsonb_build_array(v_item);
  end loop;
  for v_item in select value from jsonb_array_elements(coalesce(v_snapshot->'roster','[]'::jsonb)) loop
    select coalesce(jsonb_agg(a order by a->>'service_date'),'[]'::jsonb) into v_week_staffing
    from jsonb_array_elements(v_availability) a where a->>'slot_id'=v_item->>'slot_id';
    v_roster:=v_roster||jsonb_build_array(v_item||jsonb_build_object('week_staffing',v_week_staffing));
  end loop;
  if jsonb_typeof(v_snapshot->'latest_projection')='object' then
    select (r.response_json->>'revision')::bigint into v_projection_revision
    from public.weekly_schedule_command_receipts r
    where r.command_type='materialize_projection'
      and r.response_json#>>'{data,projection_id}'=v_snapshot#>>'{latest_projection,projection_id}'
    order by r.accepted_at desc,r.command_id desc limit 1;
  end if;
  select max(s.authority_revision) into v_staffing_revision
  from public.weekly_roster_slot_staffing_states s
  where s.effective_start<=p_week_start+6;
  if v_projection_revision is not null and (v_staffing_revision is null or v_projection_revision>v_staffing_revision) then
    v_projection_status:='current';
  elsif v_projection_revision is not null or v_staffing_revision is not null then
    v_projection_status:='stale_staffing_change';
    v_snapshot:=jsonb_set(v_snapshot,'{latest_projection}','null'::jsonb,true);
  end if;
  return jsonb_set(jsonb_set(v_snapshot,'{availability}',v_availability,true),'{roster}',v_roster,true)
    ||jsonb_build_object('projection_status',v_projection_status,'projection_authority_revision',v_projection_revision,'staffing_authority_revision',v_staffing_revision);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_read_publication_source(p_publication_id uuid, p_service_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_document jsonb; v_version uuid; v_source uuid;
begin
  perform public.static_weekly_v3_assert_control_plane(); perform public.static_weekly_v20_assert_usable_recurring_week(p_publication_id,p_service_date);
  select v.draft_document,p.version_id,v.authority_source_id into v_document,v_version,v_source
  from public.weekly_schedule_publications p
  join public.weekly_schedule_versions v on v.version_id=p.version_id
  where p.publication_id=p_publication_id;
  if not found or v_source is null or public.static_weekly_effective_version(p_service_date) is distinct from v_version then
    raise exception using errcode='23514',message='control plane source must name the effective immutable publication and registered source';
  end if;
  return jsonb_build_object(
    'source_id',v_source::text,
    'compiler_input',public.static_weekly_v4_hydrate_compiler_source(v_document#>'{authority,compilerInput}',p_service_date),
    'exceptions',public.static_weekly_compiler_exception_set(p_publication_id,p_service_date),
    'publication_id',p_publication_id::text,
    'version_id',v_version::text,
    'authority_revision',(select current_revision from public.static_weekly_schedule_control where singleton)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_recover_authority_key(p_key_id text, p_secret text, p_recovery_of text, p_configured_by text DEFAULT 'release-owner'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_now timestamptz:=statement_timestamp(); v_active text; v_active_count integer;
begin
  perform public.static_weekly_v3_assert_release_operator();
  if p_key_id !~ '^static-weekly-authority-hmac-v[0-9]+$' or p_key_id is distinct from nullif(btrim(p_key_id),'') or length(coalesce(p_secret,''))<32 or nullif(btrim(p_configured_by),'') is null or nullif(btrim(p_recovery_of),'') is null then
    raise exception using errcode='22023',message='recovery requires a distinct new versioned key, valid secret, exact failed active predecessor, and release operator identity';
  end if;
  perform 1 from public.static_weekly_authority_attestation_keys where key_state='active' and activates_at<=v_now and (verify_not_after is null or verify_not_after>v_now) for update;
  select count(*),min(key_id) into v_active_count,v_active from public.static_weekly_authority_attestation_keys where key_state='active' and activates_at<=v_now and (verify_not_after is null or verify_not_after>v_now);
  if v_active_count<>1 or p_recovery_of is distinct from v_active or p_key_id=p_recovery_of then
    raise exception using errcode='23514',message='recovery predecessor must be the one current active failed key';
  end if;
  if exists(select 1 from public.static_weekly_authority_attestation_keys where key_id=p_key_id) then
    raise exception using errcode='23505',message='recovery key identity must be new and may not be reused';
  end if;
  if exists(select 1 from public.static_weekly_authority_attestation_keys where recovery_of_key_id=p_recovery_of) then
    raise exception using errcode='23505',message='failed active key already has one immutable recovery successor';
  end if;
  update public.static_weekly_authority_attestation_keys
  set key_state='revoked',revoked_at=v_now,revoked_by='failed-active-recovery',verify_not_after=v_now
  where key_id=v_active and key_state='active';
  if not found then raise exception using errcode='40001',message='failed active key changed before atomic recovery could complete'; end if;
  insert into public.static_weekly_authority_attestation_keys(key_id,secret_material,key_state,activates_at,verify_not_after,configured_by,recovery_of_key_id)
  values(p_key_id,p_secret,'active',v_now,null,left(p_configured_by,200),p_recovery_of);
  return public.static_weekly_v3_authority_health();
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_register_authority_source(p_source_id uuid, p_canonical_source jsonb, p_configured_by text DEFAULT 'release-owner'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_digest text;
begin
  perform public.static_weekly_v3_assert_release_operator();
  if p_source_id is null or nullif(btrim(p_configured_by),'') is null then raise exception using errcode='22023',message='registered scheduler source needs an immutable UUID and release owner'; end if;
  perform public.static_weekly_v3_source_identity(p_canonical_source); v_digest:=public.static_weekly_digest_jsonb(p_canonical_source);
  insert into public.static_weekly_authority_source_documents(source_id,canonical_source,source_digest,configured_by)
  values(p_source_id,p_canonical_source,v_digest,left(p_configured_by,200));
  return jsonb_build_object('source_id',p_source_id::text,'source_digest',v_digest,'active',true);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_revoke_authority_key(p_key_id text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  perform public.static_weekly_v3_assert_release_operator();
  if nullif(btrim(p_reason),'') is null then raise exception using errcode='22023',message='key revocation reason is required'; end if;
  update public.static_weekly_authority_attestation_keys set key_state='revoked',revoked_at=statement_timestamp(),revoked_by=left(p_reason,200),verify_not_after=least(coalesce(verify_not_after,statement_timestamp()),statement_timestamp()) where key_id=p_key_id and key_state<>'active';
  if not found then raise exception using errcode='23514',message='only a non-active overlap or pending key may be revoked'; end if;
  return public.static_weekly_v3_authority_health();
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_rotate_authority_key(p_key_id text, p_secret text, p_overlap_until timestamp with time zone, p_configured_by text DEFAULT 'release-owner'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_now timestamptz:=statement_timestamp();
begin
  perform public.static_weekly_v3_assert_release_operator();
  if p_key_id !~ '^static-weekly-authority-hmac-v[0-9]+$' or length(coalesce(p_secret,''))<32 or p_overlap_until<=v_now or p_overlap_until>v_now+interval '24 hours' then raise exception using errcode='22023',message='rotation requires a new versioned key, 32-character secret, and bounded 24-hour overlap'; end if;
  update public.static_weekly_authority_attestation_keys set key_state='overlap',verify_not_after=p_overlap_until where key_state='active';
  insert into public.static_weekly_authority_attestation_keys(key_id,secret_material,key_state,activates_at,verify_not_after,configured_by) values(p_key_id,p_secret,'active',v_now,null,left(coalesce(nullif(btrim(p_configured_by),''),'release-owner'),200));
  return public.static_weekly_v3_authority_health();
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_update_draft(p_version_id uuid, p_document jsonb, p_objective jsonb, p_input_provenance jsonb, p_expected_draft_revision bigint, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET plan_cache_mode TO 'force_generic_plan'
AS $function$
declare v_actor jsonb; v_document jsonb; v_source uuid;
begin
  perform public.static_weekly_v3_assert_control_plane();
  perform public.static_weekly_v14_assert_recurring_source_use((select authority_source_id from public.weekly_schedule_versions where version_id=p_version_id),p_manager_id,null,p_idempotency_key,'update'); v_actor:=public.static_weekly_v3_manager_actor(p_manager_id); select authority_source_id into v_source from public.weekly_schedule_versions where version_id=p_version_id and lifecycle_state='draft' for share; perform public.static_weekly_v3_assert_registered_source(v_source,p_document#>'{authority,compilerInput}');
  perform public.static_weekly_assert_compiler_authority(p_document->'authority',p_document->'receipt',(select effective_start from public.weekly_schedule_versions where version_id=p_version_id),true);
  v_document:=jsonb_set(p_document,'{attestation}',public.static_weekly_v6_issue_document_attestation(p_document),true);
  return public.static_weekly_v2_update_draft(p_version_id,v_document,p_objective,p_input_provenance,p_expected_draft_revision,p_expected_revision,p_manager_id,v_actor->>'manager_name',p_idempotency_key);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v4_assert_projection_envelope(p_envelope jsonb, p_publication_id uuid, p_week_start date, p_exception_set jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_assignment jsonb;
  v_location jsonb;
  v_locations jsonb;
  v_service_mode text;
  v_legacy jsonb;
  v_legacy_assignments jsonb;
begin
  if jsonb_typeof(p_envelope->'assignments') is distinct from 'array' then
    raise exception using errcode='23514',message='projection assignments require exact service-mode and location authority';
  end if;
  for v_assignment in select value from jsonb_array_elements(p_envelope->'assignments') loop
    v_service_mode:=coalesce(v_assignment#>>'{work_snapshot,serviceMode}','scan_tracked');
    v_locations:=v_assignment#>'{work_snapshot,includedLocations}';
    if v_service_mode not in ('scan_tracked','reminder_only','response_only_no_clean')
       or jsonb_typeof(v_locations) is distinct from 'array' then
      raise exception using errcode='23514',message='each projection work snapshot requires one approved service mode and an exact physical-location array';
    end if;
    if v_service_mode='scan_tracked' and (jsonb_array_length(v_locations)<1 or jsonb_array_length(v_locations)>256) then
      raise exception using errcode='23514',message='scan-tracked projection work requires one through 256 physical location snapshots';
    elsif v_service_mode in ('reminder_only','response_only_no_clean') and jsonb_array_length(v_locations)<>0 then
      raise exception using errcode='23514',message='non-scan projection work requires an explicit empty physical-location set';
    end if;
    for v_location in select value from jsonb_array_elements(v_locations) loop
      perform public.static_weekly_assert_exact_object(
        v_location,array['locationId','locationNameSnapshot'],array['locationId','locationNameSnapshot'],
        'included location snapshot'
      );
      if jsonb_typeof(v_location->'locationId') is distinct from 'string'
         or (v_location->>'locationId') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
         or jsonb_typeof(v_location->'locationNameSnapshot') is distinct from 'string'
         or nullif(btrim(v_location->>'locationNameSnapshot'),'') is null then
        raise exception using errcode='23514',message='included location snapshots require canonical identities and nonblank names';
      end if;
    end loop;
    if (select count(*) from jsonb_array_elements(v_locations))
       <> (select count(distinct value->>'locationId') from jsonb_array_elements(v_locations)) then
      raise exception using errcode='23514',message='included location snapshots may not repeat a location identity';
    end if;
    if v_service_mode='scan_tracked' and not exists(
      select 1 from jsonb_array_elements(v_locations) x
      where x->>'locationId'=v_assignment#>>'{work_snapshot,locationId}'
    ) then
      raise exception using errcode='23514',message='scan-tracked routing location must be one of its physical locations';
    end if;
  end loop;

  select jsonb_agg(
    jsonb_set(
      a.value,'{work_snapshot}',((a.value->'work_snapshot')-'includedLocations')-'serviceMode',false
    ) order by a.ordinality
  ) into v_legacy_assignments
  from jsonb_array_elements(p_envelope->'assignments') with ordinality a(value,ordinality);
  v_legacy:=jsonb_set(p_envelope,'{assignments}',v_legacy_assignments,false);
  v_legacy:=jsonb_set(
    v_legacy,'{database_projection_identity}',
    to_jsonb(public.static_weekly_digest_jsonb(v_legacy-'database_projection_identity')),true
  );
  perform public.static_weekly_v4_assert_projection_envelope_single_location_base(
    v_legacy,p_publication_id,p_week_start,p_exception_set
  );
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v4_assert_projection_envelope_single_location_bas(p_envelope jsonb, p_publication_id uuid, p_week_start date, p_exception_set jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_authority jsonb:=p_envelope->'authority'; v_base jsonb; v_compiler_exceptions jsonb; v_publication public.weekly_schedule_publications%rowtype;
begin
  perform public.static_weekly_assert_exact_object(p_envelope,array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','database_projection_identity'],array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','database_projection_identity'],'projection envelope');
  perform public.static_weekly_assert_exact_object(p_envelope->'adapter',array['schema','version'],array['schema','version'],'projection envelope adapter');
  if jsonb_typeof(p_exception_set) is distinct from 'array' or jsonb_typeof(p_envelope->'service_date') is distinct from 'string'
    or jsonb_typeof(p_envelope->'week_start') is distinct from 'string' or jsonb_typeof(p_envelope->'week_end') is distinct from 'string'
    or jsonb_typeof(p_envelope->'authority_digest') is distinct from 'string' or jsonb_typeof(p_envelope->'replay_digest') is distinct from 'string'
    or jsonb_typeof(p_envelope->'compiler_version') is distinct from 'string' or jsonb_typeof(p_envelope->'objective') is distinct from 'object'
    or jsonb_typeof(p_envelope->'metrics') is distinct from 'object' or jsonb_typeof(p_envelope->'applied_exceptions') is distinct from 'array'
    or jsonb_typeof(p_envelope->'assignments') is distinct from 'array' or jsonb_typeof(p_envelope->'database_projection_identity') is distinct from 'string' then
    raise exception using errcode='23514',message='projection envelope requires complete typed authority, receipt, identity, and assignment fields';
  end if;
  if jsonb_array_length(p_envelope->'assignments')=0 then raise exception using errcode='23514',message='projection assignments may not be empty'; end if;
  if exists(select 1 from jsonb_array_elements(p_envelope->'assignments') as a(x) where jsonb_typeof(a.x) is distinct from 'object' or not (a.x ?& array['plan_work_id','work_id','day_of_week','service_date','status','work_snapshot','explanation'])) then
    raise exception using errcode='23514',message='projection assignments require every identity, status, snapshot, and explanation key';
  end if;
  if exists(select 1 from jsonb_array_elements(p_envelope->'assignments') as a(x)
      where jsonb_typeof(a.x->'plan_work_id') is distinct from 'string' or nullif(btrim(a.x->>'plan_work_id'),'') is null
        or jsonb_typeof(a.x->'work_id') is distinct from 'string' or nullif(btrim(a.x->>'work_id'),'') is null
        or jsonb_typeof(a.x->'day_of_week') is distinct from 'number' or (a.x->>'day_of_week') !~ '^[0-6]$'
        or jsonb_typeof(a.x->'service_date') is distinct from 'string' or nullif(btrim(a.x->>'service_date'),'') is null
        or (a.x->>'service_date') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or not pg_input_is_valid(a.x->>'service_date','date')
        or case when jsonb_typeof(a.x->'service_date')='string' and (a.x->>'service_date') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_input_is_valid(a.x->>'service_date','date') then (a.x->>'service_date')::date::text is distinct from a.x->>'service_date' or (a.x->>'service_date')::date<p_week_start or (a.x->>'service_date')::date>p_week_start+6 else false end
        or jsonb_typeof(a.x->'explanation') is distinct from 'object'
        or jsonb_typeof(a.x->'status') is distinct from 'string' or upper(a.x->>'status') not in ('ASSIGNED','OPEN','REVIEW')) then
    raise exception using errcode='23514',message='projection assignments require complete canonical seven-day identity, status, and explanation facts';
  end if;
  if (select count(*) from jsonb_array_elements(p_envelope->'assignments'))<>(select count(distinct x->>'plan_work_id') from jsonb_array_elements(p_envelope->'assignments') as a(x)) then
    raise exception using errcode='23514',message='projection assignments may not contain duplicate work identities';
  end if;
  select * into v_publication from public.weekly_schedule_publications where publication_id=p_publication_id;
  if not found then raise exception using errcode='23514',message='projection publication is unknown'; end if;
  select draft_document#>'{authority,compilerInput}' into v_base from public.weekly_schedule_versions where version_id=v_publication.version_id;
  v_compiler_exceptions:=public.static_weekly_compiler_exception_set(p_publication_id,p_week_start);
  perform public.static_weekly_assert_compiler_authority(v_authority,p_envelope->'receipt',p_week_start,false);
  if p_envelope #>> '{adapter,schema}' is distinct from p_envelope#>>'{receipt,schema}' or p_envelope #>> '{adapter,version}' is distinct from p_envelope#>>'{receipt,adapterVersion}' or p_envelope->>'service_date' is distinct from p_week_start::text or p_envelope->>'week_start' is distinct from p_week_start::text or p_envelope->>'week_end' is distinct from (p_week_start+6)::text
    or p_envelope->>'authority_digest' is distinct from public.static_weekly_digest_jsonb(v_authority) or p_envelope->>'replay_digest' is distinct from p_envelope #>>'{receipt,compiler,replayDigest}'
    or p_envelope->>'compiler_version' is distinct from v_authority #>>'{optimizerResult,compilerVersion}' or p_envelope->'objective' is distinct from v_authority #> '{optimizerResult,objective}' or p_envelope->'metrics' is distinct from v_authority #> '{optimizerResult,metrics}'
    or p_envelope->>'database_projection_identity' is distinct from public.static_weekly_digest_jsonb(p_envelope-'database_projection_identity')
    or public.static_weekly_v4_recurring_source_identity(v_authority->'compilerInput') is distinct from public.static_weekly_v4_recurring_source_identity(v_base) then
    raise exception using errcode='23514',message='projection must bind the stable registered source, complete dated receipt, objective, metrics, replay, and full weekly envelope';
  end if;
  if v_authority->'appliedExceptions' is distinct from p_exception_set or p_envelope->'applied_exceptions' is distinct from p_exception_set then
    raise exception using errcode='23514',message='overlay compiler input and applied exceptions must bind the complete accepted seven-day exception set';
  end if;
  if v_authority #> '{overlayCompilerInput,exceptions}' is distinct from v_compiler_exceptions then
    raise exception using errcode='23514',message='overlay compiler input must carry every semantic accepted exception fact for the same seven-day horizon';
  end if;
  if exists(with optimizer as(select value x from jsonb_array_elements(v_authority #> '{optimizerResult,assignments}')), projected as(select value x from jsonb_array_elements(p_envelope->'assignments'))
    select 1 from optimizer o full join projected p on p.x->>'plan_work_id'=o.x->>'planWorkId'
    where o.x is null or p.x is null or p.x->>'service_date' is distinct from o.x->>'serviceDate' or p.x->>'work_id' is distinct from o.x->>'workId' or p.x->>'day_of_week' is distinct from o.x->>'dayOfWeek' or upper(p.x->>'status') is distinct from upper(o.x->>'status')
      or (o.x->>'status'='ASSIGNED' and (p.x->>'owner_slot_id' is distinct from o.x->>'slotId' or p.x->>'owner_person_id' is distinct from o.x->>'personId'))
      or (o.x->>'status' in ('OPEN','REVIEW') and (p.x->>'owner_slot_id' is not null or p.x->>'owner_person_id' is not null))) then
    raise exception using errcode='23514',message='complete weekly projection assignments must exactly bind the canonical optimizer';
  end if;
  if exists(with optimizer as(select value x from jsonb_array_elements(v_authority #> '{optimizerResult,assignments}')), projected as(select value x from jsonb_array_elements(p_envelope->'assignments'))
    select 1 from optimizer o join projected p on p.x->>'plan_work_id'=o.x->>'planWorkId'
    where jsonb_typeof(p.x->'work_snapshot') is distinct from 'object'
      or not (p.x->'work_snapshot' ?& array['workId','dayOfWeek','originSlotId','locationId','locationCodeSnapshot','locationNameSnapshot','window','serviceEffortMinutes','serviceEffortProvenance','priority','priorityProvenance','required','coveragePolicy','bestEffortCoverage','coveragePolicyOrder','coveragePolicyProvenance','requiredQualifications','qualificationProvenance','restrictions','restrictionProvenance','restrictedSlotIds','manualLock','manualLockSlotId','overlayWork'])
      or exists(select 1 from jsonb_object_keys(p.x->'work_snapshot') as k(key) where not (k.key=any(array['workId','dayOfWeek','originSlotId','locationId','locationCodeSnapshot','locationNameSnapshot','window','serviceEffortMinutes','serviceEffortProvenance','priority','priorityProvenance','required','coveragePolicy','bestEffortCoverage','coveragePolicyOrder','coveragePolicyProvenance','requiredQualifications','qualificationProvenance','restrictions','restrictionProvenance','restrictedSlotIds','manualLock','manualLockSlotId','overlayWork'])))
      or jsonb_typeof(p.x#>'{work_snapshot,workId}') is distinct from 'string' or jsonb_typeof(p.x#>'{work_snapshot,dayOfWeek}') is distinct from 'number' or jsonb_typeof(p.x#>'{work_snapshot,originSlotId}') not in ('string','null')
      or p.x#>>'{work_snapshot,workId}' is distinct from o.x->>'workId' or p.x#>>'{work_snapshot,dayOfWeek}' is distinct from o.x->>'dayOfWeek' or p.x#>>'{work_snapshot,window,start}' is distinct from o.x#>>'{window,start}' or p.x#>>'{work_snapshot,window,end}' is distinct from o.x#>>'{window,end}' or p.x#>>'{work_snapshot,serviceEffortMinutes}' is distinct from o.x->>'serviceEffortMinutes'
      or jsonb_typeof(p.x#>'{work_snapshot,locationId}') is distinct from 'string' or p.x#>>'{work_snapshot,locationId}' !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
      or jsonb_typeof(p.x#>'{work_snapshot,locationCodeSnapshot}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,locationCodeSnapshot}'),'') is null or jsonb_typeof(p.x#>'{work_snapshot,locationNameSnapshot}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,locationNameSnapshot}'),'') is null
      or jsonb_typeof(p.x#>'{work_snapshot,window}') is distinct from 'object' or jsonb_typeof(p.x#>'{work_snapshot,window,start}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,window,start}'),'') is null or jsonb_typeof(p.x#>'{work_snapshot,window,end}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,window,end}'),'') is null
      or jsonb_typeof(p.x#>'{work_snapshot,serviceEffortMinutes}') is distinct from 'number' or jsonb_typeof(p.x#>'{work_snapshot,serviceEffortProvenance}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,serviceEffortProvenance}'),'') is null or jsonb_typeof(p.x#>'{work_snapshot,priority}') is distinct from 'number'
      or jsonb_typeof(p.x#>'{work_snapshot,priorityProvenance}') not in ('string','null') or (jsonb_typeof(p.x#>'{work_snapshot,priorityProvenance}')='string' and nullif(btrim(p.x#>>'{work_snapshot,priorityProvenance}'),'') is null)
      or jsonb_typeof(p.x#>'{work_snapshot,required}') is distinct from 'boolean' or jsonb_typeof(p.x#>'{work_snapshot,coveragePolicy}') not in ('string','null') or jsonb_typeof(p.x#>'{work_snapshot,bestEffortCoverage}') is distinct from 'boolean' or jsonb_typeof(p.x#>'{work_snapshot,coveragePolicyOrder}') not in ('number','null') or jsonb_typeof(p.x#>'{work_snapshot,coveragePolicyProvenance}') not in ('string','null')
      or jsonb_typeof(p.x#>'{work_snapshot,requiredQualifications}') is distinct from 'array' or jsonb_typeof(p.x#>'{work_snapshot,qualificationProvenance}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,qualificationProvenance}'),'') is null or jsonb_typeof(p.x#>'{work_snapshot,restrictions}') is distinct from 'array' or jsonb_typeof(p.x#>'{work_snapshot,restrictionProvenance}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,restrictionProvenance}'),'') is null or jsonb_typeof(p.x#>'{work_snapshot,restrictedSlotIds}') is distinct from 'array' or jsonb_typeof(p.x#>'{work_snapshot,manualLock}') is distinct from 'boolean' or jsonb_typeof(p.x#>'{work_snapshot,manualLockSlotId}') not in ('string','null') or jsonb_typeof(p.x#>'{work_snapshot,overlayWork}') is distinct from 'boolean'
      or exists(select 1 from jsonb_array_elements(p.x#>'{work_snapshot,requiredQualifications}') as q(value) where jsonb_typeof(q.value) is distinct from 'string' or nullif(btrim(q.value#>>'{}'),'') is null)
      or exists(select 1 from jsonb_array_elements(p.x#>'{work_snapshot,restrictions}') as r(value) where jsonb_typeof(r.value) is distinct from 'string' or nullif(btrim(r.value#>>'{}'),'') is null)
      or exists(select 1 from jsonb_array_elements(p.x#>'{work_snapshot,restrictedSlotIds}') as r(value) where jsonb_typeof(r.value) is distinct from 'string' or nullif(btrim(r.value#>>'{}'),'') is null)
      or (select count(*) from jsonb_array_elements(p.x#>'{work_snapshot,requiredQualifications}'))<>(select count(distinct value#>>'{}') from jsonb_array_elements(p.x#>'{work_snapshot,requiredQualifications}'))
      or (select count(*) from jsonb_array_elements(p.x#>'{work_snapshot,restrictions}'))<>(select count(distinct value#>>'{}') from jsonb_array_elements(p.x#>'{work_snapshot,restrictions}'))
      or (select count(*) from jsonb_array_elements(p.x#>'{work_snapshot,restrictedSlotIds}'))<>(select count(distinct value#>>'{}') from jsonb_array_elements(p.x#>'{work_snapshot,restrictedSlotIds}'))
  ) then raise exception using errcode='23514',message='projection work snapshots must be complete semantic authority facts bound to the canonical optimizer'; end if;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v4_begin_day_changes(p_service_date date, p_week_start date, p_base_version_id uuid, p_publication_id uuid, p_operations jsonb, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_actor jsonb; v_child public.weekly_schedule_command_receipts%rowtype;
  v_projection public.weekly_schedule_command_receipts%rowtype; v_projection_row public.weekly_schedule_compiled_projections%rowtype;
  v_operation jsonb; v_expected jsonb; v_mutations jsonb:='[]'::jsonb; v_snapshot jsonb;
  v_child_count integer:=0; v_requested_count integer; v_index integer; v_key text; v_expected_command text;
begin
  perform public.static_weekly_v3_assert_control_plane();
  v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
  if p_service_date is null or p_week_start is null or extract(isodow from p_week_start)<>1
     or p_service_date<p_week_start or p_service_date>p_week_start+6
     or p_base_version_id is null or p_publication_id is null or p_expected_revision is null or p_expected_revision<0
     or nullif(btrim(coalesce(p_idempotency_key,'')),'') is null or length(btrim(p_idempotency_key))>200
     or p_operations is null or jsonb_typeof(p_operations)<>'array' or jsonb_array_length(p_operations) not between 1 and 25 then
    raise exception using errcode='22023',message='complete bounded day-change batch identity is required';
  end if;
  p_idempotency_key:=btrim(p_idempotency_key);
  v_requested_count:=jsonb_array_length(p_operations);

  -- The same transaction lock used by every child and projection writer makes
  -- recognition, continuation, and independent-session races one serial order.
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));

  select * into v_projection from public.weekly_schedule_command_receipts r
  where r.actor_manager_id=p_manager_id
    and r.idempotency_key=public.static_weekly_v4_day_change_projection_key(p_idempotency_key);

  -- Index 25 is inspected as a sentinel beyond the maximum accepted batch so
  -- a previously longer chain can never be mistaken for a 25-item replay.
  for v_index in 0..25 loop
    v_key:=public.static_weekly_v4_day_change_child_key(p_idempotency_key,v_index);
    select * into v_child from public.weekly_schedule_command_receipts r
    where r.actor_manager_id=p_manager_id and r.idempotency_key=v_key;
    if found then
      if v_index<>v_child_count then
        raise exception using errcode='23505',message='idempotency key is bound to an incomplete day-change receipt chain';
      end if;
      v_child_count:=v_child_count+1;
    end if;
  end loop;

  if v_child_count=0 and v_projection.command_id is null then
    return jsonb_build_object('replayed',false);
  end if;
  if v_child_count<>v_requested_count or v_projection.command_id is null then
    raise exception using errcode='23505',message='idempotency key is bound to a different complete day-change batch';
  end if;

  for v_index in 0..v_requested_count-1 loop
    v_operation:=p_operations->v_index;
    select * into strict v_child from public.weekly_schedule_command_receipts r
    where r.actor_manager_id=p_manager_id
      and r.idempotency_key=public.static_weekly_v4_day_change_child_key(p_idempotency_key,v_index);
    if jsonb_typeof(v_operation)<>'object' or v_operation->>'operation' not in ('exception','cover_all') then
      raise exception using errcode='22023',message='day-change operations must use the normalized control-plane contract';
    end if;
    v_expected_command:=case when v_operation->>'operation'='exception' and v_operation->>'exceptionType'='reverse' then 'reverse_exception' else 'apply_exception' end;
    if v_operation->>'operation'='exception' then
      v_expected:=jsonb_build_object(
        'operation','apply_exception','exception_type',v_operation->>'exceptionType','service_date',p_service_date,
        'starts_at',case when v_operation->>'startsAt' is null then null else (v_operation->>'startsAt')::time end,
        'ends_at',case when v_operation->>'endsAt' is null then null else (v_operation->>'endsAt')::time end,
        'base_version_id',p_base_version_id,'publication_id',p_publication_id,'reason',v_operation->>'reason',
        'payload',v_operation->'payload','expected_revision',p_expected_revision+v_index,
        'actor_manager_id',p_manager_id,
        'reverses_exception_id',case when v_operation->>'reversesExceptionId' is null then null else (v_operation->>'reversesExceptionId')::uuid end
      );
      if (v_child.request_canonical_json-'actor_manager_name') is distinct from v_expected then
        raise exception using errcode='23505',message='idempotency key was already used for different ordered day-change inputs';
      end if;
    else
      v_expected:=jsonb_build_object(
        'operation','apply_exception','exception_type','cover_all','service_date',p_service_date,
        'starts_at',null,'ends_at',null,'base_version_id',p_base_version_id,'publication_id',p_publication_id,
        'reason',v_operation->>'reason','expected_revision',p_expected_revision+v_index,
        'actor_manager_id',p_manager_id,'reverses_exception_id',null
      );
      if (v_child.request_canonical_json-'actor_manager_name'-'payload') is distinct from v_expected
         or jsonb_typeof(v_child.request_canonical_json->'payload')<>'object'
         or (select count(*) from jsonb_object_keys(v_child.request_canonical_json->'payload'))<>1
         or jsonb_typeof(v_child.request_canonical_json#>'{payload,availability}')<>'object'
         or v_child.request_canonical_json#>>'{payload,availability,slotId}' is distinct from v_operation->>'slotId'
         or v_child.request_canonical_json#>'{payload,availability,breakChoice}' is distinct from v_operation->'breakChoice'
         or (v_operation->'shift'<>'null'::jsonb and v_child.request_canonical_json#>'{payload,availability,shift}' is distinct from v_operation->'shift') then
        raise exception using errcode='23505',message='idempotency key was already used for different ordered day-change inputs';
      end if;
    end if;
    if v_child.command_type<>v_expected_command or v_child.expected_revision<>p_expected_revision+v_index
       or v_child.request_digest<>public.static_weekly_digest_jsonb(v_child.request_canonical_json)
       or v_child.response_json->>'request_digest'<>v_child.request_digest
       or v_child.response_json->>'content_digest'<>v_child.content_digest
       or v_child.response_json->>'operation'<>v_expected_command
       or (v_child.response_json->>'revision')::bigint<>p_expected_revision+v_index+1
       or v_child.response_json#>>'{data,sequence}'<>(p_expected_revision+v_index+1)::text
       or v_child.response_json#>>'{data,service_date}'<>p_service_date::text
       or v_child.response_json->>'output_digest'<>public.static_weekly_digest_jsonb(v_child.response_json-'output_digest')
       or v_child.response_digest<>v_child.response_json->>'output_digest'
       or not exists(
         select 1 from public.weekly_schedule_authority_revisions a
         where a.command_id=v_child.command_id and a.authority_revision=p_expected_revision+v_index+1
           and a.operation=v_expected_command and a.actor_manager_id=p_manager_id and a.content_digest=v_child.content_digest
       ) then
      raise exception using errcode='23505',message='idempotency key is bound to an invalid day-change receipt chain';
    end if;
    v_mutations:=v_mutations||jsonb_build_array(v_child.response_json->'data');
  end loop;

  if v_projection.command_type<>'materialize_projection'
     or v_projection.expected_revision<>p_expected_revision+v_requested_count
     or v_projection.request_canonical_json->>'operation'<>'materialize_projection'
     or v_projection.request_canonical_json->>'publication_id'<>p_publication_id::text
     or v_projection.request_canonical_json->>'service_date'<>p_week_start::text
     or v_projection.request_canonical_json->>'actor_manager_id'<>p_manager_id::text
     or (v_projection.request_canonical_json->>'expected_revision')::bigint<>p_expected_revision+v_requested_count
     or v_projection.request_digest<>public.static_weekly_digest_jsonb(v_projection.request_canonical_json)
     or v_projection.response_json->>'request_digest'<>v_projection.request_digest
     or v_projection.response_json->>'content_digest'<>v_projection.content_digest
     or v_projection.response_json->>'operation'<>'materialize_projection'
     or (v_projection.response_json->>'revision')::bigint<>p_expected_revision+v_requested_count+1
     or v_projection.response_json->>'output_digest'<>public.static_weekly_digest_jsonb(v_projection.response_json-'output_digest')
     or v_projection.response_digest<>v_projection.response_json->>'output_digest'
     or not exists(
       select 1 from public.weekly_schedule_authority_revisions a
       where a.command_id=v_projection.command_id and a.authority_revision=p_expected_revision+v_requested_count+1
         and a.operation='materialize_projection' and a.actor_manager_id=p_manager_id and a.content_digest=v_projection.content_digest
     ) then
    raise exception using errcode='23505',message='idempotency key is bound to an invalid final projection receipt';
  end if;

  begin
    select * into strict v_projection_row from public.weekly_schedule_compiled_projections p
    where p.projection_id=(v_projection.response_json#>>'{data,projection_id}')::uuid;
  exception when no_data_found or too_many_rows then
    raise exception using errcode='23505',message='idempotency key is bound to a missing immutable projection';
  end;
  if v_projection_row.publication_id<>p_publication_id or v_projection_row.version_id<>p_base_version_id
     or v_projection_row.week_start<>p_week_start or v_projection_row.compiled_by_manager_id<>p_manager_id
     or v_projection_row.replay_digest<>v_projection.response_json#>>'{data,replay_digest}' then
    raise exception using errcode='23505',message='idempotency key is bound to a different immutable projection';
  end if;
  v_snapshot:=public.static_weekly_v4_projection_snapshot(v_projection_row.projection_id);
  if v_snapshot is null then
    raise exception using errcode='23505',message='idempotency key is bound to a missing immutable projection';
  end if;
  return jsonb_build_object(
    'replayed',true,
    'response',v_projection.response_json||jsonb_build_object(
      'operation','apply_day_changes',
      'data',(v_projection.response_json->'data')||jsonb_build_object('current_projection',v_snapshot,'mutations',v_mutations)
    )
  );
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v4_hydrate_compiler_source(p_source jsonb, p_service_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_slots jsonb:='[]'::jsonb;
  v_slot jsonb;
  v_ranges jsonb;
  v_hydrated jsonb;
  v_source_version jsonb;
  v_version jsonb;
  v_declared_vacant jsonb:='[]'::jsonb;
  v_active_vacant jsonb:='[]'::jsonb;
  v_availability jsonb:='[]'::jsonb;
  v_item jsonb;
  v_date date;
  v_week_start date;
  v_state text;
  v_slot_id text;
  v_is_declared_vacant boolean;
  v_is_active_vacant boolean;
begin
  if p_service_date is null or jsonb_typeof(p_source) is distinct from 'object' or jsonb_typeof(p_source->'slots') is distinct from 'array' then
    raise exception using errcode='23514',message='dated scheduler source requires one service date and stable slot array';
  end if;
  v_week_start:=public.static_weekly_source_window_start(p_source,p_service_date);
  if jsonb_typeof(p_source->'version')='object' then v_source_version:=p_source->'version';
  elsif jsonb_typeof(p_source->'versions')='array' and jsonb_array_length(p_source->'versions')=1 then v_source_version:=(p_source->'versions')->0;
  else raise exception using errcode='23514',message='dated scheduler source must carry exactly one recurring version'; end if;
  if jsonb_typeof(coalesce(v_source_version->'vacancyCapableSlotIds','[]'::jsonb)) is distinct from 'array'
    or jsonb_typeof(coalesce(v_source_version->'vacantSlotIds','[]'::jsonb)) is distinct from 'array' then
    raise exception using errcode='23514',message='vacancy-capable and active-vacancy stable-slot authority must be arrays';
  end if;
  v_declared_vacant:=coalesce(v_source_version->'vacancyCapableSlotIds','[]'::jsonb);

  for v_slot in select value from jsonb_array_elements(p_source->'slots') loop
    if jsonb_typeof(v_slot->'id') is distinct from 'string' or v_slot->>'id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      raise exception using errcode='23514',message='registered scheduler source contains a non-UUID stable roster slot identity';
    end if;
    v_slot_id:=v_slot->>'id';
    if v_slot->>'kind'='CONTRACTOR_CAPACITY' then
      perform public.static_weekly_capacity_assert_shape(v_slot);
      if not public.static_weekly_capacity_registered(v_slot)
        or exists(select 1 from public.weekly_roster_slot_incumbencies where slot_id=v_slot_id::uuid)
        or v_declared_vacant ? v_slot_id then
        raise exception using errcode='23514',message='nonemployee source capacity must match immutable registration and cannot hide an incumbent/vacancy';
      end if;
      v_slots:=v_slots||jsonb_build_array(v_slot);continue;
    end if;
    select coalesce(jsonb_agg(jsonb_build_object(
      'personId',r.person_id::text,'displayName',r.person_name_snapshot,
      'effectiveStart',r.effective_start::text,
      'effectiveEnd',case when r.effective_end is null then null else r.effective_end::text end
    ) order by r.effective_start,r.incumbency_id),'[]'::jsonb) into v_ranges
    from public.v_weekly_roster_slot_incumbency_ranges r
    where r.slot_id=v_slot_id::uuid and r.effective_start<=v_week_start+6
      and (r.effective_end is null or r.effective_end>v_week_start);
    select exists(select 1 from jsonb_array_elements_text(v_declared_vacant) vacancy(slot_id) where vacancy.slot_id=v_slot_id)
      into v_is_declared_vacant;
    if jsonb_array_length(v_ranges)=0 then
      if not v_is_declared_vacant then
        raise exception using errcode='23514',message='every non-vacant projected stable roster slot requires closure-aware incumbent history for the requested horizon';
      end if;
      v_active_vacant:=v_active_vacant||jsonb_build_array(v_slot_id);
    end if;
    v_slot:=jsonb_set(v_slot,'{incumbencies}',v_ranges,true);
    v_slots:=v_slots||jsonb_build_array(v_slot);
  end loop;

  v_hydrated:=jsonb_set(p_source,'{slots}',v_slots,true);
  if jsonb_typeof(v_hydrated->'version')='object' then v_version:=v_hydrated->'version';
  else v_version:=(v_hydrated->'versions')->0; end if;
  v_version:=jsonb_set(v_version,'{vacantSlotIds}',v_active_vacant,true);
  for v_item in select value from jsonb_array_elements(coalesce(v_version->'slotAvailability','[]'::jsonb)) loop
    v_slot_id:=v_item->>'slotId';
    if exists(select 1 from jsonb_array_elements(v_slots) slot where slot->>'id'=v_slot_id and slot->>'kind'='CONTRACTOR_CAPACITY') then
      if v_item->>'status' is distinct from 'unavailable' then
        raise exception using errcode='23514',message='registered contractor capacity cannot be activated by a recurring source';
      end if;
      v_availability:=v_availability||jsonb_build_array(v_item);continue;
    end if;
    v_date:=v_week_start+mod((v_item->>'dayOfWeek')::integer-extract(dow from v_week_start)::integer+7,7);
    select not exists(select 1 from public.v_weekly_roster_slot_incumbency_ranges r
      where r.slot_id=v_slot_id::uuid and r.effective_start<=v_date
        and (r.effective_end is null or v_date<r.effective_end)) into v_is_active_vacant;
    if v_is_active_vacant and not (v_declared_vacant ? v_slot_id) then
      raise exception using errcode='23514',message='dated vacancy requires registered stable-slot capability';
    end if;
    if v_is_active_vacant then
      v_item:=jsonb_set(v_item,'{status}',to_jsonb('vacant_unfilled'::text),true);
    else
      select s.staffing_state into v_state from public.weekly_roster_slot_staffing_states s
      where s.slot_id=v_slot_id::uuid and s.effective_start<=v_date
      order by s.effective_start desc,s.authority_revision desc limit 1;
      if v_state='vacant_unfilled' then
        raise exception using errcode='23514',message='vacant staffing state conflicts with an effective incumbent';
      end if;
      if v_state is not null then v_item:=jsonb_set(v_item,'{status}',to_jsonb(v_state),true);
      elsif v_item->>'status'='vacant_unfilled' then v_item:=jsonb_set(v_item,'{status}',to_jsonb('working'::text),true); end if;
    end if;
    v_availability:=v_availability||jsonb_build_array(v_item);
  end loop;
  v_version:=jsonb_set(v_version,'{slotAvailability}',v_availability,true);
  if jsonb_typeof(v_hydrated->'version')='object' then v_hydrated:=jsonb_set(v_hydrated,'{version}',v_version,true);
  else v_hydrated:=jsonb_set(v_hydrated,'{versions}',jsonb_build_array(v_version),true); end if;
  return jsonb_set(v_hydrated,'{serviceDate}',to_jsonb(p_service_date::text),true);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v4_mark_employee_departed(p_slot_id uuid, p_reason text, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_actor jsonb; v_manager public.ops_manager_managers%rowtype; v_prior public.weekly_schedule_command_receipts%rowtype; v_incumbent public.v_weekly_roster_slot_incumbency_ranges%rowtype; v_employee public.employees%rowtype; v_request jsonb; v_request_digest text; v_content_digest text; v_command uuid:=gen_random_uuid(); v_revision bigint; v_response jsonb; v_status jsonb; v_effective_start date:=public.sch_service_date(statement_timestamp());
begin
  perform public.static_weekly_v3_assert_control_plane(); v_manager:=public.custodial_assert_manager(p_manager_id); v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_manager_id,v_actor->>'manager_name',p_idempotency_key,'mark_employee_departed');
  if p_slot_id is null or nullif(btrim(coalesce(p_reason,'')),'') is null or char_length(p_reason)>500 or p_reason~'[\x00-\x1f\x7f]' then
    raise exception using errcode='23514',message='departure requires a stable slot and control-free reason of at most 500 characters';
  end if;
  v_request:=jsonb_build_object('operation','mark_employee_departed','slot_id',p_slot_id,'effective_start',v_effective_start,'reason',p_reason,'expected_revision',p_expected_revision,'actor_manager_id',p_manager_id);
  v_request_digest:=public.static_weekly_digest_jsonb(v_request); perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts where actor_manager_id=p_manager_id and idempotency_key=p_idempotency_key;
  if found then if v_prior.request_digest<>v_request_digest then raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs'; end if; return v_prior.response_json; end if;
  perform public.static_weekly_v5_source_availability_template(p_slot_id);
  select * into v_incumbent from public.v_weekly_roster_slot_incumbency_ranges where slot_id=p_slot_id and effective_start<=v_effective_start and (effective_end is null or v_effective_start<effective_end) order by effective_start desc limit 1;
  if not found then raise exception using errcode='23514',message='departure requires one effective stable-slot incumbent'; end if;
  select * into v_employee from public.employees where id=v_incumbent.person_id for update;
  if not found or v_employee.active is not true then raise exception using errcode='23514',message='departure requires one active custodial employee matching the stable-slot incumbent'; end if;
  perform public.static_weekly_v4_assert_employee_turnover_ready(v_employee.id);
  if exists(select 1 from public.weekly_roster_slot_staffing_states where slot_id=p_slot_id and effective_start=v_effective_start and staffing_state='departed_named_absent') then raise exception using errcode='23505',message='stable slot is already marked departed today'; end if;
  v_content_digest:=public.static_weekly_digest_jsonb(v_request-'expected_revision'-'actor_manager_id'-'operation');
  v_revision:=public.static_weekly_advance_authority(p_expected_revision,'mark_employee_departed',p_manager_id,v_actor->>'manager_name',v_command,v_content_digest);
  insert into public.weekly_roster_slot_staffing_states(slot_id,employee_id,staffing_state,effective_start,authority_revision,actor_manager_id,actor_manager_name_snapshot,reason,content_digest)
  values(p_slot_id,v_employee.id,'departed_named_absent',v_effective_start,v_revision,p_manager_id,v_actor->>'manager_name',p_reason,v_content_digest);
  v_status:=public.custodial_set_employee_active(v_employee.id,false,p_manager_id,p_reason,true);
  v_response:=public.static_weekly_response_json('mark_employee_departed',v_revision,v_content_digest,v_request_digest,jsonb_build_object('slot_id',p_slot_id,'former_employee_id',v_employee.id,'former_employee_name',v_employee.display_name,'effective_start',v_effective_start,'employee_status',v_status));
  insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest)
  values(v_command,p_manager_id,v_actor->>'manager_name','mark_employee_departed',p_idempotency_key,p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest);
  return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v4_projection_source_identity(p_source jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare v_identity jsonb; v_version jsonb; v_slots jsonb;
begin
  if jsonb_typeof(p_source) is distinct from 'object' then
    raise exception using errcode='23514',message='projection source must be one compiler input object';
  end if;
  if jsonb_typeof(p_source->'version')='object' then
    v_version:=p_source->'version';
  elsif jsonb_typeof(p_source->'versions')='array' and jsonb_array_length(p_source->'versions')=1 then
    v_version:=(p_source->'versions')->0;
  else
    raise exception using errcode='23514',message='projection source must carry exactly one recurring version';
  end if;
  v_version:=v_version-'id'-'publicationId'-'status'-'effectiveStart'-'effectiveEnd';
  v_identity:=p_source-'serviceDate'-'version'-'versions';
  if jsonb_typeof(v_identity->'slots') is distinct from 'array' then
    raise exception using errcode='23514',message='projection source must carry stable roster slots';
  end if;
  select coalesce(jsonb_agg(slot-'incumbencies' order by ordinal),'[]'::jsonb) into v_slots
  from jsonb_array_elements(v_identity->'slots') with ordinality as s(slot,ordinal);
  v_identity:=jsonb_set(v_identity,'{slots}',v_slots,true);
  return jsonb_set(v_identity,'{version}',v_version,true);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v4_replace_employee(p_slot_id uuid, p_new_employee_name text, p_reason text, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_actor jsonb; v_manager public.ops_manager_managers%rowtype; v_prior public.weekly_schedule_command_receipts%rowtype; v_incumbent public.v_weekly_roster_slot_incumbency_ranges%rowtype; v_old public.employees%rowtype; v_request jsonb; v_request_digest text; v_content_digest text; v_command uuid:=gen_random_uuid(); v_new_incumbency uuid:=gen_random_uuid(); v_revision bigint; v_response jsonb; v_created jsonb; v_status jsonb; v_assignment jsonb; v_new_employee_id uuid; v_new_name text:=regexp_replace(btrim(coalesce(p_new_employee_name,'')),'\s+',' ','g'); v_device text; v_device_count integer; v_effective_start date:=public.sch_service_date(statement_timestamp());
begin
  perform public.static_weekly_v3_assert_control_plane(); v_manager:=public.custodial_assert_manager(p_manager_id); v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_manager_id,v_actor->>'manager_name',p_idempotency_key,'replace_employee');
  if p_slot_id is null or length(v_new_name) not between 2 and 160 or nullif(btrim(coalesce(p_reason,'')),'') is null or char_length(p_reason)>500 or p_reason~'[\x00-\x1f\x7f]' then
    raise exception using errcode='23514',message='replacement requires a stable slot, new employee name, and control-free reason of at most 500 characters';
  end if;
  v_request:=jsonb_build_object('operation','replace_employee','slot_id',p_slot_id,'new_employee_name',v_new_name,'effective_start',v_effective_start,'reason',p_reason,'expected_revision',p_expected_revision,'actor_manager_id',p_manager_id);
  v_request_digest:=public.static_weekly_digest_jsonb(v_request); perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts where actor_manager_id=p_manager_id and idempotency_key=p_idempotency_key;
  if found then if v_prior.request_digest<>v_request_digest then raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs'; end if; return v_prior.response_json; end if;
  perform public.static_weekly_v5_source_availability_template(p_slot_id);
  select * into v_incumbent from public.v_weekly_roster_slot_incumbency_ranges where slot_id=p_slot_id and effective_start<v_effective_start and (effective_end is null or v_effective_start<effective_end) order by effective_start desc limit 1;
  if not found then raise exception using errcode='23514',message='replacement requires one predecessor stable-slot incumbent'; end if;
  select * into v_old from public.employees where id=v_incumbent.person_id for update;
  if not found then raise exception using errcode='23514',message='replacement predecessor must resolve to a custodial employee'; end if;
  perform public.static_weekly_v4_assert_employee_turnover_ready(v_old.id);
  if exists(select 1 from public.weekly_roster_slot_staffing_states where slot_id=p_slot_id and effective_start=v_effective_start and staffing_state='working') then raise exception using errcode='23505',message='stable slot already has a replacement today'; end if;
  select count(*),min(device_id) into v_device_count,v_device from public.devices where active=true and assigned_employee_id=v_old.id;
  if v_device_count=0 then
    select count(*),min(d.device_id) into v_device_count,v_device
    from public.devices d where d.active=true and d.assigned_employee_id is null and exists(
      select 1 from public.custodial_employee_device_assignment_history h where h.device_id=d.id and h.previous_employee_id=v_old.id and h.new_employee_id is null
        and not exists(select 1 from public.custodial_employee_device_assignment_history newer where newer.device_id=h.device_id and (newer.changed_at,newer.assignment_change_id)>(h.changed_at,h.assignment_change_id))
    );
  end if;
  if v_device_count>1 then raise exception using errcode='23514',message='replacement phone is ambiguous; assign one phone to the stable slot before retrying'; end if;
  if v_old.active then v_status:=public.custodial_set_employee_active(v_old.id,false,p_manager_id,p_reason,true);
  else update public.msg_users set is_active=false,updated_at=statement_timestamp() where employee_id=v_old.id and is_active is true; v_status:=jsonb_build_object('changed',false,'employee',to_jsonb(v_old),'released_devices','[]'::jsonb); end if;
  v_created:=public.static_weekly_v5_create_replacement_employee(v_new_name,p_manager_id);
  v_new_employee_id:=(v_created#>>'{employee,id}')::uuid;
  if v_device is not null then v_assignment:=public.custodial_assign_employee_device(v_device,v_new_employee_id,p_manager_id,p_reason,false); end if;
  v_content_digest:=public.static_weekly_digest_jsonb(v_request-'expected_revision'-'actor_manager_id'-'operation');
  v_revision:=public.static_weekly_advance_authority(p_expected_revision,'replace_employee',p_manager_id,v_actor->>'manager_name',v_command,v_content_digest);
  insert into public.weekly_roster_slot_incumbencies(incumbency_id,slot_id,person_id,person_name_snapshot,effective_start,created_by_manager_id,created_by_manager_name_snapshot,content_digest)
  values(v_new_incumbency,p_slot_id,v_new_employee_id,v_new_name,v_effective_start,p_manager_id,v_actor->>'manager_name',v_content_digest);
  insert into public.weekly_roster_slot_incumbency_closures(closed_incumbency_id,replacement_incumbency_id,closed_at_effective_date,authority_revision,actor_manager_id,actor_manager_name_snapshot,content_digest)
  values(v_incumbent.incumbency_id,v_new_incumbency,v_effective_start,v_revision,p_manager_id,v_actor->>'manager_name',v_content_digest);
  insert into public.weekly_roster_slot_staffing_states(slot_id,employee_id,staffing_state,effective_start,authority_revision,actor_manager_id,actor_manager_name_snapshot,reason,content_digest)
  values(p_slot_id,v_new_employee_id,'working',v_effective_start,v_revision,p_manager_id,v_actor->>'manager_name',p_reason,v_content_digest);
  v_response:=public.static_weekly_response_json('replace_employee',v_revision,v_content_digest,v_request_digest,jsonb_build_object('slot_id',p_slot_id,'former_employee_id',v_old.id,'former_employee_name',v_old.display_name,'new_employee_id',v_new_employee_id,'new_employee_name',v_new_name,'new_employee_code',v_created#>>'{employee,employee_code}','effective_start',v_effective_start,'device_id',v_device,'phone_assignment',v_assignment,'former_employee_status',v_status));
  insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest)
  values(v_command,p_manager_id,v_actor->>'manager_name','replace_employee',p_idempotency_key,p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest);
  return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v5_canonical_solver_tiers(p_tiers jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_projection jsonb;
begin
  if jsonb_typeof(p_tiers) is distinct from 'array' then
    raise exception using errcode='23514',message='solver tiers must be an array';
  end if;
  if exists(
    select 1
    from jsonb_array_elements(p_tiers) tier(value)
    where jsonb_typeof(tier.value) is distinct from 'object'
       or jsonb_typeof(tier.value->'attestation') is distinct from 'object'
       or jsonb_typeof(tier.value->'options') is distinct from 'object'
  ) then
    raise exception using errcode='23514',message='each solver tier requires exact options and terminal attestation objects';
  end if;

  select coalesce(jsonb_agg(
    jsonb_set(
      jsonb_set(
        tier.value,
        '{attestation}',
        (tier.value->'attestation')-'terminalReport'-'rawReceiptDigest',
        false
      ),
      '{options}',
      (tier.value->'options')-'time_limit',
      false
    ) order by tier.ordinality
  ),'[]'::jsonb)
  into v_projection
  from jsonb_array_elements(p_tiers) with ordinality tier(value,ordinality);
  return v_projection;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v5_create_replacement_employee(p_display_name text, p_manager_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_manager public.ops_manager_managers%rowtype; v_name text:=regexp_replace(btrim(coalesce(p_display_name,'')),'\s+',' ','g'); v_code text; v_employee public.employees%rowtype; v_user public.msg_users%rowtype;
begin
  v_manager:=public.custodial_assert_manager(p_manager_id);
  if length(v_name) not between 2 and 160 then raise exception using errcode='22023',message='Employee name must be between 2 and 160 characters.'; end if;
  if exists(select 1 from public.employees where active is true and lower(btrim(display_name))=lower(v_name)) then
    raise exception using errcode='23505',message='An active employee record with that name already exists.';
  end if;
  v_code:=public.custodial_next_employee_code();
  if v_code is null then raise exception using errcode='23514',message='No employee code is available for the replacement.'; end if;
  insert into public.employees(employee_code,display_name,active,role,notes)
  values(v_code,v_name,true,'staff','Fresh employee created by atomic stable-slot replacement') returning * into v_employee;
  insert into public.msg_users(employee_id,display_name,role,is_active)
  values(v_employee.id,v_employee.display_name,'employee',true) returning * into v_user;
  insert into public.custodial_employee_status_history(employee_id,employee_name,previous_active,new_active,changed_by_manager_id,change_reason,source,metadata_json)
  values(v_employee.id,v_employee.display_name,null,true,v_manager.manager_id,'employee_created','static_weekly_turnover',jsonb_build_object('employee_code',v_employee.employee_code,'msg_user_id',v_user.id));
  return jsonb_build_object('created',true,'employee',to_jsonb(v_employee),'messenger_user_id',v_user.id);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v5_projection_source_identity(p_source jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare v_identity jsonb; v_version jsonb; v_slots jsonb; v_availability jsonb;
begin
  if jsonb_typeof(p_source) is distinct from 'object' then
    raise exception using errcode='23514',message='projection source must be one compiler input object';
  end if;
  if jsonb_typeof(p_source->'version')='object' then
    v_version:=p_source->'version';
  elsif jsonb_typeof(p_source->'versions')='array' and jsonb_array_length(p_source->'versions')=1 then
    v_version:=(p_source->'versions')->0;
  else
    raise exception using errcode='23514',message='projection source must carry exactly one recurring version';
  end if;
  v_version:=v_version-'id'-'publicationId'-'status'-'effectiveStart'-'effectiveEnd'-'namedAbsentSlotIds'-'vacantSlotIds';
  if jsonb_typeof(v_version->'slotAvailability') is distinct from 'array' then
    raise exception using errcode='23514',message='projection source must retain recurring slot availability templates';
  end if;
  select coalesce(jsonb_agg(item-'status' order by ordinal),'[]'::jsonb) into v_availability
  from jsonb_array_elements(v_version->'slotAvailability') with ordinality as a(item,ordinal);
  v_version:=jsonb_set(v_version,'{slotAvailability}',v_availability,true);
  v_identity:=p_source-'serviceDate'-'version'-'versions';
  if jsonb_typeof(v_identity->'slots') is distinct from 'array' then
    raise exception using errcode='23514',message='projection source must carry stable roster slots';
  end if;
  select coalesce(jsonb_agg(slot-'incumbencies' order by ordinal),'[]'::jsonb) into v_slots
  from jsonb_array_elements(v_identity->'slots') with ordinality as s(slot,ordinal);
  v_identity:=jsonb_set(v_identity,'{slots}',v_slots,true);
  return jsonb_set(v_identity,'{version}',v_version,true);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v5_read_employee_day_dated_base(p_service_date date, p_employee_id uuid, p_now timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_result jsonb;
  v_field text;
  v_items jsonb;
  v_lunch_items jsonb;
  v_current_lunch jsonb;
begin
  v_result:=public.static_weekly_v5_read_employee_day_single_location_base(p_service_date,p_employee_id,p_now);
  foreach v_field in array array['items','all_items','current_items'] loop
    select coalesce(jsonb_agg(
      case when o.occurrence_id is null then item.value
      else item.value||jsonb_build_object(
        'service_mode',i.service_mode,
        'included_locations',i.location_names,
        'included_location_ids',i.location_ids,
        'included_location_snapshots',i.location_snapshots,
        'is_public_restroom',case when i.service_mode='scan_tracked' then i.has_public_restroom else false end
      ) end
      order by item.ordinality
    ),'[]'::jsonb) into v_items
    from jsonb_array_elements(coalesce(v_result->v_field,'[]'::jsonb)) with ordinality item(value,ordinality)
    left join public.weekly_schedule_occurrences o on o.occurrence_id::text=item.value->>'occurrence_id'
    left join lateral (
      select
        coalesce(o.authority_facts_json#>>'{work_snapshot,serviceMode}','scan_tracked') as service_mode,
        coalesce(jsonb_agg(location.value order by location.ordinality) filter(where location.value is not null),'[]'::jsonb) as location_snapshots,
        coalesce(jsonb_agg(to_jsonb(location.value->>'locationId') order by location.ordinality) filter(where location.value is not null),'[]'::jsonb) as location_ids,
        coalesce(jsonb_agg(to_jsonb(location.value->>'locationNameSnapshot') order by location.ordinality) filter(where location.value is not null),'[]'::jsonb) as location_names,
        coalesce(bool_or(lower(location.value->>'locationNameSnapshot') like '%restroom%'
          or lower(location.value->>'locationNameSnapshot') like '%bathroom%') filter(where location.value is not null),false) as has_public_restroom
      from jsonb_array_elements(
        case when jsonb_typeof(o.authority_facts_json#>'{work_snapshot,includedLocations}')='array'
          then o.authority_facts_json#>'{work_snapshot,includedLocations}' else '[]'::jsonb end
      ) with ordinality location(value,ordinality)
    ) i on true;
    v_result:=jsonb_set(v_result,array[v_field],v_items,true);
  end loop;
  if v_result->>'governed'='true' and v_result->>'projection_status'='current' then
    -- Same accepted reader drives employee display and operational reminder ownership.
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',l.responsibility_id||':'||l.normal_occurrence_id::text,
      'occurrence_id',l.normal_occurrence_id::text,'normal_occurrence_id',l.normal_occurrence_id::text,
      'projection_id',l.projection_id::text,'service_date',p_service_date::text,
      'loan_id',l.loan_id,'responsibility_id',l.responsibility_id,
      'normal_owner_person_id',l.normal_owner_id::text,'coverer_person_id',l.coverer_id::text,
      'location_group_id',l.location_group_id::text,'group_code',l.group_code,'group_name',l.group_name,
      'location_group_code',l.group_code,'location_group_name',l.group_name,'location_name',l.group_name,
      'included_locations',to_jsonb(l.included_locations),'included_location_ids',to_jsonb(l.included_location_ids),
      'included_location_snapshots',l.included_snapshots,'service_mode',l.service_mode,
      'coverage_start',to_char(l.coverage_start,'HH24:MI:SS'),'coverage_end',to_char(l.coverage_end,'HH24:MI:SS'),
      'start_time',to_char(l.coverage_start,'HH24:MI:SS'),'end_time',to_char(l.coverage_end,'HH24:MI:SS'),
      'coverage_purpose','lunch_coverage','purpose','lunch_coverage','section_title','Lunch coverage',
      'source_type','static_weekly_lunch_coverage','owner_type','EMPLOYEE','status','ASSIGNED',
      'load_points',0,'notes','Temporary responsibility; existing check deadlines unchanged.',
      'check_deadline_policy','inherit_existing_90_minute_deadline','creates_deep_clean',false,
      'is_public_restroom',l.service_mode='scan_tracked' and public.sch_is_public_restroom_group(l.location_group_id)
    ) order by l.coverage_start,l.loan_id,l.responsibility_id,l.normal_occurrence_id),'[]') into v_lunch_items
    from public.static_weekly_v8_read_lunch_segments(p_service_date) l where l.coverer_id=p_employee_id;
    select coalesce(jsonb_agg(item order by ordinal),'[]') into v_current_lunch
    from jsonb_array_elements(v_lunch_items) with ordinality rows(item,ordinal)
    where (p_now at time zone 'America/Chicago')::date=p_service_date
      and (item->>'coverage_start')::time<=(p_now at time zone 'America/Chicago')::time
      and (p_now at time zone 'America/Chicago')::time<(item->>'coverage_end')::time;
    v_result:=jsonb_set(v_result,'{all_items}',coalesce(v_result->'all_items','[]')||v_lunch_items);
    v_result:=jsonb_set(v_result,'{current_items}',coalesce(v_result->'current_items','[]')||v_current_lunch);
    v_result:=jsonb_set(v_result,'{items}',coalesce(v_result->'items','[]')||v_current_lunch);
    v_result:=v_result||jsonb_build_object('lunch_coverage_status','PERSISTED',
      'lunch_coverage_contract','static-weekly-lunch-consumers.v1',
      'assignment_count',jsonb_array_length(v_result->'all_items'));
  else
    v_result:=v_result||jsonb_build_object('lunch_coverage_status','UNAVAILABLE');
  end if;
  return jsonb_set(v_result,'{contract_version}',to_jsonb('static-weekly-employee-day.v3'::text),true);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v5_read_employee_day_single_location_base(p_service_date date, p_employee_id uuid, p_now timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_version uuid; v_publication uuid; v_week_start date; v_projection uuid; v_projection_revision bigint; v_staffing_revision bigint; v_status text:='missing_projection'; v_employee public.employees%rowtype; v_slot uuid; v_slot_count integer; v_shift_start time; v_shift_end time; v_staffing_state text; v_items jsonb:='[]'::jsonb; v_current jsonb:='[]'::jsonb; v_local_date date; v_local_time time; v_phase text; v_notice text;
begin
  if p_service_date is null or p_employee_id is null or p_now is null then raise exception using errcode='22023',message='employee day requires service_date, employee_id, and current time'; end if;
  v_version:=public.static_weekly_effective_version(p_service_date);
  if v_version is null then return jsonb_build_object('governed',false,'service_date',p_service_date::text,'source','legacy_daily_schedule'); end if;
  select p.publication_id into v_publication from public.weekly_schedule_publications p where p.version_id=v_version;
  v_week_start:=public.static_weekly_projection_window_start(p_service_date);
  select p.projection_id,(r.response_json->>'revision')::bigint into v_projection,v_projection_revision from public.weekly_schedule_compiled_projections p
  join public.weekly_schedule_command_receipts r on r.command_type='materialize_projection' and r.response_json#>>'{data,projection_id}'=p.projection_id::text
  where p.publication_id=v_publication and p.week_start=v_week_start
    and p.exception_set_digest=(select public.static_weekly_digest_jsonb(public.static_weekly_accepted_exception_set(v_publication,v_week_start)))
  order by (r.response_json->>'revision')::bigint desc,r.command_id desc limit 1;
  select max(s.authority_revision) into v_staffing_revision from public.weekly_roster_slot_staffing_states s where s.effective_start<=v_week_start+6;
  if v_projection_revision is not null and (v_staffing_revision is null or v_projection_revision>v_staffing_revision) then v_status:='current';
  elsif v_projection is not null then v_status:='stale_staffing_change'; end if;
  select * into v_employee from public.employees e where e.id=p_employee_id;
  if not found then raise exception using errcode='P0002',message='employee not found'; end if;
  if v_status<>'current' then return jsonb_build_object('governed',true,'source','static_weekly_projection','service_date',p_service_date::text,'week_start',v_week_start::text,'publication_id',v_publication::text,'projection_id',case when v_projection is null then null else v_projection::text end,'projection_status',v_status,'projection_authority_revision',v_projection_revision,'staffing_authority_revision',v_staffing_revision,'employee_id',v_employee.id::text,'employee_name',v_employee.display_name,'items','[]'::jsonb,'all_items','[]'::jsonb,'current_items','[]'::jsonb); end if;
  select count(*),(array_agg(r.slot_id order by r.slot_id))[1] into v_slot_count,v_slot from public.v_weekly_roster_slot_incumbency_ranges r
  where r.person_id=p_employee_id and r.effective_start<=p_service_date and (r.effective_end is null or p_service_date<r.effective_end);
  if v_slot_count>1 then raise exception using errcode='23514',message='employee resolves to more than one effective weekly roster slot'; end if;
  if v_slot is not null then
    select a.shift_start,a.shift_end into v_shift_start,v_shift_end from public.weekly_schedule_slot_availability a
    where a.version_id=v_version and a.slot_id=v_slot and a.day_of_week=extract(dow from p_service_date)::integer;
    select s.staffing_state into v_staffing_state from public.weekly_roster_slot_staffing_states s where s.slot_id=v_slot and s.effective_start<=p_service_date order by s.effective_start desc,s.authority_revision desc limit 1;
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',o.occurrence_id::text,'occurrence_id',o.occurrence_id::text,'projection_id',o.projection_id::text,'service_date',o.service_date::text,
    'segment_number',row_number_value,'location_id',case when o.location_id is null then null else o.location_id::text end,
    'group_code',o.location_code_snapshot,'group_name',o.location_name_snapshot,'location_group_code',o.location_code_snapshot,'location_group_name',o.location_name_snapshot,
    'location_name',o.location_name_snapshot,'included_locations',jsonb_build_array(o.location_name_snapshot),
    'coverage_start',to_char(o.coverage_start,'HH24:MI'),'coverage_end',to_char(o.coverage_end,'HH24:MI'),'start_time',to_char(o.coverage_start,'HH24:MI'),'end_time',to_char(o.coverage_end,'HH24:MI'),
    'coverage_purpose',coalesce(nullif(o.authority_facts_json#>>'{work_snapshot,coveragePurpose}',''),nullif(o.authority_facts_json#>>'{work_snapshot,purpose}',''),'area_owner'),'purpose',coalesce(nullif(o.authority_facts_json#>>'{work_snapshot,coveragePurpose}',''),nullif(o.authority_facts_json#>>'{work_snapshot,purpose}',''),'area_owner'),
    'section_title',case coalesce(nullif(o.authority_facts_json#>>'{work_snapshot,coveragePurpose}',''),nullif(o.authority_facts_json#>>'{work_snapshot,purpose}',''),'area_owner') when 'area_owner' then 'Primary area coverage' when 'restroom_upkeep' then 'Restroom upkeep' when 'deep_clean' then 'Deep cleaning' when 'late_coverage' then 'Late coverage' when 'lunch_coverage' then 'Lunch coverage' else initcap(replace(coalesce(nullif(o.authority_facts_json#>>'{work_snapshot,coveragePurpose}',''),nullif(o.authority_facts_json#>>'{work_snapshot,purpose}',''),'assigned coverage'),'_',' ')) end,
    'source_type','static_weekly_projection','owner_type','EMPLOYEE','status','ASSIGNED','load_points',coalesce((o.authority_facts_json#>>'{work_snapshot,serviceEffortMinutes}')::numeric,1),'notes',null,
    'is_public_restroom',(lower(o.location_name_snapshot) like '%restroom%' or lower(o.location_name_snapshot) like '%bathroom%')
  ) order by o.coverage_start,o.coverage_end,o.location_name_snapshot,o.work_id),'[]'::jsonb) into v_items
  from (select occurrence.*,row_number() over(order by coverage_start,coverage_end,location_name_snapshot,work_id) as row_number_value from public.weekly_schedule_occurrences occurrence where occurrence.projection_id=v_projection and occurrence.service_date=p_service_date and occurrence.owner_person_id_snapshot=p_employee_id and occurrence.state='created') o;
  v_local_date:=(p_now at time zone 'America/Chicago')::date; v_local_time:=(p_now at time zone 'America/Chicago')::time;
  if v_local_date=p_service_date then select coalesce(jsonb_agg(item order by ordinal),'[]'::jsonb) into v_current from jsonb_array_elements(v_items) with ordinality current_item(item,ordinal) where (item->>'coverage_start')::time<=v_local_time and v_local_time<(item->>'coverage_end')::time; end if;
  if v_employee.active is not true or coalesce(v_staffing_state,'working')<>'working' or v_shift_start is null or v_shift_end is null then v_phase:='off_day'; v_notice:='You are not scheduled to work today.';
  elsif jsonb_array_length(v_items)=0 then v_phase:='schedule_missing'; v_notice:='Your shift is active, but no assignments were published. Contact a Custodial Manager.';
  elsif v_local_date<p_service_date or (v_local_date=p_service_date and v_local_time<v_shift_start) then v_phase:='before_shift'; v_notice:=format('Your assigned areas are below. Your shift begins at %s.',to_char(v_shift_start,'FMHH12:MI AM'));
  elsif v_local_date>p_service_date or (v_local_date=p_service_date and v_local_time>=v_shift_end) then v_phase:='after_shift'; v_notice:='Your shift is complete. Today''s assigned areas remain below.';
  elsif jsonb_array_length(v_current)=0 then v_phase:='between_assignments'; v_notice:='No coverage window is active at this moment. Your assigned areas remain below.';
  else v_phase:='assigned_areas'; v_notice:='Your assigned areas are shown below. Choose the practical cleaning order.'; end if;
  return jsonb_build_object('ok',true,'governed',true,'source','static_weekly_projection','contract_version','static-weekly-employee-day.v1','service_date',p_service_date::text,'week_start',v_week_start::text,'publication_id',v_publication::text,'projection_id',v_projection::text,'projection_status',v_status,'projection_authority_revision',v_projection_revision,'staffing_authority_revision',v_staffing_revision,'employee_id',v_employee.id::text,'employee_name',v_employee.display_name,'employee_code',v_employee.employee_code,'employee',jsonb_build_object('id',v_employee.id::text,'display_name',v_employee.display_name,'employee_code',v_employee.employee_code),'shift',case when v_shift_start is null or v_shift_end is null then null else jsonb_build_object('start',to_char(v_shift_start,'HH12:MI AM'),'end',to_char(v_shift_end,'HH12:MI AM'),'shift_start',to_char(v_shift_start,'HH24:MI'),'shift_end',to_char(v_shift_end,'HH24:MI'),'active',v_employee.active and coalesce(v_staffing_state,'working')='working') end,'phase',v_phase,'notice',v_notice,'items',v_current,'all_items',v_items,'current_items',v_current,'assignment_count',jsonb_array_length(v_items),'schedule_status',case when v_phase='off_day' then 'off' when v_phase='schedule_missing' then 'missing_assignments' when v_phase='after_shift' then 'completed' when v_phase='between_assignments' then 'between_assignments' else 'scheduled' end);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v5_registered_source_identity(p_source jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_identity jsonb;
  v_version jsonb;
  v_slots jsonb;
  v_availability jsonb;
begin
  if jsonb_typeof(p_source) is distinct from 'object'
    or coalesce(p_source->'exceptions','[]'::jsonb)<>'[]'::jsonb then
    raise exception using errcode='23514',message='registered scheduler source must be one exception-free recurring compiler input';
  end if;
  if jsonb_typeof(p_source->'version')='object' then
    v_version:=p_source->'version';
  elsif jsonb_typeof(p_source->'versions')='array'
    and jsonb_array_length(p_source->'versions')=1 then
    v_version:=(p_source->'versions')->0;
  else
    raise exception using errcode='23514',message='registered scheduler source must carry exactly one recurring version';
  end if;
  v_version:=v_version-'id'-'publicationId'-'status'-'effectiveStart'-'effectiveEnd'-'vacantSlotIds';
  if jsonb_typeof(v_version->'slotAvailability') is distinct from 'array' then
    raise exception using errcode='23514',message='registered scheduler source must retain recurring slot availability templates';
  end if;
  select coalesce(jsonb_agg(item-'status' order by ordinal),'[]'::jsonb)
    into v_availability
  from jsonb_array_elements(v_version->'slotAvailability')
       with ordinality as availability(item,ordinal);
  v_version:=jsonb_set(v_version,'{slotAvailability}',v_availability,true);
  v_identity:=p_source-'serviceDate'-'exceptions'-'version'-'versions';
  if jsonb_typeof(v_identity->'slots') is distinct from 'array' then
    raise exception using errcode='23514',message='registered scheduler source must carry stable roster slots';
  end if;
  select coalesce(jsonb_agg(slot-'incumbencies' order by ordinal),'[]'::jsonb)
    into v_slots
  from jsonb_array_elements(v_identity->'slots')
       with ordinality as roster(slot,ordinal);
  v_identity:=jsonb_set(v_identity,'{slots}',v_slots,true);
  return jsonb_set(v_identity,'{version}',v_version,true);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v5_source_availability_template(p_slot_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_source jsonb; v_version jsonb; v_rows jsonb;
begin
  select d.canonical_source into v_source
  from public.static_weekly_authority_source_documents d
  join public.weekly_schedule_versions v on v.authority_source_id=d.source_id
  where v.lifecycle_state='published' and d.active=true and d.retired_at is null
    and exists(select 1 from jsonb_array_elements(d.canonical_source->'slots') slot where slot->>'id'=p_slot_id::text)
  order by v.published_at desc,v.version_id desc limit 1;
  if jsonb_typeof(v_source->'version')='object' then v_version:=v_source->'version';
  elsif jsonb_typeof(v_source->'versions')='array' and jsonb_array_length(v_source->'versions')=1 then v_version:=(v_source->'versions')->0;
  end if;
  select coalesce(jsonb_agg(item order by ordinal),'[]'::jsonb) into v_rows
  from jsonb_array_elements(coalesce(v_version->'slotAvailability','[]'::jsonb)) with ordinality as a(item,ordinal)
  where item->>'slotId'=p_slot_id::text;
  if jsonb_array_length(coalesce(v_rows,'[]'::jsonb))=0 then
    raise exception using errcode='23514',message='employee turnover requires a verified recurring availability template for the stable slot';
  end if;
  return v_rows;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v6_assert_document_attestation(p_document jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_attestation jsonb:=p_document->'attestation';
  v_key public.static_weekly_authority_attestation_keys%rowtype;
  v_digest text:=public.static_weekly_v6_document_identity(p_document);
  v_expected text;
begin
  perform public.static_weekly_assert_exact_object(v_attestation,
    array['schema','key_id','scope','payload_digest','signature'],
    array['schema','key_id','scope','payload_digest','signature'],'authority attestation');
  if v_attestation->>'schema' is distinct from 'memphis-zoo.static-weekly-authority-attestation.v3'
    or v_attestation->>'scope' is distinct from 'recurring_document'
    or v_attestation->>'payload_digest' is distinct from v_digest
    or v_digest is distinct from p_document#>>'{validation,database_document_identity}'
    or jsonb_typeof(v_attestation->'key_id') is distinct from 'string'
    or jsonb_typeof(v_attestation->'signature') is distinct from 'string'
    or coalesce(v_attestation->>'signature','') !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='23514',message='complete memory-bounded document attestation is required';
  end if;
  select * into v_key
  from public.static_weekly_authority_attestation_keys
  where key_id=v_attestation->>'key_id' and key_state in ('active','overlap')
    and activates_at<=statement_timestamp()
    and (verify_not_after is null or verify_not_after>statement_timestamp())
  for share;
  if not found then
    raise exception using errcode='23514',message='authority attestation key is unknown, expired, or revoked';
  end if;
  v_expected:=public.static_weekly_v3_hmac(v_key.secret_material,'recurring_document',jsonb_build_object('payload_digest',v_digest));
  if not public.static_weekly_v3_constant_time_equal(decode(v_attestation->>'signature','hex'),decode(v_expected,'hex')) then
    raise exception using errcode='23514',message='document attestation does not bind the complete Merkle identity';
  end if;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v6_initialize_registered_roster(p_source_id uuid, p_manager_id uuid, p_configured_by text DEFAULT 'production-manager'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_source jsonb;
  v_slots jsonb;
  v_vacancy_version jsonb;
  v_slot jsonb;
  v_incumbencies jsonb;
  v_incumbent jsonb;
  v_actor jsonb;
  v_slot_id uuid;
  v_person_id uuid;
  v_effective_start date;
  v_effective_end date;
  v_slot_code text;
  v_expected_slots integer:=0;
  v_expected_incumbencies integer:=0;
  v_existing_slots integer:=0;
  v_existing_incumbencies integer:=0;
  v_mismatch boolean:=false;
begin
  perform public.static_weekly_v3_assert_release_operator();
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-initial-roster',0));
  v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
  if p_source_id is null or nullif(btrim(coalesce(p_configured_by,'')),'') is null or length(p_configured_by)>200 then
    raise exception using errcode='22023',message='registered roster bootstrap requires a source, named manager, and bounded release owner';
  end if;

  select canonical_source into v_source
  from public.static_weekly_authority_source_documents
  where source_id=p_source_id and active=true and retired_at is null
  for share;
  if not found then
    raise exception using errcode='23514',message='registered roster bootstrap requires one active immutable authority source';
  end if;
  v_slots:=v_source->'slots';
  if jsonb_typeof(v_slots) is distinct from 'array' or jsonb_array_length(v_slots)=0 or jsonb_array_length(v_slots)>256 then
    raise exception using errcode='23514',message='registered roster bootstrap source must contain a bounded nonempty stable-slot set';
  end if;

  -- Validate the complete registered source before deciding between initial
  -- insertion and the exact idempotent replay path.
  for v_slot in select value from jsonb_array_elements(v_slots) loop
    perform public.static_weekly_v3_assert_uuid(v_slot->'id','registered roster slot id');
    perform public.static_weekly_v3_assert_text(v_slot->'label','registered roster slot label',200);
    v_incumbencies:=v_slot->'incumbencies';
    if v_slot->>'kind'='CONTRACTOR_CAPACITY' then perform public.static_weekly_capacity_assert_shape(v_slot); end if;
    if jsonb_typeof(v_incumbencies) is distinct from 'array' or jsonb_array_length(v_incumbencies)>64 then
      raise exception using errcode='23514',message='each registered roster slot requires bounded immutable incumbency history';
    end if;
    if jsonb_array_length(v_incumbencies)=0 and v_slot->>'kind' is distinct from 'CONTRACTOR_CAPACITY' then
      -- Only an ordinary stable slot explicitly declared vacant AND capable
      -- may have never held an incumbent. No person or history is synthesized.
      if v_slot ? 'kind' or v_slot ? 'contractorCapacity' or v_slot ? 'capacityId' then
        raise exception using errcode='23514',message='empty ordinary roster history requires an explicit stable vacancy';
      end if;
      v_vacancy_version:=null;
      if jsonb_typeof(v_source->'version')='object' and not (v_source ? 'versions') then
        v_vacancy_version:=v_source->'version';
      elsif not (v_source ? 'version') and jsonb_typeof(v_source->'versions')='array' then
        if jsonb_array_length(v_source->'versions')=1
          and jsonb_typeof(v_source->'versions'->0)='object' then
          v_vacancy_version:=v_source->'versions'->0;
        end if;
      end if;
      if v_vacancy_version is null
        or jsonb_typeof(v_vacancy_version->'vacantSlotIds') is distinct from 'array'
        or jsonb_typeof(v_vacancy_version->'vacancyCapableSlotIds') is distinct from 'array' then
        raise exception using errcode='23514',message='empty ordinary roster history requires exact vacancy declarations';
      end if;
      if jsonb_array_length(v_vacancy_version->'vacantSlotIds') not between 1 and 256
        or jsonb_array_length(v_vacancy_version->'vacancyCapableSlotIds') not between 1 and 256
        or not (v_vacancy_version->'vacantSlotIds' @> jsonb_build_array(v_slot->'id'))
        or not (v_vacancy_version->'vacancyCapableSlotIds' @> jsonb_build_array(v_slot->'id')) then
        raise exception using errcode='23514',message='empty ordinary roster history requires declared vacant and vacancy-capable identity';
      end if;
      -- Reject malformed/duplicate/foreign declarations, not just a matching
      -- substring, object key, or a caller-coerced representation.
      if exists(
        select 1 from jsonb_array_elements((v_vacancy_version->'vacantSlotIds')
          ||(v_vacancy_version->'vacancyCapableSlotIds')) entry
        where jsonb_typeof(entry) is distinct from 'string'
          or not exists(select 1 from jsonb_array_elements(v_slots) slot where slot->'id'=entry)
      ) or jsonb_array_length(v_vacancy_version->'vacantSlotIds')<>
        (select count(distinct entry) from jsonb_array_elements(v_vacancy_version->'vacantSlotIds') entry)
        or jsonb_array_length(v_vacancy_version->'vacancyCapableSlotIds')<>
        (select count(distinct entry) from jsonb_array_elements(v_vacancy_version->'vacancyCapableSlotIds') entry)
        or exists(select 1 from jsonb_array_elements(v_vacancy_version->'vacantSlotIds') entry
          where not (v_vacancy_version->'vacancyCapableSlotIds' @> jsonb_build_array(entry))) then
        raise exception using errcode='23514',message='empty ordinary roster history has malformed vacancy declarations';
      end if;
    end if;
    v_expected_slots:=v_expected_slots+1;
    for v_incumbent in select value from jsonb_array_elements(v_incumbencies) loop
      perform public.static_weekly_v3_assert_uuid(v_incumbent->'personId','registered roster incumbent person id');
      perform public.static_weekly_v3_assert_text(v_incumbent->'displayName','registered roster incumbent name',200);
      perform public.static_weekly_v3_assert_text(v_incumbent->'effectiveStart','registered roster effective start',10);
      if (v_incumbent->>'effectiveStart') !~ '^\d{4}-\d{2}-\d{2}$' then
        raise exception using errcode='23514',message='registered roster effective start must be YYYY-MM-DD';
      end if;
      v_effective_start:=(v_incumbent->>'effectiveStart')::date;
      v_effective_end:=null;
      if nullif(v_incumbent->>'effectiveEnd','') is not null then
        if (v_incumbent->>'effectiveEnd') !~ '^\d{4}-\d{2}-\d{2}$' then
          raise exception using errcode='23514',message='registered roster effective end must be YYYY-MM-DD or null';
        end if;
        v_effective_end:=(v_incumbent->>'effectiveEnd')::date;
        if v_effective_end<=v_effective_start then
          raise exception using errcode='23514',message='registered roster incumbency end must follow its start';
        end if;
      end if;
      v_expected_incumbencies:=v_expected_incumbencies+1;
    end loop;
  end loop;
  if v_expected_slots<>(select count(distinct value->>'id') from jsonb_array_elements(v_slots)) then
    raise exception using errcode='23514',message='registered roster source contains duplicate stable-slot identities';
  end if;

  select count(*) into v_existing_slots from public.weekly_roster_slots;
  select count(*) into v_existing_incumbencies from public.weekly_roster_slot_incumbencies;
  if v_existing_slots<>0 or v_existing_incumbencies<>0 then
    if v_existing_slots<>v_expected_slots or v_existing_incumbencies<>v_expected_incumbencies then
      raise exception using errcode='23514',message='registered roster bootstrap refuses partial or unrelated existing roster state';
    end if;
    for v_slot in select value from jsonb_array_elements(v_slots) loop
      v_slot_id:=(v_slot->>'id')::uuid;
      v_slot_code:='STATIC_'||upper(replace(v_slot_id::text,'-',''));
      if not exists(
        select 1 from public.weekly_roster_slots s
        where s.slot_id=v_slot_id and s.slot_code=v_slot_code and s.slot_label=v_slot->>'label'
      ) then v_mismatch:=true; exit; end if;
      if v_slot->>'kind'='CONTRACTOR_CAPACITY' and not public.static_weekly_capacity_registered(v_slot) then v_mismatch:=true; exit; end if;
      for v_incumbent in select value from jsonb_array_elements(v_slot->'incumbencies') loop
        v_person_id:=(v_incumbent->>'personId')::uuid;
        v_effective_start:=(v_incumbent->>'effectiveStart')::date;
        v_effective_end:=nullif(v_incumbent->>'effectiveEnd','')::date;
        if not exists(
          select 1 from public.weekly_roster_slot_incumbencies i
          where i.slot_id=v_slot_id and i.person_id=v_person_id
            and i.person_name_snapshot=v_incumbent->>'displayName'
            and i.effective_start=v_effective_start
            and i.effective_end is not distinct from v_effective_end
        ) then v_mismatch:=true; exit; end if;
      end loop;
      exit when v_mismatch;
    end loop;
    if v_mismatch then
      raise exception using errcode='23514',message='registered roster bootstrap refuses roster state that differs from the immutable source';
    end if;
    return jsonb_build_object(
      'source_id',p_source_id::text,
      'source_digest',public.static_weekly_digest_jsonb(v_source),
      'slot_count',v_expected_slots,
      'incumbency_count',v_expected_incumbencies,
      'already_initialized',true
    );
  end if;

  for v_slot in select value from jsonb_array_elements(v_slots) loop
    v_slot_id:=(v_slot->>'id')::uuid;
    v_slot_code:='STATIC_'||upper(replace(v_slot_id::text,'-',''));
    insert into public.weekly_roster_slots(
      slot_id,slot_code,slot_label,created_by_manager_id,created_by_manager_name_snapshot,content_digest
    ) values(
      v_slot_id,v_slot_code,v_slot->>'label',p_manager_id,v_actor->>'manager_name',
      public.static_weekly_digest_jsonb(jsonb_build_object(
        'source_id',p_source_id::text,'slot_id',v_slot_id::text,'slot_code',v_slot_code,'slot_label',v_slot->>'label'
      ))
    );
    if v_slot->>'kind'='CONTRACTOR_CAPACITY' then
      insert into public.static_weekly_contractor_capacity_registrations(
       capacity_slot_id,capacity_code,source_id,source_digest,slot_snapshot,slot_digest,registered_by_manager_id,manager_name_snapshot)
      values(v_slot_id,v_slot->>'label',p_source_id,public.static_weekly_digest_jsonb(v_source),v_slot,
       public.static_weekly_digest_jsonb(v_slot),p_manager_id,v_actor->>'manager_name');
    end if;
    for v_incumbent in select value from jsonb_array_elements(v_slot->'incumbencies') loop
      v_person_id:=(v_incumbent->>'personId')::uuid;
      v_effective_start:=(v_incumbent->>'effectiveStart')::date;
      v_effective_end:=nullif(v_incumbent->>'effectiveEnd','')::date;
      insert into public.weekly_roster_slot_incumbencies(
        slot_id,person_id,person_name_snapshot,effective_start,effective_end,
        created_by_manager_id,created_by_manager_name_snapshot,content_digest
      ) values(
        v_slot_id,v_person_id,v_incumbent->>'displayName',v_effective_start,v_effective_end,
        p_manager_id,v_actor->>'manager_name',
        public.static_weekly_digest_jsonb(jsonb_build_object(
          'source_id',p_source_id::text,'slot_id',v_slot_id::text,'person_id',v_person_id::text,
          'person_name_snapshot',v_incumbent->>'displayName','effective_start',v_effective_start::text,
          'effective_end',case when v_effective_end is null then null else to_jsonb(v_effective_end::text) end
        ))
      );
    end loop;
  end loop;

  return jsonb_build_object(
    'source_id',p_source_id::text,
    'source_digest',public.static_weekly_digest_jsonb(v_source),
    'slot_count',v_expected_slots,
    'incumbency_count',v_expected_incumbencies,
    'already_initialized',false,
    'configured_by',left(p_configured_by,200),
    'manager_id',p_manager_id::text,
    'manager_name',v_actor->>'manager_name'
  );
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v6_schedule_authority_state_dated_base(p_service_date date)
 RETURNS TABLE(service_date date, governed boolean, authority_source text, projection_status text, version_id uuid, publication_id uuid, projection_id uuid, projection_authority_revision bigint, staffing_authority_revision bigint, week_start date)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_version_id uuid;
  v_publication_id uuid;
  v_projection_id uuid;
  v_projection_revision bigint;
  v_staffing_revision bigint;
  v_week_start date;
  v_status text;
begin
  if p_service_date is null then
    raise exception using errcode = '22023', message = 'service_date is required';
  end if;

  v_version_id := public.static_weekly_effective_version(p_service_date);
  if v_version_id is null then
    return query select p_service_date, false, 'legacy_daily_schedule'::text,
      'legacy_ungoverned'::text, null::uuid, null::uuid, null::uuid,
      null::bigint, null::bigint, null::date;
    return;
  end if;

  v_week_start := public.static_weekly_projection_window_start(p_service_date);
  select p.publication_id
    into v_publication_id
  from public.weekly_schedule_publications p
  where p.version_id = v_version_id
  order by p.authority_revision desc, p.published_at desc, p.publication_id desc
  limit 1;

  if v_publication_id is null then
    return query select p_service_date, true, 'static_weekly_projection'::text,
      'missing_publication'::text, v_version_id, null::uuid, null::uuid,
      null::bigint, null::bigint, v_week_start;
    return;
  end if;


  if exists(select 1 from public.static_weekly_recurring_invalidations i
    where i.publication_id=v_publication_id and i.effective_start<=p_service_date
      and (i.effective_end is null or p_service_date<i.effective_end)) then
    return query select p_service_date,true,'static_weekly_projection'::text,
      'blocked_recurring_authority'::text,v_version_id,v_publication_id,null::uuid,
      (select max(i.authority_revision) from public.static_weekly_recurring_invalidations i
        where i.publication_id=v_publication_id and i.effective_start<=p_service_date
          and (i.effective_end is null or p_service_date<i.effective_end)),
      null::bigint,v_week_start;
    return;
  end if;
  select projection.projection_id, (receipt.response_json->>'revision')::bigint
    into v_projection_id, v_projection_revision
  from public.weekly_schedule_compiled_projections projection
  join public.weekly_schedule_command_receipts receipt
    on receipt.command_type = 'materialize_projection'
   and receipt.response_json#>>'{data,projection_id}' = projection.projection_id::text
  where projection.publication_id = v_publication_id
    and projection.week_start = v_week_start
    and projection.exception_set_digest = public.static_weekly_digest_jsonb(
      public.static_weekly_accepted_exception_set(v_publication_id, v_week_start)
    )
  order by (receipt.response_json->>'revision')::bigint desc,
           receipt.command_id desc,
           projection.compiled_at desc,
           projection.projection_id desc
  limit 1;

  select max(staffing.authority_revision)
    into v_staffing_revision
  from public.weekly_roster_slot_staffing_states staffing
  where staffing.effective_start <= v_week_start + 6;

  if v_projection_id is null or v_projection_revision is null then
    v_status := 'missing_projection';
  elsif v_staffing_revision is not null and v_projection_revision <= v_staffing_revision then
    v_status := 'stale_staffing_change';
  else
    v_status := 'current';
  end if;

  return query select p_service_date, true, 'static_weekly_projection'::text,
    v_status, v_version_id, v_publication_id, v_projection_id,
    v_projection_revision, v_staffing_revision, v_week_start;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v7_create_vacant_roster_slot(p_slot_id uuid, p_slot_label text, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_actor jsonb; v_prior public.weekly_schedule_command_receipts%rowtype;
  v_label text:=regexp_replace(btrim(coalesce(p_slot_label,'')),'\s+',' ','g');
  v_code text; v_request jsonb; v_request_digest text; v_content_digest text;
  v_command uuid:=gen_random_uuid(); v_revision bigint; v_response jsonb;
begin
  perform public.static_weekly_v3_assert_control_plane(); v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_manager_id,v_actor->>'manager_name',p_idempotency_key,'create_vacant_slot');
  if p_slot_id is null or length(v_label) not between 2 and 200 then raise exception using errcode='22023',message='vacant roster position requires a stable UUID and label'; end if;
  v_code:='STATIC_'||upper(replace(p_slot_id::text,'-',''));
  v_request:=jsonb_build_object('operation','create_vacant_slot','slot_id',p_slot_id,'slot_code',v_code,'slot_label',v_label,'expected_revision',p_expected_revision,'actor_manager_id',p_manager_id);
  v_request_digest:=public.static_weekly_digest_jsonb(v_request); perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts where actor_manager_id=p_manager_id and idempotency_key=p_idempotency_key;
  if found then if v_prior.request_digest<>v_request_digest then raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs'; end if; return v_prior.response_json; end if;
  if exists(select 1 from public.weekly_roster_slots where slot_id=p_slot_id or slot_code=v_code) then raise exception using errcode='23505',message='stable roster position already exists'; end if;
  v_content_digest:=public.static_weekly_digest_jsonb(v_request-'expected_revision'-'actor_manager_id'-'operation');
  v_revision:=public.static_weekly_advance_authority(p_expected_revision,'create_vacant_slot',p_manager_id,v_actor->>'manager_name',v_command,v_content_digest);
  insert into public.weekly_roster_slots(slot_id,slot_code,slot_label,created_by_manager_id,created_by_manager_name_snapshot,content_digest)
  values(p_slot_id,v_code,v_label,p_manager_id,v_actor->>'manager_name',v_content_digest);
  v_response:=public.static_weekly_response_json('create_vacant_slot',v_revision,v_content_digest,v_request_digest,jsonb_build_object('slot_id',p_slot_id,'slot_code',v_code,'slot_label',v_label,'vacant',true));
  insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest)
  values(v_command,p_manager_id,v_actor->>'manager_name','create_vacant_slot',p_idempotency_key,p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest);
  return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v7_fill_vacant_roster_slot(p_slot_id uuid, p_new_employee_name text, p_effective_start date, p_reason text, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_actor jsonb; v_prior public.weekly_schedule_command_receipts%rowtype; v_slot public.weekly_roster_slots%rowtype;
  v_name text:=regexp_replace(btrim(coalesce(p_new_employee_name,'')),'\s+',' ','g');
  v_request jsonb; v_request_digest text; v_content_digest text; v_command uuid:=gen_random_uuid();
  v_revision bigint; v_response jsonb; v_created jsonb; v_employee_id uuid; v_incumbency uuid:=gen_random_uuid();
  v_current_week date:=public.sch_service_date(statement_timestamp())-(extract(isodow from public.sch_service_date(statement_timestamp()))::integer-1);
begin
  perform public.static_weekly_v3_assert_control_plane(); v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_manager_id,v_actor->>'manager_name',p_idempotency_key,'fill_vacant_slot');
  if p_slot_id is null or length(v_name) not between 2 and 160 or p_effective_start is null
    or extract(isodow from p_effective_start)::integer<>1
    or nullif(btrim(coalesce(p_reason,'')),'') is null or char_length(p_reason)>500 or p_reason~'[\x00-\x1f\x7f]' then
    raise exception using errcode='23514',message='filling a vacancy requires a stable slot, fresh employee name, Monday effective date, and bounded reason';
  end if;
  v_request:=jsonb_build_object('operation','fill_vacant_slot','slot_id',p_slot_id,'new_employee_name',v_name,'effective_start',p_effective_start,'reason',p_reason,'expected_revision',p_expected_revision,'actor_manager_id',p_manager_id);
  v_request_digest:=public.static_weekly_digest_jsonb(v_request); perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts where actor_manager_id=p_manager_id and idempotency_key=p_idempotency_key;
  if found then if v_prior.request_digest<>v_request_digest then raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs'; end if; return v_prior.response_json; end if;
  -- A receipt is permanent semantic evidence. Time-dependent new-operation
  -- eligibility must never hide a successful response after its week ends.
  if p_effective_start<v_current_week then
    raise exception using errcode='23514',message='a new vacancy fill cannot start before the current week';
  end if;
  select * into v_slot from public.weekly_roster_slots where slot_id=p_slot_id for share;
  if not found then raise exception using errcode='P0002',message='vacant stable roster position was not found'; end if;
  -- A vacated position is reusable; reject any overlapping or future incumbent.
  if exists(select 1 from public.v_weekly_roster_slot_incumbency_ranges
      where slot_id=p_slot_id and (effective_end is null or p_effective_start<effective_end))
    or (exists(select 1 from public.weekly_roster_slot_incumbencies where slot_id=p_slot_id)
      and not exists(select 1 from public.weekly_roster_slot_staffing_states s
        where s.slot_id=p_slot_id and s.effective_start<=p_effective_start
          and s.staffing_state='vacant_unfilled' and s.employee_id is null
          and not exists(select 1 from public.weekly_roster_slot_staffing_states later
            where later.slot_id=p_slot_id and later.effective_start<=p_effective_start
              and (later.effective_start,later.authority_revision)>(s.effective_start,s.authority_revision)))) then
    raise exception using errcode='23514',message='only a never-filled or explicitly vacated stable position with no current or future incumbent can be filled';
  end if;
  v_created:=public.static_weekly_v5_create_replacement_employee(v_name,p_manager_id);
  v_employee_id:=(v_created#>>'{employee,id}')::uuid;
  v_content_digest:=public.static_weekly_digest_jsonb(v_request-'expected_revision'-'actor_manager_id'-'operation');
  v_revision:=public.static_weekly_advance_authority(p_expected_revision,'fill_vacant_slot',p_manager_id,v_actor->>'manager_name',v_command,v_content_digest);
  insert into public.weekly_roster_slot_incumbencies(incumbency_id,slot_id,person_id,person_name_snapshot,effective_start,created_by_manager_id,created_by_manager_name_snapshot,content_digest)
  values(v_incumbency,p_slot_id,v_employee_id,v_name,p_effective_start,p_manager_id,v_actor->>'manager_name',v_content_digest);
  insert into public.weekly_roster_slot_staffing_states(slot_id,employee_id,staffing_state,effective_start,authority_revision,actor_manager_id,actor_manager_name_snapshot,reason,content_digest)
  values(p_slot_id,v_employee_id,'working',p_effective_start,v_revision,p_manager_id,v_actor->>'manager_name',p_reason,v_content_digest);
  v_response:=public.static_weekly_response_json('fill_vacant_slot',v_revision,v_content_digest,v_request_digest,jsonb_build_object(
    'slot_id',p_slot_id,'slot_label',v_slot.slot_label,'new_employee_id',v_employee_id,'new_employee_name',v_name,
    'new_employee_code',v_created#>>'{employee,employee_code}','effective_start',p_effective_start,'phone_assignment',null
  ));
  insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest)
  values(v_command,p_manager_id,v_actor->>'manager_name','fill_vacant_slot',p_idempotency_key,p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest);
  return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v8_assert_lunch_document(p_projection_id uuid, p_document jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
 projection public.weekly_schedule_compiled_projections%rowtype;
 loan jsonb;responsibility jsonb;segment jsonb;intent jsonb;availability jsonb;helper jsonb;
 base_work jsonb;expected jsonb;actual jsonb;helper_id text;identity_key text;
 start_time time;end_time time;
 projection_availability jsonb;projection_assignments jsonb;projection_work jsonb;
 full_hour_policy jsonb;full_hour boolean;planned_loan jsonb;normal_segment_window jsonb;
begin
 perform public.static_weekly_assert_exact_object(p_document,
  array['schema','persistence_authority','verification_status','week_start','base_authority_digest','base_replay_digest','source_input_digest','candidate_digest','loans','responsibilities','notification_intents','semantic_snapshot','document_identity'],
  array['schema','persistence_authority','verification_status','week_start','base_authority_digest','base_replay_digest','source_input_digest','candidate_digest','loans','responsibilities','notification_intents','semantic_snapshot','document_identity'],'lunch document');
 select * into projection from public.weekly_schedule_compiled_projections where projection_id=p_projection_id;
 if not found then raise exception 'lunch projection is missing'; end if;
 if projection.projection_envelope#>>'{adapter,schema}'='custodial.approved-manual-period-database-adapter.v1' then
  perform public.static_weekly_manual_assert_native_lunch(p_projection_id,p_document,projection.projection_envelope,projection.publication_id,projection.week_start);return;end if;

 projection_availability:=projection.projection_envelope#>'{authority,projectionAvailability}';
 projection_assignments:=projection.projection_envelope->'assignments';
 projection_work:=projection.projection_envelope#>'{authority,overlayCompilerInput,version,assignments}';
 full_hour_policy:=projection.projection_envelope#>'{authority,compilerInput,version,lunchCoveragePolicy}';
 full_hour:=full_hour_policy is not null;
 if projection.projection_envelope#>'{authority,overlayCompilerInput,version,lunchCoveragePolicy}'
   is distinct from full_hour_policy then raise exception 'full lunch policy changed during projection';end if;
 if full_hour then
  perform public.static_weekly_assert_exact_object(full_hour_policy,
   array['schema','sourceDigest','loans','policyDigest'],array['schema','sourceDigest','loans','policyDigest'],'full lunch policy');
  if full_hour_policy->>'schema' is distinct from 'memphis-zoo.static-weekly-full-hour-lunch-policy.v1'
   or jsonb_typeof(full_hour_policy->'sourceDigest') is distinct from 'string'
   or coalesce(full_hour_policy->>'sourceDigest','') !~ '^[0-9a-f]{64}$'
   or full_hour_policy->>'policyDigest' is distinct from public.static_weekly_digest_jsonb(full_hour_policy-'policyDigest')
   or jsonb_typeof(full_hour_policy->'loans') is distinct from 'array'
   or jsonb_array_length(full_hour_policy->'loans')>1792 then raise exception 'invalid full lunch source policy';end if;
  for planned_loan in select value from jsonb_array_elements(full_hour_policy->'loans') loop
   perform public.static_weekly_assert_exact_object(planned_loan,
    array['dayOfWeek','normalOwnerSlotId','window','areas'],array['dayOfWeek','normalOwnerSlotId','window','areas'],'full lunch source loan');
   perform public.static_weekly_v3_assert_window(planned_loan->'window','full lunch source window');
   if jsonb_typeof(planned_loan->'dayOfWeek') is distinct from 'number'
    or (planned_loan->>'dayOfWeek') !~ '^[0-6]$'
    or jsonb_typeof(planned_loan->'normalOwnerSlotId') is distinct from 'string'
    or length(planned_loan->>'normalOwnerSlotId') not between 1 and 512
    or jsonb_typeof(planned_loan->'areas') is distinct from 'array'
    or jsonb_array_length(planned_loan->'areas')>128 then raise exception 'invalid full lunch source owner or areas';end if;
  end loop;
  select coalesce(jsonb_agg(entry order by entry::text),'[]') into expected from
   (select jsonb_build_array(value->'dayOfWeek',value->'normalOwnerSlotId') entry
    from jsonb_array_elements(full_hour_policy->'loans')) q;
  select coalesce(jsonb_agg(entry order by entry::text),'[]') into actual from
   (select jsonb_build_array(value->'day_of_week',value->'normal_owner_slot_id') entry
    from jsonb_array_elements(p_document->'loans')) q;
  if expected is distinct from actual then raise exception 'full lunch source owner set changed';end if;
 end if;

 if p_document->>'schema' is distinct from 'memphis-zoo.static-weekly-lunch-authority-document.v1'
  or p_document->>'persistence_authority' is distinct from 'NOT_PERSISTED'
  or p_document->>'verification_status' is distinct from 'VERIFIED'
  or p_document->>'week_start' is distinct from projection.week_start::text
  or p_document->>'base_authority_digest' is distinct from projection.authority_digest
  or p_document->>'base_replay_digest' is distinct from projection.replay_digest
  or p_document->>'source_input_digest' is distinct from projection.projection_envelope#>>'{authority,inputDigest}'
  or coalesce(p_document->>'candidate_digest','') !~ '^[0-9a-f]{64}$'
  or p_document->>'document_identity' is distinct from public.static_weekly_digest_jsonb(p_document-'document_identity') then
  raise exception 'lunch document is not bound to the exact verified projection';
 end if;
 foreach identity_key in array array['loans','responsibilities','notification_intents'] loop
  if jsonb_typeof(p_document->identity_key) is distinct from 'array'
   or jsonb_array_length(p_document->identity_key)>4096 then raise exception 'lunch document array invalid'; end if;
 end loop;
 expected:=jsonb_build_object('schema','memphis-zoo.static-weekly-lunch-semantic-snapshot.v1',
  'loans_digest',public.static_weekly_digest_jsonb(p_document->'loans'),
  'responsibilities_digest',public.static_weekly_digest_jsonb(p_document->'responsibilities'),
  'notification_intents_digest',public.static_weekly_digest_jsonb(p_document->'notification_intents'));
 if p_document->'semantic_snapshot' is distinct from expected then raise exception 'lunch semantic snapshot mismatch'; end if;
 if (select count(*)<>count(distinct value->>'loan_id') from jsonb_array_elements(p_document->'loans'))
 or (select count(*)<>count(distinct value->>'responsibility_id') from jsonb_array_elements(p_document->'responsibilities'))
 or (select count(*)<>count(distinct value->>'notification_key') from jsonb_array_elements(p_document->'notification_intents')) then
  raise exception 'duplicate or missing lunch record identity'; end if;
 select coalesce(jsonb_agg(jsonb_build_array(value->>'serviceDate',value->>'slotId') order by value->>'serviceDate',value->>'slotId'),'[]')
 into expected from jsonb_array_elements(projection_availability)
 where value->>'status'='working' and (nullif(value->>'incumbentPersonId','') is not null or value->>'ownerKind'='CONTRACTOR_CAPACITY')
  and (value->>'ownerKind'='CONTRACTOR_CAPACITY' and value->>'breakChoice'='NONE' and value->'lunch'='null'::jsonb) is not true;
 select coalesce(jsonb_agg(jsonb_build_array(value->>'service_date',value->>'normal_owner_slot_id') order by value->>'service_date',value->>'normal_owner_slot_id'),'[]')
 into actual from jsonb_array_elements(p_document->'loans');
 if actual is distinct from expected then raise exception 'lunch coverage omits or duplicates a working owner'; end if;
 for loan in select value from jsonb_array_elements(p_document->'loans') loop
  perform public.static_weekly_capacity_assert_lunch_party(p_projection_id,loan,'normal_owner');
  perform public.static_weekly_assert_exact_object(loan,
   case when loan ? 'normal_owner_capacity_id' then array['loan_id','service_date','day_of_week','normal_owner_slot_id','normal_owner_capacity_id','coverage_start','coverage_end','status','helper_slot_ids']
    else array['loan_id','service_date','day_of_week','normal_owner_slot_id','normal_owner_person_id','coverage_start','coverage_end','status','helper_slot_ids'] end,
   array['loan_id','service_date','day_of_week','normal_owner_slot_id','normal_owner_person_id','normal_owner_capacity_id','coverage_start','coverage_end','status','reason','helper_slot_ids','fallback','total_distance_minutes'],'lunch loan');
  if not (loan ?& array['reason','fallback','total_distance_minutes']) then raise exception 'lunch explanatory fields are missing'; end if;
  if coalesce(loan->>'loan_id','') !~ '^[0-9a-f]{64}$' then raise exception 'invalid lunch loan identity'; end if;
  select value into availability from jsonb_array_elements(projection_availability)
   where value->>'slotId'=loan->>'normal_owner_slot_id' and value->>'serviceDate'=loan->>'service_date';
  if not found or availability->>'incumbentPersonId' is distinct from loan->>'normal_owner_person_id'
   or loan->'day_of_week' is distinct from availability->'dayOfWeek'
   or loan->>'coverage_start' is distinct from availability#>>'{lunch,start}'
   or loan->>'coverage_end' is distinct from availability#>>'{lunch,end}' then raise exception 'lunch owner or scheduled hour mismatch'; end if;
  perform public.static_weekly_v3_assert_window(jsonb_build_object('start',loan->'coverage_start','end',loan->'coverage_end'),'lunch');
  start_time:=(loan->>'coverage_start')::time;end_time:=(loan->>'coverage_end')::time;
  if end_time<=start_time then raise exception 'accepted lunch end must follow its start'; end if;
  perform public.static_weekly_v3_assert_string_array(loan->'helper_slot_ids','lunch helpers');
  if ((loan->>'status'='NO_AREAS' and jsonb_array_length(loan->'helper_slot_ids')=0 and loan->'fallback'='null'::jsonb)
    or (loan->>'status'='PLANNED' and (
      (full_hour and jsonb_array_length(loan->'helper_slot_ids') between 1 and 2
        and (loan->'fallback'='null'::jsonb or (jsonb_array_length(loan->'helper_slot_ids')=1 and loan->>'fallback'='only_one_eligible_custodian')))
      or (not full_hour and ((jsonb_array_length(loan->'helper_slot_ids')=2 and loan->'fallback'='null'::jsonb)
        or (jsonb_array_length(loan->'helper_slot_ids')=1 and loan->>'fallback'='only_one_eligible_custodian')))))) is not true then
   raise exception 'lunch helper cardinality or fallback invalid'; end if;
  if full_hour then
   select value into strict planned_loan from jsonb_array_elements(full_hour_policy->'loans')
    where value->'dayOfWeek'=loan->'day_of_week' and value->'normalOwnerSlotId'=loan->'normal_owner_slot_id';
   if planned_loan->'window' is distinct from jsonb_build_object('start',loan->'coverage_start','end',loan->'coverage_end')
    then raise exception 'full lunch source window changed';end if;
   if loan->'helper_slot_ids' is distinct from (
     select coalesce(jsonb_agg(coverer order by coverer collate "C"),'[]'::jsonb)
     from (select distinct area->>'covererSlotId' coverer
       from jsonb_array_elements(planned_loan->'areas') area) named)
    then raise exception 'full lunch source coverer set changed';end if;
  end if;
  for helper_id in select jsonb_array_elements_text(loan->'helper_slot_ids') loop
   select value into helper from jsonb_array_elements(projection_availability)
    where value->>'slotId'=helper_id and value->>'serviceDate'=loan->>'service_date';
   if not found or helper->>'status' is distinct from 'working' or helper_id=loan->>'normal_owner_slot_id'
    or (nullif(helper->>'incumbentPersonId','') is null and helper->>'ownerKind' is distinct from 'CONTRACTOR_CAPACITY')
    or ((helper#>>'{lunch,start}' is null or helper#>>'{lunch,end}' is null)
      and (helper->>'ownerKind'='CONTRACTOR_CAPACITY' and helper->>'breakChoice'='NONE' and helper->'lunch'='null'::jsonb) is not true) or (helper#>>'{shift,start}')::time>start_time
    or (helper#>>'{shift,end}')::time<end_time
    or ((helper#>>'{lunch,start}')::time<end_time and start_time<(helper#>>'{lunch,end}')::time) then
    raise exception 'lunch helper is not available for the full scheduled hour'; end if;
   if not exists(select 1 from jsonb_array_elements(p_document->'responsibilities') r
     where r->>'loan_id'=loan->>'loan_id' and r->>'coverer_slot_id'=helper_id) then
    raise exception 'lunch helper has no assigned responsibility'; end if;
  end loop;
 end loop;
 for responsibility in select value from jsonb_array_elements(p_document->'responsibilities') loop
  perform public.static_weekly_capacity_assert_lunch_party(p_projection_id,responsibility,'normal_owner');
  perform public.static_weekly_capacity_assert_lunch_party(p_projection_id,responsibility,'coverer');
  perform public.static_weekly_assert_exact_object(responsibility,
   array['responsibility_id','loan_id','service_date','day_of_week','normal_owner_slot_id','coverer_slot_id','coverage_purpose','coverage_start','coverage_end','check_deadline_policy','creates_deep_clean','proximity_evidence','segments']
    ||case when responsibility ? 'normal_owner_capacity_id' then array['normal_owner_capacity_id'] else array['normal_owner_person_id'] end
    ||case when responsibility ? 'coverer_capacity_id' then array['coverer_capacity_id'] else array['coverer_person_id'] end,
   array['responsibility_id','loan_id','service_date','day_of_week','normal_owner_slot_id','normal_owner_person_id','normal_owner_capacity_id','coverer_slot_id','coverer_person_id','coverer_capacity_id','coverage_purpose','coverage_start','coverage_end','check_deadline_policy','creates_deep_clean','proximity_evidence','segments'],'lunch responsibility');
  select value into loan from jsonb_array_elements(p_document->'loans') where value->>'loan_id'=responsibility->>'loan_id';
  if not found or loan->>'status'<>'PLANNED' then raise exception 'lunch responsibility has no planned loan'; end if;
  foreach identity_key in array array['service_date','day_of_week','normal_owner_slot_id','normal_owner_person_id','coverage_start','coverage_end'] loop
   if responsibility->identity_key is distinct from loan->identity_key then raise exception 'lunch responsibility scope mismatch'; end if;
  end loop;
  select value into helper from jsonb_array_elements(projection_availability)
   where value->>'slotId'=responsibility->>'coverer_slot_id' and value->>'serviceDate'=responsibility->>'service_date';
  if not found or helper->>'incumbentPersonId' is distinct from responsibility->>'coverer_person_id'
   or not (loan->'helper_slot_ids' ? (responsibility->>'coverer_slot_id'))
   or coalesce(responsibility->>'responsibility_id','') !~ '^[0-9a-f]{64}$'
   or responsibility->>'coverage_purpose' is distinct from 'lunch_coverage'
   or responsibility->>'check_deadline_policy' is distinct from 'inherit_existing_90_minute_deadline'
   or responsibility->'creates_deep_clean' is distinct from 'false'::jsonb
   or jsonb_typeof(responsibility->'segments') is distinct from 'array'
   or jsonb_array_length(responsibility->'segments')=0 then raise exception 'lunch responsibility policy or recipient mismatch'; end if;
  for segment in select value from jsonb_array_elements(responsibility->'segments') loop
   perform public.static_weekly_assert_exact_object(segment,
    array['planWorkId','workId','serviceMode','window','includedLocations']||case when full_hour then array['normalWindow'] else array[]::text[] end,
    array['planWorkId','workId','serviceMode','window','includedLocations']||case when full_hour then array['normalWindow'] else array[]::text[] end,'lunch segment');
   select value into base_work from jsonb_array_elements(projection_assignments)
    where value->>'plan_work_id'=segment->>'planWorkId' and value->>'service_date'=responsibility->>'service_date';
   if not found or base_work->>'status' is distinct from 'assigned'
    or base_work->>'owner_slot_id' is distinct from responsibility->>'normal_owner_slot_id'
    or base_work->>'owner_person_id' is distinct from responsibility->>'normal_owner_person_id'
    or base_work->>'work_id' is distinct from segment->>'workId'
    or base_work#>'{work_snapshot,includedLocations}' is distinct from segment->'includedLocations'
    or base_work#>>'{work_snapshot,serviceMode}' is distinct from segment->>'serviceMode'
    or segment->>'serviceMode'='reminder_only' then raise exception 'borrowed area differs from original assignment'; end if;
   if not ((helper->'qualifications') @> (base_work#>'{work_snapshot,requiredQualifications}'))
    or (base_work#>'{work_snapshot,restrictedSlotIds}') ? (responsibility->>'coverer_slot_id')
    or exists(select 1 from jsonb_array_elements(segment->'includedLocations') location
      where helper->'restrictions' ? (location->>'locationId')) then
    raise exception 'lunch helper is restricted or unqualified for a borrowed area'; end if;
   perform public.static_weekly_v3_assert_window(segment->'window','borrowed area');
   normal_segment_window:=case when full_hour then segment->'normalWindow' else segment->'window' end;
   perform public.static_weekly_v3_assert_window(normal_segment_window,'original borrowed-area anchor');
   if (normal_segment_window->>'start')::time<>greatest((base_work#>>'{work_snapshot,window,start}')::time,(loan->>'coverage_start')::time)
    or (normal_segment_window->>'end')::time<>least((base_work#>>'{work_snapshot,window,end}')::time,(loan->>'coverage_end')::time) then
    raise exception 'borrowed-area window must be the exact normal-duty and lunch intersection'; end if;
   if full_hour then
    if segment->'window' is distinct from jsonb_build_object('start',loan->'coverage_start','end',loan->'coverage_end')
     then raise exception 'full lunch area must cover the entire accepted lunch';end if;
    select value into strict planned_loan from jsonb_array_elements(full_hour_policy->'loans')
     where value->'dayOfWeek'=loan->'day_of_week' and value->'normalOwnerSlotId'=loan->'normal_owner_slot_id';
    if not exists(select 1 from jsonb_array_elements(planned_loan->'areas') area
     where area->>'locationCode'=base_work#>>'{work_snapshot,locationCodeSnapshot}'
      and area->'covererSlotId'=responsibility->'coverer_slot_id') then
     raise exception 'full lunch recipient differs from the immutable area plan';end if;
   end if;
  end loop;
 end loop;
 if full_hour then
  for planned_loan in select value from jsonb_array_elements(full_hour_policy->'loans') loop
   for segment in select value from jsonb_array_elements(planned_loan->'areas') loop
    perform public.static_weekly_assert_exact_object(segment,array['locationCode','covererSlotId'],array['locationCode','covererSlotId'],'full lunch source area');
    if jsonb_typeof(segment->'locationCode') is distinct from 'string' or length(segment->>'locationCode') not between 1 and 512
     or jsonb_typeof(segment->'covererSlotId') is distinct from 'string' or length(segment->>'covererSlotId') not between 1 and 512
     or segment->'covererSlotId'=planned_loan->'normalOwnerSlotId' then raise exception 'invalid full lunch source area';end if;
   end loop;
  end loop;
  select coalesce(jsonb_agg(entry order by entry::text),'[]') into expected from
   (select jsonb_build_array(l->'dayOfWeek',l->'normalOwnerSlotId',a->'locationCode',a->'covererSlotId') entry
    from jsonb_array_elements(full_hour_policy->'loans') l cross join lateral jsonb_array_elements(l->'areas') a) q;
  select coalesce(jsonb_agg(entry order by entry::text),'[]') into actual from
   (select distinct jsonb_build_array(r->'day_of_week',r->'normal_owner_slot_id',a#>'{work_snapshot,locationCodeSnapshot}',r->'coverer_slot_id') entry
    from jsonb_array_elements(p_document->'responsibilities') r cross join lateral jsonb_array_elements(r->'segments') s
    join jsonb_array_elements(projection_assignments) a on a->>'plan_work_id'=s->>'planWorkId'
     and a->'service_date'=r->'service_date') q;
  if expected is distinct from actual then raise exception 'full lunch source areas omitted, duplicated or reassigned';end if;
  if exists(with areas as materialized (
    select r->>'service_date' service_date,loc->>'locationId' location_id,
     jsonb_build_array(r->'coverer_slot_id',r->'coverer_person_id',r->'coverer_capacity_id') recipient,
     (s#>>'{window,start}')::time starts,(s#>>'{window,end}')::time ends
    from jsonb_array_elements(p_document->'responsibilities') r cross join lateral jsonb_array_elements(r->'segments') s
     cross join lateral jsonb_array_elements(s->'includedLocations') loc)
   select 1 from areas a join areas b on a.service_date=b.service_date and a.location_id=b.location_id
    and a.recipient is distinct from b.recipient and a.starts<b.ends and b.starts<a.ends) then
   raise exception 'full lunch plans conflict on current physical responsibility';end if;
 end if;
 -- Account for every normal flexible duty that intersects each scheduled lunch.
 select coalesce(jsonb_agg(jsonb_build_array(l->>'loan_id',a->>'plan_work_id')
  order by l->>'loan_id',a->>'plan_work_id'),'[]') into expected
 from jsonb_array_elements(p_document->'loans') l
 join jsonb_array_elements(projection_assignments) a
  on a->>'service_date'=l->>'service_date' and a->>'owner_slot_id'=l->>'normal_owner_slot_id'
 join jsonb_array_elements(projection_work) w
  on w->>'workId'=a->>'work_id' and w->>'dayOfWeek'=a->>'day_of_week'
 where a->>'status'='assigned' and w->>'schedulingMode'='flexible_coverage_ownership'
  and w->>'serviceMode'<>'reminder_only'
  and (a#>>'{work_snapshot,window,start}')::time<(l->>'coverage_end')::time
  and (l->>'coverage_start')::time<(a#>>'{work_snapshot,window,end}')::time;
 select coalesce(jsonb_agg(jsonb_build_array(r->>'loan_id',s->>'planWorkId')
  order by r->>'loan_id',s->>'planWorkId'),'[]') into actual
 from jsonb_array_elements(p_document->'responsibilities') r cross join lateral jsonb_array_elements(r->'segments') s;
 if actual is distinct from expected then raise exception 'lunch responsibility must cover every eligible original area exactly once'; end if;
 if exists(select 1 from jsonb_array_elements(p_document->'responsibilities') r,
  jsonb_array_elements(r->'segments') s group by r->>'loan_id',s->>'planWorkId' having count(*)>1) then
  raise exception 'borrowed work assigned more than once'; end if;
 if exists(select 1 from jsonb_array_elements(p_document->'responsibilities') r,
  jsonb_array_elements(r->'segments') s,jsonb_array_elements(s->'includedLocations') location
  group by r->>'loan_id',location->>'locationId' having count(distinct r->>'coverer_slot_id')>1) then
  raise exception 'paired or grouped locations split between lunch helpers'; end if;
 for intent in select value from jsonb_array_elements(p_document->'notification_intents') loop
  perform public.static_weekly_assert_exact_object(intent,
   array['notification_key','loan_id','service_date','event','scheduled_time','coverer_slot_id','delivery_state'],
   array['notification_key','loan_id','service_date','event','scheduled_time','coverer_slot_id','delivery_state'],'lunch notification intent');
  if coalesce(intent->>'notification_key','') !~ '^[0-9a-f]{64}$'
   or intent->>'delivery_state' is distinct from 'NOT_ENQUEUED' then raise exception 'invalid lunch notification intent'; end if;
 end loop;
 select coalesce(jsonb_agg(jsonb_build_array(l->>'loan_id',l->>'service_date',h,e,
  case e when 'start' then l->>'coverage_start' else l->>'coverage_end' end) order by l->>'loan_id',h,e),'[]') into expected
 from jsonb_array_elements(p_document->'loans') l cross join lateral jsonb_array_elements_text(l->'helper_slot_ids') h
 cross join unnest(array['start','end']) e
 where exists(select 1 from jsonb_array_elements(projection_availability) a
  where a->>'slotId'=h and a->>'serviceDate'=l->>'service_date' and nullif(a->>'incumbentPersonId','') is not null);
 select coalesce(jsonb_agg(jsonb_build_array(n->>'loan_id',n->>'service_date',n->>'coverer_slot_id',n->>'event',n->>'scheduled_time')
  order by n->>'loan_id',n->>'coverer_slot_id',n->>'event'),'[]') into actual
 from jsonb_array_elements(p_document->'notification_intents') n;
 if actual is distinct from expected then raise exception 'lunch start/end intents must exactly cover every helper'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v8_materialize_lunch_document(p_projection_id uuid, p_document jsonb, p_manager_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;projection public.weekly_schedule_compiled_projections%rowtype;document public.weekly_schedule_lunch_documents%rowtype;
 before_fingerprint text;after_fingerprint text;
BEGIN
 before_fingerprint:=custodial_coverall.lunch_validator_fingerprint();
 -- The private original is an exact whole-body clone. It retains real actor,
 -- current projection, restore/authority lock, complete v8 validator and insert
 -- constraints. This wrapper does not replace admission with a prior proof.
 result:=custodial_coverall.original_v8_materialize_lunch_document(p_projection_id,p_document,p_manager_id);
 SELECT * INTO STRICT projection FROM public.weekly_schedule_compiled_projections WHERE projection_id=p_projection_id;
 SELECT * INTO STRICT document FROM public.weekly_schedule_lunch_documents WHERE projection_id=p_projection_id;
 after_fingerprint:=custodial_coverall.lunch_validator_fingerprint();
 IF before_fingerprint IS DISTINCT FROM after_fingerprint OR document.document_json IS DISTINCT FROM p_document
  OR document.document_identity IS DISTINCT FROM p_document->>'document_identity'
  OR result->>'projection_id' IS DISTINCT FROM p_projection_id::text OR result->>'document_identity' IS DISTINCT FROM document.document_identity
  THEN RAISE EXCEPTION 'Actual same-transaction full lunch admission/store correspondence changed';END IF;
 INSERT INTO custodial_coverall.manual_lunch_admission_proofs(projection_id,document_identity,validator_fingerprint,projection_digest,document_digest,full_projection_json,full_document_json)
 VALUES(p_projection_id,document.document_identity,after_fingerprint,public.static_weekly_digest_jsonb(to_jsonb(projection)),
  public.static_weekly_digest_jsonb(document.document_json),to_jsonb(projection),document.document_json) ON CONFLICT DO NOTHING;
 PERFORM custodial_coverall.require_lunch_admission_proof(p_projection_id,p_document);
 RETURN result; -- Original receipt bytes/state/leases/delivery claims unchanged.
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v8_read_completed_vacancy(p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
 v_mutation public.weekly_schedule_command_receipts%rowtype;
 v_receipt public.weekly_schedule_command_receipts%rowtype;
 v_projection public.weekly_schedule_compiled_projections%rowtype;
 v_lunch public.weekly_schedule_lunch_documents%rowtype;
 v_date date;v_week date;v_projection_snapshot jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform public.custodial_assert_manager(p_manager_id);
 perform public.static_weekly_v3_manager_actor(p_manager_id);
 if p_manager_id is null or nullif(btrim(p_idempotency_key),'') is null then
  raise exception using errcode='22023',message='completed vacancy lookup requires exact manager and command identity';
 end if;
 select * into v_mutation from public.weekly_schedule_command_receipts
  where actor_manager_id=p_manager_id and idempotency_key=p_idempotency_key and command_type='vacate_roster_slot';
 if not found then return null; end if;
 perform public.static_weekly_v8_assert_vacancy_receipt(v_mutation.command_id,'vacate_roster_slot');
 if v_mutation.response_json#>>'{data,completion_mode}'='mutation_only'
   and (v_mutation.response_json->'data') ? 'original_publication_id'
   and v_mutation.response_json#>'{data,original_publication_id}'='null'::jsonb then
  return v_mutation.response_json;
 end if;
 if v_mutation.response_json#>>'{data,completion_mode}' is distinct from 'projection_required'
   or nullif(v_mutation.response_json#>>'{data,original_publication_id}','') is null then
  raise exception using errcode='23514',message='completed vacancy original completion binding is missing or inconsistent';
 end if;
 select * into v_receipt from public.weekly_schedule_command_receipts
  where actor_manager_id=p_manager_id and idempotency_key='projection-'||encode(extensions.digest(convert_to(p_idempotency_key,'UTF8'),'sha256'),'hex');
 if not found then
  raise exception using errcode='23514',message='completed vacancy required projection receipt is missing';
 end if;
 perform public.static_weekly_v8_assert_vacancy_receipt(v_receipt.command_id,'materialize_projection');
 v_date:=(v_mutation.request_canonical_json->>'effective_start')::date;
 v_week:=v_date-(extract(isodow from v_date)::integer-1);
 if v_receipt.command_type is distinct from 'materialize_projection'
  or v_receipt.expected_revision is distinct from (v_mutation.response_json->>'revision')::bigint
  or (v_receipt.response_json->>'revision')::bigint is distinct from v_receipt.expected_revision+1
  or v_receipt.request_canonical_json->>'service_date' is distinct from v_week::text
  or v_receipt.request_canonical_json->>'publication_id' is distinct from v_mutation.response_json#>>'{data,original_publication_id}' then
  raise exception using errcode='23514',message='completed vacancy projection receipt does not bind the exact mutation';
 end if;
 select * into v_projection from public.weekly_schedule_compiled_projections
  where projection_id=(v_receipt.response_json#>>'{data,projection_id}')::uuid;
 if not found or v_projection.week_start is distinct from v_week
  or v_projection.publication_id::text is distinct from v_receipt.request_canonical_json->>'publication_id'
  or v_projection.authority_digest is distinct from v_receipt.request_canonical_json#>>'{projection_envelope,authority_digest}'
  or v_projection.replay_digest is distinct from v_receipt.request_canonical_json->>'replay_digest' then
  raise exception using errcode='23514',message='completed vacancy immutable projection binding is missing or inconsistent';
 end if;
 select * into v_lunch from public.weekly_schedule_lunch_documents where projection_id=v_projection.projection_id;
 if not found or v_lunch.accepted_by_manager_id is distinct from p_manager_id
  or v_lunch.document_identity is distinct from v_lunch.document_json->>'document_identity'
  or v_lunch.document_json->>'base_authority_digest' is distinct from v_projection.authority_digest
  or v_lunch.document_json->>'base_replay_digest' is distinct from v_projection.replay_digest then
  raise exception using errcode='23514',message='completed vacancy accepted lunch binding is missing or inconsistent';
 end if;
 perform public.static_weekly_v8_assert_lunch_document(v_projection.projection_id,v_lunch.document_json);
 -- Match the immutable projection descriptor in the manager snapshot used by
 -- the first success. Do not read today's mutable latest-projection selector.
 v_projection_snapshot:=jsonb_build_object(
  'projection_id',v_projection.projection_id::text,'publication_id',v_projection.publication_id::text,
  'version_id',v_projection.version_id::text,'week_start',v_projection.week_start::text,'week_end',v_projection.week_end::text,
  'compiler_version',v_projection.compiler_version,'metrics',v_projection.metrics_json,
  'replay_digest',v_projection.replay_digest,'compiled_at',v_projection.compiled_at,
  'assignments',v_projection.projection_envelope->'assignments');
 return v_receipt.response_json||jsonb_build_object('data',
  (v_mutation.response_json->'data')||(v_receipt.response_json->'data')||
  jsonb_build_object('current_projection',v_projection_snapshot,'mutation',v_mutation.response_json->'data'));
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v8_read_lunch_document(p_service_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare current_authority record;stored public.weekly_schedule_lunch_documents%rowtype;
begin
 select * into current_authority from public.static_weekly_v6_schedule_authority_state(p_service_date);
 if current_authority.projection_status is distinct from 'current' then
  return jsonb_build_object('persistence_status','UNAVAILABLE','projection_status',current_authority.projection_status); end if;
 select * into stored from public.weekly_schedule_lunch_documents where projection_id=current_authority.projection_id;
 if not found then return jsonb_build_object('persistence_status','MISSING','projection_id',current_authority.projection_id); end if;
 if stored.document_identity is distinct from stored.document_json->>'document_identity' then
  raise exception 'saved lunch document identity mismatch'; end if;
 -- Native-manual documents were fully admitted by the exact real v8
 -- materializer before their immutable proof was appended. Require that exact
 -- current-validator/full-projection/full-document certificate here; never
 -- substitute a prepared label, missing proof or caller-controlled flag.
 if exists(select 1 from public.weekly_schedule_compiled_projections projection
  where projection.projection_id=stored.projection_id
   and projection.projection_envelope#>>'{adapter,schema}'='custodial.approved-manual-period-database-adapter.v1') then
  perform custodial_coverall.require_lunch_admission_proof(stored.projection_id,stored.document_json);
 else
  -- Historical/non-native generic readers retain the original full validator.
  perform public.static_weekly_v8_assert_lunch_document(stored.projection_id,stored.document_json);
 end if;
 return jsonb_build_object('persistence_status','PERSISTED','projection_id',stored.projection_id,
  'document_identity',stored.document_identity,'service_date',p_service_date,
  'loans',coalesce((select jsonb_agg(value) from jsonb_array_elements(stored.document_json->'loans') where value->>'service_date'=p_service_date::text),'[]'::jsonb),
  'responsibilities',coalesce((select jsonb_agg(value) from jsonb_array_elements(stored.document_json->'responsibilities') where value->>'service_date'=p_service_date::text),'[]'::jsonb));
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v8_restore_existing_employee(p_source_id uuid, p_slot_id uuid, p_employee_id uuid, p_effective_start date, p_reason text, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_actor jsonb;
  v_prior public.weekly_schedule_command_receipts%rowtype;
  v_slot public.weekly_roster_slots%rowtype;
  v_employee public.employees%rowtype;
  v_source public.static_weekly_authority_source_documents%rowtype;
  v_source_slot jsonb;
  v_source_matches integer;
  v_prior_incumbency_count integer;
  v_request jsonb;
  v_request_digest text;
  v_content_digest text;
  v_command uuid:=gen_random_uuid();
  v_incumbency uuid:=gen_random_uuid();
  v_revision bigint;
  v_response jsonb;
  v_status jsonb; v_completion jsonb;
begin
  perform public.static_weekly_v3_assert_control_plane();
  v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
  perform public.static_weekly_assert_command_identity(
    p_expected_revision,p_manager_id,v_actor->>'manager_name',p_idempotency_key,'restore_existing_employee'
  );
  if p_source_id is null or p_slot_id is null or p_employee_id is null or p_effective_start is null

     or nullif(btrim(coalesce(p_reason,'')),'') is null
     or char_length(p_reason)>500 or p_reason~'[\x00-\x1f\x7f]' then
    raise exception using errcode='23514',message='existing-employee restoration requires a release-registered source, stable slot, existing employee, non-past effective date, and bounded reason';
  end if;
  v_request:=jsonb_build_object(
    'operation','restore_existing_employee','source_id',p_source_id,'slot_id',p_slot_id,'employee_id',p_employee_id,
    'effective_start',p_effective_start,'reason',p_reason,
    'expected_revision',p_expected_revision,'actor_manager_id',p_manager_id
  );
  v_request_digest:=public.static_weekly_digest_jsonb(v_request);
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts
    where actor_manager_id=p_manager_id and idempotency_key=p_idempotency_key;
  if found then
    if v_prior.request_digest<>v_request_digest then
      raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs';
    end if;
    perform public.static_weekly_v8_assert_vacancy_receipt(v_prior.command_id,'restore_existing_employee');
    return v_prior.response_json;
  end if;
  if p_effective_start<public.sch_service_date(statement_timestamp()) then raise exception 'new restoration cannot be backdated'; end if;
  v_completion:=public.static_weekly_v9_roster_completion_context(p_source_id,p_slot_id,p_effective_start,false);
  select * into v_slot from public.weekly_roster_slots where slot_id=p_slot_id for share;
  if not found then raise exception using errcode='P0002',message='stable roster position was not found'; end if;
  select * into v_employee from public.employees where id=p_employee_id for update;
  if not found or v_employee.employee_code!~'^EMP[0-9]+$' then
    raise exception using errcode='23514',message='restoration requires the exact existing custodial employee identity';
  end if;
  if not exists(select 1 from public.msg_users where employee_id=p_employee_id) then
    raise exception using errcode='23514',message='existing employee Messenger identity is missing; restoration will not fabricate a replacement principal';
  end if;
  select * into v_source from public.static_weekly_authority_source_documents
    where source_id=p_source_id and active=true and retired_at is null;
  if not found then
    raise exception using errcode='P0002',message='restoration requires the exact active release-registered recurring source';
  end if;
  select value into v_source_slot from jsonb_array_elements(coalesce(v_source.canonical_source->'slots','[]'::jsonb)) slot(value)
    where value->>'id'=p_slot_id::text;
  if v_source_slot is null then
    raise exception using errcode='23514',message='registered source does not contain the requested stable position';
  end if;
  select count(*) into v_source_matches
  from jsonb_array_elements(coalesce(v_source_slot->'incumbencies','[]'::jsonb)) incumbent(value)
  where value->>'personId'=p_employee_id::text
    and value->>'effectiveStart'=p_effective_start::text
    and (nullif(value->>'effectiveEnd','') is null or p_effective_start<(value->>'effectiveEnd')::date);
  if v_source_matches<>1 then
    raise exception using errcode='23514',message='registered source must bind this exact existing employee to this exact stable position and effective date';
  end if;
  select count(*) into v_prior_incumbency_count
  from public.weekly_roster_slot_incumbencies where slot_id=p_slot_id and person_id=p_employee_id;
  if exists(
    select 1 from public.v_weekly_roster_slot_incumbency_ranges r
    where r.slot_id=p_slot_id
      and (r.effective_start>=p_effective_start
        or (r.effective_start<p_effective_start and (r.effective_end is null or p_effective_start<r.effective_end)))
  ) then
    raise exception using errcode='23514',message='restoration target position already has current or future incumbency authority';
  end if;
  if exists(
    select 1 from public.v_weekly_roster_slot_incumbency_ranges r
    where r.person_id=p_employee_id and r.slot_id<>p_slot_id
      and (r.effective_start>=p_effective_start
        or (r.effective_start<p_effective_start and (r.effective_end is null or p_effective_start<r.effective_end)))
  ) then
    raise exception using errcode='23514',message='existing employee already has current or future authority in another stable position';
  end if;
  perform public.static_weekly_v4_assert_employee_turnover_ready(p_employee_id);
  if exists(
    select 1 from public.weekly_roster_slot_staffing_states
    where slot_id=p_slot_id and effective_start=p_effective_start and staffing_state='working'
  ) then
    raise exception using errcode='23505',message='stable position already has working staffing authority on restoration date';
  end if;
  v_content_digest:=public.static_weekly_digest_jsonb(v_request-'expected_revision'-'actor_manager_id'-'operation');
  v_revision:=public.static_weekly_advance_authority(
    p_expected_revision,'restore_existing_employee',p_manager_id,v_actor->>'manager_name',v_command,v_content_digest
  );
  insert into public.weekly_roster_slot_incumbencies(
    incumbency_id,slot_id,person_id,person_name_snapshot,effective_start,
    created_by_manager_id,created_by_manager_name_snapshot,content_digest
  ) values(
    v_incumbency,p_slot_id,p_employee_id,v_employee.display_name,p_effective_start,
    p_manager_id,v_actor->>'manager_name',v_content_digest
  );
  insert into public.weekly_roster_slot_staffing_states(
    slot_id,employee_id,staffing_state,effective_start,authority_revision,
    actor_manager_id,actor_manager_name_snapshot,reason,content_digest
  ) values(
    p_slot_id,p_employee_id,'working',p_effective_start,v_revision,
    p_manager_id,v_actor->>'manager_name',p_reason,v_content_digest
  );
  v_status:=public.custodial_set_employee_active(p_employee_id,true,p_manager_id,p_reason,false);
  v_response:=public.static_weekly_response_json(
    'restore_existing_employee',v_revision,v_content_digest,v_request_digest,
    jsonb_build_object(
      'slot_id',p_slot_id,'slot_label',v_slot.slot_label,
      'employee_id',p_employee_id,'employee_name',v_employee.display_name,
      'source_id',p_source_id,'source_digest',v_source.source_digest,
      'effective_start',p_effective_start,'prior_scheduler_incumbency_count',v_prior_incumbency_count,
      'restored_incumbency_id',v_incumbency,'employee_status',v_status,
      'phone_assignment',null,'history_preserved',true
    )||v_completion
  );
  insert into public.weekly_schedule_command_receipts(
    command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,
    expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest
  ) values(
    v_command,p_manager_id,v_actor->>'manager_name','restore_existing_employee',p_idempotency_key,
    p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest
  );
  return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v8_vacate_roster_slot(p_source_id uuid, p_slot_id uuid, p_employee_id uuid, p_effective_start date, p_reason text, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_actor jsonb;v_prior public.weekly_schedule_command_receipts%rowtype;
  v_source public.static_weekly_authority_source_documents%rowtype;
  v_incumbent public.v_weekly_roster_slot_incumbency_ranges%rowtype;
  v_employee public.employees%rowtype;v_slot jsonb;v_request jsonb;v_request_digest text;
  v_content_digest text;v_revision bigint;v_command uuid:=gen_random_uuid();v_response jsonb;v_status jsonb;
  v_original_publication uuid;
begin
  perform public.static_weekly_v3_assert_control_plane();
  perform public.custodial_assert_manager(p_manager_id);
  v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_manager_id,
    v_actor->>'manager_name',p_idempotency_key,'vacate_roster_slot');
  if p_source_id is null or p_slot_id is null or p_employee_id is null or p_effective_start is null
    or nullif(btrim(coalesce(p_reason,'')),'') is null or char_length(p_reason)>500
    or p_reason~'[\x00-\x1f\x7f]' then
    raise exception using errcode='23514',message='vacancy requires source, position, exact former employee, effective date and bounded reason';
  end if;
  v_request:=jsonb_build_object('operation','vacate_roster_slot','source_id',p_source_id,'slot_id',p_slot_id,
    'employee_id',p_employee_id,'effective_start',p_effective_start,'reason',p_reason,
    'expected_revision',p_expected_revision,'actor_manager_id',p_manager_id);
  v_request_digest:=public.static_weekly_digest_jsonb(v_request);
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts
    where actor_manager_id=p_manager_id and idempotency_key=p_idempotency_key;
  if found then
    if v_prior.request_digest<>v_request_digest then
      raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs';
    end if;
    perform public.static_weekly_v8_assert_vacancy_receipt(v_prior.command_id,'vacate_roster_slot');
    return v_prior.response_json;
  end if;
  -- Immediate turnover only. Do not deactivate someone today for a future vacancy.
  if p_effective_start<>public.sch_service_date(statement_timestamp()) then
    raise exception using errcode='23514',message='vacancy effective date must be the current service date; past or future turnover is not supported';
  end if;
  select * into v_source from public.static_weekly_authority_source_documents
    where source_id=p_source_id and active and retired_at is null for share;
  if not found then raise exception using errcode='23514',message='vacancy requires an active registered source'; end if;
  select value into v_slot from jsonb_array_elements(v_source.canonical_source->'slots')
    where value->>'id'=p_slot_id::text;
  if v_slot is null
    or not coalesce((v_source.canonical_source#>'{version,vacancyCapableSlotIds}') ? p_slot_id::text,false)
     then
    raise exception using errcode='23514',message='registered source must declare this stable position vacancy-capable';
  end if;
  select * into v_incumbent from public.v_weekly_roster_slot_incumbency_ranges
    where slot_id=p_slot_id and effective_start<p_effective_start
      and (effective_end is null or p_effective_start<effective_end);
  if not found or v_incumbent.person_id<>p_employee_id then
    raise exception using errcode='23514',message='vacancy requires the exact effective predecessor incumbent';
  end if;
  if exists(select 1 from public.v_weekly_roster_slot_incumbency_ranges
      where slot_id=p_slot_id and effective_start>=p_effective_start) then
    raise exception using errcode='23514',message='future incumbency already occupies this position';
  end if;
  if exists(select 1 from public.v_weekly_roster_slot_incumbency_ranges
      where person_id=p_employee_id and slot_id<>p_slot_id
        and (effective_end is null or p_effective_start<effective_end)) then
    raise exception using errcode='23514',message='former employee also has another current or future position';
  end if;
  select * into v_employee from public.employees where id=p_employee_id for update;
  if not found then raise exception using errcode='23514',message='predecessor employee identity is missing'; end if;

  -- Bind the original completion shape under the same authority lock and
  -- effective-week selector as the manager snapshot. Absence of a later
  -- projection receipt must never be interpreted as an unpublished action.
  select publication_id into v_original_publication from public.weekly_schedule_publications
    where version_id=public.static_weekly_effective_version(
      p_effective_start-(extract(isodow from p_effective_start)::integer-1));
  v_content_digest:=public.static_weekly_digest_jsonb(v_request-'expected_revision'-'actor_manager_id'-'operation');
  v_revision:=public.static_weekly_advance_authority(p_expected_revision,'vacate_roster_slot',
    p_manager_id,v_actor->>'manager_name',v_command,v_content_digest);
  insert into public.weekly_roster_slot_staffing_states(
    slot_id,employee_id,staffing_state,effective_start,authority_revision,
    actor_manager_id,actor_manager_name_snapshot,reason,content_digest)
  values(p_slot_id,null,'vacant_unfilled',p_effective_start,v_revision,
    p_manager_id,v_actor->>'manager_name',p_reason,v_content_digest);
  insert into public.weekly_roster_slot_incumbency_closures(
    closed_incumbency_id,replacement_incumbency_id,closed_at_effective_date,authority_revision,
    actor_manager_id,actor_manager_name_snapshot,content_digest)
  values(v_incumbent.incumbency_id,null,p_effective_start,v_revision,
    p_manager_id,v_actor->>'manager_name',v_content_digest);
  v_status:=public.custodial_v12_inactivate_preserving_work(p_employee_id,p_slot_id,p_manager_id,p_reason,v_revision,v_command,p_effective_start);
  v_response:=public.static_weekly_response_json('vacate_roster_slot',v_revision,v_content_digest,
    v_request_digest,jsonb_build_object('slot_id',p_slot_id,'former_employee_id',p_employee_id,
      'replacement_employee_id',null,'effective_start',p_effective_start,'source_id',p_source_id,
      'source_digest',v_source.source_digest,'employee_status',v_status,'history_preserved',true,
      'completion_mode',case when v_original_publication is null then 'mutation_only' else 'projection_required' end,
      'original_publication_id',v_original_publication));
  insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,
    actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,
    request_canonical_json,response_json,response_digest,content_digest)
  values(v_command,p_manager_id,v_actor->>'manager_name','vacate_roster_slot',p_idempotency_key,
    p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest);
  return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v9_assert_shift_end_derivation(p_authority jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
 SET plan_cache_mode TO 'force_generic_plan'
AS $function$
declare
 source jsonb:=p_authority->'compilerInput';
 effective jsonb:=jsonb_set(p_authority->'overlayCompilerInput','{exceptions}','[]'::jsonb);
 policy jsonb:=source#>'{version,shiftEndContinuityPolicy}';
 receipt jsonb:=p_authority->'shiftEndDerivation';
 roster jsonb; boundaries jsonb; chain jsonb; parent jsonb; segment jsonb; work jsonb;
 person jsonb; owner jsonb; physical jsonb; key text; previous_end text; final_end text;
 day integer; matches integer; total numeric; seen text[]:='{}'; parent_seen text[]:='{}';
 minute_samples integer:=0; location_samples integer:=0; location_count integer; span integer;
 planned_day text;planned_stages jsonb;planned_stage jsonb;planned_parent jsonb;planned_person jsonb;planned_availability jsonb;planned_families jsonb;planned_previous time;planned_last time;planned_start time;planned_end time;planned_coverage interval;planned_valid_edges jsonb;
 named jsonb; named_parent jsonb; named_chain jsonb; named_from jsonb; named_to jsonb; named_to_availability jsonb;
 named_parent_id text; named_key text; named_seen text[]:='{}';
begin
 perform public.static_weekly_assert_exact_object(policy,
  array['schema','algorithm','normalPhaseStart','weights','provenance','policyDigest'],
  array['schema','algorithm','normalPhaseStart','weights','provenance','policyDigest','namedHandoffs','plannedClosingOwnership'],'shift-end source policy');
 if policy ? 'namedHandoffs' then
  if jsonb_typeof(policy->'namedHandoffs') is distinct from 'array' then
   raise exception using errcode='23514',message='shift-end named handoffs must be one array';
  end if;
  if jsonb_array_length(policy->'namedHandoffs')>14 then
   raise exception using errcode='23514',message='shift-end named handoffs exceed the source bound';
  end if;
 end if;
 perform public.static_weekly_assert_exact_object(receipt,
  array['schema','algorithm','templateDigest','policyDigest','datedRosterDigest','derivedBaselineDigest','staffedDepartureByDay','parentChains','outputWorkDigest','continuity'],
  array['schema','algorithm','templateDigest','policyDigest','datedRosterDigest','derivedBaselineDigest','staffedDepartureByDay','parentChains','outputWorkDigest','continuity'],'shift-end derivation receipt');
 if policy->>'schema' is distinct from 'memphis-zoo.shift-end-continuity-policy.v1'
  or policy->>'algorithm' is distinct from 'dated-real-staff-directed-proximity-weighted-v1'
  or policy->>'normalPhaseStart' is distinct from '09:45'
  or coalesce(policy->>'provenance','') !~ '^owner-configuration-sha256:[a-f0-9]{64}$'
  or policy->>'policyDigest' is distinct from public.static_weekly_digest_jsonb(policy-'policyDigest')
  or receipt->>'schema' is distinct from 'memphis-zoo.shift-end-derivation.v1'
  or receipt->>'algorithm' is distinct from policy->>'algorithm'
  or receipt->>'policyDigest' is distinct from policy->>'policyDigest'
  or receipt->>'templateDigest' is distinct from public.static_weekly_digest_jsonb(source)
  or receipt->>'derivedBaselineDigest' is distinct from public.static_weekly_digest_jsonb(effective)
  or receipt->>'derivedBaselineDigest' is distinct from p_authority->>'derivedBaselineDigest'
  or source->'exceptions' is distinct from '[]'::jsonb
  or source#>'{version,shiftEndDerivationApplied}' is not null
  or effective#>>'{version,shiftEndDerivationApplied}' is distinct from policy->>'policyDigest'
  or source-'version' is distinct from effective-'version'
  or (source->'version')-'assignments' is distinct from (effective->'version')-'assignments'-'shiftEndDerivationApplied'
  or jsonb_typeof(policy->'weights') is distinct from 'object'
  or jsonb_typeof(source#>'{version,assignments}') is distinct from 'array'
  or jsonb_typeof(effective#>'{version,assignments}') is distinct from 'array'
  or jsonb_typeof(receipt->'parentChains') is distinct from 'array'
  or jsonb_array_length(source#>'{version,assignments}') not between 1 and 1024
  or jsonb_array_length(effective#>'{version,assignments}') not between 1 and 1024
  or jsonb_array_length(receipt->'parentChains')<>jsonb_array_length(source#>'{version,assignments}')
  or receipt->>'outputWorkDigest' is distinct from public.static_weekly_digest_jsonb(effective#>'{version,assignments}') then
  raise exception using errcode='23514',message='shift-end source, policy, derived baseline and receipt identities must be exact';
 end if;
 if exists(select 1 from jsonb_each(policy->'weights') w where jsonb_typeof(w.value)<>'number'
  or (w.value#>>'{}')::numeric<=0 or (w.value#>>'{}')::numeric>1000
  or (w.value#>>'{}')::numeric*2<>trunc((w.value#>>'{}')::numeric*2)) then
  raise exception using errcode='23514',message='shift-end weights require exact positive bounded half units';
 end if;
 -- Derive this roster from immutable availability plus dated incumbent ranges,
 -- never from exception-mutated projectionAvailability or a caller roster blob.
 with facts as (
  select a, s, (source->>'serviceDate')::date+
   mod((a->>'dayOfWeek')::int-extract(dow from (source->>'serviceDate')::date)::int+7,7) d
  from jsonb_array_elements(source#>'{version,slotAvailability}') a
  join jsonb_array_elements(source->'slots') s on s->>'id'=a->>'slotId'
  where coalesce(s->'contractorCapacity','false'::jsonb)='false'::jsonb
 ), dated as (
  select *, (select count(*) from jsonb_array_elements(s->'incumbencies') i
   where (i->>'effectiveStart')::date<=d and (i->>'effectiveEnd' is null or d<(i->>'effectiveEnd')::date)) n,
   (select i from jsonb_array_elements(s->'incumbencies') i
   where (i->>'effectiveStart')::date<=d and (i->>'effectiveEnd' is null or d<(i->>'effectiveEnd')::date) limit 1) incumbent
  from facts
 ) select coalesce(jsonb_agg(jsonb_build_object('serviceDate',d::text,'dayOfWeek',a->'dayOfWeek',
   'slotId',a->'slotId','personId',incumbent->'personId','vacant',n=0,'status',a->'status',
   'shift',a->'shift','lunch',a->'lunch') order by (a->>'dayOfWeek')::int,a->>'slotId'),'[]'::jsonb),
  count(*) filter(where n>1 or (n=0 and not coalesce((source#>'{version,vacancyCapableSlotIds}') ? (a->>'slotId'),false))
   or (n=0) is distinct from (a->>'status'='vacant_unfilled')
   or a->>'status' not in ('working','vacant_unfilled','departed_named_absent'))
 into roster,matches from dated;
 if matches<>0 or jsonb_array_length(roster)=0
  or (select count(*) from jsonb_array_elements(roster))<>(select count(distinct (r->>'dayOfWeek',r->>'slotId')) from jsonb_array_elements(roster) r)
  or receipt->>'datedRosterDigest' is distinct from public.static_weekly_digest_jsonb(roster) then
  raise exception using errcode='23514',message='shift-end receipt must bind one exact dated real roster';
 end if;
 select jsonb_object_agg(d::text,closing) into boundaries from (
  select (r->>'dayOfWeek')::int d,max(r#>>'{shift,end}') closing from jsonb_array_elements(roster) r
  where r->'vacant'='false'::jsonb and r->>'status'='working' group by 1
 ) endings;
 if boundaries is null or (select count(*) from jsonb_object_keys(boundaries))<>7
  or boundaries is distinct from receipt->'staffedDepartureByDay' then
  raise exception using errcode='23514',message='shift-end boundary requires real working incumbent on every day';
 end if;
 for chain in select value from jsonb_array_elements(receipt->'parentChains') loop
  perform public.static_weekly_assert_exact_object(chain,
   array['dayOfWeek','parentWorkId','physicalIdentityDigest','workloadBefore','workloadAfter','segments'],
   array['dayOfWeek','parentWorkId','physicalIdentityDigest','workloadBefore','workloadAfter','segments'],'shift-end parent chain');
  day:=(chain->>'dayOfWeek')::int; key:=day::text||':'||(chain->>'parentWorkId');
  select count(*) into matches from jsonb_array_elements(source#>'{version,assignments}') w
   where w->>'dayOfWeek'=day::text and w->>'workId'=chain->>'parentWorkId';
  if matches<>1 or key=any(parent_seen) then raise exception 'shift-end parent must exist exactly once'; end if;
  parent_seen:=array_append(parent_seen,key);
  select w into parent from jsonb_array_elements(source#>'{version,assignments}') w
   where w->>'dayOfWeek'=day::text and w->>'workId'=chain->>'parentWorkId';
  select jsonb_object_agg(k,coalesce(parent->k,'null'::jsonb)) into physical from unnest(array[
   'locationId','locationCodeSnapshot','locationNameSnapshot','includedLocations','serviceMode','requiredQualifications',
   'restrictedSlotIds','restrictions','qualificationProvenance','restrictionProvenance']) k;
  if chain->>'physicalIdentityDigest' is distinct from public.static_weekly_digest_jsonb(physical)
   or chain->'workloadBefore' is distinct from parent->'serviceEffortMinutes'
   or chain->'workloadAfter' is distinct from parent->'serviceEffortMinutes'
   or jsonb_typeof(chain->'segments') is distinct from 'array' or jsonb_array_length(chain->'segments')<1
   or position(':handoff:' in parent->>'workId')>0 or position(':open:' in parent->>'workId')>0 then
   raise exception 'shift-end chain must retain exact immutable parent identity and workload';
  end if;
  previous_end:=parent#>>'{window,start}';final_end:=boundaries->>day::text;total:=0;
  if previous_end='09:45' then
   select r into owner from jsonb_array_elements(roster) r where r->>'slotId'=parent->>'ownerSlotId' and r->>'dayOfWeek'=day::text;
   if not found or parent#>>'{window,end}' is distinct from owner#>>'{shift,end}'
    or parent->'originSlotId' is distinct from parent->'ownerSlotId'
    or not ((policy->'weights') ? (parent->>'locationCodeSnapshot')) then
    raise exception 'immutable normal parent must retain full owning position shift and weight'; end if;
  end if;
  for segment in select value from jsonb_array_elements(chain->'segments') loop
   perform public.static_weekly_assert_exact_object(segment,
    array['workId','ownerSlotId','window','serviceEffortMinutes','kind'],
    array['workId','ownerSlotId','window','serviceEffortMinutes','kind'],'shift-end segment');
   key:=day::text||':'||(segment->>'workId');
   select count(*) into matches from jsonb_array_elements(effective#>'{version,assignments}') w
    where w->>'dayOfWeek'=day::text and w->>'workId'=segment->>'workId';
   if matches<>1 or key=any(seen) then raise exception 'derived segment must occur exactly once'; end if;
   seen:=array_append(seen,key);
   select w into work from jsonb_array_elements(effective#>'{version,assignments}') w
    where w->>'dayOfWeek'=day::text and w->>'workId'=segment->>'workId';
   perform public.static_weekly_v3_assert_window(segment->'window','shift-end segment');
   if segment#>>'{window,start}' is distinct from previous_end
    or segment->'window' is distinct from work->'window'
    or segment->'ownerSlotId' is distinct from work->'ownerSlotId'
    or segment->'serviceEffortMinutes' is distinct from work->'serviceEffortMinutes'
    or jsonb_typeof(segment->'serviceEffortMinutes') is distinct from 'number'
    or (segment->>'serviceEffortMinutes')::numeric<=0
    or (segment->>'serviceEffortMinutes')::numeric<>trunc((segment->>'serviceEffortMinutes')::numeric)
    or (work-'workId'-'ownerSlotId'-'originSlotId'-'window'-'serviceEffortMinutes'-'serviceEffortProvenance')
       is distinct from (parent-'workId'-'ownerSlotId'-'originSlotId'-'window'-'serviceEffortMinutes'-'serviceEffortProvenance')
    or work->'ownerSlotId' is distinct from work->'originSlotId'
    or work->>'serviceEffortProvenance' is distinct from ((parent->>'serviceEffortProvenance')||
       case when jsonb_array_length(chain->'segments')>1 then ';shift-split-preserves-budget' else '' end) then
    raise exception 'derived segment changed immutable work, exact workload or contiguous window';
   end if;
   previous_end:=segment#>>'{window,end}';total:=total+(segment->>'serviceEffortMinutes')::numeric;
   if parent#>>'{window,start}'<>'09:45' then
    if work is distinct from parent or segment->>'kind' is distinct from 'baseline' then raise exception 'non-closing work must be unchanged'; end if;
   else
    select r into person from jsonb_array_elements(roster) r where r->>'slotId'=work->>'ownerSlotId' and r->>'dayOfWeek'=day::text;
    select a into owner from jsonb_array_elements(source#>'{version,slotAvailability}') a where a->>'slotId'=work->>'ownerSlotId' and a->>'dayOfWeek'=day::text;
    if person is null or owner is null or work#>>'{window,start}'<person#>>'{shift,start}'
     or previous_end>person#>>'{shift,end}' or previous_end>final_end
     or (work->'restrictedSlotIds') ? (work->>'ownerSlotId')
     or not ((owner->'qualifications') @> (work->'requiredQualifications'))
     or exists(select 1 from jsonb_array_elements(work->'includedLocations') loc where (owner->'restrictions') ? (loc->>'locationId')) then
     raise exception 'derived normal responsibility has off-duty or ineligible position'; end if;
    if segment->>'kind'='baseline' then
     if work->'workId' is distinct from parent->'workId' or work->'ownerSlotId' is distinct from parent->'ownerSlotId' then raise exception 'baseline segment identity changed'; end if;
    elsif segment->>'kind' in ('open','handoff') then
     if work->>'workId' is distinct from (parent->>'workId')||':'||(segment->>'kind')||':'||(work#>>'{window,start}')||':'||(work->>'ownerSlotId')
      or (segment->>'kind'='open') is distinct from (person->'vacant'='true'::jsonb)
      or (segment->>'kind'='handoff' and (person->>'status'<>'working' or person->>'personId' is null))
      or (person#>>'{lunch,start}'<=work#>>'{window,start}' and work#>>'{window,start}'<person#>>'{lunch,end}') then
      raise exception 'physical handoff or explicit OPEN segment identity invalid'; end if;
    else raise exception 'unknown derived segment kind'; end if;
   end if;
  end loop;
  if total<>(parent->>'serviceEffortMinutes')::numeric
   or (parent#>>'{window,start}'='09:45' and previous_end is distinct from final_end) then
   raise exception 'parent chain must conserve workload and reach final staffed boundary'; end if;
 end loop;
 if cardinality(seen)<>jsonb_array_length(effective#>'{version,assignments}') then raise exception 'unaccounted derived work'; end if;

 -- A policy string alone never authorizes a new recipient. Every named
 -- handoff must occur exactly once in the already-validated immutable
 -- parent chain, at the departing source worker's actual shift end, with a
 -- real eligible/on-duty recipient and all required directed edges. The
 -- accepted six-key historical policy follows this block without change.
 for named in select value from jsonb_array_elements(coalesce(policy->'namedHandoffs','[]'::jsonb)) loop
  perform public.static_weekly_assert_exact_object(named,
   array['dayOfWeek','locationCode','at','fromSlotId','toSlotId','source'],
   array['dayOfWeek','locationCode','at','fromSlotId','toSlotId','source'],'shift-end named handoff');
  if (jsonb_typeof(named->'dayOfWeek')='number'
    and named->>'dayOfWeek' ~ '^[0-6]$'
    and jsonb_typeof(named->'locationCode')='string'
    and (policy->'weights') ? (named->>'locationCode')
    and jsonb_typeof(named->'at')='string'
    and named->>'at' ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
    and jsonb_typeof(named->'fromSlotId')='string'
    and named->>'fromSlotId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    and jsonb_typeof(named->'toSlotId')='string'
    and named->>'toSlotId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    and named->>'fromSlotId'<>named->>'toSlotId'
    and jsonb_typeof(named->'source')='string'
    and length(named->>'source') between 10 and 300) is distinct from true then
   raise exception using errcode='23514',message='shift-end named handoff typed source identity invalid';
  end if;
  named_key:=(named->>'dayOfWeek')||':'||(named->>'locationCode')||':'||(named->>'at');
  if named_key=any(named_seen) then
   raise exception using errcode='23514',message='shift-end named handoff duplicated';
  end if;
  named_seen:=array_append(named_seen,named_key);
  select count(*),max(w->>'workId') into matches,named_parent_id
   from jsonb_array_elements(source#>'{version,assignments}') w
   where w->>'dayOfWeek'=named->>'dayOfWeek'
    and w->>'locationCodeSnapshot'=named->>'locationCode'
    and w#>>'{window,start}'='09:45';
  if matches<>1 then
   raise exception using errcode='23514',message='shift-end named parent source is not unique';
  end if;
  select w into named_parent from jsonb_array_elements(source#>'{version,assignments}') w
   where w->>'dayOfWeek'=named->>'dayOfWeek' and w->>'workId'=named_parent_id;
  select c into named_chain from jsonb_array_elements(receipt->'parentChains') c
   where c->>'dayOfWeek'=named->>'dayOfWeek' and c->>'parentWorkId'=named_parent_id;
  if named_chain is null then
   raise exception using errcode='23514',message='shift-end named parent chain absent';
  end if;
  select count(*) into matches
   from jsonb_array_elements(named_chain->'segments') with ordinality as s(segment,ordinal)
   where s.ordinal>1 and s.segment->>'kind'='handoff'
    and s.segment#>>'{window,start}'=named->>'at'
    and s.segment->>'ownerSlotId'=named->>'toSlotId'
    and (named_chain->'segments'->(s.ordinal::integer-2))->>'ownerSlotId'=named->>'fromSlotId'
    and (named_chain->'segments'->(s.ordinal::integer-2))#>>'{window,end}'=named->>'at';
  if matches<>1 then
   raise exception using errcode='23514',message='shift-end named handoff does not match exactly one derived segment';
  end if;
  select r into named_from from jsonb_array_elements(roster) r
   where r->>'dayOfWeek'=named->>'dayOfWeek' and r->>'slotId'=named->>'fromSlotId';
  select r into named_to from jsonb_array_elements(roster) r
   where r->>'dayOfWeek'=named->>'dayOfWeek' and r->>'slotId'=named->>'toSlotId';
  select a into named_to_availability from jsonb_array_elements(source#>'{version,slotAvailability}') a
   where a->>'dayOfWeek'=named->>'dayOfWeek' and a->>'slotId'=named->>'toSlotId';
  if (named_from->>'status'='working' and named_from->>'personId' is not null
    and named_from#>>'{shift,end}'=named->>'at'
    and named_to->>'status'='working' and named_to->>'personId' is not null
    and named_to#>>'{shift,start}'<=named->>'at'
    and named->>'at'<named_to#>>'{shift,end}'
    and not (named_to#>>'{lunch,start}'<=named->>'at' and named->>'at'<named_to#>>'{lunch,end}')
    and (named_to_availability->'qualifications') @> (named_parent->'requiredQualifications')
    and not ((named_parent->'restrictedSlotIds') ? (named->>'toSlotId'))
    and not exists(select 1 from jsonb_array_elements(case
      when jsonb_array_length(named_parent->'includedLocations')>0 then named_parent->'includedLocations'
      else jsonb_build_array(jsonb_build_object('locationId',named_parent->'locationId')) end) target
      where (named_to_availability->'restrictions') ? (target->>'locationId'))
  ) is distinct from true then
   raise exception using errcode='23514',message='shift-end named handoff source or recipient is not current and eligible';
  end if;
  -- The JS source-derived selector requires a verified directed edge from
  -- at least one exact current-source target-position anchor to every member.
  -- Normal owned members take precedence; only a position owning no normal
  -- row may use its explicit accepted route anchor.
  with anchors as (
   select l->>'locationId' id from jsonb_array_elements(source#>'{version,assignments}') w
    cross join lateral jsonb_array_elements(case when jsonb_array_length(w->'includedLocations')>0
      then w->'includedLocations' else jsonb_build_array(jsonb_build_object('locationId',w->'locationId')) end) l
    where w->>'dayOfWeek'=named->>'dayOfWeek' and w->>'ownerSlotId'=named->>'toSlotId'
     and w#>>'{window,start}'='09:45'
   union all
   select named_to_availability->>'acceptedRouteAnchorLocationId'
    where not exists(select 1 from jsonb_array_elements(source#>'{version,assignments}') w
      where w->>'dayOfWeek'=named->>'dayOfWeek' and w->>'ownerSlotId'=named->>'toSlotId'
       and w#>>'{window,start}'='09:45')
  ), targets as (
   select l->>'locationId' id from jsonb_array_elements(case
     when jsonb_array_length(named_parent->'includedLocations')>0 then named_parent->'includedLocations'
     else jsonb_build_array(jsonb_build_object('locationId',named_parent->'locationId')) end) l
  )
  select count(*) into matches from targets target where not exists(
   select 1 from anchors anchor where anchor.id is not null and
    (anchor.id=target.id or exists(select 1 from jsonb_array_elements(source->'proximity') edge
      where edge->>'fromLocationId'=anchor.id and edge->>'toLocationId'=target.id
       and edge->'verified'='true'::jsonb and jsonb_typeof(edge->'minutes')='number'
       and (edge->>'minutes')::numeric>=0 and (edge->>'minutes')::numeric=trunc((edge->>'minutes')::numeric)
       and nullif(edge->>'provenance','') is not null)));
  if matches<>0 then
   raise exception using errcode='23514',message='shift-end named handoff lacks verified directed source proximity';
  end if;
 end loop;
 if policy ? 'plannedClosingOwnership' then
  if jsonb_typeof(policy->'plannedClosingOwnership') is distinct from 'object'
   or (select jsonb_agg(k order by k) from jsonb_object_keys(policy->'plannedClosingOwnership') k)
     is distinct from '["0","1","2","3","4","5","6"]'::jsonb then
   raise exception 'planned closing source must bind all seven days';end if;
  -- Index the same verified directed edges once. Expanding the complete
  -- proximity graph again for every inherited physical member needlessly
  -- materializes it hundreds of times for a complete weekly schedule.
  select coalesce(jsonb_object_agg(jsonb_build_array(e->>'fromLocationId',e->>'toLocationId')::text,true),'{}'::jsonb)
   into planned_valid_edges from jsonb_array_elements(source->'proximity') e
   where e->'verified'='true'::jsonb and jsonb_typeof(e->'minutes')='number'
    and (e->>'minutes')::numeric>=0 and (e->>'minutes')::numeric=trunc((e->>'minutes')::numeric)
    and nullif(e->>'provenance','') is not null;
  for planned_day,planned_stages in select * from jsonb_each(policy->'plannedClosingOwnership') loop
   if jsonb_typeof(planned_stages) is distinct from 'array' or jsonb_array_length(planned_stages) not between 1 and 8
    then raise exception 'planned closing stages must be bounded';end if;
   select min((r#>>'{shift,end}')::time),max((r#>>'{shift,end}')::time) into planned_previous,planned_last
    from jsonb_array_elements(roster) r where r->>'dayOfWeek'=planned_day and r->>'status'='working'
     and r->'vacant'='false'::jsonb and r->>'personId' is not null;
   if planned_previous is null or planned_previous<='09:45'::time then raise exception 'planned closing needs a real afternoon roster';end if;
   select jsonb_agg(code order by code) into planned_families from
    (select distinct w->>'locationCodeSnapshot' code from jsonb_array_elements(source#>'{version,assignments}') w
     where w->>'dayOfWeek'=planned_day and w#>>'{window,start}'='09:45') f;
   if planned_families is null then raise exception 'planned closing normal families missing';end if;
   -- Before the first departure every family retains its normal source owner.
   if exists(select 1 from jsonb_array_elements(source#>'{version,assignments}') p
    join jsonb_array_elements(effective#>'{version,assignments}') w on w->'dayOfWeek'=p->'dayOfWeek'
     and w->'locationCodeSnapshot'=p->'locationCodeSnapshot'
    where p->>'dayOfWeek'=planned_day and p#>>'{window,start}'='09:45'
     and (w#>>'{window,start}')::time<planned_previous and (w#>>'{window,end}')::time>'09:45'::time
     and w->'ownerSlotId' is distinct from p->'ownerSlotId') then raise exception 'planned closing changed pre-departure ownership';end if;
   for planned_stage in select value from jsonb_array_elements(planned_stages) loop
    perform public.static_weekly_assert_exact_object(planned_stage,array['start','end','owners'],array['start','end','owners'],'planned closing stage');
    perform public.static_weekly_v3_assert_window(planned_stage-'owners','planned closing interval');
    planned_start:=(planned_stage->>'start')::time;planned_end:=(planned_stage->>'end')::time;
    if planned_start<>planned_previous or planned_end>planned_last or jsonb_typeof(planned_stage->'owners') is distinct from 'object'
     or (select jsonb_agg(k order by k) from jsonb_object_keys(planned_stage->'owners') k) is distinct from planned_families
     then raise exception 'planned closing stages must cover every family without gaps';end if;
    for planned_parent in select w from jsonb_array_elements(source#>'{version,assignments}') w
      where w->>'dayOfWeek'=planned_day and w#>>'{window,start}'='09:45' loop
     key:=planned_stage#>>array['owners',planned_parent->>'locationCodeSnapshot'];
     select r into planned_person from jsonb_array_elements(roster) r where r->>'dayOfWeek'=planned_day and r->>'slotId'=key;
     select a into planned_availability from jsonb_array_elements(source#>'{version,slotAvailability}') a
      where a->>'dayOfWeek'=planned_day and a->>'slotId'=key;
     if planned_person is null or planned_availability is null or planned_person->>'status'<>'working'
      or planned_person->>'personId' is null or planned_person->'vacant' is distinct from 'false'::jsonb
      or (planned_person#>>'{shift,start}')::time>planned_start or (planned_person#>>'{shift,end}')::time<planned_end
      or ((planned_person#>>'{lunch,start}')::time<planned_end and planned_start<(planned_person#>>'{lunch,end}')::time)
      or (planned_parent->'restrictedSlotIds') ? key
      or not ((planned_availability->'qualifications') @> (planned_parent->'requiredQualifications'))
      or exists(select 1 from jsonb_array_elements(planned_parent->'includedLocations') loc
       where (planned_availability->'restrictions') ? (loc->>'locationId'))
      then raise exception 'planned closing recipient is absent, off duty, restricted or unqualified';end if;
     if exists(select 1 from jsonb_array_elements(effective#>'{version,assignments}') w
      where w->>'dayOfWeek'=planned_day and w->'locationCodeSnapshot'=planned_parent->'locationCodeSnapshot'
       and (w#>>'{window,start}')::time<planned_end and planned_start<(w#>>'{window,end}')::time
       and w->>'ownerSlotId' is distinct from key) then raise exception 'derived closing owner differs from exact source plan';end if;
     select coalesce(sum(least((w#>>'{window,end}')::time,planned_end)-greatest((w#>>'{window,start}')::time,planned_start)),interval '0')
      into planned_coverage from jsonb_array_elements(effective#>'{version,assignments}') w
      where w->>'dayOfWeek'=planned_day and w->'locationCodeSnapshot'=planned_parent->'locationCodeSnapshot'
       and (w#>>'{window,start}')::time<planned_end and planned_start<(w#>>'{window,end}')::time;
     if planned_coverage<>planned_end-planned_start then raise exception 'derived closing responsibility has a gap or overlap';end if;
     with anchors as (
      select l->>'locationId' id from jsonb_array_elements(source#>'{version,assignments}') w
       cross join lateral jsonb_array_elements(case when jsonb_array_length(w->'includedLocations')>0 then w->'includedLocations'
        else jsonb_build_array(jsonb_build_object('locationId',w->'locationId')) end) l
       where w->>'dayOfWeek'=planned_day and w->>'ownerSlotId'=key and w#>>'{window,start}'='09:45'
      union all select planned_availability->>'acceptedRouteAnchorLocationId' where not exists(
       select 1 from jsonb_array_elements(source#>'{version,assignments}') w
        where w->>'dayOfWeek'=planned_day and w->>'ownerSlotId'=key and w#>>'{window,start}'='09:45')
     ), targets as (select l->>'locationId' id from jsonb_array_elements(case when jsonb_array_length(planned_parent->'includedLocations')>0
       then planned_parent->'includedLocations' else jsonb_build_array(jsonb_build_object('locationId',planned_parent->'locationId')) end) l)
     select count(*) into matches from targets t where not exists(select 1 from anchors a where a.id is not null
      and (a.id=t.id or planned_valid_edges ? jsonb_build_array(a.id,t.id)::text));
     if matches<>0 then raise exception 'planned closing lacks verified directed source proximity';end if;
    end loop;
    planned_previous:=planned_end;
   end loop;
   if planned_previous is distinct from planned_last then raise exception 'planned closing must reach final staffed departure';end if;
  end loop;
 end if;
 -- OPEN may retain a stable baseline position, never a fictitious execution
 -- owner/person. Existing optimizer/document validators retain their checks.
 if exists(select 1 from jsonb_array_elements(p_authority#>'{optimizerResult,assignments}') a
  where a->>'status' in ('OPEN','REVIEW') and (a->>'slotId' is not null or a->>'personId' is not null)) then
  raise exception 'OPEN derived work may not invent execution identity'; end if;
 for day in 0..6 loop
  select count(*),count(distinct id) into matches,location_count from (
   select l->>'locationId' id from jsonb_array_elements(source#>'{version,assignments}') w
   cross join lateral jsonb_array_elements(case when jsonb_array_length(w->'includedLocations')>0 then w->'includedLocations'
     else jsonb_build_array(jsonb_build_object('locationId',w->'locationId')) end) l
   where w->>'dayOfWeek'=day::text and w#>>'{window,start}'='09:45'
  ) locations;
  if matches<>location_count then raise exception 'immutable normal template contains duplicate physical ownership'; end if;
  span:=(extract(epoch from (boundaries->>day::text)::time)/60)::int-585;
  if span<=0 then raise exception 'invalid staffed operating span'; end if;
  minute_samples:=minute_samples+span;location_samples:=location_samples+span*location_count;
 end loop;
 if receipt->'continuity' is distinct from jsonb_build_object('minuteSamples',minute_samples,'locationMinuteChecks',location_samples,
  'coverageGaps',0,'duplicateLocations',0,'staffedDepartureByDay',boundaries,
  'scope','dated real-staff handoffs and explicit vacancy OPEN responsibility until final staffed departure; lunch overlay checked separately') then
  raise exception 'shift-end continuity counters must be independently recomputed'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v9_fill_vacant_roster_slot(p_source_id uuid, p_slot_id uuid, p_new_employee_name text, p_effective_start date, p_reason text, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_completion jsonb; v_actor jsonb; v_prior public.weekly_schedule_command_receipts%rowtype; v_slot public.weekly_roster_slots%rowtype;
  v_name text:=regexp_replace(btrim(coalesce(p_new_employee_name,'')),'\s+',' ','g');
  v_request jsonb; v_request_digest text; v_content_digest text; v_command uuid:=gen_random_uuid();
  v_revision bigint; v_response jsonb; v_created jsonb; v_employee_id uuid; v_incumbency uuid:=gen_random_uuid();
  v_current_week date:=public.sch_service_date(statement_timestamp())-(extract(isodow from public.sch_service_date(statement_timestamp()))::integer-1);
begin
  perform public.static_weekly_v3_assert_control_plane(); v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_manager_id,v_actor->>'manager_name',p_idempotency_key,'fill_vacant_slot');
  if p_source_id is null or p_slot_id is null or length(v_name) not between 2 and 160 or p_effective_start is null
    or extract(isodow from p_effective_start)::integer<>1
    or nullif(btrim(coalesce(p_reason,'')),'') is null or char_length(p_reason)>500 or p_reason~'[\x00-\x1f\x7f]' then
    raise exception using errcode='23514',message='filling a vacancy requires a stable slot, fresh employee name, Monday effective date, and bounded reason';
  end if;
  v_request:=jsonb_build_object('operation','fill_vacant_slot','source_id',p_source_id,'slot_id',p_slot_id,'new_employee_name',v_name,'effective_start',p_effective_start,'reason',p_reason,'expected_revision',p_expected_revision,'actor_manager_id',p_manager_id);
  v_request_digest:=public.static_weekly_digest_jsonb(v_request); perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts where actor_manager_id=p_manager_id and idempotency_key=p_idempotency_key;
  if found then if v_prior.request_digest<>v_request_digest then raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs'; end if; perform public.static_weekly_v8_assert_vacancy_receipt(v_prior.command_id,'fill_vacant_slot'); return v_prior.response_json; end if;
  -- A receipt is permanent semantic evidence. Time-dependent new-operation
  -- eligibility must never hide a successful response after its week ends.
  if p_effective_start<v_current_week then
    raise exception using errcode='23514',message='a new vacancy fill cannot start before the current week';
  end if;
  select * into v_slot from public.weekly_roster_slots where slot_id=p_slot_id for share;
  if not found then raise exception using errcode='P0002',message='vacant stable roster position was not found'; end if;
  -- A vacated position is reusable; reject any overlapping or future incumbent.
  if exists(select 1 from public.v_weekly_roster_slot_incumbency_ranges
      where slot_id=p_slot_id and (effective_end is null or p_effective_start<effective_end))
    or (exists(select 1 from public.weekly_roster_slot_incumbencies where slot_id=p_slot_id)
      and not exists(select 1 from public.weekly_roster_slot_staffing_states s
        where s.slot_id=p_slot_id and s.effective_start<=p_effective_start
          and s.staffing_state='vacant_unfilled' and s.employee_id is null
          and not exists(select 1 from public.weekly_roster_slot_staffing_states later
            where later.slot_id=p_slot_id and later.effective_start<=p_effective_start
              and (later.effective_start,later.authority_revision)>(s.effective_start,s.authority_revision)))) then
    raise exception using errcode='23514',message='only a never-filled or explicitly vacated stable position with no current or future incumbent can be filled';
  end if;
  v_completion:=public.static_weekly_v9_roster_completion_context(p_source_id,p_slot_id,p_effective_start,true);
  v_created:=public.static_weekly_v5_create_replacement_employee(v_name,p_manager_id);
  v_employee_id:=(v_created#>>'{employee,id}')::uuid;
  v_content_digest:=public.static_weekly_digest_jsonb(v_request-'expected_revision'-'actor_manager_id'-'operation');
  v_revision:=public.static_weekly_advance_authority(p_expected_revision,'fill_vacant_slot',p_manager_id,v_actor->>'manager_name',v_command,v_content_digest);
  insert into public.weekly_roster_slot_incumbencies(incumbency_id,slot_id,person_id,person_name_snapshot,effective_start,created_by_manager_id,created_by_manager_name_snapshot,content_digest)
  values(v_incumbency,p_slot_id,v_employee_id,v_name,p_effective_start,p_manager_id,v_actor->>'manager_name',v_content_digest);
  insert into public.weekly_roster_slot_staffing_states(slot_id,employee_id,staffing_state,effective_start,authority_revision,actor_manager_id,actor_manager_name_snapshot,reason,content_digest)
  values(p_slot_id,v_employee_id,'working',p_effective_start,v_revision,p_manager_id,v_actor->>'manager_name',p_reason,v_content_digest);
  v_response:=public.static_weekly_response_json('fill_vacant_slot',v_revision,v_content_digest,v_request_digest,jsonb_build_object(
    'slot_id',p_slot_id,'slot_label',v_slot.slot_label,'new_employee_id',v_employee_id,'new_employee_name',v_name,
    'new_employee_code',v_created#>>'{employee,employee_code}','effective_start',p_effective_start,'phone_assignment',null
  )||v_completion);
  insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest)
  values(v_command,p_manager_id,v_actor->>'manager_name','fill_vacant_slot',p_idempotency_key,p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest);
  return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v9_read_completed_roster_change(p_manager_id uuid, p_idempotency_key text, p_operation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
 v_mutation public.weekly_schedule_command_receipts%rowtype;
 v_receipt public.weekly_schedule_command_receipts%rowtype;
 v_projection public.weekly_schedule_compiled_projections%rowtype;
 v_lunch public.weekly_schedule_lunch_documents%rowtype;
 v_date date;v_week date;v_projection_snapshot jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform public.custodial_assert_manager(p_manager_id);
 perform public.static_weekly_v3_manager_actor(p_manager_id);
 if p_operation is null or p_operation not in ('vacate_roster_slot','fill_vacant_slot','restore_existing_employee') or p_manager_id is null or nullif(btrim(p_idempotency_key),'') is null then
  raise exception using errcode='22023',message='completed vacancy lookup requires exact manager and command identity';
 end if;
 select * into v_mutation from public.weekly_schedule_command_receipts
  where actor_manager_id=p_manager_id and idempotency_key=p_idempotency_key and command_type=p_operation;
 if not found then return null; end if;
 perform public.static_weekly_v8_assert_vacancy_receipt(v_mutation.command_id,p_operation);
 if v_mutation.response_json#>>'{data,completion_mode}'='mutation_only'
   and (v_mutation.response_json->'data') ? 'original_publication_id'
   and v_mutation.response_json#>'{data,original_publication_id}'='null'::jsonb then
  return v_mutation.response_json;
 end if;
 if v_mutation.response_json#>>'{data,completion_mode}' is distinct from 'projection_required'
   or nullif(v_mutation.response_json#>>'{data,original_publication_id}','') is null then
  raise exception using errcode='23514',message='completed vacancy original completion binding is missing or inconsistent';
 end if;
 select * into v_receipt from public.weekly_schedule_command_receipts
  where actor_manager_id=p_manager_id and idempotency_key='projection-'||encode(extensions.digest(convert_to(p_idempotency_key,'UTF8'),'sha256'),'hex');
 if not found then
  raise exception using errcode='23514',message='completed vacancy required projection receipt is missing';
 end if;
 perform public.static_weekly_v8_assert_vacancy_receipt(v_receipt.command_id,'materialize_projection');
 v_date:=(v_mutation.request_canonical_json->>'effective_start')::date;
 v_week:=v_date-(extract(isodow from v_date)::integer-1);
 if v_receipt.command_type is distinct from 'materialize_projection'
  or v_receipt.expected_revision is distinct from (v_mutation.response_json->>'revision')::bigint
  or (v_receipt.response_json->>'revision')::bigint is distinct from v_receipt.expected_revision+1
  or v_receipt.request_canonical_json->>'service_date' is distinct from v_week::text
  or v_receipt.request_canonical_json->>'publication_id' is distinct from v_mutation.response_json#>>'{data,original_publication_id}' then
  raise exception using errcode='23514',message='completed vacancy projection receipt does not bind the exact mutation';
 end if;
 select * into v_projection from public.weekly_schedule_compiled_projections
  where projection_id=(v_receipt.response_json#>>'{data,projection_id}')::uuid;
 if not found or v_projection.week_start is distinct from v_week
  or v_projection.publication_id::text is distinct from v_receipt.request_canonical_json->>'publication_id'
  or v_projection.authority_digest is distinct from v_receipt.request_canonical_json#>>'{projection_envelope,authority_digest}'
  or v_projection.replay_digest is distinct from v_receipt.request_canonical_json->>'replay_digest' then
  raise exception using errcode='23514',message='completed vacancy immutable projection binding is missing or inconsistent';
 end if;
 select * into v_lunch from public.weekly_schedule_lunch_documents where projection_id=v_projection.projection_id;
 if not found or v_lunch.accepted_by_manager_id is distinct from p_manager_id
  or v_lunch.document_identity is distinct from v_lunch.document_json->>'document_identity'
  or v_lunch.document_json->>'base_authority_digest' is distinct from v_projection.authority_digest
  or v_lunch.document_json->>'base_replay_digest' is distinct from v_projection.replay_digest then
  raise exception using errcode='23514',message='completed vacancy accepted lunch binding is missing or inconsistent';
 end if;
 perform public.static_weekly_v8_assert_lunch_document(v_projection.projection_id,v_lunch.document_json);
 -- Match the immutable projection descriptor in the manager snapshot used by
 -- the first success. Do not read today's mutable latest-projection selector.
 v_projection_snapshot:=jsonb_build_object(
  'projection_id',v_projection.projection_id::text,'publication_id',v_projection.publication_id::text,
  'version_id',v_projection.version_id::text,'week_start',v_projection.week_start::text,'week_end',v_projection.week_end::text,
  'compiler_version',v_projection.compiler_version,'metrics',v_projection.metrics_json,
  'replay_digest',v_projection.replay_digest,'compiled_at',v_projection.compiled_at,
  'assignments',v_projection.projection_envelope->'assignments');
 return v_receipt.response_json||jsonb_build_object('data',
  (v_mutation.response_json->'data')||(v_receipt.response_json->'data')||
  jsonb_build_object('current_projection',v_projection_snapshot,'mutation',v_mutation.response_json->'data'));
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v9_roster_completion_context(p_source_id uuid, p_slot_id uuid, p_effective_start date, p_require_vacancy boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare source public.static_weekly_authority_source_documents%rowtype;
 publication uuid; publication_source uuid; matches integer;
begin
 perform public.static_weekly_v3_assert_control_plane();
 if p_source_id is null or p_slot_id is null or p_effective_start is null or p_require_vacancy is null then
  raise exception 'roster completion requires exact source, position and date'; end if;
 select * into source from public.static_weekly_authority_source_documents
  where source_id=p_source_id and active and retired_at is null for share;
 if not found then raise exception 'roster completion requires active registered source'; end if;
 select count(*) into matches from jsonb_array_elements(source.canonical_source->'slots') s
  where s->>'id'=p_slot_id::text and coalesce(s->'contractorCapacity','false'::jsonb)='false'::jsonb;
 if matches<>1 or (p_require_vacancy and not coalesce((source.canonical_source#>'{version,vacancyCapableSlotIds}') ? p_slot_id::text,false)) then
  raise exception 'registered source must bind the exact vacancy-capable stable employee position'; end if;
 select p.publication_id,v.authority_source_id into publication,publication_source
  from public.weekly_schedule_publications p join public.weekly_schedule_versions v on v.version_id=p.version_id
  where p.version_id=public.static_weekly_effective_version(p_effective_start-(extract(isodow from p_effective_start)::int-1));
 if publication is not null and publication_source is distinct from p_source_id then
  raise exception 'roster source does not own the effective published baseline'; end if;
 return jsonb_build_object('source_id',p_source_id,'source_digest',source.source_digest,
  'completion_mode',case when publication is null then 'mutation_only' else 'projection_required' end,
  'original_publication_id',publication);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_vacancy_reviewed_current(r static_weekly_vacancy_reviewed_preparations, p_generation bigint, p_actor_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE packet jsonb;v jsonb;snapshot jsonb;original_source jsonb;current_source jsonb;published jsonb;week date;BEGIN
 IF r.state<>'UNSUBMITTED' OR r.generation IS DISTINCT FROM p_generation THEN RETURN false;END IF;
 packet:=public.static_weekly_vacancy_reviewed_packet(r.packet_utf8,r.manager_id,r.idempotency_key);
 IF public.static_weekly_digest_text(r.packet_utf8) IS DISTINCT FROM r.payload_sha256 THEN
  RAISE EXCEPTION 'Vacancy original stored checksum changed';END IF;
 v:=(packet->>'previewUtf8')::jsonb;week:=(v->>'weekStart')::date;
 IF v->>'managerName' IS DISTINCT FROM p_actor_name
  OR (v->>'effectiveStart')::date IS DISTINCT FROM public.sch_service_date(statement_timestamp()) THEN RETURN false;END IF;
 snapshot:=public.static_weekly_v3_read_manager_snapshot(week);
 IF snapshot->'authority_revision' IS DISTINCT FROM v->'expectedRevision'
  OR snapshot#>>'{current_publication,publication_id}' IS DISTINCT FROM v->>'publicationId'
 THEN RETURN false;END IF;
 SELECT jsonb_build_object('compiler_input',canonical_source) INTO original_source
  FROM public.static_weekly_authority_source_documents WHERE source_id=(v->>'sourceId')::uuid
   AND active IS TRUE AND retired_at IS NULL AND source_digest=public.static_weekly_digest_jsonb(canonical_source) FOR SHARE;
 IF NOT FOUND THEN RETURN false;END IF;
 current_source:=public.static_weekly_v3_read_authority_source((v->>'sourceId')::uuid,week);
 published:=public.static_weekly_v3_read_publication_source((v->>'publicationId')::uuid,week);
 RETURN coalesce(v->>'registeredSourceDigest'=public.static_weekly_digest_jsonb(original_source->'compiler_input')
  AND v->>'currentSourceDigest'=public.static_weekly_digest_jsonb(current_source->'compiler_input')
  AND (packet->>'preInputUtf8')::jsonb=public.static_weekly_vacancy_reviewed_input(published,week),false);
END $function$

CREATE OR REPLACE FUNCTION public.static_weekly_version_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare source_comparison public.weekly_schedule_versions%rowtype;
begin
  if tg_op='DELETE' then raise exception using errcode='23514',message='weekly versions are immutable'; end if;
  if tg_op='INSERT' then
    if new.lifecycle_state='published' and current_setting('app.static_weekly_publish_write',true) is distinct from 'on' then raise exception using errcode='23514',message='published versions require v2 publication'; end if;
    return new;
  end if;
  if old.lifecycle_state='draft' and current_setting('app.static_weekly_publish_write',true)='on' and new.lifecycle_state='published' and new.revision=old.revision then return new; end if;
  -- v3 binds a just-created v2 draft to a registered immutable source inside
  -- the same SECURITY DEFINER transaction. No other field/revision may move.
  if old.lifecycle_state='draft' and current_setting('app.static_weekly_source_bind',true)='on' and old.authority_source_id is null and new.authority_source_id is not null then
    source_comparison:=new;
    source_comparison.authority_source_id:=old.authority_source_id;
    if source_comparison is not distinct from old then return new; end if;
  end if;
  if old.lifecycle_state<>'draft' or current_setting('app.static_weekly_draft_write',true) is distinct from 'on' or new.lifecycle_state<>'draft' or new.revision<>old.revision+1 then raise exception using errcode='23514',message='draft versions require a revision-checked v2 command'; end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.tool_commit_cleaning_workflow_authoritative(p_client_session_id text, p_client_completion_id text, p_device_id text, p_location_code text, p_client_started_at text, p_client_ended_at text, p_response_json jsonb, p_scan_evidence jsonb, p_correlation_id text, p_context_id text, p_submission_proof text, p_authenticated_credential_id text, p_native_finish_scan_entry_id text, p_native_completion_attestation_version text, p_native_completion_attestation text, p_native_route_proof_secret text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_completion_id uuid; v_context_id uuid; v_finish_scan_entry_id uuid; v_result jsonb; v_started_at timestamptz; v_completed_at timestamptz;
  v_native_completed_at timestamptz; v_attestation_sha256 text;
begin
  if jsonb_typeof(p_response_json)='object' and not (p_response_json ? 'work_result') then
    if not public.custodial_oc24_legacy_replay_allowed(p_context_id,p_client_session_id,p_client_completion_id,
      p_device_id,p_location_code,p_client_started_at,p_client_ended_at,p_response_json,p_scan_evidence,p_correlation_id) then
      raise exception using errcode='22023',message='explicit work_result required; no exact accepted legacy completion';
    end if;
  else
    perform public.custodial_oc24_assert_completion_selection(p_response_json);
  end if;
  begin
    v_completion_id:=lower(btrim(coalesce(p_client_completion_id,'')))::uuid;
  exception when others then
    raise exception using errcode='22023',message='p_client_completion_id must be a UUID';
  end;
  perform public.custodial_require_native_route_proof_secret(p_native_route_proof_secret);
  if btrim(coalesce(p_native_completion_attestation_version,''))<>'custodial-native-completion.v2'
     or lower(btrim(coalesce(p_native_completion_attestation,''))) !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='42501',message='a verified native completion attestation is required';
  end if;
  begin
    v_context_id:=lower(btrim(p_context_id))::uuid;
    v_finish_scan_entry_id:=lower(btrim(p_native_finish_scan_entry_id))::uuid;
    v_native_completed_at:=btrim(p_client_ended_at)::timestamptz;
  exception when others then
    raise exception using errcode='22023',message='native completion evidence is malformed';
  end;
  if not isfinite(v_native_completed_at) then
    raise exception using errcode='22023',message='native completion evidence is malformed';
  end if;
  if jsonb_typeof(p_scan_evidence)<>'array'
     or (select count(*) from jsonb_array_elements(p_scan_evidence) e where e->>'event_type'='scan_finish')<>1
     or not exists(
       select 1 from jsonb_array_elements(p_scan_evidence) e
       where e->>'event_type'='scan_finish'
         and lower(e->>'client_event_id')=v_finish_scan_entry_id::text
         and e->>'result'='ok'
         and e->>'scanned_at'=public.custodial_canonical_utc_millis(v_native_completed_at)
         and e->'payload_json'->>'entry_source'='native-nfc'
     ) then
    raise exception using errcode='42501',message='the signed physical NFC finish scan is required';
  end if;
  if exists (
    select 1 from public.custodial_offline_actor_contexts c
    where c.context_id=v_context_id and c.native_scan_entry_id=v_finish_scan_entry_id
  ) then
    raise exception using errcode='42501',message='native finish scan must differ from the start scan';
  end if;
  v_attestation_sha256:=encode(extensions.digest(convert_to(lower(btrim(p_native_completion_attestation)),'UTF8'),'sha256'),'hex');
  if exists(
    select 1 from public.custodial_offline_actor_contexts c where c.context_id=v_context_id
      and (c.native_start_attestation_version is distinct from 'custodial-native-start.v1'
        or c.native_scan_entry_id is null
        or (c.native_completion_attestation_version is not null and
          (c.native_completion_attestation_version<>p_native_completion_attestation_version
            or c.native_completion_attestation_sha256<>v_attestation_sha256
            or c.native_completed_at<>v_native_completed_at
            or c.native_finish_scan_entry_id<>v_finish_scan_entry_id)))
  ) then
    raise exception using errcode='23505',message='native completion attestation does not match the frozen occurrence';
  end if;
  v_result:=public.custodial_commit_offline_occurrence(
    p_client_session_id,v_completion_id::text,p_device_id,p_location_code,p_client_started_at,p_client_ended_at,
    p_response_json,p_scan_evidence,p_correlation_id,p_context_id,p_submission_proof,p_authenticated_credential_id,p_backend_execution_secret
  );
  if v_result->>'status'='closed' then
    update public.custodial_offline_actor_contexts
       set native_completion_attestation_version=p_native_completion_attestation_version,
           native_completion_attestation_sha256=v_attestation_sha256,
           native_completed_at=v_native_completed_at,
           native_finish_scan_entry_id=v_finish_scan_entry_id
     where context_id=v_context_id and native_completion_attestation_version is null;
    if not found and not exists(
      select 1 from public.custodial_offline_actor_contexts c
      where c.context_id=v_context_id
        and c.native_completion_attestation_version=p_native_completion_attestation_version
        and c.native_completion_attestation_sha256=v_attestation_sha256
        and c.native_completed_at=v_native_completed_at
        and c.native_finish_scan_entry_id=v_finish_scan_entry_id
    ) then
      raise exception using errcode='23505',message='native completion attestation does not match the frozen occurrence';
    end if;
  end if;
  begin
    v_started_at:=nullif(v_result->>'started_at','')::timestamptz;
    v_completed_at:=nullif(coalesce(v_result->>'completed_at',v_result->>'ended_at'),'')::timestamptz;
  exception when others then
    return v_result||jsonb_build_object('native_completion_attested',v_result->>'status'='closed');
  end;
  return v_result || jsonb_strip_nulls(jsonb_build_object(
    'started_at',public.custodial_canonical_utc_millis(v_started_at),
    'ended_at',public.custodial_canonical_utc_millis(v_completed_at),
    'completed_at',public.custodial_canonical_utc_millis(v_completed_at),
    'native_completion_attested',v_result->>'status'='closed',
    'native_finish_scan_entry_id',case when v_result->>'status'='closed' then v_finish_scan_entry_id end
  ));
end
$function$

CREATE OR REPLACE FUNCTION public.tool_complete_session_authoritative(p_session_uuid text, p_response_json jsonb, p_device_id text, p_client_completion_id text, p_authenticated_credential_id text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_session record;
  v_context public.custodial_offline_actor_contexts%rowtype;
  v_existing public.custodial_offline_reconciliation_records%rowtype;
  v_proof text := encode(extensions.gen_random_bytes(32), 'hex');
  v_occurrence_fingerprint text;
  v_assignment_change_id uuid;
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  select s.*, d.device_id as canonical_device_id, l.location_code, c.credential_id
    into v_session from public.sessions s join public.devices d on d.id=s.device_id join public.locations l on l.id=s.location_id
    join public.device_auth_credentials c on c.credential_id=nullif(lower(btrim(p_authenticated_credential_id)),'')::uuid and c.device_id=s.device_id
   where s.session_uuid=p_session_uuid or s.client_session_id=p_session_uuid
   order by case when s.session_uuid=p_session_uuid then 0 else 1 end limit 1 for update of s;
  if v_session.id is null or upper(btrim(coalesce(p_device_id,'')))<>upper(v_session.canonical_device_id) then
    raise exception using errcode='42501', message='legacy completion is not bound to an authenticated server session';
  end if;
  -- A legacy caller never receives the one-time proof.  Its exact retry is
  -- therefore resolved from the immutable reconciliation record, while any
  -- altered completion id or response is fenced as an identity conflict.
  select * into v_existing from public.custodial_offline_reconciliation_records
    where client_session_id=v_session.client_session_id or client_completion_id=btrim(p_client_completion_id)
    order by case when client_completion_id=btrim(p_client_completion_id) then 0 else 1 end
    limit 1 for update;
  if v_existing.reconciliation_id is not null then
    if v_existing.client_session_id=v_session.client_session_id
       and v_existing.client_completion_id=btrim(p_client_completion_id)
       and v_existing.payload_json=jsonb_build_object('response_json',coalesce(p_response_json,'{}'::jsonb),'scan_evidence','[]'::jsonb) then
      insert into public.custodial_offline_reconciliation_audits(reconciliation_id,event_type,evidence_json)
      values(v_existing.reconciliation_id,'replayed',jsonb_build_object('exact_legacy_adapter_replay',true));
      return v_existing.result_json || jsonb_build_object('reconciliation_id',v_existing.reconciliation_id,'replayed',true);
    end if;
    return public.custodial_quarantine_offline_submission(
      v_session.client_session_id,p_client_completion_id,v_existing.context_id,
      encode(extensions.digest(convert_to(v_session.client_session_id||':'||coalesce(p_client_completion_id,'')||':legacy-conflict','UTF8'),'sha256'),'hex'),
      jsonb_build_object('response_json',coalesce(p_response_json,'{}'::jsonb),'scan_evidence','[]'::jsonb),
      'legacy_adapter_payload_fingerprint_conflict','{}'::jsonb,p_backend_execution_secret);
  end if;
  select * into v_context from public.custodial_offline_actor_contexts where client_session_id=v_session.client_session_id for update;
  if v_context.context_id is null then
    select assignment_change_id into v_assignment_change_id from public.custodial_employee_device_assignment_history
      where device_id=v_session.device_id and new_employee_id=v_session.employee_id order by changed_at desc limit 1;
    if v_assignment_change_id is null then raise exception using errcode='42501', message='legacy completion has no authoritative assignment epoch'; end if;
    v_occurrence_fingerprint := encode(extensions.digest(convert_to(jsonb_build_object('legacy_server_session_id',v_session.id::text,'employee_id',v_session.employee_id::text,'device_id',v_session.device_id::text,'location_id',v_session.location_id::text,'started_at',v_session.started_at,'client_session_id',v_session.client_session_id)::text,'UTF8'),'sha256'),'hex');
    insert into public.custodial_offline_actor_contexts(client_session_id,device_id,employee_id,credential_id,assignment_epoch,assignment_change_id,location_id,canonical_location_code,location_aliases,started_at,occurrence_fingerprint,expires_at)
    select v_session.client_session_id,v_session.device_id,v_session.employee_id,v_session.credential_id,d.assignment_epoch,v_assignment_change_id,v_session.location_id,v_session.location_code,jsonb_build_array(v_session.location_code),v_session.started_at,v_occurrence_fingerprint,now()+interval '7 days'
      from public.devices d where d.id=v_session.device_id
    returning * into v_context;
    insert into public.custodial_offline_submission_proofs(context_id,proof_digest) values(v_context.context_id,encode(extensions.digest(convert_to(v_proof,'UTF8'),'sha256'),'hex'));
  else
    raise exception using errcode='0A000', message='legacy completion must use the existing canonical occurrence adapter';
  end if;
  return public.custodial_commit_offline_occurrence(v_context.client_session_id,p_client_completion_id,v_session.canonical_device_id,v_session.location_code,
    v_context.started_at::text,coalesce(v_session.ended_at,now())::text,coalesce(p_response_json,'{}'::jsonb),'[]'::jsonb,
    'legacy-completion:'||p_client_completion_id,v_context.context_id::text,v_proof,v_context.credential_id::text,p_backend_execution_secret);
end
$function$

CREATE OR REPLACE FUNCTION public.tool_finish_session_exact(p_session_identifier text, p_device_id text, p_finish_operation_id uuid, p_client_ended_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_identifier text := nullif(btrim(coalesce(p_session_identifier, '')), '');
  v_device_pk uuid;
  v_canonical_device_id text;
  v_session public.sessions%rowtype;
  v_location public.locations%rowtype;
  v_employee public.employees%rowtype;
  v_ended_at timestamptz;
  v_duration_minutes integer;
  v_replayed boolean := false;
begin
  if v_identifier is null then
    raise exception using errcode = '22023', message = 'p_session_identifier is required';
  end if;
  if p_finish_operation_id is null then
    raise exception using errcode = '22023', message = 'p_finish_operation_id is required';
  end if;

  select d.id, d.device_id
    into v_device_pk, v_canonical_device_id
  from public.device_aliases da
  join public.devices d on d.id = da.canonical_device_id and d.active is true
  where da.active is true
    and upper(btrim(da.alias_identifier)) = upper(btrim(p_device_id))
  union all
  select d.id, d.device_id
  from public.devices d
  where d.active is true
    and upper(btrim(d.device_id)) = upper(btrim(p_device_id))
  limit 1;

  if v_device_pk is null then
    raise exception 'Active device not found: %', p_device_id;
  end if;

  if exists (
    select 1 from public.sessions s
    where s.finish_operation_id = p_finish_operation_id
      and s.session_uuid <> v_identifier
      and coalesce(s.client_session_id, '') <> v_identifier
  ) then
    raise exception using errcode = '23505', message = 'Finish operation id is already bound to another session';
  end if;

  select s.* into v_session
  from public.sessions s
  where (s.session_uuid = v_identifier or s.client_session_id = v_identifier)
    and s.device_id = v_device_pk
  order by case when s.session_uuid = v_identifier then 0 else 1 end
  for update
  limit 1;

  if v_session.id is null then
    raise exception 'Session not found for exact server/client identifier and device: %', v_identifier;
  end if;

  select * into v_location from public.locations where id = v_session.location_id;
  select * into v_employee from public.employees where id = v_session.employee_id;

  if v_session.status = 'cancelled' then
    return jsonb_build_object(
      'session_uuid', v_session.session_uuid,
      'client_session_id', v_session.client_session_id,
      'status', 'cancelled',
      'terminal', true,
      'discard_local_workflow', true,
      'replayed', true
    );
  end if;

  if v_session.status not in ('active', 'pending_submit', 'closed') then
    raise exception 'Session % cannot transition from status %', v_session.session_uuid, v_session.status;
  end if;

  if v_session.finish_operation_id is not null
     and v_session.finish_operation_id <> p_finish_operation_id then
    raise exception using errcode = '23505', message = 'Session was already finished by another operation id';
  end if;

  if v_session.status = 'active' then
    -- Server time is authoritative. The client timestamp is intentionally not
    -- used to calculate operational duration.
    v_ended_at := now();
    v_duration_minutes := greatest(0, round(extract(epoch from (v_ended_at - v_session.started_at)) / 60.0));
    update public.sessions s
    set status = 'pending_submit',
        ended_at = v_ended_at,
        duration_minutes = v_duration_minutes,
        duration_display = v_duration_minutes::text || ' min',
        finish_operation_id = p_finish_operation_id,
        updated_at = now()
    where s.id = v_session.id
    returning * into v_session;
  else
    v_replayed := v_session.finish_operation_id = p_finish_operation_id;
    if v_session.finish_operation_id is null then
      update public.sessions s
      set finish_operation_id = p_finish_operation_id,
          updated_at = now()
      where s.id = v_session.id
      returning * into v_session;
    end if;
  end if;

  return jsonb_build_object(
    'session_uuid', v_session.session_uuid,
    'client_session_id', v_session.client_session_id,
    'location_name', v_location.location_name,
    'employee_name', v_employee.display_name,
    'device_id', v_canonical_device_id,
    'status', v_session.status,
    'started_at', v_session.started_at,
    'ended_at', v_session.ended_at,
    'duration_minutes', v_session.duration_minutes,
    'duration_display', v_session.duration_display,
    'location_type', v_location.location_type,
    'form_type', v_location.form_type,
    'finish_operation_id', coalesce(v_session.finish_operation_id, p_finish_operation_id),
    'client_ended_at_received', p_client_ended_at is not null,
    'replayed', v_replayed
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.tool_get_offline_scan_authority_snapshot(p_device_id text, p_authenticated_credential_id text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_device record; v_credential public.device_auth_credentials%rowtype;
  v_generated_at timestamptz := date_trunc('milliseconds',clock_timestamp()); v_expires_at timestamptz;
  v_locations jsonb; v_snapshot_id text;
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  select d.id,d.device_id,d.assigned_employee_id,d.assignment_epoch,e.display_name employee_name,e.active employee_active
    into v_device from public.devices d join public.employees e on e.id=d.assigned_employee_id
   where upper(btrim(d.device_id))=upper(btrim(coalesce(p_device_id,''))) and d.active=true;
  begin
    select * into v_credential from public.device_auth_credentials
     where credential_id=nullif(lower(btrim(coalesce(p_authenticated_credential_id,''))),'')::uuid for share;
  exception when others then
    raise exception using errcode='42501',message='an active authenticated employee-device credential is required';
  end;
  if v_device.id is null or v_device.assigned_employee_id is null or v_device.employee_active is not true
     or v_credential.credential_id is null or v_credential.device_id<>v_device.id or v_credential.confirmed_at is null
     or v_credential.revoked_at is not null or v_credential.expires_at<=v_generated_at then
    raise exception using errcode='42501',message='an active authenticated employee-device assignment is required';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('location_code',l.location_code,'location_name',public.place_operational_location_name(l.id,v_generated_at),
    'location_type',l.location_type,'form_type',coalesce(l.form_type,l.location_type)) order by l.location_code),'[]'::jsonb)
    into v_locations from public.locations l where l.active=true;
  v_expires_at:=date_trunc('milliseconds',least(v_generated_at+interval '24 hours',v_credential.expires_at));
  v_snapshot_id:=encode(extensions.digest(convert_to(jsonb_build_object('contract_version','scan.v4.snapshot-bound-authority',
    'device_id',v_device.device_id,'employee_id',v_device.assigned_employee_id::text,'assignment_epoch',v_device.assignment_epoch,
    'credential_id',v_credential.credential_id::text,'generated_at',public.custodial_canonical_utc_millis(v_generated_at),'expires_at',public.custodial_canonical_utc_millis(v_expires_at),'locations',v_locations)::text,'UTF8'),'sha256'),'hex');
  insert into public.custodial_offline_scan_authority_snapshots(snapshot_id,device_id,employee_id,assignment_epoch,credential_id,generated_at,expires_at,locations_json)
  values(v_snapshot_id,v_device.id,v_device.assigned_employee_id,v_device.assignment_epoch,v_credential.credential_id,v_generated_at,v_expires_at,v_locations)
  on conflict(snapshot_id) do nothing;
  return jsonb_build_object('schema_version','offline-scan-snapshot.v2','contract_version','scan.v4.snapshot-bound-authority',
    'snapshot_id',v_snapshot_id,'canonical_device_id',v_device.device_id,'employee_id',v_device.assigned_employee_id,
    'employee_name',v_device.employee_name,'assignment_epoch',v_device.assignment_epoch,'credential_id',v_credential.credential_id,
    'generated_at',public.custodial_canonical_utc_millis(v_generated_at),'expires_at',public.custodial_canonical_utc_millis(v_expires_at),'locations',v_locations);
end $function$

cron_jobs.command:
select net.http_get(
  url := 'https://memphis-zoo-mcp.onrender.com/health',
  params := jsonb_build_object('probe', 'supabase-cron'),
  headers := jsonb_build_object('User-Agent', 'memphis-zoo-availability-bridge/1.0'),
  timeout_milliseconds := 4000
) as request_id;

statements:
create extension if not exists pg_cron;

do $$
begin
  if exists (
    select 1
    from cron.job
    where jobname = 'demo_scan_mock_advance_20m'
  ) then
    perform cron.unschedule('demo_scan_mock_advance_20m');
  end if;

  perform cron.schedule(
