        when coalesce(r.notes, '') like '%Shift updated 2026-07-14: 8:00 AM-5:00 PM.%' then r.notes
        else concat_ws(' | ', nullif(r.notes, ''), 'Shift updated 2026-07-14: 8:00 AM-5:00 PM.')
      end,
