create or replace function public.sch_audit_schedule_day(
  p_service_date date default public.sch_service_date(now())
)
returns jsonb
language plpgsql
stable
set search_path = pg_catalog, public, extensions
as $function$
declare
  v_date date := coalesce(p_service_date, public.sch_service_date(now()));
  v_detail jsonb := public.sch_audit_schedule_day_detail(v_date);
  v_roster_count integer := coalesce((v_detail #>> '{counts,active_roster_rows}')::integer, 0);
  v_assignment_count integer := coalesce((v_detail #>> '{counts,assignments_total}')::integer, 0);
  v_open_count integer := coalesce((v_detail #>> '{counts,assignments_open}')::integer, 0);
  v_expected_template_count integer := 0;
  v_schedule_expected boolean := false;
  v_readiness_ok boolean := false;
  v_issue_free boolean := false;
  v_readiness_status text;
begin
  select count(*)::integer
    into v_expected_template_count
  from public.employee_shift_templates est
  join public.employees e on e.id = est.employee_id
  where est.active = true
    and e.active = true
    and est.day_of_week = extract(dow from v_date)::integer;

  v_schedule_expected := v_expected_template_count > 0
    or v_roster_count > 0
    or v_assignment_count > 0;

  v_readiness_status := case
    when not v_schedule_expected then 'not_expected'
    when v_roster_count = 0 then 'missing_roster'
    when v_assignment_count = 0 then 'missing_assignments'
    when v_open_count > 0 then 'open_assignments'
    else 'ready'
  end;

  v_readiness_ok := (not v_schedule_expected)
    or (v_roster_count > 0 and v_assignment_count > 0 and v_open_count = 0);

  v_issue_free := jsonb_array_length(coalesce(v_detail->'assigned_while_absent', '[]'::jsonb)) = 0
    and jsonb_array_length(coalesce(v_detail->'pto_without_absence_override', '[]'::jsonb)) = 0
    and jsonb_array_length(coalesce(v_detail->'working_without_assignments', '[]'::jsonb)) = 0
    and jsonb_array_length(coalesce(v_detail->'assigned_outside_active_roster', '[]'::jsonb)) = 0
    and jsonb_array_length(coalesce(v_detail->'open_segments', '[]'::jsonb)) = 0;

  return v_detail || jsonb_build_object(
    'ok', v_readiness_ok and v_issue_free,
    'readiness_status', v_readiness_status,
    'schedule_expected', v_schedule_expected,
    'expected_template_count', v_expected_template_count,
    'readiness_ok', v_readiness_ok,
    'issue_free', v_issue_free,
    'readiness_issues', case
      when v_readiness_status = 'ready' or v_readiness_status = 'not_expected' then '[]'::jsonb
      else jsonb_build_array(jsonb_build_object(
        'code', v_readiness_status,
        'message', format('Schedule readiness failed for %s: roster=%s assignments=%s open=%s', v_date, v_roster_count, v_assignment_count, v_open_count)
      ))
    end
  );
end
$function$;

revoke all on function public.sch_audit_schedule_day(date) from public, anon, authenticated;
grant execute on function public.sch_audit_schedule_day(date) to service_role, postgres;

create or replace function public.sch_ensure_schedule_window(
  p_start_date date default public.sch_service_date(now()),
  p_days integer default 14,
  p_reason text default 'scheduled_rolling_window_readiness'
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $function$
declare
  v_start date := coalesce(p_start_date, public.sch_service_date(now()));
  v_days integer := greatest(1, least(coalesce(p_days, 14), 31));
  v_offset integer;
  v_date date;
  v_result jsonb;
  v_audit jsonb;
  v_results jsonb := '[]'::jsonb;
  v_ready integer := 0;
  v_failed integer := 0;
begin
  perform pg_advisory_xact_lock(hashtextextended('schedule-window:' || v_start::text || ':' || v_days::text, 0));

  for v_offset in 0..(v_days - 1) loop
    v_date := v_start + v_offset;
    begin
      v_result := public.sch_ensure_daily_schedule(
        v_date,
        coalesce(nullif(btrim(p_reason), ''), 'scheduled_rolling_window_readiness')
      );
      v_audit := public.sch_audit_schedule_day(v_date);
      if coalesce((v_audit->>'ok')::boolean, false) then
        v_ready := v_ready + 1;
        v_results := v_results || jsonb_build_array(jsonb_build_object(
          'service_date', v_date,
          'ok', true,
          'result', v_result,
          'audit', v_audit
        ));
      else
        v_failed := v_failed + 1;
        v_results := v_results || jsonb_build_array(jsonb_build_object(
          'service_date', v_date,
          'ok', false,
          'error', 'schedule_audit_failed',
          'result', v_result,
          'audit', v_audit
        ));
      end if;
    exception when others then
      v_failed := v_failed + 1;
      v_results := v_results || jsonb_build_array(jsonb_build_object(
        'service_date', v_date,
        'ok', false,
        'error', sqlerrm
      ));
    end;
  end loop;

  insert into public.schedule_automation_runs(
    automation_key, service_date, status, result_json, created_at, updated_at
  ) values (
    'rolling_schedule_window_ready',
    v_start,
    case when v_failed = 0 then 'completed' else 'failed' end,
    jsonb_build_object(
      'start_date', v_start,
      'days', v_days,
      'reason', p_reason,
      'ready_days', v_ready,
      'failed_days', v_failed,
      'results', v_results
    ),
    now(), now()
  )
  on conflict (automation_key, service_date) do update set
    status = excluded.status,
    result_json = excluded.result_json,
    updated_at = now();

  return jsonb_build_object(
    'ok', v_failed = 0,
    'start_date', v_start,
    'days', v_days,
    'ready_days', v_ready,
    'failed_days', v_failed,
    'results', v_results
  );
end
$function$;

revoke all on function public.sch_ensure_schedule_window(date,integer,text) from public, anon, authenticated;
grant execute on function public.sch_ensure_schedule_window(date,integer,text) to service_role, postgres;

do $block$
declare
  v_job record;
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    for v_job in
      select jobid
      from cron.job
      where jobname in ('mz-current-day-static-schedule-ready', 'mz-rolling-schedule-window-ready')
    loop
      perform cron.unschedule(v_job.jobid);
    end loop;

    perform cron.schedule(
      'mz-rolling-schedule-window-ready',
      '*/30 * * * *',
      $cron$select public.sch_ensure_schedule_window(public.sch_service_date(now()), 14, 'scheduled_rolling_window_readiness');$cron$
    );
  end if;
end
$block$;

create or replace function public.run_sql_migration(p_name text, p_sql text)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
set statement_timeout = '180s'
as $function$
declare
  v_trimmed text;
  v_executable text;
  v_lowered text;
  v_result jsonb;
  v_sha text;
  v_bytes integer;
begin
  v_trimmed := trim(coalesce(p_sql, ''));
  v_executable := regexp_replace(v_trimmed, ';\s*$', '');
  v_lowered := lower(v_executable);

  if coalesce(trim(p_name), '') = '' then raise exception 'Migration name is required'; end if;
  if v_trimmed = '' then raise exception 'Migration SQL is required'; end if;
  if v_lowered like 'begin%' or position(('com' || 'mit') in v_lowered) > 0 then
    raise exception 'Do not include transaction wrappers in p_sql. Submit the migration body only.';
  end if;
  if exists (select 1 from public.migration_log_summary where migration_name = p_name) then
    raise exception 'Migration "%" has already been applied', p_name;
  end if;

  if v_lowered ~ '^\s*(insert|update|delete)\s'
     and v_lowered like '% returning %'
     and position(';' in v_executable) = 0 then
    execute format('with _migration_rows as (%s) select coalesce(jsonb_agg(to_jsonb(_migration_rows)), ''[]''::jsonb) from _migration_rows', v_executable)
      into v_result;
  else
    execute v_trimmed;
    v_result := jsonb_build_object('ok', true, 'migration_name', p_name, 'applied_at', now());
  end if;

  v_sha := encode(extensions.digest(convert_to(p_sql, 'UTF8'), 'sha256'), 'hex');
  v_bytes := octet_length(p_sql);

  insert into public.migration_log_summary(
    migration_name, statement_count, total_sql_bytes, latest_sql_sha256,
    first_applied_at, last_applied_at, last_applied_by, updated_at
  ) values (
    p_name, 1, v_bytes, v_sha, now(), now(), current_user, now()
  );

  insert into public.migration_log(migration_name, sql_text, applied_by, notes)
  values (
    p_name,
    format('sha256:%s bytes:%s', v_sha, v_bytes),
    current_user,
    'Compact migration evidence; full SQL belongs in canonical source control.'
  );

  return v_result || jsonb_build_object('sql_sha256', v_sha, 'sql_bytes', v_bytes);
end
$function$;

revoke all on function public.run_sql_migration(text,text) from public, anon, authenticated;
grant execute on function public.run_sql_migration(text,text) to service_role, postgres;

-- Ops Manager trusted-device pairing repair.
-- Forward-only/data-preserving.  This replaces routine password enrollment with
-- short-lived, single-use pairing links while preserving the existing
-- ops_manager_trusted_devices cookie/session architecture.

create extension if not exists pgcrypto with schema extensions;

create table if not exists public.ops_manager_pairing_tokens (
  pairing_id uuid primary key default gen_random_uuid(),
  token_hash text not null unique,
  created_by_credential_id uuid null references public.ops_manager_trusted_devices(credential_id) on delete set null,
  created_by_device_id text null,
  created_by_actor text not null default 'ops_manager',
  intended_device_label text null,
  max_access_level text not null default 'full_access',
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  used_at timestamptz null,
  used_by_credential_id uuid null references public.ops_manager_trusted_devices(credential_id) on delete set null,
  used_by_device_id text null,
  revoked_at timestamptz null,
  revoked_reason text null,
  metadata_json jsonb not null default '{}'::jsonb,
  constraint ops_manager_pairing_tokens_hash_length check (length(token_hash) = 64),
  constraint ops_manager_pairing_tokens_actor_length check (length(created_by_actor) between 1 and 120),
  constraint ops_manager_pairing_tokens_access_level check (max_access_level in ('read_only','full_access')),
  constraint ops_manager_pairing_tokens_expiration check (expires_at > created_at),
  constraint ops_manager_pairing_tokens_label_length check (intended_device_label is null or length(intended_device_label) <= 160),
  constraint ops_manager_pairing_tokens_created_device_length check (created_by_device_id is null or length(created_by_device_id) between 1 and 96),
  constraint ops_manager_pairing_tokens_used_device_length check (used_by_device_id is null or length(used_by_device_id) between 1 and 96),
  constraint ops_manager_pairing_tokens_revocation_reason_length check (revoked_reason is null or length(revoked_reason) <= 160),
  constraint ops_manager_pairing_tokens_metadata_object check (jsonb_typeof(metadata_json) = 'object')
);

create index if not exists idx_ops_manager_pairing_tokens_active
  on public.ops_manager_pairing_tokens (expires_at, created_at)
  where used_at is null and revoked_at is null;

create index if not exists idx_ops_manager_pairing_tokens_created_by
  on public.ops_manager_pairing_tokens (created_by_credential_id, created_at desc);

create index if not exists idx_ops_manager_pairing_tokens_used_by
  on public.ops_manager_pairing_tokens (used_by_credential_id, used_at desc)
  where used_at is not null;

alter table public.ops_manager_pairing_tokens enable row level security;
alter table public.ops_manager_pairing_tokens force row level security;

revoke all on table public.ops_manager_pairing_tokens from public, anon, authenticated;
grant select, insert, update, delete on table public.ops_manager_pairing_tokens to postgres, service_role;

comment on table public.ops_manager_pairing_tokens is
  'Short-lived single-use Ops Manager trusted-device pairing tokens. token_hash is persisted; raw pairing tokens are returned only by the server-side creation function.';

create or replace function public.ops_manager_create_pairing_token(
  p_created_by_credential_id uuid default null,
  p_created_by_device_id text default null,
  p_created_by_actor text default 'ops_manager',
  p_intended_device_label text default null,
  p_ttl_seconds integer default 600,
  p_metadata_json jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path to 'pg_catalog', 'public', 'extensions'
as $function$
declare
  v_pairing_id uuid;
  v_token text := encode(gen_random_bytes(32), 'hex');
  v_hash text := encode(digest(v_token, 'sha256'), 'hex');
  v_ttl integer := least(900, greatest(60, coalesce(p_ttl_seconds, 600)));
  v_expires_at timestamptz := now() + make_interval(secs => least(900, greatest(60, coalesce(p_ttl_seconds, 600))));
  v_metadata jsonb := coalesce(p_metadata_json, '{}'::jsonb);
  v_access text := 'full_access';
begin
  if jsonb_typeof(v_metadata) <> 'object' then
    raise exception 'metadata_json must be an object';
  end if;

  if p_created_by_credential_id is not null and not exists (
    select 1
    from public.ops_manager_trusted_devices d
    where d.credential_id = p_created_by_credential_id
      and d.revoked_at is null
      and d.expires_at > now()
      and d.max_access_level = 'full_access'
  ) then
    raise exception 'creating credential is not an active full-access trusted manager device';
  end if;

  insert into public.ops_manager_pairing_tokens (
    token_hash,
    created_by_credential_id,
    created_by_device_id,
    created_by_actor,
    intended_device_label,
    max_access_level,
    expires_at,
    metadata_json
  )
  values (
    v_hash,
    p_created_by_credential_id,
    nullif(left(coalesce(p_created_by_device_id, ''), 96), ''),
    left(coalesce(nullif(p_created_by_actor, ''), 'ops_manager'), 120),
    nullif(left(coalesce(p_intended_device_label, ''), 160), ''),
    v_access,
    v_expires_at,
    v_metadata
  )
  returning pairing_id into v_pairing_id;

  return jsonb_build_object(
    'ok', true,
    'pairing_id', v_pairing_id,
    'pairing_token', v_token,
    'expires_at', v_expires_at,
    'ttl_seconds', v_ttl,
    'max_access_level', v_access
  );
end;
$function$;

create or replace function public.ops_manager_consume_pairing_and_enroll(
  p_token text,
  p_credential_id uuid,
  p_device_id text,
  p_device_label text,
  p_trust_token_hash text,
  p_max_access_level text default 'full_access',
  p_user_agent_hash text default null,
  p_created_ip_hash text default null,
  p_expires_at timestamptz default null,
  p_metadata_json jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path to 'pg_catalog', 'public', 'extensions'
as $function$
declare
  v_hash text;
  v_pairing public.ops_manager_pairing_tokens%rowtype;
  v_device public.ops_manager_trusted_devices%rowtype;
  v_now timestamptz := now();
  v_metadata jsonb := coalesce(p_metadata_json, '{}'::jsonb);
  v_max_access text;
begin
  if p_token is null or p_token !~ '^[a-f0-9]{64}$' then
    return jsonb_build_object('ok', false, 'status', 400, 'reason', 'malformed');
  end if;
  if p_credential_id is null then
    raise exception 'credential_id is required';
  end if;
  if p_device_id is null or length(trim(p_device_id)) < 1 or length(trim(p_device_id)) > 96 then
    raise exception 'valid device_id is required';
  end if;
  if p_device_label is null or length(trim(p_device_label)) < 1 or length(trim(p_device_label)) > 160 then
    raise exception 'valid device_label is required';
  end if;
  if p_trust_token_hash is null or length(p_trust_token_hash) <> 64 then
    raise exception 'valid trust token hash is required';
  end if;
  if p_expires_at is null or p_expires_at <= v_now then
    raise exception 'future trusted-device expiration is required';
  end if;
  if jsonb_typeof(v_metadata) <> 'object' then
    raise exception 'metadata_json must be an object';
  end if;

  v_hash := encode(digest(lower(p_token), 'sha256'), 'hex');

  select *
    into v_pairing
  from public.ops_manager_pairing_tokens
  where token_hash = v_hash
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'status', 401, 'reason', 'invalid');
  end if;
  if v_pairing.used_at is not null then
    return jsonb_build_object('ok', false, 'status', 410, 'reason', 'used', 'pairing_id', v_pairing.pairing_id);
  end if;
  if v_pairing.revoked_at is not null then
    return jsonb_build_object('ok', false, 'status', 410, 'reason', 'revoked', 'pairing_id', v_pairing.pairing_id);
  end if;
  if v_pairing.expires_at <= v_now then
    return jsonb_build_object('ok', false, 'status', 410, 'reason', 'expired', 'pairing_id', v_pairing.pairing_id);
  end if;

  v_max_access := case
    when v_pairing.max_access_level = 'full_access' and coalesce(p_max_access_level, 'full_access') = 'full_access' then 'full_access'
    else 'read_only'
  end;

  update public.ops_manager_trusted_devices
  set revoked_at = v_now,
      revoked_reason = 'device_re-enrolled_by_pairing'
  where device_id = trim(p_device_id)
    and revoked_at is null;

  insert into public.ops_manager_trusted_devices (
    credential_id,
    device_id,
    device_label,
    token_hash,
    max_access_level,
    user_agent_hash,
    created_ip_hash,
    expires_at,
    metadata_json
  )
  values (
    p_credential_id,
    trim(p_device_id),
    trim(p_device_label),
    p_trust_token_hash,
    v_max_access,
    p_user_agent_hash,
    p_created_ip_hash,
    p_expires_at,
    v_metadata || jsonb_build_object(
      'pairing_id', v_pairing.pairing_id,
      'enrollment_source', 'one_time_pairing_link'
    )
  )
  returning * into v_device;

  update public.ops_manager_pairing_tokens
  set used_at = v_now,
      used_by_credential_id = p_credential_id,
      used_by_device_id = trim(p_device_id),
      metadata_json = metadata_json || jsonb_build_object('used_user_agent_hash', p_user_agent_hash, 'used_ip_hash', p_created_ip_hash)
  where pairing_id = v_pairing.pairing_id;

  return jsonb_build_object(
    'ok', true,
    'pairing_id', v_pairing.pairing_id,
    'trusted_device', jsonb_build_object(
      'credential_id', v_device.credential_id,
      'device_id', v_device.device_id,
      'device_label', v_device.device_label,
      'max_access_level', v_device.max_access_level,
      'created_at', v_device.created_at,
      'expires_at', v_device.expires_at
    )
  );
end;
$function$;

