comment on table public.device_auth_enrollment_operations is
  'Short-lived AES-GCM ciphertext for idempotent native custodial enrollment response recovery. Plaintext device credentials are never stored here.';
comment on function public.mz_resolve_employee_push_delivery(uuid,bigint,timestamptz) is
  'Fail-closed final recipient resolution for employee FCM delivery. Reconciles stale registrations against current credential, device, employee, and assignment state.';

-- Atomic, credential-bound removal for the native custodial application.
--
-- This migration is forward-only and data-preserving. The operation record is
-- deliberately terminal and retains only the credential UUID plus its
-- non-secret result. The credential's existing one-way token hash remains the
-- proof for an authenticated replay; no plaintext device or push credential is
-- copied into operation history. Application rollback can stop calling the RPC
-- while leaving the immutable removal/audit evidence in place.

begin;

create table if not exists public.device_auth_removal_operations (
  operation_id uuid primary key,
  device_id uuid not null references public.devices(id) on delete restrict,
  credential_id uuid not null unique references public.device_auth_credentials(credential_id) on delete restrict,
  status text not null default 'removed',
  result_json jsonb not null,
  removed_at timestamptz not null,
  created_at timestamptz not null default now(),
  constraint device_auth_removal_operations_status_check
    check (status = 'removed'),
  constraint device_auth_removal_operations_result_check
    check (jsonb_typeof(result_json) = 'object')
);

create index if not exists idx_device_auth_removal_operations_device_recent
  on public.device_auth_removal_operations(device_id, removed_at desc, operation_id);
create index if not exists idx_operational_notification_jobs_employee_credential_open
  on public.operational_notification_jobs((payload_json->>'credential_id'), status)
  where job_type in ('employee_event_push', 'employee_native_push')
    and status in ('pending', 'leased');

alter table public.device_auth_removal_operations enable row level security;
alter table public.device_auth_removal_operations force row level security;
revoke all on table public.device_auth_removal_operations from public, anon, authenticated;
grant select, insert on table public.device_auth_removal_operations to postgres, service_role;

create or replace function public.device_auth_remove_custodial_credential(
  p_operation_id uuid,
  p_device_id uuid,
  p_credential_id uuid,
  p_token_hash text,
  p_now timestamptz default now()
) returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $function$
declare
  v_operation public.device_auth_removal_operations%rowtype;
  v_credential public.device_auth_credentials%rowtype;
  v_device_identifier text;
  v_push_registrations integer := 0;
  v_event_instances integer := 0;
  v_notification_jobs integer := 0;
  v_claimed_jobs integer := 0;
  v_result jsonb;
begin
  if p_operation_id is null or p_device_id is null or p_credential_id is null
     or p_token_hash is null or length(p_token_hash) <> 64 or p_now is null then
    raise exception using
      errcode = '22023',
      message = 'operation, device, and credential proof are required';
  end if;

  -- A stable operation lock makes concurrent response-loss retries deterministic
  -- even before the terminal operation row exists.
  perform pg_advisory_xact_lock(
    hashtextextended('custodial-device-removal:' || p_operation_id::text, 0)
  );

  select * into v_operation
  from public.device_auth_removal_operations
  where operation_id = p_operation_id
  for update;

  if v_operation.operation_id is not null then
    -- Revocation is intentionally ignored only for this exact terminal replay.
    -- The caller must still prove the original credential ID and one-way hash.
    select * into v_credential
    from public.device_auth_credentials
    where credential_id = p_credential_id
      and device_id = p_device_id
      and token_hash = p_token_hash
    for update;

    if v_credential.credential_id is null
       or v_operation.credential_id <> p_credential_id
       or v_operation.device_id <> p_device_id then
      return jsonb_build_object('ok', false, 'reason', 'operation_conflict');
    end if;

    return v_operation.result_json || jsonb_build_object(
      'ok', true,
      'replayed', true
    );
  end if;

  select * into v_credential
  from public.device_auth_credentials
  where credential_id = p_credential_id
  for update;

  if v_credential.credential_id is null
     or v_credential.device_id <> p_device_id
     or v_credential.token_hash <> p_token_hash then
    return jsonb_build_object('ok', false, 'reason', 'credential_mismatch');
  end if;
  if v_credential.revoked_at is not null then
    return jsonb_build_object('ok', false, 'reason', 'credential_revoked');
  end if;
  if v_credential.expires_at <= p_now then
    return jsonb_build_object('ok', false, 'reason', 'credential_expired');
  end if;
  if v_credential.confirmed_at is null then
    return jsonb_build_object('ok', false, 'reason', 'credential_unconfirmed');
  end if;

  select device_id into v_device_identifier
  from public.devices
  where id = p_device_id;
  if v_device_identifier is null
     or v_device_identifier !~ '^KIOSK_(0[2-9]|10)$' then
    return jsonb_build_object('ok', false, 'reason', 'device_not_eligible');
  end if;

  with changed as (
    update public.employee_push_registrations
       set active = false,
           revoked_at = coalesce(revoked_at, p_now),
           revoked_reason = 'custodial_device_removed',
           last_error = 'custodial_device_removed',
           updated_at = p_now
     where credential_id = p_credential_id
       and (active = true or revoked_at is null)
    returning registration_id
  )
  select count(*)::integer into v_push_registrations from changed;

  with changed as (
    update public.event_push_instances
       set state = 'cancelled',
           cancelled_at = coalesce(cancelled_at, p_now),
           last_error = 'custodial_device_removed',
           updated_at = p_now
     where credential_id = p_credential_id
       and state in ('pending', 'leased')
    returning instance_id
  )
  select count(*)::integer into v_event_instances from changed;

  -- Active lease proof is retained on a terminally cancelled claimed job. This
  -- lets the owning worker call finish_operational_notification_job_terminal,
  -- while every claim path rejects the now-dead row after a restart.
  with candidates as (
    select job_id, status as previous_status
    from public.operational_notification_jobs
    where job_type in ('employee_event_push', 'employee_native_push')
      and status in ('pending', 'leased')
      and payload_json->>'credential_id' = p_credential_id::text
    for update
  ), changed as (
    update public.operational_notification_jobs job
       set status = 'dead',
           completed_at = coalesce(job.completed_at, p_now),
           last_error = 'custodial_device_removed',
           updated_at = p_now
      from candidates
     where job.job_id = candidates.job_id
    returning candidates.previous_status
  )
  select count(*)::integer,
         (count(*) filter (where previous_status = 'leased'))::integer
    into v_notification_jobs, v_claimed_jobs
  from changed;

  update public.device_auth_credentials
     set revoked_at = p_now,
         revoked_reason = 'custodial_device_removed'
   where credential_id = p_credential_id;

  v_result := jsonb_build_object(
    'ok', true,
    'removed', true,
    'replayed', false,
    'status', 'removed',
    'operation_id', p_operation_id,
    'credential_id', p_credential_id,
    'device_id', v_device_identifier,
    'removed_at', p_now,
    'push_registrations_deactivated', v_push_registrations,
    'event_push_instances_cancelled', v_event_instances,
    'notification_jobs_cancelled', v_notification_jobs,
    'claimed_notification_jobs_cancelled', v_claimed_jobs
  );

  insert into public.device_auth_removal_operations(
    operation_id, device_id, credential_id, status, result_json, removed_at
  ) values (
    p_operation_id, p_device_id, p_credential_id, 'removed', v_result, p_now
  );

  insert into public.device_auth_events(
    device_id, credential_id, event_type, success, reason, presented_identifier, metadata_json
  ) values (
    p_device_id,
    p_credential_id,
    'custodial_device_removed',
    true,
    'client_requested_removal',
    null,
    jsonb_build_object(
      'operation_id', p_operation_id,
      'push_registrations_deactivated', v_push_registrations,
      'event_push_instances_cancelled', v_event_instances,
      'notification_jobs_cancelled', v_notification_jobs,
      'claimed_notification_jobs_cancelled', v_claimed_jobs
    )
  );

  return v_result;
end
$function$;

revoke all on function public.device_auth_remove_custodial_credential(uuid, uuid, uuid, text, timestamptz)
  from public, anon, authenticated;
grant execute on function public.device_auth_remove_custodial_credential(uuid, uuid, uuid, text, timestamptz)
  to postgres, service_role;

comment on table public.device_auth_removal_operations is
  'Immutable terminal replay records for authenticated native custodial device removal. No plaintext credentials are stored.';
comment on function public.device_auth_remove_custodial_credential(uuid, uuid, uuid, text, timestamptz) is
  'Atomically authenticates and removes one custodial credential, reconciles push delivery state, audits the action, and permits only credential-bound terminal replay.';

commit;

begin;

create or replace function public.cleaning_inspections_set_snapshot()
returns trigger
language plpgsql
security definer
set search_path to 'pg_catalog','public'
as $function$
declare
  v_session record;
  v_completion_at timestamptz;
  v_inspector_name text;
begin
  if tg_op='INSERT' then
    new.inspected_at:=statement_timestamp();
    new.created_at:=new.inspected_at;
  else
    if new.operation_id is distinct from old.operation_id then
      raise exception using errcode='23514',message='Inspection operation_id is immutable';
    end if;
    if new.session_id is distinct from old.session_id then
      raise exception using errcode='23514',message='Inspection session_id is immutable';
    end if;
    if new.inspected_at is distinct from old.inspected_at or new.created_at is distinct from old.created_at then
      raise exception using errcode='23514',message='Inspection authoritative timestamps are immutable';
    end if;
  end if;

  select
    s.location_id,s.employee_id,s.started_at,s.ended_at,s.duration_minutes,s.status,
    (select max(cr.submitted_at) from public.completion_responses cr where cr.session_id=s.id) completion_submitted_at,
    l.location_code,l.location_name,e.display_name employee_name
  into v_session
  from public.sessions s
  join public.locations l on l.id=s.location_id
  join public.employees e on e.id=s.employee_id
  where s.id=new.session_id;

  if not found then
    raise exception using errcode='P0002',message='Cleaning session was not found';
  end if;
  if v_session.status not in ('pending_submit','closed') then
    raise exception using errcode='23514',message='Only a finished cleaning session can be inspected';
  end if;
  v_completion_at:=coalesce(v_session.ended_at,v_session.completion_submitted_at);
  if v_completion_at is null then
    raise exception using errcode='23514',message='Finished cleaning session has no completion timestamp';
  end if;
  if new.inspected_at<v_completion_at then
    raise exception using errcode='23514',message='Inspection time cannot be before the cleaning session finished';
  end if;
  if new.inspected_at>v_completion_at+interval '24 hours' then
    raise exception using errcode='23514',message='Inspection cannot be recorded more than 24 hours after cleaning session completion';
  end if;
  if new.inspected_at>clock_timestamp()+interval '5 minutes' then
    raise exception using errcode='23514',message='Inspection time cannot be in the future';
  end if;

  new.location_id:=v_session.location_id;
  new.employee_id:=v_session.employee_id;
  new.employee_name_snapshot:=v_session.employee_name;
  new.location_code_snapshot:=v_session.location_code;
  new.location_name_snapshot:=v_session.location_name;
  new.session_started_at:=v_session.started_at;
  new.session_ended_at:=v_completion_at;
  new.session_duration_minutes:=coalesce(
    v_session.duration_minutes,
    case when v_session.ended_at is not null
      then greatest(0,ceil(extract(epoch from (v_session.ended_at-v_session.started_at))/60.0)::integer)
      else null end
  );

  if new.inspector_manager_id is not null then
    select m.display_name into v_inspector_name
    from public.ops_manager_managers m
    where m.manager_id=new.inspector_manager_id
      and m.active=true and m.revoked_at is null and m.is_system_principal=false;
    if not found then
      raise exception using errcode='23503',message='Active inspector manager was not found';
    end if;
    new.inspector_name_snapshot:=v_inspector_name;
  else
    new.inspector_name_snapshot:=coalesce(nullif(btrim(new.inspector_name_snapshot),''),'Custodial Manager');
  end if;

  new.updated_at:=clock_timestamp();
  return new;
end
$function$;

revoke all on function public.cleaning_inspections_set_snapshot() from public,anon,authenticated;
grant execute on function public.cleaning_inspections_set_snapshot() to postgres,service_role;

comment on function public.cleaning_inspections_set_snapshot() is
  'Assigns immutable server timestamps, binds inspections to completed session facts, and rejects evidence recorded more than 24 elapsed hours after completion.';

commit;

begin;

-- Named managers have durable individual Messenger principals.  The former
-- Operations Leadership singleton is historical-only: preserve its records,
-- but remove the RPC authority that could recreate active membership.
drop function if exists public.msg_get_or_create_ops_manager_thread(uuid);

update public.msg_threads
set is_active = false,
    title = 'Operations Leadership Chat (Retired)',
    updated_at = now()
where system_key = 'ops_manager_shared_chat_v1';

update public.msg_thread_participants p
set left_at = coalesce(p.left_at, now())
from public.msg_threads t
where t.id = p.thread_id
  and t.system_key = 'ops_manager_shared_chat_v1';

-- Table writes remain available to normal Messenger workflows, so enforce the
-- retirement at the data boundary as well as by dropping the legacy RPC.
create or replace function public.msg_reject_retired_ops_manager_shared_thread_mutation()
returns trigger
language plpgsql
set search_path = pg_catalog, public
as $function$
begin
  if tg_op = 'INSERT' and new.system_key = 'ops_manager_shared_chat_v1' then
    raise exception using
      errcode = '23514',
      message = 'The retired Operations Leadership conversation cannot be recreated';
  end if;

  if tg_op = 'UPDATE'
     and (old.system_key = 'ops_manager_shared_chat_v1'
       or new.system_key = 'ops_manager_shared_chat_v1') then
    if new.system_key is distinct from old.system_key then
      raise exception using
        errcode = '23514',
        message = 'The retired Operations Leadership system key is immutable';
    end if;
    if new.is_active is true then
      raise exception using
        errcode = '23514',
        message = 'The retired Operations Leadership conversation must remain inactive';
    end if;
  end if;

  return new;
end
$function$;

revoke all on function public.msg_reject_retired_ops_manager_shared_thread_mutation()
  from public, anon, authenticated, service_role;

drop trigger if exists trg_msg_reject_retired_ops_manager_shared_thread_mutation
  on public.msg_threads;
create trigger trg_msg_reject_retired_ops_manager_shared_thread_mutation
before insert or update of system_key, is_active on public.msg_threads
for each row execute function public.msg_reject_retired_ops_manager_shared_thread_mutation();

create or replace function public.msg_reject_retired_ops_manager_shared_participation()
returns trigger
language plpgsql
set search_path = pg_catalog, public
as $function$
begin
  if new.left_at is null and exists (
    select 1
    from public.msg_threads t
    where t.id = new.thread_id
      and t.system_key = 'ops_manager_shared_chat_v1'
  ) then
    raise exception using
      errcode = '23514',
      message = 'The retired Operations Leadership conversation cannot have active participants';
  end if;

  return new;
end
$function$;

revoke all on function public.msg_reject_retired_ops_manager_shared_participation()
  from public, anon, authenticated, service_role;

drop trigger if exists trg_msg_reject_retired_ops_manager_shared_participation
  on public.msg_thread_participants;
create trigger trg_msg_reject_retired_ops_manager_shared_participation
before insert or update of thread_id, left_at on public.msg_thread_participants
for each row execute function public.msg_reject_retired_ops_manager_shared_participation();

comment on function public.msg_reject_retired_ops_manager_shared_thread_mutation() is
  'Prevents recreation, system-key removal, and reactivation of the retired Operations Leadership room.';
comment on function public.msg_reject_retired_ops_manager_shared_participation() is
  'Prevents active participation in the retired Operations Leadership room while preserving historical rows.';

commit;

begin;

-- This later correction deliberately leaves both prior retirement migrations
-- untouched. It closes runtime authority gaps while preserving every already
--retired row and every normal active conversation contract.

-- A single locked predicate is the final authority for every mutable
-- conversation path. Locking the row keeps a concurrent tombstone or raw
--state transition from slipping between validation and the writer.
create or replace function public.msg_assert_active_mutable_thread(p_thread_id uuid)
returns void
language plpgsql
security definer
set search_path=pg_catalog,public
as $function$
declare v_thread public.msg_threads%rowtype;
begin
  if p_thread_id is null then
    raise exception using errcode='22023',message='thread_id is required.';
  end if;
  select * into v_thread
  from public.msg_threads
  where id=p_thread_id
  for update;
  if v_thread.id is null then
    raise exception using errcode='P0002',message='Conversation not found';
  end if;
  if v_thread.system_key='ops_manager_shared_chat_v1' then
    raise exception using errcode='23514',message='The retired Operations Leadership conversation is immutable';
  end if;
  if v_thread.is_active is not true then
    raise exception using errcode='23514',message='Conversation is retired or inactive';
  end if;
end
$function$;

create or replace function public.msg_assert_active_mutable_message(p_message_id uuid)
returns void
language plpgsql
security definer
set search_path=pg_catalog,public
as $function$
declare v_thread_id uuid;
begin
  if p_message_id is null then
    raise exception using errcode='22023',message='message_id is required.';
  end if;
  select m.thread_id into v_thread_id
  from public.msg_messages m
  where m.id=p_message_id
  for key share;
  if v_thread_id is null then
    raise exception using errcode='P0002',message='Message not found';
  end if;
  perform public.msg_assert_active_mutable_thread(v_thread_id);
end
$function$;

-- Event acknowledgement owns both the native-notification receipt and any
--authoritatively linked Messenger receipt in one transaction.  The native
--event instance is resolved from the canonical active device and notification
--key; a client-supplied message id is only an equality assertion.
create or replace function public.msg_acknowledge_event_device_notification(
  p_device_identifier text,
  p_notification_key text,
  p_notification_type text,
  p_action text,
  p_metadata_json jsonb,
  p_message_id uuid,
  p_user_id uuid
) returns jsonb
language plpgsql
security definer
set search_path=pg_catalog,public,extensions
as $function$
declare
  v_device public.devices%rowtype;
  v_instance public.event_push_instances%rowtype;
  v_log public.events_app_notification_log%rowtype;
  v_linked_user public.msg_users%rowtype;
  v_message public.msg_messages%rowtype;
  v_thread_id uuid;
  v_notification jsonb;
  v_receipt public.msg_receipts%rowtype;
begin
  select * into v_device
  from public.devices d
  where d.active is true
    and upper(btrim(d.device_id))=upper(btrim(coalesce(p_device_identifier,'')))
  for update;
  if v_device.id is null then
    raise exception using errcode='P0002',message='Active canonical device was not found for event acknowledgement';
  end if;

  select i.* into v_instance
  from public.event_push_instances i
  join public.device_auth_credentials c
    on c.credential_id=i.credential_id
   and c.device_id=v_device.id
   and c.confirmed_at is not null
   and c.revoked_at is null
   and c.expires_at>now()
  where i.notification_key=btrim(coalesce(p_notification_key,''))
    and i.device_id=v_device.id
    and i.employee_id=v_device.assigned_employee_id
    and i.assignment_epoch=v_device.assignment_epoch
    and i.state in ('sent','opened')
  for update of i;
  if v_instance.instance_id is null then
    raise exception using errcode='P0002',message='Active event notification was not found for this device assignment';
  end if;

  select * into v_log
  from public.events_app_notification_log l
  where l.event_id=v_instance.event_id
    and l.employee_id=v_instance.employee_id
    and l.notification_kind=v_instance.notification_kind
  for update;

  if v_log.id is not null and v_log.response_message_id is not null then
    if v_log.status<>'sent' or v_log.msg_user_id is null or v_log.thread_id is null then
      raise exception using errcode='23514',message='Authoritative Event-to-Messenger notification linkage is invalid';
    end if;
    select * into v_linked_user
    from public.msg_users u
    where u.id=v_log.msg_user_id
      and u.employee_id=v_instance.employee_id
      and u.is_active is true
    for key share;
    if v_linked_user.id is null or p_user_id is null or p_user_id<>v_linked_user.id then
      raise exception using errcode='42501',message='Server-derived Messenger user does not match the authoritative event notification recipient';
    end if;
    select * into v_message
    from public.msg_messages m
    where m.id=v_log.response_message_id
      and m.thread_id=v_log.thread_id
    for key share;
    if v_message.id is null then
      raise exception using errcode='23514',message='Authoritative Event-to-Messenger response message linkage is invalid';
    end if;
    if p_message_id is not null and p_message_id<>v_message.id then
      raise exception using errcode='23514',message='Provided message id does not match the authoritative event notification link';
    end if;
    v_thread_id:=v_message.thread_id;
    perform public.msg_assert_active_mutable_thread(v_thread_id);
    if not exists (
      select 1 from public.msg_thread_participants p
      where p.thread_id=v_thread_id and p.user_id=v_linked_user.id and p.left_at is null
    ) then
      raise exception using errcode='42501',message='Authoritative event recipient is not an active Messenger participant';
    end if;
    if not exists (
      select 1 from public.msg_receipts r
      where r.message_id=v_message.id and r.user_id=v_linked_user.id
    ) then
      raise exception using errcode='P0002',message='Authoritative event message receipt was not found';
    end if;
  elsif p_message_id is not null then
    raise exception using errcode='23514',message='Provided message id has no authoritative Event-to-Messenger link';
  end if;

  v_notification:=public.ack_device_notification(
    v_device.device_id,v_instance.notification_key,p_notification_type,p_action,p_metadata_json
  );
  if v_message.id is not null then
    v_receipt:=public.msg_acknowledge_message(v_message.id,v_linked_user.id,v_device.device_id);
  end if;
  return v_notification || jsonb_build_object(
    'event_push_instance_id',v_instance.instance_id,
    'message_receipt_id',v_receipt.id,
    'linked_message_id',v_message.id
  );
end
$function$;

-- Final precedence for the two send signatures: the common locked predicate
--runs before a replay lookup as well as before every message, receipt, audit,
--and thread cursor mutation.
create or replace function public.msg_send_message(
  p_thread_id uuid,
  p_sender_user_id uuid,
  p_body text,
  p_message_type text default 'text',
  p_metadata_json jsonb default '{}'::jsonb
) returns public.msg_messages
language plpgsql
security definer
set search_path=pg_catalog,public,extensions
as $function$
declare
  v_message public.msg_messages%rowtype;
  v_metadata jsonb := coalesce(p_metadata_json, '{}'::jsonb);
  v_client_message_id text := nullif(btrim(coalesce(p_metadata_json->>'client_message_id', '')), '');
  v_source text := lower(btrim(coalesce(p_metadata_json->>'source', '')));
  v_event_id text := nullif(btrim(coalesce(p_metadata_json->>'event_id', '')), '');
  v_dedupe_key text := nullif(btrim(coalesce(
    p_metadata_json->>'notification_instance_key',
    p_metadata_json->>'instance_key',
    p_metadata_json->>'notification_key',
    p_metadata_json->>'alert_key',
    p_metadata_json->>'reminder_key',
    ''
  )), '');
begin
  if p_thread_id is null then raise exception 'thread_id is required.'; end if;
  if p_sender_user_id is null then raise exception 'sender_user_id is required.'; end if;
  if p_body is null or btrim(p_body) = '' then raise exception 'Message body is required.'; end if;
  if length(p_body) > 2000 then raise exception 'Message body cannot exceed 2000 characters.'; end if;
  if v_client_message_id is not null and length(v_client_message_id) > 200 then
    raise exception 'client_message_id cannot exceed 200 characters.';
  end if;
  perform public.msg_assert_active_mutable_thread(p_thread_id);
  if not exists (
    select 1 from public.msg_thread_participants tp
    where tp.thread_id=p_thread_id and tp.user_id=p_sender_user_id and tp.left_at is null
  ) then raise exception 'Sender is not an active participant in this thread.'; end if;

  if v_dedupe_key is null and v_source='events_app' and v_event_id is not null then
    v_dedupe_key:='event:'||v_event_id;
  end if;
  if v_dedupe_key is not null then
    if length(v_dedupe_key)>500 then raise exception 'notification instance key cannot exceed 500 characters'; end if;
    perform pg_advisory_xact_lock(hashtextextended(
      'message-notification:'||p_thread_id::text||':'||p_sender_user_id::text||':'||v_dedupe_key,0
    ));
    select * into v_message from public.msg_messages m
    where m.thread_id=p_thread_id and m.sender_user_id=p_sender_user_id and m.is_deleted is false
      and (m.metadata_json->>'notification_instance_key'=v_dedupe_key
        or (v_source='events_app' and v_event_id is not null
          and coalesce(m.metadata_json->>'source','')='events_app'
          and m.metadata_json->>'event_id'=v_event_id))
    order by m.sent_at limit 1;
    if found then return v_message; end if;
    v_metadata:=v_metadata||jsonb_build_object('notification_instance_key',v_dedupe_key);
  end if;
  if v_client_message_id is not null then
    select * into v_message from public.msg_messages m
    where m.sender_user_id=p_sender_user_id and m.client_message_id=v_client_message_id limit 1;
    if found then return v_message; end if;
  end if;
  insert into public.msg_messages(thread_id,sender_user_id,message_type,body,metadata_json,client_message_id)
  values(p_thread_id,p_sender_user_id,coalesce(nullif(btrim(p_message_type),''),'text'),btrim(p_body),v_metadata,v_client_message_id)
  returning * into v_message;
  insert into public.msg_receipts(message_id,user_id,delivered_at,displayed_at,read_at,acknowledged_at)
  select v_message.id,tp.user_id,null,null,null,null from public.msg_thread_participants tp
  where tp.thread_id=p_thread_id and tp.left_at is null and tp.user_id<>p_sender_user_id
  on conflict(message_id,user_id) do nothing;
  update public.msg_threads set last_message_at=v_message.sent_at,updated_at=now() where id=p_thread_id;
  return v_message;
exception when unique_violation then
  if v_client_message_id is not null then
    select * into v_message from public.msg_messages m
    where m.sender_user_id=p_sender_user_id and m.client_message_id=v_client_message_id limit 1;
    if found then return v_message; end if;
  end if;
  if v_dedupe_key is not null then
    select * into v_message from public.msg_messages m
    where m.thread_id=p_thread_id and m.sender_user_id=p_sender_user_id
      and m.metadata_json->>'notification_instance_key'=v_dedupe_key limit 1;
    if found then return v_message; end if;
  end if;
  raise;
end
$function$;

create or replace function public.msg_send_message(
  p_thread_id uuid,
  p_sender_user_id uuid,
  p_body text,
  p_message_type text,
  p_metadata_json jsonb,
  p_client_message_id text
) returns public.msg_messages
language plpgsql
security definer
set search_path=pg_catalog,public,extensions
as $function$
declare v_message public.msg_messages%rowtype;
begin
  if p_thread_id is null then raise exception 'thread_id is required.'; end if;
  if p_sender_user_id is null then raise exception 'sender_user_id is required.'; end if;
  if p_body is null or btrim(p_body)='' then raise exception 'Message body is required.'; end if;
  if length(p_body)>4000 then raise exception 'Message body cannot exceed 4000 characters.'; end if;
  perform public.msg_assert_active_mutable_thread(p_thread_id);
  if not exists(select 1 from public.msg_thread_participants tp where tp.thread_id=p_thread_id and tp.user_id=p_sender_user_id and tp.left_at is null) then
    raise exception 'Sender is not an active participant in this thread.';
  end if;
  if nullif(btrim(coalesce(p_client_message_id,'')),'') is not null then
    select * into v_message from public.msg_messages where client_message_id=btrim(p_client_message_id) limit 1;
    if found then
      if v_message.thread_id<>p_thread_id or v_message.sender_user_id<>p_sender_user_id then raise exception 'client_message_id belongs to another message.'; end if;
      return v_message;
    end if;
  end if;
  insert into public.msg_messages(thread_id,sender_user_id,message_type,body,metadata_json,client_message_id)
  values(p_thread_id,p_sender_user_id,coalesce(nullif(btrim(p_message_type),''),'text'),btrim(p_body),coalesce(p_metadata_json,'{}'::jsonb),nullif(btrim(coalesce(p_client_message_id,'')),''))
  returning * into v_message;
  insert into public.msg_receipts(message_id,user_id,queued_at,delivered_at,displayed_at,read_at)
  select v_message.id,tp.user_id,now(),null,null,null from public.msg_thread_participants tp
  where tp.thread_id=p_thread_id and tp.left_at is null and tp.user_id<>p_sender_user_id
  on conflict(message_id,user_id) do nothing;
  update public.msg_threads set last_message_at=v_message.sent_at,updated_at=now() where id=p_thread_id;
  return v_message;
end
$function$;

create or replace function public.msg_acknowledge_message(p_message_id uuid,p_user_id uuid,p_device_identifier text)
returns public.msg_receipts
language plpgsql security definer
set search_path=pg_catalog,public,extensions
as $function$
declare v_receipt public.msg_receipts%rowtype;
begin
  perform public.msg_assert_active_mutable_message(p_message_id);
  update public.msg_receipts set delivered_at=coalesce(delivered_at,now()),displayed_at=coalesce(displayed_at,now()),read_at=coalesce(read_at,now()),acknowledged_at=coalesce(acknowledged_at,now()),delivery_device_identifier=nullif(btrim(coalesce(p_device_identifier,'')), '')
  where message_id=p_message_id and user_id=p_user_id returning * into v_receipt;
  if not found then raise exception 'Message receipt not found.'; end if;
  return v_receipt;
end
$function$;

create or replace function public.msg_mark_message_delivered(p_message_id uuid,p_user_id uuid,p_device_identifier text)
returns public.msg_receipts
language plpgsql security definer
set search_path=pg_catalog,public,extensions
as $function$
declare v_receipt public.msg_receipts%rowtype;
begin
  perform public.msg_assert_active_mutable_message(p_message_id);
  update public.msg_receipts set delivered_at=coalesce(delivered_at,now()),delivery_device_identifier=nullif(btrim(coalesce(p_device_identifier,'')), ''),last_delivery_attempt_at=now(),delivery_attempts=delivery_attempts+1
  where message_id=p_message_id and user_id=p_user_id returning * into v_receipt;
  if not found then raise exception 'Message receipt not found.'; end if;
  return v_receipt;
end
$function$;

create or replace function public.msg_mark_message_displayed(p_message_id uuid,p_user_id uuid,p_device_identifier text)
returns public.msg_receipts
language plpgsql security definer
set search_path=pg_catalog,public,extensions
as $function$
declare v_receipt public.msg_receipts%rowtype;
begin
  perform public.msg_assert_active_mutable_message(p_message_id);
  update public.msg_receipts set delivered_at=coalesce(delivered_at,now()),displayed_at=coalesce(displayed_at,now()),delivery_device_identifier=nullif(btrim(coalesce(p_device_identifier,'')), ''),last_delivery_attempt_at=now(),delivery_attempts=delivery_attempts+1
  where message_id=p_message_id and user_id=p_user_id returning * into v_receipt;
  if not found then raise exception 'Message receipt not found.'; end if;
  return v_receipt;
end
