-- Never-cleaned locations can only be due when they have a current operational
-- day assignment. Cancelled, inactive, and unassigned rows remain not_cleaned.
create or replace view public.v_location_dashboard_status as
with op_day as (select public.operational_day_start(now()) day_start, public.sch_service_date(now()) service_date),
scheduled_baseline as (
  select membership.location_id, min((od.service_date + schedule.coverage_start::time) at time zone 'America/Chicago') baseline_at
  from op_day od join lateral public.sch_get_daily_schedule_with_purpose(od.service_date) schedule on schedule.status='ASSIGNED' and schedule.assigned_employee_id is not null and coalesce(schedule.coverage_purpose,'area_owner')<>'reminder'
  join public.location_group_memberships membership on membership.location_group_id=schedule.location_group_id and membership.active=true
  join public.locations location on location.id=membership.location_id and location.active=true
  group by membership.location_id
), latest_scan as (select location_id,max(coalesce(scanned_at,created_at)) last_scan_at from public.scan_events group by location_id),
open_session as (select distinct on (s.location_id) s.location_id,s.id session_id,s.session_uuid,s.status session_status,s.started_at,s.ended_at,s.duration_minutes,s.duration_display,e.display_name employee_name,d.device_id device_identifier from public.sessions s cross join op_day od left join public.employees e on e.id=s.employee_id left join public.devices d on d.id=s.device_id where s.status in ('active','pending_submit') and s.started_at>=od.day_start order by s.location_id,s.started_at desc,s.created_at desc),
latest_completed as (select distinct on (s.location_id) s.location_id,s.id session_id,s.session_uuid,s.started_at,s.ended_at,s.duration_minutes,s.duration_display,e.display_name employee_name,cr.submitted_at,cr.response_json,coalesce(s.ended_at,cr.submitted_at,s.started_at) effective_completed_at from public.sessions s join public.employees e on e.id=s.employee_id left join public.completion_responses cr on cr.session_id=s.id cross join op_day od where s.status='closed' and coalesce(s.ended_at,cr.submitted_at,s.started_at)>=od.day_start order by s.location_id,coalesce(s.ended_at,cr.submitted_at,s.started_at) desc,s.started_at desc),
open_tickets as (select location_id,count(*) open_ticket_count from public.maintenance_tickets where status='open' group by location_id),
truth as (select l.id location_id,l.location_code,l.location_name,l.location_type,l.form_type,od.day_start,ls.last_scan_at,os.session_id open_session_id,os.session_uuid open_session_uuid,os.session_status open_session_status,os.started_at open_session_started_at,os.ended_at open_session_ended_at,os.employee_name open_session_employee_name,os.device_identifier open_session_device_identifier,lc.session_id latest_completed_session_id,lc.session_uuid latest_completed_session_uuid,lc.started_at latest_started_at,lc.ended_at latest_ended_at,lc.submitted_at latest_submitted_at,lc.effective_completed_at latest_completed_at,lc.employee_name latest_employee_name,lc.duration_minutes,lc.duration_display,lc.response_json,coalesce(ot.open_ticket_count,0::bigint) open_ticket_count,sb.baseline_at,coalesce(lc.effective_completed_at,sb.baseline_at) due_baseline_at from public.locations l cross join op_day od left join scheduled_baseline sb on sb.location_id=l.id left join latest_scan ls on ls.location_id=l.id left join open_session os on os.location_id=l.id left join latest_completed lc on lc.location_id=l.id left join open_tickets ot on ot.location_id=l.id where l.active=true)
select location_id,location_code,location_name,location_type,form_type,day_start operational_day_start,last_scan_at,open_session_id,open_session_uuid,open_session_status,open_session_started_at,open_session_ended_at,latest_completed_session_id,latest_completed_session_uuid,latest_started_at,latest_ended_at,latest_submitted_at,latest_completed_at,latest_employee_name,duration_minutes,duration_display,coalesce(response_json->'services_performed',response_json->'servicesPerformed',response_json->'services',response_json->'completed_services',response_json->'completedServices','[]'::jsonb) services_performed,coalesce(response_json->>'notes',response_json->>'cleaning_notes',response_json->>'cleaningNotes',response_json->>'maintenance_notes',response_json->>'maintenanceNotes',response_json->>'other_service_performed',response_json->>'otherServicePerformed',response_json->>'note') notes,open_ticket_count,
case when open_session_status in ('active','pending_submit') then 'in_progress' when due_baseline_at is null then 'not_cleaned' when form_type='restroom' and now()>=due_baseline_at+make_interval(mins=>public.get_setting_int('restroom_overdue_minutes',120)) then 'overdue' when form_type='restroom' and now()>=due_baseline_at+make_interval(mins=>public.get_setting_int('restroom_due_soon_minutes',90)) then 'due_soon' when form_type='exhibit' and now()>=due_baseline_at+make_interval(mins=>public.get_setting_int('exhibit_overdue_minutes',240)) then 'overdue' when form_type='exhibit' and now()>=due_baseline_at+make_interval(mins=>public.get_setting_int('exhibit_due_soon_minutes',195)) then 'due_soon' else 'okay' end status_code,
case when open_session_status in ('active','pending_submit') then 'blue' when due_baseline_at is null then 'black' when (form_type='restroom' and now()>=due_baseline_at+make_interval(mins=>public.get_setting_int('restroom_overdue_minutes',120))) or (form_type='exhibit' and now()>=due_baseline_at+make_interval(mins=>public.get_setting_int('exhibit_overdue_minutes',240))) then 'red' when (form_type='restroom' and now()>=due_baseline_at+make_interval(mins=>public.get_setting_int('restroom_due_soon_minutes',90))) or (form_type='exhibit' and now()>=due_baseline_at+make_interval(mins=>public.get_setting_int('exhibit_due_soon_minutes',195))) then 'yellow' else 'green' end status_color,
to_char(timezone('America/Chicago',day_start),'MM/DD/YYYY HH12:MI AM')||' Central' operational_day_start_display,to_char(timezone('America/Chicago',last_scan_at),'MM/DD/YYYY HH12:MI AM')||' Central' last_scan_at_display,to_char(timezone('America/Chicago',open_session_started_at),'MM/DD/YYYY HH12:MI AM')||' Central' open_session_started_at_display,to_char(timezone('America/Chicago',open_session_ended_at),'MM/DD/YYYY HH12:MI AM')||' Central' open_session_ended_at_display,to_char(timezone('America/Chicago',latest_started_at),'MM/DD/YYYY HH12:MI AM')||' Central' latest_started_at_display,to_char(timezone('America/Chicago',latest_ended_at),'MM/DD/YYYY HH12:MI AM')||' Central' latest_ended_at_display,to_char(timezone('America/Chicago',latest_submitted_at),'MM/DD/YYYY HH12:MI AM')||' Central' latest_submitted_at_display,to_char(timezone('America/Chicago',latest_completed_at),'MM/DD/YYYY HH12:MI AM')||' Central' latest_completed_at_display,open_session_employee_name,open_session_device_identifier from truth;

-- A reminder is for an event occurrence that has not started. Date-only
-- filtering previously emitted a morning reminder after that day's start.
create or replace function public.ops_manager_enqueue_scheduled_notifications(p_now timestamptz default now()) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $function$
declare v_local_now timestamp without time zone:=p_now at time zone 'America/Chicago'; v_local_date date:=v_local_now::date; v_local_time time:=v_local_now::time; v_dow smallint:=extract(dow from v_local_now)::smallint; v_target record; v_event_count integer; v_next_event record; v_location_count integer; v_due_count integer; v_overdue_count integer; v_location_fingerprint text; v_location_rows jsonb; v_state public.ops_manager_notification_state%rowtype; v_bucket bigint; v_inserted integer:=0;
begin
for v_target in select pd.credential_id,pd.manager_id,coalesce(pref.event_reminders_enabled,false) event_reminders_enabled,coalesce(pref.event_reminder_weekdays,array[0,1,2,3,4,5,6]::smallint[]) event_reminder_weekdays,coalesce(pref.event_reminder_time,'08:00'::time) event_reminder_time,coalesce(pref.event_lookahead_days,7) event_lookahead_days,coalesce(pref.due_soon_enabled,false) due_soon_enabled,coalesce(pref.overdue_enabled,false) overdue_enabled,coalesce(pref.location_repeat_minutes,240) location_repeat_minutes from public.ops_manager_push_devices pd join public.ops_manager_trusted_devices td on td.credential_id=pd.credential_id and td.manager_id=pd.manager_id join public.ops_manager_managers m on m.manager_id=pd.manager_id left join public.ops_manager_notification_preferences pref on pref.credential_id=pd.credential_id where pd.enabled=true and pd.revoked_at is null and td.revoked_at is null and td.expires_at>p_now and m.active=true and m.revoked_at is null and m.is_system_principal=false loop
if v_target.event_reminders_enabled and v_dow=any(v_target.event_reminder_weekdays) and v_local_time>=v_target.event_reminder_time then
select count(*)::integer into v_event_count from public.events_app_events e where e.status='SCHEDULED' and e.event_date<=v_local_date+v_target.event_lookahead_days and ((e.event_date+coalesce(e.start_time,time '00:00')) at time zone 'America/Chicago')>p_now;
if v_event_count>0 then select e.id,e.event_name,e.event_date,e.start_time,e.display_location,((e.event_date+coalesce(e.start_time,time '00:00')) at time zone 'America/Chicago') occurrence_starts_at into v_next_event from public.events_app_events e where e.status='SCHEDULED' and e.event_date<=v_local_date+v_target.event_lookahead_days and ((e.event_date+coalesce(e.start_time,time '00:00')) at time zone 'America/Chicago')>p_now order by e.event_date,e.start_time,e.event_name limit 1;
insert into public.ops_manager_notification_queue(job_key,credential_id,manager_id,notification_type,title,body,data_json) values('manager-event-digest:'||v_target.credential_id::text||':'||v_next_event.id::text||':'||extract(epoch from v_next_event.occurrence_starts_at)::bigint::text,v_target.credential_id,v_target.manager_id,'event_digest','Upcoming Memphis Zoo Events',left(format('%s event%s in the next %s day%s. Next: %s on %s%s.',v_event_count,case when v_event_count=1 then '' else 's' end,v_target.event_lookahead_days,case when v_target.event_lookahead_days=1 then '' else 's' end,coalesce(v_next_event.event_name,'Event'),to_char(v_next_event.event_date,'Mon FMDD'),case when v_next_event.display_location is null then '' else ' at '||v_next_event.display_location end),1000),jsonb_build_object('kind','event_digest','route','events.html','service_date',v_local_date::text,'lookahead_days',v_target.event_lookahead_days,'next_event_id',v_next_event.id,'next_event_starts_at',v_next_event.occurrence_starts_at)) on conflict(job_key) do nothing; get diagnostics v_event_count=row_count; v_inserted:=v_inserted+v_event_count; end if; end if;
if v_target.due_soon_enabled or v_target.overdue_enabled then select count(*)::integer,count(*) filter(where s.status_code='due_soon')::integer,count(*) filter(where s.status_code='overdue')::integer,md5(coalesce(string_agg(s.location_code||':'||s.status_code,',' order by s.status_code,s.location_code),'')),coalesce(jsonb_agg(jsonb_build_object('location_code',s.location_code,'location_name',s.location_name,'status',s.status_code) order by s.status_code,s.location_name),'[]'::jsonb) into v_location_count,v_due_count,v_overdue_count,v_location_fingerprint,v_location_rows from public.v_location_dashboard_status s where (v_target.due_soon_enabled and s.status_code='due_soon') or (v_target.overdue_enabled and s.status_code='overdue'); select * into v_state from public.ops_manager_notification_state where credential_id=v_target.credential_id and state_key='location_digest' for update; if v_location_count=0 then insert into public.ops_manager_notification_state(credential_id,state_key,fingerprint,metadata_json,updated_at) values(v_target.credential_id,'location_digest','',jsonb_build_object('due_soon',0,'overdue',0),p_now) on conflict(credential_id,state_key) do update set fingerprint='',metadata_json=excluded.metadata_json,updated_at=p_now; elsif v_state.credential_id is null or v_state.fingerprint is distinct from v_location_fingerprint or v_state.last_enqueued_at is null or v_state.last_enqueued_at<=p_now-make_interval(mins=>v_target.location_repeat_minutes) then v_bucket:=floor(extract(epoch from p_now)/(v_target.location_repeat_minutes*60))::bigint; insert into public.ops_manager_notification_queue(job_key,credential_id,manager_id,notification_type,title,body,data_json) values('manager-location-digest:'||v_target.credential_id::text||':'||v_location_fingerprint||':'||v_bucket::text,v_target.credential_id,v_target.manager_id,'location_digest','Custodial Location Attention',left(format('%s overdue and %s due soon across all active areas. Tap to review the dashboard.',v_overdue_count,v_due_count),1000),jsonb_build_object('kind','location_digest','route','dashboard.html','location_fingerprint',v_location_fingerprint,'overdue_count',v_overdue_count,'due_soon_count',v_due_count,'locations',v_location_rows)) on conflict(job_key) do nothing; get diagnostics v_location_count=row_count; v_inserted:=v_inserted+v_location_count; insert into public.ops_manager_notification_state(credential_id,state_key,fingerprint,last_enqueued_at,metadata_json,updated_at) values(v_target.credential_id,'location_digest',v_location_fingerprint,p_now,jsonb_build_object('due_soon',v_due_count,'overdue',v_overdue_count),p_now) on conflict(credential_id,state_key) do update set fingerprint=excluded.fingerprint,last_enqueued_at=excluded.last_enqueued_at,metadata_json=excluded.metadata_json,updated_at=now(); end if; end if;
end loop; return jsonb_build_object('ok',true,'enqueued',v_inserted,'checked_at',p_now,'local_date',v_local_date); end $function$;

create or replace function public.custodial_ops_manager_notification_recipient_is_current(
  p_credential_id uuid,p_manager_id uuid,p_now timestamptz default now()
) returns boolean language sql stable security definer set search_path=pg_catalog,public as $function$
  select exists (
    select 1
    from public.ops_manager_push_devices pd
    join public.ops_manager_trusted_devices td
      on td.credential_id=pd.credential_id and td.manager_id=pd.manager_id
    join public.ops_manager_managers m on m.manager_id=pd.manager_id
    where pd.credential_id=p_credential_id and pd.manager_id=p_manager_id
      and pd.enabled=true and pd.revoked_at is null
      and td.revoked_at is null and td.expires_at>p_now
      and m.active=true and m.revoked_at is null and m.is_system_principal=false
  );
$function$;
revoke all on function public.custodial_ops_manager_notification_recipient_is_current(uuid,uuid,timestamptz) from public,anon,authenticated;
grant execute on function public.custodial_ops_manager_notification_recipient_is_current(uuid,uuid,timestamptz) to postgres,service_role;

create or replace function public.custodial_ops_manager_notification_binding_is_current(
  p_push_device_id uuid,p_credential_id uuid,p_manager_id uuid,p_fcm_token_sha256 text,p_now timestamptz default now()
) returns boolean language sql stable security definer set search_path=pg_catalog,public,extensions as $function$
  select exists (
    select 1
    from public.ops_manager_push_devices pd
    join public.ops_manager_trusted_devices td
      on td.credential_id=pd.credential_id and td.manager_id=pd.manager_id
    join public.ops_manager_managers m on m.manager_id=pd.manager_id
    where pd.push_device_id=p_push_device_id
      and pd.credential_id=p_credential_id and pd.manager_id=p_manager_id
      and encode(extensions.digest(convert_to(pd.fcm_token,'UTF8'),'sha256'),'hex')=p_fcm_token_sha256
      and pd.enabled=true and pd.revoked_at is null
      and td.revoked_at is null and td.expires_at>p_now
      and m.active=true and m.revoked_at is null and m.is_system_principal=false
  );
$function$;
revoke all on function public.custodial_ops_manager_notification_binding_is_current(uuid,uuid,uuid,text,timestamptz) from public,anon,authenticated;
grant execute on function public.custodial_ops_manager_notification_binding_is_current(uuid,uuid,uuid,text,timestamptz) to postgres,service_role;

create or replace function public.custodial_ops_manager_location_digest_is_current(
  p_credential_id uuid,p_expected_fingerprint text
) returns boolean language sql stable security definer set search_path=pg_catalog,public as $function$
  with preference as (
    select coalesce(p.due_soon_enabled,false) due_soon_enabled,coalesce(p.overdue_enabled,false) overdue_enabled
    from public.ops_manager_notification_preferences p where p.credential_id=p_credential_id
  ), current_truth as (
    select md5(coalesce(string_agg(s.location_code||':'||s.status_code,',' order by s.status_code,s.location_code),'')) fingerprint
    from public.v_location_dashboard_status s cross join preference p
    where (p.due_soon_enabled and s.status_code='due_soon') or (p.overdue_enabled and s.status_code='overdue')
  )
  select coalesce(nullif(p_expected_fingerprint,'')=(select fingerprint from current_truth),false);
$function$;
revoke all on function public.custodial_ops_manager_location_digest_is_current(uuid,text) from public,anon,authenticated;
grant execute on function public.custodial_ops_manager_location_digest_is_current(uuid,text) to postgres,service_role;

-- A delayed or retried digest is useful only while the exact operational truth
-- named in its payload remains current.
create or replace function public.ops_manager_claim_notification_jobs(
  p_worker_id text,p_limit integer default 20,p_lease_seconds integer default 120
) returns setof public.ops_manager_notification_queue language plpgsql security definer set search_path=pg_catalog,public as $function$
begin
  if nullif(btrim(p_worker_id),'') is null then raise exception using errcode='22023',message='worker id is required'; end if;
  update public.ops_manager_notification_queue q set status='cancelled',completed_at=now(),leased_until=null,lease_token=null,
    last_error='notification recipient authority is no longer current',updated_at=now()
  where (q.status='pending' or (q.status='leased' and q.leased_until<now()))
    and not public.custodial_ops_manager_notification_recipient_is_current(q.credential_id,q.manager_id,now());
  update public.ops_manager_notification_queue q set status='cancelled',completed_at=now(),leased_until=null,lease_token=null,
    last_error='event occurrence is no longer upcoming',updated_at=now()
  where q.notification_type='event_digest' and (q.status='pending' or (q.status='leased' and q.leased_until<now()))
    and not exists (
      select 1 from public.events_app_events e
      where e.id=case when coalesce(q.data_json->>'next_event_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        then (q.data_json->>'next_event_id')::uuid else null end
        and e.status='SCHEDULED'
        and ((e.event_date+e.start_time) at time zone 'America/Chicago')>now()
        and to_jsonb((e.event_date+e.start_time) at time zone 'America/Chicago')=q.data_json->'next_event_starts_at'
    );
  update public.ops_manager_notification_queue q set status='cancelled',completed_at=now(),leased_until=null,lease_token=null,
    last_error='location dashboard state has changed',updated_at=now()
  where q.notification_type='location_digest' and (q.status='pending' or (q.status='leased' and q.leased_until<now()))
    and not public.custodial_ops_manager_location_digest_is_current(q.credential_id,q.data_json->>'location_fingerprint');
  return query with candidates as (
    select q.queue_id from public.ops_manager_notification_queue q
    where ((q.status='pending' and q.available_at<=now()) or (q.status='leased' and q.leased_until<now())) and q.attempts<q.max_attempts
      and public.custodial_ops_manager_notification_recipient_is_current(q.credential_id,q.manager_id,now())
      and (q.notification_type<>'event_digest' or exists (
        select 1 from public.events_app_events e
        where e.id=case when coalesce(q.data_json->>'next_event_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
          then (q.data_json->>'next_event_id')::uuid else null end
          and e.status='SCHEDULED'
          and ((e.event_date+e.start_time) at time zone 'America/Chicago')>now()
          and to_jsonb((e.event_date+e.start_time) at time zone 'America/Chicago')=q.data_json->'next_event_starts_at'
      ))
      and (q.notification_type<>'location_digest' or public.custodial_ops_manager_location_digest_is_current(q.credential_id,q.data_json->>'location_fingerprint'))
    order by q.available_at,q.created_at,q.queue_id for update skip locked limit greatest(1,least(coalesce(p_limit,20),100))
  ) update public.ops_manager_notification_queue q set status='leased',attempts=q.attempts+1,leased_at=now(),
    leased_until=now()+make_interval(secs=>greatest(15,least(coalesce(p_lease_seconds,120),900))),lease_token=gen_random_uuid(),
    worker_id=left(btrim(p_worker_id),160),updated_at=now() from candidates c where q.queue_id=c.queue_id returning q.*;
end $function$;

-- The sender calls this after acquiring its provider token and immediately
-- before dispatch so cancellation, rescheduling, or lease loss cannot cross
-- the worker's slow external-authentication window.
drop function if exists public.ops_manager_notification_job_is_current(uuid,uuid);
create function public.ops_manager_notification_job_is_current(
  p_queue_id uuid,p_lease_token uuid,p_push_device_id uuid,p_fcm_token_sha256 text
) returns boolean language sql stable security definer set search_path=pg_catalog,public as $function$
  select exists (
    select 1 from public.ops_manager_notification_queue q
    where q.queue_id=p_queue_id and q.status='leased' and q.lease_token=p_lease_token and q.leased_until>=now()
      and public.custodial_ops_manager_notification_binding_is_current(
        p_push_device_id,q.credential_id,q.manager_id,p_fcm_token_sha256,now()
      )
      and (q.notification_type<>'event_digest' or exists (
        select 1 from public.events_app_events e
        where e.id=case when coalesce(q.data_json->>'next_event_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
          then (q.data_json->>'next_event_id')::uuid else null end
          and e.status='SCHEDULED'
          and ((e.event_date+e.start_time) at time zone 'America/Chicago')>now()
          and to_jsonb((e.event_date+e.start_time) at time zone 'America/Chicago')=q.data_json->'next_event_starts_at'
      ))
      and (q.notification_type<>'location_digest' or public.custodial_ops_manager_location_digest_is_current(q.credential_id,q.data_json->>'location_fingerprint'))
  );
$function$;
revoke all on function public.ops_manager_notification_job_is_current(uuid,uuid,uuid,text) from public,anon,authenticated;
grant execute on function public.ops_manager_notification_job_is_current(uuid,uuid,uuid,text) to postgres,service_role;

drop function if exists public.ops_manager_finish_notification_job(uuid,uuid,boolean,text,text,integer);
create function public.ops_manager_finish_notification_job(
  p_queue_id uuid,p_lease_token uuid,p_push_device_id uuid,p_fcm_token_sha256 text,
  p_succeeded boolean,p_provider_message_id text default null,p_error text default null,p_retry_seconds integer default 30
) returns public.ops_manager_notification_queue language plpgsql security definer set search_path=pg_catalog,public as $function$
declare v_row public.ops_manager_notification_queue%rowtype; v_job_current boolean; v_recipient_current boolean;
begin
  select * into v_row from public.ops_manager_notification_queue where queue_id=p_queue_id and status='leased' and lease_token=p_lease_token for update;
  if v_row.queue_id is null then raise exception using errcode='P0002',message='Notification job lease was not found'; end if;
  v_recipient_current:=public.custodial_ops_manager_notification_binding_is_current(
    p_push_device_id,v_row.credential_id,v_row.manager_id,p_fcm_token_sha256,now()
  );
  v_job_current:=v_recipient_current;
  if v_row.notification_type='event_digest' then
    select v_job_current and exists (
      select 1 from public.events_app_events e
      where e.id=case when coalesce(v_row.data_json->>'next_event_id','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        then (v_row.data_json->>'next_event_id')::uuid else null end
        and e.status='SCHEDULED'
        and ((e.event_date+e.start_time) at time zone 'America/Chicago')>now()
        and to_jsonb((e.event_date+e.start_time) at time zone 'America/Chicago')=v_row.data_json->'next_event_starts_at'
    ) into v_job_current;
  end if;
  if v_row.notification_type='location_digest' then
    v_job_current:=v_job_current and public.custodial_ops_manager_location_digest_is_current(v_row.credential_id,v_row.data_json->>'location_fingerprint');
  end if;
  if not v_job_current then
    update public.ops_manager_notification_queue set status='cancelled',completed_at=now(),leased_until=null,lease_token=null,
      last_error=case when not v_recipient_current then 'notification recipient authority is no longer current' when v_row.notification_type='location_digest' then 'location dashboard state has changed' else 'event occurrence is no longer upcoming' end,
      updated_at=now() where queue_id=p_queue_id returning * into v_row;
  elsif p_succeeded then
    update public.ops_manager_notification_queue set status='sent',sent_at=now(),completed_at=now(),leased_until=null,lease_token=null,
      provider_message_id=nullif(left(coalesce(p_provider_message_id,''),500),''),last_error=null,updated_at=now()
    where queue_id=p_queue_id returning * into v_row;
    update public.ops_manager_notification_state set last_sent_at=now(),updated_at=now()
    where credential_id=v_row.credential_id and state_key=case when v_row.notification_type='location_digest' then 'location_digest' else '__none__' end;
  else
    update public.ops_manager_notification_queue set status=case when attempts>=max_attempts then 'failed' else 'pending' end,
      available_at=case when attempts>=max_attempts then available_at else now()+make_interval(secs=>greatest(15,least(coalesce(p_retry_seconds,30),86400))) end,
      completed_at=case when attempts>=max_attempts then now() else null end,leased_until=null,lease_token=null,
      last_error=left(coalesce(p_error,'Notification delivery failed'),2000),updated_at=now() where queue_id=p_queue_id returning * into v_row;
  end if;
  return v_row;
end $function$;
revoke all on function public.ops_manager_finish_notification_job(uuid,uuid,uuid,text,boolean,text,text,integer) from public,anon,authenticated;
grant execute on function public.ops_manager_finish_notification_job(uuid,uuid,uuid,text,boolean,text,text,integer) to postgres,service_role;

commit;

begin;

-- The release canary can be stopped without depending on process memory. The
-- state is keyed to the exact physical employee-phone identifier and survives
-- backend restarts and traffic moving between instances.
create table if not exists public.custodial_release_canary_controls (
  device_identifier text primary key check (device_identifier ~ '^KIOSK_(0[2-9]|10)$'),
  paused boolean not null default true,
  updated_at timestamptz not null default statement_timestamp(),
  updated_by_manager_id uuid not null references public.ops_manager_managers(manager_id),
  reason text not null check (length(btrim(reason)) between 1 and 1000)
);

create table if not exists public.custodial_release_canary_rollback_audits (
  audit_id uuid primary key default gen_random_uuid(),
  requested_at timestamptz not null default statement_timestamp(),
  requested_by_manager_id uuid not null references public.ops_manager_managers(manager_id),
  request_id uuid not null,
  device_identifier text not null check (device_identifier ~ '^KIOSK_(0[2-9]|10)$'),
  action text not null check (action in ('pause_canary','resume_canary','restore_authority')),
  reason text not null check (length(btrim(reason)) between 1 and 1000),
  authoritative_health jsonb not null,
  result_json jsonb not null default '{}'::jsonb,
  unique (requested_by_manager_id, request_id)
);

-- Capture the reviewed, known-good authority definitions at migration time.
-- A later present-but-broken RPC can be restored forward without reviving any
-- legacy writer or deleting authority evidence.
create table if not exists public.custodial_release_authority_restore_definitions (
  restore_order integer primary key,
  function_identity text not null unique,
  function_definition text not null,
  definition_sha256 text not null check (definition_sha256 ~ '^[0-9a-f]{64}$'),
  captured_at timestamptz not null default statement_timestamp()
);

-- Verify every other captured canonical definition. The health function itself
-- is captured below, so a broken or missing health RPC is also forward-restorable.
create or replace function public.custodial_backend_authority_health(p_backend_execution_secret text)
returns jsonb language plpgsql security definer set search_path to 'pg_catalog','public','extensions'
as $function$
declare
  v_expected integer;
  v_missing text[];
  v_mismatched text[];
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  select count(*) into v_expected from public.custodial_release_authority_restore_definitions;
  select array_agg(d.function_identity order by d.restore_order) into v_missing
  from public.custodial_release_authority_restore_definitions d
  where to_regprocedure(d.function_identity) is null;
  select array_agg(d.function_identity order by d.restore_order) into v_mismatched
  from public.custodial_release_authority_restore_definitions d
  where to_regprocedure(d.function_identity) is not null
    and encode(extensions.digest(convert_to(pg_get_functiondef(to_regprocedure(d.function_identity)),'UTF8'),'sha256'),'hex')<>d.definition_sha256;
  return jsonb_build_object(
    'ok',v_expected=7 and coalesce(cardinality(v_missing),0)=0 and coalesce(cardinality(v_mismatched),0)=0,
    'authority','offline-authority.v4','phase','release-canary-operational-recovery','configured',true,
    'canonical_functions_expected',7,'canonical_functions_verified',v_expected-coalesce(cardinality(v_missing),0)-coalesce(cardinality(v_mismatched),0),
    'missing_functions',to_jsonb(coalesce(v_missing,array[]::text[])),'mismatched_functions',to_jsonb(coalesce(v_mismatched,array[]::text[])),
    'issued_snapshot_ledger',true,'frozen_exact_replay',true,'operational_day_location_truth',true);
end $function$;

with wanted(restore_order, function_identity) as (values
  (1, 'public.custodial_commit_offline_occurrence(text,text,text,text,text,text,jsonb,jsonb,text,text,text,text,text)'),
  (2, 'public.tool_get_offline_scan_authority_snapshot(text,text,text)'),
  (3, 'public.custodial_start_offline_occurrence(text,text,text,text,text,text,integer,text,text,text)'),
  (4, 'public.tool_start_offline_occurrence(text,text,text,text,text,text,integer,text,text,text)'),
  (5, 'public.tool_commit_cleaning_workflow_authoritative(text,text,text,text,text,text,jsonb,jsonb,text,text,text,text,text)'),
  (6, 'public.tool_complete_session_authoritative(text,jsonb,text,text,text,text)'),
  (7, 'public.custodial_backend_authority_health(text)')
), captured as (
  select w.restore_order, w.function_identity, pg_get_functiondef(to_regprocedure(w.function_identity)) function_definition
  from wanted w
)
insert into public.custodial_release_authority_restore_definitions(
  restore_order, function_identity, function_definition, definition_sha256
)
select restore_order, function_identity, function_definition,
  encode(extensions.digest(convert_to(function_definition,'UTF8'),'sha256'),'hex')
from captured
where function_definition is not null
on conflict (restore_order) do nothing;

do $restore_set$
begin
  if (select count(*) from public.custodial_release_authority_restore_definitions) <> 7 then
    raise exception 'The release authority restoration set is incomplete';
  end if;
end
$restore_set$;

create or replace function public.custodial_release_canary_is_paused(
  p_device_identifier text, p_backend_execution_secret text
) returns boolean language plpgsql security definer set search_path to 'pg_catalog','public'
as $function$
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  if upper(btrim(coalesce(p_device_identifier,''))) !~ '^KIOSK_(0[2-9]|10)$' then
    raise exception using errcode='22023', message='an exact employee-phone canary identifier is required';
  end if;
  return coalesce((select paused from public.custodial_release_canary_controls
    where device_identifier=upper(btrim(p_device_identifier))), false);
end
$function$;

create or replace function public.custodial_control_release_canary(
  p_manager_id uuid, p_request_id uuid, p_device_identifier text, p_action text,
  p_reason text, p_authoritative_health jsonb, p_backend_execution_secret text
) returns jsonb language plpgsql security definer set search_path to 'pg_catalog','public','extensions'
as $function$
declare
  v_existing public.custodial_release_canary_rollback_audits%rowtype;
  v_definition public.custodial_release_authority_restore_definitions%rowtype;
  v_device text:=upper(btrim(coalesce(p_device_identifier,'')));
  v_result jsonb;
  v_current_health jsonb;
  v_missing text[];
  v_mismatched text[];
  v_restored integer:=0;
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  if not exists (select 1 from public.ops_manager_managers m where m.manager_id=p_manager_id
    and m.active=true and m.revoked_at is null and m.roles && array['DIRECTOR','SECURITY_ADMIN']::text[]) then
    raise exception using errcode='42501', message='named release manager authority is required';
  end if;
  if p_request_id is null or v_device !~ '^KIOSK_(0[2-9]|10)$'
     or p_action not in ('pause_canary','resume_canary','restore_authority')
     or length(btrim(coalesce(p_reason,''))) not between 1 and 1000
     or jsonb_typeof(p_authoritative_health) <> 'object' then
    raise exception using errcode='22023', message='stable request, exact canary, supported action, reason, and authority health are required';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('custodial-release-canary:'||v_device,0));
  select * into v_existing from public.custodial_release_canary_rollback_audits
   where requested_by_manager_id=p_manager_id and request_id=p_request_id for update;
  if found then
    if v_existing.device_identifier<>v_device or v_existing.action<>p_action
       or v_existing.reason<>btrim(p_reason) or v_existing.authoritative_health<>p_authoritative_health then
      raise exception using errcode='23505',message='release control request identity is already bound to different inputs';
    end if;
    return v_existing.result_json || jsonb_build_object('audit_id',v_existing.audit_id,'replayed',true);
  end if;

  if p_action='pause_canary' then
    insert into public.custodial_release_canary_controls(device_identifier,paused,updated_by_manager_id,reason)
    values(v_device,true,p_manager_id,btrim(p_reason))
    on conflict(device_identifier) do update set paused=true,updated_at=statement_timestamp(),
      updated_by_manager_id=excluded.updated_by_manager_id,reason=excluded.reason;
    v_result:=jsonb_build_object('device_identifier',v_device,'canary_paused',true,'restored_functions',0);
  elsif p_action='restore_authority' then
    if not coalesce((select paused from public.custodial_release_canary_controls where device_identifier=v_device),false) then
      raise exception using errcode='55000',message='the exact release canary must be paused before authority restoration';
    end if;
    for v_definition in select * from public.custodial_release_authority_restore_definitions order by restore_order loop
      if encode(extensions.digest(convert_to(v_definition.function_definition,'UTF8'),'sha256'),'hex')<>v_definition.definition_sha256 then
        raise exception using errcode='23514',message='a captured authority restoration definition failed its digest';
      end if;
      execute v_definition.function_definition;
      v_restored:=v_restored+1;
    end loop;
    execute 'revoke all on function public.custodial_commit_offline_occurrence(text,text,text,text,text,text,jsonb,jsonb,text,text,text,text,text) from public,anon,authenticated,service_role';
    execute 'revoke all on function public.custodial_start_offline_occurrence(text,text,text,text,text,text,integer,text,text,text), public.tool_start_offline_occurrence(text,text,text,text,text,text,integer,text,text,text), public.tool_get_offline_scan_authority_snapshot(text,text,text), public.tool_commit_cleaning_workflow_authoritative(text,text,text,text,text,text,jsonb,jsonb,text,text,text,text,text), public.tool_complete_session_authoritative(text,jsonb,text,text,text,text), public.custodial_backend_authority_health(text) from public,anon,authenticated';
    execute 'grant execute on function public.custodial_start_offline_occurrence(text,text,text,text,text,text,integer,text,text,text), public.tool_start_offline_occurrence(text,text,text,text,text,text,integer,text,text,text), public.tool_get_offline_scan_authority_snapshot(text,text,text), public.tool_commit_cleaning_workflow_authoritative(text,text,text,text,text,text,jsonb,jsonb,text,text,text,text,text), public.tool_complete_session_authoritative(text,jsonb,text,text,text,text), public.custodial_backend_authority_health(text) to postgres,service_role';
    v_result:=jsonb_build_object('device_identifier',v_device,'canary_paused',true,'restored_functions',v_restored);
  else
    select array_agg(d.function_identity order by d.restore_order) into v_missing
    from public.custodial_release_authority_restore_definitions d where to_regprocedure(d.function_identity) is null;
    select array_agg(d.function_identity order by d.restore_order) into v_mismatched
    from public.custodial_release_authority_restore_definitions d where to_regprocedure(d.function_identity) is not null
      and encode(extensions.digest(convert_to(pg_get_functiondef(to_regprocedure(d.function_identity)),'UTF8'),'sha256'),'hex')<>d.definition_sha256;
    v_current_health:=jsonb_build_object('ok',coalesce(cardinality(v_missing),0)=0 and coalesce(cardinality(v_mismatched),0)=0,
      'canonical_functions_expected',7,'canonical_functions_verified',7-coalesce(cardinality(v_missing),0)-coalesce(cardinality(v_mismatched),0),
      'missing_functions',to_jsonb(coalesce(v_missing,array[]::text[])),'mismatched_functions',to_jsonb(coalesce(v_mismatched,array[]::text[])));
    if p_authoritative_health->>'ok'<>'true' or v_current_health->>'ok'<>'true' then
      raise exception using errcode='55000',message='the release canary cannot resume until authoritative health is green';
    end if;
    insert into public.custodial_release_canary_controls(device_identifier,paused,updated_by_manager_id,reason)
    values(v_device,false,p_manager_id,btrim(p_reason))
    on conflict(device_identifier) do update set paused=false,updated_at=statement_timestamp(),
      updated_by_manager_id=excluded.updated_by_manager_id,reason=excluded.reason;
    v_result:=jsonb_build_object('device_identifier',v_device,'canary_paused',false,'restored_functions',0,'verified_authoritative_health',v_current_health);
  end if;

  insert into public.custodial_release_canary_rollback_audits(
    requested_by_manager_id,request_id,device_identifier,action,reason,authoritative_health,result_json
  ) values(p_manager_id,p_request_id,v_device,p_action,btrim(p_reason),p_authoritative_health,v_result)
  returning audit_id into v_existing.audit_id;
  return v_result || jsonb_build_object('audit_id',v_existing.audit_id,'replayed',false);
end
$function$;

-- The preceding inventory's legacy-wrapper matcher predates names ending in
-- _authoritative. Require an actual legacy function call so a recovery control
-- that mentions the canonical function identities is not misclassified as an
-- alternate terminal writer.
create or replace view public.custodial_terminal_writer_inventory as
select p.oid,p.oid::regprocedure::text as routine_identity,p.proname,
  p.prorettype <> 'pg_catalog.trigger'::regtype and (has_function_privilege('anon',p.oid,'EXECUTE') or has_function_privilege('authenticated',p.oid,'EXECUTE') or has_function_privilege('service_role',p.oid,'EXECUTE')) as application_callable,
  lower(pg_get_functiondef(p.oid)) as definition,
  (lower(pg_get_functiondef(p.oid)) ~ '(insert[[:space:]]+into|update|delete[[:space:]]+from|truncate([[:space:]]+table)?)' and lower(pg_get_functiondef(p.oid)) ~ 'public[.]?(sessions|completion_responses|scan_events|maintenance_tickets)') as mutates_terminal_truth,
  (p.proname like 'demo_scan_mock_%'
    or lower(pg_get_functiondef(p.oid)) ~ 'public[.]demo_scan_mock_[a-z0-9_]*[[:space:]]*[(]'
    or lower(pg_get_functiondef(p.oid)) ~ 'public[.](purge_closed_scan_history_before|tool_purge_closed_scan_history_before|close_maintenance_ticket|tool_close_maintenance_ticket|force_close_session|tool_force_close_session|start_session|tool_start_session|finish_session|tool_finish_session|complete_session|tool_complete_session|record_scan_event|tool_record_scan_event)[[:space:]]*[(]') as delegates_alternate_terminal_authority
from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind='f';

