-- The connected-catalog release identity includes the active pg_cron jobs.
-- Keep that observation on the dedicated read-only authority: grant only
-- schema lookup and the six columns consumed by schema-fingerprint-catalog.

begin;

do $guard$
begin
  if not exists (
    select 1
    from pg_roles
    where rolname = 'custodial_application_reader'
      and not rolsuper
      and not rolbypassrls
      and not rolcanlogin
  ) then
    raise exception 'The restricted custodial_application_reader role is required.';
  end if;

  if to_regclass('cron.job') is null then
    raise exception 'The managed cron.job catalog is required for release identity observation.';
  end if;
end
$guard$;

revoke create on schema cron from custodial_application_reader;
grant usage on schema cron to custodial_application_reader;
grant select (jobname, schedule, command, database, username, active)
  on table cron.job
  to custodial_application_reader;

do $verify$
begin
  if not has_schema_privilege('custodial_application_reader', 'cron', 'usage') then
    raise exception 'custodial_application_reader lacks cron schema usage after grant.';
  end if;

  if not has_column_privilege('custodial_application_reader', 'cron.job', 'jobname', 'select')
     or not has_column_privilege('custodial_application_reader', 'cron.job', 'schedule', 'select')
     or not has_column_privilege('custodial_application_reader', 'cron.job', 'command', 'select')
     or not has_column_privilege('custodial_application_reader', 'cron.job', 'database', 'select')
     or not has_column_privilege('custodial_application_reader', 'cron.job', 'username', 'select')
     or not has_column_privilege('custodial_application_reader', 'cron.job', 'active', 'select') then
    raise exception 'custodial_application_reader lacks an admitted cron catalog column after grant.';
  end if;

  if has_schema_privilege('custodial_application_reader', 'cron', 'create')
     or has_table_privilege('custodial_application_reader', 'cron.job', 'insert')
     or has_table_privilege('custodial_application_reader', 'cron.job', 'update')
     or has_table_privilege('custodial_application_reader', 'cron.job', 'delete') then
    raise exception 'custodial_application_reader gained forbidden cron mutation authority.';
  end if;
end
$verify$;

commit;

-- Keep the dedicated application reader explicit and independent of which
-- equivalent managed migration owner creates a later public relation.
--
-- The original reader migration granted SELECT on all then-current relations
-- and installed a broad postgres-owner default. Production therefore granted
-- two later correction-evidence relations to the reader while the clean
-- supabase_admin rebuild did not. Neither relation is an admitted application
-- read surface. Future reader access must be granted explicitly by the owning
-- migration instead of arriving through an owner-dependent default.

do $migration$
begin
  if not exists (select 1 from pg_roles where rolname = 'custodial_application_reader') then
    raise exception 'The restricted custodial_application_reader role is required.';
  end if;

  if exists (
    select 1
    from pg_default_acl d
    join pg_roles owner on owner.oid = d.defaclrole
    left join pg_namespace n on n.oid = d.defaclnamespace
    cross join lateral aclexplode(d.defaclacl) x
    join pg_roles grantee on grantee.oid = x.grantee
    where owner.rolname = 'supabase_admin'
      and n.nspname = 'public'
      and d.defaclobjtype = 'r'
      and grantee.rolname = 'custodial_application_reader'
      and x.privilege_type = 'SELECT'
  ) then
    raise exception 'supabase_admin has a reader default that requires an owner-authorized correction.';
  end if;

  if exists (select 1 from pg_roles where rolname = 'postgres') then
    execute 'alter default privileges for role postgres in schema public revoke select on tables from custodial_application_reader';
  end if;

  if to_regclass('public.custodial_session_corrections') is not null then
    revoke select on table public.custodial_session_corrections from custodial_application_reader;
  end if;
  if to_regclass('public.v_custodial_cleaning_session_truth') is not null then
    revoke select on table public.v_custodial_cleaning_session_truth from custodial_application_reader;
  end if;
end
$migration$;

do $verify$
begin
  if has_table_privilege(
    'custodial_application_reader',
    'public.custodial_session_corrections',
    'select'
  ) then
    raise exception 'custodial_session_corrections remains an unapproved application-reader surface.';
  end if;
  if has_table_privilege(
    'custodial_application_reader',
    'public.v_custodial_cleaning_session_truth',
    'select'
  ) then
    raise exception 'v_custodial_cleaning_session_truth remains an unapproved application-reader surface.';
  end if;
  if exists (
    select 1
    from pg_default_acl d
    join pg_roles owner on owner.oid = d.defaclrole
    left join pg_namespace n on n.oid = d.defaclnamespace
    cross join lateral aclexplode(d.defaclacl) x
    join pg_roles grantee on grantee.oid = x.grantee
    where owner.rolname in ('postgres', 'supabase_admin')
      and n.nspname = 'public'
      and d.defaclobjtype = 'r'
      and grantee.rolname = 'custodial_application_reader'
      and x.privilege_type = 'SELECT'
  ) then
    raise exception 'A managed migration owner still grants future public relations to custodial_application_reader.';
  end if;
end
$verify$;

-- The dedicated application reader must observe the exact release cron
-- catalog without inheriting pg_cron's owner-only row policy or receiving
-- direct authority over cron.job. Keep the bridge fixed, read-only and scoped
-- to the six release-identity columns. Also bind recovery to the corrected
-- post-20260822150000 ACL for the append-only correction table.

begin;

do $preflight$
begin
  if not exists (
    select 1
    from pg_roles
    where rolname = 'custodial_application_reader'
      and not rolsuper
      and not rolbypassrls
      and not rolcanlogin
  ) then
    raise exception 'The restricted custodial_application_reader role is required.';
  end if;
  if not exists (select 1 from pg_roles where rolname = 'supabase_admin') then
    raise exception 'The managed supabase_admin owner is required.';
  end if;
  if current_user not in ('postgres', 'supabase_admin') then
    raise exception 'A managed migration owner is required.';
  end if;
  if to_regclass('cron.job') is null then
    raise exception 'The managed cron.job catalog is required.';
  end if;
  if to_regclass('public.custodial_release_authority_restore_inventory') is null
     or to_regprocedure('public.custodial_release_authority_current_grant_definition(text)') is null then
    raise exception 'The exact release recovery inventory is unavailable.';
  end if;
end
$preflight$;

