        (tier.value->'attestation')-'terminalReport'-'rawReceiptDigest',
        false
      ),
      '{options}',
      (tier.value->'options')-'time_limit',
      false
    ) order by tier.ordinality
  ),'[]'::jsonb)
  into v_projection
  from jsonb_array_elements(p_tiers) with ordinality tier(value,ordinality);
  return v_projection;
end
