    array['durationMilliseconds','solveCount','modelBytes','modelBasisBytes','modelVariables','modelRows','modelTerms','workerOutputBytes','boundedWorkingMemoryBytes','receiptBytes','preflight','resultBytes'],'v5 solver execution receipt');
  perform public.static_weekly_assert_exact_object(v_authority_certificate->'execution',
    array['solveCount','modelBytes','modelBasisBytes','modelVariables','modelRows','modelTerms','boundedWorkingMemoryBytes','preflight'],
    array['solveCount','modelBytes','modelBasisBytes','modelVariables','modelRows','modelTerms','boundedWorkingMemoryBytes','preflight'],'v5 authority execution receipt');

  if exists(
    select 1 from unnest(array['durationMilliseconds','solveCount','modelBytes','modelBasisBytes','modelVariables','modelRows','modelTerms','workerOutputBytes','boundedWorkingMemoryBytes','receiptBytes','resultBytes']) field_name
    where jsonb_typeof(v_certificate->'execution'->field_name) is distinct from 'number'
  ) or jsonb_typeof(v_certificate#>'{execution,preflight}') is distinct from 'object'
     or jsonb_typeof(v_authority_certificate#>'{execution,preflight}') is distinct from 'object' then
    raise exception using errcode='23514',message='v5 execution receipt fields require exact numeric telemetry and one preflight object';
  end if;
  if exists(
    select 1 from unnest(array['durationMilliseconds','solveCount','modelBytes','modelBasisBytes','modelVariables','modelRows','modelTerms','workerOutputBytes','boundedWorkingMemoryBytes','receiptBytes','resultBytes']) field_name
    where (v_certificate->'execution'->>field_name)::numeric<>trunc((v_certificate->'execution'->>field_name)::numeric)
       or (v_certificate->'execution'->>field_name)::numeric<0
       or (v_certificate->'execution'->>field_name)::numeric>9007199254740991
  ) then
    raise exception using errcode='23514',message='v5 execution receipt telemetry must be nonnegative exact safe integers';
  end if;

  if jsonb_typeof(v_compiler->'compilerVersion') is distinct from 'string'
    or jsonb_typeof(v_compiler->'status') is distinct from 'string'
    or jsonb_typeof(v_compiler->'publicationAuthority') is distinct from 'string'
    or jsonb_typeof(v_compiler->'inputDigest') is distinct from 'string'
    or jsonb_typeof(v_compiler->'solutionDigest') is distinct from 'string'
    or jsonb_typeof(v_compiler->'authorityDigest') is distinct from 'string'
    or jsonb_typeof(v_compiler->'replayDigest') is distinct from 'string'
    or jsonb_typeof(v_compiler->'canonicalAuthority') is distinct from 'object'
    or jsonb_typeof(p_authority#>'{compilerInput,version}') is distinct from 'object'
    or jsonb_typeof(p_authority#>'{compilerInput,version,id}') is distinct from 'string'
    or jsonb_typeof(p_authority#>'{compilerInput,version,publicationId}') is distinct from 'string'
    or jsonb_typeof(p_authority#>'{compilerInput,version,assignments}') is distinct from 'array'
    or jsonb_typeof(p_authority#>'{compilerInput,version,slotAvailability}') is distinct from 'array'
    or jsonb_typeof(p_authority#>'{compilerInput,slots}') is distinct from 'array'
    or jsonb_typeof(p_authority#>'{compilerInput,exceptions}') is distinct from 'array'
    or jsonb_typeof(p_authority#>'{overlayCompilerInput,exceptions}') is distinct from 'array'
    or jsonb_typeof(v_optimizer->'assignments') is distinct from 'array'
    or jsonb_typeof(v_optimizer->'tiers') is distinct from 'array'
    or jsonb_typeof(v_optimizer->'certificate') is distinct from 'object'
    or jsonb_typeof(p_authority->'projectionAvailability') is distinct from 'array'
    or jsonb_typeof(p_authority->'appliedExceptions') is distinct from 'array' then
    raise exception using errcode='23514',message='compiler, optimizer, certificate, model, and projection receipt fields are required';
  end if;

  v_without:=p_authority-'databaseContentIdentity';
  if jsonb_typeof(p_authority->'inputDigest') is distinct from 'string'
    or jsonb_typeof(p_authority->'baselineInputDigest') is distinct from 'string'
    or jsonb_typeof(p_authority->'weeklyVersionDigest') is distinct from 'string'
    or jsonb_typeof(p_authority->'databaseContentIdentity') is distinct from 'string'
    or p_authority->>'effectiveDate' is distinct from p_effective_start::text
    or p_authority->>'databaseContentIdentity' is distinct from public.static_weekly_digest_jsonb(v_without)
    or p_authority->>'inputDigest' is distinct from public.static_weekly_digest_jsonb(p_authority->'overlayCompilerInput')
    or p_authority->>'baselineInputDigest' is distinct from public.static_weekly_digest_jsonb(p_authority->'compilerInput')
    or v_compiler->>'inputDigest' is distinct from p_authority->>'inputDigest'
    or v_compiler->>'solutionDigest' is distinct from public.static_weekly_digest_jsonb(v_optimizer)
    or v_compiler->>'authorityDigest' is distinct from public.static_weekly_digest_jsonb(p_authority)
    or v_compiler->'canonicalAuthority' is distinct from p_authority
    or coalesce(v_compiler->>'replayDigest','') !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='23514',message='compiler input, baseline, solution, authority, and replay identities must be exact';
  end if;

  select coalesce(jsonb_agg(tier.value->'options' order by tier.ordinality),'[]'::jsonb)
  into v_tier_options
  from jsonb_array_elements(v_solver_tiers) with ordinality tier(value,ordinality);
  v_authority_tiers:=public.static_weekly_v5_canonical_solver_tiers(v_solver_tiers);
  v_expected_authority_certificate:=
    (v_certificate-'tierReceiptDigest'-'tierOptionsDigest');
  v_expected_authority_certificate:=jsonb_set(
    v_expected_authority_certificate,
    '{execution}',
    (v_certificate->'execution')-'durationMilliseconds'-'receiptBytes'-'workerOutputBytes'-'resultBytes',
    false
  );

  if v_certificate->>'schema' is distinct from 'memphis-zoo.static-weekly-solver-certificate.v5'
    or v_certificate->>'compilerVersion' is distinct from 'static-weekly-highs-mip-v8-workload-duty-boundary'
    or v_certificate->>'compilerVersion' is distinct from v_compiler->>'compilerVersion'
    or v_optimizer->>'compilerVersion' is distinct from v_compiler->>'compilerVersion'
    or v_certificate->>'verifierVersion' is distinct from 'static-weekly-js-verifier-v8-workload-duty-boundary'
    or v_compiler#>>'{verifier,verifierVersion}' is distinct from v_certificate->>'verifierVersion'
    or v_compiler#>>'{independentVerification,verifierVersion}' is distinct from v_certificate->>'verifierVersion'
    or v_certificate->>'objectivePolicyVersion' is distinct from 'monotonic-leximax-v1'
    or v_optimizer#>>'{objective,policyVersion}' is distinct from v_certificate->>'objectivePolicyVersion'
    or v_certificate->>'canonicalInputDigest' is distinct from p_authority->>'inputDigest'
    or v_certificate->>'baselineInputDigest' is distinct from p_authority->>'baselineInputDigest'
    or v_certificate->>'weeklyVersionDigest' is distinct from p_authority->>'weeklyVersionDigest'
    or jsonb_typeof(v_certificate->'solverIdentity') is distinct from 'object'
    or v_certificate->'solverIdentity' is distinct from v_compiler#>'{solver,identity}'
    or coalesce(v_certificate->>'tierReceiptDigest','') !~ '^[0-9a-f]{64}$'
    or v_certificate->>'tierReceiptDigest' is distinct from public.static_weekly_digest_jsonb(v_solver_tiers)
    or coalesce(v_certificate->>'tierOptionsDigest','') !~ '^[0-9a-f]{64}$'
    or v_certificate->>'tierOptionsDigest' is distinct from public.static_weekly_digest_jsonb(v_tier_options)
    or coalesce(v_certificate->>'assignmentDigest','') !~ '^[0-9a-f]{64}$'
    or coalesce(v_certificate->>'modelBasisDigest','') !~ '^[0-9a-f]{64}$'
    or jsonb_typeof(v_certificate->'modelBasis') is distinct from 'object'
    or jsonb_typeof(v_certificate->'canonicalProgram') is distinct from 'object'
    or jsonb_typeof(v_certificate->'finalWitness') is distinct from 'object'
    or jsonb_typeof(v_certificate->'execution') is distinct from 'object'
    or jsonb_typeof(v_compiler#>'{independentVerification,violations}') is distinct from 'array'
    or jsonb_typeof(v_compiler#>'{independentVerification,ok}') is distinct from 'boolean'
    or v_compiler#>>'{independentVerification,ok}' is distinct from 'true'
    or v_authority_certificate is distinct from v_expected_authority_certificate
    or v_optimizer->'certificate' is distinct from v_authority_certificate
    or v_compiler->'authorityTiers' is distinct from v_authority_tiers
    or v_optimizer->'tiers' is distinct from v_authority_tiers then
    raise exception using errcode='23514',message='complete accepted v5 solver/verifier certificate, tier receipts, model, witness, and deterministic authority projection are required';
  end if;

  if p_require_publishable and (
    v_compiler->>'status' is distinct from 'FEASIBLE'
    or v_compiler->>'publicationAuthority' is distinct from 'ACCEPTABLE'
  ) then
    raise exception using errcode='23514',message='only a successful publishable compiler result may create a recurring authority version';
  end if;
  if p_require_publishable and (
    p_authority->'appliedExceptions' is distinct from '[]'::jsonb
    or p_authority->'overlayCompilerInput' is distinct from p_authority->'compilerInput'
    or p_authority->>'inputDigest' is distinct from p_authority->>'baselineInputDigest'
  ) then
    raise exception using errcode='23514',message='recurring draft authority must be an exception-free baseline compiler result';
  end if;
end
$function$;

comment on function public.static_weekly_assert_compiler_authority(jsonb,jsonb,date,boolean) is
'Admits only the exact v8 compiler/v8 verifier compact-v5 certificate, recomputes complete tier receipt digests, and binds deterministic authority projections.';

commit;

-- Keep the portable model, control plane, and database on one local-time
-- contract. Exact 24:00 is the end of the current service day and is valid
-- only as a window end; no window may start at or continue beyond it.
begin;

create or replace function public.static_weekly_v3_assert_window(p_value jsonb,p_label text)
returns void
language plpgsql
security definer
set search_path=pg_catalog,public
as $function$
declare
  v_start_minutes integer;
  v_end_minutes integer;
begin
  perform public.static_weekly_assert_exact_object(p_value,array['start','end'],array['start','end'],p_label);
  perform public.static_weekly_v3_assert_text(p_value->'start',p_label||' start',5);
  perform public.static_weekly_v3_assert_text(p_value->'end',p_label||' end',5);
  if p_value->>'start' !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
     or (p_value->>'end' !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' and p_value->>'end' is distinct from '24:00') then
    raise exception using errcode='23514',message=format('%s endpoints must be HH:MM local time with 24:00 permitted only as the end of day',p_label);
  end if;
  v_start_minutes:=substring(p_value->>'start' from 1 for 2)::integer*60+substring(p_value->>'start' from 4 for 2)::integer;
  v_end_minutes:=case when p_value->>'end'='24:00' then 1440 else substring(p_value->>'end' from 1 for 2)::integer*60+substring(p_value->>'end' from 4 for 2)::integer end;
  if v_start_minutes>=v_end_minutes then
    raise exception using errcode='23514',message=format('%s must be an ordered nonempty local window',p_label);
  end if;
end
$function$;

revoke all on function public.static_weekly_v3_assert_window(jsonb,text)
from public,anon,authenticated,service_role,static_weekly_control_plane,static_weekly_release_operator,custodial_application_reader;

comment on function public.static_weekly_v3_assert_window(jsonb,text) is
'Validates one same-service-day local window; exact 24:00 is accepted only as its terminal endpoint.';

commit;

-- Hydrate the immutable stable-roster identity from one release-registered
-- recurring source.  The release operator supplies only the registered source
-- UUID and an active named manager; caller-authored roster content is never
-- accepted.

create or replace function public.static_weekly_v6_initialize_registered_roster(
  p_source_id uuid,
  p_manager_id uuid,
  p_configured_by text default 'production-manager'
)
returns jsonb
language plpgsql
security definer
set search_path=pg_catalog,public
as $function$
declare
  v_source jsonb;
  v_slots jsonb;
  v_slot jsonb;
  v_incumbencies jsonb;
  v_incumbent jsonb;
  v_actor jsonb;
  v_slot_id uuid;
  v_person_id uuid;
  v_effective_start date;
  v_effective_end date;
  v_slot_code text;
  v_expected_slots integer:=0;
  v_expected_incumbencies integer:=0;
  v_existing_slots integer:=0;
  v_existing_incumbencies integer:=0;
  v_mismatch boolean:=false;
begin
  perform public.static_weekly_v3_assert_release_operator();
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-initial-roster',0));
  v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
  if p_source_id is null or nullif(btrim(coalesce(p_configured_by,'')),'') is null or length(p_configured_by)>200 then
    raise exception using errcode='22023',message='registered roster bootstrap requires a source, named manager, and bounded release owner';
  end if;

  select canonical_source into v_source
  from public.static_weekly_authority_source_documents
  where source_id=p_source_id and active=true and retired_at is null
  for share;
  if not found then
    raise exception using errcode='23514',message='registered roster bootstrap requires one active immutable authority source';
  end if;
  v_slots:=v_source->'slots';
  if jsonb_typeof(v_slots) is distinct from 'array' or jsonb_array_length(v_slots)=0 or jsonb_array_length(v_slots)>256 then
    raise exception using errcode='23514',message='registered roster bootstrap source must contain a bounded nonempty stable-slot set';
  end if;

  -- Validate the complete registered source before deciding between initial
  -- insertion and the exact idempotent replay path.
  for v_slot in select value from jsonb_array_elements(v_slots) loop
    perform public.static_weekly_v3_assert_uuid(v_slot->'id','registered roster slot id');
    perform public.static_weekly_v3_assert_text(v_slot->'label','registered roster slot label',200);
    v_incumbencies:=v_slot->'incumbencies';
    if jsonb_typeof(v_incumbencies) is distinct from 'array' or jsonb_array_length(v_incumbencies)=0 or jsonb_array_length(v_incumbencies)>64 then
      raise exception using errcode='23514',message='each registered roster slot requires bounded immutable incumbency history';
    end if;
    v_expected_slots:=v_expected_slots+1;
    for v_incumbent in select value from jsonb_array_elements(v_incumbencies) loop
      perform public.static_weekly_v3_assert_uuid(v_incumbent->'personId','registered roster incumbent person id');
      perform public.static_weekly_v3_assert_text(v_incumbent->'displayName','registered roster incumbent name',200);
      perform public.static_weekly_v3_assert_text(v_incumbent->'effectiveStart','registered roster effective start',10);
      if (v_incumbent->>'effectiveStart') !~ '^\d{4}-\d{2}-\d{2}$' then
        raise exception using errcode='23514',message='registered roster effective start must be YYYY-MM-DD';
      end if;
      v_effective_start:=(v_incumbent->>'effectiveStart')::date;
      v_effective_end:=null;
      if nullif(v_incumbent->>'effectiveEnd','') is not null then
        if (v_incumbent->>'effectiveEnd') !~ '^\d{4}-\d{2}-\d{2}$' then
          raise exception using errcode='23514',message='registered roster effective end must be YYYY-MM-DD or null';
        end if;
        v_effective_end:=(v_incumbent->>'effectiveEnd')::date;
        if v_effective_end<=v_effective_start then
          raise exception using errcode='23514',message='registered roster incumbency end must follow its start';
        end if;
      end if;
      v_expected_incumbencies:=v_expected_incumbencies+1;
    end loop;
  end loop;
  if v_expected_slots<>(select count(distinct value->>'id') from jsonb_array_elements(v_slots)) then
    raise exception using errcode='23514',message='registered roster source contains duplicate stable-slot identities';
  end if;

  select count(*) into v_existing_slots from public.weekly_roster_slots;
  select count(*) into v_existing_incumbencies from public.weekly_roster_slot_incumbencies;
  if v_existing_slots<>0 or v_existing_incumbencies<>0 then
    if v_existing_slots<>v_expected_slots or v_existing_incumbencies<>v_expected_incumbencies then
      raise exception using errcode='23514',message='registered roster bootstrap refuses partial or unrelated existing roster state';
    end if;
    for v_slot in select value from jsonb_array_elements(v_slots) loop
      v_slot_id:=(v_slot->>'id')::uuid;
      v_slot_code:='STATIC_'||upper(replace(v_slot_id::text,'-',''));
      if not exists(
        select 1 from public.weekly_roster_slots s
        where s.slot_id=v_slot_id and s.slot_code=v_slot_code and s.slot_label=v_slot->>'label'
      ) then v_mismatch:=true; exit; end if;
      for v_incumbent in select value from jsonb_array_elements(v_slot->'incumbencies') loop
        v_person_id:=(v_incumbent->>'personId')::uuid;
        v_effective_start:=(v_incumbent->>'effectiveStart')::date;
        v_effective_end:=nullif(v_incumbent->>'effectiveEnd','')::date;
        if not exists(
          select 1 from public.weekly_roster_slot_incumbencies i
          where i.slot_id=v_slot_id and i.person_id=v_person_id
            and i.person_name_snapshot=v_incumbent->>'displayName'
            and i.effective_start=v_effective_start
            and i.effective_end is not distinct from v_effective_end
        ) then v_mismatch:=true; exit; end if;
      end loop;
      exit when v_mismatch;
    end loop;
    if v_mismatch then
      raise exception using errcode='23514',message='registered roster bootstrap refuses roster state that differs from the immutable source';
    end if;
    return jsonb_build_object(
      'source_id',p_source_id::text,
      'source_digest',public.static_weekly_digest_jsonb(v_source),
      'slot_count',v_expected_slots,
      'incumbency_count',v_expected_incumbencies,
      'already_initialized',true
    );
  end if;

  for v_slot in select value from jsonb_array_elements(v_slots) loop
    v_slot_id:=(v_slot->>'id')::uuid;
    v_slot_code:='STATIC_'||upper(replace(v_slot_id::text,'-',''));
    insert into public.weekly_roster_slots(
      slot_id,slot_code,slot_label,created_by_manager_id,created_by_manager_name_snapshot,content_digest
    ) values(
      v_slot_id,v_slot_code,v_slot->>'label',p_manager_id,v_actor->>'manager_name',
      public.static_weekly_digest_jsonb(jsonb_build_object(
        'source_id',p_source_id::text,'slot_id',v_slot_id::text,'slot_code',v_slot_code,'slot_label',v_slot->>'label'
      ))
    );
    for v_incumbent in select value from jsonb_array_elements(v_slot->'incumbencies') loop
      v_person_id:=(v_incumbent->>'personId')::uuid;
      v_effective_start:=(v_incumbent->>'effectiveStart')::date;
      v_effective_end:=nullif(v_incumbent->>'effectiveEnd','')::date;
      insert into public.weekly_roster_slot_incumbencies(
        slot_id,person_id,person_name_snapshot,effective_start,effective_end,
        created_by_manager_id,created_by_manager_name_snapshot,content_digest
      ) values(
        v_slot_id,v_person_id,v_incumbent->>'displayName',v_effective_start,v_effective_end,
        p_manager_id,v_actor->>'manager_name',
        public.static_weekly_digest_jsonb(jsonb_build_object(
          'source_id',p_source_id::text,'slot_id',v_slot_id::text,'person_id',v_person_id::text,
          'person_name_snapshot',v_incumbent->>'displayName','effective_start',v_effective_start::text,
          'effective_end',case when v_effective_end is null then null else to_jsonb(v_effective_end::text) end
        ))
      );
    end loop;
  end loop;

  return jsonb_build_object(
    'source_id',p_source_id::text,
    'source_digest',public.static_weekly_digest_jsonb(v_source),
    'slot_count',v_expected_slots,
    'incumbency_count',v_expected_incumbencies,
    'already_initialized',false,
    'configured_by',left(p_configured_by,200),
    'manager_id',p_manager_id::text,
    'manager_name',v_actor->>'manager_name'
  );
end
$function$;

revoke all on function public.static_weekly_v6_initialize_registered_roster(uuid,uuid,text)
from public,anon,authenticated,service_role,static_weekly_control_plane,static_weekly_release_operator;
grant execute on function public.static_weekly_v6_initialize_registered_roster(uuid,uuid,text)
to static_weekly_release_operator;

-- Keep the complete static-weekly document and validation contract while
-- preventing production-sized JSON evidence from being duplicated in a
-- one-GB Postgres process merely to compute or verify its attestation.
begin;

create or replace function public.static_weekly_v6_document_identity(p_document jsonb)
returns text
language sql
stable
security definer
set search_path=pg_catalog,public
as $function$
  select public.static_weekly_digest_jsonb(jsonb_build_object(
    'schema','memphis-zoo.static-weekly-document-merkle-identity.v1',
    'adapter_digest',public.static_weekly_digest_jsonb(p_document->'adapter'),
    'authority_digest',public.static_weekly_digest_jsonb(p_document->'authority'),
    'receipt_digest',public.static_weekly_digest_jsonb(p_document->'receipt'),
    'slot_availability_digest',public.static_weekly_digest_jsonb(p_document->'slot_availability'),
    'assignments_digest',public.static_weekly_digest_jsonb(p_document->'assignments'),
    'objective_inputs_digest',public.static_weekly_digest_jsonb(p_document->'objective_inputs'),
    'semantic_snapshot_digest',public.static_weekly_digest_jsonb(p_document->'semantic_snapshot')
  ))
$function$;

create or replace function public.static_weekly_v6_issue_document_attestation(p_document jsonb)
returns jsonb
language plpgsql
security definer
set search_path=pg_catalog,public
as $function$
declare
  v_key public.static_weekly_authority_attestation_keys%rowtype;
  v_digest text:=public.static_weekly_v6_document_identity(p_document);
begin
  select * into v_key
  from public.static_weekly_authority_attestation_keys
  where key_state='active' and activates_at<=statement_timestamp()
    and (verify_not_after is null or verify_not_after>statement_timestamp())
  for share;
  if not found then
    raise exception using errcode='42501',message='static weekly authority has no active signing key';
  end if;
  return jsonb_build_object(
    'schema','memphis-zoo.static-weekly-authority-attestation.v3',
    'key_id',v_key.key_id,
    'scope','recurring_document',
    'payload_digest',v_digest,
    'signature',public.static_weekly_v3_hmac(v_key.secret_material,'recurring_document',jsonb_build_object('payload_digest',v_digest))
  );
end
$function$;

create or replace function public.static_weekly_v6_assert_document_attestation(p_document jsonb)
returns void
language plpgsql
security definer
set search_path=pg_catalog,public
as $function$
declare
  v_attestation jsonb:=p_document->'attestation';
  v_key public.static_weekly_authority_attestation_keys%rowtype;
  v_digest text:=public.static_weekly_v6_document_identity(p_document);
  v_expected text;
begin
  perform public.static_weekly_assert_exact_object(v_attestation,
    array['schema','key_id','scope','payload_digest','signature'],
    array['schema','key_id','scope','payload_digest','signature'],'authority attestation');
  if v_attestation->>'schema' is distinct from 'memphis-zoo.static-weekly-authority-attestation.v3'
    or v_attestation->>'scope' is distinct from 'recurring_document'
    or v_attestation->>'payload_digest' is distinct from v_digest
    or v_digest is distinct from p_document#>>'{validation,database_document_identity}'
    or jsonb_typeof(v_attestation->'key_id') is distinct from 'string'
    or jsonb_typeof(v_attestation->'signature') is distinct from 'string'
    or coalesce(v_attestation->>'signature','') !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='23514',message='complete memory-bounded document attestation is required';
  end if;
  select * into v_key
  from public.static_weekly_authority_attestation_keys
  where key_id=v_attestation->>'key_id' and key_state in ('active','overlap')
    and activates_at<=statement_timestamp()
    and (verify_not_after is null or verify_not_after>statement_timestamp())
  for share;
  if not found then
    raise exception using errcode='23514',message='authority attestation key is unknown, expired, or revoked';
  end if;
  v_expected:=public.static_weekly_v3_hmac(v_key.secret_material,'recurring_document',jsonb_build_object('payload_digest',v_digest));
  if not public.static_weekly_v3_constant_time_equal(decode(v_attestation->>'signature','hex'),decode(v_expected,'hex')) then
    raise exception using errcode='23514',message='document attestation does not bind the complete Merkle identity';
  end if;
end
$function$;

create or replace function public.static_weekly_assert_document_attested(p_document jsonb,p_effective_start date,p_require_publishable boolean)
returns void
language plpgsql
security definer
set search_path=pg_catalog,public
as $function$
declare
  v_legacy jsonb;
begin
  perform public.static_weekly_assert_exact_object(p_document,
    array['adapter','authority','receipt','slot_availability','assignments','objective_inputs','validation','semantic_snapshot','attestation'],
    array['adapter','authority','receipt','slot_availability','assignments','objective_inputs','validation','semantic_snapshot','attestation'],'attested adapter document');
  perform public.static_weekly_v6_assert_document_attestation(p_document);
  perform public.static_weekly_assert_exact_object(p_document->'semantic_snapshot',
    array['schema','recurring_source_digest','relational_slot_availability_digest','relational_assignments_digest'],
    array['schema','recurring_source_digest','relational_slot_availability_digest','relational_assignments_digest'],'recurring semantic snapshot');
  if p_document#>>'{semantic_snapshot,schema}' is distinct from 'memphis-zoo.static-weekly-recurring-semantic-snapshot.v2'
    or p_document#>>'{semantic_snapshot,recurring_source_digest}' is distinct from public.static_weekly_digest_jsonb(p_document#>'{authority,compilerInput}')
    or p_document#>>'{semantic_snapshot,relational_slot_availability_digest}' is distinct from public.static_weekly_digest_jsonb(p_document->'slot_availability')
    or p_document#>>'{semantic_snapshot,relational_assignments_digest}' is distinct from public.static_weekly_digest_jsonb(p_document->'assignments') then
    raise exception using errcode='23514',message='attested recurring semantic snapshot and relational materialization must be exact';
  end if;
  v_legacy:=p_document-'semantic_snapshot'-'attestation';
  v_legacy:=jsonb_set(v_legacy,'{validation,database_document_identity}',to_jsonb(public.static_weekly_document_identity(v_legacy)),true);
  perform public.static_weekly_assert_document(v_legacy,p_effective_start,p_require_publishable);
end
$function$;

create or replace function public.static_weekly_v3_create_draft(p_effective_start date,p_objective_version text,p_objective jsonb,p_input_provenance jsonb,p_document jsonb,p_expected_revision bigint,p_manager_id uuid,p_idempotency_key text,p_source_id uuid)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $function$
declare v_actor jsonb; v_document jsonb; v_response jsonb; v_version uuid; v_source uuid;
begin
  perform public.static_weekly_v3_assert_control_plane(); v_actor:=public.static_weekly_v3_manager_actor(p_manager_id); perform public.static_weekly_v3_assert_registered_source(p_source_id,p_document#>'{authority,compilerInput}');
  perform public.static_weekly_assert_compiler_authority(p_document->'authority',p_document->'receipt',p_effective_start,true);
  v_document:=jsonb_set(p_document,'{attestation}',public.static_weekly_v6_issue_document_attestation(p_document),true);
  v_response:=public.static_weekly_v2_create_draft(p_effective_start,p_objective_version,p_objective,p_input_provenance,v_document,p_expected_revision,p_manager_id,v_actor->>'manager_name',p_idempotency_key);
  v_version:=(v_response#>>'{data,version_id}')::uuid; perform set_config('app.static_weekly_source_bind','on',true); update public.weekly_schedule_versions set authority_source_id=p_source_id where version_id=v_version and authority_source_id is null;
  select authority_source_id into v_source from public.weekly_schedule_versions where version_id=v_version for share;
  if v_source is distinct from p_source_id then raise exception using errcode='23514',message='draft did not retain one immutable authority source identity'; end if;
  return v_response;
end
$function$;

create or replace function public.static_weekly_v3_update_draft(p_version_id uuid,p_document jsonb,p_objective jsonb,p_input_provenance jsonb,p_expected_draft_revision bigint,p_expected_revision bigint,p_manager_id uuid,p_idempotency_key text)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $function$
declare v_actor jsonb; v_document jsonb; v_source uuid;
begin
  perform public.static_weekly_v3_assert_control_plane(); v_actor:=public.static_weekly_v3_manager_actor(p_manager_id); select authority_source_id into v_source from public.weekly_schedule_versions where version_id=p_version_id and lifecycle_state='draft' for share; perform public.static_weekly_v3_assert_registered_source(v_source,p_document#>'{authority,compilerInput}');
  perform public.static_weekly_assert_compiler_authority(p_document->'authority',p_document->'receipt',(select effective_start from public.weekly_schedule_versions where version_id=p_version_id),true);
  v_document:=jsonb_set(p_document,'{attestation}',public.static_weekly_v6_issue_document_attestation(p_document),true);
