-- A restore rehearsal must reproduce both the fixed feedback projection and
-- the bounded public-ingest count function introduced immediately before it.
alter table public.custodial_release_authority_restore_inventory
  disable trigger trg_custodial_release_authority_restore_inventory_immutable;

do $capture_feedback_function$
declare
  identity text := to_regprocedure('public.app_get_public_rate_limit_count(text,text)')::text;
  definition text;
  next_order integer;
begin
  definition := pg_get_functiondef(to_regprocedure('public.app_get_public_rate_limit_count(text,text)'));
  if definition is null then
    raise exception 'Bounded feedback rate-count function is unavailable';
  end if;
  if exists (
    select 1 from public.custodial_release_authority_restore_inventory
    where object_kind = 'function' and object_identity = identity
  ) then
    update public.custodial_release_authority_restore_inventory
    set definition_sql = definition,
        definition_sha256 = encode(extensions.digest(convert_to(definition,'UTF8'),'sha256'),'hex'),
        captured_at = statement_timestamp()
    where object_kind = 'function' and object_identity = identity;
  else
    select coalesce(max(restore_order),100000) + 1 into next_order
    from public.custodial_release_authority_restore_inventory
    where object_kind = 'function';
    insert into public.custodial_release_authority_restore_inventory(
      restore_order, object_kind, object_identity, definition_sql, definition_sha256
    ) values (
      next_order, 'function', identity, definition,
      encode(extensions.digest(convert_to(definition,'UTF8'),'sha256'),'hex')
    );
  end if;
end
$capture_feedback_function$;

do $capture_feedback_grants$
declare
  identity text;
  definition text;
  next_order integer;
begin
  foreach identity in array array[
    'public.system_feedback_items',
    'public.app_get_public_rate_limit_count(text,text)'
  ] loop
    definition := public.custodial_release_authority_current_grant_definition(identity);
    if definition is null then
      raise exception 'Feedback grant definition % is unavailable', identity;
    end if;
    if exists (
      select 1 from public.custodial_release_authority_restore_inventory
      where object_kind = 'grant' and object_identity = identity
    ) then
      update public.custodial_release_authority_restore_inventory
      set definition_sql = definition,
          definition_sha256 = encode(extensions.digest(convert_to(definition,'UTF8'),'sha256'),'hex'),
          captured_at = statement_timestamp()
      where object_kind = 'grant' and object_identity = identity;
    else
      select coalesce(max(restore_order),1000000) + 1 into next_order
      from public.custodial_release_authority_restore_inventory
      where object_kind = 'grant';
      insert into public.custodial_release_authority_restore_inventory(
        restore_order, object_kind, object_identity, definition_sql, definition_sha256
      ) values (
        next_order, 'grant', identity, definition,
        encode(extensions.digest(convert_to(definition,'UTF8'),'sha256'),'hex')
      );
    end if;
  end loop;
end
$capture_feedback_grants$;

do $capture_feedback_policy$
declare
  identity text := 'public.system_feedback_items:custodial_application_reader_system_feedback_runtime';
  definition text;
  next_order integer;
begin
  definition := public.custodial_release_authority_current_policy_definition(identity);
  if definition is null then
    raise exception 'Required feedback reader policy is unavailable';
  end if;
  select coalesce(max(restore_order),800000) + 1 into next_order
  from public.custodial_release_authority_restore_inventory
  where object_kind = 'policy';
  insert into public.custodial_release_authority_restore_inventory(
    restore_order, object_kind, object_identity, definition_sql, definition_sha256
  ) values (
    next_order, 'policy', identity, definition,
    encode(extensions.digest(convert_to(definition,'UTF8'),'sha256'),'hex')
  );
end
$capture_feedback_policy$;

alter table public.custodial_release_authority_restore_inventory
  enable trigger trg_custodial_release_authority_restore_inventory_immutable;

do $postflight$
declare
  reader_oid oid;
  admitted_columns text[] := array[
    'acknowledged_at','acknowledged_by','category','created_at','device_id',
    'feedback_reminder_count','hub_context','id','last_feedback_reminder_at',
    'message','metadata_json','notification_status','notified_ops_count',
    'operation_id','page_url','priority','request_fingerprint','status',
    'submitted_by','summary','updated_at'
  ];
begin
  select oid into strict reader_oid
  from pg_roles
  where rolname = 'custodial_application_reader';

  if has_table_privilege('custodial_application_reader','public.system_feedback_items','select')
     or has_table_privilege('custodial_application_reader','public.system_feedback_items','insert')
     or has_table_privilege('custodial_application_reader','public.system_feedback_items','update')
     or has_table_privilege('custodial_application_reader','public.system_feedback_items','delete') then
    raise exception 'Feedback reader retained relation-level or mutation authority';
  end if;

  if (
    select array_agg(a.attname::text order by a.attname::text)
    from pg_attribute a
    cross join lateral aclexplode(a.attacl) acl
    where a.attrelid = 'public.system_feedback_items'::regclass
      and a.attnum > 0
      and not a.attisdropped
      and a.attacl is not null
      and acl.grantee = reader_oid
      and acl.privilege_type = 'SELECT'
      and not acl.is_grantable
  ) is distinct from admitted_columns then
    raise exception 'Feedback reader column projection is not exact';
  end if;

  if (
    select count(*)
    from pg_policy p
    where p.polrelid = 'public.system_feedback_items'::regclass
      and reader_oid = any(p.polroles)
      and p.polname = 'custodial_application_reader_system_feedback_runtime'
      and p.polcmd = 'r'
      and p.polpermissive
      and pg_get_expr(p.polqual,p.polrelid) = 'true'
  ) <> 1 then
    raise exception 'Feedback reader RLS policy is invalid';
  end if;

  if has_table_privilege('custodial_application_reader','public.system_feedback_legacy_image_backups','select')
     or exists (
       select 1
       from pg_attribute a
       cross join lateral aclexplode(a.attacl) acl
       where a.attrelid = 'public.system_feedback_legacy_image_backups'::regclass
         and a.attnum > 0
         and not a.attisdropped
         and a.attacl is not null
         and acl.grantee = reader_oid
     ) then
    raise exception 'Feedback reader can observe private legacy image backups';
  end if;

  if not has_function_privilege(
       'custodial_application_reader',
       'public.app_get_public_rate_limit_count(text,text)',
       'execute'
     )
     or has_function_privilege('public','public.app_get_public_rate_limit_count(text,text)','execute')
     or has_function_privilege('anon','public.app_get_public_rate_limit_count(text,text)','execute')
     or has_function_privilege('authenticated','public.app_get_public_rate_limit_count(text,text)','execute')
     or has_function_privilege('service_role','public.app_get_public_rate_limit_count(text,text)','execute') then
    raise exception 'Bounded feedback rate-count authority is invalid';
  end if;

  if (
    select count(*)
    from public.custodial_release_authority_restore_inventory
    where (object_kind,object_identity) in (
      ('function',to_regprocedure('public.app_get_public_rate_limit_count(text,text)')::text),
      ('grant','public.app_get_public_rate_limit_count(text,text)'),
      ('grant','public.system_feedback_items'),
      ('policy','public.system_feedback_items:custodial_application_reader_system_feedback_runtime')
    )
  ) <> 4 then
    raise exception 'Feedback release-recovery inventory is incomplete';
  end if;

  if exists (
    select 1 from public.custodial_release_authority_restore_inventory
    where definition_sha256 <> encode(extensions.digest(convert_to(definition_sql,'UTF8'),'sha256'),'hex')
  ) then
    raise exception 'Release recovery inventory digest mismatch';
  end if;
end
$postflight$;

commit;

-- Production already owns this Outlook synchronization ledger, but no source
-- migration described it. Independent restore therefore preserved a relation
-- that the clean-source fingerprint could never reproduce. Adopt the exact
-- production shape without rewriting rows or granting a browser principal.

begin;

create table if not exists public.events_app_outlook_sync (
  id uuid default gen_random_uuid() not null,
  outlook_message_id text not null,
  source_event_key text not null,
  event_id uuid,
  received_at timestamptz,
  source_subject text,
  payload_hash text,
  sync_status text default 'APPLIED'::text not null,
  sync_note text,
  source_payload jsonb default '{}'::jsonb not null,
  created_at timestamptz default now() not null,
  updated_at timestamptz default now() not null,
  constraint events_app_outlook_sync_pkey primary key (id),
  constraint events_app_outlook_sync_outlook_message_id_source_event_key_key
    unique (outlook_message_id, source_event_key),
  constraint events_app_outlook_sync_event_id_fkey
    foreign key (event_id) references public.events_app_events(id) on delete set null,
  constraint events_app_outlook_sync_sync_status_check check (
    sync_status = any (array[
      'APPLIED'::text,
      'UNCHANGED'::text,
      'NEEDS_REVIEW'::text,
      'BLOCKED_MANUAL'::text,
      'CANCELLED'::text,
      'ERROR'::text
    ])
  )
);

create index if not exists idx_events_app_outlook_sync_event
  on public.events_app_outlook_sync using btree (event_id, updated_at desc);
create index if not exists idx_events_app_outlook_sync_received
  on public.events_app_outlook_sync using btree (received_at desc);

alter table public.events_app_outlook_sync enable row level security;
alter table public.events_app_outlook_sync no force row level security;

revoke all privileges on table public.events_app_outlook_sync
  from public, anon, authenticated, service_role, custodial_application_reader,
       postgres, supabase_admin;
grant delete, insert, maintain, references, select, trigger, truncate, update
  on table public.events_app_outlook_sync to service_role;

comment on table public.events_app_outlook_sync is
  'Idempotency and audit ledger for ChatGPT Outlook-to-events synchronization. No mailbox credentials are stored.';

do $postflight$
declare
  expected_columns text[] := array[
    'id:uuid:true:gen_random_uuid()',
    'outlook_message_id:text:true:',
    'source_event_key:text:true:',
    'event_id:uuid:false:',
    'received_at:timestamp with time zone:false:',
    'source_subject:text:false:',
    'payload_hash:text:false:',
    'sync_status:text:true:''APPLIED''::text',
    'sync_note:text:false:',
    'source_payload:jsonb:true:''{}''::jsonb',
    'created_at:timestamp with time zone:true:now()',
    'updated_at:timestamp with time zone:true:now()'
  ];
  actual_columns text[];
  unexpected_acl integer;
begin
  select array_agg(
    a.attname::text || ':' || format_type(a.atttypid,a.atttypmod) || ':' ||
    a.attnotnull::text || ':' || coalesce(pg_get_expr(ad.adbin,ad.adrelid),'')
    order by a.attnum
  ) into actual_columns
  from pg_attribute a
  left join pg_attrdef ad on ad.adrelid=a.attrelid and ad.adnum=a.attnum
  where a.attrelid='public.events_app_outlook_sync'::regclass
    and a.attnum>0
    and not a.attisdropped;

  if actual_columns is distinct from expected_columns then
    raise exception 'Existing Outlook synchronization columns do not equal the admitted production shape';
  end if;

  if (
    select count(*)
    from pg_constraint
    where conrelid='public.events_app_outlook_sync'::regclass
      and (conname,contype,pg_get_constraintdef(oid,true)) in (
        ('events_app_outlook_sync_pkey','p','PRIMARY KEY (id)'),
        ('events_app_outlook_sync_outlook_message_id_source_event_key_key','u','UNIQUE (outlook_message_id, source_event_key)'),
        ('events_app_outlook_sync_event_id_fkey','f','FOREIGN KEY (event_id) REFERENCES events_app_events(id) ON DELETE SET NULL'),
        ('events_app_outlook_sync_sync_status_check','c','CHECK (sync_status = ANY (ARRAY[''APPLIED''::text, ''UNCHANGED''::text, ''NEEDS_REVIEW''::text, ''BLOCKED_MANUAL''::text, ''CANCELLED''::text, ''ERROR''::text]))')
      )
  ) <> 4
     or (
       select count(*) from pg_constraint
       where conrelid='public.events_app_outlook_sync'::regclass
     ) <> 4 then
    raise exception 'Existing Outlook synchronization constraints do not equal the admitted production shape';
  end if;

  if (
    select count(*)
    from pg_index ix
    join pg_class i on i.oid=ix.indexrelid
    where ix.indrelid='public.events_app_outlook_sync'::regclass
      and i.relname in (
        'events_app_outlook_sync_pkey',
        'events_app_outlook_sync_outlook_message_id_source_event_key_key',
        'idx_events_app_outlook_sync_event',
        'idx_events_app_outlook_sync_received'
      )
  ) <> 4
     or (
       select count(*) from pg_index
       where indrelid='public.events_app_outlook_sync'::regclass
     ) <> 4 then
    raise exception 'Existing Outlook synchronization indexes do not equal the admitted production shape';
  end if;

  if not exists (
    select 1 from pg_class
    where oid='public.events_app_outlook_sync'::regclass
      and relrowsecurity
      and not relforcerowsecurity
  )
     or exists (
       select 1 from pg_policy
       where polrelid='public.events_app_outlook_sync'::regclass
     ) then
    raise exception 'Outlook synchronization RLS state does not equal the admitted fail-closed shape';
  end if;

  select count(*) into unexpected_acl
  from pg_class c
  cross join lateral aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) acl
  left join pg_roles grantee on grantee.oid=acl.grantee
  where c.oid='public.events_app_outlook_sync'::regclass
    and acl.grantee<>c.relowner
    and not (
      grantee.rolname='service_role'
      and not acl.is_grantable
      and acl.privilege_type in (
        'DELETE','INSERT','MAINTAIN','REFERENCES','SELECT','TRIGGER','TRUNCATE','UPDATE'
      )
    );
  if unexpected_acl<>0 or not has_table_privilege('service_role','public.events_app_outlook_sync','select') then
    raise exception 'Outlook synchronization grants do not equal the admitted service-only shape';
  end if;

  if obj_description('public.events_app_outlook_sync'::regclass,'pg_class') is distinct from
     'Idempotency and audit ledger for ChatGPT Outlook-to-events synchronization. No mailbox credentials are stored.' then
    raise exception 'Outlook synchronization authority comment is missing';
  end if;
end
$postflight$;

commit;

-- The feedback runtime intentionally adds a second bounded column projection
-- for custodial_application_reader. Release health must verify the three-table
-- employee/device identity projection without treating that later, separately
-- inventoried feedback projection as identity-authority drift.

begin;

do $preflight$
declare
  health_definition text;
  old_filter text := E'      where n.nspname=''public'' and a.attnum>0 and not a.attisdropped and a.attacl is not null\n        and acl.grantee<>c.relowner';
  old_filter_count integer;
  identity_projection_exact boolean;
  feedback_projection_exact boolean;
begin
  if to_regprocedure('public.custodial_backend_authority_health(text)') is null
     or to_regclass('public.custodial_release_authority_restore_inventory') is null then
    raise exception 'Release health and recovery inventory are required';
  end if;

  health_definition := pg_get_functiondef('public.custodial_backend_authority_health(text)'::regprocedure);
  if encode(extensions.digest(convert_to(health_definition,'UTF8'),'sha256'),'hex')
       <> 'bb04f7c05f72d959b4aba5a3a047adad1163eaf6b88aeeebd5d0f9f6a3b10baf' then
    raise exception 'Release health definition does not match the admitted predecessor';
  end if;
  old_filter_count := (length(health_definition)-length(replace(health_definition,old_filter,'')))/length(old_filter);
  if old_filter_count <> 1 then
    raise exception 'The obsolete global column-authority filter is not uniquely identifiable';
  end if;

  select count(*)=22
    and bool_and(grantee.rolname='custodial_application_reader'
      and acl.privilege_type='SELECT' and not acl.is_grantable)
    and bool_and((c.relname,a.attname) in (
      ('devices','id'),('devices','device_id'),('devices','device_name'),('devices','active'),
      ('devices','assigned_employee_id'),('devices','last_seen_at'),('devices','created_at'),
      ('devices','updated_at'),('devices','assignment_epoch'),('employees','id'),
      ('employees','employee_code'),('employees','display_name'),('employees','active'),
      ('employees','role'),('employees','created_at'),('employees','updated_at'),
      ('device_aliases','alias_identifier'),('device_aliases','canonical_device_id'),
      ('device_aliases','active'),('device_aliases','source'),('device_aliases','created_at'),
      ('device_aliases','updated_at')
    ))
  into identity_projection_exact
  from pg_attribute a
  join pg_class c on c.oid=a.attrelid
  join pg_namespace n on n.oid=c.relnamespace
  cross join lateral aclexplode(a.attacl) acl
  left join pg_roles grantee on grantee.oid=acl.grantee
  where n.nspname='public'
    and c.relname in ('devices','employees','device_aliases')
    and a.attnum>0 and not a.attisdropped and a.attacl is not null
    and acl.grantee<>c.relowner;

  select count(*)=21
    and bool_and(grantee.rolname='custodial_application_reader'
      and acl.privilege_type='SELECT' and not acl.is_grantable)
  into feedback_projection_exact
  from pg_attribute a
  join pg_class c on c.oid=a.attrelid
  join pg_namespace n on n.oid=c.relnamespace
  cross join lateral aclexplode(a.attacl) acl
  left join pg_roles grantee on grantee.oid=acl.grantee
  where n.nspname='public' and c.relname='system_feedback_items'
    and a.attnum>0 and not a.attisdropped and a.attacl is not null
    and acl.grantee<>c.relowner;

  if identity_projection_exact is not true or feedback_projection_exact is not true then
    raise exception 'The admitted identity and feedback projections are not exact';
  end if;
end
$preflight$;

do $repair$
declare
  health_definition text;
  old_filter text := E'      where n.nspname=''public'' and a.attnum>0 and not a.attisdropped and a.attacl is not null\n        and acl.grantee<>c.relowner';
  scoped_filter text := E'      where n.nspname=''public'' and a.attnum>0 and not a.attisdropped and a.attacl is not null\n        and acl.grantee<>c.relowner\n        and c.relname in (''devices'',''employees'',''device_aliases'')';
begin
  health_definition := pg_get_functiondef('public.custodial_backend_authority_health(text)'::regprocedure);
  execute replace(health_definition,old_filter,scoped_filter);
end
$repair$;

alter table public.custodial_release_authority_restore_inventory
  disable trigger trg_custodial_release_authority_restore_inventory_immutable;

do $refresh_inventory$
declare
  changed integer;
  definition text := pg_get_functiondef('public.custodial_backend_authority_health(text)'::regprocedure);
begin
  update public.custodial_release_authority_restore_inventory
  set definition_sql=definition,
      definition_sha256=encode(extensions.digest(convert_to(definition,'UTF8'),'sha256'),'hex'),
      captured_at=statement_timestamp()
  where object_kind='function'
    and object_identity in (
      'custodial_backend_authority_health(text)',
      'public.custodial_backend_authority_health(text)'
    );
  get diagnostics changed=row_count;
  if changed <> 1 then
    raise exception 'Release health recovery inventory row is missing or duplicated';
  end if;
end
$refresh_inventory$;

alter table public.custodial_release_authority_restore_inventory
  enable trigger trg_custodial_release_authority_restore_inventory_immutable;

do $postflight$
declare
  health_definition text := pg_get_functiondef('public.custodial_backend_authority_health(text)'::regprocedure);
  inventory_definition text;
  inventory_digest text;
  identity_projection_exact boolean;
begin
  select definition_sql,definition_sha256
  into strict inventory_definition,inventory_digest
  from public.custodial_release_authority_restore_inventory
  where object_kind='function'
    and object_identity in (
      'custodial_backend_authority_health(text)',
      'public.custodial_backend_authority_health(text)'
    );

  if health_definition is distinct from inventory_definition
     or inventory_digest is distinct from encode(extensions.digest(convert_to(health_definition,'UTF8'),'sha256'),'hex')
     or health_definition not like '%and c.relname in (''devices'',''employees'',''device_aliases'')%' then
    raise exception 'Corrected release health is not exactly recoverable';
  end if;

  select count(*)=22
    and bool_and(grantee.rolname='custodial_application_reader'
      and acl.privilege_type='SELECT' and not acl.is_grantable)
    and bool_and((c.relname,a.attname) in (
      ('devices','id'),('devices','device_id'),('devices','device_name'),('devices','active'),
      ('devices','assigned_employee_id'),('devices','last_seen_at'),('devices','created_at'),
      ('devices','updated_at'),('devices','assignment_epoch'),('employees','id'),
      ('employees','employee_code'),('employees','display_name'),('employees','active'),
      ('employees','role'),('employees','created_at'),('employees','updated_at'),
      ('device_aliases','alias_identifier'),('device_aliases','canonical_device_id'),
      ('device_aliases','active'),('device_aliases','source'),('device_aliases','created_at'),
      ('device_aliases','updated_at')
    ))
  into identity_projection_exact
  from pg_attribute a
  join pg_class c on c.oid=a.attrelid
  join pg_namespace n on n.oid=c.relnamespace
  cross join lateral aclexplode(a.attacl) acl
  left join pg_roles grantee on grantee.oid=acl.grantee
  where n.nspname='public'
    and c.relname in ('devices','employees','device_aliases')
    and a.attnum>0 and not a.attisdropped and a.attacl is not null
    and acl.grantee<>c.relowner;

  if identity_projection_exact is not true then
    raise exception 'Corrected release health identity projection is not exact';
  end if;

  if exists (
    select 1 from public.custodial_release_authority_restore_inventory
    where definition_sha256<>encode(extensions.digest(convert_to(definition_sql,'UTF8'),'sha256'),'hex')
  ) then
    raise exception 'Release recovery inventory digest mismatch';
  end if;
end
$postflight$;

commit;

alter table public.weekly_roster_slot_staffing_states disable trigger user;
alter table public.weekly_roster_slot_incumbencies disable trigger user;
alter table public.weekly_roster_slots disable trigger user;

do $$
declare
  v_manager_id uuid := '00000000-0000-4000-8000-000000000001'::uuid;
  v_manager_name text;
  v_slot_id uuid;
  v_employee_id uuid;
  v_incumbency_id uuid;
  v_staffing_state_id uuid;
  v_expected_revision bigint := 16;
  v_revision bigint;
  v_command_id uuid := gen_random_uuid();
  v_reason text := 'Pre-employment clearance was not approved; the future hire was canceled before the effective schedule date.';
  v_idempotency_key text := 'cancel-gregory-staples-prestart-20260827';
  v_request jsonb;
  v_request_digest text;
  v_content_digest text;
  v_status jsonb;
  v_response jsonb;
  v_count integer;
begin
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));

  select display_name into v_manager_name
  from public.ops_manager_managers
  where manager_id=v_manager_id and active is true and revoked_at is null;
  if v_manager_name is null then raise exception 'Active manager authority was not found.'; end if;

  if exists (
    select 1 from public.weekly_schedule_command_receipts
    where actor_manager_id=v_manager_id and idempotency_key=v_idempotency_key
  ) then return; end if;

  select id into v_employee_id
  from public.employees
  where employee_code='EMP011' and display_name='Gregory Staples' and role='staff' and active is true;
  if v_employee_id is null then raise exception 'The expected active Gregory Staples employee record was not found.'; end if;

  select slot_id into v_slot_id
  from public.weekly_roster_slots
  where slot_code='STATIC_5D2D2A0E230F5B0398672E4C2826871F';
  if v_slot_id is null then raise exception 'The Option 3 stable schedule position was not found.'; end if;

  select incumbency_id into v_incumbency_id
  from public.weekly_roster_slot_incumbencies
  where slot_id=v_slot_id and person_id=v_employee_id
    and effective_start='2026-08-31'::date and effective_end is null;
  if v_incumbency_id is null then raise exception 'The expected future Gregory incumbency was not found.'; end if;

  select staffing_state_id into v_staffing_state_id
  from public.weekly_roster_slot_staffing_states
  where slot_id=v_slot_id and employee_id=v_employee_id
    and effective_start='2026-08-31'::date and staffing_state='working';
  if v_staffing_state_id is null then raise exception 'The expected future Gregory staffing state was not found.'; end if;

  if (select current_revision from public.static_weekly_schedule_control where singleton) <> v_expected_revision then
    raise exception 'Schedule authority changed before Gregory cancellation.';
  end if;
  if public.sch_service_date(statement_timestamp()) >= '2026-08-31'::date then
    raise exception 'The record is no longer a future pre-effective hire and requires normal turnover handling.';
  end if;
  if exists (select 1 from public.devices where active is true and assigned_employee_id=v_employee_id) then
    raise exception 'Gregory Staples unexpectedly has an assigned active device.';
  end if;

  v_request := jsonb_build_object(
    'operation','mark_employee_departed',
    'correction_type','cancel_future_hire_before_effective_start',
    'slot_id',v_slot_id,
    'former_employee_id',v_employee_id,
    'former_employee_name','Gregory Staples',
    'effective_start','2026-08-31',
    'new_slot_label','Option 3 schedule position',
    'reason',v_reason,
    'expected_revision',v_expected_revision,
    'actor_manager_id',v_manager_id
  );
  v_request_digest := public.static_weekly_digest_jsonb(v_request);
  v_content_digest := public.static_weekly_digest_jsonb(v_request-'expected_revision'-'actor_manager_id'-'operation');

  delete from public.weekly_roster_slot_staffing_states where staffing_state_id=v_staffing_state_id;
  get diagnostics v_count = row_count;
  if v_count <> 1 then raise exception 'Expected one future Gregory staffing-state row; removed %.',v_count; end if;

  delete from public.weekly_roster_slot_incumbencies where incumbency_id=v_incumbency_id;
  get diagnostics v_count = row_count;
  if v_count <> 1 then raise exception 'Expected one future Gregory incumbency row; removed %.',v_count; end if;

  update public.weekly_roster_slots
  set slot_label='Option 3 schedule position',content_digest=v_content_digest
  where slot_id=v_slot_id and slot_label='Gregory Staples schedule position';
  get diagnostics v_count = row_count;
  if v_count <> 1 then raise exception 'Expected one Gregory-labeled stable slot; renamed %.',v_count; end if;

  v_status := public.custodial_set_employee_active(v_employee_id,false,v_manager_id,v_reason,true);

  update public.static_weekly_schedule_control
  set current_revision=current_revision+1,
      updated_at=statement_timestamp(),
      updated_by_manager_id=v_manager_id,
      updated_by_manager_name_snapshot=v_manager_name
  where singleton and current_revision=v_expected_revision
  returning current_revision into v_revision;
  if v_revision is null then raise exception 'Stale expected schedule revision.'; end if;

  insert into public.weekly_schedule_authority_revisions(
    authority_revision,command_id,operation,actor_manager_id,
    actor_manager_name_snapshot,content_digest
  ) values (
    v_revision,v_command_id,'mark_employee_departed',v_manager_id,
    v_manager_name,v_content_digest
  );

  v_response := public.static_weekly_response_json(
    'mark_employee_departed',v_revision,v_content_digest,v_request_digest,
    jsonb_build_object(
      'slot_id',v_slot_id,
      'slot_label','Option 3 schedule position',
      'former_employee_id',v_employee_id,
      'former_employee_name','Gregory Staples',
      'effective_start','2026-08-31',
      'cancelled_before_effective_start',true,
      'vacant',true,
      'option_number',3,
      'work_days',jsonb_build_array('Saturday','Sunday','Monday','Tuesday','Wednesday'),
      'shift_start','08:00',
      'shift_end','17:00',
      'days_off',jsonb_build_array('Thursday','Friday'),
      'employee_status',v_status
    )
  );

  insert into public.weekly_schedule_command_receipts(
    command_id,actor_manager_id,actor_manager_name_snapshot,command_type,
    idempotency_key,expected_revision,request_digest,request_canonical_json,
    response_json,response_digest,content_digest
  ) values (
    v_command_id,v_manager_id,v_manager_name,'mark_employee_departed',
    v_idempotency_key,v_expected_revision,v_request_digest,v_request,
    v_response,v_response->>'output_digest',v_content_digest
  );
end
