  check (authority_radius_m is null or authority_radius_m between 25 and 5000);

create or replace function public.evaluate_location_proximity_v2(
  p_location_code text,
  p_device_identifier text,
  p_latitude numeric,
  p_longitude numeric,
  p_accuracy_m numeric default null,
  p_session_uuid text default null,
  p_client_event_id text default null,
  p_correlation_id text default null,
  p_observed_at timestamptz default null
) returns jsonb
language plpgsql
security definer
set search_path to 'pg_catalog','public','extensions'
as $function$
declare
  v_session_key text:=nullif(btrim(coalesce(p_session_uuid,'')),'');
  v_session_state text;
  v_result jsonb;
  v_location_code text;
  v_target_lat numeric;
  v_target_lon numeric;
  v_radius numeric;
  v_surveyed_at timestamptz;
  v_confidence text;
  v_source text;
  v_distance numeric;
  v_uncertainty numeric;
  v_result_code text;
  v_authoritative boolean:=false;
  v_scope text:='advisory_uncalibrated';
  v_event_id uuid;
  v_event_count integer;
begin
  if v_session_key is not null then
    v_session_state:=public.custodial_gps_session_state(p_location_code,p_device_identifier,v_session_key);
    if v_session_state is null then
      raise exception using errcode='23503', message='Session does not belong to this device and location';
    end if;
  end if;

  v_location_code:=public.resolve_scan_location_code(p_location_code);
  if v_location_code is null then
    raise exception using errcode='23503', message='Active scanned location was not found';
  end if;
  -- The measurement core historically substitutes clock_timestamp() for NULL.
  -- Settle an old queued reading as unavailable without a status/event write;
  -- an arrival time is not a phone capture time. This keeps saved cleaning
  -- actions moving and does not reject or defer a cleaning submission.
  if p_observed_at is null then
    return jsonb_build_object('ok',true,'result','gps_timestamp_unavailable',
      'authoritative',false,'authority_scope','advisory_missing_capture_time',
      'scan_event_id',null);
  end if;
  select lp.latitude,lp.longitude,lp.authority_radius_m,lp.authority_surveyed_at,
         lp.coordinate_confidence,lp.coordinate_source
    into v_target_lat,v_target_lon,v_radius,v_surveyed_at,v_confidence,v_source
  from public.locations l
  join public.location_proximity_settings lp on lp.location_id=l.id
  where l.active=true and l.location_code=v_location_code and lp.active=true
    and lp.latitude is not null and lp.longitude is not null
  order by lp.updated_at desc
  limit 1
  for share of lp;

  v_result:=public.custodial_evaluate_location_proximity_v2_measurement(
    p_location_code,p_device_identifier,p_latitude,p_longitude,p_accuracy_m,
    p_session_uuid,p_client_event_id,p_correlation_id,p_observed_at
  );

  v_result_code:=coalesce(v_result->>'result','gps_unavailable');
  if v_target_lat is not null and v_target_lon is not null
     and v_radius is not null and v_surveyed_at is not null and v_surveyed_at<=clock_timestamp()
     and lower(btrim(coalesce(v_confidence,'')))='surveyed'
     and nullif(btrim(coalesce(v_source,'')),'') is not null then
    v_scope:='surveyed_location_radius';
    -- The core has already checked observation age, accuracy and motion. Its
    -- global-radius near/away/boundary result is replaced using the surveyed
    -- exact location and radius; terminal session handling remains below.
    if v_result_code in ('near','away','boundary_uncertain') then
      v_distance:=6371000 * 2 * asin(sqrt(
        power(sin(radians((p_latitude-v_target_lat)::double precision)/2),2)
        + cos(radians(v_target_lat::double precision))*cos(radians(p_latitude::double precision))
        * power(sin(radians((p_longitude-v_target_lon)::double precision)/2),2)
      ));
      v_uncertainty:=greatest(
        greatest(5,public.get_setting_int('gps_boundary_hysteresis_m',15)),
        least(greatest(coalesce(p_accuracy_m,0),0),greatest(25,public.get_setting_int('gps_max_accuracy_m',100)))
      );
      if abs(v_distance-v_radius)<=v_uncertainty then
        v_result_code:='boundary_uncertain';
      elsif v_distance<v_radius then
        v_result_code:='near';
        v_authoritative:=true;
      else
        v_result_code:='away';
        v_authoritative:=true;
      end if;
    end if;
  elsif v_result_code in ('near','away','boundary_uncertain') then
    v_result_code:='location_uncalibrated';
  end if;

  if v_session_state is not null and v_session_state not in ('active','pending_submit') then
    v_result_code:='post_session';
    v_authoritative:=false;
    v_scope:='post_session_advisory';
  end if;

  v_event_id:=nullif(v_result->>'scan_event_id','')::uuid;
  -- A repeated client event ID may refer to an earlier, different reading.
  -- Never rewrite that evidence or return a new authoritative claim for it.
  update public.scan_events se
     set result=v_result_code,
         notes=case
           when v_result_code='near' then 'Phone is within the surveyed scanned-location radius.'
           when v_result_code='away' then 'Phone is outside the surveyed scanned-location radius.'
           when v_result_code='location_uncalibrated' then 'GPS estimate is advisory; the scanned location has no surveyed coordinate and radius.'
           when v_result_code='post_session' then 'GPS arrived after the cleaning was no longer active; advisory evidence only.'
           else se.notes end,
         payload_json=coalesce(se.payload_json,'{}'::jsonb) || jsonb_build_object(
           'authoritative',v_authoritative,'authority_scope',v_scope,
           'evidence_scope',case when v_scope='post_session_advisory' then 'post_session_advisory' else 'active_work_advisory' end,
           'session_state',v_session_state,
           'allowed_radius_m',case when v_scope='surveyed_location_radius' then v_radius else null end,
           'coordinate_source',case when v_scope='surveyed_location_radius' then v_source else se.payload_json->>'coordinate_source' end,
           'surveyed_at',v_surveyed_at
         )
  where se.id=v_event_id
    and se.event_type='work_position_check'
    and se.location_code=v_result->>'location_code'
    and se.device_identifier=v_result->>'device_id'
    and se.session_id is not distinct from (
      select s.id from public.sessions s where s.session_uuid=v_result->>'session_uuid' limit 1
    )
    and (se.payload_json->>'observed_at')::timestamptz=p_observed_at
    and se.payload_json->>'correlation_id' is not distinct from p_correlation_id
    and (se.payload_json->>'client_latitude')::numeric is not distinct from p_latitude
    and (se.payload_json->>'client_longitude')::numeric is not distinct from p_longitude
    and (se.payload_json->>'accuracy_m')::numeric is not distinct from p_accuracy_m;
  get diagnostics v_event_count=row_count;
  if v_event_count<>1 then
    v_result_code:='gps_duplicate_event';
    v_authoritative:=false;
    v_scope:='advisory_duplicate_event';
  end if;

  update public.device_location_proximity_status gps
     set result=v_result_code,
         badge_color=case when v_result_code='near' then 'green' when v_result_code='away' then 'red' else 'amber' end,
         allowed_radius_m=case when v_scope='surveyed_location_radius' then v_radius else gps.allowed_radius_m end,
         metadata_json=coalesce(gps.metadata_json,'{}'::jsonb) || jsonb_build_object(
           'authoritative',v_authoritative,'authority_scope',v_scope,
           'evidence_scope',case when v_scope='post_session_advisory' then 'post_session_advisory' else 'active_work_advisory' end,
           'session_state',v_session_state,
           'surveyed_at',v_surveyed_at
         )
  where gps.device_id=(select d.id from public.devices d where d.device_id=v_result->>'device_id' limit 1)
    and gps.location_id=(select l.id from public.locations l where l.location_code=v_result->>'location_code' limit 1)
    and gps.session_uuid=coalesce(v_result->>'session_uuid','')
    and gps.evaluated_at=(v_result->>'evaluated_at')::timestamptz;

  return v_result || jsonb_build_object(
    'result',v_result_code,
    'authoritative',v_authoritative,
    'authority_scope',v_scope,
    'evidence_scope',case when v_scope='post_session_advisory' then 'post_session_advisory' else 'active_work_advisory' end,
    'session_state',v_session_state,
    'badge_color',case when v_result_code='near' then 'green' when v_result_code='away' then 'red' else 'amber' end,
    'allowed_radius_m',case when v_scope='surveyed_location_radius' then v_radius else null end,
    'surveyed_at',v_surveyed_at
  );
end
$function$;

revoke all on function public.evaluate_location_proximity_v2(text,text,numeric,numeric,numeric,text,text,text,timestamptz)
  from public,anon,authenticated;
grant execute on function public.evaluate_location_proximity_v2(text,text,numeric,numeric,numeric,text,text,text,timestamptz)
  to service_role;

comment on function public.evaluate_location_proximity_v2(text,text,numeric,numeric,numeric,text,text,text,timestamptz) is
  'Advisory GPS evidence unless an exact location has manually surveyed coordinates and bounded radius; null capture time is rejected.';

commit;

-- Forward-only protected-work separation authority. This local candidate
-- keeps native inventory UNKNOWN and phones fenced. It is NOT release-ready
-- until original-principal replay and an audited reconciliation/finalizer are
-- implemented and proven. No historical migration is edited.
begin;
set local lock_timeout='5s';
set local statement_timeout='30s';

create table public.custodial_employee_separation_fences (
  separation_id uuid primary key default gen_random_uuid(),
  command_id uuid not null unique,
  authority_revision bigint not null unique references public.weekly_schedule_authority_revisions(authority_revision) on delete restrict,
  employee_id uuid not null references public.employees(id) on delete restrict,
  slot_id uuid not null references public.weekly_roster_slots(slot_id) on delete restrict,
  separated_at timestamptz not null,
  effective_date date not null,
  actor_manager_id uuid not null references public.ops_manager_managers(manager_id) on delete restrict,
  device_inventory_json jsonb not null check(jsonb_typeof(device_inventory_json)='array'),
  native_inventory_state text not null default 'UNKNOWN' check(native_inventory_state in ('UNKNOWN','VERIFIED_EMPTY','PROTECTED_PENDING','RECONCILED')),
  state text not null default 'PENDING_RECONCILIATION' check(state in ('PENDING_RECONCILIATION','RETAINED_UNRESOLVED','FINALIZED')),
  created_at timestamptz not null default statement_timestamp(),
  check(separated_at <= created_at + interval '1 second')
);
create index custodial_employee_separation_fences_employee_time
  on public.custodial_employee_separation_fences(employee_id,separated_at desc);
create unique index custodial_employee_one_pending_separation
  on public.custodial_employee_separation_fences(employee_id) where state='PENDING_RECONCILIATION';
alter table public.custodial_employee_separation_fences enable row level security;
alter table public.custodial_employee_separation_fences force row level security;
revoke all on table public.custodial_employee_separation_fences
  from public,anon,authenticated,service_role,static_weekly_control_plane,
       static_weekly_release_operator,custodial_application_reader;
create trigger trg_custodial_employee_separation_fences_immutable
  before update or delete on public.custodial_employee_separation_fences
  for each row execute function public.static_weekly_reject_update_delete();

-- This fence is a second line of defense at both canonical Start persistence
-- surfaces. It permits only genuinely pre-separation replay under the
-- separately attested device/snapshot/credential authority; it does not by
-- itself authenticate a client timestamp.
create function public.custodial_v12_reject_post_separation_start() returns trigger
language plpgsql security definer set search_path=pg_catalog,public as $function$
begin
  if exists(select 1 from public.custodial_employee_separation_fences f
    where f.employee_id=new.employee_id and f.state='PENDING_RECONCILIATION'
      and new.started_at>=f.separated_at) then
    raise exception using errcode='42501',message='separated employee cannot start new cleaning work';
  end if;
  return new;
end
$function$;
revoke all on function public.custodial_v12_reject_post_separation_start()
  from public,anon,authenticated,service_role,static_weekly_control_plane,
       static_weekly_release_operator,custodial_application_reader;
create trigger trg_custodial_v12_session_separation_fence
  before insert on public.sessions for each row
  execute function public.custodial_v12_reject_post_separation_start();
create trigger trg_custodial_v12_offline_separation_fence
  before insert on public.custodial_offline_actor_contexts for each row
  execute function public.custodial_v12_reject_post_separation_start();

-- No generic employee/device administration command may transfer or disable
-- an unresolved former principal's phone while its native inventory is still
-- unknown. A later audited finalizer must explicitly settle this boundary.
create function public.custodial_v12_guard_protected_device() returns trigger
language plpgsql security definer set search_path=pg_catalog,public as $function$
begin
  if old.assigned_employee_id is not null
    and (new.assigned_employee_id is distinct from old.assigned_employee_id
      or new.active is distinct from old.active)
    and exists(select 1 from public.custodial_employee_separation_fences f
      where f.employee_id=old.assigned_employee_id and f.state='PENDING_RECONCILIATION') then
    raise exception using errcode='42501',message='protected former-employee phone cannot be released or reassigned before reconciliation';
  end if;
  return new;
end
$function$;
revoke all on function public.custodial_v12_guard_protected_device()
  from public,anon,authenticated,service_role,static_weekly_control_plane,
       static_weekly_release_operator,custodial_application_reader;
create trigger trg_custodial_v12_guard_protected_device
  before update of assigned_employee_id,active on public.devices for each row
  execute function public.custodial_v12_guard_protected_device();

create function public.custodial_v12_guard_protected_credential() returns trigger
language plpgsql security definer set search_path=pg_catalog,public as $function$
begin
  if (new.revoked_at is distinct from old.revoked_at
      or new.expires_at<old.expires_at)
    and exists(select 1 from public.devices d
      join public.custodial_employee_separation_fences f
        on f.employee_id=d.assigned_employee_id and f.state='PENDING_RECONCILIATION'
      where d.id=old.device_id) then
    raise exception using errcode='42501',message='protected former-employee credential cannot be revoked before reconciliation';
  end if;
  return new;
end
$function$;
revoke all on function public.custodial_v12_guard_protected_credential()
  from public,anon,authenticated,service_role,static_weekly_control_plane,
       static_weekly_release_operator,custodial_application_reader;
create trigger trg_custodial_v12_guard_protected_credential
  before update of revoked_at,expires_at on public.device_auth_credentials for each row
  execute function public.custodial_v12_guard_protected_credential();

-- Only the already authenticated and revision-bound scheduler writer may
-- inactivate the original employee. The phone and its credential remain with
-- that principal while old signed native work reconciles. No phone is cleared,
-- released or rebound here.
create function public.custodial_v12_inactivate_preserving_work(
  p_employee_id uuid,p_slot_id uuid,p_manager_id uuid,p_reason text,
  p_authority_revision bigint,p_command_id uuid,p_effective_date date
) returns jsonb language plpgsql security definer set search_path=pg_catalog,public
as $function$
declare
  v_employee public.employees%rowtype;
  v_devices jsonb;
  v_cutoff timestamptz:=statement_timestamp();
  v_separation_id uuid;
begin
  perform public.static_weekly_v3_assert_control_plane();
  perform public.custodial_assert_manager(p_manager_id);
  select * into v_employee from public.employees where id=p_employee_id for update;
  if not found or v_employee.active is distinct from true
    or v_employee.employee_code !~ '^EMP[0-9]+$' then
    raise exception using errcode='23514',message='exact active custodian required for protected separation';
  end if;
  if p_slot_id is null or p_authority_revision is null or p_command_id is null
    or p_effective_date is null or p_effective_date<>public.sch_service_date(v_cutoff)
    or nullif(btrim(coalesce(p_reason,'')),'') is null then
    raise exception using errcode='23514',message='protected separation identity or effective date missing';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('device_uuid',d.id,'device_identifier',d.device_id)
    order by d.device_id),'[]'::jsonb) into v_devices
    from public.devices d where d.assigned_employee_id=p_employee_id and d.active is true;
  update public.employees set active=false,updated_at=v_cutoff where id=p_employee_id;
  update public.msg_users set is_active=false,updated_at=v_cutoff where employee_id=p_employee_id;
  insert into public.custodial_employee_status_history(
    employee_id,employee_name,previous_active,new_active,changed_by_manager_id,
    change_reason,source,metadata_json,changed_at)
  values(p_employee_id,v_employee.display_name,true,false,p_manager_id,p_reason,
    'static_weekly_protected_separation',
    jsonb_build_object('slot_id',p_slot_id,'authority_revision',p_authority_revision,
      'command_id',p_command_id,'device_inventory',v_devices,
      'native_inventory_state','UNKNOWN','phone_released',false),v_cutoff);
  insert into public.custodial_employee_separation_fences(
    command_id,authority_revision,employee_id,slot_id,separated_at,effective_date,
    actor_manager_id,device_inventory_json)
  values(p_command_id,p_authority_revision,p_employee_id,p_slot_id,v_cutoff,p_effective_date,
    p_manager_id,v_devices) returning separation_id into v_separation_id;
  return jsonb_build_object('changed',true,'employee_id',p_employee_id,
    'separation_id',v_separation_id,'separated_at',v_cutoff,
    'protected_work_state','PENDING_RECONCILIATION','native_inventory_state','UNKNOWN',
    'assigned_devices_retained',v_devices,'released_devices','[]'::jsonb);
end
$function$;
revoke all on function public.custodial_v12_inactivate_preserving_work(uuid,uuid,uuid,text,bigint,uuid,date)
  from public,anon,authenticated,service_role,static_weekly_release_operator,custodial_application_reader;
grant execute on function public.custodial_v12_inactivate_preserving_work(uuid,uuid,uuid,text,bigint,uuid,date)
  to static_weekly_control_plane;

-- Forward-replace the already receipt-bound vacancy writer at the exact three
-- unsafe seams. Guarded source transformation fails the migration if upstream
-- bytes differ; it never silently installs a partially patched authority.
do $migration$
declare
  v_definition text;
  v_old text;
begin
  select pg_get_functiondef('public.static_weekly_v8_vacate_roster_slot(uuid,uuid,uuid,date,text,bigint,uuid,text)'::regprocedure)
    into v_definition;
  v_old:='or not coalesce((v_source.canonical_source#>''{version,vacantSlotIds}'') ? p_slot_id::text,false)';
  if length(v_definition)-length(replace(v_definition,v_old,''))<>length(v_old) then
    raise exception 'vacancy source authority seam changed';
  end if;
  v_definition:=replace(v_definition,v_old,'');
  v_old:='perform public.static_weekly_v4_assert_employee_turnover_ready(p_employee_id);';
  if length(v_definition)-length(replace(v_definition,v_old,''))<>length(v_old) then
    raise exception 'protected work turnover guard seam changed';
  end if;
  v_definition:=replace(v_definition,v_old,'');
  v_old:='v_status:=public.custodial_set_employee_active(p_employee_id,false,p_manager_id,p_reason,true);';
  if length(v_definition)-length(replace(v_definition,v_old,''))<>length(v_old) then
    raise exception 'phone release seam changed';
  end if;
  v_definition:=replace(v_definition,v_old,
    'v_status:=public.custodial_v12_inactivate_preserving_work(p_employee_id,p_slot_id,p_manager_id,p_reason,v_revision,v_command,p_effective_start);');
  v_definition:=replace(v_definition,
    'registered source must declare this stable position vacancy-capable and vacant',
    'registered source must declare this stable position vacancy-capable');
  execute v_definition;
end
$migration$;

create function public.custodial_v12_read_separation(p_slot_id uuid,p_manager_id uuid)
returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public
as $function$
declare v_fence public.custodial_employee_separation_fences%rowtype;
begin
  perform public.static_weekly_v3_assert_control_plane();
  perform public.custodial_assert_manager(p_manager_id);
  if p_slot_id is null then raise exception using errcode='22023',message='exact stable position required';end if;
  select * into v_fence from public.custodial_employee_separation_fences
    where slot_id=p_slot_id order by separated_at desc,separation_id desc limit 1;
  if not found then return jsonb_build_object('slot_id',p_slot_id,'state','NONE');end if;
  return jsonb_build_object(
    'slot_id',v_fence.slot_id,'employee_id',v_fence.employee_id,
    'separation_id',v_fence.separation_id,'command_id',v_fence.command_id,
    'authority_revision',v_fence.authority_revision,
    'separated_at',v_fence.separated_at,'state',v_fence.state,
    'native_inventory_state',v_fence.native_inventory_state,
    'assigned_devices_retained',v_fence.device_inventory_json,
    'database_active_sessions',(select count(*) from public.sessions s
      where s.employee_id=v_fence.employee_id and s.status in ('active','pending_submit')),
    'database_activated_offline_contexts',(select count(*) from public.custodial_offline_actor_contexts c
      where c.employee_id=v_fence.employee_id and c.status='activated'),
    'phone_released',false);
end
$function$;
revoke all on function public.custodial_v12_read_separation(uuid,uuid)
  from public,anon,authenticated,service_role,static_weekly_release_operator,custodial_application_reader;
grant execute on function public.custodial_v12_read_separation(uuid,uuid)
  to static_weekly_control_plane;

do $surface$
declare v_definition text;v_additions text;
begin
  v_definition:=pg_get_functiondef('public.custodial_release_canary_authority_surface()'::regprocedure);
  if (length(v_definition)-length(replace(v_definition,'  values','')))/length('  values')<>1 then
    raise exception 'protected separation canary surface seam changed';
  end if;
  v_additions:=$rows$
 ('relation','public.custodial_employee_separation_fences','private protected-work separation and original-principal fence'),
 ('function','public.custodial_v12_reject_post_separation_start()','new Start persistence fence'),
 ('function','public.custodial_v12_guard_protected_device()','old phone ownership fence'),
 ('function','public.custodial_v12_guard_protected_credential()','old credential ownership fence'),
 ('function','public.custodial_v12_inactivate_preserving_work(uuid,uuid,uuid,text,bigint,uuid,date)','status transition preserving old phone work'),
 ('function','public.custodial_v12_read_separation(uuid,uuid)','manager-only honest pending separation readback'),
 ('trigger','public.sessions.trg_custodial_v12_session_separation_fence','new online Start fence'),
 ('trigger','public.custodial_offline_actor_contexts.trg_custodial_v12_offline_separation_fence','new offline Start fence'),
 ('trigger','public.devices.trg_custodial_v12_guard_protected_device','pending old-phone preservation'),
 ('trigger','public.device_auth_credentials.trg_custodial_v12_guard_protected_credential','pending credential preservation'),
 ('trigger','public.custodial_employee_separation_fences.trg_custodial_employee_separation_fences_immutable','immutable pending separation evidence'),
$rows$;
  execute replace(v_definition,'  values','  values'||E'\n'||v_additions);
end
$surface$;

alter table public.custodial_release_authority_restore_inventory
  disable trigger trg_custodial_release_authority_restore_inventory_immutable;
do $recovery$
declare obj record;next_order integer;
begin
  for obj in with relation_names(name) as (values ('public.custodial_employee_separation_fences')),
    funcs as (select p.oid,'public.'||p.oid::regprocedure::text identity
      from pg_proc p join pg_namespace n on n.oid=p.pronamespace
      where n.nspname='public' and (starts_with(p.proname,'custodial_v12_')
        or p.oid='public.static_weekly_v8_vacate_roster_slot(uuid,uuid,uuid,date,text,bigint,uuid,text)'::regprocedure
        or p.oid='public.custodial_release_canary_authority_surface()'::regprocedure)),
    new_triggers as (select t.oid,c.relname,n.nspname,t.tgname,t.tgenabled
      from pg_trigger t join pg_class c on c.oid=t.tgrelid
      join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='public' and t.tgname in (
        'trg_custodial_v12_session_separation_fence',
        'trg_custodial_v12_offline_separation_fence',
        'trg_custodial_v12_guard_protected_device',
        'trg_custodial_v12_guard_protected_credential',
        'trg_custodial_employee_separation_fences_immutable')),
    objects as (
      select 1000 bucket,'relation'::text kind,name identity,
        public.custodial_release_authority_current_relation_definition(name) definition from relation_names
      union all select 100000,'function',identity,pg_get_functiondef(oid) from funcs
      union all select 200000,'column',r.name||':'||a.attname,
        public.custodial_release_authority_current_column_definition(r.name||':'||a.attname)
        from relation_names r join pg_attribute a on a.attrelid=r.name::regclass and a.attnum>0 and not a.attisdropped
      union all select 300000,'column_set',name,
        public.custodial_release_authority_current_column_set_definition(name) from relation_names
      union all select 400000,'relation_state',name,
        public.custodial_release_authority_current_relation_state_definition(name) from relation_names
      union all select 500000,'constraint',r.name||':'||c.conname,
        public.custodial_release_authority_current_constraint_definition(r.name||':'||c.conname)
        from relation_names r join pg_constraint c on c.conrelid=r.name::regclass
      union all select 600000,'index','public.'||quote_ident(ci.relname),
        public.custodial_release_authority_current_index_definition('public.'||quote_ident(ci.relname))
        from relation_names r join pg_index i on i.indrelid=r.name::regclass
        join pg_class ci on ci.oid=i.indexrelid
        where not exists(select 1 from pg_constraint c where c.conindid=i.indexrelid)
      union all select 700000,'trigger',quote_ident(nspname)||'.'||quote_ident(relname)||'.'||quote_ident(tgname),
        'drop trigger if exists '||quote_ident(tgname)||' on '||quote_ident(nspname)||'.'||quote_ident(relname)||'; '
        ||pg_get_triggerdef(oid,true)||'; alter table '||quote_ident(nspname)||'.'||quote_ident(relname)||' '
        ||case tgenabled when 'O' then 'enable' when 'D' then 'disable' when 'R' then 'enable replica' when 'A' then 'enable always' end
        ||' trigger '||quote_ident(tgname)||';' from new_triggers
      union all select 900000,'grant',name,
        public.custodial_release_authority_current_grant_definition(name) from relation_names
      union all select 900000,'grant',identity,
        public.custodial_release_authority_current_grant_definition(identity) from funcs
    ) select * from objects order by bucket,identity loop
    if obj.definition is null then raise exception 'missing protected separation recovery object %',obj.identity;end if;
    update public.custodial_release_authority_restore_inventory set definition_sql=obj.definition,
      definition_sha256=public.static_weekly_digest_text(obj.definition),captured_at=statement_timestamp()
      where object_kind=obj.kind and (object_identity=obj.identity or
        case when obj.kind in ('function','grant') and object_identity like '%(%' and obj.identity like '%(%'
          then to_regprocedure(object_identity)=to_regprocedure(obj.identity) else false end);
    if not found then
      select coalesce(max(restore_order),obj.bucket)+1 into next_order
        from public.custodial_release_authority_restore_inventory
        where restore_order>=obj.bucket and restore_order<case when obj.bucket=1000 then 100000 else obj.bucket+100000 end;
      insert into public.custodial_release_authority_restore_inventory
        (restore_order,object_kind,object_identity,definition_sql,definition_sha256)
        values(next_order,obj.kind,obj.identity,obj.definition,public.static_weekly_digest_text(obj.definition));
    end if;
  end loop;
end
$recovery$;
alter table public.custodial_release_authority_restore_inventory
  enable trigger trg_custodial_release_authority_restore_inventory_immutable;

commit;

begin;

-- Employee active-state changes are now accepted only through the versioned
-- Weekly Schedule turnover commands. Their SECURITY DEFINER implementations
-- retain owner-to-owner access to this legacy helper inside the same
-- transaction; the ordinary service-role Data API must not call it directly
-- and silently bypass the scheduler revision/position ledger.
revoke all on function public.custodial_set_employee_active(uuid,boolean,uuid,text,boolean)
  from public, anon, authenticated, service_role,
       static_weekly_control_plane, static_weekly_release_operator,
       custodial_application_reader;

-- Keep disaster-restore permission replay aligned with the denied direct RPC;
-- otherwise restoration could silently re-grant the retired path.
alter table public.custodial_release_authority_restore_inventory
  disable trigger trg_custodial_release_authority_restore_inventory_immutable;
do $recovery$
declare
  v_identity text := ('public.custodial_set_employee_active(uuid,boolean,uuid,text,boolean)'::regprocedure)::text;
  v_definition text;
  v_order integer;
begin
  v_definition := public.custodial_release_authority_current_grant_definition(v_identity);
  if v_definition is null then
    raise exception 'missing retired employee-status grant definition';
  end if;
  update public.custodial_release_authority_restore_inventory
  set definition_sql = public.custodial_release_authority_current_grant_definition(object_identity),
      definition_sha256 = public.static_weekly_digest_text(
        public.custodial_release_authority_current_grant_definition(object_identity)),
      captured_at = statement_timestamp()
  where object_kind = 'grant'
    and to_regprocedure(object_identity) = v_identity::regprocedure;
  if not found then
    select coalesce(max(restore_order), 900000) + 1 into v_order
    from public.custodial_release_authority_restore_inventory
    where restore_order >= 900000;
    insert into public.custodial_release_authority_restore_inventory
      (restore_order, object_kind, object_identity, definition_sql, definition_sha256)
    values (v_order, 'grant', v_identity, v_definition,
      public.static_weekly_digest_text(v_definition));
  end if;
end
$recovery$;
alter table public.custodial_release_authority_restore_inventory
  enable trigger trg_custodial_release_authority_restore_inventory_immutable;

commit;

-- H03/H04 parent-transaction foundation. No HTTP confirmation/finalizer is
-- enabled by this migration. Only the future complete publication + phone
-- target path may insert its private receipt. A reservation alone cannot
-- commit. The ledger deliberately grants no generic mark-success operation.
begin;
set local lock_timeout='5s';
set local statement_timeout='30s';

create table public.static_weekly_recurring_confirmations (
  operation_id uuid primary key default gen_random_uuid(),
  manager_id uuid not null references public.ops_manager_managers(manager_id) on delete restrict,
  confirmation_key uuid not null,
  request_json jsonb not null check(jsonb_typeof(request_json)='object'),
  request_digest text not null check(request_digest~'^[0-9a-f]{64}$'),
  effective_start date not null check(extract(isodow from effective_start)=1),
  expected_revision bigint not null check(expected_revision>=0),
  preview_digest text not null check(preview_digest~'^[0-9a-f]{64}$'),
  full_nine_source_id uuid references public.static_weekly_authority_source_documents(source_id) on delete restrict,
  owner_xid xid8 not null default pg_current_xact_id(),
  created_at timestamptz not null default statement_timestamp(),
  unique(manager_id,confirmation_key)
);
create index static_weekly_recurring_confirmations_source
  on public.static_weekly_recurring_confirmations(full_nine_source_id)
  where full_nine_source_id is not null;

create table public.static_weekly_recurring_confirmation_receipts (
  operation_id uuid primary key references public.static_weekly_recurring_confirmations(operation_id) on delete restrict,
  source_id uuid not null unique references public.static_weekly_authority_source_documents(source_id) on delete restrict,
  source_digest text not null check(source_digest~'^[0-9a-f]{64}$'),
  publication_id uuid not null unique references public.weekly_schedule_publications(publication_id) on delete restrict,
  projection_id uuid not null unique references public.weekly_schedule_compiled_projections(projection_id) on delete restrict,
  accepted_revision bigint not null unique references public.weekly_schedule_authority_revisions(authority_revision) on delete restrict,
  lunch_document_identity text not null check(lunch_document_identity~'^[0-9a-f]{64}$'),
  receipt_json jsonb not null check(jsonb_typeof(receipt_json)='object'),
  receipt_digest text not null check(receipt_digest~'^[0-9a-f]{64}$'),
  accepted_at timestamptz not null default statement_timestamp()
);

alter table public.static_weekly_recurring_confirmations enable row level security;
alter table public.static_weekly_recurring_confirmations force row level security;
alter table public.static_weekly_recurring_confirmation_receipts enable row level security;
alter table public.static_weekly_recurring_confirmation_receipts force row level security;
revoke all on table public.static_weekly_recurring_confirmations,
  public.static_weekly_recurring_confirmation_receipts from public,anon,authenticated,
  service_role,static_weekly_control_plane,static_weekly_release_operator,custodial_application_reader;

create trigger trg_recurring_confirmation_immutable before update or delete
  on public.static_weekly_recurring_confirmations for each row
  execute function public.static_weekly_reject_update_delete();
create trigger trg_recurring_confirmation_receipt_immutable before update or delete
  on public.static_weekly_recurring_confirmation_receipts for each row
  execute function public.static_weekly_reject_update_delete();

create function public.static_weekly_v13_require_completed_recurring_confirmation()
returns trigger language plpgsql security definer set search_path=pg_catalog,public as $function$
begin
  if new.owner_xid<>pg_current_xact_id() or not exists(
    select 1 from public.static_weekly_recurring_confirmation_receipts r
    where r.operation_id=new.operation_id) then
    raise exception using errcode='23514',message='recurring confirmation cannot commit without its complete atomic receipt';
  end if;
  return null;
end
$function$;
create constraint trigger trg_recurring_confirmation_complete
  after insert on public.static_weekly_recurring_confirmations
  deferrable initially deferred for each row
  execute function public.static_weekly_v13_require_completed_recurring_confirmation();

-- Structural receipt proof; the future private acceptance routine must also
-- bind the exact complete decision, generation and durable phone targets.
-- No runtime role can insert this table or call a receipt writer here.
create function public.static_weekly_v13_guard_recurring_receipt()
returns trigger language plpgsql security definer set search_path=pg_catalog,public as $function$
declare v_parent public.static_weekly_recurring_confirmations%rowtype;
begin
  select * into strict v_parent from public.static_weekly_recurring_confirmations
    where operation_id=new.operation_id;
  if v_parent.owner_xid<>pg_current_xact_id()
    or new.accepted_revision<=v_parent.expected_revision
    or new.receipt_digest<>public.static_weekly_digest_jsonb(new.receipt_json)
    or new.receipt_json is distinct from jsonb_build_object(
      'schema','static-weekly.recurring-confirmation-receipt.v1',
      'operationId',new.operation_id,'managerId',v_parent.manager_id,
      'confirmationKey',v_parent.confirmation_key,'requestDigest',v_parent.request_digest,
      'previewDigest',v_parent.preview_digest,'effectiveStart',v_parent.effective_start,
      'sourceId',new.source_id,'sourceDigest',new.source_digest,
      'publicationId',new.publication_id,'projectionId',new.projection_id,
      'authorityRevision',new.accepted_revision,'lunchDocumentIdentity',new.lunch_document_identity,
      'accepted',true,'phoneDeliveryState','PENDING','affectedPhonesUpdated',false)
    or not exists(select 1 from public.weekly_schedule_publications p
      join public.weekly_schedule_versions v on v.version_id=p.version_id
      join public.static_weekly_authority_source_documents s on s.source_id=v.authority_source_id
      join public.weekly_schedule_compiled_projections x on x.publication_id=p.publication_id
        and x.version_id=v.version_id
      join public.weekly_schedule_lunch_documents l on l.projection_id=x.projection_id
      where p.publication_id=new.publication_id and x.projection_id=new.projection_id
        and p.actor_manager_id=v_parent.manager_id and x.compiled_by_manager_id=v_parent.manager_id
        and l.accepted_by_manager_id=v_parent.manager_id
        and p.effective_start=v_parent.effective_start and x.week_start=v_parent.effective_start
        and s.source_id=new.source_id and s.source_digest=new.source_digest
        and s.source_digest=public.static_weekly_digest_jsonb(s.canonical_source)
        and l.document_identity=new.lunch_document_identity
        and p.authority_revision>v_parent.expected_revision
        and p.authority_revision<=new.accepted_revision) then
    raise exception using errcode='23514',message='recurring receipt must bind its original transaction and exact accepted child artifacts';
  end if;
  return new;
end
$function$;
create trigger trg_recurring_confirmation_receipt_binding before insert
  on public.static_weekly_recurring_confirmation_receipts for each row
  execute function public.static_weekly_v13_guard_recurring_receipt();

create function public.static_weekly_v13_begin_recurring_confirmation(
  p_manager_id uuid,p_confirmation_key uuid,p_effective_start date,
  p_expected_revision bigint,p_preview_digest text,p_full_nine_source_id uuid default null
) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $function$
declare
  v_request jsonb; v_digest text; v_revision bigint;
  v_parent public.static_weekly_recurring_confirmations%rowtype;
  v_receipt jsonb;
begin
  perform public.static_weekly_v3_assert_control_plane();
  perform public.static_weekly_v3_manager_actor(p_manager_id);
  if p_confirmation_key is null or p_effective_start is null
    or extract(isodow from p_effective_start)<>1 or not isfinite(p_effective_start)
    or p_expected_revision is null or p_expected_revision<0
    or p_preview_digest is null or p_preview_digest!~'^[0-9a-f]{64}$'
    or (p_full_nine_source_id is not null
      and p_full_nine_source_id<>'a00cdf2a-0623-5e2d-bc65-338c1dd67202'::uuid) then
    raise exception using errcode='22023',message='exact recurring confirmation request required';
  end if;
  v_request:=jsonb_build_object('schema','static-weekly.recurring-confirmation-request.v1',
    'managerId',p_manager_id,'confirmationKey',p_confirmation_key,
    'effectiveStart',p_effective_start,'expectedRevision',p_expected_revision,
    'previewDigest',p_preview_digest,'fullNineSourceId',p_full_nine_source_id);
  v_digest:=public.static_weekly_digest_jsonb(v_request);
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  -- Reread a same-key parent BEFORE time/revision staleness. A committed retry
  -- must not accidentally compile/publish against today's roster.
  select * into v_parent from public.static_weekly_recurring_confirmations
    where manager_id=p_manager_id and confirmation_key=p_confirmation_key for update;
  if found then
    if v_parent.request_digest<>v_digest or v_parent.request_json<>v_request then
      raise exception using errcode='23505',message='recurring confirmation idempotency conflict';
    end if;
    select receipt_json into v_receipt from public.static_weekly_recurring_confirmation_receipts
      where operation_id=v_parent.operation_id;
    if v_receipt is not null then
      return jsonb_build_object('state','ACCEPTED','operationId',v_parent.operation_id,'receipt',v_receipt);
    end if;
    if v_parent.owner_xid<>pg_current_xact_id() then
      raise exception using errcode='23514',message='incomplete recurring confirmation from another transaction';
    end if;
    return jsonb_build_object('state','RESERVED','operationId',v_parent.operation_id,'requestDigest',v_digest);
  end if;
  if p_effective_start<=public.sch_service_date(statement_timestamp()) then
    raise exception using errcode='23514',message='new recurring plan must start on a future zoo-local Monday';
  end if;
  select current_revision into v_revision from public.static_weekly_schedule_control where singleton for update;
  if v_revision is distinct from p_expected_revision then
    raise exception using errcode='40001',message='recurring confirmation authority revision changed';
  end if;
  insert into public.static_weekly_recurring_confirmations(manager_id,confirmation_key,
    request_json,request_digest,effective_start,expected_revision,preview_digest,full_nine_source_id)
  values(p_manager_id,p_confirmation_key,v_request,v_digest,p_effective_start,p_expected_revision,
    p_preview_digest,p_full_nine_source_id) returning * into v_parent;
  return jsonb_build_object('state','RESERVED','operationId',v_parent.operation_id,'requestDigest',v_digest);
end
$function$;

create function public.static_weekly_v13_read_recurring_confirmation(p_manager_id uuid,p_confirmation_key uuid)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $function$
declare v_parent public.static_weekly_recurring_confirmations%rowtype;v_receipt jsonb;
begin
  perform public.static_weekly_v3_assert_control_plane();
  perform public.static_weekly_v3_manager_actor(p_manager_id);
  if p_confirmation_key is null then raise exception using errcode='22023',message='exact recurring confirmation key required';end if;
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_parent from public.static_weekly_recurring_confirmations
    where manager_id=p_manager_id and confirmation_key=p_confirmation_key;
  if not found then return jsonb_build_object('state','NOT_FOUND','confirmationKey',p_confirmation_key);end if;
  select receipt_json into v_receipt from public.static_weekly_recurring_confirmation_receipts
    where operation_id=v_parent.operation_id;
  if v_receipt is null then
    raise exception using errcode='23514',message='recurring confirmation has not committed a complete receipt';
  end if;
  return jsonb_build_object('state','ACCEPTED','operationId',v_parent.operation_id,'receipt',v_receipt);
end
$function$;

revoke all on function public.static_weekly_v13_require_completed_recurring_confirmation(),
  public.static_weekly_v13_guard_recurring_receipt(),
  public.static_weekly_v13_begin_recurring_confirmation(uuid,uuid,date,bigint,text,uuid),
  public.static_weekly_v13_read_recurring_confirmation(uuid,uuid)
  from public,anon,authenticated,service_role,static_weekly_control_plane,
    static_weekly_release_operator,custodial_application_reader;
grant execute on function public.static_weekly_v13_begin_recurring_confirmation(uuid,uuid,date,bigint,text,uuid),
  public.static_weekly_v13_read_recurring_confirmation(uuid,uuid) to static_weekly_control_plane;

-- Forward recovery inventory is appended below before the migration commits.
do $surface$
declare v_definition text;v_additions text;
begin
  v_definition:=pg_get_functiondef('public.custodial_release_canary_authority_surface()'::regprocedure);
  if (length(v_definition)-length(replace(v_definition,'  values','')))/length('  values')<>1 then
    raise exception 'recurring confirmation canary surface seam changed';
  end if;
  v_additions:=$rows$
 ('relation','public.static_weekly_recurring_confirmations','atomic recurring confirmation parent receipt boundary'),
 ('relation','public.static_weekly_recurring_confirmation_receipts','atomic recurring confirmation parent receipt boundary'),
 ('function','public.static_weekly_v13_require_completed_recurring_confirmation()','atomic recurring confirmation parent receipt boundary'),
 ('function','public.static_weekly_v13_guard_recurring_receipt()','atomic recurring confirmation parent receipt boundary'),
 ('function','public.static_weekly_v13_begin_recurring_confirmation(uuid,uuid,date,bigint,text,uuid)','atomic recurring confirmation parent receipt boundary'),
 ('function','public.static_weekly_v13_read_recurring_confirmation(uuid,uuid)','atomic recurring confirmation parent receipt boundary'),
 ('trigger','public.static_weekly_recurring_confirmations.trg_recurring_confirmation_immutable','atomic recurring confirmation parent receipt boundary'),
 ('trigger','public.static_weekly_recurring_confirmations.trg_recurring_confirmation_complete','atomic recurring confirmation parent receipt boundary'),
 ('trigger','public.static_weekly_recurring_confirmation_receipts.trg_recurring_confirmation_receipt_immutable','atomic recurring confirmation parent receipt boundary'),
 ('trigger','public.static_weekly_recurring_confirmation_receipts.trg_recurring_confirmation_receipt_binding','atomic recurring confirmation parent receipt boundary'),
$rows$;
  execute replace(v_definition,'  values','  values'||E'\n'||v_additions);
end
$surface$;

