alter table public.custodial_release_authority_restore_inventory disable trigger trg_custodial_release_authority_restore_inventory_immutable;
do $recovery$
declare signature text;kind text;definition text;changed int;bucket int;next_order int;
begin
 foreach signature in array array[
  'public.mz_location_reminder_candidates(date,timestamptz)',
  'public.operational_day_start(timestamptz)',
  'public.get_setting_int(text,integer)',
  'public.mz_latest_verified_check(uuid,timestamptz,timestamptz)',
  'public.custodial_release_canary_authority_surface()',
  'public.mz_enqueue_employee_location_pushes(timestamptz)',
  'public.mz_validate_employee_location_reminder(uuid,uuid,timestamptz)',
  'public.mz_prepare_employee_native_push_delivery(uuid,uuid,uuid,bigint,uuid,text,timestamptz)'
 ] loop
  foreach kind in array array['function','grant'] loop
   definition:=case when kind='function' then pg_get_functiondef(signature::regprocedure)
    else public.custodial_release_authority_current_grant_definition((signature::regprocedure)::text) end;
   if definition is null then raise exception 'missing notification recovery definition: %',signature;end if;
   update public.custodial_release_authority_restore_inventory set definition_sql=definition,
    definition_sha256=public.static_weekly_digest_text(definition),captured_at=statement_timestamp()
    where object_kind=kind and object_identity like '%(%' and to_regprocedure(object_identity)=signature::regprocedure;
   get diagnostics changed=row_count;
   if changed=0 and signature in ('public.operational_day_start(timestamptz)','public.get_setting_int(text,integer)') then
    bucket:=case when kind='function' then 100000 else 900000 end;
    select coalesce(max(restore_order),bucket)+1 into next_order from public.custodial_release_authority_restore_inventory
     where restore_order>=bucket and restore_order<bucket+100000;
    insert into public.custodial_release_authority_restore_inventory
     (restore_order,object_kind,object_identity,definition_sql,definition_sha256)
     values(next_order,kind,(signature::regprocedure)::text,definition,public.static_weekly_digest_text(definition));
   elsif changed<>1 then raise exception 'expected one notification recovery %: %',kind,signature;end if;
  end loop;
  -- The inventory enumerator retains its pre-existing private ACL; it is not
  -- a service RPC and this migration does not grant it to runtime callers.
  if signature<>'public.custodial_release_canary_authority_surface()' and
   (has_function_privilege('anon',signature,'EXECUTE') or has_function_privilege('authenticated',signature,'EXECUTE')
   or not has_function_privilege('service_role',signature,'EXECUTE')) then
   raise exception 'notification minimum privileges changed: %',signature;
  end if;
 end loop;
end $recovery$;
do $policy_recovery$
declare identity text:='public.device_notification_acknowledgements:custodial_reader_bound_notification_ack';
 definition text;next_order integer;
begin
 definition:=public.custodial_release_authority_current_policy_definition(identity);
 if definition is null then raise exception 'bound notification reader policy recovery missing';end if;
 select coalesce(max(restore_order),800000)+1 into next_order
  from public.custodial_release_authority_restore_inventory where object_kind='policy';
 insert into public.custodial_release_authority_restore_inventory
  (restore_order,object_kind,object_identity,definition_sql,definition_sha256)
 values(next_order,'policy',identity,definition,public.static_weekly_digest_text(definition));
end $policy_recovery$;
alter table public.custodial_release_authority_restore_inventory enable trigger trg_custodial_release_authority_restore_inventory_immutable;
commit;

-- F07-R1: only an exact JSON boolean true is a manager test notification.
-- Forward-only; preserve the existing API/ACL and all publication/ACK locks.
begin;
set local lock_timeout='5s';
set local statement_timeout='30s';
do $correction$
declare
 signature text:='public.mz_prepare_employee_native_push_delivery(uuid,uuid,uuid,bigint,uuid,text,timestamptz)';
 definition text;prior_grants text;
 old_predicate text:=$old$coalesce(v_job.payload_json#>>'{data_json,test_delivery}','false')='false'$old$;
 new_predicate text:=$new$(v_job.payload_json#>'{data_json,test_delivery}') is distinct from 'true'::jsonb$new$;
 changed integer;
begin
 definition:=pg_get_functiondef(signature::regprocedure);
 prior_grants:=public.custodial_release_authority_current_grant_definition((signature::regprocedure)::text);
 if length(definition)-length(replace(definition,old_predicate,''))<>length(old_predicate) then
  raise exception 'exact canary predecessor seam changed';
 end if;
 execute replace(definition,old_predicate,new_predicate);
 if public.custodial_release_authority_current_grant_definition((signature::regprocedure)::text) is distinct from prior_grants then
  raise exception 'exact canary correction changed API privileges';
 end if;
 definition:=pg_get_functiondef(signature::regprocedure);
 alter table public.custodial_release_authority_restore_inventory disable trigger trg_custodial_release_authority_restore_inventory_immutable;
 update public.custodial_release_authority_restore_inventory
  set definition_sql=definition,definition_sha256=public.static_weekly_digest_text(definition),captured_at=statement_timestamp()
  where object_kind='function' and object_identity like '%(%' and to_regprocedure(object_identity)=signature::regprocedure;
 get diagnostics changed=row_count;
 if changed<>1 then raise exception 'expected one exact canary recovery function';end if;
 alter table public.custodial_release_authority_restore_inventory enable trigger trg_custodial_release_authority_restore_inventory_immutable;
end $correction$;
commit;

-- H04 stage1: immutable original principal capture and purpose-only read.
-- No work acceptance, inventory acknowledgement, finalization or phone reuse.
-- Historical v12 rows remain UNKNOWN; never backfill identity from today's DB.
begin;
set local lock_timeout='5s';
set local statement_timeout='30s';
do $capture$
declare definition text;old_text text;new_text text;prior_grants text;
begin
 definition:=pg_get_functiondef('public.custodial_v12_inactivate_preserving_work(uuid,uuid,uuid,text,bigint,uuid,date)'::regprocedure);
 prior_grants:=public.custodial_release_authority_current_grant_definition('public.custodial_v12_inactivate_preserving_work(uuid,uuid,uuid,text,bigint,uuid,date)');
 old_text:=$old$select coalesce(jsonb_agg(jsonb_build_object('device_uuid',d.id,'device_identifier',d.device_id)
    order by d.device_id),'[]'::jsonb) into v_devices
    from public.devices d where d.assigned_employee_id=p_employee_id and d.active is true;$old$;
 new_text:=$new$select coalesce(jsonb_agg(jsonb_build_object(
    'schema','custodial.separation-principal.v1','device_uuid',d.id,'device_identifier',d.device_id,
    'employee_id',p_employee_id,'assignment_epoch',d.assignment_epoch,
    'credentials',coalesce((select jsonb_agg(jsonb_build_object('credential_id',c.credential_id)
       order by c.credential_id) from public.device_auth_credentials c
       where c.device_id=d.id and c.revoked_at is null and c.created_at<v_cutoff
         and c.expires_at>v_cutoff and c.confirmed_at is not null and c.confirmed_at<v_cutoff),'[]'::jsonb),
    'server_known_open_sessions',coalesce((select jsonb_agg(jsonb_build_object(
       'session_id',s.id,'session_uuid',s.session_uuid,'client_session_id',s.client_session_id,
       'started_at',s.started_at,'status_at_separation',s.status) order by s.id)
       from public.sessions s where s.employee_id=p_employee_id and s.device_id=d.id
         and s.assignment_epoch_snapshot=d.assignment_epoch and s.created_at<v_cutoff
         and s.status in ('active','pending_submit')),'[]'::jsonb))
    order by d.device_id),'[]'::jsonb) into v_devices
    from public.devices d where d.assigned_employee_id=p_employee_id and d.active is true;$new$;
 if length(definition)-length(replace(definition,old_text,''))<>length(old_text) then
  raise exception 'original principal capture predecessor seam changed';end if;
 execute replace(definition,old_text,new_text);
 if public.custodial_release_authority_current_grant_definition('public.custodial_v12_inactivate_preserving_work(uuid,uuid,uuid,text,bigint,uuid,date)') is distinct from prior_grants then
  raise exception 'original capture changed mutation privileges';end if;
end $capture$;

create function public.custodial_v13_read_separation_context(p_device_id uuid,p_credential_id uuid)
returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public
as $function$
declare f public.custodial_employee_separation_fences%rowtype;principal jsonb;matched record;
begin
 if p_device_id is null or p_credential_id is null then
  raise exception using errcode='22023',message='exact original device and credential required';end if;
 select sf as fence,item as principal into matched
 from public.custodial_employee_separation_fences sf
 cross join lateral jsonb_array_elements(sf.device_inventory_json) item
 join public.devices d on d.id=p_device_id and d.active is true
 join public.employees e on e.id=sf.employee_id and e.active is false
 join public.device_auth_credentials c on c.device_id=d.id and c.credential_id=p_credential_id and c.revoked_at is null
 where sf.state='PENDING_RECONCILIATION'
   and item->>'schema'='custodial.separation-principal.v1'
   and item->>'device_uuid'=p_device_id::text
   and item->>'device_identifier'=d.device_id
   and item->>'employee_id'=sf.employee_id::text
   and d.assigned_employee_id=sf.employee_id
   and item->'assignment_epoch'=to_jsonb(d.assignment_epoch)
   and item->'credentials' @> jsonb_build_array(jsonb_build_object('credential_id',p_credential_id))
 order by sf.separated_at desc,sf.separation_id desc limit 1;
 if not found then return null;end if;
 f:=matched.fence;principal:=matched.principal;
 return jsonb_build_object('schema','custodial.separation-context.v1',
  'separation_id',f.separation_id,'authority_revision',f.authority_revision,
  'employee_id',f.employee_id,'device_id',p_device_id,'canonical_device_id',principal->>'device_identifier',
  'credential_id',p_credential_id,'assignment_epoch',principal->'assignment_epoch',
  'cutoff_at',to_char(f.separated_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'state',f.state,'native_inventory_state',f.native_inventory_state,
  'server_known_open_sessions',principal->'server_known_open_sessions',
  'new_work_allowed',false,'phone_released',false,'purpose','SEPARATION_STATUS_ONLY');
end $function$;
revoke all on function public.custodial_v13_read_separation_context(uuid,uuid)
 from public,anon,authenticated,service_role,static_weekly_control_plane,static_weekly_release_operator,custodial_application_reader;
-- Backend authenticates retained token + native raw-body request before this
-- read. No browser/Data API role can request somebody else's context directly.
grant execute on function public.custodial_v13_read_separation_context(uuid,uuid) to custodial_application_reader;

do $surface$
declare definition text;
begin
 definition:=pg_get_functiondef('public.custodial_release_canary_authority_surface()'::regprocedure);
 if (length(definition)-length(replace(definition,'  values','')))/length('  values')<>1 then
  raise exception 'separation context canary surface seam changed';end if;
 execute replace(definition,'  values','  values'||E'\n'||
  '(''function'',''public.custodial_v13_read_separation_context(uuid,uuid)'',''purpose-only original separation context''),');
end $surface$;

alter table public.custodial_release_authority_restore_inventory disable trigger trg_custodial_release_authority_restore_inventory_immutable;
do $recovery$
declare obj record;next_order integer;
begin
 for obj in with funcs as (
   select p.oid,'public.'||p.oid::regprocedure::text identity from pg_proc p
   where p.oid in ('public.custodial_v12_inactivate_preserving_work(uuid,uuid,uuid,text,bigint,uuid,date)'::regprocedure,
    'public.custodial_v13_read_separation_context(uuid,uuid)'::regprocedure,
    'public.custodial_release_canary_authority_surface()'::regprocedure)),objects as (
   select 100000 bucket,'function'::text kind,identity,pg_get_functiondef(oid) definition from funcs
   union all select 900000,'grant',identity,public.custodial_release_authority_current_grant_definition(identity) from funcs)
  select * from objects order by bucket,identity loop
  if obj.definition is null then raise exception 'missing separation context recovery object %',obj.identity;end if;
  update public.custodial_release_authority_restore_inventory set definition_sql=obj.definition,
    definition_sha256=public.static_weekly_digest_text(obj.definition),captured_at=statement_timestamp()
    where object_kind=obj.kind and object_identity like '%(%' and to_regprocedure(object_identity)=to_regprocedure(obj.identity);
  if not found then
   select coalesce(max(restore_order),obj.bucket)+1 into next_order from public.custodial_release_authority_restore_inventory
    where restore_order>=obj.bucket and restore_order<obj.bucket+100000;
   insert into public.custodial_release_authority_restore_inventory(restore_order,object_kind,object_identity,definition_sql,definition_sha256)
    values(next_order,obj.kind,obj.identity,obj.definition,public.static_weekly_digest_text(obj.definition));
  end if;
 end loop;
end $recovery$;
alter table public.custodial_release_authority_restore_inventory enable trigger trg_custodial_release_authority_restore_inventory_immutable;
commit;

-- Correct captured recovery definitions after the GPS and recurring additions.
-- Keep all prior migration bytes, business rows, authority checks and history.
-- The backend invokes the SECURITY DEFINER tool wrapper, not the GPS helper.
-- Only that wrapper retains service-role EXECUTE; the internal implementation
-- must not remain a separately callable writer to scan_events.
begin;
set local lock_timeout='5s';
set local statement_timeout='60s';
set local search_path=pg_catalog,public,extensions;

-- Refuse to seal a different implementation or a changed wrapper boundary.
do $preflight$
declare candidate record;actual text;private_function record;
begin
 for candidate in select * from (values
  ('public.evaluate_location_proximity_v2(text,text,numeric,numeric,numeric,text,text,text,timestamp with time zone)',
   '7fa82fecdbafc4f2da58fc2996cdda75b8949a793846dc6fb6d54518be01a706'),
  ('public.tool_evaluate_location_proximity_v2(text,text,numeric,numeric,numeric,text,text,text,timestamp with time zone)',
   '2e2e6b4765cb956956b79d048bf2b8b4f13b33791dd0cde456abbee70f97801d')
 ) expected(signature,digest) loop
  select encode(extensions.digest(convert_to(pg_get_functiondef(candidate.signature::regprocedure),'UTF8'),'sha256'),'hex') into actual;
  if actual is distinct from candidate.digest then raise exception 'recovery closure predecessor changed: %',candidate.signature;end if;
  if not (select p.prosecdef from pg_proc p where p.oid=candidate.signature::regprocedure) then
   raise exception 'GPS definer boundary changed';end if;
 end loop;
 if not has_function_privilege('service_role','public.tool_evaluate_location_proximity_v2(text,text,numeric,numeric,numeric,text,text,text,timestamp with time zone)','EXECUTE')
  or has_function_privilege('anon','public.tool_evaluate_location_proximity_v2(text,text,numeric,numeric,numeric,text,text,text,timestamp with time zone)','EXECUTE')
  or has_function_privilege('authenticated','public.tool_evaluate_location_proximity_v2(text,text,numeric,numeric,numeric,text,text,text,timestamp with time zone)','EXECUTE') then
  raise exception 'existing GPS tool privilege boundary changed';end if;
 if (select count(*) from pg_attribute where attrelid='public.location_proximity_settings'::regclass
    and attname in ('authority_radius_m','authority_surveyed_at') and attnum>0 and not attisdropped and not attnotnull)<>2 then
  raise exception 'required exact-location GPS columns are absent or changed';end if;
 if not exists(select 1 from pg_constraint where conrelid='public.location_proximity_settings'::regclass
    and conname='location_proximity_authority_radius_bound' and convalidated) then
  raise exception 'GPS radius constraint is not present and validated';end if;

 -- The installer is SECURITY DEFINER and the recreated trigger DDL only names
 -- its guard; it does not authenticate that guard's transitive implementation.
 -- Pin the complete privileged call chain and both DDL event-trigger handlers
 -- before the installer can execute against a restored database.
 for candidate in select * from (values
  ('custodial_dr.acquire_application_mutation_fence()','923621addfd8dac026ea7ab439366caf9baed7c5da77afabb9f263c4b129e563'),
  ('custodial_dr.guard_application_ddl()','3461ee511455447a44f1d676102a74c8544978127cfc9645dc27e46d48f50296'),
  ('custodial_dr.guard_application_mutation()','c951e5a94562536ef46ccd3bfc4c3dfc6df2a526f3fa75891604ca625cd7c8b7'),
  ('custodial_dr.install_application_mutation_fences()','cc53626170d5afe999ebf8795f26374bbb51da7c4d6286cfa50ea2aa5d38cc5f'),
  ('custodial_dr.install_application_mutation_fences_after_ddl()','0cc7db4f3a5deab81fc13667e38a1e176bf68cc2a1f63883e72d5038db10410b')
 ) expected(signature,digest) loop
  select p.oid,p.prosecdef,p.proconfig,p.proacl,p.proowner,pg_get_userbyid(p.proowner) owner_name,
   encode(extensions.digest(convert_to(pg_get_functiondef(p.oid),'UTF8'),'sha256'),'hex') digest
  into private_function from pg_proc p where p.oid=to_regprocedure(candidate.signature);
  if not found or private_function.digest is distinct from candidate.digest
    or private_function.prosecdef is distinct from true
    or private_function.owner_name not in ('postgres','supabase_admin')
    or private_function.proconfig is distinct from array['search_path=pg_catalog, custodial_dr']::text[]
    or not has_function_privilege('supabase_admin',private_function.oid,'EXECUTE') then
   raise exception 'disaster fence privileged predecessor changed: %',candidate.signature;
  end if;
  if candidate.signature<>'custodial_dr.install_application_mutation_fences_after_ddl()'
    and (has_function_privilege('anon',private_function.oid,'EXECUTE')
      or has_function_privilege('authenticated',private_function.oid,'EXECUTE')
      or has_function_privilege('service_role',private_function.oid,'EXECUTE')) then
   raise exception 'disaster fence routine unexpectedly callable: %',candidate.signature;
  end if;
  if exists(select 1 from aclexplode(coalesce(private_function.proacl,acldefault('f',private_function.proowner))) acl
      left join pg_roles role_grantee on role_grantee.oid=acl.grantee
      where acl.privilege_type='EXECUTE'
       and (acl.grantee=0 and candidate.signature<>'custodial_dr.install_application_mutation_fences_after_ddl()'
         or acl.grantee<>0 and coalesce(role_grantee.rolname,'') not in ('postgres','supabase_admin')))
   or (candidate.signature<>'custodial_dr.install_application_mutation_fences_after_ddl()'
     and exists(select 1 from pg_roles role_grantee
      where role_grantee.rolname not in ('postgres','supabase_admin')
       and has_function_privilege(role_grantee.oid,private_function.oid,'EXECUTE'))) then
   raise exception 'disaster fence routine ACL changed: %',candidate.signature;
  end if;
 end loop;
 if (select count(*) from pg_event_trigger e where
   (e.evtname='custodial_dr_guard_application_ddl' and e.evtevent='ddl_command_start'
     and e.evtenabled='O' and e.evtfoid='custodial_dr.guard_application_ddl()'::regprocedure and e.evttags is null)
   or (e.evtname='custodial_dr_install_application_mutation_fences' and e.evtevent='ddl_command_end'
     and e.evtenabled='O' and e.evtfoid='custodial_dr.install_application_mutation_fences_after_ddl()'::regprocedure
     and e.evttags=array['CREATE TABLE','CREATE TABLE AS','ALTER TABLE']::text[]))<>2 then
  raise exception 'disaster fence event-trigger predecessor changed';
 end if;
end $preflight$;

-- This event-trigger-only helper inherited PostgreSQL's default PUBLIC
-- EXECUTE. Close that unrelated direct-call surface before invoking the
-- authenticated installer; the migration transaction rolls this back on fail.
revoke execute on function custodial_dr.install_application_mutation_fences_after_ddl()
 from public,anon,authenticated,service_role;
do $private_acl$
declare candidate record;private_function record;
begin
 for candidate in select signature from (values
  ('custodial_dr.acquire_application_mutation_fence()'),
  ('custodial_dr.guard_application_ddl()'),
  ('custodial_dr.guard_application_mutation()'),
  ('custodial_dr.install_application_mutation_fences()'),
  ('custodial_dr.install_application_mutation_fences_after_ddl()')
 ) wanted(signature) loop
  select p.oid,p.proacl,p.proowner into strict private_function from pg_proc p
   where p.oid=candidate.signature::regprocedure;
  if exists(select 1 from aclexplode(coalesce(private_function.proacl,acldefault('f',private_function.proowner))) acl
      left join pg_roles role_grantee on role_grantee.oid=acl.grantee
      where acl.privilege_type='EXECUTE'
       and (acl.grantee=0 or coalesce(role_grantee.rolname,'') not in ('postgres','supabase_admin')))
   or exists(select 1 from pg_roles role_grantee
      where role_grantee.rolname not in ('postgres','supabase_admin')
       and has_function_privilege(role_grantee.oid,private_function.oid,'EXECUTE')) then
   raise exception 'disaster fence private ACL changed: %',candidate.signature;
  end if;
 end loop;
end $private_acl$;

revoke execute on function public.evaluate_location_proximity_v2(text,text,numeric,numeric,numeric,text,text,text,timestamp with time zone)
 from service_role;

-- The source installation function is idempotent and covers every public
-- application table. Reconcile the fences explicitly before capturing their
-- exact definitions: an isolated restore may not have fired the DDL event
-- trigger while recreating the pending recurring tables.
select custodial_dr.install_application_mutation_fences();

lock table public.custodial_release_authority_restore_inventory in share row exclusive mode;
alter table public.custodial_release_authority_restore_inventory disable trigger trg_custodial_release_authority_restore_inventory_immutable;
do $capture$
declare obj record;definition text;existing_id uuid;next_order integer;affected integer;
 trigger_count integer:=0;fence_count integer:=0;existing_count integer:=0;added_count integer:=0;
begin
 -- Preserve each existing row's identity and replay position. New GPS columns
 -- and their bound constraint are independently recoverable, not only present
 -- in the table CREATE statement. The measurement core precedes the evaluator,
 -- and the evaluator precedes its SQL wrapper in the function bucket.
 for obj in select * from (values
  (1000,'relation','public.location_proximity_settings','e312e08a5c6bb2a538bb2f13fd128418c7eae110164ca6e10fec80f94ebd381a'),
  (200000,'column','public.location_proximity_settings:authority_radius_m','e398ac13f5b5c2f63f9e01aac69b97404485d3566dfdc9c8c92a320a7b076d58'),
  (200000,'column','public.location_proximity_settings:authority_surveyed_at','6e5342f29d3f8ba0e30959e99e1d41e1228277bf66c7c3b88bdfe32677b1520c'),
  (300000,'column_set','public.location_proximity_settings','6f7832f1d0dbce4ec3df23353ef40a740d4a9dae738fd19d651ba6180fec1734'),
  (500000,'constraint','public.location_proximity_settings:location_proximity_authority_radius_bound','f1492a175e016d528c744c5a81e605b040fbd131484563d65347bae78eac86c0')
 ) wanted(bucket,kind,identity,expected_digest) order by bucket,identity loop
  definition:=case obj.kind
   when 'relation' then public.custodial_release_authority_current_relation_definition(obj.identity)
   when 'column' then public.custodial_release_authority_current_column_definition(obj.identity)
   when 'column_set' then public.custodial_release_authority_current_column_set_definition(obj.identity)
   when 'constraint' then public.custodial_release_authority_current_constraint_definition(obj.identity) end;
  if definition is null then raise exception 'missing required recovery object %',obj.identity;end if;
  if public.static_weekly_digest_text(definition) is distinct from obj.expected_digest then
   raise exception 'refusing to capture changed GPS structure: %',obj.identity;end if;
  select inventory_id into existing_id from public.custodial_release_authority_restore_inventory
   where object_kind=obj.kind and object_identity=obj.identity;
  if found then
   update public.custodial_release_authority_restore_inventory set definition_sql=definition,
    definition_sha256=public.static_weekly_digest_text(definition),captured_at=statement_timestamp() where inventory_id=existing_id;
   existing_count:=existing_count+1;
  else
   select coalesce(max(restore_order),obj.bucket)+1 into next_order from public.custodial_release_authority_restore_inventory
    where restore_order>=obj.bucket and restore_order<obj.bucket+100000;
   if next_order>=obj.bucket+100000 then raise exception 'recovery bucket exhausted';end if;
   insert into public.custodial_release_authority_restore_inventory(restore_order,object_kind,object_identity,definition_sql,definition_sha256)
    values(next_order,obj.kind,obj.identity,definition,public.static_weekly_digest_text(definition));
   added_count:=added_count+1;
  end if;
 end loop;
 if existing_count+added_count<>5 then raise exception 'GPS structural inventory incomplete';end if;

 for obj in select * from (values
  ('public.evaluate_location_proximity_v2(text,text,numeric,numeric,numeric,text,text,text,timestamp with time zone)'::text,1),
  ('public.tool_evaluate_location_proximity_v2(text,text,numeric,numeric,numeric,text,text,text,timestamp with time zone)'::text,2)
 ) wanted(signature,ordinal) order by ordinal loop
  -- Use the identity which the health renderer will actually receive.
  for definition in select pg_get_functiondef(obj.signature::regprocedure) loop
   select inventory_id into existing_id from public.custodial_release_authority_restore_inventory
    where object_kind='function' and object_identity like '%(%' and to_regprocedure(object_identity)=obj.signature::regprocedure;
   if found then
    update public.custodial_release_authority_restore_inventory set definition_sql=definition,
     definition_sha256=public.static_weekly_digest_text(definition),captured_at=statement_timestamp() where inventory_id=existing_id;
   else
    select coalesce(max(restore_order),100000)+1 into next_order from public.custodial_release_authority_restore_inventory
     where restore_order>=100000 and restore_order<200000;
    if next_order>=200000 then raise exception 'function recovery bucket exhausted';end if;
    insert into public.custodial_release_authority_restore_inventory(restore_order,object_kind,object_identity,definition_sql,definition_sha256)
     values(next_order,'function',obj.signature::regprocedure::text,definition,public.static_weekly_digest_text(definition));
   end if;
  end loop;
  select inventory_id into existing_id from public.custodial_release_authority_restore_inventory
   where object_kind='grant' and object_identity like '%(%' and to_regprocedure(object_identity)=obj.signature::regprocedure;
  if found then
   select public.custodial_release_authority_current_grant_definition(object_identity) into definition
