-- Forward-only correction for two redundant, constraint-owned primary-key
-- index entries captured by the Issue and Event transition migrations. The
-- corresponding exact primary-key constraints remain in the restore inventory;
-- restoring either constraint recreates its backing index. Never drop the live
-- index, rewrite history, or broaden recovery rights to correct this catalog.
begin;
set local search_path = pg_catalog, public;

do $repair$
declare
  target record;
  live_index oid;
  live_constraint pg_constraint%rowtype;
  index_entry public.custodial_release_authority_restore_inventory%rowtype;
  constraint_entry public.custodial_release_authority_restore_inventory%rowtype;
  matched integer;
begin
  lock table public.custodial_release_authority_restore_inventory in share row exclusive mode;
  if not exists (
    select 1 from pg_trigger
    where tgrelid='public.custodial_release_authority_restore_inventory'::regclass
      and tgname='trg_custodial_release_authority_restore_inventory_immutable'
      and tgenabled='O'
  ) then
    raise exception 'release recovery inventory immutability is unavailable';
  end if;

  for target in
    select * from (values
      ('public.maintenance_ticket_outcome_history'::text, 'maintenance_ticket_outcome_history_pkey'::text),
      ('public.events_app_transition_receipts'::text, 'events_app_transition_receipts_pkey'::text)
    ) as expected(relation_identity,constraint_name)
  loop
    select c.* into strict live_constraint from pg_constraint c
    where c.conrelid=to_regclass(target.relation_identity)
      and c.conname=target.constraint_name and c.contype='p';
    live_index:=live_constraint.conindid;
    if live_index is null or live_index=0 or not exists (
      select 1 from pg_index pi join pg_class ix on ix.oid=pi.indexrelid
      join pg_namespace ns on ns.oid=ix.relnamespace
      where pi.indexrelid=live_index and pi.indrelid=live_constraint.conrelid
        and pi.indisprimary and pi.indisunique and ix.relkind='i'
        and ns.nspname='public' and ix.relname=target.constraint_name
    ) then
      raise exception 'expected primary-key backing index is not live: %.%',target.relation_identity,target.constraint_name;
    end if;

    select i.* into strict index_entry
    from public.custodial_release_authority_restore_inventory i
    where i.object_kind='index'
      and i.object_identity in (target.constraint_name,'public.'||target.constraint_name)
      and to_regclass(i.object_identity)=live_index;
    select i.* into strict constraint_entry
    from public.custodial_release_authority_restore_inventory i
    where i.object_kind='constraint'
      and to_regclass(split_part(i.object_identity,':',1))=live_constraint.conrelid
      and substr(i.object_identity,position(':' in i.object_identity)+1)=live_constraint.conname;

    if index_entry.definition_sha256<>public.static_weekly_digest_text(index_entry.definition_sql)
      or index_entry.definition_sql is distinct from public.custodial_release_authority_current_index_definition(index_entry.object_identity)
      or constraint_entry.definition_sha256<>public.static_weekly_digest_text(constraint_entry.definition_sql)
      or constraint_entry.definition_sql is distinct from public.custodial_release_authority_current_constraint_definition(constraint_entry.object_identity)
      or constraint_entry.definition_sql not like 'select public.custodial_release_authority_restore_constraint(%'
    then
      raise exception 'exact primary-key constraint/index recovery definitions do not match live catalog: %.%',target.relation_identity,target.constraint_name;
    end if;
  end loop;

  alter table public.custodial_release_authority_restore_inventory
    disable trigger trg_custodial_release_authority_restore_inventory_immutable;
  for target in
    select * from (values
      ('public.maintenance_ticket_outcome_history'::text, 'maintenance_ticket_outcome_history_pkey'::text),
      ('public.events_app_transition_receipts'::text, 'events_app_transition_receipts_pkey'::text)
    ) as expected(relation_identity,constraint_name)
  loop
    select c.conindid into strict live_index from pg_constraint c
    where c.conrelid=to_regclass(target.relation_identity)
      and c.conname=target.constraint_name and c.contype='p';
    delete from public.custodial_release_authority_restore_inventory i
    where i.object_kind='index'
      and i.object_identity in (target.constraint_name,'public.'||target.constraint_name)
      and to_regclass(i.object_identity)=live_index;
    get diagnostics matched=row_count;
    if matched<>1 then
      raise exception 'expected one redundant constraint-owned index entry: %.%',target.relation_identity,target.constraint_name;
    end if;
  end loop;
  alter table public.custodial_release_authority_restore_inventory
    enable trigger trg_custodial_release_authority_restore_inventory_immutable;
end $repair$;

commit;

-- CLI-created20261002123821, parent-reserved03150000. Accepted PC01/PC02 source only.
-- No runtime profile, sender/index/factory activation, or historical point conversion.
begin;
set local lock_timeout='5s';
set local statement_timeout='60s';

-- Interval metadata is evidence from the typed current native credential, NOT
-- qualification authority. Profiles are pinned natively and never supplied here.
create function public.custodial_native_provider_interval_observation(o jsonb,p_required boolean)
returns void language plpgsql immutable set search_path=pg_catalog,public as $fn$
declare field text; first_at timestamptz; last_at timestamptz;
begin
 if jsonb_typeof(o) is distinct from 'object' or
  (select array_agg(key order by key) from jsonb_object_keys(o) key) is distinct from
   array['boot_count','clock_profile_id','earliest_at','elapsed_realtime_ms','latest_at'] then
  raise exception 'exact native interval observation required' using errcode='22023';end if;
 foreach field in array array['boot_count','elapsed_realtime_ms'] loop
  if o->field is distinct from 'null'::jsonb and
   (jsonb_typeof(o->field) is distinct from 'number' or o->>field !~ '^(0|[1-9][0-9]{0,15})$'
    or (o->>field)::numeric>(case when field='boot_count' then 2147483647 else 9007199254740991 end)) then
   raise exception 'exact native interval counter required' using errcode='22023';end if;
 end loop;
 if o->'earliest_at'='null'::jsonb then
  if p_required is distinct from false or o->'latest_at' is distinct from 'null'::jsonb or o->'clock_profile_id' is distinct from 'null'::jsonb then
   raise exception 'complete native interval required' using errcode='22023';end if;
 else
  first_at:=public.custodial_native_provider_event_time(o->'earliest_at');last_at:=public.custodial_native_provider_event_time(o->'latest_at');
  if last_at<first_at or jsonb_typeof(o->'clock_profile_id') is distinct from 'string'
   or o->>'clock_profile_id' !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$' or o->'boot_count'='null'::jsonb or o->'elapsed_realtime_ms'='null'::jsonb then
   raise exception 'ordered qualified native interval evidence required' using errcode='22023';end if;
 end if;
end $fn$;
create function public.custodial_native_provider_observation_order(a jsonb,b jsonb)
returns boolean language sql immutable set search_path=pg_catalog as $fn$
 select case when a->'boot_count'='null'::jsonb or b->'boot_count'='null'::jsonb then true
  when (a->>'boot_count')::bigint>(b->>'boot_count')::bigint then false
  when a->'boot_count'=b->'boot_count' and a->'elapsed_realtime_ms'<>'null'::jsonb and b->'elapsed_realtime_ms'<>'null'::jsonb
   then (a->>'elapsed_realtime_ms')::bigint<=(b->>'elapsed_realtime_ms')::bigint
  else true end;
$fn$;

create or replace function public.custodial_native_provider_event_shape(p_event jsonb)
returns void language plpgsql immutable set search_path=pg_catalog,public as $fn$
declare field text;
begin
 if jsonb_typeof(p_event) is distinct from 'object' or
  (select array_agg(key order by key) from jsonb_object_keys(p_event) key) is distinct from
  array['action','admission_bounds','content_sha256','event_id','generation_id','notification_key','original_observation','principal_digest',
   'receipt_assignment_epoch','receipt_credential_id','receipt_device_id','receipt_employee_id','receipt_job_id','record_id','schema','token_digest']
  or p_event->>'schema' is distinct from 'custodial.native-provider-event.v2'
  or p_event->>'action' not in ('received','displayed','opened','acknowledged') then
  raise exception 'exact finite native event required' using errcode='22023';end if;
 foreach field in array array['action','schema','event_id','generation_id','receipt_credential_id','receipt_employee_id','receipt_job_id',
  'record_id','content_sha256','principal_digest','token_digest','notification_key','receipt_device_id'] loop
  if jsonb_typeof(p_event->field) is distinct from 'string' then raise exception 'native event string required' using errcode='22023';end if;
 end loop;
 foreach field in array array['event_id','generation_id','receipt_credential_id','receipt_employee_id','receipt_job_id'] loop
  if p_event->>field !~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then raise exception 'native event UUID required' using errcode='22023';end if;
 end loop;
 foreach field in array array['record_id','content_sha256','principal_digest','token_digest'] loop
  if p_event->>field !~ '^[0-9a-f]{64}$' then raise exception 'native event digest required' using errcode='22023';end if;
 end loop;
 if p_event->>'receipt_device_id' !~ '^KIOSK_(0[2-9]|10)$' or jsonb_typeof(p_event->'receipt_assignment_epoch') is distinct from 'number'
  or p_event->>'receipt_assignment_epoch' !~ '^[1-9][0-9]{0,15}$' or (p_event->>'receipt_assignment_epoch')::numeric>9007199254740991
  or length(p_event->>'notification_key') not between 1 and 1000 or p_event->>'notification_key' ~ '[[:cntrl:]]'
  or p_event->>'record_id'<>public.static_weekly_digest_text((p_event->>'generation_id')||E'\n'||(p_event->>'receipt_job_id')||E'\n'||(p_event->>'notification_key'))
 then raise exception 'native event identity required' using errcode='22023';end if;
 perform public.custodial_native_provider_interval_observation(p_event->'admission_bounds',true);
 perform public.custodial_native_provider_interval_observation(p_event->'original_observation',p_event->>'action'='displayed');
end $fn$;

create or replace function public.custodial_native_provider_events_at(p_credential uuid,p_credential_hash text,p_native_request uuid,
 p_attestation_digest text,p_body jsonb,p_test_at timestamptz)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $fn$
declare d public.devices%rowtype;c public.device_auth_credentials%rowtype;g public.employee_native_push_generations%rowtype;
 r public.employee_native_push_delivery_receipts%rowtype;prior public.employee_native_provider_events%rowtype;
 received public.employee_native_provider_events%rowtype;request public.employee_native_provider_event_requests%rowtype;
 e jsonb;first_event jsonb;payload jsonb;results jsonb:='[]';observed timestamptz;observed_last timestamptz;admitted timestamptz;admitted_last timestamptz;at_time timestamptz;
 other_event jsonb;field text;body_digest text;code text;replayed boolean;
begin
 perform public.custodial_begin_application_mutation();
 if p_credential is null or p_native_request is null or coalesce(p_credential_hash,'') !~ '^[0-9a-f]{64}$'
  or coalesce(p_attestation_digest,'') !~ '^[0-9a-f]{64}$' or jsonb_typeof(p_body) is distinct from 'object' or octet_length(p_body::text)>65536
  or (select array_agg(key order by key) from jsonb_object_keys(p_body) key) is distinct from array['events','schema']
  or p_body->>'schema' is distinct from 'custodial.native-provider-events.v2' or jsonb_typeof(p_body->'events') is distinct from 'array'
  or jsonb_array_length(p_body->'events') not between 1 and 16 then raise exception 'exact native event batch required' using errcode='22023';end if;
 first_event:=p_body->'events'->0;
 for e in select value from jsonb_array_elements(p_body->'events') loop
  perform public.custodial_native_provider_event_shape(e);
  foreach field in array array['receipt_credential_id','receipt_employee_id','receipt_device_id','receipt_assignment_epoch','principal_digest'] loop
   if e->field is distinct from first_event->field then raise exception 'one exact batch principal required' using errcode='22023';end if;
  end loop;
 end loop;
 if (select count(distinct x->>'event_id') from jsonb_array_elements(p_body->'events') x)<>jsonb_array_length(p_body->'events')
  or (select count(distinct (x->>'record_id',x->>'action')) from jsonb_array_elements(p_body->'events') x)<>jsonb_array_length(p_body->'events') then
  raise exception 'unique native events and transitions required' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select d0.* into d from public.devices d0 join public.device_auth_credentials c0 on c0.device_id=d0.id where c0.credential_id=p_credential for update of d0;
 select * into c from public.device_auth_credentials where credential_id=p_credential for update;
 perform 1 from public.employees where id=d.assigned_employee_id for share;
 perform 1 from public.employee_push_registrations where device_id=d.id order by registration_id for update;
 perform 1 from public.employee_native_push_generations where generation_id in(select (x->>'generation_id')::uuid from jsonb_array_elements(p_body->'events') x) order by generation_id for update;
 perform 1 from public.operational_notification_jobs where job_id in(select (x->>'receipt_job_id')::uuid from jsonb_array_elements(p_body->'events') x) order by job_id for update;
 perform 1 from public.employee_native_push_delivery_receipts where job_id in(select (x->>'receipt_job_id')::uuid from jsonb_array_elements(p_body->'events') x) order by job_id for update;
 at_time:=coalesce(p_test_at,clock_timestamp());
 if not isfinite(at_time) or d.id is null or d.active is not true or c.token_hash is distinct from p_credential_hash
  or c.confirmed_at is null or c.revoked_at is not null or c.expires_at<=at_time
  or first_event->>'receipt_credential_id' is distinct from c.credential_id::text
  or first_event->>'receipt_device_id' is distinct from d.device_id or first_event->>'receipt_employee_id' is distinct from d.assigned_employee_id::text
  or first_event->>'receipt_assignment_epoch' is distinct from d.assignment_epoch::text
  or not exists(select 1 from public.employees where id=d.assigned_employee_id and active and employee_code ~ '^EMP[0-9]+$') then
  raise exception 'current event credential required' using errcode='42501';end if;
 body_digest:=public.static_weekly_digest_text(p_body::text);
 select * into request from public.employee_native_provider_event_requests where native_request_id=p_native_request;
 if request.native_request_id is null then
  insert into public.employee_native_provider_event_requests values(p_native_request,p_credential,body_digest,p_attestation_digest,at_time);
 elsif request.credential_id<>p_credential or request.body_digest<>body_digest or request.attestation_digest<>p_attestation_digest then
  raise exception 'native request identity conflict' using errcode='23505';end if;
 -- Received first even if a durable batch was enumerated in another order.
 for e in select value from jsonb_array_elements(p_body->'events') order by value->>'record_id',
  case value->>'action' when 'received' then 0 when 'displayed' then 1 when 'opened' then 2 else 3 end loop
  code:=null;replayed:=false;
  select * into g from public.employee_native_push_generations where generation_id=(e->>'generation_id')::uuid;
  select * into r from public.employee_native_push_delivery_receipts where job_id=(e->>'receipt_job_id')::uuid;
  payload:=r.native_payload;
  if g.generation_id is null or g.device_id is distinct from d.id or g.device_identifier is distinct from d.device_id
   or g.credential_id is distinct from c.credential_id or g.employee_id is distinct from d.assigned_employee_id or g.assignment_epoch is distinct from d.assignment_epoch
   or g.principal_digest is distinct from e->>'principal_digest' or g.token_digest is distinct from e->>'token_digest' or g.revoked_at is not null
   or r.native_generation_id is distinct from g.generation_id or r.registration_id is distinct from g.registration_id
   or r.credential_id is distinct from c.credential_id or r.assignment_epoch is distinct from d.assignment_epoch
   or r.prepared_at<g.activated_at or r.prepared_at>at_time or (g.dispatch_retired_at is not null and r.prepared_at>g.dispatch_retired_at)
   or payload->>'schema' is distinct from 'custodial.native-location-payload.v2' then code:='native_provider_original_binding_invalid';end if;
  foreach field in array array['generation_id','receipt_job_id','notification_key','receipt_credential_id','receipt_employee_id','receipt_device_id',
   'receipt_assignment_epoch','principal_digest','token_digest','content_sha256'] loop
   if e->>field is distinct from payload->>field then code:='native_provider_original_binding_invalid';end if;
  end loop;
  select * into prior from public.employee_native_provider_events where event_id=(e->>'event_id')::uuid;
  if code is null and prior.event_id is not null then
   if prior.original_event<>e then code:='native_provider_event_conflict';else replayed:=true;end if;
  end if;
  if code is null and not replayed then
   if exists(select 1 from public.employee_native_provider_events where record_id=e->>'record_id' and action=e->>'action') then
    code:='native_provider_event_conflict';
   else
    admitted:=public.custodial_native_provider_event_time(e#>'{admission_bounds,earliest_at}');
    admitted_last:=public.custodial_native_provider_event_time(e#>'{admission_bounds,latest_at}');
    observed:=case when e#>'{original_observation,earliest_at}'='null'::jsonb then null else public.custodial_native_provider_event_time(e#>'{original_observation,earliest_at}') end;
    observed_last:=case when observed is null then null else public.custodial_native_provider_event_time(e#>'{original_observation,latest_at}') end;
    -- BOTH endpoints for admission; a cutoff-straddling interval grants nothing.
    -- Server receipt can tighten its own upper bound, not rewrite original evidence.
    if admitted<r.prepared_at or admitted_last>=r.native_valid_until or admitted>at_time or observed>at_time then code:='native_provider_observation_invalid';end if;
    if e->>'action'='received' then
     if observed>admitted_last or not public.custodial_native_provider_observation_order(e->'original_observation',e->'admission_bounds') then
      code:='native_provider_observation_invalid';end if;
    else
     select * into received from public.employee_native_provider_events where record_id=e->>'record_id' and action='received';
     if received.event_id is null then code:='native_provider_transition_pending';
     elsif received.original_event->>'schema' is distinct from 'custodial.native-provider-event.v2'
      or received.original_event->'admission_bounds'<>e->'admission_bounds' or received.original_event->>'content_sha256'<>e->>'content_sha256'
      or observed_last<admitted
      or not public.custodial_native_provider_observation_order(e->'admission_bounds',e->'original_observation') then code:='native_provider_observation_invalid';
     end if;
     if e->>'action'='displayed' and (observed is null or observed<r.prepared_at or observed_last>=r.native_valid_until) then
      code:='native_provider_observation_invalid';end if;
    end if;
   end if;
   if code is null then
    insert into public.employee_native_provider_events values((e->>'event_id')::uuid,e->>'record_id',e->>'action',g.generation_id,r.job_id,c.credential_id,
     e,at_time,p_native_request,p_attestation_digest) returning * into prior;
   end if;
  end if;
  if code is null and prior.action='acknowledged' then perform public.custodial_native_location_project_ack(prior.event_id,at_time);end if;
  if code is not null then results:=results||jsonb_build_array(jsonb_build_object('event_id',e->>'event_id','admitted_state','REJECTED','code',code));
  else results:=results||jsonb_build_array(prior.original_event||jsonb_build_object('schema','custodial.native-provider-event-receipt.v2',
   'admitted_state','ACCEPTED','server_received_at',public.custodial_native_location_utc(prior.server_received_at),'replayed',replayed));end if;
 end loop;
 return jsonb_build_object('ok',true,'data',jsonb_build_object('schema','custodial.native-provider-event-receipts.v2','results',results));
end $fn$;
create or replace function public.custodial_native_provider_events(p_credential uuid,p_credential_hash text,p_native_request uuid,p_attestation_digest text,p_body jsonb)
returns jsonb language sql security definer set search_path=pg_catalog,public as $fn$
 select public.custodial_native_provider_events_at(p_credential,p_credential_hash,p_native_request,p_attestation_digest,p_body,null);
$fn$;


-- Existing inventory holds current recipient/proof/registration/generation locks.
-- Its frozen scan server_now is retained byte-for-byte and NEVER reused as S.
-- Private test clocks are not granted to any runtime role.
create function public.custodial_native_provider_inventory_clock_at(p_credential uuid,p_credential_hash text,p_native_request uuid,
 p_attestation_digest text,p_body jsonb,p_test_at timestamptz,p_test_clock timestamptz)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $fn$
declare page jsonb;sampled_at timestamptz;expires timestamptz;
begin
 page:=public.custodial_native_location_inventory_at(p_credential,p_credential_hash,p_native_request,p_attestation_digest,p_body,p_test_at);
 if page->'ok' is distinct from 'true'::jsonb then return page;end if; -- Cursor rejection grants no clock.
 sampled_at:=coalesce(p_test_clock,clock_timestamp());
 select c.expires_at into strict expires from public.device_auth_credentials c where c.credential_id=p_credential;
 if not isfinite(sampled_at) or expires is null or expires<=sampled_at
  or (p_test_at is not null and sampled_at<p_test_at)
  or public.custodial_native_provider_event_time(page#>'{data,server_now}')>sampled_at then
  raise exception 'native inventory clock unavailable' using errcode='42501';end if;
 return page||jsonb_build_object('clock',jsonb_build_object('native_request_id',p_native_request::text,
  'server_now',public.custodial_native_location_utc(sampled_at),
  'valid_until',public.custodial_native_location_utc(least(sampled_at+interval '15 minutes',expires))));
end $fn$;
create function public.custodial_native_provider_inventory_clock(p_credential uuid,p_credential_hash text,p_native_request uuid,p_attestation_digest text,p_body jsonb)
returns jsonb language sql volatile security definer set search_path=pg_catalog,public as $fn$
 select public.custodial_native_provider_inventory_clock_at(p_credential,p_credential_hash,p_native_request,p_attestation_digest,p_body,null,null);
$fn$;

do $acl$ declare f regprocedure;begin
 for f in select p.oid::regprocedure from pg_proc p where p.pronamespace='public'::regnamespace and p.proname in ('custodial_native_provider_interval_observation','custodial_native_provider_observation_order','custodial_native_provider_event_shape','custodial_native_provider_events_at','custodial_native_provider_events','custodial_native_provider_inventory_clock_at','custodial_native_provider_inventory_clock') loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role,static_weekly_control_plane,static_weekly_release_operator,custodial_application_reader,static_weekly_runtime_20260823',f);
 end loop;
end $acl$;
grant execute on function public.custodial_native_provider_events(uuid,text,uuid,text,jsonb),
 public.custodial_native_provider_inventory_clock(uuid,text,uuid,text,jsonb) to service_role;
-- Old inventory is still a page-only proof, not a route clock fallback. The API
-- calls the new wrapper exclusively; historical point events remain immutable.
lock table public.custodial_release_authority_restore_inventory in share row exclusive mode;
do $recovery$ declare obj record;next_order integer;changed integer;begin
 if not exists(select 1 from pg_trigger where tgrelid='public.custodial_release_authority_restore_inventory'::regclass
  and tgname='trg_custodial_release_authority_restore_inventory_immutable' and tgenabled='O') then raise exception 'recovery immutability unavailable';end if;
 alter table public.custodial_release_authority_restore_inventory disable trigger trg_custodial_release_authority_restore_inventory_immutable;
 for obj in with funcs as(
  select p.oid,p.proname from pg_proc p where p.pronamespace='public'::regnamespace and p.proname in ('custodial_native_provider_interval_observation','custodial_native_provider_observation_order','custodial_native_provider_event_shape','custodial_native_provider_events_at','custodial_native_provider_events','custodial_native_provider_inventory_clock_at','custodial_native_provider_inventory_clock')
 ),objects as(
  select 100000 bucket,'function'::text kind,oid::regprocedure::text identity,pg_get_functiondef(oid) definition from funcs
  union all select 900000,'grant',oid::regprocedure::text,public.custodial_release_authority_current_grant_definition(oid::regprocedure::text) from funcs
 )select * from objects order by bucket,identity loop
  if obj.definition is null then raise exception 'missing interval recovery object %',obj.identity;end if;
  update public.custodial_release_authority_restore_inventory set definition_sql=obj.definition,definition_sha256=public.static_weekly_digest_text(obj.definition),captured_at=statement_timestamp()
   where object_kind=obj.kind and (object_identity=obj.identity or case when object_identity like '%(%' and obj.identity like '%(%'
    then to_regprocedure(object_identity)=to_regprocedure(obj.identity) else false end);
  get diagnostics changed=row_count;if changed>1 then raise exception 'duplicate interval recovery object %',obj.identity;end if;
  if changed=0 then
   select n into next_order from generate_series(obj.bucket+1,obj.bucket+99998) n
    where not exists(select 1 from public.custodial_release_authority_restore_inventory where restore_order=n) order by n limit 1;
   if next_order is null then raise exception 'interval recovery order exhausted';end if;
   insert into public.custodial_release_authority_restore_inventory(restore_order,object_kind,object_identity,definition_sql,definition_sha256)
    values(next_order,obj.kind,obj.identity,obj.definition,public.static_weekly_digest_text(obj.definition));
  end if;
 end loop;
 alter table public.custodial_release_authority_restore_inventory enable trigger trg_custodial_release_authority_restore_inventory_immutable;
end $recovery$;
commit;

-- Explicit optional-break choice for registered nonemployee capacity only.
-- Existing commands/employee lunch predicates and historical rows are intact.
begin;
do $patch$ declare body text;old text;new text;begin
 body:=pg_get_functiondef('public.static_weekly_assert_exception_payload(text,date,time without time zone,time without time zone,uuid,uuid,jsonb,uuid)'::regprocedure);
 old:=$s$array['slotId','shift','productiveCapacityProvenance','maxServiceEffortMinutes','maxServiceEffortProvenance','qualifications','qualificationProvenance','restrictions','restrictionProvenance','acceptedRouteAnchorLocationId','acceptedRouteProvenance'],'coverall availability');$s$;
 new:=$s$array['slotId','shift','productiveCapacityProvenance','maxServiceEffortMinutes','maxServiceEffortProvenance','qualifications','qualificationProvenance','restrictions','restrictionProvenance','acceptedRouteAnchorLocationId','acceptedRouteProvenance','breakChoice'],'coverall availability');
    if p_payload->'availability' ? 'breakChoice' then
      if p_payload#>'{availability,breakChoice}' is distinct from '"NONE"'::jsonb
       or not exists(select 1 from public.weekly_schedule_versions v
        cross join lateral jsonb_array_elements(v.draft_document#>'{authority,compilerInput,slots}') s
        where v.version_id=p_base_version_id and s->>'id'=p_payload#>>'{availability,slotId}'
         and s->>'kind'='CONTRACTOR_CAPACITY' and public.static_weekly_capacity_registered(s)) then
        raise exception using errcode='23514',message='Explicit no-break requires source-bound registered nonemployee capacity';
      end if;
    end if;$s$;
 if length(body)-length(replace(body,old,''))<>length(old) then raise exception 'Unexpected optional-break exact payload predecessor';end if;body:=replace(body,old,new);
 old:=$s$elsif p_exception_type in ('partial_absence','lunch') then$s$;
 new:=$s$elsif p_exception_type in ('partial_absence','lunch') then
    if p_exception_type='lunch' and exists(select 1 from public.weekly_schedule_exception_commands e
      where e.publication_id=p_publication_id and e.base_version_id=p_base_version_id and e.service_date=p_service_date
       and e.exception_type='cover_all' and e.payload_json#>>'{availability,slotId}'=p_payload->>'slotId'
       and e.payload_json#>>'{availability,breakChoice}'='NONE'
       and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id)) then
      raise exception using errcode='23514',message='Explicit no-break conflicts with a lunch; reverse and replace the dated engagement';end if;$s$;
 if length(body)-length(replace(body,old,''))<>length(old) then raise exception 'Unexpected lunch conflict predecessor';end if;body:=replace(body,old,new);
 old:=$s$not public.static_weekly_exception_slot_exists(p_base_version_id,p_service_date,v_lock->>'slotId',true)$s$;
 new:=$s$not (public.static_weekly_exception_slot_exists(p_base_version_id,p_service_date,v_lock->>'slotId',true)
       or exists(select 1 from public.weekly_schedule_versions v
        cross join lateral jsonb_array_elements(v.draft_document#>'{authority,compilerInput,slots}') s
        join public.weekly_schedule_exception_commands e on e.base_version_id=v.version_id
         and e.publication_id=p_publication_id and e.service_date=p_service_date and e.exception_type='cover_all'
         and e.payload_json#>>'{availability,slotId}'=s->>'id'
        where v.version_id=p_base_version_id and s->>'id'=v_lock->>'slotId'
         and s->>'kind'='CONTRACTOR_CAPACITY' and public.static_weekly_capacity_registered(s)
         and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id)))$s$;
 if length(body)-length(replace(body,old,''))<>length(old) then raise exception 'Unexpected typed manual correction predecessor';end if;body:=replace(body,old,new);execute body;

 body:=pg_get_functiondef('public.static_weekly_v4_begin_day_changes(date,date,uuid,uuid,jsonb,bigint,uuid,text)'::regprocedure);
 old:=$s$or v_child.request_canonical_json#>>'{payload,availability,slotId}' is distinct from v_operation->>'slotId'$s$;
 new:=$s$or v_child.request_canonical_json#>>'{payload,availability,slotId}' is distinct from v_operation->>'slotId'
         or v_child.request_canonical_json#>'{payload,availability,breakChoice}' is distinct from v_operation->'breakChoice'$s$;
 if length(body)-length(replace(body,old,''))<>length(old) then raise exception 'Unexpected optional-break receipt predecessor';end if;execute replace(body,old,new);

 body:=pg_get_functiondef('public.static_weekly_v8_assert_lunch_document(uuid,jsonb)'::regprocedure);
 old:=$s$where value->>'status'='working' and (nullif(value->>'incumbentPersonId','') is not null or value->>'ownerKind'='CONTRACTOR_CAPACITY');$s$;
 new:=$s$where value->>'status'='working' and (nullif(value->>'incumbentPersonId','') is not null or value->>'ownerKind'='CONTRACTOR_CAPACITY')
  and (value->>'ownerKind'='CONTRACTOR_CAPACITY' and value->>'breakChoice'='NONE' and value->'lunch'='null'::jsonb) is not true;$s$;
 if length(body)-length(replace(body,old,''))<>length(old) then raise exception 'Unexpected no-break loan inventory predecessor';end if;body:=replace(body,old,new);
 old:=$s$or (nullif(helper->>'incumbentPersonId','') is null and helper->>'ownerKind' is distinct from 'CONTRACTOR_CAPACITY') or helper#>>'{lunch,start}' is null
    or helper#>>'{lunch,end}' is null$s$;
 new:=$s$or (nullif(helper->>'incumbentPersonId','') is null and helper->>'ownerKind' is distinct from 'CONTRACTOR_CAPACITY')
    or ((helper#>>'{lunch,start}' is null or helper#>>'{lunch,end}' is null)
      and (helper->>'ownerKind'='CONTRACTOR_CAPACITY' and helper->>'breakChoice'='NONE' and helper->'lunch'='null'::jsonb) is not true)$s$;
 if length(body)-length(replace(body,old,''))<>length(old) then raise exception 'Unexpected no-break helper availability predecessor';end if;body:=replace(body,old,new);execute body;
end $patch$;

-- CREATE OR REPLACE retains each existing function's narrow ACL. Capture only
-- actual owning definition changes; no default grants or unrelated resets.
do $recovery$ declare obj record;changed integer;ord integer;begin
 alter table public.custodial_release_authority_restore_inventory disable trigger trg_custodial_release_authority_restore_inventory_immutable;
 for obj in select x.* from pg_proc p cross join lateral (
   select 800000 bucket,'function' kind,p.oid::regprocedure::text identity,pg_get_functiondef(p.oid) definition
   union all select 900000,'grant',p.oid::regprocedure::text,public.custodial_release_authority_current_grant_definition(p.oid::regprocedure::text)) x
  where p.pronamespace='public'::regnamespace and p.proname in('static_weekly_assert_exception_payload','static_weekly_v4_begin_day_changes','static_weekly_v8_assert_lunch_document') loop
  update public.custodial_release_authority_restore_inventory set definition_sql=obj.definition,
   definition_sha256=public.static_weekly_digest_text(obj.definition),captured_at=statement_timestamp()
   where object_kind=obj.kind and object_identity like '%(%' and to_regprocedure(object_identity)=to_regprocedure(obj.identity);
  get diagnostics changed=row_count;if changed>1 then raise exception 'Duplicate optional-break recovery function: %',obj.identity;end if;
  if changed=0 then
   select n into ord from generate_series(obj.bucket+1,obj.bucket+99999) n
    where not exists(select 1 from public.custodial_release_authority_restore_inventory where restore_order=n) order by n limit 1;
   if ord is null then raise exception 'Optional-break recovery order exhausted';end if;
   insert into public.custodial_release_authority_restore_inventory(restore_order,object_kind,object_identity,definition_sql,definition_sha256)
    values(ord,obj.kind,obj.identity,obj.definition,public.static_weekly_digest_text(obj.definition));
  end if;
 end loop;
 alter table public.custodial_release_authority_restore_inventory enable trigger trg_custodial_release_authority_restore_inventory_immutable;
end $recovery$;
commit;

-- Read-only source/recipient evidence for future native MESSAGE, SCHEDULE and
-- LUNCH kinds. This does not create a provider job, reservation or send right.
begin;
set local lock_timeout='5s';
set local statement_timeout='120s';

create function public.custodial_native_target_source_at(
 p_kind text,p_source_key uuid,p_employee_id uuid,p_generation_id uuid,p_at timestamptz
) returns jsonb language plpgsql stable security definer
set search_path=pg_catalog,public,extensions as $fn$
declare
 v_now timestamptz:=p_at;
 v_generation public.employee_native_push_generations%rowtype;
 v_registration public.employee_push_registrations%rowtype;
 v_device public.devices%rowtype;
 v_credential public.device_auth_credentials%rowtype;
 v_employee public.employees%rowtype;
 v_job public.operational_notification_jobs%rowtype;
 v_message record;
 v_occurrence public.weekly_schedule_occurrences%rowtype;
 v_authority record;
 v_document public.weekly_schedule_lunch_documents%rowtype;
 v_intent jsonb;
 v_loan jsonb;
 v_responsibility jsonb;
 v_availability jsonb;
 v_service_date date;
 v_scheduled_at timestamptz;
 v_valid_until timestamptz;
 v_source jsonb;
 v_recipient jsonb;
 v_status text;
begin
 if p_kind not in ('MESSAGE','SCHEDULE','LUNCH') or p_source_key is null
  or p_employee_id is null or p_generation_id is null or p_at is null or not isfinite(p_at) then
  raise exception using errcode='22023',message='exact native source kind, original key, employee and generation required';
 end if;
 select * into v_generation from public.employee_native_push_generations
  where generation_id=p_generation_id;
 if not found then
  return jsonb_build_object('schema','custodial.native-target-source.v1','kind',p_kind,
   'source_key',p_source_key,'status','TARGET_STALE','delivery_admitted',false);
 end if;
 select * into v_registration from public.employee_push_registrations
  where registration_id=v_generation.registration_id;
 select * into v_device from public.devices where id=v_generation.device_id;
 select * into v_credential from public.device_auth_credentials
  where credential_id=v_generation.credential_id;
 select * into v_employee from public.employees where id=p_employee_id;
 if v_generation.employee_id is distinct from p_employee_id
  or v_generation.dispatch_retired_at is not null or v_generation.revoked_at is not null
  or v_generation.activated_at>v_now or v_registration.registration_id is null
  or v_registration.active is not true or v_registration.revoked_at is not null
  or v_registration.device_id is distinct from v_generation.device_id
  or v_registration.credential_id is distinct from v_generation.credential_id
  or v_registration.employee_id is distinct from p_employee_id
  or v_registration.assignment_epoch is distinct from v_generation.assignment_epoch
  or v_registration.token_hash is distinct from v_generation.token_digest
  or v_device.id is null or v_device.active is not true
  or v_device.device_id is distinct from v_generation.device_identifier
  or v_device.assigned_employee_id is distinct from p_employee_id
  or v_device.assignment_epoch is distinct from v_generation.assignment_epoch
  or v_credential.credential_id is null or v_credential.device_id is distinct from v_device.id
  or v_credential.confirmed_at is null or v_credential.revoked_at is not null
  or v_credential.expires_at<=v_now or v_employee.id is null or v_employee.active is not true then
  return jsonb_build_object('schema','custodial.native-target-source.v1','kind',p_kind,
   'source_key',p_source_key,'status','TARGET_STALE','delivery_admitted',false);
 end if;
 v_recipient:=jsonb_build_object('employee_id',p_employee_id,'device_id',v_device.id,
  'device_identifier',v_device.device_id,'credential_id',v_credential.credential_id,
  'assignment_epoch',v_device.assignment_epoch,'generation_id',v_generation.generation_id,
  'principal_digest',v_generation.principal_digest,'token_digest',v_generation.token_digest);

 if p_kind='MESSAGE' then
  select * into v_job from public.operational_notification_jobs where job_id=p_source_key;
  if not found or v_job.job_type is distinct from 'employee_native_push'
   or v_job.job_key is distinct from 'employee-message-push:'||v_job.source_id::text||':'||v_credential.credential_id::text
   or v_job.status not in ('pending','leased')
   or v_job.payload_json->>'credential_id' is distinct from v_credential.credential_id::text
   or v_job.payload_json->>'employee_id' is distinct from p_employee_id::text
   or v_job.payload_json->>'device_id' is distinct from v_device.id::text
   or v_job.payload_json->>'device_identifier' is distinct from v_device.device_id
   or v_job.payload_json->>'assignment_epoch' is distinct from v_device.assignment_epoch::text
   or v_job.payload_json#>>'{data_json,kind}' is distinct from 'employee_message'
   or v_job.payload_json#>>'{data_json,message_id}' is distinct from v_job.source_id::text
   or v_job.payload_json#>>'{data_json,notification_key}' is distinct from 'message:'||v_job.source_id::text then
   v_status:='SOURCE_STALE';
  else
   select m.id,m.thread_id,m.sender_user_id,m.sent_at,m.body,m.metadata_json,
    recipient.id recipient_user_id,r.acknowledged_at
    into v_message
   from public.msg_messages m
   join public.msg_threads t on t.id=m.thread_id and t.is_active is true
    and t.system_key is distinct from 'ops_manager_shared_chat_v1'
   join public.msg_thread_participants tp on tp.thread_id=m.thread_id and tp.left_at is null
   join public.msg_users recipient on recipient.id=tp.user_id and recipient.is_active is true
    and recipient.employee_id=p_employee_id
   join public.msg_receipts r on r.message_id=m.id and r.user_id=recipient.id
   where m.id=v_job.source_id and m.is_deleted is false and m.sender_user_id<>recipient.id
    and m.sent_at<=v_now
    and r.acknowledged_at is null
    and not exists(select 1 from public.msg_message_deletions md
      where md.message_id=m.id and md.user_id=recipient.id)
    and not exists(select 1 from public.msg_thread_visibility visibility
      where visibility.thread_id=m.thread_id and visibility.user_id=recipient.id
       and (visibility.device_identifier is null
         or upper(btrim(visibility.device_identifier))=upper(btrim(v_device.device_id)))
       and coalesce(m.sent_at,m.created_at)<=visibility.hidden_before);
   if not found or v_job.payload_json#>>'{data_json,thread_id}' is distinct from v_message.thread_id::text then
    v_status:='SOURCE_STALE';
   else
    v_status:='SOURCE_ONLY_POLICY_MISSING';
    v_recipient:=v_recipient||jsonb_build_object('msg_user_id',v_message.recipient_user_id);
    v_source:=jsonb_build_object('source_id',v_message.id,'source_revision',
     public.static_weekly_digest_jsonb(jsonb_build_object('message_id',v_message.id,
      'thread_id',v_message.thread_id,'sender_user_id',v_message.sender_user_id,
      'sent_at',v_message.sent_at,'body',v_message.body,'metadata_json',v_message.metadata_json,
      'recipient_user_id',v_message.recipient_user_id)),
     'delivery_occurrence_id',v_job.job_id,'delivery_key',v_job.job_key,
     'job_status',v_job.status,'valid_from',v_message.sent_at,'valid_until',null);
   end if;
  end if;
 elsif p_kind='SCHEDULE' then
  select * into v_occurrence from public.weekly_schedule_occurrences
   where occurrence_id=p_source_key;
  if not found or v_occurrence.state is distinct from 'created'
   or v_occurrence.owner_person_id_snapshot is distinct from p_employee_id then
   v_status:='SOURCE_STALE';
  else
   select * into v_authority from public.static_weekly_v6_schedule_authority_state(v_occurrence.service_date);
   if v_authority.governed is not true or v_authority.projection_status is distinct from 'current'
    or v_authority.projection_id is distinct from v_occurrence.projection_id
    or v_authority.publication_id is distinct from v_occurrence.publication_id
    or v_authority.version_id is distinct from v_occurrence.version_id then
    v_status:='SOURCE_STALE';
   else
    v_status:='SOURCE_ONLY_POLICY_MISSING';
    v_source:=jsonb_build_object('source_id',v_occurrence.projection_id,
     'source_revision',v_authority.projection_authority_revision::text,
     'source_digest',v_occurrence.occurrence_digest,
     'publication_id',v_occurrence.publication_id,'version_id',v_occurrence.version_id,
     'service_date',v_occurrence.service_date,'assignment_occurrence_id',v_occurrence.occurrence_id,
     'delivery_occurrence_id',null,'delivery_key',null,
     'valid_from',null,'valid_until',null);
   end if;
  end if;
 else
  select * into v_job from public.operational_notification_jobs where job_id=p_source_key;
  if not found or v_job.job_type is distinct from 'employee_native_push'
   or v_job.status not in ('pending','leased')
   or v_job.payload_json->>'credential_id' is distinct from v_credential.credential_id::text
   or v_job.payload_json->>'employee_id' is distinct from p_employee_id::text
   or v_job.payload_json->>'device_id' is distinct from v_device.id::text
   or v_job.payload_json->>'device_identifier' is distinct from v_device.device_id
   or v_job.payload_json->>'assignment_epoch' is distinct from v_device.assignment_epoch::text
   or v_job.payload_json#>>'{data_json,kind}' is distinct from 'employee_lunch_coverage'
   or v_job.payload_json#>>'{data_json,projection_id}' is distinct from v_job.source_id::text then
   v_status:='SOURCE_STALE';
  else
   v_service_date:=(v_job.payload_json#>>'{data_json,service_date}')::date;
   select * into v_authority from public.static_weekly_v6_schedule_authority_state(v_service_date);
   if v_authority.governed is not true or v_authority.projection_status is distinct from 'current'
    or v_authority.projection_id is distinct from v_job.source_id then
    v_status:='SOURCE_STALE';
   else
    select * into v_document from public.weekly_schedule_lunch_documents
     where projection_id=v_authority.projection_id;
    if not found or v_document.document_identity is distinct from v_job.payload_json#>>'{data_json,document_identity}' then
     v_status:='SOURCE_STALE';
    else
     perform public.static_weekly_v8_assert_lunch_document(v_document.projection_id,v_document.document_json);
     select value into v_intent from jsonb_array_elements(v_document.document_json->'notification_intents')
      where value->>'notification_key'=v_job.payload_json#>>'{data_json,notification_key}'
       and value->>'service_date'=v_service_date::text;
     select value into v_loan from jsonb_array_elements(v_document.document_json->'loans')
      where value->>'loan_id'=v_intent->>'loan_id' and value->>'status'='PLANNED';
     select value into v_responsibility from jsonb_array_elements(v_document.document_json->'responsibilities')
      where value->>'loan_id'=v_intent->>'loan_id'
       and value->>'coverer_slot_id'=v_intent->>'coverer_slot_id'
       and value->>'coverer_person_id'=p_employee_id::text;
     select value into v_availability
      from public.weekly_schedule_compiled_projections projection,
       jsonb_array_elements(projection.projection_envelope#>'{authority,projectionAvailability}') value
      where projection.projection_id=v_authority.projection_id
       and value->>'serviceDate'=v_service_date::text
       and value->>'slotId'=v_intent->>'coverer_slot_id'
       and value->>'incumbentPersonId'=p_employee_id::text
       and value->>'status'='working';
     if v_intent is null or v_loan is null or v_responsibility is null or v_availability is null
      or v_job.job_key is distinct from 'employee-lunch-push:'||(v_intent->>'notification_key')||':'||v_credential.credential_id::text
      or v_job.payload_json#>>'{data_json,event}' is distinct from v_intent->>'event'
      or v_job.payload_json#>>'{data_json,loan_id}' is distinct from v_intent->>'loan_id'
      or v_job.payload_json#>>'{data_json,coverer_slot_id}' is distinct from v_intent->>'coverer_slot_id'
      or v_job.payload_json#>>'{data_json,scheduled_time}' is distinct from v_intent->>'scheduled_time'
      or v_job.payload_json#>>'{data_json,notification_key}' is distinct from v_intent->>'notification_key'
      or v_job.payload_json#>>'{data_json,service_date}' is distinct from v_intent->>'service_date'
      or v_intent->>'event' not in ('start','end') then
      v_status:='SOURCE_STALE';
     else
      v_scheduled_at:=(v_service_date+(v_intent->>'scheduled_time')::time) at time zone 'America/Chicago';
      v_valid_until:=(v_service_date+(case when v_intent->>'event'='start'
       then v_loan->>'coverage_end' else v_availability#>>'{shift,end}' end)::time)
       at time zone 'America/Chicago';
      if v_valid_until is null or v_valid_until<=v_scheduled_at or v_now>=v_valid_until
       or public.sch_service_date(v_now) is distinct from v_service_date then
       v_status:='SOURCE_EXPIRED';
      else
       v_status:='CURRENT_SOURCE_ONLY';
       v_source:=jsonb_build_object('source_id',v_document.projection_id,
        'source_revision',v_authority.projection_authority_revision::text,
        'source_digest',v_document.document_identity,
        'notification_key',v_intent->>'notification_key',
        'loan_id',v_intent->>'loan_id','event',v_intent->>'event',
        'coverer_slot_id',v_intent->>'coverer_slot_id',
        'service_date',v_service_date,
        'delivery_occurrence_id',v_job.job_id,'delivery_key',v_job.job_key,
        'job_status',v_job.status,'valid_from',v_scheduled_at,'valid_until',v_valid_until);
      end if;
     end if;
    end if;
   end if;
  end if;
 end if;
 return jsonb_build_object('schema','custodial.native-target-source.v1',
  'kind',p_kind,'source_key',p_source_key,'status',v_status,
  'delivery_admitted',false,'recipient',case when v_source is null then null else v_recipient end,
  'source',v_source);
end $fn$;

-- The only runtime entrypoint owns actual SQL time. The private time-parametric
-- core exists for deterministic disposable proof, not a caller-selected clock.
create function public.custodial_native_target_source(
 p_kind text,p_source_key uuid,p_employee_id uuid,p_generation_id uuid
) returns jsonb language sql stable security definer set search_path=pg_catalog,public as $fn$
 select public.custodial_native_target_source_at(p_kind,p_source_key,p_employee_id,p_generation_id,statement_timestamp());
$fn$;

revoke all on function public.custodial_native_target_source_at(text,uuid,uuid,uuid,timestamptz)
 from public,anon,authenticated,service_role,static_weekly_control_plane,
 static_weekly_release_operator,custodial_application_reader;
revoke all on function public.custodial_native_target_source(text,uuid,uuid,uuid)
 from public,anon,authenticated,service_role,static_weekly_control_plane,
 static_weekly_release_operator,custodial_application_reader;
grant execute on function public.custodial_native_target_source(text,uuid,uuid,uuid) to service_role;

do $surface$ declare definition text;begin
 definition:=pg_get_functiondef('public.custodial_release_canary_authority_surface()'::regprocedure);
 if (length(definition)-length(replace(definition,'  values','')))/length('  values')<>1 then
  raise exception 'native target-source canary seam missing';end if;
 execute replace(definition,'  values',
  '  values'||chr(10)||
  '    (''function'',''custodial_native_target_source(text,uuid,uuid,uuid)'',''private read-only native source/recipient projection''),');
end $surface$;

do $recovery$ declare obj record;ord integer;changed integer;begin
 alter table public.custodial_release_authority_restore_inventory
  disable trigger trg_custodial_release_authority_restore_inventory_immutable;
 for obj in
  select 100000 bucket,'function'::text kind,p.oid::regprocedure::text identity,
   pg_get_functiondef(p.oid) definition
   from pg_proc p where p.oid=any(array[
    'public.custodial_native_target_source_at(text,uuid,uuid,uuid,timestamptz)'::regprocedure,
    'public.custodial_native_target_source(text,uuid,uuid,uuid)'::regprocedure,
    'public.custodial_release_canary_authority_surface()'::regprocedure])
  union all
  select 900000,'grant',x.identity,
   public.custodial_release_authority_current_grant_definition(x.identity)
   from (values
    ('public.custodial_native_target_source_at(text,uuid,uuid,uuid,timestamptz)'),
    ('public.custodial_native_target_source(text,uuid,uuid,uuid)'),
    ('public.custodial_release_canary_authority_surface()')) x(identity)
 loop
  if obj.definition is null then raise exception 'native source recovery definition unavailable %',obj.identity;end if;
  update public.custodial_release_authority_restore_inventory
   set definition_sql=obj.definition,
    definition_sha256=public.static_weekly_digest_text(obj.definition),
    captured_at=statement_timestamp()
   where object_kind=obj.kind and (object_identity=obj.identity or
    (obj.kind in ('function','grant') and to_regprocedure(object_identity)=to_regprocedure(obj.identity)));
  get diagnostics changed=row_count;
  if changed>1 then raise exception 'duplicate native source recovery identity %',obj.identity;end if;
  if changed=0 then
   select n into ord from generate_series(obj.bucket+1,obj.bucket+99999) n
    where not exists(select 1 from public.custodial_release_authority_restore_inventory where restore_order=n)
    order by n limit 1;
   if ord is null then raise exception 'native source recovery order exhausted';end if;
   insert into public.custodial_release_authority_restore_inventory
    (restore_order,object_kind,object_identity,definition_sql,definition_sha256)
   values(ord,obj.kind,obj.identity,obj.definition,public.static_weekly_digest_text(obj.definition));
  end if;
 end loop;
 alter table public.custodial_release_authority_restore_inventory
  enable trigger trg_custodial_release_authority_restore_inventory_immutable;
end $recovery$;
commit;

-- Explicit source-scoped legacy capacity replacement. No old employee, slot,
-- incumbent, publication, device or protected Start/Finish row is rewritten.
-- Admission is transaction-owned and cannot commit without the complete
-- existing publication/projection/lunch receipt. This is not phone delivery.
begin;
set local lock_timeout='5s';
set local statement_timeout='30s';

create table public.static_weekly_capacity_source_previews (
 preview_id uuid primary key default gen_random_uuid(),
 manager_id uuid not null references public.ops_manager_managers(manager_id),
 source_publication_id uuid not null references public.weekly_schedule_publications(publication_id),
 expected_revision bigint not null,effective_start date not null,
 selection jsonb not null check(jsonb_typeof(selection)='array' and jsonb_array_length(selection)=8),
 basis_json jsonb not null,candidate_source jsonb not null,
 candidate_digest text not null check(candidate_digest~'^[0-9a-f]{64}$'),
 reason text not null check(length(btrim(reason)) between 1 and 500),
 created_at timestamptz not null default clock_timestamp(),
 expires_at timestamptz not null default clock_timestamp()+interval '10 minutes'
);
create table public.static_weekly_capacity_source_commands (
 operation_id uuid primary key,manager_id uuid not null references public.ops_manager_managers(manager_id),
 preview_id uuid not null unique references public.static_weekly_capacity_source_previews(preview_id),
 source_id uuid not null unique references public.static_weekly_authority_source_documents(source_id),
 request_digest text not null check(request_digest~'^[0-9a-f]{64}$'),
 owner_xid xid8 not null default pg_current_xact_id(),created_at timestamptz not null default clock_timestamp()
);
create table public.static_weekly_capacity_source_receipts (
 operation_id uuid primary key references public.static_weekly_capacity_source_commands(operation_id),
 publication_id uuid not null unique references public.weekly_schedule_publications(publication_id),
 projection_id uuid not null references public.weekly_schedule_compiled_projections(projection_id),
 receipt_json jsonb not null,receipt_digest text not null check(receipt_digest~'^[0-9a-f]{64}$'),
 created_at timestamptz not null default clock_timestamp()
);
create index capacity_source_preview_manager on public.static_weekly_capacity_source_previews(manager_id);
create index capacity_source_preview_publication on public.static_weekly_capacity_source_previews(source_publication_id);
create index capacity_source_command_manager on public.static_weekly_capacity_source_commands(manager_id);
create index capacity_source_receipt_projection on public.static_weekly_capacity_source_receipts(projection_id);
do $private$ declare rel text;begin
 foreach rel in array array['static_weekly_capacity_source_previews','static_weekly_capacity_source_commands','static_weekly_capacity_source_receipts'] loop
  execute format('alter table public.%I enable row level security',rel);
  execute format('alter table public.%I force row level security',rel);
  execute format('revoke all on table public.%I from public,anon,authenticated,service_role,custodial_application_reader,static_weekly_control_plane,static_weekly_release_operator,static_weekly_runtime_20260823',rel);
  execute format('create trigger capacity_source_immutable before update or delete on public.%I for each row execute function public.static_weekly_reject_update_delete()',rel);
 end loop;
end $private$;

create function public.static_weekly_capacity_source_locks() returns void
language plpgsql security definer set search_path=pg_catalog,public as $fn$
begin
 -- Existing common recurring lock FIRST. Then source/roster/catalog/device
 -- admission witnesses in fixed order. Core snapshots and history unchanged.
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 lock table public.weekly_roster_slots,public.weekly_roster_slot_incumbencies,
  public.weekly_roster_slot_incumbency_closures,public.weekly_roster_slot_staffing_states,
  public.static_weekly_authority_source_documents,public.static_weekly_contractor_capacity_registrations,
  public.weekly_schedule_publications,public.location_groups,public.location_group_memberships,public.locations,
  public.employees,public.devices in share mode;
end $fn$;

create function public.static_weekly_capacity_source_basis(p_manager uuid,p_publication uuid,p_start date,p_revision bigint)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $fn$
declare actor jsonb;source jsonb;roster jsonb;dependencies jsonb;old_people uuid[];findings jsonb;authority record;
begin
 perform public.static_weekly_v3_assert_control_plane();actor:=public.static_weekly_v3_manager_actor(p_manager);
 perform public.static_weekly_capacity_source_locks();
 if p_start is null or extract(isodow from p_start)<>1 or p_start<=public.sch_service_date(clock_timestamp())
  or p_revision is distinct from (select current_revision from public.static_weekly_schedule_control where singleton) then
  raise exception using errcode='40001',message='Capacity source preview requires exact current revision and a future complete Monday';end if;
 source:=public.static_weekly_v3_read_publication_source(p_publication,p_start);
 select * into strict authority from public.static_weekly_v6_schedule_authority_state(p_start);
 if authority.publication_id is distinct from p_publication then raise exception using errcode='40001',message='Exact effective source publication required';end if;
 select coalesce(array_agg(distinct (i->>'personId')::uuid),'{}'::uuid[]) into old_people
  from jsonb_array_elements(source#>'{compiler_input,slots}') s
  cross join lateral jsonb_array_elements(coalesce(s->'incumbencies','[]'::jsonb)) i
  where s->'contractorCapacity'='true'::jsonb and s->>'kind' is distinct from 'CONTRACTOR_CAPACITY';
 roster:=jsonb_build_object(
  'slots',coalesce((select jsonb_agg(to_jsonb(s) order by slot_id) from public.weekly_roster_slots s),'[]'::jsonb),
  'incumbencies',coalesce((select jsonb_agg(to_jsonb(s) order by incumbency_id) from public.weekly_roster_slot_incumbencies s),'[]'::jsonb),
  'closures',coalesce((select jsonb_agg(to_jsonb(s) order by incumbency_closure_id) from public.weekly_roster_slot_incumbency_closures s),'[]'::jsonb),
  'staffing',coalesce((select jsonb_agg(to_jsonb(s) order by staffing_state_id) from public.weekly_roster_slot_staffing_states s),'[]'::jsonb));
 dependencies:=jsonb_build_object(
  'catalog',public.place_source_manifest(),
  'employee_status',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'active',e.active,'display_name',e.display_name) order by e.id)
    from public.employees e where exists(select 1 from jsonb_array_elements(source#>'{compiler_input,slots}') s
      cross join lateral jsonb_array_elements(coalesce(s->'incumbencies','[]'::jsonb)) i where i->>'personId'=e.id::text)),'[]'::jsonb),
  'devices',coalesce((select jsonb_agg(to_jsonb(d) order by id) from public.devices d where assigned_employee_id=any(old_people)),'[]'::jsonb),
  'protected_sessions',coalesce((select jsonb_agg(to_jsonb(s) order by id) from public.sessions s where employee_id=any(old_people) and status in('active','pending_submit')),'[]'::jsonb),
  'protected_offline_contexts',coalesce((select jsonb_agg(to_jsonb(c) order by context_id) from public.custodial_offline_actor_contexts c where employee_id=any(old_people) and status='activated'),'[]'::jsonb),
  'registered_capacity',coalesce((select jsonb_agg(to_jsonb(c) order by capacity_slot_id) from public.static_weekly_contractor_capacity_registrations c),'[]'::jsonb));
 findings:='[]'::jsonb;
 if jsonb_array_length(dependencies->'devices')>0 then findings:=findings||'"LEGACY_CAPACITY_HAS_DEVICE_IDENTITY_REQUIRING_RECONCILIATION"'::jsonb;end if;
 if jsonb_array_length(dependencies->'protected_sessions')>0 or jsonb_array_length(dependencies->'protected_offline_contexts')>0 then findings:=findings||'"LEGACY_CAPACITY_HAS_PROTECTED_WORK_REQUIRING_RECONCILIATION"'::jsonb;end if;
 if jsonb_array_length(dependencies->'registered_capacity')>0 then findings:=findings||'"TYPED_POOL_ALREADY_REGISTERED_RECONCILE_EXISTING_SOURCE"'::jsonb;end if;
 return jsonb_build_object('manager_id',p_manager,'manager_name',actor->>'manager_name',
  'authority_revision',p_revision,'trusted_service_date',public.sch_service_date(clock_timestamp()),
  'source_id',source->'source_id','publication_id',source->'publication_id','current_publication_id',source->'publication_id',
  'version_id',source->'version_id','compiler_input',source->'compiler_input',
  'source_digest',public.static_weekly_digest_jsonb(source->'compiler_input'),
  'roster_digest',public.static_weekly_digest_jsonb(roster),'dependency_digest',public.static_weekly_digest_jsonb(dependencies),
  'all_slot_ids',coalesce((select jsonb_agg(slot_id::text order by slot_id) from public.weekly_roster_slots),'[]'::jsonb),
  'future_exception_count',(select count(*) from public.weekly_schedule_exception_commands where publication_id=p_publication and service_date>=p_start),
  'capacity_dependency_findings',findings);
end $fn$;

create function public.static_weekly_capacity_source_legacy_reference(p_value jsonb,p_ids text[])
returns boolean language plpgsql immutable set search_path=pg_catalog,public as $fn$
declare item jsonb;key text;begin
 if jsonb_typeof(p_value)='string' then return (p_value#>>'{}')=any(p_ids);
 elsif jsonb_typeof(p_value)='array' then
  for item in select value from jsonb_array_elements(p_value) loop
   if public.static_weekly_capacity_source_legacy_reference(item,p_ids) then return true;end if;
  end loop;
 elsif jsonb_typeof(p_value)='object' then
  for key,item in select * from jsonb_each(p_value) loop
   if key=any(p_ids) or public.static_weekly_capacity_source_legacy_reference(item,p_ids) then return true;end if;
  end loop;
 end if;return false;
end $fn$;

create function public.static_weekly_capacity_source_candidate(p_basis jsonb,p_selection jsonb,p_start date,p_version uuid,p_publication uuid)
returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $fn$
declare source jsonb:=p_basis->'compiler_input';candidate jsonb;version jsonb;slot jsonb;mapping jsonb;availability jsonb;
 slots jsonb:='[]';rows jsonb:='[]';old_ids text[];seen_old text[]:='{}';seen_new text[]:='{}';seen_codes text[]:='{}';
 ordinary_people text[];id text;new_id text;code text;
begin
 if source is null or jsonb_typeof(source->'slots') is distinct from 'array'
  or p_basis->'capacity_dependency_findings' is distinct from '[]'::jsonb
  or p_basis->>'future_exception_count'<>'0'
  or p_basis->>'source_digest' is distinct from public.static_weekly_digest_jsonb(source)
  or p_version is null or p_publication is null then raise exception using errcode='55000',message='Exact unconflicted server source basis required';end if;
 select array_agg(s->>'id' order by s->>'id') into old_ids from jsonb_array_elements(source->'slots') s where s->'contractorCapacity'='true'::jsonb;
 if cardinality(old_ids) is distinct from 8
  or (select count(*) from jsonb_array_elements(source->'slots') s where s->'contractorCapacity' is distinct from 'true'::jsonb)<>9
  or exists(select 1 from jsonb_array_elements(source->'slots') s where s->'contractorCapacity'='true'::jsonb and s->>'kind'='CONTRACTOR_CAPACITY') then
  raise exception using errcode='55000',message='Existing source does not contain the explicit nine-position/eight-legacy-capacity pool; reconcile actual source templates';end if;
 select coalesce(array_agg(distinct i->>'personId'),'{}'::text[]) into ordinary_people
  from jsonb_array_elements(source->'slots') s cross join lateral jsonb_array_elements(coalesce(s->'incumbencies','[]'::jsonb)) i
  where s->'contractorCapacity' is distinct from 'true'::jsonb;
 if exists(select 1 from jsonb_array_elements(source->'slots') s where s->>'id'=any(old_ids)
  and (jsonb_typeof(s->'incumbencies') is distinct from 'array' or jsonb_array_length(s->'incumbencies')=0
   or exists(select 1 from jsonb_array_elements(s->'incumbencies') i where i->>'personId'=any(ordinary_people)))) then
  raise exception using errcode='55000',message='Legacy capacity identity is absent or shared with a real employee position; explicit reconciliation required';end if;
 if p_selection is null or jsonb_typeof(p_selection)<>'array' or jsonb_array_length(p_selection)<>8 or octet_length(p_selection::text)>8192 then
  raise exception using errcode='22023',message='Exactly eight explicit old-slot/new-capacity/code mappings required';end if;
 for mapping in select value from jsonb_array_elements(p_selection) loop
  perform public.static_weekly_assert_exact_object(mapping,array['legacy_slot_id','new_capacity_id','capacity_code'],array['legacy_slot_id','new_capacity_id','capacity_code'],'capacity source mapping');
  perform public.static_weekly_v3_assert_uuid(mapping->'legacy_slot_id','legacy capacity slot');
  perform public.static_weekly_v3_assert_uuid(mapping->'new_capacity_id','new nonemployee capacity');
  id:=(mapping->>'legacy_slot_id')::uuid::text;new_id:=(mapping->>'new_capacity_id')::uuid::text;code:=mapping->>'capacity_code';
  if id<>mapping->>'legacy_slot_id' or new_id<>mapping->>'new_capacity_id' or not id=any(old_ids)
   or id=any(seen_old) or new_id=any(seen_new) or code=any(seen_codes) or code is null or code !~ '^CoverAll0[1-8]$'
   or exists(select 1 from public.weekly_roster_slots where slot_id=new_id::uuid) then
   raise exception using errcode='22023',message='Mapping must use each exact original UUID once, each new unused UUID once and each CoverAll01..08 code once';end if;
  seen_old:=array_append(seen_old,id);seen_new:=array_append(seen_new,new_id);seen_codes:=array_append(seen_codes,code);
 end loop;
 version:=source->'version';
 if public.static_weekly_capacity_source_legacy_reference(version-array['id','publicationId','effectiveStart','effectiveEnd','slotAvailability'],old_ids) then
  raise exception using errcode='55000',message='Accepted duties/origins/policy reference legacy capacity; explicit replacement-duty reconciliation required';end if;
 for slot in select value from jsonb_array_elements(source->'slots') loop
  if slot->>'id'=any(old_ids) then
   select value into strict mapping from jsonb_array_elements(p_selection) where value->>'legacy_slot_id'=slot->>'id';
   slot:=jsonb_build_object('id',mapping->>'new_capacity_id','capacityId',mapping->>'new_capacity_id','label',mapping->>'capacity_code',
     'kind','CONTRACTOR_CAPACITY','contractorCapacity',true,'incumbencies','[]'::jsonb,'contractorAvailability',slot->'contractorAvailability');
   perform public.static_weekly_capacity_assert_shape(slot);
  end if;slots:=slots||jsonb_build_array(slot);
 end loop;
 for availability in select value from jsonb_array_elements(version->'slotAvailability') loop
  if availability->>'slotId'=any(old_ids) then
   perform public.static_weekly_assert_exact_object(availability,array['slotId','dayOfWeek','status'],array['slotId','dayOfWeek','status'],'inactive legacy capacity');
   if availability->>'status'<>'unavailable' then raise exception using errcode='55000',message='Recurring legacy capacity is active; do not silently change eligibility';end if;
   select value into strict mapping from jsonb_array_elements(p_selection) where value->>'legacy_slot_id'=availability->>'slotId';
   availability:=jsonb_set(availability,'{slotId}',mapping->'new_capacity_id');
  end if;rows:=rows||jsonb_build_array(availability);
 end loop;
 version:=version||jsonb_build_object('id',p_version,'publicationId',p_publication,'effectiveStart',p_start,'effectiveEnd',null,'status','published','slotAvailability',rows);
 candidate:=source||jsonb_build_object('slots',slots,'version',version,'serviceDate',p_start);
 return candidate;
end $fn$;

create function public.static_weekly_capacity_source_preview_document(p public.static_weekly_capacity_source_previews)
returns jsonb language sql stable security definer set search_path=pg_catalog,public as $fn$
 select jsonb_build_object('schema','custodial.capacity-source-preview.v1','preview_id',p.preview_id,'manager_id',p.manager_id,
  'source_publication_id',p.source_publication_id,'expected_revision',p.expected_revision,'effective_start',p.effective_start,
  'selection',p.selection,'basis',p.basis_json,'candidate_source',p.candidate_source,'candidate_digest',p.candidate_digest,
  'reason',p.reason,'expires_at',p.expires_at,'admitted',false,'published',false,'affected_phones_updated',false,
  'historical_employee_rows_changed',false,'new_employee_rows',0)
$fn$;

-- Only the two membership-style collections may be permuted. Exact full
-- element JSONB + multiplicity is retained, with no drop/dedup/extra fields.
-- Everything else (including ordered routes/assignments/history) stays exact.
create function public.static_weekly_capacity_source_order_equivalent(p_raw jsonb,p_canonical jsonb)
returns boolean language plpgsql immutable set search_path=pg_catalog,public as $fn$
declare a jsonb;b jsonb;items jsonb;v jsonb;
begin
 if jsonb_typeof(p_raw) is distinct from 'object' or jsonb_typeof(p_canonical) is distinct from 'object'
  or jsonb_typeof(p_raw->'slots') is distinct from 'array' or jsonb_typeof(p_canonical->'slots') is distinct from 'array'
  or jsonb_typeof(p_raw#>'{version,slotAvailability}') is distinct from 'array'
  or jsonb_typeof(p_canonical#>'{version,slotAvailability}') is distinct from 'array' then return false;end if;
 a:=p_raw;b:=p_canonical;
 select coalesce(jsonb_agg(value order by value->>'id' collate "C",value::text collate "C"),'[]'::jsonb) into items from jsonb_array_elements(a->'slots');a:=jsonb_set(a,'{slots}',items);
 select coalesce(jsonb_agg(value order by value->>'id' collate "C",value::text collate "C"),'[]'::jsonb) into items from jsonb_array_elements(b->'slots');b:=jsonb_set(b,'{slots}',items);
 select coalesce(jsonb_agg(value order by (value->>'dayOfWeek')::integer,value->>'slotId' collate "C",value::text collate "C"),'[]'::jsonb) into items from jsonb_array_elements(a#>'{version,slotAvailability}');a:=jsonb_set(a,'{version,slotAvailability}',items);
 select coalesce(jsonb_agg(value order by (value->>'dayOfWeek')::integer,value->>'slotId' collate "C",value::text collate "C"),'[]'::jsonb) into items from jsonb_array_elements(b#>'{version,slotAvailability}');b:=jsonb_set(b,'{version,slotAvailability}',items);
 return a=b;
end $fn$;

create function public.static_weekly_capacity_source_preview(p_manager uuid,p_publication uuid,p_start date,p_revision bigint,p_selection jsonb,p_reason text,p_canonical_source jsonb)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $fn$
declare basis jsonb;candidate jsonb;preview public.static_weekly_capacity_source_previews%rowtype;
begin
 basis:=public.static_weekly_capacity_source_basis(p_manager,p_publication,p_start,p_revision);
 if p_reason is null or length(btrim(p_reason)) not between 1 and 500 then raise exception using errcode='22023',message='Explicit source transition reason required';end if;
 candidate:=public.static_weekly_capacity_source_candidate(basis,p_selection,p_start,
  (p_canonical_source#>>'{version,id}')::uuid,(p_canonical_source#>>'{version,publicationId}')::uuid);
 if not public.static_weekly_capacity_source_order_equivalent(candidate,p_canonical_source) then
  raise exception using errcode='23514',message='Canonical source may permute only exact slot/availability elements; no values, multiplicity or other array changes';end if;
 candidate:=p_canonical_source;
 insert into public.static_weekly_capacity_source_previews(manager_id,source_publication_id,expected_revision,effective_start,selection,basis_json,candidate_source,candidate_digest,reason)
 values(p_manager,p_publication,p_revision,p_start,p_selection,basis,candidate,public.static_weekly_digest_jsonb(candidate),p_reason) returning * into preview;
 return public.static_weekly_capacity_source_preview_document(preview);
end $fn$;

create function public.static_weekly_capacity_source_status(p_manager uuid,p_operation uuid)
returns jsonb language plpgsql volatile security definer set search_path=pg_catalog,public as $fn$
declare command public.static_weekly_capacity_source_commands%rowtype;receipt jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();perform public.static_weekly_v3_manager_actor(p_manager);
 -- A NOT_FOUND result must wait for an in-flight confirmation, not race its
 -- commit. VOLATILE permits a fresh snapshot after the authority lock wait.
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select * into command from public.static_weekly_capacity_source_commands where operation_id=p_operation;
 if not found then return jsonb_build_object('operation_id',p_operation,'state','NOT_FOUND','accepted',false);end if;
 if command.manager_id<>p_manager then raise exception using errcode='42501',message='Original named manager required';end if;
 select receipt_json into strict receipt from public.static_weekly_capacity_source_receipts where operation_id=p_operation;
 return receipt;
end $fn$;

create function public.static_weekly_capacity_source_begin(p_manager uuid,p_operation uuid,p_preview uuid)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $fn$
declare command public.static_weekly_capacity_source_commands%rowtype;preview public.static_weekly_capacity_source_previews%rowtype;
 basis jsonb;sid uuid:=gen_random_uuid();slot jsonb;actor jsonb;code text;request jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();actor:=public.static_weekly_v3_manager_actor(p_manager);
 perform public.static_weekly_capacity_source_locks();
 if p_operation is null or p_preview is null then raise exception using errcode='22023',message='Exact original operation and preview identities required';end if;
 select * into command from public.static_weekly_capacity_source_commands where operation_id=p_operation;
 if found then
  if command.manager_id<>p_manager or command.preview_id<>p_preview then raise exception using errcode='23505',message='Original manager, operation and complete preview required';end if;
  return jsonb_build_object('replayed',true,'receipt',public.static_weekly_capacity_source_status(p_manager,p_operation));end if;
 select * into preview from public.static_weekly_capacity_source_previews where preview_id=p_preview;
 if not found or preview.manager_id<>p_manager then raise exception using errcode='42501',message='Exact attributable preview required';end if;
 if preview.expires_at<=clock_timestamp() then raise exception using errcode='40001',message='Source preview expired; generate a new exact preview';end if;
 basis:=public.static_weekly_capacity_source_basis(p_manager,preview.source_publication_id,preview.effective_start,preview.expected_revision);
 if basis is distinct from preview.basis_json then raise exception using errcode='40001',message='Exact source/publication/roster/dependencies changed';end if;
 if not public.static_weekly_capacity_source_order_equivalent(preview.candidate_source,public.static_weekly_capacity_source_candidate(basis,preview.selection,preview.effective_start,
  (preview.candidate_source#>>'{version,id}')::uuid,(preview.candidate_source#>>'{version,publicationId}')::uuid))
  or preview.candidate_digest<>public.static_weekly_digest_jsonb(preview.candidate_source) then raise exception 'Stored source candidate integrity mismatch';end if;
 request:=jsonb_build_object('operation_id',p_operation,'manager_id',p_manager,'manager_name',actor->>'manager_name',
  'preview_id',p_preview,'basis',basis,'selection',preview.selection,'reason',preview.reason,'candidate_digest',preview.candidate_digest);
 perform public.custodial_begin_application_mutation();
 insert into public.static_weekly_authority_source_documents(source_id,canonical_source,source_digest,configured_by)
 values(sid,preview.candidate_source,preview.candidate_digest,'capacity-source-transition:'||p_operation);
 insert into public.static_weekly_capacity_source_commands(operation_id,manager_id,preview_id,source_id,request_digest)
 values(p_operation,p_manager,p_preview,sid,public.static_weekly_digest_jsonb(request));
 for slot in select value from jsonb_array_elements(preview.candidate_source->'slots') where value->>'kind'='CONTRACTOR_CAPACITY' loop
  code:='STATIC_'||upper(replace(slot->>'id','-',''));
  insert into public.weekly_roster_slots(slot_id,slot_code,slot_label,created_by_manager_id,created_by_manager_name_snapshot,content_digest)
  values((slot->>'id')::uuid,code,slot->>'label',p_manager,actor->>'manager_name',
   public.static_weekly_digest_jsonb(jsonb_build_object('source_id',sid,'slot_id',slot->>'id','slot_code',code,'slot_label',slot->>'label')));
  insert into public.static_weekly_contractor_capacity_registrations(capacity_slot_id,capacity_code,source_id,source_digest,slot_snapshot,slot_digest,registered_by_manager_id,manager_name_snapshot)
  values((slot->>'id')::uuid,slot->>'label',sid,preview.candidate_digest,slot,public.static_weekly_digest_jsonb(slot),p_manager,actor->>'manager_name');
 end loop;
 return public.static_weekly_capacity_source_preview_document(preview)||jsonb_build_object('source_id',sid,'replayed',false);
end $fn$;

create function public.static_weekly_capacity_source_assert_use(p_source uuid,p_manager uuid,p_key text,p_stage text)
returns void language plpgsql security definer set search_path=pg_catalog,public as $fn$
declare command public.static_weekly_capacity_source_commands%rowtype;
begin
 select * into command from public.static_weekly_capacity_source_commands where source_id=p_source;
 if not found or exists(select 1 from public.static_weekly_capacity_source_receipts where operation_id=command.operation_id) then return;end if;
 if command.owner_xid<>pg_current_xact_id() or command.manager_id<>p_manager or p_stage not in('draft','publish')
  or p_key is distinct from 'capacity-source:'||command.operation_id||':'||p_stage then
  raise exception using errcode='42501',message='Unaccepted source restricted to exact admitted manager/transaction/child operation';end if;
end $fn$;

create function public.static_weekly_capacity_source_assert_unchanged_draft(p_version uuid)
returns void language plpgsql security definer set search_path=pg_catalog,public as $fn$
declare command public.static_weekly_capacity_source_commands%rowtype;preview public.static_weekly_capacity_source_previews%rowtype;
 old_version uuid;old_facts jsonb;new_facts jsonb;old_capacities uuid[];new_capacities uuid[];
begin
 select c.* into command from public.static_weekly_capacity_source_commands c join public.weekly_schedule_versions v on v.authority_source_id=c.source_id where v.version_id=p_version;
 if not found or exists(select 1 from public.static_weekly_capacity_source_receipts where operation_id=command.operation_id) then return;end if;
 select * into strict preview from public.static_weekly_capacity_source_previews where preview_id=command.preview_id;
 select version_id into strict old_version from public.weekly_schedule_publications where publication_id=preview.source_publication_id;
 select array_agg((s->>'legacy_slot_id')::uuid),array_agg((s->>'new_capacity_id')::uuid) into old_capacities,new_capacities from jsonb_array_elements(preview.selection) s;
 select jsonb_agg(to_jsonb(a)-array['assignment_id','version_id','payload_json','authority_facts_json','content_digest','created_at'] order by day_of_week,work_id)
  into old_facts from public.weekly_schedule_slot_assignments a where version_id=old_version;
 select jsonb_agg(to_jsonb(a)-array['assignment_id','version_id','payload_json','authority_facts_json','content_digest','created_at'] order by day_of_week,work_id)
  into new_facts from public.weekly_schedule_slot_assignments a where version_id=p_version;
 if old_facts is distinct from new_facts then raise exception using errcode='55000',message='Capacity registration changed accepted ordinary ownership, work, windows or constraints';end if;
 select jsonb_agg(to_jsonb(a)-array['availability_id','version_id','content_digest','created_at'] order by slot_id,day_of_week)
  into old_facts from public.weekly_schedule_slot_availability a where version_id=old_version and not slot_id=any(old_capacities);
 select jsonb_agg(to_jsonb(a)-array['availability_id','version_id','content_digest','created_at'] order by slot_id,day_of_week)
  into new_facts from public.weekly_schedule_slot_availability a where version_id=p_version and not slot_id=any(new_capacities);
 if old_facts is distinct from new_facts then raise exception using errcode='55000',message='Capacity registration changed employee identity/workday/shift/lunch/restrictions';end if;
end $fn$;

create function public.static_weekly_capacity_source_finalize(p_manager uuid,p_operation uuid,p_publication uuid,p_projection uuid)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $fn$
declare command public.static_weekly_capacity_source_commands%rowtype;preview public.static_weekly_capacity_source_previews%rowtype;
 authority record;lunch public.weekly_schedule_lunch_documents%rowtype;receipt jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();perform public.static_weekly_v3_manager_actor(p_manager);
 select * into strict command from public.static_weekly_capacity_source_commands where operation_id=p_operation;
 if command.manager_id<>p_manager or command.owner_xid<>pg_current_xact_id() then raise exception using errcode='42501',message='Exact original source transaction required';end if;
 select * into strict preview from public.static_weekly_capacity_source_previews where preview_id=command.preview_id;
 if not exists(select 1 from public.weekly_schedule_publications p join public.weekly_schedule_versions v using(version_id)
  where p.publication_id=p_publication and p.actor_manager_id=p_manager and p.idempotency_key='capacity-source:'||p_operation||':publish'
   and v.authority_source_id=command.source_id and p.effective_start=preview.effective_start) then raise exception 'Exact admitted source publication receipt required';end if;
 select * into strict authority from public.static_weekly_v6_schedule_authority_state(preview.effective_start);
 select * into strict lunch from public.weekly_schedule_lunch_documents where projection_id=p_projection;
 if authority.publication_id is distinct from p_publication or authority.projection_id is distinct from p_projection
  or authority.projection_status is distinct from 'current' or lunch.accepted_by_manager_id is distinct from p_manager
  or not exists(select 1 from public.weekly_schedule_command_receipts where actor_manager_id=p_manager
   and command_type='materialize_projection' and idempotency_key='capacity-source:'||p_operation||':projection:'||preview.effective_start
   and response_json#>>'{data,projection_id}'=p_projection::text) then raise exception 'Complete current projection/lunch and original child receipt required';end if;
 receipt:=jsonb_build_object('schema','custodial.capacity-source-receipt.v1','state','ACCEPTED','accepted',true,
  'operation_id',p_operation,'manager_id',p_manager,'preview_id',preview.preview_id,'request_digest',command.request_digest,
  'source_id',command.source_id,'candidate_digest',preview.candidate_digest,'basis_source_digest',preview.basis_json->'source_digest',
  'basis_roster_digest',preview.basis_json->'roster_digest','basis_dependency_digest',preview.basis_json->'dependency_digest',
  'publication_id',p_publication,'projection_id',p_projection,'authority_revision',authority.projection_authority_revision,
  'effective_start',preview.effective_start,'selection',preview.selection,'historical_employee_rows_changed',false,
  'new_employee_rows',0,'manual_activation_required',true,'affected_phones_updated',false,'phone_delivery_state','PENDING');
 insert into public.static_weekly_capacity_source_receipts(operation_id,publication_id,projection_id,receipt_json,receipt_digest)
 values(p_operation,p_publication,p_projection,receipt,public.static_weekly_digest_jsonb(receipt));return receipt;
end $fn$;

create function public.static_weekly_capacity_source_require_receipt() returns trigger
language plpgsql security definer set search_path=pg_catalog,public as $fn$
begin
 if not exists(select 1 from public.static_weekly_capacity_source_receipts where operation_id=new.operation_id) then
  raise exception using errcode='23514',message='Capacity source admission cannot commit without complete publication/projection/lunch receipt';end if;return new;
end $fn$;
create constraint trigger capacity_source_complete after insert on public.static_weekly_capacity_source_commands
 deferrable initially deferred for each row execute function public.static_weekly_capacity_source_require_receipt();

-- Prove the exact predecessors BEFORE replacing any owning hook. Alias
-- normalization is allowed only for byte-proven same-OID stored semantics;
-- stale/mismatched definitions fail closed and need source reconciliation.
do $predecessors$ declare signature text;hook regprocedure;alias record;expected text;legacy_hash text;guard text;
 seam text:='perform public.static_weekly_v3_assert_control_plane();';begin
 foreach signature in array array[
  'public.static_weekly_v3_create_draft(date,text,jsonb,jsonb,jsonb,bigint,uuid,text,uuid)',
  'public.static_weekly_v3_publish_draft(uuid,bigint,bigint,uuid,text,text,uuid)',
  'public.static_weekly_v3_read_manager_snapshot_base(date)'] loop
  hook:=signature::regprocedure;
  for alias in select * from public.custodial_release_authority_restore_inventory
   where object_kind in('function','grant') and object_identity like '%(%'
    and position((select proname from pg_proc where oid=hook)||'(' in object_identity)>0 loop
   if to_regprocedure(alias.object_identity) is distinct from hook then
    raise exception 'Capacity hook recovery alias resolves to a different identity: %',alias.object_identity;end if;
   expected:=case when alias.object_kind='function' then pg_get_functiondef(hook)
    else public.custodial_release_authority_current_grant_definition(alias.object_identity) end;
   if alias.definition_sha256<>public.static_weekly_digest_text(alias.definition_sql) then
    raise exception 'Capacity hook stored predecessor integrity invalid: % %',alias.object_kind,alias.object_identity;end if;
   if alias.definition_sql is distinct from expected then
    -- Verified cd799f5 disposable pre-state records exactly two old aliases
    -- left by03030000's schema-qualified/unqualified identity split. Accept
    -- ONLY their known source hashes, then replay that migration's exact guard
    -- insertion and require complete byte equality to the LIVE predecessor.
    -- This is not a general stale-definition recapture or guard removal.
    select h,g into legacy_hash,guard from (values
     ('public.static_weekly_v3_create_draft(date,text,jsonb,jsonb,jsonb,bigint,uuid,text,uuid)',
      'd42f06e2c90931e2f532d89293927e7a5e1c8049bae1f68a1cacbdcec543482b',
      'perform public.place_operational_assert_source_use(p_source_id,p_manager_id,p_idempotency_key,''draft'');'),
     ('public.static_weekly_v3_publish_draft(uuid,bigint,bigint,uuid,text,text,uuid)',
      '8a87818d63aa3ecf2bc0d1a175608e5d3716d47465ae8862d122f2d9871a0c86',
      'perform public.place_operational_assert_source_use((select authority_source_id from public.weekly_schedule_versions where version_id=p_draft_version_id),p_manager_id,p_idempotency_key,''publish''); perform public.place_operational_assert_unchanged_draft(p_draft_version_id); if not exists(select 1 from public.weekly_schedule_command_receipts where actor_manager_id=p_manager_id and idempotency_key=p_idempotency_key) then perform public.place_operational_assert_accepted_names((select authority_source_id from public.weekly_schedule_versions where version_id=p_draft_version_id),(select effective_start from public.weekly_schedule_versions where version_id=p_draft_version_id)); end if;')) known(s,h,g)
     where s=signature;
    if alias.object_kind<>'function' or legacy_hash is null or alias.definition_sha256<>legacy_hash
     or length(alias.definition_sql)-length(replace(alias.definition_sql,seam,''))<>length(seam)
     or replace(alias.definition_sql,seam,seam||E'\n '||guard) is distinct from expected then
    raise exception 'Capacity hook stored predecessor drift requires reconciliation: % %',alias.object_kind,alias.object_identity;end if;
   end if;
  end loop;
 end loop;
end $predecessors$;

-- Existing source/publication guards gain only transaction-owned admission.
do $hooks$ declare item record;body text;old text;begin
 for item in select * from (values
  ('public.static_weekly_v3_create_draft(date,text,jsonb,jsonb,jsonb,bigint,uuid,text,uuid)',
   'perform public.static_weekly_capacity_source_assert_use(p_source_id,p_manager_id,p_idempotency_key,''draft'');'),
  ('public.static_weekly_v3_publish_draft(uuid,bigint,bigint,uuid,text,text,uuid)',
   'perform public.static_weekly_capacity_source_assert_use((select authority_source_id from public.weekly_schedule_versions where version_id=p_draft_version_id),p_manager_id,p_idempotency_key,''publish''); perform public.static_weekly_capacity_source_assert_unchanged_draft(p_draft_version_id);')) x(signature,guard) loop
  body:=pg_get_functiondef(item.signature::regprocedure);old:='perform public.static_weekly_v3_assert_control_plane();';
  if length(body)-length(replace(body,old,''))<>length(old) then raise exception 'Exact capacity source publisher guard seam required';end if;
  execute replace(body,old,old||' '||item.guard);
 end loop;
end $hooks$;

-- Future setup slots must not appear as ordinary vacant employees in the old
-- manager roster. Only an accepted (or this transaction's pending) replacement
-- source scopes the whole roster; unrelated existing publications keep their
-- original turnover/vacancy behavior. No historic employee is deactivated.
create function public.static_weekly_capacity_source_roster_visible(p_slot uuid,p_version uuid)
returns boolean language plpgsql stable security definer set search_path=pg_catalog,public as $fn$
declare included boolean;scoped boolean;
begin
 select exists(select 1 from public.weekly_schedule_versions v
  cross join lateral jsonb_array_elements(v.draft_document#>'{authority,compilerInput,slots}') s
  where v.version_id=p_version and s->>'id'=p_slot::text) into included;
 if exists(select 1 from public.static_weekly_contractor_capacity_registrations where capacity_slot_id=p_slot)
  and not included then return false;end if;
 select exists(select 1 from public.weekly_schedule_versions v
  join public.static_weekly_capacity_source_commands c on c.source_id=v.authority_source_id
  where v.version_id=p_version and (c.owner_xid=pg_current_xact_id()
   or exists(select 1 from public.static_weekly_capacity_source_receipts r where r.operation_id=c.operation_id))) into scoped;
 return not scoped or included;
end $fn$;
do $roster$ declare body text;seam text:='from public.weekly_roster_slots s;';begin
 body:=pg_get_functiondef('public.static_weekly_v3_read_manager_snapshot_base(date)'::regprocedure);
 if length(body)-length(replace(body,seam,''))<>length(seam) then raise exception 'Exact manager roster source seam required';end if;
 execute replace(body,seam,'from public.weekly_roster_slots s where public.static_weekly_capacity_source_roster_visible(s.slot_id,v_display_version_id);');
end $roster$;

-- No default grants, public constraint helper, or direct private table access.
do $acl$ declare fn record;begin
 for fn in select oid::regprocedure::text signature from pg_proc
  where pronamespace='public'::regnamespace and proname like 'static_weekly_capacity_source_%' loop
  execute 'revoke all on function '||fn.signature||' from public,anon,authenticated,service_role,custodial_application_reader,static_weekly_control_plane,static_weekly_release_operator,static_weekly_runtime_20260823';
 end loop;
end $acl$;
grant execute on function public.static_weekly_capacity_source_basis(uuid,uuid,date,bigint),
 public.static_weekly_capacity_source_preview(uuid,uuid,date,bigint,jsonb,text,jsonb),
 public.static_weekly_capacity_source_begin(uuid,uuid,uuid),
 public.static_weekly_capacity_source_status(uuid,uuid),
 public.static_weekly_capacity_source_finalize(uuid,uuid,uuid,uuid) to static_weekly_control_plane;

-- Capture only the owning private surface and the three exact forward hooks.
-- Normalize pre-existing regprocedure spelling instead of duplicate identities.
do $recovery$ declare obj record;ord integer;changed integer;begin
 alter table public.custodial_release_authority_restore_inventory disable trigger trg_custodial_release_authority_restore_inventory_immutable;
 for obj in select * from (
  select 100000 bucket,'function'::text kind,p.oid::regprocedure::text identity,pg_get_functiondef(p.oid) definition
   from pg_proc p where pronamespace='public'::regnamespace and (proname like 'static_weekly_capacity_source_%' or oid in(
    'public.static_weekly_v3_create_draft(date,text,jsonb,jsonb,jsonb,bigint,uuid,text,uuid)'::regprocedure,
    'public.static_weekly_v3_publish_draft(uuid,bigint,bigint,uuid,text,text,uuid)'::regprocedure,
    'public.static_weekly_v3_read_manager_snapshot_base(date)'::regprocedure))
  union all select 900000,'grant',p.oid::regprocedure::text,public.custodial_release_authority_current_grant_definition(p.oid::regprocedure::text)
   from pg_proc p where pronamespace='public'::regnamespace and (proname like 'static_weekly_capacity_source_%' or oid in(
    'public.static_weekly_v3_create_draft(date,text,jsonb,jsonb,jsonb,bigint,uuid,text,uuid)'::regprocedure,
    'public.static_weekly_v3_publish_draft(uuid,bigint,bigint,uuid,text,text,uuid)'::regprocedure,
    'public.static_weekly_v3_read_manager_snapshot_base(date)'::regprocedure))
  union all select x.* from unnest(array['public.static_weekly_capacity_source_previews','public.static_weekly_capacity_source_commands','public.static_weekly_capacity_source_receipts']) rel cross join lateral (
   select 1000,'relation'::text,rel,public.custodial_release_authority_current_relation_definition(rel)
   union all select 200000,'column',rel||':'||attname,public.custodial_release_authority_current_column_definition(rel||':'||attname) from pg_attribute where attrelid=rel::regclass and attnum>0 and not attisdropped
   union all select 300000,'column_set',rel,public.custodial_release_authority_current_column_set_definition(rel)
   union all select 400000,'relation_state',rel,public.custodial_release_authority_current_relation_state_definition(rel)
