 GET DIAGNOSTICS changed=ROW_COUNT;IF changed<>1 THEN RAISE EXCEPTION 'Canary grant representation update scope changed';END IF;
 ALTER TABLE public.custodial_release_authority_restore_inventory ENABLE TRIGGER trg_custodial_release_authority_restore_inventory_immutable;
 IF EXISTS(SELECT 1 FROM manager_recovery_targets t LEFT JOIN public.custodial_release_authority_restore_inventory i USING(object_kind,object_identity)
  WHERE i.definition_sql IS DISTINCT FROM t.definition_sql OR i.definition_sha256 IS DISTINCT FROM t.definition_sha256) THEN
  RAISE EXCEPTION 'Manager recovery readback does not match the exact targets';END IF;
 IF EXISTS(SELECT u.* FROM manager_unrelated_recovery u WHERE NOT(u.object_kind IN ('function','grant') AND u.object_identity='custodial_release_canary_authority_surface()') AND NOT EXISTS(SELECT 1 FROM manager_recovery_identity_corrections c WHERE c.kind=u.object_kind AND c.old_identity=u.object_identity)
   EXCEPT SELECT * FROM public.custodial_release_authority_restore_inventory)
  OR EXISTS(SELECT i.* FROM public.custodial_release_authority_restore_inventory i WHERE NOT(i.object_kind IN ('function','grant') AND i.object_identity='custodial_release_canary_authority_surface()')
   AND NOT EXISTS(SELECT 1 FROM manager_recovery_targets t WHERE t.object_kind=i.object_kind AND t.object_identity=i.object_identity)
   AND NOT EXISTS(SELECT 1 FROM manager_recovery_identity_corrections c WHERE c.kind=i.object_kind AND c.identity=i.object_identity)
   EXCEPT SELECT * FROM manager_unrelated_recovery) THEN RAISE EXCEPTION 'Unrelated recovery bindings changed';END IF;
 IF EXISTS(SELECT 1 FROM manager_recovery_identity_corrections c LEFT JOIN public.custodial_release_authority_restore_inventory i ON i.object_kind=c.kind AND i.object_identity=c.identity
  WHERE i.restore_order IS DISTINCT FROM c.restore_order OR i.definition_sql IS DISTINCT FROM c.definition_sql OR i.definition_sha256 IS DISTINCT FROM c.sha256) THEN
  RAISE EXCEPTION 'Approved-initial recovery identities did not converge';END IF;
 IF EXISTS(SELECT 1 FROM manager_recovery_expected e WHERE NOT EXISTS(SELECT 1 FROM public.custodial_release_canary_authority_surface() s WHERE s.object_kind='function' AND s.object_identity=e.identity)
   OR NOT EXISTS(SELECT 1 FROM public.custodial_release_canary_authority_surface() s WHERE s.object_kind='grant' AND s.object_identity=e.identity)) THEN
  RAISE EXCEPTION 'Manager canary surface is incomplete';END IF;
 IF (SELECT max(restore_order) FROM public.custodial_release_authority_restore_inventory i JOIN manager_recovery_targets t USING(object_kind,object_identity) WHERE i.object_kind='function')
  >=(SELECT min(restore_order) FROM public.custodial_release_authority_restore_inventory i JOIN manager_recovery_targets t USING(object_kind,object_identity) WHERE i.object_kind='grant') THEN
  RAISE EXCEPTION 'Manager recovery functions must be restored before their grants';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.custodial_release_authority_restore_inventory'::regclass
  AND tgname='trg_custodial_release_authority_restore_inventory_immutable' AND tgenabled='O') THEN RAISE EXCEPTION 'Manager recovery guard was not restored';END IF;
END $bind$;
COMMIT;

-- Bounded contractor additions share the existing absence transaction.
-- Preserve the v1 validator for older releases and rollback compatibility.
BEGIN;
CREATE OR REPLACE FUNCTION public.custodial_authorize_coverage_operations_v2(
 p_manager_id uuid,p_credential_id uuid,p_device_id text,p_session_access text,
 p_service_date date,p_publication_id uuid,p_operations jsonb
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO pg_catalog,public
AS $fn$
DECLARE actor jsonb; item jsonb; kind text; source jsonb; slot_id text;
 ordinary jsonb := '[]'::jsonb; capacity jsonb; lunch jsonb;
 shift_start time; shift_end time; lunch_start time; lunch_end time;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();
 actor:=public.custodial_action_actor_v1(p_manager_id,p_credential_id,p_device_id,p_session_access,'manage_absences');
 IF (actor->>'owner')::boolean THEN RETURN actor; END IF;
 IF jsonb_typeof(p_operations) IS DISTINCT FROM 'array' OR jsonb_array_length(p_operations) NOT BETWEEN 1 AND 25 THEN
  RAISE EXCEPTION USING errcode='22023',message='One to 25 coverage operations are required';
 END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_operations) LOOP
  kind:=item->>'exceptionType';
  IF item->>'operation'='cover_all' THEN
   IF item-ARRAY['operation','slotId','shift','reason']<>'{}'::jsonb
     OR jsonb_typeof(item->'shift') IS DISTINCT FROM 'object'
     OR (item->'shift')-ARRAY['start','end']<>'{}'::jsonb
     OR coalesce(item#>>'{shift,start}','')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$'
     OR coalesce(item#>>'{shift,end}','')!~'^(([01][0-9]|2[0-3]):[0-5][0-9]|24:00)$' THEN
    RAISE EXCEPTION USING errcode='42501',message='CoverAll requires one explicit valid shift';
   END IF;
   slot_id:=item->>'slotId';
   IF source IS NULL THEN source:=public.static_weekly_v3_read_publication_source(p_publication_id,p_service_date); END IF;
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(source#>'{compiler_input,slots}') s
      WHERE s->>'id'=slot_id AND s->>'contractorCapacity'='true'
      AND EXISTS(SELECT 1 FROM jsonb_array_elements(s->'contractorAvailability') a
       WHERE (a->>'dayOfWeek')::integer=extract(dow FROM p_service_date)::integer)) THEN
    RAISE EXCEPTION USING errcode='42501',message='CoverAll must use registered contractor capacity on this date';
   END IF;
   IF (SELECT count(*) FROM jsonb_array_elements(p_operations) x WHERE x->>'operation'='cover_all' AND x->>'slotId'=slot_id)<>1
     OR (SELECT count(*) FROM jsonb_array_elements(p_operations) x WHERE x->>'operation'='exception' AND x->>'exceptionType'='lunch' AND x#>>'{payload,slotId}'=slot_id)<>1 THEN
    RAISE EXCEPTION USING errcode='42501',message='Each CoverAll addition requires exactly one recorded lunch';
   END IF;
   SELECT x INTO lunch FROM jsonb_array_elements(p_operations) x WHERE x->>'operation'='exception' AND x->>'exceptionType'='lunch' AND x#>>'{payload,slotId}'=slot_id;
   shift_start:=(item#>>'{shift,start}')::time;shift_end:=(item#>>'{shift,end}')::time;
   IF coalesce(lunch->>'startsAt','')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$'
     OR coalesce(lunch->>'endsAt','')!~'^(([01][0-9]|2[0-3]):[0-5][0-9]|24:00)$' THEN
    RAISE EXCEPTION USING errcode='42501',message='CoverAll lunch requires actual start and end times';
   END IF;
   lunch_start:=(lunch->>'startsAt')::time;lunch_end:=(lunch->>'endsAt')::time;
   IF shift_start>=shift_end OR lunch_start<shift_start OR lunch_end>shift_end OR lunch_end-lunch_start<>interval '1 hour' THEN
    RAISE EXCEPTION USING errcode='42501',message='CoverAll lunch must be one hour within the recorded shift';
   END IF;
  ELSIF item->>'operation'='exception' AND kind='lunch' THEN
   IF (item->'payload')-ARRAY['slotId']<>'{}'::jsonb OR item->>'reversesExceptionId' IS NOT NULL
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_operations) x WHERE x->>'operation'='cover_all' AND x->>'slotId'=item#>>'{payload,slotId}') THEN
    RAISE EXCEPTION USING errcode='42501',message='Delegated lunch must belong to the CoverAll addition in this batch';
   END IF;
  ELSE
   ordinary:=ordinary||jsonb_build_array(item);
  END IF;
 END LOOP;
 IF jsonb_array_length(ordinary)>0 THEN
  PERFORM public.custodial_authorize_absence_operations_v1(p_manager_id,p_credential_id,p_device_id,p_session_access,p_service_date,p_publication_id,ordinary);
 END IF;
 RETURN actor;
END $fn$;
REVOKE ALL ON FUNCTION public.custodial_authorize_coverage_operations_v2(uuid,uuid,text,text,date,uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.custodial_authorize_coverage_operations_v2(uuid,uuid,text,text,date,uuid,jsonb) TO static_weekly_control_plane;
COMMIT;

-- Preserve the exact already-applied compatibility function and its denied
-- browser/service grants during recovery. Does not replace the newer scheduler.
BEGIN;
SET LOCAL lock_timeout='5s';SET LOCAL statement_timeout='30s';SET LOCAL search_path=pg_catalog,public,extensions;
LOCK TABLE public.custodial_release_authority_restore_inventory IN ACCESS EXCLUSIVE MODE;
CREATE TEMP TABLE preserved_coverall_unrelated ON COMMIT DROP AS
 SELECT * FROM public.custodial_release_authority_restore_inventory;
DO $bind$
DECLARE signature constant text:='custodial_authorize_coverage_operations_v2(uuid,uuid,text,text,date,uuid,jsonb)';function_oid oid;actual text;grant_sql text;old_surface text;new_surface text;
 current_saved public.custodial_release_authority_restore_inventory%ROWTYPE;next_order integer;changed integer;
BEGIN
 function_oid:=to_regprocedure('public.'||signature);
 IF function_oid IS NULL OR public.static_weekly_digest_text(pg_get_functiondef(function_oid))<>'5bdb1a0874cccc02f6612a04277caa774cc8e232313dafd4dfc6bfe19d97cdf8' THEN
  RAISE EXCEPTION 'Applied compatibility validator differs from reviewed source';END IF;
 IF has_function_privilege('anon',function_oid,'EXECUTE') OR has_function_privilege('authenticated',function_oid,'EXECUTE')
  OR has_function_privilege('service_role',function_oid,'EXECUTE') OR NOT has_function_privilege('static_weekly_control_plane',function_oid,'EXECUTE') THEN
  RAISE EXCEPTION 'Applied compatibility grants differ from the admitted source';END IF;
 IF EXISTS(SELECT 1 FROM public.custodial_release_authority_restore_inventory WHERE object_kind IN ('function','grant') AND object_identity=signature) THEN
  RAISE EXCEPTION 'Compatibility validator recovery was already captured; reconcile source';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.custodial_release_authority_restore_inventory'::regclass AND tgname='trg_custodial_release_authority_restore_inventory_immutable' AND tgenabled='O') THEN RAISE EXCEPTION 'Inventory immutability guard missing';END IF;
 old_surface:=pg_get_functiondef('public.custodial_release_canary_authority_surface()'::regprocedure);
 IF public.static_weekly_digest_text(old_surface)<>'f877d8cacc8090426fb3fef36a2219aa6010ae203a53a7f5def0782a707e77c7' THEN RAISE EXCEPTION 'Unexpected canary predecessor';END IF;
 SELECT * INTO STRICT current_saved FROM public.custodial_release_authority_restore_inventory WHERE object_kind='function' AND object_identity='custodial_release_canary_authority_surface()';
 IF current_saved.definition_sql IS DISTINCT FROM old_surface OR current_saved.definition_sha256<>'f877d8cacc8090426fb3fef36a2219aa6010ae203a53a7f5def0782a707e77c7' THEN RAISE EXCEPTION 'Saved canary predecessor changed';END IF;
 grant_sql:=public.custodial_release_authority_current_grant_definition(signature);IF grant_sql IS NULL THEN RAISE EXCEPTION 'Grant serializer unavailable';END IF;
 new_surface:=replace(old_surface,'  values',E'  values\n'||$entries$    ('function','custodial_authorize_coverage_operations_v2(uuid,uuid,text,text,date,uuid,jsonb)','preserve separately applied CoverAll compatibility validator'),
    ('grant','custodial_authorize_coverage_operations_v2(uuid,uuid,text,text,date,uuid,jsonb)','preserve separately applied CoverAll compatibility validator'),
$entries$);
 IF public.static_weekly_digest_text(new_surface)<>'78bf7e443aeeeed42b5a7129678bd12d97f26fa43bce714b53f7199991c451fc' THEN RAISE EXCEPTION 'Derived canary target differs';END IF;
 EXECUTE new_surface;
 IF public.static_weekly_digest_text(pg_get_functiondef('public.custodial_release_canary_authority_surface()'::regprocedure))<>'78bf7e443aeeeed42b5a7129678bd12d97f26fa43bce714b53f7199991c451fc' THEN RAISE EXCEPTION 'Installed canary target differs';END IF;
 ALTER TABLE public.custodial_release_authority_restore_inventory DISABLE TRIGGER trg_custodial_release_authority_restore_inventory_immutable;
 SELECT max(restore_order)+1 INTO next_order FROM public.custodial_release_authority_restore_inventory WHERE object_kind='function';
 actual:=pg_get_functiondef(function_oid);
 INSERT INTO public.custodial_release_authority_restore_inventory(restore_order,object_kind,object_identity,definition_sql,definition_sha256) VALUES(next_order,'function',signature,actual,public.static_weekly_digest_text(actual));
 SELECT max(restore_order)+1 INTO next_order FROM public.custodial_release_authority_restore_inventory WHERE object_kind='grant';
 INSERT INTO public.custodial_release_authority_restore_inventory(restore_order,object_kind,object_identity,definition_sql,definition_sha256) VALUES(next_order,'grant',signature,grant_sql,public.static_weekly_digest_text(grant_sql));
 UPDATE public.custodial_release_authority_restore_inventory SET definition_sql=new_surface,definition_sha256='78bf7e443aeeeed42b5a7129678bd12d97f26fa43bce714b53f7199991c451fc',captured_at=statement_timestamp()
 WHERE inventory_id=current_saved.inventory_id AND definition_sha256='f877d8cacc8090426fb3fef36a2219aa6010ae203a53a7f5def0782a707e77c7';
 GET DIAGNOSTICS changed=ROW_COUNT;IF changed<>1 THEN RAISE EXCEPTION 'Canary update scope changed';END IF;
 ALTER TABLE public.custodial_release_authority_restore_inventory ENABLE TRIGGER trg_custodial_release_authority_restore_inventory_immutable;
 IF EXISTS(SELECT u.* FROM preserved_coverall_unrelated u WHERE u.inventory_id<>current_saved.inventory_id EXCEPT SELECT * FROM public.custodial_release_authority_restore_inventory)
  OR EXISTS(SELECT i.* FROM public.custodial_release_authority_restore_inventory i WHERE i.inventory_id<>current_saved.inventory_id AND NOT(i.object_kind IN ('function','grant') AND i.object_identity=signature) EXCEPT SELECT * FROM preserved_coverall_unrelated) THEN RAISE EXCEPTION 'Unrelated recovery inventory changed';END IF;
 IF (SELECT count(*) FROM public.custodial_release_canary_authority_surface() WHERE object_kind IN ('function','grant') AND object_identity=signature)<>2 THEN RAISE EXCEPTION 'Compatibility recovery surface incomplete';END IF;
END $bind$;
COMMIT;

-- Forward-only correction for the existing native-alert ALWAYS guard.
-- The 232-source inventory still serialized its historical ordinary ENABLE
-- state. Restore must not downgrade the already stronger live trigger.
-- No business records, callable functions, ACLs or historical SQL are changed.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
SET LOCAL search_path=pg_catalog,public,extensions;
LOCK TABLE public.custodial_release_authority_restore_inventory IN ACCESS EXCLUSIVE MODE;
CREATE TEMP TABLE native_guard_unrelated_inventory ON COMMIT DROP AS
 SELECT * FROM public.custodial_release_authority_restore_inventory;
DO $rebind$
DECLARE
 identity constant text:='public.custodial_release_authority_restore_inventory.trg_custodial_release_authority_restore_inventory_immutable';
 before_hash constant text:='ff48cf273742e44575d014d0fcf978fe955e809d7949090e844458aca60b7372';
 after_hash constant text:='b3ab6991571f3d233ec13116b59229d4c06f8a5a0205cb097949a5335d3172b8';
 before_sql constant text:=$definition$drop trigger if exists trg_custodial_release_authority_restore_inventory_immutable on public.custodial_release_authority_restore_inventory; CREATE TRIGGER trg_custodial_release_authority_restore_inventory_immutable BEFORE DELETE OR UPDATE ON custodial_release_authority_restore_inventory FOR EACH ROW EXECUTE FUNCTION custodial_reject_release_authority_inventory_mutation(); alter table public.custodial_release_authority_restore_inventory enable trigger trg_custodial_release_authority_restore_inventory_immutable;$definition$;
 after_sql text;actual_sql text;changed integer;
 saved public.custodial_release_authority_restore_inventory%ROWTYPE;
BEGIN
 after_sql:=replace(before_sql,' enable trigger ',' enable always trigger ');
 IF public.static_weekly_digest_text(before_sql)<>before_hash
  OR public.static_weekly_digest_text(after_sql)<>after_hash THEN
  RAISE EXCEPTION 'Native inventory guard source constants changed';END IF;
 SELECT * INTO STRICT saved FROM public.custodial_release_authority_restore_inventory
  WHERE object_kind='trigger' AND object_identity=identity;
 IF saved.restore_order<>700027 OR saved.definition_sql IS DISTINCT FROM before_sql
  OR saved.definition_sha256<>before_hash THEN
  RAISE EXCEPTION 'Native inventory guard saved predecessor changed';END IF;
 IF public.static_weekly_digest_text(pg_get_functiondef('public.custodial_reject_release_authority_inventory_mutation()'::regprocedure))
  IS DISTINCT FROM '7904db6a14a4c8d2b93cbe4d53ba34f68052e736d15f0a55323fa04c1fae76f6' THEN
  RAISE EXCEPTION 'Native inventory guard mutation function changed';END IF;
 SELECT 'drop trigger if exists '||quote_ident(t.tgname)||' on public.custodial_release_authority_restore_inventory; '
  ||pg_get_triggerdef(t.oid,true)||'; alter table public.custodial_release_authority_restore_inventory enable always trigger '
  ||quote_ident(t.tgname)||';' INTO STRICT actual_sql
  FROM pg_trigger t WHERE t.tgrelid='public.custodial_release_authority_restore_inventory'::regclass
   AND t.tgname='trg_custodial_release_authority_restore_inventory_immutable'
   AND NOT t.tgisinternal AND t.tgenabled='A'
   AND t.tgfoid='public.custodial_reject_release_authority_inventory_mutation()'::regprocedure;
 IF actual_sql IS DISTINCT FROM after_sql OR public.static_weekly_digest_text(actual_sql)<>after_hash THEN
  RAISE EXCEPTION 'Native inventory guard live ALWAYS definition changed';END IF;
 ALTER TABLE public.custodial_release_authority_restore_inventory DISABLE TRIGGER trg_custodial_release_authority_restore_inventory_immutable;
 UPDATE public.custodial_release_authority_restore_inventory
  SET definition_sql=after_sql,definition_sha256=after_hash,captured_at=statement_timestamp()
  WHERE inventory_id=saved.inventory_id AND object_kind='trigger' AND object_identity=identity
   AND restore_order=700027 AND definition_sql=before_sql AND definition_sha256=before_hash;
 GET DIAGNOSTICS changed=ROW_COUNT;
 IF changed<>1 THEN RAISE EXCEPTION 'Native inventory guard recovery update scope changed';END IF;
 ALTER TABLE public.custodial_release_authority_restore_inventory ENABLE ALWAYS TRIGGER trg_custodial_release_authority_restore_inventory_immutable;
 IF EXISTS(SELECT u.* FROM native_guard_unrelated_inventory u WHERE u.inventory_id<>saved.inventory_id
   EXCEPT SELECT * FROM public.custodial_release_authority_restore_inventory)
  OR EXISTS(SELECT i.* FROM public.custodial_release_authority_restore_inventory i WHERE i.inventory_id<>saved.inventory_id
   EXCEPT SELECT * FROM native_guard_unrelated_inventory) THEN
  RAISE EXCEPTION 'Unrelated native inventory rows changed';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.custodial_release_authority_restore_inventory'::regclass
  AND tgname='trg_custodial_release_authority_restore_inventory_immutable' AND tgenabled='A')
  OR NOT EXISTS(SELECT 1 FROM public.custodial_release_authority_restore_inventory
   WHERE inventory_id=saved.inventory_id AND object_identity=identity AND object_kind='trigger'
    AND restore_order=700027 AND definition_sql=actual_sql AND definition_sha256=after_hash) THEN
  RAISE EXCEPTION 'Native inventory ALWAYS guard recovery readback changed';END IF;
END $rebind$;
COMMIT;

-- Exact existing postgres NEW-creator equivalence; canonical bodies/other-role revocations unchanged.
-- Exact owner/credential-bound initial selection metadata; no baseline mutation.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';

-- BEGIN FINITE NEW-CREATOR PROFILE 100
DO $creator_pre$ BEGIN
 IF current_user<>'postgres' OR session_user<>current_user
  OR current_setting('custodial.deployment_project_ref',true) IS DISTINCT FROM 'rqquvtjdmugpigbndmne'
  OR current_setting('session_replication_role')<>'origin'
  OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND NOT rolsuper AND rolbypassrls)
  OR NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='public.custodial_release_authority_restore_inventory'::regclass AND relowner='postgres'::regrole)
  OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.custodial_release_authority_restore_inventory'::regclass
   AND tgname='trg_custodial_release_authority_restore_inventory_immutable' AND tgenabled='A')
  OR to_regclass('pg_temp.custodial_creator_acl_100_before') IS NOT NULL
  OR EXISTS(SELECT 1 FROM unnest(ARRAY[]::text[]) x WHERE to_regclass(x) IS NOT NULL)
  OR EXISTS(SELECT 1 FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname=ANY(ARRAY['custodial_read_approved_initial_selection_v1']::text[]))
  OR EXISTS(SELECT 1 FROM public.custodial_release_authority_restore_inventory i
   CROSS JOIN LATERAL(SELECT regexp_replace(i.object_identity,'[[:space:]"]','','g') identity) clean
   WHERE (i.object_kind IN('function','grant') AND EXISTS(SELECT 1 FROM unnest(ARRAY['custodial_read_approved_initial_selection_v1']::text[]) name
    WHERE split_part(clean.identity,'(',1)=ANY(ARRAY[name,'public.'||name])))
    OR EXISTS(SELECT 1 FROM unnest(ARRAY[]::text[]) relation
     WHERE starts_with(clean.identity,relation) OR starts_with(clean.identity,substr(relation,8)))) THEN
  RAISE EXCEPTION 'Finite creator Source100 original owner/new-object boundary changed';
 END IF;
END $creator_pre$;
CREATE TEMP TABLE custodial_creator_acl_100_before(class text NOT NULL,signature text PRIMARY KEY,object_oid oid NOT NULL,owner_oid oid NOT NULL,owner_acl jsonb NOT NULL,definition_md5 text) ON COMMIT DROP;
-- END FINITE NEW-CREATOR PROFILE 100
CREATE FUNCTION public.custodial_read_approved_initial_selection_v1(
 p_manager_id uuid,p_credential_id uuid,p_device_id text,p_session_access text,p_week_start date
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public
AS $fn$
DECLARE choices jsonb;revision bigint;
BEGIN
 PERFORM public.static_weekly_v3_assert_control_plane();
 IF p_week_start IS NULL OR NOT isfinite(p_week_start) OR extract(isodow FROM p_week_start)<>1 THEN
  RAISE EXCEPTION USING errcode='22023',message='Approved initial selection requires a Monday week';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 -- Reuse current credential/device/registry/owner decisions, not token claims.
 choices:=public.custodial_read_approved_schedule_choices_v1(p_manager_id,p_credential_id,p_device_id,p_session_access);
 SELECT current_revision INTO STRICT revision FROM public.static_weekly_schedule_control WHERE singleton;
 RETURN choices||jsonb_build_object('schema','custodial.approved-initial-selection.v1',
  'week_start',p_week_start,'week_end',p_week_start+6,'authority_revision',revision,
  'published',false,'snapshot_authority','SELECTION_METADATA_ONLY');
END $fn$;

DO $creator_function_before$ DECLARE spec record;p record;BEGIN
 FOR spec IN SELECT * FROM jsonb_to_recordset($creator_specs$[{"signature":"public.custodial_read_approved_initial_selection_v1(uuid,uuid,text,text,date)","name":"custodial_read_approved_initial_selection_v1","body_md5":"8c4270a3003fe3c9134b099e5c470c0d","argument_names":["p_manager_id","p_credential_id","p_device_id","p_session_access","p_week_start"],"returns":"jsonb","language":"plpgsql","security_definer":true,"volatility":"v","config":["search_path=pg_catalog, public"],"nonowner_execute":["static_weekly_control_plane"]}]$creator_specs$::jsonb)
  AS x(signature text,name text,body_md5 text,argument_names text[],returns text,language text,security_definer boolean,volatility text,config text[],nonowner_execute text[]) LOOP
  SELECT f.*,l.lanname INTO STRICT p FROM pg_proc f JOIN pg_language l ON l.oid=f.prolang WHERE f.oid=to_regprocedure(spec.signature) AND f.pronamespace='public'::regnamespace;
  IF p.proowner<>'postgres'::regrole OR p.proname<>spec.name OR md5(p.prosrc)<>spec.body_md5
   OR p.proargnames IS DISTINCT FROM spec.argument_names OR pg_get_function_result(p.oid)<>spec.returns OR p.lanname<>spec.language
   OR p.prosecdef<>spec.security_definer OR p.provolatile::text<>spec.volatility OR p.proconfig IS DISTINCT FROM spec.config
   OR p.prokind<>'f' OR p.proretset OR p.provariadic<>0 OR p.pronargdefaults<>0 OR p.proisstrict OR p.proleakproof OR p.proparallel<>'u'
   OR NOT has_function_privilege(current_user,p.oid,'EXECUTE')
