ee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"catalog_kind":"function","schema":"public","owner":"postgres","body_md5":"17fee06fe96eaccd15d01d65b5f0ff69","definition_md5":"b15fb327f4dd6272f8555e051b0565bc","security_definer":true,"volatility":"v","configuration":["search_path=pg_catalog, public, extensions"]},{"object_kind":"view","object_identity":"public.v_admin_health_snapshot","restore_order":"850004","original_sha256":"c41722314d98f8466f7b17ae3e832daf8f2e04ffe21cf86f0de3ca7d4224533b","saved_sha256":"94727a754bb4ad6ebbe0d941370acd9ff730c2f1868c02630e948bccb6cecb58","current_sha256":"94727a754bb4ad6ebbe0d941370acd9ff730c2f1868c02630e948bccb6cecb58","current_definition_sql":"create or replace view public.v_admin_health_snapshot as  WITH cfg AS (\n         SELECT get_setting_int('stale_session_timeout_minutes'::text, 120) AS stale_timeout_minutes,\n            get_setting_int('scan_history_warning_mb'::text, 350) AS scan_history_warning_mb,\n            operational_day_start(now()) AS operational_day_start\n        ), storage AS (\n         SELECT scan_history_storage_summary() AS summary\n        ), counts AS (\n         SELECT ( SELECT count(*) AS count\n                   FROM custodial_open_work() custodial_open_work(open_work_id, source_kind, session_id, context_id, session_uuid, client_session_id, location_id, location_code, location_name, employee_id, employee_name, device_id, device_identifier, status, started_at, ended_at, duration_minutes, duration_display, created_at)\n                  WHERE custodial_open_work.status = 'active'::text) AS active_sessions,\n            ( SELECT count(*) AS count\n                   FROM custodial_open_work() custodial_open_work(open_work_id, source_kind, session_id, context_id, session_uuid, client_session_id, location_id, location_code, location_name, employee_id, employee_name, device_id, device_identifier, status, started_at, ended_at, duration_minutes, duration_display, created_at)\n                  WHERE custodial_open_work.status = 'pending_submit'::text) AS pending_submit_sessions,\n            ( SELECT count(*) AS count\n                   FROM sessions\n                  WHERE sessions.status = 'closed'::text AND COALESCE(sessions.ended_at, sessions.started_at, sessions.created_at) >= (( SELECT cfg.operational_day_start\n                           FROM cfg))) AS closed_sessions_today,\n            ( SELECT count(*) AS count\n                   FROM v_open_maintenance_tickets) AS open_ticket_count,\n            ( SELECT count(*) AS count\n                   FROM v_location_dashboard_status\n                  WHERE v_location_dashboard_status.status_code = 'overdue'::text) AS overdue_locations,\n            ( SELECT count(*) AS count\n                   FROM v_location_dashboard_status\n                  WHERE v_location_dashboard_status.status_code = 'due_soon'::text) AS due_soon_locations,\n            ( SELECT count(*) AS count\n                   FROM v_location_dashboard_status\n                  WHERE v_location_dashboard_status.status_code = 'in_progress'::text) AS in_progress_locations,\n            ( SELECT count(*) AS count\n                   FROM locations\n                  WHERE locations.active = true) AS active_locations,\n            ( SELECT count(*) AS count\n                   FROM devices\n                  WHERE devices.active = true) AS active_devices,\n            ( SELECT count(*) AS count\n                   FROM devices\n                  WHERE devices.active = true AND devices.last_seen_at >= (now() - '24:00:00'::interval)) AS devices_seen_last_24h,\n            ( SELECT count(*) AS count\n                   FROM devices\n                  WHERE devices.active = true AND (devices.last_seen_at IS NULL OR devices.last_seen_at < (now() - '24:00:00'::interval))) AS devices_missing_recent_heartbeat,\n            ( SELECT count(*) AS count\n                   FROM custodial_open_work() custodial_open_work(open_work_id, source_kind, session_id, context_id, session_uuid, client_session_id, location_id, location_code, location_name, employee_id, employee_name, device_id, device_identifier, status, started_at, ended_at, duration_minutes, duration_display, created_at)\n                  WHERE COALESCE(custodial_open_work.ended_at, custodial_open_work.started_at) <= (now() - make_interval(mins => ( SELECT cfg.stale_timeout_minutes\n                           FROM cfg)))) AS stale_open_sessions,\n            ( SELECT count(*) AS count\n                   FROM system_logs\n                  WHERE (system_logs.level = ANY (ARRAY['WARN'::text, 'ERROR'::text])) AND system_logs.created_at >= (now() - '24:00:00'::interval)) AS warn_error_logs_last_24h\n        )\n SELECT now() AS snapshot_at,\n    ( SELECT cfg.operational_day_start\n           FROM cfg) AS operational_day_start,\n    ( SELECT cfg.stale_timeout_minutes\n           FROM cfg) AS stale_timeout_minutes,\n    ( SELECT cfg.scan_history_warning_mb\n           FROM cfg) AS scan_history_warning_mb,\n    counts.active_sessions,\n    counts.pending_submit_sessions,\n    counts.closed_sessions_today,\n    counts.open_ticket_count,\n    counts.overdue_locations,\n    counts.due_soon_locations,\n    counts.in_progress_locations,\n    counts.active_locations,\n    counts.active_devices,\n    counts.devices_seen_last_24h,\n    counts.devices_missing_recent_heartbeat,\n    counts.stale_open_sessions,\n    counts.warn_error_logs_last_24h,\n    storage.summary AS storage_summary\n   FROM counts\n     CROSS JOIN storage; alter view public.v_admin_health_snapshot reset (check_option,security_barrier,security_invoker); alter view public.v_admin_health_snapshot owner to postgres;","classification":"view_terminal_owner_only","explicit_identity":"public.v_admin_health_snapshot","catalog_kind":"view","schema":"public","owner":"postgres","relation_kind":"v","relation_options":null},{"object_kind":"view","object_identity":"public.v_exception_queue","restore_order":"850005","original_sha256":"af8fcfd45b4b8392c51ffb73f5269a559c4c40c5321a93bcac67af02619e06b2","saved_sha256":"448695dcb7db375c283c1b18e8078a5a1b8ab0c79bb51222792dac183848a1fc","current_sha256":"448695dcb7db375c283c1b18e8078a5a1b8ab0c79bb51222792dac183848a1fc","current_definition_sql":"create or replace view public.v_exception_queue as  SELECT 'open_ticket'::text AS exception_type,\n    ticket.ticket_id::text AS entity_id,\n    ticket.location_code,\n    ticket.location_name,\n    ticket.date_submitted AS event_at,\n    ticket.date_submitted_display AS event_at_display,\n    ticket.maintenance_issue AS summary,\n    ticket.reported_by AS actor,\n    jsonb_build_object('fixture_type', ticket.fixture_type, 'fixture_identifier', ticket.fixture_identifier, 'out_of_order', ticket.out_of_order, 'status', ticket.status) AS details\n   FROM v_open_maintenance_tickets ticket\nUNION ALL\n SELECT 'overdue_location'::text AS exception_type,\n    location.location_id::text AS entity_id,\n    location.location_code,\n    location.location_name,\n    location.latest_completed_at AS event_at,\n    location.latest_completed_at_display AS event_at_display,\n    'Location overdue for cleaning'::text AS summary,\n    location.latest_employee_name AS actor,\n    jsonb_build_object('form_type', location.form_type, 'status_code', location.status_code, 'status_color', location.status_color, 'open_ticket_count', location.open_ticket_count) AS details\n   FROM v_location_dashboard_status location\n  WHERE location.status_code = 'overdue'::text\nUNION ALL\n SELECT 'stale_device'::text AS exception_type,\n    device.id::text AS entity_id,\n    NULL::text AS location_code,\n    device.device_name AS location_name,\n    GREATEST(device.last_seen_at, sync.last_server_ack_at, sync.updated_at) AS event_at,\n        CASE\n            WHEN GREATEST(device.last_seen_at, sync.last_server_ack_at, sync.updated_at) IS NULL THEN 'Never seen'::text\n            ELSE to_char(timezone('America/Chicago'::text, GREATEST(device.last_seen_at, sync.last_server_ack_at, sync.updated_at)), 'MM/DD/YYYY HH12:MI AM'::text) || ' Central'::text\n        END AS event_at_display,\n    'Device missing recent heartbeat'::text AS summary,\n    device.device_id AS actor,\n    jsonb_build_object('device_id', device.device_id, 'active', device.active, 'last_seen_at', device.last_seen_at, 'last_server_ack_at', sync.last_server_ack_at, 'sync_updated_at', sync.updated_at) AS details\n   FROM devices device\n     LEFT JOIN device_sync_status sync ON sync.device_id = device.id\n  WHERE device.active = true AND device.assigned_employee_id IS NOT NULL AND (GREATEST(device.last_seen_at, sync.last_server_ack_at, sync.updated_at) IS NULL OR GREATEST(device.last_seen_at, sync.last_server_ack_at, sync.updated_at) < (now() - '24:00:00'::interval))\nUNION ALL\n SELECT 'stale_open_session'::text AS exception_type,\n    work.session_uuid AS entity_id,\n    work.location_code,\n    work.location_name,\n    COALESCE(work.ended_at, work.started_at) AS event_at,\n    to_char(timezone('America/Chicago'::text, COALESCE(work.ended_at, work.started_at)), 'MM/DD/YYYY HH12:MI AM'::text) || ' Central'::text AS event_at_display,\n    'Open session exceeded stale timeout'::text AS summary,\n    work.employee_name AS actor,\n    jsonb_build_object('status', work.status, 'device_id', work.device_identifier, 'started_at', work.started_at, 'ended_at', work.ended_at) AS details\n   FROM custodial_open_work() work(open_work_id, source_kind, session_id, context_id, session_uuid, client_session_id, location_id, location_code, location_name, employee_id, employee_name, device_id, device_identifier, status, started_at, ended_at, duration_minutes, duration_display, created_at)\n  WHERE COALESCE(work.ended_at, work.started_at) <= (now() - make_interval(mins => get_setting_int('stale_session_timeout_minutes'::text, 120))); alter view public.v_exception_queue reset (check_option,security_barrier,security_invoker); alter view public.v_exception_queue owner to postgres;","classification":"view_terminal_owner_only","explicit_identity":"public.v_exception_queue","catalog_kind":"view","schema":"public","owner":"postgres","relation_kind":"v","relation_options":null},{"object_kind":"view","object_identity":"public.v_location_dashboard_status","restore_order":"850002","original_sha256":"01f2738d65fe42e4aa6c3af221cde19b7550c9ece1edd2654890a9ce52df24c5","saved_sha256":"7956b0b208e62458fdd54bf96578c06fc490d583e5fcf06aa66baa2cbe8957d9","current_sha256":"7956b0b208e62458fdd54bf96578c06fc490d583e5fcf06aa66baa2cbe8957d9","current_definition_sql":"create or replace view public.v_location_dashboard_status as  WITH op_day AS (\n         SELECT operational_day_start(now()) AS day_start,\n            sch_service_date(now()) AS service_date\n        ), authority AS (\n         SELECT state.service_date,\n            state.governed,\n            state.authority_source,\n            state.projection_status,\n            state.version_id,\n            state.publication_id,\n            state.projection_id,\n            state.projection_authority_revision,\n            state.staffing_authority_revision,\n            state.week_start\n           FROM op_day day\n             CROSS JOIN LATERAL static_weekly_v6_schedule_authority_state(day.service_date) state(service_date, governed, authority_source, projection_status, version_id, publication_id, projection_id, projection_authority_revision, staffing_authority_revision, week_start)\n        ), scheduled_baseline AS (\n         SELECT assignment.location_id,\n            min(((day.service_date + assignment.coverage_start) AT TIME ZONE 'America/Chicago'::text)) AS baseline_at\n           FROM op_day day\n             JOIN LATERAL custodial_operational_location_assignments(day.service_date) assignment(service_date, authority_source, projection_status, version_id, publication_id, projection_id, occurrence_id, location_group_id, group_code, group_name, assigned_employee_id, assigned_employee_name, assignment_status, coverage_start, coverage_end, location_id, location_code, location_name, form_type) ON true\n          GROUP BY assignment.location_id\n        ), latest_scan AS (\n         SELECT scan_events.location_id,\n            max(COALESCE(scan_events.scanned_at, scan_events.created_at)) AS last_scan_at\n           FROM scan_events\n          GROUP BY scan_events.location_id\n        ), open_session AS (\n         SELECT DISTINCT ON (work.location_id) work.location_id,\n            work.location_code,\n            work.session_id,\n            work.session_uuid,\n            work.status AS session_status,\n            work.started_at,\n            work.ended_at,\n            work.duration_minutes,\n            work.duration_display,\n            work.employee_name,\n            work.device_identifier\n           FROM custodial_open_work() work(open_work_id, source_kind, session_id, context_id, session_uuid, client_session_id, location_id, location_code, location_name, employee_id, employee_name, device_id, device_identifier, status, started_at, ended_at, duration_minutes, duration_display, created_at)\n          WHERE work.source_kind <> 'session'::text OR work.started_at >= operational_day_start(now())\n          ORDER BY work.location_id, work.started_at DESC, work.created_at DESC, work.open_work_id DESC\n        ), latest_completed AS (\n         SELECT DISTINCT ON (session.location_id) session.location_id,\n            session.id AS session_id,\n            session.session_uuid,\n            session.started_at,\n            session.ended_at,\n            session.duration_minutes,\n            session.duration_display,\n            employee.display_name AS employee_name,\n            completion.submitted_at,\n            completion.response_json,\n            COALESCE(session.ended_at, completion.submitted_at, session.started_at) AS effective_completed_at\n           FROM sessions session\n             JOIN employees employee ON employee.id = session.employee_id\n             LEFT JOIN completion_responses completion ON completion.session_id = session.id\n             CROSS JOIN op_day day\n          WHERE session.status = 'closed'::text AND (completion.response_json ->> 'work_result'::text) IS DISTINCT FROM 'checked_no_cleaning_needed'::text AND COALESCE(session.ended_at, completion.submitted_at, session.started_at) >= day.day_start\n          ORDER BY session.location_id, (COALESCE(session.ended_at, completion.submitted_at, session.started_at)) DESC, session.started_at DESC\n        ), open_tickets AS (\n         SELECT maintenance_tickets.location_id,\n            count(*) AS open_ticket_count\n           FROM maintenance_tickets\n          WHERE maintenance_tickets.status = 'open'::text\n          GROUP BY maintenance_tickets.location_id\n        ), truth AS (\n         SELECT location.id AS location_id,\n            COALESCE(open_session.location_code, location.location_code) AS location_code,\n            place_operational_location_name(location.id, statement_timestamp()) AS location_name,\n            location.location_type,\n            location.form_type,\n            day.day_start,\n            latest_scan.last_scan_at,\n            open_session.session_id AS open_session_id,\n            open_session.session_uuid AS open_session_uuid,\n            open_session.session_status AS open_session_status,\n            open_session.started_at AS open_session_started_at,\n            open_session.ended_at AS open_session_ended_at,\n            open_session.employee_name AS open_session_employee_name,\n            open_session.device_identifier AS open_session_device_identifier,\n            latest_completed.session_id AS latest_completed_session_id,\n            latest_completed.session_uuid AS latest_completed_session_uuid,\n            latest_completed.started_at AS latest_started_at,\n            latest_completed.ended_at AS latest_ended_at,\n            latest_completed.submitted_at AS latest_submitted_at,\n            latest_completed.effective_completed_at AS latest_completed_at,\n            latest_completed.employee_name AS latest_employee_name,\n            latest_completed.duration_minutes,\n            latest_completed.duration_display,\n            latest_completed.response_json,\n            COALESCE(open_tickets.open_ticket_count, 0::bigint) AS open_ticket_count,\n            scheduled_baseline.baseline_at,\n            mz_latest_verified_check(location.id, day.day_start, now()) AS verified_check_at,\n                CASE\n                    WHEN latest_completed.effective_completed_at IS NULL THEN NULL::timestamp with time zone\n                    ELSE GREATEST(latest_completed.effective_completed_at, mz_latest_verified_check(location.id, day.day_start, now()))\n                END AS due_baseline_at,\n            authority.authority_source AS schedule_authority_source,\n            authority.projection_status AS schedule_projection_status\n           FROM locations location\n             CROSS JOIN op_day day\n             CROSS JOIN authority\n             LEFT JOIN scheduled_baseline ON scheduled_baseline.location_id = location.id\n             LEFT JOIN latest_scan ON latest_scan.location_id = location.id\n             LEFT JOIN open_session ON open_session.location_id = location.id\n             LEFT JOIN latest_completed ON latest_completed.location_id = location.id\n             LEFT JOIN open_tickets ON open_tickets.location_id = location.id\n          WHERE location.active = true\n        )\n SELECT location_id,\n    location_code,\n    location_name,\n    location_type,\n    form_type,\n    day_start AS operational_day_start,\n    last_scan_at,\n    open_session_id,\n    open_session_uuid,\n    open_session_status,\n    open_session_started_at,\n    open_session_ended_at,\n    latest_completed_session_id,\n    latest_completed_session_uuid,\n    latest_started_at,\n    latest_ended_at,\n    latest_submitted_at,\n    latest_completed_at,\n    latest_employee_name,\n    duration_minutes,\n    duration_display,\n    COALESCE(response_json -> 'services_performed'::text, response_json -> 'servicesPerformed'::text, response_json -> 'services'::text, response_json -> 'completed_services'::text, response_json -> 'completedServices'::text, '[]'::jsonb) AS services_performed,\n    COALESCE(response_json ->> 'notes'::text, response_json ->> 'cleaning_notes'::text, response_json ->> 'cleaningNotes'::text, response_json ->> 'maintenance_notes'::text, response_json ->> 'maintenanceNotes'::text, response_json ->> 'other_service_performed'::text, response_json ->> 'otherServicePerformed'::text, response_json ->> 'note'::text) AS notes,\n    open_ticket_count,\n        CASE\n            WHEN due_baseline_at IS NULL AND (open_session_status = ANY (ARRAY['active'::text, 'pending_submit'::text])) THEN 'in_progress'::text\n            WHEN due_baseline_at IS NULL THEN 'not_cleaned'::text\n            WHEN form_type = 'restroom'::text AND now() >= (due_baseline_at + make_interval(mins =>\n            CASE\n                WHEN mz_is_approved_admin_location(location_id, now()) THEN 180\n                ELSE get_setting_int('restroom_overdue_minutes'::text, 90)\n            END)) THEN 'overdue'::text\n            WHEN form_type = 'restroom'::text AND now() >= (due_baseline_at + make_interval(mins =>\n            CASE\n                WHEN mz_is_approved_admin_location(location_id, now()) THEN 165\n                ELSE get_setting_int('restroom_due_soon_minutes'::text, 75)\n            END)) THEN 'due_soon'::text\n            WHEN form_type = 'exhibit'::text AND now() >= (due_baseline_at + make_interval(mins =>\n            CASE\n                WHEN mz_is_approved_admin_location(location_id, now()) THEN 180\n                ELSE get_setting_int('exhibit_overdue_minutes'::text, 210)\n            END)) THEN 'overdue'::text\n            WHEN form_type = 'exhibit'::text AND now() >= (due_baseline_at + make_interval(mins =>\n            CASE\n                WHEN mz_is_approved_admin_location(location_id, now()) THEN 165\n                ELSE get_setting_int('exhibit_due_soon_minutes'::text, 195)\n            END)) THEN 'due_soon'::text\n            WHEN open_session_status = ANY (ARRAY['active'::text, 'pending_submit'::text]) THEN 'in_progress'::text\n            ELSE 'okay'::text\n        END AS status_code,\n        CASE\n            WHEN due_baseline_at IS NULL AND (open_session_status = ANY (ARRAY['active'::text, 'pending_submit'::text])) THEN 'blue'::text\n            WHEN due_baseline_at IS NULL THEN 'black'::text\n            WHEN form_type = 'restroom'::text AND now() >= (due_baseline_at + make_interval(mins =>\n            CASE\n                WHEN mz_is_approved_admin_location(location_id, now()) THEN 180\n                ELSE get_setting_int('restroom_overdue_minutes'::text, 90)\n            END)) OR form_type = 'exhibit'::text AND now() >= (due_baseline_at + make_interval(mins =>\n            CASE\n                WHEN mz_is_approved_admin_location(location_id, now()) THEN 180\n                ELSE get_setting_int('exhibit_overdue_minutes'::text, 210)\n            END)) THEN 'red'::text\n            WHEN form_type = 'restroom'::text AND now() >= (due_baseline_at + make_interval(mins =>\n            CASE\n                WHEN mz_is_approved_admin_location(location_id, now()) THEN 165\n                ELSE get_setting_int('restroom_due_soon_minutes'::text, 75)\n            END)) OR form_type = 'exhibit'::text AND now() >= (due_baseline_at + make_interval(mins =>\n            CASE\n                WHEN mz_is_approved_admin_location(location_id, now()) THEN 165\n                ELSE get_setting_int('exhibit_due_soon_minutes'::text, 195)\n            END)) THEN 'yellow'::text\n            WHEN open_session_status = ANY (ARRAY['active'::text, 'pending_submit'::text]) THEN 'blue'::text\n            ELSE 'green'::text\n        END AS status_color,\n    to_c