tion_name,\n            location.location_type,\n            location.active AS location_active,\n            work.session_id,\n            work.session_uuid,\n            work.session_status,\n            work.started_at,\n            work.ended_at,\n            work.duration_minutes,\n            work.duration_display,\n            work.employee_name,\n            work.device_id,\n            row_number() OVER (PARTITION BY location.id ORDER BY work.source_priority, work.started_at DESC NULLS LAST, work.created_at DESC NULLS LAST, work.session_id DESC NULLS LAST) AS rn\n           FROM locations location\n             LEFT JOIN work_candidates work ON work.location_id = location.id\n        )\n SELECT location_id,\n    location_code,\n    location_name,\n    location_type,\n    location_active,\n    session_id,\n    session_uuid,\n    session_status,\n    started_at,\n    ended_at,\n    duration_minutes,\n    duration_display,\n    employee_name,\n    device_id\n   FROM ranked\n  WHERE rn = 1; alter view public.v_location_status reset (check_option,security_barrier,security_invoker); alter view public.v_location_status owner to postgres;","classification":"view_terminal_owner_only","explicit_identity":"public.v_location_status","catalog_kind":"view","schema":"public","owner":"postgres","relation_kind":"v","relation_options":null},{"object_kind":"view","object_identity":"public.v_memphis_area_schedule","restore_order":"850009","original_sha256":"e13e853bf2653473553c62f20f286871393107509c11def746c9e371f2ddadd1","saved_sha256":"a472a46cf414c5e4095fc824826c76a3c84a7fa4ce041b9a9bf19194304f8219","current_sha256":"a472a46cf414c5e4095fc824826c76a3c84a7fa4ce041b9a9bf19194304f8219","current_definition_sql":"create or replace view public.v_memphis_area_schedule as  WITH authority_dates AS (\n         SELECT DISTINCT occurrence.service_date\n           FROM weekly_schedule_occurrences occurrence\n        UNION\n         SELECT DISTINCT assignment.service_date\n           FROM