f5983a05d209b4e6eae8","current_definition_sql":"create or replace view public.v_open_maintenance_tickets as  SELECT mt.id AS ticket_id,\n    COALESCE(mt.location_code_snapshot, l.location_code) AS location_code,\n    COALESCE(mt.location_name_snapshot, l.location_name) AS location_name,\n    mt.reported_at AS date_submitted,\n    mt.issue_summary AS maintenance_issue,\n    COALESCE(mt.reporter_name_snapshot, e.display_name) AS reported_by,\n    mt.fixture_type,\n    mt.fixture_identifier,\n    mt.out_of_order,\n    mt.status,\n    mt.issue_payload,\n    mt.close_notes,\n    mt.created_at,\n    to_char(timezone('America/Chicago'::text, mt.reported_at), 'MM/DD/YYYY'::text) AS date_submitted_date_display,\n    to_char(timezone('America/Chicago'::text, mt.reported_at), 'MM/DD/YYYY HH12:MI AM'::text) || ' Central'::text AS date_submitted_display,\n    to_char(timezone('America/Chicago'::text, mt.created_at), 'MM/DD/YYYY HH12:MI AM'::text) || ' Central'::text AS created_at_display,\n    mt.issue_source\n   FROM maintenance_tickets mt\n     LEFT JOIN locations l ON l.id = mt.location_id\n     LEFT JOIN employees e ON e.id = mt.reported_by_employee_id\n  WHERE mt.status = 'open'::text; alter view public.v_open_maintenance_tickets reset (check_option,security_barrier,security_invoker); alter view public.v_open_maintenance_tickets owner to postgres;","classification":"view_terminal_owner_only","explicit_identity":"public.v_open_maintenance_tickets","catalog_kind":"view","schema":"public","owner":"postgres","relation_kind":"v","relation_options":null},{"object_kind":"view","object_identity":"public.v_restroom_check_timers","restore_order":"850003","original_sha256":"8dd302c13b6c138e49ebccb7fa548734d35d0d3bc64cf05c2ab3563b773b6fbd","saved_sha256":"7a3f322a4d0ac8c6dca8e34fd3fb693e81a43c4fd34a71b7713406cc43976b5d","current_sha256":"7a3f322a4d0ac8c6dca8e34fd3fb693e81a43c4fd34a71b7713406cc43976b5d","current_definition_sql":"create or replace view public.v_restroom_check_timers as  WITH restroom_locations AS (\n         SELECT group_row.id AS location_group_id,\n            group_row.group_code,\n            group_row.group_name,\n            location.id AS location_id,\n            location.location_code,\n            location.location_name\n           FROM location_groups group_row\n             JOIN location_group_memberships membership ON membership.location_group_id = group_row.id AND membership.active = true\n             JOIN locations location ON location.id = membership.location_id AND location.active = true\n          WHERE group_row.active = true AND lower(COALESCE(location.form_type, location.location_type, ''::text)) = 'restroom'::text AND sch_is_public_restroom_group(group_row.id) AND NOT (location.location_name ~~* '%East Admin%'::text OR location.location_name ~~* '%West Admin%'::text OR location.location_name ~~* '%Elephant Trunk%'::text)\n        ), activity AS (\n         SELECT session.location_id,\n            COALESCE(session.ended_at, completion.submitted_at, session.started_at) AS activity_at,\n            COALESCE(submitter.display_name, employee.display_name) AS actor_name,\n            COALESCE(completion_device.device_id, device.device_id) AS device_identifier\n           FROM sessions session\n             LEFT JOIN completion_responses completion ON completion.session_id = session.id\n             LEFT JOIN employees submitter ON submitter.id = completion.submitted_by_employee_id\n             LEFT JOIN employees employee ON employee.id = session.employee_id\n             LEFT JOIN devices completion_device ON completion_device.id = completion.device_id\n             LEFT JOIN devices device ON device.id = session.device_id\n          WHERE COALESCE(session.ended_at, completion.submitted_at, session.started_at) >= operational_day_start(now()) AND session.status = 'closed'::text AND ((completion.response_json ->> 'work_result'::text) IS DISTINCT FROM 'checked_no_cleaning_needed'::text OR session.ended_at = mz_latest_verified_check(session.location_id, operational_day_start(now()), now()))\n        ), latest_completion AS (\n         SELECT DISTINCT ON (restroom_1.location_id) restroom_1.location_id,\n            activity.activity_at AS last_completed_at,\n            activity.actor_name AS last_completed_by,\n            activity.device_identifier AS last_completed_device\n           FROM restroom_locations restroom_1\n             LEFT JOIN activity ON activity.location_id = restroom_1.location_id\n          ORDER BY restroom_1.location_id, activity.activity_at DESC NULLS LAST\n        ), current_owner AS (\n         SELECT DISTINCT ON (assignment.location_group_id) assignment.location_group_id,\n            assignment.assigned_employee_id,\n            employee.display_name AS assigned_owner,\n            assignment.coverage_start::time without time zone AS coverage_start,\n            assignment.coverage_end::time without time zone AS coverage_end,\n            assignment.coverage_purpose,\n            assignment.status\n           FROM static_weekly_v6_read_schedule_segments(sch_service_date(now())) assignment(service_date, location_group_id, group_code, group_name, included_locations, included_location_ids, segment_id, segment_number, owner_type, assigned_employee_id, assigned_employee_name, coverage_start, coverage_end, status, load_points, coverage_purpose, notes, source_type, service_mode, governed, projection_status, version_id, publication_id, projection_id)\n             LEFT JOIN employees employee ON employee.id = assignment.assigned_employee_id\n          WHERE assignment.service_date = sch_service_date(now()) AND timezone('America/Chicago'::text, now())::time without time zone >= assignment.coverage_start::time without time zone AND timezone('America/Chicago'::text, now())::time without time zone < assignment.coverage_end::time without time zone\n          ORDER BY assignment.location_group_id, (\n                CASE\n                    WHEN assignment.coverage_purpose = ANY (ARRAY['restroom_check'::text, 'restroom_upkeep'::text, 'area_owner'::text]) THEN 0\n                    ELSE 1\n                END), assignment.coverage_start DESC\n        )\n SELECT sch_service_date(now()) AS service_date,\n    restroom.location_group_id,\n    restroom.group_code,\n    restroom.group_name AS schedule_package_name,\n    restroom.location_id,\n    restroom.location_code,\n    restroom.location_name AS scanned_restroom_name,\n    latest.last_completed_at,\n    timezone('America/Chicago'::text, latest.last_completed_at) AS last_completed_at_central,\n    latest.last_completed_by,\n    latest.last_completed_device,\n        CASE\n            WHEN dashboard.latest_completed_at IS NOT NULL AND latest.last_completed_at IS NOT NULL THEN latest.last_completed_at + '01:30:00'::interval\n            ELSE NULL::timestamp with time zone\n        END AS next_check_due_at,\n        CASE\n            WHEN dashboard.latest_completed_at IS NOT NULL AND latest.last_completed_at IS NOT NULL THEN timezone('America/Chicago'::text, latest.last_completed_at + '01:30:00'::interval)\n            ELSE NULL::timestamp without time zone\n        END AS next_check_due_at_central,\n        CASE\n            WHEN dashboard.latest_completed_at IS NULL OR latest.last_completed_at IS NULL THEN 'not_cleaned_yet'::text\n            WHEN (latest.last_completed_at + '01:30:00'::interval) <= now() THEN 'overdue'::text\n            WHEN (latest.last_completed_at + '01:30:00'::interval) <= (now() + '00:15:00'::interval) THEN 'due_soon'::text\n            ELSE 'ok'::text\n        END AS timer_status,\n        CASE\n            WHEN dashboard.latest_completed_at IS NOT NULL AND latest.last_completed_at IS NOT NULL THEN round(EXTRACT(epoch FROM latest.last_completed_at + '01:30:00'::interval - now()) / 60.0)::integer\n            ELSE NULL::integer\n        END AS minutes_until_due,\n    owner.assigned_employee_id,\n    owner.assigned_owner,\n    to_char(owner.coverage_start::interval, 'HH24:MI'::text) AS owner_coverage_start,\n    to_char(owner.coverage_end::interval, 'HH24:MI'::text) AS owner_coverage_end,\n    owner.coverage_purpose,\n    owner.status AS owner_status,\n        CASE\n            WHEN dashboard.latest_completed_at IS NOT NULL AND latest.last_completed_at IS NOT NULL THEN 'scan_completion'::text\n            ELSE 'no_scan_today'::text\n        END AS timer_source\n   FROM restroom_locations restroom\n     LEFT JOIN v_location_dashboard_status dashboard ON dashboard.location_id = restroom.location_id\n     LEFT JOIN latest_completion latest ON latest.location_id = restroom.location_id\n     LEFT JOIN current_owner owner ON owner.location_group_id = restroom.location_group_id; alter view public.v_restroom_check_timers reset (check_option,security_barrier,security_invoker); alter view public.v_restroom_check_timers owner to postgres;","classification":"view_terminal_owner_only","explicit_identity":"public.v_restroom_check_timers","catalog_kind":"view","schema":"public","owner":"postgres","relation_kind":"v","relation_options":null},{"object_kind":"view","object_identity":"public.v_restroom_package_status","restore_order":"850006","original_sha256":"2fe5b2142c577937fe58b385d3f34ed5e2102026066c782ced0d1c1ac5a81065","saved_sha256":"82d51cc69fc3e048e4d29e515805ee25415a3828b8095e58be5236bc1a110a10","current_sha256":"82d51cc69fc3e048e4d29e515805ee25415a3828b8095e58be5236bc1a110a10","current_definition_sql":"create or replace view public.v_restroom_package_status as  SELECT service_date,\n    location_group_id,\n    group_code,\n    schedule_package_name,\n    count(*)::integer AS restroom_count,\n    count(*) FILTER (WHERE timer_status <> 'not_cleaned_yet'::text)::integer AS cleaned_count,\n    count(*) FILTER (WHERE timer_status = 'not_cleaned_yet'::text)::integer AS not_cleaned_count,\n    count(*) FILTER (WHERE timer_status = 'due_soon'::text)::integer AS due_soon_count,\n    count(*) FILTER (WHERE timer_status = 'overdue':