DO $existing_profile253$
DECLARE spec jsonb; item jsonb; helper jsonb; obj oid; definition text; digest text; acl jsonb; expected_acl jsonb; rel oid;
BEGIN
 SELECT data INTO STRICT spec FROM complete_frame_existing_profile;
 IF current_user<>'postgres' OR session_user<>current_user
  OR current_setting('custodial.deployment_project_ref',true) IS DISTINCT FROM 'rqquvtjdmugpigbndmne'
  OR current_setting('session_replication_role')<>'origin'
  OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND NOT rolsuper AND rolbypassrls)
  OR NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='public.custodial_release_authority_restore_inventory'::regclass AND relowner='postgres'::regrole)
  OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.custodial_release_authority_restore_inventory'::regclass
   AND tgname='trg_custodial_release_authority_restore_inventory_immutable' AND tgenabled='A' AND NOT tgisinternal
   AND tgfoid='public.custodial_reject_release_authority_inventory_mutation()'::regprocedure)
  OR spec->>'schema'<>'custodial.source253-existing-original-postgres.v1'
  OR spec->>'scope'<>'DISTINCT_EXISTING_RUNTIME_PROFILE_NOT_NOAUTO_EQUIVALENCE'
  OR jsonb_array_length(spec->'original_rows')<>6968 OR jsonb_array_length(spec->'runtime_rows')<>6968
  OR jsonb_array_length(spec->'finite_new84')<>84 OR jsonb_array_length(spec->'helpers')<>8
 THEN RAISE EXCEPTION 'Distinct Source253 original actor/ALWAYS/full reference changed';END IF;
 -- These existing Source renderers are checked before invoking any of them.
 FOR helper IN SELECT x FROM jsonb_array_elements(spec->'helpers') x LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
   WHERE p.oid=to_regprocedure(helper->>'identity') AND n.nspname='public' AND p.proowner='postgres'::regrole
    AND md5(pg_get_functiondef(p.oid))=helper->>'full_definition_md5') THEN
   RAISE EXCEPTION 'Distinct Source253 fixed render helper changed';END IF;
 END LOOP;
 SELECT encode(extensions.digest(convert_to('['||string_agg(
  '{"object_kind":'||to_json(x->>0)::text||',"object_identity":'||to_json(x->>1)::text||
  ',"restore_order":'||(x->>2)||',"definition_sha256":'||to_json(x->>3)::text||'}',','
  ORDER BY (x->>0) COLLATE "C",(x->>1) COLLATE "C")||']','UTF8'),'sha256'),'hex')
  INTO digest FROM jsonb_array_elements(spec->'original_rows') x;
 IF digest IS DISTINCT FROM '3944844de0557a78f2cfcd65f43607196934c511c1837eda0335519fafd6b76f'
  OR (SELECT count(DISTINCT (x->>0,x->>1)) FROM jsonb_array_elements(spec->'original_rows') x)<>6968
  OR (SELECT count(DISTINCT (x->>0,x->>1)) FROM jsonb_array_elements(spec->'runtime_rows') x)<>6968
  OR (SELECT count(*) FROM public.custodial_release_authority_restore_inventory)<>6968
  OR EXISTS(
   WITH wanted AS(SELECT x->>0 kind,x->>1 identity,(x->>2)::integer restore_order,x->>3 digest FROM jsonb_array_elements(spec->'runtime_rows') x)
   SELECT 1 FROM wanted w FULL JOIN public.custodial_release_authority_restore_inventory i ON w.kind=i.object_kind AND w.identity=i.object_identity
   WHERE w.kind IS NULL OR i.object_kind IS NULL OR w.restore_order IS DISTINCT FROM i.restore_order
    OR w.digest IS DISTINCT FROM i.definition_sha256 OR i.definition_sha256 IS DISTINCT FROM public.static_weekly_digest_text(i.definition_sql))
 THEN RAISE EXCEPTION 'Distinct Source253 full6968 exact identity/order/selfhash profile changed';END IF;
 IF to_regprocedure('custodial_release_canary_authority_surface()')::oid IS DISTINCT FROM 'public.custodial_release_canary_authority_surface()'::regprocedure::oid
  OR NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='public.custodial_release_canary_authority_surface()'::regprocedure
   AND proowner='postgres'::regrole AND public.static_weekly_digest_text(pg_get_functiondef(oid))=spec->>'extended_canary_sha256') THEN
  RAISE EXCEPTION 'Distinct Source253 exact public canary body/owner changed';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
  'grantor',pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable)
  ORDER BY (CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END)::text COLLATE pg_catalog."C",pg_get_userbyid(a.grantor)::text COLLATE pg_catalog."C",a.privilege_type COLLATE pg_catalog."C",a.is_grantable),'[]'::jsonb)
  INTO acl FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a
  WHERE p.oid='public.custodial_release_canary_authority_surface()'::regprocedure;
 SELECT coalesce(jsonb_agg(x ORDER BY (x->>'grantee') COLLATE pg_catalog."C",(x->>'grantor') COLLATE pg_catalog."C",(x->>'privilege') COLLATE pg_catalog."C",(x->>'grantable')::boolean),'[]'::jsonb) INTO expected_acl
  FROM jsonb_array_elements(spec->'canary_acl') x;
 IF acl IS DISTINCT FROM expected_acl THEN RAISE EXCEPTION 'Distinct Source253 exact canary named ACL changed';END IF;
 IF (SELECT count(*) FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN(
  'custodial_private_custody_v1_immutable','custodial_private_custody_v1_read_chunk','custodial_private_custody_v1_retain_chunk'))<>3
  OR (SELECT count(*) FROM pg_attribute WHERE attrelid IN('public.custodial_native_private_custody_operations'::regclass,'public.custodial_native_private_custody_chunks'::regclass) AND attnum>0 AND NOT attisdropped)<>28
  OR (SELECT count(*) FROM pg_constraint WHERE conrelid IN('public.custodial_native_private_custody_operations'::regclass,'public.custodial_native_private_custody_chunks'::regclass))<>32
  OR (SELECT count(*) FROM pg_index i WHERE indrelid IN('public.custodial_native_private_custody_operations'::regclass,'public.custodial_native_private_custody_chunks'::regclass)
   AND NOT EXISTS(SELECT 1 FROM pg_constraint c WHERE c.conindid=i.indexrelid))<>4
  OR (SELECT count(*) FROM pg_trigger WHERE tgrelid IN('public.custodial_native_private_custody_operations'::regclass,'public.custodial_native_private_custody_chunks'::regclass) AND NOT tgisinternal)<>6
 THEN RAISE EXCEPTION 'Distinct Source253 exact new custody catalog census/overloads changed';END IF;
 FOR item IN SELECT x FROM jsonb_array_elements(spec->'finite_new84') x LOOP
  definition:=NULL;obj:=NULL;acl:=NULL;
  IF item->>'object_kind'='function' THEN
   obj:=to_regprocedure(item->>'object_identity');
   IF NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.oid=obj
    AND n.nspname='public' AND p.proowner='postgres'::regrole AND md5(p.prosrc)=item->>'body_md5'
    AND md5(pg_get_functiondef(p.oid))=item->>'full_definition_md5') THEN
    RAISE EXCEPTION 'Distinct Source253 exact three new custody function bodies/owners changed';END IF;
   definition:=pg_get_functiondef(obj);
  ELSIF item->>'object_kind'='grant' THEN
   IF strpos(item->>'object_identity','(')>0 THEN
    obj:=to_regprocedure(item->>'object_identity');
    IF NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.oid=obj AND n.nspname='public' AND p.proowner='postgres'::regrole) THEN
     RAISE EXCEPTION 'Distinct Source253 new custody routine ACL target owner changed';END IF;
    SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
     'grantor',pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable)
     ORDER BY (CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END)::text COLLATE pg_catalog."C",pg_get_userbyid(a.grantor)::text COLLATE pg_catalog."C",a.privilege_type COLLATE pg_catalog."C",a.is_grantable),'[]'::jsonb)
     INTO acl FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid=obj;
   ELSE
    obj:=to_regclass(item->>'object_identity');
    IF NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.oid=obj AND n.nspname='public'
     AND c.relkind='r' AND c.relowner='postgres'::regrole AND c.relrowsecurity AND c.relforcerowsecurity)
     OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=obj)
     OR EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=obj AND attnum>0 AND NOT attisdropped AND attacl IS NOT NULL) THEN
     RAISE EXCEPTION 'Distinct Source253 new opaque custody table owner/FORCE RLS/no-policy boundary changed';END IF;
    SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
     'grantor',pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable)
     ORDER BY (CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END)::text COLLATE pg_catalog."C",pg_get_userbyid(a.grantor)::text COLLATE pg_catalog."C",a.privilege_type COLLATE pg_catalog."C",a.is_grantable),'[]'::jsonb)
     INTO acl FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE c.oid=obj;
   END IF;
   SELECT coalesce(jsonb_agg(x ORDER BY (x->>'grantee') COLLATE pg_catalog."C",(x->>'grantor') COLLATE pg_catalog."C",(x->>'privilege') COLLATE pg_catalog."C",(x->>'grantable')::boolean),'[]'::jsonb) INTO expected_acl
    FROM jsonb_array_elements(item->'expected_acl') x;
   IF acl IS DISTINCT FROM expected_acl THEN RAISE EXCEPTION 'Distinct Source253 exact new custody owner/runtime named ACL changed';END IF;
   IF strpos(item->>'object_identity','(')>0 THEN
    IF EXISTS(SELECT 1 FROM unnest(ARRAY['postgres','anon','authenticated','service_role','custodial_application_reader','static_weekly_control_plane','static_weekly_release_operator']) role
     WHERE has_function_privilege(role,obj,'EXECUTE') IS DISTINCT FROM EXISTS(SELECT 1 FROM jsonb_array_elements(item->'expected_acl') a
      WHERE a->>'grantee'=role AND a->>'privilege'='EXECUTE')) THEN
     RAISE EXCEPTION 'Distinct Source253 exact new custody effective function privileges changed';END IF;
   ELSIF EXISTS(SELECT 1 FROM unnest(ARRAY['anon','authenticated','service_role','custodial_application_reader','static_weekly_control_plane','static_weekly_release_operator']) role
    CROSS JOIN (SELECT DISTINCT privilege_type privilege FROM pg_class c CROSS JOIN LATERAL aclexplode(acldefault('r',c.relowner)) a WHERE c.oid=obj) rights
    WHERE has_table_privilege(role,obj,privilege)) THEN
    RAISE EXCEPTION 'Distinct Source253 opaque custody effective runtime table privileges changed';
   END IF;
   definition:=public.custodial_release_authority_current_grant_definition(item->>'object_identity');
  ELSIF item->>'object_kind'='relation' THEN definition:=public.custodial_release_authority_current_relation_definition(item->>'object_identity');
  ELSIF item->>'object_kind'='column' THEN definition:=public.custodial_release_authority_current_column_definition(item->>'object_identity');
  ELSIF item->>'object_kind'='column_set' THEN definition:=public.custodial_release_authority_current_column_set_definition(item->>'object_identity');
  ELSIF item->>'object_kind'='relation_state' THEN definition:=public.custodial_release_authority_current_relation_state_definition(item->>'object_identity');
  ELSIF item->>'object_kind'='constraint' THEN definition:=public.custodial_release_authority_current_constraint_definition(item->>'object_identity');
  ELSIF item->>'object_kind'='index' THEN definition:=public.custodial_release_authority_current_index_definition(item->>'object_identity');
  ELSIF item->>'object_kind'='trigger' THEN
   rel:=to_regclass(regexp_replace(item->>'object_identity','\.[^.]+$',''));
   SELECT 'drop trigger if exists '||quote_ident(t.tgname)||' on '||quote_ident(n.nspname)||'.'||quote_ident(c.relname)||'; '
    ||pg_get_triggerdef(t.oid,true)||'; alter table '||quote_ident(n.nspname)||'.'||quote_ident(c.relname)
    ||CASE WHEN t.tgenabled='A' THEN ' enable always trigger ' WHEN t.tgenabled='O' THEN ' enable trigger ' ELSE ' UNADMITTED ' END||quote_ident(t.tgname)||';'
    INTO definition FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace
    WHERE t.tgrelid=rel AND t.tgname=split_part(item->>'object_identity','.',3) AND NOT t.tgisinternal
     AND ((t.tgname='custodial_disaster_restore_mutation_fence' AND t.tgfoid='custodial_dr.guard_application_mutation()'::regprocedure)
      OR (t.tgname<>'custodial_disaster_restore_mutation_fence' AND t.tgfoid='public.custodial_private_custody_v1_immutable()'::regprocedure));
  ELSE RAISE EXCEPTION 'Distinct Source253 unknown new custody object kind';END IF;
  IF definition IS DISTINCT FROM item->>'expected_definition_sql'
   OR public.static_weekly_digest_text(definition) IS DISTINCT FROM item->>'expected_sha256' THEN
   RAISE EXCEPTION 'Distinct Source253 exact84 new catalog definitions changed';END IF;
 END LOOP;
