   and context.native_completed_at>context.started_at and context.native_completed_at<=statement_timestamp()
   and exists(select 1 from public.custodial_offline_scan_event_evidence evidence
    where evidence.context_id=context.context_id and evidence.reconciliation_id=receipt.reconciliation_id
      and evidence.session_id=s.id and lower(evidence.client_event_id)=context.native_finish_scan_entry_id::text
      and evidence.event_payload->>'event_type'='scan_finish'
      and evidence.event_payload->>'result'='ok'
      and evidence.event_payload#>>'{payload_json,entry_source}'='native-nfc'
      and evidence.event_payload->>'scanned_at'=public.custodial_canonical_utc_millis(context.native_completed_at))
 ) into v_native;
 select count(*),count(*) filter(where t.status='open'),
  count(*) filter(where t.resolution_outcome='work_order_sent'),
  count(*) filter(where t.resolution_outcome='mark_fixed'),
  count(*) filter(where t.status='closed' and t.resolution_outcome is null),
  coalesce(jsonb_agg(jsonb_build_object('ticket_id',t.id,'status',t.status,
   'resolution_outcome',t.resolution_outcome,'external_work_order_reference',t.external_work_order_reference,
   'resolution_actor_manager_id',t.resolution_actor_manager_id,'closed_at',t.closed_at,
   'issue_summary',t.issue_summary) order by t.reported_at,t.id) filter(where t.id is not null),'[]'::jsonb)
 into v_total,v_open,v_work_order,v_fixed,v_legacy_closed,v_tickets
 from public.maintenance_tickets t where t.completion_response_id=r.id and t.issue_source='completion_form';
 if jsonb_typeof(r.response_json->'attention_needed')='boolean' then
  v_issue_known:=true; v_issue:=(r.response_json->>'attention_needed')::boolean;
 end if;
 if jsonb_typeof(r.response_json->'maintenance_issues_found')='array' then
  v_raw_issue_count:=jsonb_array_length(r.response_json->'maintenance_issues_found');
 end if;
 if v_raw_issue_count=0 and (lower(coalesce(r.response_json->>'out_of_order_signed','')) in ('yes','true')
    or nullif(btrim(coalesce(r.response_json->>'out_of_order_details','')),'') is not null) then
  v_raw_issue_count:=1;
 end if;
 if v_total>0 or v_raw_issue_count>0
    or lower(coalesce(r.response_json->>'out_of_order_signed','')) in ('yes','true')
    or nullif(btrim(coalesce(r.response_json->>'out_of_order_details','')),'') is not null then
  v_issue_known:=true; v_issue:=true;
 end if;
 v_work:=r.response_json->>'work_result';
 if not v_issue_known then v_follow_up:='unknown';
 elsif not v_issue then v_follow_up:='none_reported';
 elsif v_total>0 and v_fixed=v_total and v_raw_issue_count>0 and v_total>=v_raw_issue_count
  then v_follow_up:='linked_tickets_marked_fixed_coverage_unverified';
 else v_follow_up:='required_or_unresolved';
 end if;
 if not v_native then v_class:='historical_or_unverified_completion';
 elsif v_work='checked_no_cleaning_needed' then v_class:='checked_only';
 elsif v_work not in ('full','details') or v_work is null then v_class:='unknown';
 elsif v_follow_up='none_reported' then v_class:='cleaned_no_issues_reported';
 elsif v_follow_up='linked_tickets_marked_fixed_coverage_unverified'
  then v_class:='cleaned_linked_tickets_marked_fixed_coverage_unverified';
 elsif v_follow_up='required_or_unresolved' then v_class:='cleaned_follow_up_required';
 else v_class:='cleaned_issue_state_unknown';
 end if;
 return jsonb_build_object('session_id',s.id,'session_uuid',s.session_uuid,'session_status',s.status,
  'location_id',s.location_id,'employee_id',s.employee_id,'device_id',s.device_id,
  'started_at',s.started_at,'ended_at',s.ended_at,
  'completion_recorded',true,'completion_response_id',r.id,'client_completion_id',r.client_completion_id,
  'submitted_at',r.submitted_at,'original_response',r.response_json,
  'taxonomy_version',r.response_json#>>'{taxonomy,version}',
  'taxonomy_digest',r.response_json#>>'{taxonomy,digest}',
  'taxonomy_status',case when not (r.response_json ? 'taxonomy') then 'unversioned_historical_or_protected_draft'
   when v_catalog is null or v_digest is distinct from r.response_json#>>'{taxonomy,digest}' then 'metadata_unverified_legacy'
   else 'versioned_current_catalog' end,
  'catalog_digest',v_digest,'catalog',v_catalog,
  'native_exact_receipt_admitted',v_native,'work_result',v_work,'issue_reported',case when v_issue_known then to_jsonb(v_issue) else 'null'::jsonb end,
  'linked_completion_tickets',v_tickets,'linked_ticket_count',v_total,'linked_open_count',v_open,
  'linked_work_order_sent_count',v_work_order,'linked_mark_fixed_count',v_fixed,
  'linked_legacy_closed_unknown_count',v_legacy_closed,'raw_reported_issue_count',v_raw_issue_count,
  'linked_issue_count_shortfall',greatest(v_raw_issue_count-v_total,0),'follow_up',v_follow_up,
  'classification',v_class,'inspection_evaluation','not_performed_by_this_reader');
end $new_prosrc$ THEN
  RAISE EXCEPTION 'manager evidence exact200 Source not installed'; END IF;
 IF (SELECT oid FROM manager_evidence_domain_proc_before) IS DISTINCT FROM 'public.custodial_manager_completion_evidence(uuid,text,text)'::regprocedure::oid
 OR EXISTS(SELECT 1 FROM manager_evidence_domain_proc_before old LEFT JOIN pg_proc now ON now.oid=old.oid
  WHERE (old.full_row-'prosrc') IS DISTINCT FROM (to_jsonb(now)-'prosrc')) THEN
  RAISE EXCEPTION 'manager evidence OID ownership permissions properties changed'; END IF;
 IF (SELECT count(*) FROM public.custodial_release_authority_restore_inventory)<>(SELECT count(*) FROM manager_evidence_domain_inventory_before)
 OR EXISTS(SELECT 1 FROM manager_evidence_domain_inventory_before old FULL JOIN public.custodial_release_authority_restore_inventory now USING(inventory_id)
  WHERE CASE WHEN old.object_kind='function' AND old.object_identity LIKE '%(%'
    AND to_regprocedure(old.object_identity)='public.custodial_manager_completion_evidence(uuid,text,text)'::regprocedure
   THEN (to_jsonb(old)-ARRAY['definition_sql','definition_sha256','captured_at']) IS DISTINCT FROM (to_jsonb(now)-ARRAY['definition_sql','definition_sha256','captured_at'])
   ELSE to_jsonb(old) IS DISTINCT FROM to_jsonb(now) END)
 OR EXISTS(SELECT 1 FROM public.custodial_release_authority_restore_inventory
  WHERE definition_sha256 IS DISTINCT FROM public.static_weekly_digest_text(definition_sql))
 OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.custodial_release_authority_restore_inventory'::regclass
  AND tgname='trg_custodial_release_authority_restore_inventory_immutable' AND NOT tgisinternal AND tgenabled='A') THEN
  RAISE EXCEPTION 'manager evidence inventory identity unrelated rows or immutability changed'; END IF;
END $after$;
COMMIT;

-- Append294: qualify the inner location lookup without rewriting prior migrations.
-- Preserve all prior293 migration bodies. Correct only the inner table reference.
begin;
do $repair$
declare
  target oid := to_regprocedure('public.get_location_scan_state(text,text)');
  before_definition text;
  after_definition text;
  inventory_identity text;
  inventory_definition text;
  inventory_sha text;
  inventory_count integer;
  changed integer;
  old_seam constant text := '(select id from public.locations where location_code=vls.location_code)';
  new_seam constant text := '(select scan_location.id from public.locations AS scan_location where scan_location.location_code=vls.location_code)';
begin
  if target is null then raise exception 'Location scan-state function is missing'; end if;
  before_definition := pg_get_functiondef(target);
  if length(before_definition)-length(replace(before_definition,old_seam,'')) <> length(old_seam) then
    raise exception 'Location scan-state inner-reference preimage changed';
  end if;
  if position(new_seam in before_definition) <> 0 then
    raise exception 'Location scan-state alias correction already present';
  end if;
  select count(*) into inventory_count
    from public.custodial_release_authority_restore_inventory
    where object_kind='function' and to_regprocedure(object_identity)=target;
  if inventory_count <> 1 then raise exception 'Location scan-state recovery identity is missing or duplicated'; end if;
  select object_identity,definition_sql,definition_sha256
    into strict inventory_identity,inventory_definition,inventory_sha
    from public.custodial_release_authority_restore_inventory
    where object_kind='function' and to_regprocedure(object_identity)=target;
  if inventory_definition is distinct from before_definition
    or inventory_sha is distinct from public.static_weekly_digest_text(before_definition) then
    raise exception 'Location scan-state captured/live recovery definition differs';
  end if;
  if not exists(select 1 from pg_trigger where
    tgrelid='public.custodial_release_authority_restore_inventory'::regclass
    and tgname='trg_custodial_release_authority_restore_inventory_immutable'
    and tgenabled='A') then
    raise exception 'Location scan-state recovery immutability is unavailable';
  end if;
  execute replace(before_definition,old_seam,new_seam);
  after_definition := pg_get_functiondef(target);
  if after_definition is distinct from replace(before_definition,old_seam,new_seam) then
    raise exception 'Location scan-state definition changed outside the selected alias';
  end if;
  alter table public.custodial_release_authority_restore_inventory
    disable trigger trg_custodial_release_authority_restore_inventory_immutable;
  update public.custodial_release_authority_restore_inventory
    set definition_sql=after_definition,
      definition_sha256=public.static_weekly_digest_text(after_definition),
      captured_at=statement_timestamp()
    where object_kind='function' and object_identity=inventory_identity
      and definition_sql=before_definition and definition_sha256=inventory_sha;
  get diagnostics changed=row_count;
  if changed <> 1 then raise exception 'Location scan-state recovery rebind is not singular'; end if;
  alter table public.custodial_release_authority_restore_inventory
    enable always trigger trg_custodial_release_authority_restore_inventory_immutable;
end $repair$;
commit;

-- PROPOSAL ONLY: accepted actual lunch windows; no historical migration edits.
-- Retains exact accepted projection/lunch equality, positive window/shift,
-- unknown-lunch refusal, helper cardinality, role/credential and stale guards.
begin;
set local lock_timeout='5s';
set local statement_timeout='30s';
do $actual$ declare p record; body text; begin
 for p in select * from (values
  ('public.static_weekly_v8_assert_lunch_document(uuid,jsonb)','if end_time-start_time<>interval ''1 hour'' then raise exception ''lunch must last exactly one hour''; end if;','if end_time<=start_time then raise exception ''accepted lunch end must follow its start''; end if;'),
  ('public.static_weekly_assert_exception_payload(text,date,time,time,uuid,uuid,jsonb,uuid)','p_exception_type=''lunch'' and p_ends_at-p_starts_at=interval ''1 hour''','p_exception_type=''lunch'' and p_ends_at>p_starts_at'),
  ('public.custodial_authorize_absence_operations_v1(uuid,uuid,text,text,date,uuid,jsonb)','end_text::time-start_text::time<>interval ''1 hour''','end_text::time<=start_text::time'),
  ('public.custodial_authorize_absence_operations_v1(uuid,uuid,text,text,date,uuid,jsonb)','Only the actual one-hour lunch accompanying dated CoverAll capacity is delegated','Only the actual positive lunch window within dated CoverAll capacity is delegated'),
  ('public.custodial_authorize_coverage_operations_v2(uuid,uuid,text,text,date,uuid,jsonb)','lunch_end-lunch_start<>interval ''1 hour''','lunch_end<=lunch_start'),
  ('public.custodial_authorize_coverage_operations_v2(uuid,uuid,text,text,date,uuid,jsonb)','CoverAll lunch must be one hour within the recorded shift','CoverAll lunch must be a positive actual window within the recorded shift'),
  ('public.custodial_native_lunch_live(uuid,jsonb,timestamptz)','
  or (intent->>''event''=''start'' and ends_at>scheduled+interval ''1 hour'') then return false;end if;',' then return false;end if;')
 ) v(identity,old_seam,new_seam) loop
  body:=pg_get_functiondef(to_regprocedure(p.identity));
  if body is null or length(body)-length(replace(body,p.old_seam,''))<>length(p.old_seam) then
   raise exception 'Exact actual-lunch predecessor mismatch: %',p.identity;
  end if;
  execute replace(body,p.old_seam,p.new_seam);
 end loop;
end $actual$;
-- CREATE OR REPLACE preserves existing ACLs; retain canary-recovery fullbodies.
alter table public.custodial_release_authority_restore_inventory disable trigger trg_custodial_release_authority_restore_inventory_immutable;
do $recovery$ declare identity text; body text; changed integer; begin
 foreach identity in array array[
  'public.static_weekly_v8_assert_lunch_document(uuid,jsonb)',
  'public.static_weekly_assert_exception_payload(text,date,time,time,uuid,uuid,jsonb,uuid)',
  'public.custodial_authorize_absence_operations_v1(uuid,uuid,text,text,date,uuid,jsonb)',
  'public.custodial_authorize_coverage_operations_v2(uuid,uuid,text,text,date,uuid,jsonb)',
  'public.custodial_native_lunch_live(uuid,jsonb,timestamptz)'
 ] loop
  body:=pg_get_functiondef(to_regprocedure(identity));
  update public.custodial_release_authority_restore_inventory i
   set definition_sql=body,definition_sha256=public.static_weekly_digest_text(body),captured_at=statement_timestamp()
   where case when i.object_kind='function' then to_regprocedure(i.object_identity) else null end=to_regprocedure(identity);
  get diagnostics changed=row_count;
  if changed<>1 then raise exception 'Exact actual-lunch recovery function missing/duplicated: %',identity;end if;
 end loop;
end $recovery$;
alter table public.custodial_release_authority_restore_inventory enable always trigger trg_custodial_release_authority_restore_inventory_immutable;
commit;

-- Canonical contractor handout capabilities. No legacy employee/capacity map.
-- Additive only: old token/history rows remain unchanged.
begin;
set local lock_timeout='5s';set local statement_timeout='30s';
create table public.static_weekly_coverall_access_links(
 link_id uuid not null,
 token_hash text not null unique check(token_hash~'^[a-f0-9]{64}$'),
 binding jsonb not null check(jsonb_typeof(binding)='object'),
 source_id uuid references public.static_weekly_authority_source_documents(source_id),
 source_digest text check(source_digest~'^[a-f0-9]{64}$'),
 manager_id uuid not null references public.ops_manager_managers(manager_id),
 credential_id uuid not null references public.ops_manager_trusted_devices(credential_id),
 device_id text not null, session_access text not null check(session_access in('full_access','read_only')),
 created_at timestamptz not null default clock_timestamp(),expires_at timestamptz not null,
 revoked_at timestamptz,revoked_by uuid references public.ops_manager_managers(manager_id),
 primary key(manager_id,link_id),
 check(expires_at>created_at and expires_at<=created_at+interval '7 days'),
 check(revoked_at is not null or (source_id is not null and source_digest is not null))
);
alter table public.static_weekly_coverall_access_links enable row level security;
alter table public.static_weekly_coverall_access_links force row level security;
revoke all on public.static_weekly_coverall_access_links from public,anon,authenticated,service_role,custodial_application_reader,static_weekly_control_plane,static_weekly_release_operator;

create function public.static_weekly_assert_coverall_link_basis(p_binding jsonb,p_source uuid default null,p_digest text default null)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $fn$
declare a record;src jsonb;source_row record;doc jsonb;projection record;day date;revision bigint;
begin
 perform public.static_weekly_v3_assert_control_plane();
 if not exists(select 1 from custodial_dr.restore_control where singleton and mutations_paused is false and state in('READY','COMPLETE')) then
  raise exception using errcode='55000',message='Canonical CoverAll authority is unavailable during restore';end if;
 perform public.static_weekly_assert_exact_object(p_binding,
  array['schema','week_start','service_date','capacity_id','publication_id','projection_id','authority_revision','replay_digest','lunch_document_identity','document_digest'],
  array['schema','week_start','service_date','capacity_id','publication_id','projection_id','authority_revision','replay_digest','lunch_document_identity','document_digest'],'canonical CoverAll binding');
 if (p_binding->>'schema'='custodial.coverall-canonical-binding.v1'
  and p_binding->>'service_date'~'^\d{4}-\d{2}-\d{2}$' and p_binding->>'week_start'~'^\d{4}-\d{2}-\d{2}$'
  and p_binding->>'capacity_id'~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$'
  and p_binding->>'publication_id'~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$'
  and p_binding->>'projection_id'~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$'
  and jsonb_typeof(p_binding->'authority_revision')='number' and p_binding->>'authority_revision'~'^(0|[1-9][0-9]*)$'
  and p_binding->>'replay_digest'~'^[a-f0-9]{64}$' and p_binding->>'lunch_document_identity'~'^[a-f0-9]{64}$'
  and p_binding->>'document_digest'~'^[a-f0-9]{64}$') is not true then
  raise exception using errcode='22023',message='Exact canonical CoverAll binding required';end if;
 day:=(p_binding->>'service_date')::date;
 if not isfinite(day) or day-(extract(isodow from day)::integer-1)<>(p_binding->>'week_start')::date then
  raise exception using errcode='22023',message='Exact canonical CoverAll week/date required';end if;
 select current_revision into strict revision from public.static_weekly_schedule_control where singleton;
 select * into a from public.static_weekly_v6_schedule_authority_state(day);
 select * into projection from public.weekly_schedule_compiled_projections where projection_id=(p_binding->>'projection_id')::uuid;
 if a.governed is not true or a.projection_status is distinct from 'current'
  or a.projection_id::text is distinct from p_binding->>'projection_id'
  or a.publication_id::text is distinct from p_binding->>'publication_id'
  or revision is distinct from (p_binding->>'authority_revision')::bigint
  or projection.replay_digest is distinct from p_binding->>'replay_digest' then
  raise exception using errcode='40001',message='Canonical CoverAll schedule changed';end if;
 select s.* into source_row from public.weekly_schedule_versions v
  join public.static_weekly_authority_source_documents s on s.source_id=v.authority_source_id
  where v.version_id=a.version_id;
 if source_row.source_id is null or source_row.active is not true or source_row.retired_at is not null
  or source_row.source_digest is distinct from public.static_weekly_digest_jsonb(source_row.canonical_source)
  or (p_source is not null and source_row.source_id is distinct from p_source)
  or (p_digest is not null and source_row.source_digest is distinct from p_digest) then
  raise exception using errcode='40001',message='Canonical CoverAll source changed';end if;
 doc:=public.static_weekly_v8_read_lunch_document(day);
 if doc->>'persistence_status' is distinct from 'PERSISTED'
  or doc->>'projection_id' is distinct from p_binding->>'projection_id'
  or doc->>'document_identity' is distinct from p_binding->>'lunch_document_identity' then
  raise exception using errcode='40001',message='Canonical CoverAll lunch changed';end if;
 src:=public.static_weekly_v3_read_publication_source(a.publication_id,day);
 if not exists(select 1 from jsonb_array_elements(src#>'{compiler_input,slots}') s
   where s->>'id'=p_binding->>'capacity_id' and s->'contractorCapacity'='true'::jsonb)
  or not exists(select 1 from jsonb_array_elements(src->'exceptions') e
   where e->>'type'='cover_all' and e->>'serviceDate'=day::text
    and e#>>'{payload,availability,slotId}'=p_binding->>'capacity_id') then
  raise exception using errcode='40001',message='Canonical CoverAll capacity is not accepted for this date';end if;
 return jsonb_build_object('source_id',source_row.source_id,'source_digest',source_row.source_digest);
end $fn$;

create function public.static_weekly_issue_coverall_link(
 p_manager uuid,p_credential uuid,p_device text,p_access text,p_link uuid,p_token_hash text,p_binding jsonb,p_ttl integer
) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $fn$
declare actor jsonb;basis jsonb;created timestamptz;expires timestamptz;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 actor:=public.custodial_action_actor_v1(p_manager,p_credential,p_device,p_access,'manage_coverall');
 if p_link is null or coalesce(p_token_hash,'')!~'^[a-f0-9]{64}$' or p_ttl is null or p_ttl not between 1 and 168 then
  raise exception using errcode='22023',message='Bounded canonical CoverAll issuance required';end if;
 basis:=public.static_weekly_assert_coverall_link_basis(p_binding);
 actor:=public.custodial_action_actor_v1(p_manager,p_credential,p_device,p_access,'manage_coverall');
 created:=clock_timestamp();expires:=created+make_interval(hours=>p_ttl);
 -- The once-only request ID is scoped to the server-derived issuing manager.
 -- Another manager may use/revoke the same nonsecret UUID without interference.
 insert into public.static_weekly_coverall_access_links(link_id,token_hash,binding,source_id,source_digest,manager_id,credential_id,device_id,session_access,created_at,expires_at)
 values(p_link,p_token_hash,p_binding,(basis->>'source_id')::uuid,basis->>'source_digest',p_manager,p_credential,p_device,p_access,created,expires);
 return jsonb_build_object('link_id',p_link,'expires_at',expires);
end $fn$;

create function public.static_weekly_read_coverall_link(p_token_hash text)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $fn$
declare link public.static_weekly_coverall_access_links%rowtype;actor jsonb;manager_name text;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 if coalesce(p_token_hash,'')!~'^[a-f0-9]{64}$' then raise exception using errcode='42501',message='CoverAll link unavailable';end if;
 select * into link from public.static_weekly_coverall_access_links where token_hash=p_token_hash for share;
 if not found or link.revoked_at is not null or link.expires_at<=clock_timestamp() then
  raise exception using errcode='42501',message='CoverAll link unavailable';end if;
 actor:=public.custodial_action_actor_v1(link.manager_id,link.credential_id,link.device_id,link.session_access,'manage_coverall');
 perform public.static_weekly_assert_coverall_link_basis(link.binding,link.source_id,link.source_digest);
 if link.expires_at<=clock_timestamp() then raise exception using errcode='42501',message='CoverAll link unavailable';end if;
 actor:=public.custodial_action_actor_v1(link.manager_id,link.credential_id,link.device_id,link.session_access,'manage_coverall');
 select display_name into strict manager_name from public.ops_manager_managers where manager_id=link.manager_id;
 if link.expires_at<=clock_timestamp() then raise exception using errcode='42501',message='CoverAll link unavailable';end if;
 return jsonb_build_object('schema','custodial.coverall-canonical-access.v1','binding',link.binding,
  'issuing_manager',jsonb_build_object('managerId',link.manager_id,'managerName',manager_name));
end $fn$;

create function public.static_weekly_revoke_coverall_link(p_manager uuid,p_credential uuid,p_device text,p_access text,p_link uuid)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $fn$
declare actor jsonb;link public.static_weekly_coverall_access_links%rowtype;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 actor:=public.custodial_action_actor_v1(p_manager,p_credential,p_device,p_access,'manage_coverall');
 select * into link from public.static_weekly_coverall_access_links where manager_id=p_manager and link_id=p_link for update;
 -- Capture FOUND before rechecking current credential after a possible row wait.
 if found then
  actor:=public.custodial_action_actor_v1(p_manager,p_credential,p_device,p_access,'manage_coverall');
 else
  actor:=public.custodial_action_actor_v1(p_manager,p_credential,p_device,p_access,'manage_coverall');
  -- Durable nonsecret tombstone settles an unknown issuance and prevents a
  -- delayed original POST from creating this request after revocation ACK.
  insert into public.static_weekly_coverall_access_links(link_id,token_hash,binding,manager_id,credential_id,device_id,session_access,created_at,expires_at,revoked_at,revoked_by)
   values(p_link,public.static_weekly_digest_text('revoked-coverall-request:'||p_manager::text||':'||p_link::text),'{}'::jsonb,p_manager,p_credential,p_device,p_access,
    statement_timestamp(),statement_timestamp()+interval '1 second',statement_timestamp(),p_manager);
  return jsonb_build_object('link_id',p_link,'revoked',true);
 end if;
 -- Revocation is exact issuer scope. Cross-issuer administrative revocation
 -- requires a separate explicit issuer context, never a guessed request ID.
 update public.static_weekly_coverall_access_links set revoked_at=coalesce(revoked_at,clock_timestamp()),revoked_by=coalesce(revoked_by,p_manager) where manager_id=p_manager and link_id=p_link;
 return jsonb_build_object('link_id',p_link,'revoked',true);
end $fn$;
revoke all on function public.static_weekly_assert_coverall_link_basis(jsonb,uuid,text),public.static_weekly_issue_coverall_link(uuid,uuid,text,text,uuid,text,jsonb,integer),public.static_weekly_read_coverall_link(text),public.static_weekly_revoke_coverall_link(uuid,uuid,text,text,uuid) from public,anon,authenticated,service_role,custodial_application_reader,static_weekly_control_plane,static_weekly_release_operator;
grant execute on function public.static_weekly_issue_coverall_link(uuid,uuid,text,text,uuid,text,jsonb,integer),public.static_weekly_read_coverall_link(text),public.static_weekly_revoke_coverall_link(uuid,uuid,text,text,uuid) to static_weekly_control_plane;
-- Explicit dependency-closed recovery membership for ONLY this new capability
-- relation and its four routines. Existing captured objects stay byte-identical
-- except the canary surface definition expanded by these exact new roots.
select custodial_dr.install_application_mutation_fences();
lock table public.custodial_release_authority_restore_inventory in access exclusive mode;
create temp table coverall_link_recovery_before on commit drop as table public.custodial_release_authority_restore_inventory;
create temp table coverall_link_new_recovery(bucket integer,kind text,identity text,definition text,primary key(kind,identity)) on commit drop;
do $capture_new$
declare rel text:='public.static_weekly_coverall_access_links';rid oid:=rel::regclass;
 sig text;obj record;surface text;roots text;next_order integer;surface_before text;affected integer;
begin
 if (select array_agg(attname::text order by attname) from pg_attribute where attrelid=rid and attnum>0 and not attisdropped)
  is distinct from array['binding','created_at','credential_id','device_id','expires_at','link_id','manager_id','revoked_at','revoked_by','session_access','source_digest','source_id','token_hash']::text[] then
  raise exception 'Canonical CoverAll recovery column set changed';end if;
 insert into coverall_link_new_recovery values
  (1000,'relation',rel,public.custodial_release_authority_current_relation_definition(rel)),
  (300000,'column_set',rel,public.custodial_release_authority_current_column_set_definition(rel)),
  (400000,'relation_state',rel,public.custodial_release_authority_current_relation_state_definition(rel)),
  (900000,'grant',rel,public.custodial_release_authority_current_grant_definition(rel));
 insert into coverall_link_new_recovery
  select 200000,'column',rel||':'||attname,public.custodial_release_authority_current_column_definition(rel||':'||attname)
  from pg_attribute where attrelid=rid and attnum>0 and not attisdropped;
 insert into coverall_link_new_recovery
  select 500000,'constraint',rel||':'||conname,public.custodial_release_authority_current_constraint_definition(rel||':'||conname)
  from pg_constraint where conrelid=rid;
 insert into coverall_link_new_recovery
  select 600000,'index',indexrelid::regclass::text,public.custodial_release_authority_current_index_definition(indexrelid::regclass::text)
  from pg_index i where indrelid=rid and not exists(select 1 from pg_constraint c where c.conindid=i.indexrelid);
 insert into coverall_link_new_recovery
  select 700000,'trigger',rel||'.'||quote_ident(tgname),
   'drop trigger if exists '||quote_ident(tgname)||' on '||rel||'; '||pg_get_triggerdef(oid,true)||'; alter table '||rel||' '
    ||case tgenabled when 'O' then 'enable' when 'D' then 'disable' when 'R' then 'enable replica' when 'A' then 'enable always' end
    ||' trigger '||quote_ident(tgname)||';'
  from pg_trigger where tgrelid=rid and not tgisinternal;
 insert into coverall_link_new_recovery
  select 800000,'policy',rel||':'||polname,public.custodial_release_authority_current_policy_definition(rel||':'||polname)
  from pg_policy where polrelid=rid;
 if not exists(select 1 from coverall_link_new_recovery where kind='trigger') then
  raise exception 'Canonical CoverAll mutation fence was not installed';end if;
 foreach sig in array array[
  'public.static_weekly_assert_coverall_link_basis(jsonb,uuid,text)',
  'public.static_weekly_issue_coverall_link(uuid,uuid,text,text,uuid,text,jsonb,integer)',
  'public.static_weekly_read_coverall_link(text)',
  'public.static_weekly_revoke_coverall_link(uuid,uuid,text,text,uuid)'
 ] loop
  insert into coverall_link_new_recovery values
   (100000,'function',sig::regprocedure::text,pg_get_functiondef(sig::regprocedure)),
   (1000000,'grant',sig::regprocedure::text,public.custodial_release_authority_current_grant_definition(sig::regprocedure::text));
 end loop;
 if exists(select 1 from coverall_link_new_recovery where definition is null or definition='') then
  raise exception 'Canonical CoverAll recovery renderer missing';end if;
 if exists(select 1 from coverall_link_new_recovery n join public.custodial_release_authority_restore_inventory i
   on i.object_kind=n.kind and i.object_identity=n.identity) then
  raise exception 'Unexpected prior canonical CoverAll recovery membership';end if;
 surface_before:=pg_get_functiondef('public.custodial_release_canary_authority_surface()'::regprocedure);
 if (select count(*) from public.custodial_release_authority_restore_inventory
   where case when object_kind='function' then to_regprocedure(object_identity) else null end='public.custodial_release_canary_authority_surface()'::regprocedure
    and definition_sql=surface_before and definition_sha256=public.static_weekly_digest_text(surface_before))<>1 then
  raise exception 'Exact prior canary recovery definition unavailable';end if;
 -- Retain every existing surface row/body. The already established source
 -- function has one VALUES insertion seam, never a generic function waiver.
 if length(surface_before)-length(replace(surface_before,'  values',''))<>length('  values') then
  raise exception 'Exact canary VALUES predecessor changed';end if;
 select string_agg(format('(%L,%L,%L),',kind,identity,'canonical capacity-bound private handout; no legacy employee mapping'),E'\n ' order by bucket,kind,identity)
 into roots from coverall_link_new_recovery where kind in('relation','column_set','relation_state','function','grant');
 surface:=replace(surface_before,'  values','  values'||E'\n '||roots);
 execute surface;
 alter table public.custodial_release_authority_restore_inventory disable trigger trg_custodial_release_authority_restore_inventory_immutable;
 for obj in select * from coverall_link_new_recovery order by bucket,kind,identity loop
  -- Maintained bounded first-unused allocation tolerates existing high
  -- sentinel rows without moving any preserved restore order.
  select n into next_order from generate_series(obj.bucket+1,
   case when obj.bucket=1000 then 99999 else obj.bucket+99999 end) n
   where not exists(select 1 from public.custodial_release_authority_restore_inventory i where i.restore_order=n)
   order by n limit 1;
  if next_order is null then raise exception 'Canonical CoverAll recovery bucket exhausted: kind=% bucket=%',obj.kind,obj.bucket;end if;
  insert into public.custodial_release_authority_restore_inventory(restore_order,object_kind,object_identity,definition_sql,definition_sha256)
   values(next_order,obj.kind,obj.identity,obj.definition,public.static_weekly_digest_text(obj.definition));
 end loop;
 update public.custodial_release_authority_restore_inventory
  set definition_sql=pg_get_functiondef('public.custodial_release_canary_authority_surface()'::regprocedure),
   definition_sha256=public.static_weekly_digest_text(pg_get_functiondef('public.custodial_release_canary_authority_surface()'::regprocedure)),captured_at=statement_timestamp()
  where case when object_kind='function' then to_regprocedure(object_identity) else null end='public.custodial_release_canary_authority_surface()'::regprocedure;
 get diagnostics affected=row_count;if affected<>1 then raise exception 'Exact canary recovery row changed';end if;
 alter table public.custodial_release_authority_restore_inventory enable always trigger trg_custodial_release_authority_restore_inventory_immutable;
 if exists(select 1 from coverall_link_new_recovery n left join public.custodial_release_authority_restore_inventory i
   on i.object_kind=n.kind and i.object_identity=n.identity
   where i.definition_sql is distinct from n.definition or i.definition_sha256 is distinct from public.static_weekly_digest_text(n.definition)) then
  raise exception 'Canonical CoverAll recovery readback mismatch';end if;
 if exists(select b.* from coverall_link_recovery_before b where not(case when b.object_kind='function' then to_regprocedure(b.object_identity)='public.custodial_release_canary_authority_surface()'::regprocedure else false end)
   except select * from public.custodial_release_authority_restore_inventory)
  or exists(select i.* from public.custodial_release_authority_restore_inventory i
   where not(case when i.object_kind='function' then to_regprocedure(i.object_identity)='public.custodial_release_canary_authority_surface()'::regprocedure else false end)
    and not exists(select 1 from coverall_link_new_recovery n where i.object_kind=n.kind and i.object_identity=n.identity)
   except select * from coverall_link_recovery_before) then
  raise exception 'Unrelated recovery inventory changed';end if;
 if exists(select 1 from coverall_link_new_recovery n where n.kind in('relation','column_set','relation_state','function','grant')
   and not exists(select 1 from public.custodial_release_canary_authority_surface() s where s.object_kind=n.kind and s.object_identity=n.identity)) then
  raise exception 'Canonical CoverAll canary roots incomplete';end if;
end $capture_new$;
commit;

-- Source-only proposal. Activation requires reviewed legacy OAuth reauthorization;
-- no manager/device/browser trust table or legacy connector token is changed.
begin;
create table public.mcp_oauth_replay_artifacts_v2 (
  artifact_digest text primary key check (artifact_digest ~ '^[0-9a-f]{64}$'),
  authority_generation bigint not null check (authority_generation >= 0),
  artifact_kind text not null check (artifact_kind in ('decision','code')),
  expires_at timestamptz not null,
  consumed_at timestamptz not null default clock_timestamp()
);
create table public.mcp_oauth_token_families_v2 (
  family_digest text primary key check (family_digest ~ '^[0-9a-f]{64}$'),
  authority_generation bigint not null check (authority_generation >= 0),
  binding_digest text not null check (binding_digest ~ '^[0-9a-f]{64}$'),
  current_refresh_digest text check (current_refresh_digest ~ '^[0-9a-f]{64}$'),
  generation bigint not null default 0 check (generation >= 0 and generation <= 9007199254740991),
  expires_at timestamptz not null,
  created_at timestamptz not null default clock_timestamp(),
  revoked_at timestamptz,
  revocation_reason text check (revocation_reason is null or revocation_reason='refresh_reuse')
);
alter table public.mcp_oauth_replay_artifacts_v2 enable row level security;
alter table public.mcp_oauth_token_families_v2 enable row level security;
revoke all on public.mcp_oauth_replay_artifacts_v2, public.mcp_oauth_token_families_v2 from public, anon, authenticated, service_role;
grant select, insert on public.mcp_oauth_replay_artifacts_v2 to service_role;
grant select, insert, update on public.mcp_oauth_token_families_v2 to service_role;

-- Reuse the existing service-only shared mutation fence and its non-restored
-- control authority. No direct custodial_dr grant and no new SECURITY DEFINER.
create function public.mcp_oauth_authority_generation_v2()
returns text language sql volatile security invoker set search_path=pg_catalog,public set lock_timeout='5s' set statement_timeout='8s' as $$
  select public.custodial_begin_application_mutation()::text;
$$;

create function public.mcp_oauth_consume_decision_v2(p_artifact_digest text,p_expires_at bigint,p_authority_generation text)
returns boolean language plpgsql security invoker set search_path=pg_catalog,public set lock_timeout='5s' set statement_timeout='8s' as $$
declare v_authority_generation bigint;
begin
  v_authority_generation := public.custodial_begin_application_mutation();
  if p_authority_generation is null or p_authority_generation <> v_authority_generation::text then return false; end if;
  if p_artifact_digest is null or p_artifact_digest !~ '^[0-9a-f]{64}$' or p_expires_at is null
    or p_expires_at <= extract(epoch from clock_timestamp()) or p_expires_at > extract(epoch from clock_timestamp())+600 then return false; end if;
  insert into public.mcp_oauth_replay_artifacts_v2(artifact_digest,authority_generation,artifact_kind,expires_at)
    values(p_artifact_digest,v_authority_generation,'decision',to_timestamp(p_expires_at)) on conflict do nothing;
  if not found then return false; end if;
  -- Unique-key contention can wait past expiration. Raising rolls back the insert.
  if p_expires_at <= extract(epoch from clock_timestamp()) then raise exception 'OAuth decision expired' using errcode='22023'; end if;
  return true;
end $$;

create function public.mcp_oauth_exchange_code_v2(p_code_digest text,p_code_expires_at bigint,p_family_digest text,
  p_binding_digest text,p_refresh_digest text,p_expires_at bigint,p_authority_generation text)
returns boolean language plpgsql security invoker set search_path=pg_catalog,public set lock_timeout='5s' set statement_timeout='8s' as $$
declare v_authority_generation bigint;
begin
  v_authority_generation := public.custodial_begin_application_mutation();
  if p_authority_generation is null or p_authority_generation <> v_authority_generation::text then return false; end if;
  if p_code_digest is null or p_code_digest !~ '^[0-9a-f]{64}$'
    or p_family_digest is null or p_family_digest !~ '^[0-9a-f]{64}$'
    or p_binding_digest is null or p_binding_digest !~ '^[0-9a-f]{64}$'
    or (p_refresh_digest is not null and p_refresh_digest !~ '^[0-9a-f]{64}$')
    or p_code_expires_at is null or p_expires_at is null
    or p_code_expires_at <= extract(epoch from clock_timestamp())
    or p_code_expires_at > extract(epoch from clock_timestamp())+600
    or p_expires_at <= extract(epoch from clock_timestamp())
    or p_expires_at > extract(epoch from clock_timestamp())+2592000 then return false; end if;
  insert into public.mcp_oauth_replay_artifacts_v2(artifact_digest,authority_generation,artifact_kind,expires_at)
    values(p_code_digest,v_authority_generation,'code',to_timestamp(p_code_expires_at)) on conflict do nothing;
  if not found then return false; end if;
  -- This family INSERT and the code's one-use INSERT commit or roll back together.
  insert into public.mcp_oauth_token_families_v2(family_digest,authority_generation,binding_digest,current_refresh_digest,expires_at)
    values(p_family_digest,v_authority_generation,p_binding_digest,p_refresh_digest,to_timestamp(p_expires_at));
  if p_code_expires_at <= extract(epoch from clock_timestamp()) or p_expires_at <= extract(epoch from clock_timestamp()) then
    raise exception 'OAuth code expired' using errcode='22023'; end if;
  return true;
end $$;

create function public.mcp_oauth_rotate_refresh_v2(p_family_digest text,p_binding_digest text,p_previous_digest text,
  p_generation bigint,p_next_digest text,p_expires_at bigint,p_authority_generation text)
returns boolean language plpgsql security invoker set search_path=pg_catalog,public set lock_timeout='5s' set statement_timeout='8s' as $$
declare f public.mcp_oauth_token_families_v2%rowtype; v_authority_generation bigint;
begin
  v_authority_generation := public.custodial_begin_application_mutation();
  if p_authority_generation is null or p_authority_generation <> v_authority_generation::text then return false; end if;
  if p_family_digest is null or p_family_digest !~ '^[0-9a-f]{64}$'
    or p_binding_digest is null or p_binding_digest !~ '^[0-9a-f]{64}$'
    or p_previous_digest is null or p_previous_digest !~ '^[0-9a-f]{64}$'
    or p_next_digest is null or p_next_digest !~ '^[0-9a-f]{64}$' or p_next_digest=p_previous_digest
    or p_generation is null or p_generation < 0 or p_generation >= 9007199254740991
    or p_expires_at is null then return false; end if;
  select * into f from public.mcp_oauth_token_families_v2 where family_digest=p_family_digest for update;
  if not found or f.authority_generation <> v_authority_generation or f.binding_digest <> p_binding_digest or f.revoked_at is not null
    or f.expires_at <= clock_timestamp() or p_expires_at <= extract(epoch from clock_timestamp())
    or p_expires_at > extract(epoch from clock_timestamp())+2592000 then return false; end if;
  if f.generation<>p_generation or f.current_refresh_digest is distinct from p_previous_digest then
    -- Return false rather than raising: the reuse revocation MUST commit.
    update public.mcp_oauth_token_families_v2 set revoked_at=clock_timestamp(),revocation_reason='refresh_reuse'
      where family_digest=p_family_digest;
    return false;
  end if;
  update public.mcp_oauth_token_families_v2 set current_refresh_digest=p_next_digest,
    generation=p_generation+1,expires_at=to_timestamp(p_expires_at) where family_digest=p_family_digest;
  return true;
end $$;

create function public.mcp_oauth_family_active_v2(p_family_digest text,p_binding_digest text,p_authority_generation text)
returns boolean language plpgsql volatile security invoker set search_path=pg_catalog,public set lock_timeout='5s' set statement_timeout='8s' as $$
declare v_authority_generation bigint;
begin
  v_authority_generation := public.custodial_begin_application_mutation();
  if p_authority_generation is null or p_authority_generation <> v_authority_generation::text then return false; end if;
  return exists(select 1 from public.mcp_oauth_token_families_v2 where family_digest=p_family_digest
    and authority_generation=v_authority_generation and binding_digest=p_binding_digest
    and revoked_at is null and expires_at>clock_timestamp());
end $$;
revoke all on function public.mcp_oauth_authority_generation_v2(),public.mcp_oauth_consume_decision_v2(text,bigint,text),
  public.mcp_oauth_exchange_code_v2(text,bigint,text,text,text,bigint,text),
  public.mcp_oauth_rotate_refresh_v2(text,text,text,bigint,text,bigint,text),
  public.mcp_oauth_family_active_v2(text,text,text) from public,anon,authenticated,service_role;
grant execute on function public.mcp_oauth_authority_generation_v2(),public.mcp_oauth_consume_decision_v2(text,bigint,text),
  public.mcp_oauth_exchange_code_v2(text,bigint,text,text,text,bigint,text),
  public.mcp_oauth_rotate_refresh_v2(text,text,text,bigint,text,bigint,text),
  public.mcp_oauth_family_active_v2(text,text,text) to service_role;
commit;

-- Full scheduled-lunch coverage is opted into by the immutable compiler
-- source, never a request flag. Original duty intersections remain separate
-- anchors, with unchanged work/person/location/qualification checks.
begin;
set local lock_timeout='5s';
set local statement_timeout='30s';
do $full_lunch$
declare body text;seam record;old text;new text;before_acl text;identity text;
begin
 foreach identity in array array[
  'public.static_weekly_v3_create_draft(date,text,jsonb,jsonb,jsonb,bigint,uuid,text,uuid)',
  'public.static_weekly_v3_update_draft(uuid,jsonb,jsonb,jsonb,bigint,bigint,uuid,text)',
  'public.static_weekly_v3_publish_draft(uuid,bigint,bigint,uuid,text,text,uuid)',
  'public.static_weekly_v3_materialize_projection(uuid,date,text,text,jsonb,jsonb,text,jsonb,bigint,uuid,text)'] loop
  before_acl:=public.custodial_release_authority_current_grant_definition(identity);
  execute format('alter function %s set plan_cache_mode=force_generic_plan',identity);
  if public.custodial_release_authority_current_grant_definition(identity) is distinct from before_acl then
   raise exception 'draft RPC ACL changed: %',identity;end if;
 end loop;
 -- These validators inspect opaque, production-sized JSON parameters. A
 -- value-specific SPI plan can retain many copies of a complete authority
 -- while folding its immutable checks. Reuse parameterized plans locally;
 -- every validator expression, size bound and admission check still runs.
 identity:='public.static_weekly_assert_compiler_authority(jsonb,jsonb,date,boolean)';
 before_acl:=public.custodial_release_authority_current_grant_definition(identity);
 alter function public.static_weekly_assert_compiler_authority(jsonb,jsonb,date,boolean)
  set plan_cache_mode=force_generic_plan;
 if public.custodial_release_authority_current_grant_definition(identity) is distinct from before_acl then
  raise exception 'compiler validator ACL changed';end if;
 -- Source binding changes only one UUID. Comparing full rows through JSON
 -- expands both complete draft documents unnecessarily. A typed row copy
 -- masks that same UUID and compares every remaining column, including any
 -- later-added columns, with exact NULL-aware equality. The guard remains
 -- installed and its other transition rules are unchanged.
 identity:='public.static_weekly_version_guard()';
 before_acl:=public.custodial_release_authority_current_grant_definition(identity);
 body:=pg_get_functiondef(to_regprocedure(identity));
 for seam in select * from (values
 ($old$AS $function$
begin$old$,
  $new$AS $function$
declare source_comparison public.weekly_schedule_versions%rowtype;
begin$new$),
 ($old$  if old.lifecycle_state='draft' and current_setting('app.static_weekly_source_bind',true)='on' and old.authority_source_id is null and new.authority_source_id is not null and (to_jsonb(new)-'authority_source_id')=(to_jsonb(old)-'authority_source_id') then return new; end if;$old$,
  $new$  if old.lifecycle_state='draft' and current_setting('app.static_weekly_source_bind',true)='on' and old.authority_source_id is null and new.authority_source_id is not null then
    source_comparison:=new;
    source_comparison.authority_source_id:=old.authority_source_id;
    if source_comparison is not distinct from old then return new; end if;
  end if;$new$)
 ) changes(old,new) loop
  if length(body)-length(replace(body,seam.old,''))<>length(seam.old) then raise exception 'exact version guard predecessor mismatch';end if;
  body:=replace(body,seam.old,seam.new);
 end loop;
 execute body;
 if public.custodial_release_authority_current_grant_definition(identity) is distinct from before_acl then
  raise exception 'version guard ACL changed';end if;
 -- Remove excluded top-level keys in one traversal. Retain only the
 -- published compiler input needed for the exact source comparison, rather
 -- than a second complete signed draft. No identity or admission rule moves.
 identity:='public.static_weekly_assert_projection_envelope_attested(jsonb,uuid,date,jsonb)';
 before_acl:=public.custodial_release_authority_current_grant_definition(identity);
 body:=pg_get_functiondef(to_regprocedure(identity));
 for seam in select * from (values
  ($old$(p_envelope-'attestation')-'database_projection_identity'$old$,
   $new$p_envelope-array['attestation','database_projection_identity']$new$),
  ($old$select v.draft_document into v_document$old$,
   $new$select v.draft_document#>'{authority,compilerInput}' into v_document$new$),
  ($old$public.static_weekly_v5_projection_source_identity(v_document#>'{authority,compilerInput}')$old$,
   $new$public.static_weekly_v5_projection_source_identity(v_document)$new$),
  ($old$p_envelope-'semantic_snapshot'-'attestation'$old$,
   $new$p_envelope-array['semantic_snapshot','attestation']$new$)
 ) changes(old,new) loop
  if length(body)-length(replace(body,seam.old,''))<>length(seam.old) then raise exception 'exact projection identity predecessor mismatch';end if;
  body:=replace(body,seam.old,seam.new);
 end loop;
 execute body;
 if public.custodial_release_authority_current_grant_definition(identity) is distinct from before_acl then
  raise exception 'projection identity validator ACL changed';end if;
 identity:='public.static_weekly_v8_assert_lunch_document(uuid,jsonb)';
 before_acl:=public.custodial_release_authority_current_grant_definition(identity);
 body:=pg_get_functiondef(to_regprocedure(identity));
 for seam in select * from (values
 ($old$ projection_availability jsonb;projection_assignments jsonb;projection_work jsonb;$old$,
  $new$ projection_availability jsonb;projection_assignments jsonb;projection_work jsonb;
